/** API CenaBR via proxy — Bearer só no servidor. Retorna corpo upstream. */
async function chamarApiCenaSegura(payload){
  if(!_sbAuthToken){
    console.warn('[ERP] chamarApiCenaSegura sem JWT:', payload&&payload.path);
    return Promise.reject(new Error(ERP.disabledMsg));
  }
  var res = await chamarEdgeFunction('erp-cenabr-proxy', payload||{});
  if(!res || res.error){
    throw new Error((res && (res.message || res.error)) || 'Proxy ERP falhou');
  }
  if(res.ok === false){
    throw new Error('ERP retornou status '+(res.status||'?')+(res.message?': '+res.message:''));
  }
  // Proxy: { ok, status, data: upstreamBody }
  return (res.data !== undefined) ? res.data : res;
}

// Restaurar cache do localStorage ao iniciar
(function(){
  try{
    var ts=parseInt(localStorage.getItem(ERP.cache.keyTs)||'0');
    var raw=localStorage.getItem(ERP.cache.key);
    if(raw&&(Date.now()-ts)<ERP.cache.ttl){
      var saved=JSON.parse(raw);
      if(saved&&saved.length) fornecedores=saved;
    }
  }catch(e){}
})();

function erpSalvarCache(d){
  try{
    localStorage.setItem(ERP.cache.key,JSON.stringify(d));
    localStorage.setItem(ERP.cache.keyTs,String(Date.now()));
  }catch(e){}
}
function erpInvalidarCache(){
  try{localStorage.removeItem(ERP.cache.key);localStorage.removeItem(ERP.cache.keyTs);}catch(e){}
}
function erpCacheValido(){
  try{return (Date.now()-parseInt(localStorage.getItem(ERP.cache.keyTs)||'0'))<ERP.cache.ttl;}catch(e){return false;}
}
function erpCacheInfo(){
  if(!erpCacheValido()||!fornecedores.length) return '';
  var mins=0;
  try{mins=Math.max(0,Math.round((ERP.cache.ttl-(Date.now()-parseInt(localStorage.getItem(ERP.cache.keyTs)||'0')))/60000));}catch(e){}
  return '✅ '+fornecedores.length+' fornecedores · cache ~'+mins+' min';
}

function _erpSetStatus(txt,cor){
  var el=document.getElementById('forn-load-status');
  if(el) el.innerHTML=txt?'<span style="color:'+(cor||'#888')+'">'+txt+'</span>':'';
}

function erpFetchPagina(pg){
  // Fase 2B: proxy Edge Function com JWT — sem Bearer no browser.
  return chamarApiCenaSegura({ path:'/suppliers', method:'GET', query:{ page:String(pg) } });
}

// Remove duplicados por CNPJ válido — mantém o cadastro matriz (is_root_supplier).
// CNPJs vazios/zerados são placeholders de fornecedores distintos: não deduplicar.
function erpDedup(items){
  var vistos={};
  var ordenados=items.slice().sort(function(a,b){
    var ra=a.is_root_supplier?0:1, rb=b.is_root_supplier?0:1;
    if(ra!==rb)return ra-rb;
    return (a.id||0)-(b.id||0);
  });
  var out=[];
  ordenados.forEach(function(s){
    var c=String(s.cpf_cnpj||s.cnpj||s.cnpj_cpf||'').replace(/\D/g,'');
    if(!c||/^0+$/.test(c)){ out.push(s); return; }
    if(vistos[c]) return;
    vistos[c]=true;
    out.push(s);
  });
  return out;
}

function erpNorm(s){
  var st='Inativo';
  if(s.status==='ativo'||s.status==='active'||s.active===true||s.active===1||s.status===1||s.status==='1'||s.is_active===true||s.is_active===1) st='Ativo';
  var email = s.email||s.email_address||s.contact_email||s.contato_email||'';
  if(!email && s.contacts && s.contacts[0]) email = s.contacts[0].email||s.contacts[0].email_address||'';
  var tel = s.telefone||s.phone||s.celular||s.mobile||s.whatsapp||s.contact_phone||s.contato_fone||s.fone||'';
  if(!tel && s.contacts && s.contacts[0]) tel = s.contacts[0].phone||s.contacts[0].telefone||s.contacts[0].mobile||'';
  return {
    id:'_erp_'+(s.id||s.uuid||String(Math.random())),
    razao_social:s.razao_social||s.name||s.nome||s.company_name||s.fantasy_name||'',
    nome_fantasia:s.nome_fantasia||s.fantasy_name||s.trade_name||'',
    cnpj_cpf:s.cnpj||s.cpf||s.cnpj_cpf||s.cpf_cnpj||s.document||s.tax_id||'',
    tipo:s.tipo||s.type||(s.cnpj?'Jurídica':'Física'),
    email:email, telefone:tel,
    cidade:s.cidade||s.city||(s.address&&s.address.city)||'',
    estado:s.estado||s.uf||s.state||(s.address&&s.address.state)||'',
    endereco:s.endereco||s.address_line||(s.address&&s.address.street)||'',
    cep:s.cep||s.zip||s.postal_code||'',
    status:st, _erp:true, _erp_id:s.id, _erp_raw:s
  };
}

// Buscar todas as páginas em paralelo
function erpFetchTodos(){
  return erpFetchPagina(1).then(function(resp){
    var items=resp.data||resp.results||[];
    var meta=resp.meta||{};
    var lastPage=meta.last_page||resp.last_page||1;
    var total=meta.total||resp.total||items.length;
    _erpSetStatus('📥 1/'+lastPage+' — '+items.length+'/'+total,'#185FA5');
    if(lastPage<=1) return items;
    var promises=[];
    for(var p=2;p<=lastPage;p++){
      (function(pg){
        promises.push(erpFetchPagina(pg)
          .then(function(r){return r.data||r.results||[];})
          .catch(function(){return [];}));
      })(p);
    }
    return Promise.all(promises).then(function(pages){
      pages.forEach(function(pg,i){
        items=items.concat(pg);
        _erpSetStatus('📥 '+(i+2)+'/'+lastPage+' — '+items.length+'/'+total,'#185FA5');
      });
      return items;
    });
  });
}

function erpCarregarFornecedores(forceRefresh){
  if(!_sbAuthToken){
    _erpSetStatus('⚠ Sync ERP exige login Auth','#854F0B');
    if(forceRefresh && typeof progShowToast==='function'){
      progShowToast('⚠ '+ERP.disabledMsg);
    }
    return carregarFornDB().then(function(r){
      if(r&&r.length && !(fornecedores||[]).some(function(f){return f._erp;}))
        fornecedores=r.slice();
      setTimeout(function(){_erpSetStatus('');},4000);
      return r||[];
    });
  }

  if(!forceRefresh&&erpCacheValido()&&fornecedores.length>50)
    return Promise.resolve(fornecedores);

  if(forceRefresh) erpInvalidarCache();
  _erpSetStatus('🔄 Conectando ao ERP...','#888');

  return erpFetchTodos().then(function(items){
    var norm=erpDedup(items).map(erpNorm).filter(function(f){return f.razao_social;})
      .sort(function(a,b){return a.razao_social.localeCompare(b.razao_social,'pt-BR',{sensitivity:'base'});});
    erpSalvarCache(norm);
    // Mantém ERP em fornecedores, mas NÃO apaga o cadastro local (_fornDB)
    fornecedores=norm;
    _erpSetStatus('✅ '+norm.length+' ERP','#3B6D11');
    setTimeout(function(){_erpSetStatus('');},3000);
    return carregarFornDB().then(function(){ return norm; });
  }).catch(function(e){
    console.error('ERP:',e);
    _erpSetStatus('⚠️ ERP indisponível','#854F0B');
    setTimeout(function(){_erpSetStatus('');},4000);
    return carregarFornDB().then(function(r){
      if(r&&r.length && !(fornecedores||[]).some(function(f){return f._erp;}))
        fornecedores=r.slice();
      return r||[];
    });
  });
}
// ── FIM INTEGRAÇÃO ERP ────────────────────────────────────────────────
var usuarioLogado=null;
var _gestorContAtivo=null;
var _gestorContratos=[];

var contratos=[],categorias=[],subcategorias=[],verbas=[],lancamentos=[],fornecedores=[],fin_faturamentos=[],fin_indices_ipca=[];
var _fornDB=[]; // fornecedores da tabela Supabase (uuids reais) — não é sobrescrito pelo cache do ERP
function carregarFornDB(){
  if(DEMO) return Promise.resolve(_fornDB);
  // Sem filtro de status e com paginação: evita sumir ativos além do limite 1000
  var fetchFn = typeof sbFetchAll==='function'
    ? sbFetchAll('fornecedores',{order:'razao_social.asc',pageSize:1000,maxPages:20})
    : sbFetch('fornecedores',{order:'razao_social',limit:5000});
  return fetchFn.then(function(r){
    if(Array.isArray(r)) _fornDB=r.filter(function(f){ return f.deleted_at==null; });
    return _fornDB||[];
  }).catch(function(){ return _fornDB||[]; });
}
function _fornFindById(fid){
  return (_fornDB||[]).find(function(x){ return x.id===fid; })
    || (fornecedores||[]).find(function(x){ return x.id===fid && !x._erp; });
}
/** Opções de &lt;select&gt;: cadastro local (UUID) + ERP, sem duplicar CNPJ. */
function _fornOptsSelectHtml(selectedId){
  var sel = selectedId!=null && selectedId!=='' ? String(selectedId) : '';
  var lst = typeof frtFornecedoresLista==='function'
    ? frtFornecedoresLista()
    : { db: (_fornDB||[]).slice(), erp: (fornecedores||[]).filter(function(f){return f._erp;}) };
  var db = (lst.db||[]).filter(function(f){
    return f.status==='Ativo' || String(f.id)===sel;
  });
  var erp = (lst.erp||[]).filter(function(f){
    return f.status==='Ativo' || String(f.id)===sel;
  });
  var html = '<option value="">Selecione (opcional)</option>';
  if(db.length){
    html += '<optgroup label="Cadastrados">'+db.map(function(f){
      return '<option value="'+f.id+'"'+(String(f.id)===sel?' selected':'')+'>'
        +(typeof _escAttrLanc==='function'?_escAttrLanc(f.razao_social||''):String(f.razao_social||'').replace(/"/g,'&quot;'))
        +'</option>';
    }).join('')+'</optgroup>';
  }
  if(erp.length){
    html += '<optgroup label="ERP CenaBR">'+erp.map(function(f){
      return '<option value="'+f.id+'"'+(String(f.id)===sel?' selected':'')+'>'
        +(typeof _escAttrLanc==='function'?_escAttrLanc(f.razao_social||''):String(f.razao_social||'').replace(/"/g,'&quot;'))
        +'</option>';
    }).join('')+'</optgroup>';
  }
  return html;
}
function _fornChaveNome(s){
  return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/\b(ltda|ltda\.|me|epp|sa|s\.a\.|eireli)\b/gi,'').replace(/[^a-z0-9]/g,'');
}
function _fornChaveCnpj(c){ return String(c||'').replace(/\D/g,''); }
function _fornNormTexto(s){
  return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}
function _fornListaBusca(){
  var vistos = {}, out = [];
  function add(f){
    if(!f) return;
    var k = String(f.id||'') || (_fornChaveCnpj(f.cnpj_cpf)+'|'+_fornChaveNome(f.razao_social));
    if(vistos[k]) return;
    vistos[k] = 1;
    out.push(f);
  }
  if(typeof frtFornecedoresLista==='function'){
    var lst = frtFornecedoresLista();
    (lst.db||[]).forEach(add);
    (lst.erp||[]).forEach(add);
  } else {
    (_fornDB||[]).forEach(add);
  }
  (fornecedores||[]).forEach(add);
  return out;
}
function _fornMinScoreBusca(q){
  var digits = _fornChaveCnpj(q).length;
  if(digits >= 3) return 0.28;
  if(String(q||'').trim().length <= 2) return 0.18;
  return 0.32;
}
function _fornScoreBusca(texto, f){
  if(!texto||!f) return 0;
  var raw = String(texto).trim();
  var tc = _fornChaveCnpj(raw);
  if(tc.length >= 3){
    var fc = _fornChaveCnpj(f.cnpj_cpf);
    if(fc){
      if(tc === fc) return 1;
      if(fc.indexOf(tc) >= 0) return 0.92 + Math.min(0.07, tc.length / Math.max(fc.length, 1));
      if(tc.indexOf(fc) >= 0 && fc.length >= 11) return 0.95;
    }
    // Telefone (só dígitos)
    var ft = _fornChaveCnpj(f.telefone);
    if(ft && ft.indexOf(tc) >= 0) return 0.88 + Math.min(0.08, tc.length / Math.max(ft.length, 1));
  }
  var t = _fornChaveNome(raw);
  if(t){
    var r = _fornChaveNome(f.razao_social);
    var nf = _fornChaveNome(f.nome_fantasia);
    if(t === r || t === nf) return 1;
    if(r && r.indexOf(t) >= 0) return Math.min(0.99, 0.72 + t.length / Math.max(r.length, 1) * 0.27);
    if(t.indexOf(r) >= 0 && r.length >= 3) return 0.86;
    if(nf && nf.indexOf(t) >= 0) return Math.min(0.98, 0.68 + t.length / Math.max(nf.length, 1) * 0.3);
    if(nf && t.indexOf(nf) >= 0 && nf.length >= 3) return 0.82;
  }
  var rawLow = _fornNormTexto(raw);
  // E-mail
  var em = _fornNormTexto(f.email||'');
  if(rawLow.length >= 2 && em){
    if(em === rawLow) return 1;
    if(em.indexOf(rawLow) >= 0) return 0.9;
    if(rawLow.indexOf('@') >= 0 && em.indexOf(rawLow.split('@')[0]) >= 0) return 0.85;
  }
  // Telefone texto parcial
  var telNorm = _fornNormTexto(f.telefone||'');
  if(rawLow.length >= 3 && telNorm && telNorm.indexOf(rawLow) >= 0) return 0.86;

  var hay = _fornNormTexto((f.razao_social||'')+' '+(f.nome_fantasia||'')+' '+(f.email||'')+' '+(f.telefone||''));
  if(rawLow.length >= 2 && hay.indexOf(rawLow) >= 0) return 0.78;
  var tokens = rawLow.split(/\s+/).filter(function(w){ return w.length >= 2; });
  if(tokens.length){
    var matched = tokens.filter(function(w){ return hay.indexOf(w) >= 0; }).length;
    if(matched === tokens.length) return 0.74 + Math.min(0.2, matched * 0.05);
    if(matched > 0) return 0.38 + matched / tokens.length * 0.34;
  }
  return 0;
}
function _fornBuscarFornecedores(texto, limit){
  var q = String(texto||'').trim();
  if(!q) return [];
  var minSc = _fornMinScoreBusca(q);
  var scores = [];
  _fornListaBusca().forEach(function(f){
    var sc = _fornScoreBusca(q, f);
    if(sc >= minSc) scores.push({f:f, sc:sc});
  });
  scores.sort(function(a,b){
    if(b.sc !== a.sc) return b.sc - a.sc;
    return (a.f.razao_social||'').localeCompare(b.f.razao_social||'', 'pt-BR', {sensitivity:'base'});
  });
  return scores.slice(0, limit || 25);
}
function _fornTextoBateFornecedor(texto, f){
  return _fornScoreBusca(texto, f) >= _fornMinScoreBusca(texto);
}
function _fornResolverPorTexto(texto){
  var t=String(texto||'').trim();
  if(!t) return { id:null, razao_social:'', motivo:'Locadora vazia' };
  var hits = _fornBuscarFornecedores(t, 1);
  if(hits.length){
    var f = hits[0].f, sc = hits[0].sc;
    var tc = _fornChaveCnpj(t);
    var motivo = (tc.length >= 11 && tc === _fornChaveCnpj(f.cnpj_cpf)) ? 'CNPJ'
      : (sc >= 0.98 ? 'Nome exato' : 'Nome similar');
    return { id:f.id, razao_social:f.razao_social, motivo:motivo };
  }
  return { id:null, razao_social:t, motivo:'Sem match no cadastro Supabase' };
}
function _fornSugerirProximo(texto){
  var hits = _fornBuscarFornecedores(texto, 1);
  return hits.length ? hits[0].f : null;
}
function fornAuditarVinculoLocacoes(){
  return carregarFornDB().then(function(){
    var vinculadas=[], comMatch=[], semMatch=[], semLocadora=[];
    (locacoes||[]).forEach(function(l){
      var loc=(l.locadora||'').trim();
      if(l.fornecedor_id){
        vinculadas.push({ id:l.id, nome:l.nome||'—', locadora:loc, fornecedor_id:l.fornecedor_id,
          forn_nome:( _fornFindById(l.fornecedor_id)||{}).razao_social||'?', inicio:l.inicio, termino:l.termino });
        return;
      }
      if(!loc){ semLocadora.push({ id:l.id, nome:l.nome||'—', inicio:l.inicio, termino:l.termino }); return; }
      var r=_fornResolverPorTexto(loc);
      if(r.id){
        comMatch.push({ id:l.id, nome:l.nome||'—', locadora:loc, match_nome:r.razao_social, match_id:r.id, motivo:r.motivo,
          inicio:l.inicio, termino:l.termino });
      } else {
        var sug=_fornSugerirProximo(loc);
        semMatch.push({ id:l.id, nome:l.nome||'—', locadora:loc, motivo:r.motivo,
          sugestao:sug?(sug.razao_social+(sug.cnpj_cpf?' — '+sug.cnpj_cpf:'')):null,
          inicio:l.inicio, termino:l.termino });
      }
    });
    return { vinculadas:vinculadas, comMatch:comMatch, semMatch:semMatch, semLocadora:semLocadora,
      total:(locacoes||[]).length };
  });
}
function fornRelatorioVinculoHtml(rep){
  if(!rep) return '';
  function tbl(cols, rows, cor){
    if(!rows.length) return '<div style="font-size:11px;color:#888;padding:4px 0">Nenhum</div>';
    return '<div style="overflow-x:auto;max-height:220px;overflow-y:auto;margin-bottom:.75rem;border:.5px solid #e0dfd8;border-radius:8px">'
      +'<table class="tbl" style="font-size:11px;margin:0"><thead><tr>'
      +cols.map(function(c){ return '<th style="background:'+(cor||'#f9f9f7')+'">'+c+'</th>'; }).join('')
      +'</tr></thead><tbody>'
      +rows.map(function(r){
        return '<tr><td>'+escHtml(r.nome)+'</td><td>'+escHtml(r.locadora||'—')+'</td>'
          +(r.forn_nome!==undefined?'<td>'+escHtml(r.forn_nome)+'</td>':'')
          +(r.match_nome!==undefined?'<td style="color:#3B6D11">→ '+escHtml(r.match_nome)+'</td><td>'+escHtml(r.motivo||'')+'</td>':'')
          +(r.motivo!==undefined&&r.match_nome===undefined?'<td style="color:#854F0B">'+escHtml(r.motivo)+'</td><td>'+(r.sugestao?escHtml(r.sugestao):'—')+'</td>':'')
          +'<td style="white-space:nowrap">'+fmtD(r.inicio||'')+' — '+fmtD(r.termino||'')+'</td></tr>';
      }).join('')+'</tbody></table></div>';
  }
  return '<div style="font-size:12px;margin-bottom:.5rem">Total: <b>'+rep.total+'</b> locações · '
    +'<span style="color:#3B6D11">✓ '+rep.vinculadas.length+' já vinculadas</span> · '
    +'<span style="color:#185FA5">◆ '+rep.comMatch.length+' prontas para vincular</span> · '
    +'<span style="color:#854F0B">⚠ '+rep.semMatch.length+' sem match</span> · '
    +'<span style="color:#888">○ '+rep.semLocadora.length+' sem locadora</span></div>'
    +'<div style="font-weight:600;font-size:11px;color:#3B6D11;margin-top:.5rem">✓ Já vinculadas ('+rep.vinculadas.length+')</div>'
    +tbl(['Equipamento','Locadora','Fornecedor cadastro','Período'], rep.vinculadas, '#EEF7E8')
    +'<div style="font-weight:600;font-size:11px;color:#185FA5">◆ Pendentes — match encontrado ('+rep.comMatch.length+')</div>'
    +tbl(['Equipamento','Locadora digitada','Vincular a','Motivo','Período'], rep.comMatch, '#EEF4FF')
    +'<div style="font-weight:600;font-size:11px;color:#854F0B">⚠ Sem match no cadastro ('+rep.semMatch.length+')</div>'
    +tbl(['Equipamento','Locadora digitada','Motivo','Sugestão próxima','Período'], rep.semMatch, '#FFF8E8')
    +(rep.semLocadora.length?('<div style="font-weight:600;font-size:11px;color:#888">○ Sem locadora ('+rep.semLocadora.length+')</div>'
      +'<div style="overflow-x:auto;max-height:120px;overflow-y:auto;margin-bottom:.75rem;border:.5px solid #e0dfd8;border-radius:8px">'
      +'<table class="tbl" style="font-size:11px"><thead><tr><th>Equipamento</th><th>Período</th></tr></thead><tbody>'
      +rep.semLocadora.map(function(r){
        return '<tr><td>'+escHtml(r.nome)+'</td><td>'+fmtD(r.inicio||'')+' — '+fmtD(r.termino||'')+'</td></tr>';
      }).join('')+'</tbody></table></div>'):'');
}
function openFornAuditoriaLocacoes(){
  progShowToast('⏳ Analisando locações...');
  fornAuditarVinculoLocacoes().then(function(rep){
    window._fornUltimoRelatorioLoc=rep;
    setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:920px;max-height:90vh;overflow-y:auto">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem">'
      +'<h3 style="margin:0">📋 Auditoria — locações × fornecedores</h3>'
      +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button></div>'
      +fornRelatorioVinculoHtml(rep)
      +'<div class="ma"><button class="btn" onclick="closeModal()">Fechar</button>'
      +(rep.comMatch.length?'<button class="btn btn-pri" onclick="fornVincularLocacoesLote(true)">🏗 Vincular '+rep.comMatch.length+' com match</button>':'')
      +'</div></div></div>');
  });
}
function fornVincularLocacoesLote(aplicar){
  fornAuditarVinculoLocacoes().then(function(rep){
    if(!aplicar){
      openFornAuditoriaLocacoes();
      return;
    }
    if(!rep.comMatch.length){
      progShowToast('Nenhuma locação pendente com match automático. Veja o relatório.');
      openFornAuditoriaLocacoes();
      return;
    }
    if(!confirm('Vincular '+rep.comMatch.length+' locação(ões) ao cadastro de fornecedores?\n\n'
      +rep.semMatch.length+' continuarão sem vínculo (sem match).\n'+rep.vinculadas.length+' já estavam OK.')) return;
    var prom=[], ok=0;
    rep.comMatch.forEach(function(row){
      var l=locacoes.find(function(x){ return x.id===row.id; });
      if(!l) return;
      l.fornecedor_id=row.match_id;
      l.locadora=row.match_nome;
      ok++;
      if(!DEMO) prom.push(sbUpdate('locacoes',{fornecedor_id:row.match_id,locadora:row.match_nome},'id=eq.'+row.id));
    });
    Promise.all(prom).then(function(){
      return fornAuditarVinculoLocacoes();
    }).then(function(rep2){
      window._fornUltimoRelatorioLoc=rep2;
      if(typeof renderLocacoes==='function') renderLocacoes();
      progShowToast('✅ '+ok+' vinculada(s). ⚠ '+rep2.semMatch.length+' ainda sem match — veja relatório.');
      setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:920px;max-height:90vh;overflow-y:auto">'
        +'<h3 style="margin:0 0 .75rem">Resultado da vinculação</h3>'
        +'<div style="background:#EEF7E8;border-radius:8px;padding:.6rem .85rem;font-size:12px;margin-bottom:.75rem">'
        +'<b>'+ok+'</b> locação(ões) vinculada(s) agora. <b>'+rep2.vinculadas.length+'</b> total com fornecedor_id. '
        +'<b>'+rep2.semMatch.length+'</b> ainda precisam de cadastro ou ajuste manual do nome.</div>'
        +fornRelatorioVinculoHtml(rep2)
        +'<div class="ma"><button class="btn btn-pri" onclick="closeModal()">Fechar</button></div></div></div>');
    }).catch(function(e){
      progShowToast('❌ Erro: '+(e&&e.message||e),'erro');
    });
  });
}

