async function sbFetch(table,opts){
  opts=opts||{};
  if(DEMO)return null;
  var select=opts.select||'*';
  var filters=opts.filters||[];
  var order=opts.order||null;
  var limit=opts.limit||1000;
  var url=SB.url+'/rest/v1/'+table+'?select='+select;
  filters.forEach(function(f){url+='&'+f;});
  if(order)url+='&order='+order;
  url+='&limit='+limit;
  try{
    var res=await cenaAuthAuthorizedFetch(url,{method:'GET'},{requireAuth:!!opts.requireAuth, op:'sbFetch:'+table});
    if(res.aborted || !res.ok) return null;
    if(res.json!=null) return Array.isArray(res.json)?res.json:(res.json?res.json:[]);
    return res.text?JSON.parse(res.text):[];
  }catch(e){return null;}
}

// Busca paginada — ignora o limite de 1000 do Supabase buscando em chunks de 1000
async function sbFetchPaged(table, opts){
  opts = opts||{};
  if(DEMO) return null;
  var select  = opts.select||'*';
  var filters = opts.filters||[];
  var order   = opts.order||null;
  var all     = [];
  var page    = 0;
  var size    = 1000;
  while(true){
    var from = page * size;
    var to   = from + size - 1;
    var url  = SB.url+'/rest/v1/'+table+'?select='+select;
    filters.forEach(function(f){ url += '&'+f; });
    if(order) url += '&order='+order;
    url += '&limit='+size+'&offset='+from;
    try{
      var res = await cenaAuthAuthorizedFetch(url,{
        method:'GET',
        headers:{'Range-Unit':'items','Range':from+'-'+to}
      },{requireAuth:!!opts.requireAuth, op:'sbFetchPaged:'+table});
      if(res.aborted || !res.ok) break;
      var rows = Array.isArray(res.json) ? res.json : (res.text ? JSON.parse(res.text) : []);
      if(!rows.length) break;
      all = all.concat(rows);
      if(rows.length < size) break; // última página
      page++;
    } catch(e){ break; }
  }
  return all;
}

async function sbFetchAll(table,opts){
  opts=opts||{};
  if(DEMO)return [];
  var select=opts.select||'*';
  var filters=opts.filters||[];
  var order=opts.order||'id';
  // PostgREST exige direção (.asc/.desc) em cada coluna
  order=String(order).split(',').map(function(p){
    p=String(p||'').trim();
    if(!p) return '';
    if(/\.(asc|desc)$/i.test(p)) return p;
    return p+'.asc';
  }).filter(Boolean).join(',');
  var pageSize=opts.pageSize||1000;
  var allRows=[];
  var offset=0;
  var maxPages=opts.maxPages!=null?opts.maxPages:50; // até ~50k linhas (antes 20k cortava períodos longos)
  while(maxPages-->0){
    var url=SB.url+'/rest/v1/'+table+'?select='+encodeURIComponent(select);
    filters.forEach(function(f){url+='&'+f;});
    url+='&order='+order+'&limit='+pageSize+'&offset='+offset;
    try{
      var res=await cenaAuthAuthorizedFetch(url,{
        method:'GET',
        headers:{
          'Content-Type':'application/json',
          'Accept':'application/json',
          'Prefer':'count=none'
        }
      },{requireAuth:!!opts.requireAuth, op:'sbFetchAll:'+table});
      if(res.aborted) break;
      if(!res.ok){
        console.warn('[sbFetchAll] HTTP',res.status,'tabela:',table);
        break;
      }
      if(!res.text||res.text==='null'){break;}
      var rows=Array.isArray(res.json)?res.json:JSON.parse(res.text);
      if(!Array.isArray(rows)||!rows.length)break;
      allRows=allRows.concat(rows);
      if(rows.length<pageSize)break;
      offset+=pageSize;
    }catch(e){
      console.error('[sbFetchAll] erro:',e,'tabela:',table);
      break;
    }
  }
  return allRows;
}

