var _cenaTagDemoCreds = [];

function cenaTagNormalizarUid(valor){
  if(typeof cenaRfidNormalizarUid==='function') return cenaRfidNormalizarUid(valor);
  return String(valor==null?'':valor)
    .replace(/[\n\r\t]+/g,'')
    .replace(/[\s\-]+/g,'')
    .trim()
    .toUpperCase();
}

function cenaTagPodeCadastrar(){
  if(typeof perfilAcessoTotal==='function' && perfilAcessoTotal()) return true;
  var p = String((usuarioLogado && usuarioLogado.perfil) || '').toLowerCase();
  return p==='admin' || p==='diretoria' || p==='gestor' || p==='coordenador';
}

function cenaTagFmtTs(iso){
  if(typeof cenaRfidFmtTs==='function') return cenaRfidFmtTs(iso);
  if(!iso) return '—';
  var d = new Date(iso);
  if(isNaN(d.getTime())) return '—';
  function p(n){ return String(n).padStart(2,'0'); }
  return p(d.getDate())+'/'+p(d.getMonth()+1)+'/'+d.getFullYear()+' '+p(d.getHours())+':'+p(d.getMinutes());
}

function cenaTagEsc(s){
  if(typeof cenaRfidEsc==='function') return cenaRfidEsc(s);
  if(typeof escHtml==='function') return escHtml(String(s==null?'':s));
  return String(s==null?'':s).replace(/[&<>"']/g, function(ch){
    return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[ch];
  });
}

function cenaTagVeiculoMotivo(vei){
  if(!vei || !vei.id) return 'VEICULO_INATIVO';
  if(vei.ativo===false) return 'VEICULO_INATIVO';
  var st=String(vei.status||'').toLowerCase();
  if(st==='baixado' || st==='inativo' || st.indexOf('inativ')>=0) return 'VEICULO_INATIVO';
  if(st==='bloqueado' || st==='quarentena') return 'VEICULO_BLOQUEADO';
  return null;
}

function cenaTagParseErro(txt, status){
  var msg = 'Erro TAG ('+status+')';
  try{
    var j = JSON.parse(txt);
    msg = j.message || j.details || j.hint || msg;
    if(String(j.hint||'')==='TAG_UID_HISTORICO' || /já vinculad/i.test(msg)){
      if(msg.indexOf('⛔')!==0) msg = '⛔ '+msg;
    }
  }catch(e){
    if(txt) msg = String(txt).slice(0, 280);
  }
  return msg;
}

async function cenaTagRpc(fn, params){
  if(DEMO) return {ok:false, error:'DEMO_USE_LOCAL'};
  var tok = null;
  try{
    tok = await cenaAuthGetValidToken({requireAuth:true, forceLogin:false, reason:'tag:'+fn});
  }catch(e){ tok = null; }
  if(!tok || tok==='demo' || (typeof sbAuthJwtIsAuthenticated==='function' && !sbAuthJwtIsAuthenticated(tok))){
    return {ok:false, error:'Sessão Auth obrigatória para TAG. Faça login autenticado (não MD5).'};
  }
  try{
    var r = await fetch(SB.url+'/rest/v1/rpc/'+fn, {
      method:'POST',
      headers:{
        'apikey': SB.key,
        'Authorization': 'Bearer '+tok,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(params||{})
    });
    var txt = await r.text();
    var data = null;
    try{ data = txt ? JSON.parse(txt) : null; }catch(e1){ data = null; }
    if(!r.ok){
      console.error('cenaTagRpc', fn, r.status, txt);
      return {ok:false, error: cenaTagParseErro(txt, r.status), status:r.status, raw:data};
    }
    return {ok:true, data:data};
  }catch(e){
    console.error('cenaTagRpc', fn, e);
    return {ok:false, error: String(e && e.message || e)};
  }
}

function cenaTagDemoLista(veicId){
  return _cenaTagDemoCreds.filter(function(x){ return String(x.veiculo_id)===String(veicId) && x.tipo==='RFID_TAG'; });
}

function cenaTagDemoAtiva(veicId){
  return cenaTagDemoLista(veicId).filter(function(x){ return x.status==='ATIVO'; })[0] || null;
}

async function cenaTagCarregarCredenciais(veicId){
  if(DEMO){
    return cenaTagDemoLista(veicId).slice().sort(function(a,b){
      return String(b.criado_em||'').localeCompare(String(a.criado_em||''));
    });
  }
  var rows = await sbFetch('veiculo_credenciais', {
    requireAuth: true,
    select: 'id,veiculo_id,tipo,uid,uid_normalizado,status,ativado_em,criado_em,bloqueado_em,motivo_bloqueio,substitui_credencial_id,criado_por',
    filters: ['veiculo_id=eq.'+veicId, 'tipo=eq.RFID_TAG'],
    order: 'criado_em.desc',
    limit: 40
  });
  return rows || [];
}

function cenaTagPickAtual(lista){
  lista=lista||[];
  var at = lista.filter(function(x){ return x.status==='ATIVO'; })[0];
  var bl = lista.filter(function(x){ return x.status==='BLOQUEADO'; })[0];
  return at || bl || lista[0] || null;
}

function cenaTagDemoResolver(uid){
  var n = cenaTagNormalizarUid(uid);
  if(!n) return {ok:false, encontrado:false, autenticavel:false, motivo:'UID_VAZIO', credencial:null, veiculo:null};
  var cred = _cenaTagDemoCreds.filter(function(x){ return x.tipo==='RFID_TAG' && x.uid_normalizado===n; })[0];
  if(!cred) return {ok:true, encontrado:false, autenticavel:false, motivo:'TAG_DESCONHECIDA', credencial:null, veiculo:null};
  var vei = (typeof frt_veiculos!=='undefined'?frt_veiculos:[]).find(function(v){ return String(v.id)===String(cred.veiculo_id); }) || {};
  var motivoCred = cred.status==='BLOQUEADO' ? 'TAG_BLOQUEADA' : (cred.status==='SUBSTITUIDO' ? 'TAG_SUBSTITUIDA' : null);
  var motivoVei = cred.status==='ATIVO' ? cenaTagVeiculoMotivo(vei) : null;
  var motivo = motivoCred || motivoVei;
  var aut = !motivo;
  return {
    ok:true, encontrado:true, autenticavel:!!aut,
    motivo: motivo,
    credencial:{id:cred.id, status:cred.status},
    veiculo:{id:vei.id||cred.veiculo_id, placa:vei.placa||'—', modelo:vei.modelo||'—', status:vei.status||'—'}
  };
}

async function cenaTagResolverVeiculo(uid){
  var n = cenaTagNormalizarUid(uid);
  if(!n) return {ok:false, encontrado:false, autenticavel:false, motivo:'UID_VAZIO', credencial:null, veiculo:null};
  if(DEMO) return cenaTagDemoResolver(uid);
  var rpc = await cenaTagRpc('fn_tag_resolver', {p_uid: uid});
  if(!rpc.ok) return {ok:false, encontrado:false, autenticavel:false, motivo:'ERRO', error:rpc.error, credencial:null, veiculo:null};
  return rpc.data || {ok:true, encontrado:false, autenticavel:false, motivo:'TAG_DESCONHECIDA', credencial:null, veiculo:null};
}

function cenaTagDemoVincular(veicId, uid){
  var n = cenaTagNormalizarUid(uid);
  if(!n) return {ok:false, error:'UID TAG vazio após normalização'};
  var exist = _cenaTagDemoCreds.filter(function(x){ return x.tipo==='RFID_TAG' && x.uid_normalizado===n; })[0];
  if(exist) return {ok:false, error:'⛔ TAG já vinculada a outro registro (histórico).'};
  if(cenaTagDemoAtiva(veicId)) return {ok:false, error:'Veículo já possui TAG ATIVA. Use substituição.'};
  var now = new Date().toISOString();
  var row = {
    id:'tag-demo-'+Date.now(), veiculo_id:veicId, tipo:'RFID_TAG',
    uid:String(uid||'').trim(), uid_normalizado:n, status:'ATIVO',
    ativado_em:now, criado_em:now, origem_leitura:'SIMULADOR', criado_por:'DEMO'
  };
  _cenaTagDemoCreds.push(row);
  return {ok:true, data:{ok:true, acao:'TAG_VINCULADA', credencial:{id:row.id, status:'ATIVO'}}};
}

function cenaTagDemoBloquear(veicId, motivo){
  if(!String(motivo||'').trim()) return {ok:false, error:'Motivo de bloqueio obrigatório'};
  var at = cenaTagDemoAtiva(veicId);
  if(!at) return {ok:false, error:'Veículo não possui TAG ATIVA para bloquear'};
  at.status='BLOQUEADO';
  at.bloqueado_em=new Date().toISOString();
  at.motivo_bloqueio=String(motivo).trim();
  return {ok:true, data:{ok:true, acao:'TAG_BLOQUEADA', credencial:{id:at.id, status:'BLOQUEADO'}}};
}

function cenaTagDemoReativar(veicId){
  if(cenaTagDemoAtiva(veicId)) return {ok:false, error:'Veículo já possui TAG ATIVA.'};
  var bl = cenaTagDemoLista(veicId).filter(function(x){ return x.status==='BLOQUEADO'; })
    .sort(function(a,b){ return String(b.bloqueado_em||'').localeCompare(String(a.bloqueado_em||'')); })[0];
  if(!bl) return {ok:false, error:'Não há TAG BLOQUEADA para reativar'};
  bl.status='ATIVO';
  bl.ativado_em=new Date().toISOString();
  bl.bloqueado_em=null;
  bl.motivo_bloqueio=null;
  return {ok:true, data:{ok:true, acao:'TAG_REATIVADA', credencial:{id:bl.id, status:'ATIVO'}}};
}

function cenaTagDemoSubstituir(veicId, uid, motivo){
  var n = cenaTagNormalizarUid(uid);
  if(!n) return {ok:false, error:'UID TAG vazio após normalização'};
  var at = cenaTagDemoAtiva(veicId);
  if(!at) return {ok:false, error:'Veículo não possui TAG ATIVA para substituir'};
  if(at.uid_normalizado===n) return {ok:false, error:'O UID lido já é a TAG ATIVA deste veículo'};
  var exist = _cenaTagDemoCreds.filter(function(x){ return x.tipo==='RFID_TAG' && x.uid_normalizado===n; })[0];
  if(exist && String(exist.veiculo_id)!==String(veicId)) return {ok:false, error:'⛔ TAG já vinculada a outro veículo.'};
  at.status='SUBSTITUIDO';
  var now=new Date().toISOString();
  var nova;
  if(exist && String(exist.veiculo_id)===String(veicId)){
    exist.status='ATIVO';
    exist.ativado_em=now;
    exist.substitui_credencial_id=at.id;
    exist.bloqueado_em=null;
    exist.motivo_bloqueio=null;
    nova=exist;
  } else {
    nova={
      id:'tag-demo-'+Date.now(), veiculo_id:veicId, tipo:'RFID_TAG',
      uid:String(uid||'').trim(), uid_normalizado:n, status:'ATIVO',
      ativado_em:now, criado_em:now, substitui_credencial_id:at.id,
      origem_leitura:'SIMULADOR', criado_por:'DEMO', motivo:motivo||null
    };
    _cenaTagDemoCreds.push(nova);
  }
  return {ok:true, data:{ok:true, acao:'TAG_SUBSTITUIDA', credencial_anterior:{id:at.id, status:'SUBSTITUIDO'}, credencial:{id:nova.id, status:'ATIVO'}}};
}

async function cenaTagExecVincular(veicId, uid){
  if(DEMO) return cenaTagDemoVincular(veicId, uid);
  return cenaTagRpc('fn_tag_vincular', {p_veiculo_id:veicId, p_uid:uid, p_origem_leitura:'SIMULADOR'});
}
async function cenaTagExecSubstituir(veicId, uid, motivo){
  if(DEMO) return cenaTagDemoSubstituir(veicId, uid, motivo);
  return cenaTagRpc('fn_tag_substituir', {p_veiculo_id:veicId, p_uid:uid, p_origem_leitura:'SIMULADOR', p_motivo:motivo||null});
}
async function cenaTagExecBloquear(veicId, motivo){
  if(DEMO) return cenaTagDemoBloquear(veicId, motivo);
  return cenaTagRpc('fn_tag_bloquear', {p_veiculo_id:veicId, p_motivo:motivo});
}
async function cenaTagExecReativar(veicId){
  if(DEMO) return cenaTagDemoReativar(veicId);
  return cenaTagRpc('fn_tag_reativar', {p_veiculo_id:veicId});
}

function cenaTagSecaoHtml(veicId, vei, lista){
  var pode = cenaTagPodeCadastrar();
  var cred = cenaTagPickAtual(lista);
  var st = cred && cred.status;
  var corpo;
  var hist = (lista||[]).map(function(c){
    return '<div style="font-size:11px;color:#555;padding:3px 0;border-bottom:.5px solid #e8eef5">'
      +'<b>'+cenaTagEsc(c.status)+'</b> · '+cenaTagEsc(c.uid_normalizado||'—')
      +' · '+cenaTagFmtTs(c.ativado_em||c.criado_em)
      +(c.status==='BLOQUEADO'&&c.motivo_bloqueio?' · '+cenaTagEsc(c.motivo_bloqueio):'')
      +(c.substitui_credencial_id?' · subst.':'')
      +'</div>';
  }).join('');
  if(!cred){
    corpo = '<div style="font-size:13px;color:#666">Status: <b>Sem TAG</b></div>';
  } else if(st==='ATIVO'){
    corpo = '<div style="font-size:13px">TAG atual: <b style="letter-spacing:.03em">'+cenaTagEsc(cred.uid_normalizado||'—')+'</b></div>'
      +'<div style="font-size:13px;margin-top:2px">Status: <b>Ativo</b></div>'
      +'<div style="font-size:12px;color:#666">Ativada em: '+cenaTagFmtTs(cred.ativado_em||cred.criado_em)+'</div>';
  } else if(st==='BLOQUEADO'){
    corpo = '<div style="font-size:13px">TAG: <b style="letter-spacing:.03em">'+cenaTagEsc(cred.uid_normalizado||'—')+'</b></div>'
      +'<div style="font-size:13px;margin-top:2px">Status: <b>Bloqueado</b> — não autentica</div>'
      +'<div style="font-size:12px;color:#666">Em: '+cenaTagFmtTs(cred.bloqueado_em)+'</div>'
      +(cred.motivo_bloqueio?'<div style="font-size:12px;color:#854F0B">Motivo: '+cenaTagEsc(cred.motivo_bloqueio)+'</div>':'');
  } else {
    corpo = '<div style="font-size:13px;color:#666">Sem TAG ATIVA (último: '+cenaTagEsc(st)+').</div>';
  }
  return '<div style="background:#F4F8FC;border:1px solid #c5d8ea;border-radius:10px;padding:.7rem .8rem">'
    +'<div style="font-weight:700;font-size:12px;color:#185FA5;margin-bottom:6px">Identificação de acesso — TAG RFID</div>'
    +corpo
    +(pode?'':'<div style="font-size:11px;color:#888;margin-top:6px">Somente Admin / Diretoria / Gestor / Coordenador cadastram ou bloqueiam.</div>')
    +'<div style="margin-top:10px;display:grid;grid-template-columns:1fr auto;gap:6px;align-items:end">'
    +'<div><label style="font-size:10px;color:#888;display:block;margin-bottom:2px">UID / TAG simulada</label>'
    +'<input class="inp" id="cena-tag-uid" style="width:100%;font-family:monospace;letter-spacing:.04em" placeholder="Ex.: A1 B2 C3 D4" autocomplete="off"/></div>'
    +'<button class="btn btn-sm" type="button" onclick="cenaTagAcaoResolver(\''+veicId+'\')">Resolver TAG</button>'
    +'</div>'
    +'<div id="cena-tag-resolver-out" style="font-size:12px;margin-top:6px;color:#555"></div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:10px">'
    +(pode?'<button class="btn btn-sm" type="button" onclick="cenaTagAcaoVincular(\''+veicId+'\')">Vincular TAG</button>':'')
    +(pode&&st==='ATIVO'?'<button class="btn btn-sm" type="button" onclick="cenaTagAcaoSubstituir(\''+veicId+'\')">Substituir TAG</button>':'')
    +(pode&&st==='ATIVO'?'<button class="btn btn-sm" type="button" onclick="cenaTagAcaoBloquear(\''+veicId+'\')" style="color:#A32D2D;border-color:#A32D2D">Bloquear TAG</button>':'')
    +(pode&&st==='BLOQUEADO'?'<button class="btn btn-sm" type="button" onclick="cenaTagAcaoReativar(\''+veicId+'\')">Reativar TAG</button>':'')
    +'</div>'
    +(hist?'<div style="margin-top:10px"><div style="font-size:10px;font-weight:700;color:#888;text-transform:uppercase;margin-bottom:4px">Histórico</div>'+hist+'</div>':'')
    +'<div style="font-size:10px;color:#888;margin-top:8px">Leitura simulada. Sem hardware. Não abre portão.</div>'
    +'</div>';
}

function cenaTagMontarSecao(veicId, vei){
  var el = document.getElementById('cena-tag-secao');
  if(!el || !veicId) return;
  el.innerHTML = '<div style="padding:10px;color:#888;font-size:12px">Carregando TAG do veículo…</div>';
  cenaTagCarregarCredenciais(veicId).then(function(lista){
    var box = document.getElementById('cena-tag-secao');
    if(!box) return;
    box.innerHTML = cenaTagSecaoHtml(veicId, vei, lista);
  }).catch(function(){
    var box = document.getElementById('cena-tag-secao');
    if(box) box.innerHTML = cenaTagSecaoHtml(veicId, vei, []);
  });
}

function cenaTagUidCampo(){
  return cenaTagNormalizarUid(((document.getElementById('cena-tag-uid')||{}).value)||'');
}

function cenaTagMostrarResolver(r, uid){
  var out = document.getElementById('cena-tag-resolver-out');
  if(!out) return;
  if(!r || r.motivo==='UID_VAZIO'){
    out.innerHTML = '<span style="color:#A32D2D">Informe um UID para resolver.</span>';
    return;
  }
  if(!r.encontrado){
    out.innerHTML = '<span style="color:#A32D2D">Não encontrada · '+cenaTagEsc(r.motivo||'TAG_DESCONHECIDA')+'</span>';
    return;
  }
  var vei = r.veiculo||{};
  var cor = r.autenticavel ? '#3B6D11' : '#A32D2D';
  out.innerHTML = '<span style="color:'+cor+'">'+(r.autenticavel?'Identificada e autenticável':'Não autentica')
    +' · '+(r.motivo||'OK')
    +' · '+(vei.placa||'—')+' '+(vei.modelo||'')
    +' · credencial '+(r.credencial&&r.credencial.status||'—')
    +'</span>'
    +'<div style="font-size:10px;color:#888;margin-top:2px">UID normalizado: '+cenaTagEsc(uid)+' · sem decisão de portão</div>';
}

async function cenaTagAcaoResolver(veicId){
  var uid = ((document.getElementById('cena-tag-uid')||{}).value||'').trim();
  var r = await cenaTagResolverVeiculo(uid);
  cenaTagMostrarResolver(r, cenaTagNormalizarUid(uid));
}

async function cenaTagAcaoVincular(veicId){
  if(!cenaTagPodeCadastrar()){ if(typeof progShowToast==='function') progShowToast('Sem permissão para cadastrar TAG.','erro'); return; }
  var uid = ((document.getElementById('cena-tag-uid')||{}).value||'').trim();
  if(!cenaTagNormalizarUid(uid)){ alert('Informe o UID / TAG simulada.'); return; }
  var r = await cenaTagExecVincular(veicId, uid);
  if(!r.ok){
    if(typeof progShowToast==='function') progShowToast(r.error||'Falha ao vincular TAG','erro');
    else alert(r.error||'Falha ao vincular TAG');
    return;
  }
  if(typeof progShowToast==='function') progShowToast('TAG vinculada.');
  cenaTagMontarSecao(veicId, cenaTagDadosVeic(veicId));
}

async function cenaTagAcaoSubstituir(veicId){
  if(!cenaTagPodeCadastrar()){ if(typeof progShowToast==='function') progShowToast('Sem permissão para substituir TAG.','erro'); return; }
  var uid = ((document.getElementById('cena-tag-uid')||{}).value||'').trim();
  if(!cenaTagNormalizarUid(uid)){ alert('Informe o novo UID / TAG simulada.'); return; }
  var motivo = prompt('Motivo da substituição (opcional):','')||'';
  var r = await cenaTagExecSubstituir(veicId, uid, motivo);
  if(!r.ok){
    if(typeof progShowToast==='function') progShowToast(r.error||'Falha ao substituir TAG','erro');
    else alert(r.error||'Falha ao substituir TAG');
    return;
  }
  if(typeof progShowToast==='function') progShowToast('TAG substituída. Histórico preservado.');
  cenaTagMontarSecao(veicId, cenaTagDadosVeic(veicId));
}

async function cenaTagAcaoBloquear(veicId){
  if(!cenaTagPodeCadastrar()){ if(typeof progShowToast==='function') progShowToast('Sem permissão para bloquear TAG.','erro'); return; }
  var motivo = prompt('Motivo do bloqueio (obrigatório):','');
  if(motivo==null) return;
  if(!String(motivo).trim()){ alert('Informe o motivo do bloqueio.'); return; }
  var r = await cenaTagExecBloquear(veicId, String(motivo).trim());
  if(!r.ok){
    if(typeof progShowToast==='function') progShowToast(r.error||'Falha ao bloquear TAG','erro');
    else alert(r.error||'Falha ao bloquear TAG');
    return;
  }
  if(typeof progShowToast==='function') progShowToast('TAG bloqueada. Não autentica.');
  cenaTagMontarSecao(veicId, cenaTagDadosVeic(veicId));
}

async function cenaTagAcaoReativar(veicId){
  if(!cenaTagPodeCadastrar()){ if(typeof progShowToast==='function') progShowToast('Sem permissão para reativar TAG.','erro'); return; }
  if(!confirm('Reativar a TAG bloqueada deste veículo?')) return;
  var r = await cenaTagExecReativar(veicId);
  if(!r.ok){
    if(typeof progShowToast==='function') progShowToast(r.error||'Falha ao reativar TAG','erro');
    else alert(r.error||'Falha ao reativar TAG');
    return;
  }
  if(typeof progShowToast==='function') progShowToast('TAG reativada.');
  cenaTagMontarSecao(veicId, cenaTagDadosVeic(veicId));
}

function cenaTagDadosVeic(veicId){
  return (typeof frt_veiculos!=='undefined'?frt_veiculos:[]).find(function(v){ return String(v.id)===String(veicId); }) || {id:veicId};
}

/* PORT-AUTO-SYS-1C — pontos de acesso + dispositivos lógicos (SIMULADO). Sem hardware. */
var _cenaAcessoPontos = [];
var _cenaAcessoDisps = [];
