function cenaAcessoInfraPodeCadastrar(){
  var p = String((typeof usuarioLogado!=='undefined' && usuarioLogado && usuarioLogado.perfil) || '').toLowerCase().trim();
  return ['admin','diretoria','gestor','coordenador'].indexOf(p) >= 0;
}
function cenaAcessoInfraPodeLer(){
  var p = String((typeof usuarioLogado!=='undefined' && usuarioLogado && usuarioLogado.perfil) || '').toLowerCase().trim();
  return cenaAcessoInfraPodeCadastrar() || ['supervisor','supervisor_tma','portaria','escritorio'].indexOf(p) >= 0;
}
