function cenaAcessoInfraSeedsDemo(){
  var bases = (typeof filiais!=='undefined' && filiais.length) ? filiais : [{id:'f-demo-cena01', codigo:'CENA01', nome:'COAQUIRA (DEMO)'}];
  _cenaAcessoPontos = [];
  _cenaAcessoDisps = [];
  bases.forEach(function(f){
    var suf = String(f.codigo||'BASE').replace(/\s+/g,'_');
    cenaAcessoInfraTplPontos().forEach(function(p){
      _cenaAcessoPontos.push({
        id:'pt-'+f.id+'-'+p.codigo, codigo:p.codigo, nome:p.nome, base_id:f.id,
        tipo:p.tipo, sentido:p.sentido, ativo:true, criado_em:new Date().toISOString()
      });
    });
    cenaAcessoInfraTplDisps().forEach(function(d){
      var ponto = _cenaAcessoPontos.find(function(x){ return x.base_id===f.id && x.codigo===d.ponto; });
      _cenaAcessoDisps.push({
        id:'dp-'+f.id+'-'+d.pref,
        codigo:d.pref+'_'+suf,
        nome:d.nome,
        tipo:d.tipo,
        base_id:f.id,
        ponto_acesso_id: ponto ? ponto.id : null,
        sentido:d.sentido,
        funcao:d.funcao,
        identificador_hardware:d.pref+'_'+suf,
        ativo:true,
        status_comunicacao:'SIMULADO',
        ultima_comunicacao:null,
        configuracao:{origem:'SEED_1C', simulado:true, sem_hardware:true}
      });
    });
  });
}
function cenaAcessoInfraCarregar(){
  if(typeof DEMO!=='undefined' && DEMO){
    if(!_cenaAcessoPontos.length) cenaAcessoInfraSeedsDemo();
    _cenaAcessoInfraCarregado = true;
    return Promise.resolve();
  }
  return Promise.all([
    sbFetch('portaria_pontos_acesso', {requireAuth:true, select:'id,codigo,nome,base_id,portaria_id,tipo,sentido,ativo,criado_em,atualizado_em', order:'codigo', limit:200}),
    sbFetch('portaria_dispositivos', {requireAuth:true, select:'id,codigo,nome,tipo,base_id,ponto_acesso_id,sentido,funcao,identificador_hardware,ativo,status_comunicacao,ultima_comunicacao,configuracao,criado_em,atualizado_em', order:'codigo', limit:400})
  ]).then(function(arr){
    _cenaAcessoPontos = arr[0]||[];
    _cenaAcessoDisps = arr[1]||[];
    _cenaAcessoInfraCarregado = true;
    if(!_cenaAcessoPontos.length){
      console.info('[CENA 1C] portaria_pontos_acesso vazia — aplique sql_portaria_acesso_infra_1c.sql');
    }
  }).catch(function(err){
    console.warn('[CENA 1C] falha ao carregar infra (SQL 1C pendente?)', err);
    _cenaAcessoPontos = [];
    _cenaAcessoDisps = [];
    _cenaAcessoInfraCarregado = true;
  });
}
function cenaAcessoInfraFiltroBase(){
  var el = document.getElementById('cena-acesso-base');
  return el ? String(el.value||'') : '';
}
