    await sbUpdate('portaria_dispositivos', {ativo:!!ativo}, 'id=eq.'+id);
    var row = _cenaAcessoDisps.find(function(x){ return String(x.id)===String(id); });
    if(row) row.ativo=!!ativo;
    cenaAcessoInfraRender();
    cenaAcessoInfraToast(ativo?'Dispositivo ativado.':'Dispositivo desativado.');
