var _modalBackdropDown = null;
function modalBackdropPointerDown(ev){
  _modalBackdropDown = (ev.target === ev.currentTarget) ? ev.currentTarget : null;
}
function modalBackdropPointerUp(ev){
  var bg = ev.currentTarget;
  if(_modalBackdropDown === bg && ev.target === bg) closeModal();
  _modalBackdropDown = null;
}
function modalBackdropTouchEnd(ev){
  var bg = ev.currentTarget;
  var t = ev.changedTouches && ev.changedTouches[0];
  if(_modalBackdropDown === bg && t){
    var el = document.elementFromPoint(t.clientX, t.clientY);
    if(el === bg) closeModal();
  }
  _modalBackdropDown = null;
}
function modalWireBackdropClose(root){
  if(!root) return;
  root.querySelectorAll('.modal-bg').forEach(function(bg){
    if(bg.getAttribute('data-backdrop-wired') === '1') return;
    bg.setAttribute('data-backdrop-wired','1');
    var oc = bg.getAttribute('onclick')||'';
    if(oc.indexOf('closeModal') >= 0) bg.removeAttribute('onclick');
    bg.addEventListener('mousedown', modalBackdropPointerDown);
    bg.addEventListener('mouseup', modalBackdropPointerUp);
    bg.addEventListener('touchstart', modalBackdropPointerDown, {passive:true});
    bg.addEventListener('touchend', modalBackdropTouchEnd, {passive:true});
  });
}

function cenaModalHost(){
  var ma=document.getElementById('modal-area');
  if(ma) return ma;
  ma=document.createElement('div');
  ma.id='modal-area';
  var host=document.body||document.documentElement;
  if(host) host.appendChild(ma);
  return document.getElementById('modal-area')||ma;
}
function setModal(html){
  var ma=cenaModalHost();
  if(!ma){ console.error('setModal: #modal-area indisponível'); return; }
  ma.style.pointerEvents='auto';
  ma.innerHTML=html||'';
  ma.style.pointerEvents=html?'auto':'none';
  if(html){
    modalWireBackdropClose(ma);
    if(typeof _autoRefresh !== 'undefined'){
      _autoRefresh._pausadoAntesModal = _autoRefresh._pausado;
      if(!_autoRefresh._pausado) _autoRefresh.pausar();
      _autoRefresh._modalAberto = true;
    }
    // Ordenar selects do modal alfabeticamente
    setTimeout(function(){
      ma.querySelectorAll('select:not([data-nosort])').forEach(function(sel){
        sortarOpts(sel, true);
      });
    }, 30);
    // Se estiver no diário de bordo, scrollar para o modal
    var pgDiario=document.getElementById('pg-diario');
    var isDiario = pgDiario && !pgDiario.classList.contains('hidden');
    if(isDiario){
      setTimeout(function(){
        var modalEl=ma.querySelector('.modal');
        if(modalEl) modalEl.scrollIntoView({behavior:'smooth',block:'center'});
      },100);
    } else {
      window.scrollTo({top:0,behavior:'smooth'});
    }
  }
}
function closeModal(){
  if(typeof cenaRfidCancelarLeitura==='function') cenaRfidCancelarLeitura();
  _modalBackdropDown = null;
  var ma=document.getElementById('modal-area');
  if(!ma) return;
  ma.style.pointerEvents='none';
  ma.innerHTML='';
  ma.style.pointerEvents='none';
  window._eeNfFile=null; window._eeNfBase64=null; window._eeNfMime='';
  if(typeof _almReq!=='undefined'){
    _almReq.corrigindoInfo=false;
    _almReq.corrSnapshot=null;
  }
  if(typeof _autoRefresh !== 'undefined' && _autoRefresh._modalAberto){
    _autoRefresh._modalAberto = false;
    if(!_autoRefresh._pausadoAntesModal) _autoRefresh.retomar();
  }
}

// ── btnBusy: anti-duplo-clique + feedback visual em botões de ação ─────────
// Uso:  onclick="btnBusy(this, minhaFn, 'Salvando…')"
//       onclick="btnBusy(this, function(){ return fn(arg); }, 'Salvando…')"
// Desabilita o botão na hora (bloqueia cliques repetidos por rede lenta),
// troca o rótulo por spinner enquanto roda e restaura ao terminar (ou em erro).
// Serve para fn síncrona ou async. NÃO substitui travas de reentrada das
// funções críticas — é a camada visual + trava de clique.
function btnBusy(btn, fn, txtBusy){
  if(typeof fn!=='function') return;
  if(btn && (btn.disabled || btn.getAttribute('data-bb')==='1')) return; // já ocupado
  var html0=null;
  if(btn){
    html0=btn.innerHTML;
    btn.setAttribute('data-bb','1');
    btn.disabled=true;
    btn.style.opacity='.65';
    btn.style.cursor='progress';
    if(txtBusy) btn.innerHTML='<span class="bb-spin"></span>'+txtBusy;
  }
  function _bbRestaura(){
    if(btn && btn.isConnected){
      btn.disabled=false;
      btn.removeAttribute('data-bb');
      btn.style.opacity='';
      btn.style.cursor='';
      if(html0!=null) btn.innerHTML=html0;
    }
  }
  var r;
  try{ r=fn.call(btn); }
  catch(e){ console.error('[btnBusy]',e); _bbRestaura(); return; }
  if(r && typeof r.then==='function'){
    r.then(_bbRestaura, function(e){ console.error('[btnBusy]',e); _bbRestaura(); });
  } else {
    _bbRestaura();
  }
}

// ── Rede de segurança GLOBAL contra clique repetido acidental ──────────────
// Cobre o "achei que travou e cliquei de novo" em QUALQUER botão de ação, sem
// tocar em cada onclick: ignora o REPIQUE no mesmo botão dentro de uma janela
// curta. Não afeta o 1º clique, nem botões diferentes, nem cliques espaçados.
// Fora da rede: botões pequenos (.btn-sm — steppers/ações inline) e quem marcar
// data-fastclick. Botões críticos têm proteção própria mais forte (btnBusy +
// trava de reentrada). É uma camada ADITIVA de segurança.
(function(){
  var JANELA=600; // ms entre cliques no mesmo botão
  document.addEventListener('click', function(e){
    var b=(e.target && e.target.closest) ? e.target.closest('button,.btn') : null;
    if(!b) return;
    if(b.classList && b.classList.contains('btn-sm')) return;
    if(b.hasAttribute && b.hasAttribute('data-fastclick')) return;
    var agora=Date.now();
    var ult=b._bbLastClick||0;
    if(agora-ult < JANELA){
      e.stopImmediatePropagation();
      e.preventDefault();
      return;
    }
    b._bbLastClick=agora;
  }, true); // fase de captura: roda antes do onclick inline
})();

// ── Helpers de data e flags de módulos lazy ───────────────────────────────
function _diasAtras(n){
  var d=new Date(Date.now()-n*86400000);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
