// ── Helper para garantir módulo carregado antes de renderizar ─────────────
function _precisaModulo(modName,cb){
  var carregado={'financeiro':function(){return _modFinanceiro;},'obras':function(){return _modObras;},'diario':function(){return _modDiario;},'sesmt':function(){return _modSESMT;},'viabilidade':function(){return _modViabilidade;}};
  var loader={'financeiro':carregarModuloFinanceiro,'obras':carregarModuloObras,'diario':carregarModuloDiario,'sesmt':carregarModuloSESMT,'viabilidade':carregarModuloViabilidade};
  if(carregado[modName]()){cb();return;}
  var spinId='_spin_mod_'+Date.now();
  var spinEl=document.createElement('div');
  spinEl.id=spinId;spinEl.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1a1a18;color:#fff;padding:12px 20px;border-radius:10px;font-size:13px;z-index:9999;opacity:.9';
  spinEl.textContent='Carregando...';document.body.appendChild(spinEl);
  var done=false;
  function finish(){
    if(done) return;
    done=true;
    var el=document.getElementById(spinId);if(el)el.remove();
    try{ cb(); }catch(eCb){ console.error('Erro callback módulo',modName,eCb); }
  }
  // Evita spinner eterno se a rede travar
  var to=setTimeout(function(){
    console.warn('[módulo]',modName,'timeout — seguindo sem aguardar');
    finish();
  },25000);
  Promise.resolve(loader[modName]()).then(function(){
    clearTimeout(to); finish();
  }).catch(function(e){
    console.error('Erro módulo',modName,e);
    clearTimeout(to); finish();
  });
}

