// CONTRATOS
// Valor Consumido = valor lançado manualmente até a data de corte + soma do
// faturamento (financeiro_faturamentos) do contrato a partir da data de corte.
// Sem data de corte cadastrada, soma TODO o faturamento do contrato (a data de
// corte só serve pra restringir a partir de quando a soma automática conta —
// sem ela, não há nada a excluir).
function contratoValorConsumido(c){
  var inicial = Number(c.valor_consumido_inicial||0);
  var corte = c.data_corte ? String(c.data_corte).slice(0,10) : null;
  var faturado = (fin_faturamentos||[]).filter(function(f){
    if(f.contrato_id!==c.id && f.contratante_id!==c.id) return false;
    if(finEhRetencaoAvulsa(f)) return false;
    if(corte && String(f.data_emissao||'').slice(0,10) < corte) return false;
    return true;
  }).reduce(function(s,f){return s+Number(f.valor_bruto||0);},0);
  return inicial + faturado;
}
/** Soma aditivos que alteram valor (valor / prazo_e_valor). */
function contratoValorAditivos(c){
  if(!c||!c.id) return 0;
  return (aditivos||[]).filter(function(a){
    if(String(a.contrato_id)!==String(c.id)) return false;
    var t=String(a.tipo||'').toLowerCase();
    if(t==='prazo') return false;
    return t==='valor' || t==='prazo_e_valor' || t.indexOf('valor')>=0 || (!t && Number(a.valor)>0);
  }).reduce(function(s,a){ return s+Number(a.valor||0); },0);
}
/** Valor contratual vigente = valor base + aditivos de valor. */
function contratoValorTotal(c){
  return Number((c&&c.valor_total)||0) + contratoValorAditivos(c);
}
function contratoSaldo(c){
  return contratoValorTotal(c) - contratoValorConsumido(c);
}

function renderContratos(){
  var q=((document.getElementById('fil-cont-q')||{}).value||'').toLowerCase();
  var st=(document.getElementById('fil-cont-status')||{}).value||'';
  var _cBase=_gestorContAtivo?contratos.filter(function(c){return c.id===_gestorContAtivo;}):contratos;
  var rows=_cBase.filter(function(c){return(!q||c.nome.toLowerCase().indexOf(q)>=0||c.codigo.toLowerCase().indexOf(q)>=0||((c.cliente||'').toLowerCase().indexOf(q)>=0))&&(!st||c.status===st);});
  var stCls={Ativo:'ok',Encerrado:'gray',Suspenso:'warn','Em negociação':'info'};
  document.getElementById('tbody-cont').innerHTML=rows.map(function(c){
    var orc=verbas.filter(function(v){return v.contrato_id===c.id;}).reduce(function(s,v){return s+Number(v.valor_planejado||0);},0);
    var real=verbas.filter(function(v){return v.contrato_id===c.id;}).reduce(function(s,v){return s+Number(v.valor_realizado||0);},0);
    var valTot=contratoValorTotal(c);
    var adit=contratoValorAditivos(c);
    return '<tr><td style="font-weight:500">'+c.codigo+'</td><td>'+c.nome+'</td>'
      +'<td style="color:#888">'+(c.cliente||'—')+'</td><td>'+(c.responsavel||'—')+'</td>'
      +'<td style="font-size:11px">'+fmtD(c.data_inicio)+'</td><td style="font-size:11px">'+fmtD(c.data_termino)+'</td>'
      +'<td style="font-weight:500" title="'+(adit?('Base '+fmtR(c.valor_total)+' + aditivos '+fmtR(adit)):'')+'">'+fmtR(valTot)
      +(adit?'<div style="font-size:10px;color:#888;font-weight:400">inclui aditivo '+fmtR(adit)+'</div>':'')
      +'</td>'
      +'<td>'+fmtR(contratoValorConsumido(c))+'</td>'
      +'<td style="font-weight:500;color:'+(contratoSaldo(c)<0?'#A32D2D':'#3B6D11')+'">'+fmtR(contratoSaldo(c))+'</td>'
      +'<td><span class="bdg '+(stCls[c.status]||'gray')+'">'+c.status+'</span></td>'
      +'<td style="display:flex;gap:4px">'
      +'<button class="btn btn-sm" title="Editar contrato" onclick="openEditarContrato(\''+c.id+'\')">Editar</button>'
      +'<button class="btn btn-sm" onclick="irVerbas(\''+c.id+'\')">Verbas</button>'
      +'<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" onclick="excluirContrato(\''+c.id+'\')">Excluir</button>'
      +'</td></tr>';
  }).join('')||'<tr><td colspan="11" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum contrato</td></tr>';

  // Totalizador
  var totalQtd = rows.length;
  var totalValor = rows.reduce(function(s,c){return s+contratoValorTotal(c);},0);
  var totalConsumido = rows.reduce(function(s,c){return s+contratoValorConsumido(c);},0);
  var totalSaldo = totalValor - totalConsumido;
  var totalOrc = rows.reduce(function(s,c){
    return s+verbas.filter(function(v){return v.contrato_id===c.id;})
      .reduce(function(sv,v){return sv+Number(v.valor_planejado||0);},0);
  },0);

  // Verificar se já existe o rodapé, remover e recriar
  var oldFoot = document.getElementById('cont-totalizador');
  if(oldFoot) oldFoot.remove();

  var tbl = document.querySelector('#tbody-cont') ? document.querySelector('#tbody-cont').closest('table') : null;
  if(tbl){
    var tfoot = document.createElement('tfoot');
    tfoot.id = 'cont-totalizador';
    tfoot.innerHTML = '<tr style="background:#1a1a18;color:#fff">'
      +'<td colspan="4" style="padding:.6rem 1rem;font-size:12px;font-weight:600">'
        +'Total: <b>'+totalQtd+'</b> contrato'+(totalQtd!==1?'s':'')
      +'</td>'
      +'<td colspan="2" style="padding:.6rem 1rem;font-size:12px;text-align:right;font-weight:600">'
        +'Valor total: <b>'+fmtR(totalValor)+'</b>'
      +'</td>'
      +(totalOrc>0
        ?'<td style="padding:.6rem 1rem;font-size:12px;text-align:right;font-weight:600">'
          +'Orçado: <b>'+fmtR(totalOrc)+'</b>'+'</td>'
        :'<td></td>')
      +'<td style="padding:.6rem 1rem;font-size:12px;text-align:right;font-weight:600">'
        +'Consumido: <b>'+fmtR(totalConsumido)+'</b>'
      +'</td>'
      +'<td style="padding:.6rem 1rem;font-size:12px;text-align:right;font-weight:600;color:'+(totalSaldo<0?'#F3A6A6':'#9FE0A6')+'">'
        +'Saldo: <b>'+fmtR(totalSaldo)+'</b>'
      +'</td>'
      +'<td colspan="2"></td>'
      +'</tr>';
    tbl.appendChild(tfoot);
  }
}

function openNovoContrato(){
  // Garantir filiais carregadas antes de abrir o modal
  if(!filiais.length && !DEMO){
    sbFetch('filiais',{filters:['ativa=eq.true'],order:'nome'}).then(function(rows){
      if(rows&&rows.length) filiais=rows;
      _openNovoContratoModal();
    }).catch(function(){ _openNovoContratoModal(); });
    return;
  }
  _openNovoContratoModal();
}
