    +'<div class="fg"><label>Status</label><select id="nc-status"><option>Ativo</option><option>Em negociação</option><option>Suspenso</option><option>Encerrado</option></select></div>'
    +'<div class="fg"><label>Filial responsável</label><select id="nc-filial">'+filOpts+'</select></div>'
    +'<div class="fg"><label>Data de reajuste</label><input id="nc-reaj" type="date"/></div>'
