// LANÇAMENTOS
// ═══════════════════════════════════════════════════════════
// MÓDULO FINANCEIRO — FATURAMENTOS, DRE, DASHBOARD
// ═══════════════════════════════════════════════════════════

var FIN_STATUS_COR = {
  'A Receber': {bg:'#E6F1FB', cor:'#185FA5', bdg:'info'},
  'Vencido':   {bg:'#FCEBEB', cor:'#A32D2D', bdg:'danger'},
  'Recebido':  {bg:'#EAF3DE', cor:'#3B6D11', bdg:'ok'},
};

var FIN_TIPOS_RECEITA = ['Contrato','Medição','Reembolso','Receita Operacional','Receita Extraordinária','Outros'];

var FIN_IPCA_FALLBACK = {
  '2024-01':0.42,'2024-02':0.83,'2024-03':0.16,'2024-04':0.38,'2024-05':0.46,'2024-06':0.21,
  '2024-07':0.38,'2024-08':0.02,'2024-09':0.44,'2024-10':0.56,'2024-11':0.39,'2024-12':0.52,
  '2025-01':0.16,'2025-02':0.83,'2025-03':0.56,'2025-04':0.43,'2025-05':0.26,'2025-06':0.24,
  '2025-07':0.26,'2025-08':0.22,'2025-09':0.48,'2025-10':0.42,'2025-11':0.18,'2025-12':0.52,
  '2026-01':0.30,'2026-02':0.20,'2026-03':0.25,'2026-04':0.22,'2026-05':0.30,'2026-06':0.25
};

function finRetencaoPctContrato(cid){
  var c=contratos.find(function(x){return x.id===cid;});
  if(!c||c.retencao_percentual==null||c.retencao_percentual==='') return 0;
  return Number(c.retencao_percentual)||0;
}

/** Contrato cadastrado ou dados de contrato legado (não cadastrado). */
function finRetencaoContratoInfo(f){
  f=f||{};
  var c=(contratos||[]).find(function(x){return x.id===f.contrato_id;})||{};
  if(f.contrato_id&&c.id){
    return {codigo:c.codigo||'—', nome:c.nome||'—', cliente:c.cliente||'', legado:false, avulsa:!!f.eh_retencao_avulsa};
  }
  return {
    codigo:f.contrato_legado_codigo||'—',
    nome:f.contrato_legado_nome||(f.eh_retencao_avulsa?'Contrato legado':'—'),
    cliente:f.cliente_legado||'',
    legado:true,
    avulsa:!!f.eh_retencao_avulsa
  };
}

function finEhRetencaoAvulsa(f){
  return !!(f&&(f.eh_retencao_avulsa||f.tipo==='Retenção Avulsa'));
}

function finCalcValorRetencao(bruto,cid,manualVal){
  if(manualVal!=null&&manualVal!=='') return Math.round(Number(manualVal)*100)/100;
  var pct=finRetencaoPctContrato(cid);
  if(!pct||!bruto) return 0;
  return Math.round(Number(bruto)*pct/100*100)/100;
}

function finCalcTotalRecebido(f){
  f=f||{};
  var liq=Number(f.valor_liquido||0);
  var ret=Number(f.valor_retencao||0);
  var juros=Number(f.juros_antecipacao||0);
  return Math.round(Math.max(0,liq-ret-juros)*100)/100;
}

function finIpcaPctMes(ym){
  var row=(fin_indices_ipca||[]).find(function(x){return x.competencia===ym;});
  if(row&&row.percentual!=null) return Number(row.percentual);
  return FIN_IPCA_FALLBACK[ym]!=null?FIN_IPCA_FALLBACK[ym]:0;
}

function finAddMesYm(ym,delta){
  var y=parseInt(String(ym).slice(0,4),10), m=parseInt(String(ym).slice(5,7),10);
  m+=delta;
  while(m>12){m-=12;y++;}
  while(m<1){m+=12;y--;}
  return y+'-'+String(m).padStart(2,'0');
}

function finIpcaFator(dataEmissao,dataRef){
  if(!dataEmissao) return 1;
  var ini=String(dataEmissao).slice(0,7);
  var fim=String(dataRef||dataHojeLocal()).slice(0,7);
  if(ini>=fim) return 1;
  var cur=finAddMesYm(ini,1), fator=1;
  while(cur<=fim){
    fator*=(1+finIpcaPctMes(cur)/100);
    cur=finAddMesYm(cur,1);
  }
  return Math.round(fator*1000000)/1000000;
}

function finRetencaoReajustada(f,dataRef){
  var base=Number(f.valor_retencao||0);
  if(!base) return 0;
  var ref=dataRef||(f.data_retencao_recebimento||dataHojeLocal());
  return Math.round(base*finIpcaFator(f.data_emissao,ref)*100)/100;
}

function finAplicarRetencoesAutomaticas(){
  (fin_faturamentos||[]).forEach(function(f){
    if(f.valor_retencao_manual||!f.contrato_id) return;
    var pct=finRetencaoPctContrato(f.contrato_id);
    if(!pct||!f.valor_bruto) return;
    f.valor_retencao=finCalcValorRetencao(f.valor_bruto,f.contrato_id);
  });
}

async function finRecalcRetencoesFaturamentos(silent){
  var n=0;
  for(var i=0;i<(fin_faturamentos||[]).length;i++){
    var f=fin_faturamentos[i];
    if(f.valor_retencao_manual||!f.contrato_id) continue;
    var pct=finRetencaoPctContrato(f.contrato_id);
    if(!pct||!f.valor_bruto) continue;
    var novo=finCalcValorRetencao(f.valor_bruto,f.contrato_id);
    if(Number(f.valor_retencao||0)===novo) continue;
    f.valor_retencao=novo;
    n++;
    if(!DEMO&&f.id) await sbUpdate('financeiro_faturamentos',{valor_retencao:novo,valor_retencao_manual:false,updated_at:new Date().toISOString()},'id=eq.'+f.id);
  }
  if(!silent&&typeof progShowToast==='function') progShowToast(n?('Retenções recalculadas: '+n+' NF-e.'):'Nenhuma retenção a recalcular.');
  finRenderFaturados();
  finRenderRetencoes();
}

function finFiltrarRetencoes(){
  var cli=(document.getElementById('ret-fil-cliente')||{}).value||'';
  var cid=(document.getElementById('ret-fil-cont')||{}).value||'';
  var st=(document.getElementById('ret-fil-status')||{}).value||'';
  return (fin_faturamentos||[]).filter(function(f){
    if(!Number(f.valor_retencao||0)) return false;
    var info=finRetencaoContratoInfo(f);
    if(cli&&info.cliente!==cli) return false;
    if(cid==='__legado__'){ if(!info.legado&&!finEhRetencaoAvulsa(f)) return false; }
    else if(cid&&f.contrato_id!==cid) return false;
    if(st==='avulsa'&&!finEhRetencaoAvulsa(f)&&!info.legado) return false;
    var reaj=finRetencaoReajustada(f);
    var rec=Number(f.valor_retencao_recebido||0);
    var saldo=Math.round((reaj-rec)*100)/100;
    if(st==='pendente'&&saldo<=0) return false;
    if(st==='recebido'&&saldo>0) return false;
    return true;
  });
}

function finPopularRetencaoFiltros(){
  var selCli=document.getElementById('ret-fil-cliente');
  if(selCli){
    var pv=selCli.value||'';
    var clientes={};
    (contratos||[]).forEach(function(c){if(c.cliente) clientes[c.cliente]=true;});
    (fin_faturamentos||[]).forEach(function(f){
      var info=finRetencaoContratoInfo(f);
      if(info.cliente) clientes[info.cliente]=true;
    });
    selCli.innerHTML='<option value="">Todos os clientes</option>'
      +Object.keys(clientes).sort().map(function(cl){
        return '<option value="'+escHtml(cl)+'">'+escHtml(cl)+'</option>';
      }).join('');
    selCli.value=pv;
  }
  var selCont=document.getElementById('ret-fil-cont');
  if(selCont){
    var pvC=selCont.value||'';
    var opts='<option value="">Todos os contratos</option>'
      +'<option value="__legado__">Contratos legados / avulsos</option>';
    (contratos||[]).slice().sort(function(a,b){
      return(a.codigo||a.nome||'').localeCompare(b.codigo||b.nome||'');
    }).forEach(function(c){
      opts+='<option value="'+escHtml(c.id)+'">'+escHtml((c.codigo?c.codigo+' — ':'')+(c.nome||''))+'</option>';
    });
    selCont.innerHTML=opts;
    selCont.value=pvC;
  }
}

function finRenderRetencoes(){
  finAplicarRetencoesAutomaticas();
  finPopularRetencaoFiltros();
  var lista=finFiltrarRetencoes();
  var tb=document.getElementById('ret-tbody'); if(!tb) return;
  var totRet=0, totReaj=0, totRec=0, totSaldo=0;
  lista.forEach(function(f){
    var ret=Number(f.valor_retencao||0);
    var reaj=finRetencaoReajustada(f);
    var rec=Number(f.valor_retencao_recebido||0);
    var saldo=Math.round((reaj-rec)*100)/100;
    totRet+=ret; totReaj+=reaj; totRec+=rec; totSaldo+=saldo;
  });
  var res=document.getElementById('ret-resumo');
  if(res) res.innerHTML=[
    {l:'Retenção original', v:finFmt(totRet), c:'#555'},
    {l:'Reajustado (IPCA)', v:finFmt(totReaj), c:'#185FA5'},
    {l:'Recebido', v:finFmt(totRec), c:'#3B6D11'},
    {l:'Saldo', v:finFmt(totSaldo), c:totSaldo>0?'#854F0B':'#3B6D11'},
    {l:'Lançamentos', v:String(lista.length), c:'#534AB7'},
  ].map(function(x){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:8px 12px;text-align:center">'
      +'<div style="font-size:10px;color:#888;margin-bottom:3px">'+x.l+'</div>'
      +'<div style="font-size:15px;font-weight:700;color:'+x.c+'">'+x.v+'</div></div>';
  }).join('');
  if(!lista.length){
    tb.innerHTML='<tr><td colspan="10" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma retenção encontrada. Use <b>+ Lançar retenção</b> para avulsas/legado, ou defina % no contrato e fature.</td></tr>';
    return;
  }
  lista.sort(function(a,b){return String(a.data_emissao||'').localeCompare(String(b.data_emissao||''));});
  tb.innerHTML=lista.map(function(f){
    var info=finRetencaoContratoInfo(f);
    var reaj=finRetencaoReajustada(f);
    var rec=Number(f.valor_retencao_recebido||0);
    var saldo=Math.round((reaj-rec)*100)/100;
    var badge=info.legado||finEhRetencaoAvulsa(f)
      ?'<div style="font-size:9px;color:#854F0B;margin-top:2px">Avulsa / legado</div>':'';
    return '<tr>'
      +'<td style="font-family:monospace;font-size:12px">'+escHtml(info.codigo)+badge+'</td>'
      +'<td style="font-size:12px">'+escHtml(info.nome)
      +(info.cliente?'<div style="font-size:10px;color:#888">'+escHtml(info.cliente)+'</div>':'')+'</td>'
      +'<td style="font-family:monospace;font-size:12px">'+(f.nfe||'—')+'</td>'
      +'<td style="font-size:12px">'+fmtD(f.data_emissao)+'</td>'
      +'<td style="text-align:right;font-size:12px">'+finFmt(f.valor_retencao)+'</td>'
      +'<td style="text-align:right;font-size:12px;font-weight:600;color:#185FA5" title="IPCA até '+(f.data_retencao_recebimento?fmtD(f.data_retencao_recebimento):'hoje')+'">'+finFmt(reaj)+'</td>'
      +'<td style="text-align:right;font-size:12px;color:#3B6D11">'+finFmt(rec)+'</td>'
      +'<td style="text-align:right;font-size:12px;font-weight:600;color:'+(saldo>0?'#854F0B':'#3B6D11')+'">'+finFmt(saldo)+'</td>'
      +'<td style="font-size:12px">'+(f.data_retencao_recebimento?fmtD(f.data_retencao_recebimento):'—')+'</td>'
      +'<td style="white-space:nowrap;display:flex;gap:4px;flex-wrap:wrap">'
      +'<button class="btn btn-sm btn-pri" onclick="finAbrirRecebimentoRetencao(\''+escHtml(f.id)+'\')">'+(saldo>0?'Receber':'Editar rec.')+'</button>'
      +'<button class="btn btn-sm" onclick="finAbrirEditarRetencao(\''+escHtml(f.id)+'\')" title="Editar retenção">Editar</button>'
      +'<button class="btn btn-sm" style="color:#A32D2D;border-color:#F4C0C0" onclick="finExcluirRetencao(\''+escHtml(f.id)+'\')" title="Excluir ou zerar retenção">Excluir</button>'
      +'</td>'
      +'</tr>';
  }).join('');
}

/** Modal: lançar ou editar retenção avulsa (contrato cadastrado ou legado). */
function finAbrirLancamentoRetencao(id){
  var f=id?(fin_faturamentos||[]).find(function(x){return x.id===id;}):null;
  var isEdit=!!f; f=f||{};
  var modoLegado=!f.contrato_id||!!f.contrato_legado_codigo||!!f.cliente_legado;
  if(isEdit&&f.contrato_id&&!f.contrato_legado_codigo) modoLegado=false;
  if(!isEdit) modoLegado=false;
  var optsContr=(contratos||[]).slice().sort(function(a,b){
    return(a.codigo||a.nome||'').localeCompare(b.codigo||b.nome||'');
  }).map(function(c){
    return '<option value="'+escHtml(c.id)+'"'+(f.contrato_id===c.id?' selected':'')+'>'
      +escHtml((c.codigo?c.codigo+' — ':'')+(c.nome||''))+'</option>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px">'
    +'<h3 style="margin-bottom:.35rem">'+(isEdit?'Editar retenção avulsa':'Lançar retenção')+'</h3>'
    +'<div style="font-size:11px;color:#555;margin-bottom:1rem;padding:.65rem;background:#EBF4FD;border-radius:8px">'
    +'Use para controle e cobrança futura. Pode vincular a um contrato do ERP ou informar um <b>contrato antigo não cadastrado</b> (só para constar).</div>'
    +'<div style="display:flex;gap:8px;margin-bottom:1rem">'
    +'<label style="font-size:12px;display:flex;align-items:center;gap:6px;cursor:pointer">'
    +'<input type="radio" name="ret-lanc-modo" id="ret-lanc-modo-cad" value="cad"'+(modoLegado?'':' checked')+' onchange="finRetLancToggleModo()"/> Contrato cadastrado</label>'
    +'<label style="font-size:12px;display:flex;align-items:center;gap:6px;cursor:pointer">'
    +'<input type="radio" name="ret-lanc-modo" id="ret-lanc-modo-leg" value="leg"'+(modoLegado?' checked':'')+' onchange="finRetLancToggleModo()"/> Contrato legado (não cadastrado)</label>'
    +'</div>'
    +'<div id="ret-lanc-wrap-cad" style="display:'+(modoLegado?'none':'block')+'">'
    +'<div class="fg"><label>Contrato</label><select class="inp" id="ret-lanc-cont" style="width:100%"><option value="">Selecione</option>'+optsContr+'</select></div>'
    +'</div>'
    +'<div id="ret-lanc-wrap-leg" style="display:'+(modoLegado?'block':'none')+'">'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'
    +'<div class="fg"><label>Nº / código do contrato</label><input class="inp" id="ret-lanc-cod" style="width:100%" value="'+escHtml(f.contrato_legado_codigo||'')+'" placeholder="Ex.: 4600001234"/></div>'
    +'<div class="fg"><label>Cliente</label><input class="inp" id="ret-lanc-cli" style="width:100%" value="'+escHtml(f.cliente_legado||'')+'" placeholder="Nome do cliente"/></div>'
    +'<div class="fg" style="grid-column:span 2"><label>Nome / descrição do contrato</label><input class="inp" id="ret-lanc-nome" style="width:100%" value="'+escHtml(f.contrato_legado_nome||'')+'" placeholder="Ex.: Manutenção predial 2019–2021"/></div>'
    +'</div></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px">'
    +'<div class="fg"><label>NFE (opcional)</label><input class="inp" id="ret-lanc-nfe" style="width:100%" value="'+escHtml(f.nfe||'')+'"/></div>'
    +'<div class="fg"><label>Data referência</label><input class="inp" type="date" id="ret-lanc-data" style="width:100%" value="'+(f.data_emissao||dataHojeLocal())+'"/></div>'
    +'<div class="fg"><label>Valor retenção (R$) *</label><input class="inp" type="number" step="0.01" id="ret-lanc-val" style="width:100%" value="'+(f.valor_retencao!=null?f.valor_retencao:'')+'"/></div>'
    +'<div class="fg"><label>Valor bruto NF (opc.)</label><input class="inp" type="number" step="0.01" id="ret-lanc-bruto" style="width:100%" value="'+(f.valor_bruto||'')+'" placeholder="Só referência"/></div>'
    +'<div class="fg" style="grid-column:span 2"><label>Observação</label><textarea class="inp" id="ret-lanc-obs" style="width:100%;height:56px" placeholder="Motivo, período, quem cobrar…">'+escHtml(f.observacao||'')+'</textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:1rem">'
    +(isEdit?'<button class="btn" style="color:#A32D2D" onclick="finExcluirRetencaoAvulsa(\''+escHtml(f.id)+'\')">Excluir</button>':'')
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="ret-lanc-salvar" style="flex:2">'+(isEdit?'Salvar alterações':'Lançar retenção')+'</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var btn=document.getElementById('ret-lanc-salvar');
    if(!btn) return;
    btn.onclick=function(){ finSalvarLancamentoRetencao(isEdit?f:null); };
  },40);
}

function finRetLancToggleModo(){
  var leg=!!(document.getElementById('ret-lanc-modo-leg')||{}).checked;
  var wCad=document.getElementById('ret-lanc-wrap-cad');
  var wLeg=document.getElementById('ret-lanc-wrap-leg');
  if(wCad) wCad.style.display=leg?'none':'block';
  if(wLeg) wLeg.style.display=leg?'block':'none';
}

async function finSalvarLancamentoRetencao(existente){
  var leg=!!(document.getElementById('ret-lanc-modo-leg')||{}).checked;
  var val=parseFloat((document.getElementById('ret-lanc-val')||{}).value);
  if(!val||val<=0){ progShowToast('Informe o valor da retenção.','erro'); return; }
  var cid=null, codLeg=null, nomeLeg=null, cliLeg=null;
  if(leg){
    codLeg=((document.getElementById('ret-lanc-cod')||{}).value||'').trim()||null;
    nomeLeg=((document.getElementById('ret-lanc-nome')||{}).value||'').trim()||null;
    cliLeg=((document.getElementById('ret-lanc-cli')||{}).value||'').trim()||null;
    if(!codLeg&&!nomeLeg){ progShowToast('Informe ao menos o código ou o nome do contrato legado.','erro'); return; }
  } else {
    cid=((document.getElementById('ret-lanc-cont')||{}).value||'')||null;
    if(!cid){ progShowToast('Selecione o contrato.','erro'); return; }
  }
  var bruto=parseFloat((document.getElementById('ret-lanc-bruto')||{}).value)||0;
  var dados={
    nfe:((document.getElementById('ret-lanc-nfe')||{}).value||'').trim()||null,
    contrato_id:cid,
    contrato_legado_codigo:codLeg,
    contrato_legado_nome:nomeLeg,
    cliente_legado:cliLeg,
    eh_retencao_avulsa:true,
    tipo:'Retenção Avulsa',
    data_emissao:(document.getElementById('ret-lanc-data')||{}).value||dataHojeLocal(),
    data_vencimento:null,
    valor_bruto:bruto,
    valor_retencao:Math.round(val*100)/100,
    valor_retencao_manual:true,
    valor_liquido:0,
    juros_antecipacao:0,
    status:'A Receber',
    observacao:((document.getElementById('ret-lanc-obs')||{}).value||'').trim()||'',
    origem_api:false,
    updated_at:new Date().toISOString()
  };
  if(existente){
    dados.valor_retencao_recebido=existente.valor_retencao_recebido||0;
    dados.data_retencao_recebimento=existente.data_retencao_recebimento||null;
  } else {
    dados.valor_retencao_recebido=0;
    dados.data_retencao_recebimento=null;
    dados.created_at=dados.updated_at;
  }
  try{
    if(!DEMO){
      if(existente&&existente.id){
        await sbUpdate('financeiro_faturamentos',dados,'id=eq.'+existente.id);
        Object.assign(existente,dados);
      } else {
        var ins=await sbInsert('financeiro_faturamentos',dados);
        if(ins&&ins[0]) fin_faturamentos.unshift(ins[0]);
        else { dados.id='fat-ret-'+Date.now(); fin_faturamentos.unshift(dados); }
      }
    } else {
      if(existente) Object.assign(existente,dados);
      else { dados.id='fat-ret-'+Date.now(); fin_faturamentos.unshift(dados); }
    }
    closeModal();
    finRenderRetencoes();
    progShowToast(existente?'Retenção atualizada.':'Retenção lançada — controle disponível para cobrança.');
  }catch(e){
    console.error(e);
    var msg=String((e&&(e.message||e.msg))||e||'');
    if(/eh_retencao|contrato_legado|column|PGRST204/i.test(msg))
      progShowToast('Rode sql_fin_retencao_manual.sql no Supabase e tente de novo.','erro');
    else progShowToast('Erro ao salvar retenção.','erro');
  }
}

async function finExcluirRetencaoAvulsa(id){
  return finExcluirRetencao(id);
}

/** Editar retenção: avulsa usa modal completo; de faturamento edita valor/NFE/obs. */
function finAbrirEditarRetencao(id){
  var f=(fin_faturamentos||[]).find(function(x){return x.id===id;});
  if(!f){ progShowToast('Retenção não encontrada.','erro'); return; }
  if(finEhRetencaoAvulsa(f)){ finAbrirLancamentoRetencao(id); return; }
  var info=finRetencaoContratoInfo(f);
  var pct=f.contrato_id?finRetencaoPctContrato(f.contrato_id):0;
  var autoSug=finCalcValorRetencao(f.valor_bruto,f.contrato_id);
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin-bottom:.35rem">Editar retenção</h3>'
    +'<div style="font-size:11px;color:#555;margin-bottom:1rem;padding:.65rem;background:#f9f9f7;border-radius:8px">'
    +'<div><b>'+escHtml(info.codigo)+'</b> · '+escHtml(info.nome)+'</div>'
    +'<div>Origem: faturamento NF'+(f.nfe?' <b>'+escHtml(f.nfe)+'</b>':'')+' · Bruto '+finFmt(f.valor_bruto||0)
    +(pct?' · % contrato '+pct+'%':'')+'</div></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'
    +'<div class="fg"><label>NFE</label><input class="inp" id="ret-ed-nfe" style="width:100%" value="'+escHtml(f.nfe||'')+'"/></div>'
    +'<div class="fg"><label>Data emissão</label><input class="inp" type="date" id="ret-ed-data" style="width:100%" value="'+(f.data_emissao||'')+'"/></div>'
    +'<div class="fg"><label>Valor retenção (R$) *</label><input class="inp" type="number" step="0.01" id="ret-ed-val" style="width:100%" value="'+(f.valor_retencao!=null?f.valor_retencao:'')+'"/>'
    +'<div style="font-size:10px;color:#888;margin-top:2px">Sugestão auto: '+finFmt(autoSug)
    +' <button type="button" class="btn btn-sm" style="font-size:10px;padding:1px 6px" onclick="document.getElementById(\'ret-ed-val\').value='+autoSug+'">Usar</button></div></div>'
    +'<div class="fg"><label>Já recebido (R$)</label><input class="inp" type="number" step="0.01" id="ret-ed-rec" style="width:100%" value="'+(f.valor_retencao_recebido||0)+'"/></div>'
    +'<div class="fg" style="grid-column:span 2"><label>Observação</label><textarea class="inp" id="ret-ed-obs" style="width:100%;height:56px">'+escHtml(f.observacao||'')+'</textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:1rem;flex-wrap:wrap">'
    +'<button class="btn" style="color:#A32D2D;border-color:#F4C0C0" onclick="finExcluirRetencao(\''+escHtml(f.id)+'\')">Excluir</button>'
    +'<button class="btn" onclick="closeModal();finEditarFaturamento(\''+escHtml(f.id)+'\')" title="Abrir NF completa">Abrir faturamento</button>'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="ret-ed-salvar" style="flex:1">Salvar</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var btn=document.getElementById('ret-ed-salvar'); if(!btn) return;
    btn.onclick=async function(){
      var val=parseFloat((document.getElementById('ret-ed-val')||{}).value);
      if(isNaN(val)||val<0){ progShowToast('Informe o valor da retenção.','erro'); return; }
      var payload={
        nfe:((document.getElementById('ret-ed-nfe')||{}).value||'').trim()||null,
        data_emissao:(document.getElementById('ret-ed-data')||{}).value||f.data_emissao||null,
        valor_retencao:Math.round(val*100)/100,
        valor_retencao_manual:true,
        valor_retencao_recebido:parseFloat((document.getElementById('ret-ed-rec')||{}).value)||0,
        observacao:((document.getElementById('ret-ed-obs')||{}).value||'').trim()||'',
        updated_at:new Date().toISOString()
      };
      try{
        if(!DEMO) await sbUpdate('financeiro_faturamentos',payload,'id=eq.'+f.id);
        Object.assign(f,payload);
        closeModal();
        finRenderRetencoes();
        if(typeof finRenderFaturados==='function') finRenderFaturados();
        progShowToast('Retenção atualizada.');
      }catch(e){ console.error(e); progShowToast('Erro ao salvar.','erro'); }
    };
  },40);
}

/**
 * Excluir retenção:
 * - Avulsa/legado: apaga o registro.
 * - De faturamento: pergunta se zera a retenção (mantém a NF) ou apaga o faturamento inteiro.
 */
async function finExcluirRetencao(id){
  var f=(fin_faturamentos||[]).find(function(x){return x.id===id;});
  if(!f){ progShowToast('Retenção não encontrada.','erro'); return; }
  if(finEhRetencaoAvulsa(f)){
    if(!confirm('Excluir esta retenção avulsa/legado?')) return;
    try{
      if(!DEMO&&f.id) await sbDelete('financeiro_faturamentos','id=eq.'+f.id);
      fin_faturamentos=(fin_faturamentos||[]).filter(function(x){return x.id!==id;});
      closeModal();
      finRenderRetencoes();
      progShowToast('Retenção excluída.');
    }catch(e){ console.error(e); progShowToast('Erro ao excluir.','erro'); }
    return;
  }
  var msg='Esta retenção veio de um faturamento (NF'+(f.nfe?' '+f.nfe:'')+').\n\n'
    +'OK = zerar a retenção e manter a NF no Faturado\n'
    +'Cancelar = não fazer nada';
  if(!confirm(msg)) return;
  try{
    var payload={
      valor_retencao:0,
      valor_retencao_manual:true,
      valor_retencao_recebido:0,
      data_retencao_recebimento:null,
      updated_at:new Date().toISOString()
    };
    if(!DEMO) await sbUpdate('financeiro_faturamentos',payload,'id=eq.'+f.id);
    Object.assign(f,payload);
    closeModal();
    finRenderRetencoes();
    if(typeof finRenderFaturados==='function') finRenderFaturados();
    progShowToast('Retenção zerada (NF mantida no Faturado).');
  }catch(e){ console.error(e); progShowToast('Erro ao zerar retenção.','erro'); }
}

function finAbrirRecebimentoRetencao(id){
  var f=(fin_faturamentos||[]).find(function(x){return x.id===id;});
  if(!f) return;
  var info=finRetencaoContratoInfo(f);
  var reaj=finRetencaoReajustada(f);
  var recAtual=Number(f.valor_retencao_recebido||0);
  var saldo=Math.round((reaj-recAtual)*100)/100;
  setModal('<div class="modal-bg"><div class="modal" style="max-width:460px">'
    +'<h3>Recebimento de retenção'+(f.nfe?' — NFE '+escHtml(f.nfe):'')+'</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:1rem;padding:.65rem;background:#f9f9f7;border-radius:8px">'
    +'<div>'+escHtml(info.codigo)+' · '+escHtml(info.nome)+(info.legado?' <span style="color:#854F0B">(legado)</span>':'')+'</div>'
    +'<div>Retenção original: <strong>'+finFmt(f.valor_retencao)+'</strong></div>'
    +'<div>Reajustado IPCA (hoje): <strong style="color:#185FA5">'+finFmt(reaj)+'</strong></div>'
    +'<div>Saldo pendente: <strong style="color:#854F0B">'+finFmt(Math.max(0,saldo))+'</strong></div></div>'
    +'<div class="fg"><label>Valor recebido (R$)</label>'
    +'<input class="inp" type="number" step="0.01" id="ret-rec-val" value="'+(recAtual||saldo||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Data do recebimento</label>'
    +'<input class="inp" type="date" id="ret-rec-data" value="'+(f.data_retencao_recebimento||dataHojeLocal())+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Valor retenção na NF (editável)</label>'
    +'<input class="inp" type="number" step="0.01" id="ret-rec-base" value="'+(f.valor_retencao||'')+'" style="width:100%"/></div>'
    +'<div style="display:flex;gap:8px;margin-top:1rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="ret-rec-salvar" style="flex:2">Salvar recebimento</button></div></div></div>');
  setTimeout(function(){
    var btn=document.getElementById('ret-rec-salvar');
    if(!btn) return;
    btn.onclick=function(){
      var dataRec=(document.getElementById('ret-rec-data')||{}).value||null;
      var valRec=parseFloat((document.getElementById('ret-rec-val')||{}).value)||0;
      var valRet=parseFloat((document.getElementById('ret-rec-base')||{}).value)||0;
      var payload={
        valor_retencao:valRet,
        valor_retencao_manual:true,
        valor_retencao_recebido:valRec,
        data_retencao_recebimento:dataRec,
        updated_at:new Date().toISOString()
      };
      if(!DEMO){
        sbUpdate('financeiro_faturamentos',payload,'id=eq.'+f.id).then(function(){
          Object.assign(f,payload);
          closeModal();
          finRenderRetencoes();
          finRenderFaturados();
          progShowToast('Recebimento de retenção salvo.');
        });
      } else {
        Object.assign(f,payload);
        closeModal();
        finRenderRetencoes();
        finRenderFaturados();
        progShowToast('Recebimento de retenção salvo.');
      }
    };
  },50);
}

function finMostrarAba(aba){
  ['lancamentos','faturado','retencao','dre','dashboard','sincronizar'].forEach(function(a){
    var el=document.getElementById('fin-aba-'+a);
    var btn=document.getElementById('fin-tab-'+a);
    if(el) el.style.display = a===aba?'':'none';
    if(btn){ btn.style.color=a===aba?'#185FA5':'#888'; btn.style.borderBottomColor=a===aba?'#185FA5':'transparent'; btn.style.fontWeight=a===aba?'600':'500'; }
  });
  if(aba==='faturado')    { finRenderFaturados(); finPopularContratosFat(); }
  if(aba==='retencao')    { finRenderRetencoes(); }
  if(aba==='dre')         { finRenderDRE(); finPopularContratosDRE(); }
  if(aba==='dashboard')   { finRenderDashboard(); }
  if(aba==='sincronizar') {
    // Restaurar logs do localStorage
    if(!_finLogs.length){ try{ _finLogs=JSON.parse(localStorage.getItem('fin_sinc_logs')||'[]'); }catch(e){ _finLogs=[]; } }
    finRenderLogs();
    finRenderSincCards();
  }
}

function finAtualizarStatusVencidos(){
  var hoje=dataHojeLocal();
  fin_faturamentos.forEach(function(f){
    if(f.status!=='Recebido' && f.data_vencimento && f.data_vencimento<hoje) f.status='Vencido';
  });
}

function finPopularContratosFat(){
  var sel=document.getElementById('fat-fil-cont');
  if(!sel||sel.options.length>1)return;
  contratos.sort(function(a,b){return(a.codigo||'').localeCompare(b.codigo||'');}).forEach(function(c){
    var o=document.createElement('option'); o.value=c.id; o.textContent=(c.nome); sel.appendChild(o);
  });
}

function finPopularContratosDRE(){
  var sel=document.getElementById('dre-fil-cont');
  if(!sel||sel.options.length>1)return;
  contratos.sort(function(a,b){return(a.codigo||'').localeCompare(b.codigo||'');}).forEach(function(c){
    var o=document.createElement('option'); o.value=c.id; o.textContent=(c.nome); sel.appendChild(o);
  });
}

function finFmt(v){ return 'R$ '+(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}); }

function finFiltrarFaturamentos(){
  var status  = (document.getElementById('fat-fil-status')||{}).value||'';
  var tipo    = (document.getElementById('fat-fil-tipo')||{}).value||'';
  var cont    = (document.getElementById('fat-fil-cont')||{}).value||'';
  var nfe     = ((document.getElementById('fat-fil-nfe')||{}).value||'').trim().toLowerCase();
  var ini     = (document.getElementById('fat-fil-ini')||{}).value||'';
  var fim     = (document.getElementById('fat-fil-fim')||{}).value||'';
  return fin_faturamentos.filter(function(f){
    if(typeof finEhRetencaoAvulsa==='function'&&finEhRetencaoAvulsa(f)) return false;
    if(status && f.status!==status) return false;
    if(tipo && f.tipo!==tipo) return false;
    if(cont && f.contrato_id!==cont && f.contratante_id!==cont) return false;
    if(nfe && String(f.nfe||'').toLowerCase().indexOf(nfe)<0) return false;
    if(ini && (f.data_emissao||'')<ini) return false;
    if(fim && (f.data_emissao||'')>fim) return false;
    return true;
  });
}

function finRenderFaturados(){
  finAtualizarStatusVencidos();
  var lista = finFiltrarFaturamentos();
  var tb = document.getElementById('fat-tbody'); if(!tb) return;

  // Resumo cards
  var totBruto  = lista.reduce(function(s,f){return s+(f.valor_bruto||0);},0);
  var totRet    = lista.reduce(function(s,f){return s+(f.valor_retencao||0);},0);
  var totJuros  = lista.reduce(function(s,f){return s+(f.juros_antecipacao||0);},0);
  var totLiq    = lista.reduce(function(s,f){return s+(f.valor_liquido||0);},0);
  var totRec    = lista.filter(function(f){return f.status==='Recebido';}).reduce(function(s,f){return s+finCalcTotalRecebido(f);},0);
  var totAR     = lista.filter(function(f){return f.status==='A Receber';}).reduce(function(s,f){return s+(f.valor_liquido||0);},0);
  var totVenc   = lista.filter(function(f){return f.status==='Vencido';}).reduce(function(s,f){return s+(f.valor_liquido||0);},0);
  var resumo = document.getElementById('fat-resumo');
  if(resumo) resumo.innerHTML = [
    {l:'Total Faturado',   v:finFmt(totBruto), c:'#555'},
    {l:'Total Retenção',   v:finFmt(totRet),   c:'#854F0B'},
    {l:'Receita Líquida',  v:finFmt(totLiq),   c:'#185FA5'},
    {l:'Juros antecipação',v:finFmt(totJuros), c:'#A32D2D'},
    {l:'Total Recebido',   v:finFmt(totRec),    c:'#3B6D11'},
    {l:'A Receber',        v:finFmt(totAR),     c:'#185FA5'},
    {l:'Vencido',          v:finFmt(totVenc),   c:'#A32D2D'},
  ].map(function(x){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:8px 12px;text-align:center">'
      +'<div style="font-size:10px;color:#888;margin-bottom:3px">'+x.l+'</div>'
      +'<div style="font-size:15px;font-weight:700;color:'+x.c+'">'+x.v+'</div></div>';
  }).join('');

  // Alertas
  var alertasEl = document.getElementById('fat-alertas');
  if(alertasEl){
    var vencidos = fin_faturamentos.filter(function(f){return f.status==='Vencido';});
    alertasEl.innerHTML = vencidos.length
      ? '<div style="background:#FCEBEB;border:.5px solid #F5AEAE;border-radius:8px;padding:10px 14px;font-size:12px;color:#A32D2D;display:flex;align-items:center;gap:8px">'
        +'<span style="font-size:18px">⚠</span>'
        +'<span><b>'+vencidos.length+' faturamento'+( vencidos.length>1?'s':'')+' vencido'+( vencidos.length>1?'s':'')+'</b> — total de '+finFmt(totVenc)+' em atraso.</span></div>'
      : '';
  }

  if(!lista.length){
    tb.innerHTML='<tr><td colspan="14" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum faturamento encontrado.</td></tr>';
    return;
  }

  tb.innerHTML = lista.map(function(f){
    var sc = FIN_STATUS_COR[f.status]||{bg:'#f5f5f3',cor:'#555'};
    var cont = contratos.find(function(c){return c.id===f.contrato_id||c.id===f.contratante_id;})||{};
    if(!f.valor_retencao&&!f.valor_retencao_manual) f.valor_retencao=finCalcValorRetencao(f.valor_bruto,f.contrato_id);
    var totRec=finCalcTotalRecebido(f);
    var vencRow = f.status==='Vencido'?'background:#FFF9F9;':'';
    return '<tr style="'+vencRow+'">'
      +'<td data-label="NFE" style="font-family:monospace;font-size:12px">'+(f.nfe||'—')+'</td>'
      +'<td data-label="Contratante" style="font-size:12px">'+(cont.codigo||f.contratante_nome||'—')+'</td>'
      +'<td data-label="Tipo"><span class="bdg gray" style="font-size:10px">'+(f.tipo||'—')+'</span></td>'
      +'<td data-label="Emissão" style="font-size:12px">'+(f.data_emissao||'—').split('-').reverse().join('/')+'</td>'
      +'<td data-label="Vencimento" style="font-size:12px;color:'+(f.status==='Vencido'?'#A32D2D':'inherit')+'"><b>'+(f.data_vencimento||'—').split('-').reverse().join('/')+'</b></td>'
      +'<td data-label="Valor Bruto" style="font-size:12px">'+finFmt(f.valor_bruto)+'</td>'
      +'<td data-label="Retenção" style="font-size:12px;color:#854F0B">'+(Number(f.valor_retencao||0)?finFmt(f.valor_retencao):'—')+'</td>'
      +'<td data-label="Valor Líquido" style="font-size:12px;font-weight:600">'+finFmt(f.valor_liquido)+'</td>'
      +'<td data-label="Juros antec." style="font-size:12px;color:#A32D2D">'+(Number(f.juros_antecipacao||0)?finFmt(f.juros_antecipacao):'—')+'</td>'
      +'<td data-label="Total recebido" style="font-size:12px;font-weight:600;color:'+(f.status==='Recebido'?'#3B6D11':'#888')+'">'+(f.status==='Recebido'?finFmt(totRec):'—')+'</td>'
      +'<td data-label="Recebido em" style="font-size:12px">'+(f.data_recebimento?fmtD(f.data_recebimento):'—')+'</td>'
      +'<td data-label="Status"><span class="bdg" style="background:'+sc.bg+';color:'+sc.cor+';font-size:11px">'+f.status+'</span></td>'
      +'<td data-label="Origem"><span style="font-size:10px;color:#aaa">'+(f.origem_api?'🔗 API':'Manual')+'</span></td>'
      +'<td style="white-space:nowrap;display:flex;gap:3px">'
      +'<button class="btn btn-sm" onclick="finEditarFaturamento(\''+f.id+'\')" title="Editar">✎</button>'
      +'<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" onclick="finExcluirFaturamento(\''+f.id+'\')" title="Excluir faturamento">Excluir</button>'
      +'</td>'
      +'</tr>';
  }).join('');
}

function finRenderDRE(){
  var cont   = (document.getElementById('dre-fil-cont')||{}).value||'';
  var period = (document.getElementById('dre-fil-periodo')||{}).value||'90';
  var hoje   = dataHojeLocal();
  var ini;
  if(period==='30')  ini=_diasAtras(30);
  else if(period==='mes') ini=hoje.slice(0,7)+'-01';
  else if(period==='ano') ini=hoje.slice(0,4)+'-01-01';
  else ini=_diasAtras(90);

  var fats = fin_faturamentos.filter(function(f){
    if(typeof finEhRetencaoAvulsa==='function'&&finEhRetencaoAvulsa(f)) return false;
    if(cont && f.contrato_id!==cont && f.contratante_id!==cont) return false;
    return (f.data_emissao||'')>=ini;
  });
  var lancs = lancamentos.filter(function(l){
    if(cont && l.contrato_id!==cont) return false;
    return (l.data_emissao||l.data||'')>=ini;
  });

  var recBruta  = fats.reduce(function(s,f){return s+(f.valor_bruto||0);},0);
  var recLiq    = fats.reduce(function(s,f){return s+(f.valor_liquido||0);},0);
  var totPago   = lancs.filter(function(l){return l.status==='Pago'||l.status==='Aprovado';}).reduce(function(s,l){return s+(l.valor||0);},0);
  var resultado = recLiq - totPago;

  var wrap = document.getElementById('dre-content'); if(!wrap) return;
  wrap.innerHTML = '<div class="card" style="max-width:560px;margin:0 auto">'
    +'<div class="ch"><span class="ct" style="font-size:15px">DRE Simplificado</span><span style="font-size:11px;color:#aaa">'+ini.split('-').reverse().join('/')+' a '+hoje.split('-').reverse().join('/')+'</span></div>'
    +'<div style="padding:.75rem 1rem">'
    + function(){
        var rows=[
          {desc:'(+) Receita Bruta',         v:recBruta,  bold:false, color:'#185FA5'},
          {desc:'(-) Deduções',               v:recBruta-recLiq, bold:false, color:'#A32D2D'},
          {desc:'(=) Receita Líquida',        v:recLiq,    bold:true,  color:'#185FA5'},
          {desc:'(-) Despesas / Custos',      v:totPago,   bold:false, color:'#A32D2D'},
          {desc:'(=) Resultado Operacional',  v:resultado, bold:true,  color:resultado>=0?'#3B6D11':'#A32D2D'},
        ];
        return rows.map(function(r,i){
          var sep = i===2||i===4 ? 'border-top:1px solid #e0dfd8;margin-top:4px;padding-top:8px;' : '';
          return '<div style="display:flex;justify-content:space-between;padding:6px 0;'+sep+'">'
            +'<span style="font-size:13px;font-weight:'+(r.bold?700:400)+';color:#444">'+r.desc+'</span>'
            +'<span style="font-size:13px;font-weight:'+(r.bold?700:600)+';color:'+r.color+'">'+finFmt(r.v)+'</span>'
            +'</div>';
        }).join('');
      }()
    +'</div></div>'
    + '<div class="card" style="margin-top:1rem"><div class="ch"><span class="ct">Detalhamento por Mês</span></div>'
    + finRenderDREmeses(fats, lancs) + '</div>';
}

function finRenderDREmeses(fats, lancs){
  var meses={};
  fats.forEach(function(f){
    var m=(f.data_emissao||'').slice(0,7); if(!m)return;
    if(!meses[m])meses[m]={rec:0,desp:0};
    meses[m].rec+=(f.valor_liquido||0);
  });
  lancs.filter(function(l){return l.status==='Pago'||l.status==='Aprovado';}).forEach(function(l){
    var m=(l.data_emissao||l.data||'').slice(0,7); if(!m)return;
    if(!meses[m])meses[m]={rec:0,desp:0};
    meses[m].desp+=(l.valor||0);
  });
  var sorted=Object.keys(meses).sort().reverse();
  if(!sorted.length) return '<div style="padding:1rem;color:#aaa;font-size:12px;text-align:center">Nenhum dado no período.</div>';
  return '<div style="overflow-x:auto"><table class="tbl"><thead><tr>'
    +'<th>Mês</th><th>Receita Líquida</th><th>Despesas</th><th>Resultado</th></tr></thead><tbody>'
    +sorted.map(function(m){
      var r=meses[m]; var res=r.rec-r.desp;
      var mc=m.split('-'); var label=mc[1]+'/'+mc[0];
      return '<tr>'
        +'<td><b>'+label+'</b></td>'
        +'<td style="color:#185FA5">'+finFmt(r.rec)+'</td>'
        +'<td style="color:#A32D2D">'+finFmt(r.desp)+'</td>'
        +'<td style="font-weight:700;color:'+(res>=0?'#3B6D11':'#A32D2D')+'">'+finFmt(res)+'</td>'
        +'</tr>';
    }).join('')+'</tbody></table></div>';
}

function finRenderDashboard(){
  finAtualizarStatusVencidos();
  var hoje=dataHojeLocal();
  var totFat   = fin_faturamentos.reduce(function(s,f){return s+(f.valor_bruto||0);},0);
  var totRec   = fin_faturamentos.filter(function(f){return f.status==='Recebido';}).reduce(function(s,f){return s+finCalcTotalRecebido(f);},0);
  var totAR    = fin_faturamentos.filter(function(f){return f.status==='A Receber';}).reduce(function(s,f){return s+(f.valor_liquido||0);},0);
  var totVenc  = fin_faturamentos.filter(function(f){return f.status==='Vencido';}).reduce(function(s,f){return s+(f.valor_liquido||0);},0);
  var totPago  = lancamentos.filter(function(l){return l.status==='Pago'||l.status==='Aprovado';}).reduce(function(s,l){return s+(l.valor||0);},0);
  var recLiq   = fin_faturamentos.reduce(function(s,f){return s+(f.valor_liquido||0);},0);
  var result   = recLiq - totPago;
  var fluxo    = totRec - totPago;

  var cards=[
    {l:'Total Faturado',        v:finFmt(totFat),   c:'#555',    icon:'🧾'},
    {l:'Total Recebido',        v:finFmt(totRec),   c:'#3B6D11', icon:'✅'},
    {l:'A Receber',             v:finFmt(totAR),    c:'#185FA5', icon:'⏳'},
    {l:'Vencido',               v:finFmt(totVenc),  c:'#A32D2D', icon:'🚨'},
    {l:'Total Pago (despesas)', v:finFmt(totPago),  c:'#888',    icon:'💸'},
    {l:'Resultado Operacional', v:finFmt(result),   c:result>=0?'#3B6D11':'#A32D2D', icon:'📊'},
    {l:'Fluxo de Caixa',       v:finFmt(fluxo),    c:fluxo>=0?'#3B6D11':'#A32D2D', icon:'🔄'},
    {l:'Receita Líquida',       v:finFmt(recLiq),   c:'#185FA5', icon:'💹'},
  ];

  var d=document.getElementById('fin-dashboard-cards');
  if(d) d.innerHTML=cards.map(function(x){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:6px">'
      +'<div style="display:flex;align-items:center;gap:8px">'
      +'<span style="font-size:20px">'+x.icon+'</span>'
      +'<span style="font-size:11px;color:#888">'+x.l+'</span></div>'
      +'<div style="font-size:18px;font-weight:700;color:'+x.c+'">'+x.v+'</div>'
      +'</div>';
  }).join('');

  // Alertas dashboard
  var alertas=[];
  if(fin_faturamentos.filter(function(f){return f.status==='Vencido';}).length)
    alertas.push({icon:'🚨',msg:'Existem faturamentos vencidos sem recebimento.',cor:'#A32D2D',bg:'#FCEBEB'});
  if(totAR>totRec)
    alertas.push({icon:'⚠️',msg:'Valor a receber ('+finFmt(totAR)+') supera o já recebido.',cor:'#854F0B',bg:'#FEF3E2'});
  if(result<0)
    alertas.push({icon:'📉',msg:'Resultado operacional negativo: '+finFmt(result),cor:'#A32D2D',bg:'#FCEBEB'});

  var ad=document.getElementById('fin-alertas-dash');
  if(ad) ad.innerHTML=alertas.length
    ? alertas.map(function(a){return '<div style="background:'+a.bg+';border-radius:8px;padding:8px 12px;font-size:12px;color:'+a.cor+';margin-bottom:6px;display:flex;gap:8px"><span>'+a.icon+'</span><span>'+a.msg+'</span></div>';}).join('')
    : '<div style="color:#aaa;font-size:12px;padding:.5rem">✅ Nenhum alerta financeiro.</div>';

  // Mini gráfico de receitas por mês (texto)
  var chartEl=document.getElementById('fin-chart-receitas');
  if(chartEl){
    var meses={}; fin_faturamentos.forEach(function(f){ var m=(f.data_emissao||'').slice(0,7);if(!m)return;if(!meses[m])meses[m]=0;meses[m]+=(f.valor_liquido||0);});
    var sorted=Object.keys(meses).sort().slice(-6);
    var max=Math.max.apply(null,sorted.map(function(m){return meses[m];})||[1]);
    chartEl.innerHTML=sorted.length?'<div style="display:flex;align-items:flex-end;gap:6px;height:80px;padding-top:.5rem">'
      +sorted.map(function(m){
        var v=meses[m]; var h=Math.round((v/max)*70);
        return '<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px">'
          +'<div style="background:#185FA5;width:100%;height:'+h+'px;border-radius:3px 3px 0 0" title="'+finFmt(v)+'"></div>'
          +'<div style="font-size:9px;color:#888">'+m.slice(5)+'</div></div>';
      }).join('')+'</div>'
      :'<div style="color:#aaa;font-size:12px">Sem dados.</div>';
  }
}

function finNovoFaturamento(){
  finAbrirModalFaturamento(null);
}

function finEditarFaturamento(id){
  var f=fin_faturamentos.find(function(x){return x.id===id;});
  if(f) finAbrirModalFaturamento(f);
}

async function finExcluirFaturamento(id){
  if(!_podeExcluirCritico()){
    if(typeof progShowToast==='function') progShowToast('Somente admin/gestor pode excluir faturamentos.','erro');
    else alert('Somente admin/gestor pode excluir faturamentos.');
    return;
  }
  var f=(fin_faturamentos||[]).find(function(x){return String(x.id)===String(id);});
  if(!f){
    if(typeof progShowToast==='function') progShowToast('Faturamento não encontrado.','erro');
    return;
  }
  var nfe=f.nfe||'(sem NFE)';
  var brutoTxt=typeof finFmt==='function'?finFmt(f.valor_bruto):('R$ '+Number(f.valor_bruto||0).toLocaleString('pt-BR'));
  var msg='Excluir este faturamento?\n\n'
    +'NF-e '+nfe+'\n'
    +brutoTxt+' · '+(f.status||'—')
    +'\n\nO registro será desativado (soft-delete), não apagado do banco'
    +(Number(f.valor_retencao||0)>0?' (inclui a retenção vinculada)':'')+'.';
  if(f.status==='Recebido'){
    msg+='\n\nAtenção: o faturamento já está marcado como Recebido.';
  }
  if(!confirm(msg)) return;
  if(f.status==='Recebido' && !confirm('Confirma exclusão de faturamento JÁ RECEBIDO?\nNF-e '+nfe)) return;
  try{
    if(!DEMO){
      if(typeof isUUID==='function'&&!isUUID(String(id))){
        console.warn('[Fat] exclusão local — id não é UUID:', id);
      } else {
        await sbDelete('financeiro_faturamentos','id=eq.'+id);
      }
    }
    fin_faturamentos=(fin_faturamentos||[]).filter(function(x){return String(x.id)!==String(id);});
    if(typeof auditLog==='function'){
      auditLog('excluir','financeiro','Excluiu faturamento NF-e '+nfe+(f.valor_bruto!=null?' — '+brutoTxt:''),{id:id,status:f.status,nfe:f.nfe,contrato:f.contrato_id,valor_bruto:f.valor_bruto});
    }
    closeModal();
    finRenderFaturados();
    if(typeof finRenderRetencoes==='function') finRenderRetencoes();
    if(typeof finRenderDashboard==='function'){
      var abaDash=document.getElementById('fin-aba-dashboard');
      if(abaDash&&abaDash.style.display!=='none') finRenderDashboard();
    }
    if(typeof progShowToast==='function') progShowToast('Faturamento excluído.');
  }catch(e){
    console.error('[Fat] excluir',e);
    if(typeof progShowToast==='function') progShowToast('Erro ao excluir faturamento.','erro');
    else alert('Erro ao excluir faturamento.');
  }
}

function finAbrirModalFaturamento(f){
  var isNew=!f; f=f||{};
  var _fatRetManual=!!f.valor_retencao_manual;
  var optsContr=contratos.map(function(c){return '<option value="'+c.id+'"'+(f.contrato_id===c.id?' selected':'')+'>'+escHtml(c.nome)+'</option>';}).join('');
  var optsStatus=['A Receber','Vencido','Recebido'].map(function(s){return '<option'+(f.status===s?' selected':'')+'>'+s+'</option>';}).join('');
  var optsTipo=FIN_TIPOS_RECEITA.map(function(t){return '<option'+(f.tipo===t?' selected':'')+'>'+t+'</option>';}).join('');
  var retIni=f.valor_retencao!=null?f.valor_retencao:finCalcValorRetencao(f.valor_bruto,f.contrato_id);
  setModal('<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3 style="margin-bottom:1rem">'+(isNew?'Novo Faturamento':'Editar Faturamento')+'</h3>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1rem">'
    +'<div class="fg"><label>NFE</label><input class="inp" id="fat-nfe" value="'+escHtml(f.nfe||'')+'" placeholder="Número da NF"></div>'
    +'<div class="fg"><label>Tipo</label><select class="inp" id="fat-tipo"><option value="">Selecione</option>'+optsTipo+'</select></div>'
    +'<div class="fg" style="grid-column:span 2"><label>Contratante / Contrato</label><select class="inp" id="fat-cont"><option value="">Selecione</option>'+optsContr+'</select></div>'
    +'<div class="fg"><label>Data Emissão</label><input class="inp" type="date" id="fat-emissao" value="'+(f.data_emissao||'')+'"></div>'
    +'<div class="fg"><label>Data Vencimento</label><input class="inp" type="date" id="fat-venc" value="'+(f.data_vencimento||'')+'"></div>'
    +'<div class="fg"><label>Valor Bruto (R$)</label><input class="inp" type="number" step="0.01" id="fat-bruto" value="'+(f.valor_bruto||'')+'"></div>'
    +'<div class="fg"><label>Retenção (R$)</label><input class="inp" type="number" step="0.01" id="fat-retencao" value="'+(retIni||'')+'"><div style="font-size:10px;color:#888;margin-top:2px">Auto pelo % do contrato; editável.</div></div>'
    +'<div class="fg"><label>Valor Líquido NF (R$)</label><input class="inp" type="number" step="0.01" id="fat-liquido" value="'+(f.valor_liquido||'')+'"></div>'
    +'<div class="fg"><label>Juros antecipação (R$)</label><input class="inp" type="number" step="0.01" id="fat-juros" value="'+(f.juros_antecipacao||'')+'" placeholder="0,00"><div style="font-size:10px;color:#888;margin-top:2px">Deságio por antecipação de pagamento.</div></div>'
    +'<div class="fg"><label>Data recebimento</label><input class="inp" type="date" id="fat-data-rec" value="'+(f.data_recebimento||'')+'"></div>'
    +'<div class="fg"><label>Total recebido (R$)</label><input class="inp" id="fat-total-rec" readonly style="background:#EAF3DE;font-weight:600;color:#3B6D11" value=""></div>'
    +'<div class="fg"><label>Bruto − Retenção</label><input class="inp" id="fat-pos-ret" readonly style="background:#f5f5f3" value=""></div>'
    +'<div class="fg"><label>Status</label><select class="inp" id="fat-status">'+optsStatus+'</select></div>'
    +'<div class="fg" style="grid-column:span 2"><label>Observação</label><textarea class="inp" id="fat-obs" style="height:50px">'+escHtml(f.observacao||'')+'</textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;justify-content:space-between;align-items:center">'
    +(!isNew?'<button class="btn" style="color:#A32D2D;border-color:#A32D2D" onclick="finExcluirFaturamento(\''+escHtml(f.id)+'\')">Excluir</button>':'<span></span>')
    +'<div style="display:flex;gap:8px;flex:1;justify-content:flex-end">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="fat-salvar-btn">Salvar</button>'
    +'</div></div></div></div>');
  function finFatAtualizarRetencaoModal(forceAuto){
    var bruto=parseFloat((document.getElementById('fat-bruto')||{}).value)||0;
    var liq=parseFloat((document.getElementById('fat-liquido')||{}).value)||0;
    var juros=parseFloat((document.getElementById('fat-juros')||{}).value)||0;
    var cid=(document.getElementById('fat-cont')||{}).value;
    var elRet=document.getElementById('fat-retencao');
    var elPos=document.getElementById('fat-pos-ret');
    var elTot=document.getElementById('fat-total-rec');
    if(elRet&&(forceAuto||!_fatRetManual)) elRet.value=finCalcValorRetencao(bruto,cid);
    var ret=parseFloat((elRet||{}).value)||0;
    if(elPos) elPos.value=finFmt(Math.max(0,bruto-ret));
    if(elTot) elTot.value=finFmt(finCalcTotalRecebido({valor_liquido:liq,valor_retencao:ret,juros_antecipacao:juros}));
  }
  setTimeout(function(){
    var elBruto=document.getElementById('fat-bruto');
    var elCont=document.getElementById('fat-cont');
    var elRet=document.getElementById('fat-retencao');
    var elLiq=document.getElementById('fat-liquido');
    var elJuros=document.getElementById('fat-juros');
    var elStatus=document.getElementById('fat-status');
    var elDataRec=document.getElementById('fat-data-rec');
    if(elBruto) elBruto.oninput=function(){ finFatAtualizarRetencaoModal(true); };
    if(elCont) elCont.onchange=function(){ finFatAtualizarRetencaoModal(true); };
    if(elRet) elRet.oninput=function(){ _fatRetManual=true; finFatAtualizarRetencaoModal(false); };
    if(elLiq) elLiq.oninput=function(){ finFatAtualizarRetencaoModal(false); };
    if(elJuros) elJuros.oninput=function(){ finFatAtualizarRetencaoModal(false); };
    if(elStatus) elStatus.onchange=function(){
      if(elStatus.value==='Recebido'&&elDataRec&&!elDataRec.value) elDataRec.value=dataHojeLocal();
      finFatAtualizarRetencaoModal(false);
    };
    finFatAtualizarRetencaoModal(false);
    var btn=document.getElementById('fat-salvar-btn');
    if(btn)btn.onclick=function(){
      var bruto=parseFloat((document.getElementById('fat-bruto')||{}).value)||0;
      var retencao=parseFloat((document.getElementById('fat-retencao')||{}).value)||0;
      var juros=parseFloat((document.getElementById('fat-juros')||{}).value)||0;
      var status=(document.getElementById('fat-status')||{}).value||'A Receber';
      var dataRec=(document.getElementById('fat-data-rec')||{}).value||null;
      if(status==='Recebido'&&!dataRec) dataRec=dataHojeLocal();
      var dados={
        nfe:(document.getElementById('fat-nfe')||{}).value||'',
        contrato_id:(document.getElementById('fat-cont')||{}).value||null,
        tipo:(document.getElementById('fat-tipo')||{}).value||'',
        data_emissao:(document.getElementById('fat-emissao')||{}).value||null,
        data_vencimento:(document.getElementById('fat-venc')||{}).value||null,
        valor_bruto:bruto,
        valor_retencao:retencao,
        valor_retencao_manual:_fatRetManual||retencao!==finCalcValorRetencao(bruto,(document.getElementById('fat-cont')||{}).value),
        valor_liquido:parseFloat((document.getElementById('fat-liquido')||{}).value)||0,
        juros_antecipacao:juros,
        data_recebimento:status==='Recebido'?dataRec:null,
        status:status,
        observacao:(document.getElementById('fat-obs')||{}).value||'',
        origem_api:false,
        updated_at:new Date().toISOString()
      };
      if(!dados.valor_retencao_recebido&&f.valor_retencao_recebido!=null) dados.valor_retencao_recebido=f.valor_retencao_recebido;
      if(!dados.data_retencao_recebimento&&f.data_retencao_recebimento) dados.data_retencao_recebimento=f.data_retencao_recebimento;
      if(!DEMO){
        if(isNew){
          dados.created_at=dados.updated_at;
          dados.valor_retencao_recebido=0;
          sbInsert('financeiro_faturamentos',dados).then(function(r){
            if(r&&r.length){fin_faturamentos.unshift(r[0]);finRenderFaturados();finRenderRetencoes();}
          });
        } else {
          sbUpdate('financeiro_faturamentos',dados,'id=eq.'+f.id);
          var idx=fin_faturamentos.findIndex(function(x){return x.id===f.id;});
          if(idx>=0) fin_faturamentos[idx]=Object.assign({},f,dados);
          finRenderFaturados();
          finRenderRetencoes();
        }
      } else {
        dados.id=Date.now().toString();
        dados.valor_retencao_recebido=f.valor_retencao_recebido||0;
        fin_faturamentos.unshift(dados);
        finRenderFaturados();
        finRenderRetencoes();
      }
      closeModal();
      progShowToast('✅ Faturamento salvo.');
    };
  },50);
}

function finSincronizar(){
  progShowToast('🔄 Iniciando sincronização com API financeiro CENA...');
  setTimeout(function(){
    sbFetch('financeiro_faturamentos',{order:'data_emissao.desc'}).then(function(rows){
      rows=(rows||[]).filter(function(r){return !r.deleted_at;});
      if(rows.length){ fin_faturamentos=rows; finAtualizarStatusVencidos(); finRenderFaturados(); progShowToast('✅ Sincronização concluída — '+rows.length+' faturamentos.'); }
      else progShowToast('⚠ Nenhum dado retornado da API.');
    }).catch(function(){ progShowToast('⚠ Erro na sincronização.'); });
  },500);
}

var _finLogs = [];

function finAddLog(tipo, endpoint, status, registros, detalhe){
  var agora = new Date();
  var log = {
    dt: agora.toLocaleDateString('pt-BR')+' '+agora.toLocaleTimeString('pt-BR'),
    tipo: tipo, endpoint: endpoint, status: status,
    registros: registros||0, detalhe: detalhe||''
  };
  _finLogs.unshift(log);
  if(_finLogs.length>100) _finLogs.pop();
  try{ localStorage.setItem('fin_sinc_logs', JSON.stringify(_finLogs.slice(0,50))); }catch(e){}
  finRenderLogs();
}

function finRenderLogs(){
  var tb = document.getElementById('fin-logs-tbody'); if(!tb) return;
  if(!_finLogs.length){
    tb.innerHTML='<tr><td colspan="6" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum log de sincronização ainda.</td></tr>';
    return;
  }
  tb.innerHTML = _finLogs.map(function(l){
    var cor = l.status==='OK'?'#3B6D11':l.status==='ERRO'?'#A32D2D':'#854F0B';
    var bg  = l.status==='OK'?'#EAF3DE':l.status==='ERRO'?'#FCEBEB':'#FEF3E2';
    return '<tr>'
      +'<td style="font-size:11px;white-space:nowrap">'+l.dt+'</td>'
      +'<td><span class="bdg" style="background:'+bg+';color:'+cor+';font-size:10px">'+l.tipo+'</span></td>'
      +'<td style="font-size:11px;color:#888">'+escHtml(l.endpoint)+'</td>'
      +'<td><span style="font-size:11px;font-weight:600;color:'+cor+'">'+l.status+'</span></td>'
      +'<td style="font-size:12px;text-align:center">'+l.registros+'</td>'
      +'<td style="font-size:11px;color:#888">'+escHtml(l.detalhe)+'</td>'
      +'</tr>';
  }).join('');
}

function finRenderSincCards(){
  var el = document.getElementById('fin-sinc-cards'); if(!el) return;
  var ultima = _finLogs[0];
  el.innerHTML = [
    {l:'Total faturamentos', v:fin_faturamentos.length, c:'#185FA5', icon:'🧾'},
    {l:'Total lançamentos',  v:lancamentos.length,       c:'#555',    icon:'💸'},
    {l:'Última sincronização',v:ultima?ultima.dt:'Nunca', c:'#3B6D11', icon:'🕐'},
    {l:'Logs registrados',   v:_finLogs.length,           c:'#854F0B', icon:'📋'},
  ].map(function(x){
    return '<div style="background:#f9f9f7;border-radius:8px;padding:10px 12px">'
      +'<div style="font-size:10px;color:#888;margin-bottom:3px">'+x.icon+' '+x.l+'</div>'
      +'<div style="font-size:14px;font-weight:700;color:'+x.c+'">'+x.v+'</div>'
      +'</div>';
  }).join('');
}

function finSetProgresso(pct, msg){
  var bar=document.getElementById('fin-sinc-bar');
  var msgEl=document.getElementById('fin-sinc-msg');
  var wrap=document.getElementById('fin-sinc-progresso');
  if(wrap) wrap.style.display = pct<100 ? '' : 'none';
  if(bar) bar.style.width = pct+'%';
  if(msgEl) msgEl.textContent = msg||'';
}

function finSincronizarLancamentos(){
  var url   = (document.getElementById('fin-api-url')||{}).value||'';
  var token = (document.getElementById('fin-api-token')||{}).value||'';
  var dias  = (document.getElementById('fin-api-periodo')||{}).value||'90';
  finSetProgresso(20,'Buscando lançamentos...');
  progShowToast('🔄 Sincronizando lançamentos...');

  // Buscar do banco (aguarda integração real com API CENA)
  var d = _diasAtras(parseInt(dias)||90);
  sbFetch('lancamentos',{order:'data_emissao.desc',filters:['data_emissao=gte.'+d]}).then(function(rows){
    rows=(rows||[]).filter(function(r){return !r.deleted_at;});
    if(rows.length){ lancamentos=rows; renderLancamentos(); }
    var n = rows.length;
    finAddLog('Lançamentos', url||'supabase/lancamentos', 'OK', n, 'Últimos '+dias+' dias');
    finSetProgresso(100,'');
    finRenderSincCards();
    progShowToast('✅ Lançamentos sincronizados — '+n+' registros.');
  }).catch(function(e){
    finAddLog('Lançamentos', url||'supabase/lancamentos', 'ERRO', 0, String(e));
    finSetProgresso(100,'');
    progShowToast('⚠ Erro ao sincronizar lançamentos.');
  });
}

function finSincronizarFaturamentos(){
  var url   = (document.getElementById('fin-api-url')||{}).value||'';
  var token = (document.getElementById('fin-api-token')||{}).value||'';
  finSetProgresso(20,'Buscando faturamentos...');
  progShowToast('🔄 Sincronizando faturamentos...');

  sbFetch('financeiro_faturamentos',{order:'data_emissao.desc'}).then(function(rows){
    rows=(rows||[]).filter(function(r){return !r.deleted_at;});
    if(rows.length){ fin_faturamentos=rows; finAtualizarStatusVencidos(); finRenderFaturados(); }
    var n = rows.length;
    finAddLog('Faturamentos', url||'supabase/financeiro_faturamentos', 'OK', n, 'Todos os registros');
    finSetProgresso(100,'');
    finRenderSincCards();
    progShowToast('✅ Faturamentos sincronizados — '+n+' registros.');
  }).catch(function(e){
    finAddLog('Faturamentos', url||'supabase/financeiro_faturamentos', 'ERRO', 0, String(e));
    finSetProgresso(100,'');
    progShowToast('⚠ Erro ao sincronizar faturamentos.');
  });
}

function finSincronizarTudo(){
  var btn=document.getElementById('fin-btn-sinc');
  if(btn){btn.disabled=true;btn.textContent='⏳ Sincronizando...';}
  finSetProgresso(10,'Iniciando sincronização completa...');
  progShowToast('🔄 Sincronização completa iniciada...');

  var url   = (document.getElementById('fin-api-url')||{}).value||'';
  var dias  = (document.getElementById('fin-api-periodo')||{}).value||'90';
  var d     = _diasAtras(parseInt(dias)||90);

  Promise.all([
    sbFetch('lancamentos',{order:'data_emissao.desc',filters:['data_emissao=gte.'+d]}),
    sbFetch('financeiro_faturamentos',{order:'data_emissao.desc'}),
  ]).then(function(res){
    var nLanc=0, nFat=0;
    if(res[0]&&res[0].length){ lancamentos=res[0].filter(function(r){return !r.deleted_at;}); nLanc=lancamentos.length; renderLancamentos(); }
    if(res[1]&&res[1].length){ fin_faturamentos=res[1].filter(function(r){return !r.deleted_at;}); nFat=fin_faturamentos.length; finAtualizarStatusVencidos(); finRenderFaturados(); }
    finAddLog('Completa', url||'supabase', 'OK', nLanc+nFat, 'Lanç:'+nLanc+' | Fat:'+nFat);
    finSetProgresso(100,'');
    finRenderSincCards();
    if(btn){btn.disabled=false;btn.textContent='🔄 Sincronizar agora';}
    progShowToast('✅ Sincronização concluída — '+nLanc+' lançamentos e '+nFat+' faturamentos.');
  }).catch(function(e){
    finAddLog('Completa', url||'supabase', 'ERRO', 0, String(e));
    finSetProgresso(100,'');
    if(btn){btn.disabled=false;btn.textContent='🔄 Sincronizar agora';}
    progShowToast('⚠ Erro durante sincronização.');
  });
}

function finVerLogs(){
  finMostrarAba('sincronizar');
  setTimeout(function(){
    var el=document.getElementById('fin-logs-wrap');
    if(el)el.scrollIntoView({behavior:'smooth'});
  },200);
}

function finLimparLogs(){
  if(!confirm('Limpar todos os logs de sincronização?'))return;
  _finLogs=[];
  try{localStorage.removeItem('fin_sinc_logs');}catch(e){}
  finRenderLogs();
  finRenderSincCards();
}

function renderLancamentos(){
  var cid=(document.getElementById('fil-lanc-cont')||{}).value||'';
  if(!cid){
    var tb_g=document.getElementById('tbody-lanc');
    if(tb_g)tb_g.innerHTML='<tr><td colspan="12" style="padding:1.5rem;text-align:center;color:#aaa">Selecione um contrato para visualizar os dados.</td></tr>';
    return;
  }
  var st=(document.getElementById('fil-lanc-status')||{}).value||'';
  var ini=(document.getElementById('fil-lanc-ini')||{}).value||'';
  var fim=(document.getElementById('fil-lanc-fim')||{}).value||'';
  var rows=lancamentos.filter(function(l){
    if(cid&&l.contrato_id!==cid)return false;
    if(st&&l.status!==st)return false;
    if(ini&&l.data_emissao&&l.data_emissao<ini)return false;
    if(fim&&l.data_emissao&&l.data_emissao>fim)return false;
    return true;
  });
  var stCls={Lançado:'gray','Em análise':'warn',Aprovado:'ok',Reprovado:'danger',Pago:'teal','Pago parcial':'warn',Cancelado:'gray'};
  var total=rows.reduce(function(s,l){return s+Number(l.valor||0);},0);
  document.getElementById('tbody-lanc').innerHTML=rows.map(function(l){
    var anexos='';
    if(l.anexo_xml)anexos+='<a href="'+l.anexo_xml+'" target="_blank" style="font-size:10px;color:#185FA5;text-decoration:none" title="NF XML">📄 XML</a> ';
    if(l.anexo_pdf)anexos+='<a href="'+l.anexo_pdf+'" target="_blank" style="font-size:10px;color:#185FA5;text-decoration:none" title="Documento">📎 PDF</a>';
    if(!anexos)anexos='<span style="color:#ccc;font-size:11px">—</span>';
    return '<tr>'
      +'<td style="font-size:11px">'+fmtD(l.data_emissao)+'</td>'
      +'<td style="font-size:11px">'+fNomeCont(l.contrato_id)+'</td>'
      +'<td style="font-size:11px">'+fNomeCat(l.categoria_id)+'</td>'
      +'<td style="font-size:11px;color:#555">'+fNomeSub(l.subcategoria_id)+'</td>'
      +'<td>'+(l.descricao||'—')+'</td>'
      +'<td style="font-size:11px;color:#888">'+fNomeForn(l.fornecedor_id)+'</td>'
      +'<td style="font-size:11px;color:#888">'+(l.competencia||'—')+'</td>'
      +'<td style="font-size:11px;color:#888">'+(l.documento_fiscal||'—')+'</td>'
      +'<td style="font-weight:500;white-space:nowrap">'+fmtR(l.valor)+'</td>'
      +'<td><span class="bdg '+(stCls[l.status]||'gray')+'">'+(l.status||'—')+'</span></td>'
      +'<td>'+anexos+'</td>'
      +'<td style="display:flex;gap:3px;white-space:nowrap">'
      +'<button class="btn btn-sm" onclick="openEditarLancamento(\''+l.id+'\')">Editar</button>'
      +(l.status==='Lançado'?'<button class="btn btn-sm" onclick="enviarAprovacao(\''+l.id+'\')">Enviar</button>':'')
      +'<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" onclick="excluirLancamento(\''+l.id+'\')" title="Excluir lançamento">Excluir</button>'
      +'</td></tr>';
  }).join('')||'<tr><td colspan="12" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum lançamento</td></tr>';
  var lt=document.getElementById('lanc-totais');
  if(lt)lt.innerHTML='<span><b>'+rows.length+'</b> lançamentos</span><span style="margin-left:1.5rem"><b>Total: '+fmtR(total)+'</b></span><span style="margin-left:1.5rem;color:#3B6D11">Pagos: '+fmtR(rows.filter(function(l){return l.status==='Pago';}).reduce(function(s,l){return s+Number(l.valor);},0))+'</span><span style="margin-left:1.5rem;color:#854F0B">Pendentes: '+fmtR(rows.filter(function(l){return ['Lançado','Em análise','Aprovado'].indexOf(l.status)>=0;}).reduce(function(s,l){return s+Number(l.valor);},0))+'</span>';
}
function vbeSelectNaturezaDespesaHtml(selId, selected){
  var labels=(typeof VBE_LABEL_CAT_DESPESA!=='undefined'&&VBE_LABEL_CAT_DESPESA)?VBE_LABEL_CAT_DESPESA:{
    salarios:'Salários',encargos:'Encargos',horas_extras_adicionais:'Horas extras / adicionais',
    beneficios:'Benefícios',vale_refeicao:'Vale refeição',vale_alimentacao:'Vale alimentação',
    vale_transporte:'Vale transporte',plano_saude:'Plano de saúde',plano_odontologico:'Plano odontológico',
    seguro_vida:'Seguro de vida',cesta_basica:'Cesta básica',diarias_hospedagens:'Diárias / hospedagens',
    treinamentos:'Treinamentos',uniformes:'Uniformes',epi:'EPI',epc:'EPC',
    combustivel:'Combustível',pedagios:'Pedágios',locacao_frota:'Locação frota',manutencao_frota:'Manutenção frota',
    pneus:'Pneus',documentacao_frota:'Documentação frota',seguros_frota:'Seguros frota',
    materiais:'Materiais',ferramentas:'Ferramentas',administrativo:'Administrativo',
    servicos_terceiros:'Serviços de terceiros',tributos_nao_faturamento:'Tributos (não fat.)',
    multas_juros:'Multas / juros',outros:'Outros'
  };
  var opts='<option value="">Automático (classificador)</option>';
  Object.keys(labels).forEach(function(k){
    opts+='<option value="'+k+'"'+(String(selected||'')===k?' selected':'')+'>'+escHtml(labels[k])+'</option>';
  });
  return '<select id="'+selId+'">'+opts+'</select>';
}
function vbeSelectGrupoDreHtml(selId, selected){
  var grupos=[
    ['','Automático'],
    ['pessoal','Pessoal'],
    ['frota','Frota'],
    ['materiais_equipamentos','Materiais / equipamentos'],
    ['backoffice','Backoffice'],
    ['tributos_financeiro','Tributos / financeiro'],
    ['outros','Outros']
  ];
  var opts=grupos.map(function(g){
    return '<option value="'+g[0]+'"'+(String(selected||'')===g[0]?' selected':'')+'>'+g[1]+'</option>';
  }).join('');
  return '<select id="'+selId+'">'+opts+'</select>';
}
function vbeSelectAplicacaoCustoHtml(selId, selected){
  var opts=[
    ['','Não definido'],
    ['operacional','Operacional'],
    ['backoffice','Backoffice'],
    ['rateado','Rateado']
  ].map(function(g){
    return '<option value="'+g[0]+'"'+(String(selected||'')===g[0]?' selected':'')+'>'+g[1]+'</option>';
  }).join('');
  return '<select id="'+selId+'">'+opts+'</select>';
}
function vbeLerCamposClassificacaoForm(prefix){
  var nat=((document.getElementById(prefix+'-natureza')||{}).value||'').trim();
  var grp=((document.getElementById(prefix+'-grupo')||{}).value||'').trim();
  var ap=((document.getElementById(prefix+'-aplicacao')||{}).value||'').trim();
  var vpRaw=(document.getElementById(prefix+'-valor-pago')||{}).value;
  var vp=(vpRaw===''||vpRaw==null)?null:parseFloat(vpRaw);
  if(vp!=null&&isNaN(vp)) vp=null;
  var manual=!!nat;
  return {
    natureza_despesa:nat||null,
    grupo_dre:grp||null,
    aplicacao_custo:ap||null,
    valor_pago:vp,
    classificacao_manual:manual,
    classificacao_origem:manual?'manual':'',
    classificacao_confianca:manual?'Manual':null
  };
}
function vbeHtmlBlocoClassificacaoLanc(prefix, l){
  l=l||{};
  return '<div style="margin-top:.75rem;padding:.75rem;background:#fafaf8;border:.5px solid #e0dfd8;border-radius:10px">'
    +'<div style="font-size:12px;font-weight:600;margin-bottom:6px;color:#333">Classificação Viabilidade (Etapa G)</div>'
    +'<div class="g2">'
    +'<div class="fg"><label>Natureza gerencial</label>'+vbeSelectNaturezaDespesaHtml(prefix+'-natureza',l.natureza_despesa||'')+'</div>'
    +'<div class="fg"><label>Grupo DRE</label>'+vbeSelectGrupoDreHtml(prefix+'-grupo',l.grupo_dre||'')+'</div>'
    +'<div class="fg"><label>Aplicação do custo</label>'+vbeSelectAplicacaoCustoHtml(prefix+'-aplicacao',l.aplicacao_custo||'')+'</div>'
    +'<div class="fg"><label>Valor pago (R$) — parcial</label><input id="'+prefix+'-valor-pago" type="number" step="0.01" placeholder="Se Pago parcial" value="'+(l.valor_pago!=null&&l.valor_pago!==''?l.valor_pago:'')+'"/></div>'
    +'</div>'
    +'<div style="font-size:10px;color:#888;margin-top:4px">Natureza preenchida = classificação manual (prevalece no DRE). Valor pago usado em status Pago parcial.</div>'
    +'</div>';
}

function openNovoLancamento(){
  var contOpts=contratos.map(function(c){return '<option value="'+c.id+'">'+c.nome+'</option>';}).join('');
  var catOpts=categorias.map(function(c){return '<option value="'+c.id+'">'+c.nome+'</option>';}).join('');
  var fornOpts=typeof _fornOptsSelectHtml==='function'
    ? _fornOptsSelectHtml('')
    : '<option value="">Selecione (opcional)</option>'+fornecedores.map(function(f){return '<option value="'+f.id+'">'+f.razao_social+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:600px"><h3>Novo lançamento</h3>'
    +'<div class="g2">'
    +'<div class="fg"><label>Contrato</label><select id="nl-cont">'+contOpts+'</select></div>'
    +'<div class="fg"><label>Categoria</label><select id="nl-cat" onchange="atualizarSubcat()">'+catOpts+'</select></div>'
    +'<div class="fg"><label>Subcategoria</label><select id="nl-subcat"><option value="">Nenhuma</option></select></div>'
    +'<div class="fg"><label>Valor (R$)</label><input id="nl-val" type="number" step="0.01"/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Descrição</label><input id="nl-desc" placeholder="Descreva a despesa"/></div>'
    +'<div class="fg"><label>Fornecedor</label><select id="nl-forn">'+fornOpts+'</select></div>'
    +'<div class="fg"><label>Documento fiscal</label><input id="nl-doc" placeholder="NF-000000"/></div>'
    +'<div class="fg"><label>Data de emissão</label><input id="nl-emi" type="date" value="'+dataHojeLocal()+'"/></div>'
    +'<div class="fg"><label>Competência (MM/AAAA)</label><input id="nl-comp" placeholder="04/2026"/></div>'
    +'<div class="fg"><label>Data vencimento</label><input id="nl-venc" type="date"/></div>'
    +'<div class="fg"><label>Centro de custo</label><input id="nl-cc"/></div>'
    +'<div class="fg"><label>Nº da RC</label><input id="nl-rc" placeholder="RC-0000"/></div>'
    +'<div class="fg"><label>Solicitante</label><input id="nl-solicitante" placeholder="Nome do solicitante"/></div>'
    +'</div>'
    +vbeHtmlBlocoClassificacaoLanc('nl',{})
    +'<div class="fg"><label>Observação</label><textarea id="nl-obs"></textarea></div>'
    +'<div class="fg"><label>Anexar NF (XML)</label><input id="nl-xml" type="file" accept=".xml" style="font-size:12px"/></div>'
    +'<div class="fg"><label>Anexar documento (PDF)</label><input id="nl-pdf" type="file" accept=".pdf,.doc,.docx" style="font-size:12px"/></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="salvarLancamento()">Salvar lançamento</button></div></div></div>');
  atualizarSubcat();
}
function atualizarSubcat(selCatId, selSubId){
  var catEl=document.getElementById(selCatId||'nl-cat');
  var sel=document.getElementById(selSubId||'nl-subcat');
  if(!sel) return;
  var catId=(catEl&&catEl.value)||'';
  var atual=sel.value||'';
  var subs=(subcategorias||[]).filter(function(s){return s.categoria_id===catId && s.ativa!==false;});
  sel.innerHTML='<option value="">Nenhuma</option>'+subs.map(function(s){
    return '<option value="'+s.id+'"'+(atual===s.id?' selected':'')+'>'+s.nome+'</option>';
  }).join('');
}
function _escAttrLanc(v){
  return String(v==null?'':v)
    .replace(/&/g,'&amp;')
    .replace(/"/g,'&quot;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;');
}
function _escTextLanc(v){
  return String(v==null?'':v)
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;');
}
function salvarLancamento(){
  var val=parseFloat((document.getElementById('nl-val')||{}).value)||0;
  var desc=(document.getElementById('nl-desc')||{}).value||'';
  if(!desc.trim())return alert('Preencha a descrição.');
  if(!val)return alert('Informe o valor.');
  var cls=vbeLerCamposClassificacaoForm('nl');
  var novo={
    id:'l'+Date.now(),
    contrato_id:(document.getElementById('nl-cont')||{}).value||'',
    categoria_id:(document.getElementById('nl-cat')||{}).value||'',
    subcategoria_id:(document.getElementById('nl-subcat')||{}).value||null,
    descricao:desc.trim(),
    fornecedor_id:(document.getElementById('nl-forn')||{}).value||null,
    documento_fiscal:(document.getElementById('nl-doc')||{}).value||'',
    data_emissao:(document.getElementById('nl-emi')||{}).value||null,
    competencia:(document.getElementById('nl-comp')||{}).value||'',
    data_vencimento:(document.getElementById('nl-venc')||{}).value||null,
    valor:val,
    centro_custo:(document.getElementById('nl-cc')||{}).value||'',
    observacao:(document.getElementById('nl-obs')||{}).value||'',
    numero_rc:(document.getElementById('nl-rc')||{}).value||'',
    solicitante:(document.getElementById('nl-solicitante')||{}).value||'',
    status:'Lançado',
    criado_em:dataHojeLocal(),
    natureza_despesa:cls.natureza_despesa,
    grupo_dre:cls.grupo_dre,
    aplicacao_custo:cls.aplicacao_custo,
    valor_pago:cls.valor_pago,
    classificacao_manual:!!cls.classificacao_manual,
    classificacao_origem:cls.classificacao_origem||null,
    classificacao_confianca:cls.classificacao_confianca
  };
  if(novo.grupo_dre&&!novo.natureza_despesa){
    // grupo sozinho ainda conta como hint manual parcial
    novo.classificacao_manual=true;
    novo.classificacao_origem='manual';
    novo.classificacao_confianca='Manual';
  }
  lancamentos.unshift(novo);
  // atualiza verba realizado
  var v=verbas.find(function(x){return x.contrato_id===novo.contrato_id&&x.categoria_id===novo.categoria_id;});
  if(v)v.valor_realizado=(v.valor_realizado||0)+val;
  auditLog('criar','financeiro','Novo lançamento: '+(novo.descricao||'')+(novo.valor?' — R$ '+Number(novo.valor).toLocaleString('pt-BR'):''),{tipo:novo.tipo,valor:novo.valor,contrato:novo.contrato_id});
  if(!DEMO)sbInsert('lancamentos',_semId(novo)).catch(function(e){
    console.warn('[Lanc] insert com colunas Etapa G falhou — rode o SQL sql_lancamentos_etapa_g_colunas_classificacao.sql',e);
    if(typeof progShowToast==='function') progShowToast('Falha ao salvar classificação. Confira se o SQL Etapa G foi aplicado no Supabase.','erro');
  });
  closeModal();renderLancamentos();atualizarMetricas();
}
function openEditarLancamento(lid){
  var l=lancamentos.find(function(x){return x.id===lid;});if(!l)return;
  var contOpts=contratos.map(function(c){
    return '<option value="'+c.id+'"'+(String(c.id)===String(l.contrato_id)?' selected':'')+'>'+_escAttrLanc(c.nome)+'</option>';
  }).join('');
  var catOpts=categorias.filter(function(c){return c.ativa!==false;}).map(function(c){
    return '<option value="'+c.id+'"'+(String(c.id)===String(l.categoria_id)?' selected':'')+'>'+_escAttrLanc(c.nome)+'</option>';
  }).join('');
  var fornOpts=typeof _fornOptsSelectHtml==='function'
    ? _fornOptsSelectHtml(l.fornecedor_id||'')
    : '<option value="">Selecione (opcional)</option>'+fornecedores.map(function(f){
    return '<option value="'+f.id+'"'+(String(f.id)===String(l.fornecedor_id)?' selected':'')+'>'+_escAttrLanc(f.razao_social)+'</option>';
  }).join('');
  var stOpts=['Lançado','Em análise','Aprovado','Reprovado','Pago','Pago parcial','Cancelado'].map(function(s){
    return '<option'+(l.status===s?' selected':'')+'>'+s+'</option>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:640px"><h3>Editar lançamento</h3>'
    +'<div class="g2">'
    +'<div class="fg"><label>Contrato</label><select id="el-cont">'+contOpts+'</select></div>'
    +'<div class="fg"><label>Categoria</label><select id="el-cat" onchange="atualizarSubcat(\'el-cat\',\'el-subcat\')">'+catOpts+'</select></div>'
    +'<div class="fg"><label>Subcategoria</label><select id="el-subcat"><option value="">Nenhuma</option></select></div>'
    +'<div class="fg"><label>Valor (R$)</label><input id="el-val" type="number" step="0.01" value="'+(l.valor!=null?l.valor:'')+'"/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Descrição</label><input id="el-desc" value="'+_escAttrLanc(l.descricao||'')+'"/></div>'
    +'<div class="fg"><label>Fornecedor</label><select id="el-forn">'+fornOpts+'</select></div>'
    +'<div class="fg"><label>Documento fiscal / NFE</label><input id="el-doc" value="'+_escAttrLanc(l.documento_fiscal||'')+'"/></div>'
    +'<div class="fg"><label>Data de emissão</label><input id="el-emi" type="date" value="'+(l.data_emissao||'')+'"/></div>'
    +'<div class="fg"><label>Competência (MM/AAAA)</label><input id="el-comp" placeholder="06/2026" value="'+_escAttrLanc(l.competencia||'')+'"/></div>'
    +'<div class="fg"><label>Data vencimento</label><input id="el-venc" type="date" value="'+(l.data_vencimento||'')+'"/></div>'
    +'<div class="fg"><label>Data pagamento</label><input id="el-pag" type="date" value="'+(l.data_pagamento||'')+'"/></div>'
    +'<div class="fg"><label>Centro de custo</label><input id="el-cc" value="'+_escAttrLanc(l.centro_custo||'')+'"/></div>'
    +'<div class="fg"><label>Status</label><select id="el-status">'+stOpts+'</select></div>'
    +'<div class="fg"><label>Nº da RC</label><input id="el-rc" value="'+_escAttrLanc(l.numero_rc||'')+'"/></div>'
    +'<div class="fg"><label>Solicitante</label><input id="el-solicitante" value="'+_escAttrLanc(l.solicitante||'')+'"/></div>'
    +'</div>'
    +vbeHtmlBlocoClassificacaoLanc('el',l)
    +'<div class="fg"><label>Observação</label><textarea id="el-obs">'+_escTextLanc(l.observacao||'')+'</textarea></div>'
    +'<div class="ma" style="justify-content:space-between">'
    +'<button class="btn" style="color:#A32D2D;border-color:#A32D2D" onclick="excluirLancamento(\''+lid+'\')">Excluir</button>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="salvarEditarLanc(\''+lid+'\')">Salvar</button>'
    +'</div></div></div></div>');
  atualizarSubcat('el-cat','el-subcat');
  var subSel=document.getElementById('el-subcat');
  if(subSel && l.subcategoria_id){
    subSel.value=l.subcategoria_id;
    if(subSel.value!==String(l.subcategoria_id)){
      // subcategoria pode estar em outra categoria ou inativa — inclui opção
      subSel.innerHTML+='<option value="'+l.subcategoria_id+'" selected>'+_escAttrLanc(fNomeSub(l.subcategoria_id))+'</option>';
      subSel.value=l.subcategoria_id;
    }
  }
}
function salvarEditarLanc(lid){
  var l=lancamentos.find(function(x){return x.id===lid;});if(!l)return;
  var novoVal=parseFloat((document.getElementById('el-val')||{}).value);
  if(isNaN(novoVal)) novoVal=l.valor;
  var diff=novoVal-Number(l.valor||0);
  l.contrato_id=(document.getElementById('el-cont')||{}).value||l.contrato_id;
  l.categoria_id=(document.getElementById('el-cat')||{}).value||l.categoria_id;
  l.subcategoria_id=(document.getElementById('el-subcat')||{}).value||null;
  if(!l.subcategoria_id) l.subcategoria_id=null;
  l.descricao=(document.getElementById('el-desc')||{}).value||l.descricao;
  l.valor=novoVal;
  l.status=(document.getElementById('el-status')||{}).value||l.status;
  l.fornecedor_id=(document.getElementById('el-forn')||{}).value||null;
  if(!l.fornecedor_id) l.fornecedor_id=null;
  l.documento_fiscal=(document.getElementById('el-doc')||{}).value||'';
  l.data_emissao=(document.getElementById('el-emi')||{}).value||null;
  l.competencia=(document.getElementById('el-comp')||{}).value||'';
  l.data_vencimento=(document.getElementById('el-venc')||{}).value||null;
  l.data_pagamento=(document.getElementById('el-pag')||{}).value||null;
  l.centro_custo=(document.getElementById('el-cc')||{}).value||'';
  l.observacao=(document.getElementById('el-obs')||{}).value||'';
  l.numero_rc=(document.getElementById('el-rc')||{}).value||'';
  l.solicitante=(document.getElementById('el-solicitante')||{}).value||'';
  var cls=vbeLerCamposClassificacaoForm('el');
  l.natureza_despesa=cls.natureza_despesa;
  l.grupo_dre=cls.grupo_dre;
  l.aplicacao_custo=cls.aplicacao_custo;
  l.valor_pago=cls.valor_pago;
  l.classificacao_manual=!!(cls.natureza_despesa||cls.grupo_dre);
  l.classificacao_origem=l.classificacao_manual?'manual':(l.classificacao_origem||null);
  l.classificacao_confianca=l.classificacao_manual?'Manual':l.classificacao_confianca;
  if(l.status==='Pago'&&(l.valor_pago==null||l.valor_pago==='')) l.valor_pago=Number(l.valor||0);
  if(diff!==0){var v=verbas.find(function(x){return x.contrato_id===l.contrato_id&&x.categoria_id===l.categoria_id;});if(v)v.valor_realizado=(v.valor_realizado||0)+diff;}
  auditLog('editar','financeiro','Editou lançamento #'+lid+(l.descricao?' — '+l.descricao:''),{id:lid});
  if(!DEMO){
    var payload={
      contrato_id:l.contrato_id||null,
      categoria_id:l.categoria_id||null,
      subcategoria_id:l.subcategoria_id||null,
      descricao:l.descricao,
      valor:l.valor,
      status:l.status,
      fornecedor_id:l.fornecedor_id||null,
      documento_fiscal:l.documento_fiscal||null,
      data_emissao:l.data_emissao||null,
      competencia:l.competencia||null,
      data_vencimento:l.data_vencimento||null,
      data_pagamento:l.data_pagamento||null,
      centro_custo:l.centro_custo||null,
      observacao:l.observacao||null,
      numero_rc:l.numero_rc||null,
      solicitante:l.solicitante||null,
      natureza_despesa:l.natureza_despesa||null,
      grupo_dre:l.grupo_dre||null,
      aplicacao_custo:l.aplicacao_custo||null,
      valor_pago:l.valor_pago!=null?l.valor_pago:null,
      classificacao_manual:!!l.classificacao_manual,
      classificacao_origem:l.classificacao_origem||null,
      classificacao_confianca:l.classificacao_confianca||null
    };
    Promise.resolve(sbUpdate('lancamentos',payload,'id=eq.'+lid)).catch(function(e){
      console.warn('[Lanc] update Etapa G — rode SQL sql_lancamentos_etapa_g_colunas_classificacao.sql',e);
      if(typeof progShowToast==='function') progShowToast('Falha ao salvar classificação. Aplique o SQL Etapa G no Supabase.','erro');
    });
  }
  closeModal();renderLancamentos();atualizarMetricas();
}
async function excluirLancamento(lid){
  if(!_podeExcluirCritico()){
    if(typeof progShowToast==='function') progShowToast('Somente admin/gestor pode excluir lançamentos.','erro');
    else alert('Somente admin/gestor pode excluir lançamentos.');
    return;
  }
  var l=lancamentos.find(function(x){return String(x.id)===String(lid);});
  if(!l){
    if(typeof progShowToast==='function') progShowToast('Lançamento não encontrado.','erro');
    return;
  }
  var desc=l.descricao||'(sem descrição)';
  var valorTxt=typeof fmtR==='function'?fmtR(l.valor):('R$ '+Number(l.valor||0).toLocaleString('pt-BR'));
  var msg='Excluir este lançamento financeiro?\n\n'
    +desc+'\n'
    +valorTxt+' · '+(l.status||'—')
    +'\n\nO registro será desativado (soft-delete), não apagado do banco.';
  if(l.status==='Pago'||l.status==='Pago parcial'){
    msg+='\n\nAtenção: o lançamento já está marcado como '+(l.status)+'.';
  }
  if(!confirm(msg)) return;
  if((l.status==='Pago'||l.status==='Pago parcial') && !confirm('Confirma exclusão de lançamento já '+l.status+'?')) return;
  try{
    if(!DEMO){
      if(typeof isUUID==='function'&&!isUUID(String(lid))){
        console.warn('[Lanc] exclusão local — id não é UUID:', lid);
      } else {
        await sbDelete('lancamentos','id=eq.'+lid);
      }
    }
    var v=verbas.find(function(x){return x.contrato_id===l.contrato_id&&x.categoria_id===l.categoria_id;});
    if(v) v.valor_realizado=Math.max(0,(Number(v.valor_realizado||0)-Number(l.valor||0)));
    lancamentos=lancamentos.filter(function(x){return String(x.id)!==String(lid);});
    auditLog('excluir','financeiro','Excluiu lançamento: '+desc+(l.valor!=null?' — '+valorTxt:''),{id:lid,status:l.status,contrato:l.contrato_id,valor:l.valor});
    closeModal();
    renderLancamentos();
    if(typeof renderAprovacao==='function') renderAprovacao();
    if(typeof atualizarMetricas==='function') atualizarMetricas();
    if(typeof progShowToast==='function') progShowToast('Lançamento excluído.');
  }catch(e){
    console.error('[Lanc] excluir',e);
    if(typeof progShowToast==='function') progShowToast('Erro ao excluir lançamento.','erro');
    else alert('Erro ao excluir lançamento.');
  }
}
function enviarAprovacao(lid){
  var l=lancamentos.find(function(x){return x.id===lid;});if(!l)return;
  l.status='Em análise';
  if(!DEMO)sbUpdate('lancamentos',{status:'Em análise'},'id=eq.'+lid);
  renderLancamentos();renderAprovacao();
}

// APROVAÇÃO
function renderAprovacao(){
  var pend=lancamentos.filter(function(l){return l.status==='Em análise';});
  var al=document.getElementById('aprov-lista');if(!al)return;
  if(!pend.length){al.innerHTML='<div style="border:.5px solid #e0dfd8;border-radius:12px;display:flex;align-items:center;justify-content:center;height:120px;color:#bbb;font-size:13px">Nenhum lançamento aguardando aprovação</div>';return;}
  al.innerHTML=pend.map(function(l){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem;margin-bottom:.75rem">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:.75rem">'
      +'<div><div style="font-weight:500;font-size:13px">'+l.descricao+'</div>'
      +'<div style="font-size:11px;color:#888;margin-top:2px">'+fNomeCont(l.contrato_id)+' — '+fNomeCat(l.categoria_id)+' — '+fmtD(l.data_emissao)+'</div></div>'
      +'<div style="font-size:18px;font-weight:500;color:#1a1a18">'+fmtR(l.valor)+'</div></div>'
      +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">Fornecedor: '+fNomeForn(l.fornecedor_id)+' | Doc: '+(l.documento_fiscal||'—')+'</div>'
      +'<div style="display:flex;gap:8px">'
      +'<button class="btn btn-pri" onclick="aprovarLanc(\''+l.id+'\')">Aprovar</button>'
      +'<button class="btn" style="border-color:#A32D2D;color:#A32D2D" onclick="reprovarLanc(\''+l.id+'\')">Reprovar</button>'
      +'<button class="btn" onclick="marcarPago(\''+l.id+'\')">Marcar como pago</button>'
      +'</div></div>';
  }).join('');
}
function aprovarLanc(lid){
  var l=lancamentos.find(function(x){return x.id===lid;});if(!l)return;
  l.status='Aprovado';auditLog('editar','financeiro','Aprovou lançamento #'+lid,{id:lid,status:'Aprovado'});if(!DEMO)sbUpdate('lancamentos',{status:'Aprovado'},'id=eq.'+lid);
  renderAprovacao();renderLancamentos();
}
function reprovarLanc(lid){
  var motivo=prompt('Motivo da reprovação:');if(motivo===null)return;
  var l=lancamentos.find(function(x){return x.id===lid;});if(!l)return;
  l.status='Reprovado';l.motivo_reprovacao=motivo;
  auditLog('editar','financeiro','Reprovou lançamento #'+lid+(motivo?' — Motivo: '+motivo:''),{id:lid,status:'Reprovado'});
  if(!DEMO)sbUpdate('lancamentos',{status:'Reprovado',motivo_reprovacao:motivo},'id=eq.'+lid);
  renderAprovacao();renderLancamentos();
}
function marcarPago(lid){
  var l=lancamentos.find(function(x){return x.id===lid;});if(!l)return;
  l.status='Pago';l.data_pagamento=dataHojeLocal();
  if(l.valor_pago==null||l.valor_pago==='') l.valor_pago=Number(l.valor||0);
  auditLog('editar','financeiro','Marcou como Pago lançamento #'+lid,{id:lid,status:'Pago'});
  if(!DEMO)sbUpdate('lancamentos',{status:'Pago',data_pagamento:l.data_pagamento,valor_pago:l.valor_pago},'id=eq.'+lid);
  renderAprovacao();renderLancamentos();
}

// RELATÓRIOS
// ═══════════════════════════════════════════════════════
// RELATÓRIOS — TAB BAR E TMA ESCALA
// ═══════════════════════════════════════════════════════
var _relAbaAtual = 'financeiro';

function relAbaSelecionar(aba){
  var abas = ['financeiro','tma','frotas','plpt','rdse','sot'];
  abas.forEach(function(a){
    var el = document.getElementById('rel-aba-'+a);
    var btn = document.getElementById('rel-tab-'+a);
    if(el) el.style.display = a===aba ? '' : 'none';
    if(btn){ btn.style.borderBottomColor = a===aba ? '#1a1a18' : 'transparent'; btn.style.color = a===aba ? '#1a1a18' : '#888'; }
  });
  _relAbaAtual = aba;
  if(aba==='tma') relTmaInicializar();
  if(aba==='frotas') relFrotasInicializar();
}

// ── Relatórios → Frotas (cadastro de veículos) ─────────────────
var _relFrotasCache = null;

function relFrotasInicializar(){
  var selCont=document.getElementById('rel-frt-cont');
  if(selCont && selCont.options.length<=1){
    (contratos||[]).slice().sort(function(a,b){
      return String(almContratoLabel(a,false)||'').localeCompare(String(almContratoLabel(b,false)||''),'pt-BR',{sensitivity:'base'});
    }).forEach(function(c){
      selCont.appendChild(new Option(almContratoLabel(c,false)||c.nome||c.codigo||c.id, c.id));
    });
  }
  var selSt=document.getElementById('rel-frt-status');
  if(selSt && selSt.options.length<=1){
    (FRT_STATUS||[]).forEach(function(s){ selSt.appendChild(new Option(s,s)); });
    selSt.appendChild(new Option('Inativo','Inativo'));
  }
  var selTipo=document.getElementById('rel-frt-tipo');
  if(selTipo && selTipo.options.length<=1){
    var tipos={};
    (FRT_TIPOS_OPERACIONAIS||[]).forEach(function(t){ tipos[t]=1; });
    (FRT_TIPOS||[]).forEach(function(t){ tipos[t]=1; });
    Object.keys(tipos).sort(function(a,b){return a.localeCompare(b,'pt-BR');}).forEach(function(t){
      selTipo.appendChild(new Option(t,t));
    });
  }
  // Período combustível padrão: mês corrente
  var ini=document.getElementById('rel-frt-comb-ini');
  var fim=document.getElementById('rel-frt-comb-fim');
  var hoje=typeof dataHojeLocal==='function'?dataHojeLocal():new Date().toISOString().slice(0,10);
  if(ini && !ini.value) ini.value=hoje.slice(0,8)+'01';
  if(fim && !fim.value) fim.value=hoje;
}

function relFrotasDocLabel(lista, tiposAceitos){
  if(!lista||!lista.length) return 'Não cadastrado';
  var found=null;
  lista.forEach(function(d){
    var t=String(d.tipo||'');
    if(tiposAceitos.indexOf(t)<0) return;
    if(!found){ found=d; return; }
    var a=String(d.validade||d.data_validade||d.data_vencimento||d.emissao||'');
    var b=String(found.validade||found.data_validade||found.data_vencimento||found.emissao||'');
    if(a>b) found=d;
  });
  if(!found) return 'Não cadastrado';
  var val=String(found.validade||found.data_validade||found.data_vencimento||'').slice(0,10);
  if(val){
    var hoje=typeof dataHojeLocal==='function'?dataHojeLocal():new Date().toISOString().slice(0,10);
    var lab=typeof fmtD==='function'?fmtD(val):val;
    return val<hoje ? ('Vencido '+lab) : lab;
  }
  return found.numero||found.status||'Cadastrado';
}

function relFrotasSeguroLabel(v, docsPlaca){
  var tem=!!(v&&(v.tem_seguro===true||v.tem_seguro==='true'||v.tem_seguro===1||v.tem_seguro==='Sim'));
  if(tem){
    var s=(v.seguradora||'').trim();
    var tip=(v.tipo_seguro||'').trim();
    var val=v.validade_seguro?String(v.validade_seguro).slice(0,10):'';
    var parts=['Sim'];
    if(s) parts.push(s);
    if(tip) parts.push(tip);
    if(val) parts.push('val. '+(typeof fmtD==='function'?fmtD(val):val));
    return parts.join(' · ');
  }
  var docSeg=relFrotasDocLabel(docsPlaca,['Seguro']);
  if(docSeg && docSeg!=='Não cadastrado') return 'Sim · '+docSeg;
  return 'Não';
}

function relFrotasCabecalho(){
  return [
    'Placa','Tipo (Posse)','Status','Tipo equipamento','Modelo','Marca','Combustível','Ano',
    'Renavam','Centro de Custo','Valor Locação','Valor Combustível','Gestor','Seguro','Chassi',
    'Final da Placa','Licenciamento','Grupo Restrição','Rastreador','CRLV','Ensaio Acústico',
    'Ensaio Elétrico','Próprio / Empresa Locação'
  ];
}

function relFrotasLinhaVals(r){
  return [
    r.placa,r.posse,r.status,r.tipoEquip,r.modelo,r.marca,r.combustivel,r.ano,
    r.renavam,r.centroCusto,r.valorLocacaoFmt,r.valorCombFmt,r.gestor,r.seguro,r.chassi,
    r.finalPlaca,r.licenciamento,r.grupoRestricao,r.rastreador,r.crlv,r.ensaioAcustico,
    r.ensaioEletrico,r.empresaLocacao
  ];
}

function relFrotasGerar(){
  var wrap=document.getElementById('rel-frt-resultado');
  if(!wrap) return;
  wrap.innerHTML='<div style="padding:1rem;color:#888;font-size:12px">⏳ Carregando frota, documentos e combustível...</div>';
  var contId=(document.getElementById('rel-frt-cont')||{}).value||'';
  var posseF=(document.getElementById('rel-frt-posse')||{}).value||'';
  var statusF=(document.getElementById('rel-frt-status')||{}).value||'';
  var tipoF=(document.getElementById('rel-frt-tipo')||{}).value||'';
  var combIni=(document.getElementById('rel-frt-comb-ini')||{}).value||'';
  var combFim=(document.getElementById('rel-frt-comb-fim')||{}).value||'';

  var jobs=[];
  // Veículos (completo)
  if(typeof frtFetchVeiculosCompleto==='function'){
    jobs.push(frtFetchVeiculosCompleto().then(function(rows){
      if(rows&&rows.length){
        var byId={}; (frt_veiculos||[]).forEach(function(v){ if(v&&v.id) byId[v.id]=v; });
        rows.forEach(function(v){ if(v&&v.id) byId[v.id]=v; });
        frt_veiculos=Object.keys(byId).map(function(k){return byId[k];});
      }
    }).catch(function(){}));
  } else if(!DEMO){
    jobs.push(sbFetch('frotas_veiculos',{order:'placa',limit:5000}).then(function(rows){
      if(rows&&rows.length) frt_veiculos=rows;
    }).catch(function(){}));
  }
  // Documentos
  if(!DEMO){
    jobs.push(frtFetchDocumentosCompleto().then(function(r){
      if(r&&r.length) frt_documentos=(typeof fdocNormRows==='function'?fdocNormRows(r):r);
    }).catch(function(){}));
  }
  // Combustível no período
  if(!DEMO && (combIni||combFim)){
    var fComb=[];
    if(combIni) fComb.push('data=gte.'+combIni);
    if(combFim) fComb.push('data=lte.'+combFim);
    var fetchComb=typeof sbFetchAll==='function'
      ? sbFetchAll('frotas_combustivel',{filters:fComb,order:'data.desc',maxPages:8})
      : sbFetch('frotas_combustivel',{filters:fComb,order:'data.desc',limit:5000});
    jobs.push(fetchComb.then(function(rows){
      if(!rows||!rows.length) return;
      var byId={}; (frt_combustivel||[]).forEach(function(c){ if(c&&c.id) byId[c.id]=c; });
      rows.forEach(function(c){ if(c&&c.id) byId[c.id]=c; });
      frt_combustivel=Object.keys(byId).map(function(k){return byId[k];});
    }).catch(function(){}));
  }

  Promise.all(jobs).then(function(){
    var docsByPlaca={};
    (frt_documentos||[]).forEach(function(d){
      var np=typeof frtNormPlaca==='function'?frtNormPlaca(d.placa):String(d.placa||'').toUpperCase().replace(/[-\s]/g,'');
      if(!np) return;
      if(!docsByPlaca[np]) docsByPlaca[np]=[];
      docsByPlaca[np].push(d);
    });
    var combByPlaca={};
    (frt_combustivel||[]).forEach(function(c){
      var ds=String(c.data||'').slice(0,10);
      if(combIni && ds && ds<combIni) return;
      if(combFim && ds && ds>combFim) return;
      var np=typeof frtNormPlaca==='function'?frtNormPlaca(c.placa):String(c.placa||'').toUpperCase().replace(/[-\s]/g,'');
      if(!np) return;
      combByPlaca[np]=(combByPlaca[np]||0)+(Number(c.valor_total)||0);
    });

    var rows=(frt_veiculos||[]).filter(function(v){
      if(!v||!v.placa) return false;
      if(contId && String(v.contrato_id||'')!==String(contId)) return false;
      if(posseF && String(v.posse||'')!==posseF) return false;
      if(statusF){
        if(statusF==='Inativo'){
          if(!(v.ativo===false || v.status==='Baixado' || String(v.status||'').toLowerCase().indexOf('inativ')>=0)) return false;
        } else if(String(v.status||'')!==statusF) return false;
      }
      if(tipoF){
        var te=String(v.tipo_operacional||v.tipo||'');
        if(te!==tipoF) return false;
      }
      return true;
    }).slice().sort(function(a,b){
      return String(a.placa||'').localeCompare(String(b.placa||''),'pt-BR');
    });

    var dados=rows.map(function(v){
      var np=typeof frtNormPlaca==='function'?frtNormPlaca(v.placa):String(v.placa||'').toUpperCase().replace(/[-\s]/g,'');
      var docs=docsByPlaca[np]||[];
      var valorLoc=Number(v.valor_mensal)||0;
      var valorComb=combByPlaca[np]||0;
      var status=v.status||'';
      if(v.ativo===false && status!=='Baixado' && String(status).toLowerCase().indexOf('inativ')<0){
        status=(status?status+' / ':'')+'Inativo';
      }
      var empresaLoc='—';
      if(String(v.posse||'')==='Próprio') empresaLoc='Próprio';
      else if(v.fornecedor_id) empresaLoc=(typeof fNomeForn==='function'?fNomeForn(v.fornecedor_id):'—');
      var temRastr=!!(v.rastreador_fornecedor||v.rastreador_id_externo);
      return {
        placa:v.placa||'',
        posse:v.posse||'—',
        status:status||'—',
        tipoEquip:(v.tipo_operacional||v.tipo||'—'),
        modelo:v.modelo||'—',
        marca:v.marca||'—',
        combustivel:v.combustivel||'—',
        ano:v.ano!=null&&v.ano!==''?String(v.ano):'—',
        renavam:v.renavam||'—',
        centroCusto:v.contrato_id?(typeof fNomeCont==='function'?fNomeCont(v.contrato_id):'—'):'—',
        valorLocacao:valorLoc,
        valorLocacaoFmt:valorLoc?fmtR(valorLoc):'—',
        valorComb:valorComb,
        valorCombFmt:valorComb?fmtR(valorComb):'—',
        gestor:v.responsavel||'—',
        seguro:relFrotasSeguroLabel(v,docs),
        chassi:v.chassi||'—',
        finalPlaca:np?np.slice(-1):'—',
        licenciamento:relFrotasDocLabel(docs,['Licenciamento']),
        grupoRestricao:'—',
        rastreador:temRastr?'Sim':'Não',
        crlv:relFrotasDocLabel(docs,['CRLV']),
        ensaioAcustico:relFrotasDocLabel(docs,['Teste Acústico']),
        ensaioEletrico:relFrotasDocLabel(docs,['Teste Dielétrico']),
        empresaLocacao:empresaLoc
      };
    });

    _relFrotasCache={dados:dados,combIni:combIni,combFim:combFim,geradoEm:new Date().toLocaleString('pt-BR')};
    wrap._dados=dados;

    if(!dados.length){
      wrap.innerHTML='<div style="padding:1.5rem;text-align:center;color:#888;font-size:12px">Nenhum veículo encontrado com os filtros informados.</div>';
      document.getElementById('btn-rel-frt-pdf').style.display='none';
      document.getElementById('btn-rel-frt-excel').style.display='none';
      return;
    }

    var cab=relFrotasCabecalho();
    var html='<div style="padding:.5rem .75rem;font-size:12px;color:#555;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px">'
      +'<span><b>'+dados.length+'</b> veículo(s)'
      +(combIni||combFim?' · combustível '+(combIni||'…')+' a '+(combFim||'…'):'')
      +'</span>'
      +'<span style="color:#888">Grupo Restrição: campo ainda não cadastrado no ERP (exibe —)</span>'
      +'</div>';
    html+='<div style="overflow-x:auto;max-height:70vh"><table class="tbl" style="font-size:11px;white-space:nowrap"><thead><tr>';
    cab.forEach(function(h){ html+='<th style="position:sticky;top:0;background:#f0f0f0;z-index:1">'+escHtml(h)+'</th>'; });
    html+='</tr></thead><tbody>';
    dados.forEach(function(r,i){
      var bg=i%2===0?'#fff':'#fafaf8';
      html+='<tr style="background:'+bg+'">';
      relFrotasLinhaVals(r).forEach(function(c,ci){
        var bold=ci===0?'font-weight:700;letter-spacing:.5px':'';
        html+='<td style="'+bold+'">'+escHtml(String(c==null?'':c))+'</td>';
      });
      html+='</tr>';
    });
    html+='</tbody></table></div>';
    wrap.innerHTML=html;
    document.getElementById('btn-rel-frt-pdf').style.display='';
    document.getElementById('btn-rel-frt-excel').style.display='';
  }).catch(function(err){
    wrap.innerHTML='<div style="padding:1rem;color:#c00;font-size:12px">Erro ao gerar: '+escHtml(String(err))+'</div>';
  });
}

function relFrotasExportarExcel(){
  var dados=(_relFrotasCache&&_relFrotasCache.dados)||[];
  if(!dados.length){ progShowToast('⚠️ Gere o relatório primeiro.'); return; }
  var cab=relFrotasCabecalho();
  var linhas=dados.map(relFrotasLinhaVals);
  var per='';
  if(_relFrotasCache.combIni||_relFrotasCache.combFim){
    per=' · Combustível '+(_relFrotasCache.combIni||'…')+' a '+(_relFrotasCache.combFim||'…');
  }
  exportarXLS(
    'frota_veiculos_'+(_relFrotasCache.combIni||'todos'),
    cab,
    linhas,
    'Cadastro de Frota — Veículos'+per+' · '+dados.length+' registro(s)'
  );
}

function relFrotasExportarPDF(){
  var dados=(_relFrotasCache&&_relFrotasCache.dados)||[];
  if(!dados.length){ progShowToast('⚠️ Gere o relatório primeiro.'); return; }
  var cab=relFrotasCabecalho();
  var per='';
  if(_relFrotasCache.combIni||_relFrotasCache.combFim){
    per=' · Combustível '+(_relFrotasCache.combIni||'…')+' a '+(_relFrotasCache.combFim||'…');
  }
  var html='<div style="padding:8px 12px;font-family:Arial,sans-serif">'
    +'<div style="font-size:14px;font-weight:700;margin-bottom:4px">ERP CENA — Cadastro de Frota (Veículos)</div>'
    +'<div style="font-size:10px;color:#555;margin-bottom:8px">'+dados.length+' veículo(s)'+escHtml(per)
    +' · Gerado em '+escHtml(_relFrotasCache.geradoEm||'')+'</div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:7px">'
    +'<thead><tr>'+cab.map(function(h){
      return '<th style="background:#1a1a18;color:#fff;padding:3px 4px;border:1px solid #333;text-align:left">'+escHtml(h)+'</th>';
    }).join('')+'</tr></thead><tbody>';
  dados.forEach(function(r,i){
    var bg=i%2===0?'#fff':'#f5f5f3';
    html+='<tr>'+relFrotasLinhaVals(r).map(function(c){
      return '<td style="padding:2px 4px;border:1px solid #ccc;background:'+bg+'">'+escHtml(String(c==null?'':c))+'</td>';
    }).join('')+'</tr>';
  });
  html+='</tbody></table></div>';
  _tmaPrintOverlay(html);
}

function relTmaInicializar(){
  // Popular selects de equipe e tipo
  var TMA_CID = '04277076-baa5-4ea4-85dc-bddf55541e68';
  // Popular select de colaborador (Histórico)
  var selColab = document.getElementById('hc-colab-id');
  if(selColab && selColab.options.length <= 1){
    var colsHc = (colaboradores||[]).filter(function(c){ return c.ativo!==false; })
      .sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR',{sensitivity:'base'}); });
    colsHc.forEach(function(c){
      selColab.appendChild(new Option(c.nome+(c.re?' (RE '+c.re+')':''), c.id));
    });
  }
  var selEq = document.getElementById('tma-rel-eq');
  if(selEq && selEq.options.length <= 1){
    (equipes_disp||[]).filter(function(e){return e.contrato_id===TMA_CID&&e.status==='Ativo';})
      .sort(function(a,b){return (a.codigo||'').localeCompare(b.codigo||'');})
      .forEach(function(e){ selEq.appendChild(new Option(e.codigo+' — '+(e.nome||''), e.id)); });
  }
  relTmaPopularTiposMulti();
  // Selects dos novos relatórios (saída S/N e horas logadas)
  ['tma-saiu-eq','tma-horas-eq','tma-fat-eq'].forEach(function(id){
    var sel=document.getElementById(id);
    if(sel && sel.options.length<=1){
      (equipes_disp||[]).filter(function(e){return e.contrato_id===TMA_CID&&e.status==='Ativo';})
        .sort(function(a,b){return (a.codigo||'').localeCompare(b.codigo||'');})
        .forEach(function(e){ sel.appendChild(new Option(e.codigo+' — '+(e.nome||''), e.id)); });
    }
  });
  // Data padrão = hoje
  var hoje = dataHojeLocal();
  var ini = document.getElementById('tma-rel-ini');
  var fim = document.getElementById('tma-rel-fim');
  if(ini && !ini.value) ini.value = hoje;
  if(fim && !fim.value) fim.value = hoje;
  // Período padrão últimos 7 dias para saída/horas/faturamento ponto
  var d7=new Date(); d7.setDate(d7.getDate()-6);
  var ini7=d7.toISOString().slice(0,10);
  [['tma-saiu-ini','tma-saiu-fim'],['tma-horas-ini','tma-horas-fim'],['tma-fat-ini','tma-fat-fim']].forEach(function(pair){
    var a=document.getElementById(pair[0]), b=document.getElementById(pair[1]);
    if(a&&!a.value) a.value=ini7;
    if(b&&!b.value) b.value=hoje;
  });
}

/** Multi-select de tipos de equipe — relatório escala TMA Oeste */
function relTmaPopularTiposMulti(){
  var box=document.getElementById('tma-rel-tipo-opts');
  if(!box) return;
  if(box.getAttribute('data-ready')==='1' && box.children.length) return;
  var tipos=(tipos_equipe||[]).slice().sort(function(a,b){
    return String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR',{sensitivity:'base'});
  });
  if(!tipos.length){
    box.innerHTML='<div style="font-size:11px;color:#aaa;padding:4px">Nenhum tipo cadastrado</div>';
    return;
  }
  box.innerHTML=tipos.map(function(t){
    return '<label style="display:flex;align-items:center;gap:6px;font-size:12px;padding:3px 2px;cursor:pointer">'
      +'<input type="checkbox" class="tma-rel-tipo-chk" value="'+escHtml(String(t.id))+'" onchange="relTmaTipoMultiOnChange()"/>'
      +escHtml(t.nome||t.id)
      +'</label>';
  }).join('');
  box.setAttribute('data-ready','1');
  var all=document.getElementById('tma-rel-tipo-all');
  if(all) all.checked=true;
  relTmaAtualizarLabelTipos();
}

function relTmaToggleTipoMulti(ev){
  if(ev){ ev.preventDefault(); ev.stopPropagation(); }
  relTmaPopularTiposMulti();
  var panel=document.getElementById('tma-rel-tipo-panel');
  if(!panel) return;
  var open=panel.style.display==='none'||!panel.style.display;
  panel.style.display=open?'block':'none';
  if(open){
    setTimeout(function(){
      document.addEventListener('click', relTmaFecharTipoMultiOutside, {once:true});
    }, 0);
  }
}
function relTmaFecharTipoMultiOutside(e){
  var panel=document.getElementById('tma-rel-tipo-panel');
  var btn=document.getElementById('tma-rel-tipo-btn');
  if(!panel) return;
  if(panel.contains(e.target) || (btn&&btn.contains(e.target))) {
    document.addEventListener('click', relTmaFecharTipoMultiOutside, {once:true});
    return;
  }
  panel.style.display='none';
}
function relTmaTipoMultiToggleAll(checked){
  document.querySelectorAll('#tma-rel-tipo-opts .tma-rel-tipo-chk').forEach(function(chk){
    chk.checked=!!checked;
  });
  relTmaAtualizarLabelTipos();
}
function relTmaTipoMultiOnChange(){
  var chks=Array.prototype.slice.call(document.querySelectorAll('#tma-rel-tipo-opts .tma-rel-tipo-chk'));
  var all=document.getElementById('tma-rel-tipo-all');
  if(all){
    var nOn=chks.filter(function(c){return c.checked;}).length;
    all.checked = nOn===0 || nOn===chks.length;
    // Se marcou algum específico, "Todos" fica desmarcado (exceto se marcou todos)
    if(nOn>0 && nOn<chks.length) all.checked=false;
    if(nOn===chks.length && chks.length) all.checked=true;
  }
  relTmaAtualizarLabelTipos();
}
/** Retorna [] = todos os tipos; ou lista de tipo_id selecionados */
function relTmaGetTiposSelecionados(){
  var chks=Array.prototype.slice.call(document.querySelectorAll('#tma-rel-tipo-opts .tma-rel-tipo-chk'));
  if(!chks.length) return [];
  var sel=chks.filter(function(c){return c.checked;}).map(function(c){return String(c.value);});
  var all=document.getElementById('tma-rel-tipo-all');
  // Nenhum marcado ou "Todos" marcado sem parcial → sem filtro
  if(!sel.length) return [];
  if(all && all.checked && sel.length===chks.length) return [];
  if(all && all.checked && sel.length===0) return [];
  // Se "Todos" marcado e nenhum específico: sem filtro
  if(all && all.checked && !chks.some(function(c){return c.checked;})) return [];
  // Seleção parcial
  if(sel.length && sel.length<chks.length) return sel;
  if(sel.length===chks.length) return []; // todos os itens = equivalente a Todos
  return sel;
}
function relTmaAtualizarLabelTipos(){
  var lab=document.getElementById('tma-rel-tipo-label');
  if(!lab) return;
  var ids=relTmaGetTiposSelecionados();
  if(!ids.length){ lab.textContent='Todos'; return; }
  var nomes=ids.map(function(id){
    var t=(tipos_equipe||[]).find(function(x){return String(x.id)===String(id);});
    return t?(t.nome||id):id;
  });
  if(nomes.length===1) lab.textContent=nomes[0];
  else if(nomes.length<=2) lab.textContent=nomes.join(', ');
  else lab.textContent=nomes.length+' tipos selecionados';
  lab.title=nomes.join(', ');
}

// Helper: Exportar como XLS real (Excel abre diretamente)
function exportarXLS(nomeArquivo, cabecalho, linhas, titulo){
  var estiloTh = 'background:#1a1a18;color:#fff;font-weight:bold;padding:5px 8px;border:1px solid #999;white-space:nowrap';
  var estiloTd = 'padding:4px 8px;border:1px solid #ccc';
  var html = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">'
    +'<head><meta charset="UTF-8"><style>td,th{mso-number-format:"@";}</style></head><body>'
    +(titulo?'<h3 style="font-family:Arial">'+titulo+'</h3>':'')
    +'<table border="1" cellspacing="0" cellpadding="4" style="font-family:Arial;font-size:11px;border-collapse:collapse">'
    +'<thead><tr>'+cabecalho.map(function(h){return '<th style="'+estiloTh+'">'+h+'</th>';}).join('')+'</tr></thead>'
    +'<tbody>'+linhas.map(function(r,i){
      var bg=i%2===0?'#fff':'#f5f5f3';
      return '<tr>'+r.map(function(c){return '<td style="'+estiloTd+';background:'+bg+'">'+String(c===null||c===undefined?'':c)+'</td>';}).join('')+'</tr>';
    }).join('')+'</tbody></table></body></html>';
  var b=new Blob([html],{type:'application/vnd.ms-excel;charset=utf-8'});
  var l=document.createElement('a');l.href=URL.createObjectURL(b);
  l.download=(nomeArquivo||'relatorio')+'.xls';l.click();
}

// ── Relatório: Não Escalados ───────────────────────────────
// ══════════════════════════════════════════════════════════════════
// MÓDULO: TRATAMENTO DE VERIFICAR
// ══════════════════════════════════════════════════════════════════
var _vtDados = []; // cache local dos tratamentos
var _colabHistorico = {}; // colaboradores dispensados/inativos (Tratamento Verificar)

function progFindColab(id){
  if(!id) return null;
  var cid = String(id);
  var c = (typeof colaboradores!=='undefined'?colaboradores:[]).find(function(x){ return String(x.id)===cid; });
  if(c) return c;
  var h = _colabHistorico[cid];
  return h || null;
}

var VT_ETAPAS = [
  {id:'supervisao',  label:'Supervisão'},
  {id:'coordenacao', label:'Coordenação'},
  {id:'gerencia',    label:'Gerência'},
  {id:'dp',          label:'Depto. Pessoal'}
];
var VT_DECISOES = [
  {id:'ajustado',        label:'Ajustado'},
  {id:'advertencia',     label:'Advertência'},
  {id:'demissao',        label:'Demissão'},
  {id:'desconto_folha',  label:'Desconto em Folha'}
];
var VT_STATUS_LABEL = {pendente:'🔴 Pendente', em_andamento:'🟡 Em andamento', concluido:'🟢 Concluído'};

// Garante registro em verificar_tratamentos (retorna true se inseriu novo)
function vtGarantirTratamento(colaboradorId, dataOcorr, obs){
  if(DEMO || !colaboradorId || !dataOcorr) return Promise.resolve(false);
  var data = (dataOcorr||'').split('T')[0];
  return sbFetch('verificar_tratamentos',{
    filters:['colaborador_id=eq.'+colaboradorId,'data_ocorrencia=eq.'+data],
    select:'id,obs_verificar',
    limit:1
  }).then(function(ex){
    if(ex && ex.length){
      if(obs && !(ex[0].obs_verificar||'').trim()){
        return sbUpdate('verificar_tratamentos',{obs_verificar:obs},'id=eq.'+ex[0].id).then(function(){return false;});
      }
      return false;
    }
    return sbInsert('verificar_tratamentos',{
      colaborador_id: colaboradorId,
      data_ocorrencia: data,
      obs_verificar: obs||'',
      gravidade: 'media',
      status:'pendente'
    }, {silent:true}).then(function(res){
      if(res) return true; // inseriu novo
      // Corrida: outra chamada criou o mesmo colaborador+data entre o SELECT e o INSERT.
      // O 409 (unique verificar_tratamentos_colab_data_uniq) NÃO é erro aqui — o registro já existe.
      var err = window._sbLastInsertErr||'';
      if(/23505|duplicate|verificar_tratamentos_colab_data_uniq/i.test(err)){
        if(obs){
          return sbFetch('verificar_tratamentos',{
            filters:['colaborador_id=eq.'+colaboradorId,'data_ocorrencia=eq.'+data],
            select:'id,obs_verificar', limit:1
          }).then(function(ex2){
            if(ex2 && ex2.length && !(ex2[0].obs_verificar||'').trim()){
              return sbUpdate('verificar_tratamentos',{obs_verificar:obs},'id=eq.'+ex2[0].id).then(function(){return false;});
            }
            return false;
          }).catch(function(){ return false; });
        }
        return false;
      }
      return false; // outro erro: não quebra o fluxo de sincronização
    });
  }).catch(function(){ return false; });
}

// Importa status Verificar da programação (prog_status_diario) para verificar_tratamentos
function vtSincronizarPeriodo(ini, fim, silent){
  if(DEMO || !ini || !fim) return Promise.resolve({inseridos:0,existentes:0});
  return sbFetchAll('prog_status_diario',{
    filters:['status=eq.verificar','data=gte.'+ini,'data=lte.'+fim,'deleted_at=is.null'],
    select:'colaborador_id,data,obs',
    order:'data.asc'
  }).then(function(rows){
    if(!rows || !rows.length) return {inseridos:0,existentes:0};
    // Dedup por colaborador+dia antes de disparar em paralelo: se a programação
    // tiver mais de um registro 'verificar' no mesmo dia p/ o mesmo colaborador,
    // rodar vtGarantirTratamento pros dois ao mesmo tempo cria duplicidade (ambos
    // checam "já existe?" antes de qualquer um terminar o insert).
    var vistos = {};
    var unicos = [];
    rows.forEach(function(r){
      var dataOcorr = (r.data||'').split('T')[0];
      var chave = r.colaborador_id+'|'+dataOcorr;
      if(vistos[chave]) return;
      vistos[chave] = true;
      unicos.push(r);
    });
    var inseridos=0, existentes=0;
    var promises = unicos.map(function(r){
      var dataOcorr = (r.data||'').split('T')[0];
      return vtGarantirTratamento(r.colaborador_id, dataOcorr, r.obs||'').then(function(novo){
        if(novo) inseridos++; else existentes++;
      });
    });
    return Promise.all(promises).then(function(){
      if(!silent && inseridos) progShowToast('✅ '+inseridos+' ocorrência(s) importada(s) da programação.');
      vtAtualizarAbaAlerta();
      return {inseridos:inseridos, existentes:existentes};
    });
  }).catch(function(e){
    console.error('vtSincronizarPeriodo erro:', e);
    return {inseridos:0,existentes:0};
  });
}

function vtDataMenosDias(isoData, dias){
  var d = new Date((isoData||dataHojeLocal())+'T12:00:00');
  d.setDate(d.getDate() - (dias||0));
  return d.toISOString().split('T')[0];
}

// ── Carrega datas com pendência para o select ────────────────────────────────
function vtCarregarDatasPendentes(){
  if(DEMO) return;
  // Buscar todas as ocorrências não concluídas (paginado + ordenado por data)
  sbFetchAll('verificar_tratamentos',{
    filters:['status=in.(pendente,em_andamento)'],
    select:'data_ocorrencia',
    order:'data_ocorrencia.desc'
  }).then(function(rows){
    var sel = document.getElementById('vt-fil-data-pend');
    if(!sel) return;
    // Coletar datas únicas e ordenar
    var datas = [];
    (rows||[]).forEach(function(r){
      var d = (r.data_ocorrencia||'').split('T')[0];
      if(d && datas.indexOf(d)<0) datas.push(d);
    });
    datas.sort().reverse(); // mais recente primeiro
    // Reconstruir opções
    var atual = sel.value;
    sel.innerHTML = '<option value="">Todas as datas ('+datas.length+' com pendência)</option>';
    datas.forEach(function(d){
      var opt = document.createElement('option');
      opt.value = d;
      // Formato dd/mm/aa
      var p = d.split('-');
      opt.textContent = '📅 '+p[2]+'/'+p[1]+'/'+p[0].slice(2);
      if(d===atual) opt.selected=true;
      sel.appendChild(opt);
    });
  }).catch(function(e){ console.error('vtCarregarDatasPendentes erro:',e); });
}

function vtFiltrarDataPendencia(){
  var data = (document.getElementById('vt-fil-data-pend')||{}).value||'';
  if(data){
    // Preencher filtros de data com a data selecionada
    var ini = document.getElementById('vt-fil-ini');
    var fim = document.getElementById('vt-fil-fim');
    if(ini) ini.value = data;
    if(fim) fim.value = data;
  }
  vtCarregar();
}

function vtInicializar(){
  var ini = document.getElementById('vt-fil-ini');
  var fim = document.getElementById('vt-fil-fim');
  var hoje = dataHojeLocal();
  if(ini && !ini.value){ ini.value = hoje; }
  if(fim && !fim.value){ fim.value = hoje; }
  // Sincroniza programação → tratamentos (90 dias) e carrega lista atual
  var syncIni = vtDataMenosDias(hoje, 90);
  vtSincronizarPeriodo(syncIni, hoje, true).then(function(){
    vtCarregarDatasPendentes();
    vtCarregar();
  });
}

function vtCarregar(){
  var ini    = (document.getElementById('vt-fil-ini')||{}).value||'';
  var fim    = (document.getElementById('vt-fil-fim')||{}).value||'';
  var busca  = ((document.getElementById('vt-fil-colab')||{}).value||'').toLowerCase().trim();
  var stFil  = (document.getElementById('vt-fil-status')||{}).value||'';
  var setor  = (document.getElementById('vt-fil-setor')||{}).value||'';
  var wrap   = document.getElementById('vt-lista');
  if(!wrap) return;
  if(!ini||!fim){ progShowToast('⚠ Informe o período.'); return; }
  wrap.innerHTML = '<div style="padding:1rem;color:#888">⏳ Carregando...</div>';
  var filters = ['data_ocorrencia=gte.'+ini,'data_ocorrencia=lte.'+fim];
  sbFetch('verificar_tratamentos',{filters:filters,order:'data_ocorrencia.desc,status.asc',limit:500})
    .then(function(rows){
      _vtDados = rows||[];
      vtCarregarColabsFaltantes(_vtDados, function(){
        vtRenderLista(busca, stFil, setor);
      });
    }).catch(function(e){
      console.error('vtCarregar erro:',e);
      wrap.innerHTML='<div style="padding:1rem;color:#A32D2D">Erro ao carregar tratamentos.</div>';
    });
}

// Busca em _colabHistorico os colaboradores (inclusive dispensados) referenciados
// nos tratamentos que não estão no array ativo. Chama cb ao terminar (sempre).
function vtCarregarColabsFaltantes(rows, cb){
  var faltando = [];
  (rows||[]).forEach(function(t){
    var id = t.colaborador_id;
    if(id && !colaboradores.find(function(c){return String(c.id)===String(id);}) && !(id in _colabHistorico)){
      if(faltando.indexOf(id)<0) faltando.push(id);
    }
  });
  if(!faltando.length || DEMO){ cb(); return; }
  faltando.forEach(function(id){ _colabHistorico[id]=null; }); // marca tentado (evita refetch)
  sbFetch('colaboradores',{filters:['id=in.('+faltando.slice(0,200).join(',')+')'],limit:200})
    .then(function(rows2){
      (rows2||[]).forEach(function(c){ _colabHistorico[c.id]=c; });
      cb();
    }).catch(function(){ cb(); });
}

function vtRenderIndicadores(todos){
  var el = document.getElementById('vt-indicadores');
  if(!el) return;
  if(!todos||!todos.length){ el.style.display='none'; return; }

  // Calcular métricas
  var total      = todos.length;
  var pendente   = todos.filter(function(t){return t.status==='pendente';}).length;
  var andamento  = todos.filter(function(t){return t.status==='em_andamento';}).length;
  var concluido  = todos.filter(function(t){return t.status==='concluido';}).length;

  // Decisões (um registro pode ter múltiplas)
  var ajustado=0, advertencia=0, demissao=0, desconto=0;
  todos.forEach(function(t){
    if(!t.decisoes) return;
    var dec = t.decisoes.split(',');
    dec.forEach(function(d){
      d = d.trim();
      if(d==='ajustado')       ajustado++;
      if(d==='advertencia')    advertencia++;
      if(d==='demissao')       demissao++;
      if(d==='desconto_folha') desconto++;
    });
  });

  function card(valor, label, cor, bg, icon){
    return '<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;'
      +'background:'+bg+';border:1.5px solid '+cor+';border-radius:10px;padding:8px 16px;min-width:80px;flex:1">'
      +'<div style="font-size:22px;font-weight:900;color:'+cor+';line-height:1">'+valor+'</div>'
      +'<div style="font-size:10px;color:'+cor+';font-weight:600;text-align:center;margin-top:2px">'+icon+' '+label+'</div>'
      +'</div>';
  }

  el.style.display='block';
  el.innerHTML =
    // Linha 1 — Status
    '<div style="margin-bottom:6px">'
    +'<div style="font-size:10px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px">Visão Geral do Período</div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
    + card(total,    'Total Verificar', '#8B1A6B','#FDF4FA','🔍')
    + card(pendente, 'Pendentes',       '#C0392B','#FFF5F5','🔴')
    + card(andamento,'Em Andamento',    '#B7770D','#FFFBEE','🟡')
    + card(concluido,'Concluídos',      '#3B6D11','#F4FAF0','🟢')
    +'</div></div>'
    // Linha 2 — Decisões
    +'<div>'
    +'<div style="font-size:10px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px">Decisões Aplicadas</div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
    + card(ajustado,    'Ajustados',       '#185FA5','#EEF6FF','✅')
    + card(advertencia, 'Advertências',    '#854F0B','#FFF8EE','⚠️')
    + card(demissao,    'Demissões',       '#A32D2D','#FFF5F5','❌')
    + card(desconto,    'Descontos Folha', '#534AB7','#F5F4FF','💸')
    +'</div></div>';
}

function vtRenderLista(busca, stFil, setor){
  var wrap = document.getElementById('vt-lista');
  if(!wrap) return;
  // Indicadores calculados sobre TODOS os dados do período (sem filtros)
  vtRenderIndicadores(_vtDados);
  var lista = _vtDados.filter(function(t){
    var col = progFindColab(t.colaborador_id);
    var nome = col?col.nome:'';
    var re   = col?(col.re||''):'';
    if(busca && nome.toLowerCase().indexOf(busca)<0 && String(re).toLowerCase().indexOf(busca)<0) return false;
    if(stFil && t.status!==stFil) return false;
    if(setor){
      var campoResp = 'resp_'+setor;
      if(t[campoResp] && String(t[campoResp]).trim()) return false;
    }
    return true;
  });

  if(!lista.length){
    wrap.innerHTML='<div style="padding:1rem;color:#888">Nenhuma ocorrência encontrada. Use "Gerar da programação" para importar os colaboradores em Verificar.</div>';
    return;
  }

  var html='<div style="padding:.5rem 1rem;font-size:11px;color:#888;margin-bottom:.5rem">'+lista.length+' ocorrência(s)</div>';
  html+='<table style="width:100%;border-collapse:collapse;font-size:12px">';
  html+='<thead><tr style="background:#F9F4FA;color:#555">'
    +'<th style="padding:8px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Data</th>'
    +'<th style="padding:8px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">RE</th>'
    +'<th style="padding:8px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Colaborador</th>'
    +'<th style="padding:8px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Obs. Original</th>'
    +'<th style="padding:8px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Status</th>'
    +'<th style="padding:8px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Decisão</th>'
    +'<th style="padding:8px 10px;text-align:center;border-bottom:.5px solid #e0dfd8"></th>'
    +'</tr></thead><tbody>';

  lista.forEach(function(t,i){
    var col = progFindColab(t.colaborador_id);
    var nome = col?escHtml(col.nome):'<span style="color:#aaa" title="Colaborador não encontrado">('+escHtml(String(t.colaborador_id).substring(0,8))+'…)</span>';
    if(col && (col.dispensado===true || col.ativo===false)){
      nome += ' <span style="background:#FCEBEB;color:#A32D2D;border-radius:3px;padding:0 5px;font-size:9px;font-weight:700;vertical-align:middle" title="'+(col.data_dispensa?'Dispensado em '+fmtD(col.data_dispensa):'Inativo')+(col.motivo_dispensa?' — '+escHtml(col.motivo_dispensa):'')+'">DEMITIDO</span>';
    }
    var re   = col?(col.re||'—'):'—';
    var bg   = i%2===0?'#fff':'#fdf9ff';
    var decisoes = t.decisoes ? t.decisoes.split(',').map(function(d){
      var dec = VT_DECISOES.find(function(x){return x.id===d.trim();});
      return dec?dec.label:d;
    }).join(', ') : '—';
    // Indicadores de pendência por setor
    var pendencias = VT_ETAPAS.filter(function(e){
      return !(t['resp_'+e.id]&&String(t['resp_'+e.id]).trim());
    }).map(function(e){
      return '<span style="background:#FFF3CC;color:#854F0B;border-radius:3px;padding:1px 5px;font-size:10px;margin-right:2px">⭕'+e.label+'</span>';
    }).join('');

    html+='<tr style="background:'+bg+'" id="vt-row-'+t.id+'">'
      +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8">'+fmtD(t.data_ocorrencia)+'</td>'
      +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;font-family:monospace">'+escHtml(re)+'</td>'
      +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;font-weight:500">'+nome+'</td>'
      +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;color:#8B1A6B;max-width:160px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="'+escHtml(t.obs_verificar||'')+'">'+escHtml(t.obs_verificar||'—')+'</td>'
      +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8">'+(VT_STATUS_LABEL[t.status]||t.status)+'</td>'
      +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;font-size:11px">'
      +(t.status!=='concluido'?pendencias:'<span style="color:#3B6D11">'+escHtml(decisoes)+'</span>')
      +'</td>'
      +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;text-align:center">'
      +'<button class="btn btn-pri" style="font-size:11px;padding:3px 10px" data-vtid="'+t.id+'" onclick="vtAbrirTratamento(this.dataset.vtid)">✏️ Tratar</button>'
      +'</td>'
      +'</tr>';
  });

  html+='</tbody></table>';
  wrap.innerHTML = html;
}

function vtGerarLista(){
  var ini  = (document.getElementById('vt-fil-ini')||{}).value||'';
  var fim  = (document.getElementById('vt-fil-fim')||{}).value||'';
  if(!ini||!fim){ progShowToast('⚠ Informe o período De/Até antes de gerar.'); return; }
  var wrap = document.getElementById('vt-lista');
  var label = ini===fim ? fmtD(ini) : fmtD(ini)+' a '+fmtD(fim);
  if(wrap) wrap.innerHTML='<div style="padding:1rem;color:#888">⏳ Importando colaboradores em Verificar de '+label+'...</div>';
  vtSincronizarPeriodo(ini, fim, false).then(function(res){
    if(!res.inseridos && !res.existentes){
      progShowToast('Nenhum colaborador em Verificar no período.');
      if(wrap) wrap.innerHTML='<div style="padding:1rem;color:#888;font-size:12px">Nenhum colaborador em Verificar no período selecionado.</div>';
      return;
    }
    if(res.inseridos===0 && res.existentes){
      progShowToast('ℹ️ '+res.existentes+' ocorrência(s) já importada(s) no período.');
    }
    vtCarregarDatasPendentes();
    vtCarregar();
  }).catch(function(e){
    console.error('vtGerarLista erro:',e);
    progShowToast('⚠ Erro ao gerar lista.','erro');
  });
}


function vtAbrirTratamento(id){
  var t = _vtDados.find(function(x){return x.id===id;});
  if(!t){ vtCarregarETratar(id); return; }
  var col = colaboradores.find(function(c){return String(c.id)===String(t.colaborador_id);});
  var nome = col?col.nome:'Colaborador';
  var re   = col?(col.re||'—'):'—';
  var resp = usuarioLogado?usuarioLogado.nome:'';
  var decisoesArr = t.decisoes?t.decisoes.split(',').map(function(d){return d.trim();}):[]; 
  var gravVal = t.gravidade || 'media';

  var etapasHtml = VT_ETAPAS.map(function(e){
    var campoResp = 'resp_'+e.id;
    var campoPor  = 'resp_'+e.id+'_por';
    var campoEm   = 'resp_'+e.id+'_em';
    var val  = t[campoResp]||'';
    var por  = t[campoPor]||'';
    var em   = t[campoEm]?(' — '+new Date(t[campoEm]).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})):'';
    var temResp = !!val;
    return '<div style="border:.5px solid #e0dfd8;border-radius:8px;padding:12px;margin-bottom:10px;background:'+(temResp?'#f9fff5':'#fff')+'">'
      +'<div style="font-weight:700;font-size:12px;color:'+(temResp?'#3B6D11':'#555')+';margin-bottom:6px">'+(temResp?'✅ ':'⭕ ')+e.label+(por?' <span style="font-weight:400;color:#888">por '+escHtml(por)+em+'</span>':'')+'</div>'
      +'<textarea id="vt-resp-'+e.id+'" style="width:100%;min-height:60px;border:.5px solid #e0dfd8;border-radius:6px;padding:8px;font-size:12px;resize:vertical;box-sizing:border-box" placeholder="Resposta da '+e.label+'...">'
      +escHtml(val)+'</textarea>'
      +'</div>';
  }).join('');

  var decHtml = VT_DECISOES.map(function(d){
    var checked = decisoesArr.indexOf(d.id)>=0 ? 'checked' : '';
    return '<label style="display:flex;align-items:center;gap:6px;cursor:pointer;font-size:13px;padding:6px 10px;border:.5px solid #e0dfd8;border-radius:6px;background:'+(checked?'#f9fff5':'#fff')+'" id="vt-dec-label-'+d.id+'">'
      +'<input type="checkbox" id="vt-dec-'+d.id+'" '+checked+' onchange="vtDecChange()" style="cursor:pointer"> '+d.label+'</label>';
  }).join('');


  var html = '<div style="padding:1rem">'
    +'<div style="display:flex;gap:10px;margin-bottom:1rem;flex-wrap:wrap">'
    +'<div style="flex:1;min-width:200px;background:#F9F4FA;border-radius:8px;padding:10px">'
    +'<div style="font-size:11px;color:#888">Colaborador</div>'
    +'<div style="font-weight:700;font-size:14px">'+escHtml(nome)+'</div>'
    +'<div style="font-size:12px;color:#555;font-family:monospace">RE: '+escHtml(re)+'</div>'
    +'</div>'
    +'<div style="flex:1;min-width:140px;background:#F9F4FA;border-radius:8px;padding:10px">'
    +'<div style="font-size:11px;color:#888">Data da ocorrência</div>'
    +'<div style="font-weight:700;font-size:14px">'+fmtD(t.data_ocorrencia)+'</div>'
    +'</div>'
    +'<div style="flex:2;min-width:200px;background:#FFF5F9;border-radius:8px;padding:10px">'
    +'<div style="font-size:11px;color:#888">Observação original</div>'
    +'<div style="font-size:12px;color:#8B1A6B;font-style:italic">'+escHtml(t.obs_verificar||'Sem observação')+'</div>'
    +'</div>'
    +'</div>'

    +'<div style="margin-bottom:1rem">'
    +'<div style="font-weight:700;font-size:13px;color:#333;margin-bottom:8px;border-bottom:.5px solid #e0dfd8;padding-bottom:4px">📋 Etapas de Resposta</div>'
    +etapasHtml
    +'</div>'

    +'<div style="margin-bottom:1rem">'
    +'<div style="font-weight:700;font-size:13px;color:#333;margin-bottom:8px;border-bottom:.5px solid #e0dfd8;padding-bottom:4px">📊 Gravidade da ocorrência</div>'
    +'<select id="vt-gravidade" class="inp" style="width:220px;font-size:12px">'
    +'<option value="baixa"'+(gravVal==='baixa'?' selected':'')+'>Baixa</option>'
    +'<option value="media"'+(gravVal==='media'?' selected':'')+'>Média</option>'
    +'<option value="alta"'+(gravVal==='alta'?' selected':'')+'>Alta</option>'
    +'</select>'
    +'<div style="font-size:11px;color:#888;margin-top:4px">Impacta a nota de Conduta na avaliação IEC (advertência, desconto em folha, etc.).</div>'
    +'</div>'

    +'<div style="margin-bottom:1rem">'
    +'<div style="font-weight:700;font-size:13px;color:#333;margin-bottom:8px;border-bottom:.5px solid #e0dfd8;padding-bottom:4px">⚖️ Decisão Final <span style="font-size:11px;font-weight:400;color:#888">(pode selecionar mais de uma)</span></div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">'
    +decHtml
    +'</div>'
    +'<textarea id="vt-decisao-obs" style="width:100%;min-height:50px;border:.5px solid #e0dfd8;border-radius:6px;padding:8px;font-size:12px;resize:vertical;box-sizing:border-box" placeholder="Observação sobre a decisão...">'
    +escHtml(t.decisao_obs||'')+'</textarea>'
    +'</div>'

    +'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px;padding-top:10px;border-top:.5px solid #e0dfd8">'
    +'<div style="font-size:11px;color:#888;flex:1">Status definido automaticamente ao salvar.</div>'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" style="background:#3B6D11;border-color:#3B6D11;padding:8px 20px;font-size:13px" data-vtid="'+id+'" data-vtresp="'+resp+'" onclick="vtSalvarTratamento(this.dataset.vtid,this.dataset.vtresp)">💾 Salvar Tratamento</button>'
    +(  (function(){ var pf=usuarioLogado&&usuarioLogado.perfil; return (pf==='rh'||pf==='dp'||pf==='admin'||pf==='gestor'||pf==='diretoria'||(typeof perfilAcessoTotal==='function'&&perfilAcessoTotal())); })()?'<button class="btn" style="background:#7B1FA2;border-color:#7B1FA2;color:#fff;padding:8px 20px;font-size:13px" data-vtid="'+id+'" data-vtresp="'+resp+'" onclick="vtEncerrarTratamento(this.dataset.vtid,this.dataset.vtresp)">🔒 Encerrar (RH)</button>':''  )
    +'</div>';

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:700px;width:95vw;margin:auto">'
    +'<div class="mh" style="display:flex;justify-content:space-between;align-items:center">'
    +'<span style="font-weight:700;font-size:15px">✏️ Tratamento de Verificar</span>'
    +'<button class="btn" onclick="closeModal()" style="padding:2px 10px;font-size:18px;line-height:1">×</button>'
    +'</div>'
    + html
    +'</div></div>');
}

function vtEncerrarTratamento(id, resp){
  var t = _vtDados.find(function(x){return x.id===id;});
  if(!t) return;
  // RH pode encerrar mesmo que status ja seja concluido (ex: correcao)
  var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:380px">'
    +'<div style="font-size:15px;font-weight:700;color:#7B1FA2;margin-bottom:.5rem">🔒 Encerrar Tratamento</div>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.85rem">Marca como <b>Concluido</b>. Apenas RH pode encerrar.</div>'
    +'<div class="fg" style="margin-bottom:.85rem">'
    +'<label style="font-size:11px;font-weight:500">Observacao de encerramento (opcional)</label>'
    +'<textarea id="vt-enc-obs" class="inp" style="width:100%;min-height:60px;resize:vertical" placeholder="Motivo ou observacao final..."></textarea>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn" id="vt-enc-conf" style="background:#7B1FA2;border-color:#7B1FA2;color:#fff;flex:2">🔒 Confirmar Encerramento</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var btn=document.getElementById('vt-enc-conf');
    if(!btn) return;
    btn.onclick=function(){
      var obs=(document.getElementById('vt-enc-obs')||{}).value||'';
      var payload={status:'concluido',encerrado_por:resp,encerrado_em:new Date().toISOString(),alterado_em:new Date().toISOString()};
      if(obs) payload.decisao_obs=obs;
      closeModal();
      if(DEMO){ progShowToast('DEMO nao salvou.'); return; }
      sbUpdate('verificar_tratamentos',payload,'id=eq.'+id)
        .then(function(){
          Object.assign(t,payload);
          progShowToast('🔒 Tratamento encerrado pelo RH.');
          vtAtualizarAbaAlerta();
          vtCarregarDatasPendentes();
          var busca=((document.getElementById('vt-fil-colab')||{}).value||'').toLowerCase().trim();
          var stFil=(document.getElementById('vt-fil-status')||{}).value||'';
          var setor=(document.getElementById('vt-fil-setor')||{}).value||'';
          vtRenderLista(busca,stFil,setor);
        }).catch(function(e){ console.error(e); progShowToast('Erro ao encerrar.','erro'); });
    };
  },50);
}

function vtDecChange(){
  VT_DECISOES.forEach(function(d){
    var cb  = document.getElementById('vt-dec-'+d.id);
    var lbl = document.getElementById('vt-dec-label-'+d.id);
    if(cb && lbl) lbl.style.background = cb.checked ? '#f9fff5' : '#fff';
  });
}

function vtSalvarTratamento(id, resp){
  var t = _vtDados.find(function(x){return x.id===id;});
  if(!t) return;
  var payload = {};
  VT_ETAPAS.forEach(function(e){
    var ta = document.getElementById('vt-resp-'+e.id);
    var val = ta?ta.value.trim():'';
    payload['resp_'+e.id] = val;
    if(val && val !== (t['resp_'+e.id]||'')){
      payload['resp_'+e.id+'_por'] = resp;
      payload['resp_'+e.id+'_em']  = new Date().toISOString();
    } else {
      payload['resp_'+e.id+'_por'] = t['resp_'+e.id+'_por']||'';
      payload['resp_'+e.id+'_em']  = t['resp_'+e.id+'_em']||null;
    }
  });
  var decisoes = VT_DECISOES.filter(function(d){
    var cb = document.getElementById('vt-dec-'+d.id);
    return cb && cb.checked;
  }).map(function(d){return d.id;}).join(',');
  payload.decisoes    = decisoes;
  payload.decisao_obs = (document.getElementById('vt-decisao-obs')||{}).value||'';
  payload.gravidade   = (document.getElementById('vt-gravidade')||{}).value || 'media';
  payload.alterado_em = new Date().toISOString();

  // Status: checkboxes e respostas avancam para em_andamento apenas
  // Somente RH pode definir concluido via vtEncerrarTratamento
  var temDecisao  = decisoes.length > 0;
  var temResposta = VT_ETAPAS.some(function(e){ return !!(payload['resp_'+e.id]); });
  if(t.status === 'concluido'){
    payload.status = 'concluido'; // nao regride status ja encerrado pelo RH
  } else {
    payload.status = (temDecisao || temResposta) ? 'em_andamento' : 'pendente';
  }

  if(DEMO){ progShowToast('DEMO — não salvou.'); closeModal(); return; }
  sbUpdate('verificar_tratamentos', payload, 'id=eq.'+id)
    .then(function(){
      Object.assign(t, payload);
      progShowToast('✅ Tratamento salvo.');
      vtAtualizarAbaAlerta();
      vtCarregarDatasPendentes(); // Atualiza datas com pendência
      closeModal();
      var ini = (document.getElementById('vt-fil-ini')||{}).value||'';
      var fim = (document.getElementById('vt-fil-fim')||{}).value||'';
      var busca = ((document.getElementById('vt-fil-colab')||{}).value||'').toLowerCase().trim();
      var stFil = (document.getElementById('vt-fil-status')||{}).value||'';
      var setor = (document.getElementById('vt-fil-setor')||{}).value||'';
      vtRenderLista(busca, stFil, setor);
    }).catch(function(e){
      console.error('vtSalvarTratamento erro:',e);
      progShowToast('⚠ Erro ao salvar tratamento.','erro');
    });
}

function vtCarregarETratar(id){
  sbFetch('verificar_tratamentos',{filters:['id=eq.'+id],limit:1}).then(function(rows){
    if(rows&&rows.length){ _vtDados.push(rows[0]); vtAbrirTratamento(id); }
  });
}

// Atualiza o estado de piscar da aba com base nos tratamentos pendentes/em andamento
function vtAtualizarAbaAlerta(){
  var btn = document.getElementById('tab-prog-verificar');
  if(!btn) return;
  // Buscar contagem do banco (status pendente ou em_andamento)
  if(DEMO) return;
  sbFetch('verificar_tratamentos',{
    filters:['status=in.(pendente,em_andamento)'],
    select:'id,status',
    limit:500
  }).then(function(rows){
    btn.classList.remove('vt-alerta-vermelho','vt-alerta-amarelo');
    if(!rows||!rows.length) return;
    var temPendente    = rows.some(function(r){return r.status==='pendente';});
    var temAndamento   = rows.some(function(r){return r.status==='em_andamento';});
    // Vermelho tem prioridade (pendente não tratado)
    if(temPendente){
      btn.classList.add('vt-alerta-vermelho');
    } else if(temAndamento){
      btn.classList.add('vt-alerta-amarelo');
    }
  }).catch(function(){});
}

// Helper: nome abreviado até max caracteres (preserva palavras completas)
function nomeAbrev(nome, max){
  max = max||40;
  if(!nome) return '';
  if(nome.length <= max) return nome;
  var palavras = nome.trim().split(/\s+/);
  var result = '';
  for(var i=0; i<palavras.length; i++){
    var test = result ? result+' '+palavras[i] : palavras[i];
    if(test.length > max) break;
    result = test;
  }
  return result || nome.slice(0, max);
}

