// MÓDULO: CADASTRO DE ESCALAS
// ══════════════════════════════════════════════════════════════════
function escalasCadAbrir(){
  escalasCadRender();
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:600px;width:95vw">'
    +'<div class="mh" style="display:flex;justify-content:space-between;align-items:center">'
    +'<span style="font-weight:700;font-size:15px">⏰ Cadastro de Escalas</span>'
    +'<button class="btn" onclick="closeModal()" style="padding:2px 10px;font-size:18px;line-height:1">×</button>'
    +'</div>'
    +'<div style="padding:1rem">'
    // Formulário nova escala
    +'<div style="background:#F9F4FA;border-radius:8px;padding:12px;margin-bottom:1rem">'
    +'<div style="font-weight:700;font-size:12px;color:#555;margin-bottom:8px">+ Nova Escala</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end">'
    +'<div><div style="font-size:11px;color:#888;margin-bottom:3px">Tipo</div>'
    +'<input class="inp" id="esc-novo-tipo" placeholder="Ex: Matutino, Vespertino..." style="width:160px"/></div>'
    +'<div><div style="font-size:11px;color:#888;margin-bottom:3px">Início</div>'
    +'<input class="inp" id="esc-novo-ini" type="time" style="width:100px"/></div>'
    +'<div><div style="font-size:11px;color:#888;margin-bottom:3px">Fim</div>'
    +'<input class="inp" id="esc-novo-fim" type="time" style="width:100px"/></div>'
    +'<button class="btn btn-pri" onclick="escalasCadSalvar()">+ Adicionar</button>'
    +'</div></div>'
    // Lista
    +'<div id="escala-cad-lista"></div>'
    +'</div></div></div>');
  setTimeout(escalasCadRenderLista, 50);
}

function escalasCadRenderLista(){
  var el = document.getElementById('escala-cad-lista');
  if(!el) return;
  if(!escalas_cad.length){
    el.innerHTML='<div style="color:#888;font-size:12px;padding:.5rem">Nenhuma escala cadastrada.</div>';
    return;
  }
  el.innerHTML = '<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#F9F4FA">'
    +'<th style="padding:7px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Tipo</th>'
    +'<th style="padding:7px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Início</th>'
    +'<th style="padding:7px 10px;text-align:left;border-bottom:.5px solid #e0dfd8">Fim</th>'
    +'<th style="padding:7px 10px;text-align:center;border-bottom:.5px solid #e0dfd8"></th>'
    +'</tr></thead><tbody>'
    + escalas_cad.map(function(e,i){
      var bg = i%2===0?'#fff':'#fdf9ff';
      return '<tr style="background:'+bg+'">'
        +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;font-weight:600">'+escHtml(e.tipo)+'</td>'
        +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;font-family:monospace">'+escHtml(e.inicio||'—')+'</td>'
        +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;font-family:monospace">'+escHtml(e.fim||'—')+'</td>'
        +'<td style="padding:7px 10px;border-bottom:.5px solid #f0efe8;text-align:center">'
        +'<button class="btn" style="color:#A32D2D;border-color:#A32D2D;font-size:11px;padding:2px 8px" data-escid="'+e.id+'" onclick="escalasCadExcluir(this.dataset.escid)">Excluir</button>'
        +'</td></tr>';
    }).join('')
    +'</tbody></table>';
}

function escalasCadRender(){ /* chamado pelo setModal */ }

function escalasCadSalvar(){
  var tipo = (document.getElementById('esc-novo-tipo')||{}).value.trim();
  var ini  = (document.getElementById('esc-novo-ini')||{}).value||'';
  var fim  = (document.getElementById('esc-novo-fim')||{}).value||'';
  if(!tipo||!ini||!fim){ progShowToast('⚠ Preencha todos os campos.'); return; }
  if(DEMO){ progShowToast('DEMO'); return; }
  sbInsert('escalas',{tipo:tipo,inicio:ini,fim:fim}).then(function(res){
    if(res&&res[0]){ escalas_cad.push(res[0]); }
    else { escalas_cad.push({id:'loc'+Date.now(),tipo:tipo,inicio:ini,fim:fim}); }
    // Limpar campos
    var t=document.getElementById('esc-novo-tipo');
    var i=document.getElementById('esc-novo-ini');
    var f=document.getElementById('esc-novo-fim');
    if(t)t.value=''; if(i)i.value=''; if(f)f.value='';
    escalasCadRenderLista();
    progShowToast('✅ Escala "'+tipo+'" cadastrada.');
  }).catch(function(e){ console.error(e); progShowToast('⚠ Erro ao salvar.','erro'); });
}

function escalasCadExcluir(id){
  if(!confirm('Excluir esta escala?')) return;
  if(!DEMO) sbDelete('escalas','id=eq.'+id);
  escalas_cad = escalas_cad.filter(function(e){return e.id!==id;});
  // Remover de colaboradores vinculados
  colaboradores.forEach(function(c){ if(c.escala_id===id){ c.escala_id=null; if(!DEMO) sbUpdate('colaboradores',{escala_id:null},'id=eq.'+c.id); } });
  escalasCadRenderLista();
}

// Helper: retorna objeto da escala pelo id
function getEscala(id){ return escalas_cad.find(function(e){return e.id===id;})||null; }
function getEscalaLabel(id){
  var e = getEscala(id);
  return e ? e.tipo+' '+e.inicio+'-'+e.fim : '';
}

// ── Relatório: Colaboradores em Verificar ──────────────────────────────────
function relTmaVerificar(){
  var ini   = (document.getElementById('tma-vf-ini')||{}).value||'';
  var fim   = (document.getElementById('tma-vf-fim')||{}).value||'';
  var busca = ((document.getElementById('tma-vf-colab')||{}).value||'').toLowerCase().trim();
  var wrap  = document.getElementById('tma-vf-resultado');
  if(!wrap) return;
  if(!ini||!fim){ progShowToast('⚠ Informe o período.');return; }

  wrap.innerHTML = '<div style="padding:1rem;color:#888">⏳ Carregando...</div>';

  var filters = [
    'status=eq.verificar',
    'data=gte.'+ini,
    'data=lte.'+fim
  ];

  sbFetch('prog_status_diario',{filters:filters,order:'data.asc'}).then(function(rows){
    if(!rows||!rows.length){
      wrap.innerHTML='<div style="padding:1rem;color:#888">Nenhum colaborador em Verificar no período.</div>';
      document.getElementById('btn-vf-pdf').style.display='none';
      document.getElementById('btn-vf-excel').style.display='none';
      return;
    }

    // Montar lista com dados dos colaboradores
    var registros = rows.map(function(r){
      var col = colaboradores.find(function(c){return String(c.id)===String(r.colaborador_id);});
      return {
        data: r.data,
        nome: col?col.nome:'(ID: '+r.colaborador_id+')',
        re:   col?(col.re||'—'):'—',
        obs:  r.obs||''
      };
    }).filter(function(r){
      if(!busca) return true;
      return r.nome.toLowerCase().indexOf(busca)>=0 || String(r.re).toLowerCase().indexOf(busca)>=0;
    });

    if(!registros.length){
      wrap.innerHTML='<div style="padding:1rem;color:#888">Nenhum resultado para o filtro informado.</div>';
      return;
    }

    // Agrupar por data
    var porData = {};
    registros.forEach(function(r){
      if(!porData[r.data]) porData[r.data]=[];
      porData[r.data].push(r);
    });

    // Ordenar datas e dentro de cada data ordenar por nome
    var datas = Object.keys(porData).sort();
    datas.forEach(function(d){
      porData[d].sort(function(a,b){return a.nome.localeCompare(b.nome,'pt-BR');});
    });

    // Total
    var total = registros.length;

    // Renderizar
    var html = '<div style="padding:1rem">';
    html += '<div style="font-size:12px;color:#888;margin-bottom:1rem">'+total+' ocorrência(s) no período — '+fmtD(ini)+' a '+fmtD(fim)+'</div>';

    datas.forEach(function(d){
      var lista = porData[d];
      var dLabel = fmtD(d);
      html += '<div style="margin-bottom:1.25rem">';
      html += '<div style="font-weight:700;font-size:13px;color:#8B1A6B;border-bottom:2px solid #8B1A6B22;padding-bottom:4px;margin-bottom:8px">📅 '+dLabel+'</div>';
      html += '<table style="width:100%;border-collapse:collapse;font-size:12px">';
      html += '<thead><tr style="background:#F9F4FA;color:#555">'
           +'<th style="text-align:left;padding:6px 10px;border-bottom:.5px solid #e0dfd8">Nome</th>'
           +'<th style="text-align:left;padding:6px 10px;border-bottom:.5px solid #e0dfd8;width:70px">RE</th>'
           +'<th style="text-align:left;padding:6px 10px;border-bottom:.5px solid #e0dfd8">Observação</th>'
           +'</tr></thead><tbody>';
      lista.forEach(function(r,i){
        var bg = i%2===0?'#fff':'#fdf9ff';
        html += '<tr style="background:'+bg+'">'
             +'<td style="padding:6px 10px;border-bottom:.5px solid #f0efe8;font-weight:500">'+escHtml(r.nome)+'</td>'
             +'<td style="padding:6px 10px;border-bottom:.5px solid #f0efe8;font-family:monospace">'+escHtml(r.re)+'</td>'
             +'<td style="padding:6px 10px;border-bottom:.5px solid #f0efe8;color:'+(r.obs?'#8B1A6B':'#aaa')+';font-style:'+(r.obs?'normal':'italic')+'">'+escHtml(r.obs||'Sem observação')+'</td>'
             +'</tr>';
      });
      html += '</tbody></table></div>';
    });

    html += '</div>';
    wrap.innerHTML = html;
    document.getElementById('btn-vf-pdf').style.display='inline-flex';
    document.getElementById('btn-vf-excel').style.display='inline-flex';
    // Guardar dados para exportação
    window._tmaVfDados = {datas:datas, porData:porData, ini:ini, fim:fim, total:total};
  }).catch(function(e){
    console.error('relTmaVerificar erro:',e);
    wrap.innerHTML='<div style="padding:1rem;color:#A32D2D">Erro ao carregar dados.</div>';
  });
}

function relTmaVerificarPDF(){
  if(!window._tmaVfDados) return;
  var d=window._tmaVfDados;
  var linhas=[];
  d.datas.forEach(function(dt){
    linhas.push(['','','📅 '+fmtD(dt),'','']);
    d.porData[dt].forEach(function(r){
      linhas.push([fmtD(dt),r.re,r.nome,r.obs||'—']);
    });
  });
  var html='<html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;font-size:11px}'
    +'table{width:100%;border-collapse:collapse}th,td{padding:5px 8px;border:.5px solid #ccc;text-align:left}'
    +'th{background:#F9F4FA;font-weight:700}h2{color:#8B1A6B}</style></head><body>'
    +'<h2>🔍 Relatório de Verificar — '+fmtD(d.ini)+' a '+fmtD(d.fim)+'</h2>'
    +'<p style="color:#888;font-size:11px">Total: '+d.total+' ocorrência(s)</p>'
    +'<table><thead><tr><th>Data</th><th>RE</th><th>Colaborador</th><th>Observação</th></tr></thead><tbody>';
  d.datas.forEach(function(dt){
    d.porData[dt].forEach(function(r){
      html+='<tr><td>'+fmtD(dt)+'</td><td>'+escHtml(r.re)+'</td><td>'+escHtml(r.nome)+'</td><td>'+escHtml(r.obs||'—')+'</td></tr>';
    });
  });
  html+='</tbody></table></body></html>';
  var w=window.open('','_blank');
  if(w){w.document.write(html);w.document.close();setTimeout(function(){w.print();},400);}
}

function relTmaVerificarExcel(){
  if(!window._tmaVfDados) return;
  var d=window._tmaVfDados;
  var linhas=['Data,RE,Nome,Observacao'];
  d.datas.forEach(function(dt){
    d.porData[dt].forEach(function(r){
      linhas.push([fmtD(dt),r.re,r.nome,(r.obs||'')].map(function(v){return '"'+String(v).replace(/"/g,'""')+'"';}).join(','));
    });
  });
  var a=document.createElement('a');
  a.href='data:text/csv;charset=utf-8,%EF%BB%BF'+encodeURIComponent(linhas.join('%0D%0A'));
  a.download='verificar_'+d.ini+'_'+d.fim+'.csv';
  a.click();
}
function relTmaNaoEscalados(){
  var TMA_CID='04277076-baa5-4ea4-85dc-bddf55541e68';
  var data=(document.getElementById('tma-ne-data')||{}).value||dataHojeLocal();
  var wrap=document.getElementById('tma-ne-resultado');
  wrap.innerHTML='<div style="padding:1rem;color:#888;font-size:12px">⏳ Calculando...</div>';
  sbFetch('composicao_dia',{filters:['data=eq.'+data]}).then(function(comps){
    var escIds={};
    (comps||[]).forEach(function(c){parseColabIds(c.colaborador_ids).forEach(function(id){if(id)escIds[id]=true;});});
    var corDia=(_calDados&&_calDados[data])||CAL_CORES_2026[data]||'';
    return sbFetch('prog_status_diario',{filters:['data=eq.'+data,'deleted_at=is.null']}).then(function(stRows){
      var stMap={};(stRows||[]).forEach(function(r){stMap[r.colaborador_id]=r.status;});
      var corBgs={verde:'#92D050',azul:'#00B0F0',amarelo:'#FFD700'};
      var naoEsc=colaboradores.filter(function(c){
        if(c.ativo===false||c.contrato_id!==TMA_CID) return false;
        if(escIds[c.id]) return false;
        var st=stMap[c.id]||_progStatus[c.id]||'disponivel';
        if(st!=='disponivel') return false;
        if(corDia&&c.cor_escala&&c.cor_escala===corDia) return false;
        return true;
      }).sort(function(a,b){return(a.nome||'').localeCompare(b.nome||'','pt-BR');});
      wrap.innerHTML='<div style="overflow-x:auto"><table class="tbl" style="font-size:12px">'
        +'<thead><tr><th>RE</th><th>Nome Completo</th><th>Equipe Vinculada</th><th>CNH</th><th>Cor Escala</th></tr></thead>'
        +'<tbody>'+naoEsc.map(function(c){
          var eq=(equipes_disp||[]).find(function(e){return e.id===c.equipe_id;});
          var corBg=c.cor_escala?corBgs[c.cor_escala]:'';
          var corCell=corBg?'<span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:'+corBg+';vertical-align:middle;margin-right:4px"></span>'+(c.cor_escala||''):'\u2014';
          return '<tr><td>'+String(c.re||'')+'</td><td style="font-weight:500">'+String(c.nome||'')+'</td>'
            +'<td>'+String(eq?eq.codigo:'\u2014')+'</td><td style="text-align:center">'+String(c.cnh_categoria||'\u2014')+'</td>'
            +'<td>'+corCell+'</td></tr>';
        }).join('')+'</tbody></table></div>'
        +'<div style="padding:.5rem 1rem;font-size:12px;color:#888">Total: <b>'+naoEsc.length+'</b> não escalados</div>';
      wrap._dados=naoEsc;
      document.getElementById('btn-ne-pdf').style.display='';
      document.getElementById('btn-ne-excel').style.display='';
    });
  });
}
