// ── Relatório: Por Status ──────────────────────────────────
function relTmaStatus(){
  var TMA_CID='04277076-baa5-4ea4-85dc-bddf55541e68';
  var data=(document.getElementById('tma-st-data')||{}).value||dataHojeLocal();
  var flags=Array.from(document.querySelectorAll('#tma-st-flags input:checked')).map(function(i){return i.value;});
  if(!flags.length){progShowToast('\u26a0 Selecione ao menos um status.');return;}
  var wrap=document.getElementById('tma-st-resultado');
  wrap.innerHTML='<div style="padding:1rem;color:#888;font-size:12px">\u23f3 Calculando...</div>';
  Promise.all([
    sbFetch('composicao_dia',{filters:['data=eq.'+data]}),
    sbFetch('prog_status_diario',{filters:['data=eq.'+data,'deleted_at=is.null']}),
    sbFetch('prog_status_diario',{filters:progFiltrosStatusPersistentes(data),order:'data.desc',limit:200})
  ]).then(function(res){
    var comps=res[0]||[];var stRows=res[1]||[];var persistRows=res[2]||[];
    var escIds={};
    comps.forEach(function(c){parseColabIds(c.colaborador_ids).forEach(function(id){if(id)escIds[id]=true;});});
    var stMap={};
    stRows.forEach(function(r){stMap[r.colaborador_id]=r.status;});
    // Apply persistent ferias/afastado spanning today
    persistRows.forEach(function(r){
      if(!stMap[r.colaborador_id]||stMap[r.colaborador_id]==='disponivel'){
        stMap[r.colaborador_id]=r.status;
      }
    });
    Object.keys(_progStatus||{}).forEach(function(id){if(!stMap[id])stMap[id]=_progStatus[id];});
    var corDia=(_calDados&&_calDados[data])||CAL_CORES_2026[data]||'';
    var ST_LABEL={escalado:'Escalado',faltou:'Faltou',folga:'Folga',ferias:'Férias',afastado:'Afastado',treinamento:'Treinamento',inapto:'Inapto'};
    var ST_COR={escalado:'#3B6D11',faltou:'#A32D2D',folga:'#854F0B',ferias:'#185FA5',afastado:'#A32D2D',treinamento:'#533AB7',inapto:'#7B2D00'};
    function getStColab(c){
      var stBanco=stMap[c.id]||'disponivel';
      if(flags.indexOf('escalado')>=0&&escIds[c.id]) return 'escalado';
      if(flags.indexOf(stBanco)>=0&&stBanco!=='disponivel') return stBanco;
      if(flags.indexOf('folga')>=0&&stBanco==='disponivel'&&corDia&&c.cor_escala&&c.cor_escala===corDia) return 'folga';
      return null;
    }
    var resultado=[];
    colaboradores.filter(function(c){return c.ativo!==false&&c.contrato_id===TMA_CID;}).forEach(function(c){
      var s=getStColab(c);if(s)resultado.push({c:c,status:s});
    });
    resultado.sort(function(a,b){
      if(a.status!==b.status)return a.status.localeCompare(b.status);
      return(a.c.nome||'').localeCompare(b.c.nome||'','pt-BR');
    });
    var corBgs={verde:'#92D050',azul:'#00B0F0',amarelo:'#FFD700'};
    wrap.innerHTML='<div style="overflow-x:auto"><table class="tbl" style="font-size:12px">'
      +'<thead><tr><th>RE</th><th>Nome</th><th>Equipe</th><th>CNH</th><th>Cor</th><th>Status</th></tr></thead><tbody>'
      +resultado.map(function(r){
        var c=r.c;var eq=(equipes_disp||[]).find(function(e){return e.id===c.equipe_id;});
        var corBg=c.cor_escala?corBgs[c.cor_escala]:'';
        var cor=corBg?'<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:'+corBg+';vertical-align:middle"></span>':'\u2014';
        return '<tr><td>'+String(c.re||'')+'</td><td style="font-weight:500">'+String(c.nome||'')+'</td>'
          +'<td>'+String(eq?eq.codigo:'\u2014')+'</td><td style="text-align:center">'+String(c.cnh_categoria||'\u2014')+'</td>'
          +'<td style="text-align:center">'+cor+'</td>'
          +'<td><span style="color:'+ST_COR[r.status]+';font-weight:600;font-size:11px">'+ST_LABEL[r.status]+'</span></td></tr>';
      }).join('')+'</tbody></table></div>'
      +'<div style="padding:.5rem 1rem;font-size:12px;color:#888">Total: <b>'+resultado.length+'</b> colaboradores</div>';
    wrap._dados=resultado;document.getElementById('btn-st-excel').style.display='';
  });
}
