    'causas-codx':'<div class="card"><div class="ch"><span class="ct">⚠️ Causas COD X</span><button class="btn btn-pri" onclick="openNovaCausaCodX()">+ Nova causa</button></div><div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Causa</th><th>Ativa</th><th></th></tr></thead><tbody id="tbody-causas-codx-vis"></tbody></table></div></div>',
    'checklists':'<div class="card"><div class="ch"><span class="ct">📋 Checklists de Campo</span><button class="btn btn-pri" onclick="openNovoChecklist()">+ Novo checklist</button></div><div style="padding:.75rem 0"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:1rem"><button class="btn btn-sm" onclick="filtrarChecklistsCad(\'EPI\')">🦺 EPI</button><button class="btn btn-sm" onclick="filtrarChecklistsCad(\'Veicular\')">🚗 Veicular</button><button class="btn btn-sm" onclick="filtrarChecklistsCad(\'APR\')">⚠️ APR</button><button class="btn btn-sm" onclick="abrirPreviewAPREquatorial()" style="background:#185FA5;color:#fff;border-color:#185FA5">⚡ APR Equatorial</button><button class="btn btn-sm" onclick="filtrarChecklistsCad(\'\')" style="background:#1a1a18;color:#fff">Todos</button></div><div id="lista-checklists-cad"></div></div></div>',
