    'unidades-medida':'<div class="card"><div class="ch"><span class="ct">📐 Unidades de Medida</span><button class="btn btn-pri" onclick="openNovaUnidade()">+ Nova unidade</button></div><div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Sigla</th><th>Nome</th><th>Descrição</th><th>Status</th><th></th></tr></thead><tbody id="tbody-unidades-vis"></tbody></table></div></div>',
    'materiais-cat':'<div class="card"><div class="ch"><span class="ct">📦 Catálogo de Materiais</span><div style="display:flex;gap:6px"><select class="inp" id="mat-fil-cont" style="width:200px" onchange="renderMateriaisVis()"><option value="">Todos os contratos</option></select><input class="inp" id="mat-fil-busca" placeholder="Buscar por nome ou código SAP..." style="width:220px" oninput="renderMateriaisVis()"/><button class="btn btn-pri" onclick="openNovoMaterial()">+ Novo material</button></div></div><div style="overflow-x:auto"><table class="tbl tbl-responsive"><thead><tr><th>Código SAP</th><th>Descrição</th><th>Categoria</th><th>Unidade</th><th>Contratos</th><th>Status</th><th></th></tr></thead><tbody id="tbody-materiais-vis"></tbody></table></div></div>',
    permissoes:'<div class="card"><div class="ch"><span class="ct">🔐 Permissões de Acesso</span>'
