/** Cadastro-mestre mínimo (exceção). Preferir Contratação para admissão. */
function openNovoColaboradorRapido(){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin:0 0 10px">Cadastro rápido × Contratação</h3>'
    +'<div style="font-size:13px;line-height:1.55;color:#444;margin-bottom:12px">'
    +'O cadastro rápido grava só o básico em <b>colaboradores</b> (nome, RE, cargo, contrato…). '
    +'<b>Não</b> gera o processo de Contratação (questionário, kit de documentos, remuneração, conferência).'
    +'<br><br>Usar os dois caminhos para a <b>mesma pessoa</b> pode criar <b>duplicidade</b> ou deixar a admissão incompleta.'
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:8px">'
    +'<button class="btn btn-pri" id="nc-ir-ct">Ir para Contratação / Admissão (recomendado)</button>'
    +'<button class="btn" id="nc-seguir-rapido">Continuar cadastro rápido (exceção)</button>'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var a=document.getElementById('nc-ir-ct');
    var b=document.getElementById('nc-seguir-rapido');
    if(a) a.onclick=function(){ closeModal(); rhAbrirContratacaoDeCadastros(); };
    if(b) b.onclick=function(){ closeModal(); openNovoColaborador(); };
  }, 40);
}

function colabEhPj(c){
  if(!c) return false;
  if(c.eh_pj===true || c.eh_pj===1 || c.eh_pj==='true' || c.eh_pj==='t') return true;
  var t=String(c.tipo_pessoa||c.tipo||'').toUpperCase();
  return t==='PJ'||t==='JURIDICA'||t==='JURÍDICA';
}
function colabNormCnpj(v){
  var d=String(v==null?'':v).replace(/\D/g,'');
  return d.length===14?d:'';
}
function ncTogglePjUI(){
  var on=!!(document.getElementById('nc-eh-pj')||{}).checked;
  var box=document.getElementById('nc-pj-campos');
  if(box) box.style.display=on?'':'none';
  var labNome=document.getElementById('nc-lab-nome');
  if(labNome) labNome.textContent=on?'Nome fantasia / responsável *':'Nome completo *';
  var labBro=document.getElementById('nc-lab-bro');
  if(labBro) labBro.textContent=on?'CPF do responsável (opcional)':'BRO / CPF';
}

