var _permissoes = {}; // { usuario_id: { modulo_id: true/false } }
var _permCarregado = false;

async function permCarregar(){
  if(DEMO){ _permCarregado=true; return; }
  var rows = await sbFetch('user_permissoes', {}) || [];
  _permissoes = {};
  rows.forEach(function(r){
    if(!_permissoes[r.usuario_id]) _permissoes[r.usuario_id]={};
    _permissoes[r.usuario_id][r.modulo] = r.ativo !== false;
  });
  _permCarregado = true;
}

function permTemAcesso(moduloId){
  if(!usuarioLogado) return false;
  if(usuarioLogado.perfil==='admin' || (typeof perfilAcessoTotal==='function' && perfilAcessoTotal())) return true;
  if((typeof perfilEhSupervisor==='function' ? perfilEhSupervisor() : false) && (moduloId==='cadastros'||moduloId==='relatorios')) return true;
  if(!_permCarregado) return true; // enquanto carrega, libera
  var perms = _permissoes[usuarioLogado.id];
  if(!perms) return true; // sem restrição configurada: libera
  return perms[moduloId] !== false; // se explicitamente false, bloqueia
}

function permRenderTabela(){
  var wrap = document.getElementById('perm-tabela-wrap'); if(!wrap) return;
  var busca = ((document.getElementById('perm-busca-usr')||{}).value||'').toLowerCase();
  var filPerfil = (document.getElementById('perm-fil-perfil')||{}).value||'';

  var usrs = usuarios_lista.filter(function(u){
    if(u.perfil==='admin' || u.perfil==='diretoria') return false;
    if(filPerfil && u.perfil!==filPerfil) return false;
    if(busca && !u.nome.toLowerCase().includes(busca) && !(u.email||'').toLowerCase().includes(busca)) return false;
    return true;
  });

  if(!usrs.length){
    wrap.innerHTML='<div style="color:#aaa;text-align:center;padding:2rem">Nenhum usuário encontrado.</div>';
    return;
  }

  // Agrupar módulos por grupo
  var grupos={};
  PERM_MODULOS.forEach(function(m){
    if(!grupos[m.grupo]) grupos[m.grupo]=[];
    grupos[m.grupo].push(m);
  });

  var gruposOrdem=['Principal','Operacional','Gestão','RH','Admin'];

  var thead='<thead><tr>'
    +'<th style="min-width:160px;position:sticky;left:0;background:#f9f9f7;z-index:2">Usuário</th>'
    +'<th style="min-width:80px;position:sticky;left:160px;background:#f9f9f7;z-index:2">Perfil</th>';

  gruposOrdem.forEach(function(grp){
    var mods=grupos[grp]||[];
    if(!mods.length) return;
    thead+='<th colspan="'+mods.length+'" style="text-align:center;background:#1a1a18;color:#fff;font-size:10px;padding:4px 8px">'+grp+'</th>';
  });
  thead+='</tr><tr>'
    +'<th style="position:sticky;left:0;background:#f9f9f7;z-index:2"></th>'
    +'<th style="position:sticky;left:160px;background:#f9f9f7;z-index:2"></th>';

  gruposOrdem.forEach(function(grp){
    var mods=grupos[grp]||[];
    mods.forEach(function(m){
      thead+='<th style="text-align:center;padding:4px 6px;min-width:72px;font-size:9px;color:#555;writing-mode:vertical-rl;height:70px;vertical-align:bottom;transform:rotate(180deg)">'
        +m.icon+' '+m.label+'</th>';
    });
  });
  thead+='</tr></thead>';

  var tbody='<tbody>';
  usrs.forEach(function(u){
    var perms=_permissoes[u.id]||{};
    tbody+='<tr>'
      +'<td style="font-weight:600;font-size:12px;position:sticky;left:0;background:#fff;z-index:1;white-space:nowrap">'+u.nome+'<div style="font-size:10px;color:#888;font-weight:400">'+(u.email||'')+'</div></td>'
      +'<td style="position:sticky;left:160px;background:#fff;z-index:1"><span style="font-size:10px;background:#EBF4FD;color:#185FA5;padding:2px 6px;border-radius:4px">'+u.perfil+'</span></td>';

    gruposOrdem.forEach(function(grp){
      var mods=grupos[grp]||[];
      mods.forEach(function(m){
        var checked = perms[m.id]!==false; // default: sim
        tbody+='<td style="text-align:center;padding:4px">'
          +'<label style="display:flex;align-items:center;justify-content:center;cursor:pointer">'
          +'<input type="checkbox" data-uid="'+u.id+'" data-mod="'+m.id+'" '+(checked?'checked':'')+' '
          +'style="width:16px;height:16px;accent-color:#185FA5;cursor:pointer"'
          +' onchange="permOnChange(this)">'
          +'</label></td>';
      });
    });
    tbody+='</tr>';
  });
  tbody+='</tbody>';

  wrap.innerHTML='<table style="border-collapse:collapse;width:100%;min-width:900px">'
    +thead+tbody+'</table>';
}

function permOnChange(el){
  var uid=el.getAttribute('data-uid');
  var mod=el.getAttribute('data-mod');
  if(!_permissoes[uid]) _permissoes[uid]={};
  _permissoes[uid][mod]=el.checked;
}

async function permSalvarTodas(){
  if(DEMO){progShowToast('Demo: permissões não salvas.');return;}
  var btn=document.querySelector('#cad-conteudo-inner .btn-pri');
  if(btn){btn.textContent='⌛ Salvando...';btn.disabled=true;}

  var ops=[];
  Object.keys(_permissoes).forEach(function(uid){
    var perms=_permissoes[uid];
    Object.keys(perms).forEach(function(mod){
      ops.push({usuario_id:uid,modulo:mod,ativo:perms[mod]});
    });
  });

  // Upsert em lotes
  var ok=true;
  for(var i=0;i<ops.length;i++){
    var r=await sbFetch('user_permissoes',{filters:['usuario_id=eq.'+ops[i].usuario_id,'modulo=eq.'+ops[i].modulo]});
    if(r&&r.length){
      await sbUpdate('user_permissoes',{ativo:ops[i].ativo},'id=eq.'+r[0].id);
    } else {
      await sbInsert('user_permissoes',ops[i]);
    }
  }

  if(btn){btn.textContent='💾 Salvar alterações';btn.disabled=false;}
  progShowToast('✅ Permissões salvas com sucesso!');
}

// ── Ordenação alfabética de selects ─────────────────────────────────────
function sortarOpts(selectEl, manterPrimeiro){
  if(!selectEl) return;
  var valorAtual = selectEl.value;
  var opts = Array.from(selectEl.options);
  var inicio = (manterPrimeiro!==false && opts.length && !opts[0].value) ? 1 : 0;
  var fixos  = opts.slice(0, inicio);
  var paraOrdenar = opts.slice(inicio);
  paraOrdenar.sort(function(a,b){
    return (a.text||'').localeCompare((b.text||''), 'pt-BR', {sensitivity:'base'});
  });
  while(selectEl.options.length) selectEl.remove(0);
  fixos.concat(paraOrdenar).forEach(function(o){ selectEl.appendChild(o); });
  if(valorAtual && Array.from(selectEl.options).some(function(o){ return o.value===valorAtual; })){
    selectEl.value = valorAtual;
  }
}

function sortarSelectId(id, manterPrimeiro){
  sortarOpts(document.getElementById(id), manterPrimeiro);
}

// Ordenar todos os selects de uma vez (chame após renders)
function sortarTodosSelects(){
  var sels = document.querySelectorAll('select.inp, select.select, .modal select, .fg select');
  sels.forEach(function(sel){
    if(sel.dataset.nosort) return; // [data-nosort] para excluir
    sortarOpts(sel, true);
  });
}

// ═══════════════════════════════════════════════════════
// STATUS DE PROJETOS
// ═══════════════════════════════════════════════════════
var status_projetos_db = [];

function statusProjRender(){
  var tb = document.getElementById('tbody-status-proj'); if(!tb) return;
  var busca = (document.getElementById('sp-busca')||{}).value || '';
  var lista = status_projetos_db.filter(function(s){
    if(!busca) return true;
    var b = busca.toLowerCase();
    return (s.cliente||'').toLowerCase().includes(b)
        || (s.status||'').toLowerCase().includes(b)
        || (s.descricao||'').toLowerCase().includes(b);
  });
  if(!lista.length){
    tb.innerHTML='<tr><td colspan="4" style="text-align:center;color:#aaa;padding:2rem">Nenhum registro encontrado</td></tr>';
    return;
  }
  tb.innerHTML = lista.map(function(s){
    return '<tr>'
      +'<td data-label="Cliente"><strong>'+escHtml(s.cliente||'—')+'</strong></td>'
      +'<td data-label="Status"><span style="background:#EBF4FD;color:#185FA5;border-radius:12px;padding:2px 10px;font-size:12px;font-weight:600">'+escHtml(s.status||'—')+'</span></td>'
      +'<td data-label="Descrição" style="max-width:300px;font-size:12px;color:#555">'+escHtml(s.descricao||'—')+'</td>'
      +'<td style="white-space:nowrap;text-align:right">'
      +'<button class="btn" style="font-size:11px;padding:3px 10px;margin-right:4px" onclick="statusProjAbrirModal(\''+s.id+'\')">✏️ Editar</button>'
      +'<button class="btn" style="font-size:11px;padding:3px 10px;background:#FFF0F0;border-color:#ffcccc;color:#c00" onclick="statusProjExcluir(\''+s.id+'\')">🗑</button>'
      +'</td></tr>';
  }).join('');
}

function statusProjAbrirModal(id){
  var reg = id ? status_projetos_db.find(function(s){return s.id===id;}) : null;
  var titulo = reg ? 'Editar Status de Projeto' : 'Novo Status de Projeto';

  // Montar opções de clientes do cadastro
  var optsClientes = '<option value="">Selecione o cliente...</option>'
    + (clientes||[]).map(function(c){
        var nome = c.razao_social||c.nome||c.fantasia||'';
        var sel  = reg && reg.cliente_id === c.id ? ' selected' : '';
        return '<option value="'+c.id+'"'+sel+'>'+escHtml(nome)+'</option>';
      }).join('');

  // Se não há clientes carregados, carregar agora
  if(!clientes||!clientes.length){
    sbFetch('clientes',{filters:['status=eq.Ativo'],order:'razao_social'}).then(function(res){
      if(res&&res.length){ clientes=res; }
      statusProjAbrirModal(id); // reabrir com dados
    });
    progShowToast('⏳ Carregando clientes...');
    return;
  }

  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin-bottom:1rem">'+titulo+'</h3>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:12px;font-weight:600;color:#555;display:block;margin-bottom:4px">Cliente *</label>'
    +'<select id="sp-cliente-id" class="inp" style="width:100%">'+optsClientes+'</select>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:12px;font-weight:600;color:#555;display:block;margin-bottom:4px">Status *</label>'
    +'<input id="sp-status" class="inp" placeholder="Ex: Em andamento, Concluído, Pausado..." style="width:100%" value="'+escHtml(reg?reg.status||'':'')+'" maxlength="80"/>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:12px;font-weight:600;color:#555;display:block;margin-bottom:4px">Descrição <span id="sp-char-count" style="font-weight:400;color:#aaa">('+((reg&&reg.descricao)?reg.descricao.length:0)+'/200)</span></label>'
    +'<textarea id="sp-descricao" class="inp" placeholder="Descreva o status em até 200 caracteres..." style="width:100%;min-height:90px;resize:vertical" maxlength="200" oninput="var c=this.value.length;document.getElementById(\'sp-char-count\').textContent=\'(\'+c+\'/200)\'">'+escHtml(reg?reg.descricao||'':'')+'</textarea>'
    +'</div>'
    +'<div class="ma">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="statusProjSalvar(\''+( reg?reg.id:'')+'\')">💾 Salvar</button>'
    +'</div></div></div>');
}

function statusProjSalvar(id){
  var clienteId = (document.getElementById('sp-cliente-id')||{}).value||'';
  var status    = (document.getElementById('sp-status')||{}).value||'';
  var descricao = (document.getElementById('sp-descricao')||{}).value||'';
  if(!clienteId){ progShowToast('⚠ Selecione o cliente.'); return; }
  if(!status.trim()){ progShowToast('⚠ Informe o status.'); return; }
  if(descricao.length > 200){ progShowToast('⚠ Descrição excede 200 caracteres.'); return; }
  // Resolver nome do cliente
  var cliObj = (clientes||[]).find(function(c){return c.id===clienteId;});
  var clienteNome = cliObj ? (cliObj.razao_social||cliObj.nome||cliObj.fantasia||'') : '';
  var payload = { cliente_id: clienteId, cliente: clienteNome, status: status.trim(), descricao: descricao.trim() };
  if(id){
    var idx = status_projetos_db.findIndex(function(s){return s.id===id;});
    if(idx>=0) Object.assign(status_projetos_db[idx], payload);
    if(!DEMO) sbUpdate('status_projetos', payload, 'id=eq.'+id);
    progShowToast('✅ Status atualizado.');
  } else {
    var novo = Object.assign({id:'sp_'+Date.now()}, payload);
    status_projetos_db.push(novo);
    if(!DEMO){
      sbInsert('status_projetos', payload).then(function(res){
        if(res&&res[0]&&res[0].id){
          var local=status_projetos_db.find(function(s){return s.id===novo.id;});
          if(local) local.id=res[0].id;
        }
      }).catch(function(e){console.error(e);});
    }
    progShowToast('✅ Status cadastrado.');
  }
  closeModal();
  statusProjRender();
}

function statusProjExcluir(id){
  if(!confirm('Excluir este status de projeto?')) return;
  status_projetos_db = status_projetos_db.filter(function(s){return s.id!==id;});
  if(!DEMO) sbFetch('status_projetos',{filters:['id=eq.'+id]}).then(function(){
    // usar delete via fetch direto
    var h={'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key),'Content-Type':'application/json'};
    fetch(SB.url+'/rest/v1/status_projetos?id=eq.'+id,{method:'DELETE',headers:h}).catch(function(){});
  });
  progShowToast('🗑 Status removido.');
  statusProjRender();
}

function statusProjCarregar(){
  if(DEMO) return Promise.resolve();
  return sbFetch('status_projetos',{order:'cliente'}).then(function(res){
    if(res&&res.length) status_projetos_db=res;
  }).catch(function(){});
}

function renderCadastros(){
  var CAD_GRUPOS = [
    {id:'financeiro',   label:'💰 Financeiro',  cor:'#185FA5',
     items:[{id:'categorias',icon:'🏷️',titulo:'Categorias de Despesa'},{id:'clientes',icon:'🏭',titulo:'Clientes'},{id:'fornecedores',icon:'🏢',titulo:'Fornecedores'}]},
    {id:'sesmt',        label:'🦺 SESMT',        cor:'#854F0B',
     items:[{id:'cursos',icon:'📚',titulo:'Cursos'},{id:'normas',icon:'📜',titulo:'Normas'},{id:'checklists',icon:'✅',titulo:'Checklists de Campo'}]},
    {id:'almoxarifado', label:'📦 Almoxarifado', cor:'#085041',
     items:[{id:'materiais-cat',icon:'📦',titulo:'Catálogo de Materiais'},{id:'unidades-medida',icon:'📐',titulo:'Unidades de Medida'},{id:'estoque',icon:'🗄️',titulo:'Estoque'},{id:'kits-campo',icon:'🧰',titulo:'Kits de Campo'},{id:'kits-veiculo',icon:'🚗',titulo:'Kits Modelo Materiais'}]},
    {id:'operacional',  label:'⚙️ Operacional',  cor:'#533AB7',
     items:[{id:'causas-codx',icon:'⚠️',titulo:'Causas COD X'},{id:'celulares',icon:'📱',titulo:'Celulares da Empresa'},{id:'equipes-disp',icon:'⚡',titulo:'Equipes de Disponibilidade'},{id:'equipes-obs',icon:'👷',titulo:'Equipes e Supervisores'},{id:'servicos',icon:'📋',titulo:'Tabela de Serviços'},{id:'status-projetos',icon:'📊',titulo:'Status de Projetos'},{id:'tipos-eq',icon:'🔧',titulo:'Tipos de Equipe'},{id:'tipos-servico',icon:'🔨',titulo:'Tipos de Serviço'},{id:'escalas-cad',icon:'⏰',titulo:'Escalas de Trabalho'}]},
    {id:'sistema',      label:'🖥️ Sistema',       cor:'#555',
     items:[{id:'colaboradores',icon:'👥',titulo:'Colaboradores'},{id:'cargos',icon:'💼',titulo:'Cargos'},{id:'usuarios',icon:'👤',titulo:'Usuários do sistema'},{id:'perfis-usuario',icon:'🎭',titulo:'Perfis de Usuário'},{id:'permissoes',icon:'🔐',titulo:'Permissões de Acesso'},{id:'veiculos',icon:'🚗',titulo:'Veículos / Frota'}]},
  ];
  if(typeof perfilEhDpRh==='function' && perfilEhDpRh()){
    CAD_GRUPOS = CAD_GRUPOS.map(function(g){
      return Object.assign({}, g, {items: g.items.filter(function(it){
        return it.id==='colaboradores'||it.id==='cargos';
      })});
    }).filter(function(g){ return g.items.length; });
  } else if(typeof perfilEhSupervisor==='function' && perfilEhSupervisor()){
    CAD_GRUPOS = CAD_GRUPOS.map(function(g){
      return Object.assign({}, g, {items: g.items.filter(function(it){
        return it.id!=='usuarios' && it.id!=='perfis-usuario' && it.id!=='permissoes';
      })});
    }).filter(function(g){ return g.items.length; });
  }
  var grid = document.getElementById('cad-grid');
  if(!grid) return;
  var ativo = grid.getAttribute('data-ativo')||'';
  if(!window._cadGrupoAberto) window._cadGrupoAberto = {financeiro:true,sesmt:true,almoxarifado:true,operacional:true,sistema:true};
  // Auto-expandir grupo do item ativo
  if(ativo){
    CAD_GRUPOS.forEach(function(g){
      if(g.items.some(function(it){return it.id===ativo;})) window._cadGrupoAberto[g.id]=true;
    });
  }
  grid.innerHTML = '';
  CAD_GRUPOS.forEach(function(g){
    var aberto = !!window._cadGrupoAberto[g.id];
    var hdr = document.createElement('div');
    hdr.style.cssText='display:flex;align-items:center;gap:5px;padding:5px 6px;cursor:pointer;border-radius:6px;margin-bottom:1px;user-select:none;margin-top:6px';
    hdr.innerHTML='<span style="font-size:10px;font-weight:700;color:'+g.cor+';flex:1;letter-spacing:.3px">'+g.label+'</span>'
      +'<span id="cad-grp-arr-'+g.id+'" style="font-size:9px;color:'+g.cor+';display:inline-block;transition:transform .2s;transform:'+(aberto?'rotate(90deg)':'rotate(0)')+'" >▶</span>';
    hdr.onmouseenter=function(){this.style.background='rgba(0,0,0,.04)';};
    hdr.onmouseleave=function(){this.style.background='';};
    hdr.onclick=(function(gid){return function(){
      window._cadGrupoAberto[gid]=!window._cadGrupoAberto[gid];
      var l=document.getElementById('cad-grp-list-'+gid);
      var a=document.getElementById('cad-grp-arr-'+gid);
      if(l)l.style.display=window._cadGrupoAberto[gid]?'':'none';
      if(a)a.style.transform=window._cadGrupoAberto[gid]?'rotate(90deg)':'rotate(0)';
    };})(g.id);
    grid.appendChild(hdr);
    var list=document.createElement('div');
    list.id='cad-grp-list-'+g.id;
    list.style.display=aberto?'':'none';
    g.items.forEach(function(c){
      var isAt=c.id===ativo;
      var div=document.createElement('div');
      div.setAttribute('data-id',c.id);
      div.style.cssText='padding:5px 8px 5px 18px;border-radius:7px;cursor:pointer;margin-bottom:1px;'
        +'background:'+(isAt?'#E8F0FE':'transparent')+';'
        +'border-left:2px solid '+(isAt?g.cor:'transparent')+';';
      div.innerHTML='<div style="display:flex;align-items:center;gap:7px">'
        +'<span style="font-size:12px">'+c.icon+'</span>'
        +'<span style="font-size:11px;font-weight:'+(isAt?'600':'400')+';color:'+(isAt?g.cor:'#444')+'">'+c.titulo+'</span>'
        +'</div>';
      div.onmouseenter=function(){if(!isAt)this.style.background='#f5f5f3';};
      div.onmouseleave=function(){if(!isAt)this.style.background='transparent';};
      div.onclick=(function(cid){return function(){abrirCadastro(cid);};})(c.id);
      list.appendChild(div);
    });
    grid.appendChild(list);
  });
}
// ── Novos cadastros: Cursos, Normas (SESMT) e Estoque ───────
var _cad_cursos  = [];
var _cad_normas  = [];
var _cursosTentouCarregar = false;

// ══════════════════════════════════════════════════════════════
// CADASTRO MESTRE DE CARGOS (fonte única; Cadastros e RH abrem o mesmo)
// Tokens futuros (não gerar contrato nesta fase):
//   [[CARGO]] = nome
//   [[OBJETO_DA_FUNÇÃO]] = objeto_funcao
//   [[DESCRIÇÃO_DAS_ATIVIDADES_E_RESPONSABILIDADES]] = descricao_atividades_responsabilidades
// Matriz de requisitos (RH-1B) e importação em massa (RH-1A.1) NÃO entram aqui.
// ══════════════════════════════════════════════════════════════
var _cad_cargos = [];
var _cadCargosVerInativos = false;
function cadCargosSetVerInativos(ver){
  _cadCargosVerInativos = !!ver;
  _cadRenderCargosLista();
}
function cadPodeEditarCargos(){
  var p=(usuarioLogado&&usuarioLogado.perfil)||'';
  if(typeof perfilAcessoTotal==='function' && perfilAcessoTotal()) return true;
  if(typeof perfilEhDpRh==='function' && perfilEhDpRh()) return true;
  return p==='gestor' || p==='coordenador';
}
function cadCargoTexto(c, campo){
  if(!c) return '';
  return String(c[campo]||'').replace(/\s+$/,'');
}
function cadCargoDescricaoCompleta(c){
  return !!(String(c&&c.objeto_funcao||'').trim() && String(c&&c.descricao_atividades_responsabilidades||'').trim());
}
function cadCargoPreviewHtml(txt, n){
  var t=String(txt||'').replace(/\s+/g,' ').trim();
  if(!t) return '<span style="color:#bbb">—</span>';
  var max=n||72;
  var short=t.length>max?t.slice(0,max)+'…':t;
  var tip=t.length>400?t.slice(0,400)+'…':t;
  return '<span title="'+escHtml(tip)+'" style="font-size:11px;color:#555">'+escHtml(short)+'</span>';
}
function cadCargoTokensDocumento(c){
  return {
    '[[CARGO]]': (c&&c.nome)||'',
    '[[OBJETO_DA_FUNÇÃO]]': cadCargoTexto(c,'objeto_funcao'),
    '[[DESCRIÇÃO_DAS_ATIVIDADES_E_RESPONSABILIDADES]]': cadCargoTexto(c,'descricao_atividades_responsabilidades')
  };
}
function cadCarregarCargos(cb, force){
  if(DEMO){ if(cb)cb(); return; }
  if(_cad_cargos.length && !force){ if(cb)cb(); return; }
  sbFetch('cargos',{order:'nome.asc'}).then(function(rows){ if(rows)_cad_cargos=rows; if(cb)cb(); })
    .catch(function(){ if(cb)cb(); });
}
function _cargosAtivosOrdenados(){
  return _cad_cargos.filter(function(c){return c.ativo!==false;})
    .sort(function(a,b){ return (a.categoria||'~').localeCompare(b.categoria||'~','pt-BR')||String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'); });
}
// <select> de cargo agrupado por categoria. Inclui o valor atual mesmo se não cadastrado (não perde legado).
function _cargosParaSelect(){
  var ativos=_cargosAtivosOrdenados();
  if(ativos.length) return ativos;
  var vistos={}, out=[];
  (colaboradores||[]).forEach(function(c){
    if(c.ativo===false) return;
    var n=(c.cargo||'').trim();
    if(!n||vistos[n]) return;
    vistos[n]=true;
    out.push({nome:n, categoria:'Em uso nos colaboradores'});
  });
  return out.sort(function(a,b){ return a.nome.localeCompare(b.nome,'pt-BR'); });
}
function cargoSelectHtml(selected, attrs){
  selected=selected||'';
  var ativos=_cargosParaSelect();
  var byCat={}; ativos.forEach(function(c){ (byCat[c.categoria||'Outros']=byCat[c.categoria||'Outros']||[]).push(c.nome); });
  var existe=ativos.some(function(c){return c.nome===selected;});
  var html='<select '+(attrs||'')+'><option value="">— Selecione o cargo —</option>';
  if(selected && !existe) html+='<optgroup label="Atual (fora do cadastro)"><option value="'+escHtml(selected)+'" selected>'+escHtml(selected)+'</option></optgroup>';
  Object.keys(byCat).sort().forEach(function(cat){
    html+='<optgroup label="'+escHtml(cat)+'">'+byCat[cat].map(function(n){
      return '<option value="'+escHtml(n)+'"'+(n===selected?' selected':'')+'>'+escHtml(n)+'</option>';
    }).join('')+'</optgroup>';
  });
  if(!ativos.length && !selected) html+='<option value="" disabled>(nenhum cargo cadastrado)</option>';
  return html+'</select>';
}
function rhCargoNormNome(s){
  return String(s||'').trim().replace(/\s+/g,' ').toLowerCase();
}
function rhCargoPorNomeHistorico(nome){
  var n=rhCargoNormNome(nome);
  if(!n) return null;
  var hits=(_cad_cargos||[]).filter(function(c){
    return c && c.id && c.ativo!==false && rhCargoNormNome(c.nome)===n;
  });
  if(hits.length===1) return hits[0];
  var exatos=hits.filter(function(c){ return String(c.nome||'').trim()===String(nome||'').trim(); });
  return exatos.length===1?exatos[0]:null;
}
/** Texto histórico (colaboradores.cargo) prevalece se o cargo_id apontar para outro nome. */
function rhCargoResolverHistorico(cargoId, cargoNome){
  cargoId=cargoId!=null&&cargoId!==''?String(cargoId):'';
  if(cargoId==='__hist__') cargoId='';
  cargoNome=String(cargoNome||'').trim();
  var porId=cargoId?(_cad_cargos||[]).find(function(c){ return String(c.id)===cargoId; }):null;
  var porNome=rhCargoPorNomeHistorico(cargoNome);
  if(cargoNome && porNome){
    if(!porId || rhCargoNormNome(porId.nome)!==rhCargoNormNome(cargoNome)){
      return {id:String(porNome.id), nome:String(porNome.nome||cargoNome).trim()};
    }
  }
  if(porId) return {id:String(porId.id), nome:String(porId.nome||cargoNome).trim()};
  if(cargoId) return {id:cargoId, nome:cargoNome||cargoId};
  return {id:'', nome:cargoNome};
}
function rhCargoAplicarSelectNc(cargoId, cargoNome){
  var el=document.getElementById('nc-cargo');
  if(!el) return null;
  if(cargoId!=null) el.setAttribute('data-cargo-hist-id', String(cargoId||''));
  if(cargoNome!=null) el.setAttribute('data-cargo-hist-nome', String(cargoNome||''));
  var r=rhCargoResolverHistorico(cargoId, cargoNome);
  if(r.id){
    el.value=r.id;
    if(el.value!==r.id){
      var opt=document.createElement('option');
      opt.value=r.id;
      opt.textContent=r.nome||r.id;
      el.appendChild(opt);
      el.value=r.id;
    }
    return r;
  }
  if(r.nome){
    var histOpt=null;
    Array.from(el.options).forEach(function(o){ if(o.value==='__hist__') histOpt=o; });
    if(!histOpt){
      histOpt=document.createElement('option');
      histOpt.value='__hist__';
      el.insertBefore(histOpt, el.options[1]||null);
    }
    histOpt.textContent=r.nome;
    el.value='__hist__';
  }
  return r;
}
/** Select do Cargo Mestre com value = id. Na edição, o nome histórico prevalece sobre cargo_id divergente. */
function cargoSelectHtmlPorId(selectedId, selectedNome, attrs){
  var origId=selectedId!=null&&selectedId!==''?String(selectedId):'';
  var origNome=String(selectedNome||'').trim();
  var resolved=rhCargoResolverHistorico(origId, origNome);
  selectedId=resolved.id;
  selectedNome=resolved.nome;
  var ativos=_cargosAtivosOrdenados();
  var byCat={};
  ativos.forEach(function(c){
    if(!c||!c.id) return;
    (byCat[c.categoria||'Outros']=byCat[c.categoria||'Outros']||[]).push(c);
  });
  var existe=ativos.some(function(c){ return String(c.id)===selectedId; });
  attrs=String(attrs||'');
  if(!/\bdata-nosort\b/.test(attrs)) attrs+=' data-nosort="1"';
  var html='<select '+attrs+' data-cargo-modo="id" data-cargo-hist-id="'+escHtml(origId)+'" data-cargo-hist-nome="'+escHtml(origNome)+'"><option value="">— Selecione o cargo —</option>';
  if(selectedId && !existe){
    html+='<optgroup label="Atual (id sem cadastro ativo)"><option value="'+escHtml(selectedId)+'" selected>'
      +escHtml(selectedNome||selectedId)+'</option></optgroup>';
  }
  if(!selectedId && selectedNome){
    html+='<optgroup label="Salvo no cadastro"><option value="__hist__" selected>'
      +escHtml(selectedNome)+'</option></optgroup>';
  }
  Object.keys(byCat).sort().forEach(function(cat){
    html+='<optgroup label="'+escHtml(cat)+'">'+byCat[cat].map(function(c){
      return '<option value="'+escHtml(String(c.id))+'"'+(String(c.id)===selectedId?' selected':'')+'>'+escHtml(c.nome||'')+'</option>';
    }).join('')+'</optgroup>';
  });
  if(!ativos.length && !selectedId) html+='<option value="" disabled>(nenhum cargo cadastrado)</option>';
  return html+'</select>';
}
/** Lê #nc-cargo. Vazio/__hist__ devolve o cargo histórico salvo. */
function rhCargoLerSelectNc(){
  var el=document.getElementById('nc-cargo');
  if(!el) return {cargo_id:null, cargo:''};
  var raw=String(el.value||'').trim();
  var histId=String(el.getAttribute('data-cargo-hist-id')||'').trim();
  var histNome=String(el.getAttribute('data-cargo-hist-nome')||'').trim();
  var modo=(el.getAttribute('data-cargo-modo')||'')==='id';
  if(!raw || raw==='__hist__'){
    if(histId||histNome){
      var resolved=rhCargoResolverHistorico(histId, histNome);
      return {cargo_id:resolved.id||histId||null, cargo:resolved.nome||histNome||''};
    }
    return {cargo_id:null, cargo:''};
  }
  if(modo){
    var obj=(_cad_cargos||[]).find(function(c){ return String(c.id)===raw; });
    if(obj) return {cargo_id:String(obj.id), cargo:String(obj.nome||'').trim()};
    var opt=el.options[el.selectedIndex];
    var label=opt?String(opt.text||'').trim():'';
    return {cargo_id:raw, cargo:label||''};
  }
  var hits=(_cad_cargos||[]).filter(function(x){ return String(x.nome||'').trim()===raw; });
  return {cargo_id:hits.length===1?String(hits[0].id):null, cargo:raw};
}
// <datalist> de cargos ativos (sugestão; permite digitar — usado onde o cargo pode ser externo)
function cargoDatalistHtml(dlId){
  return '<datalist id="'+dlId+'">'+_cargosAtivosOrdenados().map(function(c){return '<option value="'+escHtml(c.nome)+'">';}).join('')+'</datalist>';
}
var _rhMatrizStatus = {};
function cadRenderCargos(){
  _cadCargosVerInativos = false;
  var inner=document.getElementById('cad-conteudo-inner'); if(!inner) return;
  inner.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa;font-size:13px">⏳ Carregando cargos...</div>';
  cadCarregarCargos(function(){
    if(DEMO){ _cadRenderCargosLista(); return; }
    sbFetch('rh_cargo_requisitos',{select:'cargo_id,status,ativo',filters:['ativo=eq.true']}).then(function(rows){
      _rhMatrizStatus={};
      (rows||[]).forEach(function(r){ if(r.ativo!==false) _rhMatrizStatus[String(r.cargo_id)]=r.status||'NAO_CONFIGURADA'; });
      _cadRenderCargosLista();
    }).catch(function(){ _cadRenderCargosLista(); });
  }, !DEMO);
}
function cadFiltrarCargos(){ _cadRenderCargosLista(); }
function cadVerTextoCargo(id, campo){
  var c=_cad_cargos.find(function(x){return String(x.id)===String(id);}); if(!c) return;
  var titulo=campo==='objeto_funcao'?'Objeto Principal da Função':'Descrição das Atividades e Responsabilidades';
  var txt=cadCargoTexto(c,campo);
  setModal('<div class="modal-bg"><div class="modal" style="max-width:640px">'
    +'<h3 style="margin-bottom:.5rem">'+escHtml(c.nome||'Cargo')+'</h3>'
    +'<div style="font-size:12px;font-weight:600;margin-bottom:.4rem">'+escHtml(titulo)+'</div>'
    +'<div style="white-space:pre-wrap;font-size:13px;line-height:1.45;max-height:60vh;overflow:auto;padding:.6rem .75rem;background:#F8FAFC;border-radius:8px;border:.5px solid #e8e8e4">'
    +(txt?escHtml(txt):'<span style="color:#aaa">Sem texto cadastrado.</span>')+'</div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Fechar</button>'
    +(cadPodeEditarCargos()?'<button class="btn btn-pri" onclick="cadNovoCargo(\''+String(c.id).replace(/'/g,"\\'")+'\')">✎ Editar</button>':'')
    +'</div></div></div>');
}
function _cadRenderCargosLista(){
  var inner=document.getElementById('cad-conteudo-inner'); if(!inner) return;
  var q=((document.getElementById('cad-cargo-busca')||{}).value||'').toLowerCase().trim();
  var podeEd=cadPodeEditarCargos();
  var verInativos=!!_cadCargosVerInativos;
  var nAtivos=0, nInativos=0;
  (_cad_cargos||[]).forEach(function(c){ if(c.ativo===false) nInativos++; else nAtivos++; });
  var uso={}; (colaboradores||[]).forEach(function(c){ if(c.ativo!==false && c.cargo){ uso[c.cargo]=(uso[c.cargo]||0)+1; } });
  var lista=_cad_cargos.slice().sort(function(a,b){ return (a.categoria||'~').localeCompare(b.categoria||'~','pt-BR')||a.nome.localeCompare(b.nome,'pt-BR'); });
  lista=lista.filter(function(c){ return verInativos ? c.ativo===false : c.ativo!==false; });
  if(q) lista=lista.filter(function(c){
    return (c.nome||'').toLowerCase().indexOf(q)>=0
      || (c.categoria||'').toLowerCase().indexOf(q)>=0
      || String(c.objeto_funcao||'').toLowerCase().indexOf(q)>=0
      || String(c.descricao_atividades_responsabilidades||'').toLowerCase().indexOf(q)>=0;
  });
  var rows=lista.map(function(c){
    var n=uso[c.nome]||0; var inativo=c.ativo===false;
    var completa=cadCargoDescricaoCompleta(c);
    var cid=String(c.id||'').replace(/'/g,"\\'");
    var acoes='<button class="btn btn-sm" style="font-size:10px" onclick="cadNovoCargo(\''+cid+'\')">'+(podeEd?'✎':'👁')+'</button>';
    if(podeEd){
      acoes+='<button class="btn btn-sm" style="font-size:10px" onclick="cadToggleCargoAtivo(\''+cid+'\')">'+(inativo?'Reativar':'Inativar')+'</button>'
        +'<button class="btn btn-sm" style="font-size:10px;background:#FCEBEB;color:#A32D2D" onclick="cadDeletarCargo(\''+cid+'\',\''+escHtml((c.nome||'').replace(/'/g,"\\'"))+'\','+n+')">🗑</button>';
    }
    return '<tr'+(inativo?' style="opacity:.5"':'')+'>'
      +'<td style="font-weight:500;font-size:12px">'+escHtml(c.nome)+'<div style="font-size:10px;color:#888">'+escHtml(c.categoria||'—')+(n?' · '+n+' colab.':'')+'</div></td>'
      +'<td style="max-width:220px">'+cadCargoPreviewHtml(c.objeto_funcao,70)
      +(String(c.objeto_funcao||'').trim()?' <button class="btn btn-sm" style="font-size:9px;padding:1px 5px" onclick="cadVerTextoCargo(\''+cid+'\',\'objeto_funcao\')">Ver</button>':'')+'</td>'
      +'<td style="max-width:220px">'+cadCargoPreviewHtml(c.descricao_atividades_responsabilidades,70)
      +(String(c.descricao_atividades_responsabilidades||'').trim()?' <button class="btn btn-sm" style="font-size:9px;padding:1px 5px" onclick="cadVerTextoCargo(\''+cid+'\',\'descricao_atividades_responsabilidades\')">Ver</button>':'')+'</td>'
      +'<td style="text-align:center"><span style="background:'+(completa?'#EAF3DE':'#FFF4E5')+';color:'+(completa?'#3B6D11':'#854F0B')+';border-radius:4px;padding:1px 6px;font-size:10px;white-space:nowrap">'+(completa?'DESCRIÇÃO COMPLETA':'INCOMPLETA')+'</span></td>'
      +'<td style="text-align:center">'+rhMatrizBadgeHtml(c.id)+'</td>'
      +'<td style="text-align:center"><span style="background:'+(inativo?'#f5f5f3':'#EAF3DE')+';color:'+(inativo?'#888':'#3B6D11')+';border-radius:4px;padding:1px 6px;font-size:10px">'+(inativo?'Inativo':'Ativo')+'</span></td>'
      +'<td style="white-space:nowrap;display:flex;gap:4px;justify-content:flex-end">'+acoes+'</td></tr>';
  }).join('');
  var titulo=verInativos
    ? '💼 Cargos inativos ('+lista.length+(q?' de '+nInativos:'')+')'
    : '💼 Cadastro Mestre de Cargos ('+lista.length+(q?' de '+nAtivos:'')+')';
  var btnTroca=verInativos
    ? '<button class="btn" id="cad-cargo-ver-ativos" onclick="cadCargosSetVerInativos(false)">← Ver ativos ('+nAtivos+')</button>'
    : '<button class="btn" id="cad-cargo-ver-inativos" onclick="cadCargosSetVerInativos(true)">Ver inativos ('+nInativos+')</button>';
  var emptyMsg=verInativos
    ? (q?'Nenhum cargo inativo encontrado na busca.':'Nenhum cargo inativo.')
    : (q?'Nenhum cargo ativo encontrado na busca.':'Nenhum cargo ativo. Rode o <b>sql_cargos.sql</b>'+(podeEd?' ou clique em <b>+ Novo Cargo</b>':'')+'.');
  var nota=verInativos
    ? 'Exibindo cargos inativos. Use <b>Reativar</b> para devolver o cargo ao cadastro ativo, ou <b>Ver ativos</b> para voltar à lista principal.'
    : 'Fonte única dos cargos (Cadastros e RH). Colaborador escolhe daqui. Descrição funcional é opcional — não bloqueia folha, Synergy, SESMT nem cadastro. Importação em massa: fase RH-1A.1.';
  inner.innerHTML='<div class="card"><div class="ch"><span class="ct">'+titulo+'</span>'
    +'<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">'
    +'<input class="inp" id="cad-cargo-busca" placeholder="Buscar..." style="width:160px" value="'+escHtml(q)+'" oninput="cadFiltrarCargos()"/>'
    +btnTroca
    +(podeEd?'<button class="btn" onclick="cadAbrirImportMassaCargos()">Importar planilha RH-1A.1</button><button class="btn btn-pri" onclick="cadNovoCargo()">+ Novo Cargo</button>':'')+'</div></div>'
    +'<div style="padding:.4rem .9rem;font-size:11px;color:'+(verInativos?'#854F0B':'#888')+(verInativos?';background:#FFF8E1':'')+'">'+nota+'</div>'
    +'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Cargo</th><th>Objeto da Função</th><th>Atividades/Responsabilidades</th><th style="text-align:center">Completude</th><th style="text-align:center">Requisitos</th><th style="text-align:center">Status</th><th></th></tr></thead>'
    +'<tbody>'+(rows||'<tr><td colspan="7" style="text-align:center;color:#aaa;padding:1.5rem">'+emptyMsg+'</td></tr>')+'</tbody></table></div></div>';
  var bi=document.getElementById('cad-cargo-busca'); if(bi&&q){ bi.focus(); bi.setSelectionRange(bi.value.length,bi.value.length); }
}
function cadNovoCargo(id){
  var c=id?(_cad_cargos.find(function(x){return String(x.id)===String(id);})||{}):{};
  var soLeitura=!cadPodeEditarCargos();
  if(!id && soLeitura){ progShowToast('⚠ Sem permissão para incluir cargo.','erro'); return; }
  var cats=['Eletrica','Obras','Operacao de maquinas','Almoxarifado','Administrativo/Apoio','Outros'];
  var catSet={}; _cad_cargos.forEach(function(x){if(x.categoria)catSet[x.categoria]=true;}); cats.forEach(function(x){catSet[x]=true;});
  var catOpts=Object.keys(catSet).sort().map(function(x){return '<option'+(c.categoria===x?' selected':'')+'>'+escHtml(x)+'</option>';}).join('');
  var dis=soLeitura?' disabled':'';
  var idJs=id?String(id).replace(/'/g,"\\'"):'';
  _cadCargoEditId=id?String(id):null;
  function tabBtn(k,lab){ return '<button type="button" class="btn btn-sm cad-cg-tab" data-tab="'+k+'" onclick="cadCargoSetAba(\''+k+'\')" style="font-size:11px">'+lab+'</button>'; }
  setModal('<div class="modal-bg"><div class="modal" style="max-width:820px;max-height:92vh;overflow:auto">'
    +'<div id="cad-cg-modal-topo" style="position:sticky;top:0;background:#fff;z-index:4;padding-bottom:.55rem;margin-bottom:.75rem;border-bottom:.5px solid #f0efe8">'
    +'<h3 id="cad-cg-modal-titulo" style="margin:0 0 .5rem">'+(id?(soLeitura?'👁 Cargo':'✎ Editar Cargo'):'💼 Novo Cargo')
    +(c.nome?'<div style="font-size:16px;font-weight:700;margin-top:4px;color:#185FA5">'+escHtml(c.nome)+'</div>':'')
    +'</h3>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
    +tabBtn('dados','Dados do Cargo')+tabBtn('desc','Descrição Funcional')+(id?tabBtn('req','Requisitos do Cargo'):'')
    +(id?tabBtn('testes','Testes e Avaliações'):'')
    +'</div></div>'
    +'<div id="cad-cg-aba-dados">'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Nome do cargo *</label><input class="inp" id="cg-nome" style="width:100%" value="'+escHtml(c.nome||'')+'" placeholder="Ex: ELETRICISTA II"'+dis+'/></div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Categoria</label><select class="inp" id="cg-cat" style="width:100%"'+dis+'><option value="">—</option>'+catOpts+'</select></div>'
    +'<div class="fg" style="margin-bottom:.8rem"><label style="font-size:11px;font-weight:500"><input type="checkbox" id="cg-ativo" '+(c.ativo!==false?'checked':'')+dis+'/> Ativo</label></div>'
    +'</div>'
    +'<div id="cad-cg-aba-desc" style="display:none">'
    +'<div style="font-size:10px;color:#888;margin-bottom:.5rem">Não preencha os dois campos com o mesmo texto. Objeto = finalidade; Descrição = o que executa.</div>'
    +'<div class="fg" style="margin-bottom:.7rem"><label style="font-size:11px;font-weight:500">Objeto Principal da Função</label>'
    +'<div style="font-size:10px;color:#888;margin:.15rem 0 .35rem">Síntese da finalidade principal deste cargo. Poderá ser utilizada em contratos, seleção e outros processos do RH.</div>'
    +'<textarea class="inp" id="cg-objeto" rows="4" style="width:100%;min-height:88px;resize:vertical" placeholder="Para que este cargo existe?"'+dis+'>'+escHtml(cadCargoTexto(c,'objeto_funcao'))+'</textarea></div>'
    +'<div class="fg" style="margin-bottom:.6rem"><label style="font-size:11px;font-weight:500">Descrição das Atividades e Responsabilidades</label>'
    +'<div style="font-size:10px;color:#888;margin:.15rem 0 .35rem">Atividades típicas, responsabilidades e limites de atuação relacionados a este cargo.</div>'
    +'<textarea class="inp" id="cg-atividades" rows="8" style="width:100%;min-height:160px;resize:vertical" placeholder="O que este profissional normalmente executa e por quais responsabilidades responde?"'+dis+'>'+escHtml(cadCargoTexto(c,'descricao_atividades_responsabilidades'))+'</textarea></div>'
    +'</div>'
    +(id?'<div id="cad-cg-aba-req" style="display:none"><div id="rh-matriz-wrap" style="font-size:12px;color:#888">Carregando matriz…</div></div>':'')
    +(id?'<div id="cad-cg-aba-testes" style="display:none"><div id="rh-cargo-testes-wrap" style="font-size:12px;color:#888">Carregando testes do cargo…</div></div>':'')
    +'<div class="ma"><button class="btn" onclick="closeModal()">'+(soLeitura?'Fechar':'Cancelar')+'</button>'
    +(soLeitura?'':'<button class="btn btn-pri" onclick="salvarCargo('+(id?'\''+idJs+'\'':'')+')">💾 Salvar dados do cargo</button>')
    +'</div></div></div>');
  cadCargoSetAba('dados');
  if(id && typeof rhMatrizAbrir==='function') rhMatrizAbrir(id, soLeitura);
}
function cadCargoNomeEdicao(){
  var inp=document.getElementById('cg-nome');
  if(inp && String(inp.value||'').trim()) return String(inp.value).trim();
  if(typeof rhMatrizCargoNome==='function'){
    var n=rhMatrizCargoNome();
    if(n) return n;
  }
  var id=_cadCargoEditId;
  var c=id?(_cad_cargos||[]).find(function(x){ return String(x.id)===String(id); }):null;
  return (c&&c.nome)||'';
}
function cadCargoAtualizarTituloModal(aba){
  var el=document.getElementById('cad-cg-modal-titulo');
  if(!el) return;
  var nome=cadCargoNomeEdicao();
  var soLeitura=!cadPodeEditarCargos();
  var id=_cadCargoEditId;
  var prefix=!id?'💼 Novo Cargo':(aba==='req'?(soLeitura?'👁 Requisitos do cargo':'Requisitos do cargo'):(aba==='testes'?(soLeitura?'👁 Testes e Avaliações':'Testes e Avaliações do cargo'):(soLeitura?'👁 Cargo':'✎ Editar Cargo')));
  el.innerHTML=nome
    ? prefix+'<div style="font-size:16px;font-weight:700;margin-top:4px;color:#185FA5">'+escHtml(nome)+'</div>'
    : prefix;
}
function cadCargoSetAba(k){
  ['dados','desc','req','testes'].forEach(function(x){
    var el=document.getElementById('cad-cg-aba-'+x); if(el) el.style.display=x===k?'':'none';
  });
  document.querySelectorAll('.cad-cg-tab').forEach(function(b){
    var on=b.getAttribute('data-tab')===k;
    b.style.background=on?'#185FA5':'';
    b.style.color=on?'#fff':'';
  });
  cadCargoAtualizarTituloModal(k);
  if(k==='req' || k==='testes'){
    var md=document.querySelector('#modal-area .modal');
    if(md) md.scrollTop=0;
  }
  if(k==='testes' && typeof rhCargoTestesRender==='function') rhCargoTestesRender();
  var btn=document.querySelector('.modal .ma .btn-pri');
  var cid=_cadCargoEditId||null;
  if(btn && cid && cadPodeEditarCargos()){
    if(k==='req'){
      btn.textContent='💾 Salvar matriz';
      btn.setAttribute('onclick','rhMatrizSalvarTudo()');
    } else {
      btn.textContent='💾 Salvar dados do cargo';
      btn.setAttribute('onclick',"salvarCargo('"+String(cid).replace(/'/g,"\\'")+"')");
    }
  }
}
var _cadCargoEditId=null;
var _rhCargoTestes={lista:[], catalogo:[], byId:{}, cargoId:null, disponivel:true, form:null, verId:null};
function rhCargoTestesSqlHint(){
  return 'Aplique no SQL Editor: SQLS/sql_rh_selecao_cargo_teste_vaga_fase_sel1d2.sql (após rh_testes e rh_vagas). O ERP não aplica SQL.';
}
function rhCargoTestesEtapaLabel(v){
  return ({ANTES_ENTREVISTA:'Antes da entrevista',APOS_ENTREVISTA:'Após a entrevista',OUTRA:'Outra'})[v]||v||'—';
}
function rhCargoTestesQuem(){
  return (typeof usuarioLogado!=='undefined'&&usuarioLogado)?(usuarioLogado.nome||usuarioLogado.email||null):null;
}
function rhCargoTestesPublicados(){
  var byCod={};
  (_rhCargoTestes.catalogo||[]).forEach(function(t){
    if(!t||t.ativo===false) return;
    var k=String(t.codigo||t.id);
    var cur=byCod[k];
    if(!cur || Number(t.versao||1)>Number(cur.versao||1)) byCod[k]=t;
  });
  return Object.keys(byCod).map(function(k){ return byCod[k]; }).sort(function(a,b){
    return String(a.nome||a.codigo).localeCompare(String(b.nome||b.codigo),'pt');
  });
}
function rhCargoTestesJaVinculado(teste){
  var tid=String(teste.id||'');
  var cod=String(teste.codigo||'');
  return (_rhCargoTestes.lista||[]).some(function(x){
    if(!x||x.ativo===false) return false;
    if(String(x.teste_id)===tid) return true;
    var t=_rhCargoTestes.byId[String(x.teste_id)];
    return !!(t && cod && String(t.codigo||'')===cod);
  });
}
function rhCargoTestesCarregar(cargoId){
  _rhCargoTestes.cargoId=cargoId?String(cargoId):null;
  _rhCargoTestes.lista=[];
  _rhCargoTestes.catalogo=[];
  _rhCargoTestes.byId={};
  if(!_rhCargoTestes.cargoId) return Promise.resolve();
  return Promise.all([
    sbFetch('rh_cargo_testes',{filters:['cargo_id=eq.'+_rhCargoTestes.cargoId],order:'ordem.asc',limit:200}),
    sbFetch('rh_testes',{filters:['ativo=eq.true'],order:'codigo.asc',limit:500})
  ]).then(function(arr){
    if(arr[0]===null){ _rhCargoTestes.disponivel=false; return; }
    _rhCargoTestes.disponivel=true;
    _rhCargoTestes.lista=arr[0]||[];
    _rhCargoTestes.catalogo=arr[1]||[];
    _rhCargoTestes.byId={};
    _rhCargoTestes.catalogo.forEach(function(t){ if(t&&t.id) _rhCargoTestes.byId[String(t.id)]=t; });
  }).catch(function(){ _rhCargoTestes.disponivel=false; });
}
function rhCargoTestesRender(){
  var wrap=document.getElementById('rh-cargo-testes-wrap'); if(!wrap) return;
  var cid=_cadCargoEditId;
  var soLeitura=!cadPodeEditarCargos();
  var nome=cadCargoNomeEdicao();
  if(!cid){ wrap.innerHTML='<div style="color:#888">Salve o cargo antes de vincular testes.</div>'; return; }
  wrap.innerHTML='<div style="color:#888">Carregando testes do cargo…</div>';
  rhCargoTestesCarregar(cid).then(function(){
    if(!_rhCargoTestes.disponivel){
      wrap.innerHTML='<div style="color:#854F0B;background:#FEF3E2;padding:8px;border-radius:8px">'+escHtml(rhCargoTestesSqlHint())+'</div>';
      return;
    }
    var rows=(_rhCargoTestes.lista||[]).slice().sort(function(a,b){ return (a.ordem||0)-(b.ordem||0); });
    var html='<div style="font-size:12px;color:#555;margin-bottom:8px">Testes do <b>Banco de Testes</b> aplicados a este cargo. A vaga herda um snapshot ao ser salva — alterar aqui não muda vaga já aberta.</div>'
      +(nome?'<div style="font-weight:700;margin-bottom:8px;color:#185FA5">Cargo: '+escHtml(nome)+'</div>':'')
      +(soLeitura?'':'<div style="margin-bottom:8px"><button type="button" class="btn btn-sm btn-pri" id="rh-cg-vincular-teste" onclick="rhCargoTestesAbrirForm()">+ Vincular teste</button></div>')
      +'<div id="rh-cargo-testes-form"></div>'
      +'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Ordem</th><th>Teste</th><th>Obrigatório</th><th>Eliminatório</th><th>Nota mín.</th><th>Tentativas</th><th>Etapa</th><th>Ativo</th><th></th></tr></thead><tbody>';
    if(!rows.length){
      html+='<tr><td colspan="9" style="text-align:center;color:#aaa;padding:1.2rem">Nenhum teste vinculado. Clique em + Vincular teste.</td></tr>';
    } else {
      rows.forEach(function(r, idx){
        var t=_rhCargoTestes.byId[String(r.teste_id)]||{};
        var rid=String(r.id||'').replace(/'/g,'');
        var tid=String(r.teste_id||'').replace(/'/g,'');
        var acoes='<button type="button" class="btn btn-sm" onclick="rhCargoTestesVer(\''+tid+'\')">Ver</button>';
        if(!soLeitura){
          acoes+=' <button type="button" class="btn btn-sm" onclick="rhCargoTestesAbrirForm(\''+rid+'\')">Editar</button>';
          if(idx>0) acoes+=' <button type="button" class="btn btn-sm" onclick="rhCargoTestesReordenar(\''+rid+'\',-1)">↑</button>';
          if(idx<rows.length-1) acoes+=' <button type="button" class="btn btn-sm" onclick="rhCargoTestesReordenar(\''+rid+'\',1)">↓</button>';
          if(r.ativo!==false) acoes+=' <button type="button" class="btn btn-sm" onclick="rhCargoTestesDesativar(\''+rid+'\')">Desativar</button>';
          acoes+=' <button type="button" class="btn btn-sm" style="color:#A32D2D" onclick="rhCargoTestesRemover(\''+rid+'\')">Remover</button>';
        }
        html+='<tr'+(r.ativo===false?' style="opacity:.55"':'')+'><td>'+escHtml(rhCargoTestesTxt(r.ordem))+'</td>'
          +'<td>'+escHtml(rhCargoTestesTxt(t.nome||r.teste_id))+'<div style="font-size:10px;color:#888">'+escHtml(rhCargoTestesTxt(t.codigo))+(t.versao?' · v'+escHtml(rhCargoTestesTxt(t.versao)):'')+'</div></td>'
          +'<td>'+(r.obrigatorio!==false?'Sim':'Não')+'</td>'
          +'<td>'+(r.eliminatorio?'Sim':'Não')+'</td>'
          +'<td>'+(r.nota_minima!=null?escHtml(rhCargoTestesTxt(r.nota_minima))+'%':'—')+'</td>'
          +'<td>'+escHtml(rhCargoTestesTxt(r.tentativas_maximas||1))+'</td>'
          +'<td>'+escHtml(rhCargoTestesEtapaLabel(r.etapa_processo))+'</td>'
          +'<td>'+(r.ativo!==false?'Sim':'Não')+'</td>'
          +'<td style="white-space:nowrap">'+acoes+'</td></tr>';
      });
    }
    html+='</tbody></table></div><div id="rh-cargo-testes-ver"></div>';
    wrap.innerHTML=html;
    if(_rhCargoTestes.form) rhCargoTestesAbrirForm(_rhCargoTestes.form.id||null);
    if(_rhCargoTestes.verId) rhCargoTestesVer(_rhCargoTestes.verId);
  });
}
function rhCargoTestesTxt(v){ return (v==null||v===false)?'':String(v); }
function rhCargoTestesAbrirForm(id){
  if(!cadPodeEditarCargos()){ if(typeof progShowToast==='function') progShowToast('Sem permissão para vincular teste.','erro'); return; }
  var box=document.getElementById('rh-cargo-testes-form');
  if(!box){ if(typeof progShowToast==='function') progShowToast('Área de vínculo não encontrada. Reabra a aba Testes e Avaliações.','erro'); return; }
  var row=id?(_rhCargoTestes.lista||[]).filter(function(x){ return String(x.id)===String(id); })[0]:null;
  _rhCargoTestes.form=row?{id:row.id}:{};
  var publicados=rhCargoTestesPublicados();
  var opts=publicados.filter(function(t){
    if(row && String(t.id)===String(row.teste_id)) return true;
    return !rhCargoTestesJaVinculado(t);
  }).map(function(t){
    return '<option value="'+escHtml(rhCargoTestesTxt(t.id))+'"'+(row&&String(row.teste_id)===String(t.id)?' selected':'')+'>'
      +escHtml(rhCargoTestesTxt(t.nome||t.codigo)+' · '+rhCargoTestesTxt(t.codigo)+' · v'+rhCargoTestesTxt(t.versao||1))+'</option>';
  }).join('');
  var ordPadrao=row&&row.ordem!=null?row.ordem:(((_rhCargoTestes.lista||[]).length||0)+1);
  box.innerHTML='<div id="rh-cargo-testes-form-box" style="border:.5px solid #e8e6df;border-radius:10px;padding:10px;margin-bottom:10px;background:#fafaf7">'
    +'<div style="font-weight:700;margin-bottom:8px">'+(row?'Editar regra do vínculo':'+ Vincular teste do Banco')+'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px">'
    +'<div style="grid-column:1/-1"><label style="font-size:11px">Teste (ativos / aptos)</label><select class="inp" id="cg-ct-teste"'+(row?' disabled':'')+'>'
    +'<option value="">Selecione…</option>'+(opts||'<option value="" disabled>Nenhum teste disponível</option>')+'</select></div>'
    +'<div><label style="font-size:11px">Obrigatório</label><select class="inp" id="cg-ct-obrig"><option value="1"'+( !row||row.obrigatorio!==false?' selected':'')+'>Sim</option><option value="0"'+(row&&row.obrigatorio===false?' selected':'')+'>Não</option></select></div>'
    +'<div><label style="font-size:11px">Eliminatório</label><select class="inp" id="cg-ct-elim"><option value="0"'+( !row||!row.eliminatorio?' selected':'')+'>Não</option><option value="1"'+(row&&row.eliminatorio?' selected':'')+'>Sim</option></select></div>'
    +'<div><label style="font-size:11px">Nota mínima (%)</label><input class="inp" id="cg-ct-nota" type="number" min="0" max="100" step="1" value="'+escHtml(rhCargoTestesTxt(row&&row.nota_minima))+'"/></div>'
    +'<div><label style="font-size:11px">Tentativas</label><input class="inp" id="cg-ct-tent" type="number" min="1" value="'+escHtml(rhCargoTestesTxt(row&&row.tentativas_maximas!=null?row.tentativas_maximas:1))+'"/></div>'
    +'<div><label style="font-size:11px">Ordem</label><input class="inp" id="cg-ct-ord" type="number" min="1" value="'+escHtml(rhCargoTestesTxt(ordPadrao))+'"/></div>'
    +'<div><label style="font-size:11px">Etapa</label><select class="inp" id="cg-ct-etapa">'
    +[['ANTES_ENTREVISTA','Antes da entrevista'],['APOS_ENTREVISTA','Após a entrevista'],['OUTRA','Outra']].map(function(p){
      return '<option value="'+p[0]+'"'+(row&&row.etapa_processo===p[0]?' selected':'')+'>'+p[1]+'</option>';
    }).join('')+'</select></div>'
    +'<div><label style="font-size:11px">Ativo</label><select class="inp" id="cg-ct-ativo"><option value="1"'+( !row||row.ativo!==false?' selected':'')+'>Sim</option><option value="0"'+(row&&row.ativo===false?' selected':'')+'>Não</option></select></div>'
    +'</div><div style="margin-top:8px"><button type="button" class="btn btn-pri" onclick="rhCargoTestesSalvarForm()">Salvar vínculo</button> '
    +'<button type="button" class="btn" onclick="_rhCargoTestes.form=null;rhCargoTestesRender()">Cancelar</button></div></div>';
  try{ box.scrollIntoView({block:'nearest'}); }catch(e){}
}
function rhCargoTestesSalvarForm(){
  if(!cadPodeEditarCargos()) return;
  var cid=_cadCargoEditId; if(!cid) return;
  var editId=_rhCargoTestes.form&&_rhCargoTestes.form.id;
  var testeId=((document.getElementById('cg-ct-teste')||{}).value)||'';
  if(!testeId){ progShowToast('Selecione um teste ativo do Banco.','erro'); return; }
  var t=_rhCargoTestes.byId[String(testeId)];
  if(!editId && t && rhCargoTestesJaVinculado(t)){ progShowToast('Este teste já está vinculado e ativo neste cargo.','erro'); return; }
  var nota=((document.getElementById('cg-ct-nota')||{}).value);
  var tent=parseInt((document.getElementById('cg-ct-tent')||{}).value,10);
  var ord=parseInt((document.getElementById('cg-ct-ord')||{}).value,10);
  var payload={
    cargo_id:String(cid),
    teste_id:testeId,
    obrigatorio:((document.getElementById('cg-ct-obrig')||{}).value)!=='0',
    eliminatorio:((document.getElementById('cg-ct-elim')||{}).value)==='1',
    nota_minima:(nota===''||nota==null)?null:Number(nota),
    tentativas_maximas:(tent>=1)?tent:1,
    ordem:(ord>=1)?ord:1,
    etapa_processo:((document.getElementById('cg-ct-etapa')||{}).value)||'ANTES_ENTREVISTA',
    ativo:((document.getElementById('cg-ct-ativo')||{}).value)!=='0',
    atualizado_em:new Date().toISOString(),
    criado_por:rhCargoTestesQuem()
  };
  function ok(){
    _rhCargoTestes.form=null;
    if(typeof auditLog==='function') auditLog('editar','rh',(editId?'Editou':'Vinculou')+' teste do cargo '+cid,{teste_id:testeId});
    progShowToast('Vínculo salvo.');
    rhCargoTestesRender();
  }
  if(editId){
    delete payload.teste_id; delete payload.cargo_id; delete payload.criado_por;
    sbUpdate('rh_cargo_testes',payload,'id=eq.'+editId).then(function(r){
      if(!r){ progShowToast('Falha ao atualizar. '+rhCargoTestesSqlHint(),'erro'); return; }
      ok();
    });
  } else {
    payload.criado_em=new Date().toISOString();
    sbInsert('rh_cargo_testes',payload).then(function(r){
      if(!r||!r[0]){ progShowToast('Falha ao vincular. '+rhCargoTestesSqlHint(),'erro'); return; }
      ok();
    });
  }
}
function rhCargoTestesDesativar(id){
  if(!cadPodeEditarCargos()) return;
  sbUpdate('rh_cargo_testes',{ativo:false,atualizado_em:new Date().toISOString()},'id=eq.'+id).then(function(r){
    if(!r){ progShowToast('Não foi possível desativar.','erro'); return; }
    progShowToast('Vínculo desativado.');
    rhCargoTestesRender();
  });
}
function rhCargoTestesRemover(id){
  if(!cadPodeEditarCargos()) return;
  var row=(_rhCargoTestes.lista||[]).filter(function(x){ return String(x.id)===String(id); })[0];
  if(!row) return;
  if(!confirm('Remover este vínculo do cargo? Vagas já abertas mantêm o snapshot. Histórico não é apagado.')) return;
  var cargoId=row.cargo_id;
  var testeId=row.teste_id;
  sbFetch('rh_vaga_testes',{filters:['teste_id=eq.'+testeId,'cargo_id=eq.'+cargoId,'ativo=eq.true'],limit:1}).then(function(uso){
    if(uso===null){ progShowToast(rhCargoTestesSqlHint(),'erro'); return; }
    if(uso&&uso.length){
      progShowToast('Já usado em vaga. O vínculo foi só desativado (histórico preservado).');
      return rhCargoTestesDesativar(id);
    }
    return sbFetch('rh_teste_tentativas',{filters:['teste_id=eq.'+testeId],limit:1}).then(function(tents){
      if(tents&&tents.length){
        progShowToast('Já há tentativas deste teste. O vínculo foi só desativado.');
        return rhCargoTestesDesativar(id);
      }
      return fetch(SB.url+'/rest/v1/rh_cargo_testes?id=eq.'+id,{
        method:'DELETE',
        headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key),'Prefer':'return=minimal'}
      }).then(function(r){
        if(!r.ok){ return rhCargoTestesDesativar(id); }
        if(typeof auditLog==='function') auditLog('excluir','rh','Removeu vínculo teste-cargo',{id:id,teste_id:testeId});
        progShowToast('Vínculo removido.');
        rhCargoTestesRender();
      });
    });
  });
}
function rhCargoTestesReordenar(id, dir){
  if(!cadPodeEditarCargos()) return;
  var rows=(_rhCargoTestes.lista||[]).slice().sort(function(a,b){ return (a.ordem||0)-(b.ordem||0); });
  var i=rows.findIndex(function(x){ return String(x.id)===String(id); });
  var j=i+(dir>0?1:-1);
  if(i<0||j<0||j>=rows.length) return;
  var a=rows[i], b=rows[j];
  var oa=a.ordem||(i+1), ob=b.ordem||(j+1);
  Promise.all([
    sbUpdate('rh_cargo_testes',{ordem:ob,atualizado_em:new Date().toISOString()},'id=eq.'+a.id),
    sbUpdate('rh_cargo_testes',{ordem:oa,atualizado_em:new Date().toISOString()},'id=eq.'+b.id)
  ]).then(function(){ rhCargoTestesRender(); });
}
function rhCargoTestesVer(testeId){
  _rhCargoTestes.verId=testeId;
  var box=document.getElementById('rh-cargo-testes-ver'); if(!box) return;
  var t=_rhCargoTestes.byId[String(testeId)]||{};
  box.innerHTML='<div style="margin-top:10px;padding:10px;border:.5px solid #eee;border-radius:8px"><div style="font-weight:700;margin-bottom:6px">'+escHtml(t.nome||'Teste')+'</div><div style="color:#888">Carregando questões (sem gabarito)…</div></div>';
  Promise.all([
    sbFetch('rh_teste_questoes',{filters:['teste_id=eq.'+testeId,'ativo=eq.true'],order:'ordem.asc'}),
    sbFetch('rh_teste_alternativas',{filters:['ativo=eq.true'],limit:400})
  ]).then(function(arr){
    var qs=arr[0]||[];
    var alts=arr[1]||[];
    box.innerHTML='<div style="margin-top:10px;padding:10px;border:.5px solid #eee;border-radius:8px">'
      +'<div style="font-weight:700;margin-bottom:6px">'+escHtml(t.nome||'Teste')+' · '+escHtml(t.codigo||'')+(t.versao?' · v'+t.versao:'')+'</div>'
      +(qs.map(function(q){
        var op=alts.filter(function(a){ return String(a.questao_id)===String(q.id); }).sort(function(a,b){ return (a.ordem||0)-(b.ordem||0); });
        return '<div style="margin-bottom:8px"><div>'+escHtml(q.ordem)+'. '+escHtml(q.enunciado)+'</div>'
          +'<ul style="margin:4px 0 0 18px;font-size:12px">'+op.map(function(a){ return '<li>'+escHtml(a.texto)+'</li>'; }).join('')+'</ul></div>';
      }).join('')||'<div style="color:#aaa">Sem questões neste teste.</div>')
      +'<button type="button" class="btn btn-sm" onclick="_rhCargoTestes.verId=null;var e=document.getElementById(\'rh-cargo-testes-ver\');if(e)e.innerHTML=\'\'">Fechar visualização</button></div>';
  });
}
var _rhMatriz = {cargoId:null, header:null, cnh:[], nrs:[], cursos:[], docs:[], testes:[], soLeitura:false};
var RH_MATRIZ_NIVEIS = [
  {v:'OBRIGATORIO', l:'Obrigatório'},
  {v:'DESEJAVEL', l:'Desejável'},
  {v:'NAO_SE_APLICA', l:'Não se aplica'}
];
var RH_MATRIZ_CNH = ['A','B','C','D','E','AB','AC','AD','AE'];
var RH_MATRIZ_TESTES = [
  {v:'TECNICO', l:'Técnico'},
  {v:'SEGURANCA', l:'Segurança'},
  {v:'PORTUGUES', l:'Português / Interpretação'},
  {v:'RACIOCINIO', l:'Raciocínio'},
  {v:'EXCEL', l:'Excel'},
  {v:'ESPECIFICO', l:'Conhecimento específico'},
  {v:'SITUACIONAL', l:'Perfil Comportamental e Raciocínio Situacional'}
];
var RH_MATRIZ_MOMENTO = [
  {v:'SELECAO', l:'Seleção'},
  {v:'PRE_ADMISSAO', l:'Pré-admissão'},
  {v:'ADMISSAO', l:'Admissão'},
  {v:'ANTES_INICIO', l:'Antes do início da atividade'},
  {v:'CONTINUO', l:'Contínuo'}
];
function rhMatrizBadgeHtml(cargoId){
  var st=_rhMatrizStatus[String(cargoId)]||'NAO_CONFIGURADA';
  var map={NAO_CONFIGURADA:['#FFF4E5','#854F0B','NÃO CONFIGURADOS'],EM_CONFIGURACAO:['#E8F0FE','#185FA5','EM CONFIGURAÇÃO'],APROVADA:['#EAF3DE','#3B6D11','APROVADOS']};
  var m=map[st]||map.NAO_CONFIGURADA;
  return '<span style="background:'+m[0]+';color:'+m[1]+';border-radius:4px;padding:1px 6px;font-size:10px;white-space:nowrap">'+m[2]+'</span>';
}
function rhMatrizNivelHtml(sel, id, onchangeAttr){
  return '<select class="inp" id="'+id+'" style="width:140px"'+(onchangeAttr?' onchange="'+onchangeAttr+'"':'')+'>'
    +RH_MATRIZ_NIVEIS.map(function(n){return '<option value="'+n.v+'"'+(sel===n.v?' selected':'')+'>'+n.l+'</option>';}).join('')
    +'</select>';
}
function rhMatrizNivelLabel(v){
  var n=RH_MATRIZ_NIVEIS.filter(function(x){return x.v===v;})[0];
  return n?n.l:(v||'—');
}
function rhMatrizMomentoHtml(sel, id, onchangeAttr){
  sel=sel||'ADMISSAO';
  return '<select class="inp" id="'+id+'" style="width:160px"'+(onchangeAttr?' onchange="'+onchangeAttr+'"':'')+'>'
    +RH_MATRIZ_MOMENTO.map(function(n){return '<option value="'+n.v+'"'+(sel===n.v?' selected':'')+'>'+n.l+'</option>';}).join('')
    +'</select>';
}
/** Persiste alteração de nível/momento em linha já gravada (não depende do select de inclusão). */
function rhMatrizAlterarCampo(tabela, id, listaKey, campo, el){
  if(_rhMatriz.soLeitura||!el) return;
  var val=String(el.value||'').trim();
  if(!val) return;
  var lista=_rhMatriz[listaKey]||[];
  var row=lista.find(function(x){return String(x.id)===String(id);});
  if(!row) return;
  var antes=row[campo];
  if(String(antes||'')===val) return;
  var patch={}; patch[campo]=val;
  function okLocal(){
    row[campo]=val;
    var reabriu=false;
    if(_rhMatriz.header && _rhMatriz.header.status==='APROVADA'){
      var p={status:'EM_CONFIGURACAO',aprovado_em:null,aprovado_por:null,updated_at:new Date().toISOString()};
      if(!DEMO && _rhMatriz.header.id) sbUpdate('rh_cargo_requisitos',p,'id=eq.'+_rhMatriz.header.id);
      Object.assign(_rhMatriz.header,p);
      _rhMatrizStatus[_rhMatriz.cargoId]='EM_CONFIGURACAO';
      if(typeof rhProntidaoSincronizarMatrizStatus==='function') rhProntidaoSincronizarMatrizStatus(_rhMatriz.cargoId,'EM_CONFIGURACAO');
      if(typeof rhProntidaoInvalidate==='function') rhProntidaoInvalidate({catalogo:true});
      reabriu=true;
    }
    rhMatrizAudit('ALTEROU_REQUISITO '+campo,{tabela:tabela,id:id,anterior:antes,novo:val});
    progShowToast('✅ Nível/momento atualizado.');
    if(reabriu) rhMatrizRender();
  }
  if(DEMO){ okLocal(); return; }
  Promise.resolve(sbUpdate(tabela,patch,'id=eq.'+id)).then(function(ok){
    if(ok===false){
      el.value=antes||'OBRIGATORIO';
      progShowToast('❌ Não gravou a alteração. Verifique o banco.','erro');
      return;
    }
    okLocal();
  });
}
function rhMatrizAudit(acao, extra){
  if(typeof auditLog!=='function') return;
  auditLog('editar','rh',acao, Object.assign({tabela:'rh_cargo_requisitos', cargo_id:_rhMatriz.cargoId}, extra||{}));
}
function rhMatrizAbrir(cargoId, soLeitura){
  var seq=++_rhMatrizLoadSeq;
  _rhMatriz={cargoId:String(cargoId), header:null, cnh:[], nrs:[], cursos:[], docs:[], testes:[], soLeitura:!!soLeitura, _loadSeq:seq, draftAdd:null};
  var wrap=document.getElementById('rh-matriz-wrap');
  if(!wrap) return;
  function depois(){ if(seq!==_rhMatrizLoadSeq) return; rhMatrizRender(); }
  if(DEMO){ depois(); return; }
  var f=['cargo_id=eq.'+encodeURIComponent(cargoId)];
  Promise.all([
    sbFetch('rh_cargo_requisitos',{filters:f}),
    sbFetch('rh_cargo_requisitos_cnh',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_nrs',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_treinamentos',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_documentos',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_testes',{filters:f.concat(['ativo=eq.true'])})
  ]).then(function(arr){
    if(seq!==_rhMatrizLoadSeq) return;
    if(arr[0]===null){
      var w=document.getElementById('rh-matriz-wrap');
      if(w) w.innerHTML='<div style="color:#A32D2D">Tabelas da matriz indisponíveis. Aplique <b>sql_rh_matriz_requisitos_cargo_fase1b.sql</b> no Supabase.</div>';
      return;
    }
    _rhMatriz.header=(arr[0]&&arr[0][0])||null;
    _rhMatriz.cnh=arr[1]||[]; _rhMatriz.nrs=arr[2]||[]; _rhMatriz.cursos=arr[3]||[];
    _rhMatriz.docs=arr[4]||[]; _rhMatriz.testes=arr[5]||[];
    return rhMatrizGarantirCatalogos();
  }).then(depois).catch(function(){
    if(seq!==_rhMatrizLoadSeq) return;
    wrap.innerHTML='<div style="color:#A32D2D">Tabelas da matriz indisponíveis. Aplique <b>sql_rh_matriz_requisitos_cargo_fase1b.sql</b> no Supabase.</div>';
  });
}
var _rhMatrizLoadSeq=0;
function rhMatrizRecarregarDoBanco(){
  var cargoId=_rhMatriz.cargoId;
  if(!cargoId) return Promise.resolve(false);
  if(DEMO){ rhMatrizRender(); return Promise.resolve(true); }
  var seq=++_rhMatrizLoadSeq;
  _rhMatriz._loadSeq=seq;
  var f=['cargo_id=eq.'+encodeURIComponent(cargoId)];
  return Promise.all([
    sbFetch('rh_cargo_requisitos',{filters:f}),
    sbFetch('rh_cargo_requisitos_cnh',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_nrs',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_treinamentos',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_documentos',{filters:f.concat(['ativo=eq.true'])}),
    sbFetch('rh_cargo_requisitos_testes',{filters:f.concat(['ativo=eq.true'])})
  ]).then(function(arr){
    if(seq!==_rhMatrizLoadSeq) return false;
    if(arr[0]===null) return false;
    if(arr[0]&&arr[0][0]) _rhMatriz.header=arr[0][0];
    _rhMatriz.cnh=arr[1]||[]; _rhMatriz.nrs=arr[2]||[]; _rhMatriz.cursos=arr[3]||[];
    _rhMatriz.docs=arr[4]||[]; _rhMatriz.testes=arr[5]||[];
    rhMatrizRender();
    return true;
  }).catch(function(){ return false; });
}
function rhMatrizGarantirCatalogos(){
  var jobs=[];
  if(!_cad_cursos.length && !DEMO) jobs.push(sbFetch('sesmt_cursos',{order:'nome.asc'}).then(function(r){ if(r)_cad_cursos=r; }).catch(function(){}));
  if(!_cad_normas.length && !DEMO) jobs.push(sbFetch('sesmt_normas',{order:'codigo.asc'}).then(function(r){ if(r)_cad_normas=r; }).catch(function(){}));
  if(typeof rhCarregarRegras==='function') jobs.push(rhCarregarRegras().catch(function(){}));
  return Promise.all(jobs);
}
function rhMatrizDocTipos(){
  var seen={}, out=[];
  (_rhRegras||[]).forEach(function(r){
    var t=(r.tipo_documento||'').trim(); if(!t||seen[t.toLowerCase()]) return;
    seen[t.toLowerCase()]=true; out.push({id:r.id, tipo:t});
  });
  return out.sort(function(a,b){return a.tipo.localeCompare(b.tipo,'pt-BR');});
}
function rhMatrizNormaLabel(id){
  var n=(_cad_normas||[]).find(function(x){return String(x.id)===String(id);});
  return n?((n.codigo||'')+' — '+(n.nome||'')):id;
}
function rhMatrizCursoLabel(id){
  var c=(_cad_cursos||[]).find(function(x){return String(x.id)===String(id);});
  return c?((c.sigla?c.sigla+' — ':'')+(c.nome||'')):id;
}
function rhMatrizDocLabel(id){
  var d=(_rhRegras||[]).find(function(x){return String(x.id)===String(id);});
  return d?(d.tipo_documento||id):id;
}
function rhMatrizRender(){
  var wrap=document.getElementById('rh-matriz-wrap'); if(!wrap) return;
  var h=_rhMatriz.header||{};
  var st=h.status||'NAO_CONFIGURADA';
  var dis=_rhMatriz.soLeitura?' disabled':'';
  var hid=function(v){ return v?' checked':''; };
  var nomeCargo=(typeof rhMatrizCargoNome==='function'?rhMatrizCargoNome():'')||(typeof cadCargoNomeEdicao==='function'?cadCargoNomeEdicao():'');
  wrap.innerHTML=(nomeCargo?'<div style="font-size:15px;font-weight:700;color:#185FA5;margin-bottom:.45rem">'+escHtml(nomeCargo)+'</div>':'')
    +'<div style="font-size:11px;color:#666;margin-bottom:.6rem">Define o que este cargo exige. A prontidão (RH-1C) consome somente matriz <b>APROVADA</b>. Não libera colaborador para campo e não substitui o SESMT.</div>'
    +'<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.6rem .7rem;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.35rem">1. SITUAÇÃO DA MATRIZ</div>'
    +rhMatrizBadgeHtml(_rhMatriz.cargoId)
    +(h.aprovado_em?'<div style="font-size:10px;color:#888;margin-top:4px">Aprovada em '+escHtml(String(h.aprovado_em).slice(0,16).replace('T',' '))+(h.aprovado_por?' · '+escHtml(h.aprovado_por):'')+'</div>':'')
    +(!_rhMatriz.soLeitura?'<div style="margin-top:.45rem;display:flex;gap:6px;flex-wrap:wrap">'
      +'<button class="btn btn-sm btn-pri" onclick="rhMatrizSalvarTudo()">💾 Salvar matriz</button>'
      +(st!=='APROVADA'?'<button class="btn btn-sm" onclick="rhMatrizAprovar()">Aprovar matriz</button>':'<button class="btn btn-sm" onclick="rhMatrizReabrir()">Reabrir para configuração</button>')
      +'<button class="btn btn-sm" style="color:#185FA5;border-color:#185FA5" onclick="rhMatrizAbrirImportSesmt()">⬇ Importar do SESMT</button>'
      +'</div>':'')
    +'<div style="font-size:10px;color:#888;margin-top:6px"><b>Salvar matriz</b> grava regime, CNH/NR/treinamentos/docs/testes pendentes na linha de inclusão e os níveis das linhas já listadas. O botão do rodapé “Salvar dados do cargo” <b>não</b> grava requisitos. Import SESMT: trilha + docs do checklist — depois inative ou inclua extras.</div>'
    +'</div>'
    +'<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.6rem .7rem;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.35rem">2. HABILITAÇÕES — CNH</div>'
    +'<label style="font-size:12px"><input type="checkbox" id="mx-exige-cnh"'+hid(h.exige_cnh)+dis+'/> Exige CNH</label>'
    +'<div style="font-size:10px;color:#888;margin:4px 0 6px">Para gravar: escolha a <b>categoria</b> (A, B…) + nível e clique <b>Salvar matriz</b> (ou + CNH). Para mudar o nível de uma CNH já listada, use o select <b>na linha da tabela</b> (ou o nível da inclusão se não estiver adicionando outra).</div>'
    +rhMatrizTabela(_rhMatriz.cnh, function(r){
      var rid=String(r.id||'').replace(/'/g,'');
      return '<td>'+escHtml(r.categoria)+'</td><td>'
        +(_rhMatriz.soLeitura?escHtml(rhMatrizNivelLabel(r.nivel_exigencia))
          :rhMatrizNivelHtml(r.nivel_exigencia||'OBRIGATORIO','mx-nv-cnh-'+rid,
            'rhMatrizAlterarCampo(\'rh_cargo_requisitos_cnh\',\''+rid+'\',\'cnh\',\'nivel_exigencia\',this)'))
        +'</td><td>'+escHtml(r.observacao||'—')+'</td>'
        +(!_rhMatriz.soLeitura?'<td><button class="btn btn-sm" onclick="rhMatrizInativar(\'rh_cargo_requisitos_cnh\',\''+rid+'\',\'cnh\')">Inativar</button></td>':'<td></td>');
    }, ['Categoria','Nível','Obs.',''])
    +(!_rhMatriz.soLeitura?rhMatrizLinhaAdd('cnh'):'')
    +'</div>'
    +'<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.6rem .7rem;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.35rem">3. SAÚDE OCUPACIONAL</div>'
    +'<label style="font-size:12px"><input type="checkbox" id="mx-exige-aso"'+hid(h.exige_aso)+dis+'/> ASO / validação ocupacional obrigatória</label>'
    +'<div style="font-size:10px;color:#888;margin-top:4px">Não define exames clínicos. Apenas se o cargo exige ASO.</div>'
    +'</div>'
    +'<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.6rem .7rem;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.35rem">4. SEGURANÇA E TREINAMENTOS</div>'
    +'<div style="font-size:11px;font-weight:600;margin:.3rem 0">NRs (catálogo sesmt_normas)</div>'
    +rhMatrizTabela(_rhMatriz.nrs, function(r){
      var rid=String(r.id||'').replace(/'/g,'');
      return '<td>'+escHtml(rhMatrizNormaLabel(r.norma_id))+'</td><td>'
        +(_rhMatriz.soLeitura?escHtml(rhMatrizNivelLabel(r.nivel_exigencia))
          :rhMatrizNivelHtml(r.nivel_exigencia||'OBRIGATORIO','mx-nv-nr-'+rid,
            'rhMatrizAlterarCampo(\'rh_cargo_requisitos_nrs\',\''+rid+'\',\'nrs\',\'nivel_exigencia\',this)'))
        +'</td>'
        +(!_rhMatriz.soLeitura?'<td><button class="btn btn-sm" onclick="rhMatrizInativar(\'rh_cargo_requisitos_nrs\',\''+rid+'\',\'nrs\')">Inativar</button></td>':'<td></td>');
    }, ['NR','Nível',''])
    +(!_rhMatriz.soLeitura?rhMatrizLinhaAdd('nr'):'')
    +'<div style="font-size:11px;font-weight:600;margin:.6rem 0 .3rem">Treinamentos (catálogo sesmt_cursos)</div>'
    +rhMatrizTabela(_rhMatriz.cursos, function(r){
      var rid=String(r.id||'').replace(/'/g,'');
      return '<td>'+escHtml(rhMatrizCursoLabel(r.curso_id))+'</td><td>'
        +(_rhMatriz.soLeitura?escHtml(rhMatrizNivelLabel(r.nivel_exigencia))
          :rhMatrizNivelHtml(r.nivel_exigencia||'OBRIGATORIO','mx-nv-curso-'+rid,
            'rhMatrizAlterarCampo(\'rh_cargo_requisitos_treinamentos\',\''+rid+'\',\'cursos\',\'nivel_exigencia\',this)'))
        +'</td>'
        +(!_rhMatriz.soLeitura?'<td><button class="btn btn-sm" onclick="rhMatrizInativar(\'rh_cargo_requisitos_treinamentos\',\''+rid+'\',\'cursos\')">Inativar</button></td>':'<td></td>');
    }, ['Treinamento','Nível',''])
    +(!_rhMatriz.soLeitura?rhMatrizLinhaAdd('curso'):'')
    +'</div>'
    +'<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.6rem .7rem;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.35rem">5. DOCUMENTAÇÃO (rh_documentos_obrigatorios)</div>'
    +rhMatrizTabela(_rhMatriz.docs, function(r){
      var rid=String(r.id||'').replace(/'/g,'');
      var mom=RH_MATRIZ_MOMENTO.filter(function(x){return x.v===r.momento_exigencia;})[0];
      return '<td>'+escHtml(rhMatrizDocLabel(r.tipo_documento_id))+'</td><td>'
        +(_rhMatriz.soLeitura?escHtml(rhMatrizNivelLabel(r.nivel_exigencia))
          :rhMatrizNivelHtml(r.nivel_exigencia||'OBRIGATORIO','mx-nv-doc-'+rid,
            'rhMatrizAlterarCampo(\'rh_cargo_requisitos_documentos\',\''+rid+'\',\'docs\',\'nivel_exigencia\',this)'))
        +'</td><td>'
        +(_rhMatriz.soLeitura?escHtml(mom?mom.l:(r.momento_exigencia||'—'))
          :rhMatrizMomentoHtml(r.momento_exigencia||'ADMISSAO','mx-mom-doc-'+rid,
            'rhMatrizAlterarCampo(\'rh_cargo_requisitos_documentos\',\''+rid+'\',\'docs\',\'momento_exigencia\',this)'))
        +'</td>'
        +(!_rhMatriz.soLeitura?'<td><button class="btn btn-sm" onclick="rhMatrizInativar(\'rh_cargo_requisitos_documentos\',\''+rid+'\',\'docs\')">Inativar</button></td>':'<td></td>');
    }, ['Documento','Nível','Momento',''])
    +(!_rhMatriz.soLeitura?rhMatrizLinhaAdd('doc'):'')
    +'</div>'
    +'<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.6rem .7rem;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.35rem">6. REGIME</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    +'<div class="fg"><label style="font-size:11px">Jornada / regime (padrão do cargo)</label><select class="inp" id="mx-regime"'+dis+'>'
    +rhMatrizOptRegime(h.regime_jornada)+'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Regime de benefício (padrão)</label><select class="inp" id="mx-beneficio"'+dis+'>'
    +rhMatrizOptRegime(h.regime_beneficio)+'</select></div></div>'
    +'<label style="font-size:12px;display:block;margin-top:.4rem"><input type="checkbox" id="mx-confianca"'+hid(h.cargo_confianca)+dis+'/> Cargo de confiança (característica do cargo; não altera ponto/folha)</label>'
    +'</div>'
    +'<div style="border:.5px solid #e8e8e4;border-radius:8px;padding:.6rem .7rem;margin-bottom:.6rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.35rem">7. SELEÇÃO — testes (preparatório)</div>'
    +'<label style="font-size:12px"><input type="checkbox" id="mx-exige-teste"'+hid(h.exige_teste_aptidao)+dis+'/> Exige teste de aptidão</label>'
    +'<div style="font-size:10px;color:#888;margin:4px 0">Não cria perguntas nem aplica testes (RH-SEL-1D).</div>'
    +rhMatrizTabela(_rhMatriz.testes, function(r){
      var rid=String(r.id||'').replace(/'/g,'');
      var p=RH_MATRIZ_TESTES.filter(function(x){return x.v===r.perfil;})[0];
      return '<td>'+escHtml(p?p.l:r.perfil)+'</td><td>'
        +(_rhMatriz.soLeitura?escHtml(rhMatrizNivelLabel(r.nivel_exigencia))
          :rhMatrizNivelHtml(r.nivel_exigencia||'OBRIGATORIO','mx-nv-teste-'+rid,
            'rhMatrizAlterarCampo(\'rh_cargo_requisitos_testes\',\''+rid+'\',\'testes\',\'nivel_exigencia\',this)'))
        +'</td>'
        +(!_rhMatriz.soLeitura?'<td><button class="btn btn-sm" onclick="rhMatrizInativar(\'rh_cargo_requisitos_testes\',\''+rid+'\',\'testes\')">Inativar</button></td>':'<td></td>');
    }, ['Perfil','Nível',''])
    +(!_rhMatriz.soLeitura?rhMatrizLinhaAdd('teste'):'')
    +'</div>'
    +'<div class="fg"><label style="font-size:11px;font-weight:500">8. Observações</label>'
    +'<textarea class="inp" id="mx-obs" rows="3" style="width:100%;resize:vertical"'+dis+'>'+escHtml(h.observacoes||'')+'</textarea></div>';
}
function rhMatrizOptRegime(sel){
  var opts=[['','—'],['ponto','Ponto'],['dias_uteis','Dias úteis'],['escala','Escala'],['fixo','Fixo'],['especial','Especial']];
  return opts.map(function(o){return '<option value="'+o[0]+'"'+(sel===o[0]?' selected':'')+'>'+o[1]+'</option>';}).join('');
}
function rhMatrizTabela(lista, cellFn, cols){
  if(!lista||!lista.length) return '<div style="font-size:11px;color:#aaa;margin:.3rem 0">Nenhum item.</div>';
  return '<table class="tbl" style="margin:.35rem 0"><thead><tr>'+cols.map(function(c){return '<th>'+c+'</th>';}).join('')+'</tr></thead><tbody>'
    +lista.map(function(r){ return '<tr>'+cellFn(r)+'</tr>'; }).join('')+'</tbody></table>';
}
function rhMatrizLinhaAdd(tipo){
  var d=_rhMatriz.draftAdd||{};
  function nvHtml(id, draftKey){
    return rhMatrizNivelHtml(d[draftKey]||'OBRIGATORIO', id);
  }
  if(tipo==='cnh'){
    return '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:end;margin-top:.35rem">'
      +'<select class="inp" id="mx-add-cnh-cat" style="width:110px"><option value="">— CNH —</option>'
      +RH_MATRIZ_CNH.map(function(x){return '<option value="'+x+'"'+(d.cnhCat===x?' selected':'')+'>'+x+'</option>';}).join('')+'</select>'
      +nvHtml('mx-add-cnh-nv','cnhNv')
      +'<button class="btn btn-sm" onclick="rhMatrizAddCnh()">+ CNH</button></div>';
  }
  if(tipo==='nr'){
    var nrs=(_cad_normas||[]).filter(function(n){return n.ativa!==false;});
    return '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:end;margin-top:.35rem">'
      +'<select class="inp" id="mx-add-nr" style="min-width:220px"><option value="">— NR —</option>'
      +(nrs.length?nrs.map(function(n){return '<option value="'+escHtml(String(n.id))+'"'+(String(d.nrId||'')===String(n.id)?' selected':'')+'>'+escHtml((n.codigo||'')+' — '+(n.nome||''))+'</option>';}).join(''):'<option value="">Cadastre normas em Cadastros → Normas</option>')+'</select>'
      +nvHtml('mx-add-nr-nv','nrNv')
      +'<button class="btn btn-sm" onclick="rhMatrizAddNr()">+ NR</button></div>';
  }
  if(tipo==='curso'){
    var jaCurso={};
    (_rhMatriz.cursos||[]).forEach(function(x){ if(x&&x.curso_id) jaCurso[String(x.curso_id)]=true; });
    var csAll=(_cad_cursos||[]).filter(function(c){return c.status!=='Inativo';});
    var cs=csAll.filter(function(c){ return !jaCurso[String(c.id)]; });
    if(d.cursoId && jaCurso[String(d.cursoId)]) d.cursoId='';
    var cursoOpts=!csAll.length
      ? '<option value="">Cadastre cursos em Cadastros → Cursos</option>'
      : (!cs.length
        ? '<option value="">Todos os treinamentos já estão na matriz</option>'
        : cs.map(function(c){return '<option value="'+escHtml(String(c.id))+'"'+(String(d.cursoId||'')===String(c.id)?' selected':'')+'>'+escHtml((c.sigla?c.sigla+' — ':'')+(c.nome||''))+'</option>';}).join(''));
    return '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:end;margin-top:.35rem">'
      +'<select class="inp" id="mx-add-curso" style="min-width:240px"><option value="">— Treinamento —</option>'
      +cursoOpts+'</select>'
      +nvHtml('mx-add-curso-nv','cursoNv')
      +'<button class="btn btn-sm" onclick="rhMatrizAddCurso()">+ Treinamento</button></div>';
  }
  if(tipo==='doc'){
    var jaDocId={}, jaDocTipo={};
    (_rhMatriz.docs||[]).forEach(function(x){
      if(!x) return;
      if(x.tipo_documento_id) jaDocId[String(x.tipo_documento_id)]=true;
      var lab=rhMatrizDocLabel(x.tipo_documento_id);
      if(lab) jaDocTipo[String(lab).toLowerCase()]=true;
    });
    var dsAll=rhMatrizDocTipos();
    var ds=dsAll.filter(function(doc){
      return !jaDocId[String(doc.id)] && !jaDocTipo[String(doc.tipo||'').toLowerCase()];
    });
    if(d.docId && (jaDocId[String(d.docId)] || jaDocTipo[String(rhMatrizDocLabel(d.docId)||'').toLowerCase()])) d.docId='';
    var docOpts=!dsAll.length
      ? '<option value="">Regras documentais RH indisponíveis</option>'
      : (!ds.length
        ? '<option value="">Todos os documentos já estão na matriz</option>'
        : ds.map(function(doc){return '<option value="'+escHtml(String(doc.id))+'"'+(String(d.docId||'')===String(doc.id)?' selected':'')+'>'+escHtml(doc.tipo)+'</option>';}).join(''));
    return '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:end;margin-top:.35rem">'
      +'<select class="inp" id="mx-add-doc" style="min-width:220px"><option value="">— Documento —</option>'
      +docOpts+'</select>'
      +nvHtml('mx-add-doc-nv','docNv')
      +'<select class="inp" id="mx-add-doc-mom" style="width:170px">'+RH_MATRIZ_MOMENTO.map(function(m){return '<option value="'+m.v+'"'+( (d.docMom||'SELECAO')===m.v?' selected':'')+'>'+m.l+'</option>';}).join('')+'</select>'
      +'<button class="btn btn-sm" onclick="rhMatrizAddDoc()">+ Documento</button></div>';
  }
  if(tipo==='teste'){
    return '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:end;margin-top:.35rem">'
      +'<select class="inp" id="mx-add-teste" style="min-width:200px"><option value="">— Perfil —</option>'
      +RH_MATRIZ_TESTES.map(function(t){return '<option value="'+t.v+'"'+(d.testeId===t.v?' selected':'')+'>'+t.l+'</option>';}).join('')+'</select>'
      +nvHtml('mx-add-teste-nv','testeNv')
      +'<button class="btn btn-sm" onclick="rhMatrizAddTeste()">+ Perfil de teste</button></div>';
  }
  return '';
}
function rhMatrizLerCab(){
  return {
    exige_cnh:!!(document.getElementById('mx-exige-cnh')||{}).checked,
    exige_aso:!!(document.getElementById('mx-exige-aso')||{}).checked,
    exige_teste_aptidao:!!(document.getElementById('mx-exige-teste')||{}).checked,
    cargo_confianca:!!(document.getElementById('mx-confianca')||{}).checked,
    regime_jornada:(document.getElementById('mx-regime')||{}).value||null,
    regime_beneficio:(document.getElementById('mx-beneficio')||{}).value||null,
    observacoes:((document.getElementById('mx-obs')||{}).value||'').trim()||null,
    updated_at:new Date().toISOString()
  };
}
function rhMatrizEnsureHeader(cb){
  if(_rhMatriz.header&&_rhMatriz.header.id){ if(cb)cb(_rhMatriz.header); return; }
  var payload=Object.assign({cargo_id:_rhMatriz.cargoId, status:'EM_CONFIGURACAO', ativo:true}, rhMatrizLerCab());
  if(DEMO){ payload.id='mx'+Date.now(); _rhMatriz.header=payload; if(cb)cb(payload); return; }
  sbInsert('rh_cargo_requisitos',payload).then(function(r){
    if(r&&r[0]){ _rhMatriz.header=r[0]; _rhMatrizStatus[_rhMatriz.cargoId]=r[0].status; if(cb)cb(r[0]); }
    else progShowToast('❌ Não gravou o cabeçalho da matriz. Rode o SQL da RH-1B.','erro');
  });
}
function rhMatrizSalvarCab(){
  // Compat: agora o botão principal usa rhMatrizSalvarTudo (cabeçalho + filhos).
  return rhMatrizSalvarTudo();
}
/** Grava cabeçalho (regime/exigências) + níveis das linhas + itens selecionados na inclusão. */
function rhMatrizSalvarTudo(){
  if(_rhMatriz.soLeitura) return Promise.resolve(false);
  // Captura o formulário ANTES de qualquer await/render (senão some categoria/nível na UI).
  var snap={
    cab:rhMatrizLerCab(),
    cnhCat:((document.getElementById('mx-add-cnh-cat')||{}).value||'').trim(),
    cnhNv:((document.getElementById('mx-add-cnh-nv')||{}).value)||'OBRIGATORIO',
    nrId:((document.getElementById('mx-add-nr')||{}).value||'').trim(),
    nrNv:((document.getElementById('mx-add-nr-nv')||{}).value)||'OBRIGATORIO',
    cursoId:((document.getElementById('mx-add-curso')||{}).value||'').trim(),
    cursoNv:((document.getElementById('mx-add-curso-nv')||{}).value)||'OBRIGATORIO',
    docId:((document.getElementById('mx-add-doc')||{}).value||'').trim(),
    docNv:((document.getElementById('mx-add-doc-nv')||{}).value)||'OBRIGATORIO',
    docMom:((document.getElementById('mx-add-doc-mom')||{}).value)||null,
    testeId:((document.getElementById('mx-add-teste')||{}).value||'').trim(),
    testeNv:((document.getElementById('mx-add-teste-nv')||{}).value)||'OBRIGATORIO',
    niveisCnh:{}, niveisNr:{}, niveisCurso:{}, niveisDoc:{}, momentosDoc:{}, niveisTeste:{}
  };
  (_rhMatriz.cnh||[]).forEach(function(r){
    var el=document.getElementById('mx-nv-cnh-'+r.id);
    if(el) snap.niveisCnh[String(r.id)]=el.value;
  });
  (_rhMatriz.nrs||[]).forEach(function(r){
    var el=document.getElementById('mx-nv-nr-'+r.id);
    if(el) snap.niveisNr[String(r.id)]=el.value;
  });
  (_rhMatriz.cursos||[]).forEach(function(r){
    var el=document.getElementById('mx-nv-curso-'+r.id);
    if(el) snap.niveisCurso[String(r.id)]=el.value;
  });
  (_rhMatriz.docs||[]).forEach(function(r){
    var el=document.getElementById('mx-nv-doc-'+r.id);
    if(el) snap.niveisDoc[String(r.id)]=el.value;
    var mom=document.getElementById('mx-mom-doc-'+r.id);
    if(mom) snap.momentosDoc[String(r.id)]=mom.value;
  });
  (_rhMatriz.testes||[]).forEach(function(r){
    var el=document.getElementById('mx-nv-teste-'+r.id);
    if(el) snap.niveisTeste[String(r.id)]=el.value;
  });

  if(snap.cab.exige_cnh && !snap.cnhCat && !(_rhMatriz.cnh||[]).length){
    progShowToast('⚠ Exige CNH está marcado: selecione a categoria (A, B, …) na linha de inclusão e salve de novo.','erro');
    return Promise.resolve(false);
  }

  // Atalho UX: nível da linha de inclusão (ex.: Não se aplica) sem novo item
  // → aplica nas linhas JÁ gravadas daquele bloco (o select da tabela é o canônico).
  function aplicarNivelInclusaoNasLinhas(temItemNovo, nvInclusao, mapaIds, lista){
    if(temItemNovo || !nvInclusao || nvInclusao==='OBRIGATORIO') return;
    (lista||[]).forEach(function(r){ if(r&&r.id) mapaIds[String(r.id)]=nvInclusao; });
  }
  aplicarNivelInclusaoNasLinhas(!!snap.cnhCat, snap.cnhNv, snap.niveisCnh, _rhMatriz.cnh);
  aplicarNivelInclusaoNasLinhas(!!snap.nrId, snap.nrNv, snap.niveisNr, _rhMatriz.nrs);
  aplicarNivelInclusaoNasLinhas(!!snap.cursoId, snap.cursoNv, snap.niveisCurso, _rhMatriz.cursos);
  aplicarNivelInclusaoNasLinhas(!!snap.docId, snap.docNv, snap.niveisDoc, _rhMatriz.docs);
  aplicarNivelInclusaoNasLinhas(!!snap.testeId, snap.testeNv, snap.niveisTeste, _rhMatriz.testes);

  var orfaos=[];
  if(!snap.cnhCat && snap.cnhNv!=='OBRIGATORIO' && !(_rhMatriz.cnh||[]).length) orfaos.push('CNH');
  if(!snap.nrId && snap.nrNv!=='OBRIGATORIO' && !(_rhMatriz.nrs||[]).length) orfaos.push('NR');
  if(!snap.cursoId && snap.cursoNv!=='OBRIGATORIO' && !(_rhMatriz.cursos||[]).length) orfaos.push('Treinamento');
  if(!snap.docId && snap.docNv!=='OBRIGATORIO' && !(_rhMatriz.docs||[]).length) orfaos.push('Documento');
  if(!snap.testeId && snap.testeNv!=='OBRIGATORIO' && !(_rhMatriz.testes||[]).length) orfaos.push('Teste');

  // Rascunho da linha de inclusão (mantém Não se aplica visível após redraw se ainda não incluiu item)
  _rhMatriz.draftAdd={
    cnhCat:snap.cnhCat, cnhNv:snap.cnhNv,
    nrId:snap.nrId, nrNv:snap.nrNv,
    cursoId:snap.cursoId, cursoNv:snap.cursoNv,
    docId:snap.docId, docNv:snap.docNv, docMom:snap.docMom||'SELECAO',
    testeId:snap.testeId, testeNv:snap.testeNv
  };

  var payload=snap.cab;
  var antes=_rhMatriz.header?JSON.parse(JSON.stringify(_rhMatriz.header)):{};
  function salvarCabecalho(){
    return new Promise(function(resolve){
      function done(row){
        _rhMatriz.header=row;
        if(row.status==='APROVADA'){
          payload.status='EM_CONFIGURACAO'; payload.aprovado_em=null; payload.aprovado_por=null;
          if(!DEMO) sbUpdate('rh_cargo_requisitos',{status:'EM_CONFIGURACAO',aprovado_em:null,aprovado_por:null,updated_at:payload.updated_at},'id=eq.'+row.id);
          row.status='EM_CONFIGURACAO';
          if(typeof rhProntidaoSincronizarMatrizStatus==='function') rhProntidaoSincronizarMatrizStatus(_rhMatriz.cargoId,'EM_CONFIGURACAO');
          if(typeof rhProntidaoInvalidate==='function') rhProntidaoInvalidate({catalogo:true});
          rhMatrizAudit('REABRIU_MATRIZ (edição após aprovada)',{anterior:'APROVADA',novo:'EM_CONFIGURACAO'});
        }
        _rhMatrizStatus[_rhMatriz.cargoId]=row.status||'EM_CONFIGURACAO';
        rhMatrizAudit('ALTEROU_REQUISITO cabeçalho',{anterior:antes,novo:payload});
        resolve(true);
      }
      if(!_rhMatriz.header){
        rhMatrizEnsureHeader(function(h){
          if(!h){ resolve(false); return; }
          if(DEMO){ done(Object.assign({},h,payload)); return; }
          Promise.resolve(sbUpdate('rh_cargo_requisitos',payload,'id=eq.'+h.id)).then(function(ok){
            if(ok===false){ resolve(false); return; }
            done(Object.assign({},h,payload));
          });
        });
        return;
      }
      if(_rhMatriz.header.status==='NAO_CONFIGURADA') payload.status='EM_CONFIGURACAO';
      if(DEMO){ done(Object.assign({},_rhMatriz.header,payload)); return; }
      Promise.resolve(sbUpdate('rh_cargo_requisitos',payload,'id=eq.'+_rhMatriz.header.id)).then(function(ok){
        if(ok===false){ resolve(false); return; }
        done(Object.assign({},_rhMatriz.header,payload));
      });
    });
  }
  function syncCampoLinha(tabela, row, campo, val){
    if(!row||!row.id||val==null||val==='') return Promise.resolve(true);
    if(String(row[campo]||'')===String(val||'')) return Promise.resolve(true);
    var patch={}; patch[campo]=val;
    if(DEMO){ row[campo]=val; return Promise.resolve(true); }
    return Promise.resolve(sbUpdate(tabela,patch,'id=eq.'+row.id)).then(function(ok){
      if(ok===false) return false;
      row[campo]=val;
      return true;
    });
  }
  function sincronizarNiveisSnap(){
    var jobs=[];
    (_rhMatriz.cnh||[]).forEach(function(r){
      if(snap.niveisCnh[String(r.id)]!=null) jobs.push(syncCampoLinha('rh_cargo_requisitos_cnh',r,'nivel_exigencia',snap.niveisCnh[String(r.id)]));
    });
    (_rhMatriz.nrs||[]).forEach(function(r){
      if(snap.niveisNr[String(r.id)]!=null) jobs.push(syncCampoLinha('rh_cargo_requisitos_nrs',r,'nivel_exigencia',snap.niveisNr[String(r.id)]));
    });
    (_rhMatriz.cursos||[]).forEach(function(r){
      if(snap.niveisCurso[String(r.id)]!=null) jobs.push(syncCampoLinha('rh_cargo_requisitos_treinamentos',r,'nivel_exigencia',snap.niveisCurso[String(r.id)]));
    });
    (_rhMatriz.docs||[]).forEach(function(r){
      if(snap.niveisDoc[String(r.id)]!=null) jobs.push(syncCampoLinha('rh_cargo_requisitos_documentos',r,'nivel_exigencia',snap.niveisDoc[String(r.id)]));
      if(snap.momentosDoc[String(r.id)]!=null) jobs.push(syncCampoLinha('rh_cargo_requisitos_documentos',r,'momento_exigencia',snap.momentosDoc[String(r.id)]));
    });
    (_rhMatriz.testes||[]).forEach(function(r){
      if(snap.niveisTeste[String(r.id)]!=null) jobs.push(syncCampoLinha('rh_cargo_requisitos_testes',r,'nivel_exigencia',snap.niveisTeste[String(r.id)]));
    });
    return Promise.all(jobs).then(function(arr){
      return {ok:arr.every(function(x){return x!==false;}), n:arr.length};
    });
  }
  function flushPendentes(){
    var jobs=[];
    if(snap.cnhCat) jobs.push(rhMatrizAddCnh({silent:true, skipRender:true, categoria:snap.cnhCat, nivel:snap.cnhNv}));
    if(snap.nrId) jobs.push(rhMatrizAddNr({silent:true, skipRender:true, norma_id:snap.nrId, nivel:snap.nrNv}));
    if(snap.cursoId) jobs.push(rhMatrizAddCurso({silent:true, skipRender:true, curso_id:snap.cursoId, nivel:snap.cursoNv}));
    if(snap.docId) jobs.push(rhMatrizAddDoc({silent:true, skipRender:true, tipo_documento_id:snap.docId, nivel:snap.docNv, momento:snap.docMom}));
    if(snap.testeId) jobs.push(rhMatrizAddTeste({silent:true, skipRender:true, perfil:snap.testeId, nivel:snap.testeNv}));
    if(!jobs.length) return Promise.resolve({ok:true, n:0, fail:0});
    return Promise.all(jobs).then(function(arr){
      var fail=arr.filter(function(x){return !x||(!x.ok && x.reason!=='dup');}).length;
      var okN=arr.filter(function(x){return x&&x.ok;}).length;
      if(_rhMatriz.draftAdd){
        if(snap.cnhCat){ _rhMatriz.draftAdd.cnhCat=''; _rhMatriz.draftAdd.cnhNv='OBRIGATORIO'; }
        if(snap.nrId){ _rhMatriz.draftAdd.nrId=''; _rhMatriz.draftAdd.nrNv='OBRIGATORIO'; }
        if(snap.cursoId){ _rhMatriz.draftAdd.cursoId=''; _rhMatriz.draftAdd.cursoNv='OBRIGATORIO'; }
        if(snap.docId){ _rhMatriz.draftAdd.docId=''; _rhMatriz.draftAdd.docNv='OBRIGATORIO'; _rhMatriz.draftAdd.docMom='SELECAO'; }
        if(snap.testeId){ _rhMatriz.draftAdd.testeId=''; _rhMatriz.draftAdd.testeNv='OBRIGATORIO'; }
      }
      return {ok:fail===0, n:okN, fail:fail, detalhe:arr};
    });
  }
  return salvarCabecalho().then(function(cabOk){
    if(!cabOk){ progShowToast('❌ Falha ao salvar cabeçalho da matriz (regime).','erro'); return false; }
    return sincronizarNiveisSnap().then(function(nv){
      return flushPendentes().then(function(fl){
        return rhMatrizRecarregarDoBanco().then(function(){
          if(!nv.ok || !fl.ok){
            progShowToast('❌ Regime gravado, mas parte dos requisitos falhou. Veja o console (sbInsert rh_cargo_requisitos_*).','erro');
            return false;
          }
          if(snap.cnhCat && fl.n===0 && !( _rhMatriz.cnh||[]).some(function(x){return String(x.categoria).toUpperCase()===snap.cnhCat.toUpperCase();})){
            progShowToast('❌ A categoria CNH '+snap.cnhCat+' não gravou. Rode SQLS/sql_rh_matriz_requisitos_cargo_fase1b_rls.sql no Supabase.','erro');
            return false;
          }
          if(orfaos.length){
            progShowToast('⚠ Nível em '+orfaos.join(', ')+' não gravou: não há item na tabela nem seleção na 1ª caixa. “Nenhum item” = seção sem exigência. Para gravar o nível, escolha o item (NR/curso/…) ou altere o nível na linha já listada.','erro');
          }
          var extra=[];
          if(fl.n) extra.push(fl.n+' item(ns) incluído(s)');
          if(Object.keys(snap.niveisCnh).length||Object.keys(snap.niveisNr).length||Object.keys(snap.niveisCurso).length||Object.keys(snap.niveisDoc).length||Object.keys(snap.niveisTeste).length) extra.push('níveis atualizados');
          if((_rhMatriz.cnh||[]).length) extra.push((_rhMatriz.cnh||[]).length+' CNH');
          if(!orfaos.length) progShowToast('✅ Matriz salva'+(extra.length?' — '+extra.join(', '):' (regime/exigências)')+'.');
          else if(extra.length) progShowToast('✅ Parcial: '+extra.join(', ')+'.');
          return true;
        });
      });
    });
  });
}
function rhMatrizAprovar(){
  if(_rhMatriz.soLeitura) return;
  var user=(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||'';
  var patch={status:'APROVADA',aprovado_em:new Date().toISOString(),aprovado_por:user,updated_at:new Date().toISOString()};
  function ok(h){ _rhMatriz.header=h; if(typeof rhProntidaoSincronizarMatrizStatus==='function') rhProntidaoSincronizarMatrizStatus(_rhMatriz.cargoId,'APROVADA'); else _rhMatrizStatus[_rhMatriz.cargoId]='APROVADA'; if(typeof rhProntidaoInvalidate==='function') rhProntidaoInvalidate({catalogo:true}); if(typeof rhProntidaoCarregarFontes==='function') rhProntidaoCarregarFontes(); rhMatrizAudit('APROVOU_MATRIZ',{novo:'APROVADA'}); rhMatrizRender(); progShowToast('✅ Matriz aprovada. A prontidão passa a consumir estes requisitos.'); }
  rhMatrizEnsureHeader(function(h){
    if(DEMO){ ok(Object.assign({},h,patch)); return; }
    Promise.resolve(sbUpdate('rh_cargo_requisitos',patch,'id=eq.'+h.id)).then(function(r){
      if(r===false){ progShowToast('❌ Falha ao aprovar.','erro'); return; }
      ok(Object.assign({},h,patch));
    });
  });
}
function rhMatrizReabrir(){
  if(_rhMatriz.soLeitura||!_rhMatriz.header) return;
  var patch={status:'EM_CONFIGURACAO',updated_at:new Date().toISOString()};
  if(!DEMO) sbUpdate('rh_cargo_requisitos',patch,'id=eq.'+_rhMatriz.header.id);
  Object.assign(_rhMatriz.header,patch);
  if(typeof rhProntidaoSincronizarMatrizStatus==='function') rhProntidaoSincronizarMatrizStatus(_rhMatriz.cargoId,'EM_CONFIGURACAO');
  else _rhMatrizStatus[_rhMatriz.cargoId]='EM_CONFIGURACAO';
  if(typeof rhProntidaoInvalidate==='function') rhProntidaoInvalidate({catalogo:true});
  if(typeof rhProntidaoCarregarFontes==='function') rhProntidaoCarregarFontes();
  rhMatrizAudit('REABRIU_MATRIZ',{anterior:'APROVADA',novo:'EM_CONFIGURACAO'});
  rhMatrizRender();
}
function rhMatrizAposFilho(listaKey, row, acao, skipRender){
  if(_rhMatriz.header && _rhMatriz.header.status==='APROVADA'){
    var p={status:'EM_CONFIGURACAO',aprovado_em:null,aprovado_por:null,updated_at:new Date().toISOString()};
    if(!DEMO && _rhMatriz.header.id) sbUpdate('rh_cargo_requisitos',p,'id=eq.'+_rhMatriz.header.id);
    Object.assign(_rhMatriz.header,p);
    if(typeof rhProntidaoSincronizarMatrizStatus==='function') rhProntidaoSincronizarMatrizStatus(_rhMatriz.cargoId,'EM_CONFIGURACAO');
    else _rhMatrizStatus[_rhMatriz.cargoId]='EM_CONFIGURACAO';
    if(typeof rhProntidaoInvalidate==='function') rhProntidaoInvalidate({catalogo:true});
    rhMatrizAudit('REABRIU_MATRIZ (item alterado)',{});
  } else if(!_rhMatriz.header || _rhMatriz.header.status==='NAO_CONFIGURADA'){
    if(_rhMatriz.header&&_rhMatriz.header.id&&!DEMO) sbUpdate('rh_cargo_requisitos',{status:'EM_CONFIGURACAO',updated_at:new Date().toISOString()},'id=eq.'+_rhMatriz.header.id);
    if(_rhMatriz.header) _rhMatriz.header.status='EM_CONFIGURACAO';
    _rhMatrizStatus[_rhMatriz.cargoId]='EM_CONFIGURACAO';
  }
  rhMatrizAudit(acao,{dados:row});
  if(!skipRender) rhMatrizRender();
}
function rhMatrizAddCnh(opts){
  opts=opts||{};
  return new Promise(function(resolve){
    var cat=(opts.categoria!=null?String(opts.categoria):((document.getElementById('mx-add-cnh-cat')||{}).value||'')).trim();
    var nv=(opts.nivel!=null?String(opts.nivel):((document.getElementById('mx-add-cnh-nv')||{}).value))||'OBRIGATORIO';
    if(!cat){ if(!opts.silent) progShowToast('⚠ Selecione a categoria da CNH.','erro'); resolve({ok:false}); return; }
    if(_rhMatriz.cnh.some(function(x){return String(x.categoria).toUpperCase()===cat.toUpperCase();})){
      if(!opts.silent) progShowToast('⚠ Categoria CNH já associada.','erro');
      resolve({ok:false, reason:'dup'}); return;
    }
    rhMatrizEnsureHeader(function(){
      var row={cargo_id:_rhMatriz.cargoId,categoria:cat,nivel_exigencia:nv,ativo:true};
      function ok(r0){
        _rhMatriz.cnh.push(r0);
        rhMatrizAposFilho('cnh',r0,'ADICIONOU_REQUISITO CNH', !!opts.skipRender);
        resolve({ok:true, row:r0});
      }
      if(DEMO){ row.id='cnh'+Date.now(); ok(row); return; }
      sbInsert('rh_cargo_requisitos_cnh',row).then(function(r){
        if(r&&r[0]) ok(r[0]);
        else { if(!opts.silent) progShowToast('❌ Falha ao gravar CNH. Verifique SQL/RLS da matriz.','erro'); resolve({ok:false}); }
      });
    });
  });
}
function rhMatrizAddNr(opts){
  opts=opts||{};
  return new Promise(function(resolve){
    var nid=(opts.norma_id!=null?String(opts.norma_id):((document.getElementById('mx-add-nr')||{}).value||'')).trim();
    var nv=(opts.nivel!=null?String(opts.nivel):((document.getElementById('mx-add-nr-nv')||{}).value))||'OBRIGATORIO';
    if(!nid){ if(!opts.silent) progShowToast('⚠ Selecione uma NR do catálogo.','erro'); resolve({ok:false}); return; }
    if(_rhMatriz.nrs.some(function(x){return String(x.norma_id)===nid;})){
      if(!opts.silent) progShowToast('⚠ NR já associada.','erro'); resolve({ok:false, reason:'dup'}); return;
    }
    rhMatrizEnsureHeader(function(){
      var row={cargo_id:_rhMatriz.cargoId,norma_id:nid,nivel_exigencia:nv,ativo:true};
      function ok(r0){
        _rhMatriz.nrs.push(r0);
        rhMatrizAposFilho('nrs',r0,'ADICIONOU_REQUISITO NR', !!opts.skipRender);
        resolve({ok:true, row:r0});
      }
      if(DEMO){ row.id='nr'+Date.now(); ok(row); return; }
      sbInsert('rh_cargo_requisitos_nrs',row).then(function(r){
        if(r&&r[0]) ok(r[0]);
        else { if(!opts.silent) progShowToast('❌ Falha ao gravar NR.','erro'); resolve({ok:false}); }
      });
    });
  });
}
function rhMatrizAddCurso(opts){
  opts=opts||{};
  return new Promise(function(resolve){
    var cid=(opts.curso_id!=null?String(opts.curso_id):((document.getElementById('mx-add-curso')||{}).value||'')).trim();
    var nv=(opts.nivel!=null?String(opts.nivel):((document.getElementById('mx-add-curso-nv')||{}).value))||'OBRIGATORIO';
    if(!cid){ if(!opts.silent) progShowToast('⚠ Selecione um treinamento.','erro'); resolve({ok:false}); return; }
    if(_rhMatriz.cursos.some(function(x){return String(x.curso_id)===cid;})){
      if(!opts.silent) progShowToast('⚠ Treinamento já associado.','erro'); resolve({ok:false, reason:'dup'}); return;
    }
    rhMatrizEnsureHeader(function(){
      var row={cargo_id:_rhMatriz.cargoId,curso_id:cid,nivel_exigencia:nv,ativo:true};
      function ok(r0){
        _rhMatriz.cursos.push(r0);
        rhMatrizAposFilho('cursos',r0,'ADICIONOU_REQUISITO treinamento', !!opts.skipRender);
        resolve({ok:true, row:r0});
      }
      if(DEMO){ row.id='tr'+Date.now(); ok(row); return; }
      sbInsert('rh_cargo_requisitos_treinamentos',row).then(function(r){
        if(r&&r[0]) ok(r[0]);
        else { if(!opts.silent) progShowToast('❌ Falha ao gravar treinamento.','erro'); resolve({ok:false}); }
      });
    });
  });
}
