    +'</div>'

    // ── Configurações de validade ──
    +'<div style="font-size:10px;font-weight:700;color:#185FA5;text-transform:uppercase;letter-spacing:.5px;margin:0 0 8px">Validade &amp; Periodicidade</div>'
