function _fornRefreshLista(){
  if(document.getElementById('tbody-forn-vis') && typeof renderFornecedoresVis==='function') renderFornecedoresVis();
  else if(typeof renderCadastros==='function') renderCadastros();
}
// ── Anti-duplicidade de fornecedores ──────────────────────────────
function _fornNormNome(s){
  return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
}
function _fornNormDoc(s){ return String(s||'').replace(/\D/g,''); }
function _fornLev(a,b){
  a=a||''; b=b||'';
  if(a===b) return 0;
  if(!a.length) return b.length;
  if(!b.length) return a.length;
  var prev=[], i, j;
  for(j=0;j<=b.length;j++) prev[j]=j;
  for(i=1;i<=a.length;i++){
    var cur=[i];
    for(j=1;j<=b.length;j++){
      var cost=a.charAt(i-1)===b.charAt(j-1)?0:1;
      cur[j]=Math.min(cur[j-1]+1, prev[j]+1, prev[j-1]+cost);
    }
    prev=cur;
  }
  return prev[b.length];
}
function _fornSimil(a,b){
  var na=_fornNormNome(a), nb=_fornNormNome(b);
  if(!na||!nb) return 0;
  if(na===nb) return 1;
  var maxL=Math.max(na.length,nb.length);
  var r=1-(_fornLev(na,nb)/maxL);
  if(na.indexOf(nb)>=0 || nb.indexOf(na)>=0) r=Math.max(r,0.9);
  return r;
}
function _fornCheckDuplicidade(nome, cnpj){
  var seen={}, uniq=[];
  (fornecedores||[]).concat(_fornDB||[]).forEach(function(f){
    if(!f) return; var k=String(f.id); if(seen[k]) return; seen[k]=1; uniq.push(f);
  });
  var nnome=_fornNormNome(nome), ndoc=_fornNormDoc(cnpj);
  var exato=null, similares=[];
  uniq.forEach(function(f){
    if(String(f.status||'')==='Inativo') return;
    var fdoc=_fornNormDoc(f.cnpj_cpf||f.cnpj||f.documento||'');
    if(ndoc && fdoc && ndoc===fdoc){ if(!exato) exato={f:f, motivo:'CNPJ/CPF'}; return; }
    var fn=_fornNormNome(f.razao_social||f.nome||f.nome_fantasia||'');
    if(nnome && fn===nnome){ if(!exato) exato={f:f, motivo:'nome'}; return; }
    var sim=_fornSimil(nome, f.razao_social||f.nome||f.nome_fantasia||'');
    if(sim>=0.82) similares.push({f:f, score:sim});
  });
  similares.sort(function(a,b){ return b.score-a.score; });
  return {exato:exato, similares:similares.slice(0,6)};
}
function _fornDupResumoHtml(f){
  var e=(typeof escHtml==='function')?escHtml:function(x){return String(x==null?'':x);};
  return '<div style="background:#f6f6f2;border-radius:8px;padding:7px 10px;font-size:13px;margin:3px 0"><b>'+e(f.razao_social||f.nome||f.nome_fantasia||'—')+'</b>'
    +(f.cnpj_cpf||f.cnpj?'<br><span style="color:#555">CNPJ/CPF: '+e(f.cnpj_cpf||f.cnpj)+'</span>':'')
    +(f.tipo?' <span style="color:#888;font-size:11px">· '+e(f.tipo)+'</span>':'')+'</div>';
}
async function salvarFornecedor(force){
  var rs=(document.getElementById('nf-rs')||{}).value||'';if(!rs.trim())return;
  var cnpj=(document.getElementById('nf-cnpj')||{}).value||'';
  if(!force){
    var _dup=_fornCheckDuplicidade(rs, cnpj);
    if(_dup.exato){
      almNfOverlay('<div class="modal" style="max-width:520px" onclick="event.stopPropagation()">'
        +'<h3 style="margin:0 0 .5rem">⛔ Fornecedor já cadastrado</h3>'
        +'<p style="font-size:13px">Já existe um fornecedor com o mesmo <b>'+_dup.exato.motivo+'</b>:</p>'
        +_fornDupResumoHtml(_dup.exato.f)
        +'<p style="font-size:12px;color:#555;margin-top:.4rem">Não é possível cadastrar em duplicidade. Se precisar, edite o fornecedor existente.</p>'
        +'<div class="ma" style="margin-top:.8rem"><button class="btn btn-pri" onclick="almNfFecharOverlay()">Entendi</button></div></div>');
      return;
    }
    if(_dup.similares && _dup.similares.length){
      almNfOverlay('<div class="modal" style="max-width:560px" onclick="event.stopPropagation()">'
        +'<h3 style="margin:0 0 .4rem">⚠ Fornecedores parecidos</h3>'
        +'<p style="font-size:13px">Há fornecedor(es) com nome parecido. Confira se não é o mesmo antes de cadastrar:</p>'
        +'<div style="max-height:240px;overflow:auto;margin:.4rem 0">'
        +_dup.similares.map(function(s){ return _fornDupResumoHtml(s.f).replace('</div>',' <span style="color:#888;font-size:11px">('+Math.round(s.score*100)+'% parecido)</span></div>'); }).join('')
        +'</div>'
        +'<div class="ma" style="margin-top:.5rem;display:flex;gap:8px;flex-wrap:wrap">'
        +'<button class="btn" onclick="almNfFecharOverlay()">Revisar</button>'
        +'<button class="btn btn-pri" onclick="almNfFecharOverlay();salvarFornecedor(true)">Cadastrar mesmo assim</button>'
        +'</div></div>');
      return;
    }
  }
  var payload={
    razao_social:rs.trim(),
    cnpj_cpf:cnpj,
    tipo:(document.getElementById('nf-tipo')||{}).value||'Fornecedor',
    contato:(document.getElementById('nf-cont')||{}).value||'',
    telefone:(document.getElementById('nf-tel')||{}).value||'',
    email:(document.getElementById('nf-email')||{}).value||'',
    status:'Ativo'
  };
  closeModal();
  var novo=null;
  if(DEMO){
    novo=Object.assign({id:'f'+Date.now()},payload);
  } else {
    var rows=await sbInsert('fornecedores',payload);
    if(!rows||!rows[0]){
      if(typeof progShowToast==='function') progShowToast('Erro ao salvar fornecedor.','erro');
      else alert('Erro ao salvar fornecedor.');
      return;
    }
    novo=rows[0];
  }
  if(!_fornDB) _fornDB=[];
  if(!_fornDB.some(function(x){return String(x.id)===String(novo.id);})) _fornDB.push(novo);
  if(!(fornecedores||[]).some(function(x){return String(x.id)===String(novo.id);})) fornecedores.push(novo);
  _fornRefreshLista();
  if(typeof progShowToast==='function') progShowToast('Fornecedor cadastrado.');
}
async function excluirFornecedor(fid){
  var f=(typeof _fornFindById==='function'?_fornFindById(fid):null)
    || (fornecedores||[]).find(function(x){return String(x.id)===String(fid);})
    || (_fornDB||[]).find(function(x){return String(x.id)===String(fid);});
  if(!f){
    if(typeof progShowToast==='function') progShowToast('Fornecedor não encontrado.','erro');
    else alert('Fornecedor não encontrado.');
    return;
  }
  if(f._erp){
    if(typeof progShowToast==='function') progShowToast('Fornecedor do ERP não pode ser excluído aqui.','erro');
    return;
  }
  if(!confirm('Excluir fornecedor "'+(f.razao_social||'')+'"?\n\nO registro será removido da lista (soft-delete no banco quando disponível).'))return;
  var idStr=String(fid);
  fornecedores=(fornecedores||[]).filter(function(x){return String(x.id)!==idStr;});
  _fornDB=(_fornDB||[]).filter(function(x){return String(x.id)!==idStr;});
  if(!DEMO && typeof isUUID==='function' && isUUID(idStr)){
    await sbDelete('fornecedores','id=eq.'+idStr);
  } else if(!DEMO){
    console.warn('[forn] exclusão só local — id não é UUID:', idStr);
  }
  _fornRefreshLista();
  if(typeof progShowToast==='function') progShowToast('Fornecedor excluído.');
}
