function gerirSubcats(catId){
  var cat=categorias.find(function(x){return x.id===catId;});if(!cat)return;
  var subs=subcategorias.filter(function(s){return s.categoria_id===catId;});
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px"><h3>Subcategorias — '+cat.nome+'</h3>'    +'<div id="lista-subcat" style="margin-bottom:1rem;max-height:280px;overflow-y:auto">'    +subs.map(function(s){return '<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 10px;background:#f9f9f7;border-radius:8px;margin-bottom:4px;font-size:12px"><span>'+s.nome+'</span><button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D;flex-shrink:0" id="rm-sub-'+s.id+'">Remover</button></div>';}).join('')    +'</div>'    +'<div style="display:flex;gap:8px;margin-bottom:.5rem"><input class="inp" id="nova-subcat" placeholder="Nova subcategoria..." style="flex:1"/>'    +'<button class="btn btn-pri" id="btn-add-sub">+ Adicionar</button></div>'    +'<div style="border-top:.5px solid #e0dfd8;padding-top:.75rem">'    +'<div style="font-size:11px;color:#888;margin-bottom:5px">📋 Importar em massa — cole várias (uma por linha ou separadas por ;):</div>'    +'<textarea id="massa-subcat" style="width:100%;height:80px;border:.5px solid #e0dfd8;border-radius:8px;padding:8px;font-size:12px;resize:vertical" placeholder="SUBCATEGORIA 1&#10;SUBCATEGORIA 2&#10;ou SUBCAT 1; SUBCAT 2"></textarea>'    +'<button class="btn btn-pri" id="btn-importar-sub" style="margin-top:6px;width:100%">Importar todas</button>'    +'</div>'    +'<div id="importar-feedback" style="font-size:12px;margin-top:6px"></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Fechar</button></div></div></div>');
  subs.forEach(function(s){
    var b=document.getElementById('rm-sub-'+s.id);
    if(b)b.onclick=function(){removerSubcat(s.id,catId);};
  });
  var btnAdd=document.getElementById('btn-add-sub');
  if(btnAdd)btnAdd.onclick=function(){adicionarSubcat(catId);};
  var btnImp=document.getElementById('btn-importar-sub');
  if(btnImp)btnImp.onclick=function(){importarSubcats(catId);};
}
function adicionarSubcat(catId){
  var inp=document.getElementById('nova-subcat');
  var nome=(inp||{}).value.trim();if(!nome)return;
  var nova={id:'sub'+Date.now(),categoria_id:catId,nome:nome,ativa:true};
  subcategorias.push(nova);if(!DEMO)sbInsert('subcategorias_despesa',_semId(nova));
  if(inp)inp.value='';
  gerirSubcats(catId);
}
function importarSubcats(catId){
  var txt=(document.getElementById('massa-subcat')||{}).value||'';
  var itens=txt.split(/[;\n]/).map(function(s){return s.trim();}).filter(function(s){return s.length>0;});
  if(!itens.length){var fb=document.getElementById('importar-feedback');if(fb)fb.innerHTML='<span style="color:#A32D2D">Nenhum item encontrado.</span>';return;}
  var existentes=subcategorias.filter(function(s){return s.categoria_id===catId;}).map(function(s){return s.nome.toLowerCase();});
  var novas=itens.filter(function(n){return existentes.indexOf(n.toLowerCase())<0;});
  var duplicadas=itens.length-novas.length;
  novas.forEach(function(nome,i){
    var nova={id:'sub'+Date.now()+'x'+i,categoria_id:catId,nome:nome,ativa:true};
    subcategorias.push(nova);
    if(!DEMO)sbInsert('subcategorias_despesa',_semId(nova));
  });
  var fb=document.getElementById('importar-feedback');
  if(fb){
    var msg='<span style="color:#3B6D11">✓ '+novas.length+' importada(s).</span>';
    if(duplicadas>0)msg+=' <span style="color:#888">('+duplicadas+' já existia(m) — ignorada(s))</span>';
    fb.innerHTML=msg;
  }
  setTimeout(function(){gerirSubcats(catId);},600);
}
function removerSubcat(sid,catId){
  if(!confirm('Remover subcategoria?'))return;
  subcategorias=subcategorias.filter(function(s){return s.id!==sid;});
  if(!DEMO)sbUpdate('subcategorias_despesa',{ativa:false},'id=eq.'+sid);
  gerirSubcats(catId);
}


