function fmtMesAno(ma){if(!ma)return'—';var p=ma.split('-');if(p.length<2)return ma;var meses=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];return(meses[parseInt(p[1])-1]||p[1])+'/'+p[0];}
function mesAnoAtual(){var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');}

