// PRODUTIVIDADE
function popularFiltrosProd(){
  var sel=document.getElementById('fil-prod-cont');if(!sel)return;
  sel.innerHTML='<option value="">Todos</option>'+_contratosVisiveis().map(function(c){return '<option value="'+c.id+'">'+c.nome+'</option>';}).join('');
  var selAno=document.getElementById('fil-prod-ano');if(!selAno)return;
  var anos=new Set();
  produtividade.forEach(function(p){if(p.mes_ano)anos.add(p.mes_ano.split('-')[0]);});
  var anoAtual=new Date().getFullYear();
  for(var y=anoAtual-2;y<=anoAtual+1;y++)anos.add(String(y));
  selAno.innerHTML=Array.from(anos).sort().map(function(a){return '<option value="'+a+'"'+(a===String(anoAtual)?' selected':'')+'>'+a+'</option>';}).join('');
}

function getProdFiltro(){
  var sel=document.getElementById('fil-prod-cont');
  var contsSel=Array.from((sel||{selectedOptions:[]}).selectedOptions).map(function(o){return o.value;}).filter(Boolean);
  var ano=(document.getElementById('fil-prod-ano')||{}).value||String(new Date().getFullYear());
  var mes=(document.getElementById('fil-prod-mes')||{}).value||'';
  return {contsSel:contsSel,ano:ano,mes:mes};
}

function renderProdutividade(){
  var f=getProdFiltro();
  // Incluir medições faturadas como realizado
  var medFaturadas=medicoes.filter(function(m){return m.status==='faturada'&&m.faturado_em;});
  medFaturadas.forEach(function(m){
    if(!m.total_medido)return;
    var ma=m.faturado_em?m.faturado_em.substring(0,7):(m.data_fim?m.data_fim.substring(0,7):'');
    if(!ma)return;
    var idx=produtividade.findIndex(function(p){return p.contrato_id===m.contrato_id&&p.mes_ano===ma;});
    if(idx>=0){
      // Somar ao valor faturado existente se ainda não somou
      if(!produtividade[idx]._med_ids) produtividade[idx]._med_ids=[];
      if(produtividade[idx]._med_ids.indexOf(m.id)<0){
        produtividade[idx].valor_faturado=(produtividade[idx].valor_faturado||0)+m.total_medido;
        produtividade[idx]._med_ids.push(m.id);
      }
    } else {
      // Criar entrada automática para medições sem lançamento manual
      if(!produtividade.find(function(p){return p._auto_med_id===m.id;})){
        produtividade.push({
          id:'auto-'+m.id, contrato_id:m.contrato_id, mes_ano:ma,
          meta_prod:0, prod_prevista:0, prod_realizada:0,
          valor_faturado:m.total_medido, receita_oportunidade:0,
          _auto_med_id:m.id, _auto:true
        });
      }
    }
  });

  var rows=produtividade.filter(function(p){
    if(f.contsSel.length&&f.contsSel.indexOf(p.contrato_id)<0)return false;
    if(f.ano&&(!p.mes_ano||p.mes_ano.indexOf(f.ano)!==0))return false;
    if(f.mes&&(!p.mes_ano||p.mes_ano.substring(5,7)!==f.mes))return false;
    return true;
  });
  rows.sort(function(a,b){return(a.mes_ano||'')>(b.mes_ano||'')?1:-1;});

  // Métricas
  var totMeta=rows.reduce(function(s,p){return s+Number(p.meta_prod||0);},0);
  var totPrev=rows.reduce(function(s,p){return s+Number(p.prod_prevista||0);},0);
  var totReal=rows.reduce(function(s,p){return s+Number(p.prod_realizada||0);},0);
  var totFat=rows.reduce(function(s,p){return s+Number(p.valor_faturado||0);},0);
  var totOp=rows.reduce(function(s,p){return s+Number(p.receita_oportunidade||0);},0);
  var totRecTotal=totFat+totOp;
  var totDesp=lancamentos.filter(function(l){
    if(f.contsSel.length&&f.contsSel.indexOf(l.contrato_id)<0)return false;
    if(f.ano&&(!l.data_emissao||l.data_emissao.indexOf(f.ano)!==0))return false;
    if(f.mes&&(!l.data_emissao||l.data_emissao.substring(5,7)!==f.mes))return false;
    return true;
  }).reduce(function(s,l){return s+Number(l.valor||0);},0);
  var resultado=totRecTotal-totDesp;

  var pm=document.getElementById('prod-metricas');
  if(pm)pm.innerHTML=[
    {l:'Meta Produtividade',v:fmtR(totMeta),c:'#185FA5'},
    {l:'Prod. Realizada',v:fmtR(totReal),c:totReal>=totMeta?'#3B6D11':'#854F0B'},
    {l:'Faturado + Oportunidade',v:fmtR(totRecTotal),c:'#3B6D11'},
    {l:'Resultado (Rec - Desp)',v:fmtR(resultado),c:resultado>=0?'#3B6D11':'#A32D2D'},
  ].map(function(m){return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem"><div style="font-size:11px;color:#888;margin-bottom:4px">'+m.l+'</div><div style="font-size:20px;font-weight:600;color:'+m.c+'">'+m.v+'</div></div>';}).join('');

  // Resumo receita x despesa
  var rrd=document.getElementById('prod-resumo-rec-desp');
  if(rrd)rrd.innerHTML='<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;font-size:13px">'    +'<div style="text-align:center"><div style="color:#888;font-size:11px;margin-bottom:4px">Total Receitas</div><div style="font-size:18px;font-weight:600;color:#3B6D11">'+fmtR(totRecTotal)+'</div><div style="font-size:11px;color:#aaa">Fat.: '+fmtR(totFat)+' | Op.: '+fmtR(totOp)+'</div></div>'    +'<div style="text-align:center"><div style="color:#888;font-size:11px;margin-bottom:4px">Total Despesas</div><div style="font-size:18px;font-weight:600;color:#A32D2D">'+fmtR(totDesp)+'</div></div>'    +'<div style="text-align:center"><div style="color:#888;font-size:11px;margin-bottom:4px">Resultado</div><div style="font-size:18px;font-weight:600;color:'+(resultado>=0?'#3B6D11':'#A32D2D')+'">'+fmtR(resultado)+'</div></div>'    +'</div>';

  // Tabela
  var tb=document.getElementById('tbody-prod');
  if(tb)tb.innerHTML=rows.map(function(p){
    var totRec=Number(p.valor_faturado||0)+Number(p.receita_oportunidade||0);
    var atingiu=p.meta_prod>0?Math.round(p.prod_realizada/p.meta_prod*100):0;
    return '<tr>'      +'<td style="font-weight:500">'+fmtMesAno(p.mes_ano)+(p._auto?'<span style="font-size:9px;background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;margin-left:4px">auto</span>':'')+'</td>'      +'<td style="font-size:11px">'+fNomeCont(p.contrato_id)+'</td>'      +'<td>'+fmtR(p.meta_prod)+'</td>'      +'<td>'+fmtR(p.prod_prevista)+'</td>'      +'<td style="color:'+(p.prod_realizada>=p.meta_prod?'#3B6D11':'#854F0B')+'">'+fmtR(p.prod_realizada)+' <span style="font-size:10px;color:#aaa">('+atingiu+'%)</span></td>'      +'<td style="font-weight:500">'+fmtR(p.valor_faturado)+'</td>'      +'<td style="color:#534AB7">'+fmtR(p.receita_oportunidade)+'</td>'      +'<td style="font-weight:500;color:#3B6D11">'+fmtR(totRec)+'</td>'      +'<td style="display:flex;gap:3px">'      +'<button class="btn btn-sm" onclick="openEditarProd(\''+p.id+'\')">Editar</button>'+'<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" onclick="deletarProd(\''+p.id+'\')">Excluir</button>'      +'</td></tr>';
  }).join('')||'<tr><td colspan="9" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum registro</td></tr>';
}

function openNovoProd(){
  var contOpts=contratos.map(function(c){return '<option value="'+c.id+'">'+c.nome+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px"><h3>Lançar Produtividade / Faturamento</h3>'    +'<div class="g2">'    +'<div class="fg"><label>Contrato</label><select id="np-cont">'+contOpts+'</select></div>'    +'<div class="fg"><label>Mês/Ano (AAAA-MM)</label><input id="np-ma" placeholder="'+mesAnoAtual()+'" value="'+mesAnoAtual()+'"/></div>'    +'<div class="fg"><label>Meta de Produtividade (R$)</label><input id="np-meta" type="number" step="0.01" placeholder="0,00"/></div>'    +'<div class="fg"><label>Produtividade Prevista (R$)</label><input id="np-prev" type="number" step="0.01" placeholder="0,00"/></div>'    +'<div class="fg"><label>Produtividade Realizada (R$)</label><input id="np-real" type="number" step="0.01" placeholder="0,00"/></div>'    +'<div class="fg"><label>Valor Medido / Faturado (R$)</label><input id="np-fat" type="number" step="0.01" placeholder="0,00"/></div>'    +'<div class="fg" style="grid-column:1/-1"><label>Receita de Oportunidade (R$)</label><input id="np-op" type="number" step="0.01" placeholder="0,00"/></div>'    +'</div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" onclick="salvarProd()">Salvar</button></div></div></div>');
}

function salvarProd(){
  var cid=(document.getElementById('np-cont')||{}).value||'';
  var ma=(document.getElementById('np-ma')||{}).value||'';
  if(!cid||!ma)return alert('Selecione contrato e informe mês/ano.');
  var novo={id:'p'+Date.now(),contrato_id:cid,mes_ano:ma,
    meta_prod:parseFloat((document.getElementById('np-meta')||{}).value)||0,
    prod_prevista:parseFloat((document.getElementById('np-prev')||{}).value)||0,
    prod_realizada:parseFloat((document.getElementById('np-real')||{}).value)||0,
    valor_faturado:parseFloat((document.getElementById('np-fat')||{}).value)||0,
    receita_oportunidade:parseFloat((document.getElementById('np-op')||{}).value)||0};
  // substituir se já existir mesmo mês/contrato
  var idx=produtividade.findIndex(function(p){return p.contrato_id===cid&&p.mes_ano===ma;});
  if(idx>=0){produtividade[idx]=Object.assign(produtividade[idx],novo);if(!DEMO)sbUpdate('produtividade',novo,'id=eq.'+produtividade[idx].id);}
  else{produtividade.push(novo);if(!DEMO)sbInsert('produtividade',_semId(novo));}
  closeModal();renderProdutividade();renderDashboard();
}

function openEditarProd(pid){
  var p=produtividade.find(function(x){return x.id===pid;});if(!p)return;
  var contOpts=contratos.map(function(c){return '<option value="'+c.id+'"'+(c.id===p.contrato_id?' selected':'')+'>'+c.nome+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px"><h3>Editar — '+fmtMesAno(p.mes_ano)+'</h3>'    +'<div class="g2">'    +'<div class="fg"><label>Contrato</label><select id="np-cont">'+contOpts+'</select></div>'    +'<div class="fg"><label>Mês/Ano</label><input id="np-ma" value="'+(p.mes_ano||'')+'"/></div>'    +'<div class="fg"><label>Meta Produtividade (R$)</label><input id="np-meta" type="number" value="'+(p.meta_prod||0)+'"/></div>'    +'<div class="fg"><label>Prod. Prevista (R$)</label><input id="np-prev" type="number" value="'+(p.prod_prevista||0)+'"/></div>'    +'<div class="fg"><label>Prod. Realizada (R$)</label><input id="np-real" type="number" value="'+(p.prod_realizada||0)+'"/></div>'    +'<div class="fg"><label>Valor Medido / Faturado (R$)</label><input id="np-fat" type="number" value="'+(p.valor_faturado||0)+'"/></div>'    +'<div class="fg" style="grid-column:1/-1"><label>Receita de Oportunidade (R$)</label><input id="np-op" type="number" value="'+(p.receita_oportunidade||0)+'"/></div>'    +'</div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" onclick="salvarEditarProd(\''+pid+'\')">Salvar</button></div></div></div>');
}

function salvarEditarProd(pid){
  var p=produtividade.find(function(x){return x.id===pid;});if(!p)return;
  p.contrato_id=(document.getElementById('np-cont')||{}).value||p.contrato_id;
  p.mes_ano=(document.getElementById('np-ma')||{}).value||p.mes_ano;
  p.meta_prod=parseFloat((document.getElementById('np-meta')||{}).value)||0;
  p.prod_prevista=parseFloat((document.getElementById('np-prev')||{}).value)||0;
  p.prod_realizada=parseFloat((document.getElementById('np-real')||{}).value)||0;
  p.valor_faturado=parseFloat((document.getElementById('np-fat')||{}).value)||0;
  p.receita_oportunidade=parseFloat((document.getElementById('np-op')||{}).value)||0;
  if(!DEMO)sbUpdate('produtividade',p,'id=eq.'+pid);
  closeModal();renderProdutividade();renderDashboard();
}

function deletarProd(pid){
  if(!confirm('Excluir este registro de produtividade?'))return;
  produtividade=produtividade.filter(function(p){return p.id!==pid;});
  renderProdutividade();renderDashboard();
}

// ALERTA REAJUSTE
function alertasReajuste(){
  var alertas=[];
  var hoje=new Date();hoje.setHours(0,0,0,0);
  contratos.filter(function(c){return c.data_reajuste&&c.status==='Ativo';}).forEach(function(c){
    var dr=new Date(c.data_reajuste+'T00:00:00');
    var diff=Math.round((dr-hoje)/(1000*60*60*24));
    // Sinalizar apenas vencidos ou com menos de 30 dias
    if(diff>30)return;
    var icone=diff<0?'⚠ Reajuste VENCIDO':'⚠ Reajuste em '+diff+' dias';
    var tipo=diff<0?'alerta-100':'alerta-90';
    alertas.push({tipo:tipo,cid:c.id,codigo:c.codigo,nome:c.nome,
      msg:icone+': '+c.nome+' ('+fmtD(c.data_reajuste)+')',
      diff:diff});
  });
  return alertas;
}

function openRegistrarReajuste(cid){
  var c=contratos.find(function(x){return x.id===cid;});if(!c)return;
  var hist=c.historico_reajuste?(typeof c.historico_reajuste==='string'?JSON.parse(c.historico_reajuste):c.historico_reajuste):[];
  var indices=['IPCA','IGP-M','INPC','IPC-A','INCC','FIPE','Livre (negociado)'];
  var hoje=dataHoje();

  // Construir modal via DOM para garantir que eventos funcionem
  var ma=document.getElementById('modal-area');
  if(!ma)return;

  // Histórico HTML
  var histHtml='';
  if(hist.length){
    histHtml='<div style="margin-bottom:.75rem"><div style="font-size:11px;font-weight:600;color:#888;margin-bottom:4px">REAJUSTES ANTERIORES</div>'
      +hist.map(function(h){
        return '<div style="display:flex;justify-content:space-between;font-size:12px;padding:5px 0;border-bottom:.5px solid #f0efe8">'
          +'<span>'+fmtD(h.data)+' — '+h.indice+' ('+h.percentual+'%)</span>'
          +'<span style="color:#888">Próximo: '+fmtD(h.nova_data)+'</span>'
          +'</div>';
      }).join('')
      +'</div>';
  }

  ma.innerHTML='<div class="modal-bg"><div class="modal" style="max-width:500px">'
    +'<h3>Registrar Reajuste — '+c.codigo+'</h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">'+c.nome+'</div>'
    +histHtml
    +'<div class="g2">'
    +'<div class="fg"><label>Data do reajuste</label><input id="rr-data" type="date" value="'+hoje+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Índice aplicado</label><select id="rr-indice" style="width:100%">'
    +indices.map(function(i){return '<option>'+i+'</option>';}).join('')
    +'</select></div>'
    +'<div class="fg"><label>Percentual aplicado (%)</label><input id="rr-pct" type="number" step="0.01" placeholder="ex: 4.62" style="width:100%"/></div>'
    +'<div class="fg"><label>Próxima data de reajuste</label><input id="rr-nova-data" type="date" style="width:100%"/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Observação</label><input id="rr-obs" placeholder="Ex: Reajuste conforme cláusula 5ª" style="width:100%"/></div>'
    +'</div>'
    +'<div class="ma">'
    +'<button class="btn" id="rr-btn-cancel">Cancelar</button>'
    +'<button class="btn btn-pri" id="rr-btn-salvar">Salvar reajuste</button>'
    +'</div></div></div>';

  document.getElementById('rr-btn-cancel').onclick=function(){ma.innerHTML='';};

  document.getElementById('rr-btn-salvar').onclick=function(){
    var data=document.getElementById('rr-data').value||hoje;
    var indice=document.getElementById('rr-indice').value||'';
    var pct=parseFloat(document.getElementById('rr-pct').value)||0;
    var novaData=document.getElementById('rr-nova-data').value||'';
    var obs=document.getElementById('rr-obs').value||'';
    if(!pct){alert('Informe o percentual aplicado.');return;}
    if(!novaData){alert('Informe a próxima data de reajuste.');return;}
    if(!c.historico_reajuste)c.historico_reajuste=[];
    if(typeof c.historico_reajuste==='string')c.historico_reajuste=JSON.parse(c.historico_reajuste);
    c.historico_reajuste.push({data:data,indice:indice,percentual:pct,nova_data:novaData,obs:obs});
    c.data_reajuste=novaData;
    c.ultimo_reajuste_data=data;
    c.ultimo_reajuste_indice=indice;
    c.ultimo_reajuste_pct=pct;
    if(!DEMO)sbUpdate('contratos',{
      data_reajuste:novaData,
      historico_reajuste:JSON.stringify(c.historico_reajuste),
      ultimo_reajuste_data:data,
      ultimo_reajuste_indice:indice,
      ultimo_reajuste_pct:pct
    },'id=eq.'+cid);
    ma.innerHTML='';
    renderDashboard();
    alert('✓ Reajuste registrado! Próximo: '+fmtD(novaData));
  };
}

// SALVAR LANÇAMENTO COM RC, SOLICITANTE E UPLOAD
var _salvarLancOrig = salvarLancamento;
salvarLancamento = async function(){
  var val=parseFloat((document.getElementById('nl-val')||{}).value)||0;
  var desc=(document.getElementById('nl-desc')||{}).value||'';
  if(!desc.trim())return alert('Preencha a descrição.');
  if(!val)return alert('Informe o valor.');
  var xmlFile=(document.getElementById('nl-xml')||{}).files;
  var pdfFile=(document.getElementById('nl-pdf')||{}).files;
  var xmlUrl='',pdfUrl='';
  if(xmlFile&&xmlFile.length&&!DEMO){
    var r1=await sbUpload(xmlFile[0],'nfs/'+Date.now()+'_'+xmlFile[0].name);
    if(r1)xmlUrl=r1;
  }
  if(pdfFile&&pdfFile.length&&!DEMO){
    var r2=await sbUpload(pdfFile[0],'docs/'+Date.now()+'_'+pdfFile[0].name);
    if(r2)pdfUrl=r2;
  }
  function uuidOrNull(v){
    v=(v==null?'':String(v)).trim();
    if(!v||v.indexOf('_erp_')===0) return null;
    if(typeof isUUID==='function'&&!isUUID(v)) return null;
    return v;
  }
  var fornSel=(document.getElementById('nl-forn')||{}).value||'';
  var fornId=null;
  try{
    if(fornSel && typeof frtResolverFornecedorId==='function' && !DEMO){
      fornId=await frtResolverFornecedorId(fornSel);
    } else if(fornSel && String(fornSel).indexOf('_erp_')!==0){
      fornId=fornSel;
    }
  }catch(eForn){
    console.warn('salvarLancamento fornecedor ERP',eForn);
    if(typeof progShowToast==='function') progShowToast('⚠ Não foi possível cadastrar o fornecedor do ERP. Tente de novo ou cadastre-o antes.','erro');
    fornId=null;
  }
  fornId=uuidOrNull(fornId);
  var novo={id:'l'+Date.now(),
    contrato_id:uuidOrNull((document.getElementById('nl-cont')||{}).value)||'',
    categoria_id:uuidOrNull((document.getElementById('nl-cat')||{}).value)||'',
    subcategoria_id:uuidOrNull((document.getElementById('nl-subcat')||{}).value),
    descricao:desc.trim(),
    fornecedor_id:fornId,
    documento_fiscal:(document.getElementById('nl-doc')||{}).value||'',
    data_emissao:(document.getElementById('nl-emi')||{}).value||null,
    competencia:(document.getElementById('nl-comp')||{}).value||'',
    data_vencimento:(document.getElementById('nl-venc')||{}).value||null,
    valor:val,
    centro_custo:(document.getElementById('nl-cc')||{}).value||'',
    observacao:(document.getElementById('nl-obs')||{}).value||'',
    status:'Lançado',
    criado_em:dataHojeLocal()};
  var rc=(document.getElementById('nl-rc')||{}).value||'';
  var sol=(document.getElementById('nl-solicitante')||{}).value||'';
  if(rc) novo.numero_rc=rc;
  if(sol) novo.solicitante=sol;
  if(xmlUrl) novo.anexo_xml=xmlUrl;
  if(pdfUrl) novo.anexo_pdf=pdfUrl;
  lancamentos.unshift(novo);
  var v=verbas.find(function(x){return x.contrato_id===novo.contrato_id&&x.categoria_id===novo.categoria_id;});
  if(v)v.valor_realizado=(v.valor_realizado||0)+val;
  if(!DEMO){
    var payload=_semId(novo);
    ['fornecedor_id','subcategoria_id','contrato_id','categoria_id'].forEach(function(k){
      if(payload[k]===''||payload[k]==null) delete payload[k];
      else if(String(payload[k]).indexOf('_erp_')===0) delete payload[k];
    });
    var ins=await sbInsert('lancamentos',payload);
    if(!ins && (payload.anexo_xml||payload.anexo_pdf||payload.numero_rc||payload.solicitante)){
      var slim=Object.assign({},payload);
      delete slim.anexo_xml; delete slim.anexo_pdf; delete slim.numero_rc; delete slim.solicitante;
      ins=await sbInsert('lancamentos',slim);
      if(ins && typeof progShowToast==='function'){
        progShowToast('⚠ Lançamento salvo sem anexos/RC. Rode sql_lancamentos_anexos_rc.sql no Supabase.','erro');
      }
    }
  }
  closeModal();renderLancamentos();atualizarMetricas();
};

// UPLOAD SUPABASE STORAGE
async function sbUpload(file, path){
  try{
    var SB_BUCKET='cena-docs';
    var url=SB.url+'/storage/v1/object/'+SB_BUCKET+'/'+path;
    var h={'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key),'Content-Type':(file&&file.type)?file.type:'application/octet-stream','x-upsert':'true'};
    var r=await fetch(url,{method:'POST',headers:h,body:file});
    if(r.ok) return SB.url+'/storage/v1/object/public/'+SB_BUCKET+'/'+path;
    // Fallback: converter para base64 e salvar inline
    return await new Promise(function(res){
      var reader=new FileReader();
      reader.onload=function(e){ res(e.target.result); };
      reader.onerror=function(){ res(''); };
      reader.readAsDataURL(file);
    });
  }catch(e){
    // Fallback base64
    try{
      return await new Promise(function(res){
        var reader=new FileReader();
        reader.onload=function(e){ res(e.target.result); };
        reader.onerror=function(){ res(''); };
        reader.readAsDataURL(file);
      });
    }catch(e2){ return ''; }
  }
}

