// RENDER VERBAS com comprometido
var _renderVerbasOrig = renderVerbas;
renderVerbas = function(){
  var cid=(document.getElementById('fil-verb-cont')||{}).value||'';
  if(!cid){document.getElementById('tbody-verb').innerHTML='<tr><td colspan="8" style="padding:1.5rem;text-align:center;color:#aaa">Selecione um contrato</td></tr>';return;}
  var rows=verbas.filter(function(v){return v.contrato_id===cid;});
  var alertasHtml='';
  var totalPlan=0,totalReal=0,totalComp=0;
  document.getElementById('tbody-verb').innerHTML=rows.map(function(v){
    var comp=requisicoes.filter(function(r){return r.contrato_id===cid&&r.categoria_id===v.categoria_id&&r.status==='Pendente';}).reduce(function(s,r){return s+Number(r.valor||0);},0);
    var pct=v.valor_planejado>0?Math.round(v.valor_realizado/v.valor_planejado*100):0;
    var saldo=v.valor_planejado-v.valor_realizado-comp;
    totalPlan+=Number(v.valor_planejado||0);totalReal+=Number(v.valor_realizado||0);totalComp+=comp;
    if(pct>=80)alertasHtml+='<div class="alerta-bar '+(pct>=100?'alerta-100':pct>=90?'alerta-90':'alerta-80')+'">⚠ '+fNomeCat(v.categoria_id)+': '+pct+'% consumido</div>';
    var cor=pct>=100?'#E24B4A':pct>=90?'#EF9F27':pct>=80?'#EF9F27':'#3B6D11';
    return '<tr><td style="font-weight:500">'+fNomeCat(v.categoria_id)+'</td>'      +'<td>'+fmtR(v.valor_planejado)+'</td>'      +'<td style="color:#A32D2D">'+fmtR(v.valor_realizado)+'</td>'      +'<td style="color:#854F0B">'+fmtR(comp)+'</td>'      +'<td style="font-weight:500;color:'+(saldo<0?'#A32D2D':'#3B6D11')+'">'+fmtR(saldo)+'</td>'      +'<td><div style="display:flex;align-items:center;gap:6px"><div class="prog-wrap" style="flex:1"><div class="prog-bar" style="width:'+Math.min(100,pct)+'%;background:'+cor+'"></div></div><span style="font-size:11px;color:'+cor+'">'+pct+'%</span></div></td>'      +'<td><span class="bdg '+(pct>=100?'danger':pct>=90?'warn':pct>=80?'warn':'ok')+'">'+(pct>=100?'Estourado':pct>=90?'Crítico':pct>=80?'Atenção':'Normal')+'</span></td>'      +'<td style="display:flex;gap:4px">'      +'<button class="btn btn-sm" onclick="openEditarVerba(\''+v.id+'\')">Editar</button>'      +'<button class="btn btn-sm" onclick="openNovaRC(\''+cid+'\'\',\''+v.categoria_id+'\')">+ RC</button>'      +'</td></tr>';
  }).join('')||'<tr><td colspan="8" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma verba definida</td></tr>';
  var va=document.getElementById('verbas-alertas');if(va)va.innerHTML=alertasHtml?'<div style="padding:.5rem 0">'+alertasHtml+'</div>':'';
  var vt=document.getElementById('verb-totais');
  if(vt){var st=totalPlan-totalReal-totalComp;var pt=totalPlan>0?Math.round(totalReal/totalPlan*100):0;
    vt.innerHTML='<span style="margin-right:1rem"><b>Planejado:</b> '+fmtR(totalPlan)+'</span><span style="margin-right:1rem"><b>Realizado:</b> '+fmtR(totalReal)+'</span><span style="margin-right:1rem;color:#854F0B"><b>Comprometido (RC):</b> '+fmtR(totalComp)+'</span><span style="color:'+(st<0?'#A32D2D':'#3B6D11')+'"><b>Saldo disponível:</b> '+fmtR(st)+'</span>';}
};

// NOVA REQUISIÇÃO DE COMPRA (RC)
function openNovaRC(cid, catId){
  setModal('<div class="modal-bg"><div class="modal"><h3>Nova Requisição de Compra (RC)</h3>'    +'<div class="g2">'    +'<div class="fg"><label>Número RC</label><input id="rc-num" placeholder="RC-0001"/></div>'    +'<div class="fg"><label>Solicitante</label><input id="rc-sol"/></div>'    +'<div class="fg"><label>Valor estimado (R$)</label><input id="rc-val" type="number" step="0.01" placeholder="0,00"/></div>'    +'<div class="fg"><label>Data RC</label><input id="rc-data" type="date" value="'+dataHojeLocal()+'"/></div>'    +'<div class="fg" style="grid-column:1/-1"><label>Descrição</label><input id="rc-desc" placeholder="Descreva o item da compra"/></div>'    +'</div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-salvar-rc">Salvar RC</button></div></div></div>');
  document.getElementById('btn-salvar-rc').onclick = function(){ salvarRC(cid, catId); };
}
function salvarRC(cid,catId){
  var num=(document.getElementById('rc-num')||{}).value||'';
  var val=parseFloat((document.getElementById('rc-val')||{}).value)||0;
  if(!num.trim()||!val)return alert('Preencha o número da RC e o valor.');
  var nova={id:'rc'+Date.now(),contrato_id:cid,categoria_id:catId,
    numero_rc:num.trim(),
    solicitante:(document.getElementById('rc-sol')||{}).value||'',
    valor:val,
    data_rc:(document.getElementById('rc-data')||{}).value||null,
    descricao:(document.getElementById('rc-desc')||{}).value||'',
    status:'Pendente'};
  requisicoes.push(nova);
  if(!DEMO)sbInsert('requisicoes_compra',_semId(nova));
  closeModal();renderVerbas();
}

// EDITAR E DELETAR CATEGORIAS
function editarCategoria(catId){
  var cat=categorias.find(function(x){return x.id===catId;});if(!cat)return;
  setModal('<div class="modal-bg"><div class="modal"><h3>Editar categoria</h3>'    +'<div class="fg"><label>Nome</label><input id="ecat-nome" value="'+cat.nome+'"/></div>'    +'<div class="fg"><label>Status</label><select id="ecat-ativa"><option value="true"'+(cat.ativa?' selected':'')+'>Ativa</option><option value="false"'+(!cat.ativa?' selected':'')+'>Inativa</option></select></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-salvar-cat">Salvar</button></div></div></div>');
  document.getElementById('btn-salvar-cat').onclick = function(){ salvarEditarCat(catId); };
}
function salvarEditarCat(catId){
  var cat=categorias.find(function(x){return x.id===catId;});if(!cat)return;
  cat.nome=(document.getElementById('ecat-nome')||{}).value||cat.nome;
  cat.ativa=(document.getElementById('ecat-ativa')||{}).value==='true';
  if(!DEMO)sbUpdate('categorias_despesa',{nome:cat.nome,ativa:cat.ativa},'id=eq.'+catId);
  closeModal();renderCadastros();
}
function deletarCategoria(catId){
  var cat=categorias.find(function(x){return x.id===catId;});if(!cat)return;
  if(!confirm('Excluir categoria "'+cat.nome+'"? Esta ação não pode ser desfeita.'))return;
  categorias=categorias.filter(function(c){return c.id!==catId;});
  subcategorias=subcategorias.filter(function(s){return s.categoria_id!==catId;});
  if(!DEMO){
    sbUpdate('categorias_despesa',{ativa:false},'id=eq.'+catId);
  }
  renderCadastros();
}

