function calcSaldoCorrigido(adi){
  var pagas=parcelas_adi.filter(function(p){return p.adiantamento_id===adi.id&&p.status==='Pago';});
  var totalPago=pagas.reduce(function(s,p){return s+Number(p.valor||0);},0);
  var saldoBruto=Number(adi.valor_total||0)-totalPago;
  if(saldoBruto<=0)return 0;
  // correcao mensal simples: (perc_anual/12) ao mes sobre parcelas pendentes
  var mesesRestantes=Number(adi.num_parcelas||0)-pagas.length;
  var percMensal=(Number(adi.perc_correcao||0)/100)/12;
  var saldoCorrigido=saldoBruto*(1+percMensal*mesesRestantes);
  return saldoCorrigido;
}

function renderAdiantamentos(){
  var stCls={Quitado:'ok','Em andamento':'warn',Cancelado:'gray'};
  var tb=document.getElementById('tbody-adi');if(!tb)return;
  tb.innerHTML=adiantamentos.map(function(a){
    var pagas=parcelas_adi.filter(function(p){return p.adiantamento_id===a.id&&p.status==='Pago';}).length;
    var saldoOrig=Number(a.valor_total||0)-parcelas_adi.filter(function(p){return p.adiantamento_id===a.id&&p.status==='Pago';}).reduce(function(s,p){return s+Number(p.valor||0);},0);
    var saldoCorr=calcSaldoCorrigido(a);
    var st=saldoOrig<=0?'Quitado':a.status||'Em andamento';
    return '<tr>'      +'<td style="font-size:11px">'+fNomeCont(a.contrato_id)+'</td>'      +'<td style="font-weight:500">'+fmtR(a.valor_total)+'</td>'      +'<td style="font-size:11px">'+fmtD(a.data_inicio_desconto)+'</td>'      +'<td style="font-size:11px">'+fmtD(a.data_termino_desconto)+'</td>'      +'<td style="text-align:center">'+a.num_parcelas+'</td>'      +'<td style="text-align:center;color:#3B6D11">'+pagas+'</td>'      +'<td style="font-weight:500;color:'+(saldoOrig<=0?'#3B6D11':'#A32D2D')+'">'+fmtR(saldoOrig)+'</td>'      +'<td style="font-weight:500;color:#854F0B">'+fmtR(saldoCorr)+'</td>'      +'<td style="font-size:11px">'+(a.indice||'—')+(a.perc_correcao?' ('+a.perc_correcao+'% a.a.)':'')+'</td>'      +'<td><span class="bdg '+(stCls[st]||'warn')+'">'+st+'</span></td>'      +'<td style="display:flex;gap:4px">'      +'<button class="btn btn-sm" onclick="verParcelas(\''+a.id+'\')">Parcelas</button>'      +'<button class="btn btn-sm" onclick="editarAdiantamento(\''+a.id+'\')">Editar</button>'      +'</td></tr>';
  }).join('')||'<tr><td colspan="11" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum adiantamento cadastrado</td></tr>';
}

function openNovoAdiantamento(){
  var contOpts=contratos.map(function(c){return '<option value="'+c.id+'">'+c.nome+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:580px"><h3>Novo Adiantamento</h3>'    +'<div class="g2">'    +'<div class="fg" style="grid-column:1/-1"><label>Contrato</label><select id="na-cont">'+contOpts+'</select></div>'    +'<div class="fg"><label>Valor total adiantado (R$)</label><input id="na-val" type="number" step="0.01" placeholder="0,00"/></div>'    +'<div class="fg"><label>Nº de parcelas para devolução</label><input id="na-parc" type="number" placeholder="ex: 6"/></div>'    +'<div class="fg"><label>Data início dos descontos</label><input id="na-ini" type="date"/></div>'    +'<div class="fg"><label>Data término dos descontos</label><input id="na-fim" type="date"/></div>'    +'<div class="fg"><label>Índice de correção</label><select id="na-indice"><option value="">Nenhum</option><option value="IPCA">IPCA</option><option value="IGPM">IGP-M</option><option value="INPC">INPC</option></select></div>'    +'<div class="fg"><label>% correção anual prevista</label><input id="na-perc" type="number" step="0.01" placeholder="ex: 4.50"/></div>'    +'</div>'    +'<div class="fg"><label>Observação</label><textarea id="na-obs"></textarea></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-salvar-adi">Salvar adiantamento</button></div></div></div>');
  document.getElementById('btn-salvar-adi').onclick = salvarAdiantamento;
}

function salvarAdiantamento(){
  var cid=(document.getElementById('na-cont')||{}).value||'';
  var val=parseFloat((document.getElementById('na-val')||{}).value)||0;
  var parc=parseInt((document.getElementById('na-parc')||{}).value)||0;
  var ini=(document.getElementById('na-ini')||{}).value||null;
  var fim=(document.getElementById('na-fim')||{}).value||null;
  if(!cid||!val||!parc||!ini)return alert('Preencha contrato, valor, parcelas e data de início.');
  var novo={id:'a'+Date.now(),contrato_id:cid,valor_total:val,num_parcelas:parc,
    data_inicio_desconto:ini,data_termino_desconto:fim,
    indice:(document.getElementById('na-indice')||{}).value||'',
    perc_correcao:parseFloat((document.getElementById('na-perc')||{}).value)||0,
    observacao:(document.getElementById('na-obs')||{}).value||'',
    status:'Em andamento',criado_em:dataHojeLocal()};
  // gerar parcelas automaticamente
  var valParc=Math.floor(val/parc*100)/100;
  var resto=Math.round((val - valParc*parc)*100)/100;
  var dataBase=ini?new Date(ini+'T00:00:00'):new Date();
  for(var i=1;i<=parc;i++){
    var comp=dataBase.getFullYear()+'-'+String(dataBase.getMonth()+1).padStart(2,'0');
    var vp=i===parc?valParc+resto:valParc;
    parcelas_adi.push({id:'pa'+Date.now()+'_'+i,adiantamento_id:novo.id,numero:i,competencia:comp,valor:vp,data_pagamento:null,status:'Pendente'});
    dataBase.setMonth(dataBase.getMonth()+1);
  }
  adiantamentos.push(novo);
  if(!DEMO){
    sbInsert('adiantamentos',_semId(novo));
  }
  closeModal();renderAdiantamentos();
}

function editarAdiantamento(aid){
  var a=adiantamentos.find(function(x){return x.id===aid;});if(!a)return;
  var contOpts=contratos.map(function(c){return '<option value="'+c.id+'"'+(c.id===a.contrato_id?' selected':'')+'>'+c.nome+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:580px"><h3>Editar Adiantamento</h3>'    +'<div class="g2">'    +'<div class="fg" style="grid-column:1/-1"><label>Contrato</label><select id="na-cont">'+contOpts+'</select></div>'    +'<div class="fg"><label>Valor total adiantado (R$)</label><input id="na-val" type="number" value="'+(a.valor_total||0)+'"/></div>'    +'<div class="fg"><label>Nº de parcelas</label><input id="na-parc" type="number" value="'+(a.num_parcelas||0)+'"/></div>'    +'<div class="fg"><label>Data início dos descontos</label><input id="na-ini" type="date" value="'+(a.data_inicio_desconto||'')+'"/></div>'    +'<div class="fg"><label>Data término dos descontos</label><input id="na-fim" type="date" value="'+(a.data_termino_desconto||'')+'"/></div>'    +'<div class="fg"><label>Índice de correção</label><select id="na-indice">'    +['','IPCA','IGPM','INPC'].map(function(i){return '<option value="'+i+'"'+(a.indice===i?' selected':'')+'>'+( i||'Nenhum')+'</option>';}).join('')    +'</select></div>'    +'<div class="fg"><label>% correção anual</label><input id="na-perc" type="number" step="0.01" value="'+(a.perc_correcao||0)+'"/></div>'    +'</div>'    +'<div class="fg"><label>Observação</label><textarea id="na-obs">'+(a.observacao||'')+'</textarea></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-edit-adi">Salvar</button></div></div></div>');
  document.getElementById('btn-edit-adi').onclick = function(){ salvarEditarAdi(aid); };
}

function salvarEditarAdi(aid){
  var a=adiantamentos.find(function(x){return x.id===aid;});if(!a)return;
  a.contrato_id=(document.getElementById('na-cont')||{}).value||a.contrato_id;
  a.valor_total=parseFloat((document.getElementById('na-val')||{}).value)||a.valor_total;
  a.num_parcelas=parseInt((document.getElementById('na-parc')||{}).value)||a.num_parcelas;
  a.data_inicio_desconto=(document.getElementById('na-ini')||{}).value||a.data_inicio_desconto;
  a.data_termino_desconto=(document.getElementById('na-fim')||{}).value||a.data_termino_desconto;
  a.indice=(document.getElementById('na-indice')||{}).value||'';
  a.perc_correcao=parseFloat((document.getElementById('na-perc')||{}).value)||0;
  a.observacao=(document.getElementById('na-obs')||{}).value||'';
  if(!DEMO)sbUpdate('adiantamentos',a,'id=eq.'+aid);
  closeModal();renderAdiantamentos();
}

function verParcelas(aid){
  var a=adiantamentos.find(function(x){return x.id===aid;});if(!a)return;
  var det=document.getElementById('adi-detalhe');
  if(det)det.style.display='block';
  var tit=document.getElementById('adi-detalhe-titulo');
  if(tit)tit.textContent='Parcelas — '+fNomeCont(a.contrato_id)+' ('+fmtR(a.valor_total)+')';
  var btn=document.getElementById('btn-nova-parcela');
  if(btn)btn.onclick=function(){openRegistrarParcela(aid);};
  renderParcelasAdi(aid);
  det.scrollIntoView({behavior:'smooth'});
}

function renderParcelasAdi(aid){
  var rows=parcelas_adi.filter(function(p){return p.adiantamento_id===aid;});
  rows.sort(function(a,b){return a.numero-b.numero;});
  var stCls={Pago:'teal',Pendente:'warn',Cancelado:'gray'};
  var totalPago=rows.filter(function(p){return p.status==='Pago';}).reduce(function(s,p){return s+Number(p.valor||0);},0);
  var totalPend=rows.filter(function(p){return p.status==='Pendente';}).reduce(function(s,p){return s+Number(p.valor||0);},0);
  var tb=document.getElementById('tbody-adi-parcelas');
  if(tb)tb.innerHTML=rows.map(function(p){
    return '<tr>'      +'<td style="text-align:center;font-weight:500">'+p.numero+'/'+rows.length+'</td>'      +'<td>'+fmtMesAno(p.competencia)+'</td>'      +'<td style="font-weight:500">'+fmtR(p.valor)+'</td>'      +'<td style="font-size:11px;color:#888">'+(p.data_pagamento?fmtD(p.data_pagamento):'—')+'</td>'      +'<td><span class="bdg '+(stCls[p.status]||'gray')+'">'+p.status+'</span></td>'      +'<td>'      +(p.status==='Pendente'?'<button class="btn btn-sm" id="btn-pagar-pa-'+p.id+'">Marcar pago</button>':'')      +'</td></tr>';
  }).join('')||'<tr><td colspan="6" style="padding:1rem;text-align:center;color:#aaa">Nenhuma parcela</td></tr>';
  // Adicionar eventos após render
  rows.filter(function(p){return p.status==='Pendente';}).forEach(function(p){
    var btn=document.getElementById('btn-pagar-pa-'+p.id);
    if(btn)btn.onclick=function(){marcarParcelaPaga(p.id,aid);};
  });
  var tot=document.getElementById('adi-parcelas-totais');
  if(tot)tot.innerHTML='<span style="margin-right:1.5rem"><b>Pago:</b> '+fmtR(totalPago)+'</span>'    +'<span style="margin-right:1.5rem;color:#854F0B"><b>Pendente:</b> '+fmtR(totalPend)+'</span>'    +'<span style="color:#A32D2D"><b>Saldo corrigido ('+( adiantamentos.find(function(x){return x.id===aid;})||{}).indice||'—'+'):</b> '+fmtR(calcSaldoCorrigido(adiantamentos.find(function(x){return x.id===aid;})||{}))+'</span>';
}

function marcarParcelaPaga(pid, aid){
  var p=parcelas_adi.find(function(x){return x.id===pid;});if(!p)return;
  p.status='Pago';p.data_pagamento=dataHojeLocal();
  if(!DEMO)sbUpdate('parcelas_adiantamento',{status:'Pago',data_pagamento:p.data_pagamento},'id=eq.'+pid);
  renderParcelasAdi(aid);renderAdiantamentos();
}

function openRegistrarParcela(aid){
  var a=adiantamentos.find(function(x){return x.id===aid;});if(!a)return;
  var proxNum=parcelas_adi.filter(function(p){return p.adiantamento_id===aid;}).length+1;
  setModal('<div class="modal-bg"><div class="modal"><h3>Registrar parcela manual</h3>'    +'<div class="g2">'    +'<div class="fg"><label>Nº da parcela</label><input id="rp-num" type="number" value="'+proxNum+'"/></div>'    +'<div class="fg"><label>Competência (AAAA-MM)</label><input id="rp-comp" value="'+mesAnoAtual()+'"/></div>'    +'<div class="fg"><label>Valor do desconto (R$)</label><input id="rp-val" type="number" step="0.01" placeholder="0,00"/></div>'    +'<div class="fg"><label>Data pagamento</label><input id="rp-data" type="date" value="'+dataHojeLocal()+'"/></div>'    +'</div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-salvar-rp">Salvar</button></div></div></div>');
  document.getElementById('btn-salvar-rp').onclick=function(){
    var nova={id:'pa'+Date.now(),adiantamento_id:aid,
      numero:parseInt((document.getElementById('rp-num')||{}).value)||proxNum,
      competencia:(document.getElementById('rp-comp')||{}).value||mesAnoAtual(),
      valor:parseFloat((document.getElementById('rp-val')||{}).value)||0,
      data_pagamento:(document.getElementById('rp-data')||{}).value||null,
      status:'Pago'};
    if(!nova.valor)return alert('Informe o valor.');
    parcelas_adi.push(nova);
    if(!DEMO)sbInsert('parcelas_adiantamento',_semId(nova));
    closeModal();renderParcelasAdi(aid);renderAdiantamentos();
  };
}


