function openImportarFornecedores(){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:580px"><h3>Importar Fornecedores em massa</h3>'    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">Cole um fornecedor por linha. Formato aceito:<br>'    +'<b>Razão Social</b> (só nome) ou <b>Razão Social ; CNPJ/CPF ; Tipo</b><br>'    +'Tipos: Fornecedor, Locadora, Prestador, Transportadora (padrão: Fornecedor)</div>'    +'<textarea id="massa-forn" style="width:100%;height:150px;border:.5px solid #e0dfd8;border-radius:8px;padding:8px;font-size:12px;resize:vertical" placeholder="Posto Combustíveis Ltda&#10;ScafFlex Andaimes ; 98.765.432/0001-11 ; Locadora&#10;EPI Nordeste ; 11.222.333/0001-44"></textarea>'    +'<div id="forn-import-feedback" style="font-size:12px;margin-top:6px"></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-imp-forn">Importar</button></div></div></div>');
  document.getElementById('btn-imp-forn').onclick = function(){
    var txt=(document.getElementById('massa-forn')||{}).value||'';
    var linhas=txt.split('\n').map(function(s){return s.trim();}).filter(function(s){return s.length>0;});
    if(!linhas.length){document.getElementById('forn-import-feedback').innerHTML='<span style="color:#A32D2D">Nenhum item encontrado.</span>';return;}
    var existentes=fornecedores.map(function(f){return f.razao_social.toLowerCase();});
    var importados=0,duplicados=0;
    linhas.forEach(function(linha,i){
      var partes=linha.split(';').map(function(p){return p.trim();});
      var nome=partes[0];
      if(!nome)return;
      if(existentes.indexOf(nome.toLowerCase())>=0){duplicados++;return;}
      var novo={id:'f'+Date.now()+'x'+i,
        razao_social:nome,
        cnpj_cpf:partes[1]||'',
        tipo:partes[2]||'Fornecedor',
        contato:'',telefone:'',email:'',status:'Ativo'};
      fornecedores.push(novo);
      if(!DEMO)sbInsert('fornecedores',_semId(novo));
      importados++;
    });
    var fb=document.getElementById('forn-import-feedback');
    if(fb){
      var msg='<span style="color:#3B6D11">✓ '+importados+' fornecedor(es) importado(s).</span>';
      if(duplicados>0)msg+=' <span style="color:#888">('+duplicados+' já existia(m) — ignorado(s))</span>';
      fb.innerHTML=msg;
    }
    setTimeout(function(){closeModal();renderCadastros();},700);
  };
}

