// EM CAMPO — PWA / offline
// ═══════════════════════════════════════════════════════
var _campoProjAtual = null;
var _campoServicosReg = []; // serviços do registro atual
var _offlineQueue = [];     // fila offline

// Offline: salvar/carregar fila local
function offlineSave(item){
  _offlineQueue.push(item);
  try{localStorage.setItem('cena_offline_queue',JSON.stringify(_offlineQueue));}catch(e){}
}
function offlineLoad(){
  try{var q=localStorage.getItem('cena_offline_queue');if(q)_offlineQueue=JSON.parse(q);}catch(e){}
}
function offlineSync(){
  if(!_offlineQueue.length)return;
  var q=_offlineQueue.slice();
  _offlineQueue=[];
  try{localStorage.removeItem('cena_offline_queue');}catch(e){}
  q.forEach(function(item){
    if(item.type==='exec'){execucoes.push(item.data);if(!DEMO)sbInsert('execucoes_obra',Object.assign({},item.data,{fotos:JSON.stringify(item.data.fotos||[]),id:undefined}));}
    else if(item.type==='mov'){mov_sap.push(item.data);if(!DEMO)sbInsertMovSap(item.data);}
    else if(item.type==='sol'){sol_materiais.push(item.data);if(!DEMO)sbInsert('sol_materiais',Object.assign({},item.data,{id:undefined}));}
  });
}


var veiculos = []; // {id, placa, modelo, marca, ano, cor, tipo, status, contratos_ids:[]}
var _veiculosCarregadosDB = false;
var sol_materiais = []; // {id, projeto_id, encarregado_nome, descricao, qtd, unidade, motivo, status, data}

// Monitorar conexão
window.addEventListener('online', function(){offlineSync();});
offlineLoad();

function isOnline(){return navigator.onLine;}

function renderCampo(){
  if(!usuarioLogado)return;
  var el=document.getElementById('campo-usuario-nome');
  if(el)el.textContent=usuarioLogado.nome+' — '+(usuarioLogado.celular||'');
  voltarCampoLista();
}

function voltarCampoLista(){
  document.getElementById('campo-projetos').style.display='block';
  document.getElementById('campo-detalhe').style.display='none';
  _campoProjAtual=null;
  _campoServicosReg=[];

  var lista=document.getElementById('campo-lista-proj');if(!lista)return;
  
  // Admin vê todos os projetos; encarregado vê só os atribuídos
  var projs;
  if(usuarioLogado.perfil==='admin'){
    projs=projetos.filter(function(p){return p.status==='Em andamento'||p.status==='Planejado';});
  } else {
    var meusProjs=proj_encarregados.filter(function(pe){
      return pe.nome===usuarioLogado.nome||pe.usuario_id===usuarioLogado.id;
    }).map(function(pe){return pe.projeto_id;});
    projs=projetos.filter(function(p){return meusProjs.indexOf(p.id)>=0;});
  }

  if(!projs.length){
    var msgEmpty=usuarioLogado.perfil==='admin'?'Nenhum projeto em andamento. Crie projetos na aba 🏚️ Obras.':'Nenhum projeto atribuído a você. Contate a administração.';
    lista.innerHTML='<div style="text-align:center;padding:2rem;color:#aaa;font-size:13px">'+msgEmpty+'</div>';
    return;
  }

  var stCls={'Em andamento':'ok',Concluído:'teal',Suspenso:'warn',Planejado:'info'};
  lista.innerHTML=projs.map(function(p){
    var execsHoje=execucoes.filter(function(e){return e.projeto_id===p.id&&e.nome_enc===usuarioLogado.nome&&e.data===dataHojeLocal();}).length;
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1.1rem;cursor:pointer" id="campo-card-'+p.id+'">'      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:.5rem">'      +'<div style="font-weight:600;font-size:13px">'+p.codigo+' — '+p.nome+'</div>'      +'<span class="bdg '+(stCls[p.status]||'gray')+'">'+p.status+'</span>'      +'</div>'      +'<div style="font-size:11px;color:#888;margin-bottom:.5rem">'+fNomeCont(p.contrato_id)+' | Prazo: '+fmtD(p.data_prazo)+'</div>'      +(execsHoje?'<div style="font-size:11px;color:#3B6D11">✓ '+execsHoje+' registro(s) hoje</div>':'')      +'<button class="btn btn-pri" style="width:100%;margin-top:.75rem;padding:8px" id="btn-entrar-'+p.id+'">Entrar no projeto</button>'      +'</div>';
  }).join('');

  projs.forEach(function(p){
    var b=document.getElementById('btn-entrar-'+p.id);
    if(b)b.onclick=function(){abrirProjCampo(p.id);};
  });
}

function abrirProjCampo(pid){
  _campoProjAtual=pid;
  _campoServicosReg=[];
  var p=projetos.find(function(x){return x.id===pid;});if(!p)return;
  document.getElementById('campo-proj-nome').textContent=p.codigo+' — '+p.nome;
  document.getElementById('campo-proj-contrato').textContent=fNomeCont(p.contrato_id);
  document.getElementById('campo-projetos').style.display='none';
  document.getElementById('campo-detalhe').style.display='block';

  // Preencher data padrão
  var hoje=dataHoje();
  var dd=document.getElementById('c-exec-data');if(dd)dd.value=hoje;
  var dm=document.getElementById('c-mat-data');if(dm)dm.value=hoje;

  // Popular materiais do projeto
  popularMatCampo(pid);
  campoShowSub('exec');
  renderCampoServicosReg();
}

function campoShowSub(sub){
  ['exec','mat','hist'].forEach(function(s){
    var el=document.getElementById('campo-sub-'+s);
    if(el)el.style.display=s===sub?'block':'none';
    var btn=document.getElementById('btn-campo-'+s);
    if(btn){btn.style.background=s===sub?'#1a1a18':'';btn.style.color=s===sub?'#fff':'';}
  });
  if(sub==='hist')renderCampoHistorico();
}

function popularMatCampo(pid){
  var proj=projetos.find(function(x){return x.id===pid;});if(!proj)return;
  // Materiais pré-selecionados para o projeto
  var matsProj=proj.materiais_projeto||[];
  var mats=matsProj.length
    ?mat_sap.filter(function(m){return matsProj.indexOf(m.id)>=0;})
    :mat_sap.filter(function(m){return m.contrato_id===proj.contrato_id;});
  var sel=document.getElementById('c-mat-item');if(!sel)return;
  sel.innerHTML='<option value="">Selecione o material</option>'+mats.map(function(m){
    return '<option value="'+m.id+'">'+m.codigo_sap+' — '+m.descricao+' (saldo: '+m.saldo_disponivel+' '+m.unidade+')</option>';
  }).join('');
}

// Serviços do registro atual
function renderCampoServicosReg(){
  var lista=document.getElementById('campo-servicos-lista');if(!lista)return;
  if(!_campoServicosReg.length){
    lista.innerHTML='<div style="color:#aaa;font-size:12px;padding:.25rem 0">Nenhum serviço adicionado</div>';
    return;
  }
  lista.innerHTML=_campoServicosReg.map(function(s,i){
    return '<div style="display:flex;justify-content:space-between;align-items:center;background:#f9f9f7;border-radius:8px;padding:7px 10px;margin-bottom:5px;font-size:12px">'      +'<div><div style="font-weight:500">'+s.descricao+'</div><div style="color:#888">'+s.qtd+' '+s.unidade+' × '+fmtR(s.valor_unit)+'</div></div>'      +'<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" id="rm-cs-'+i+'">✕</button>'      +'</div>';
  }).join('');
  _campoServicosReg.forEach(function(s,i){
    var b=document.getElementById('rm-cs-'+i);
    if(b)b.onclick=function(){_campoServicosReg.splice(i,1);renderCampoServicosReg();};
  });
  var btnAdd=document.getElementById('btn-add-campo-serv');
  if(btnAdd)btnAdd.onclick=function(){openAdicionarServicoCampo();};
}

function openAdicionarServicoCampo(){
  if(!_campoProjAtual)return;
  var proj=projetos.find(function(x){return x.id===_campoProjAtual;});if(!proj)return;
  // Serviços pré-selecionados para o projeto
  var servsProj=proj.servicos_projeto||[];
  var servsFiltrados=servsProj.length
    ?servicos.filter(function(s){return servsProj.indexOf(s.id)>=0;})
    :servicos.filter(function(s){return s.contrato_id===proj.contrato_id;});
  var opts=servsFiltrados.map(function(s){
    var val = s.valor_ups && s.valor_ups > 0 ? s.valor_ups : (s.valor_hora || 0);
    return '<option value="'+s.id+'" data-desc="'+(s.descricao||'')+'" data-uni="'+(s.unidade||'UN')+'" data-val="'+val+'">'+( s.codigo?s.codigo+' — ':'')+s.descricao+'</option>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal"><h3>Adicionar Serviço</h3>'    +'<div class="fg"><label>Serviço</label><select id="cs-serv" style="width:100%" onchange="preencherServCampo()">'+opts+'</select></div>'    +'<div class="g2">'    +'<div class="fg"><label>Qtd executada</label><input id="cs-qtd" type="number" step="0.01" style="width:100%" placeholder="0"/></div>'    +'<div class="fg"><label>Valor unit. (R$)</label><input id="cs-val" type="number" step="0.01" style="width:100%"/></div>'    +'</div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-add-cs">Adicionar</button></div></div></div>');
  preencherServCampo();
  document.getElementById('btn-add-cs').onclick=function(){
    var sel=document.getElementById('cs-serv');
    var opt=sel?sel.options[sel.selectedIndex]:null;
    var qtd=parseFloat((document.getElementById('cs-qtd')||{}).value)||0;
    var val=parseFloat((document.getElementById('cs-val')||{}).value)||0;
    if(!qtd)return alert('Informe a quantidade.');
    _campoServicosReg.push({
      servico_id:(sel||{}).value||'',
      descricao:opt?opt.getAttribute('data-desc'):'',
      unidade:opt?opt.getAttribute('data-uni'):'UN',
      qtd:qtd,valor_unit:val
    });
    closeModal();renderCampoServicosReg();
  };
}

function preencherServCampo(){
  var sel=document.getElementById('cs-serv');if(!sel)return;
  var opt=sel.options[sel.selectedIndex];
  var val=document.getElementById('cs-val');
  if(val&&opt)val.value=opt.getAttribute('data-val')||'';
}

// Salvar execução (com suporte offline)
document.addEventListener('DOMContentLoaded',function(){
  var btn=document.getElementById('btn-salvar-campo-exec');
  if(btn)btn.addEventListener('click',async function(){
    if(!_campoProjAtual||!usuarioLogado)return;
    var atv=(document.getElementById('c-exec-atv')||{}).value.trim()||'';
    if(!atv)return alert('Descreva a atividade executada.');
    var fotosUrls=[];
    var arquivos=(document.getElementById('c-exec-fotos')||{}).files;
    if(arquivos&&arquivos.length&&isOnline()&&!DEMO){
      for(var i=0;i<arquivos.length;i++){
        var url=await sbUpload(arquivos[i],'obras/'+_campoProjAtual+'/'+Date.now()+'_'+arquivos[i].name);
        if(url)fotosUrls.push(url);
      }
    }
    var novo={id:'ex'+Date.now(),projeto_id:_campoProjAtual,encarregado_id:usuarioLogado.id||'',
      nome_enc:usuarioLogado.nome,
      data:(document.getElementById('c-exec-data')||{}).value||dataHojeLocal(),
      atividade:atv,
      status_exec:(document.getElementById('c-exec-st')||{}).value||'Em execução',
      obs:(document.getElementById('c-exec-obs')||{}).value||'',
      fotos:fotosUrls};
    // Salvar serviços
    var exServs=_campoServicosReg.map(function(s){return Object.assign({id:'es'+Date.now()+'_'+Math.random(),execucao_id:novo.id},s);});

    if(isOnline()){
      execucoes.push(novo);
      exServs.forEach(function(s){exec_servicos.push(s);});
      if(!DEMO){
        sbInsert('execucoes_obra',Object.assign({},novo,{fotos:JSON.stringify(fotosUrls),id:undefined}));
        exServs.forEach(function(s){sbInsert('exec_servicos',_semId(s));});
      }
      document.getElementById('campo-exec-offline-msg').style.display='none';
    } else {
      offlineSave({type:'exec',data:novo,servicos:exServs});
      document.getElementById('campo-exec-offline-msg').style.display='block';
    }

    // Limpar form
    document.getElementById('c-exec-atv').value='';
    document.getElementById('c-exec-obs').value='';
    document.getElementById('c-exec-fotos').value='';
    document.getElementById('c-exec-fotos-prev').innerHTML='';
    _campoServicosReg=[];
    renderCampoServicosReg();
    alert('✓ Registro salvo'+(isOnline()?'':' localmente — será enviado quando conectar')+'!');
  });

  // Preview fotos campo
  var fotoInput=document.getElementById('c-exec-fotos');
  if(fotoInput)fotoInput.addEventListener('change',function(ev){
    var prev=document.getElementById('c-exec-fotos-prev');if(!prev)return;prev.innerHTML='';
    Array.from(ev.target.files).forEach(function(f){
      var url=URL.createObjectURL(f);
      prev.innerHTML+='<img src="'+url+'" style="width:70px;height:70px;object-fit:cover;border-radius:6px;border:.5px solid #e0dfd8"/>';
    });
  });

  // Salvar movimentação material
  var btnMat=document.getElementById('btn-salvar-campo-mat');
  if(btnMat)btnMat.addEventListener('click',function(){
    if(!_campoProjAtual||!usuarioLogado)return;
    var mid=(document.getElementById('c-mat-item')||{}).value||'';
    var qtd=parseFloat((document.getElementById('c-mat-qtd')||{}).value)||0;
    var tipo=(document.getElementById('c-mat-tipo')||{}).value||'Retirada';
    if(!mid||!qtd)return alert('Selecione o material e informe a quantidade.');
    var mat=mat_sap.find(function(x){return x.id===mid;});
    var novo={id:'mv'+Date.now(),projeto_id:_campoProjAtual,encarregado_id:usuarioLogado.id||'',
      nome_enc:usuarioLogado.nome,material_id:mid,
      descricao_mat:mat?mat.descricao:'',tipo:tipo,qtd:qtd,
      unidade:mat?mat.unidade:'UN',
      data:(document.getElementById('c-mat-data')||{}).value||dataHojeLocal(),
      status:'Confirmado'};
    if(isOnline()){
      mov_sap.push(novo);
      if(mat){if(tipo==='Retirada')mat.saldo_disponivel-=qtd;else if(tipo==='Devolução')mat.saldo_disponivel+=qtd;}
      if(!DEMO)sbInsertMovSap(novo);
      document.getElementById('campo-mat-offline-msg').style.display='none';
    } else {
      offlineSave({type:'mov',data:novo});
      document.getElementById('campo-mat-offline-msg').style.display='block';
    }
    document.getElementById('c-mat-qtd').value='';
    popularMatCampo(_campoProjAtual);
    alert('✓ Movimentação registrada'+(isOnline()?'':' localmente')+'!');
  });

  // Solicitar material extra
  var btnSol=document.getElementById('btn-salvar-campo-sol');
  if(btnSol)btnSol.addEventListener('click',function(){
    if(!_campoProjAtual||!usuarioLogado)return;
    var desc=(document.getElementById('c-sol-desc')||{}).value.trim()||'';
    var qtd=parseFloat((document.getElementById('c-sol-qtd')||{}).value)||0;
    if(!desc||!qtd)return alert('Preencha a descrição e quantidade.');
    var nova={id:'sol'+Date.now(),projeto_id:_campoProjAtual,
      encarregado_nome:usuarioLogado.nome,
      descricao:desc,qtd:qtd,
      unidade:(document.getElementById('c-sol-uni')||{}).value||'UN',
      motivo:(document.getElementById('c-sol-mot')||{}).value||'',
      status:'Pendente',
      data:dataHojeLocal()};
    if(isOnline()){
      sol_materiais.push(nova);
      if(!DEMO)sbInsert('sol_materiais',_semId(nova));
    } else {
      offlineSave({type:'sol',data:nova});
    }
    document.getElementById('c-sol-desc').value='';
    document.getElementById('c-sol-qtd').value='';
    document.getElementById('c-sol-uni').value='';
    document.getElementById('c-sol-mot').value='';
    alert('✓ Solicitação enviada para aprovação!');
  });
});

function renderCampoHistorico(){
  if(!_campoProjAtual||!usuarioLogado)return;
  var execs=execucoes.filter(function(e){return e.projeto_id===_campoProjAtual&&e.nome_enc===usuarioLogado.nome;});
  execs.sort(function(a,b){return b.data>a.data?1:-1;});
  var lista=document.getElementById('campo-hist-lista');
  if(lista){
    lista.innerHTML=execs.length?execs.map(function(e){
      var servs=exec_servicos.filter(function(s){return s.execucao_id===e.id;}).length;
      var stCls={'Totalmente executado':'teal','Parcialmente executado':'warn','Não iniciado':'gray','Em execução':'ok'};
      return '<div style="border:.5px solid #e0dfd8;border-radius:10px;padding:.85rem;margin-bottom:.65rem">'        +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.4rem">'        +'<div style="font-size:12px;font-weight:500">'+fmtD(e.data)+'</div>'        +'<span class="bdg '+(stCls[e.status_exec]||'gray')+'">'+e.status_exec+'</span>'        +'</div>'        +'<div style="font-size:12px">'+e.atividade+'</div>'        +(e.obs?'<div style="font-size:11px;color:#888;margin-top:4px">'+e.obs+'</div>':'')        +'<div style="font-size:11px;color:#888;margin-top:4px">'+servs+' serviço(s) | '+(e.fotos?e.fotos.length:0)+' foto(s)</div>'        +'</div>';
    }).join(''):'<div style="color:#aaa;font-size:12px">Nenhum registro neste projeto</div>';
  }

  // Saldo materiais
  var movs=mov_sap.filter(function(m){return m.projeto_id===_campoProjAtual&&m.nome_enc===usuarioLogado.nome;});
  var saldoMap={};
  movs.forEach(function(m){
    if(!saldoMap[m.descricao_mat])saldoMap[m.descricao_mat]={mat:m.descricao_mat,uni:m.unidade,ret:0,baixa:0,dev:0};
    if(m.tipo==='Retirada')saldoMap[m.descricao_mat].ret+=Number(m.qtd||0);
    else if(m.tipo==='Baixa aplicação')saldoMap[m.descricao_mat].baixa+=Number(m.qtd||0);
    else if(m.tipo==='Devolução')saldoMap[m.descricao_mat].dev+=Number(m.qtd||0);
  });
  var sm=document.getElementById('campo-saldo-mat');
  if(sm){
    var items=Object.values(saldoMap);
    sm.innerHTML=items.length?items.map(function(r){
      var saldo=r.ret-r.baixa-r.dev;
      return '<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:.5px solid #f0efe8;font-size:12px">'        +'<div>'+r.mat+'</div>'        +'<div style="font-weight:600;color:'+(saldo>0?'#854F0B':saldo===0?'#3B6D11':'#A32D2D')+'">'+saldo+' '+r.uni+'</div>'        +'</div>';
    }).join(''):'<div style="color:#aaa;font-size:12px">Nenhuma movimentação</div>';
  }
}

// Solicitações de material extra — visível na aprovação administrativa
function renderSolicitacoesMat(){
  var pend=sol_materiais.filter(function(s){return s.status==='Pendente';});
  return pend;
}

// Seleção de serviços/materiais por projeto (admin)
function openSelecionarItensProj(pid, tipo){
  var p=projetos.find(function(x){return x.id===pid;});if(!p)return;
  var atual=tipo==='servicos'?(p.servicos_projeto||[]):(p.materiais_projeto||[]);
  var lista=tipo==='servicos'
    ?servicos.filter(function(s){return s.contrato_id===p.contrato_id;})
    :mat_sap.filter(function(m){return m.contrato_id===p.contrato_id;});
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px"><h3>'+(tipo==='servicos'?'Serviços':'Materiais')+' do projeto — '+p.nome+'</h3>'    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">Selecione os itens disponíveis para este projeto:</div>'    +'<div style="max-height:300px;overflow-y:auto">'    +lista.map(function(item){
      var checked=atual.indexOf(item.id)>=0?'checked':'';
      return '<label style="display:flex;align-items:center;gap:8px;padding:6px;cursor:pointer;font-size:12px;border-bottom:.5px solid #f0efe8">'        +'<input type="checkbox" value="'+item.id+'" '+checked+' style="width:16px;height:16px"/>'        +(tipo==='servicos'?(item.codigo?'<b>'+item.codigo+'</b> — ':'')+item.descricao:item.codigo_sap+' — '+item.descricao)        +'</label>';
    }).join('')    +'</div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-salvar-itens-proj">Salvar seleção</button></div></div></div>');
  document.getElementById('btn-salvar-itens-proj').onclick=function(){
    var checkboxes=document.querySelectorAll('#modal-area input[type=checkbox]');
    var selecionados=[];
    checkboxes.forEach(function(cb){if(cb.checked)selecionados.push(cb.value);});
    if(tipo==='servicos')p.servicos_projeto=selecionados;
    else p.materiais_projeto=selecionados;
    if(!DEMO)sbUpdate('projetos_obra',tipo==='servicos'?{servicos_projeto:JSON.stringify(selecionados)}:{materiais_projeto:JSON.stringify(selecionados)},'id=eq.'+pid);
    closeModal();
    alert('✓ '+(tipo==='servicos'?'Serviços':'Materiais')+' do projeto atualizados!');
  };
}



