function fNomeTipoEq(tid){var t=tipos_equipe.find(function(x){return x.id===tid;});return t?t.nome:'—';}
function fNomeColaborador(cid){var c=colaboradores.find(function(x){return x.id===cid;});return c?c.nome:'—';}

function msToHHMM(ms){
  var total=Math.floor(ms/1000);
  var h=Math.floor(total/3600);var m=Math.floor((total%3600)/60);var s=total%60;
  return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
}


// Utilitário: parsear campo que pode vir como string JSON ou já ser array/objeto
function parseJsonField(val, defaultVal){
  if(!val)return defaultVal;
  if(typeof val==='string'){try{return JSON.parse(val);}catch(e){return defaultVal;}}
  return val;
}
function renderDiario(){
  if(!usuarioLogado) return;
  console.log('[renderDiario] chamado — perfil:', usuarioLogado.perfil, 'contrato:', usuarioLogado.contrato_id, '_dbEquipe:', _dbEquipe&&_dbEquipe.id);

  var hoje = dataHojeLocal(); // DEVE ficar aqui — usado em TODOS os fluxos (TMA, PLPT, admin)

  var PLPT_CID_DB = CONTRATOS_UUID_MAP['PLPT'];
  var contratoPLPT = usuarioLogado.contrato_id === PLPT_CID_DB;
  var irParaDiarioCampo = usuarioLogado.perfil==='equipe' ||
    (usuarioLogado.perfil==='encarregado' && contratoTemFluxoProjeto(usuarioLogado.contrato_id));

  if(!irParaDiarioCampo){
    if(!DEMO && _dbEquipe){
      Promise.all([
        sbFetch('sessoes_disponibilidade',{filters:['data=eq.'+hoje,'equipe_id=eq.'+_dbEquipe.id],order:'login_ts.desc'}),
        sbFetch('plpt_sessoes',{filters:['data=eq.'+hoje,'equipe_id=eq.'+_dbEquipe.id],order:'login_ts.desc'}),
        sbFetch('turnos_abertos',{filters:['data=eq.'+hoje,'equipe_id=eq.'+_dbEquipe.id]}),
        sbFetch('ordens_diario',{filters:['data=eq.'+hoje,'equipe_id=eq.'+_dbEquipe.id]}),
        sbFetch('composicao_dia',{filters:['equipe_id=eq.'+_dbEquipe.id,'data=eq.'+hoje]}),
        sbFetch('colaboradores',{filters:['equipe_id=eq.'+_dbEquipe.id,'ativo=eq.true'],order:'nome'}),
      ]).then(function(res){
        // Mesclar sessoes TMA + PLPT
        var sessTMA  = (res[0]||[]).map(function(s){s.eventos=parseJsonField(s.eventos,[]);s._tipo='TMA';return s;});
        var sessPLPT = (res[1]||[]).map(function(s){s.eventos=parseJsonField(s.eventos,[]);s._tipo='PLPT';return s;});
        var todasSess = sessTMA.concat(sessPLPT);
        todasSess.forEach(function(s){
          var idx=sessoes_disp.findIndex(function(x){return x.id===s.id;});
          if(idx>=0) sessoes_disp[idx]=s; else sessoes_disp.push(s);
        });
        // Atualizar composicao_dia com dados frescos — preservar motorista_id em memória
        if(res[4]&&res[4].length){
          _mergeComposicaoDia(res[4][0]);
        }
        // Atualizar colaboradores da equipe
        if(res[5]&&res[5].length){
          res[5].forEach(function(c){
            var ci=colaboradores.findIndex(function(x){return x.id===c.id;});
            if(ci>=0) colaboradores[ci]=c; else colaboradores.push(c);
          });
        }
        if(res[2]&&res[2].length) res[2].forEach(function(t){
          t.respostas_epi=parseJsonField(t.respostas_epi,[]);
          t.respostas_vei=parseJsonField(t.respostas_vei,[]);
          var i=turnos_abertos.findIndex(function(x){return x.id===t.id;});
          if(i>=0) turnos_abertos[i]=t; else turnos_abertos.push(t);
        });
        if(res[3]&&res[3].length) res[3].forEach(function(o){
          o.eventos=parseJsonField(o.eventos,[]);
          if(!ordens_db.find(function(x){return x.id===o.id;})) ordens_db.push(o);
        });
        _renderDiarioAdmin();
      }).catch(function(){_renderDiarioAdmin();});
    } else {
      _renderDiarioAdmin();
    }
    return;
  }
  // Encontrar equipe do usuário — priorizar escala do dia sobre equipe fixa do cadastro
  if(!_dbEquipe){
    var _reLogin0=(usuarioLogado.email||'').split('@')[0];
    var _colab0=colaboradores.find(function(c){
      return (_reLogin0 && c.re===_reLogin0) || c.re===usuarioLogado.re;
    });
    var compHoje0=_findComposicaoColaborador(_colabIdsParaBusca(_colab0, _reLogin0), hoje);
    if(compHoje0 && compHoje0.equipe_id){
      var eqEsc=equipes_disp.find(function(e){return e.id===compHoje0.equipe_id;})
               ||equipes.find(function(e){return e.id===compHoje0.equipe_id;});
      if(eqEsc){
        _dbEquipe=_buildDbEquipeObj(eqEsc);
        usuarioLogado.equipe_id=eqEsc.id;
        try{ var _lsE=JSON.parse(localStorage.getItem('cena_user')||'{}'); _lsE.equipe_id=eqEsc.id; localStorage.setItem('cena_user',JSON.stringify(_lsE)); }catch(e){}
      }
    }
  }
  if(!_dbEquipe && usuarioLogado.perfil!=='equipe'){
    _dbEquipe=equipes_disp.find(function(e){return e.id===usuarioLogado.equipe_id||e.codigo===usuarioLogado.equipe_codigo;});
  }
  console.log('[renderDiario] equipes_disp.find:', !!_dbEquipe, '| equipes_disp.length:', equipes_disp.length, '| equipe_id:', usuarioLogado.equipe_id);

  // Fallback: equipe fixa do colaborador (somente se não escalado hoje; perfil equipe usa programação)
  if(!_dbEquipe && !usuarioLogado.equipe_id && !DEMO && usuarioLogado.perfil!=='equipe'){
    var re = (usuarioLogado.email||'').split('@')[0];
    var colabLocal = colaboradores.find(function(c){ return c.re===re; });
    if(colabLocal && colabLocal.equipe_id){
      usuarioLogado.equipe_id = colabLocal.equipe_id;
      _dbEquipe = equipes_disp.find(function(e){return e.id===colabLocal.equipe_id;})
               || equipes.find(function(e){return e.id===colabLocal.equipe_id;});
      if(_dbEquipe && equipes.find(function(e){return e.id===colabLocal.equipe_id;})){
        var eqP = equipes.find(function(e){return e.id===colabLocal.equipe_id;});
        _dbEquipe = {id:eqP.id,codigo:eqP.nome_equipe,nome:eqP.nome_equipe,
          supervisor:eqP.supervisor,contrato_id:eqP.contrato_id,
          tipo:eqP.cargo||'',status:eqP.status,_plpt:true};
      }
    }
  }

  // Tentar em equipes PLPT/Obras se não achou em equipes_disp (perfil equipe: só via programação)
  if(!_dbEquipe && usuarioLogado.equipe_id && usuarioLogado.perfil!=='equipe'){
    var eqPlpt = equipes.find(function(e){return e.id===usuarioLogado.equipe_id;})
              || equipes_disp.find(function(e){return e.id===usuarioLogado.equipe_id;});
    if(eqPlpt){
      _dbEquipe = {
        id:          eqPlpt.id,
        codigo:      eqPlpt.nome_equipe||eqPlpt.codigo||'',
        nome:        eqPlpt.nome_equipe||eqPlpt.nome||'',
        supervisor:  eqPlpt.supervisor||'',
        contrato_id: eqPlpt.contrato_id||usuarioLogado.contrato_id||'',
        tipo:        eqPlpt.cargo||eqPlpt.tipo||'',
        status:      eqPlpt.status||'',
        _plpt:       !equipes_disp.some(function(e){return e.id===eqPlpt.id;}) && contratoTemFluxoProjeto(eqPlpt.contrato_id||usuarioLogado.contrato_id)
      };
    } else if(!DEMO){
      // Não encontrada nos arrays locais (pode ter status diferente) — buscar direto por ID
      console.log('[renderDiario] equipe não encontrada localmente, buscando do banco:', usuarioLogado.equipe_id);
      Promise.all([
        sbFetch('equipes',{filters:['id=eq.'+usuarioLogado.equipe_id]}),
        sbFetch('equipes_disp',{filters:['id=eq.'+usuarioLogado.equipe_id]})
      ]).then(function(res){
        var eq = (res[0]&&res[0][0]) || (res[1]&&res[1][0]);
        if(eq){
          _dbEquipe = {
            id:          eq.id,
            codigo:      eq.nome_equipe||eq.codigo||'',
            nome:        eq.nome_equipe||eq.nome||'',
            supervisor:  eq.supervisor||'',
            contrato_id: eq.contrato_id||usuarioLogado.contrato_id||'',
            tipo:        eq.cargo||eq.tipo||'',
            status:      eq.status||'',
            _plpt:       !equipes_disp.some(function(e){return e.id===eq.id;}) && contratoTemFluxoProjeto(eq.contrato_id||usuarioLogado.contrato_id)
          };
          if(!equipes.find(function(x){return x.id===eq.id;})) equipes.push(eq);
          console.log('[renderDiario] equipe encontrada no banco:', eq.id, '_plpt:', _dbEquipe._plpt);
          renderDiario();
        }
      }).catch(function(){});
      return;
    }
  }

  // Se não achou localmente E tem equipe_id/codigo no usuário, buscar do banco (exceto perfil equipe — usa programação)
  if(!_dbEquipe && !DEMO && usuarioLogado.perfil!=='equipe' && (usuarioLogado.equipe_id||usuarioLogado.equipe_codigo)){
    // Detectar se é UUID real (36 chars com hífens) ou ID local demo
    var eqId = usuarioLogado.equipe_id||'';
    var eqCod = usuarioLogado.equipe_codigo||'';
    var isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(eqId);

    // Buscar em equipes_disp E equipes (PLPT) em paralelo
    Promise.all([
      sbFetch('equipes_disp',{filters:['status=eq.Ativo'],order:'codigo'}),
      sbFetch('equipes',{filters:['status=neq.Inativo']})
    ]).then(function(res){
      var resDisp  = res[0]||[];
      var resPlpt  = res[1]||[];

      resDisp.forEach(function(e){
        if(!equipes_disp.find(function(x){return x.id===e.id;})) equipes_disp.push(e);
      });
      resPlpt.forEach(function(e){
        if(!equipes.find(function(x){return x.id===e.id;})) equipes.push(e);
      });

      // Tentar achar em equipes_disp
      _dbEquipe = equipes_disp.find(function(e){
        return (isUUID && e.id===eqId) || (!isUUID && eqCod && e.codigo===eqCod) || (!isUUID && eqId && e.codigo===eqId);
      });

      // Tentar em equipes PLPT
      if(!_dbEquipe){
        var eqP = equipes.find(function(e){ return e.id===eqId; });
        if(eqP) _dbEquipe = {
          id:eqP.id, codigo:eqP.nome_equipe, nome:eqP.nome_equipe,
          supervisor:eqP.supervisor, contrato_id:eqP.contrato_id,
          tipo:eqP.cargo||'', status:eqP.status, _plpt:true
        };
      }
      if(_dbEquipe){
        renderDiario();
      } else {
        // Equipe não achada em equipes_disp — ir para dashboard
        document.getElementById('pg-diario').classList.add('hidden');
        /* pg-app-content removido */;
        var hdr=document.getElementById('hdr-principal');if(hdr)hdr.style.display='';
        var nm=document.getElementById('nav-main');if(nm&&window.innerWidth>=768)nm.style.display='flex';
        showMain('dashboard');
      }
    }).catch(function(e){
      console.error('Erro ao buscar equipes:',e);
      var wrap=document.getElementById('pg-diario');
      if(wrap) wrap.innerHTML='<div style="padding:2rem;text-align:center"><div style="font-size:32px">⚠️</div><div style="font-size:13px;color:#888;margin-top:.5rem">Erro ao carregar equipes. Verifique a conexão.</div><button class="btn" onclick="fazerLogout()" style="margin-top:1rem">Sair</button></div>';
    });
    return; // aguardar busca
  }

  // Recarregar composição do dia do banco para ter UUIDs atualizados
  // composicao_dia será buscada junto com as sessoes abaixo
  if(!_dbEquipe){
    // Colaborador de campo sem equipe fixa — buscar na programação do dia
    if(!DEMO && usuarioLogado.id){
      var hoje2 = dataHoje();

      var _cids = (usuarioLogado.contrato_id||'').split(',').map(function(s){return s.trim();}).filter(Boolean);
      var _cidFilter = _cids.length===1 ? 'contrato_id=eq.'+_cids[0] : 'contrato_id=in.('+_cids.join(',')+')';

      var dbNome = document.getElementById('db-equipe-nome');
      if(dbNome) dbNome.textContent = '⏳ Buscando sua programação...';

      // Buscar colaborador pelo email ou usuario_id para obter o ID correto
      Promise.all([
        sbFetch('composicao_dia', {filters:['data=eq.'+hoje2]}),
        sbFetch('equipes', {filters:[_cidFilter,'status=eq.Ativo']}),
        sbFetch('equipes_disp', {filters:['status=eq.Ativo']}),
        sbFetch('colaboradores', {filters:[_cidFilter,'ativo=eq.true']})
      ]).then(function(res){
        var comps   = res[0]||[];
        var eqsPlpt = res[1]||[];
        var eqsDisp = res[2]||[];
        var colabs  = res[3]||[];

        // Atualizar arrays globais
        eqsPlpt.forEach(function(e){ if(!equipes.find(function(x){return x.id===e.id;})) equipes.push(e); });
        eqsDisp.forEach(function(e){ if(!equipes_disp.find(function(x){return x.id===e.id;})) equipes_disp.push(e); });
        colabs.forEach(function(c){ if(!colaboradores.find(function(x){return x.id===c.id;})) colaboradores.push(c); });
        comps.forEach(function(c){
          c.colaborador_ids = parseJsonField(c.colaborador_ids, []);
          if(!composicao_dia.find(function(x){return x.id===c.id;})) composicao_dia.push(c);
        });

      // Buscar colaborador pelo email/nome/usuario_id para obter o ID correto
        var _reLogin = (usuarioLogado.email||'').split('@')[0];
        var colabPorEmail = colabs.find(function(c){
          if(!c) return false;
          return (_reLogin && c.re===_reLogin) || c.re===usuarioLogado.re;
        });
        var colabId = colabPorEmail ? colabPorEmail.id : usuarioLogado.id;
        var idsParaBuscar = [colabId];
        if(colabPorEmail && colabPorEmail.id !== usuarioLogado.id) idsParaBuscar.push(usuarioLogado.id);

        // Carregar veículos do dia
        progCarregarVeiculos(hoje2);

        // Encontrar composição onde este colaborador está escalado hoje
        var compDoColaborador = comps.find(function(c){
          var ids = parseJsonField(c.colaborador_ids, []);
          return idsParaBuscar.some(function(bid){ return ids.indexOf(bid) >= 0; });
        });

        if(compDoColaborador){
          // Buscar equipe correspondente nos arrays carregados
          var eqEncontrada = equipes.find(function(e){return e.id===compDoColaborador.equipe_id;})
            || equipes_disp.find(function(e){return e.id===compDoColaborador.equipe_id;});

          if(eqEncontrada){
            _dbEquipe = {
              id:          eqEncontrada.id,
              codigo:      eqEncontrada.nome_equipe || eqEncontrada.codigo || eqEncontrada.nome,
              nome:        eqEncontrada.nome_equipe || eqEncontrada.nome || eqEncontrada.codigo,
              supervisor:  eqEncontrada.supervisor,
              contrato_id: eqEncontrada.contrato_id,
              tipo:        eqEncontrada.cargo||eqEncontrada.tipo||'',
              status:      eqEncontrada.status,
              _plpt:       !!eqEncontrada.nome_equipe
            };
            // Persistir equipe_id para evitar loop no próximo renderDiario()
            usuarioLogado.equipe_id = eqEncontrada.id;
            try{ var _ls=JSON.parse(localStorage.getItem('cena_user')||'{}'); _ls.equipe_id=eqEncontrada.id; localStorage.setItem('cena_user',JSON.stringify(_ls)); }catch(e){}
            renderDiario();
            return;
          }

          // Equipe não está nos arrays locais — usar equipe_id da composição diretamente
          // Buscar detalhes da equipe no banco e renderizar
          _dbEquipe = {
            id:          compDoColaborador.equipe_id,
            nome:        usuarioLogado.nome || 'Equipe PLPT',
            tipo:        'PLPT',
            codigo:      '',
            supervisor:  '',
            contrato_id: usuarioLogado.contrato_id,
            _plpt:       contratoTemFluxoProjeto(usuarioLogado.contrato_id)
          };
          // Persistir equipe_id para evitar loop
          usuarioLogado.equipe_id = compDoColaborador.equipe_id;
          try{ var _ls2=JSON.parse(localStorage.getItem('cena_user')||'{}'); _ls2.equipe_id=compDoColaborador.equipe_id; localStorage.setItem('cena_user',JSON.stringify(_ls2)); }catch(e){}
          // Tentar buscar dados reais da equipe
          if(!DEMO){
            sbFetch('equipes',{filters:['id=eq.'+compDoColaborador.equipe_id]}).then(function(res){
              if(res&&res[0]){
                var eq=res[0];
                _dbEquipe.nome  = eq.nome_equipe||eq.nome||_dbEquipe.nome;
                _dbEquipe.tipo  = eq.cargo||eq.tipo||_dbEquipe.tipo;
                _dbEquipe.supervisor = eq.supervisor||'';
                _dbEquipe.codigo = eq.codigo||'';
                _dbEquipe._plpt  = true;
                if(!equipes.find(function(x){return x.id===eq.id;})) equipes.push(eq);
              }
              // Usar renderDiario() para passar pelo fluxo completo de restauração de sessão
              if(!_plptModalTurnoAberto) renderDiario();
            }).catch(function(){ if(!_plptModalTurnoAberto) renderDiario(); });
          } else {
            if(!_plptModalTurnoAberto) renderDiario();
          }
          return;
        }

        // Não está programado hoje — verificar se é PLPT (fluxo projeto)
        if(contratoTemFluxoProjeto(usuarioLogado.contrato_id)){
          // Usar equipe_id do usuário ou da composição encontrada
          var eqIdFallback = (compDoColaborador && compDoColaborador.equipe_id)
            || usuarioLogado.equipe_id || null;

          if(!_dbEquipe){
            // Tentar encontrar nome real da equipe nos arrays
            var eqReal = equipes.find(function(e){return e.id===eqIdFallback;});
            _dbEquipe = {
              id:          eqIdFallback || 'sem-equipe',
              nome:        (eqReal && (eqReal.nome_equipe||eqReal.nome)) || usuarioLogado.nome || 'Equipe PLPT',
              tipo:        (eqReal && (eqReal.cargo||eqReal.tipo)) || 'PLPT',
              codigo:      (eqReal && (eqReal.codigo||eqReal.nome_equipe)) || '',
              supervisor:  (eqReal && eqReal.supervisor) || '',
              contrato_id: usuarioLogado.contrato_id,
              _plpt:       true
            };
          }

          // Carregar veículos antes de renderizar
          var _hojeFallback = dataHoje();
          if(!DEMO && eqIdFallback){
            sbFetch('prog_veiculos_dia',{filters:['equipe_id=eq.'+eqIdFallback,'data=eq.'+_hojeFallback]})
              .then(function(rows){
                if(rows&&rows.length){
                  rows.forEach(function(r){
                    _progVeiculos[r.equipe_id+'_'+_hojeFallback]={
                      placa:r.placa,modelo:r.modelo,id:r.veiculo_id,
                      justificativa:r.justificativa,alterado_por:r.alterado_por
                    };
                  });
                }
                if(!_plptModalTurnoAberto) renderDiario();
              }).catch(function(){ if(!_plptModalTurnoAberto) renderDiario(); });
          } else {
            if(!_plptModalTurnoAberto) renderDiario();
          }
          return;
        }
        // TMA sem programação — mostrar mensagem no HTML estático
        var dbNome2 = document.getElementById('db-equipe-nome');
        if(dbNome2) dbNome2.textContent = 'Sem programação para hoje';
        var dbTipo2 = document.getElementById('db-equipe-tipo');
        if(dbTipo2) dbTipo2.textContent = 'Aguarde o encarregado confirmar sua programação';
        var dbAcoes = document.getElementById('db-acoes-wrap')||document.querySelector('#pg-diario [style*="padding:.75rem 1rem"]');
        if(dbAcoes) dbAcoes.style.display='none';
      }).catch(function(e){
        console.error('Erro ao buscar programação:', e);
        var dbNome3 = document.getElementById('db-equipe-nome');
        if(dbNome3) dbNome3.textContent = '⚠️ Erro ao buscar programação';
      });
      return;
    }
    // DEMO ou sem ID: ir para dashboard
    document.getElementById('pg-diario').classList.add('hidden');
    var hdr=document.getElementById('hdr-principal');if(hdr)hdr.style.display='';
    var nm=document.getElementById('nav-main');if(nm&&window.innerWidth>=768)nm.style.display='flex';
    showMain('dashboard');
    return;
  }

  var hoje=dataHoje();
  var el=document.getElementById('db-equipe-nome');
  if(el) el.textContent=_dbEquipe?(_dbEquipe.codigo||_dbEquipe.nome||'Equipe'):'';
  var et=document.getElementById('db-equipe-tipo');if(et)et.textContent=_dbEquipe?(_dbEquipe.tipo||fNomeTipoEq(_dbEquipe.tipo_id)||''):'';
  var ed=document.getElementById('db-data-hoje');if(ed)ed.textContent=fmtD(hoje);

  // Contrato badge
  var contBadge=document.getElementById('db-contrato-badge');
  if(contBadge && _dbEquipe){
    var cont=contratos.find(function(c){return c.id===_dbEquipe.contrato_id;});
    contBadge.textContent=cont?cont.codigo:'';
  }

  // Supervisor
  var supEl=document.getElementById('db-supervisor-nome');
  if(supEl && _dbEquipe) supEl.textContent=_dbEquipe.supervisor||'—';

  // Membros chips
  var membrosEl=document.getElementById('db-membros-chips');
  if(membrosEl && _dbEquipe){
    var membros=colaboradores.filter(function(c){
      return c.equipe_id===_dbEquipe.id && c.ativo!==false;
    });
    // Também pegar da composicao_dia se disponível
    var comp=_findComposicaoEquipe(_dbEquipe.id, hoje);
    if(comp){
      var idsComp=Array.isArray(comp.colaborador_ids)?comp.colaborador_ids.filter(Boolean)
        :(function(){return parseColabIds(comp.colaborador_ids)}());
      if(idsComp.length){
        membros=idsComp.map(function(id){return colaboradores.find(function(c){return c.id===id;});}).filter(Boolean);
      }
    }
    membrosEl.innerHTML=membros.length
      ? membros.map(function(c){
          var ini=(c.nome||'?').charAt(0).toUpperCase();
          var partes=(c.nome||'').split(' ');
          var nomeC=partes[0]+(partes[1]?' '+partes[1].charAt(0)+'.':'');
          return '<span title="'+c.nome+'" style="display:inline-flex;align-items:center;gap:3px;background:#EAF3DE;color:#3B6D11;border-radius:4px;padding:1px 6px;font-size:10px;font-weight:500">'
            +'<span style="width:14px;height:14px;border-radius:50%;background:#3B6D11;color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:8px;font-weight:700">'+ini+'</span>'
            +nomeC+'</span>';
        }).join('')
      : '<span style="font-size:10px;color:#aaa">Sem membros escalados</span>';
  }

  // Veículo da equipe — múltiplos fallbacks
  var veicInfoEl = document.getElementById('db-veiculo-info');
  if(veicInfoEl && _dbEquipe){
    var placa = '';
    var modelo = '';

    // 1. Sessão ativa (KM disponível)
    if(_dbSessao && _dbSessao.placa){ placa = _dbSessao.placa; }

    // 2. Turno aberto de hoje
    if(!placa){
      var turnoHoje = (turnos_abertos||[]).find(function(t){
        return t.equipe_id===_dbEquipe.id && t.data===hoje;
      });
      if(turnoHoje && turnoHoje.placa) placa = turnoHoje.placa;
    }

    // 3. Programação do dia (progGetVeiculo / localStorage)
    if(!placa){
      var veicProg = (typeof progGetVeiculo==='function') ? progGetVeiculo(_dbEquipe.id, hoje) : null;
      if(veicProg && veicProg.placa){ placa = veicProg.placa; modelo = veicProg.modelo||''; }
    }

    // 4. Veículo vinculado diretamente à equipe no cadastro
    if(!placa){
      var vEq = (frt_veiculos||[]).find(function(v){
        return v.equipe_id===_dbEquipe.id && v.ativo!==false;
      }) || (veiculos||[]).find(function(v){
        return v.equipe_id===_dbEquipe.id;
      });
      if(vEq){ placa = vEq.placa||''; modelo = vEq.modelo||vEq.tipo||''; }
    }

    if(placa){
      veicInfoEl.style.display = '';
      var plEl = document.getElementById('db-veiculo-placa');
      if(plEl) plEl.textContent = placa;
      if(!modelo){
        var vFrt = (frt_veiculos||[]).find(function(v){return v.placa===placa;})
                || (veiculos||[]).find(function(v){return v.placa===placa;});
        modelo = vFrt ? (vFrt.modelo||vFrt.tipo||'') : '';
      }
      var modEl = document.getElementById('db-veiculo-modelo');
      if(modEl) modEl.textContent = modelo;
      var kmEl = document.getElementById('db-km-ini-label');
      if(kmEl) kmEl.textContent = (_dbSessao&&_dbSessao.km_inicial) ? _dbSessao.km_inicial+' km' : '—';
      var kfWrap = document.getElementById('db-km-final-wrap');
      var kfLbl  = document.getElementById('db-km-fin-label');
      if(_dbSessao && _dbSessao.km_final){
        if(kfWrap) kfWrap.style.display = '';
        if(kfLbl)  kfLbl.textContent = _dbSessao.km_final+' km';
      }
    } else {
      veicInfoEl.style.display = 'none';
    }
  }

  // Para contratos de projeto: marcar _plpt e carregar veículos (mas NÃO renderizar aqui — o bloco abaixo cuida da sessão)
  if(_dbEquipe && contratoTemFluxoProjeto(_dbEquipe.contrato_id||usuarioLogado.contrato_id)){
    var contDiario2 = contratos.find(function(c){return c.id===(_dbEquipe.contrato_id||usuarioLogado.contrato_id);});
    // Verificar se é TMA (equipes_disp) — TMA NUNCA usa fluxo PLPT
    var isTMAEquipe = equipes_disp.some(function(e){ return e.id === _dbEquipe.id; });
    var isDisponibilidade2 = isTMAEquipe ||
      (contDiario2 && (contDiario2.modalidade_trabalho||'').toLowerCase().includes('disponibilidade'));
    if(!isDisponibilidade2){
      _dbEquipe._plpt = true;
      // Carregar veículos em background sem interromper fluxo de sessão
      if(!DEMO){
        var _hoje3=dataHoje();
        sbFetch('prog_veiculos_dia',{filters:['equipe_id=eq.'+_dbEquipe.id,'data=eq.'+_hoje3]})
          .then(function(rows){
            if(rows&&rows.length){
              rows.forEach(function(r){
                _progVeiculos[r.equipe_id+'_'+_hoje3]={
                  placa:r.placa,modelo:r.modelo,id:r.veiculo_id,
                  justificativa:r.justificativa,alterado_por:r.alterado_por
                };
              });
            }
            // NÃO chamar renderDiarioPlpt aqui — o bloco de sessão abaixo cuida disso
          }).catch(function(){});
      }
      // Continua para o bloco de sessão abaixo (sem return)
    }
  }

  // Para equipes com fluxo de projeto (PLPT e demais contratos habilitados):
  // TMA (Disponibilidade) usa o fluxo estático do diário de bordo - NÃO substituir pg-diario
  // TMA: equipes em equipes_disp NUNCA usam fluxo PLPT
  var _isTMAEquipeDisp = _dbEquipe && equipes_disp.some(function(e){ return e.id === _dbEquipe.id; });
  if(_isTMAEquipeDisp) {
    _dbEquipe._plpt = false;
  }

  if(!_isTMAEquipeDisp && (_dbEquipe && _dbEquipe._plpt || (usuarioLogado.contrato_id && contratoTemFluxoProjeto(usuarioLogado.contrato_id)))){
    // Se contrato é Disponibilidade → usar fluxo estático, não renderDiarioPlpt
    var contDiario = contratos.find(function(c){return c.id===usuarioLogado.contrato_id;});
    if(contDiario && (contDiario.modalidade_trabalho==='Disponibilidade' || _isTMAEquipeDisp)){
      // Fluxo estático: apenas carregar dados e atualizar botões
      _dbEquipe._plpt = false; // não usar fluxo PLPT
      if(!_dbSessao){
        _dbSessao = sessoes_disp.find(function(s){
          return s.equipe_id===_dbEquipe.id && s.data===hoje;
        })||null;
      }
      if(_dbSessao) _dbSessao.eventos = parseJsonField(_dbSessao.eventos,[]);
      // Restaurar ordem ativa se houver
      if(!_dbOrdemAtual){
        _dbOrdemAtual = ordens_db.find(function(o){
          return o.equipe_id===_dbEquipe.id && o.data===hoje
            && ['a_caminho','no_local','em_andamento','encerrando'].indexOf(o.status)>=0;
        })||null;
        if(_dbOrdemAtual) _dbOrdemAtual.eventos = parseJsonField(_dbOrdemAtual.eventos,[]);
      }
      dbAtualizarBotoes();
      renderDbComposicao();
      renderDbOrdemAtual();
      renderDbOrdensDia();
      renderDbHistoricoSessao();
      // Popular supervisão do diário
      dbIniciarSupervisionSection();
      return;
    }
    // Marcar equipe como "fluxo projeto" se ainda não marcada
    if(!_dbEquipe){
      // _dbEquipe ainda não chegou do banco — aguardar (fetch async vai chamar renderDiario novamente)
      console.log('[PLPT RELOAD] _dbEquipe nulo — aguardando fetch async');
      return;
    }
    if(!_dbEquipe._plpt) _dbEquipe._plpt = true;
    console.log('[PLPT RELOAD] equipe_id', _dbEquipe.id, 'data hoje', hoje, 'dataHojeLocal=', dataHojeLocal());
    console.log('[PLPT RELOAD] _dbEquipe._plpt=', _dbEquipe._plpt, 'contrato=', _dbEquipe.contrato_id);
    var CID_FETCH = (_dbEquipe && _dbEquipe.contrato_id) || (usuarioLogado && usuarioLogado.contrato_id) || '';
    // Buscar programação do dia para esta equipe específica
    // Buscar prog do dia — hoje primeiro, depois dias recentes (turno aberto de ontem)
    var d3dias = new Date(Date.now()-3*24*60*60*1000).toISOString().slice(0,10);
    sbFetch('plpt_prog_dia',{filters:[
      'equipe_id=eq.'+_dbEquipe.id,
      'data=gte.'+d3dias,
      'contrato_id=eq.'+CID_FETCH
    ], order:'data.desc', limit:5}).then(function(resP){
      // Preferir prog de hoje; se não houver, pegar o mais recente com sessão aberta
      var progHoje = (resP||[]).find(function(p){ return (p.data||'').slice(0,10)===hoje; });
      var prog = progHoje || (resP&&resP[0]) || null;
      _plptDiario.prog = prog;

      if(!prog){
        // Sem plpt_prog_dia — buscar colaboradores E sessão do dia
        Promise.all([
          sbFetch('colaboradores',{filters:['contrato_id=eq.'+CID_FETCH,'equipe_id=eq.'+_dbEquipe.id,'ativo=eq.true'],order:'nome'}),
          sbFetch('plpt_sessoes',{filters:['equipe_id=eq.'+_dbEquipe.id],order:'login_ts.desc',limit:10}),
          sbFetch('composicao_dia',{filters:['equipe_id=eq.'+_dbEquipe.id,'data=eq.'+hoje]})
        ]).then(function(resArr){
          var cols = resArr[0]||[];
          var sessRows = resArr[1]||[];

          // Função para escolher melhor sessão da lista
          function _escolherMelhorSessao(rows){
            var melhor = null; var sc = -1;
            rows.forEach(function(s){
              if(s.logout_ts && s.logout_ts !== 0 && s.logout_ts !== '0') return;
              var evs = parseJsonField(s.eventos, []);
              var score = evs.length + (evs.some(function(e){ return e.tipo==='_PROJ_STATE'; }) ? 100 : 0);
              if(score > sc){ sc = score; melhor = s; }
            });
            if(!melhor && rows.length) melhor = rows[0];
            return {row: melhor, score: sc};
          }

          var res1 = _escolherMelhorSessao(sessRows);
          var sessRow = res1.row; var melhorScore = res1.score;
          console.log('[PLPT RELOAD] plpt_sessoes:', sessRows.length, 'escolhida:', sessRow&&sessRow.id, 'score:', melhorScore);

          // Continuar com o resto independentemente — fallback para sessoes_disponibilidade se necessário
          function _continuarComSessao(sr){
          var compRow = resArr[2]&&resArr[2][0] ? resArr[2][0] : null;
          cols.forEach(function(c){
            var ci=colaboradores.findIndex(function(x){return x.id===c.id;});
            if(ci>=0) colaboradores[ci]=c; else colaboradores.push(c);
          });
          if(compRow){
            compRow.colaborador_ids=parseJsonField(compRow.colaborador_ids,[]);
            var ci=composicao_dia.findIndex(function(x){return x.equipe_id===_dbEquipe.id&&x.data===hoje;});
            if(ci>=0) composicao_dia[ci]=compRow; else composicao_dia.push(compRow);
            if(compRow.confirmada) _plptDiario.composConfirm=true;
          }
          if(sr && !_plptDiario.sessao){
            _plptRestaurarSessao(sr);
            _plptDiario.composConfirm = true;
          } else if(!sr && !_plptDiario.sessao){
            // Fallback: tentar restaurar do localStorage
            var localEstado = _plptCarregarLocal();
            if(localEstado && localEstado.sessao && localEstado.sessao.inicio_ts){
              console.log('[PLPT RELOAD] restaurando do localStorage');
              _plptDiario.sessao = localEstado.sessao;
              _plptDiario.composConfirm = true;
              if(localEstado.projetoAtivo && localEstado.projetoAtivo._pjId){
                var pj = localEstado.projetoAtivo;
                _plptDiario.projetos.push(pj);
                _plptDiario.projetoAtivo = pj;
              }
            } else if(!DEMO && _dbEquipe){
              // Último fallback: buscar turno aberto de dia anterior (virada de dia)
              console.log('[PLPT RELOAD] iniciando fallback busca turno anterior para equipe:', _dbEquipe.id);
              sbFetch('plpt_sessoes',{
                filters:['equipe_id=eq.'+_dbEquipe.id],
                order:'login_ts.desc', limit:10
              }).then(function(rows){
                console.log('[PLPT RELOAD] fallback rows:', rows&&rows.length, rows&&rows.map(function(r){return r.id+'/'+r.data+'/logout:'+r.logout_ts;}));
                var aberta = (rows||[]).find(function(s){
                  return !s.logout_ts || s.logout_ts===0 || s.logout_ts==='0';
                });
                if(aberta){
                  console.log('[PLPT RELOAD] turno aberto de dia anterior:', aberta.id, 'data:', aberta.data);
                  // Adicionar ao array se não existir
                  if(!sessoes_disp.find(function(x){return x.id===aberta.id;})){
                    aberta.eventos = parseJsonField(aberta.eventos,[]);
                    sessoes_disp.push(aberta);
                  }
                  _plptRestaurarSessao(aberta);
                }
                if(!_plptModalTurnoAberto) renderDiarioPlpt();
              }).catch(function(){ if(!_plptModalTurnoAberto) renderDiarioPlpt(); });
              return; // renderDiarioPlpt será chamado no .then acima
            }
          }
          if(!_plptDiario.projetos) _plptDiario.projetos = [];
          if(!_plptModalTurnoAberto) renderDiarioPlpt();
          } // fim _continuarComSessao

          if(sessRow){
            _continuarComSessao(sessRow);
          } else {
            // plpt_sessoes vazia — checar sessoes_disponibilidade (sessões antigas/migração)
            console.log('[PLPT RELOAD] plpt_sessoes vazia, verificando sessoes_disponibilidade...');
            sbFetch('sessoes_disponibilidade',{filters:['equipe_id=eq.'+_dbEquipe.id],order:'login_ts.desc',limit:10})
              .then(function(rowsAntigos){
                var res2 = _escolherMelhorSessao(rowsAntigos||[]);
                console.log('[PLPT RELOAD] sessoes_disponibilidade:', (rowsAntigos||[]).length, 'score:', res2.score);
                _continuarComSessao(res2.row);
              }).catch(function(){ _continuarComSessao(null); });
          }
        }).catch(function(err){ console.error('[PLPT RELOAD] ERRO no fetch sem prog:', err); _plptDiario.projetos=[]; if(!_plptModalTurnoAberto) renderDiarioPlpt(); });
        return;
      }

      // 2. Buscar projetos programados para este prog_dia específico
      Promise.all([
        sbFetch('plpt_prog_projetos',{filters:['prog_dia_id=eq.'+prog.id],order:'ordem'}),
        sbFetch('colaboradores',{filters:['contrato_id=eq.'+CID_FETCH,'equipe_id=eq.'+_dbEquipe.id,'ativo=eq.true'],order:'nome'}),
      ]).then(function(res){
        var progProjs = res[0]||[];
        var cols      = res[1]||[];

        // Atualizar colaboradores
        cols.forEach(function(c){
          var ci=colaboradores.findIndex(function(x){return x.id===c.id;});
          if(ci>=0) colaboradores[ci]=c; else colaboradores.push(c);
        });

        _plptDiario.projetos = progProjs;

        // 3. Carregar dados reais dos sot_projetos se não estiverem em memória
        var projIds = progProjs.map(function(p){return p.projeto_id;}).filter(Boolean);
        var faltam  = projIds.filter(function(id){
          return !sot_projetos.find(function(x){return x.id===id;});
        });

        // 4. Recuperar sessão — plpt_sessoes primeiro, fallback sessoes_disponibilidade
        var buscarSessao = !DEMO
          ? Promise.all([
              sbFetch('plpt_sessoes',{filters:['equipe_id=eq.'+_dbEquipe.id],order:'login_ts.desc',limit:10}),
              sbFetch('sessoes_disponibilidade',{filters:['equipe_id=eq.'+_dbEquipe.id],order:'login_ts.desc',limit:10})
            ]).then(function(rs){ return (rs[0]||[]).concat(rs[1]||[]); })
          : Promise.resolve([]);

        Promise.all([
          faltam.length && !DEMO
            ? sbFetch('sot_projetos',{filters:['id=in.('+faltam.join(',')+')'],limit:200})
            : Promise.resolve([]),
          buscarSessao
        ]).then(function(r2){
          var projRows  = r2[0]||[];
          var sessRows  = r2[1]||[];
          var sessaoRow = null; var _sc2 = -1;
          sessRows.forEach(function(s){
            if(s.logout_ts && s.logout_ts !== 0 && s.logout_ts !== '0') return;
            var evs = parseJsonField(s.eventos, []);
            var score = evs.length + (evs.some(function(e){ return e.tipo==='_PROJ_STATE'; }) ? 100 : 0);
            if(score > _sc2){ _sc2 = score; sessaoRow = s; }
          });
          if(!sessaoRow && sessRows.length) sessaoRow = sessRows[0];
          console.log('[PLPT RELOAD] (com prog) sessRows:', sessRows.length, 'sessaoRow:', sessaoRow&&sessaoRow.id, 'score:', _sc2);

          projRows.forEach(function(p){
            if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p);
          });

          if(sessaoRow && !_plptDiario.sessao){
            // Check if this session is from today or a previous day
            var sessData = (sessaoRow.data||'').slice(0,10);
            var hoje2    = dataHojeLocal();
            if(sessData && sessData === hoje2){
              // Session from TODAY — restore normally (same day continuation)
              _plptRestaurarSessao(sessaoRow);
            } else if(sessData && sessData !== hoje2){
              // Session from PREVIOUS DAY — restore timer/state BUT NOT projetoAtivo
              // Today's prog_dia defines what projects are active today
              _plptRestaurarSessaoMinima(sessaoRow);
              // Mark as "virada de dia" so the banner shows
              _plptDiario._turnoViradaDia = true;
            } else {
              // No date info — restore normally
              _plptRestaurarSessao(sessaoRow);
            }
          } else if(!sessaoRow && !_plptDiario.sessao){
            var localEstadoProg = _plptCarregarLocal();
            if(localEstadoProg && localEstadoProg.sessao && localEstadoProg.sessao.inicio_ts){
              console.log('[PLPT RELOAD] restaurando do localStorage (com prog)');
              _plptDiario.sessao = localEstadoProg.sessao;
              _plptDiario.composConfirm = true;
              if(localEstadoProg.projetoAtivo && localEstadoProg.projetoAtivo._pjId){
                var pjProg = localEstadoProg.projetoAtivo;
                if(!_plptDiario.projetos.find(function(p){return p._pjId===pjProg._pjId;}))
                  _plptDiario.projetos.push(pjProg);
                _plptDiario.projetoAtivo = pjProg;
              }
            } else if(!DEMO && _dbEquipe){
              // Último fallback: buscar turno aberto de dia anterior (virada de dia)
              sbFetch('plpt_sessoes',{
                filters:['equipe_id=eq.'+_dbEquipe.id],
                order:'login_ts.desc', limit:10
              }).then(function(rows){
                var aberta = (rows||[]).find(function(s){
                  return !s.logout_ts || s.logout_ts===0 || s.logout_ts==='0';
                });
                if(aberta){
                  console.log('[PLPT RELOAD] turno aberto de dia anterior (com prog):', aberta.id, 'data:', aberta.data);
                  if(!sessoes_disp.find(function(x){return x.id===aberta.id;})){
                    aberta.eventos = parseJsonField(aberta.eventos,[]);
                    sessoes_disp.push(aberta);
                  }
                  _plptRestaurarSessao(aberta);
                }
                if(!_plptModalTurnoAberto) renderDiarioPlpt();
              }).catch(function(){ if(!_plptModalTurnoAberto) renderDiarioPlpt(); });
              return;
            }
          }

          if(!_plptModalTurnoAberto) renderDiarioPlpt();
        }).catch(function(err){ console.error('[PLPT RELOAD] ERRO no fetch com prog:', err); if(!_plptModalTurnoAberto) renderDiarioPlpt(); });
      }).catch(function(err){
        console.error('[PLPT RELOAD] ERRO no fetch prog_projetos:', err);
        _plptDiario.projetos = [];
        if(!_plptModalTurnoAberto) renderDiarioPlpt();
      });

    }).catch(function(err){
      console.error('[PLPT RELOAD] ERRO no fetch plpt_prog_dia:', err);
      _plptDiario.prog     = null;
      _plptDiario.projetos = [];
      if(!_plptModalTurnoAberto) renderDiarioPlpt();
    });
    return;
  }

  // Recuperar sessão do dia
  _dbSessao=sessoes_disp.find(function(s){return s.equipe_id===(_dbEquipe?_dbEquipe.id:'')&&s.data===hoje;})||null;
  if(_dbSessao){
    _dbSessao.eventos=parseJsonField(_dbSessao.eventos,[]);
  }

  // Restaurar ordem ativa do banco (se sessão aberta)
  if(!DEMO && _dbEquipe && _dbSessao && !_dbSessao.logout_ts){
    sbFetch('ordens_diario',{
      filters:['equipe_id=eq.'+(_dbEquipe?_dbEquipe.id:''),'data=eq.'+hoje],
      order:'criado_em.desc'
    }).then(function(res){
      if(res&&res.length){
        // Atualizar array local
        res.forEach(function(o){
          o.eventos=parseJsonField(o.eventos,[]);
          // Limpar blob URLs expiradas
          o.eventos.forEach(function(ev){
            if(ev.foto&&ev.foto.indexOf('blob:')===0) ev.foto=null;
          });
          var i=ordens_db.findIndex(function(x){return x.id===o.id;});
          if(i>=0) ordens_db[i]=o; else ordens_db.push(o);
        });
        // Restaurar ordem ativa (não encerrada/cancelada)
        var ordemAtiva=res.find(function(o){
          return o.status!=='encerrada'&&o.status!=='cancelada'&&o.status!=='disponivel';
        });
        if(ordemAtiva && !_dbOrdemAtual){
          _dbOrdemAtual=ordemAtiva;
        }
      }
      renderDbComposicao();
      renderDbOrdemAtual();
      renderDbOrdensDia();
      renderDbHistoricoSessao();
      dbAtualizarBotoes();
      if(_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts) dbIniciarTimer();
    }).catch(function(){
      renderDbComposicao();
      renderDbOrdemAtual();
      renderDbOrdensDia();
      renderDbHistoricoSessao();
      dbAtualizarBotoes();
      if(_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts) dbIniciarTimer();
    });
  } else {
    renderDbComposicao();
    renderDbOrdemAtual();
    renderDbOrdensDia();
    renderDbHistoricoSessao();
    dbAtualizarBotoes();
    if(_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts) dbIniciarTimer();
  }
}

// ── DIÁRIO DE BORDO PLPT ────────────────────────────────────────────
var _plptDiario = {
  prog:         null,   // registro de plpt_prog_dia
  projetos:     [],     // registros de plpt_prog_projetos
  projetoAtivo: null,   // projeto sendo executado agora
  sessao:       null,   // sessão aberta hoje (turno)
  composConfirm: false, // colaborador confirmou composição
};

var _plptModalTurnoAberto = false;



function _plptIniciarNovaExecucao(){
  _plptDiario._novaExecucaoHoje = true;

  // Encerrar turno anterior automaticamente
  if(_plptDiario.sessao && _plptDiario.sessao.id && !DEMO){
    sbUpdate('plpt_sessoes', {
      logout_ts:   Date.now(),
      status:      'Encerrado automático — nova programação',
    }, 'id=eq.'+_plptDiario.sessao.id)
    .catch(function(e){ console.error('encerrar sessao anterior:', e); });
  }

  // Reset da sessão e projeto ativo para começar do zero
  _plptDiario.sessao       = null;
  _plptDiario.projetoAtivo = null;
  _plptDiario.composConfirm = false;
  // Keep _plptDiario.projetos (from today's prog_dia) — these are today's projects
  // Clear old events from localStorage
  // Limpar estado local do turno anterior
  try{
    localStorage.removeItem('plpt_diario_state');
    localStorage.removeItem('plpt_diario_state_prog');
  } catch(e){}


  progShowToast('✅ Nova execução iniciada! O histórico da obra está disponível nos projetos.');
  renderDiarioPlpt();
}


function _plptContinuarTurnoAnterior(){
  _plptDiario._continuarTurnoAnterior = true;

  var dataSess = (_plptDiario.sessao && _plptDiario.sessao.data)
    ? (_plptDiario.sessao.data||'').slice(0,10) : '';

  if(!dataSess || DEMO){ renderDiarioPlpt(); return; }

  var eqId = _dbEquipe && _dbEquipe.id;
  progShowToast('⏳ Carregando turno de '+dataSess+'...');

  Promise.all([
    sbFetch('composicao_dia',{filters:['data=eq.'+dataSess,'equipe_id=neq.null'],limit:50}),
    eqId ? sbFetch('plpt_prog_dia',{filters:['data=eq.'+dataSess,'equipe_id=eq.'+eqId],limit:5})
         : Promise.resolve([])
  ]).then(function(res){
    var comps = res[0]||[];
    var progs = res[1]||[];

    comps.forEach(function(r){
      r.colaborador_ids = parseJsonField(r.colaborador_ids,[]);
      r.projeto_ids     = parseJsonField(r.projeto_ids||'[]',[]);
      if(!composicao_dia.find(function(x){return x.id===r.id;}))
        composicao_dia.push(r);
    });

    var prog = progs[0]||null;
    if(prog) _plptDiario.prog = prog;

    if(!prog){
      var comp = comps.find(function(c){ return c.equipe_id===eqId; });
      var projIds = comp ? (comp.projeto_ids||[]) : [];
      var faltam  = projIds.filter(function(id){
        return id && !sot_projetos.find(function(p){return p.id===id;});
      });
      var carregarE = faltam.length
        ? sbFetch('sot_projetos',{filters:['id=in.('+faltam.join(',')+')']})
            .then(function(rows){ (rows||[]).forEach(function(p){ if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p); }); })
        : Promise.resolve();
      carregarE.then(function(){ progShowToast('✅ Turno de '+dataSess+' carregado!'); renderDiarioPlpt(); })
               .catch(function(){ renderDiarioPlpt(); });
      return;
    }

    sbFetch('plpt_prog_projetos',{filters:['prog_dia_id=eq.'+prog.id],order:'ordem'})
      .then(function(progProjs){
        _plptDiario.projetos = progProjs||[];
        var projIds = (progProjs||[]).map(function(p){return p.projeto_id;}).filter(Boolean);
        var faltam  = projIds.filter(function(id){
          return !sot_projetos.find(function(p){return p.id===id;});
        });
        var carregarS = faltam.length
          ? sbFetch('sot_projetos',{filters:['id=in.('+faltam.join(',')+')']})
              .then(function(rows){ (rows||[]).forEach(function(p){ if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p); }); })
          : Promise.resolve();
        carregarS.then(function(){ progShowToast('✅ Turno de '+dataSess+' carregado!'); renderDiarioPlpt(); })
                 .catch(function(){ renderDiarioPlpt(); });
      }).catch(function(){ renderDiarioPlpt(); });
  }).catch(function(){ renderDiarioPlpt(); });
}


function renderDiarioPlpt(){
  if(_plptModalTurnoAberto) return;
  var pg = document.getElementById('pg-diario'); if(!pg) return;
  var eq = _dbEquipe;
  if(!eq){
    pg.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa;font-size:13px">⏳ Carregando dados da equipe...</div>';
    return;
  }
  var hoje    = dataHojeLocal();
  var prog    = _plptDiario.prog;
  var projs   = _plptDiario.projetos;
  var sessao  = _plptDiario.sessao;
  var PLPT_CID = usuarioLogado ? usuarioLogado.contrato_id : CONTRATOS_UUID_MAP['PLPT'];

  // Se turno é de ontem, usar data da sessão para encontrar composição
  var dataBusca = hoje;
  var compDia = composicao_dia.find(function(c){
    var cd=(c.data||'').split('T')[0];
    return c.equipe_id===eq.id && (cd===hoje||c.data===hoje);
  });
  if(!compDia && sessao && sessao.data){
    var dataSess = (sessao.data||'').slice(0,10);
    if(dataSess && dataSess !== hoje){
      compDia = composicao_dia.find(function(c){
        var cd=(c.data||'').split('T')[0];
        return c.equipe_id===eq.id && cd===dataSess;
      });
      if(compDia) dataBusca = dataSess;
    }
  }
  var temEscala = prog || compDia;
  var escalaConfirmada = !!(compDia && compDia.confirmada) || !!_plptDiario.composConfirm;

  // Buscar projetos da composição se ainda não carregados
  var compHojeCheck = composicao_dia.find(function(c){
    var cd=(c.data||'').split('T')[0];
    return c.equipe_id===eq.id&&(cd===hoje||c.data===hoje);
  });
  var projIdsCheck = [];
  try{projIdsCheck=JSON.parse((compHojeCheck&&compHojeCheck.projeto_ids)||'[]');}catch(e){}
  var projFaltando = projIdsCheck.filter(function(pid){
    return pid && typeof sot_projetos!=='undefined' && !sot_projetos.find(function(x){return x.id===pid;});
  });
  if(projFaltando.length && !DEMO){
    sbFetch('sot_projetos',{filters:['id=in.('+projFaltando.join(',')+')']} )
      .then(function(rows){
        if(rows&&rows.length){
          rows.forEach(function(p){
            if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p);
          });
        }
        if(!_plptModalTurnoAberto) renderDiarioPlpt();
      }).catch(function(){});
    return; // aguardar e re-renderizar
  }

  // ── Membros da equipe ────────────────────────────
  var membros = [];
  if(compDia){
    parseJsonField(compDia.colaborador_ids,[]).filter(Boolean).forEach(function(id){
      var c=colaboradores.find(function(x){return x.id===id;});
      if(c) membros.push(c);
    });
  }
  if(!membros.length){
    membros = colaboradores.filter(function(c){
      return c.equipe_id===eq.id && c.ativo!==false;
    });
  }

  // ── Veículo da equipe ────────────────────────────
  var veic = null;
  // Primeiro: _progVeiculos (carregado do banco)
  var pvKey = eq.id+'_'+hoje;
  if(_progVeiculos[pvKey]){
    var pvObj = _progVeiculos[pvKey];
    veic = frt_veiculos.find(function(v){return v.placa===pvObj.placa||v.id===pvObj.id;});
    if(!veic && pvObj.placa) veic = {placa:pvObj.placa, modelo:pvObj.modelo||'—'};
  }
  // Segundo: plpt_prog_dia
  if(!veic && prog && prog.veiculo_placa){
    veic = frt_veiculos.find(function(v){return v.placa===prog.veiculo_placa;});
    if(!veic) veic = {placa:prog.veiculo_placa, modelo:'—'};
  }
  var veicInfo = veic ? (veic.placa+' — '+veic.modelo) : '—';

  // ── Status do turno ──────────────────────────────
  var turnoAtivo  = sessao && sessao.inicio_ts && !sessao.fim_ts;
  console.log('[renderDiarioPlpt] sessao:', sessao&&sessao.id, 'inicio_ts:', sessao&&sessao.inicio_ts, 'fim_ts:', sessao&&sessao.fim_ts, 'turnoAtivo:', !!turnoAtivo);
  var turnoStatus = !sessao ? 'Aguardando' : turnoAtivo ? 'Em campo' : 'Encerrado';
  var turnoCorFundo = turnoAtivo ? '#185FA5' : '#1a1a18';

  // ── Composição (sempre visível) ──────────────────
  var membrosHtml = membros.length
    ? membros.map(function(c,i){
        var ini=(c.nome||'U').charAt(0).toUpperCase();
        return '<div style="display:flex;align-items:center;gap:10px;padding:.5rem 0;border-bottom:.5px solid #f5f5f3">'
          +'<div style="width:30px;height:30px;border-radius:50%;background:'+(escalaConfirmada?'#EAF3DE':'#e0dfd8')
          +';color:'+(escalaConfirmada?'#3B6D11':'#555')+';display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0">'+ini+'</div>'
          +'<span style="font-size:10px;color:#aaa;width:18px">T'+(i+1)+'</span>'
          +'<div style="flex:1"><div style="font-size:13px;font-weight:600">'+c.nome+'</div>'
          +'<div style="font-size:11px;color:#888">RE '+(c.re||'—')+' | '+(c.cargo||'')+'</div></div>'
          +'</div>';
      }).join('')
    : '<div style="font-size:12px;color:#aaa;padding:.5rem 0">Sem membros escalados</div>';

  // ── Cronômetro ───────────────────────────────────
  var cronometroHtml = '';
  if(turnoAtivo && sessao.inicio_ts){
    var diff = Math.floor((Date.now()-new Date(sessao.inicio_ts).getTime())/1000);
    var hh=String(Math.floor(diff/3600)).padStart(2,'0');
    var mm=String(Math.floor((diff%3600)/60)).padStart(2,'0');
    var ss=String(diff%60).padStart(2,'0');
    var emAlmoco = !!_plptAlmocoInicioTs;
    cronometroHtml='<div style="background:'+(emAlmoco?'#854F0B':turnoCorFundo)+';color:#fff;padding:1.25rem;text-align:center;border-radius:12px;margin-bottom:1rem" id="plpt-cronometro-wrap">'
      +(emAlmoco
        ?'<div id="plpt-almoco-timer" style="font-size:18px;font-weight:700;letter-spacing:1px;margin-bottom:.75rem">🍽 Calculando...</div>'
        :'<div style="font-size:32px;font-weight:700;letter-spacing:2px" id="plpt-cronometro">'+hh+':'+mm+':'+ss+'</div>'
         +'<div style="font-size:11px;opacity:.7;margin-top:4px">Tempo de turno</div>'
      )
      +'<div style="display:flex;gap:8px;margin-top:.75rem">'
      +(emAlmoco
        ?'<button onclick="plptDiarioRetornarAlmoco()" style="flex:1;padding:.65rem;background:#fff;color:#854F0B;border:none;border-radius:8px;cursor:pointer;font-size:13px;font-weight:700">↩ Retornar do almoço</button>'
        :'<button onclick="plptDiarioAlmoco()" style="flex:1;padding:.6rem;background:rgba(255,255,255,.15);color:#fff;border:.5px solid rgba(255,255,255,.3);border-radius:8px;cursor:pointer;font-size:13px">🍽 Almoço</button>'
         +'<button onclick="plptDiarioEncerrar()" style="flex:1;padding:.6rem;background:#A32D2D;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:13px;font-weight:600">■ Encerrar</button>'
      )
      +'</div></div>';
  }

  // ── Ações rápidas (só com turno ativo e projeto ativo) ──
  var projAtivo = _plptDiario.projetoAtivo;
  var acoesHtml = '';
  if(turnoAtivo && projAtivo){
    var projId = projAtivo.projeto_id;
    acoesHtml = '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:1rem">'
      +'<button onclick="plptAbrirAtividades(\''+projId+'\')" style="flex:1;padding:10px 8px;background:#EBF4FD;color:#185FA5;border:.5px solid #185FA5;border-radius:10px;cursor:pointer;font-size:12px;font-weight:600">⚡ Atividades</button>'      +'<button onclick="(_isContratoEquatorial(eq.contrato_id||(usuarioLogado&&usuarioLogado.contrato_id)||\"\")?abrirAPREquatorial(eq.contrato_id||(usuarioLogado&&usuarioLogado.contrato_id)||\"\",eq.id,hoje,projId):showSub(\"campo-apr\"))" style="flex:1;padding:10px 8px;background:#185FA5;color:#fff;border:.5px solid #185FA5;border-radius:10px;cursor:pointer;font-size:12px;font-weight:600">📋 APR</button>'      +'<button onclick="plptAbrirMateriais(\''+projId+'\')" style="flex:1;padding:10px 8px;background:#EAF3DE;color:#3B6D11;border:.5px solid #3B6D11;border-radius:10px;cursor:pointer;font-size:12px;font-weight:600">📦 Materiais</button>'
      +'<button onclick="plptAbrirBaixaMateriais(\''+projId+'\')" style="flex:1;padding:10px 8px;background:#f9f9f7;color:#555;border:.5px solid #e0dfd8;border-radius:10px;cursor:pointer;font-size:12px;font-weight:600">📋 Baixa de materiais</button>'
      +'<button onclick="plptAbrirReservaMateriais(\\\''+projId+'\\\')" style="flex:1;padding:10px 8px;background:#533AB7;color:#fff;border:.5px solid #533AB7;border-radius:10px;cursor:pointer;font-size:12px;font-weight:600">🧰 Reservar Materiais</button>'
      +'</div>';
  }

  // ── Projetos/OS ──────────────────────────────────
  // compHoje: busca por equipe e data da sessão (hoje ou ontem)
  var _sessData = (sessao&&sessao.data?(sessao.data||'').slice(0,10):hoje);
  var compHoje = composicao_dia.find(function(c){
    if(c.equipe_id!==eq.id) return false;
    var cd=(c.data||'').slice(0,10);
    return cd===hoje||cd===_sessData;
  });
  var projIdsComp=[];
  try{projIdsComp=JSON.parse((compHoje&&compHoje.projeto_ids)||'[]');}catch(e){}
  // Se nenhum projeto na composição mas há projeto ativo na sessão, incluir
  if(!projIdsComp.length && _plptDiario.projetoAtivo && _plptDiario.projetoAtivo.projeto_id){
    projIdsComp = [_plptDiario.projetoAtivo.projeto_id];
  }
  var projsComp=projIdsComp.map(function(pid){
    // PLPT diário: usar apenas sot_projetos (não projetos_obra)
    return (typeof sot_projetos!=='undefined'?sot_projetos.find(function(x){return x.id===pid;}):null);
  }).filter(Boolean);
  // listaOS: combina prog.projetos + composicao_dia + projetoAtivo da sessão
  var listaOS_base = prog ? projs : projsComp.map(function(p){return {projeto_id:p.id,status:'pendente'};});
  // Se lista vazia mas há projeto ativo restaurado na sessão, incluir
  if(!listaOS_base.length && _plptDiario.projetoAtivo && _plptDiario.projetoAtivo.projeto_id){
    listaOS_base = [{projeto_id:_plptDiario.projetoAtivo.projeto_id, _pjId:_plptDiario.projetoAtivo._pjId, status:'em andamento'}];
  }
  var listaOS = listaOS_base;
  var projsHtmlLocal = listaOS.map(function(pj,i){
    var sot=(typeof sot_projetos!=='undefined'?sot_projetos.find(function(x){return x.id===pj.projeto_id;}):null)||{};
    var codReal=sot.codigo_cliente||sot.codigo||sot.numero_cadastro||sot.nome||pj.projeto_id||'Projeto';
    var isAtivo=projAtivo&&pj.projeto_id===projAtivo.projeto_id;
    // Etapa atual do projeto ativo
    var etapaProj='';
    var podeClicar=true;
    if(isAtivo && projAtivo._timeline && projAtivo._timeline.length){
      var ultEv=projAtivo._timeline[projAtivo._timeline.length-1];
      etapaProj=ultEv.desc;
      var CONCLUIDA='Encerramento das atividades';
      podeClicar = etapaProj!==CONCLUIDA; // pode clicar enquanto não encerrado
    }
    var stCor={pendente:'#888','em andamento':'#185FA5',concluido:'#3B6D11',cancelado:'#A32D2D'}[pj.status||'pendente']||'#888';
    return '<div style="display:flex;align-items:center;gap:8px;padding:.6rem .75rem;'
      +'background:'+(isAtivo?'#E8F0FE':'#fff')+';border:'+(isAtivo?'1.5px solid #185FA5':'.5px solid #e0dfd8')+';'
      +'border-radius:8px;margin-bottom:6px;cursor:'+(podeClicar?'pointer':'default')+';opacity:'+(podeClicar?1:.7)+'"'
      +(podeClicar?' onclick="plptDiarioAbrirProjeto(\''+pj.projeto_id+'\')"':'')+'>'
      +'<span style="background:#1a1a18;color:#fff;border-radius:50%;width:22px;height:22px;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;flex-shrink:0">'+(i+1)+'</span>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:12px;font-weight:700">'+(codReal)+'</div>'
      +'<div style="font-size:11px;color:#888;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(sot.nome||'')+(sot.tipo_servico?' · '+sot.tipo_servico:'')+'</div>'
      +'</div>'
      +(isAtivo && etapaProj?'<span style="font-size:10px;color:#185FA5;font-weight:700;text-align:right;flex-shrink:0">'+etapaProj+'</span>':'')
      +(function(){
        var pjAtivs = (projAtivo&&projAtivo.projeto_id===pj.projeto_id&&projAtivo._atividades)?projAtivo._atividades:null;
        if(!pjAtivs||!pjAtivs.length) return isAtivo?'<span style="font-size:16px;color:#185FA5;margin-left:4px">▶</span>':'<span style="font-size:12px;color:#aaa;margin-left:4px">›</span>';
        var semViab=pjAtivs.some(function(a){return (a._qtdViab!==undefined?a._qtdViab:(a.qtd_viabilizada||0))===0;});
        var algExec=pjAtivs.some(function(a){var v=a._qtdViab!==undefined?a._qtdViab:(a.qtd_viabilizada||0);var e=a._qtdExec!==undefined?a._qtdExec:(a.qtd_executada||0);return v>0&&e===0;});
        if(semViab) return '<span style="font-size:10px;background:#FEF3E2;color:#854F0B;border-radius:4px;padding:2px 6px;font-weight:700;margin-left:4px">📋 Viab</span>';
        if(algExec) return '<span style="font-size:10px;background:#EAF3DE;color:#3B6D11;border-radius:4px;padding:2px 6px;font-weight:700;margin-left:4px">▶ Exec</span>';
        return '<span style="font-size:10px;background:#EAF3DE;color:#3B6D11;border-radius:4px;padding:2px 6px;font-weight:700;margin-left:4px">✅</span>';
      }())
      +'</div>';
  }).join('') || '<div style="font-size:12px;color:#aaa;padding:1rem;text-align:center">Nenhum projeto programado para hoje</div>';

  // ── Histórico ────────────────────────────────────
  var histHtml='';
  if(sessao&&sessao.eventos&&sessao.eventos.length){
    histHtml='<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem;margin-bottom:1rem">'
      +'<div style="font-size:12px;font-weight:700;color:#555;margin-bottom:.5rem">Histórico do turno</div>'
      +(sessao.eventos||[]).filter(function(ev){ return ev.tipo !== '_PROJ_STATE'; }).map(function(ev){
        var hora=ev.hora||(ev.ts?new Date(ev.ts).toTimeString().slice(0,5):'—');
        var desc=ev.desc||ev.tipo||ev.obs||'—';
        return '<div style="display:flex;gap:8px;padding:4px 0;font-size:12px">'
          +'<span style="color:#185FA5;font-weight:600;flex-shrink:0">'+hora+'</span>'
          +'<span>'+desc+'</span></div>';
      }).join('')
      +'</div>';
  }

  // ── Montar tela ──────────────────────────────────
  // Detectar virada de dia: turno ativo mas data da sessão != hoje
  var turnoDeOntem = false;
  var dataSessao = '';
  if(turnoAtivo && sessao){
    // Tentar extrair data da sessão — várias fontes possíveis
    var fontesDatas = [sessao.data, sessao.inicio_ts, sessao.login_ts];
    for(var _fi=0; _fi<fontesDatas.length; _fi++){
      var _fd = fontesDatas[_fi];
      if(!_fd) continue;
      if(typeof _fd === 'number'){
        var _dt = new Date(_fd);
        if(!isNaN(_dt)){ dataSessao = _dt.toISOString().slice(0,10); break; }
      } else if(typeof _fd === 'string' && _fd.length >= 10){
        dataSessao = _fd.slice(0,10); break;
      }
    }
    console.log('[renderDiarioPlpt] dataSessao extraída:', dataSessao, 'fontes:', fontesDatas);
    if(dataSessao && dataSessao !== hoje) turnoDeOntem = true;
  }

  var viradaBanner = '';
  var temProgHoje = !!(prog && (prog.data||'').slice(0,10)===hoje);
  console.log('[renderDiarioPlpt] turnoDeOntem:', turnoDeOntem, 'dataSessao:', dataSessao, 'hoje:', hoje, 'temProgHoje:', temProgHoje);
  if(turnoDeOntem){
    var _jaDecidiu = _plptDiario._continuarTurnoAnterior || _plptDiario._novaExecucaoHoje;
    if(temProgHoje && !_jaDecidiu){
      // Nova programação hoje + turno anterior aberto — mostrar duas opções
      viradaBanner = '<div style="background:#533AB7;color:#fff;padding:.75rem 1rem;border-radius:0 0 12px 12px;margin-bottom:.75rem">'
        +'<div style="font-weight:700;font-size:14px">📅 Nova programação para hoje — turno anterior ainda aberto</div>'
        +'<div style="font-size:12px;opacity:.9;margin-top:2px">A obra foi programada novamente. Como deseja prosseguir?</div>'
        +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px">'
        +'<button onclick="_plptIniciarNovaExecucao()" style="padding:9px;background:#fff;color:#533AB7;border:none;border-radius:8px;cursor:pointer;font-size:12px;font-weight:700;line-height:1.4">🆕 Nova execução hoje<br><span style=\'font-size:10px;font-weight:400;opacity:.8\'>Encerra turno anterior</span></button>'
        +'<button onclick="_plptContinuarTurnoAnterior()" style="padding:9px;background:rgba(255,255,255,.15);color:#fff;border:1px solid rgba(255,255,255,.4);border-radius:8px;cursor:pointer;font-size:12px;font-weight:700;line-height:1.4">▶ Continuar turno anterior<br><span style=\'font-size:10px;font-weight:400;opacity:.8\'>Mesma execução</span></button>'
        +'</div></div>';
    } else if(!_jaDecidiu){
      var _btnCont = '<button onclick="_plptContinuarTurnoAnterior()" '
        +'style="margin-top:8px;width:100%;padding:9px;background:#fff;color:#A32D2D;border:none;border-radius:8px;cursor:pointer;font-size:13px;font-weight:700">'
        +'▶ Continuar trabalhando neste turno</button>';
      viradaBanner = '<div style="background:#A32D2D;color:#fff;padding:.75rem 1rem;border-radius:0 0 12px 12px;margin-bottom:.75rem">'
        +'<div style="font-weight:700;font-size:14px">⚠️ Turno em andamento desde '+fmtD(dataSessao)+'</div>'
        +'<div style="font-size:12px;opacity:.9;margin-top:2px">Este turno ainda está aberto. Clique abaixo para continuar.</div>'
        +_btnCont+'</div>';
    }
  }

  pg.innerHTML='<div style="max-width:600px;margin:0 auto;padding:1rem">'
    + viradaBanner

    // Header com tipo de equipe e veículo
    +'<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:.75rem 1rem;margin-bottom:.75rem">'
    +'<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:4px">'
    +'<div>'
    +'<div style="font-size:16px;font-weight:700">'+eq.nome+'</div>'
    +'<div style="font-size:11px;color:#888;margin-top:1px">'+(eq.tipo||eq.cargo||'EQUIPE PLPT')+' • '+fmtD(hoje)+'</div>'
    +'</div>'
    +'<span style="font-size:11px;font-weight:600;padding:3px 8px;border-radius:6px;background:'+(turnoAtivo?'#EBF4FD':'#f9f9f7')+';color:'+(turnoAtivo?'#185FA5':'#888')+'">'+turnoStatus+'</span>'
    +'</div>'
    +'<div style="display:flex;gap:12px;margin-top:6px;padding-top:6px;border-top:.5px solid #f5f5f3">'
    +'<div style="font-size:11px"><span style="color:#888">Veículo: </span><span style="font-weight:600">'+veicInfo+'</span></div>'
    +(prog&&prog.encarregado_nome?'<div style="font-size:11px"><span style="color:#888">Enc.: </span><span style="font-weight:600">'+prog.encarregado_nome+'</span></div>':'')
    +'</div>'
    +'</div>'

    // Cronômetro
    + cronometroHtml

    // Botão Iniciar dia
    +(!sessao&&temEscala&&escalaConfirmada
      ?'<button onclick="dbAbrirModalTurno()" style="width:100%;padding:.9rem;background:#1a1a18;color:#fff;border:none;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer;margin-bottom:1rem">▶ Iniciar novo dia</button>'
      :''
    )

    // Aviso sem programação
    +(!temEscala
      ?'<div style="background:#FFF3E0;border:.5px solid #F9A825;border-radius:10px;padding:.75rem 1rem;font-size:12px;color:#7B4F00;margin-bottom:1rem">⚠ Sem programação para hoje. Contate o supervisor.</div>'
      :''
    )

    // Composição — sempre visível
    +'<div style="background:#fff;border:.5px solid '+(escalaConfirmada?'#3B6D11':'#e0dfd8')+';border-radius:12px;padding:1rem;margin-bottom:1rem">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">'
    +'<span style="font-size:12px;font-weight:700;color:#555">Composição da Equipe</span>'
    +(escalaConfirmada
      ?'<span style="font-size:10px;color:#3B6D11;font-weight:600;background:#EAF3DE;padding:2px 8px;border-radius:4px">✓ Confirmada</span>'
      :temEscala
        ?'<span style="font-size:10px;color:#854F0B">Aguardando confirmação</span>'
        :'<span style="font-size:10px;color:#A32D2D">Sem escala</span>'
    )
    +'</div>'
    + membrosHtml
    +(temEscala&&!escalaConfirmada&&!sessao
      ?'<div style="display:flex;gap:8px;margin-top:.75rem">'
       +'<button onclick="diarioConfirmarEscala()" style="flex:1;padding:.65rem;background:#1a1a18;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:13px;font-weight:600">✓ Confirmar escala</button>'
       +'<button onclick="plptDiarioReportarComposicao()" style="padding:.65rem 1rem;background:#fff;color:#A32D2D;border:.5px solid #A32D2D;border-radius:8px;cursor:pointer;font-size:12px">⚠ Reportar</button>'
       +'</div>'
      :''
    )
    +'</div>'

    // Ações rápidas (Atividades / Materiais / Baixa)
    + acoesHtml

    // Projetos/OS
    +(sessao
      ?'<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem;margin-bottom:1rem">'
       +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
       +'<span style="font-size:12px;font-weight:700;color:#555">Projetos do dia</span>'
       +'<span style="font-size:10px;color:#888">'+listaOS.length+' projeto(s)</span>'
       +'</div>'
       +projsHtmlLocal
       +'</div>'
      :''
    )

    // Histórico
    + histHtml

    +'</div>';

  if(turnoAtivo){
    if(_plptAlmocoInicioTs) _plptIniciarTimerAlmoco();
    else _plptIniciarCronometro();
  }
  // Verificar materiais separados aguardando retirada
  // Check materials regardless of turno status — reservations persist across days
  console.log('[KANBAN] eq:', eq&&eq.id, 'calling _plptVerificarMateriaisSeparados');
  if(eq && eq.id){
    setTimeout(function(){ _plptVerificarMateriaisSeparados(eq.id); }, 500);
  }
}

var _plptCronometroInterval = null;
function _plptIniciarCronometro(){
  if(_plptCronometroInterval) clearInterval(_plptCronometroInterval);
  _plptCronometroInterval = setInterval(function(){
    if(_plptAlmocoInicioTs) return; // pausado durante almoço
    var el = document.getElementById('plpt-cronometro');
    if(!el){ clearInterval(_plptCronometroInterval); return; }
    var sessao = _plptDiario.sessao;
    if(!sessao||!sessao.inicio_ts){ clearInterval(_plptCronometroInterval); return; }
    var diff = Math.floor((Date.now()-new Date(sessao.inicio_ts).getTime())/1000);
    el.textContent = String(Math.floor(diff/3600)).padStart(2,'0')+':'+
                     String(Math.floor((diff%3600)/60)).padStart(2,'0')+':'+
                     String(diff%60).padStart(2,'0');
  }, 1000);
}

function plptDocTogglePreview(idx){
  var el  = document.getElementById('plpt-doc-preview-'+idx);
  var btn = document.getElementById('plpt-doc-btn-'+idx);
  if(!el) return;
  var aberto = el.style.display !== 'none';
  el.style.display = aberto ? 'none' : '';
  if(btn) btn.textContent = aberto ? '👁 Ver' : '✕ Fechar';
}

function plptDiarioConfirmarComposicao(){
  _plptDiario.composConfirm = true;
  progShowToast('✅ Composição confirmada');
  renderDiarioPlpt();
}


// ═══════════════════════════════════════════════════════════════════════
// PLPT — RETIRADA DE MATERIAIS (Equipe confirma após composição)
// ═══════════════════════════════════════════════════════════════════════

function _plptVerificarMateriaisSeparados(eqId){
  if(DEMO) return;
  var hoje = dataHojeLocal();

  // For admin/gestor: eqId may be null — show all pending
  // For equipe: only show their own
  var projIds = [];
  if(eqId){
    var progHoje = _plptDiario.prog;
    var comp = composicao_dia.find(function(x){
      return x.equipe_id===eqId && (x.data||'').slice(0,10)===hoje;
    });
    projIds = comp ? parseColabIds(comp.projeto_ids||'[]') : [];
    if(_plptDiario.projetos && _plptDiario.projetos.length){
      _plptDiario.projetos.forEach(function(p){
        if(p.projeto_id && projIds.indexOf(p.projeto_id)<0) projIds.push(p.projeto_id);
      });
    }
  }

  console.log('[KANBAN MAT] eqId:', eqId, 'projIds:', projIds);

  // Fetch ALL active requisitions — filter locally
  // Avoid deleted_at filter (column may not exist)
  sbFetch('plpt_requisicoes_materiais',{
    filters:['status=in.(Aguardando aprovação,Separação,Aguardando confirmação almox,Em campo)'],
    order:'criado_em.desc', limit:500
  }).then(function(rows){
    console.log('[KANBAN MAT] rows from DB:', rows ? rows.length : 0);
    if(!document.getElementById('pg-diario')) return;
    if(!rows||!rows.length){
      console.log('[KANBAN MAT] nenhuma requisição ativa no banco');
      return;
    }

    var minhas = !eqId ? rows : rows.filter(function(r){
      if(r.equipe_id===eqId) return true;
      if(projIds.length && projIds.indexOf(r.projeto_id)>=0) return true;
      return false;
    });
    console.log('[KANBAN MAT] minhas:', minhas.length, 'de', rows.length, 'eqId:', eqId);
    // Show ALL pending reservations - no date filter
    // Reservations persist until cancelled or completed
    if(!minhas.length) return;
    _plptMostrarBannerMateriais(minhas);
  }).catch(function(){});
}


// ── Cancelar Requisição ──────────────────────────────────────────────────────

function plptAbrirDetalheReqs(reqs){
  if(!reqs||!reqs.length) return;
  // Store reqs globally for cancel access
  window._pendReqs = reqs;
  var html = reqs.map(function(r,ri){
    var itens = [];
    try{ itens = JSON.parse(r.itens||'[]'); }catch(e){}
    return '<div style="border:.5px solid #e0dfd8;border-radius:8px;padding:.75rem;margin-bottom:.5rem">'
      +'<div style="font-size:12px;font-weight:600;margin-bottom:.25rem">'+escHtml(r.projeto_nome||r.projeto_id||'Projeto')+'</div>'
      +'<div style="font-size:11px;color:#888;margin-bottom:.5rem">Status: '+r.status+'</div>'
      +itens.map(function(it){
        return '<div style="display:flex;justify-content:space-between;font-size:11px;padding:2px 0">'
          +'<span>'+escHtml(it.descricao||it.material_desc||'')+'</span>'
          +'<span>'+it.qtd+' '+(it.unidade||'UN')+'</span></div>';
      }).join('')
      +'<div style="margin-top:.5rem">'
      +'<button onclick="closeModal();plptAbrirCancelarReq([window._pendReqs['+ri+']])" '
      +'class="btn btn-sm" style="font-size:10px;color:#A32D2D;border-color:#A32D2D">🗑 Cancelar</button>'
      +'</div></div>';
  }).join('');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:460px">'
    +'<h3 style="margin-bottom:.75rem">⏳ Requisições Aguardando Almoxarife</h3>'
    +html
    +'<button class="btn" onclick="closeModal()" style="width:100%;margin-top:.5rem">Fechar</button>'
    +'</div></div>');
}


function plptAbrirCancelarReq(reqs){
  if(!reqs||!reqs.length) return;
  var r = reqs[0]; // Show first one

  var cargo   = (usuarioLogado&&usuarioLogado.cargo||'').toLowerCase();
  var isAlmox = cargo.includes('almox') || cargo.includes('estoque');
  var isSolic = r.solicitante_id === (usuarioLogado&&usuarioLogado.id);
  var podeCanc = isSolic || !isAlmox; // requester can always cancel; non-almox too

  var itens = [];
  try{ itens = JSON.parse(r.itens||'[]'); }catch(e){}

  var itensHtml = itens.map(function(it){
    return '<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:.5px solid #f0efe8;font-size:12px">'
      +'<span>'+escHtml(it.descricao||it.material_desc||'')+'</span>'
      +'<span style="color:#555">'+it.qtd+' '+(it.unidade||'UN')+'</span>'
      +'</div>';
  }).join('');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:460px">'
    +'<h3 style="margin-bottom:.5rem">📋 Requisição — '+escHtml(r.projeto_nome||r.projeto_id||'')+'</h3>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.6rem .75rem;margin-bottom:.75rem;font-size:11px;color:#555">'
    +'<div>Status: <b>'+r.status+'</b></div>'
    +'<div>Solicitante: <b>'+escHtml(r.solicitante||r.solicitante_nome||'—')+'</b></div>'
    +'<div>Data: <b>'+fmtD(r.data||r.criado_em||'')+'</b></div>'
    +'</div>'
    +'<div style="margin-bottom:.75rem">'+itensHtml+'</div>'
    +(reqs.length>1?'<div style="font-size:11px;color:#888;margin-bottom:.5rem">E mais '+(reqs.length-1)+' requisição(ões)...</div>':'')
    +(podeCanc
      ? '<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Motivo do cancelamento</label>'
        +'<textarea class="inp" id="canc-motivo" rows="2" style="width:100%;resize:none" placeholder="Ex: Materiais não serão mais necessários nesta semana"></textarea></div>'
        +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
        +'<button class="btn" onclick="closeModal()">Fechar</button>'
        +'<button class="btn" onclick="plptConfirmarCancelamento(\''+r.id+'\',\''+r.projeto_id+'\')" '
        +'style="flex:2;background:#A32D2D;color:#fff;border-color:#A32D2D;font-size:12px">🗑 Cancelar Requisição</button>'
        +'</div>'
      : '<div style="background:#FEF3E2;border-radius:8px;padding:.6rem .75rem;font-size:12px;color:#854F0B">'
        +'⚠ Somente quem fez a requisição pode cancelá-la.<br>Entre em contato com <b>'+escHtml(r.solicitante||'—')+'</b>.'
        +'</div>'
        +'<div style="margin-top:.75rem"><button class="btn" onclick="closeModal()" style="width:100%">Fechar</button></div>')
    +'</div></div>');
}

function plptConfirmarCancelamento(reqId, projetoId){
  var motivo = ((document.getElementById('canc-motivo')||{}).value||'').trim();
  if(!motivo){ progShowToast('⚠ Informe o motivo do cancelamento.','erro'); return; }

  var r = (window.plpt_requisicoes||[]).find(function(x){ return x.id===reqId; });
  if(r) r.status = 'Cancelada';

  if(!DEMO){
    sbUpdate('plpt_requisicoes_materiais',
      {status:'Cancelada', motivo_cancelamento:motivo, cancelado_em:new Date().toISOString(),
       cancelado_por:usuarioLogado?usuarioLogado.nome:''},
      'id=eq.'+reqId
    );
  }
  closeModal();
  progShowToast('✅ Requisição cancelada.');
  // Remove from Kanban banner
  setTimeout(function(){
    var banner = document.getElementById('plpt-mat-banner');
    if(banner) banner.remove();
  }, 500);
}


function _plptMostrarBannerMateriais(reqs){
  console.log('[KANBAN BANNER] reqs recebidas:', reqs ? reqs.length : 0, reqs ? reqs.map(function(r){return {id:r.id,status:r.status,eq:r.equipe_id};}) : []);
  var pg = document.getElementById('pg-diario');
  if(!pg){ console.log('[KANBAN BANNER] pg-diario não encontrado'); return; }

  // Se banner já existe com mesmo número de reqs, não recriar
  var old = document.getElementById('plpt-mat-banner');
  var oldCount = old ? parseInt(old.dataset.reqCount||'0') : -1;
  var oldStatus = old ? old.dataset.status : '';
  var newStatus = reqs.some(function(r){return r.status==='Separação';}) ? 'pendente' : 'aguardando';
  if(old && oldCount === reqs.length && oldStatus === newStatus) return;
  if(old) old.remove();

  var totalItens = 0;
  var emCampo = 0;
  reqs.forEach(function(r){
    var itens = parseJsonField(r.itens,[]);
    totalItens += itens.length;
    if(r.status==='Em campo') emCampo += itens.length;
  });
  var paraRetirar = totalItens - emCampo;

  // Verificar se todas já foram confirmadas pela equipe ou ainda há pendentes
  var emAprovacao = reqs.filter(function(r){ return r.status==='Aguardando aprovação'; });
  var pendentes   = reqs.filter(function(r){ return r.status==='Separação'; });
  var aguardando  = reqs.filter(function(r){ return r.status==='Aguardando confirmação almox'; });

  var emCampReqs = reqs.filter(function(r){ return r.status==='Em campo'; });
  var bgColor, titulo, subtitulo;
  if(pendentes.length){
    bgColor   = '#533AB7';
    titulo    = '📦 Material separado aguardando retirada!';
    subtitulo = totalItens+' item(ns) em '+pendentes.length+' requisição(ões) — toque para conferir e retirar';
  } else if(aguardando.length){
    bgColor   = '#854F0B';
    titulo    = '⏳ Aguardando liberação do almoxarifado';
    subtitulo = aguardando.length+' requisição(ões) confirmada(s) — almoxarife irá liberar em breve';
  } else if(emAprovacao.length){
    bgColor   = '#185FA5';
    titulo    = '🔔 Requisição aguardando aprovação';
    subtitulo = emAprovacao.length+' requisição(ões) enviada(s) — aguardando aprovação do almoxarife';
  } else {
    bgColor   = '#185FA5';
    titulo    = '🔧 Materiais em campo';
    subtitulo = emCampReqs.length+' requisição(ões) com materiais ativos — '+emCampo+' item(ns)';
  }

  var banner = document.createElement('div');
  banner.id = 'plpt-mat-banner';
  banner.dataset.reqCount = reqs.length;
  banner.dataset.status   = pendentes.length ? 'pendente' : 'aguardando';
  banner.style.cssText = 'position:sticky;top:0;z-index:100;background:'+bgColor+';color:#fff;padding:.75rem 1rem;border-radius:0 0 10px 10px;margin-bottom:.5rem;cursor:'+(pendentes.length||aguardando.length||emAprovacao.length?'pointer':'default')+';box-shadow:0 2px 8px rgba(0,0,0,.2)';
  banner.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between">'
    +'<div>'
    +'<div style="font-weight:700;font-size:14px">'+titulo+'</div>'
    +'<div style="font-size:12px;opacity:.9">'+subtitulo+'</div>'
    +'</div>'
    +(pendentes.length?'<div style="font-size:22px">→</div>':'<div style="font-size:22px">⏳</div>')
    +'</div>';
  if(pendentes.length){
    banner.onclick = function(){ plptAbrirRetiradaMateriais(pendentes); };
  } else if(aguardando.length){
    banner.onclick = function(){ plptAbrirDetalheReqs(aguardando); };
  } else if(emAprovacao.length){
    banner.onclick = function(){ plptAbrirCancelarReq(emAprovacao); };
  }
  // Try to insert into active page, fallback to body
  var _oldB = document.getElementById('plpt-mat-banner');
  if(_oldB) _oldB.remove();
  pg.insertBefore(banner, pg.firstChild);
  console.log('[KANBAN BANNER] inserido em pg-diario');
}

function plptAbrirRetiradaMateriais(reqs){
  // Montar lista de todos os itens com edição de qtd
  var todosItens = [];
  reqs.forEach(function(req){
    var proj = (typeof sot_projetos!=='undefined'?sot_projetos:[]).find(function(p){return p.id===req.projeto_id;})||{};
    parseJsonField(req.itens,[]).forEach(function(it){
      var qSep = it.qtd_sep != null ? it.qtd_sep : (it.qtd_req||0);
      todosItens.push({
        req_id:   req.id,
        mat_id:   it.mat_id||'',
        projeto:  proj.codigo_cliente||proj.codigo||proj.nome||'—',
        nome:     it.nome||it.codigo||'Material',
        codigo:   it.codigo||'',
        unidade:  it.unidade||'UN',
        qtd_prog: qSep,
        qtd_ret:  qSep,
      });
    });
  });

  var linhas = todosItens.map(function(it, i){
    return '<div style="padding:8px 0;border-bottom:.5px solid #f0efe8">'
      +'<div style="display:flex;align-items:center;gap:8px">'
      +'<input type="checkbox" id="ret-chk-'+i+'" checked style="width:18px;height:18px;cursor:pointer" onchange="_plptRetCheckToggle('+i+')"/>'
      +'<div style="flex:1">'
      +'<div style="font-weight:600;font-size:13px">'+escHtml(it.nome)+'</div>'
      +(it.codigo?'<div style="font-size:10px;color:#888;font-family:monospace">'+escHtml(it.codigo)+'</div>':'')
      +'<div style="font-size:11px;color:#555">Proj: '+escHtml(it.projeto)+'</div>'
      +'</div>'
      +'<div style="text-align:right">'
      +'<div style="font-size:10px;color:#888;margin-bottom:2px">Separado: '+it.qtd_prog+' '+escHtml(it.unidade)+'</div>'
      +'<div style="display:flex;align-items:center;gap:4px">'
      +'<label style="font-size:10px;color:#533AB7;font-weight:600">Qtd:</label>'
      +'<input type="number" id="ret-qtd-'+i+'" value="'+it.qtd_prog+'" min="0" step="0.01" '
      +'style="width:65px;padding:4px;border:.5px solid #533AB7;border-radius:6px;text-align:center;font-size:12px;font-weight:600"/>'
      +'<span style="font-size:11px;color:#888">'+escHtml(it.unidade)+'</span>'+'<span id="ret-warn-'+i+'" style="display:none;font-size:9px;color:#A32D2D;font-weight:700;margin-left:4px">⚠ ACIMA</span>'
      +'</div></div>'
      +'</div></div>';
  }).join('');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:500px">'
    +'<h3 style="margin-bottom:.25rem">📦 Confirmar Retirada de Materiais</h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">Confira cada item, ajuste a quantidade se necessário e confirme.</div>'
    +'<div style="max-height:55vh;overflow-y:auto;margin-bottom:.75rem">'
    +linhas
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Observações (opcional)</label>'
    +'<input class="inp" id="ret-obs-mat" placeholder="Diferenças, danos, falta de item..." style="width:100%"/>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="_plptConfirmarRetirada()" '
    +'style="flex:2;background:#533AB7;border-color:#533AB7">✅ Confirmar Retirada</button>'
    +'</div></div></div>');

  window._plptRetItens = todosItens;
  window._plptRetReqIds = reqs.map(function(r){return r.id;});
}

function _plptRetCheckToggle(i){
  var inp = document.getElementById('ret-qtd-'+i);
  var chk = document.getElementById('ret-chk-'+i);
  if(inp) inp.disabled = chk && !chk.checked;
  if(inp && chk && !chk.checked) inp.value = 0;
}

function _plptRetQtdCheck(i, qtdProg, input){
  // Highlight in red if over programmed qty
  var val = parseFloat(input.value)||0;
  input.style.borderColor = val > qtdProg ? '#A32D2D' : '#533AB7';
  input.style.color       = val > qtdProg ? '#A32D2D' : '#1a1a18';
  // Show warning label
  var warn = document.getElementById('ret-warn-'+i);
  if(warn) warn.style.display = val > qtdProg ? '' : 'none';
}

function _plptConfirmarRetirada(){
  var itens  = window._plptRetItens  || [];
  var reqIds = window._plptRetReqIds || [];
  var g   = function(id){ return parseFloat((document.getElementById(id)||{}).value||'0')||0; };
  var obs = ((document.getElementById('ret-obs-mat')||{}).value||'').trim();

  var itensFinal = itens.map(function(it, i){
    var chk    = document.getElementById('ret-chk-'+i);
    var qtdRet = (chk&&chk.checked) ? g('ret-qtd-'+i) : 0;
    return Object.assign({}, it, {
      qtd_ret:  qtdRet,
      incluido: !!(chk&&chk.checked),
    });
  });

  // Classificar divergências
  var acimaProg = itensFinal.filter(function(it){ return it.incluido && it.qtd_ret > it.qtd_prog; });
  var abaixoProg = itensFinal.filter(function(it){ return it.incluido && it.qtd_ret < it.qtd_prog && it.qtd_ret > 0; });
  var excluidos  = itensFinal.filter(function(it){ return !it.incluido; });

  // Se tem retirada ACIMA do programado → exige autorização antes de continuar
  if(acimaProg.length){
    _plptSolicitarAutorizacaoAcima(acimaProg, itensFinal, reqIds, obs);
    return;
  }

  // Sem acima do programado — salvar diretamente
  _plptSalvarRetirada(itensFinal, reqIds, obs, null);
}

function _plptSolicitarAutorizacaoAcima(acima, itensFinal, reqIds, obs){
  // reqIds e itensFinal passados como parâmetro (não via window para evitar sobrescrita)
  // Modal exigindo autorização de responsável
  var listaAcima = acima.map(function(it){
    return '<div style="padding:4px 0;border-bottom:.5px solid #F59E0B33;font-size:12px">'
      +'<strong>'+escHtml(it.nome)+'</strong>'
      +'<span style="color:#A32D2D;margin-left:8px">Programado: '+it.qtd_prog+' → Retirando: '+it.qtd_ret+' '+escHtml(it.unidade)+'</span>'
      +'</div>';
  }).join('');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.5rem;color:#A32D2D">⚠️ Retirada Acima do Autorizado</h3>'
    +'<div style="background:#FFF0F0;border:.5px solid #A32D2D;border-radius:8px;padding:10px 14px;margin-bottom:.75rem">'
    +'<div style="font-size:12px;margin-bottom:6px">Os itens abaixo excedem a quantidade separada pelo almoxarifado:</div>'
    +listaAcima
    +'</div>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">'
    +'Para retirar acima do autorizado é necessário o <strong>nome e senha</strong> de um responsável (gerente/supervisor).'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.5rem">'
    +'<label style="font-size:11px;font-weight:600">Nome do responsável *</label>'
    +'<input class="inp" id="aut-nome" placeholder="Nome completo" style="width:100%"/>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Justificativa *</label>'
    +'<input class="inp" id="aut-just" placeholder="Motivo para retirada adicional" style="width:100%"/>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="aut-confirmar" style="flex:2;background:#A32D2D;border-color:#A32D2D">✅ Autorizar e Confirmar</button>'
    +'</div></div></div>');

  setTimeout(function(){
    var btn = document.getElementById('aut-confirmar');
    if(!btn) return;
    btn.onclick = function(){
      var nome = ((document.getElementById('aut-nome')||{}).value||'').trim();
      var just = ((document.getElementById('aut-just')||{}).value||'').trim();
      if(!nome){ progShowToast('⚠ Informe o nome do responsável.','erro'); return; }
      if(!just){ progShowToast('⚠ Informe a justificativa.','erro'); return; }
      var autorizacao = {autorizado_por: nome, justificativa: just, ts: new Date().toISOString()};
      closeModal();
      _plptSalvarRetirada(itensFinal, reqIds, obs, autorizacao);
    };
  },50);
}

function _plptSalvarRetirada(itensFinal, reqIds, obs, autorizacao){
  var abaixoProg = itensFinal.filter(function(it){ return it.incluido && it.qtd_ret < it.qtd_prog && it.qtd_ret > 0; });
  var acimaProg  = itensFinal.filter(function(it){ return it.incluido && it.qtd_ret > it.qtd_prog; });
  var excluidos  = itensFinal.filter(function(it){ return !it.incluido; });
  var temDiverg  = abaixoProg.length > 0 || acimaProg.length > 0 || excluidos.length > 0;

  // Montar obs_divergencia detalhada
  var divStr = [];
  acimaProg.forEach(function(it){
    divStr.push('↑ '+it.nome+': prog '+it.qtd_prog+' → retirou '+it.qtd_ret+' '+it.unidade
      +(autorizacao?' [aut: '+autorizacao.autorizado_por+']':''));
  });
  abaixoProg.forEach(function(it){
    divStr.push('↓ '+it.nome+': prog '+it.qtd_prog+' → retirou '+it.qtd_ret+' '+it.unidade);
  });
  excluidos.forEach(function(it){
    divStr.push('✕ '+it.nome+': NÃO RETIRADO');
  });

  // Montar observacoes completas (inclui divergência e autorização)
  var obsCompleta = [];
  if(obs) obsCompleta.push(obs);
  if(temDiverg) obsCompleta.push('Divergência: '+divStr.join(' | '));
  if(autorizacao) obsCompleta.push('Autorizado por: '+autorizacao.autorizado_por+' | '+autorizacao.justificativa);

  var obsStr = obsCompleta.length ? obsCompleta.join(' || ') : null;
  var retiradoPor = usuarioLogado ? usuarioLogado.nome : '';

  function _montarItensReq(rid, existingItens){
    var incluidos = itensFinal.filter(function(it){ return it.incluido && it.req_id === rid; });
    return incluidos.map(function(it){
      var prev = existingItens.find(function(x){
        return String(x.mat_id||'') === String(it.mat_id||'')
          || (it.codigo && x.codigo === it.codigo);
      }) || {};
      return Object.assign({}, prev, {
        mat_id:       it.mat_id,
        codigo:       it.codigo,
        nome:         it.nome,
        unidade:      it.unidade,
        qtd_req:      it.qtd_prog,
        qtd_sep:      prev.qtd_sep != null ? prev.qtd_sep : it.qtd_prog,
        qtd_ret:      it.qtd_ret,
        divergente:   it.qtd_ret !== (prev.qtd_sep != null ? prev.qtd_sep : it.qtd_prog),
        retirado_por: retiradoPor,
        retirado_em:  new Date().toISOString(),
      });
    });
  }

  function _finalizarUi(){
    var banner = document.getElementById('plpt-mat-banner');
    if(banner) banner.remove();
    if(temDiverg){
      var msg = [];
      if(acimaProg.length)  msg.push(acimaProg.length+' item(ns) acima do programado');
      if(abaixoProg.length) msg.push(abaixoProg.length+' item(ns) com qtd menor');
      if(excluidos.length)  msg.push(excluidos.length+' item(ns) não retirado(s)');
      progShowToast('⚠ Retirada com ajustes: '+msg.join(', ')+'. Almoxarife será notificado.');
    } else {
      var n = itensFinal.filter(function(x){ return x.incluido; }).length;
      progShowToast('✅ Retirada confirmada! '+n+' item(ns) retirado(s).');
    }
    closeModal();
    renderDiarioPlpt();
  }

  if(DEMO){
    if(_plptDiario && _plptDiario.projetoAtivo){
      var pjDemo = _plptDiario.projetoAtivo;
      var pidsDemo = {};
      reqIds.forEach(function(rid){ pidsDemo[rid]=1; });
      (pjDemo._requisicoes||[]).forEach(function(r){
        if(!pidsDemo[r.id]) return;
        r.status = 'Aguardando confirmação almox';
      });
      plptMarcarViabilidadeProjeto(pjDemo._pjId || pjDemo.projeto_id, pjDemo);
    }
    _finalizarUi();
    return;
  }

  Promise.all(reqIds.map(function(rid){
    return sbFetch('plpt_requisicoes_materiais', {filters:['id=eq.'+rid], limit:1})
      .then(function(rows){
        var r = rows && rows[0];
        var existingItens = r ? parseJsonField(r.itens, []) : [];
        var newItens = _montarItensReq(rid, existingItens);
        if(!newItens.length) return null;
        var divRet = [];
        newItens.forEach(function(it){
          var base = it.qtd_sep != null ? it.qtd_sep : it.qtd_req;
          if(it.qtd_ret !== base){
            if(it.qtd_ret > base) divRet.push('↑ '+it.nome+': separado '+base+' → retirou '+it.qtd_ret);
            else if(it.qtd_ret < base) divRet.push('↓ '+it.nome+': separado '+base+' → retirou '+it.qtd_ret);
          }
        });
        var payload = {
          status:      'Aguardando confirmação almox',
          observacoes: obsStr,
          itens:       JSON.stringify(newItens),
        };
        if(temDiverg || divRet.length) payload.obs_divergencia = [divStr.join(' | '), divRet.join(' | ')].filter(Boolean).join(' || ');
        return sbUpdate('plpt_requisicoes_materiais', payload, 'id=eq.'+rid);
      });
  })).then(function(){
    if(window._coMatFetched) window._coMatFetched = {};
    if(_plptDiario && _plptDiario.projetoAtivo){
      var pjAct = _plptDiario.projetoAtivo;
      var pids = {};
      reqIds.forEach(function(rid){ pids[rid]=1; });
      (pjAct._requisicoes||[]).forEach(function(r){
        if(!pids[r.id]) return;
        r.status = 'Aguardando confirmação almox';
        var existing = parseJsonField(r.itens, []);
        var merged = existing.map(function(x){
          var match = itensFinal.find(function(it){
            return it.req_id === r.id && (String(it.mat_id||'')===String(x.mat_id||'') || (it.codigo && x.codigo===it.codigo));
          });
          if(!match) return x;
          return Object.assign({}, x, {
            qtd_ret: match.incluido ? match.qtd_ret : 0,
            retirado_por: retiradoPor,
            retirado_em: new Date().toISOString(),
          });
        });
        r.itens = typeof merged === 'string' ? merged : JSON.stringify(merged);
      });
      plptMarcarViabilidadeProjeto(pjAct._pjId || pjAct.projeto_id, pjAct);
    }
    _finalizarUi();
  }).catch(function(e){
    console.error('retirada update:', e);
    progShowToast('⚠ Erro ao salvar retirada: '+(e&&e.message||e), 'erro');
  });
}


function _plptNotificarDivergenciaAlmox(itens, reqIds, obs){
  // Criar entrada em sol_materiais com flag de divergência para aparecer no kanban
  if(DEMO) return;
  reqIds.forEach(function(rid){
    sbFetch('plpt_requisicoes_materiais',{filters:['id=eq.'+rid]})
      .then(function(rows){
        var r = rows&&rows[0]; if(!r) return;
        var proj = (typeof sot_projetos!=='undefined'?sot_projetos:[]).find(function(p){return p.id===r.projeto_id;})||{};
        var divergStr = itens.filter(function(x){return !x.incluido||(x.qtd_ret!==x.qtd_prog);})
          .map(function(x){
            return x.incluido
              ? x.nome+': separado '+x.qtd_prog+' → retirou '+x.qtd_ret+' '+x.unidade
              : x.nome+': NÃO RETIRADO';
          }).join('; ');
        // Atualizar motivo com divergência para aparecer no kanban
        sbUpdate('plpt_requisicoes_materiais',{
          obs_divergencia: '⚠ DIVERGÊNCIA: '+divergStr+(obs?' | Obs: '+obs:''),
        },'id=eq.'+rid).catch(function(){});
      }).catch(function(){});
  });
}


function diarioConfirmarEscala(){
  var hoje=dataHojeLocal();
  var eq=_dbEquipe; if(!eq) return;
  var comp=composicao_dia.find(function(c){
    var cd=(c.data||'').split('T')[0];
    return c.equipe_id===eq.id&&(cd===hoje||c.data===hoje);
  });
  if(!comp){ progShowToast('⚠ Nenhuma composição encontrada'); return; }
  comp.confirmada=true;
  _plptDiario.composConfirm=true;
  if(!DEMO){
    var isLocal=comp._local||!comp.id||comp.id.startsWith('local_');
    if(isLocal){
      sbInsert('composicao_dia',{equipe_id:eq.id,data:hoje,
        colaborador_ids:comp.colaborador_ids,turno:'Manha',confirmada:true})
        .then(function(r){if(r&&r[0]&&r[0].id){comp.id=r[0].id;comp._local=false; almOnComposicaoConfirmada(comp);}});
    } else {
      sbUpdate('composicao_dia',{confirmada:true},'id=eq.'+comp.id);
      almOnComposicaoConfirmada(comp);
    }
  } else almOnComposicaoConfirmada(comp);
  progShowToast('✅ Escala confirmada!');
  // Verificar materiais separados para esta equipe
  _plptVerificarMateriaisSeparados(eq.id);
  renderDiarioPlpt();
}


// ═══════════════════════════════════════════════════════════════════════
// PLPT — RESERVA DE MATERIAIS
// Fluxo: Equipe solicita → Gerente aprova → Almoxarifado separa → Campo usa → Devolução
// ═══════════════════════════════════════════════════════════════════════

var RSV_TMA_CID = '04277076-baa5-4ea4-85dc-bddf55541e68';

function rsvEquipesDoContrato(contratoId){
  var cid = String(contratoId||'').trim();
  if(!cid) return [];
  var vistos = {}, out = [];
  function add(e){
    if(!e || e.status==='Inativo') return;
    if(String(e.contrato_id||'') !== cid) return;
    var k = String(e.id||'');
    if(!k || vistos[k]) return;
    vistos[k] = 1;
    out.push(e);
  }
  (typeof equipes!=='undefined' ? equipes : []).forEach(add);
  if(cid === RSV_TMA_CID) (equipes_disp||[]).forEach(add);
  out.sort(function(a,b){
    return (a.codigo||a.nome_equipe||a.nome||'').localeCompare(b.codigo||b.nome_equipe||b.nome||'', 'pt-BR', {sensitivity:'base'});
  });
  return out;
}
function rsvEquipePorId(equipeId, contratoId){
  if(!equipeId) return null;
  return rsvEquipesDoContrato(contratoId).find(function(e){ return String(e.id)===String(equipeId); })
    || (equipes||[]).find(function(e){ return String(e.id)===String(equipeId); })
    || (equipes_disp||[]).find(function(e){ return String(e.id)===String(equipeId); });
}
function rsvEquipesOptsHtml(contratoId, opts){
  opts = opts || {};
  var list = rsvEquipesDoContrato(contratoId);
  var selId = opts.selectedId;
  return '<option value="">Selecione a equipe...</option>'
    + list.map(function(e){
      var label = e.codigo || e.nome_equipe || e.nome || e.id;
      if(e.nome && e.codigo && label.indexOf(e.nome) < 0) label += ' — ' + e.nome;
      return '<option value="'+e.id+'"'+(selId && String(selId)===String(e.id)?' selected':'')+'>'+escHtml(label)+'</option>';
    }).join('');
}

function plptMateriaisRetiradosMap(projId, pj){
  var map = {};
  var reqs = (pj && pj._requisicoes) || [];
  reqs.forEach(function(req){
    if(['Separação','Aguardando confirmação almox','Em campo','Devolvida','Aguardando devolução','Aplicação confirmada'].indexOf(req.status) < 0) return;
    parseJsonField(req.itens, []).forEach(function(it){
      var keys = [it.mat_id, it.codigo].filter(Boolean);
      if(!keys.length) return;
      var q = 0;
      if(req.status === 'Em campo' || req.status === 'Devolvida'){
        q = it.qtd_ret != null ? Number(it.qtd_ret) : (it.qtd_sep != null ? Number(it.qtd_sep) : Number(it.qtd_req)||0);
      } else if(req.status === 'Aguardando confirmação almox'){
        q = it.qtd_ret != null ? Number(it.qtd_ret) : 0;
      } else if(req.status === 'Separação'){
        q = it.qtd_sep != null ? Number(it.qtd_sep) : Number(it.qtd_req)||0;
      }
      if(q <= 0) return;
      keys.forEach(function(k){ map[String(k)] = Math.max(map[String(k)]||0, q); });
    });
  });
  return map;
}
function plptProjetoFaseExecucao(projId, pj){
  if(pj && pj._faseExecucao) return true;
  var mats = (pj && pj._materiais) ? pj._materiais
    : (typeof sot_materiais_proj !== 'undefined' ? sot_materiais_proj.filter(function(m){ return m.projeto_id===projId; }) : []);
  if(mats.some(function(m){ return (m.qtd_viabilizada||0)>0 || (m.qtd_entregue||0)>0 || (m.qtd_aplicada||0)>0; })) return true;
  var ativs = (pj && pj._atividades) ? pj._atividades : [];
  if(ativs.some(function(a){ return (a.qtd_viabilizada||0)>0 || (a.qtd_executada||0)>0; })) return true;
  var reqs = (pj && pj._requisicoes) || [];
  if(reqs.some(function(r){ return ['Aguardando confirmação almox','Em campo','Devolvida','Aguardando devolução','Aplicação confirmada'].indexOf(r.status)>=0; })) return true;
  var retMap = plptMateriaisRetiradosMap(projId, pj);
  if(Object.keys(retMap).length && pj && pj._timeline && pj._timeline.length) return true;
  return false;
}
function plptMarcarViabilidadeProjeto(projId, pj){
  if(!pj) return;
  pj._faseExecucao = true;
  pj._baixaSubAba = 'executada';
  (pj._materiais||[]).forEach(function(m){
    var base = m.qtd_projetada || m.qtd || m.qtd_prevista || 0;
    if((m.qtd_viabilizada||0) <= 0 && base > 0){
      m.qtd_viabilizada = base;
      m._qtdViab = base;
      if(!DEMO && m.id) sbUpdate('sot_materiais', {qtd_viabilizada: base}, 'id=eq.'+m.id);
    }
  });
  (pj._atividades||[]).forEach(function(a){
    var base = a.qtd_prevista || 0;
    if((a.qtd_viabilizada||0) <= 0 && base > 0){
      a.qtd_viabilizada = base;
      a._qtdViab = base;
      if(!DEMO && a.id) sbUpdate('sot_atividades', {qtd_viabilizada: base}, 'id=eq.'+a.id);
    }
  });
}
function plptMatRetiradoQtd(mat, retMap){
  if(!mat || !retMap) return 0;
  return Math.max(retMap[String(mat.id)]||0, retMap[String(mat.codigo_sap)]||0, retMap[String(mat.codigo)]||0);
}
var PLPT_REQ_STATUS_ATIVOS = ['Aguardando aprovação','Aprovada','Separação','Aguardando confirmação almox','Em campo','Aguardando devolução'];
function plptFmtTs(iso){
  if(!iso) return '—';
  try{
    var d = new Date(iso);
    return d.toLocaleDateString('pt-BR')+' '+d.toTimeString().slice(0,5);
  }catch(e){ return String(iso).slice(0,16).replace('T',' '); }
}
function sotMatObsPayload(viab, aplic){
  var p = [];
  if(viab) p.push('Viab: '+viab);
  if(aplic) p.push('Aplic: '+aplic);
  return p.length ? {observacao: p.join(' | ')} : {};
}
function sotAtivObsPayload(viab, exec){
  var payload = {};
  if(viab) payload.obs_viabilidade = viab;
  if(exec) payload.obs_execucao = exec;
  if(viab || exec){
    payload.observacoes = (viab ? 'Viab: '+viab : '') + (viab && exec ? ' | ' : '') + (exec ? 'Exec: '+exec : '');
  }
  return payload;
}
function plptTemRequisicaoPendente(projId, pj){
  return ((pj && pj._requisicoes) || []).some(function(r){
    return !r.deleted_at && PLPT_REQ_STATUS_ATIVOS.indexOf(r.status) >= 0;
  });
}
function plptRequisicoesEmCampo(projId, pj){
  return ((pj && pj._requisicoes) || []).filter(function(r){
    return !r.deleted_at && ['Em campo','Aguardando devolução'].indexOf(r.status) >= 0;
  });
}
function plptQtdEntregueItem(it){
  return it.qtd_ret != null ? Number(it.qtd_ret) : (it.qtd_sep != null ? Number(it.qtd_sep) : Number(it.qtd_req)||0);
}
function plptSalvarRelatorioObras(projId, texto){
  var p = (typeof sot_projetos !== 'undefined' ? sot_projetos.find(function(x){ return x.id===projId; }) : null);
  if(p) p.relatorio_obras = texto;
  if(_plptDiario && _plptDiario.projetoAtivo) _plptDiario.projetoAtivo._relatorioObras = texto;
  if(!DEMO && projId){
    var payload = {
      relatorio_obras: texto,
      relatorio_obras_at: new Date().toISOString(),
      relatorio_obras_por: usuarioLogado ? usuarioLogado.nome : null,
    };
    sbUpdate('sot_projetos', payload, 'id=eq.'+projId).catch(function(){
      if(p) sbUpdate('sot_projetos', {observacoes: ((p.observacoes||'')+'\n[Relatório obras '+dataHojeLocal()+']\n'+texto).trim()}, 'id=eq.'+projId).catch(function(){});
    });
  }
}
function plptRenderResumoOperacoes(projId, pj, sot, ativs, mats){
  ativs = ativs || (pj && pj._atividades) || [];
  mats  = mats  || (pj && pj._materiais)  || [];
  sot   = sot   || (typeof sot_projetos!=='undefined' ? sot_projetos.find(function(x){ return x.id===projId; }) : null) || {};
  var reqs = (pj && pj._requisicoes) || [];
  var execPrev = ativs.reduce(function(s,a){ return s+(a.qtd_prevista||0); }, 0);
  var execReal = ativs.reduce(function(s,a){ return s+(a._qtdExec!==undefined?a._qtdExec:(a.qtd_executada||0)); }, 0);
  var matProg  = mats.reduce(function(s,m){ return s+(m.qtd||m.qtd_projetada||m.qtd_prevista||0); }, 0);
  var matAplic = mats.reduce(function(s,m){ return s+(m._qtdAplic!==undefined?m._qtdAplic:(m.qtd_aplicada||0)); }, 0);
  var cards = '<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin-bottom:.75rem">'
    +[{l:'Ativ. programadas',v:execPrev,c:'#555'},{l:'Ativ. executadas',v:execReal,c:'#3B6D11'},
       {l:'Mat. programados',v:matProg,c:'#555'},{l:'Mat. aplicados',v:matAplic,c:'#085041'}]
      .map(function(x){
        return '<div style="background:#f9f9f7;border-radius:8px;padding:.5rem .65rem;text-align:center">'
          +'<div style="font-size:10px;color:#888">'+x.l+'</div>'
          +'<div style="font-size:16px;font-weight:700;color:'+x.c+'">'+x.v+'</div></div>';
      }).join('')
    +'</div>';
  var reqRows = reqs.length ? reqs.map(function(r){
    var itens = parseJsonField(r.itens, []);
    var itensHtml = itens.map(function(it){
      var qEnt = plptQtdEntregueItem(it);
      var qApl = it.qtd_aplicada||0;
      var qDev = it.qtd_a_devolver != null ? it.qtd_a_devolver : (it.qtd_devolvida||0);
      return '<tr style="border-bottom:.5px solid #f0efe8;font-size:10px">'
        +'<td style="padding:4px 6px">'+escHtml(it.nome||it.codigo||'—')+'</td>'
        +'<td style="padding:4px 6px;text-align:center">'+ (it.qtd_req||0) +'</td>'
        +'<td style="padding:4px 6px;text-align:center">'+ (it.qtd_sep!=null?it.qtd_sep:'—') +'</td>'
        +'<td style="padding:4px 6px;text-align:center;color:#3B6D11;font-weight:600">'+ (it.qtd_ret!=null?it.qtd_ret:'—') +'</td>'
        +'<td style="padding:4px 6px;text-align:center;color:#085041">'+ qApl +'</td>'
        +'<td style="padding:4px 6px;text-align:center;color:#854F0B">'+ qDev +'</td>'
        +'<td style="padding:4px 6px;font-size:9px;color:#888">'
        +(it.separado_por?'Sep: '+escHtml(it.separado_por)+' ':'')
        +(it.retirado_por?'Ret: '+escHtml(it.retirado_por)+' ':'')
        +(it.aplicado_por?'Apl: '+escHtml(it.aplicado_por)+' ':'')
        +(it.devolvido_por?'Dev: '+escHtml(it.devolvido_por):'')
        +'</td></tr>';
    }).join('');
    return '<div style="border:.5px solid #e0dfd8;border-radius:8px;margin-bottom:8px;overflow:hidden">'
      +'<div style="background:#f5f5f3;padding:6px 10px;font-size:11px;font-weight:700;display:flex;justify-content:space-between">'
      +'<span>Requisição · '+itens.length+' item(ns)</span>'
      +'<span style="color:#185FA5">'+escHtml(r.status||'')+'</span></div>'
      +'<div style="padding:4px 10px;font-size:9px;color:#888;border-bottom:.5px solid #f0efe8">'
      +'Solic: '+escHtml(r.solicitante||'—')
      +(r.data?' · Data: '+fmtD(r.data):'')
      +(r.criado_em?' · Criada: '+plptFmtTs(r.criado_em):'')
      +'</div>'
      +'<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#1a1a18;color:#fff;font-size:9px">'
      +'<th style="padding:4px 6px;text-align:left">Material</th><th style="padding:4px 6px">Reserv.</th>'
      +'<th style="padding:4px 6px">Sep.</th><th style="padding:4px 6px">Ret.</th><th style="padding:4px 6px">Aplic.</th>'
      +'<th style="padding:4px 6px">Dev.</th><th style="padding:4px 6px">Responsáveis</th></tr></thead>'
      +'<tbody>'+itensHtml+'</tbody></table>'
      +(r.obs_divergencia?'<div style="padding:4px 10px;font-size:9px;color:#A32D2D;background:#FFF0F0">⚠ '+escHtml(r.obs_divergencia.slice(0,200))+'</div>':'')
      +'</div>';
  }).join('') : '<div style="font-size:12px;color:#aaa;padding:1rem;text-align:center">Nenhuma requisição registrada</div>';
  var rel = (sot.relatorio_obras || (pj && pj._relatorioObras) || '');
  return cards
    +'<div style="font-size:12px;font-weight:700;margin-bottom:.5rem;color:#1a1a18">📋 Requisições e movimentações</div>'
    +reqRows
    +(rel ? '<div style="margin-top:.75rem;background:#F0EEFF;border-radius:8px;padding:.65rem .85rem">'
      +'<div style="font-size:11px;font-weight:700;color:#533AB7;margin-bottom:4px">📝 Relatório de obras'
      +(sot.relatorio_obras_at ? ' · '+plptFmtTs(sot.relatorio_obras_at):'')
      +(sot.relatorio_obras_por ? ' · '+escHtml(sot.relatorio_obras_por):'')
      +'</div>'
      +'<div style="font-size:11px;color:#555;white-space:pre-wrap">'+escHtml(rel)+'</div></div>' : '');
}
function plptBuildAbaCampo(projId, pj, faseExec, sot){
  sot = sot || {};
  var relAtual = sot.relatorio_obras || pj._relatorioObras || '';
  var relBlock = '<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">📝 Relatório de obras</label>'
    +'<textarea class="inp" id="plpt-relatorio-obras" rows="4" placeholder="Descreva o que foi executado no dia, condições de campo, pendências..." '
    +'style="width:100%;resize:vertical;font-size:12px;box-sizing:border-box">'+escHtml(relAtual)+'</textarea>'
    +'<div style="font-size:10px;color:#888;margin-top:3px">Salvo no projeto — disponível para análise pela IA.</div>'
    +'</div>';
  var reqsCampo = plptRequisicoesEmCampo(projId, pj);
  if(faseExec || reqsCampo.length){
    if(!reqsCampo.length){
      return '<div style="padding:.25rem 0">'
        +'<div style="font-size:12px;color:#3B6D11;background:#EAF3DE;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem">'
        +'<b>Fase de execução</b> — viabilidade concluída. Quando houver material em campo, confirme aplicação e devolução aqui (não envie nova requisição para aprovação).'
        +'</div>'+relBlock
        +'<button class="btn btn-pri" onclick="plptSalvarRelatorioObrasBtn(\''+projId+'\')" '
        +'style="width:100%;background:#533AB7;border-color:#533AB7">💾 Salvar relatório de obras</button>'
        +'<div id="camp-inline-status" style="margin-top:.5rem;font-size:12px;text-align:center;color:#888"></div>'
        +'</div>';
    }
    var linhasReq = reqsCampo.map(function(req, ri){
      var itens = parseJsonField(req.itens, []);
      return itens.map(function(it, ii){
        var qEnt = plptQtdEntregueItem(it);
        var qApl = it.qtd_aplicada||0;
        var qDev = it.qtd_a_devolver != null ? it.qtd_a_devolver : Math.max(0, qEnt - qApl);
        var isRet = qEnt > 0;
        return '<div style="border:.5px solid '+(isRet?'#3B6D11':'#e0dfd8')+';border-radius:8px;padding:.6rem .75rem;margin-bottom:6px;background:'+(isRet?'#EAF3DE':'#fff')+'">'
          +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">'
          +'<div style="font-size:12px;font-weight:600;flex:1">'+(it.nome||it.codigo||'—')+'</div>'
          +(isRet?'<span style="font-size:9px;background:#3B6D11;color:#fff;border-radius:3px;padding:1px 6px">Retirado '+qEnt+'</span>':'')
          +'</div>'
          +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:11px">'
          +'<div><label style="font-size:10px;font-weight:600;color:#085041">Qtd aplicada</label>'
          +'<input type="number" id="camp-apl-'+ri+'-'+ii+'" min="0" max="'+qEnt+'" step="0.01" value="'+qApl+'" '
          +'oninput="plptCampoCalcDev('+ri+','+ii+','+qEnt+')" '
          +'style="width:100%;padding:4px;border:.5px solid #085041;border-radius:6px;text-align:center"/></div>'
          +'<div><label style="font-size:10px;font-weight:600;color:#854F0B">Qtd a devolver</label>'
          +'<input type="number" id="camp-dev-'+ri+'-'+ii+'" min="0" max="'+qEnt+'" step="0.01" value="'+qDev+'" '
          +'style="width:100%;padding:4px;border:.5px solid #854F0B;border-radius:6px;text-align:center"/></div>'
          +'</div>'
          +'<div style="font-size:9px;color:#888;margin-top:4px">'+(it.unidade||'UN')
          +(it.retirado_por?' · Retirado por '+escHtml(it.retirado_por):'')
          +(it.retirado_em?' · '+plptFmtTs(it.retirado_em):'')
          +'</div></div>';
      }).join('');
    }).join('');
    window._plptCampoReqIds = reqsCampo.map(function(r){ return r.id; });
    return '<div style="padding:.25rem 0">'
      +'<div style="font-size:12px;color:#3B6D11;background:#EAF3DE;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem">'
      +'<b>Confirmar aplicação e devolução</b> — informe o que foi aplicado e o que retorna ao almox. '
      +'<span style="color:#A32D2D;font-weight:700">Não envie nova requisição para aprovação.</span>'
      +'</div>'
      +linhasReq
      +relBlock
      +'<button class="btn btn-pri" onclick="plptConfirmarAplicacaoDevolucao(\''+projId+'\')" '
      +'style="width:100%;background:#085041;border-color:#085041;padding:.75rem;font-size:13px;font-weight:700;margin-bottom:.5rem">'
      +'✅ Confirmar aplicação e material a devolver</button>'
      +'<div id="camp-inline-status" style="font-size:12px;text-align:center;color:#888"></div>'
      +'</div>';
  }
  // ── Nova reserva (primeira viabilidade) ──
  var mats = (typeof sot_materiais_proj!=='undefined' ? sot_materiais_proj : [])
    .filter(function(m){ return m.projeto_id===projId; });
  if(!mats.length){
    return '<div style="padding:2rem;text-align:center;color:#aaa;background:#f9f9f7;border-radius:10px">'
      +'<div style="font-size:24px;margin-bottom:.5rem">📦</div>'
      +'<div>Nenhum material programado para este projeto.</div></div>';
  }
  var bloqueio = plptTemRequisicaoPendente(projId, pj)
    ? '<div style="font-size:11px;color:#854F0B;background:#FEF3E2;border-radius:8px;padding:.5rem .75rem;margin-bottom:.75rem">'
      +'⚠ Já existe requisição em andamento neste projeto. Aguarde separação/retirada ou confirme a aplicação na aba Campo.'
      +'</div>' : '';
  var linhas = mats.map(function(m, i){
    return '<tr style="border-bottom:.5px solid #f0efe8">'
      +'<td style="padding:7px 8px"><input type="checkbox" id="rsv-chk-'+i+'" onchange="_plptReservaToggle('+i+')" style="cursor:pointer"/></td>'
      +'<td style="padding:7px 8px;font-size:12px">'+(m.codigo_sap?'<span style="font-size:10px;color:#888;display:block">'+m.codigo_sap+'</span>':'')
      +escHtml(m.descricao||'Material')+'</td>'
      +'<td style="padding:7px 8px;text-align:center;font-size:12px;color:#185FA5;font-weight:600">'+(m.qtd_projetada||0)+' '+(m.unidade||'UN')+'</td>'
      +'<td style="padding:7px 8px;text-align:center">'
      +'<input type="number" id="rsv-qtd-'+i+'" min="0" max="'+(m.qtd_projetada||0)+'" value="0" disabled '
      +'style="width:65px;padding:4px;border:.5px solid #e0dfd8;border-radius:6px;text-align:center;font-size:12px" '
      +'oninput="_plptReservaQtd('+i+',this.value)"/></td></tr>';
  }).join('');
  window._plptReservaItensDisp = mats;
  window._plptReservaProjId = projId;
  return bloqueio
    +'<div style="padding:.25rem 0">'
    +'<div style="font-size:12px;color:#555;background:#F0EEFF;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem">'
    +'Primeira reserva — selecione materiais para o dia. Gerente aprova antes da separação.'
    +'</div>'
    +'<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#1a1a18;color:#fff;font-size:11px">'
    +'<th style="padding:7px 8px;width:32px"></th><th style="padding:7px 8px;text-align:left">Material</th>'
    +'<th style="padding:7px 8px">Programado</th><th style="padding:7px 8px">Qtd a usar</th></tr></thead>'
    +'<tbody>'+linhas+'</tbody></table>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin:.75rem 0">'
    +'<div><label style="font-size:11px;font-weight:600">Equipe</label>'
    +'<div style="padding:8px;background:#f9f9f7;border:.5px solid #e0dfd8;border-radius:6px;font-size:12px;font-weight:600">'
    +escHtml(_dbEquipe?(_dbEquipe.codigo||_dbEquipe.nome_equipe||_dbEquipe.nome||'—'):'—')+'</div></div>'
    +'<div><label style="font-size:11px;font-weight:600">Data da aplicação</label>'
    +'<input class="inp" id="rsv-data-inline" type="date" value="'+dataHojeLocal()+'" style="width:100%"/></div></div>'
    +relBlock
    +'<button class="btn btn-pri" onclick="plptEnviarReservaInline()" '
    +(plptTemRequisicaoPendente(projId,pj)?'disabled style="width:100%;opacity:.5;cursor:not-allowed"':'style="width:100%;background:#533AB7;border-color:#533AB7"')
    +'>📤 Enviar para Aprovação</button>'
    +'<div id="rsv-inline-status" style="margin-top:.5rem;font-size:12px;text-align:center;color:#888"></div>'
    +'</div>';
}
function plptCampoCalcDev(ri, ii, qEnt){
  var inpA = document.getElementById('camp-apl-'+ri+'-'+ii);
  var inpD = document.getElementById('camp-dev-'+ri+'-'+ii);
  if(!inpA || !inpD) return;
  var apl = parseFloat(inpA.value)||0;
  inpD.value = Math.max(0, qEnt - apl);
}
function plptSalvarRelatorioObrasBtn(projId){
  var txt = ((document.getElementById('plpt-relatorio-obras')||{}).value||'').trim();
  plptSalvarRelatorioObras(projId, txt);
  progShowToast('✅ Relatório de obras salvo no projeto.');
}
function plptConfirmarAplicacaoDevolucao(projId){
  var pj = _plptDiario.projetoAtivo; if(!pj) return;
  var reqs = plptRequisicoesEmCampo(projId, pj);
  if(!reqs.length){ progShowToast('⚠ Nenhum material em campo para confirmar.','erro'); return; }
  var relatorio = ((document.getElementById('plpt-relatorio-obras')||{}).value||'').trim();
  var quem = usuarioLogado ? usuarioLogado.nome : '';
  var agora = new Date().toISOString();
  var st = document.getElementById('camp-inline-status');
  try{
    reqs.forEach(function(req, ri){
      var itens = parseJsonField(req.itens, []);
      itens.forEach(function(it, ii){
        var qEnt = plptQtdEntregueItem(it);
        var qApl = parseFloat((document.getElementById('camp-apl-'+ri+'-'+ii)||{}).value)||0;
        var qDev = parseFloat((document.getElementById('camp-dev-'+ri+'-'+ii)||{}).value);
        if(isNaN(qDev)) qDev = Math.max(0, qEnt - qApl);
        if(qApl + qDev > qEnt + 0.001){
          throw new Error('Aplicado + devolver não pode exceder retirado em: '+(it.nome||it.codigo));
        }
        if(qApl < 0 || qDev < 0) throw new Error('Quantidades inválidas em: '+(it.nome||it.codigo));
      });
    });
  }catch(e){
    progShowToast('⚠ '+e.message,'erro');
    return;
  }
  if(DEMO){
    reqs.forEach(function(req, ri){
      var itens = parseJsonField(req.itens, []);
      var itensN = itens.map(function(it, ii){
        var qEnt = plptQtdEntregueItem(it);
        var qApl = parseFloat((document.getElementById('camp-apl-'+ri+'-'+ii)||{}).value)||0;
        var qDev = parseFloat((document.getElementById('camp-dev-'+ri+'-'+ii)||{}).value);
        if(isNaN(qDev)) qDev = Math.max(0, qEnt - qApl);
        return Object.assign({}, it, {qtd_aplicada:qApl, qtd_a_devolver:qDev, aplicado_por:quem, aplicado_em:agora});
      });
      var temDev = itensN.some(function(it){ return (it.qtd_a_devolver||0)>0; });
      req.itens = JSON.stringify(itensN);
      req.status = temDev ? 'Aguardando devolução' : 'Aplicação confirmada';
    });
    plptSalvarRelatorioObras(projId, relatorio);
    if(st){ st.style.color='#3B6D11'; st.textContent='✅ Aplicação confirmada (demo)'; }
    progShowToast('✅ Aplicação e devolução registradas!');
    _plptRenderProjetoDetalhe(projId);
    return;
  }
  Promise.all(reqs.map(function(req, ri){
    var itens = parseJsonField(req.itens, []);
    var itensN = itens.map(function(it, ii){
      var qEnt = plptQtdEntregueItem(it);
      var qApl = parseFloat((document.getElementById('camp-apl-'+ri+'-'+ii)||{}).value)||0;
      var qDev = parseFloat((document.getElementById('camp-dev-'+ri+'-'+ii)||{}).value);
      if(isNaN(qDev)) qDev = Math.max(0, qEnt - qApl);
      return Object.assign({}, it, {
        qtd_aplicada: qApl, qtd_a_devolver: qDev,
        aplicado_por: quem, aplicado_em: agora,
      });
    });
    var temDev = itensN.some(function(it){ return (it.qtd_a_devolver||0) > 0; });
    var devStr = itensN.filter(function(it){ return it.qtd_a_devolver>0; })
      .map(function(it){ return it.nome+': devolver '+it.qtd_a_devolver+' '+(it.unidade||'UN'); }).join(' | ');
    var payload = {
      status: temDev ? 'Aguardando devolução' : 'Aplicação confirmada',
      itens: JSON.stringify(itensN),
      observacoes: (req.observacoes||'')+' || Aplicação confirmada por '+quem+' em '+plptFmtTs(agora)
        +(devStr?' | A devolver: '+devStr:''),
    };
    req.status = payload.status;
    req.itens = payload.itens;
    return sbUpdate('plpt_requisicoes_materiais', payload, 'id=eq.'+req.id).then(function(){
      itensN.forEach(function(it){
        if((it.qtd_aplicada||0) <= 0) return;
        var filt = ['projeto_id=eq.'+projId];
        if(it.codigo) filt.push('codigo_sap=eq.'+it.codigo);
        else if(it.nome) filt.push('descricao=eq.'+encodeURIComponent(it.nome));
        sbFetch('sot_materiais', {filters:filt, limit:1}).then(function(rows){
          var row = rows && rows[0]; if(!row) return;
          var nova = (row.qtd_aplicada||0) + it.qtd_aplicada;
          sbUpdate('sot_materiais', {qtd_aplicada: nova}, 'id=eq.'+row.id);
        }).catch(function(){});
      });
    });
  })).then(function(){
    plptSalvarRelatorioObras(projId, relatorio);
    if(window._coMatFetched) window._coMatFetched = {};
    if(st){ st.style.color='#3B6D11'; st.textContent='✅ Aplicação confirmada — almoxarifado notificado sobre devoluções.'; }
    progShowToast('✅ Aplicação e devolução registradas!');
    _plptRenderProjetoDetalhe(projId);
  }).catch(function(e){
    console.error('plptConfirmarAplicacaoDevolucao:', e);
    progShowToast('⚠ Erro ao confirmar: '+(e&&e.message||e),'erro');
  });
}

var _plptReservaAtual = null; // {projeto_id, equipe_id, data, itens:[{mat_id, nome, qtd_prog, qtd_req}]}

function plptAbrirReservaMateriais(projetoId){
  var proj = sot_projetos.find(function(p){ return p.id===projetoId; });
  if(!proj){ progShowToast('⚠ Projeto não encontrado.'); return; }

  // Buscar materiais programados para este projeto
  var matsProg = (typeof sot_materiais !== 'undefined' ? sot_materiais : [])
    .filter(function(m){ return m.projeto_id===projetoId && m.status !== 'Devolvido'; });

  if(!matsProg.length){
    progShowToast('⚠ Nenhum material programado para este projeto. Cadastre na aba Materiais primeiro.', 'erro');
    return;
  }

  _plptReservaAtual = {
    projeto_id: projetoId,
    equipe_id:  _dbEquipe ? _dbEquipe.id : null,
    data:       dataHojeLocal(),
    itens:      matsProg.map(function(m){
      return {
        mat_id:    m.id,
        codigo:    m.codigo||'',
        nome:      m.nome||'Material',
        unidade:   m.unidade||'UN',
        qtd_prog:  Number(m.quantidade||0),
        qtd_req:   0,
        qtd_dev:   0,
        selecionado: false,
      };
    })
  };

  _plptRenderModalReserva(proj);
}

function _plptRenderModalReserva(proj){
  var itens = _plptReservaAtual.itens;

  var linhas = itens.map(function(it, i){
    return '<tr style="border-bottom:.5px solid #f0efe8">'
      +'<td style="padding:7px 8px">'
      +'<input type="checkbox" id="rsv-chk-'+i+'" onchange="_plptReservaToggle('+i+')" style="cursor:pointer"/>'
      +'</td>'
      +'<td style="padding:7px 8px;font-size:12px">'
      +(it.codigo?'<span style="font-size:10px;color:#888;display:block">'+escHtml(it.codigo)+'</span>':'')
      +escHtml(it.nome)+'</td>'
      +'<td style="padding:7px 8px;text-align:center;font-size:12px;color:#185FA5;font-weight:600">'+it.qtd_prog+' '+escHtml(it.unidade)+'</td>'
      +'<td style="padding:7px 8px;text-align:center">'
      +'<input type="number" id="rsv-qtd-'+i+'" min="0" max="'+it.qtd_prog+'" value="0" '
      +'style="width:70px;padding:4px;border:.5px solid #e0dfd8;border-radius:6px;text-align:center;font-size:12px" '
      +'oninput="_plptReservaQtd('+i+',this.value)" disabled/>'
      +'</td>'
      +'</tr>';
  }).join('');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:640px">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem">'
    +'<div>'
    +'<div style="font-weight:700;font-size:15px">🧰 Reserva de Materiais</div>'
    +'<div style="font-size:11px;color:#888;margin-top:2px">'+escHtml(proj.nome||proj.codigo||'Projeto')
    +' · '+escHtml(_dbEquipe?(_dbEquipe.codigo||_dbEquipe.nome):'')+'</div>'
    +'</div>'
    +'<span style="font-size:11px;color:#533AB7;font-weight:600">'+dataHojeLocal().split('-').reverse().join('/')+'</span>'
    +'</div>'
    +'<div style="font-size:12px;color:#555;background:#F0EEFF;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem">'
    +'Selecione os materiais que serão utilizados hoje e informe a quantidade. '
    +'Pode ser menor que o programado. Após envio, o gerente aprovará e o almoxarifado fará a separação.'
    +'</div>'
    +'<div style="max-height:320px;overflow-y:auto;margin-bottom:1rem">'
    +'<table style="width:100%;border-collapse:collapse">'
    +'<thead><tr style="background:#1a1a18;color:#fff;font-size:11px">'
    +'<th style="padding:7px 8px;width:32px"></th>'
    +'<th style="padding:7px 8px;text-align:left">Material</th>'
    +'<th style="padding:7px 8px">Programado</th>'
    +'<th style="padding:7px 8px">Qtd a usar</th>'
    +'</tr></thead>'
    +'<tbody id="rsv-tbody">'+linhas+'</tbody>'
    +'</table>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr;gap:.5rem;margin-bottom:.5rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Data da aplicação *</label>'
    +'<input class="inp" id="rsv-data" type="date" value="'+dataHojeLocal()+'" style="width:100%"/></div>'
    +'</div>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem;font-size:12px">'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">📝 Relatório de obras</label>'
    +'<input class="inp" id="rsv-obs" placeholder="Opcional — condições de campo, execução do dia..." style="width:100%;margin-top:4px"/>'
    +'</div>'
    +'<div class="ma">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="plptEnviarReserva()" style="background:#533AB7;border-color:#533AB7">📤 Enviar para Aprovação</button>'
    +'</div>'
    +'</div></div>');
}

function _plptReservaToggle(i){
  var chk  = document.getElementById('rsv-chk-'+i);
  var inp  = document.getElementById('rsv-qtd-'+i);
  if(!chk || !inp) return;
  var on = chk.checked;
  inp.disabled = !on;
  _plptReservaAtual.itens[i].selecionado = on;
  if(on && Number(inp.value)===0){
    inp.value = _plptReservaAtual.itens[i].qtd_prog;
    _plptReservaAtual.itens[i].qtd_req = _plptReservaAtual.itens[i].qtd_prog;
  }
  if(!on){ inp.value=0; _plptReservaAtual.itens[i].qtd_req=0; }
}

function _plptReservaQtd(i, val){
  var it  = _plptReservaAtual.itens[i];
  var qtd = Math.min(Math.max(0, Number(val)||0), it.qtd_prog);
  it.qtd_req = qtd;
  var inp = document.getElementById('rsv-qtd-'+i);
  if(inp && Number(inp.value) > it.qtd_prog) inp.value = it.qtd_prog;
}


function plptEnviarReservaInline(){
  var mats   = window._plptReservaItensDisp || [];
  var projId = window._plptReservaProjId;
  var pj     = _plptDiario && _plptDiario.projetoAtivo;
  if(plptProjetoFaseExecucao(projId, pj) || plptRequisicoesEmCampo(projId, pj).length){
    var st0 = document.getElementById('rsv-inline-status');
    if(st0){ st0.style.color='#A32D2D'; st0.textContent='⚠ Use "Confirmar aplicação e devolução" — não envie nova requisição.'; }
    progShowToast('⚠ Material já em campo. Confirme aplicação na aba Campo.','erro');
    return;
  }
  if(plptTemRequisicaoPendente(projId, pj)){
    var st1 = document.getElementById('rsv-inline-status');
    if(st1){ st1.style.color='#A32D2D'; st1.textContent='⚠ Já existe requisição em andamento neste projeto.'; }
    progShowToast('⚠ Requisição pendente — aguarde separação ou retirada.','erro');
    return;
  }
  var itensSel = [];

  mats.forEach(function(m, i){
    var chk = document.getElementById('rsv-chk-'+i);
    var inp = document.getElementById('rsv-qtd-'+i);
    if(chk && chk.checked && inp){
      // Max reservável = programado - já aplicado
      var _saldoDisp = Math.max(0, (m.qtd_projetada||0) - (m.qtd_aplicada||0));
      var qtd = Math.min(parseFloat(inp.value)||0, _saldoDisp);
      if(qtd > 0) itensSel.push({
        mat_id:    m.id,
        codigo:    m.codigo_sap||'',
        nome:      m.descricao||'',
        unidade:   m.unidade||'UN',
        qtd_prog:  m.qtd_projetada||0,
        qtd_req:   qtd,
      });
    }
  });

  if(!itensSel.length){
    var st = document.getElementById('rsv-inline-status');
    if(st){ st.style.color='#A32D2D'; st.textContent='⚠ Selecione ao menos um material com quantidade.'; }
    return;
  }

  var obs = (document.getElementById('rsv-obs-inline')||{}).value||'';
  var relObra = ((document.getElementById('plpt-relatorio-obras')||{}).value||'').trim();
  if(relObra) plptSalvarRelatorioObras(projId, relObra);
  var rsvInlineEqId  = _dbEquipe ? _dbEquipe.id : null;
  var rsvInlineData  = (document.getElementById('rsv-data-inline')||{}).value  || (dataHojeLocal ? dataHojeLocal() : new Date().toISOString().slice(0,10));
  if(!rsvInlineEqId){
    var st = document.getElementById('rsv-inline-status');
    if(st){ st.style.color='#A32D2D'; st.textContent='⚠ Equipe não identificada na sessão.'; }
    return;
  }
  var payload = {
    projeto_id:  projId,
    equipe_id:   rsvInlineEqId,
    data:        rsvInlineData,
    status:      'Aguardando aprovação',
    solicitante: usuarioLogado ? usuarioLogado.nome : '',
    observacoes: obs,
    itens:       JSON.stringify(itensSel),
    criado_em:   new Date().toISOString(),
  };

  var st = document.getElementById('rsv-inline-status');

  if(!DEMO){
    sbInsert('plpt_requisicoes_materiais', payload)
      .then(function(){
        if(st){ st.style.color='#3B6D11'; st.textContent='✅ Requisição enviada! Aguardando aprovação do gerente.'; }
        // Registrar no histórico do turno
        if(_dbSessao){
          _dbSessao.eventos = _dbSessao.eventos||[];
          _dbSessao.eventos.push({tipo:'REQUISICAO_MAT', ts:Date.now(),
            obs:'Requisição de '+itensSel.length+' material(is)'});
        }
        progShowToast('✅ '+itensSel.length+' material(is) solicitado(s)! Gerente será notificado.');
      })
      .catch(function(e){
        if(st){ st.style.color='#A32D2D'; st.textContent='⚠ Erro ao enviar: '+e.message; }
        console.error('plptEnviarReservaInline:', e);
      });
  } else {
    if(st){ st.style.color='#3B6D11'; st.textContent='✅ Requisição enviada (demo)!'; }
    progShowToast('✅ Requisição enviada (modo demo)');
  }
}


function plptEnviarReserva(){
  var d     = _plptReservaAtual;
  var pj    = _plptDiario && _plptDiario.projetoAtivo;
  if(plptProjetoFaseExecucao(d.projeto_id, pj) || plptTemRequisicaoPendente(d.projeto_id, pj)){
    progShowToast('⚠ Não envie nova requisição — confirme aplicação na aba Campo do diário.','erro');
    return;
  }
  var itensSel = d.itens.filter(function(it){ return it.selecionado && it.qtd_req > 0; });
  if(!itensSel.length){
    progShowToast('⚠ Selecione ao menos um material com quantidade maior que zero.', 'erro');
    return;
  }
  var obs         = (document.getElementById('rsv-obs')||{}).value||'';
  if(obs.trim()) plptSalvarRelatorioObras(d.projeto_id, obs.trim());
  var rsvEquipeId = (_dbEquipe ? _dbEquipe.id : null) || d.equipe_id || '';
  var rsvData     = (document.getElementById('rsv-data')||{}).value||d.data||dataHojeLocal();

  if(!rsvEquipeId){
    progShowToast('⚠ Equipe não identificada na sessão do diário.','erro');
    return;
  }

  var payload = {
    projeto_id:  d.projeto_id,
    equipe_id:   rsvEquipeId,
    data:        rsvData,
    status:      'Aguardando aprovação',
    solicitante: usuarioLogado ? usuarioLogado.nome : '',
    observacoes: obs,
    itens:       JSON.stringify(itensSel.map(function(it){
      return {mat_id:it.mat_id, codigo:it.codigo, nome:it.nome, unidade:it.unidade,
              qtd_prog:it.qtd_prog, qtd_req:it.qtd_req};
    })),
    criado_em:   new Date().toISOString(),
  };

  if(!DEMO){
    sbInsert('plpt_requisicoes_materiais', payload).catch(function(e){
      console.error('plptEnviarReserva erro:', e);
    });
  }
  closeModal();
  progShowToast('✅ Requisição enviada para aprovação do gerente!');
  // Registrar no histórico do turno
  if(_dbSessao){
    var ev = {tipo:'REQUISICAO_MAT', ts:Date.now(),
      obs:'Requisição de '+itensSel.length+' material(is) — Projeto '+d.projeto_id};
    _dbSessao.eventos = _dbSessao.eventos||[];
    _dbSessao.eventos.push(ev);
  }
}

// ── Admin: visualizar e aprovar requisições ────────────────────────────
async function plptRenderRequisicoes(contratoId){
  var pnl = document.getElementById('pp-painel-requisicoes');
  var tblCheck = document.getElementById('plpt-req-tbl');
  console.log('[CENA-DEBUG] plpt-req-tbl inicial:', tblCheck ? 'ENCONTRADO' : 'NULL');
  // Garantir que o painel e os filtros existem no DOM
  var pnl = document.getElementById('pp-painel-requisicoes');
  if(pnl && !document.getElementById('req-fil-status')){
    pnl.innerHTML =
      '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.75rem;margin-bottom:.75rem">'
      +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;align-items:end">'
      +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Contrato</label>'
      +'<select class="inp" id="req-fil-contrato" style="width:100%" onchange="plptRenderRequisicoes()"><option value="">Todos</option></select></div>'
      +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Filial</label>'
      +'<select class="inp" id="req-fil-filial" style="width:100%" onchange="plptRenderRequisicoes()"><option value="">Todas</option></select></div>'
      +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Status</label>'
      +'<select class="inp" id="req-fil-status" style="width:100%" onchange="plptRenderRequisicoes()">'
      +'<option value="">Todos</option>'
      +'<option value="Aguardando aprovação">⏳ Aguardando aprovação</option>'
      +'<option value="Aprovada">✅ Aprovada</option>'
      +'<option value="Separação">📦 Separação</option>'
      +'<option value="Aguardando confirmação almox">⏳ Aguardando confirmação almox</option>'
      +'<option value="Em campo">🔧 Em campo</option>'
      +'<option value="Devolvida">🔄 Devolvida</option>'
      +'<option value="Reprovada">❌ Reprovada</option>'
      +'<option value="Excluída">🗑 Excluída</option>'
      +'</select></div>'
      +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Data início</label>'
      +'<input class="inp" type="date" id="req-fil-de" style="width:100%" onchange="plptRenderRequisicoes()"/></div>'
      +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Data fim</label>'
      +'<input class="inp" type="date" id="req-fil-ate" style="width:100%" onchange="plptRenderRequisicoes()"/></div>'
      +'<div style="display:flex;align-items:flex-end">'
      +'<button class="btn" onclick="plptLimparFiltrosReq()" style="width:100%">✕ Limpar</button></div>'
      +'</div></div>'
      +'<div id="plpt-req-tbl"><div style="padding:1.5rem;text-align:center;color:#aaa">⏳ Carregando...</div></div>';
  }

  var tbl = document.getElementById('plpt-req-tbl');
  if(!tbl){
    if(pnl){ tbl=document.createElement('div'); tbl.id='plpt-req-tbl'; pnl.appendChild(tbl); }
    else { return; }
  }

  if(DEMO){
    tbl.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Sem requisições no modo demo.</div>';
    return;
  }

  tbl.innerHTML='<div style="padding:1.5rem;text-align:center;color:#aaa">⏳ Carregando...</div>';

  var rows = [];
  try {
    var result = await sbFetch('plpt_requisicoes_materiais', {order:'criado_em.desc', limit:500});
    rows = Array.isArray(result) ? result : [];
  } catch(e) {
    console.error('plptRenderRequisicoes fetch erro:', e);
    tbl.innerHTML = '<div style="padding:2rem;text-align:center">'
      +'<div style="font-size:22px;margin-bottom:.5rem">📋</div>'
      +'<div style="color:#555;font-weight:600">Nenhuma requisição encontrada</div>'
      +'<div style="font-size:11px;color:#aaa;margin-top:.4rem">Verifique se o SQL de RLS foi executado no Supabase.<br>Erro: '
      +(e&&e.message||String(e))+'</div>'
      +'</div>';
    return;
  }

  try {
    // Popular selects na primeira carga
    _plptPopularFiltrosReq(rows);

    // Ler filtros
    var fContrato = (document.getElementById('req-fil-contrato')||{}).value||'';
    var fFilial   = (document.getElementById('req-fil-filial')||{}).value||'';
    var fStatus   = (document.getElementById('req-fil-status')||{}).value||'';
    var fDe       = (document.getElementById('req-fil-de')||{}).value||'';
    var fAte      = (document.getElementById('req-fil-ate')||{}).value||'';

    var filtered = rows.filter(function(r){
      // Handle Excluída: show only deleted if filter=Excluída, hide deleted otherwise
      if(fStatus === 'Excluída'){
        if(!r.deleted_at) return false;
      } else {
        if(r.deleted_at) return false; // always hide deleted unless specifically requested
        if(fStatus && r.status !== fStatus) return false;
      }
      var rData = (r.data||r.criado_em||'').slice(0,10);
      if(fDe  && rData < fDe)  return false;
      if(fAte && rData > fAte) return false;
      if(fContrato){
        var proj = (typeof sot_projetos!=='undefined'?sot_projetos:[]).find(function(p){return p.id===r.projeto_id;});
        // Compare as string to handle UUID vs text type differences
        if(!proj || String(proj.contrato_id) !== String(fContrato)) return false;
      }
      if(fFilial){
        var eq = equipes_disp.find(function(e){return e.id===r.equipe_id;})
              || equipes.find(function(e){return e.id===r.equipe_id;});
        if(!eq || eq.filial_id !== fFilial) return false;
      }
      return true;
    });

    if(!filtered.length){
      tbl.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">'
        +'<div style="font-size:22px;margin-bottom:.5rem">📋</div>'
        +'<div>Nenhuma requisição encontrada.</div>'
        +'<div style="font-size:11px;margin-top:.4rem;color:#bbb">Se esperava registros, verifique se o SQL de RLS foi executado no Supabase.</div>'
        +'</div>';
      return;
    }

    var SC = {'Aguardando aprovação':{bg:'#FEF3E2',c:'#854F0B'},'Aprovada':{bg:'#EAF3DE',c:'#3B6D11'},
      'Separação':{bg:'#EBF4FD',c:'#185FA5'},'Aguardando confirmação almox':{bg:'#F0EEFF',c:'#533AB7'},
      'Em campo':{bg:'#EAF3DE',c:'#085041'},'Devolvida':{bg:'#f5f5f3',c:'#888'},
      'Reprovada':{bg:'#FFF0F0',c:'#A32D2D'},'Excluída':{bg:'#f5f5f3',c:'#bbb'}};

    var counts={};
    filtered.forEach(function(r){counts[r.status]=(counts[r.status]||0)+1;});
    var metBar='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:.75rem">'
      +Object.keys(counts).map(function(st){var sc=SC[st]||{bg:'#f5f5f3',c:'#555'};
        return '<span style="background:'+sc.bg+';color:'+sc.c+';border-radius:8px;padding:3px 10px;font-size:11px;font-weight:600">'+st+': '+counts[st]+'</span>';
      }).join('')+'</div>';

    var rows_html = filtered.map(function(r){
      var eq   = equipes_disp.find(function(e){return e.id===r.equipe_id;})||equipes.find(function(e){return e.id===r.equipe_id;});
      var proj = (typeof sot_projetos!=='undefined'?sot_projetos:[]).find(function(p){return p.id===r.projeto_id;});
      var cont = proj?contratos.find(function(ct){return ct.id===proj.contrato_id;}):null;
      var fil  = eq&&eq.filial_id?filiais.find(function(f){return f.id===eq.filial_id;}):null;
      var itens= parseJsonField(r.itens,[]);
      var sc   = SC[r.status]||{bg:'#f5f5f3',c:'#555'};
      var btns = r.status==='Aguardando aprovação'
        ? '<div style="display:flex;gap:3px;flex-wrap:wrap">'
          +'<button class="btn btn-sm" onclick="plptAprovarReq(\''+r.id+'\')" style="background:#3B6D11;color:#fff;font-size:10px">✅ Aprovar</button>'
          +'<button class="btn btn-sm" onclick="plptReprovarReq(\''+r.id+'\')" style="background:#A32D2D;color:#fff;font-size:10px">❌ Reprovar</button></div>'
        : r.status==='Aprovada'
          ? '<button class="btn btn-sm" onclick="plptSepararReq(\''+r.id+'\')" style="background:#185FA5;color:#fff;font-size:10px">📦 Separar</button>'
        : r.status==='Separação'
          ? '<button class="btn btn-sm" onclick="plptEnviarCampoReq(\''+r.id+'\')" style="background:#533AB7;color:#fff;font-size:10px">🚚 Enviar campo</button>'
        : r.status==='Em campo'
          ? '<button class="btn btn-sm" onclick="plptDevolverReq(\''+r.id+'\')" style="font-size:10px">🔄 Devolução</button>'
          : '<button class="btn btn-sm" onclick="plptVerItens(\''+r.id+'\')" style="font-size:10px">👁 Ver</button>';
      // Botão excluir — sempre visível com justificativa obrigatória
      var btnDel = r.deleted_at ? '' :
        '<button class="btn btn-sm" onclick="plptExcluirReq(\''+r.id+'\')" '
        +'style="background:none;color:#A32D2D;border:.5px solid #A32D2D;font-size:10px;margin-left:4px" title="Excluir">🗑</button>';
      return '<tr style="border-bottom:.5px solid #f0efe8;opacity:'+(r.deleted_at?'0.5':'1')+'">'
        +'<td style="padding:7px 10px;white-space:nowrap">'+fmtD(r.data||r.criado_em)+'</td>'
        +'<td style="padding:7px 10px"><div style="font-weight:500">'+escHtml(eq?eq.codigo||eq.nome:'—')+'</div>'
        +(fil?'<div style="font-size:10px;color:#888">'+escHtml(fil.codigo||fil.nome)+'</div>':'')
        +(r.solicitante?'<div style="font-size:10px;color:#aaa">'+escHtml(r.solicitante)+'</div>':'')+'</td>'
        +'<td style="padding:7px 10px"><div style="font-weight:500">'+escHtml(proj?proj.codigo_cliente||proj.nome||proj.codigo:'—')+'</div>'
        +(cont?'<div style="font-size:10px;color:#888">'+escHtml(cont.codigo||cont.nome)+'</div>':'')+'</td>'
        +'<td style="padding:7px 10px;text-align:center"><button class="btn btn-sm" onclick="plptVerItens(\''+r.id+'\')" style="font-size:10px">'+itens.length+' item(ns)</button></td>'
        +'<td style="padding:7px 10px;text-align:center"><span style="background:'+sc.bg+';color:'+sc.c+';border-radius:8px;padding:2px 8px;font-size:10px;font-weight:600">'+r.status+'</span></td>'
        +'<td style="padding:7px 10px"><div style="display:flex;gap:2px;align-items:center;flex-wrap:wrap">'+btns+btnDel+'</div></td>'
        +'</tr>';
    }).join('');

    tbl.innerHTML = metBar
      +'<table style="width:100%;border-collapse:collapse;font-size:12px">'
      +'<thead><tr style="background:#1a1a18;color:#fff">'
      +'<th style="padding:7px 10px;text-align:left">Data</th>'
      +'<th style="padding:7px 10px;text-align:left">Equipe / Filial</th>'
      +'<th style="padding:7px 10px;text-align:left">Projeto / Contrato</th>'
      +'<th style="padding:7px 10px">Itens</th>'
      +'<th style="padding:7px 10px">Status</th>'
      +'<th style="padding:7px 10px">Ações</th>'
      +'</tr></thead><tbody>'+rows_html+'</tbody></table>';

  } catch(e2) {
    console.error('plptRenderRequisicoes render erro:', e2);
    tbl.innerHTML = '<div style="padding:2rem;text-align:center">'
      +'<div style="font-size:22px;margin-bottom:.5rem">📋</div>'
      +'<div style="color:#555;font-weight:600">Erro ao renderizar requisições</div>'
      +'<div style="font-size:11px;color:#aaa;margin-top:.4rem">'+(e2&&e2.message||String(e2))+'</div>'
      +'</div>';
  }
}

function _plptPopularFiltrosReq(rows){
  // Popular select de Contrato — preservar seleção atual
  var selCont = document.getElementById('req-fil-contrato');
  if(selCont){
    var valAtualCont = selCont.value; // salvar antes de repopular
    var conts = typeof _contratosVisiveis==='function' ? _contratosVisiveis() : contratos;
    // Só repopular se ainda não tiver opções suficientes
    if(selCont.options.length < conts.length + 1){
      while(selCont.options.length > 1) selCont.remove(1);
      conts
        .slice()
        .sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||''); })
        .forEach(function(ct){
          var opt = document.createElement('option');
          opt.value = ct.id;
          opt.textContent = ct.nome || ct.codigo || ct.id;
          selCont.appendChild(opt);
        });
    }
    // Restaurar seleção anterior
    if(valAtualCont) selCont.value = valAtualCont;
  }

  // Popular select de Filial — preservar seleção atual
  var selFil = document.getElementById('req-fil-filial');
  if(selFil){
    var valAtualFil = selFil.value; // salvar antes de repopular
    var doPopular = function(){
      if(selFil.options.length < filiais.length + 1){
        while(selFil.options.length > 1) selFil.remove(1);
        filiais
          .slice()
          .sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||''); })
          .forEach(function(f){
            var opt = document.createElement('option');
            opt.value = f.id;
            opt.textContent = (f.codigo ? f.codigo+' — ' : '') + (f.nome||f.id);
            selFil.appendChild(opt);
          });
      }
      // Restaurar seleção anterior
      if(valAtualFil) selFil.value = valAtualFil;
    };
    if(!filiais.length && !DEMO){
      sbFetch('filiais',{filters:['ativa=eq.true'],order:'nome'})
        .then(function(rows){ if(rows&&rows.length) filiais=rows; doPopular(); })
        .catch(function(){ doPopular(); });
    } else {
      doPopular();
    }
  }
}


function plptLimparFiltrosReq(){
  ['req-fil-contrato','req-fil-filial','req-fil-status','req-fil-de','req-fil-ate']
    .forEach(function(id){ var el=document.getElementById(id); if(el) el.value=''; });
  plptRenderRequisicoes();
}



function plptExcluirReq(id){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:400px">'
    +'<h3 style="margin-bottom:.5rem;color:#A32D2D">🗑 Excluir Requisição</h3>'
    +'<div style="background:#FFF0F0;border:.5px solid #A32D2D;border-radius:8px;padding:10px 14px;margin-bottom:.75rem;font-size:12px">'
    +'<div>Esta ação marcará a requisição como excluída. Ela não aparecerá mais na lista padrão, mas pode ser consultada com o filtro "Excluída".</div>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Justificativa obrigatória *</label>'
    +'<textarea class="inp" id="excl-just" placeholder="Motivo da exclusão..." rows="3" style="width:100%;resize:vertical"></textarea>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Seu nome *</label>'
    +'<input class="inp" id="excl-nome" value="'+(usuarioLogado?escHtml(usuarioLogado.nome||''):'')+'" style="width:100%"/>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="excl-confirmar" style="flex:2;background:#A32D2D;border-color:#A32D2D">🗑 Confirmar Exclusão</button>'
    +'</div></div></div>');

  setTimeout(function(){
    var btn = document.getElementById('excl-confirmar');
    if(!btn) return;
    btn.onclick = function(){
      var just = ((document.getElementById('excl-just')||{}).value||'').trim();
      var nome = ((document.getElementById('excl-nome')||{}).value||'').trim();
      if(!just){ progShowToast('⚠ Informe a justificativa.','erro'); return; }
      if(!nome){ progShowToast('⚠ Informe seu nome.','erro'); return; }
      closeModal();
      if(!DEMO){
        sbUpdate('plpt_requisicoes_materiais', {
          deleted_at:  new Date().toISOString(),
          observacoes: 'EXCLUÍDA por '+nome+' em '+new Date().toLocaleString('pt-BR')+' | '+just,
        }, 'id=eq.'+id)
        .then(function(){
          progShowToast('✅ Requisição excluída por '+nome);
          plptRenderRequisicoes();
        })
        .catch(function(e){ progShowToast('⚠ Erro: '+(e&&e.message||e),'erro'); });
      } else {
        progShowToast('✅ Requisição excluída (demo)');
        plptRenderRequisicoes();
      }
    };
  },50);
}


