function plptDevolverReq(id){
  var rows = typeof plpt_requisicoes !== 'undefined' ? plpt_requisicoes : [];
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3>🔄 Registrar Devolução</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">Informe as quantidades devolvidas por item:</div>'
    +'<div id="dev-body">⏳ Carregando...</div>'
    +'<div class="ma" style="margin-top:1rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="plptSalvarDevolucao(\''+id+'\')">💾 Salvar Devolução</button>'
    +'</div></div></div>');
  // Load itens
  sbFetch('plpt_requisicoes_materiais',{filters:['id=eq.'+id]}).then(function(rows){
    var r = rows && rows[0];
    if(!r){ document.getElementById('dev-body').textContent='Requisição não encontrada.'; return; }
    var itens = parseJsonField(r.itens,[]);
    document.getElementById('dev-body').innerHTML = '<table style="width:100%;font-size:12px;border-collapse:collapse">'
      +'<thead><tr style="background:#f5f5f3"><th style="padding:6px 8px;text-align:left">Material</th>'
      +'<th style="padding:6px 8px">Enviado</th><th style="padding:6px 8px">Devolvido</th></tr></thead>'
      +'<tbody>'
      +itens.map(function(it,i){
        return '<tr style="border-bottom:.5px solid #f0efe8">'
          +'<td style="padding:6px 8px">'+escHtml(it.nome)+'</td>'
          +'<td style="padding:6px 8px;text-align:center">'+it.qtd_req+' '+escHtml(it.unidade||'UN')+'</td>'
          +'<td style="padding:6px 8px;text-align:center">'
          +'<input type="number" id="dev-qtd-'+i+'" min="0" max="'+it.qtd_req+'" value="'+it.qtd_req+'" '
          +'style="width:65px;padding:4px;border:.5px solid #e0dfd8;border-radius:6px;text-align:center"/>'
          +'</td></tr>';
      }).join('')
      +'</tbody></table>';
    document.getElementById('dev-body').setAttribute('data-req-id', id);
    document.getElementById('dev-body').setAttribute('data-itens', JSON.stringify(itens));
  });
}

function plptSalvarDevolucao(reqId){
  var body = document.getElementById('dev-body');
  if(!body) return;
  var itens = parseJsonField(body.getAttribute('data-itens'),[]);
  var devolvidos = itens.map(function(it,i){
    var inp = document.getElementById('dev-qtd-'+i);
    return Object.assign({}, it, {qtd_dev: Number((inp&&inp.value)||0)});
  });
  if(!DEMO){
    sbUpdate('plpt_requisicoes_materiais',{
      status:'Devolvida',
      itens_devolucao: JSON.stringify(devolvidos),
      data_devolucao:  new Date().toISOString(),
    },'id=eq.'+reqId)
    .then(function(){ closeModal(); plptRenderRequisicoes(); progShowToast('✅ Devolução registrada!'); })
    .catch(function(e){ console.error(e); });
  } else {
    closeModal();
    progShowToast('✅ Devolução registrada (demo)');
  }
}


