function plptDiarioIniciarDia(){
  if(!_plptDiario.composConfirm){
    alert('Confirme a composição da equipe antes de iniciar o dia.');
    return;
  }
  var agora = new Date();
  var hora  = agora.toTimeString().slice(0,5);
  var hoje  = dataHojeLocal();
  // login_ts = timestamp numérico (campo real da tabela sessoes_disponibilidade)
  // inicio_ts = ISO string (alias para compatibilidade com renderDiarioPlpt)
  _plptDiario.sessao = {
    login_ts:  agora.getTime(),
    inicio_ts: (function(){var _d=agora;var off=-_d.getTimezoneOffset();var s=off>=0?'+':'-';var hh=String(Math.floor(Math.abs(off)/60)).padStart(2,'0');var mm=String(Math.abs(off)%60).padStart(2,'0');return _d.getFullYear()+'-'+String(_d.getMonth()+1).padStart(2,'0')+'-'+String(_d.getDate()).padStart(2,'0')+'T'+String(_d.getHours()).padStart(2,'0')+':'+String(_d.getMinutes()).padStart(2,'0')+':'+String(_d.getSeconds()).padStart(2,'0')+s+hh+':'+mm;})(),
    fim_ts:    null,
    logout_ts: null,
    eventos:   [{hora:hora, desc:'Início do dia'}]
  };
  var comp = composicao_dia.find(function(c){
    return c.equipe_id===_dbEquipe.id && c.data===hoje && !c._local;
  });
  if(!DEMO){
    // Inserir em sessoes_disponibilidade com timestamps ISO
    sbInsert('plpt_sessoes', {
      equipe_id:   _dbEquipe.id,
      data:        hoje,
      login_ts:    _plptDiario.sessao.login_ts,
      almoco_ts:   null,
      retorno_ts:  null,
      logout_ts:   null,
      placa:       '',
      km_inicial:  0,
      minutos_faturados: 0,
      eventos:     JSON.stringify(_plptDiario.sessao.eventos)
    }).then(function(r){
      if(r&&r[0]&&r[0].id) _plptDiario.sessao.id = r[0].id;
    }).catch(function(e){ console.warn('plpt_sessoes insert erro:', e); });

    // Salvar também em plpt_sessoes_dia se tiver prog
    if(_plptDiario.prog){
      sbInsert('plpt_sessoes_dia',{
        prog_dia_id:    _plptDiario.prog.id,
        equipe_id:      _dbEquipe.id,
        data:           hoje,
        inicio_ts:      _plptDiario.sessao.inicio_ts,
        colaborador_id: usuarioLogado ? usuarioLogado.id : null,
        eventos:        JSON.stringify(_plptDiario.sessao.eventos),
        status:         'em andamento'
      }).catch(function(){});
    }
  }
  progShowToast('▶ Turno iniciado');
  renderDiarioPlpt();
}

var _plptAlmocoTimer    = null;
var _plptAlmocoInicioTs = null;

// ── Salvar estado da sessão PLPT no banco ────────────────────────────────
function _plptSalvarLocal(){
  if(!_plptDiario.sessao || !usuarioLogado) return;
  var key = 'plpt_sessao_' + (usuarioLogado.id||usuarioLogado.equipe_id||'x');
  var estado = {
    ts: Date.now(),
    data: dataHojeLocal(),
    sessao: {
      id:         _plptDiario.sessao.id,
      login_ts:   _plptDiario.sessao.login_ts,
      inicio_ts:  _plptDiario.sessao.inicio_ts,
      almoco_ts:  _plptDiario.sessao.almoco_ts,
      retorno_ts: _plptDiario.sessao.retorno_ts,
      logout_ts:  _plptDiario.sessao.logout_ts,
      eventos:    _plptDiario.sessao.eventos||[]
    },
    projetoAtivo: _plptDiario.projetoAtivo ? {
      _pjId:     _plptDiario.projetoAtivo._pjId,
      projeto_id:_plptDiario.projetoAtivo._pjId,
      _timeline: _plptDiario.projetoAtivo._timeline||[]
    } : null
  };
  try{ localStorage.setItem(key, JSON.stringify(estado)); } catch(e){}
}

function _plptCarregarLocal(){
  if(!usuarioLogado) return null;
  var key = 'plpt_sessao_' + (usuarioLogado.id||usuarioLogado.equipe_id||'x');
  try{
    var raw = localStorage.getItem(key);
    if(!raw) return null;
    var estado = JSON.parse(raw);
    // Só usar se for do mesmo dia
    if(estado.data !== dataHojeLocal()) return null;
    // Não restaurar sessão já encerrada
    if(estado.sessao && estado.sessao.logout_ts) return null;
    return estado;
  } catch(e){ return null; }
}

function _plptLimparLocal(){
  if(!usuarioLogado) return;
  var key = 'plpt_sessao_' + (usuarioLogado.id||usuarioLogado.equipe_id||'x');
  try{ localStorage.removeItem(key); } catch(e){}
}


// Restore session state without overwriting today's project (used for "virada de dia" with new prog)
function _plptRestaurarSessaoMinima(sessaoRow){
  if(!sessaoRow || _plptDiario.sessao) return;
  console.log('[PLPT RESTORE MINIMA] apenas estado do turno, sem projeto ativo:', sessaoRow.id);
  var loginTs   = typeof sessaoRow.login_ts === 'number'
    ? new Date(sessaoRow.login_ts).toISOString()
    : sessaoRow.login_ts || new Date().toISOString();
  var inicioIso = sessaoRow.inicio_ts
    ? (typeof sessaoRow.inicio_ts === 'number'
        ? new Date(sessaoRow.inicio_ts).toISOString()
        : sessaoRow.inicio_ts)
    : loginTs;

  // Restore session info (timer, login) but NOT projetoAtivo
  _plptDiario.sessao = {
    id:         sessaoRow.id,
    data:       sessaoRow.data || (inicioIso ? inicioIso.slice(0,10) : null),
    login_ts:   loginTs,
    inicio_ts:  inicioIso,
    fim_ts:     sessaoRow.logout_ts ? new Date(sessaoRow.logout_ts).toISOString() : null,
    logout_ts:  sessaoRow.logout_ts || null,
    almoco_ts:  sessaoRow.almoco_ts || null,
    retorno_ts: sessaoRow.retorno_ts || null,
    eventos:    []  // don't restore old events — today is a fresh start
  };
  // _plptDiario.projetoAtivo remains null — will be set when user opens a project today
  // _plptDiario.projetos is already set from prog_dia
  console.log('[PLPT RESTORE MINIMA] sessao restaurada, projetoAtivo = null (nova execução hoje)');
}


function _plptRestaurarSessao(sessaoRow){
  console.log('[PLPT RESTORE] entrou', sessaoRow&&sessaoRow.id, 'já tem sessao?', !!_plptDiario.sessao, 'login_ts:', sessaoRow&&sessaoRow.login_ts, 'logout_ts:', sessaoRow&&sessaoRow.logout_ts, 'data:', sessaoRow&&sessaoRow.data);
  if(!sessaoRow || _plptDiario.sessao) return;
  var loginTs = sessaoRow.login_ts;
  var inicioIso = loginTs ? (typeof loginTs==='number' ? new Date(loginTs).toISOString() : loginTs) : null;
  var todosEventos = parseJsonField(sessaoRow.eventos, []);
  console.log('[PLPT RESTORE] eventos parseados:', todosEventos.length, todosEventos);

  var projState      = todosEventos.find(function(e){ return e.tipo === '_PROJ_STATE'; });
  var eventosVisuais = todosEventos.filter(function(e){ return e.tipo !== '_PROJ_STATE'; });
  console.log('[PLPT RESTORE] projState:', projState);

  _plptDiario.sessao = {
    id:         sessaoRow.id,
    data:       sessaoRow.data || (inicioIso ? inicioIso.slice(0,10) : null),
    login_ts:   loginTs,
    inicio_ts:  inicioIso,
    fim_ts:     sessaoRow.logout_ts ? new Date(sessaoRow.logout_ts).toISOString() : null,
    logout_ts:  sessaoRow.logout_ts  || null,
    almoco_ts:  sessaoRow.almoco_ts  || null,
    retorno_ts: sessaoRow.retorno_ts || null,
    eventos:    eventosVisuais
  };
  _plptDiario.composConfirm = true;
  console.log('[PLPT RESTORE] sessao restaurada:', _plptDiario.sessao.id, 'inicio_ts:', inicioIso);

  if(projState && projState.projId){
    var pjExist = _plptDiario.projetos.find(function(p){
      return p.projeto_id === projState.projId || p._pjId === projState.projId;
    });
    if(!pjExist){
      pjExist = {projeto_id: projState.projId, _pjId: projState.projId, status: 'em andamento'};
      _plptDiario.projetos.push(pjExist);
    }
    pjExist._pjId     = projState.projId;
    pjExist._timeline = projState.timeline || [];
    _plptDiario.projetoAtivo = pjExist;
    console.log('[PLPT RESTORE] projeto ativo restaurado:', projState.projId, 'timeline:', pjExist._timeline.length, 'etapas');
    // Garantir que sot_projetos tem este projeto
    if(typeof sot_projetos!=='undefined' && !sot_projetos.find(function(p){return p.id===projState.projId;}) && !DEMO){
      sbFetch('sot_projetos',{filters:['id=eq.'+projState.projId]})
        .then(function(rows){
          if(rows&&rows[0]) sot_projetos.push(rows[0]);
          renderDiarioPlpt();
        }).catch(function(){});
    }
  }
}

function plptSalvarSessao(){
  if(DEMO || !_plptDiario.sessao) return;
  var sess = _plptDiario.sessao;
  if(!sess.id || !isUUID(sess.id)){
    sess._pendingSave = true;
    return;
  }

  // Eventos visíveis (sem marcadores internos)
  var eventosVisuais = (sess.eventos||[]).filter(function(e){ return e.tipo !== '_PROJ_STATE'; });

  // Embutir estado do projeto ativo para restauração após reload
  var eventosParaSalvar = eventosVisuais.slice();
  if(_plptDiario.projetoAtivo && _plptDiario.projetoAtivo._pjId){
    eventosParaSalvar.push({
      tipo:     '_PROJ_STATE',
      projId:   _plptDiario.projetoAtivo._pjId,
      timeline: _plptDiario.projetoAtivo._timeline || []
    });
  }

  var payload = { eventos: JSON.stringify(eventosParaSalvar) };
  if(sess.almoco_ts)  payload.almoco_ts  = sess.almoco_ts;
  if(sess.retorno_ts) payload.retorno_ts = sess.retorno_ts;
  if(sess.logout_ts)  payload.logout_ts  = sess.logout_ts;
  if(sess.minutos_faturados!=null) payload.minutos_faturados = sess.minutos_faturados;
  console.log('[PLPT] salvar sessão', {id: sess.id, eventos: eventosParaSalvar.length, projetoAtivo: _plptDiario.projetoAtivo&&_plptDiario.projetoAtivo._pjId});
  _plptSalvarLocal(); // backup localStorage
  sbUpdate('plpt_sessoes', payload, 'id=eq.'+sess.id)
    .then(function(res){ console.log('[PLPT] update sessão OK', res); })
    .catch(function(e){ console.error('[PLPT] update sessão ERRO', e, payload); });
}

function plptDiarioAlmoco(){
  if(_plptAlmocoInicioTs){ alert('Você já está em almoço.'); return; }
  var agora = new Date();
  _plptAlmocoInicioTs = Date.now();
  if(_plptDiario.sessao && _plptDiario.sessao.eventos)
    _plptDiario.sessao.eventos.push({hora:agora.toTimeString().slice(0,5), desc:'Início do almoço'});
  if(_plptDiario.sessao) _plptDiario.sessao.almoco_ts = _plptAlmocoInicioTs;
  plptSalvarSessao();

  // Parar cronômetro principal
  if(_plptCronometroInterval){ clearInterval(_plptCronometroInterval); _plptCronometroInterval=null; }

  renderDiarioPlpt();
  _plptIniciarTimerAlmoco();
}

function _plptIniciarTimerAlmoco(){
  if(_plptAlmocoTimer) clearInterval(_plptAlmocoTimer);
  var fim = _plptAlmocoInicioTs + 55*60*1000;
  _plptAlmocoTimer = setInterval(function(){
    var el = document.getElementById('plpt-almoco-timer');
    if(!el){ clearInterval(_plptAlmocoTimer); return; }
    var restante = fim - Date.now();
    if(restante <= 0){
      clearInterval(_plptAlmocoTimer);
      el.textContent = '⏰ Almoço encerrado — clique em Retornar';
      el.style.background = '#A32D2D';
      return;
    }
    var m = Math.floor(restante/60000);
    var s = Math.floor((restante%60000)/1000);
    el.textContent = '🍽 Almoço — '+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+' restantes';
  }, 1000);
}

function plptDiarioRetornarAlmoco(){
  if(!_plptAlmocoInicioTs) return;
  clearInterval(_plptAlmocoTimer);
  _plptAlmocoTimer = null;
  var agora = new Date();
  var durMin = Math.round((Date.now()-_plptAlmocoInicioTs)/60000);
  _plptAlmocoInicioTs = null;
  if(_plptDiario.sessao && _plptDiario.sessao.eventos)
    _plptDiario.sessao.eventos.push({hora:agora.toTimeString().slice(0,5), desc:'Retorno do almoço ('+durMin+' min)'});
  if(_plptDiario.sessao) _plptDiario.sessao.retorno_ts = Date.now();
  plptSalvarSessao();
  progShowToast('✅ Retorno registrado — '+durMin+' min de almoço');
  renderDiarioPlpt();
  _plptIniciarCronometro();
}

function plptDiarioEncerrar(){
  if(!confirm('Confirma o encerramento do turno?')) return;
  var agora = new Date();
  var hora  = agora.toTimeString().slice(0,5);
  if(_plptDiario.sessao){
    _plptDiario.sessao.fim_ts = agora.toISOString();
    _plptDiario.sessao.logout_ts = agora.getTime();
    if(!_plptDiario.sessao.eventos) _plptDiario.sessao.eventos = [];
    _plptDiario.sessao.eventos.push({hora:hora, desc:'Encerramento do turno'});
    plptSalvarSessao();
    _plptLimparLocal(); // apagar backup ao encerrar
  }
  if(_plptCronometroInterval){ clearInterval(_plptCronometroInterval); _plptCronometroInterval=null; }
  progShowToast('■ Turno encerrado');
  renderDiarioPlpt();
}

function plptDiarioAbrirProjeto(projId){
  if(!_plptDiario.sessao||!_plptDiario.sessao.inicio_ts){
    alert('Inicie o turno antes de abrir uma ordem.');
    return;
  }

  // Guard: se o projetoAtivo já é este projeto e já tem eventos, apenas re-renderizar
  if(_plptDiario.projetoAtivo
     && _plptDiario.projetoAtivo._pjId === projId
     && _plptDiario.projetoAtivo._timeline
     && _plptDiario.projetoAtivo._timeline.length){
    _plptRenderProjetoDetalhe(projId);
    return;
  }

  // Buscar objeto do projeto — primeiro em projetos, depois criar entrada persistente
  var pj = _plptDiario.projetos.find(function(p){
    return p.projeto_id===projId || p._pjId===projId;
  });
  if(!pj){
    // Criar entrada persistente no array para manter _timeline entre navegações
    pj = {projeto_id: projId, _pjId: projId, status: 'pendente'};
    _plptDiario.projetos.push(pj);
  }
  pj._pjId    = projId;
  pj._timeline = pj._timeline || [];

  _plptDiario.projetoAtivo = pj;

  _plptRenderProjetoDetalhe(projId);
}

function _plptRenderProjetoDetalhe(projId){
  var pg  = document.getElementById('pg-diario'); if(!pg) return;
  var sot = (typeof sot_projetos!=='undefined' ? sot_projetos.find(function(x){return x.id===projId;}) : null)||{};
  var pj  = _plptDiario.projetoAtivo;
  var aba = pj._abaAtiva || 'timeline';
  // Código real do projeto — usar codigo_cliente > codigo > nome > id
  var codReal = sot.codigo_cliente || sot.codigo || sot.numero_cadastro || sot.nome || projId;

  var timeline = pj._timeline||[];
  var ETAPAS = ['A caminho','Chegou no local','APR preenchida','Início das atividades','Encerramento das atividades'];
  var etapaAtual = timeline.length ? timeline[timeline.length-1].desc : '';
  var idx = ETAPAS.indexOf(etapaAtual);
  var proximaEtapa = (idx>=0 && idx<ETAPAS.length-1) ? ETAPAS[idx+1] : null;
  var concluido = etapaAtual === 'Encerramento das atividades';

  // Carregar atividades/materiais/documentos se ainda não carregados
  var ativs  = (pj._atividades   || []);
  var mats   = (pj._materiais    || []);
  var docs   = (pj._documentos   || []);
  var loaded = pj._loaded;

  if(!loaded){
    pj._loaded = true;
    Promise.all([
      sbFetch('sot_atividades', {filters:['projeto_id=eq.'+projId], order:'ordem_exec'}),
      sbFetch('sot_materiais',  {filters:['projeto_id=eq.'+projId,'deleted_at=is.null']}),
      sbFetch('sot_documentos', {filters:['projeto_id=eq.'+projId], order:'criado_em.desc'}),
      sbFetch('sot_adicionais', {filters:['projeto_id=eq.'+projId], order:'criado_em.desc'}),
      sbFetch('plpt_requisicoes_materiais', {filters:['projeto_id=eq.'+projId,'deleted_at=is.null'], order:'criado_em.desc', limit:80}),
    ]).then(function(res){
      pj._atividades  = res[0]||[];
      pj._materiais   = res[1]||[];
      pj._documentos  = res[2]||[];
      pj._adicionais  = res[3]||[];
      pj._requisicoes = res[4]||[];
      if(plptProjetoFaseExecucao(projId, pj)) pj._faseExecucHint = true;
      _plptRenderProjetoDetalhe(projId);
    }).catch(function(){
      pj._atividades=[]; pj._materiais=[]; pj._documentos=[]; pj._adicionais=[]; pj._requisicoes=[];
      _plptRenderProjetoDetalhe(projId);
    });
    // Mostrar loading enquanto busca
    pg.innerHTML = '<div style="max-width:600px;margin:0 auto;padding:1rem;text-align:center;padding-top:3rem;color:#aaa">'
      +'<div style="font-size:24px;margin-bottom:.75rem">⏳</div>'
      +'<div>Carregando dados do projeto...</div></div>';
    return;
  }

  var faseExec = plptProjetoFaseExecucao(projId, pj);
  var retMap   = plptMateriaisRetiradosMap(projId, pj);
  if(faseExec) pj._baixaSubAba = 'executada';

  // ── Aba: Timeline ────────────────────────────────
  var timelineHtml = timeline.map(function(ev){
    return '<div style="display:flex;gap:8px;padding:4px 0;font-size:12px">'
      +'<span style="color:#185FA5;font-weight:600;flex-shrink:0;width:40px">'+ev.hora+'</span>'
      +'<span>'+ev.desc+'</span>'
      +'</div>';
  }).join('') || '<div style="font-size:12px;color:#aaa;padding:.5rem 0">Aguardando início</div>';

  // ── Aba: Atividades ──────────────────────────────
  // Compute overall state for banner
  var _semViab = ativs.filter(function(a){ return (a._qtdViab!==undefined?a._qtdViab:(a.qtd_viabilizada||0))===0; });
  var _semExec = ativs.filter(function(a){
    var v=a._qtdViab!==undefined?a._qtdViab:(a.qtd_viabilizada||0);
    var e=a._qtdExec!==undefined?a._qtdExec:(a.qtd_executada||0);
    return faseExec ? e===0 : (v>0&&e===0);
  });
  var _estadoBanner = '';
  if(ativs.length){
    if(faseExec){
      if(_semExec.length)
        _estadoBanner = '<div style="background:#EAF3DE;border-left:3px solid #3B6D11;border-radius:0 6px 6px 0;padding:.5rem .75rem;margin-bottom:.5rem;font-size:11px;font-weight:700;color:#3B6D11">▶ Fase de execução — '+_semExec.length+' atividade'+(+_semExec.length>1?'s':'')+' para executar</div>';
      else
        _estadoBanner = '<div style="background:#EAF3DE;border-left:3px solid #3B6D11;border-radius:0 6px 6px 0;padding:.5rem .75rem;margin-bottom:.5rem;font-size:11px;font-weight:700;color:#3B6D11">✅ Todas as atividades executadas</div>';
    } else if(_semViab.length)
      _estadoBanner = '<div style="background:#FEF3E2;border-left:3px solid #854F0B;border-radius:0 6px 6px 0;padding:.5rem .75rem;margin-bottom:.5rem;font-size:11px;font-weight:700;color:#854F0B">📋 Ação necessária: Viabilidade — '+_semViab.length+' atividade'+(+_semViab.length>1?'s':'')+' aguardando</div>';
    else if(_semExec.length)
      _estadoBanner = '<div style="background:#EAF3DE;border-left:3px solid #3B6D11;border-radius:0 6px 6px 0;padding:.5rem .75rem;margin-bottom:.5rem;font-size:11px;font-weight:700;color:#3B6D11">▶ Ação necessária: Execução — '+_semExec.length+' atividade'+(+_semExec.length>1?'s':'')+' pronta'+(+_semExec.length>1?'s':'')+' para executar</div>';
    else
      _estadoBanner = '<div style="background:#EAF3DE;border-left:3px solid #3B6D11;border-radius:0 6px 6px 0;padding:.5rem .75rem;margin-bottom:.5rem;font-size:11px;font-weight:700;color:#3B6D11">✅ Todas as atividades executadas</div>';
  }

  var ativsHtml = ativs.length
    ? _estadoBanner + ativs.map(function(a, i){
        var viab    = a._qtdViab  !== undefined ? a._qtdViab  : (a.qtd_viabilizada||0);
        var exec    = a._qtdExec  !== undefined ? a._qtdExec  : (a.qtd_executada||0);
        var temViab = viab > 0;
        var stCor   = exec>0?'#3B6D11':viab>0?'#185FA5':'#aaa';
        var stLabel = exec>0?'Executado':viab>0?'Viabilizado':'Pendente';
        return '<div style="border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .75rem;margin-bottom:6px">'
          +'<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">'
          +'<div style="flex:1;min-width:0">'
          +'<div style="font-size:12px;font-weight:600">'+(a.descricao||a.codigo||'—')+'</div>'
          +'<div style="font-size:10px;color:#aaa;margin-top:1px">'+(a.codigo||'')+(a.etapa?' | Etapa: '+a.etapa:'')+'</div>'
          +'<div style="display:flex;gap:8px;margin-top:4px;font-size:11px">'
          +'<span style="color:#888">Prev: <b>'+(a.qtd_prevista||0)+'</b></span>'
          +'<span style="color:#185FA5">Viab: <b>'+viab+'</b></span>'
          +'<span style="color:#3B6D11">Exec: <b>'+exec+'</b></span>'
          +'<span style="color:#888">'+(a.unidade||'UN')+'</span>'
          +'</div>'
          +(a._obsViab||a._obsExec
            ? '<div style="font-size:10px;color:#888;margin-top:3px;font-style:italic">'
              +(a._obsViab?'Viab: '+a._obsViab:'')
              +(a._obsViab&&a._obsExec?' · ':'')
              +(a._obsExec?'Exec: '+a._obsExec:'')
              +'</div>'
            : '')
          +'</div>'
          +'<div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0">'
          +'<span style="font-size:10px;color:'+stCor+';font-weight:600;text-align:right">'+stLabel+'</span>'
          +(faseExec
            ? (exec===0
              ? '<button onclick="plptLancarAtividade(\\\''+projId+'\\\',' +i+')" '
                +'style="padding:4px 10px;background:#3B6D11;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:600;white-space:nowrap">▶ Execução</button>'
              : '<span style="font-size:18px">✅</span>')
            : (viab===0
            ? '<button onclick="plptLancarViabilidadeAtividade(\\\''+projId+'\\\',' +i+')" '
              +'style="padding:4px 10px;background:#854F0B;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:600;white-space:nowrap">📋 Viabilidade</button>'
            : exec===0
              ? '<button onclick="plptLancarAtividade(\\\''+projId+'\\\',' +i+')" '
                +'style="padding:4px 10px;background:#3B6D11;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:600;white-space:nowrap">▶ Execução</button>'
              : '<span style="font-size:18px">✅</span>'))
          +'</div>'
          +'</div></div>';
      }).join('')
    : '<div style="font-size:12px;color:#aaa;padding:1rem;text-align:center">Nenhuma atividade cadastrada neste projeto</div>';

  // ── Aba: Materiais ───────────────────────────────
  var matsHtml = mats.length
    ? mats.map(function(m, i){
        var viab    = m._qtdViab  !== undefined ? m._qtdViab  : (m.qtd_viabilizada||m.qtd||0);
        var aplic   = m._qtdAplic !== undefined ? m._qtdAplic : (m.qtd_aplicada||0);
        var temViab = viab > 0;
        var stCor   = aplic>0?'#3B6D11':viab>0?'#185FA5':'#aaa';
        var stLabel = aplic>0?'Aplicado':viab>0?'Viabilizado':'Pendente';
        return '<div style="border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .75rem;margin-bottom:6px">'
          +'<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">'
          +'<div style="flex:1;min-width:0">'
          +'<div style="font-size:12px;font-weight:600">'+(m.descricao||m.codigo_sap||'—')+'</div>'
          +'<div style="font-size:10px;color:#aaa;margin-top:1px">'+(m.codigo_sap||'')+'</div>'
          +'<div style="display:flex;gap:8px;margin-top:4px;font-size:11px">'
          +'<span style="color:#888">Prev: <b>'+(m.qtd||m.qtd_prevista||0)+'</b></span>'
          +'<span style="color:#185FA5">Viab: <b>'+viab+'</b></span>'
          +'<span style="color:#3B6D11">Aplic: <b>'+aplic+'</b></span>'
          +'<span style="color:#888">'+(m.unidade||'UN')+'</span>'
          +'</div>'
          +(m._obsViab||m._obsAplic
            ? '<div style="font-size:10px;color:#888;margin-top:3px;font-style:italic">'
              +(m._obsViab?'Viab: '+m._obsViab:'')
              +(m._obsViab&&m._obsAplic?' · ':'')
              +(m._obsAplic?'Aplic: '+m._obsAplic:'')
              +'</div>'
            : '')
          +'</div>'
          +'<div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0">'
          +'<span style="font-size:10px;color:'+stCor+';font-weight:600;text-align:right">'+stLabel+'</span>'
          +'<button onclick="plptLancarMaterial(\''+projId+'\','+i+')" '
          +'style="padding:4px 10px;background:'+(faseExec?'#3B6D11':'#1a1a18')+';color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:600;white-space:nowrap">'+(faseExec?'▶ Aplicar':'▶ Lançar')+'</button>'
          +'</div>'
          +'</div></div>';
      }).join('')
    : '<div style="font-size:12px;color:#aaa;padding:1rem;text-align:center">Nenhum material cadastrado neste projeto</div>';

  // ── Aba: Documentos ──────────────────────────────
  var iconeDoc = function(d){
    var ext = (d.arquivo_nome||d.nome||'').split('.').pop().toLowerCase();
    return {pdf:'📄',kml:'🗺',kmz:'🗺',dwg:'📐',dxf:'📐',doc:'📝',docx:'📝',xml:'📋'}[ext]||'📎';
  };
  var docsHtml = docs.length
    ? docs.map(function(d, di){
        var link  = d.arquivo_url||d.url||null;
        var b64   = d.arquivo_base64||null;
        var tipo  = (d.arquivo_tipo||'').toLowerCase();
        var isPdf = tipo.includes('pdf')||(d.arquivo_nome||d.nome||'').toLowerCase().endsWith('.pdf');
        var href  = link || (b64 ? 'data:'+(d.arquivo_tipo||'application/octet-stream')+';base64,'+b64 : null);
        return '<div style="border:.5px solid #e0dfd8;border-radius:8px;overflow:hidden;margin-bottom:6px" id="plpt-doc-card-'+di+'">'
          +'<div style="display:flex;align-items:center;gap:8px;padding:.6rem .75rem;background:#fff">'
          +'<span style="font-size:18px;flex-shrink:0">'+iconeDoc(d)+'</span>'
          +'<div style="flex:1;min-width:0">'
          +'<div style="font-size:12px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(d.nome||d.arquivo_nome||'Documento')+'</div>'
          +'<div style="font-size:10px;color:#888">'+(d.tipo||'arquivo').toUpperCase()
            +(d.arquivo_tamanho?' · '+Math.round(d.arquivo_tamanho/1024)+'KB':'')
            +(d.criado_em?' · '+fmtD(d.criado_em.split('T')[0]):'')+'</div>'
          +'</div>'
          +'<div style="display:flex;gap:4px;flex-shrink:0">'
          +(isPdf && b64
            ? '<button onclick="plptDocTogglePreview('+di+')" id="plpt-doc-btn-'+di+'" style="padding:4px 8px;background:#185FA5;color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:11px">👁 Ver</button>'
            : href
              ? '<a href="'+href+'" '+(link?'target="_blank"':'download="'+(d.arquivo_nome||d.nome||'arquivo')+'"')+' style="padding:4px 8px;background:#185FA5;color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:11px;text-decoration:none">'+(link?'↗':'⬇')+'</a>'
              : ''
          )
          +'</div></div>'
          // Preview iframe para PDF base64
          +(isPdf && b64
            ? '<div id="plpt-doc-preview-'+di+'" style="display:none">'
              +'<iframe src="data:application/pdf;base64,'+b64+'" style="width:100%;height:480px;border:none;display:block"></iframe>'
              +'</div>'
            : '')
          +'</div>';
      }).join('')
    : '<div style="font-size:12px;color:#aaa;padding:1rem;text-align:center">Nenhum documento cadastrado neste projeto</div>';

  // ── Aba: Baixa de Materiais (Viabilidade + Executada) ───
  var baixaSubAba = pj._baixaSubAba||'viabilidade';
  if(faseExec) baixaSubAba = 'executada';
  var baixaHtml;
  if(faseExec){
    baixaHtml = '<div>'
      +'<div style="font-size:12px;color:#3B6D11;background:#EAF3DE;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem">'
      +'<b>Fase de execução</b> — viabilidade já concluída neste projeto. Informe a quantidade aplicada. '
      +'Materiais <span style="color:#3B6D11;font-weight:700">em verde</span> foram retirados pela equipe.'
      +'</div>'
      +(mats.length
        ? mats.map(function(m,i){
            var aplic = m._qtdAplic !==undefined ? m._qtdAplic : (m.qtd_aplicada||0);
            var previsto = m.qtd||m.qtd_prevista||0;
            var retQtd = plptMatRetiradoQtd(m, retMap);
            var isRet = retQtd > 0;
            var bg = isRet ? '#EAF3DE' : '#fff';
            var border = isRet ? '#3B6D11' : '#e0dfd8';
            return '<div style="border:.5px solid '+border+';border-radius:8px;padding:.6rem .75rem;margin-bottom:6px;background:'+bg+'">'
              +'<div style="display:flex;align-items:flex-start;gap:8px">'
              +'<input type="checkbox" id="baixa-chk-'+i+'" onchange="plptBaixaToggleItem('+i+','+(isRet?'true':'false')+')" style="margin-top:4px;cursor:pointer;flex-shrink:0"/>'
              +'<div style="flex:1;min-width:0">'
              +'<div style="display:flex;align-items:center;gap:6px">'
              +'<div style="font-size:12px;font-weight:600">'+(m.descricao||m.codigo_sap||'—')+'</div>'
              +(isRet?'<span style="font-size:9px;background:#3B6D11;color:#fff;border-radius:3px;padding:1px 6px;font-weight:700">Retirado '+retQtd+'</span>':'')
              +'</div>'
              +'<div style="font-size:10px;color:#888">'+(m.codigo_sap||'—')+' · Prev: '+(previsto||0)+' '+(m.unidade||'UN')+'</div>'
              +(!isRet
                ? '<div id="baixa-motivo-wrap-'+i+'" style="display:none;margin-top:6px">'
                  +'<label style="font-size:10px;font-weight:600;color:#854F0B;display:block;margin-bottom:2px">Justificativa * — material não retirado</label>'
                  +'<textarea id="baixa-motivo-'+i+'" rows="2" placeholder="Explique como está aplicando sem retirada..." '
                  +'style="width:100%;padding:4px 6px;border:.5px solid #854F0B;border-radius:6px;font-size:11px;resize:none;box-sizing:border-box"></textarea>'
                  +'</div>'
                : '')
              +'</div>'
              +'<div style="display:flex;align-items:center;gap:6px;flex-shrink:0">'
              +'<input type="number" min="0" max="'+previsto+'" value="'+(aplic||0)+'" '
              +'id="baixa-executada-'+i+'" disabled '
              +'style="width:60px;padding:4px 6px;border:.5px solid #e0dfd8;border-radius:6px;font-size:14px;text-align:center;background:#f5f5f3"/>'
              +'<span style="font-size:10px;color:#888">'+(m.unidade||'UN')+'</span>'
              +'<button onclick="plptSalvarBaixa(\''+projId+'\','+i+',\'executada\')" '
              +'style="padding:4px 10px;background:#3B6D11;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:600">✓</button>'
              +'</div></div></div>';
          }).join('')
        : '<div style="font-size:12px;color:#aaa;padding:1rem;text-align:center">Nenhum material neste projeto</div>'
      )
      +'</div>';
  } else {
    baixaHtml = '<div>'
      +'<div style="display:flex;border-bottom:.5px solid #e0dfd8;margin-bottom:.75rem">'
      +'<button onclick="plptBaixaSubAba(\''+projId+'\',\'viabilidade\')" style="flex:1;padding:.5rem;border:none;border-bottom:2px solid '+(baixaSubAba==='viabilidade'?'#185FA5':'transparent')+';background:none;color:'+(baixaSubAba==='viabilidade'?'#185FA5':'#888')+';font-size:12px;font-weight:'+(baixaSubAba==='viabilidade'?'700':'500')+';cursor:pointer">📋 Viabilidade</button>'
      +'<button onclick="plptBaixaSubAba(\''+projId+'\',\'executada\')" style="flex:1;padding:.5rem;border:none;border-bottom:2px solid '+(baixaSubAba==='executada'?'#3B6D11':'transparent')+';background:none;color:'+(baixaSubAba==='executada'?'#3B6D11':'#888')+';font-size:12px;font-weight:'+(baixaSubAba==='executada'?'700':'500')+';cursor:pointer">✅ Executada</button>'
      +'</div>'
      +(mats.length
        ? mats.map(function(m,i){
            var viab  = m._qtdViab  !==undefined ? m._qtdViab  : (m.qtd_viabilizada||0);
            var aplic = m._qtdAplic !==undefined ? m._qtdAplic : (m.qtd_aplicada||0);
            var previsto = m.qtd||m.qtd_prevista||0;
            var campo = baixaSubAba==='viabilidade' ? viab : aplic;
            var corBotao = baixaSubAba==='viabilidade' ? '#185FA5' : '#3B6D11';
            return '<div style="border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .75rem;margin-bottom:6px">'
              +'<div style="display:flex;align-items:center;justify-content:space-between;gap:8px">'
              +'<div style="flex:1;min-width:0">'
              +'<div style="font-size:12px;font-weight:600">'+(m.descricao||m.codigo_sap||'—')+'</div>'
              +'<div style="font-size:10px;color:#888">'+(m.codigo_sap||'—')+' · Prev: '+(previsto||0)+' '+(m.unidade||'UN')+'</div>'
              +'</div>'
              +'<div style="display:flex;align-items:center;gap:6px;flex-shrink:0">'
              +'<input type="number" min="0" max="'+previsto+'" value="'+(campo||0)+'" '
              +'id="baixa-'+baixaSubAba+'-'+i+'" '
              +'style="width:60px;padding:4px 6px;border:.5px solid #e0dfd8;border-radius:6px;font-size:14px;text-align:center"/>'
              +'<span style="font-size:10px;color:#888">'+(m.unidade||'UN')+'</span>'
              +'<button onclick="plptSalvarBaixa(\''+projId+'\','+i+',\''+baixaSubAba+'\')" '
              +'style="padding:4px 10px;background:'+corBotao+';color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:600">✓</button>'
              +'</div></div></div>';
          }).join('')
        : '<div style="font-size:12px;color:#aaa;padding:1rem;text-align:center">Nenhum material neste projeto</div>'
      )
      +'</div>';
  }

  // ── Aba: Adicional ───────────────────────────────
  var adics = pj._adicionais || [];
  var adicAtivs = adics.filter(function(a){return a.tipo==='atividade';});
  var adicMats  = adics.filter(function(a){return a.tipo==='material';});

  function renderAdicItem(item, i){
    return '<div style="border:.5px solid #854F0B44;border-radius:8px;padding:.6rem .75rem;margin-bottom:6px;background:#FFFBF5">'
      +'<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:12px;font-weight:600">'+(item.descricao||'—')+'</div>'
      +'<div style="font-size:10px;color:#888">'+(item.codigo_sap||'')+(item.codigo_sap?' · ':'')+item.qtd_solicitada+' '+(item.unidade||'UN')+'</div>'
      +(item.observacoes?'<div style="font-size:10px;color:#555;margin-top:2px;font-style:italic">'+item.observacoes+'</div>':'')
      +(item.fotos&&item.fotos.length?'<div style="font-size:10px;color:#185FA5;margin-top:2px">📷 '+item.fotos.length+' foto(s)</div>':'')
      +'</div>'
      +'<div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0">'
      +'<span style="font-size:9px;color:#854F0B;font-weight:600">ADICIONAL</span>'
      +'<button onclick="plptEditarAdicional(\''+projId+'\','+i+',\''+item.tipo+'\')" '
      +'style="padding:3px 8px;background:#fff;color:#555;border:.5px solid #e0dfd8;border-radius:5px;cursor:pointer;font-size:10px">✏️</button>'
      +(item.status==='aprovado'
        ? '<span style="font-size:9px;background:#EAF3DE;color:#3B6D11;border-radius:3px;padding:2px 6px">✅ Aprovado</span>'
        : (function(){
            // Only coordinator+ can approve
            var cargo = (usuarioLogado&&usuarioLogado.cargo||'').toLowerCase();
            var podeAprovar = ['coordenador','gerente','supervisor','admin','diretor','gestor'].some(function(r){return cargo.includes(r);});
            if(!podeAprovar) return '<span style="font-size:9px;background:#FEF3E2;color:#854F0B;border-radius:3px;padding:2px 6px">⏳ Aguard. aprovação</span>';
            return '<div style="display:flex;flex-direction:column;gap:3px">'
              +'<button onclick="plptAprovarAdicional(\''+projId+'\',\''+item.id+'\',\''+item.catalog_id+'\',\''+escHtml(item.descricao||'')+'\',' +item.qtd_solicitada+',\''+item.unidade+'\',\''+escHtml(item.codigo_sap||'')+'\')" '
              +'style="padding:3px 8px;background:#3B6D11;color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:10px">✅ Aprovar</button>'
              +'<span style="font-size:9px;background:#FEF3E2;color:#854F0B;border-radius:3px;padding:2px 6px;text-align:center">⏳ Pendente</span>'
              +'</div>';
          })()
        )
      +'</div></div></div>';
  }

// ── Aba: Campo / Reserva ─────────────────────────────────────────────
  if(!pj._relatorioObras && sot.relatorio_obras) pj._relatorioObras = sot.relatorio_obras;
  var reservaHtml = plptBuildAbaCampo(projId, pj, faseExec, sot);
  var resumoHtml  = plptRenderResumoOperacoes(projId, pj, sot, ativs, mats);

  var adicHtml = '<div>'
    // Sub-abas Atividades / Materiais
    +'<div style="display:flex;gap:4px;margin-bottom:.75rem">'
    +'<button onclick="plptAdicSubAba(\''+projId+'\',\'atividade\')" '
    +'style="flex:1;padding:6px;border-radius:6px;border:.5px solid '+(pj._adicSub==='atividade'?'#185FA5':'#e0dfd8')+';background:'+(pj._adicSub==='atividade'?'#EBF4FD':'#fff')+';color:'+(pj._adicSub==='atividade'?'#185FA5':'#555')+';font-size:11px;font-weight:'+(pj._adicSub==='atividade'?'700':'400')+';cursor:pointer">⚡ Atividades ('+adicAtivs.length+')</button>'
    +'<button onclick="plptAdicSubAba(\''+projId+'\',\'material\')" '
    +'style="flex:1;padding:6px;border-radius:6px;border:.5px solid '+(pj._adicSub!=='atividade'?'#854F0B':'#e0dfd8')+';background:'+(pj._adicSub!=='atividade'?'#FEF3E2':'#fff')+';color:'+(pj._adicSub!=='atividade'?'#854F0B':'#555')+';font-size:11px;font-weight:'+(pj._adicSub!=='atividade'?'700':'400')+';cursor:pointer">📦 Materiais ('+adicMats.length+')</button>'
    +'</div>'
    // Lista
    +(pj._adicSub==='atividade'
      ? (adicAtivs.length ? adicAtivs.map(function(a,i){return renderAdicItem(a,i);}).join('') : '<div style="font-size:12px;color:#aaa;text-align:center;padding:1rem">Nenhuma atividade adicional</div>')
      : (adicMats.length  ? adicMats.map(function(a,i){return renderAdicItem(a,i);}).join('') : '<div style="font-size:12px;color:#aaa;text-align:center;padding:1rem">Nenhum material adicional</div>')
    )
    // Botões
    +'<div style="display:flex;gap:6px;margin-top:.75rem">'
    +'<button onclick="plptNovoAdicional(\''+projId+'\',\''+(pj._adicSub||'material')+'\')" '
    +'style="flex:1;padding:10px;background:#854F0B;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:12px;font-weight:600">+ Adicionar '+(pj._adicSub==='atividade'?'atividade':'material')+'</button>'
    +'<button onclick="plptGerarDePara(\''+projId+'\')" '
    +'style="flex:1;padding:10px;background:#185FA5;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:12px;font-weight:600">📋 Gerar De Para</button>'
    +'</div></div>';

  // ── Selector de aba ──────────────────────────────
  function btnAba(id,label,icon){
    var ativo=aba===id;
    return '<button onclick="plptSetAba(\''+projId+'\',\''+id+'\')" style="flex:1;padding:.45rem 2px;border:none;border-bottom:2px solid '+(ativo?'#185FA5':'transparent')+';background:none;color:'+(ativo?'#185FA5':'#888')+';font-size:10px;font-weight:'+(ativo?'700':'500')+';cursor:pointer">'+icon+'<br>'+label+'</button>';
  }

  var abaCampoLabel = (faseExec || plptRequisicoesEmCampo(projId, pj).length) ? 'Campo' : 'Reservar';
  var abaContent = aba==='atividades' ? ativsHtml
    : aba==='materiais'  ? matsHtml
    : aba==='reserva'    ? reservaHtml
    : aba==='resumo'     ? resumoHtml
    : aba==='adicional'  ? adicHtml
    : aba==='baixa'      ? baixaHtml
    : aba==='documentos' ? docsHtml
    : timelineHtml;

  // ── Render final ─────────────────────────────────
  pg.innerHTML = '<div style="max-width:600px;margin:0 auto;padding:1rem">'

    // Header com voltar
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:1rem">'
    +'<button onclick="renderDiarioPlpt()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#555">◀</button>'
    +'<div style="flex:1;min-width:0">'
    +'<div style="font-size:15px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+codReal+'</div>'
    +'<div style="font-size:11px;color:#888">'+(sot.nome||'')+(sot.tipo_servico?' · '+sot.tipo_servico:'')+(sot.cidade?' · '+sot.cidade:'')+'</div>'
    +'</div>'
    +'<span style="font-size:11px;color:#185FA5;font-weight:600;flex-shrink:0">'+(etapaAtual||'Pendente')+'</span>'
    +'</div>'

    // Abas
    +'<div style="display:flex;border-bottom:1px solid #e0dfd8;margin-bottom:.75rem">'
    +btnAba('timeline',  'Status',    '📍')
    +btnAba('atividades','Atividades','⚡')
    +btnAba('materiais', 'Materiais', '📦')
    +btnAba('reserva',   abaCampoLabel, (faseExec?'✅':'🧰'))
    +btnAba('resumo',    'Resumo',    '📊')
    +btnAba('adicional', 'Adicional', '➕')
    +btnAba('baixa',     'Baixa',     '✏️')
    +btnAba('documentos','Docs',      '📄')
    +'</div>'

    // Conteúdo da aba
    +'<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem;margin-bottom:.75rem">'
    + abaContent
    +'</div>'

    // Botões de ação (só na aba timeline)
    +(aba==='timeline'
      ? (!timeline.length
          // Projeto ainda não iniciado — botão inicial "A caminho"
          ? '<button onclick="plptDiarioIniciarACaminho(\''+projId+'\')" style="width:100%;padding:.85rem;background:#185FA5;color:#fff;border:none;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;margin-bottom:.5rem">🚗 A caminho</button>'
          : (proximaEtapa && !concluido
              ? '<button onclick="plptDiarioAvancarEtapa(\''+projId+'\')" style="width:100%;padding:.85rem;background:#1a1a18;color:#fff;border:none;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;margin-bottom:.5rem">→ '+proximaEtapa+'</button>'
              : '')
            +(concluido
              ? '<button onclick="plptDiarioEncerrarOrdem(\''+projId+'\')" style="width:100%;padding:.85rem;background:#3B6D11;color:#fff;border:none;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;margin-bottom:.5rem">✓ Atividade encerrada</button>'
              : '')
        )
        +'<button onclick="plptDiarioAdicionarFoto(\''+projId+'\')" style="width:100%;padding:.7rem;background:#fff;color:#555;border:.5px solid #e0dfd8;border-radius:10px;font-size:13px;cursor:pointer;margin-bottom:.5rem">📷 Adicionar foto</button>'
        +'<button onclick="plptDiaroCancelarOrdem(\''+projId+'\')" style="width:100%;padding:.7rem;background:#fff;color:#A32D2D;border:.5px solid #A32D2D;border-radius:10px;font-size:13px;cursor:pointer">✕ Cancelar ordem</button>'
      : '')

    +'</div>';
}

function plptDiarioIniciarACaminho(projId){
  var pj  = _plptDiario.projetoAtivo;
  if(!pj || (pj._pjId||pj.projeto_id) !== projId) return;
  if(pj._timeline && pj._timeline.length){ return; } // já iniciado, ignorar duplo clique
  var sot = (typeof sot_projetos!=='undefined' ? sot_projetos.find(function(x){return x.id===projId;}) : null)||{};
  var hora = new Date().toTimeString().slice(0,5);
  pj._timeline = pj._timeline || [];
  pj._timeline.push({hora:hora, desc:'A caminho'});
  if(_plptDiario.sessao){
    if(!_plptDiario.sessao.eventos) _plptDiario.sessao.eventos=[];
    _plptDiario.sessao.eventos.push({hora:hora, desc:'A caminho — '+(sot.codigo_cliente||sot.codigo||sot.nome||'Projeto')});
    plptSalvarSessao();
  }
  _plptRenderProjetoDetalhe(projId);
}

function plptBaixaSubAba(projId, subAba){
  if(_plptDiario.projetoAtivo){
    if(plptProjetoFaseExecucao(projId, _plptDiario.projetoAtivo)) return;
    _plptDiario.projetoAtivo._baixaSubAba=subAba;
  }
  _plptRenderProjetoDetalhe(projId);
}

function plptBaixaToggleItem(idx, isRetirado){
  var chk = document.getElementById('baixa-chk-'+idx);
  var inp = document.getElementById('baixa-executada-'+idx);
  var wrap = document.getElementById('baixa-motivo-wrap-'+idx);
  if(!chk) return;
  var on = chk.checked;
  if(inp){
    inp.disabled = !on;
    inp.style.background = on ? '#fff' : '#f5f5f3';
  }
  if(wrap && !isRetirado) wrap.style.display = on ? 'block' : 'none';
}

function plptSalvarBaixa(projId, idx, tipo){
  var pj = _plptDiario.projetoAtivo; if(!pj) return;
  var mat = (pj._materiais||[])[idx]; if(!mat) return;
  var faseExec = plptProjetoFaseExecucao(projId, pj);
  var chk = document.getElementById('baixa-chk-'+idx);
  if(faseExec && chk && !chk.checked){
    progShowToast('⚠ Marque o material para registrar a aplicação.', 'erro');
    return;
  }
  var rawVal = (document.getElementById('baixa-'+tipo+'-'+idx)||{}).value;
  var val = rawVal===''?0:parseFloat(rawVal);
  if(isNaN(val)) val=0;
  if(faseExec && tipo==='executada'){
    var retMap = plptMateriaisRetiradosMap(projId, pj);
    var retQtd = plptMatRetiradoQtd(mat, retMap);
    if(val > 0 && retQtd <= 0){
      var motivo = ((document.getElementById('baixa-motivo-'+idx)||{}).value||'').trim();
      if(!motivo){
        alert('Informe a justificativa: este material não foi retirado pela equipe.');
        return;
      }
      mat._obsAplic = (mat._obsAplic ? mat._obsAplic+' | ' : '') + 'Sem retirada: '+motivo;
    }
    mat._qtdAplic = val;
    if(!DEMO&&mat.id){
      var payload = {qtd_aplicada:val};
      if(mat._obsAplic) payload.observacao = mat._obsAplic;
      sbUpdate('sot_materiais', payload, 'id=eq.'+mat.id);
    }
    progShowToast('✅ Aplicação salva: '+val+' '+(mat.unidade||'UN'));
    _plptRenderProjetoDetalhe(projId);
    return;
  }
  if(tipo==='viabilidade'){
    mat._qtdViab = val;
    if(!DEMO&&mat.id) sbUpdate('sot_materiais',{qtd_viabilizada:val},'id=eq.'+mat.id);
  } else {
    mat._qtdAplic = val;
    if(!DEMO&&mat.id) sbUpdate('sot_materiais',{qtd_aplicada:val},'id=eq.'+mat.id);
  }
  progShowToast('✅ '+( tipo==='viabilidade'?'Viabilidade':'Executada')+' salva: '+val+' '+(mat.unidade||'UN'));
}

function plptAdicSubAba(projId, sub){
  if(_plptDiario.projetoAtivo) _plptDiario.projetoAtivo._adicSub = sub;
  _plptRenderProjetoDetalhe(projId);
}

function plptNovoAdicional(projId, tipo){
  var pj = _plptDiario.projetoAtivo; if(!pj) return;
  var sot = (typeof sot_projetos!=='undefined'?sot_projetos.find(function(x){return x.id===projId;}):null)||{};
  var cid = sot.contrato_id || (usuarioLogado ? usuarioLogado.contrato_id : '');

  function _abrirModal(catalogoMats, catalogoAtivs){
    var catalogo = tipo==='atividade' ? catalogoAtivs : catalogoMats;
    window._adicCatalogo = catalogo;
    window._adicTipo = tipo;
    window._adicCatId = null;
    var titulo = tipo==='atividade' ? '⚡ Nova Atividade Adicional' : '📦 Novo Material Adicional';
    var placeholder = tipo==='atividade' ? 'Buscar por descrição ou código...' : 'Buscar por descrição ou código SAP...';

    var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
      +'<div class="modal" style="max-width:480px">'
      +'<h3 style="margin-bottom:.75rem">'+titulo+'</h3>'
      +'<div style="margin-bottom:.5rem">'
      +'<label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">🔍 Buscar no Almoxarifado SAP'
      +(catalogo.length?' ('+catalogo.length+' itens)':' — carregando...')+'</label>'
      +'<input class="inp" id="adic-busca" style="width:100%" placeholder="'+placeholder+'" oninput="plptAdicFiltrar()"/>'
      +'</div>'
      +'<div id="adic-resultados" style="max-height:180px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px;margin-bottom:.75rem;display:none"></div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.65rem;margin-bottom:.65rem">'
      +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição *</label>'
      +'<input class="inp" id="adic-desc" style="width:100%" placeholder="Descrição do item"/></div>'
      +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Código SAP</label>'
      +'<input class="inp" id="adic-sap" style="width:100%" placeholder="Ex: 1234567"/></div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">'
      +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Qtd *</label>'
      +'<input class="inp" id="adic-qtd" type="number" min="0" style="width:100%" value="1"/></div>'
      +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Unidade</label>'
      +'<input class="inp" id="adic-un" style="width:100%" value="UN"/></div>'
      +'</div></div>'
      +'<div style="margin-bottom:.65rem"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observações / Justificativa</label>'
      +'<textarea class="inp" id="adic-obs" style="width:100%;height:64px;resize:none" placeholder="Ex: Material necessário por divergência no projeto..."></textarea></div>'
      +'<div style="margin-bottom:.75rem"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">📷 Fotos</label>'
      +'<input type="file" id="adic-foto" accept="image/*" multiple style="font-size:12px;width:100%"/></div>'
      +'<div style="display:flex;gap:8px">'
      +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
      +'<button class="btn btn-pri" onclick="plptSalvarAdicional(\''+projId+'\',\''+tipo+'\')" style="flex:2">Salvar adicional</button>'
      +'</div></div></div>';

    setModal(html);
    setTimeout(function(){
      window.plptAdicFiltrar = function(){
        var q=(document.getElementById('adic-busca')||{}).value.trim().toLowerCase();
        var res=document.getElementById('adic-resultados'); if(!res) return;
        var cat=window._adicCatalogo||[];
        var matches = q
          ? cat.filter(function(item){
              var desc=(item.descricao||item.nome||'').toLowerCase();
              var sap=(item.codigo_sap||item.codigo||'').toLowerCase();
              return desc.indexOf(q)>=0 || sap.indexOf(q)>=0;
            })
          : cat; // sem filtro: mostrar todos
        matches = matches.slice(0,30);
        res.style.display = '';
        if(!matches.length){
          res.innerHTML='<div style="padding:8px 12px;font-size:12px;color:#aaa">Nenhum resultado'+(q?' para "'+q+'"':'')+'</div>';
          return;
        }
        res.innerHTML=matches.map(function(item){
          var sap=item.codigo_sap||item.codigo||'';
          var desc=item.descricao||item.nome||'';
          var un=item.unidade||'UN';
          var idx=cat.indexOf(item);
          var saldoLbl = item.saldo != null ? ' · saldo '+item.saldo+' '+un : '';
          return '<div onclick="plptAdicSelecionar('+idx+')" '
            +'style="padding:8px 12px;cursor:pointer;border-bottom:.5px solid #f5f5f3;font-size:12px" '
            +'onmouseover="this.style.background=\'#f9f9f7\'" onmouseout="this.style.background=\'\'">'
            +(sap?'<b style="color:#185FA5">'+sap+'</b> — ':'')
            +desc
            +'<span style="float:right;font-size:10px;color:#888">'+un+saldoLbl+'</span>'
            +'</div>';
        }).join('')
        +(cat.length>30?'<div style="padding:6px 12px;font-size:10px;color:#aaa;text-align:center">Mostrando 30 de '+cat.length+' — refine a busca</div>':'');
      };

      window.plptAdicSelecionar = function(idx){
        var item=(window._adicCatalogo||[])[idx]; if(!item) return;
        var sap=item.codigo_sap||item.codigo||'';
        var desc=item.descricao||item.nome||'';
        var un=item.unidade||'UN';
        var dEl=document.getElementById('adic-desc'); if(dEl) dEl.value=desc;
        var sEl=document.getElementById('adic-sap');  if(sEl) sEl.value=sap;
        var uEl=document.getElementById('adic-un');   if(uEl) uEl.value=un;
        var bEl=document.getElementById('adic-busca');
        if(bEl) bEl.value=(sap?sap+' — ':'')+desc;
        var res=document.getElementById('adic-resultados'); if(res) res.style.display='none';
        window._adicCatId=item.id||null;
      };

      // Mostrar lista imediatamente ao abrir
      var b=document.getElementById('adic-busca');
      if(b){
        b.focus();
        b.onfocus = function(){ plptAdicFiltrar(); };
      }
      plptAdicFiltrar(); // exibir os primeiros 30 ao abrir
    },80);
  }

  // Filtrar materiais do catálogo pelo contrato
  function _filtrarMats(rows){
    return rows.filter(function(m){
      if(m.status==='Inativo') return false;
      if(!cid) return true;
      var cids=[]; try{cids=JSON.parse(m.contratos_ids||'[]');}catch(e){}
      return cids.indexOf('todos')>=0 || cids.indexOf(cid)>=0;
    });
  }
  // Filtrar atividades pelo contrato
  function _filtrarAtivs(rows){
    return rows.filter(function(s){
      if(!cid) return true;
      return !s.contrato_id || s.contrato_id===cid;
    });
  }

  // Merge itens_catalogo into catalogo_materiais for RDSE materials
  if(typeof itens_catalogo!=='undefined' && itens_catalogo.length){
    itens_catalogo.forEach(function(it){
      var cm = typeof catalogo_materiais!=='undefined' ? catalogo_materiais : [];
      if(!cm.find(function(x){ return x.codigo_sap===it.codigo; })){
        cm.push({id:it.id, nome:it.nome||it.descricao||'', descricao:it.nome||it.descricao||'',
          codigo_sap:it.codigo||'', unidade:it.unidade_medida||it.unidade||'UN',
          status:it.ativo===false?'Inativo':'Ativo', contratos_ids:['todos'],
          preco_unitario:it.preco_unitario||0});
      }
    });
  }
  var localAtivs = _filtrarAtivs(typeof servicos!=='undefined' ? servicos : []);

  if(tipo==='material'){
    setModal('<div class="modal-bg"><div class="modal" style="max-width:480px;text-align:center;padding:2rem">'
      +'<div style="color:#888;font-size:13px">⏳ Carregando catálogo Almoxarifado SAP...</div></div></div>');
    sotCarregarCatalogoAlmSAP(cid, function(lista){
      _abrirModal(lista, localAtivs);
    });
    return;
  }

  var needAtivs = localAtivs.length===0 && !DEMO;
  if(needAtivs){
    sbFetch('servicos',{filters:cid?['contrato_id=eq.'+cid]:[]}).then(function(sRows){
      var atCat = sRows && sRows.length ? sRows : [];
      _abrirModal([], atCat);
    }).catch(function(){ _abrirModal([], localAtivs); });
  } else {
    _abrirModal([], localAtivs);
  }
}

// Helper para escapar aspas em atributos inline
function escHtml(str){ return (str||'').replace(/'/g,"\\'").replace(/"/g,'&quot;'); }

function plptSalvarAdicional(projId, tipo){
  var desc=(document.getElementById('adic-desc')||{}).value.trim();
  if(!desc){alert('Informe a descrição.');return;}
  var qtd=parseFloat((document.getElementById('adic-qtd')||{}).value)||0;
  var sap=(document.getElementById('adic-sap')||{}).value.trim();
  var un=(document.getElementById('adic-un')||{}).value.trim()||'UN';
  var obs=(document.getElementById('adic-obs')||{}).value.trim();
  var sel=document.getElementById('adic-cat-sel');
  var catId=(window._adicCatId)||(sel&&sel.value?sel.value:null);

  var fotoInput=document.getElementById('adic-foto');
  var files=fotoInput?Array.from(fotoInput.files):[];

  function finalizarSalvar(fotos){
    var item={
      projeto_id:projId, tipo:tipo, catalog_id:catId,
      descricao:desc, codigo_sap:sap, unidade:un,
      qtd_solicitada:qtd, observacoes:obs,
      fotos:fotos,
      criado_por:(usuarioLogado&&usuarioLogado.nome)||'',
      status:'pendente'
    };
    var pj=_plptDiario.projetoAtivo;
    if(!pj._adicionais) pj._adicionais=[];
    pj._adicionais.push(item);
    if(!DEMO){
      var payload=Object.assign({},item,{fotos:JSON.stringify(fotos)});
      sbInsert('sot_adicionais',payload).then(function(r){
        if(r&&r[0]&&r[0].id) item.id=r[0].id;
      });
    }
    closeModal();
    _plptDiario.projetoAtivo._adicSub=tipo;
    _plptRenderProjetoDetalhe(projId);
    progShowToast('✅ Adicional salvo');
  }

  if(!files.length){finalizarSalvar([]);return;}
  var fotos=[];
  var pending=files.length;
  files.forEach(function(f){
    var r=new FileReader();
    r.onload=function(e){
      fotos.push({nome:f.name,base64:e.target.result.split(',')[1],tipo:f.type});
      if(--pending===0) finalizarSalvar(fotos);
    };
    r.readAsDataURL(f);
  });
}


function plptAprovarAdicional(projId, adicId, catalogId, descricao, qtd, unidade, codigoSap){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.5rem">✅ Aprovar Material Adicional</h3>'
    +'<div style="background:#EAF3DE;border-radius:8px;padding:10px 14px;margin-bottom:.75rem;font-size:12px">'
    +'<div style="font-weight:700;font-size:13px">'+escHtml(descricao)+'</div>'
    +(codigoSap?'<div style="font-size:10px;color:#888;font-family:monospace">'+escHtml(codigoSap)+'</div>':'')
    +'<div style="margin-top:4px">Quantidade solicitada: <strong>'+qtd+' '+escHtml(unidade)+'</strong></div>'
    +'<div style="font-size:11px;color:#555;margin-top:4px">Ao aprovar, este material será adicionado ao saldo do projeto e ficará disponível para reserva pela equipe.</div>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.5rem">'
    +'<label style="font-size:11px;font-weight:600">Qtd aprovada *</label>'
    +'<input class="inp" id="apadv-qtd" type="number" step="0.01" min="0" value="'+qtd+'" style="width:100%"/>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Aprovado por *</label>'
    +'<input class="inp" id="apadv-nome" value="'+(usuarioLogado?escHtml(usuarioLogado.nome||''):'')+'" style="width:100%"/>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="apadv-confirmar" style="flex:2;background:#3B6D11;border-color:#3B6D11">✅ Confirmar Aprovação</button>'
    +'</div></div></div>');

  setTimeout(function(){
    var btn = document.getElementById('apadv-confirmar');
    if(!btn) return;
    btn.onclick = function(){
      var qtdAp = parseFloat((document.getElementById('apadv-qtd')||{}).value||'0')||0;
      var nome  = ((document.getElementById('apadv-nome')||{}).value||'').trim();
      if(!nome){   progShowToast('⚠ Informe quem está aprovando.','erro'); return; }
      if(qtdAp<=0){ progShowToast('⚠ Informe a quantidade aprovada.','erro'); return; }
      closeModal();

      if(DEMO){
        _plptAplicarAprovacaoAdicional(projId, adicId, catalogId, descricao, qtdAp, unidade, codigoSap, nome);
        return;
      }

      // 1. Atualizar sot_adicionais
      sbUpdate('sot_adicionais', {
        status:       'aprovado',
        qtd_aprovada: qtdAp,
        aprovado_por: nome,
        aprovado_em:  new Date().toISOString(),
      }, 'id=eq.'+adicId)
      .then(function(){
        // 2. Verificar se já existe entrada em sot_materiais para este projeto+catálogo
        return sbFetch('sot_materiais', {
          filters: ['projeto_id=eq.'+projId, catalogId ? 'catalog_id=eq.'+catalogId : 'descricao=eq.'+encodeURIComponent(descricao)],
          limit: 1
        });
      })
      .then(function(existing){
        var matRow = existing && existing[0];
        if(matRow){
          // Adicionar ao viabilizado existente
          var novaQtd = (matRow.qtd_viabilizada||0) + qtdAp;
          return sbUpdate('sot_materiais', {qtd_viabilizada: novaQtd}, 'id=eq.'+matRow.id);
        } else {
          // Criar nova entrada em sot_materiais
          return sbInsert('sot_materiais', {
            projeto_id:      projId,
            catalog_id:      catalogId||null,
            descricao:       descricao,
            codigo_sap:      codigoSap||null,
            unidade:         unidade,
            qtd_projetada:   qtdAp,
            qtd_viabilizada: qtdAp,
            adicional:       true,
          });
        }
      })
      .then(function(){
        _plptAplicarAprovacaoAdicional(projId, adicId, catalogId, descricao, qtdAp, unidade, codigoSap, nome);
      })
      .catch(function(e){
        progShowToast('⚠ Erro ao aprovar: '+(e&&e.message||e),'erro');
      });
    };
  },50);
}

function _plptAplicarAprovacaoAdicional(projId, adicId, catalogId, descricao, qtdAp, unidade, codigoSap, nome){
  // Atualizar array local
  var pj = _plptDiario.projetoAtivo;
  if(pj && pj._adicionais){
    var adic = pj._adicionais.find(function(a){return a.id===adicId;});
    if(adic){ adic.status='aprovado'; adic.qtd_aprovada=qtdAp; adic.aprovado_por=nome; }
  }
  // Atualizar sot_materiais_proj local
  if(typeof sot_materiais_proj!=='undefined'){
    var matExist = sot_materiais_proj.find(function(m){
      return m.projeto_id===projId && (m.catalog_id===catalogId || m.descricao===descricao);
    });
    if(matExist){
      matExist.qtd_viabilizada = (matExist.qtd_viabilizada||0) + qtdAp;
    } else {
      sot_materiais_proj.push({
        id: 'adic-'+Date.now(),
        projeto_id:      projId,
        catalog_id:      catalogId||null,
        descricao:       descricao,
        codigo_sap:      codigoSap||null,
        unidade:         unidade,
        qtd_projetada:   qtdAp,
        qtd_viabilizada: qtdAp,
        adicional:       true,
      });
    }
  }
  progShowToast('✅ Adicional aprovado! '+qtdAp+' '+unidade+' adicionados ao saldo do projeto.');
  if(typeof sotLiberarRequisicoesAdicional==='function'){
    sotLiberarRequisicoesAdicional(projId, descricao, codigoSap||'');
  }
  if(typeof sotAtualizarAbaAtual==='function') sotAtualizarAbaAtual(projId);
  _plptRenderProjetoDetalhe(projId);
}


function plptEditarAdicional(projId, idx, tipo){
  var pj=_plptDiario.projetoAtivo; if(!pj) return;
  var lista=(tipo==='atividade'?pj._adicionais.filter(function(a){return a.tipo==='atividade';}):pj._adicionais.filter(function(a){return a.tipo==='material';}));
  var item=lista[idx]; if(!item) return;
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.75rem">✏️ Editar Adicional</h3>'
    +'<div style="margin-bottom:.5rem"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição</label>'
    +'<input class="inp" id="ed-adic-desc" style="width:100%" value="'+(item.descricao||'')+'"/></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-bottom:.5rem">'
    +'<div><label style="font-size:11px">Qtd</label><input class="inp" id="ed-adic-qtd" type="number" style="width:100%" value="'+(item.qtd_solicitada||0)+'"/></div>'
    +'<div><label style="font-size:11px">Unidade</label><input class="inp" id="ed-adic-un" style="width:100%" value="'+(item.unidade||'UN')+'"/></div>'
    +'</div>'
    +'<div style="margin-bottom:.75rem"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observações</label>'
    +'<textarea class="inp" id="ed-adic-obs" style="width:100%;height:60px;resize:none">'+(item.observacoes||'')+'</textarea></div>'
    +'<div class="ma">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn" onclick="plptExcluirAdicional(\''+projId+'\','+idx+',\''+tipo+'\')" style="color:#A32D2D;border-color:#A32D2D">🗑</button>'
    +'<button class="btn btn-pri" onclick="plptAtualizarAdicional(\''+projId+'\','+idx+',\''+tipo+'\')">Salvar</button>'
    +'</div></div></div>');
}

function plptAtualizarAdicional(projId, idx, tipo){
  var pj=_plptDiario.projetoAtivo; if(!pj) return;
  var lista=pj._adicionais.filter(function(a){return a.tipo===tipo;});
  var item=lista[idx]; if(!item) return;
  item.descricao=(document.getElementById('ed-adic-desc')||{}).value.trim()||item.descricao;
  item.qtd_solicitada=parseFloat((document.getElementById('ed-adic-qtd')||{}).value)||0;
  item.unidade=(document.getElementById('ed-adic-un')||{}).value.trim()||'UN';
  item.observacoes=(document.getElementById('ed-adic-obs')||{}).value.trim();
  if(!DEMO&&item.id) sbUpdate('sot_adicionais',{
    descricao:item.descricao,qtd_solicitada:item.qtd_solicitada,
    unidade:item.unidade,observacoes:item.observacoes
  },'id=eq.'+item.id);
  closeModal();
  _plptRenderProjetoDetalhe(projId);
  progShowToast('✅ Adicional atualizado');
}

function plptExcluirAdicional(projId, idx, tipo){
  var pj=_plptDiario.projetoAtivo; if(!pj) return;
  if(!confirm('Remover este adicional?')) return;
  var lista=pj._adicionais.filter(function(a){return a.tipo===tipo;});
  var item=lista[idx];
  if(item&&item.id&&!DEMO) sbFetch('sot_adicionais',{filters:['id=eq.'+item.id]}).then(function(){
    fetch(SB.url+'/rest/v1/sot_adicionais?id=eq.'+item.id,{method:'DELETE',
      headers:{'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)}});
  });
  pj._adicionais=pj._adicionais.filter(function(a,i){
    if(a.tipo!==tipo) return true;
    return lista.indexOf(a)!==idx;
  });
  closeModal();
  _plptRenderProjetoDetalhe(projId);
  progShowToast('Adicional removido');
}

function plptGerarDePara(projId){
  var pj  = _plptDiario.projetoAtivo; if(!pj) return;
  var sot = (typeof sot_projetos!=='undefined'?sot_projetos.find(function(x){return x.id===projId;}):null)||{};
  var mats  = pj._materiais  || [];
  var ativs = pj._atividades || [];
  var adics = pj._adicionais || [];
  var adicMats  = adics.filter(function(a){return a.tipo==='material';});
  var adicAtivs = adics.filter(function(a){return a.tipo==='atividade';});
  var hoje = dataHoje();

  // ── Helpers ─────────────────────────────────────
  function statusCor(st){
    return {saida_total:'#A32D2D',reducao:'#854F0B',mantido:'#3B6D11',adicional:'#185FA5'}[st]||'#555';
  }
  function statusLabel(st){
    return {saida_total:'Saída total',reducao:'Redução',mantido:'Mantido',adicional:'Adicional'}[st]||st;
  }
  function statusBg(st){
    return {saida_total:'#FFF0F0',reducao:'#FFF8EC',mantido:'#F0FAF0',adicional:'#EBF4FD'}[st]||'#fff';
  }

  // ── Processar Materiais ──────────────────────────
  var linhasMats = mats.map(function(m){
    var prev = m.qtd||m.qtd_prevista||0;
    var viab = m._qtdViab!==undefined ? m._qtdViab : (m.qtd_viabilizada||0);
    var st = viab===0&&prev>0 ? 'saida_total' : viab<prev ? 'reducao' : 'mantido';
    return {
      sap:  m.codigo_sap||'—', desc: m.descricao||'—', un: m.unidade||'UN',
      de: prev, para: viab, status: st, obs: ''
    };
  });
  adicMats.forEach(function(a){
    linhasMats.push({
      sap: a.codigo_sap||'—', desc: a.descricao||'—', un: a.unidade||'UN',
      de: 0, para: a.qtd_solicitada||0, status: 'adicional', obs: a.observacoes||''
    });
  });

  // ── Processar Atividades ─────────────────────────
  var linhasAtivs = ativs.map(function(a){
    var prev = a.qtd_prevista||0;
    var viab = a._qtdViab!==undefined ? a._qtdViab : (a.qtd_viabilizada||0);
    var st = viab===0&&prev>0 ? 'saida_total' : viab<prev ? 'reducao' : 'mantido';
    return {
      cod: a.codigo||'—', desc: a.descricao||'—', un: a.unidade||'UN',
      de: prev, para: viab, status: st, obs: ''
    };
  });
  adicAtivs.forEach(function(a){
    linhasAtivs.push({
      cod: a.codigo_sap||'—', desc: a.descricao||'—', un: a.unidade||'UN',
      de: 0, para: a.qtd_solicitada||0, status: 'adicional', obs: a.observacoes||''
    });
  });

  // ── Resumo ───────────────────────────────────────
  function contarStatus(linhas, st){ return linhas.filter(function(l){return l.status===st;}).length; }
  var resMats  = {total:mats.length+adicMats.length,  saidas:contarStatus(linhasMats,'saida_total'),  reduc:contarStatus(linhasMats,'reducao'),  adic:adicMats.length};
  var resAtivs = {total:ativs.length+adicAtivs.length, saidas:contarStatus(linhasAtivs,'saida_total'), reduc:contarStatus(linhasAtivs,'reducao'), adic:adicAtivs.length};

  // ── Builder de tabela ────────────────────────────
  function buildTabela(linhas, colCod, titulo, corTitulo){
    if(!linhas.length) return '<div style="font-size:12px;color:#aaa;text-align:center;padding:.75rem">Nenhum item</div>';
    return '<table style="width:100%;border-collapse:collapse;font-size:11px">'
      +'<thead><tr style="background:#f9f9f7">'
      +'<th style="padding:5px 6px;text-align:left;border-bottom:.5px solid #e0dfd8;color:'+corTitulo+'">'+colCod+'</th>'
      +'<th style="padding:5px 6px;text-align:left;border-bottom:.5px solid #e0dfd8;color:'+corTitulo+'">Descrição</th>'
      +'<th style="padding:5px 6px;text-align:center;border-bottom:.5px solid #e0dfd8;color:#854F0B">DE</th>'
      +'<th style="padding:5px 6px;text-align:center;border-bottom:.5px solid #e0dfd8;color:#3B6D11">PARA</th>'
      +'<th style="padding:5px 6px;text-align:center;border-bottom:.5px solid #e0dfd8;color:'+corTitulo+'">Unid.</th>'
      +'<th style="padding:5px 6px;text-align:center;border-bottom:.5px solid #e0dfd8;color:'+corTitulo+'">Status</th>'
      +'</tr></thead><tbody>'
      +linhas.map(function(l){
        var cor=statusCor(l.status), bg=statusBg(l.status);
        var seta = l.status==='mantido'?'→':l.status==='adicional'?'⬆':l.para<l.de?'⬇':'→';
        return '<tr style="background:'+bg+'">'
          +'<td style="padding:5px 6px;border-bottom:.5px solid #f5f5f3;font-weight:600;color:#185FA5">'+(l.sap||l.cod||'—')+'</td>'
          +'<td style="padding:5px 6px;border-bottom:.5px solid #f5f5f3">'+(l.desc)+(l.obs?'<br><span style="font-size:10px;color:#888;font-style:italic">'+l.obs+'</span>':'')+'</td>'
          +'<td style="padding:5px 6px;border-bottom:.5px solid #f5f5f3;text-align:center;color:#854F0B;font-weight:600">'+(l.de||'—')+'</td>'
          +'<td style="padding:5px 6px;border-bottom:.5px solid #f5f5f3;text-align:center;font-weight:700;color:'+cor+'">'+seta+' '+l.para+'</td>'
          +'<td style="padding:5px 6px;border-bottom:.5px solid #f5f5f3;text-align:center;color:#888">'+l.un+'</td>'
          +'<td style="padding:5px 6px;border-bottom:.5px solid #f5f5f3;text-align:center">'
          +'<span style="background:'+bg+';color:'+cor+';border:.5px solid '+cor+';border-radius:4px;padding:1px 5px;font-size:10px;font-weight:600;white-space:nowrap">'+statusLabel(l.status)+'</span>'
          +'</td></tr>';
      }).join('')
      +'</tbody></table>';
  }

  // ── Texto para copiar ────────────────────────────
  function tabelaTexto(linhas, colCod){
    return linhas.map(function(l){
      var cod=l.sap||l.cod||'—';
      return cod+' | '+l.desc+' | DE: '+l.de+' → PARA: '+l.para+' '+l.un+' | '+statusLabel(l.status)+(l.obs?' | '+l.obs:'');
    }).join('\n');
  }
  var textoSimples =
    '============================================\n'
    +'DE PARA — VIABILIZAÇÃO DE PROJETO\n'
    +'============================================\n'
    +'Projeto : '+(sot.codigo_cliente||sot.codigo||projId)+'\n'
    +(sot.nome?'Descrição: '+sot.nome+'\n':'')
    +(sot.cidade?'Cidade   : '+sot.cidade+'\n':'')
    +'Data    : '+hoje+'\n'
    +'\n--- MATERIAIS ('+linhasMats.length+' itens) ---\n'
    +(linhasMats.length?tabelaTexto(linhasMats,'Cód.SAP'):'Sem materiais')
    +'\n\n--- ATIVIDADES ('+linhasAtivs.length+' itens) ---\n'
    +(linhasAtivs.length?tabelaTexto(linhasAtivs,'Código'):'Sem atividades')
    +'\n============================================\n'
    +'Resumo Materiais : '+resMats.saidas+' saídas, '+resMats.reduc+' reduções, '+resMats.adic+' adicionais\n'
    +'Resumo Atividades: '+resAtivs.saidas+' saídas, '+resAtivs.reduc+' reduções, '+resAtivs.adic+' adicionais\n';

  // ── HTML final ───────────────────────────────────
  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:680px;max-height:92vh;overflow-y:auto;padding:1.25rem">'

    // Cabeçalho
    +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:.75rem">'
    +'<div>'
    +'<h3 style="margin:0 0 2px 0;font-size:15px">📋 De Para — Viabilização</h3>'
    +'<div style="font-size:11px;color:#888">'+(sot.codigo_cliente||sot.codigo||projId)+(sot.nome?' — '+sot.nome:'')+(sot.cidade?' | '+sot.cidade:'')+'</div>'
    +'</div>'
    +'<div style="display:flex;gap:6px;flex-shrink:0">'
    +'<button onclick="plptCopiarDePara()" class="btn btn-sm" style="font-size:11px">📋 Copiar</button>'
    +'<button onclick="window.print()" class="btn btn-sm" style="font-size:11px">🖨 Imprimir</button>'
    +'<button onclick="closeModal()" class="btn btn-sm" style="font-size:11px">✕</button>'
    +'</div></div>'

    // Resumo visual
    +'<div style="display:flex;gap:6px;margin-bottom:1rem;flex-wrap:wrap">'
    +[
      {l:'Mat. Saídas',   v:resMats.saidas,  c:'#A32D2D', bg:'#FFF0F0'},
      {l:'Mat. Reduções', v:resMats.reduc,   c:'#854F0B', bg:'#FFF8EC'},
      {l:'Mat. Adicionais',v:resMats.adic,   c:'#185FA5', bg:'#EBF4FD'},
      {l:'Ativ. Saídas',  v:resAtivs.saidas, c:'#A32D2D', bg:'#FFF0F0'},
      {l:'Ativ. Reduções',v:resAtivs.reduc,  c:'#854F0B', bg:'#FFF8EC'},
      {l:'Ativ. Adicionais',v:resAtivs.adic, c:'#185FA5', bg:'#EBF4FD'},
    ].map(function(r){
      return '<div style="background:'+r.bg+';color:'+r.c+';border:.5px solid '+r.c+';border-radius:6px;padding:3px 8px;font-size:11px;font-weight:600">'
        +r.l+': '+r.v+'</div>';
    }).join('')
    +'</div>'

    // Seção Materiais
    +'<div style="font-size:12px;font-weight:700;color:#854F0B;margin-bottom:.4rem;padding-bottom:.25rem;border-bottom:1.5px solid #854F0B">📦 Materiais</div>'
    +'<div style="margin-bottom:1rem;overflow-x:auto">'
    +buildTabela(linhasMats, 'Cód. SAP', 'Materiais', '#854F0B')
    +'</div>'

    // Seção Atividades
    +(linhasAtivs.length
      ? '<div style="font-size:12px;font-weight:700;color:#185FA5;margin-bottom:.4rem;padding-bottom:.25rem;border-bottom:1.5px solid #185FA5">⚡ Atividades</div>'
        +'<div style="margin-bottom:1rem;overflow-x:auto">'
        +buildTabela(linhasAtivs, 'Código', 'Atividades', '#185FA5')
        +'</div>'
      : ''
    )

    // Legenda
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:10px;color:#888;margin-bottom:.5rem">'
    +'<span>🔴 Saída total = qty viabilizada = 0</span>'
    +'<span>🟠 Redução = qty viabilizada menor que projetada</span>'
    +'<span>🟢 Mantido = mesma qty</span>'
    +'<span>🔵 Adicional = não estava no projeto</span>'
    +'</div>'

    +'<textarea id="depara-txt" style="position:absolute;opacity:0;pointer-events:none;width:1px;height:1px">'+textoSimples+'</textarea>'
    +'</div></div>';

  window._plptDeParaTxt = textoSimples;
  setModal(html);
  setTimeout(function(){
    document.querySelectorAll('.mn-full-btn').forEach(function(btn){
      btn.onclick=function(){
        closeModal();
        var i=parseInt(this.getAttribute('data-mi'));
        if(itensMenu[i]) itensMenu[i].acao();
      };
    });
    // Bind do campo data de retorno
    var inpData=document.getElementById('retorno-data');
    if(inpData){
      var _orig=inpData.getAttribute('data-original')||'';
      inpData.addEventListener('change',function(){ progVerificarMudancaData(this,_orig); });
    }
  },50);
}

function plptCopiarDePara(){
  var el = document.getElementById('depara-txt');
  if(el){ el.select(); document.execCommand('copy'); progShowToast('✅ Copiado! Cole no e-mail.'); }
  else if(window._plptDeParaTxt){
    navigator.clipboard.writeText(window._plptDeParaTxt).then(function(){
      progShowToast('✅ Copiado! Cole no e-mail.');
    });
  }
}

function plptSetAba(projId, aba){
  if(_plptDiario.projetoAtivo) _plptDiario.projetoAtivo._abaAtiva = aba;
  _plptRenderProjetoDetalhe(projId);
}


function plptLancarViabilidadeAtividade(projId, idx){
  var pj = _plptDiario.projetoAtivo; if(!pj||!pj._atividades) return;
  if(plptProjetoFaseExecucao(projId, pj)){
    progShowToast('⚠ Viabilidade já concluída neste projeto — use Execução.', 'erro');
    return;
  }
  var a  = pj._atividades[idx]; if(!a) return;
  var prev = a.qtd_prevista || 0;

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'    +'<div class="modal" style="max-width:380px">'    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'    +'<h3 style="margin:0;font-size:14px">📋 Lançar Viabilidade</h3>'    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#888">✕</button>'    +'</div>'    +'<div style="font-size:12px;font-weight:500;color:#555;margin-bottom:.75rem">'+(a.descricao||a.codigo||'—')+'</div>'    +'<div style="background:#FEF3E2;border-radius:8px;padding:.75rem;margin-bottom:.75rem">'    +'<div style="font-size:11px;font-weight:700;color:#854F0B;margin-bottom:.4rem">📋 Qtd Viabilizada *</div>'    +'<input id="plpt-viab-qtd" type="number" min="0" value="'+prev+'" class="inp" style="width:100%;font-size:16px;text-align:center"/>'    +'<div style="font-size:10px;color:#888;margin-top:4px;text-align:center">Previsto: <b>'+prev+'</b></div>'    +'</div>'    +'<div style="margin-bottom:.75rem">'    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:4px">Observação</label>'    +'<textarea id="plpt-viab-obs" class="inp" rows="2" style="width:100%;resize:none;box-sizing:border-box">'+(a._obsViab||'')+'</textarea>'    +'</div>'    +'<div style="font-size:11px;color:#854F0B;background:#FEF3E2;border-radius:6px;padding:.5rem .75rem;margin-bottom:.75rem">'    +'⚠ A execução só poderá ser lançada na próxima programação após a viabilidade.'    +'</div>'    +'<div style="display:flex;gap:8px">'    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'    +'<button class="btn btn-pri" onclick="plptConfirmarViabilidade(\''+projId+'\','+idx+')" style="flex:1;background:#854F0B;border-color:#854F0B">📋 Salvar Viabilidade</button>'    +'</div>'    +'</div></div>');
}

function plptConfirmarViabilidade(projId, idx){
  var pj = _plptDiario.projetoAtivo; if(!pj||!pj._atividades) return;
  var a  = pj._atividades[idx]; if(!a) return;
  var viab    = parseFloat((document.getElementById('plpt-viab-qtd')||{}).value)||0;
  var obsViab = ((document.getElementById('plpt-viab-obs')||{}).value||'').trim();

  if(isNaN(viab)||viab<0){ alert('Informe uma quantidade válida.'); return; }

  // Update local
  a._qtdViab  = viab;
  a._obsViab  = obsViab;
  a.qtd_viabilizada = viab;

  // Save to DB (only viabilidade fields)
  if(!DEMO && a.id && isUUID(a.id)){
    var vPayload = {qtd_viabilizada:viab};
    if(obsViab) vPayload.obs_viabilidade = obsViab;
    if(obsViab) vPayload.observacoes = (a.observacoes ? a.observacoes+' | ' : '') + 'Viab: '+obsViab;
    sbUpdate('sot_atividades', vPayload, 'id=eq.'+a.id);
  }

  closeModal();
  progShowToast('📋 Viabilidade registrada! Execução disponível na próxima programação.');

  // Re-render the diario to show updated state
  if(typeof renderDiarioPlpt === 'function') renderDiarioPlpt();
}


function plptLancarAtividade(projId, idx){
  var pj = _plptDiario.projetoAtivo; if(!pj||!pj._atividades) return;
  var a  = pj._atividades[idx]; if(!a) return;
  var faseExec = plptProjetoFaseExecucao(projId, pj);
  var viab    = a._qtdViab  !== undefined ? a._qtdViab  : (a.qtd_viabilizada||0);
  var exec    = a._qtdExec  !== undefined ? a._qtdExec  : (a.qtd_executada||0);
  var prev    = a.qtd_prevista || 0;
  if(faseExec && viab <= 0) viab = prev;

  var viabBlock = faseExec ? '' : (
    '<div style="background:#EBF4FD;border-radius:8px;padding:.75rem;margin-bottom:.75rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.5rem">1️⃣ Quantidade Viabilizada</div>'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem">'
    +'<input type="number" id="plpt-viab-qtd" min="0" step="0.01" value="'+viab+'" '
    +'style="flex:1;padding:.5rem;border:.5px solid #185FA5;border-radius:6px;font-size:14px;text-align:center"/>'
    +'<span style="font-size:12px;color:#555">'+(a.unidade||'UN')+'</span>'
    +'</div>'
    +'<textarea id="plpt-viab-obs" placeholder="Observação da viabilização (opcional)..." '
    +'style="width:100%;padding:.4rem;border:.5px solid #ddd;border-radius:6px;font-size:12px;height:50px;resize:none;box-sizing:border-box">'+( a._obsViab||'')+'</textarea>'
    +'</div>'
  );

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:420px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0;font-size:14px">'+(faseExec?'⚡ Executar Atividade':'⚡ Lançar Atividade')+'</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#888">✕</button>'
    +'</div>'
    +'<div style="font-size:13px;font-weight:600;margin-bottom:.25rem">'+(a.descricao||a.codigo||'—')+'</div>'
    +'<div style="font-size:11px;color:#888;margin-bottom:1rem">'+(a.codigo||'')+'  Prev: '+prev+' '+(a.unidade||'UN')+'</div>'
    +(faseExec?'<div style="font-size:11px;color:#3B6D11;background:#EAF3DE;border-radius:6px;padding:.4rem .6rem;margin-bottom:.75rem">Fase de execução — viabilidade já concluída neste projeto.</div>':'')
    +viabBlock
    +'<div style="background:#EAF3DE;border-radius:8px;padding:.75rem;margin-bottom:1rem">'
    +'<div style="font-size:11px;font-weight:700;color:#3B6D11;margin-bottom:.5rem">'+(faseExec?'Quantidade Executada':'2️⃣ Quantidade Executada')+'</div>'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem">'
    +'<input type="number" id="plpt-exec-qtd" min="0" step="0.01" value="'+exec+'" '
    +'style="flex:1;padding:.5rem;border:.5px solid #3B6D11;border-radius:6px;font-size:14px;text-align:center"/>'
    +'<span style="font-size:12px;color:#555">'+(a.unidade||'UN')+'</span>'
    +'</div>'
    +'<textarea id="plpt-exec-obs" placeholder="Observação da execução (opcional)..." '
    +'style="width:100%;padding:.4rem;border:.5px solid #ddd;border-radius:6px;font-size:12px;height:50px;resize:none;box-sizing:border-box">'+( a._obsExec||'')+'</textarea>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="plptConfirmarAtividade(\''+projId+'\','+idx+')" style="flex:1">💾 Salvar</button>'
    +'</div>'
    +'</div></div>');

  if(!faseExec){
    setTimeout(function(){
      var inpViab = document.getElementById('plpt-viab-qtd');
      var inpExec = document.getElementById('plpt-exec-qtd');
      var obsExec = document.getElementById('plpt-exec-obs');
      if(inpExec){ inpExec.disabled=false; inpExec.style.background='#fff'; inpExec.style.borderColor='#3B6D11'; }
      if(obsExec){ obsExec.disabled=false; obsExec.style.background='#fff'; }
      if(inpViab) inpViab.oninput = function(){
        var v = this.value===''?null:parseFloat(this.value);
        if(v===0 && inpExec) inpExec.value='0';
      };
    }, 50);
  }
}

function plptConfirmarAtividade(projId, idx){
  var pj = _plptDiario.projetoAtivo; if(!pj||!pj._atividades) return;
  var a  = pj._atividades[idx]; if(!a) return;
  var faseExec = plptProjetoFaseExecucao(projId, pj);
  var viabEl = document.getElementById('plpt-viab-qtd');
  var viab    = viabEl ? parseFloat(viabEl.value) : (a._qtdViab !== undefined ? a._qtdViab : (a.qtd_viabilizada||0));
  var exec    = parseFloat((document.getElementById('plpt-exec-qtd')||{}).value);
  if(isNaN(viab)) viab = faseExec ? (a.qtd_prevista||0) : 0;
  if(isNaN(exec)) exec = 0;
  var obsViab = viabEl ? ((document.getElementById('plpt-viab-obs')||{}).value||'').trim() : (a._obsViab||'');
  var obsExec = ((document.getElementById('plpt-exec-obs')||{}).value||'').trim();

  if(!faseExec && exec > viab){
    alert('A quantidade executada não pode ser maior que a viabilizada ('+viab+').');
    return;
  }
  if(faseExec && viab <= 0) viab = a.qtd_prevista || viab;

  a._qtdViab  = viab;
  a._qtdExec  = exec;
  a._obsViab  = obsViab;
  a._obsExec  = obsExec;

  if(!DEMO && a.id){
    var payload = Object.assign({qtd_viabilizada: viab, qtd_executada: exec}, sotAtivObsPayload(obsViab, obsExec));
    sbUpdate('sot_atividades', payload, 'id=eq.'+a.id);
  }
  if(_plptDiario.sessao){
    if(!_plptDiario.sessao.eventos) _plptDiario.sessao.eventos=[];
    var hora = new Date().toTimeString().slice(0,5);
    _plptDiario.sessao.eventos.push({hora:hora, desc:'Ativ.: '+(a.descricao||a.codigo)+' V:'+viab+' E:'+exec});
    plptSalvarSessao();
  }
  _plptAtualizarExecucaoParcial(projId);

  closeModal();
  setTimeout(function(){
    progShowToast('✅ Atividade salva — Viab: '+viab+' / Exec: '+exec);
    _plptRenderProjetoDetalhe(projId);
  }, 50);
}

function plptLancarMaterial(projId, idx){
  var pj = _plptDiario.projetoAtivo; if(!pj||!pj._materiais) return;
  var m  = pj._materiais[idx]; if(!m) return;
  var faseExec = plptProjetoFaseExecucao(projId, pj);
  var viab    = m._qtdViab  !== undefined ? m._qtdViab  : (m.qtd_viabilizada||m.qtd||0);
  var aplic   = m._qtdAplic !== undefined ? m._qtdAplic : (m.qtd_aplicada||0);
  var retMap  = plptMateriaisRetiradosMap(projId, pj);
  var retQtd  = plptMatRetiradoQtd(m, retMap);
  if(faseExec && viab <= 0) viab = m.qtd||m.qtd_prevista||0;

  var viabBlock = faseExec ? '' : (
    '<div style="background:#EBF4FD;border-radius:8px;padding:.75rem;margin-bottom:.75rem">'
    +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.5rem">1️⃣ Quantidade Viabilizada</div>'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem">'
    +'<input type="number" id="plpt-mviab-qtd" min="0" step="0.01" value="'+viab+'" '
    +'style="flex:1;padding:.5rem;border:.5px solid #185FA5;border-radius:6px;font-size:14px;text-align:center"/>'
    +'<span style="font-size:12px;color:#555">'+(m.unidade||'UN')+'</span>'
    +'</div>'
    +'<textarea id="plpt-mviab-obs" placeholder="Observação (opcional)..." '
    +'style="width:100%;padding:.4rem;border:.5px solid #ddd;border-radius:6px;font-size:12px;height:50px;resize:none;box-sizing:border-box">'+( m._obsViab||'')+'</textarea>'
    +'</div>'
  );

  var retiradoHint = (faseExec && retQtd > 0)
    ? '<div style="font-size:11px;color:#3B6D11;background:#EAF3DE;border-radius:6px;padding:.4rem .6rem;margin-bottom:.75rem">✓ Material retirado: <b>'+retQtd+'</b> '+(m.unidade||'UN')+'</div>'
    : (faseExec ? '<div style="font-size:11px;color:#854F0B;background:#FEF3E2;border-radius:6px;padding:.4rem .6rem;margin-bottom:.75rem">⚠ Material não consta como retirado — justifique na observação se aplicar.</div>' : '');

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:420px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0;font-size:14px">'+(faseExec?'📦 Aplicar Material':'📦 Lançar Material')+'</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#888">✕</button>'
    +'</div>'
    +'<div style="font-size:13px;font-weight:600;margin-bottom:.25rem">'+(m.descricao||m.codigo_sap||'—')+'</div>'
    +'<div style="font-size:11px;color:#888;margin-bottom:1rem">'+(m.codigo_sap||'')+'  Prev: '+(m.qtd||m.qtd_prevista||0)+' '+(m.unidade||'UN')+'</div>'
    +retiradoHint
    +viabBlock
    +'<div style="background:#EAF3DE;border-radius:8px;padding:.75rem;margin-bottom:1rem">'
    +'<div style="font-size:11px;font-weight:700;color:#3B6D11;margin-bottom:.5rem">'+(faseExec?'Quantidade Aplicada':'2️⃣ Quantidade Aplicada')+'</div>'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem">'
    +'<input type="number" id="plpt-maplic-qtd" min="0" step="0.01" value="'+aplic+'" '
    +'style="flex:1;padding:.5rem;border:.5px solid #3B6D11;border-radius:6px;font-size:14px;text-align:center"/>'
    +'<span style="font-size:12px;color:#555">'+(m.unidade||'UN')+'</span>'
    +'</div>'
    +'<textarea id="plpt-maplic-obs" placeholder="'+(faseExec && retQtd<=0?'Justificativa obrigatória se aplicar sem retirada...':'Observação (opcional)...')+'" '
    +'style="width:100%;padding:.4rem;border:.5px solid #ddd;border-radius:6px;font-size:12px;height:50px;resize:none;box-sizing:border-box">'+( m._obsAplic||'')+'</textarea>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="plptConfirmarMaterial(\''+projId+'\','+idx+')" style="flex:1">💾 Salvar</button>'
    +'</div>'
    +'</div></div>');

  if(!faseExec){
    setTimeout(function(){
      var inpViab = document.getElementById('plpt-mviab-qtd');
      var inpAplic = document.getElementById('plpt-maplic-qtd');
      var obsAplic = document.getElementById('plpt-maplic-obs');
      if(inpAplic){ inpAplic.disabled=false; inpAplic.style.background='#fff'; inpAplic.style.borderColor='#3B6D11'; }
      if(obsAplic){ obsAplic.disabled=false; obsAplic.style.background='#fff'; }
      if(inpViab) inpViab.oninput = function(){
        var v = this.value===''?null:parseFloat(this.value);
        if(v===0 && inpAplic) inpAplic.value='0';
      };
    }, 50);
  }
}

function plptConfirmarMaterial(projId, idx){
  var pj = _plptDiario.projetoAtivo; if(!pj||!pj._materiais) return;
  var m  = pj._materiais[idx]; if(!m) return;
  var faseExec = plptProjetoFaseExecucao(projId, pj);
  var viabEl = document.getElementById('plpt-mviab-qtd');
  var viab    = viabEl ? parseFloat(viabEl.value) : (m._qtdViab !== undefined ? m._qtdViab : (m.qtd_viabilizada||m.qtd||0));
  var aplic   = parseFloat((document.getElementById('plpt-maplic-qtd')||{}).value);
  if(isNaN(viab)) viab = faseExec ? (m.qtd||m.qtd_prevista||0) : 0;
  if(isNaN(aplic)) aplic = 0;
  var obsViab = viabEl ? ((document.getElementById('plpt-mviab-obs')||{}).value||'').trim() : (m._obsViab||'');
  var obsAplic= ((document.getElementById('plpt-maplic-obs')||{}).value||'').trim();

  if(faseExec){
    var retMap = plptMateriaisRetiradosMap(projId, pj);
    var retQtd = plptMatRetiradoQtd(m, retMap);
    if(aplic > 0 && retQtd <= 0 && !obsAplic){
      alert('Informe a justificativa: este material não foi retirado pela equipe.');
      return;
    }
    if(viab <= 0) viab = m.qtd||m.qtd_prevista||0;
  } else if(aplic > viab){
    alert('A quantidade aplicada não pode ser maior que a viabilizada ('+viab+').');
    return;
  }

  m._qtdViab  = viab;
  m._qtdAplic = aplic;
  m._obsViab  = obsViab;
  m._obsAplic = obsAplic;

  if(!DEMO && m.id){
    var payload = Object.assign({qtd_viabilizada: viab, qtd_aplicada: aplic}, sotMatObsPayload(obsViab, obsAplic));
    sbUpdate('sot_materiais', payload, 'id=eq.'+m.id);
  }
  if(_plptDiario.sessao){
    if(!_plptDiario.sessao.eventos) _plptDiario.sessao.eventos=[];
    var hora = new Date().toTimeString().slice(0,5);
    _plptDiario.sessao.eventos.push({hora:hora, desc:'Mat.: '+(m.descricao||m.codigo_sap)+' V:'+viab+' A:'+aplic});
    plptSalvarSessao();
  }

  closeModal();
  setTimeout(function(){
    progShowToast('✅ Material salvo — '+(faseExec?'Aplic: ':'Viab: '+viab+' / Aplic: ')+aplic);
    _plptRenderProjetoDetalhe(projId);
  }, 50);
}

function plptDiarioAvancarEtapa(projId){
  var ETAPAS = ['A caminho','Chegou no local','APR preenchida','Início das atividades','Encerramento das atividades'];
  var pj = _plptDiario.projetoAtivo;
  if(!pj || (pj._pjId||pj.projeto_id) !== projId) return;
  var timeline = pj._timeline||[];
  var etapaAtual = timeline.length ? timeline[timeline.length-1].desc : '';
  var idx = ETAPAS.indexOf(etapaAtual);
  if(idx<0||idx>=ETAPAS.length-1) return;
  var proxima = ETAPAS[idx+1];
  // Guard: não adicionar a mesma etapa duas vezes seguidas (duplo clique)
  if(timeline.length && timeline[timeline.length-1].desc === proxima) return;
  var hora = new Date().toTimeString().slice(0,5);
  pj._timeline.push({hora:hora, desc:proxima});
  if(_plptDiario.sessao && _plptDiario.sessao.eventos)
    _plptDiario.sessao.eventos.push({hora:hora, desc:proxima});
  plptSalvarSessao();
  // Salvar lançamento de etapa
  if(!DEMO && _plptDiario.prog){
    sbInsert('plpt_lancamentos',{
      prog_dia_id:   _plptDiario.prog.id,
      sessao_id:     _plptDiario.sessao ? _plptDiario.sessao.id : null,
      projeto_id:    projId,
      equipe_id:     _dbEquipe ? _dbEquipe.id : null,
      colaborador_id:usuarioLogado ? usuarioLogado.id : null,
      contrato_id:   (usuarioLogado?usuarioLogado.contrato_id:CONTRATOS_UUID_MAP['PLPT']),
      data:          dataHoje(),
      tipo:          'etapa',
      etapa:         proxima,
      descricao:     proxima
    }).catch(function(){});
  }
  progShowToast('✓ '+proxima);
  _plptRenderProjetoDetalhe(projId);
}

function plptDiarioEncerrarOrdem(projId){
  var pj  = _plptDiario.projetos.find(function(p){return p.projeto_id===projId;});
  if(pj) pj.status = 'concluido';

  // ── Ponte PLPT → execucoes_obra ──────────────────────────────────
  // Ao encerrar uma ordem PLPT, cria um registro de execução para
  // aparecer na aba Operacional → Execução
  _plptCriarExecucaoObra(projId);
  // ─────────────────────────────────────────────────────────────────

  _plptDiario.projetoAtivo = null;
  progShowToast('✅ Ordem encerrada');
  renderDiarioPlpt();
}

// Atualiza ou cria registro de execução parcial enquanto o dia está em andamento
function _plptAtualizarExecucaoParcial(projId){
  try {
    var hoje  = dataHoje();
    var eq    = _dbEquipe;
    // Verificar se já existe um registro PLPT para este projeto/data
    var existente = (typeof execucoes!=='undefined')
      ? execucoes.find(function(e){ return e.projeto_id===projId && e.data===hoje && e.origem==='PLPT'; })
      : null;

    if(existente){
      // Atualizar o registro existente com novas atividades
      var sot = (typeof sot_projetos!=='undefined' ? sot_projetos.find(function(x){return x.id===projId;}) : null)||{};
      var atividades = ((_plptDiario.projetoAtivo||{})._atividades||[])
        .filter(function(a){ return (a._qtdExec||0)>0 || (a._qtdViab||0)>0; });
      var descAtiv = atividades.length
        ? atividades.map(function(a){
            return (a.descricao||a.codigo)+(a._qtdViab?' Viab:'+a._qtdViab:'')+(a._qtdExec?' Exec:'+a._qtdExec:'');
          }).join('; ')
        : existente.atividade;
      existente.atividade    = (sot.codigo_cliente||sot.codigo||'Projeto')+' — '+descAtiv.substring(0,120);
      existente.status_exec  = 'Em execução';
      if(!DEMO && !/^plpt\d+$/.test(existente.id)){
        sbUpdate('execucoes_obra',{atividade:existente.atividade,status_exec:'Em execução'},'id=eq.'+existente.id).catch(function(){});
      }
    }
    // Se não existe ainda, não cria — só cria no encerramento
  } catch(e){
    console.warn('_plptAtualizarExecucaoParcial:', e);
  }
}
function _plptCriarExecucaoObra(projId){
  try {
    var sot   = (typeof sot_projetos!=='undefined' ? sot_projetos.find(function(x){return x.id===projId;}) : null)||{};
    var pj    = (_plptDiario.projetos||[]).find(function(p){return p.projeto_id===projId;})||{};
    var sessao= _plptDiario.sessao;
    var eq    = _dbEquipe;

    // Montar resumo das atividades lançadas no dia
    var atividades = ((_plptDiario.projetoAtivo||{})._atividades||[])
      .filter(function(a){ return (a._qtdExec||0) > 0 || (a._qtdViab||0) > 0; });

    var descAtiv = atividades.length
      ? atividades.map(function(a){
          return (a.descricao||a.codigo||'Atividade')
            + (a._qtdViab?' — Viab:'+a._qtdViab:'')
            + (a._qtdExec?' / Exec:'+a._qtdExec:'');
        }).join('; ')
      : 'Execução registrada via Diário de Bordo PLPT';

    // Montar timeline como observação
    var timeline = ((_plptDiario.projetoAtivo||{})._timeline||[]);
    var obsTimeline = timeline.length
      ? timeline.map(function(t){ return t.hora+' '+t.desc; }).join(' → ')
      : '';

    var novo = {
      id:            'plpt'+Date.now(),
      projeto_id:    projId,
      encarregado_id: usuarioLogado ? usuarioLogado.id : '',
      nome_enc:      (eq ? eq.nome : '') + (usuarioLogado ? ' / '+usuarioLogado.nome : ''),
      data:          dataHoje(),
      atividade:     (sot.codigo_cliente||sot.codigo||'Projeto') + ' — ' + descAtiv.substring(0,120),
      status_exec:   pj.status === 'concluido' ? 'Totalmente executado' : 'Parcialmente executado',
      obs:           obsTimeline,
      fotos:         [],
      origem:        'PLPT',  // marca que veio do diário PLPT
      contrato_id:   usuarioLogado ? usuarioLogado.contrato_id : null
    };

    // Adicionar ao array local
    if(typeof execucoes !== 'undefined') execucoes.unshift(novo);

    // Salvar no banco
    if(!DEMO){
      sbInsert('execucoes_obra', {
        projeto_id:    novo.projeto_id,
        encarregado_id:novo.encarregado_id,
        nome_enc:      novo.nome_enc,
        data:          novo.data,
        atividade:     novo.atividade,
        status_exec:   novo.status_exec,
        obs:           novo.obs,
        fotos:         '[]',
        origem:        'PLPT'
      }).catch(function(e){ console.warn('_plptCriarExecucaoObra:', e); });
    }
  } catch(e){
    console.warn('_plptCriarExecucaoObra erro:', e);
  }
}

function plptDiarioAdicionarFoto(projId){
  progShowToast('📷 Funcionalidade de foto em desenvolvimento');
}

function plptDiaroCancelarOrdem(projId){
  if(!confirm('Cancelar esta ordem?')) return;
  var pj = _plptDiario.projetos.find(function(p){return p.projeto_id===projId;});
  if(pj) pj.status = 'cancelado';
  _plptDiario.projetoAtivo = null;
  progShowToast('Ordem cancelada');
  renderDiarioPlpt();
}
// ── FIM DIÁRIO PLPT ────────────────────────────────────────────────

function renderDbComposicao(){
  if(!_dbEquipe)return;
  var hoje=dataHoje();
  var wrap=document.getElementById('db-composicao');if(!wrap)return;
  var badge=document.getElementById('db-comp-status');
  var eqLbl=escHtml(_dbEquipe.codigo||_dbEquipe.nome||'Equipe');
  var comp=_findComposicaoEquipe(_dbEquipe.id, hoje);

  if(!comp){
    if(!DEMO && _dbEquipe && !wrap._buscandoComp){
      wrap._buscandoComp=true;
      sbFetch('composicao_dia',{filters:['equipe_id=eq.'+_dbEquipe.id,'data=eq.'+hoje],limit:1})
        .then(function(rows){
          wrap._buscandoComp=false;
          if(rows&&rows[0]){ _mergeComposicaoDia(rows[0]); renderDbComposicao(); }
        }).catch(function(){ wrap._buscandoComp=false; });
    }
    wrap.innerHTML='<div style="font-size:12px;font-weight:600;color:#333;margin-bottom:6px">'+eqLbl+' · '+fmtD(hoje)+'</div>'
      +'<div style="color:#A32D2D;font-size:12px">⚠ Composição não programada para hoje. Contate a operação.</div>'
      +'<div style="font-size:11px;color:#888;margin-top:6px">A programação do dia precisa ser confirmada em <b>Disponibilidade TMA</b> antes do turno.</div>';
    if(badge){badge.textContent='Não programada';badge.className='bdg danger';}
    var bOk=document.getElementById('btn-db-comp-ok'); if(bOk) bOk.style.display='none';
    var bEr=document.getElementById('btn-db-comp-err'); if(bEr) bEr.style.display='none';
    return;
  }

  var cidsList = parseJsonField(comp.colaborador_ids, []);

  // Montar lista de colaboradores — busca por id, com fallback para usuário logado
  var colsEncontrados = [];

  // 1. Tentar achar cada id no array local de colaboradores
  cidsList.forEach(function(cid){
    var col = colaboradores.find(function(x){ return x.id === cid; });
    if(col){ colsEncontrados.push(col); return; }
    // Fallback: pode ser id local ainda não sincronizado — tentar pelo índice
    // ou mostrar como "Colaborador" genérico para não perder a contagem
    colsEncontrados.push({id:cid, nome:'Colaborador', re:'—', cargo:'—', _fallback:true});
  });

  // 2. Se lista vazia mas há usuário logado, mostrar pelo menos ele
  if(!colsEncontrados.length && usuarioLogado && usuarioLogado.nome){
    colsEncontrados.push({
      id: usuarioLogado.id,
      nome: usuarioLogado.nome,
      re: '—',
      cargo: 'Líder',
      _atual: true
    });
  }

  // 3. Tentar enriquecer fallbacks pelo contrato da equipe
  colsEncontrados = colsEncontrados.map(function(c){
    if(!c._fallback) return c;
    // Tentar achar pelo contrato — se só há 1 colaborador no contrato com esse índice
    var colsContrato = colaboradores.filter(function(x){
      return x.contrato_id === _dbEquipe.contrato_id && x.ativo !== false;
    });
    // Se a quantidade bate, tentar mapear por posição
    if(colsContrato.length === cidsList.length){
      var idx = cidsList.indexOf(c.id);
      if(idx >= 0 && colsContrato[idx]) return colsContrato[idx];
    }
    return c;
  });

  function mkColCard(col, isAtual){
    var bg = isAtual ? '#E6F1FB' : '#f5f5f3';
    var cor = isAtual ? '#185FA5' : '#555';
    return '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:.5px solid #f0efe8">'
      +'<div style="width:34px;height:34px;background:'+bg+';border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:'+cor+';flex-shrink:0">'
      +col.nome.charAt(0).toUpperCase()+'</div>'
      +'<div style="flex:1">'
      +'<div style="font-size:13px;font-weight:500">'+col.nome+(col._atual?' <span style="font-size:10px;color:#185FA5">(você)</span>':'')+'</div>'
      +'<div style="font-size:11px;color:#888">RE: '+(col.re||'—')+' | '+(col.cargo||'—')+'</div>'
      +'</div>'
      +'</div>';
  }

  // Mostrar apenas T1 (índice 0) e T2 (índice 1) no diário — folguista (índice 2) não aparece
  var colsT1T2 = colsEncontrados.slice(0,2).filter(Boolean);
  var cols = colsT1T2.map(function(col, idx){
    var isAtual = usuarioLogado && col.id === usuarioLogado.id;
    var label = idx===0?'T1':'T2';
    var card = mkColCard(col, isAtual);
    // Adicionar label de posição
    return card.replace('<div style="flex:1">', '<div style="font-size:9px;color:#aaa;font-weight:700;letter-spacing:1px;margin-right:6px;flex-shrink:0">'+label+'</div><div style="flex:1">');
  }).join('');

  wrap.innerHTML = '<div style="font-size:12px;font-weight:600;color:#333;margin-bottom:8px">'+eqLbl+' · '+fmtD(hoje)+'</div>'
    +(cols || '<div style="color:#aaa;font-size:12px;padding:.5rem">Nenhum colaborador programado</div>');

  if(comp.confirmada){
    if(badge){badge.textContent='Confirmada';badge.className='bdg ok';}
    document.getElementById('btn-db-comp-ok').style.display='none';
    document.getElementById('btn-db-comp-err').style.display='none';
  } else if(comp.erro_reportado){
    if(badge){badge.textContent='Erro reportado';badge.className='bdg danger';}
    document.getElementById('btn-db-comp-ok').style.display='none';
    document.getElementById('btn-db-comp-err').style.display='none';
  } else {
    if(badge){badge.textContent='Aguardando confirmação';badge.className='bdg warn';}
    // Mostrar botões de confirmação
    document.getElementById('btn-db-comp-ok').style.display='';
    document.getElementById('btn-db-comp-err').style.display='';
  }

  document.getElementById('btn-db-comp-ok').onclick=function(){
    comp.confirmada=true;
    function afterConfirm(){
      almOnComposicaoConfirmada(comp);
      renderDbComposicao();
    }
    if(!DEMO){
      sbUpdate('composicao_dia',{confirmada:true},'id=eq.'+comp.id).then(afterConfirm).catch(afterConfirm);
    } else afterConfirm();
  };
  document.getElementById('btn-db-comp-err').onclick=function(){
    var motivo=prompt('Descreva o problema na composição:');
    if(!motivo)return;
    comp.erro_reportado=true;
    var sol={id:'sc'+Date.now(),equipe_id:_dbEquipe.id,data:hoje,motivo:motivo,status:'Pendente'};
    sol_comp.push(sol);
    if(!DEMO)sbInsert('sol_composicao',_semId(sol));
    if(badge){badge.textContent='Erro reportado';badge.className='bdg danger';}
    alert('Erro reportado para a operação!');
    renderDbComposicao();
  };
}

// ── DISPONIBILIDADE ──────────────────────────────────────────────────────────
function dbLogin(){
  if(!_dbEquipe)return;
  var hoje=dataHoje();
  if(_dbSessao&&_dbSessao.logout_ts){_dbSessao=null;}
  if(_dbSessao&&_dbSessao.login_ts){alert('Você já iniciou o dia!');return;}
  // Abrir modal de abertura de turno com UI dedicada
  dbAbrirModalTurno();
}

function dbAbrirModalTurno(){
  if(!_dbEquipe){
    progShowToast('⚠ Equipe não identificada. Recarregue a página.');
    return;
  }
  _plptModalTurnoAberto = true;
  var hoje = dataHojeLocal();

  // Buscar veículo programado no banco para esta equipe hoje
  function abrirComPlaca(placaProg, modeloProg){
    var veicsEquipe = veiculos.filter(function(v){
      return (v.contratos_ids||[]).indexOf(_dbEquipe.contrato_id)>=0;
    });
    var placaOpts = veicsEquipe.length
      ? veicsEquipe.map(function(v){
          return '<option value="'+v.placa+'"'+(v.placa===placaProg?' selected':'')+'>'+v.placa+' — '+v.modelo+'</option>';
        }).join('')
      : '<option value="">Informe a placa manualmente</option>';

  var ma=document.getElementById('modal-area');
  ma.style.pointerEvents='auto';
  ma.innerHTML='<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin-bottom:.25rem">🔑 Abertura de Turno</h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:1rem">'+(_dbEquipe?_dbEquipe.nome:'')+'  •  '+new Date().toLocaleDateString('pt-BR')+'</div>'
    // Etapa 1: KM e placa
    +'<div id="turno-etapa-1">'
    +'<div class="g2">'
    +'<div class="fg"><label>KM inicial do veículo <span style="color:#A32D2D">*</span></label>'    +'<div style="display:flex;gap:6px;align-items:center">'    +'<input id="db-km-ini" type="number" placeholder="Ex: 12500" style="flex:1;font-size:16px" autofocus/>'    +'<button type="button" id="btn-cam-km-ini" style="background:#185FA5;color:#fff;border:none;border-radius:8px;padding:8px 12px;font-size:18px;cursor:pointer" title="Fotografar odômetro">📷</button>'    +'</div>'    +'<div style="font-size:10px;color:#888;margin-top:2px">📷 = IA lê o odômetro automaticamente</div>'    +'</div>'
    +'<div class="fg"><label>Placa do veículo <span style="color:#A32D2D">*</span></label>'
    +(veicsEquipe.length
      ? '<select id="db-placa" style="width:100%;font-size:14px">'+placaOpts+'</select>'
      : '<input id="db-placa" placeholder="Ex: ABC-1234" value="'+placaProg+'" style="width:100%;text-transform:uppercase" oninput="this.value=this.value.toUpperCase()"/>')
    +'</div></div>'
    +'<div id="db-placa-aviso" style="display:none;background:#FFF3E0;border:.5px solid #EF9F27;border-radius:8px;padding:.6rem .9rem;font-size:12px;color:#854F0B;margin:.5rem 0">⚠️ Esta placa está sendo usada por outra equipe. Verifique antes de continuar.</div>'
    +'<div class="ma" style="margin-top:1rem">'
    +'<button class="btn" id="btn-turno-cancelar">Cancelar</button>'
    +'<button class="btn btn-pri" id="btn-turno-prox">Próximo: EPI →</button>'
    +'</div></div>'
    // Etapa 2: EPI
    +'<div id="turno-etapa-2" style="display:none">'
    +'<div style="font-size:12px;font-weight:600;color:#185FA5;margin-bottom:.5rem">🦺 Checklist de EPI</div>'
    +'<div id="db-epi-conteudo" style="max-height:300px;overflow-y:auto"></div>'
    +'<div class="ma" style="margin-top:1rem">'
    +'<button class="btn" id="btn-turno-volta-epi">← Voltar</button>'
    +'<button class="btn btn-pri" id="btn-turno-prox-epi">Próximo: Veicular →</button>'
    +'</div></div>'
    // Etapa 3: Veicular
    +'<div id="turno-etapa-3" style="display:none">'
    +'<div style="font-size:12px;font-weight:600;color:#185FA5;margin-bottom:.5rem">🚗 Checklist Veicular</div>'
    +'<div id="db-vei-conteudo" style="max-height:300px;overflow-y:auto"></div>'
    +'<div class="ma" style="margin-top:1rem">'
    +'<button class="btn" id="btn-turno-volta-vei">← Voltar</button>'
    +'<button class="btn btn-pri" id="btn-turno-confirmar">✓ Confirmar e iniciar dia</button>'
    +'</div></div>'
    +'</div></div>';

  // ── Renderizar checklist ──────────────────────────────
  // Forçar seleção do veículo programado no select
  if(placaProg){
    var selPlaca = document.getElementById('db-placa');
    if(selPlaca && selPlaca.tagName==='SELECT'){
      // Tentar selecionar pela placa
      var optFound = false;
      for(var oi=0;oi<selPlaca.options.length;oi++){
        if(selPlaca.options[oi].value===placaProg){ selPlaca.selectedIndex=oi; optFound=true; break; }
      }
      // Se não encontrou a placa no select, adicionar como opção no topo
      if(!optFound){
        var novaOpt = document.createElement('option');
        novaOpt.value = placaProg;
        novaOpt.text  = placaProg+(modeloProg?' — '+modeloProg:'');
        novaOpt.selected = true;
        selPlaca.insertBefore(novaOpt, selPlaca.firstChild);
      }
    }
  }

  function renderClEtapa(tipo, containerId){
    var cl=checklists_templates.find(function(c){return c.tipo===tipo;});
    var div=document.getElementById(containerId);
    if(!div)return;
    if(!cl){
      div.innerHTML='<div style="color:#aaa;font-size:12px;padding:1rem;text-align:center">Nenhum checklist de '+tipo+' cadastrado.<br>Configure em ⚙️ Cadastros > Checklists.</div>';
      return;
    }
    div.innerHTML='<div style="font-size:11px;color:#888;margin-bottom:.5rem">'+cl.nome+' • '+cl.itens.length+' itens</div>'
      +cl.itens.map(function(it,i){
        return '<div style="padding:10px 0;border-bottom:.5px solid #f5f5f3">'
          +'<div style="font-size:12px;margin-bottom:6px">'+(i+1)+'. '+it.pergunta
          +(it.obrigatorio?'<span style="color:#A32D2D"> *</span>':'')+'</div>'
          +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:4px">'
          +'<label style="font-size:12px;display:flex;align-items:center;gap:5px;cursor:pointer;padding:4px 8px;border-radius:8px;border:1.5px solid #e0dfd8">'
          +'<input type="radio" name="cl-'+tipo+'-'+i+'" value="C" style="width:15px;height:15px"/> ✅ Conforme</label>'
          +'<label style="font-size:12px;display:flex;align-items:center;gap:5px;cursor:pointer;padding:4px 8px;border-radius:8px;border:1.5px solid #e0dfd8">'
          +'<input type="radio" name="cl-'+tipo+'-'+i+'" value="N" style="width:15px;height:15px"/> ❌ Não conforme</label>'
          +'<label style="font-size:12px;display:flex;align-items:center;gap:5px;cursor:pointer;padding:4px 8px;border-radius:8px;border:1.5px solid #e0dfd8">'
          +'<input type="radio" name="cl-'+tipo+'-'+i+'" value="A" style="width:15px;height:15px"/> — N/A</label>'
          +'</div>'
          +(it.foto_obrigatoria
            ?'<div style="margin-top:4px">'
              +'<input type="file" accept="image/*" capture="environment" id="cl-foto-'+tipo+'-'+i+'" style="display:none"/>'
              +'<button class="btn" id="cl-foto-btn-'+tipo+'-'+i+'" style="font-size:11px;padding:5px 10px;border-color:#854F0B;color:#854F0B" type="button">📷 Tirar foto (obrigatório)</button>'
              +'<span id="cl-foto-ok-'+tipo+'-'+i+'" style="display:none;font-size:11px;color:#3B6D11;margin-left:6px">✓ Foto adicionada</span>'
              +'</div>'
            :'')
          +'</div>';
      }).join('');
    // Vincular botões de foto dos checklists
    cl.itens.forEach(function(it,i){
      if(!it.foto_obrigatoria)return;
      var btn=document.getElementById('cl-foto-btn-'+tipo+'-'+i);
      var inp=document.getElementById('cl-foto-'+tipo+'-'+i);
      var ok=document.getElementById('cl-foto-ok-'+tipo+'-'+i);
      if(btn&&inp){
        btn.onclick=function(){inp.click();};
        inp.onchange=function(e){
          var file=e.target.files[0];
          if(file){
            var r=new FileReader();
            r.onload=function(ev){
              comprimirImagem(ev.target.result,function(c){
                inp._foto=c; // guardar base64 comprimido no input
                if(ok){ok.style.display='inline';}
                if(btn){btn.style.borderColor='#3B6D11';btn.style.color='#3B6D11';btn.textContent='📷 Trocar foto';}
              });
            };
            r.readAsDataURL(file);
          }
        };
      }
    });
  }

  function validarCl(tipo){
    var cl=checklists_templates.find(function(c){return c.tipo===tipo;});
    if(!cl)return true; // sem template = pular
    var pendente=false;
    cl.itens.forEach(function(it,i){
      if(it.obrigatorio&&!document.querySelector('input[name="cl-'+tipo+'-'+i+'"]:checked'))
        pendente=true;
    });
    return !pendente;
  }

  function coletarRespostasCl(tipo){
    var cl=checklists_templates.find(function(c){return c.tipo===tipo;});
    if(!cl)return[];
    return cl.itens.map(function(it,i){
      var r=document.querySelector('input[name="cl-'+tipo+'-'+i+'"]:checked');
      return{item_id:it.id,pergunta:it.pergunta,resposta:r?r.value:''};
    });
  }

  renderClEtapa('EPI','db-epi-conteudo');

  // Scroll para o modal
  setTimeout(function(){
    var modalEl=ma.querySelector('.modal');
    if(modalEl) modalEl.scrollIntoView({behavior:'smooth',block:'start'});
  },100);

  // ── Botões ────────────────────────────────────────────
  function irEtapa(n){
    [1,2,3].forEach(function(x){
      var el=document.getElementById('turno-etapa-'+x);
      if(el)el.style.display=x===n?'block':'none';
    });
  }

  setTimeout(function(){
    var btnCancel=document.getElementById('btn-turno-cancelar');
    if(btnCancel)btnCancel.onclick=function(){ma.innerHTML='';};

    // Etapa 1 → 2
    var btnProx=document.getElementById('btn-turno-prox');
    if(btnProx)btnProx.onclick=function(){
      var km=parseFloat((document.getElementById('db-km-ini')||{}).value)||0;
      var placa=((document.getElementById('db-placa')||{}).value||'').trim().toUpperCase();
      if(!km||!placa){alert('Informe o KM inicial e a placa.');return;}
      // Verificar placa duplicada
      var hoje=dataHoje();
      var placaDup=turnos_abertos.find(function(t){
        return t.placa===placa&&t.data===hoje&&t.equipe_id!==_dbEquipe.id&&t.status==='aberto';
      });
      var aviso=document.getElementById('db-placa-aviso');
      if(placaDup&&aviso){aviso.style.display='block';}
      window._dbKmInicial=km;
      window._dbPlaca=placa;
      renderClEtapa('EPI','db-epi-conteudo');
      irEtapa(2);
    };

    // Etapa 2 → 3
    var btnVoltaEpi=document.getElementById('btn-turno-volta-epi');
    if(btnVoltaEpi)btnVoltaEpi.onclick=function(){irEtapa(1);};

    var btnProxEpi=document.getElementById('btn-turno-prox-epi');
    if(btnProxEpi)btnProxEpi.onclick=function(){
      if(!validarCl('EPI')){alert('Preencha todos os itens obrigatórios do checklist de EPI.');return;}
      window._dbRespostasEpi=coletarRespostasCl('EPI');
      renderClEtapa('Veicular','db-vei-conteudo');
      irEtapa(3);
    };

    // Etapa 3 → confirmar
    var btnVoltaVei=document.getElementById('btn-turno-volta-vei');
    if(btnVoltaVei)btnVoltaVei.onclick=function(){irEtapa(2);};

    var btnConfirmar=document.getElementById('btn-turno-confirmar');
    if(btnConfirmar)btnConfirmar.onclick=function(){
      if(!validarCl('Veicular')){alert('Preencha todos os itens obrigatórios do checklist Veicular.');return;}
      window._dbRespostasVei=coletarRespostasCl('Veicular');
      _plptModalTurnoAberto = false;
      ma.innerHTML='';
      _dbIniciarTurnoConfirmado();
    };
    var btnCancelar=document.getElementById('btn-turno-cancelar');
    if(btnCancelar)btnCancelar.onclick=function(){
      _plptModalTurnoAberto = false;
      ma.innerHTML='';
    };
  },50);
  } // fim abrirComPlaca

  // Buscar veículo programado — banco → memória → frotas vinculadas
  var veicJaEmMemoria = typeof progGetVeiculo==='function' ? progGetVeiculo(_dbEquipe.id, hoje) : null;

  function resolverVeiculo(rows){
    // 1. Banco (prog_veiculos_dia)
    if(rows && rows.length){
      return {placa: rows[0].placa||'', modelo: rows[0].modelo||''};
    }
    // 2. Memória (_progVeiculos)
    if(veicJaEmMemoria && veicJaEmMemoria.placa){
      return veicJaEmMemoria;
    }
    // 3. Frotas vinculadas ao contrato com equipe_id
    var vEq = (frt_veiculos||[]).find(function(v){return v.equipe_id===_dbEquipe.id;})
           || (veiculos||[]).find(function(v){return v.equipe_id===_dbEquipe.id;});
    if(vEq) return {placa: vEq.placa||'', modelo: vEq.modelo||vEq.tipo||''};
    return {placa:'', modelo:''};
  }

  if(!DEMO){
    sbFetch('prog_veiculos_dia',{filters:['equipe_id=eq.'+_dbEquipe.id,'data=eq.'+hoje]})
      .then(function(rows){
        var v = resolverVeiculo(rows);
        abrirComPlaca(v.placa, v.modelo);
      }).catch(function(){
        var v = resolverVeiculo(null);
        abrirComPlaca(v.placa, v.modelo);
      });
  } else {
    abrirComPlaca('','');
  }
} // fim dbAbrirModalTurno

function _dbIniciarTurnoConfirmado(){
  if(!_dbEquipe)return;
  var hoje=dataHoje();
  var epiOk=window._dbRespostasEpi?!window._dbRespostasEpi.some(function(r){return r.resposta==='N';}):true;
  var veiOk=window._dbRespostasVei?!window._dbRespostasVei.some(function(r){return r.resposta==='N';}):true;

  if(!epiOk||!veiOk){
    var msg='Foram encontrados itens NAO CONFORMES:';
    if(!epiOk)msg+='\n- EPI com irregularidades';
    if(!veiOk)msg+='\n- Veiculo com irregularidades';
    msg+='\n\nDeseja iniciar o turno mesmo assim?';
    if(!confirm(msg))return;
  }

  _dbSessao={id:'sess'+Date.now(),equipe_id:_dbEquipe.id,data:hoje,
    login_ts:Date.now(),almoco_ts:null,retorno_ts:null,logout_ts:null,
    minutos_faturados:0,eventos:[],
    km_inicial:window._dbKmInicial||0,
    placa:window._dbPlaca||'',veiculo_slot:dbGetVeiculoSlot()};
  var _veicTurno=dbResolverVeiculoDiario();
  if(_veicTurno){
    if(_veicTurno.veiculo_id) _dbSessao.veiculo_id=_veicTurno.veiculo_id;
    if(!_dbSessao.placa&&_veicTurno.placa) _dbSessao.placa=_veicTurno.placa;
  }
  _dbSessao.eventos.push({tipo:'Início do dia',ts:Date.now(),
    obs:'KM: '+(window._dbKmInicial||0)+' | Placa: '+(window._dbPlaca||'')});

  // Registrar turno
  var turnoExist=turnos_abertos.find(function(t){return t.equipe_id===_dbEquipe.id&&t.data===hoje;});
  if(turnoExist){
    turnoExist.km_inicial=window._dbKmInicial||0;
    turnoExist.placa=window._dbPlaca||'';
    turnoExist.checklist_epi_ok=epiOk;
    turnoExist.checklist_vei_ok=veiOk;
    turnoExist.status='aberto';
  } else {
    var novoTurno={id:'t'+Date.now(),equipe_id:_dbEquipe.id,data:hoje,
      km_inicial:window._dbKmInicial||0,placa:window._dbPlaca||'',
      checklist_epi_ok:epiOk,checklist_vei_ok:veiOk,
      respostas_epi:window._dbRespostasEpi||[],
      respostas_vei:window._dbRespostasVei||[],
      status:'aberto'};
    turnos_abertos.push(novoTurno);
    if(!DEMO && !(_dbEquipe && _dbEquipe._plpt)){
      // turnos_abertos é só para TMA (equipes_disp); PLPT usa plpt_sessoes_dia
      sbInsert('turnos_abertos',{
        equipe_id:novoTurno.equipe_id,
        data:novoTurno.data,
        km_inicial:novoTurno.km_inicial,
        placa:novoTurno.placa,
        checklist_epi_ok:novoTurno.checklist_epi_ok,
        checklist_vei_ok:novoTurno.checklist_vei_ok,
        respostas_epi:JSON.stringify(novoTurno.respostas_epi),
        respostas_vei:JSON.stringify(novoTurno.respostas_vei),
        status:'aberto'
      }).then(function(res){
        if(res&&res[0]&&res[0].id){
          novoTurno.id=res[0].id;
        }
      }).catch(function(e){console.error('Erro ao salvar turno:',e);});
    }
  }

  sessoes_disp.push(_dbSessao);
  if(!DEMO && !(_dbEquipe&&_dbEquipe._plpt)){
    var payloadSessao = {
      equipe_id:         _dbSessao.equipe_id,
      data:              _dbSessao.data,
      login_ts:          _dbSessao.login_ts,
      almoco_ts:         null,
      retorno_ts:        null,
      logout_ts:         null,
      km_inicial:        _dbSessao.km_inicial||0,
      placa:             _dbSessao.placa||'',
      minutos_faturados: 0,
      eventos:           JSON.stringify(_dbSessao.eventos||[])
    };
    sbInsert('sessoes_disponibilidade', payloadSessao).then(function(res){
      if(res&&res[0]&&res[0].id){
        _dbSessao.id=res[0].id;
        var local=sessoes_disp.find(function(x){return x.equipe_id===_dbSessao.equipe_id&&x.data===_dbSessao.data;});
        if(local) local.id=res[0].id;
        // Salvar qualquer atualização que aconteceu antes do UUID chegar
        if(_dbSessao._pendingSave){
          dbSalvarSessao();
          delete _dbSessao._pendingSave;
        }
      }
    }).catch(function(e){console.error('Erro ao salvar sessão:',e);});
  } // fim do bloco TMA insert

  // Para TMA (Disponibilidade) e equipes de projeto diferentes do fluxo PLPT
  var contTurno = contratos.find(function(c){return c.id===(usuarioLogado?usuarioLogado.contrato_id:'');});
  var isDisponibilidade = contTurno && contTurno.modalidade_trabalho==='Disponibilidade';
  // Garantia extra: equipes em equipes_disp são SEMPRE TMA
  var _turnoIsTMA = equipes_disp.some(function(e){ return _dbEquipe && e.id === _dbEquipe.id; });
  if(_turnoIsTMA) { if(_dbEquipe) _dbEquipe._plpt = false; }

  if(isDisponibilidade || _turnoIsTMA || !(_dbEquipe&&_dbEquipe._plpt)){
    // Fluxo estático — atualiza botões na página existente
    dbAtualizarBotoes();
    var bl=document.getElementById('btn-db-login');
    if(bl){bl.textContent='▶ Iniciar dia';bl.style.background='';}
    dbIniciarTimer();
    renderDbComposicao();
    renderDbOrdemAtual();
    renderDbOrdensDia();
    renderDbHistoricoSessao();
    var sl=document.getElementById('db-status-label');if(sl)sl.textContent='Disponível';
    return;
  }

  // Fluxo PLPT (projetos não-Disponibilidade)
  var loginTs = _dbSessao.login_ts;
  _plptDiario.sessao = {
    id:        null,       // será preenchido após insert
    login_ts:  loginTs,
    inicio_ts: new Date(loginTs).toISOString(),
    fim_ts:    null,
    logout_ts: null,
    almoco_ts: null,
    retorno_ts: null,
    eventos:   _dbSessao.eventos||[],
    placa:     _dbSessao.placa||'',
    km_inicial: _dbSessao.km_inicial||0
  };
  _plptDiario.composConfirm = true;
  _plptModalTurnoAberto = false;

  // Inserir sessão PLPT no banco — verificar se já existe uma hoje
  if(!DEMO){
    // Verificar se já há sessão ativa hoje para esta equipe
    sbFetch('plpt_sessoes',{
      filters:['equipe_id=eq.'+_dbEquipe.id,'data=eq.'+dataHojeLocal()],
      order:'login_ts.desc'
    }).then(function(existentes){
      // Procurar sessão ativa com dados úteis
      var sessExistente = null; var melhorSc = -1;
      (existentes||[]).forEach(function(s){
        if(s.logout_ts && s.logout_ts !== 0) return;
        var evs = parseJsonField(s.eventos,[]);
        var sc = evs.length + (evs.some(function(e){return e.tipo==='_PROJ_STATE';}) ? 100 : 0);
        if(sc > melhorSc){ melhorSc=sc; sessExistente=s; }
      });

      if(sessExistente && melhorSc > 0){
        // Restaurar estado da sessão existente em vez de sobrescrever
        console.log('[PLPT] reutilizando sessão existente', sessExistente.id, 'score:', melhorSc);
        var evExist = parseJsonField(sessExistente.eventos, []);
        var projStateExist = evExist.find(function(e){ return e.tipo==='_PROJ_STATE'; });

        // Usar o mesmo ID da sessão existente
        _plptDiario.sessao.id = sessExistente.id;
        _dbSessao.id          = sessExistente.id;

        // Preservar eventos históricos existentes (mesclar com novo Início do dia)
        var evNovos = _plptDiario.sessao.eventos || [];
        var evHistorico = evExist.filter(function(e){ return e.tipo !== '_PROJ_STATE'; });
        // Adicionar eventos do dia atual que não existem no histórico
        evNovos.forEach(function(ev){
          if(!evHistorico.find(function(h){ return h.ts===ev.ts&&h.tipo===ev.tipo; })){
            evHistorico.push(ev);
          }
        });
        _plptDiario.sessao.eventos = evHistorico;

        // Restaurar projeto ativo se tinha _PROJ_STATE
        if(projStateExist && projStateExist.projId && !_plptDiario.projetoAtivo){
          var pjEx = {projeto_id: projStateExist.projId, _pjId: projStateExist.projId, _timeline: projStateExist.timeline||[]};
          if(!_plptDiario.projetos.find(function(p){ return p._pjId===pjEx._pjId; })) _plptDiario.projetos.push(pjEx);
          _plptDiario.projetoAtivo = pjEx;
        }

        plptSalvarSessao();
        return;
      }

      var payloadSessaoPLPT = {
        equipe_id:         _dbEquipe.id,
        data:              dataHojeLocal(),
        login_ts:          loginTs,
        almoco_ts:         null,
        retorno_ts:        null,
        logout_ts:         null,
        km_inicial:        _dbSessao.km_inicial||0,
        placa:             _dbSessao.placa||'',
        minutos_faturados: 0,
        eventos:           JSON.stringify(_plptDiario.sessao.eventos)
      };
      console.log('[PLPT] insert sessão iniciado', payloadSessaoPLPT);
      sbInsert('plpt_sessoes', payloadSessaoPLPT).then(function(res){
        console.log('[PLPT] insert sessão retorno', res);
        if(res&&res[0]&&res[0].id){
          var uuid = res[0].id;
          _plptDiario.sessao.id = uuid;
          _dbSessao.id          = uuid;
          console.log('[PLPT] id válido?', isUUID(_plptDiario.sessao.id));
          if(_plptDiario.sessao._pendingSave) delete _plptDiario.sessao._pendingSave;
          plptSalvarSessao();
        } else {
          progShowToast('⚠ Sessão não foi salva no banco. Verifique a conexão.');
          console.warn('[PLPT] insert sessão falhou', res);
        }
      }).catch(function(e){ console.error('Erro ao salvar sessão PLPT:', e); });
    });
  }

  renderDiarioPlpt();
}

// ── Salvar estado atual da sessão TMA no banco ──────────────────────────
function dbSalvarSessao(){
  if(DEMO || !_dbSessao) return;
  if(_dbEquipe && _dbEquipe._plpt) return;
  if(!isUUID(_dbSessao.id)){
    _dbSessao._pendingSave = true;
    return;
  }
  var payload = {
    eventos: JSON.stringify(_dbSessao.eventos||[]),
    minutos_faturados: _dbSessao.minutos_faturados||0
  };
  if(_dbSessao.almoco_ts)  payload.almoco_ts  = _dbSessao.almoco_ts;
  if(_dbSessao.retorno_ts) payload.retorno_ts = _dbSessao.retorno_ts;
  if(_dbSessao.logout_ts)  payload.logout_ts  = _dbSessao.logout_ts;
  if(_dbSessao.km_final!=null) payload.km_final = _dbSessao.km_final;
  sbUpdate('sessoes_disponibilidade', payload, 'id=eq.'+_dbSessao.id);
}

function dbAlmoco(){
  if(!_dbSessao){
    progShowToast('⚠ Nenhuma sessão ativa. Inicie o turno primeiro.');
    return;
  }
  if(_dbSessao.almoco_ts){
    progShowToast('⚠ Almoço já registrado nesta sessão.');
    return;
  }
  if(_dbOrdemAtual && ['em_andamento','no_local','a_caminho','encerrando'].indexOf(_dbOrdemAtual.status)>=0){
    if(!confirm('Existe uma OS em andamento. Deseja ir para o almoço mesmo assim?')) return;
  }
  _dbSessao.almoco_ts = Date.now();
  if(!_dbSessao.eventos) _dbSessao.eventos = [];
  _dbSessao.eventos.push({tipo:'Início do almoço', ts:_dbSessao.almoco_ts});
  dbSalvarSessao();
  if(typeof _dbTimer !== 'undefined') clearInterval(_dbTimer);
  dbAtualizarBotoes();
  var sl = document.getElementById('db-status-label'); if(sl) sl.textContent = 'Almoço';
  renderDbHistoricoSessao();
  // Timer regressivo de 55 min
  var elTimer = document.getElementById('db-almoco-timer');
  if(elTimer) elTimer.style.display = '';
  var fim = _dbSessao.almoco_ts + 55*60*1000;
  if(typeof _dbAlmocoTimer !== 'undefined') clearInterval(_dbAlmocoTimer);
  _dbAlmocoTimer = setInterval(function(){
    var restante = fim - Date.now();
    var el = document.getElementById('db-almoco-timer');
    if(restante <= 0){
      clearInterval(_dbAlmocoTimer);
      if(el){el.textContent = '🍽 Almoço encerrado — clique em Retomar'; el.style.background = '#A32D2D';}
      return;
    }
    var m = Math.floor(restante/60000); var s = Math.floor((restante%60000)/1000);
    if(el) el.textContent = '🍽 Almoço — '+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+' restantes';
  }, 1000);
  progShowToast('🍽 Almoço registrado');
}

function dbRetomar(){
  if(!_dbSessao)return;
  _dbSessao.retorno_ts=Date.now();
  if(!_dbSessao.eventos)_dbSessao.eventos=[];
  var durMin=Math.round((_dbSessao.retorno_ts-_dbSessao.almoco_ts)/60000);
  _dbSessao.eventos.push({tipo:'Retorno do almoço',ts:_dbSessao.retorno_ts,obs:durMin+' min de almoço'});
  dbSalvarSessao();
  clearInterval(_dbAlmocoTimer);
  // Esconder timer de almoço
  var elAT=document.getElementById('db-almoco-timer');
  if(elAT){elAT.style.display='none';elAT.textContent='';elAT.style.background='#854F0B';}
  dbAtualizarBotoes();
  // Restaurar texto do botão login
  var bl=document.getElementById('btn-db-login');
  if(bl){bl.textContent='▶ Iniciar dia';bl.style.background='';}
  dbIniciarTimer();
  renderDbHistoricoSessao();
  var sl=document.getElementById('db-status-label');if(sl)sl.textContent='Disponível';
  renderDbHistoricoSessao();
}

function dbLogout(){
  if(!_dbSessao) return;
  if(_dbSessao.logout_ts){ progShowToast('ℹ Dia já encerrado'); return; }
  if(_dbOrdemAtual&&_dbOrdemAtual.status==='em_andamento'){
    alert('Encerre a ordem atual antes de encerrar o dia.'); return;
  }
  if(dbVeiculoKitChegadaPendente()&&!window._dbLogoutIgnorarChegada){
    setModal('<div class="modal-bg"><div class="modal" style="max-width:400px">'
      +'<h3 style="margin-bottom:.5rem;color:#854F0B">⚠ Checklist de chegada pendente</h3>'
      +'<p style="font-size:12px;color:#555;margin-bottom:1rem">Antes de encerrar o dia, declare os materiais restantes no veículo (foto + comparação de saldo).</p>'
      +'<button type="button" class="btn" id="btn-chk-chegada-logout" style="width:100%;margin-bottom:8px;background:#3B6D11;color:#fff">🏁 Preencher checklist chegada</button>'
      +'<button type="button" class="btn" id="btn-logout-sem-chegada" style="width:100%;margin-bottom:8px;border-color:#854F0B;color:#854F0B">Encerrar sem checklist</button>'
      +'<button type="button" class="btn" onclick="closeModal()" style="width:100%">Cancelar</button>'
      +'</div></div>');
    setTimeout(function(){
      var b1=document.getElementById('btn-chk-chegada-logout');
      var b2=document.getElementById('btn-logout-sem-chegada');
      if(b1) b1.onclick=function(){
        closeModal();
        dbAbrirChecklistChegadaVeiculo({onComplete:function(){
          window._dbLogoutIgnorarChegada=true;
          dbLogout();
        }});
      };
      if(b2) b2.onclick=function(){
        closeModal();
        window._dbLogoutIgnorarChegada=true;
        dbLogout();
      };
    },50);
    return;
  }
  window._dbLogoutIgnorarChegada=false;

  var minFat=Math.floor(dbCalcMinFaturados()/60000);
  var hFat=Math.floor(minFat/60);
  var mFat=minFat%60;
  var kmIni=_dbSessao.km_inicial||0;
  var placa=_dbSessao.placa||'—';

  // ── Usar painel inline (não modal fixed) para evitar problema
  // com teclado virtual no celular que empurra o conteúdo
  var pgDiario=document.getElementById('pg-diario');
  if(!pgDiario)return;

  // Criar painel de encerramento acima do conteúdo do diário
  var existente=document.getElementById('db-encerramento-panel');
  if(existente)existente.remove();

  var panel=document.createElement('div');
  panel.id='db-encerramento-panel';
  panel.style.cssText='position:relative;z-index:100;background:#fff;border:2px solid #A32D2D;border-radius:14px;padding:1.25rem;margin-bottom:1rem;box-shadow:0 4px 20px rgba(163,45,45,.15)';
  panel.innerHTML=
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem">'
    +'<h3 style="margin:0;font-size:15px;color:#A32D2D">■ Encerrar o dia</h3>'
    +'<button id="btn-cancel-logout" style="background:none;border:none;font-size:20px;cursor:pointer;color:#888;padding:4px">✕</button>'
    +'</div>'
    // Resumo
    +'<div style="background:#f9f9f7;border-radius:10px;padding:.85rem;margin-bottom:1rem;display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    +'<div><div style="font-size:11px;color:#888">Horas faturáveis</div>'
    +'<div style="font-size:20px;font-weight:700;color:#185FA5">'+String(hFat).padStart(2,'0')+':'+String(mFat).padStart(2,'0')+'</div></div>'
    +'<div><div style="font-size:11px;color:#888">Placa / KM inicial</div>'
    +'<div style="font-size:13px;font-weight:600">'+placa+' / '+kmIni+'</div></div>'
    +'</div>'
    // KM final
    +'<div style="margin-bottom:.75rem">'
    +'<label style="font-size:12px;color:#888;display:block;margin-bottom:5px">KM final do veículo <span style="color:#A32D2D">*</span></label>'
    +'<div style="display:flex;gap:6px;align-items:center">'    +'<input id="db-km-fim" type="number" inputmode="numeric" pattern="[0-9]*" placeholder="Ex: 12650"'    +' style="flex:1;font-size:18px;padding:12px;border:1.5px solid #e0dfd8;border-radius:10px;background:#fff"/>'    +'<button type="button" id="btn-cam-km-fim" style="background:#3B6D11;color:#fff;border:none;border-radius:10px;padding:14px 16px;font-size:20px;cursor:pointer" title="Fotografar odômetro">📷</button>'    +'</div>'    +'<div style="font-size:10px;color:#888;margin-top:2px">📷 = IA lê o odômetro automaticamente</div>'
    +' style="width:100%;font-size:18px;padding:12px;border:1.5px solid #e0dfd8;border-radius:10px;background:#fff;-webkit-appearance:none;appearance:none;box-sizing:border-box"/>'
    +'<div id="db-km-aviso" style="display:none;font-size:11px;color:#A32D2D;margin-top:4px">KM final deve ser maior que '+kmIni+'</div>'
    +'</div>'
    // Observação
    +'<div style="margin-bottom:1rem">'
    +'<label style="font-size:12px;color:#888;display:block;margin-bottom:5px">Observação (opcional)</label>'
    +'<textarea id="db-obs-fim" placeholder="Ocorrências do dia..." rows="3"'
    +' style="width:100%;font-size:14px;padding:10px;border:1.5px solid #e0dfd8;border-radius:10px;background:#fff;resize:none;box-sizing:border-box"></textarea>'
    +'</div>'
    // Botão confirmar
    +'<button id="btn-confirm-logout" style="width:100%;padding:14px;background:#A32D2D;color:#fff;border:none;border-radius:12px;font-size:15px;font-weight:600;cursor:pointer">■ Confirmar encerramento</button>';

  // Inserir no topo do pg-diario
  pgDiario.insertBefore(panel, pgDiario.firstChild);

  // Scroll para o topo para mostrar o painel
  pgDiario.scrollIntoView({behavior:'smooth', block:'start'});
  window.scrollTo({top:0, behavior:'smooth'});

  // Focar no campo KM após um instante
  setTimeout(function(){
    var inp=document.getElementById('db-km-fim');
    if(inp){
      inp.focus();
      inp.scrollIntoView({behavior:'smooth', block:'center'});
    }
    var btnCF=document.getElementById('btn-cam-km-fim');
    if(btnCF)btnCF.onclick=function(){dbAbrirCameraOdometro('db-km-fim','KM final');};
  }, 300);

  // Eventos
  document.getElementById('btn-cancel-logout').onclick=function(){
    panel.remove();
  };

  document.getElementById('btn-confirm-logout').onclick=function(){
    var kmFim=parseFloat((document.getElementById('db-km-fim')||{}).value)||0;
    var aviso=document.getElementById('db-km-aviso');
    if(!kmFim){
      var inp=document.getElementById('db-km-fim');
      if(inp){inp.style.borderColor='#A32D2D';inp.focus();}
      return;
    }
    if(kmFim<=kmIni){
      if(aviso)aviso.style.display='block';
      var inp=document.getElementById('db-km-fim');
      if(inp){inp.style.borderColor='#A32D2D';inp.focus();}
      return;
    }
    var obs=(document.getElementById('db-obs-fim')||{}).value||'';
    panel.remove();
    _dbEncerrarTurnoConfirmado(kmFim, obs);
  };
}

function _dbEncerrarTurnoConfirmado(kmFim, obs){
  if(_dbSessao.logout_ts){ return; } // já encerrado — ignorar duplicata
  _dbSessao.logout_ts=Date.now();
  _dbSessao.km_final=kmFim;
  _dbSessao.minutos_faturados=Math.floor(dbCalcMinFaturados()/60000);
  if(!_dbSessao.eventos)_dbSessao.eventos=[];
  _dbSessao.eventos.push({tipo:'Encerramento do dia',ts:_dbSessao.logout_ts,
    obs:_dbSessao.minutos_faturados+' min faturados | KM final: '+kmFim+(obs?' | '+obs:'')});
  clearInterval(_dbTimer);

  // Atualizar registro do turno
  var turno=turnos_abertos.find(function(t){
    return t.equipe_id===_dbEquipe.id&&t.data===dataHojeLocal();
  });
  if(turno){turno.km_final=kmFim;turno.status='encerrado';}

  dbSalvarSessao();

  dbAtualizarBotoes();
  var sl=document.getElementById('db-status-label');if(sl)sl.textContent='Dia encerrado';
  renderDbHistoricoSessao();
  var ht=document.getElementById('db-timer');if(ht)ht.style.color='#888';

  // Resumo do dia
  var hFat=Math.floor(_dbSessao.minutos_faturados/60);
  var mFat=_dbSessao.minutos_faturados%60;
  var kmRod=kmFim-(_dbSessao.km_inicial||0);
  var nOrdens=ordens_db.filter(function(o){
    return o.equipe_id===(_dbEquipe?_dbEquipe.id:'')&&o.data===dataHojeLocal();
  }).length;
  setTimeout(function(){
    alert('Dia encerrado!'
      +' Horas: '+String(hFat).padStart(2,'0')+':'+String(mFat).padStart(2,'0')
      +' | KM rodado: '+kmRod+' km'
      +' | Ordens: '+nOrdens);
  },100);
}

function dbReabrirTurno(){
  if(!_dbSessao) return;
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:360px">'
    +'<h3 style="margin-bottom:.75rem;color:#854F0B">↩ Reabrir turno</h3>'
    +'<p style="font-size:13px;color:#555;margin-bottom:1rem">O turno foi encerrado às '
    +fmtHHMM(_dbSessao.logout_ts)+'. Deseja reabrir e continuar?</p>'
    +'<div class="ma">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn" onclick="dbConfirmarReabrir()" style="color:#854F0B;border-color:#854F0B">↩ Reabrir</button>'
    +'</div></div></div>');
}

function dbConfirmarReabrir(){
  if(!_dbSessao) return;
  delete _dbSessao.logout_ts;
  delete _dbSessao.km_final;
  // Remover evento de encerramento da lista
  if(_dbSessao.eventos){
    _dbSessao.eventos = _dbSessao.eventos.filter(function(e){
      return e.tipo !== 'Encerramento do dia';
    });
  }
  if(!DEMO&&isUUID(_dbSessao.id)) sbUpdate('sessoes_disponibilidade',{
    logout_ts: null, km_final: null,
    eventos: JSON.stringify(_dbSessao.eventos||[])
  },'id=eq.'+_dbSessao.id);
  // Esconder botão reabrir
  var btnRe=document.getElementById('btn-db-reabrir');if(btnRe)btnRe.style.display='none';
  // Reativar timer
  dbIniciarTimer();
  closeModal();
  dbAtualizarBotoes();
  var sl=document.getElementById('db-status-label');
  if(sl) sl.textContent='Turno em andamento';
  progShowToast('✅ Turno reaberto com sucesso');
}

function fmtHHMM(ts){
  if(!ts) return '—';
  var d=new Date(typeof ts==='number'?ts:ts);
  return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
}

function dbCalcMinFaturados(){
  if(!_dbSessao||!_dbSessao.login_ts)return 0;
  var agora=_dbSessao.logout_ts||Date.now();
  var total=agora-_dbSessao.login_ts;
  // Descontar almoço
  if(_dbSessao.almoco_ts){
    var fimAlmoco=_dbSessao.retorno_ts||Math.min(_dbSessao.almoco_ts+55*60*1000,agora);
    total-=(fimAlmoco-_dbSessao.almoco_ts);
  }
  return Math.max(0,total);
}

function dbIniciarTimer(){
  // Mostrar elementos de timer
  var elTimer=document.getElementById('db-timer');
  var elHoras=document.getElementById('db-horas-disp');
  if(elTimer)elTimer.style.display='';
  if(elHoras)elHoras.style.display='';
  clearInterval(_dbTimer);
  _dbTimer=setInterval(function(){
    var ms=dbCalcMinFaturados();
    var el=document.getElementById('db-horas-disp');if(el)el.textContent=msToHHMM(ms);
    var timer=document.getElementById('db-timer');if(timer)timer.textContent=msToHHMM(ms);
    // Alerta e auto-encerramento após 13h
    if(_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts){
      var horasAtivo=(Date.now()-_dbSessao.login_ts)/3600000;
      if(horasAtivo>=13){
        clearInterval(_dbTimer);
        alert('⚠️ Seu turno atingiu o limite de 13 horas. O dia será encerrado automaticamente.');
        dbLogout();
      }
    }
  },1000);
}

function dbIniciarSupervisionSection(){
  var selEq  = document.getElementById('db-admin-eq');
  var inpData= document.getElementById('db-admin-data');
  var btnBus = document.getElementById('btn-db-admin-buscar');

  // Popular select de equipes do contrato do usuário logado
  if(selEq){
    var cid = usuarioLogado ? usuarioLogado.contrato_id : '';
    var eqsDisp = equipes_disp.filter(function(e){
      return (!cid || e.contrato_id===cid) && e.status==='Ativo';
    });
    selEq.innerHTML = '<option value="">Todas as equipes</option>'
      + eqsDisp.map(function(e){
          return '<option value="'+e.id+'">'+e.codigo+' — '+e.nome+'</option>';
        }).join('');
    // Se só tem 1 equipe (o encarregado da própria equipe), pré-selecionar
    if(eqsDisp.length===1) selEq.value = eqsDisp[0].id;
  }

  // Data padrão = hoje
  if(inpData && !inpData.value) inpData.value = dataHoje();

  // Navegação de mês — botões ← →
  var wrap = document.getElementById('db-admin-wrap');
  if(wrap && !document.getElementById('db-cal-nav')){
    var navDiv = document.createElement('div');
    navDiv.id = 'db-cal-nav';
    navDiv.style.cssText = 'display:flex;align-items:center;gap:6px;padding:.5rem .75rem;border-top:.5px solid #f0efe8';
    navDiv.innerHTML =
      '<button onclick="dbNavMes(-1)" style="border:none;background:none;font-size:18px;cursor:pointer;padding:2px 8px">◀</button>'
      +'<span id="db-cal-mes-label" style="font-size:13px;font-weight:600;flex:1;text-align:center"></span>'
      +'<button onclick="dbNavMes(1)" style="border:none;background:none;font-size:18px;cursor:pointer;padding:2px 8px">▶</button>';
    var resultDiv = document.getElementById('db-admin-resultado');
    var cardInner = wrap.querySelector('div > div');
    if(resultDiv && cardInner) cardInner.insertBefore(navDiv, resultDiv);
    else if(cardInner) cardInner.appendChild(navDiv);
    dbAtualizarMesLabel();
  }

  if(btnBus) btnBus.onclick = _buscarDiarioAdmin;
}

function dbAtualizarMesLabel(){
  var inp = document.getElementById('db-admin-data');
  var lbl = document.getElementById('db-cal-mes-label');
  if(!lbl||!inp||!inp.value) return;
  var d = new Date(inp.value+'T12:00:00');
  lbl.textContent = d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
}

function dbNavMes(delta){
  var inp = document.getElementById('db-admin-data');
  if(!inp||!inp.value) return;
  var d = new Date(inp.value+'T12:00:00');
  d.setMonth(d.getMonth()+delta);
  // Ir para o primeiro dia do novo mês
  d.setDate(1);
  inp.value = (function(){var _d=d;return _d.getFullYear()+'-'+String(_d.getMonth()+1).padStart(2,'0')+'-'+String(_d.getDate()).padStart(2,'0');})();
  dbAtualizarMesLabel();
  _buscarDiarioAdmin();
}


function dbAtualizarBotoes(){
  var btnLogin=document.getElementById('btn-db-login');
  var btnAlmoco=document.getElementById('btn-db-almoco');
  var btnLogout=document.getElementById('btn-db-logout');
  var btnRetomar=document.getElementById('btn-db-retomar-wrap');

  if(!_dbSessao){
    var btnRe=document.getElementById('btn-db-reabrir');if(btnRe)btnRe.style.display='none';
    if(btnLogin)btnLogin.style.display='';
    // Dia encerrado — mostrar botão para iniciar novo dia (caso precise corrigir)
    if(btnLogin){
      btnLogin.style.display='';
      btnLogin.textContent='▶ Iniciar novo dia';
      btnLogin.style.background='#534AB7';
    }
    if(btnAlmoco)btnAlmoco.style.display='none';
    if(btnLogout)btnLogout.style.display='none';
    if(btnRetomar)btnRetomar.style.display='none';
  } else if(_dbSessao.almoco_ts&&!_dbSessao.retorno_ts){
    var btnRe2=document.getElementById('btn-db-reabrir');if(btnRe2)btnRe2.style.display='none';
    if(btnLogin)btnLogin.style.display='none';
    if(btnAlmoco)btnAlmoco.style.display='none';
    if(btnLogout)btnLogout.style.display='none';
    if(btnRetomar)btnRetomar.style.display='';
  } else if(_dbSessao.logout_ts){
    // Dia já encerrado — esconder ações, mostrar opção de reabrir
    if(btnLogin)btnLogin.style.display='none';
    if(btnAlmoco)btnAlmoco.style.display='none';
    if(btnLogout)btnLogout.style.display='none';
    if(btnRetomar)btnRetomar.style.display='none';
    // Botão reabrir
    var btnReabrir=document.getElementById('btn-db-reabrir');
    if(!btnReabrir){
      btnReabrir=document.createElement('button');
      btnReabrir.id='btn-db-reabrir';
      btnReabrir.className='btn';
      btnReabrir.style.cssText='flex:1;padding:14px;font-size:15px;border-radius:12px;color:#854F0B;border-color:#854F0B';
      btnReabrir.textContent='↩ Reabrir turno';
      btnReabrir.onclick=dbReabrirTurno;
      var wrap=document.getElementById('btn-db-logout');
      if(wrap&&wrap.parentNode) wrap.parentNode.appendChild(btnReabrir);
    } else {
      btnReabrir.style.display='';
    }
  } else {
    var btnRe3=document.getElementById('btn-db-reabrir');if(btnRe3)btnRe3.style.display='none';
    if(btnLogin)btnLogin.style.display='none';
    if(btnAlmoco)btnAlmoco.style.display='';
    if(btnLogout)btnLogout.style.display='';
    if(btnRetomar)btnRetomar.style.display='none';
  }
  // Mostrar ações rápidas só quando em turno ativo (não no almoço nem encerrado)
  var ar=document.getElementById('db-acoes-rapidas');
  if(ar){
    var emTurno=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts
      &&(!_dbSessao.almoco_ts||_dbSessao.retorno_ts);
    ar.style.display=emTurno?'flex':'none';
  }
  var btnMat=document.getElementById('btn-db-materiais');
  if(btnMat){
    var podeMat=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts&&_dbPodeBaixarMateriais();
    btnMat.disabled=!podeMat;
    btnMat.style.opacity=podeMat?'':'0.45';
    btnMat.title=podeMat?'':'Registre ou encerre uma OS antes de baixar materiais';
  }

  // Checklists do turno — sempre visíveis após turno iniciado
  if(_dbSessao && _dbSessao.login_ts && !_dbSessao.logout_ts){
    dbRenderChecklistsTurno();
  } else {
    var clWrap=document.getElementById('db-checklists-wrap');
    if(clWrap) clWrap.style.display='none';
  }
  var obsWrap = document.getElementById('db-obs-wrap');
  var obsNum  = document.getElementById('db-obs-num');
  var obsTxt  = document.getElementById('db-obs-texto');
  if(obsWrap){
    var emAtividade = _dbOrdemAtual &&
      ['em_andamento','encerrando','encerrada'].indexOf(_dbOrdemAtual.status) >= 0;
    obsWrap.style.display = emAtividade ? '' : 'none';
    if(emAtividade && obsNum)
      obsNum.textContent = 'OS #'+(_dbOrdemAtual.numero_ordem||'');
    if(emAtividade && obsTxt && obsTxt.dataset.ordemId !== (_dbOrdemAtual.id||'')){
      // Carregar observação salva para esta OS
      obsTxt.value = _dbOrdemAtual.observacao || '';
      obsTxt.dataset.ordemId = _dbOrdemAtual.id||'';
    }
  }
  // Card veículo — aparece após turno iniciado com placa
  var veicInfo = document.getElementById('db-veiculo-info');
  if(veicInfo){
    if(_dbSessao && _dbSessao.placa){
      veicInfo.style.display='';
      var plEl=document.getElementById('db-veiculo-placa');
      if(plEl) plEl.textContent=_dbSessao.placa;
      var vFrt=(frt_veiculos||[]).find(function(v){return v.placa===_dbSessao.placa;})
            ||(veiculos||[]).find(function(v){return v.placa===_dbSessao.placa;});
      var modEl=document.getElementById('db-veiculo-modelo');
      if(modEl) modEl.textContent=vFrt?(vFrt.modelo||vFrt.tipo||''):'';
      var kmEl=document.getElementById('db-km-ini-label');
      if(kmEl) kmEl.textContent=(_dbSessao.km_inicial||0)+' km';
      var kfWrap=document.getElementById('db-km-final-wrap');
      var kfLbl=document.getElementById('db-km-fin-label');
      if(_dbSessao.km_final){
        if(kfWrap) kfWrap.style.display='';
        if(kfLbl) kfLbl.textContent=_dbSessao.km_final+' km';
      }
    } else {
      veicInfo.style.display='none';
    }
  }
  var btnChk=document.getElementById('btn-db-checklist-saida');
  if(btnChk){
    var emTurnoChk=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts&&(!_dbSessao.almoco_ts||_dbSessao.retorno_ts);
    btnChk.disabled=!emTurnoChk;
    btnChk.style.opacity=emTurnoChk?'':'0.45';
    btnChk.textContent=(emTurnoChk&&dbVeiculoKitPendente())?'✅ Checklist saída (pendente)':'✅ Checklist saída';
  }
  dbRenderAlertaAlmox();
  dbRenderVeiculoKitChecklist();
  dbRenderSolicitacoesDiario();
  var btnChg=document.getElementById('btn-db-checklist-chegada');
  if(btnChg){
    var emTurnoChg=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts&&(!_dbSessao.almoco_ts||_dbSessao.retorno_ts);
    btnChg.disabled=!emTurnoChg;
    btnChg.style.opacity=emTurnoChg?'':'0.45';
    btnChg.textContent=(emTurnoChg&&dbVeiculoKitChegadaPendente())?'🏁 Checklist chegada (pendente)':'🏁 Checklist chegada';
  }
  var btnSol=document.getElementById('btn-db-solicitar-mat');
  if(btnSol){
    var emTurnoSol=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts&&(!_dbSessao.almoco_ts||_dbSessao.retorno_ts);
    btnSol.disabled=!emTurnoSol;
    btnSol.style.opacity=emTurnoSol?'':'0.45';
  }
}

// ─── DIÁRIO: AÇÕES RÁPIDAS ───────────────────────────────────

// Motivos de aguardo pré-definidos
var DB_MOTIVOS_AGUARDO = [
  'Aguardando ordem de serviço',
  'Aguardando liberação do cliente',
  'Aguardando peça/material',
  'Aguardando deslocamento',
  'Equipe em descanso obrigatório',
  'Aguardando condições climáticas',
  'Parada operacional',
  'Outro motivo'
];

function dbSalvarObsDetalhe(oid){
  var o = ordens_db.find(function(x){return x.id===oid;});
  if(!o) return;
  var txt = (document.getElementById('detalhe-obs-txt')||{}).value||'';
  o.observacao = txt;
  if(_dbOrdemAtual && _dbOrdemAtual.id===oid){
    _dbOrdemAtual.observacao = txt;
    var ta = document.getElementById('db-obs-texto');
    if(ta) ta.value = txt;
  }
  if(!DEMO){
    // Se ID real (UUID), update. Se ID local, tenta insert/update com equipe+data+numero
    if(/^[0-9a-f-]{36}$/i.test(oid)){
      sbUpdate('ordens_diario',{observacao:txt},'id=eq.'+oid);
    } else if(o.equipe_id && o.data && o.numero_ordem){
      sbUpdate('ordens_diario',{observacao:txt},
        'equipe_id=eq.'+o.equipe_id+'&data=eq.'+o.data+'&numero_ordem=eq.'+o.numero_ordem);
    }
  }
  progShowToast('✅ Observação salva');
}

function dbRenderChecklistsTurno(){
  var wrap   = document.getElementById('db-checklists-wrap');
  var corpo  = document.getElementById('db-checklists-corpo');
  var badges = document.getElementById('db-checklists-badges');
  if(!wrap||!corpo) return;
  var hoje = dataHoje();
  var turno = turnos_abertos.find(function(t){
    return t.equipe_id===(_dbEquipe?_dbEquipe.id:'') && t.data===hoje;
  });
  if(!turno){ wrap.style.display='none'; return; }
  var resEpi = parseJsonField(turno.respostas_epi,[]);
  var resVei = parseJsonField(turno.respostas_vei,[]);
  if(!resEpi.length && !resVei.length){ wrap.style.display='none'; return; }
  wrap.style.display='';
  if(badges){
    badges.innerHTML='';
    if(resEpi.length){
      var epiOk=!!turno.checklist_epi_ok;
      badges.innerHTML+='<span class="bdg '+(epiOk?'ok':'danger')+'" style="font-size:10px">🦺 EPI '+(epiOk?'OK':'NOK')+'</span>';
    }
    if(resVei.length){
      var veiOk=!!turno.checklist_vei_ok;
      badges.innerHTML+='<span class="bdg '+(veiOk?'ok':'danger')+'" style="font-size:10px;margin-left:4px">🚗 Veicular '+(veiOk?'OK':'NOK')+'</span>';
    }
  }
  function renderCl(titulo, itens){
    if(!itens.length) return '';
    return '<div style="margin-bottom:.75rem">'
      +'<div style="font-size:12px;font-weight:600;color:#555;margin-bottom:4px">'+titulo+'</div>'
      + itens.map(function(r){
          var v=r.resposta;
          var cor=v==='S'||v==='Sim'||v===true?'#3B6D11':v==='N'||v==='Não'?'#A32D2D':'#888';
          var lbl=v==='S'?'✅ Sim':v==='N'?'❌ Não':v;
          return '<div style="display:flex;justify-content:space-between;gap:8px;padding:4px 0;border-bottom:.5px solid #f5f5f3">'
            +'<span style="font-size:12px;color:#555;flex:1">'+(r.item||r.pergunta||'')+'</span>'
            +'<span style="font-size:11px;font-weight:700;color:'+cor+';white-space:nowrap">'+lbl+'</span>'
            +'</div>'
            +(r.foto?'<div><img src="'+r.foto+'" style="width:80px;height:60px;object-fit:cover;border-radius:6px;margin:3px 0;border:.5px solid #e0dfd8;cursor:pointer" onclick="window.open(\''+r.foto+'\')"/></div>':'');
        }).join('')+'</div>';
  }
  corpo.innerHTML = renderCl('🦺 Checklist EPI', resEpi) + renderCl('🚗 Checklist Veicular', resVei);
}

function dbSalvarObsDebounce(){
  clearTimeout(_dbObsTimer);
  _dbObsTimer = setTimeout(dbSalvarObs, 1500);
}

function dbSalvarObs(){
  clearTimeout(_dbObsTimer);
  if(!_dbOrdemAtual) return;
  var txt = (document.getElementById('db-obs-texto')||{}).value||'';
  _dbOrdemAtual.observacao = txt;
  // Atualizar também em ordens_db
  var o = ordens_db.find(function(x){return x.id===_dbOrdemAtual.id;});
  if(o) o.observacao = txt;
  if(!DEMO){
    var oid = _dbOrdemAtual.id;
    if(/^[0-9a-f-]{36}$/i.test(oid)){
      sbUpdate('ordens_diario',{observacao:txt},'id=eq.'+oid);
    } else if(_dbOrdemAtual.equipe_id && _dbOrdemAtual.data && _dbOrdemAtual.numero_ordem){
      sbUpdate('ordens_diario',{observacao:txt},
        'equipe_id=eq.'+_dbOrdemAtual.equipe_id+'&data=eq.'+_dbOrdemAtual.data+'&numero_ordem=eq.'+_dbOrdemAtual.numero_ordem);
    }
  }
  progShowToast('✅ Observação salva');
}


function dbRegistrarAguardando(){
  if(!_dbSessao||!_dbSessao.login_ts){alert('Inicie o turno primeiro.');return;}

  var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:380px">'
    +'<h3 style="margin-bottom:.75rem">⏳ Aguardando</h3>'
    +'<p style="font-size:12px;color:#888;margin-bottom:.75rem">Selecione o motivo:</p>'
    +'<div style="display:flex;flex-direction:column;gap:6px;margin-bottom:.75rem">'
    +DB_MOTIVOS_AGUARDO.map(function(m,i){
      return '<button id="db-ag-btn-'+i+'" style="padding:10px 12px;border-radius:8px;'
        +'background:#f9f9f7;border:.5px solid #e0dfd8;cursor:pointer;font-size:13px;text-align:left">'+m+'</button>';
    }).join('')
    +'</div>'
    +'<input id="db-ag-outro" class="inp" placeholder="Outro motivo..." style="width:100%;margin-bottom:.75rem"/>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="db-ag-confirmar" style="flex:1">Registrar</button>'
    +'</div></div></div>';
  setModal(html);

  setTimeout(function(){
    var selecionado='';
    DB_MOTIVOS_AGUARDO.forEach(function(m,i){
      var btn=document.getElementById('db-ag-btn-'+i);
      if(!btn)return;
      btn.onclick=function(){
        document.querySelectorAll('[id^="db-ag-btn-"]').forEach(function(b){
          b.style.background='#f9f9f7';b.style.border='.5px solid #e0dfd8';b.style.fontWeight='';
        });
        btn.style.background='#E6F1FB';btn.style.border='.5px solid #185FA5';btn.style.fontWeight='600';
        selecionado=m;
        document.getElementById('db-ag-outro').value='';
      };
    });
    var btnConf=document.getElementById('db-ag-confirmar');
    if(btnConf)btnConf.onclick=function(){
      var outro=(document.getElementById('db-ag-outro')||{}).value.trim();
      var motivo=outro||selecionado;
      if(!motivo){alert('Selecione ou informe o motivo.');return;}
      dbAdicionarEvento('⏳ '+motivo);
      closeModal();
    };
  },50);
}

function dbRegistrarTipoServico(){
  if(!_dbSessao||!_dbSessao.login_ts){alert('Inicie o turno primeiro.');return;}

  var cid=_dbEquipe?_dbEquipe.contrato_id:'';
  var lista=servicos.filter(function(s){return !cid||s.contrato_id===cid;});
  if(!lista.length){
    // Lista manual se não houver serviços cadastrados
    lista=[
      {id:'m1',descricao:'Poda de árvore',codigo:'POD'},
      {id:'m2',descricao:'Manutenção de rede',codigo:'MAN'},
      {id:'m3',descricao:'Instalação',codigo:'INS'},
      {id:'m4',descricao:'Vistoria',codigo:'VIS'},
    ];
  }

  var html='<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3>🔧 Tipo de Serviço</h3>'
    +'<input id="db-sv-busca" class="inp" placeholder="Buscar serviço..." style="width:100%;margin-bottom:.75rem"/>'
    +'<div id="db-sv-lista" style="max-height:300px;overflow-y:auto;display:flex;flex-direction:column;gap:4px;margin-bottom:1rem">'
    +lista.map(function(s){
      return '<button id="db-sv-'+s.id+'" style="padding:8px 12px;border-radius:8px;border:.5px solid #e0dfd8;'
        +'background:#f9f9f7;cursor:pointer;text-align:left;font-size:12px">'
        +(s.codigo?'<span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:10px;margin-right:6px">'+s.codigo+'</span>':' ')
        +s.descricao+'</button>';
    }).join('')
    +'</div>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.5rem">Ou descrever manualmente:</div>'
    +'<input id="db-sv-manual" class="inp" placeholder="Descreva o serviço..." style="width:100%;margin-bottom:1rem"/>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="db-sv-confirmar" style="flex:1">Registrar</button>'
    +'</div></div></div>';
  setModal(html);

  setTimeout(function(){
    var selecionado='';
    // Busca
    var inputBusca=document.getElementById('db-sv-busca');
    if(inputBusca){
      inputBusca.focus();
      inputBusca.oninput=function(){
        var q=inputBusca.value.toLowerCase();
        lista.forEach(function(s){
          var btn=document.getElementById('db-sv-'+s.id);
          if(btn)btn.style.display=(s.descricao.toLowerCase().indexOf(q)>=0||(s.codigo||'').toLowerCase().indexOf(q)>=0)?'':'none';
        });
      };
    }
    lista.forEach(function(s){
      var btn=document.getElementById('db-sv-'+s.id);
      if(!btn)return;
      btn.onclick=function(){
        document.querySelectorAll('[id^="db-sv-"]').forEach(function(b){
          if(b.tagName==='BUTTON'){b.style.background='#f9f9f7';b.style.border='.5px solid #e0dfd8';}
        });
        btn.style.background='#EAF3DE';btn.style.border='.5px solid #3B6D11';
        selecionado=s.descricao+(s.codigo?' ('+s.codigo+')':'');
        document.getElementById('db-sv-manual').value='';
      };
    });
    var btnConf=document.getElementById('db-sv-confirmar');
    if(btnConf)btnConf.onclick=function(){
      var manual=(document.getElementById('db-sv-manual')||{}).value.trim();
      var serv=manual||selecionado;
      if(!serv){alert('Selecione ou descreva o serviço.');return;}
      dbAdicionarEvento('🔧 Serviço: '+serv);
      closeModal();
    };
  },50);
}

var _DB_OS_ABERTA_STS=['a_caminho','no_local','em_andamento','encerrando'];
var _DB_OS_ENCERRADA_STS=['encerrada','disponivel'];

function _dbOrdensHojeEquipe(){
  if(!_dbEquipe) return [];
  var hoje=dataHojeLocal();
  return ordens_db.filter(function(o){
    return o.equipe_id===_dbEquipe.id&&String(o.data||'').slice(0,10)===hoje;
  });
}
function _dbOsAbertaParaBaixa(){
  if(_dbOrdemAtual&&_DB_OS_ABERTA_STS.indexOf(_dbOrdemAtual.status)>=0) return _dbOrdemAtual;
  var hoje=dataHojeLocal();
  return ordens_db.find(function(o){
    return _dbEquipe&&o.equipe_id===_dbEquipe.id&&String(o.data||'').slice(0,10)===hoje
      &&_DB_OS_ABERTA_STS.indexOf(o.status)>=0;
  })||null;
}
function _dbOsEncerradasParaBaixa(){
  return _dbOrdensHojeEquipe().filter(function(o){
    return _DB_OS_ENCERRADA_STS.indexOf(o.status)>=0;
  });
}
function _dbPodeBaixarMateriais(){
  return !!(_dbOsAbertaParaBaixa()||_dbOsEncerradasParaBaixa().length);
}
function _dbMovSapRefereOs(m,numOs){
  if(!m||numOs==null||numOs==='') return false;
  if(String(m.ordem_id||'')===String(numOs)) return true;
  var fo=m.funcao_operacional||'';
  return fo.indexOf('#'+numOs)>=0;
}
function dbRegistrarEventoMaterial(ordemRef,resumo,extra){
  extra=extra||{};
  var tipo='📦 Materiais (OS #'+ordemRef+')';
  var obsTxt=resumo+(extra.placa?' · 🚗 '+extra.placa:'');
  var ev={tipo:tipo,ts:Date.now(),obs:obsTxt,foto:null};
  if(_dbSessao){
    if(!_dbSessao.eventos) _dbSessao.eventos=[];
    _dbSessao.eventos.push({tipo:tipo,ts:ev.ts,obs:obsTxt});
    dbSalvarSessao();
    renderDbHistoricoSessao();
  }
  var o=ordens_db.find(function(x){
    return _dbEquipe&&x.equipe_id===_dbEquipe.id&&String(x.data||'').slice(0,10)===dataHojeLocal()
      &&String(x.numero_ordem)===String(ordemRef);
  });
  if(o){
    if(!o.eventos) o.eventos=[];
    o.eventos.push(ev);
    if(!DEMO){
      if(o.id&&/^[0-9a-f-]{36}$/i.test(o.id)){
        sbUpdate('ordens_diario',{eventos:JSON.stringify(o.eventos)},'id=eq.'+o.id);
      }else if(o.equipe_id&&o.data&&o.numero_ordem){
        sbUpdate('ordens_diario',{eventos:JSON.stringify(o.eventos)},
          'equipe_id=eq.'+o.equipe_id+'&data=eq.'+o.data+'&numero_ordem=eq.'+o.numero_ordem);
      }
    }
    if(_dbOrdemAtual&&_dbOrdemAtual.id===o.id) renderDbOrdemAtual();
    renderDbOrdensDia();
  }
}

// ─── F2: Geo, evidências, alertas, checklist saída veículo ───────────────
function _dbNormPlaca(p){ return String(p||'').replace(/[-\s]/g,'').toUpperCase(); }

function dbGetVeiculoSlot(){
  if(window._dbVeiculoSlot==null){
    try{
      var k='db_veic_slot_'+(_dbEquipe?_dbEquipe.id:'')+'_'+dataHojeLocal();
      var s=localStorage.getItem(k);
      if(s) window._dbVeiculoSlot=parseInt(s,10)||1;
    }catch(e){}
  }
  return window._dbVeiculoSlot===2?2:1;
}
function dbSetVeiculoSlot(n){
  window._dbVeiculoSlot=(n===2?2:1);
  try{
    var k='db_veic_slot_'+(_dbEquipe?_dbEquipe.id:'')+'_'+dataHojeLocal();
    localStorage.setItem(k,String(window._dbVeiculoSlot));
  }catch(e){}
  if(_dbSessao) _dbSessao.veiculo_slot=window._dbVeiculoSlot;
  dbRenderVeiculoKitChecklist();
  dbRenderAlertaAlmox();
}

function campoCapturarGeo(cb){
  cb=cb||function(){};
  if(!navigator.geolocation){
    cb({sem_geo:true,latitude:null,longitude:null,endereco_aproximado:null});
    return;
  }
  navigator.geolocation.getCurrentPosition(
    function(pos){
      cb({sem_geo:false,latitude:pos.coords.latitude,longitude:pos.coords.longitude,endereco_aproximado:null});
    },
    function(){ cb({sem_geo:true,latitude:null,longitude:null,endereco_aproximado:null,geoErro:true}); },
    {enableHighAccuracy:true,timeout:15000,maximumAge:60000}
  );
}

async function campoSalvarEvidencia(opts){
  opts=opts||{};
  if(!opts.foto_url&&opts.file&&typeof sbUpload==='function'){
    opts.foto_url=await sbUpload(opts.file,'evidencias/'+opts.origem_tipo+'/'+Date.now()+'_'+opts.file.name);
  }
  if(!opts.foto_url) return null;
  var row={
    origem_tipo:opts.origem_tipo,
    origem_id:opts.origem_id,
    equipe_id:opts.equipe_id||null,
    veiculo_id:opts.veiculo_id||null,
    veiculo_slot:opts.veiculo_slot||1,
    placa:opts.placa||null,
    usuario_id:opts.usuario_id||(typeof usuarioLogado!=='undefined'&&usuarioLogado?usuarioLogado.id:null),
    foto_url:opts.foto_url,
    latitude:opts.latitude||null,
    longitude:opts.longitude||null,
    endereco_aproximado:opts.endereco_aproximado||null,
    sem_geo:!!opts.sem_geo,
    sem_geo_justificativa:opts.sem_geo_justificativa||null,
    tipo_evidencia:opts.tipo_evidencia||null,
    observacao:opts.observacao||null
  };
  if(DEMO) return row;
  var res=await sbInsert('evidencias_operacionais',row).catch(function(err){ console.warn('evidencias_operacionais',err); return null; });
  return res&&res[0]?res[0]:null;
}

async function campoCriarAlerta(opts){
  opts=opts||{};
  if(!opts.mensagem) return null;
  var row={
    data:opts.data||dataHojeLocal(),
    tipo:opts.tipo||'kit_incompleto',
    severidade:opts.severidade||'media',
    equipe_id:opts.equipe_id||(_dbEquipe?_dbEquipe.id:null),
    veiculo_id:opts.veiculo_id||null,
    veiculo_slot:opts.veiculo_slot||1,
    placa:opts.placa||null,
    origem_tipo:opts.origem_tipo||null,
    origem_id:opts.origem_id||null,
    mensagem:opts.mensagem,
    status:'aberto',
    destinatario:opts.destinatario||'almoxarifado'
  };
  if(DEMO){ _dbAlertasCampo.push(Object.assign({id:'demo-a'+Date.now()},row)); return row; }
  var dup=(_dbAlertasCampo||[]).some(function(a){
    return a.status==='aberto'&&a.tipo===row.tipo&&a.placa===row.placa
      &&String(a.data||'').split('T')[0]===row.data&&(a.veiculo_slot||1)===row.veiculo_slot;
  });
  if(dup) return null;
  var res=await sbInsert('campo_alertas_operacionais',row).catch(function(err){ console.warn('campo_alertas_operacionais',err); return null; });
  if(res&&res[0]){ _dbAlertasCampo.push(res[0]); return res[0]; }
  return null;
}

function dbGetChecklistSaidaHoje(veic, slot){
  if(!veic||!veic.placa) return null;
  var hoje=dataHojeLocal();
  slot=slot||dbGetVeiculoSlot();
  return (_dbChecklistsCampo||[]).find(function(c){
    return c.tipo==='saida'&&c.status!=='cancelado'
      &&String(c.data||'').split('T')[0]===hoje
      &&_dbNormPlaca(c.placa)===_dbNormPlaca(veic.placa)
      &&(c.veiculo_slot||1)===slot;
  })||null;
}

function dbVeiculoKitPendente(){
  if(!_dbSessao||!_dbSessao.login_ts||_dbSessao.logout_ts) return false;
  var veic=dbResolverVeiculoDiario();
  if(!veic||!veic.placa) return false;
  var chk=dbGetChecklistSaidaHoje(veic,veic.veiculo_slot);
  return !(chk&&['aceito','conferido','divergente'].indexOf(chk.status)>=0);
}

function dbAlertasVeiculoAbertos(veic){
  if(!veic) return [];
  var hoje=dataHojeLocal();
  return (_dbAlertasCampo||[]).filter(function(a){
    if(a.status!=='aberto') return false;
    if(String(a.data||'').split('T')[0]!==hoje) return false;
    if(veic.placa&&a.placa&&_dbNormPlaca(a.placa)!==_dbNormPlaca(veic.placa)) return false;
    if(veic.veiculo_slot&&(a.veiculo_slot||1)!==veic.veiculo_slot) return false;
    return true;
  });
}

function _dbGetStatusKitVeiculo(veic){
  if(!veic) return '';
  var frt=veic.veiculo;
  if(!frt&&veic.placa){
    frt=(frt_veiculos||[]).find(function(v){return _dbNormPlaca(v.placa)===_dbNormPlaca(veic.placa);});
  }
  if(!frt&&veic.veiculo_id){
    frt=(frt_veiculos||[]).find(function(v){return v.id===veic.veiculo_id;});
  }
  return (frt&&frt.status_kit_materiais)||veic.status_kit_materiais||'';
}
function _dbStatusKitCargaPendente(st){
  return ['vistoria_inicial_pendente','vistoria_inicial_realizada','reposicao_inicial_pendente',
    'reposicao_inicial_em_separacao','reposicao_inicial_parcial','sem_kit_cadastrado'].indexOf(st||'')>=0;
}

function dbRenderAlertaAlmox(){
  var el=document.getElementById('db-alerta-almox');
  if(!el) return;
  var emTurno=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts&&(!_dbSessao.almoco_ts||_dbSessao.retorno_ts);
  if(!emTurno){ el.style.display='none'; el.innerHTML=''; return; }
  var veic=dbResolverVeiculoDiario();
  if(!veic||!veic.placa){ el.style.display='none'; el.innerHTML=''; return; }
  var msgs=[];
  if(dbVeiculoKitPendente()){
    msgs.push({cor:'#854F0B',txt:'⚠ Checklist de saída pendente — confira o kit do veículo <b>'+veic.placa+'</b> (slot '+(veic.veiculo_slot||1)+').',acao:'dbAbrirChecklistSaidaVeiculo()'});
  }
  if(dbVeiculoKitChegadaPendente()&&_dbSessao&&_dbSessao.login_ts){
    msgs.push({cor:'#533AB7',txt:'🏁 Checklist de chegada pendente — declare materiais ao retornar (<b>'+veic.placa+'</b>).',acao:'dbAbrirChecklistChegadaVeiculo()'});
  }
  var chk=dbGetChecklistSaidaHoje(veic,veic.veiculo_slot);
  if(chk&&chk.kit_incompleto){
    msgs.push({cor:'#A32D2D',txt:'⚠ Veículo com kit incompleto. Dirigir-se ao almoxarifado — <b>'+veic.placa+'</b>.',acao:'dbAbrirChecklistSaidaVeiculo()'});
  }
  var stKit=_dbGetStatusKitVeiculo(veic);
  if(_dbStatusKitCargaPendente(stKit)){
    msgs.push({cor:'#533AB7',txt:'⚠ Veículo <b>'+veic.placa+'</b> ainda não está com carga inicial completa. Dirigir-se ao almoxarifado.',acao:''});
  }else if(stKit==='carga_inicial_abastecida'){
    msgs.push({cor:'#185FA5',txt:'ℹ Carga inicial abastecida — <b>'+veic.placa+'</b>. Confira checklist de saída.',acao:'dbAbrirChecklistSaidaVeiculo()'});
  }
  dbAlertasVeiculoAbertos(veic).forEach(function(a){
    if(a.tipo==='kit_incompleto'&&!msgs.some(function(m){return m.txt.indexOf('kit incompleto')>=0;})){
      msgs.push({cor:'#A32D2D',txt:'⚠ '+a.mensagem,acao:'dbAbrirChecklistSaidaVeiculo()'});
    } else if(a.tipo!=='kit_incompleto'){
      msgs.push({cor:'#533AB7',txt:'ℹ '+a.mensagem,acao:''});
    }
  });
  if(!msgs.length){ el.style.display='none'; el.innerHTML=''; return; }
  el.style.display='';
  el.innerHTML=msgs.map(function(m){
    return '<div onclick="'+(m.acao||'')+'" style="background:'+m.cor+'15;border-left:4px solid '+m.cor+';border-radius:8px;padding:.55rem .75rem;margin-bottom:4px;font-size:12px;color:#333;cursor:'+(m.acao?'pointer':'default')+'">'+m.txt+'</div>';
  }).join('');
}

function dbRenderVeiculoKitChecklist(){
  var wrap=document.getElementById('db-veiculo-kit-wrap');
  if(!wrap) return;
  var emTurno=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts&&(!_dbSessao.almoco_ts||_dbSessao.retorno_ts);
  if(!emTurno){ wrap.style.display='none'; wrap.innerHTML=''; return; }
  var veic=dbResolverVeiculoDiario();
  if(!veic||!veic.placa){ wrap.style.display='none'; wrap.innerHTML=''; return; }
  wrap.style.display='';
  var slotHtml='';
  if(typeof isMotoDupla==='function'&&isMotoDupla(_dbEquipe)){
    var sl=dbGetVeiculoSlot();
    slotHtml='<div style="display:flex;gap:6px;align-items:center;margin-bottom:6px">'
      +'<span style="font-size:11px;color:#555">Veículo slot:</span>'
      +'<button type="button" onclick="dbSetVeiculoSlot(1)" style="padding:4px 10px;border-radius:6px;font-size:11px;border:.5px solid #ccc;background:'+(sl===1?'#185FA5;color:#fff':'#fff')+'">1</button>'
      +'<button type="button" onclick="dbSetVeiculoSlot(2)" style="padding:4px 10px;border-radius:6px;font-size:11px;border:.5px solid #ccc;background:'+(sl===2?'#185FA5;color:#fff':'#fff')+'">2</button>'
      +'</div>';
  }
  var chk=dbGetChecklistSaidaHoje(veic,veic.veiculo_slot);
  var chkCh=dbGetChecklistChegadaHoje(veic,veic.veiculo_slot);
  var stKit=_dbGetStatusKitVeiculo(veic);
  var kitN=typeof almResolverKitVeiculo==='function'?almResolverKitVeiculo(veic.veiculo_id,veic.tipo_operacional,veic.contrato_id).length:0;
  var stLbl='Saída pendente', stCor='#854F0B';
  if(chk){
    if(chk.kit_incompleto){ stLbl='Saída: kit incompleto'; stCor='#A32D2D'; }
    else if(['aceito','conferido'].indexOf(chk.status)>=0){ stLbl='Saída OK'; stCor='#3B6D11'; }
    else if(chk.status==='divergente'){ stLbl='Saída divergente'; stCor='#A32D2D'; }
    else { stLbl='Saída: '+chk.status; }
  }
  var stChLbl=chkCh?'Chegada OK':'Chegada pendente';
  var stChCor=chkCh?'#3B6D11':'#533AB7';
  var kitStHtml='';
  if(stKit){
    var kitStLbl=(typeof VIST_KIT_ST!=='undefined'&&VIST_KIT_ST[stKit])?VIST_KIT_ST[stKit]:stKit;
    var kitStCor=stKit==='em_operacao'?'#3B6D11':(_dbStatusKitCargaPendente(stKit)?'#854F0B':'#533AB7');
    kitStHtml='<div style="font-size:10px;font-weight:600;color:'+kitStCor+';margin-top:4px">Kit materiais: '+escHtml(kitStLbl)+'</div>';
  }
  wrap.innerHTML=slotHtml
    +'<div style="background:#f9f9f7;border-radius:10px;padding:.6rem .75rem;border:.5px solid #e0dfd8">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">'
    +'<div><div style="font-size:12px;font-weight:600">📦 Kit veículo · '+veic.placa+'</div>'
    +'<div style="font-size:11px;color:#666">'+(veic.tipo_operacional||'—')+' · '+kitN+' item(ns)</div>'+kitStHtml+'</div>'
    +'<div style="text-align:right"><span style="font-size:10px;font-weight:700;color:'+stCor+'">'+stLbl+'</span><br>'
    +'<span style="font-size:10px;font-weight:700;color:'+stChCor+'">'+stChLbl+'</span></div>'
    +'</div>'
    +'<button type="button" class="btn" onclick="dbAbrirChecklistSaidaVeiculo()" style="width:100%;margin-top:8px;font-size:12px;padding:8px">'+(chk?'Ver checklist saída':'Checklist saída')+'</button>'
    +'<button type="button" class="btn" onclick="dbAbrirChecklistChegadaVeiculo()" style="width:100%;margin-top:6px;font-size:12px;padding:8px;border-color:#533AB7;color:#533AB7">'+(chkCh?'Ver checklist chegada':'Checklist chegada')+'</button>'
    +'</div>';
}

function _dbChkItemStatus(esperada, informada, naoLoc){
  if(naoLoc) return 'nao_localizado';
  var e=parseFloat(esperada)||0, i=parseFloat(informada);
  if(isNaN(i)) return 'pendente';
  if(Math.abs(i-e)<0.0001) return 'conferido';
  if(i<e) return 'faltando';
  if(i>e) return 'excedente';
  return 'conferido';
}

function dbAbrirChecklistSaidaVeiculo(){
  if(!_dbSessao||!_dbSessao.login_ts){ progShowToast('Inicie o turno primeiro.','erro'); return; }
  dbPrepararBaixaMateriais(function(veic, kitRpc){
    if(!veic||!veic.placa){ progShowToast('Veículo não identificado na programação.','erro'); return; }
    var kit=dbResolverKitBaixa(veic, kitRpc);
    if(!kit.length){ progShowToast('Kit vazio — cadastre em Almox → Kits Modelo ('+(veic.tipo_operacional||'?')+').','erro'); return; }
    window._dbChkSaidaVeic=veic;
    window._dbChkSaidaItens=kit.map(function(k,i){
      var q=parseFloat(k.quantidade_basica)||0;
      return {idx:i,kit_linha_id:k.id,material_id:k.material_id||null,
        codigo_material:k.codigo_material||'',descricao_material:k.descricao_material||'—',
        unidade:k.unidade||'UN',quantidade_esperada:q,quantidade_informada:q};
    });
    var existente=dbGetChecklistSaidaHoje(veic,veic.veiculo_slot);
    var stKit=_dbGetStatusKitVeiculo(veic);
    var avisoCarga=_dbStatusKitCargaPendente(stKit)
      ?'<div style="background:#FFF7E6;border:.5px solid #f0d088;border-radius:8px;padding:.55rem .75rem;font-size:11px;color:#854F0B;margin-bottom:.75rem">'
      +'⚠ <b>Carga inicial ainda pendente</b> — você pode sair, mas informe observação e foto. Almox e supervisor serão alertados.</div>':'';
    var html='<div class="modal-bg"><div class="modal" style="max-width:520px;max-height:92vh;overflow:auto">'
      +'<h3 style="margin-bottom:.5rem">✅ Checklist saída — '+veic.placa+'</h3>'
      +avisoCarga
      +'<p style="font-size:11px;color:#888;margin-bottom:.75rem">Slot '+(veic.veiculo_slot||1)+' · '+(veic.tipo_operacional||'')+(existente?' · registro anterior: '+existente.status:'')+'</p>'
      +'<div style="max-height:38vh;overflow:auto;margin-bottom:.75rem;border:.5px solid #e0dfd8;border-radius:8px">'
      +'<table style="width:100%;font-size:11px;border-collapse:collapse">'
      +'<thead><tr style="background:#f5f5f3"><th style="padding:6px;text-align:left">Material</th><th style="padding:6px">Esp.</th><th style="padding:6px">Conf.</th><th style="padding:6px">N/L</th></tr></thead><tbody>'
      +window._dbChkSaidaItens.map(function(it){
        return '<tr style="border-top:.5px solid #eee"><td style="padding:5px 6px">'+it.descricao_material+'<div style="font-size:9px;color:#999">'+it.codigo_material+'</div></td>'
          +'<td style="padding:5px;text-align:center">'+it.quantidade_esperada+' '+it.unidade+'</td>'
          +'<td style="padding:5px;text-align:center"><input type="number" min="0" step="any" id="db-chk-q-'+it.idx+'" value="'+it.quantidade_informada+'" style="width:56px;padding:4px;font-size:11px;border-radius:4px;border:.5px solid #ccc"/></td>'
          +'<td style="padding:5px;text-align:center"><input type="checkbox" id="db-chk-nl-'+it.idx+'" title="Não localizado"/></td></tr>';
      }).join('')
      +'</tbody></table></div>'
      +'<label style="font-size:11px;display:block;margin-bottom:4px">📷 Foto geral do veículo/materiais *</label>'
      +'<input type="file" accept="image/*" capture="environment" id="db-chk-foto" style="display:none"/>'
      +'<button type="button" class="btn" id="db-chk-foto-btn" style="width:100%;padding:12px;font-size:13px;border-color:#533AB7;color:#533AB7;margin-bottom:4px">📷 Tirar foto (câmera)</button>'
      +'<span id="db-chk-foto-ok" style="display:none;font-size:11px;color:#3B6D11;margin-left:2px">✓ Foto capturada</span>'
      +'<div id="db-chk-foto-prev" style="margin-bottom:.75rem"></div>'
      +'<div id="db-chk-geo-wrap" style="display:none;margin-bottom:.75rem">'
      +'<label style="font-size:11px;color:#854F0B">Geolocalização indisponível — justificativa *</label>'
      +'<textarea id="db-chk-geo-just" rows="2" style="width:100%;font-size:11px;padding:6px;border-radius:6px;border:.5px solid #ccc"></textarea></div>'
      +'<label style="font-size:11px;display:block;margin-bottom:4px">Observação</label>'
      +'<textarea id="db-chk-obs" rows="2" style="width:100%;font-size:11px;padding:6px;border-radius:6px;border:.5px solid #ccc;margin-bottom:.75rem"></textarea>'
      +'<label style="font-size:11px;display:flex;gap:6px;align-items:flex-start;margin-bottom:.75rem"><input type="checkbox" id="db-chk-aceite"/> '
      +'Recebi o veículo <b>'+veic.placa+'</b> e conferi o kit básico de materiais.</label>'
      +'<div style="display:flex;gap:8px"><button type="button" class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
      +'<button type="button" class="btn" id="db-chk-salvar-btn" onclick="dbSalvarChecklistSaidaVeiculo()" style="flex:2;background:#3B6D11;color:#fff">Salvar checklist</button></div>'
      +'</div></div>';
    setModal(html);
    setTimeout(function(){
      window._dbChkFotoFile=null;
      var inp=document.getElementById('db-chk-foto');
      var btnF=document.getElementById('db-chk-foto-btn');
      var prev=document.getElementById('db-chk-foto-prev');
      var ok=document.getElementById('db-chk-foto-ok');
      if(btnF&&inp){
        btnF.onclick=function(){ inp.click(); };
        inp.onchange=function(e){
          var f=e.target.files&&e.target.files[0];
          if(!f) return;
          window._dbChkFotoFile=f;
          if(prev) prev.innerHTML='<img src="'+URL.createObjectURL(f)+'" style="max-width:100%;border-radius:8px;max-height:160px;margin-top:6px"/>';
          if(ok) ok.style.display='inline';
          btnF.style.borderColor='#3B6D11'; btnF.style.color='#3B6D11'; btnF.textContent='📷 Trocar foto';
        };
      }
    },50);
  });
}

async function dbSalvarChecklistSaidaVeiculo(){
  var veic=window._dbChkSaidaVeic;
  var itens=window._dbChkSaidaItens||[];
  if(!veic||!itens.length){ progShowToast('Dados do checklist inválidos.','erro'); return; }
  var aceite=document.getElementById('db-chk-aceite');
  if(!aceite||!aceite.checked){ progShowToast('Marque o aceite de recebimento.','erro'); return; }
  var file=window._dbChkFotoFile||null;
  if(!file){
    var fotoIn=document.getElementById('db-chk-foto');
    file=fotoIn&&fotoIn.files&&fotoIn.files[0]?fotoIn.files[0]:null;
  }
  if(!file&&!DEMO){ progShowToast('Tire a foto pelo botão da câmera.','erro'); return; }
  var btn=document.getElementById('db-chk-salvar-btn');
  if(btn){ btn.disabled=true; btn.textContent='Salvando…'; }
  var geo=await new Promise(function(resolve){ campoCapturarGeo(resolve); });
  var semGeo=!!geo.sem_geo;
  var justEl=document.getElementById('db-chk-geo-just');
  if(semGeo){
    var wrap=document.getElementById('db-chk-geo-wrap');
    if(wrap) wrap.style.display='';
    var just=justEl?(justEl.value||'').trim():'';
    if(!just){ progShowToast('Informe a justificativa para ausência de GPS.','erro'); if(btn){btn.disabled=false;btn.textContent='Salvar checklist';} return; }
    geo.sem_geo_justificativa=just;
  }
  var obs=((document.getElementById('db-chk-obs')||{}).value||'').trim();
  var stKitSaida=_dbGetStatusKitVeiculo(veic);
  if(_dbStatusKitCargaPendente(stKitSaida)&&!obs){
    progShowToast('Carga inicial pendente — observação obrigatória no checklist.','erro');
    if(btn){btn.disabled=false;btn.textContent='Salvar checklist';} return;
  }
  var kitIncompleto=false;
  var itensPayload=itens.map(function(it){
    var nlEl=document.getElementById('db-chk-nl-'+it.idx);
    var qEl=document.getElementById('db-chk-q-'+it.idx);
    var nl=nlEl&&nlEl.checked;
    var qi=qEl?parseFloat(qEl.value):it.quantidade_informada;
    var st=_dbChkItemStatus(it.quantidade_esperada, qi, nl);
    if(st==='faltando'||st==='nao_localizado') kitIncompleto=true;
    return {kit_linha_id:it.kit_linha_id,material_id:it.material_id,codigo_material:it.codigo_material,
      descricao_material:it.descricao_material,unidade:it.unidade,
      quantidade_esperada:it.quantidade_esperada,quantidade_informada:isNaN(qi)?null:qi,status_item:st};
  });
  var hoje=dataHojeLocal();
  var fotoUrl=null;
  if(file&&typeof sbUpload==='function') fotoUrl=await sbUpload(file,'evidencias/checklist_saida/'+Date.now()+'_'+file.name);
  else if(DEMO) fotoUrl='demo://checklist';
  if(!fotoUrl){ progShowToast('Erro ao enviar foto.','erro'); if(btn){btn.disabled=false;btn.textContent='Salvar checklist';} return; }
  var chkRow={
    data:hoje,tipo:'saida',equipe_id:_dbEquipe.id,veiculo_id:veic.veiculo_id||null,
    veiculo_slot:veic.veiculo_slot||1,placa:veic.placa,sessao_id:(_dbSessao&&_dbSessao.id)||null,
    contrato_id:veic.contrato_id||(_dbEquipe?_dbEquipe.contrato_id:null),
    usuario_id:(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.id:null,
    latitude:geo.latitude||null,longitude:geo.longitude||null,endereco_aproximado:geo.endereco_aproximado||null,
    sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa||null,
    foto_url:fotoUrl,status:kitIncompleto?'divergente':'aceito',kit_incompleto:kitIncompleto,
    observacao:obs||null,aceite_em:new Date().toISOString()
  };
  var chkId=null;
  if(DEMO){
    chkId='demo-chk-'+Date.now();
    _dbChecklistsCampo.push(Object.assign({id:chkId},chkRow));
  } else {
    var ins=await sbInsert('campo_veiculo_checklists',chkRow).catch(function(err){
      console.error('campo_veiculo_checklists',err);
      progShowToast('Erro ao salvar checklist — talvez já exista registro do dia.','erro');
      return null;
    });
    if(!ins||!ins[0]){ if(btn){btn.disabled=false;btn.textContent='Salvar checklist';} return; }
    chkId=ins[0].id;
    _dbChecklistsCampo.push(ins[0]);
    for(var i=0;i<itensPayload.length;i++){
      var ip=Object.assign({checklist_id:chkId},itensPayload[i]);
      await sbInsert('campo_veiculo_checklist_itens',ip).catch(function(err){ console.warn('checklist_itens',err); });
    }
  }
  await campoSalvarEvidencia({
    origem_tipo:'checklist_saida',origem_id:chkId,foto_url:fotoUrl,
    equipe_id:_dbEquipe.id,veiculo_id:veic.veiculo_id,veiculo_slot:veic.veiculo_slot||1,placa:veic.placa,
    latitude:geo.latitude,longitude:geo.longitude,sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa,
    tipo_evidencia:'foto_geral',observacao:obs||null
  });
  if(kitIncompleto){
    await campoCriarAlerta({
      tipo:'kit_incompleto',destinatario:'almoxarifado',veiculo_id:veic.veiculo_id,
      veiculo_slot:veic.veiculo_slot||1,placa:veic.placa,origem_tipo:'checklist_saida',origem_id:chkId,
      mensagem:'Veículo '+veic.placa+' (slot '+(veic.veiculo_slot||1)+') com kit incompleto na saída. Dirigir-se ao almoxarifado.',
      severidade:'alta'
    });
  }
  if(_dbStatusKitCargaPendente(stKitSaida)){
    await campoCriarAlerta({
      tipo:'carga_inicial_pendente',destinatario:'almoxarifado',severidade:'media',
      equipe_id:_dbEquipe?_dbEquipe.id:null,veiculo_id:veic.veiculo_id,
      veiculo_slot:veic.veiculo_slot||1,placa:veic.placa,origem_tipo:'checklist_saida',origem_id:chkId,
      mensagem:'Saída com carga inicial pendente — '+veic.placa+(obs?': '+obs:'')
    });
    await campoCriarAlerta({
      tipo:'carga_inicial_pendente',destinatario:'supervisor',severidade:'media',
      equipe_id:_dbEquipe?_dbEquipe.id:null,veiculo_id:veic.veiculo_id,
      veiculo_slot:veic.veiculo_slot||1,placa:veic.placa,origem_tipo:'checklist_saida',origem_id:chkId,
      mensagem:'Equipe saiu com carga inicial incompleta — '+veic.placa
    });
  }
  if(semGeo){
    await campoCriarAlerta({
      tipo:'sem_geolocalizacao',destinatario:'supervisor',veiculo_id:veic.veiculo_id,
      veiculo_slot:veic.veiculo_slot||1,placa:veic.placa,origem_tipo:'checklist_saida',origem_id:chkId,
      mensagem:'Checklist saída '+veic.placa+' registrado sem geolocalização.',
      severidade:'baixa'
    });
  }
  closeModal();
  dbRenderAlertaAlmox();
  dbRenderVeiculoKitChecklist();
  dbAtualizarBotoes();
  progShowToast(kitIncompleto?'Checklist salvo — kit incompleto, vá ao almox':'✅ Checklist de saída registrado');
}

// ─── F5: Solicitação material em campo + supervisor + recebimento ───────
var DB_SOL_PRIORIDADE={normal:'Normal',urgente:'Urgente',emergencia:'Emergência'};
var DB_SOL_STATUS_LABEL={
  pendente_supervisor:'Pendente supervisor',ajuste_solicitado:'Ajuste solicitado',aprovada:'Aprovada',
  rejeitada:'Rejeitada',em_separacao:'Em separação',entregue:'Entregue — confirmar recebimento',
  confirmada:'Confirmada',cancelada:'Cancelada'
};

function _dbNomeEquipeSol(eqId){
  var eq=(equipes||[]).find(function(e){return e.id===eqId;});
  return eq?(eq.nome||eq.codigo||'—'):'—';
}

function dbSolicitacoesEquipeHoje(){
  if(!_dbEquipe) return [];
  var hoje=dataHojeLocal();
  return (_dbSolicitacoesCampo||[]).filter(function(s){
    return s.equipe_id===_dbEquipe.id && String(s.data||'').split('T')[0]===hoje;
  });
}

function dbRenderSolicitacoesDiario(){
  var wrap=document.getElementById('db-solicitacoes-wrap');
  if(!wrap) return;
  var emTurno=_dbSessao&&_dbSessao.login_ts&&!_dbSessao.logout_ts&&(!_dbSessao.almoco_ts||_dbSessao.retorno_ts);
  if(!emTurno){ wrap.style.display='none'; wrap.innerHTML=''; return; }
  var sols=dbSolicitacoesEquipeHoje().filter(function(s){
    return ['pendente_supervisor','aprovada','em_separacao','entregue','ajuste_solicitado'].indexOf(s.status)>=0;
  });
  if(!sols.length){ wrap.style.display='none'; wrap.innerHTML=''; return; }
  wrap.style.display='';
  wrap.innerHTML='<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.6rem .75rem">'
    +'<div style="font-size:12px;font-weight:600;margin-bottom:6px">📝 Solicitações de material</div>'
    +sols.map(function(s){
      var cor=s.status==='entregue'?'#3B6D11':s.status==='rejeitada'?'#A32D2D':'#533AB7';
      var btn=s.status==='entregue'
        ?'<button type="button" class="btn" onclick="dbConfirmarRecebimentoMaterial(\''+s.id+'\')" style="margin-top:6px;width:100%;font-size:11px;padding:6px;background:#3B6D11;color:#fff">✅ Confirmar recebimento</button>':'';
      return '<div style="border-left:3px solid '+cor+';padding:6px 8px;margin-bottom:6px;background:#f9f9f7;border-radius:6px">'
        +'<div style="font-size:11px;font-weight:600">'+(DB_SOL_STATUS_LABEL[s.status]||s.status)+' · '+(DB_SOL_PRIORIDADE[s.prioridade]||s.prioridade)+'</div>'
        +'<div style="font-size:10px;color:#666;margin-top:2px">'+(s.placa||'—')+(s.numero_ordem?' · OS '+s.numero_ordem:'')+'</div>'
        +'<div style="font-size:10px;color:#555;margin-top:2px">'+escHtml((s.texto_solicitacao||'').slice(0,120))+'</div>'
        +btn+'</div>';
    }).join('')
    +'</div>';
}

function dbSolicitarMateriais(){
  if(!_dbSessao||!_dbSessao.login_ts){ progShowToast('Inicie o turno primeiro.','erro'); return; }
  var veic=dbResolverVeiculoDiario();
  var osOpts='';
  var ordensHoje=ordens_db.filter(function(o){
    return _dbEquipe&&o.equipe_id===_dbEquipe.id&&String(o.data||'').slice(0,10)===dataHojeLocal();
  });
  ordensHoje.forEach(function(o){
    osOpts+='<option value="'+escHtml(String(o.numero_ordem||''))+'">OS #'+escHtml(String(o.numero_ordem||''))+'</option>';
  });
  var osDefault=_dbOrdemAtual?String(_dbOrdemAtual.numero_ordem||''):'';
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px;max-height:92vh;overflow:auto">'
    +'<h3 style="margin-bottom:.5rem">📝 Solicitar materiais</h3>'
    +'<p style="font-size:11px;color:#888;margin-bottom:.75rem">'+(veic&&veic.placa?('Veículo '+veic.placa+' · slot '+(veic.veiculo_slot||1)):'Veículo não identificado')+'</p>'
    +'<label style="font-size:11px">OS (opcional)</label>'
    +'<select id="db-sol-os" class="inp" style="width:100%;margin-bottom:.75rem;font-size:12px"><option value="">— Sem OS —</option>'+osOpts+'</select>'
    +'<label style="font-size:11px">Prioridade *</label>'
    +'<select id="db-sol-prioridade" class="inp" style="width:100%;margin-bottom:.75rem;font-size:12px">'
    +'<option value="normal">Normal</option><option value="urgente">Urgente</option><option value="emergencia">Emergência</option></select>'
    +'<label style="font-size:11px">O que precisa? *</label>'
    +'<textarea id="db-sol-texto" rows="3" class="inp" style="width:100%;margin-bottom:.75rem;font-size:12px" placeholder="Descreva os materiais necessários..."></textarea>'
    +'<label style="font-size:11px">Justificativa *</label>'
    +'<textarea id="db-sol-just" rows="2" class="inp" style="width:100%;margin-bottom:.75rem;font-size:12px" placeholder="Motivo da solicitação..."></textarea>'
    +'<label style="font-size:11px">📷 Foto (opcional)</label>'
    +'<input type="file" accept="image/*" capture="environment" id="db-sol-foto" style="display:none"/>'
    +'<button type="button" class="btn" id="db-sol-foto-btn" style="width:100%;padding:10px;font-size:12px;border-color:#533AB7;color:#533AB7;margin-bottom:4px">📷 Tirar foto (câmera)</button>'
    +'<span id="db-sol-foto-ok" style="display:none;font-size:11px;color:#3B6D11">✓ Foto capturada</span>'
    +'<div id="db-sol-foto-prev" style="margin-bottom:.75rem"></div>'
    +'<div id="db-sol-geo-wrap" style="display:none;margin-bottom:.75rem">'
    +'<label style="font-size:11px;color:#854F0B">GPS indisponível — justificativa *</label>'
    +'<textarea id="db-sol-geo-just" rows="2" class="inp" style="width:100%;font-size:11px"></textarea></div>'
    +'<div style="display:flex;gap:8px"><button type="button" class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button type="button" class="btn" id="db-sol-salvar-btn" onclick="dbSalvarSolicitacaoMaterial()" style="flex:2;background:#533AB7;color:#fff">Enviar ao supervisor</button></div>'
    +'</div></div>');
  setTimeout(function(){
    window._dbSolFotoFile=null;
    var osEl=document.getElementById('db-sol-os');
    if(osEl&&osDefault) osEl.value=osDefault;
    var inp=document.getElementById('db-sol-foto');
    var btnF=document.getElementById('db-sol-foto-btn');
    if(btnF&&inp){
      btnF.onclick=function(){ inp.click(); };
      inp.onchange=function(e){
        var f=e.target.files&&e.target.files[0]; if(!f) return;
        window._dbSolFotoFile=f;
        var prev=document.getElementById('db-sol-foto-prev');
        if(prev) prev.innerHTML='<img src="'+URL.createObjectURL(f)+'" style="max-width:100%;border-radius:8px;max-height:120px;margin-top:6px"/>';
        var ok=document.getElementById('db-sol-foto-ok'); if(ok) ok.style.display='inline';
        btnF.textContent='📷 Trocar foto';
      };
    }
  },50);
}

async function dbSalvarSolicitacaoMaterial(){
  if(!_dbEquipe||!_dbSessao){ progShowToast('Turno não iniciado.','erro'); return; }
  var texto=((document.getElementById('db-sol-texto')||{}).value||'').trim();
  var just=((document.getElementById('db-sol-just')||{}).value||'').trim();
  if(!texto){ progShowToast('Descreva o que precisa.','erro'); return; }
  if(!just){ progShowToast('Justificativa obrigatória.','erro'); return; }
  var prioridade=(document.getElementById('db-sol-prioridade')||{}).value||'normal';
  var numeroOrdem=((document.getElementById('db-sol-os')||{}).value||'').trim()||null;
  var veic=dbResolverVeiculoDiario();
  var btn=document.getElementById('db-sol-salvar-btn');
  if(btn){ btn.disabled=true; btn.textContent='Enviando…'; }
  var geo=await new Promise(function(resolve){ campoCapturarGeo(resolve); });
  var semGeo=!!geo.sem_geo;
  if(semGeo){
    document.getElementById('db-sol-geo-wrap').style.display='';
    var gj=((document.getElementById('db-sol-geo-just')||{}).value||'').trim();
    if(!gj){ progShowToast('Informe justificativa para ausência de GPS.','erro'); if(btn){btn.disabled=false;btn.textContent='Enviar ao supervisor';} return; }
    geo.sem_geo_justificativa=gj;
  }
  var fotoUrl=null;
  var file=window._dbSolFotoFile||null;
  if(file&&typeof sbUpload==='function') fotoUrl=await sbUpload(file,'evidencias/solicitacao_campo/'+Date.now()+'_'+file.name);
  var hoje=dataHojeLocal();
  var row={
    data:hoje,equipe_id:_dbEquipe.id,
    veiculo_id:veic?veic.veiculo_id:null,veiculo_slot:veic?veic.veiculo_slot||1:1,
    placa:veic?veic.placa:null,numero_ordem:numeroOrdem,
    sessao_id:(_dbSessao&&_dbSessao.id)||null,
    contrato_id:veic?veic.contrato_id||(_dbEquipe.contrato_id||null):(_dbEquipe.contrato_id||null),
    texto_solicitacao:texto,justificativa:just,prioridade:prioridade,
    status:'pendente_supervisor',
    usuario_solicitante_id:(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.id:null,
    latitude:geo.latitude||null,longitude:geo.longitude||null,
    sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa||null,
    foto_url:fotoUrl
  };
  if(DEMO){
    row.id='demo-sol-'+Date.now();
    _dbSolicitacoesCampo.unshift(row);
  } else {
    var ins=await sbInsert('campo_solicitacoes_materiais',row).catch(function(err){
      console.error('campo_solicitacoes_materiais',err);
      progShowToast('Erro ao enviar solicitação.','erro'); return null;
    });
    if(!ins||!ins[0]){ if(btn){btn.disabled=false;btn.textContent='Enviar ao supervisor';} return; }
    row=ins[0];
    _dbSolicitacoesCampo.unshift(row);
    if(fotoUrl){
      await campoSalvarEvidencia({
        origem_tipo:'solicitacao_campo',origem_id:row.id,foto_url:fotoUrl,
        equipe_id:_dbEquipe.id,veiculo_id:row.veiculo_id,veiculo_slot:row.veiculo_slot,placa:row.placa,
        latitude:geo.latitude,longitude:geo.longitude,sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa,
        tipo_evidencia:'foto_solicitacao'
      });
    }
    if(semGeo){
      await campoCriarAlerta({
        tipo:'sem_geolocalizacao',destinatario:'supervisor',placa:row.placa,
        veiculo_id:row.veiculo_id,veiculo_slot:row.veiculo_slot,
        origem_tipo:'solicitacao_campo',origem_id:row.id,
        mensagem:'Solicitação material '+ (row.placa||'') +' sem geolocalização.',
        severidade:'baixa'
      });
    }
  }
  if(_dbSessao){
    if(!_dbSessao.eventos) _dbSessao.eventos=[];
    _dbSessao.eventos.push({tipo:'📝 Solicitação material',ts:Date.now(),obs:texto.slice(0,80)});
    dbSalvarSessao(); renderDbHistoricoSessao();
  }
  closeModal();
  dbRenderSolicitacoesDiario();
  progShowToast('✅ Solicitação enviada ao supervisor');
}

function renderCampoSolicitacoesMateriais(){
  var pg=document.getElementById('pg-campo-solicitacoes');
  if(!pg) return;
  pg.classList.remove('hidden');
  var lista=document.getElementById('csol-lista');
  var resumo=document.getElementById('csol-resumo');
  if(!lista) return;
  function pintar(){
  var stFil=(document.getElementById('csol-fil-status')||{}).value||'pendente_supervisor';
  var rows=(_dbSolicitacoesCampo||[]).slice().sort(function(a,b){
    return String(b.criado_em||'').localeCompare(String(a.criado_em||''));
  });
  if(stFil) rows=rows.filter(function(s){ return s.status===stFil; });
  if(_gestorContratos&&_gestorContratos.length){
    rows=rows.filter(function(s){
      var eq=(equipes||[]).find(function(e){return e.id===s.equipe_id;});
      return eq&&_gestorContratos.indexOf(eq.contrato_id)>=0;
    });
  }
  if(resumo){
    var pend=(_dbSolicitacoesCampo||[]).filter(function(s){return s.status==='pendente_supervisor';}).length;
    resumo.textContent=pend+' pendente(s) · '+rows.length+' exibida(s)';
  }
  if(!rows.length){
    lista.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa;font-size:13px">Nenhuma solicitação neste filtro.</div>';
    return;
  }
  lista.innerHTML='<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#f5f5f3;text-align:left"><th style="padding:8px">Data</th><th style="padding:8px">Equipe</th><th style="padding:8px">Veículo</th><th style="padding:8px">Prioridade</th><th style="padding:8px">Status</th><th style="padding:8px">Solicitação</th><th style="padding:8px"></th></tr></thead><tbody>'
    +rows.map(function(s){
      var podeAprovar=['pendente_supervisor','ajuste_solicitado'].indexOf(s.status)>=0;
      return '<tr style="border-top:.5px solid #eee">'
        +'<td style="padding:8px;white-space:nowrap">'+fmtD(s.data)+'</td>'
        +'<td style="padding:8px">'+escHtml(_dbNomeEquipeSol(s.equipe_id))+'</td>'
        +'<td style="padding:8px">'+escHtml(s.placa||'—')+(s.numero_ordem?'<div style="font-size:10px;color:#888">OS '+escHtml(s.numero_ordem)+'</div>':'')+'</td>'
        +'<td style="padding:8px">'+escHtml(DB_SOL_PRIORIDADE[s.prioridade]||s.prioridade)+'</td>'
        +'<td style="padding:8px"><span class="bdg '+(s.status==='pendente_supervisor'?'warn':s.status==='rejeitada'?'danger':s.status==='confirmada'?'ok':'info')+'">'+(DB_SOL_STATUS_LABEL[s.status]||s.status)+'</span></td>'
        +'<td style="padding:8px;max-width:220px">'+escHtml((s.texto_solicitacao||'').slice(0,100))+'</td>'
        +'<td style="padding:8px;white-space:nowrap">'+(podeAprovar?'<button class="btn btn-sm" onclick="campoAbrirModalAprovarSolicitacao(\''+s.id+'\')">Analisar</button>':'—')+'</td>'
        +'</tr>';
    }).join('')+'</tbody></table>';
  }
  if(!DEMO){
    lista.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa;font-size:12px">⏳ Carregando...</div>';
    sbFetch('campo_solicitacoes_materiais',{order:'criado_em.desc',filters:['data=gte.'+_diasAtras(14)],limit:400})
      .then(function(rows){ _dbSolicitacoesCampo=rows||[]; pintar(); })
      .catch(function(){ pintar(); });
    return;
  }
  pintar();
}

function campoAbrirModalAprovarSolicitacao(solId){
  var sol=(_dbSolicitacoesCampo||[]).find(function(s){return s.id===solId;});
  if(!sol){ progShowToast('Solicitação não encontrada.','erro'); return; }
  window._campoSolAprovar=sol;
  window._campoSolItensAprovar=[{descricao_material:'',codigo_material:'',quantidade:1,unidade:'UN',material_id:null}];
  var html='<div class="modal-bg"><div class="modal" style="max-width:560px;max-height:92vh;overflow:auto">'
    +'<h3 style="margin-bottom:.25rem">Analisar solicitação</h3>'
    +'<div style="font-size:11px;color:#666;margin-bottom:.75rem">'+escHtml(_dbNomeEquipeSol(sol.equipe_id))+' · '+escHtml(sol.placa||'—')+' · '+(DB_SOL_PRIORIDADE[sol.prioridade]||'')+'</div>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.6rem;margin-bottom:.75rem;font-size:12px">'
    +'<div><b>Solicitação:</b> '+escHtml(sol.texto_solicitacao||'')+'</div>'
    +'<div style="margin-top:4px"><b>Justificativa:</b> '+escHtml(sol.justificativa||'')+'</div>'
    +(sol.numero_ordem?'<div style="margin-top:4px"><b>OS:</b> '+escHtml(sol.numero_ordem)+'</div>':'')
    +'</div>'
    +'<div style="font-size:12px;font-weight:600;margin-bottom:6px">Itens aprovados (estruturar requisição)</div>'
    +'<div id="campo-sol-itens-wrap"></div>'
    +'<button type="button" class="btn" onclick="campoSolAddItemAprovar()" style="font-size:11px;margin:.5rem 0">+ Adicionar item</button>'
    +'<label style="font-size:11px">Motivo rejeição (se rejeitar)</label>'
    +'<textarea id="campo-sol-rejeicao" rows="2" class="inp" style="width:100%;margin-bottom:.75rem;font-size:11px"></textarea>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap">'
    +'<button type="button" class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button type="button" class="btn" onclick="campoRejeitarSolicitacao()" style="flex:1;border-color:#A32D2D;color:#A32D2D">Rejeitar</button>'
    +'<button type="button" class="btn" id="campo-sol-aprovar-btn" onclick="campoAprovarSolicitacao()" style="flex:2;background:#3B6D11;color:#fff">Aprovar e enviar ao almox</button>'
    +'</div></div></div>';
  setModal(html);
  campoRenderItensAprovarSol();
}

function campoRenderItensAprovarSol(){
  var wrap=document.getElementById('campo-sol-itens-wrap');
  if(!wrap) return;
  var itens=window._campoSolItensAprovar||[];
  wrap.innerHTML=itens.map(function(it,i){
    return '<div style="display:grid;grid-template-columns:1fr 80px 56px 50px 28px;gap:4px;align-items:center;margin-bottom:4px">'
      +'<input class="inp" id="csol-it-desc-'+i+'" value="'+escHtml(it.descricao_material||'')+'" placeholder="Material" style="font-size:11px"/>'
      +'<input class="inp" id="csol-it-cod-'+i+'" value="'+escHtml(it.codigo_material||'')+'" placeholder="Código" style="font-size:11px"/>'
      +'<input class="inp" type="number" min="0.0001" step="any" id="csol-it-qtd-'+i+'" value="'+(it.quantidade||1)+'" style="font-size:11px"/>'
      +'<input class="inp" id="csol-it-uni-'+i+'" value="'+escHtml(it.unidade||'UN')+'" style="font-size:11px"/>'
      +'<button type="button" onclick="campoSolRemItemAprovar('+i+')" style="border:none;background:none;color:#A32D2D;cursor:pointer">✕</button>'
      +'</div>';
  }).join('');
}

function campoSolAddItemAprovar(){
  if(!window._campoSolItensAprovar) window._campoSolItensAprovar=[];
  window._campoSolItensAprovar.push({descricao_material:'',codigo_material:'',quantidade:1,unidade:'UN',material_id:null});
  campoRenderItensAprovarSol();
}
function campoSolRemItemAprovar(idx){
  if(!window._campoSolItensAprovar||window._campoSolItensAprovar.length<=1) return;
  window._campoSolItensAprovar.splice(idx,1);
  campoRenderItensAprovarSol();
}

async function campoCriarReservaAlmoxSolicitacao(sol, itens){
  if(!itens||!itens.length) return null;
  if(DEMO){
    var demo={
      id:'arc-sol'+Date.now(),_v2:true,tipo_reserva:'solicitacao_campo_aprovada',
      equipe_id:sol.equipe_id,data:sol.data,data_referencia:sol.data,
      placa:sol.placa,veiculo_id:sol.veiculo_id,veiculo_slot:sol.veiculo_slot||1,
      solicitacao_id:sol.id,os_numero:sol.numero_ordem,status:'Pendente',origem:'solicitacao_campo',
      itens:itens.map(function(it){return {nome:it.descricao_material,codigo:it.codigo_material,qtd:it.quantidade,unidade:it.unidade};}),
      _itens:itens
    };
    _almEntregasCampo.unshift(demo);
    return demo;
  }
  var cab={
    tipo_reserva:'solicitacao_campo_aprovada',equipe_id:sol.equipe_id,
    data_referencia:sol.data,contrato_id:sol.contrato_id||null,
    placa:sol.placa||null,veiculo_id:sol.veiculo_id||null,veiculo_slot:sol.veiculo_slot||1,
    solicitacao_id:sol.id,os_numero:sol.numero_ordem||null,
    status:'Pendente',origem:'solicitacao_campo',escopo:'veiculo',categoria:'material_campo',
    observacoes:((sol.texto_solicitacao||'')+'').slice(0,500)||null
  };
  var ins=await sbInsert('alm_reservas_campo',cab).catch(function(err){ console.error('reserva solicitacao',err); return null; });
  if(!ins||!ins[0]) return null;
  var res=ins[0];
  var rows=itens.map(function(it){
    return {
      reserva_id:res.id,material_id:it.material_id||null,
      codigo_material:(it.codigo_material||'').trim()||null,
      descricao:it.descricao_material,unidade:it.unidade||'UN',categoria:'material_campo',
      quantidade_reservada:it.quantidade,quantidade_repor:it.quantidade,status:'Pendente'
    };
  });
  var ri=await sbInsert('alm_reserva_itens',rows).catch(function(err){ console.warn('itens reserva sol',err); return []; });
  var view=_almReservaToEntrega(res, ri||rows);
  _almEntregasCampo.unshift(view);
  return view;
}

async function campoAprovarSolicitacao(){
  var sol=window._campoSolAprovar;
  if(!sol){ progShowToast('Solicitação inválida.','erro'); return; }
  var n=(window._campoSolItensAprovar||[]).length;
  var itens=[];
  for(var i=0;i<n;i++){
    var desc=((document.getElementById('csol-it-desc-'+i)||{}).value||'').trim();
    var cod=((document.getElementById('csol-it-cod-'+i)||{}).value||'').trim();
    var qtd=parseFloat((document.getElementById('csol-it-qtd-'+i)||{}).value);
    var uni=((document.getElementById('csol-it-uni-'+i)||{}).value||'UN').trim()||'UN';
    if(!desc) continue;
    if(!qtd||qtd<=0){ progShowToast('Quantidade inválida no item '+(i+1)+'.','erro'); return; }
    itens.push({descricao_material:desc,codigo_material:cod||null,quantidade:qtd,unidade:uni,material_id:null});
  }
  if(!itens.length){ progShowToast('Adicione ao menos um item aprovado.','erro'); return; }
  var btn=document.getElementById('campo-sol-aprovar-btn');
  if(btn){ btn.disabled=true; btn.textContent='Aprovando…'; }
  var reserva=await campoCriarReservaAlmoxSolicitacao(sol,itens);
  if(!reserva&&!DEMO){ progShowToast('Erro ao criar requisição no almox.','erro'); if(btn){btn.disabled=false;btn.textContent='Aprovar e enviar ao almox';} return; }
  var supId=(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.id:null;
  if(!DEMO){
    for(var j=0;j<itens.length;j++){
      await sbInsert('campo_solicitacao_material_itens',{
        solicitacao_id:sol.id,material_id:itens[j].material_id,codigo_material:itens[j].codigo_material,
        descricao_material:itens[j].descricao_material,quantidade:itens[j].quantidade,unidade:itens[j].unidade,
        origem:'manual_supervisor',aprovado:true
      });
    }
    await sbUpdate('campo_solicitacoes_materiais',{
      status:'aprovada',supervisor_id:supId,reserva_id:reserva?reserva.id:null,
      atualizado_em:new Date().toISOString()
    },'id=eq.'+sol.id);
  }
  sol.status='aprovada'; sol.supervisor_id=supId; sol.reserva_id=reserva?reserva.id:null;
  closeModal();
  renderCampoSolicitacoesMateriais();
  progShowToast('✅ Solicitação aprovada — card criado no Kanban Almox');
}

async function campoRejeitarSolicitacao(){
  var sol=window._campoSolAprovar;
  if(!sol) return;
  var motivo=((document.getElementById('campo-sol-rejeicao')||{}).value||'').trim();
  if(!motivo){ progShowToast('Informe o motivo da rejeição.','erro'); return; }
  if(!DEMO){
    await sbUpdate('campo_solicitacoes_materiais',{
      status:'rejeitada',motivo_rejeicao:motivo,
      supervisor_id:(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.id:null,
      atualizado_em:new Date().toISOString()
    },'id=eq.'+sol.id);
  }
  sol.status='rejeitada'; sol.motivo_rejeicao=motivo;
  closeModal();
  renderCampoSolicitacoesMateriais();
  dbRenderSolicitacoesDiario();
  progShowToast('Solicitação rejeitada');
}

function dbConfirmarRecebimentoMaterial(solId){
  var sol=(_dbSolicitacoesCampo||[]).find(function(s){return s.id===solId;});
  if(!sol||sol.status!=='entregue'){ progShowToast('Nada pendente para confirmar.','erro'); return; }
  window._dbRecSol=sol;
  var reserva=_almEntregasCampo.find(function(e){return e.id===sol.reserva_id||e.solicitacao_id===sol.id;});
  var its=reserva?_almEntregaItens(reserva):[];
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3>✅ Confirmar recebimento</h3>'
    +'<p style="font-size:11px;color:#666;margin-bottom:.75rem">'+escHtml(sol.placa||'—')+' · materiais entregues pelo almox</p>'
    +'<ul style="font-size:12px;margin:0 0 .75rem 1.2rem;padding:0">'
    +its.map(function(it){return '<li>'+escHtml(it.nome||'—')+' — '+(it.qtd_entregue||it.qtd||'?')+' '+escHtml(it.unidade||'UN')+'</li>';}).join('')
    +'</ul>'
    +'<input type="file" accept="image/*" capture="environment" id="db-rec-foto" style="display:none"/>'
    +'<button type="button" class="btn" id="db-rec-foto-btn" style="width:100%;padding:10px;font-size:12px;border-color:#533AB7;color:#533AB7;margin-bottom:4px">📷 Tirar foto (câmera)</button>'
    +'<div id="db-rec-foto-prev" style="margin-bottom:.75rem"></div>'
    +'<div id="db-rec-geo-wrap" style="display:none;margin-bottom:.75rem">'
    +'<label style="font-size:11px;color:#854F0B">GPS indisponível — justificativa *</label>'
    +'<textarea id="db-rec-geo-just" rows="2" class="inp" style="width:100%;font-size:11px"></textarea></div>'
    +'<label style="font-size:11px;display:flex;gap:6px;margin-bottom:.75rem"><input type="checkbox" id="db-rec-aceite"/> Confirmo o recebimento dos materiais no veículo.</label>'
    +'<div style="display:flex;gap:8px"><button type="button" class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button type="button" class="btn" id="db-rec-salvar-btn" onclick="dbSalvarRecebimentoMaterial()" style="flex:2;background:#3B6D11;color:#fff">Confirmar</button></div>'
    +'</div></div>');
  setTimeout(function(){
    window._dbRecFotoFile=null;
    var inp=document.getElementById('db-rec-foto');
    var btnF=document.getElementById('db-rec-foto-btn');
    if(btnF&&inp){
      btnF.onclick=function(){ inp.click(); };
      inp.onchange=function(e){
        var f=e.target.files&&e.target.files[0]; if(!f) return;
        window._dbRecFotoFile=f;
        var prev=document.getElementById('db-rec-foto-prev');
        if(prev) prev.innerHTML='<img src="'+URL.createObjectURL(f)+'" style="max-width:100%;border-radius:8px;max-height:140px"/>';
        btnF.textContent='📷 Trocar foto';
      };
    }
  },50);
}

async function dbSalvarRecebimentoMaterial(){
  var sol=window._dbRecSol;
  if(!sol){ progShowToast('Solicitação inválida.','erro'); return; }
  var aceite=document.getElementById('db-rec-aceite');
  if(!aceite||!aceite.checked){ progShowToast('Marque a confirmação de recebimento.','erro'); return; }
  var file=window._dbRecFotoFile||null;
  if(!file&&!DEMO){ progShowToast('Foto obrigatória — use a câmera.','erro'); return; }
  var btn=document.getElementById('db-rec-salvar-btn');
  if(btn){ btn.disabled=true; btn.textContent='Salvando…'; }
  var geo=await new Promise(function(resolve){ campoCapturarGeo(resolve); });
  var semGeo=!!geo.sem_geo;
  if(semGeo){
    document.getElementById('db-rec-geo-wrap').style.display='';
    var gj=((document.getElementById('db-rec-geo-just')||{}).value||'').trim();
    if(!gj){ progShowToast('Justificativa GPS obrigatória.','erro'); if(btn){btn.disabled=false;btn.textContent='Confirmar';} return; }
    geo.sem_geo_justificativa=gj;
  }
  var fotoUrl=null;
  if(file&&typeof sbUpload==='function') fotoUrl=await sbUpload(file,'evidencias/recebimento_campo/'+Date.now()+'_'+file.name);
  else if(DEMO) fotoUrl='demo://rec';
  if(!fotoUrl){ progShowToast('Erro ao enviar foto.','erro'); if(btn){btn.disabled=false;btn.textContent='Confirmar';} return; }
  var reserva=_almEntregasCampo.find(function(e){return e.id===sol.reserva_id||e.solicitacao_id===sol.id;});
  var its=reserva?_almEntregaItens(reserva):[];
  var hoje=dataHojeLocal();
  if(!DEMO){
    for(var i=0;i<its.length;i++){
      var it=its[i];
      var qRec=parseFloat(it.qtd_entregue!=null?it.qtd_entregue:(it.qtd_sep!=null?it.qtd_sep:it.qtd))||0;
      if(qRec<=0) continue;
      await sbInsert('campo_recebimentos_materiais',{
        data:hoje,solicitacao_id:sol.id,reserva_id:reserva?reserva.id:null,
        equipe_id:sol.equipe_id,veiculo_id:sol.veiculo_id,veiculo_slot:sol.veiculo_slot||1,placa:sol.placa,
        material_id:it.item_id||null,codigo_material:it.codigo||it.codigo_sap||null,
        descricao_material:it.nome||'—',quantidade_recebida:qRec,unidade:it.unidade||'UN',
        recebido_por:(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.id:null,
        latitude:geo.latitude||null,longitude:geo.longitude||null,
        sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa||null,
        foto_url:fotoUrl
      });
    }
    await sbUpdate('campo_solicitacoes_materiais',{
      status:'confirmada',atualizado_em:new Date().toISOString()
    },'id=eq.'+sol.id);
    if(sol.veiculo_id){
      await sbRpc('fn_campo_recalc_saldo_veiculo',{
        p_veiculo_id:sol.veiculo_id,p_data:hoje,p_veiculo_slot:sol.veiculo_slot||1
      });
    }
    await campoSalvarEvidencia({
      origem_tipo:'recebimento_campo',origem_id:sol.id,foto_url:fotoUrl,
      equipe_id:sol.equipe_id,veiculo_id:sol.veiculo_id,veiculo_slot:sol.veiculo_slot,placa:sol.placa,
      latitude:geo.latitude,longitude:geo.longitude,sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa,
      tipo_evidencia:'confirmacao_recebimento'
    });
  }
  sol.status='confirmada';
  if(_dbSessao){
    if(!_dbSessao.eventos) _dbSessao.eventos=[];
    _dbSessao.eventos.push({tipo:'✅ Recebimento material',ts:Date.now(),obs:sol.placa||''});
    dbSalvarSessao(); renderDbHistoricoSessao();
  }
  closeModal();
  dbRenderSolicitacoesDiario();
  progShowToast('✅ Recebimento confirmado — saldo do veículo atualizado');
}

// ─── F6: Checklist chegada + excedente veículo ─────────────────────────────
function dbGetChecklistChegadaHoje(veic, slot){
  if(!veic||!veic.placa) return null;
  var hoje=dataHojeLocal();
  slot=slot||dbGetVeiculoSlot();
  return (_dbChecklistsCampo||[]).find(function(c){
    return c.tipo==='chegada'&&c.status!=='cancelado'
      &&String(c.data||'').split('T')[0]===hoje
      &&_dbNormPlaca(c.placa)===_dbNormPlaca(veic.placa)
      &&(c.veiculo_slot||1)===slot;
  })||null;
}

function dbVeiculoKitChegadaPendente(){
  if(!_dbSessao||!_dbSessao.login_ts) return false;
  var veic=dbResolverVeiculoDiario();
  if(!veic||!veic.placa||!veic.veiculo_id) return false;
  var kitN=typeof almResolverKitVeiculo==='function'?almResolverKitVeiculo(veic.veiculo_id,veic.tipo_operacional,veic.contrato_id).length:0;
  if(!kitN) return false;
  var chk=dbGetChecklistChegadaHoje(veic,veic.veiculo_slot);
  return !(chk&&['aceito','conferido','divergente'].indexOf(chk.status)>=0);
}

function _dbChkItemStatusChegada(teorico, informada){
  var t=parseFloat(teorico)||0, i=parseFloat(informada);
  if(isNaN(i)) return 'pendente';
  if(Math.abs(i-t)<0.0001) return 'conferido';
  if(i<t) return 'faltando';
  if(i>t) return 'excedente';
  return 'conferido';
}

function _dbWireFotoBtn(inpId, btnId, prevId, storeProp){
  var inp=document.getElementById(inpId);
  var btnF=document.getElementById(btnId);
  var prev=document.getElementById(prevId);
  if(!btnF||!inp) return;
  btnF.onclick=function(){ inp.click(); };
  inp.onchange=function(e){
    var f=e.target.files&&e.target.files[0]; if(!f) return;
    window[storeProp]=f;
    if(prev) prev.innerHTML='<img src="'+URL.createObjectURL(f)+'" style="max-width:100%;border-radius:8px;max-height:120px;margin-top:4px"/>';
    btnF.textContent='📷 Trocar foto';
    btnF.style.borderColor='#3B6D11'; btnF.style.color='#3B6D11';
  };
}

function dbAbrirChecklistChegadaVeiculo(opts){
  opts=opts||{};
  if(!_dbSessao||!_dbSessao.login_ts){ progShowToast('Inicie o turno primeiro.','erro'); return; }
  dbPrepararBaixaMateriais(function(veic, kitRpc){
    _dbEnriquecerVeicFrota(veic).then(function(veicE){
      veic=veicE||veic;
      if(!veic||!veic.placa){ progShowToast('Veículo não identificado.','erro'); return; }
      var kit=dbResolverKitBaixa(veic, kitRpc);
      if(!kit.length){ progShowToast('Kit vazio — nada a declarar na chegada.','erro'); return; }
      var hoje=dataHojeLocal();
      var doneRpc=!DEMO&&veic.veiculo_id
        ? sbRpc('fn_campo_recalc_saldo_veiculo',{p_veiculo_id:veic.veiculo_id,p_data:hoje,p_veiculo_slot:veic.veiculo_slot||1})
        : Promise.resolve();
      doneRpc.then(function(){
        dbCalcularSaldosVeiculoDia(veic, function(saldosMap){
          window._dbChkChegadaVeic=veic;
          window._dbChkChegadaOnComplete=opts.onComplete||null;
          window._dbChkChegadaItens=kit.map(function(k,i){
            var ch=k.material_id||k.codigo_material||k.descricao_material;
            var teor=saldosMap&&saldosMap[ch]!=null?parseFloat(saldosMap[ch]):parseFloat(k.quantidade_basica)||0;
            return {idx:i,kit_linha_id:k.id,material_id:k.material_id||null,
              codigo_material:k.codigo_material||'',descricao_material:k.descricao_material||'—',
              unidade:k.unidade||'UN',saldo_teorico:teor,quantidade_informada:teor};
          });
          var existente=dbGetChecklistChegadaHoje(veic,veic.veiculo_slot);
          var html='<div class="modal-bg"><div class="modal" style="max-width:540px;max-height:92vh;overflow:auto">'
            +'<h3 style="margin-bottom:.5rem">🏁 Checklist chegada — '+veic.placa+'</h3>'
            +'<p style="font-size:11px;color:#888;margin-bottom:.75rem">Declare o saldo restante · compare com saldo teórico do dia'
            +(existente?' · registro: '+existente.status:'')+'</p>'
            +'<div style="max-height:36vh;overflow:auto;margin-bottom:.75rem;border:.5px solid #e0dfd8;border-radius:8px">'
            +'<table style="width:100%;font-size:11px;border-collapse:collapse">'
            +'<thead><tr style="background:#f5f5f3"><th style="padding:6px;text-align:left">Material</th><th style="padding:6px">Teórico</th><th style="padding:6px">Declarado</th></tr></thead><tbody>'
            +window._dbChkChegadaItens.map(function(it){
              return '<tr style="border-top:.5px solid #eee"><td style="padding:5px 6px">'+it.descricao_material
                +'<div style="font-size:9px;color:#999">'+it.codigo_material+'</div></td>'
                +'<td style="padding:5px;text-align:center;font-weight:600;color:#185FA5">'+it.saldo_teorico+' '+it.unidade+'</td>'
                +'<td style="padding:5px;text-align:center"><input type="number" min="0" step="any" id="db-chg-q-'+it.idx+'" value="'+it.quantidade_informada+'" style="width:56px;padding:4px;font-size:11px;border-radius:4px;border:.5px solid #ccc"/></td></tr>';
            }).join('')
            +'</tbody></table></div>'
            +'<label style="font-size:11px">📷 Foto do veículo *</label>'
            +'<input type="file" accept="image/*" capture="environment" id="db-chg-foto-veic" style="display:none"/>'
            +'<button type="button" class="btn" id="db-chg-foto-veic-btn" style="width:100%;padding:10px;font-size:12px;border-color:#533AB7;color:#533AB7;margin:4px 0">📷 Tirar foto veículo</button>'
            +'<div id="db-chg-foto-veic-prev" style="margin-bottom:.5rem"></div>'
            +'<label style="font-size:11px">📷 Foto dos materiais *</label>'
            +'<input type="file" accept="image/*" capture="environment" id="db-chg-foto-mat" style="display:none"/>'
            +'<button type="button" class="btn" id="db-chg-foto-mat-btn" style="width:100%;padding:10px;font-size:12px;border-color:#533AB7;color:#533AB7;margin:4px 0">📷 Tirar foto materiais</button>'
            +'<div id="db-chg-foto-mat-prev" style="margin-bottom:.75rem"></div>'
            +'<div id="db-chg-geo-wrap" style="display:none;margin-bottom:.75rem">'
            +'<label style="font-size:11px;color:#854F0B">GPS indisponível — justificativa *</label>'
            +'<textarea id="db-chg-geo-just" rows="2" class="inp" style="width:100%;font-size:11px"></textarea></div>'
            +'<label style="font-size:11px">Observação</label>'
            +'<textarea id="db-chg-obs" rows="2" class="inp" style="width:100%;font-size:11px;margin-bottom:.75rem"></textarea>'
            +'<label style="font-size:11px;display:flex;gap:6px;margin-bottom:.75rem"><input type="checkbox" id="db-chg-aceite"/> '
            +'Retornei o veículo <b>'+veic.placa+'</b> e declarei os materiais restantes.</label>'
            +'<div style="display:flex;gap:8px"><button type="button" class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
            +'<button type="button" class="btn" id="db-chg-salvar-btn" onclick="dbSalvarChecklistChegadaVeiculo()" style="flex:2;background:#533AB7;color:#fff">Salvar chegada</button></div>'
            +'</div></div>';
          setModal(html);
          setTimeout(function(){
            window._dbChgFotoVeic=null; window._dbChgFotoMat=null;
            _dbWireFotoBtn('db-chg-foto-veic','db-chg-foto-veic-btn','db-chg-foto-veic-prev','_dbChgFotoVeic');
            _dbWireFotoBtn('db-chg-foto-mat','db-chg-foto-mat-btn','db-chg-foto-mat-prev','_dbChgFotoMat');
          },50);
        });
      });
    });
  });
}

async function _dbAtualizarSaldoDeclarado(veic, itensDecl){
  if(DEMO||!veic||!veic.veiculo_id) return;
  var hoje=dataHojeLocal();
  var rows=await sbFetch('campo_veiculo_saldo_dia',{
    filters:['veiculo_id=eq.'+veic.veiculo_id,'data=eq.'+hoje,'veiculo_slot=eq.'+(veic.veiculo_slot||1)],
    limit:200
  }).catch(function(){ return []; });
  for(var i=0;i<itensDecl.length;i++){
    var it=itensDecl[i];
    var row=(rows||[]).find(function(r){
      if(it.material_id&&r.material_id===it.material_id) return true;
      if(it.codigo_material&&r.codigo_material===it.codigo_material) return true;
      return r.descricao_material===it.descricao_material;
    });
    if(!row||!row.id) continue;
    var decl=parseFloat(it.quantidade_informada);
    if(isNaN(decl)) continue;
    var teor=parseFloat(row.saldo_teorico)||0;
    await sbUpdate('campo_veiculo_saldo_dia',{
      saldo_declarado:decl,divergencia:decl-teor,atualizado_em:new Date().toISOString()
    },'id=eq.'+row.id).catch(function(err){ console.warn('saldo_declarado',err); });
  }
}

async function campoCriarReservaExcedenteVeiculo(veic, itensExc, origemOpts){
  if(!itensExc||!itensExc.length) return null;
  if(typeof origemOpts==='string') origemOpts={checklistId:origemOpts};
  origemOpts=origemOpts||{};
  var hoje=dataHojeLocal();
  var equipeId=origemOpts.equipe_id!==undefined?origemOpts.equipe_id:(_dbEquipe?_dbEquipe.id:null);
  var origem=origemOpts.origem||'checklist_chegada';
  var vistoriaId=origemOpts.vistoria_id||null;
  var checklistId=origemOpts.checklistId||null;
  if(vistoriaId&&!DEMO){
    var dupMem=(_almEntregasCampo||[]).find(function(e){
      return e.tipo_reserva==='excedente_veiculo'&&e.vistoria_id===vistoriaId&&e.status!=='Cancelado';
    });
    if(dupMem) return dupMem;
    try{
      var ex=await sbFetch('alm_reservas_campo',{
        filters:['vistoria_id=eq.'+vistoriaId,'tipo_reserva=eq.excedente_veiculo','status=neq.Cancelado'],
        limit:1
      });
      if(ex&&ex[0]){
        var ri=await sbFetch('alm_reserva_itens',{filters:['reserva_id=eq.'+ex[0].id],limit:50}).catch(function(){return [];});
        var view=_almReservaToEntrega(ex[0],ri||[]);
        _almEntregasCampo.unshift(view);
        return view;
      }
    }catch(eDup){ console.warn('dup excedente',eDup); }
  }
  if(DEMO){
    var demo={id:'arc-exc'+Date.now(),_v2:true,tipo_reserva:'excedente_veiculo',status:'Excedente a recolher',
      equipe_id:equipeId,data:hoje,placa:veic.placa,veiculo_id:veic.veiculo_id||veic.id,
      vistoria_id:vistoriaId,
      itens:itensExc.map(function(x){return {nome:x.descricao_material,qtd:x.qtd_excedente,unidade:x.unidade};})};
    _almEntregasCampo.unshift(demo);
    return demo;
  }
  var cab={
    tipo_reserva:'excedente_veiculo',equipe_id:equipeId,data_referencia:hoje,
    contrato_id:veic.contrato_id||(_dbEquipe?_dbEquipe.contrato_id:null),
    placa:veic.placa,veiculo_id:veic.veiculo_id||veic.id,veiculo_slot:veic.veiculo_slot||1,
    vistoria_id:vistoriaId,
    status:'Excedente a recolher',origem:origem,escopo:'veiculo',categoria:'material_campo',
    observacoes:(origem==='vistoria_inicial'?'Excedente vistoria inicial':'Excedente checklist chegada')
      +(checklistId?' · '+checklistId:'')+(vistoriaId?' · vist '+vistoriaId:'')
  };
  var ins=await sbInsert('alm_reservas_campo',cab).catch(function(err){ console.error('excedente reserva',err); return null; });
  if(!ins||!ins[0]) return null;
  var res=ins[0];
  var rows=itensExc.map(function(it){
    return {
      reserva_id:res.id,material_id:it.material_id||null,
      codigo_material:it.codigo_material||null,descricao:it.descricao_material,
      unidade:it.unidade||'UN',categoria:'material_campo',
      quantidade_reservada:it.qtd_excedente,quantidade_repor:it.qtd_excedente,status:'Pendente'
    };
  });
  var ri=await sbInsert('alm_reserva_itens',rows).catch(function(err){ console.warn('excedente itens',err); return []; });
  var view=_almReservaToEntrega(res, ri||rows);
  _almEntregasCampo.unshift(view);
  return view;
}

async function dbSalvarChecklistChegadaVeiculo(){
  var veic=window._dbChkChegadaVeic;
  var itens=window._dbChkChegadaItens||[];
  if(!veic||!itens.length){ progShowToast('Dados inválidos.','erro'); return; }
  var aceite=document.getElementById('db-chg-aceite');
  if(!aceite||!aceite.checked){ progShowToast('Marque o aceite de retorno.','erro'); return; }
  var fVeic=window._dbChgFotoVeic, fMat=window._dbChgFotoMat;
  if((!fVeic||!fMat)&&!DEMO){ progShowToast('Fotos do veículo e dos materiais são obrigatórias.','erro'); return; }
  var btn=document.getElementById('db-chg-salvar-btn');
  if(btn){ btn.disabled=true; btn.textContent='Salvando…'; }
  var geo=await new Promise(function(resolve){ campoCapturarGeo(resolve); });
  var semGeo=!!geo.sem_geo;
  if(semGeo){
    document.getElementById('db-chg-geo-wrap').style.display='';
    var gj=((document.getElementById('db-chg-geo-just')||{}).value||'').trim();
    if(!gj){ progShowToast('Justificativa GPS obrigatória.','erro'); if(btn){btn.disabled=false;btn.textContent='Salvar chegada';} return; }
    geo.sem_geo_justificativa=gj;
  }
  var obs=(document.getElementById('db-chg-obs')||{}).value||'';
  var hoje=dataHojeLocal();
  var fotoVeicUrl=null, fotoMatUrl=null;
  if(fVeic&&typeof sbUpload==='function') fotoVeicUrl=await sbUpload(fVeic,'evidencias/checklist_chegada/veic_'+Date.now()+'.jpg');
  if(fMat&&typeof sbUpload==='function') fotoMatUrl=await sbUpload(fMat,'evidencias/checklist_chegada/mat_'+Date.now()+'.jpg');
  else if(DEMO){ fotoVeicUrl='demo://veic'; fotoMatUrl='demo://mat'; }
  if(!fotoVeicUrl||!fotoMatUrl){ progShowToast('Erro ao enviar fotos.','erro'); if(btn){btn.disabled=false;btn.textContent='Salvar chegada';} return; }
  var hasDivergencia=false, hasExcedente=false;
  var itensExc=[], itensPayload=[];
  itens.forEach(function(it){
    var qEl=document.getElementById('db-chg-q-'+it.idx);
    var qi=qEl?parseFloat(qEl.value):it.quantidade_informada;
    var st=_dbChkItemStatusChegada(it.saldo_teorico, qi);
    if(st!=='conferido') hasDivergencia=true;
    if(st==='excedente'){ hasExcedente=true; itensExc.push({
      material_id:it.material_id,codigo_material:it.codigo_material,descricao_material:it.descricao_material,
      unidade:it.unidade,qtd_excedente:qi-(parseFloat(it.saldo_teorico)||0)
    }); }
    itensPayload.push({
      kit_linha_id:it.kit_linha_id,material_id:it.material_id,codigo_material:it.codigo_material,
      descricao_material:it.descricao_material,unidade:it.unidade,
      quantidade_esperada:it.saldo_teorico,quantidade_informada:isNaN(qi)?null:qi,status_item:st
    });
  });
  var chkRow={
    data:hoje,tipo:'chegada',equipe_id:_dbEquipe.id,veiculo_id:veic.veiculo_id||null,
    veiculo_slot:veic.veiculo_slot||1,placa:veic.placa,sessao_id:(_dbSessao&&_dbSessao.id)||null,
    contrato_id:veic.contrato_id||(_dbEquipe?_dbEquipe.contrato_id:null),
    usuario_id:(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.id:null,
    latitude:geo.latitude||null,longitude:geo.longitude||null,
    sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa||null,
    foto_url:fotoVeicUrl,status:hasDivergencia?'divergente':'aceito',
    kit_incompleto:hasDivergencia&&!hasExcedente,observacao:obs||null,aceite_em:new Date().toISOString()
  };
  var chkId=null;
  if(DEMO){
    chkId='demo-chg-'+Date.now();
    _dbChecklistsCampo.push(Object.assign({id:chkId},chkRow));
  } else {
    var ins=await sbInsert('campo_veiculo_checklists',chkRow).catch(function(err){
      console.error('checklist chegada',err);
      progShowToast('Erro ao salvar — talvez já exista registro do dia.','erro');
      return null;
    });
    if(!ins||!ins[0]){ if(btn){btn.disabled=false;btn.textContent='Salvar chegada';} return; }
    chkId=ins[0].id;
    _dbChecklistsCampo.push(ins[0]);
    for(var i=0;i<itensPayload.length;i++){
      await sbInsert('campo_veiculo_checklist_itens',Object.assign({checklist_id:chkId},itensPayload[i]))
        .catch(function(err){ console.warn('chk chegada item',err); });
    }
    await _dbAtualizarSaldoDeclarado(veic, itensPayload);
    await campoSalvarEvidencia({
      origem_tipo:'checklist_chegada',origem_id:chkId,foto_url:fotoVeicUrl,
      equipe_id:_dbEquipe.id,veiculo_id:veic.veiculo_id,veiculo_slot:veic.veiculo_slot,placa:veic.placa,
      latitude:geo.latitude,longitude:geo.longitude,sem_geo:semGeo,sem_geo_justificativa:geo.sem_geo_justificativa,
      tipo_evidencia:'foto_veiculo',observacao:obs||null
    });
    await campoSalvarEvidencia({
      origem_tipo:'checklist_chegada',origem_id:chkId,foto_url:fotoMatUrl,
      equipe_id:_dbEquipe.id,veiculo_id:veic.veiculo_id,veiculo_slot:veic.veiculo_slot,placa:veic.placa,
      tipo_evidencia:'foto_materiais',observacao:obs||null,sem_geo:semGeo
    });
  }
  if(hasExcedente&&itensExc.length){
    await campoCriarReservaExcedenteVeiculo(veic, itensExc, chkId);
    await campoCriarAlerta({
      tipo:'excedente_veiculo',destinatario:'almoxarifado',severidade:'alta',
      veiculo_id:veic.veiculo_id,veiculo_slot:veic.veiculo_slot,placa:veic.placa,
      origem_tipo:'checklist_chegada',origem_id:chkId,
      mensagem:'Excedente a recolher no veículo '+veic.placa+' (slot '+(veic.veiculo_slot||1)+'). Ver Kanban Almox.'
    });
  }
  if(_dbSessao){
    if(!_dbSessao.eventos) _dbSessao.eventos=[];
    _dbSessao.eventos.push({tipo:'🏁 Checklist chegada',ts:Date.now(),obs:veic.placa+(hasExcedente?' · excedente':'' )});
    dbSalvarSessao(); renderDbHistoricoSessao();
  }
  var cb=window._dbChkChegadaOnComplete;
  closeModal();
  dbRenderAlertaAlmox();
  dbRenderVeiculoKitChecklist();
  dbAtualizarBotoes();
  progShowToast(hasExcedente?'Chegada salva — excedente enviado ao almox':'✅ Checklist de chegada registrado');
  if(typeof cb==='function') cb();
}

function _dbInferirTipoOperacional(v){
  if(!v) return '';
  if((v.tipo_operacional||'').trim()) return String(v.tipo_operacional).trim();
  var txt=(String(v.modelo||'')+' '+String(v.tipo||'')).toLowerCase();
  if(txt.indexOf('fiorino')>=0) return 'Fiorino TMA';
  if(txt.indexOf('moto')>=0) return 'Moto TMA';
  if(txt.indexOf('caminh')>=0||txt.indexOf('cesto')>=0||txt.indexOf('munck')>=0) return 'Cesto Aéreo';
  return '';
}
function dbResolverVeiculoDiario(){
  if(!_dbEquipe) return null;
  var hoje=dataHojeLocal();
  var slot=dbGetVeiculoSlot(), placa='', veiculoId=null, veiculo=null;
  if(_dbSessao){
    if(_dbSessao.veiculo_id) veiculoId=_dbSessao.veiculo_id;
    if(_dbSessao.placa) placa=String(_dbSessao.placa).trim();
    if(_dbSessao.veiculo_slot) slot=parseInt(_dbSessao.veiculo_slot,10)||slot;
  }
  var vp=null;
  if(typeof isMotoDupla==='function'&&isMotoDupla(_dbEquipe)&&slot===2){
    vp=typeof progGetVeiculoB==='function'?progGetVeiculoB(_dbEquipe.id,hoje):null;
  } else {
    vp=typeof progGetVeiculo==='function'?progGetVeiculo(_dbEquipe.id,hoje):null;
  }
  if(vp){
    if(!placa) placa=(vp.placa||'').trim();
    if(!veiculoId) veiculoId=vp.veiculo_id||vp.id||null;
  }
  if(placa){
    veiculo=(frt_veiculos||[]).find(function(v){ return _dbNormPlaca(v.placa)===_dbNormPlaca(placa); });
    if(!veiculo) veiculo=(veiculos||[]).find(function(v){ return _dbNormPlaca(v.placa)===_dbNormPlaca(placa); });
  }
  if(veiculoId&&!veiculo){
    veiculo=(frt_veiculos||[]).find(function(v){return v.id===veiculoId;})
      ||(veiculos||[]).find(function(v){return v.id===veiculoId;});
  }
  if(veiculo){ veiculoId=veiculo.id; if(!placa) placa=veiculo.placa||''; }
  if(!placa) return null;
  var contratoVeic=veiculo&&(veiculo.contrato_id||null);
  var contratoEq=_dbEquipe.contrato_id||null;
  var tipoOp=veiculo?(_dbInferirTipoOperacional(veiculo)||''):'';
  return {
    veiculo_id:veiculoId, placa:placa, veiculo_slot:slot, veiculo:veiculo,
    contrato_id:contratoVeic||contratoEq||null,
    tipo_operacional:tipoOp,
    _tipo_operacional_inferido:veiculo&&tipoOp&&!(veiculo.tipo_operacional||'').trim()
  };
}
function dbGarantirFrotasVeiculos(cb){
  if(DEMO||(frt_veiculos&&frt_veiculos.length)){ if(cb)cb(); return Promise.resolve(); }
  return sbFetch('frotas_veiculos',{filters:['status=neq.Inativo'],order:'placa',limit:3000}).then(function(rows){
    if(rows&&rows.length) frt_veiculos=rows;
    if(cb)cb();
  }).catch(function(){ if(cb)cb(); });
}
async function _dbEnriquecerVeicFrota(veic){
  if(!veic||DEMO) return veic;
  if((veic.tipo_operacional||'').trim()&&veic.veiculo_id&&veic.veiculo) return veic;
  var rows=[];
  if(veic.veiculo_id){
    rows=await sbFetch('frotas_veiculos',{filters:['id=eq.'+veic.veiculo_id],limit:1}).catch(function(){return[];});
  }
  if((!rows||!rows.length)&&veic.placa){
    var np=String(veic.placa).replace(/[-\s]/g,'').toUpperCase();
    var all=await sbFetch('frotas_veiculos',{filters:['status=neq.Inativo'],order:'placa',limit:3000}).catch(function(){return[];});
    rows=(all||[]).filter(function(v){
      return String(v.placa||'').replace(/[-\s]/g,'').toUpperCase()===np;
    });
  }
  if(rows&&rows[0]){
    veic.veiculo_id=rows[0].id;
    veic.placa=rows[0].placa||veic.placa;
    veic.veiculo=rows[0];
    veic.tipo_operacional=_dbInferirTipoOperacional(rows[0]);
    if(rows[0].contrato_id) veic.contrato_id=veic.contrato_id||rows[0].contrato_id;
    if(!(frt_veiculos||[]).find(function(v){return v.id===rows[0].id;})){
      frt_veiculos=frt_veiculos||[];
      frt_veiculos.push(rows[0]);
    }
  } else if(veic.veiculo&&!((veic.tipo_operacional||'').trim())){
    veic.tipo_operacional=_dbInferirTipoOperacional(veic.veiculo);
  }
  return veic;
}
async function dbPrepararBaixaMateriais(cb){
  await Promise.all([
    dbGarantirFrotasVeiculos(),
    new Promise(function(resolve){
      if(typeof almCarregarKitsVeiculo==='function') almCarregarKitsVeiculo(resolve,true);
      else resolve();
    })
  ]);
  var veic=dbResolverVeiculoDiario();
  veic=await _dbEnriquecerVeicFrota(veic);
  var kitRpc=null;
  if(veic){
    var kitLocal=typeof almResolverKitVeiculo==='function'
      ? almResolverKitVeiculo(veic.veiculo_id,veic.tipo_operacional,veic.contrato_id):[];
    if(!kitLocal.length&&!DEMO){
      kitRpc=await sbRpc('fn_alm_resolver_kit_veiculo',{
        p_veiculo_id:veic.veiculo_id||null,
        p_tipo_operacional:(veic.tipo_operacional||'').trim()||null,
        p_contrato_id:veic.contrato_id||null
      });
    }
  }
  if(cb) cb(veic, kitRpc);
}
function dbResolverKitBaixa(veic, kitRpc){
  var local=typeof almResolverKitVeiculo==='function'
    ? almResolverKitVeiculo(veic.veiculo_id,veic.tipo_operacional,veic.contrato_id):[];
  if(local.length) return local;
  if(kitRpc&&kitRpc.length) return kitRpc;
  return [];
}
function _dbBaixaSaldoChave(item){
  return item.material_id||item.codigo_material||item.descricao||item.descricao_material||'';
}
function _dbBaixaSaldoItem(saldosMap, item){
  if(!saldosMap) return null;
  var keys=[item.material_id, item.codigo_material, item.descricao||item.descricao_material].filter(Boolean);
  for(var i=0;i<keys.length;i++){
    if(saldosMap[keys[i]]!=null) return saldosMap[keys[i]];
  }
  return null;
}
async function dbCalcularSaldosVeiculoDia(veic, cb){
  var map={};
  if(!veic||!veic.veiculo_id){ if(cb)cb(map); return map; }
  var hoje=dataHojeLocal();
  if(DEMO){
    (typeof almResolverKitVeiculo==='function'?almResolverKitVeiculo(veic.veiculo_id,veic.tipo_operacional,veic.contrato_id):[]).forEach(function(k){
      var ch=k.material_id||k.codigo_material||k.descricao_material;
      if(ch) map[ch]=parseFloat(k.quantidade_basica)||0;
    });
    if(cb)cb(map); return map;
  }
  var rows=await sbFetch('campo_veiculo_saldo_dia',{
    filters:['veiculo_id=eq.'+veic.veiculo_id,'data=eq.'+hoje,'veiculo_slot=eq.'+(veic.veiculo_slot||1)],
    limit:200
  }).catch(function(){ return []; });
  (rows||[]).forEach(function(s){
    var sal=parseFloat(s.saldo_teorico);
    if(s.material_id) map[s.material_id]=sal;
    if(s.codigo_material) map[s.codigo_material]=sal;
    if(s.descricao_material) map[s.descricao_material]=sal;
  });
  if(cb)cb(map);
  return map;
}
async function dbRegistrarBaixaMaterial(payload){
  var baixaPayload={
    data:payload.data,
    equipe_id:payload.equipe_id,
    veiculo_id:payload.veiculo_id||null,
    veiculo_slot:payload.veiculo_slot||1,
    placa:payload.placa,
    numero_ordem:String(payload.numero_ordem),
    ordem_diario_id:payload.ordem_diario_id||null,
    sessao_id:payload.sessao_id||null,
    contrato_id:payload.contrato_id||null,
    material_id:payload.material_id||null,
    codigo_material:payload.codigo_material||null,
    descricao_material:payload.descricao_material,
    unidade:payload.unidade||'UN',
    quantidade_utilizada:payload.quantidade_utilizada,
    usuario_id:payload.usuario_id||null,
    observacao:payload.observacao||null,
    justificativa_excesso:payload.justificativa_excesso||null,
    status:payload.status||'confirmado'
  };
  if(DEMO){
    var demo=Object.assign({id:'bx'+Date.now()+Math.random().toString(36).slice(2,5)},baixaPayload);
    _campoBaixas.unshift(demo);
    return {baixa:demo,reserva_id:null};
  }
  var res=await sbInsert('campo_baixas_materiais',baixaPayload);
  var baixa=res&&res[0]?res[0]:null;
  if(!baixa) throw new Error('Falha ao gravar baixa');
  var movPayload=_movSapPayloadSanitize({
    encarregado_id:payload.usuario_id,
    nome_enc:(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.nome:'',
    equipe_id:payload.equipe_id,
    ordem_id:String(payload.numero_ordem),
    descricao_mat:payload.descricao_material,
    qtd:payload.quantidade_utilizada,
    unidade:payload.unidade||'UN',
    tipo:'Baixa aplicação',
    data:payload.data,
    status:payload.status==='confirmado'?'Confirmado':'Pendente',
    veiculo_id:payload.veiculo_id,
    placa:payload.placa,
    baixa_id:baixa.id,
    veiculo_slot:payload.veiculo_slot||1
  });
  try{
    var movRes=await sbInsertMovSap(movPayload);
    var movLocal=Object.assign({funcao_operacional:'OS #'+payload.numero_ordem},movPayload);
    if(movRes&&movRes[0]&&movRes[0].id){
      baixa.mov_sap_id=movRes[0].id;
      await sbUpdate('campo_baixas_materiais',{mov_sap_id:movRes[0].id},'id=eq.'+baixa.id);
      mov_sap.unshift(Object.assign({id:movRes[0].id},movLocal));
    } else {
      mov_sap.unshift(Object.assign({id:'mv'+Date.now()},movLocal));
    }
  }catch(e){ console.warn('mov_sap espelho',e); }
  var ref=await sbFetch('campo_baixas_materiais',{filters:['id=eq.'+baixa.id],limit:1}).catch(function(){return[];});
  if(ref&&ref[0]){
    baixa.reserva_reposicao_id=ref[0].reserva_reposicao_id;
    Object.assign(baixa,ref[0]);
  }
  _campoBaixas.unshift(baixa);
  if(typeof _almEntregasCarregado!=='undefined') _almEntregasCarregado=false;
  return {baixa:baixa,reserva_id:baixa.reserva_reposicao_id||null};
}
function _dbAbrirModalBaixaMateriais(veic, osAberta, osEncerradas, saldosMap, kitRpc){
  var kitItens=dbResolverKitBaixa(veic, kitRpc);
  var matsLista=kitItens.map(function(k,i){
    var desc=k.descricao_material||'—';
    var sal=_dbBaixaSaldoItem(saldosMap,{material_id:k.material_id,codigo_material:k.codigo_material,descricao:desc});
    if(sal==null) sal=parseFloat(k.quantidade_basica)||0;
    return {
      idx:i, material_id:k.material_id||null, codigo_material:k.codigo_material||'',
      descricao:desc, unidade:k.unidade||'UN', qtd_kit:parseFloat(k.quantidade_basica)||0, saldo:sal
    };
  });
  var osBanner='';
  if(osAberta){
    osBanner='<div style="background:#E6F1FB;border:.5px solid #185FA5;border-radius:8px;padding:.65rem .85rem;margin-bottom:.75rem;font-size:12px">'
      +'<strong>OS vinculada:</strong> #'+escHtml(String(osAberta.numero_ordem))
      +' <span style="color:#888">(em andamento)</span></div>';
  }else{
    osBanner='<div style="margin-bottom:.75rem">'
      +'<label style="font-size:12px;font-weight:600;display:block;margin-bottom:4px">Ordem de serviço desta baixa <span style="color:#A32D2D">*</span></label>'
      +'<select id="db-mat-os-sel" class="inp" style="width:100%">'
      +'<option value="">— Selecione a OS —</option>'
      +osEncerradas.map(function(o){
        var stLbl={encerrada:'Encerrada',disponivel:'Disponível'}[o.status]||o.status;
        return '<option value="'+escHtml(String(o.numero_ordem))+'">OS #'+escHtml(String(o.numero_ordem))+' ('+stLbl+')</option>';
      }).join('')
      +'</select></div>';
  }
  var veicBanner='<div style="background:#EAF3DE;border:.5px solid #3B6D11;border-radius:8px;padding:.55rem .75rem;margin-bottom:.75rem;font-size:12px">'
    +'<strong>🚗 '+escHtml(veic.placa)+'</strong>'
    +(veic.tipo_operacional?' · '+escHtml(veic.tipo_operacional):'')
    +(veic.veiculo_slot>1?' · slot '+veic.veiculo_slot:'')
    +'</div>';
  var kitAviso=!matsLista.length
    ?'<div style="background:#FEF3E2;border:.5px solid #854F0B;border-radius:8px;padding:.5rem .75rem;margin-bottom:.75rem;font-size:11px;color:#854F0B">'
      +'⚠ Kit não encontrado'
      +(veic.tipo_operacional?' para modelo <b>'+escHtml(veic.tipo_operacional)+'</b>':' — veículo sem <b>modelo operacional</b> em Frotas')
      +(_almVeicKitMateriais.length?' ('+_almVeicKitMateriais.length+' itens cadastrados no sistema)':'')
      +'. Cadastre em Almox → Kits Modelo ou use materiais manuais abaixo.</div>':'';
  var listaHtml=matsLista.length?matsLista.map(function(m,i){
    return '<div style="display:flex;align-items:center;gap:6px;padding:8px 10px;border-bottom:.5px solid #f5f5f3" id="db-mat-row-'+i+'" data-saldo="'+m.saldo+'">'
      +'<input type="checkbox" id="db-mat-chk-'+i+'" style="width:16px;height:16px;cursor:pointer;flex-shrink:0"/>'
      +'<span style="flex:1;font-size:12px;min-width:0" id="db-mat-nome-'+i+'">'+escHtml(m.descricao)
      +(m.codigo_material?'<span style="color:#888;font-size:10px;margin-left:4px">'+escHtml(m.codigo_material)+'</span>':'')
      +'</span>'
      +'<span style="font-size:10px;color:#185FA5;white-space:nowrap" title="Saldo teórico">saldo '+m.saldo+'</span>'
      +'<input type="number" id="db-mat-qtd-'+i+'" min="0.01" step="0.01" value="1" style="width:56px;padding:4px;border:.5px solid #e0dfd8;border-radius:6px;font-size:12px;display:none"/>'
      +'<span id="db-mat-uni-lbl-'+i+'" style="font-size:10px;color:#888;display:none">'+escHtml(m.unidade)+'</span>'
      +'</div>';
  }).join('')
    :'<div style="padding:1rem;text-align:center;color:#aaa;font-size:12px">Nenhum item no kit — adicione manualmente.</div>';
  var html='<div class="modal-bg"><div class="modal" style="max-width:500px">'
    +'<h3>📦 Baixa de Materiais</h3>'
    +veicBanner+osBanner+kitAviso
    +'<div style="font-size:12px;color:#888;margin-bottom:.5rem">Itens do kit do veículo — informe quantidade utilizada na OS:</div>'
    +'<input id="db-mat-busca" class="inp" placeholder="Buscar material..." style="width:100%;margin-bottom:.5rem"/>'
    +'<div id="db-mat-lista" style="max-height:240px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px;margin-bottom:.75rem">'+listaHtml+'</div>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.75rem;margin-bottom:.75rem">'
    +'<div style="font-size:12px;font-weight:500;margin-bottom:.5rem">Material não listado no kit:</div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
    +'<input id="db-mat-novo-nome" class="inp" placeholder="Descrição" style="flex:2;min-width:120px"/>'
    +'<input id="db-mat-novo-qtd" class="inp" type="number" min="0.01" step="0.01" value="1" style="width:64px"/>'
    +'<select id="db-mat-novo-uni" class="inp" style="width:56px"><option>UN</option><option>M</option><option>KG</option><option>PC</option></select>'
    +'<button class="btn btn-pri" id="db-mat-add-btn" style="padding:6px 10px">+</button>'
    +'</div><div id="db-mat-extras" style="margin-top:.5rem;display:flex;flex-wrap:wrap;gap:4px"></div></div>'
    +'<div id="db-mat-just-box" style="display:none;background:#FFF0F0;border:.5px solid #A32D2D;border-radius:8px;padding:.65rem .75rem;margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600;color:#A32D2D">Justificativa — baixa acima do saldo teórico <span style="color:#A32D2D">*</span></label>'
    +'<textarea id="db-mat-just-excesso" class="inp" rows="2" placeholder="Explique o consumo acima do saldo..." style="width:100%;margin-top:4px"></textarea>'
    +'<div style="font-size:10px;color:#888;margin-top:4px">Baixa ficará como <b>aguardando aprovação</b> até supervisor autorizar.</div></div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="db-mat-confirmar" style="flex:1">Registrar baixa</button>'
    +'</div></div></div>';
  setModal(html);
  window._dbBaixaVeic=veic;
  window._dbBaixaMatsLista=matsLista;
  window._dbBaixaSaldos=saldosMap||{};
  window._dbBaixaMatExtras=[];
  setTimeout(function(){ _dbBaixaMatBindModal(osAberta); },80);
}
function _dbBaixaMatChecarExcesso(){
  var lista=window._dbBaixaMatsLista||[];
  var saldos=window._dbBaixaSaldos||{};
  var excesso=false;
  lista.forEach(function(m,i){
    var chk=document.getElementById('db-mat-chk-'+i); if(!chk||!chk.checked) return;
    var qtd=parseFloat((document.getElementById('db-mat-qtd-'+i)||{}).value)||0;
    var sal=m.saldo!=null?m.saldo:_dbBaixaSaldoItem(saldos,m);
    if(sal!=null&&qtd>sal+0.0001) excesso=true;
  });
  (window._dbBaixaMatExtras||[]).forEach(function(ex,i){
    if(ex.saldo!=null&&parseFloat(ex.qtd)>ex.saldo+0.0001) excesso=true;
  });
  var box=document.getElementById('db-mat-just-box');
  if(box) box.style.display=excesso?'block':'none';
  return excesso;
}
function _dbBaixaMatBindModal(osAberta){
  var matsLista=window._dbBaixaMatsLista||[];
  matsLista.forEach(function(m,i){
    var chk=document.getElementById('db-mat-chk-'+i);
    var qtd=document.getElementById('db-mat-qtd-'+i);
    var uni=document.getElementById('db-mat-uni-lbl-'+i);
    if(chk){
      chk.onchange=function(){
        if(qtd) qtd.style.display=chk.checked?'':'none';
        if(uni) uni.style.display=chk.checked?'':'none';
        _dbBaixaMatChecarExcesso();
      };
    }
    if(qtd) qtd.oninput=_dbBaixaMatChecarExcesso;
  });
  var busca=document.getElementById('db-mat-busca');
  if(busca) busca.oninput=function(){
    var q=busca.value.toLowerCase();
    matsLista.forEach(function(m,i){
      var row=document.getElementById('db-mat-row-'+i);
      if(row) row.style.display=(m.descricao||'').toLowerCase().indexOf(q)>=0||(m.codigo_material||'').toLowerCase().indexOf(q)>=0?'flex':'none';
    });
  };
  var btnAdd=document.getElementById('db-mat-add-btn');
  if(btnAdd) btnAdd.onclick=function(){
    var nome=(document.getElementById('db-mat-novo-nome')||{}).value.trim();
    var qtd=(document.getElementById('db-mat-novo-qtd')||{}).value||'1';
    var uni=(document.getElementById('db-mat-novo-uni')||{}).value||'UN';
    if(!nome) return;
    window._dbBaixaMatExtras=window._dbBaixaMatExtras||[];
    window._dbBaixaMatExtras.push({nome:nome,qtd:qtd,uni:uni,saldo:null});
    var extEl=document.getElementById('db-mat-extras');
    if(extEl) extEl.innerHTML=window._dbBaixaMatExtras.map(function(e,i){
      return '<div style="background:#EAF3DE;color:#3B6D11;border-radius:6px;padding:3px 8px;font-size:11px;display:flex;align-items:center;gap:4px">'
        +e.qtd+' '+e.uni+' '+escHtml(e.nome)
        +'<span style="cursor:pointer;color:#A32D2D" onclick="window._dbBaixaMatExtras.splice('+i+',1);this.parentElement.remove();_dbBaixaMatChecarExcesso();">×</span></div>';
    }).join('');
    document.getElementById('db-mat-novo-nome').value='';
    document.getElementById('db-mat-novo-qtd').value='1';
    _dbBaixaMatChecarExcesso();
  };
  var btnConf=document.getElementById('db-mat-confirmar');
  if(btnConf) btnConf.onclick=function(){ _dbBaixaMatConfirmar(osAberta); };
}
async function _dbBaixaMatConfirmar(osAberta){
  var veic=window._dbBaixaVeic;
  var matsLista=window._dbBaixaMatsLista||[];
  if(!veic||!_dbEquipe){ progShowToast('Sessão inválida.','erro'); return; }
  var itens=[];
  matsLista.forEach(function(m,i){
    var chk=document.getElementById('db-mat-chk-'+i);
    if(!chk||!chk.checked) return;
    var qtd=parseFloat((document.getElementById('db-mat-qtd-'+i)||{}).value)||0;
    if(qtd<=0) return;
    itens.push({
      material_id:m.material_id, codigo_material:m.codigo_material||null,
      descricao_material:m.descricao, unidade:m.unidade, quantidade_utilizada:qtd, saldo:m.saldo
    });
  });
  (window._dbBaixaMatExtras||[]).forEach(function(e){
    var qtd=parseFloat(e.qtd)||0;
    if(qtd<=0) return;
    itens.push({material_id:null,codigo_material:null,descricao_material:e.nome,unidade:e.uni,quantidade_utilizada:qtd,saldo:e.saldo});
  });
  if(!itens.length){ progShowToast('Selecione ao menos um material.','erro'); return; }
  var ordemRef=osAberta?String(osAberta.numero_ordem):(document.getElementById('db-mat-os-sel')||{}).value;
  if(!ordemRef){ progShowToast('Selecione a ordem de serviço.','erro'); return; }
  var ordemObj=osAberta||ordens_db.find(function(o){return String(o.numero_ordem)===String(ordemRef);});
  var excesso=_dbBaixaMatChecarExcesso();
  var justExcesso=((document.getElementById('db-mat-just-excesso')||{}).value||'').trim();
  if(excesso&&!justExcesso){
    progShowToast('Informe justificativa — consumo acima do saldo teórico.','erro'); return;
  }
  var btn=document.getElementById('db-mat-confirmar');
  if(btn){ btn.disabled=true; btn.textContent='Salvando...'; }
  var data=dataHojeLocal();
  var uid=(typeof usuarioLogado!=='undefined'&&usuarioLogado)?usuarioLogado.id:null;
  var ok=0, pendentes=0, erros=0;
  try{
    for(var j=0;j<itens.length;j++){
      var it=itens[j];
      var acimaSaldo=it.saldo!=null&&it.quantidade_utilizada>(it.saldo+0.0001);
      var st=acimaSaldo?'aguardando_aprovacao':'confirmado';
      await dbRegistrarBaixaMaterial({
        data:data, equipe_id:_dbEquipe.id,
        veiculo_id:veic.veiculo_id, veiculo_slot:veic.veiculo_slot||1, placa:veic.placa,
        numero_ordem:ordemRef, ordem_diario_id:ordemObj?ordemObj.id:null,
        sessao_id:_dbSessao?_dbSessao.id:null, contrato_id:veic.contrato_id,
        material_id:it.material_id, codigo_material:it.codigo_material,
        descricao_material:it.descricao_material, unidade:it.unidade,
        quantidade_utilizada:it.quantidade_utilizada,
        usuario_id:uid,
        justificativa_excesso:acimaSaldo?justExcesso:null,
        status:st
      });
      if(st==='confirmado') ok++; else pendentes++;
    }
  }catch(e){
    console.error('dbBaixaMat',e); erros++;
    progShowToast('Erro ao registrar baixa — verifique RLS/sql_veiculo_kit_fase0.sql','erro');
    if(btn){ btn.disabled=false; btn.textContent='Registrar baixa'; }
    return;
  }
  var resumo=itens.map(function(it){return it.quantidade_utilizada+' '+it.unidade+' '+it.descricao_material;}).join(' | ');
  dbRegistrarEventoMaterial(ordemRef,resumo,{placa:veic.placa});
  closeModal();
  if(pendentes&&!ok) progShowToast('⏳ '+pendentes+' baixa(s) aguardando aprovação (acima do saldo).');
  else if(pendentes) progShowToast('✅ '+ok+' baixa(s) confirmada(s); '+pendentes+' aguardando aprovação.');
  else progShowToast('✅ Baixa registrada — reposição gerada no Kanban Almox.');
}
function dbBaixarMateriais(){
  if(!_dbSessao||!_dbSessao.login_ts){alert('Inicie o turno primeiro.');return;}
  var osAberta=_dbOsAbertaParaBaixa();
  var osEncerradas=_dbOsEncerradasParaBaixa();
  if(!osAberta&&!osEncerradas.length){
    progShowToast('⚠ Registre ou encerre uma OS antes de baixar materiais.');
    return;
  }
  var veicPre=dbResolverVeiculoDiario();
  if(!veicPre||!veicPre.placa){
    progShowToast('⚠ Veículo não identificado — confira programação do dia ou inicie turno com placa.','erro');
    return;
  }
  progShowToast('Carregando kit do veículo...','info');
  dbPrepararBaixaMateriais(function(veic, kitRpc){
    if(!veic||!veic.placa){
      progShowToast('⚠ Veículo não identificado após carregar frota.','erro'); return;
    }
    dbCalcularSaldosVeiculoDia(veic,function(saldos){
      _dbAbrirModalBaixaMateriais(veic,osAberta,osEncerradas,saldos||{},kitRpc);
    });
  });
}


// ── ORDENS ───────────────────────────────────────────────────────────────────
var MOTIVOS_CANCEL=[
  'Local já estava reestabelecido',
  'Cliente não autorizou serviço',
  'Serviço incompatível com o tipo de equipe',
  'Veículo quebrado',
  'Outros',
];

function dbNovaOrdem(){
  if(!_dbSessao||_dbSessao.logout_ts){alert('Inicie o dia antes de receber ordens.');return;}
  if(_dbOrdemAtual&&_dbOrdemAtual.status==='em_andamento'){alert('Encerre a ordem atual primeiro.');return;}
  setModal('<div class="modal-bg"><div class="modal"><h3>Receber nova ordem</h3>'    +'<div class="fg"><label>Número da ordem (eOrder)</label><input id="db-num-ordem" type="number" style="width:100%;font-size:18px;text-align:center" placeholder="000000"/></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-conf-ordem" style="flex:1;padding:10px">Confirmar</button></div></div></div>');
  document.getElementById('btn-conf-ordem').onclick=function(){
    var num=(document.getElementById('db-num-ordem')||{}).value.trim();
    if(!num)return alert('Informe o número da ordem.');
    var hoje=dataHoje();
    _dbOrdemAtual={id:'ord'+Date.now(),equipe_id:_dbEquipe.id,data:hoje,
      numero_ordem:num,status:'a_caminho',
      eventos:[{tipo:'A caminho',ts:Date.now(),obs:'Deslocando para o local',foto:null}]};
    ordens_db.push(_dbOrdemAtual);
    if(!DEMO){
      sbInsert('ordens_diario',Object.assign({},_dbOrdemAtual,{eventos:JSON.stringify(_dbOrdemAtual.eventos),id:undefined}))
        .then(function(res){
          if(res&&res[0]&&res[0].id){
            // Atualizar com UUID real do banco
            var local=ordens_db.find(function(x){return x.id===_dbOrdemAtual.id;});
            if(local){local.id=res[0].id;}
            _dbOrdemAtual.id=res[0].id;
          }
        }).catch(function(e){console.error('Erro ao inserir ordem:',e);});
    }
    closeModal();
    renderDbOrdemAtual();renderDbOrdensDia();
  };
}

function dbAdicionarEvento(tipo){
  if(!_dbOrdemAtual)return;
  if(tipo==='cancelar'){
    dbCancelarOrdem();return;
  }
  if(tipo==='foto'){
    dbAdicionarFotoOrdem();return;
  }
  _dbOrdemAtual.eventos.push({tipo:tipo,ts:Date.now(),obs:'',foto:null});
  var statusMap={'A caminho':'a_caminho','Chegou_local':'no_local','Inicio_ativ':'em_andamento','Encerramento_ativ':'encerrando','Atividade_encerrada':'encerrada','Equipe_disponivel':'disponivel'};
  if(statusMap[tipo])_dbOrdemAtual.status=statusMap[tipo];
  if(!DEMO)sbUpdate('ordens_diario',{status:_dbOrdemAtual.status,eventos:JSON.stringify(_dbOrdemAtual.eventos)},'id=eq.'+_dbOrdemAtual.id);
  if(tipo==='Equipe_disponivel'){
    _dbOrdemAtual=null;
  }
  renderDbOrdemAtual();renderDbOrdensDia();
}

function dbCancelarOrdem(){
  setModal('<div class="modal-bg"><div class="modal"><h3>Cancelar ordem</h3>'    +'<div class="fg"><label>Motivo do cancelamento</label>'    +'<select id="db-motivo-sel" style="width:100%" onchange="dbMotivoChange()">'    +MOTIVOS_CANCEL.map(function(m){return '<option>'+m+'</option>';}).join('')    +'</select></div>'    +'<div class="fg" id="db-motivo-outro-wrap" style="display:none"><label>Descreva o motivo</label><textarea id="db-motivo-outro" style="width:100%;height:60px"></textarea></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Voltar</button>'    +'<button class="btn" style="border-color:#A32D2D;color:#A32D2D" id="btn-conf-cancel">Confirmar cancelamento</button></div></div></div>');
  document.getElementById('btn-conf-cancel').onclick=function(){
    var sel=document.getElementById('db-motivo-sel');
    var motivo=sel?sel.value:'';
    if(motivo==='Outros'){motivo=(document.getElementById('db-motivo-outro')||{}).value.trim()||'Outros';}
    _dbOrdemAtual.status='cancelada';
    _dbOrdemAtual.motivo_cancel=motivo;
    _dbOrdemAtual.eventos.push({tipo:'Atividade cancelada',ts:Date.now(),obs:motivo,foto:null});
    if(!DEMO)sbUpdate('ordens_diario',{status:'cancelada',motivo_cancel:motivo,eventos:JSON.stringify(_dbOrdemAtual.eventos)},'id=eq.'+_dbOrdemAtual.id);
    _dbOrdemAtual=null;
    closeModal();renderDbOrdemAtual();renderDbOrdensDia();
  };
}

function dbMotivoChange(){
  var sel=document.getElementById('db-motivo-sel');
  var wrap=document.getElementById('db-motivo-outro-wrap');
  if(wrap)wrap.style.display=(sel&&sel.value==='Outros')?'block':'none';
}

function dbAdicionarFotoOrdem(){
  if(!_dbOrdemAtual)return;
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:400px">'
    +'<div class="mh"><span style="font-weight:700">📷 Foto — Ordem '+escHtml(_dbOrdemAtual.numero_ordem)+'</span></div>'
    +'<div style="padding:1rem">'
    // Dois inputs ocultos: câmera e arquivo
    +'<input type="file" id="db-foto-camera" accept="image/*" capture="environment" style="display:none"/>'
    +'<input type="file" id="db-foto-arquivo" accept="image/*" style="display:none"/>'
    // Botões de escolha
    +'<div style="display:flex;gap:10px;margin-bottom:1rem">'
    +'<button class="btn" id="btn-db-usar-camera" style="flex:1;padding:14px;font-size:13px;flex-direction:column;display:flex;align-items:center;gap:4px">📷<br><span style="font-size:11px">Câmera</span></button>'
    +'<button class="btn" id="btn-db-usar-arquivo" style="flex:1;padding:14px;font-size:13px;flex-direction:column;display:flex;align-items:center;gap:4px">📁<br><span style="font-size:11px">Arquivo</span></button>'
    +'</div>'
    +'<div id="db-foto-prev" style="text-align:center;margin:.5rem 0"></div>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="btn-salvar-foto-ord" style="display:none">Salvar foto</button>'
    +'</div></div></div></div>');

  function dbFotoOnChange(f){
    if(!f) return;
    var url=URL.createObjectURL(f);
    document.getElementById('db-foto-prev').innerHTML='<img src="'+url+'" style="max-width:100%;border-radius:8px;max-height:220px"/>';
    var btnSalvar = document.getElementById('btn-salvar-foto-ord');
    if(btnSalvar) btnSalvar.style.display='';
  }
  document.getElementById('db-foto-camera').onchange=function(ev){ dbFotoOnChange(ev.target.files[0]); };
  document.getElementById('db-foto-arquivo').onchange=function(ev){ dbFotoOnChange(ev.target.files[0]); };
  document.getElementById('btn-db-usar-camera').onclick=function(){ document.getElementById('db-foto-camera').click(); };
  document.getElementById('btn-db-usar-arquivo').onclick=function(){ document.getElementById('db-foto-arquivo').click(); };

  document.getElementById('btn-salvar-foto-ord').onclick=async function(){
    var fCamera  = document.getElementById('db-foto-camera').files[0];
    var fArquivo = document.getElementById('db-foto-arquivo').files[0];
    var f = fCamera||fArquivo;
    if(!f){alert('Selecione uma foto.');return;}
    var url='';
    if(isOnline()&&!DEMO){
      // Usar numero_ordem no path se id ainda for local
      var pathId=isUUID(_dbOrdemAtual.id)?_dbOrdemAtual.id:('ordem_'+_dbOrdemAtual.numero_ordem);
      url=await sbUpload(f,'ordens/'+pathId+'/'+Date.now()+'_'+f.name);
    }
    _dbOrdemAtual.eventos.push({tipo:'Foto registrada',ts:Date.now(),obs:'',foto:url||URL.createObjectURL(f)});
    if(!DEMO)sbUpdate('ordens_diario',{eventos:JSON.stringify(_dbOrdemAtual.eventos)},'id=eq.'+_dbOrdemAtual.id);
    closeModal();renderDbOrdemAtual();
    alert('✓ Foto salva!');
  };
}

function renderDbOrdemAtual(){
  var body=document.getElementById('db-ordem-body');
  var acoes=document.getElementById('db-ordem-acoes');
  var badge=document.getElementById('db-ordem-status-badge');
  if(!body||!acoes)return;

  if(_dbOrdemAtual)_dbOrdemAtual.eventos=parseJsonField(_dbOrdemAtual.eventos,[]);
  if(!_dbOrdemAtual||_dbOrdemAtual.status==='encerrada'||_dbOrdemAtual.status==='cancelada'){
    body.innerHTML='<div style="color:#aaa;font-size:12px;text-align:center;padding:.5rem">Nenhuma ordem ativa</div>';
    if(badge){badge.textContent='Sem ordem';badge.className='bdg gray';}
    acoes.innerHTML='';
    var btnNova=document.createElement('button');
    btnNova.className='btn btn-pri';btnNova.style.cssText='width:100%;padding:10px';
    btnNova.textContent='+ Receber nova ordem';btnNova.onclick=dbNovaOrdem;
    acoes.appendChild(btnNova);
    return;
  }

  var stLabel={a_caminho:'A caminho',no_local:'No local',em_andamento:'Em atividade',encerrando:'Encerrando',encerrada:'Encerrada',disponivel:'Disponível',cancelada:'Cancelada'};
  var stCls={a_caminho:'warn',no_local:'warn',em_andamento:'ok',encerrando:'info',encerrada:'teal',disponivel:'teal',cancelada:'danger'};
  if(badge){badge.textContent=stLabel[_dbOrdemAtual.status]||'';badge.className='bdg '+(stCls[_dbOrdemAtual.status]||'gray');}

  var evLabels={Chegou_local:'Chegou no local',Inicio_ativ:'Início das atividades',Encerramento_ativ:'Encerramento das atividades',Atividade_encerrada:'Atividade encerrada',Equipe_disponivel:'Equipe disponível'};
  var evHtml=(_dbOrdemAtual.eventos||[]).map(function(ev){
    var d=new Date(ev.ts);
    var hora=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
    return '<div style="display:flex;gap:8px;align-items:center;padding:5px 0;font-size:12px;border-bottom:.5px solid #f0efe8">'      +'<span style="background:#E6F1FB;color:#185FA5;border-radius:6px;padding:2px 7px;font-size:11px;font-weight:500;white-space:nowrap">'+hora+'</span>'      +'<span>'+(evLabels[ev.tipo]||ev.tipo)+'</span>'      +(ev.foto?'<a href="'+ev.foto+'" target="_blank" style="margin-left:4px">📷</a>':'')      +'</div>';
  }).join('');

  body.innerHTML='<div style="font-size:15px;font-weight:700;color:#185FA5;margin-bottom:.75rem">Ordem #'+_dbOrdemAtual.numero_ordem+'</div>'
    +evHtml
    +(_dbOrdemAtual.observacao
      ? '<div style="margin-top:.5rem;background:#f9f9f7;border-radius:6px;padding:.5rem .75rem;font-size:12px;color:#555">'
        +'<span style="font-weight:600;color:#888;font-size:10px;display:block;margin-bottom:2px">OBSERVAÇÕES</span>'
        +_dbOrdemAtual.observacao
        +'</div>'
      : '');

  // Botões via DOM (sem aspas problemáticas em onclick)
  acoes.innerHTML='';
  function addBtn(txt, cls, fn){
    var b=document.createElement('button');
    b.className='btn '+(cls||'');
    b.style.cssText='width:100%;padding:10px;margin-bottom:6px';
    b.textContent=txt;b.onclick=fn;acoes.appendChild(b);
  }

  if(_dbOrdemAtual.status==='a_caminho'){
    addBtn('📍 Cheguei no local','btn-pri',function(){dbAdicionarEvento('Chegou_local');});
  } else if(_dbOrdemAtual.status==='no_local'){
    // APR obrigatória — verificar se já foi preenchida para esta ordem
    var aprOk=aprs_registradas.some(function(a){
      var os=String(_dbOrdemAtual.numero_ordem);
      return (String(a.ordem_id||'')===os||String(a.numero_os||'')===os)
        &&a.equipe_id===(_dbEquipe?_dbEquipe.id:'');
    });
    // APR: confirmação simples (equipe confirma que preencheu — sem formulário aqui)
    var bApr=document.createElement('button');
    bApr.className='btn';
    bApr.style.cssText='width:100%;padding:9px;margin-bottom:6px;'
      +(aprOk?'border-color:#3B6D11;color:#3B6D11;background:#EAF3DE;':'border-color:#854F0B;color:#854F0B;font-weight:600');
    bApr.textContent=aprOk?'✅ APR preenchida':'📋 Confirmar: APR foi preenchida';
    bApr.onclick=(function(ok){
      return function(){
        if(ok){
          if(!confirm('Desmarcar confirmação da APR?')) return;
          aprs_registradas=aprs_registradas.filter(function(a){
            var os=String(_dbOrdemAtual.numero_ordem);
            return !((String(a.ordem_id||'')===os||String(a.numero_os||'')===os)&&a.equipe_id===(_dbEquipe?_dbEquipe.id:''));
          });
        } else {
          var hojeApr=dataHojeLocal();
          var osNum=String(_dbOrdemAtual.numero_ordem);
          var na={id:gerarUUID(),ordem_id:osNum,numero_os:osNum,equipe_id:_dbEquipe?_dbEquipe.id:'',
            data:hojeApr,tipo:'confirmacao',resultado:'OK',
            confirmado_em:new Date().toISOString(),
            confirmado_por:usuarioLogado?usuarioLogado.nome:''};
          aprs_registradas.push(na);
          if(!DEMO){
            sbInsertAprsRegistradas({
              equipe_id:String(na.equipe_id||''),
              data:hojeApr,
              ordem_id:osNum,
              tipo:'confirmacao',
              resultado:'OK',
              confirmado_em:na.confirmado_em,
              confirmado_por:na.confirmado_por,
              respostas:{tipo:'confirmacao',confirmado_em:na.confirmado_em,confirmado_por:na.confirmado_por}
            }).then(function(res){
              if(res&&res[0]&&res[0].id) na.id=res[0].id;
            }).catch(function(e){ console.warn('aprs_registradas confirmacao',e); });
          }
          progShowToast('✅ APR confirmada como preenchida.');
        }
        dbAtualizarBotoes();
      };
    })(aprOk);
    acoes.appendChild(bApr);

    // Início de atividades — sem bloqueio por APR
    var btnIni=document.createElement('button');
    btnIni.className='btn btn-pri';
    btnIni.style.cssText='width:100%;padding:10px;margin-bottom:6px;';
    btnIni.textContent='▶ Início das atividades';
    btnIni.onclick=function(){ dbAdicionarEvento('Inicio_ativ'); };
    acoes.appendChild(btnIni);
  } else if(_dbOrdemAtual.status==='em_andamento'){
    addBtn('⏹ Encerramento das atividades','btn-pri',function(){dbAdicionarEvento('Encerramento_ativ');});
    addBtn('📷 Adicionar foto','',function(){dbAdicionarEvento('foto');});
  } else if(_dbOrdemAtual.status==='encerrando'){
    addBtn('✓ Atividade encerrada','btn-pri',function(){dbAdicionarEvento('Atividade_encerrada');});
    addBtn('📷 Adicionar foto','',function(){dbAdicionarEvento('foto');});
  } else if(_dbOrdemAtual.status==='encerrada'){
    addBtn('✅ Equipe disponível','btn-pri',function(){dbAdicionarEvento('Equipe_disponivel');});
  }
  var bCancel=document.createElement('button');
  bCancel.className='btn';bCancel.style.cssText='width:100%;padding:8px;border-color:#A32D2D;color:#A32D2D;margin-bottom:0';
  bCancel.textContent='✗ Cancelar ordem';bCancel.onclick=function(){dbAdicionarEvento('cancelar');};
  acoes.appendChild(bCancel);

  // Campo observações — aparece a partir de "em andamento"
  var statusComObs = ['em_andamento','encerrando','encerrada','Equipe_disponivel'];
  if(statusComObs.indexOf(_dbOrdemAtual.status)>=0 || _dbOrdemAtual.observacao){
    var obsDiv = document.createElement('div');
    obsDiv.style.cssText = 'margin-top:4px';
    obsDiv.innerHTML =
      '<div style="font-size:11px;font-weight:600;color:#555;margin-bottom:4px">📝 Observações da OS</div>'
      +'<textarea id="db-obs-texto" placeholder="Descreva o que foi feito, materiais, informações importantes..." '
      +'style="width:100%;min-height:100px;border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem;font-size:13px;resize:vertical;font-family:inherit;box-sizing:border-box">'
      +(_dbOrdemAtual.observacao||'')+'</textarea>'
      +'<div style="display:flex;justify-content:flex-end;margin-top:4px">'
      +'<button onclick="dbSalvarObs()" style="background:#1a1a18;color:#fff;border:none;border-radius:6px;padding:5px 14px;font-size:11px;cursor:pointer">💾 Salvar</button>'
      +'</div>';
    acoes.appendChild(obsDiv);
    // Auto-save ao digitar
    setTimeout(function(){
      var ta = document.getElementById('db-obs-texto');
      if(ta) ta.oninput = dbSalvarObsDebounce;
    }, 50);
  }
}
function renderDbHistoricoSessao(){
  var wrap=document.getElementById('db-historico-sessao');if(!wrap)return;
  if(!_dbSessao||!_dbSessao.eventos||!_dbSessao.eventos.length){
    wrap.innerHTML='<div style="color:#aaa;font-size:12px">Nenhum evento registrado</div>';return;
  }
  var tipoIcon={'Início do dia':'▶','Início do almoço':'🍽','Retorno do almoço':'↩','Encerramento do dia':'■'};
  var tipoCor={'Início do dia':'#3B6D11','Início do almoço':'#854F0B','Retorno do almoço':'#185FA5','Encerramento do dia':'#888'};
  wrap.innerHTML=_dbSessao.eventos.map(function(ev){
    var d=new Date(ev.ts);
    var hora=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
    var icon=tipoIcon[ev.tipo]||'•';
    var cor=tipoCor[ev.tipo]||'#555';
    return '<div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:.5px solid #f0efe8;font-size:12px">'      +'<span style="background:#f9f9f7;border-radius:6px;padding:2px 8px;font-size:11px;font-weight:600;color:#185FA5;white-space:nowrap">'+hora+'</span>'      +'<span style="font-size:14px">'+icon+'</span>'      +'<div><div style="font-weight:500;color:'+cor+'">'+ev.tipo+'</div>'      +(ev.obs?'<div style="font-size:11px;color:#888">'+ev.obs+'</div>':'')      +'</div></div>';
  }).join('');
}

function renderDbOrdensDia(){
  var wrap=document.getElementById('db-ordens-dia');if(!wrap)return;
  if(!_dbEquipe)return;
  var hoje=dataHoje();
  ordens_db.forEach(function(o){o.eventos=parseJsonField(o.eventos,[]);});
  var ords=ordens_db.filter(function(o){return o.equipe_id===_dbEquipe.id&&o.data===hoje;});
  if(!ords.length){wrap.innerHTML='<div style="color:#aaa;font-size:12px">Nenhuma ordem registrada hoje</div>';return;}

  var stLabel={a_caminho:'A caminho',no_local:'No local',em_andamento:'Em atividade',
    encerrando:'Encerrando',encerrada:'Encerrada',disponivel:'Disponível',cancelada:'Cancelada'};
  var stCls={a_caminho:'warn',no_local:'warn',em_andamento:'ok',
    encerrando:'info',encerrada:'teal',disponivel:'teal',cancelada:'danger'};

  // Lista compacta — cada OS em uma linha clicável
  wrap.innerHTML='<div style="display:flex;flex-direction:column;gap:6px">'
    +ords.map(function(o){
      var evs=o.eventos||[];
      var ultimoEv=evs.length?evs[evs.length-1]:null;
      var durTotal='';
      if(evs.length>=2){
        var m=Math.floor((evs[evs.length-1].ts-evs[0].ts)/60000);
        durTotal=m>0?m+'min':'';
      }
      var temFoto=evs.some(function(ev){return ev.foto&&ev.foto.indexOf('blob:')<0;});
      return '<div id="os-item-'+o.id+'" class="os-item-row" style="display:flex;justify-content:space-between;align-items:center;padding:.65rem .85rem;background:#fff;border:.5px solid #e0dfd8;border-radius:10px;cursor:pointer">'
        +'<div style="display:flex;align-items:center;gap:10px">'
        +'<div style="font-weight:700;font-size:14px;color:#185FA5">#'+o.numero_ordem+'</div>'
        +'<div>'
        +(o.endereco?'<div style="font-size:12px;color:#555;max-width:160px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+o.endereco+'</div>':'')
        +(durTotal?'<div style="font-size:11px;color:#aaa">⏱ '+durTotal+'</div>':'')
        +'</div>'
        +'</div>'
        +'<div style="display:flex;align-items:center;gap:6px">'
        +(temFoto?'<span style="font-size:12px">📷</span>':'')
        +'<span class="bdg '+(stCls[o.status]||'gray')+'" style="font-size:11px">'+(stLabel[o.status]||o.status)+'</span>'
        +'<span style="color:#aaa;font-size:14px">›</span>'
        +'</div>'
        +'</div>';
    }).join('')
    +'</div>';

  // Vincular cliques
  ords.forEach(function(o){
    var el=document.getElementById('os-item-'+o.id);
    if(el) el.onclick=function(){ abrirDetalheOrdem(o.id); };
  });
  if(typeof dbAtualizarBotoes==='function') dbAtualizarBotoes();
}

function abrirDetalheOrdem(oid){
  var o=ordens_db.find(function(x){return x.id===oid;});
  if(!o)return;
  var evs=parseJsonField(o.eventos,[]);
  var stLabel={a_caminho:'A caminho',no_local:'No local',em_andamento:'Em atividade',
    encerrando:'Encerrando',encerrada:'Encerrada',disponivel:'Disponível',cancelada:'Cancelada'};
  var stCls={a_caminho:'warn',no_local:'warn',em_andamento:'ok',
    encerrando:'info',encerrada:'teal',disponivel:'teal',cancelada:'danger'};
  var evLabel={'A caminho':'A caminho','Chegou_local':'Chegou no local','Chegou no local':'Chegou no local',
    'Inicio_ativ':'Início das atividades','Início das atividades':'Início das atividades',
    'Encerramento_ativ':'Encerramento das atividades','Encerramento das atividades':'Encerramento das atividades',
    'Atividade_encerrada':'Atividade encerrada','Atividade encerrada':'Atividade encerrada',
    'Equipe_disponivel':'Equipe disponível','Equipe disponível':'Equipe disponível',
    'Atividade cancelada':'Atividade cancelada','Foto registrada':'Foto registrada'};
  var evIcon={'A caminho':'🚗','Chegou_local':'📍','Chegou no local':'📍',
    'Inicio_ativ':'▶','Início das atividades':'▶',
    'Encerramento_ativ':'⏹','Encerramento das atividades':'⏹',
    'Atividade_encerrada':'✓','Atividade encerrada':'✓',
    'Equipe_disponivel':'✅','Equipe disponível':'✅',
    'Atividade cancelada':'✗','Foto registrada':'📷'};
  var evCor={'A caminho':'#854F0B','Chegou_local':'#185FA5','Chegou no local':'#185FA5',
    'Inicio_ativ':'#3B6D11','Início das atividades':'#3B6D11',
    'Encerramento_ativ':'#534AB7','Encerramento das atividades':'#534AB7',
    'Atividade_encerrada':'#3B6D11','Atividade encerrada':'#3B6D11',
    'Equipe_disponivel':'#0F6E56','Equipe disponível':'#0F6E56',
    'Atividade cancelada':'#A32D2D','Foto registrada':'#185FA5'};

  function fmtHora(ts){var d=new Date(ts);return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');}
  function calcDur(ts1,ts2){var m=Math.floor((ts2-ts1)/60000);return m>0?m+'min':'';}

  var durTotal='';
  if(evs.length>=2){
    var totalMin=Math.floor((evs[evs.length-1].ts-evs[0].ts)/60000);
    durTotal=totalMin+'min total';
  }

  var timeline=evs.map(function(ev,i){
    var lbl=evLabel[ev.tipo]||ev.tipo;
    var icon=evIcon[ev.tipo]||evIcon[lbl]||'•';
    var cor=evCor[ev.tipo]||evCor[lbl]||'#555';
    var hora=fmtHora(ev.ts);
    var dur=i>0?calcDur(evs[i-1].ts,ev.ts):'';
    var isFoto=ev.tipo==='Foto registrada';
    var isCancel=ev.tipo==='Atividade cancelada';
    var isLast=i===evs.length-1;
    return '<div style="display:flex;gap:10px;align-items:flex-start;padding:8px 0'+(isLast?'':';border-bottom:.5px solid #f5f5f3')+'">'
      +'<div style="display:flex;flex-direction:column;align-items:center;flex-shrink:0">'
      +'<div style="width:30px;height:30px;border-radius:50%;background:'+(isCancel?'#FCEBEB':isFoto?'#E6F1FB':'#EAF3DE')+';display:flex;align-items:center;justify-content:center;font-size:14px">'+icon+'</div>'
      +(isLast?'':'<div style="width:2px;flex:1;background:#e0dfd8;margin:3px 0;min-height:12px"></div>')
      +'</div>'
      +'<div style="flex:1;padding-bottom:2px">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;gap:4px">'
      +'<span style="font-size:13px;font-weight:600;color:'+cor+'">'+lbl+'</span>'
      +'<div style="display:flex;align-items:center;gap:5px">'
      +(dur?'<span style="font-size:10px;color:#aaa;background:#f5f5f3;padding:1px 5px;border-radius:4px">'+dur+'</span>':'')
      +'<span style="font-size:12px;font-weight:700;color:#185FA5;background:#E6F1FB;padding:2px 8px;border-radius:6px">'+hora+'</span>'
      +'</div></div>'
      +(ev.obs&&ev.obs!==''&&ev.tipo!=='A caminho'?'<div style="font-size:11px;color:#888;margin-top:2px">'+ev.obs+'</div>':'')
      +(isFoto&&ev.foto&&ev.foto.indexOf('blob:')<0
        ?'<img src="'+ev.foto+'" data-src="'+encodeURIComponent(ev.foto)+'" style="width:64px;height:64px;object-fit:cover;border-radius:8px;margin-top:6px;border:.5px solid #e0dfd8;cursor:pointer" title="Clique para ampliar"/>'
        :'')
      +'</div></div>';
  }).join('');

  // Buscar APR desta OS específica
  var aprsOs = aprs_registradas.filter(function(a){
    var os=String(o.numero_ordem);
    return (String(a.ordem_id||'')===os||String(a.numero_os||'')===os)
      && a.equipe_id===(_dbEquipe?_dbEquipe.id:'');
  });

  // Seção observações
  var obsHtml = '<div style="margin-top:1rem;border-top:.5px solid #f0efe8;padding-top:.75rem">'
    +'<div style="font-size:12px;font-weight:600;color:#555;margin-bottom:6px">📝 Observações</div>'
    +'<textarea id="detalhe-obs-txt" style="width:100%;height:90px;border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem;font-size:13px;resize:vertical;font-family:inherit;box-sizing:border-box">'
    +(o.observacao||'')+'</textarea>'
    +'<div style="display:flex;justify-content:flex-end;margin-top:4px">'
    +'<button onclick="dbSalvarObsDetalhe(\''+o.id+'\')" style="background:#1a1a18;color:#fff;border:none;border-radius:6px;padding:5px 14px;font-size:11px;cursor:pointer">💾 Salvar</button>'
    +'</div></div>';

  // Seção APR — formulário completo com fotos
  var aprHtml = '';
  if(aprsOs.length){
    aprHtml = '<div style="margin-top:.75rem;border-top:.5px solid #f0efe8;padding-top:.75rem">'
      +'<div style="font-size:12px;font-weight:600;color:#854F0B;margin-bottom:8px">⚠️ APR Preenchida</div>'
      + aprsOs.map(function(a){
          var resps = parseJsonField(a.respostas||a.itens, []);
          var nok = resps.some(function(r){return r.resposta==='N';});
          return '<div style="background:#FEF9F0;border:.5px solid #F0C87A;border-radius:8px;padding:.75rem;margin-bottom:6px">'
            +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.5rem">'
            +'<span style="font-size:11px;font-weight:700;color:#854F0B">APR — OS #'+o.numero_ordem+'</span>'
            +'<span style="font-size:10px;font-weight:700;color:'+(nok?'#A32D2D':'#3B6D11')+'">'+( nok?'⚠ NOK':'✅ OK')+'</span>'
            +'</div>'
            + resps.map(function(r){
                var respCor = r.resposta==='C'||r.resposta==='Sim'||r.resposta===true ? '#3B6D11'
                  : r.resposta==='N' ? '#A32D2D' : '#888';
                var respLabel = r.resposta==='C'?'✅ Conforme':r.resposta==='N'?'❌ Não conforme':r.resposta==='A'?'— N/A':r.resposta;
                return '<div style="padding:5px 0;border-bottom:.5px solid #f0efe8">'
                  +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
                  +'<span style="font-size:12px;color:#555;flex:1">'+r.pergunta+'</span>'
                  +'<span style="font-size:11px;font-weight:700;color:'+respCor+';white-space:nowrap">'+respLabel+'</span>'
                  +'</div>'
                  +(r.foto?'<img src="'+r.foto+'" style="width:80px;height:60px;object-fit:cover;border-radius:6px;margin-top:4px;border:.5px solid #e0dfd8;cursor:pointer" onclick="window.open(\''+r.foto+'\')"/>':'')
                  +'</div>';
              }).join('')
            +'</div>';
        }).join('')
      +'</div>';
  } else if(o.status==='encerrada'||o.status==='disponivel'){
    aprHtml = '<div style="margin-top:.75rem;border-top:.5px solid #f0efe8;padding-top:.75rem">'
      +'<div style="font-size:11px;color:#aaa;text-align:center;padding:.5rem">Nenhuma APR registrada para esta OS</div>'
      +'</div>';
  }

  var matsOs=(_campoBaixas||[]).filter(function(b){
    return String(b.numero_ordem)===String(o.numero_ordem)
      &&(!_dbEquipe||b.equipe_id===_dbEquipe.id)
      && b.status!=='cancelado';
  });
  if(!matsOs.length){
    matsOs=mov_sap.filter(function(m){
      return m.tipo==='Baixa aplicação'&&_dbMovSapRefereOs(m,o.numero_ordem);
    }).map(function(m){
      return {descricao_material:m.descricao_mat,quantidade_utilizada:m.qtd,unidade:m.unidade,data:m.data,status:'confirmado',_legado:true};
    });
  }
  var matsHtml='';
  if(matsOs.length){
    matsHtml='<div style="margin-top:.75rem;border-top:.5px solid #f0efe8;padding-top:.75rem">'
      +'<div style="font-size:12px;font-weight:600;color:#3B6D11;margin-bottom:8px">📦 Materiais baixados</div>'
      +matsOs.map(function(m){
        var stLbl=m.status==='aguardando_aprovacao'?'<span style="font-size:9px;color:#854F0B;margin-left:4px">⏳ aprovação</span>':'';
        return '<div style="font-size:12px;padding:5px 0;border-bottom:.5px solid #f5f5f3;display:flex;justify-content:space-between;gap:8px">'
          +'<span style="font-weight:500">'+escHtml(m.descricao_material||m.descricao_mat||'')+stLbl+'</span>'
          +'<span style="white-space:nowrap;color:#555">'+Number(m.quantidade_utilizada||m.qtd||0)+' '+(m.unidade||'')
          +(m.data?'<span style="color:#aaa;font-size:10px;margin-left:4px">'+fmtD(m.data)+'</span>':'')
          +'</span></div>';
      }).join('')
      +'</div>';
  }

  setModal(
    '<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem">'
    +'<div>'
    +'<h3 style="margin:0;color:#185FA5">Ordem #'+o.numero_ordem+'</h3>'
    +(o.endereco?'<div style="font-size:12px;color:#888;margin-top:2px">📍 '+o.endereco+'</div>':'')
    +(durTotal?'<div style="font-size:11px;color:#aaa;margin-top:2px">⏱ '+durTotal+'</div>':'')
    +'</div>'
    +'<span class="bdg '+(stCls[o.status]||'gray')+'">'+(stLabel[o.status]||o.status)+'</span>'
    +'</div>'
    +(o.motivo_cancel?'<div style="background:#FCEBEB;border-radius:8px;padding:8px 12px;font-size:12px;color:#A32D2D;margin-bottom:.75rem">✗ '+o.motivo_cancel+'</div>':'')
    +'<div style="max-height:65vh;overflow-y:auto">'
    + timeline
    + matsHtml
    + obsHtml
    + aprHtml
    +'</div>'
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>'
  );
}

// RELATÓRIO DISPONIBILIDADE
function renderRelatorioDisp(cid, mes_ano){
  var eqs=equipes_disp.filter(function(e){return!cid||e.contrato_id===cid;});
  var resultado=eqs.map(function(eq){
    var tipo=tipos_equipe.find(function(t){return t.id===eq.tipo_id;});
    var sessoes=sessoes_disp.filter(function(s){
      return s.equipe_id===eq.id&&(!mes_ano||s.data.indexOf(mes_ano)===0);
    });
    // Meta = 8h por dia × número de dias que a equipe trabalhou
    // (se não trabalhou nenhum dia no mês, usa 22 dias úteis como base)
    var diasTrabalhados = sessoes.length || 22;
    var meta = diasTrabalhados * 8 * 60; // em minutos (8h fixas/dia)
    var totalMin=sessoes.reduce(function(acc,s){return acc+(s.minutos_faturados||0);},0);
    var totalOrdens=ordens_db.filter(function(o){
      return o.equipe_id===eq.id&&(!mes_ano||o.data.indexOf(mes_ano)===0);
    });
    var encerradas=totalOrdens.filter(function(o){return o.status==='encerrada';}).length;
    var canceladas=totalOrdens.filter(function(o){return o.status==='cancelada';}).length;
    var pct=meta>0?Math.round(totalMin/meta*100):0;
    return {eq:eq,tipo:tipo,meta:meta,realMin:totalMin,encerradas:encerradas,canceladas:canceladas,pct:pct};
  });
  return resultado;
}

function abrirRelDisp(){
  var contOpts=contratos.map(function(c){return '<option value="'+c.id+'">'+c.nome+'</option>';}).join('');
  // Gerar opções de meses
  var meses=[];var d=new Date();
  for(var i=0;i<12;i++){
    var y=d.getFullYear();var m=String(d.getMonth()+1).padStart(2,'0');
    meses.push(y+'-'+m);d.setMonth(d.getMonth()-1);
  }
  var mesOpts=meses.map(function(m){return '<option value="'+m+'">'+fmtMesAno(m)+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:700px"><h3>Relatório de Disponibilidade</h3>'    +'<div class="g2" style="margin-bottom:1rem">'    +'<div class="fg"><label>Contrato</label><select id="rel-disp-cont" style="width:100%"><option value="">Todos</option>'+contOpts+'</select></div>'    +'<div class="fg"><label>Mês</label><select id="rel-disp-mes" style="width:100%">'+mesOpts+'</select></div>'    +'</div>'    +'<button class="btn btn-pri" id="btn-gerar-rel-disp" style="width:100%;margin-bottom:1rem">Gerar relatório</button>'    +'<div id="rel-disp-resultado"></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Fechar</button>'    +'<button class="btn" id="btn-impr-disp">🖨 Imprimir / PDF</button></div></div></div>');
  document.getElementById('btn-gerar-rel-disp').onclick=async function(){
    var btn=document.getElementById('btn-gerar-rel-disp');
    if(btn){btn.textContent='Gerando...';btn.disabled=true;}
    var cid=(document.getElementById('rel-disp-cont')||{}).value||'';
    var mes=(document.getElementById('rel-disp-mes')||{}).value||'';
    // Buscar ordens do período no banco (não confiar só no array local)
    if(!DEMO && mes){
      try{
        var ini=mes+'-01';
        var _mp2=mes.split('-');
        var fim=mes+'-'+String(new Date(parseInt(_mp2[0]),parseInt(_mp2[1]),0).getDate()).padStart(2,'0');
        var resOrdens=await sbFetch('ordens_diario',{
          filters:['data=gte.'+ini,'data=lte.'+fim],
          order:'data.desc'
        });
        if(resOrdens&&resOrdens.length){
          resOrdens.forEach(function(o){
            o.eventos=parseJsonField(o.eventos,[]);
            if(!ordens_db.find(function(x){return x.id===o.id;}))
              ordens_db.push(o);
          });
        }
        var resSessoes=await sbFetch('sessoes_disponibilidade',{
          filters:['data=gte.'+ini,'data=lte.'+fim],
          order:'data.desc'
        });
        if(resSessoes&&resSessoes.length){
          resSessoes.forEach(function(s){
            s.eventos=parseJsonField(s.eventos,[]);
            if(!sessoes_disp.find(function(x){return x.id===s.id;}))
              sessoes_disp.push(s);
          });
        }
      }catch(e){console.error('Erro ao buscar dados do período:',e);}
    }
    if(btn){btn.textContent='Gerar relatório';btn.disabled=false;}
    var dados=renderRelatorioDisp(cid,mes);
    var totalH=dados.reduce(function(s,r){return s+r.realMin;},0);
    var totalOrdens=dados.reduce(function(s,r){return s+r.encerradas+r.canceladas;},0);
    var totalEncerradas=dados.reduce(function(s,r){return s+r.encerradas;},0);
    var totalCanceladas=dados.reduce(function(s,r){return s+r.canceladas;},0);
    var html='<div style="overflow-x:auto"><table class="tbl"><thead><tr>'
      +'<th>Equipe</th><th>Tipo</th><th>Meta</th><th>Realizado</th><th>% Meta</th>'
      +'<th>Ordens exec.</th><th>Canceladas</th><th>Total ordens</th>'
      +'</tr></thead><tbody>'
      +dados.map(function(r){
        var cor=r.pct>=90?'#3B6D11':r.pct>=70?'#854F0B':'#A32D2D';
        var hReal=Math.floor(r.realMin/60); var mReal=r.realMin%60;
        var hMeta=Math.round(r.meta/60);
        return '<tr>'
          +'<td style="font-weight:500">'+r.eq.codigo+' — '+r.eq.nome+'</td>'
          +'<td style="font-size:11px">'+(r.tipo?r.tipo.nome:'—')+'</td>'
          +'<td>'+hMeta+'h</td>'
          +'<td>'+String(hReal).padStart(2,'0')+'h '+String(mReal).padStart(2,'0')+'min</td>'
          +'<td style="font-weight:700;color:'+cor+'">'+r.pct+'%</td>'
          +'<td style="font-weight:600;color:#185FA5">'+r.encerradas+'</td>'
          +'<td style="color:#A32D2D">'+r.canceladas+'</td>'
          +'<td style="font-weight:500">'+(r.encerradas+r.canceladas)+'</td>'
          +'</tr>';
      }).join('')
      +'<tr style="background:#f9f9f7;font-weight:700"><td colspan="2">Total</td>'
      +'<td></td><td>'+Math.round(totalH/60)+'h</td><td></td>'
      +'<td style="color:#185FA5">'+totalEncerradas+'</td>'
      +'<td style="color:#A32D2D">'+totalCanceladas+'</td>'
      +'<td>'+(totalEncerradas+totalCanceladas)+'</td></tr>'
      +'</tbody></table></div>';
    var rd=document.getElementById('rel-disp-resultado');if(rd)rd.innerHTML=html;
  };
  document.getElementById('btn-impr-disp').onclick=function(){
    var cont=document.getElementById('rel-disp-resultado');if(!cont)return;
    var w=window.open('','_blank','width=900,height=600');
    if(w){w.document.write('<html><head><meta charset="UTF-8"><title>Relatório Disponibilidade</title><style>body{font-family:Arial,sans-serif;padding:2rem}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:6px 8px;font-size:12px}th{background:#f5f5f3}</style></head><body><h2>Relatório de Disponibilidade</h2>'+cont.innerHTML+'</body></html>');w.document.close();setTimeout(function(){w.print();},400);}
  };
}



