// ═══════════════════════════════════════════════════════════════
// CATÁLOGO DE MATERIAIS
// ═══════════════════════════════════════════════════════════════

var catalogo_materiais = []; // {id, codigo_sap, descricao, categoria, unidade, contratos_ids[], status, obs}

function renderMateriaisVis(){
  var tb = document.getElementById('tbody-materiais-vis'); if(!tb) return;
  var cid = (document.getElementById('mat-fil-cont')||{}).value||'';
  var busca = ((document.getElementById('mat-fil-busca')||{}).value||'').toLowerCase();

  var rows = catalogo_materiais.filter(function(m){
    if(cid){
      var cids = m.contratos_ids||[];
      if(cids.indexOf(cid)<0 && cids.indexOf('todos')<0) return false;
    }
    if(busca && m.descricao.toLowerCase().indexOf(busca)<0 &&
       (m.codigo_sap||'').toLowerCase().indexOf(busca)<0) return false;
    return true;
  });

  if(!rows.length){
    tb.innerHTML='<tr><td colspan="7" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum material encontrado.</td></tr>';
    return;
  }

  tb.innerHTML = rows.map(function(m){
    var cids = m.contratos_ids||[];
    var contNomes = cids.indexOf('todos')>=0
      ? '<span style="background:#1a1a18;color:#fff;border-radius:4px;padding:1px 6px;font-size:10px">Todos</span>'
      : cids.slice(0,3).map(function(cid){
          var c=contratos.find(function(x){return x.id===cid;})||{codigo:'?'};
          return '<span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:10px">'+c.codigo+'</span>';
        }).join(' ')+(cids.length>3?'<span style="font-size:10px;color:#aaa"> +'+( cids.length-3)+'</span>':'');
    return '<tr>'
      +'<td style="font-family:monospace;font-size:12px;font-weight:500">'+(m.codigo_sap||'—')+'</td>'
      +'<td style="font-weight:500">'+m.descricao+'</td>'
      +'<td style="font-size:11px;color:#888">'+(m.categoria||'—')+'</td>'
      +'<td style="font-size:11px">'+(m.unidade||'UN')+'</td>'
      +'<td style="font-size:11px">'+contNomes+'</td>'
      +'<td><span class="bdg '+(m.status==='Ativo'?'ok':'gray')+'">'+(m.status||'Ativo')+'</span></td>'
      +'<td style="display:flex;gap:4px">'
        +'<button class="btn btn-sm" id="edit-mat-'+m.id+'">Editar</button>'
        +'<button class="btn btn-sm" id="dup-mat-'+m.id+'" title="Duplicar" style="color:#185FA5;border-color:#185FA5">⊕</button>'
      +'</td></tr>';
  }).join('');

  // Totalizador
  var foot = document.getElementById('mat-tfoot');
  if(foot) foot.remove();
  var tbl = tb.closest('table');
  if(tbl){
    var tf = document.createElement('tfoot');
    tf.id = 'mat-tfoot';
    tf.innerHTML = '<tr style="background:#f9f9f7">'
      +'<td colspan="7" style="padding:.5rem 1rem;font-size:12px;color:#555">'
      +'<b>'+rows.length+'</b> material'+(rows.length!==1?'is':'')
      +(cid?' neste contrato':' no catálogo')+'</td></tr>';
    tbl.appendChild(tf);
  }

  rows.forEach(function(m){
    var be=document.getElementById('edit-mat-'+m.id);
    if(be)be.onclick=function(){openEditarMaterial(m.id);};
    var bd=document.getElementById('dup-mat-'+m.id);
    if(bd)bd.onclick=function(){duplicarMaterial(m.id);};
  });
}

function openNovoMaterial(){ materialModal(null); }
function openEditarMaterial(id){
  var m=catalogo_materiais.find(function(x){return x.id===id;});
  materialModal(m);
}
function duplicarMaterial(id){
  var m=catalogo_materiais.find(function(x){return x.id===id;});
  if(!m)return;
  var copia=Object.assign({},m,{id:'mat'+Date.now(),codigo_sap:(m.codigo_sap?m.codigo_sap+'-COPIA':''),descricao:m.descricao+' (cópia)'});
  catalogo_materiais.push(copia);
  if(!DEMO)sbInsert('catalogo_materiais',_payloadMat(copia)).then(function(r){if(r&&r[0]&&r[0].id)copia.id=r[0].id;});
  renderMateriaisVis();
}

function _payloadMat(m){
  return {codigo_sap:m.codigo_sap,descricao:m.descricao,categoria:m.categoria,
    unidade:m.unidade,contratos_ids:JSON.stringify(m.contratos_ids||[]),
    status:m.status||'Ativo',obs:m.obs||''};
}

function materialModal(m){
  var cats = ['Cabo/Fio', 'Conector/Terminal', 'Isolamento', 'Estrutura/Suporte', 'Equipamento', 'Ferramenta', 'EPI', 'Sinalização', 'Consumível', 'Iluminação', 'Eletroduto/Conduit', 'Quadro/Painel', 'Outros'];
  var catOpts = cats.map(function(c){return '<option'+(m&&m.categoria===c?' selected':'')+'>'+c+'</option>';}).join('');
  var unOpts = ['UN','M','M²','KG','PC','CX','CJ','GL','PST','VÃO','H','KM','L','T'].map(function(u){
    return '<option'+(m&&m.unidade===u?' selected':'')+'>'+u+'</option>';
  }).join('');

  // Contratos vinculados
  var mCids = m&&m.contratos_ids ? (typeof m.contratos_ids==='string'?JSON.parse(m.contratos_ids):m.contratos_ids) : [];
  var todosMarcado = mCids.indexOf('todos')>=0;

  var contList = contratos.map(function(c){
    var checked = todosMarcado || mCids.indexOf(c.id)>=0;
    return '<label style="display:flex;align-items:center;gap:6px;padding:4px 0;font-size:13px;cursor:pointer">'
      +'<input type="checkbox" class="mat-cont-chk" value="'+c.id+'"'+(checked?' checked':'')+' style="width:15px;height:15px"/>'
      +c.nome+'</label>';
  }).join('');

  var html='<div class="modal-bg"><div class="modal" style="max-width:560px">'
    +'<h3>'+(m?'Editar Material':'Novo Material')+'</h3>'
    +'<div style="display:grid;grid-template-columns:1fr;gap:.75rem;margin-bottom:1rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição *</label>'
    +'<input class="inp" id="mat-desc" style="width:100%" value="'+(m?m.descricao||'':'')+'" placeholder="Ex: Conector perfurante derivação 10/4"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Código SAP</label>'
    +'<input class="inp" id="mat-sap" style="width:100%" value="'+(m?m.codigo_sap||'':'')+'" placeholder="1234567"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Unidade</label>'
    +'<select class="inp" id="mat-un" style="width:100%">'+unOpts+'</select></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Categoria</label>'
    +'<select class="inp" id="mat-cat" style="width:100%">'+catOpts+'</select></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Status</label>'
    +'<select class="inp" id="mat-status" style="width:100%">'
    +'<option'+(m&&m.status==='Inativo'?'':' selected')+'>Ativo</option>'
    +'<option'+(m&&m.status==='Inativo'?' selected':'')+'>Inativo</option>'
    +'</select></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observações</label>'
    +'<input class="inp" id="mat-obs" style="width:100%" value="'+(m?m.obs||'':'')+'" /></div>'
    +'</div>'
    // Contratos vinculados
    +'<div style="margin-bottom:1rem">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.5rem">'
    +'<label style="font-size:11px;font-weight:500">Contratos vinculados *</label>'
    +'<label style="display:flex;align-items:center;gap:5px;font-size:12px;cursor:pointer">'
    +'<input type="checkbox" id="mat-todos-cont"'+(todosMarcado?' checked':'')+' style="width:14px;height:14px" onchange="matToggleTodos(this)"/> Vincular a TODOS os contratos</label>'
    +'</div>'
    +'<div id="mat-cont-lista" style="border:.5px solid #e0dfd8;border-radius:8px;padding:.5rem .75rem;max-height:160px;overflow-y:auto;display:'+(todosMarcado?'none':'')+'">'
    +contList+'</div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="salvar-mat-cat" style="flex:1">'+(m?'Salvar':'Criar material')+'</button>'
    +'</div></div></div>';
  setModal(html);

  setTimeout(function(){
    var btn=document.getElementById('salvar-mat-cat');if(!btn)return;
    btn.onclick=function(){
      var desc=(document.getElementById('mat-desc')||{}).value.trim();
      if(!desc){alert('Informe a descrição.');return;}
      var todos=!!(document.getElementById('mat-todos-cont')||{}).checked;
      var cids=todos?['todos']:Array.from(document.querySelectorAll('.mat-cont-chk:checked')).map(function(c){return c.value;});
      if(!cids.length){alert('Selecione pelo menos um contrato.');return;}
      var payload={
        codigo_sap:(document.getElementById('mat-sap')||{}).value.trim(),
        descricao:desc,
        categoria:(document.getElementById('mat-cat')||{}).value||'Outros',
        unidade:(document.getElementById('mat-un')||{}).value||'UN',
        contratos_ids:cids,
        status:(document.getElementById('mat-status')||{}).value||'Ativo',
        obs:(document.getElementById('mat-obs')||{}).value||''
      };
      if(m){
        var i=catalogo_materiais.findIndex(function(x){return x.id===m.id;});
        if(i>=0)Object.assign(catalogo_materiais[i],payload);
        if(!DEMO)sbUpdate('catalogo_materiais',_payloadMat(payload),'id=eq.'+m.id);
      } else {
        var novo=Object.assign({id:'mat'+Date.now()},payload);
        catalogo_materiais.push(novo);
        if(!DEMO)sbInsert('catalogo_materiais',_payloadMat(novo)).then(function(r){if(r&&r[0]&&r[0].id)novo.id=r[0].id;});
      }
      closeModal();
      renderMateriaisVis();
    };
  },50);
}

function matToggleTodos(chk){
  var lista=document.getElementById('mat-cont-lista');
  if(lista)lista.style.display=chk.checked?'none':'';
}

function carregarCatalogoMateriais(){
  if(DEMO)return Promise.resolve();
  return sbFetch('catalogo_materiais',{order:'descricao'}).then(function(rows){
    if(rows&&rows.length){
      catalogo_materiais=rows.map(function(r){
        r.contratos_ids=typeof r.contratos_ids==='string'?JSON.parse(r.contratos_ids||'[]'):r.contratos_ids||[];
        return r;
      });
    }
  }).catch(function(){});
}


// ═══════════════════════════════════════════════════════════════
// CADASTROS AUXILIARES — Clientes, Tipos de Serviço, Unidades
// ═══════════════════════════════════════════════════════════════

var clientes = [];
var tipos_servico_cad = [];
var unidades_medida = [];

// Unidades padrão pré-carregadas
var UNIDADES_PADRAO = [
  {id:'un-m',   sigla:'M',    nome:'Metro',        descricao:'Metro linear',              status:'Ativo'},
  {id:'un-m2',  sigla:'M²',   nome:'Metro quadrado',descricao:'Metro quadrado de área',   status:'Ativo'},
  {id:'un-un',  sigla:'UN',   nome:'Unidade',      descricao:'Unidade simples',           status:'Ativo'},
  {id:'un-pst', sigla:'PST',  nome:'Poste',        descricao:'Poste instalado',           status:'Ativo'},
  {id:'un-vao', sigla:'VÃO',  nome:'Vão',          descricao:'Vão de linha',              status:'Ativo'},
  {id:'un-cx',  sigla:'CX',   nome:'Caixa',        descricao:'Caixa / embalagem',         status:'Ativo'},
  {id:'un-cj',  sigla:'CJ',   nome:'Conjunto',     descricao:'Conjunto de itens',         status:'Ativo'},
  {id:'un-h',   sigla:'H',    nome:'Hora',         descricao:'Hora de serviço',           status:'Ativo'},
  {id:'un-ed',  sigla:'ED',   nome:'Equipe/Dia',   descricao:'Equipe por dia de trabalho',status:'Ativo'},
  {id:'un-pc',  sigla:'PC',   nome:'Peça',         descricao:'Peça avulsa',               status:'Ativo'},
  {id:'un-kg',  sigla:'KG',   nome:'Quilograma',   descricao:'Peso em quilogramas',       status:'Ativo'},
  {id:'un-gl',  sigla:'GL',   nome:'Global',       descricao:'Valor global/serviço',      status:'Ativo'},
  {id:'un-pnt', sigla:'PNT',  nome:'Ponto',        descricao:'Ponto de ligação',          status:'Ativo'},
  {id:'un-tr',  sigla:'TR',   nome:'Trecho',       descricao:'Trecho de rede',            status:'Ativo'},
];

// ── CLIENTES ─────────────────────────────────────────────────

function renderClientesVis(){
  var tb=document.getElementById('tbody-clientes-vis');if(!tb)return;
  var busca=((document.getElementById('cli-busca')||{}).value||'').toLowerCase();

  var rows=clientes.filter(function(c){
    if(c.ativo===false)return false;
    if(busca&&c.razao_social.toLowerCase().indexOf(busca)<0&&
       (c.nome_fantasia||'').toLowerCase().indexOf(busca)<0&&
       (c.cnpj_cpf||'').indexOf(busca)<0)return false;
    return true;
  });

  if(!rows.length){
    tb.innerHTML='<tr><td colspan="7" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum cliente cadastrado.</td></tr>';
    return;
  }
  tb.innerHTML=rows.map(function(c){
    return '<tr>'
      +'<td data-label="Razão Social" style="font-weight:500">'+c.razao_social+'</td>'
      +'<td data-label="Fantasia" style="font-size:12px;color:#888">'+(c.nome_fantasia||'—')+'</td>'
      +'<td data-label="CNPJ/CPF" style="font-size:12px;font-family:monospace">'+(c.cnpj_cpf||'—')+'</td>'
      +'<td data-label="Cidade" style="font-size:12px">'+(c.cidade||'—')+(c.uf?' / '+c.uf:'')+'</td>'
      +'<td data-label="Contato" style="font-size:12px">'+(c.contato_principal||'—')+'<br>'
        +'<span style="color:#185FA5">'+(c.telefone||'')+'</span></td>'
      +'<td data-label="Status"><span class="bdg '+(c.status==='Ativo'?'ok':'gray')+'">'+(c.status||'Ativo')+'</span></td>'
      +'<td><button class="btn btn-sm" id="edit-cli-'+c.id+'">Editar</button></td>'
      +'</tr>';
  }).join('');

  rows.forEach(function(c){
    var b=document.getElementById('edit-cli-'+c.id);
    if(b)b.onclick=function(){openEditarCliente(c.id);};
  });
}

function openNovoCliente(){ clienteModal(null); }
function openEditarCliente(id){
  var c=clientes.find(function(x){return x.id===id;});
  clienteModal(c);
}

function clienteModal(c){
  var ufs=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
  var html='<div class="modal-bg"><div class="modal" style="max-width:560px">'
    +'<h3>'+(c?'Editar Cliente':'Novo Cliente')+'</h3>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-bottom:1rem">'
    +cliCampo('Razão Social *','cli-razao','text',c?c.razao_social:'','span2')
    +cliCampo('Nome Fantasia','cli-fantasia','text',c?c.nome_fantasia||'':'')
    +cliCampo('CNPJ / CPF','cli-cnpj','text',c?c.cnpj_cpf||'':'')
    +cliCampo('Inscrição Estadual','cli-ie','text',c?c.inscricao_estadual||'':'')
    +cliCampo('Endereço','cli-end','text',c?c.endereco||'':'','span2')
    +cliCampo('Cidade','cli-cidade','text',c?c.cidade||'':'')
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">UF</label>'
    +'<select class="inp" id="cli-uf" style="width:100%">'
    +ufs.map(function(u){return '<option'+(c&&c.uf===u?' selected':'')+'>'+u+'</option>';}).join('')
    +'</select></div>'
    +cliCampo('Contato Principal','cli-contato','text',c?c.contato_principal||'':'')
    +cliCampo('Telefone','cli-tel','text',c?c.telefone||'':'')
    +cliCampo('E-mail','cli-email','email',c?c.email||'':'')
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Status</label>'
    +'<select class="inp" id="cli-status" style="width:100%">'
    +'<option'+(c&&c.status==='Inativo'?'':' selected')+'>Ativo</option>'
    +'<option'+(c&&c.status==='Inativo'?' selected':'')+'>Inativo</option>'
    +'</select></div>'
    +cliCampo('Observações','cli-obs','textarea',c?c.observacoes||'':'','span2')
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="salvar-cli" style="flex:1">'+(c?'Salvar':'Criar')+'</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var btn=document.getElementById('salvar-cli');
    if(!btn)return;
    btn.onclick=function(){
      var g=function(id){return (document.getElementById(id)||{}).value||'';};
      var razao=g('cli-razao').trim();
      if(!razao){alert('Razão social é obrigatória.');return;}
      var payload={razao_social:razao,nome_fantasia:g('cli-fantasia'),
        cnpj_cpf:g('cli-cnpj'),inscricao_estadual:g('cli-ie'),
        endereco:g('cli-end'),cidade:g('cli-cidade'),uf:g('cli-uf'),
        contato_principal:g('cli-contato'),telefone:g('cli-tel'),
        email:g('cli-email'),status:g('cli-status')||'Ativo',
        observacoes:g('cli-obs')};
      if(c){
        var i=clientes.findIndex(function(x){return x.id===c.id;});
        if(i>=0)Object.assign(clientes[i],payload);
        if(!DEMO)sbUpdate('clientes',payload,'id=eq.'+c.id);
      } else {
        var novo=Object.assign({id:'cli'+Date.now()},payload);
        clientes.push(novo);
        if(!DEMO)sbInsert('clientes',payload).then(function(r){if(r&&r[0]&&r[0].id)novo.id=r[0].id;});
      }
      closeModal();
      renderClientesVis();
    };
  },50);
}

function cliCampo(label,id,tipo,val,extra){
  var span=extra==='span2'?'grid-column:span 2':'';
  var inp='';
  if(tipo==='textarea') inp='<textarea class="inp" id="'+id+'" style="width:100%;height:55px">'+(val||'')+'</textarea>';
  else inp='<input type="'+tipo+'" class="inp" id="'+id+'" style="width:100%" value="'+(val||'')+'"/>';
  return '<div style="'+span+'"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">'+label+'</label>'+inp+'</div>';
}

// ── TIPOS DE SERVIÇO ─────────────────────────────────────────

function renderTiposServicoVis(){
  var tb=document.getElementById('tbody-tsv-vis');if(!tb)return;
  var cid=(document.getElementById('tsv-fil-cont')||{}).value||'';
  var busca=((document.getElementById('tsv-busca')||{}).value||'').toLowerCase();

  var rows=tipos_servico_cad.filter(function(t){
    if(cid&&t.contrato_id!==cid)return false;
    if(busca&&t.nome.toLowerCase().indexOf(busca)<0&&(t.codigo||'').indexOf(busca)<0)return false;
    return true;
  });

  if(!rows.length){
    tb.innerHTML='<tr><td colspan="9" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum tipo de serviço cadastrado.</td></tr>';
    return;
  }
  tb.innerHTML=rows.map(function(t){
    var cont=contratos.find(function(c){return c.id===t.contrato_id;})||{codigo:'—'};
    var sim='<span style="color:#3B6D11;font-weight:600">S</span>';
    var nao='<span style="color:#aaa">N</span>';
    return '<tr>'
      +'<td style="font-size:11px"><span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px">'+cont.codigo+'</span></td>'
      +'<td style="font-family:monospace;font-size:12px">'+(t.codigo||'—')+'</td>'
      +'<td style="font-weight:500">'+t.nome+'</td>'
      +'<td style="font-size:11px;color:#888">'+(t.unidade_padrao||'—')+'</td>'
      +'<td style="text-align:center">'+(t.exige_apr?sim:nao)+'</td>'
      +'<td style="text-align:center">'+(t.exige_fotos?sim:nao)+'</td>'
      +'<td style="text-align:center">'+(t.exige_material?sim:nao)+'</td>'
      +'<td><span class="bdg '+(t.status==='Ativo'?'ok':'gray')+'">'+(t.status||'Ativo')+'</span></td>'
      +'<td><button class="btn btn-sm" id="edit-tsv-'+t.id+'">Editar</button></td>'
      +'</tr>';
  }).join('');
  rows.forEach(function(t){
    var b=document.getElementById('edit-tsv-'+t.id);
    if(b)b.onclick=function(){openEditarTipoServico(t.id);};
  });
}

function openNovoTipoServico(){ tipoServicoModal(null); }
function openEditarTipoServico(id){
  var t=tipos_servico_cad.find(function(x){return x.id===id;});
  tipoServicoModal(t);
}

function tipoServicoModal(t){
  var contOpts=contratos.map(function(c){
    return '<option value="'+c.id+'"'+(t&&t.contrato_id===c.id?' selected':'')+'>'+c.nome+'</option>';
  }).join('');
  var unOpts=['','M','M²','UN','PST','VÃO','CX','CJ','H','ED','PC','KG','GL','PNT','TR'].concat(
    unidades_medida.map(function(u){return u.sigla;})
  ).filter(function(v,i,a){return a.indexOf(v)===i;}).map(function(u){
    return '<option'+(t&&t.unidade_padrao===u?' selected':'')+'>'+u+'</option>';
  }).join('');
  var chk=function(id,val){return '<input type="checkbox" id="'+id+'"'+(val?' checked':'')+' style="margin-right:4px"/>';};

  var html='<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3>'+(t?'Editar Tipo de Serviço':'Novo Tipo de Serviço')+'</h3>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-bottom:1rem">'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Contrato *</label>'
    +'<select class="inp" id="tsv-cont" style="width:100%"><option value="">Selecione...</option>'+contOpts+'</select></div>'

    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Nome *</label>'
    +'<input class="inp" id="tsv-nome" style="width:100%" value="'+(t?t.nome||'':'')+'" /></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição</label>'
    +'<textarea class="inp" id="tsv-desc" style="width:100%;height:55px">'+(t?t.descricao||'':'')+'</textarea></div>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.75rem">'
    +'<div style="font-size:11px;font-weight:600;margin-bottom:.5rem;color:#555">Requisitos obrigatórios:</div>'
    +'<div style="display:flex;gap:1.5rem;flex-wrap:wrap;font-size:13px">'
    +'<label>'+chk('tsv-apr',t&&t.exige_apr)+'Exige APR</label>'
    +'<label>'+chk('tsv-fotos',t&&t.exige_fotos)+'Exige fotos</label>'
    +'<label>'+chk('tsv-mat',t&&t.exige_material)+'Exige material</label>'
    +'<label>'+chk('tsv-chk',t&&t.checklist_especifico)+'Checklist específico</label>'
    +'</div></div>'
    +'<input type="hidden" id="tsv-status" value="Ativo">'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="salvar-tsv" style="flex:1">'+(t?'Salvar':'Criar')+'</button>'
    +'</div></div></div>';
  setModal(html);
  // Conectar botão salvar diretamente após setModal
  var btn = document.getElementById('salvar-tsv');
  if(btn){
    btn.onclick = function(){
      var g=function(id){return (document.getElementById(id)||{}).value||'';};
      var gc=function(id){return !!(document.getElementById(id)||{}).checked;};
      var nome=g('tsv-nome').trim();
      var cont=g('tsv-cont');
      if(!nome||!cont){alert('Contrato e nome são obrigatórios.');return;}
      var payload={contrato_id:cont,nome:nome,descricao:g('tsv-desc'),
        exige_apr:gc('tsv-apr'),exige_fotos:gc('tsv-fotos'),
        exige_material:gc('tsv-mat'),checklist_especifico:gc('tsv-chk'),
        status:'Ativo'};
      if(t){
        var i=tipos_servico_cad.findIndex(function(x){return x.id===t.id;});
        if(i>=0)Object.assign(tipos_servico_cad[i],payload);
        if(!DEMO)sbUpdate('tipos_servico_contrato',payload,'id=eq.'+t.id);
      } else {
        var novo=Object.assign({id:'tsv'+Date.now()},payload);
        tipos_servico_cad.push(novo);
        if(!DEMO){
          console.log('[tipoServico] inserindo payload:',JSON.stringify(payload));
          sbInsert('tipos_servico_contrato',payload)
            .then(function(r){
              console.log('[tipoServico] resposta:',JSON.stringify(r));
              if(r&&r[0]&&r[0].id) novo.id=r[0].id;
            })
            .catch(function(e){ console.error('[tipoServico] erro:',e); });
        }
      }
      closeModal();
      renderTiposServicoVis();
    };
  }
}

// ── UNIDADES DE MEDIDA ────────────────────────────────────────

function renderUnidadesVis(){
  var tb=document.getElementById('tbody-unidades-vis');if(!tb)return;
  // Mesclar padrões com cadastradas
  var todas=UNIDADES_PADRAO.concat(unidades_medida.filter(function(u){
    return !UNIDADES_PADRAO.find(function(p){return p.sigla===u.sigla;});
  }));
  tb.innerHTML=todas.map(function(u){
    var padrao=!!UNIDADES_PADRAO.find(function(p){return p.id===u.id;});
    return '<tr>'
      +'<td style="font-family:monospace;font-weight:700;color:#185FA5">'+u.sigla+'</td>'
      +'<td style="font-weight:500">'+u.nome+'</td>'
      +'<td style="font-size:12px;color:#888">'+(u.descricao||'—')+'</td>'
      +'<td><span class="bdg '+(u.status==='Ativo'?'ok':'gray')+'">'+(u.status||'Ativo')+'</span>'
        +(padrao?' <span style="font-size:10px;color:#aaa">(padrão)</span>':'')+'</td>'
      +'<td>'+(padrao?'':('<button class="btn btn-sm" id="edit-un-'+u.id+'">Editar</button>'))+'</td>'
      +'</tr>';
  }).join('');
  unidades_medida.forEach(function(u){
    var b=document.getElementById('edit-un-'+u.id);
    if(b)b.onclick=function(){openEditarUnidade(u.id);};
  });
}

function openNovaUnidade(){ unidadeModal(null); }
function openEditarUnidade(id){
  var u=unidades_medida.find(function(x){return x.id===id;});
  unidadeModal(u);
}
function unidadeModal(u){
  var html='<div class="modal-bg"><div class="modal" style="max-width:380px">'
    +'<h3>'+(u?'Editar Unidade':'Nova Unidade de Medida')+'</h3>'
    +'<div style="display:flex;flex-direction:column;gap:.75rem;margin-bottom:1rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Sigla * (ex: M, UN, PST)</label>'
    +'<input class="inp" id="un-sigla" style="width:100%;text-transform:uppercase" value="'+(u?u.sigla:'')+'" /></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Nome *</label>'
    +'<input class="inp" id="un-nome" style="width:100%" value="'+(u?u.nome:'')+'" /></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição</label>'
    +'<input class="inp" id="un-desc" style="width:100%" value="'+(u?u.descricao||'':'')+'" /></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="salvar-un" style="flex:1">'+(u?'Salvar':'Criar')+'</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var btn=document.getElementById('salvar-un');if(!btn)return;
    btn.onclick=function(){
      var sigla=(document.getElementById('un-sigla')||{}).value.trim().toUpperCase();
      var nome=(document.getElementById('un-nome')||{}).value.trim();
      if(!sigla||!nome){alert('Sigla e nome são obrigatórios.');return;}
      var payload={sigla:sigla,nome:nome,
        descricao:(document.getElementById('un-desc')||{}).value||'',status:'Ativo'};
      if(u){
        var i=unidades_medida.findIndex(function(x){return x.id===u.id;});
        if(i>=0)Object.assign(unidades_medida[i],payload);
        if(!DEMO)sbUpdate('unidades_medida',payload,'id=eq.'+u.id);
      } else {
        var novo=Object.assign({id:'un'+Date.now()},payload);
        unidades_medida.push(novo);
        if(!DEMO)sbInsert('unidades_medida',payload).then(function(r){if(r&&r[0]&&r[0].id)novo.id=r[0].id;});
      }
      closeModal();
      renderUnidadesVis();
    };
  },50);
}

// ── Carregar clientes e tipos de serviço no carregarDados ────
// (chamado separadamente para não bloquear o load principal)
function carregarCadastrosAuxiliares(){
  if(DEMO)return Promise.resolve();
  return Promise.all([
    sbFetch('clientes',{filters:['status=eq.Ativo'],order:'razao_social'}),
    sbFetch('tipos_servico_contrato',{order:'nome'}),
    sbFetch('unidades_medida',{order:'sigla'}),
    sbFetch('catalogo_materiais',{order:'descricao'}),
    sbFetch('status_projetos',{order:'cliente'}),
  ]).then(function(res){
    if(res[0]&&res[0].length) clientes=res[0];
    if(res[1]&&res[1].length) tipos_servico_cad=res[1];
    if(res[2]&&res[2].length) unidades_medida=res[2];
    if(res[3]&&res[3].length){
      catalogo_materiais=res[3].map(function(r){
        r.contratos_ids=typeof r.contratos_ids==='string'?JSON.parse(r.contratos_ids||'[]'):r.contratos_ids||[];
        return r;
      });
    }
    if(res[4]&&res[4].length) status_projetos_db=res[4];
  }).catch(function(){});
}





// ═══════════════════════════════════════════════════════════════
// SALDO SAP — Verificação e Reservas
// ═══════════════════════════════════════════════════════════════

var alm_reservas = []; // reservas por projeto

// ── Saldo SAP por material do projeto ────────────────────────
function sotCarregarDadosSaldoSAP(contId, cb){
  function done(){
    if(typeof almCalcularSaldo==='function') almCalcularSaldo();
    if(cb) cb();
  }
  if(DEMO){ done(); return; }
  var proms = [];
  if(!alm_movimentos.length){
    proms.push(
      (typeof almCarregarMovimentos==='function'
        ? almCarregarMovimentos()
        : sbFetch('alm_movimentos',{order:'criado_em.desc',limit:5000})
      ).then(function(rows){
        if(rows&&rows.length) alm_movimentos = rows;
      }).catch(function(){})
    );
  }
  if(!mat_sap.length){
    proms.push(sbFetch('materiais_sap',{order:'descricao'}).then(function(rows){
      if(rows&&rows.length) mat_sap = rows;
    }).catch(function(){}));
  }
  if(!catalogo_materiais.length){
    proms.push(sbFetch('catalogo_materiais',{order:'descricao'}).then(function(rows){
      if(rows&&rows.length){
        catalogo_materiais = rows.map(function(r){
          r.contratos_ids = typeof r.contratos_ids==='string' ? JSON.parse(r.contratos_ids||'[]') : (r.contratos_ids||[]);
          return r;
        });
      }
    }).catch(function(){}));
  }
  if(!proms.length){ done(); return; }
  Promise.all(proms).then(done).catch(done);
}

function sotCalcularSaldosProjeto(projetoId){
  var mats = sot_materiais_proj.filter(function(m){ return m.projeto_id===projetoId; });
  var proj = sot_projetos.find(function(p){ return p.id===projetoId; });
  var contId = proj ? proj.contrato_id : '';

  if(typeof almCalcularSaldo==='function') almCalcularSaldo();

  var saldoPorSap = {};
  (alm_estoque||[]).forEach(function(e){
    if(contId && e.contrato_id && e.contrato_id!==contId && e.contrato_id!=='geral') return;
    var cod = String(e.codigo_sap||'').trim().toUpperCase();
    if(!cod) return;
    saldoPorSap[cod] = (saldoPorSap[cod]||0) + (Number(e.saldo)||0);
  });
  (mat_sap||[]).forEach(function(m){
    if(contId && m.contrato_id && m.contrato_id!==contId) return;
    var cod = String(m.codigo_sap||'').trim().toUpperCase();
    if(!cod || saldoPorSap[cod]!=null) return;
    saldoPorSap[cod] = Number(m.saldo_disponivel)||0;
  });
  sotBuildListaAlmSAP(contId).forEach(function(item){
    var cod = String(item.codigo_sap||'').trim().toUpperCase();
    if(!cod || saldoPorSap[cod]!=null || item.saldo==null) return;
    saldoPorSap[cod] = Number(item.saldo)||0;
  });
  (alm_reservas||[]).forEach(function(r){
    if(r.status!=='reservado' && r.status!=='separacao') return;
    var cod = String(r.codigo_sap||'').trim().toUpperCase();
    if(!cod || saldoPorSap[cod]==null) return;
    saldoPorSap[cod] -= Number(r.qtd||0);
  });

  return mats.map(function(m){
    var cod = String(m.codigo_sap||'').trim().toUpperCase();
    var saldoDisp = cod && saldoPorSap[cod]!=null ? Math.max(0, saldoPorSap[cod]) : null;
    var qtdNec = Number(m.qtd_projetada)||0;
    var ok = saldoDisp!=null ? saldoDisp >= qtdNec : null;
    var parcial = saldoDisp!=null && saldoDisp > 0 && saldoDisp < qtdNec;
    return {
      mat: m,
      saldoDisp: saldoDisp,
      qtdNec: qtdNec,
      ok: ok,
      parcial: parcial,
      falta: saldoDisp!=null ? Math.max(0, qtdNec - saldoDisp) : null,
      semSaldo: !cod || saldoDisp==null
    };
  });
}

function sotMapSaldosProjeto(projetoId){
  var lista = sotCalcularSaldosProjeto(projetoId);
  var map = {};
  lista.forEach(function(r){ map[r.mat.id] = r; });
  return { lista: lista, map: map };
}

function sotBannerSaldoMateriais(resultado){
  if(!resultado||!resultado.length) return '';
  var comSap = resultado.filter(function(r){ return !r.semSaldo; });
  if(!comSap.length){
    return '<div style="background:#FEF3E2;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem;font-size:12px;color:#854F0B">'
      +'⚠ Nenhum material com <b>código SAP</b> vinculado — edite os materiais e informe o código para consultar estoque.'
      +'</div>';
  }
  var tudoOk = comSap.every(function(r){ return r.ok; });
  var faltando = comSap.filter(function(r){ return !r.ok; }).length;
  if(tudoOk){
    return '<div style="background:#EAF3DE;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">'
      +'<span style="color:#3B6D11;font-weight:600">✅ Estoque SAP suficiente para executar a obra</span>'
      +'<button id="btn-prog-saldo" class="btn btn-pri" style="font-size:11px">Enviar para programação</button>'
      +'</div>';
  }
  return '<div style="background:#FCEBEB;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">'
    +'<span style="color:#A32D2D;font-weight:600">⚠ '+faltando+' material(is) com saldo SAP insuficiente</span>'
    +'<button id="btn-prog-saldo" class="btn" style="font-size:11px;color:#A32D2D;border-color:#A32D2D">Forçar programação</button>'
    +'</div>';
}

function sotRefreshSaldoMateriais(projetoId){
  var proj = sot_projetos.find(function(p){ return p.id===projetoId; });
  var contId = proj ? proj.contrato_id : '';
  var content = document.getElementById('sot-tab-content');
  if(content && window._sotTabAtiva==='materiais'){
    content.innerHTML = '<div style="padding:1.5rem;text-align:center;color:#888">Consultando saldo SAP...</div>';
  }
  sotCarregarDadosSaldoSAP(contId, function(){
    var saldosInfo = sotMapSaldosProjeto(projetoId);
    if(content && window._sotTabAtiva==='materiais'){
      content.innerHTML = sotRenderTabMateriais(projetoId, saldosInfo);
      sotBindBotoesSaldoMateriais(projetoId, saldosInfo.lista);
    }
    progShowToast('✅ Saldo SAP atualizado');
  });
}

function sotBindBotoesSaldoMateriais(projetoId, resultado){
  setTimeout(function(){
    var bv = document.getElementById('btn-verificar-saldo');
    if(bv) bv.onclick = function(){ sotRefreshSaldoMateriais(projetoId); };
    var bp = document.getElementById('btn-prog-saldo');
    if(bp) bp.onclick = function(){ sotEnviarParaProgramacao(projetoId, resultado||[]); };
  }, 50);
}

function sotRenderTabMateriaisComSaldoAuto(projetoId, contentEl){
  var el = contentEl || document.getElementById('sot-tab-content');
  if(!el) return;
  var proj = sot_projetos.find(function(p){ return p.id===projetoId; });
  var contId = proj ? proj.contrato_id : '';
  if(!sot_materiais_proj.filter(function(m){ return m.projeto_id===projetoId; }).length){
    el.innerHTML = sotRenderTabMateriais(projetoId, null);
    return;
  }
  el.innerHTML = '<div style="padding:1.5rem;text-align:center;color:#888">Consultando saldo SAP...</div>';
  sotCarregarDadosSaldoSAP(contId, function(){
    var saldosInfo = sotMapSaldosProjeto(projetoId);
    el.innerHTML = sotRenderTabMateriais(projetoId, saldosInfo);
    sotBindBotoesSaldoMateriais(projetoId, saldosInfo.lista);
  });
}

// ── Verificar saldo dos materiais do projeto ─────────────────
function sotVerificarSaldoMateriais(projetoId){
  var mats = sot_materiais_proj.filter(function(m){return m.projeto_id===projetoId;});
  if(!mats.length){ alert('Nenhum material cadastrado neste projeto.'); return; }
  sotRefreshSaldoMateriais(projetoId);
}

// ── Render da aba materiais com saldos ───────────────────────
function sotRenderTabMateriaisComSaldo(projetoId, resultado){
  if(!resultado||!resultado.length){
    return '<div style="padding:2rem;text-align:center;color:#aaa">Nenhum material cadastrado.</div>';
  }

  var tudoOk = resultado.every(function(r){return r.ok;});
  var algumFalta = resultado.some(function(r){return !r.ok;});

  var banner = tudoOk
    ? '<div style="background:#EAF3DE;border-radius:8px;padding:.6rem .85rem;margin:.75rem;display:flex;align-items:center;justify-content:space-between">'
      +'<span style="color:#3B6D11;font-weight:600">✅ Todos os materiais têm saldo disponível</span>'
      +'<button id="btn-prog-saldo" class="btn btn-pri" style="font-size:12px">Enviar para programação</button>'
      +'</div>'
    : '<div style="background:#FCEBEB;border-radius:8px;padding:.6rem .85rem;margin:.75rem;display:flex;align-items:center;justify-content:space-between">'
      +'<span style="color:#A32D2D;font-weight:600">⚠ '
        +resultado.filter(function(r){return !r.ok;}).length
        +' material(is) sem saldo suficiente</span>'
      +'<button id="btn-prog-saldo" class="btn" style="font-size:12px;color:#A32D2D;border-color:#A32D2D">Forçar programação</button>'
      +'</div>';

  var tabela = '<div style="overflow-x:auto">'
    +'<table class="tbl" style="min-width:700px">'
    +'<thead><tr style="background:#f9f9f7">'
    +'<th>Material</th><th>Cód. SAP</th><th>Un</th>'
    +'<th style="text-align:right">Projetado</th>'
    +'<th style="text-align:right">Saldo SAP</th>'
    +'<th style="text-align:right">Falta</th>'
    +'<th style="text-align:center">Status</th>'
    +'</tr></thead><tbody>'
    + resultado.map(function(r){
        var m = r.mat;
        var corSaldo = r.ok ? '#3B6D11' : r.parcial ? '#854F0B' : '#A32D2D';
        var bgSaldo  = r.ok ? '#EAF3DE' : r.parcial ? '#FEF3E2' : '#FCEBEB';
        var icon = r.ok ? '✅' : r.parcial ? '⚠' : '❌';
        return '<tr>'
          +'<td style="font-weight:500">'+m.descricao+'</td>'
          +'<td style="font-family:monospace;font-size:11px">'+(m.codigo_sap||'—')+'</td>'
          +'<td style="font-size:12px">'+(m.unidade||'UN')+'</td>'
          +'<td style="text-align:right;font-size:12px">'+r.qtdNec+'</td>'
          +'<td style="text-align:right;font-weight:700;font-size:14px;color:'+corSaldo+';background:'+bgSaldo+'">'+r.saldoDisp+'</td>'
          +'<td style="text-align:right;font-size:12px;color:#A32D2D">'+(r.falta>0?r.falta:'-')+'</td>'
          +'<td style="text-align:center;font-size:16px">'+icon+'</td>'
          +'</tr>';
      }).join('')
    +'</tbody></table></div>';

  return banner + tabela;
}

// ── Enviar para programação com validação de saldo ───────────
function sotEnviarParaProgramacao(projetoId, resultado){
  var proj = sot_projetos.find(function(p){return p.id===projetoId;});
  if(!proj) return;

  var tudoOk = !resultado || !resultado.length || resultado.filter(function(r){ return !r.semSaldo; }).every(function(r){ return r.ok; });
  var faltando = resultado ? resultado.filter(function(r){ return !r.semSaldo && !r.ok; }) : [];

  if(tudoOk){
    // Saldo ok — programar direto
    void _sotProgramarProjeto(projetoId, resultado, null);
  } else {
    // Saldo insuficiente — pedir justificativa
    var listaFalta = faltando.map(function(r){
      return r.mat.descricao+': faltam '+r.falta+' '+( r.mat.unidade||'UN');
    }).join('\n');

    var html='<div class="modal-bg"><div class="modal" style="max-width:480px">'
      +'<h3>⚠ Saldo insuficiente</h3>'
      +'<div style="background:#FCEBEB;border-radius:8px;padding:.75rem;margin-bottom:1rem">'
      +'<b style="color:#A32D2D">Materiais sem saldo:</b>'
      +'<div style="margin-top:.5rem;font-size:12px;color:#A32D2D">'
      +faltando.map(function(r){
        return '<div>❌ '+r.mat.descricao+' — faltam <b>'+r.falta+'</b> '+(r.mat.unidade||'UN')+'</div>';
      }).join('')
      +'</div></div>'
      +'<div style="font-size:13px;color:#555;margin-bottom:.75rem">'
      +'Você pode forçar a programação informando a justificativa. Os materiais faltantes entrarão automaticamente como <b>Reserva/Separação</b> no almoxarifado.'
      +'</div>'
      +'<div style="margin-bottom:1rem"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Justificativa *</label>'
      +'<textarea class="inp" id="prog-justif" style="width:100%;height:80px" placeholder="Ex: Material em trânsito, previsão de chegada 25/04. Programação urgente solicitada pelo cliente."></textarea></div>'
      +'<div style="display:flex;gap:8px">'
      +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
      +'<button class="btn" id="btn-forcar-prog" style="flex:1;color:#A32D2D;border-color:#A32D2D">Forçar e reservar</button>'
      +'</div></div></div>';
    setModal(html);
    setTimeout(function(){
      var btn=document.getElementById('btn-forcar-prog');if(!btn)return;
      btn.onclick=async function(){
        var justif=(document.getElementById('prog-justif')||{}).value.trim();
        if(!justif){alert('Informe a justificativa.');return;}
        closeModal();
        await _sotProgramarProjeto(projetoId, resultado, justif);
      };
    },50);
  }
}

async function _sotProgramarProjeto(projetoId, resultado, justificativa){
  var proj = sot_projetos.find(function(p){return p.id===projetoId;});
  if(!proj)return;

  // Alterar status para Programado
  var stAnterior = proj.status;
  proj.status = 'Programado';
  if(!DEMO){
    sbUpdate('sot_projetos',{status:'Programado',atualizado_em:new Date().toISOString()},'id=eq.'+projetoId);
    sbInsert('sot_projetos_historico',{
      projeto_id:projetoId,status_anterior:stAnterior,status_novo:'Programado',
      obs:justificativa?'Forçado: '+justificativa:'Saldo verificado e aprovado',
      usuario:usuarioLogado?usuarioLogado.nome:''
    });
  }

  // Reservar TODOS os materiais do projeto no almoxarifado
  var totalReservados = 0;
  var totalPendentes = 0;
  if(resultado && resultado.length){
    for(var r of resultado){
      if(!r.qtdNec || r.qtdNec <= 0) continue; // ignorar sem quantidade

      // Verificar se já existe reserva para este material/projeto
      var jaReservado = alm_movimentos.some(function(m){
        return (m.status==='reservado'||m.status==='reservado_pendente'||m.status==='separacao')
          && m.projeto_id===projetoId
          && (m.material_id===r.mat.material_id || m.material_desc===r.mat.descricao);
      });
      if(jaReservado) continue;

      var temSaldo = r.ok; // true = saldo disponível, false = faltando
      var reserva = {
        id:'res'+Date.now()+Math.random().toString(36).substr(2,5),
        tipo:'saida',
        status: temSaldo ? 'reservado' : 'reservado_pendente',
        material_id:r.mat.material_id||'',
        material_desc:r.mat.descricao,
        codigo_sap:r.mat.codigo_sap||'',
        unidade:r.mat.unidade||'UN',
        contrato_id:proj.contrato_id||'',
        qtd:r.qtdNec,
        qtd_disponivel:Math.min(r.saldoDisp, r.qtdNec),
        qtd_faltante:r.falta,
        qtd_aplicada:0, qtd_devolvida:0,
        data:dataHojeLocal(),
        projeto_id:projetoId, projeto_nome:proj.nome,
        os_ref:'RESERVA - '+proj.nome,
        obs: temSaldo
          ? 'Reserva automática — saldo disponível'
          : 'Reserva pendente — faltam '+r.falta+' '+r.mat.unidade
            +(justificativa?' | Justificativa: '+justificativa:''),
        registrado_por:usuarioLogado?usuarioLogado.nome:'',
        criado_em:new Date().toISOString()
      };
      var okReserva = await almSalvarMovimentoSeguro(reserva);
      if(!okReserva) continue;
      if(temSaldo) totalReservados++;
      else totalPendentes++;
    }
  }

  // Toast de confirmação
  var msg = '✅ Projeto programado — '
    +totalReservados+' material(is) reservado(s)'
    +(totalPendentes>0?' | '+totalPendentes+' pendente(s) sem saldo':'')
    +'. Veja em Almoxarifado → Reservas.';

  var t=document.createElement('div');
  t.style.cssText='position:fixed;bottom:20px;right:20px;background:#1a1a18;color:#fff;padding:12px 16px;border-radius:10px;font-size:13px;z-index:9999;max-width:360px';
  t.textContent=msg;
  document.body.appendChild(t);
  setTimeout(function(){t.remove();},5000);

  // Recarregar projeto
  sotAbrirProjeto(projetoId);
}

// ── Render reservas no almoxarifado ──────────────────────────
function almRenderReservas(cid, busca){
  var tb=document.getElementById('alm-tbody-reservas');if(!tb)return;
  var rows=alm_movimentos.filter(function(m){
    if(m.status!=='reservado'&&m.status!=='separacao')return false;
    if(cid&&m.contrato_id!==cid)return false;
    if(busca&&(m.material_desc||'').toLowerCase().indexOf(busca)<0)return false;
    return true;
  });
  if(!rows.length){
    tb.innerHTML='<tr><td colspan="9" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma reserva ativa.</td></tr>';
    return;
  }
  tb.innerHTML=rows.map(function(m){
    var stCor={reservado:'#3B6D11',reservado_pendente:'#A32D2D',separacao:'#185FA5'}[m.status]||'#555';
    var stLabel={reservado:'✅ Reservado',reservado_pendente:'⚠ Pendente (sem saldo)',separacao:'📦 Em separação'}[m.status]||m.status;
    var cont=contratos.find(function(c){return c.id===m.contrato_id;})||{codigo:'Geral'};
    return '<tr>'
      +'<td style="font-weight:500">'+m.material_desc+'</td>'
      +'<td style="font-size:12px">'+(m.projeto_nome||'—')+'</td>'
      +'<td><span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:11px">'+cont.codigo+'</span></td>'
      +'<td style="text-align:right;font-weight:600;color:'+stCor+'">'+m.qtd+'</td>'
      +'<td style="font-size:12px">'+m.unidade+'</td>'
      +'<td><span style="background:'+stCor+'22;color:'+stCor+';border-radius:4px;padding:2px 7px;font-size:11px;font-weight:600">'+stLabel+'</span></td>'
      +'<td style="font-size:11px">'+fmtD(m.data)+'</td>'
      +'<td style="font-size:11px;color:#888;max-width:200px;overflow:hidden;text-overflow:ellipsis">'+(m.obs||'—')+'</td>'
      +'<td style="display:flex;gap:4px">'
        +(m.status==='reservado'?'<button class="btn btn-sm" data-rid="'+m.id+'" data-act="separar" style="color:#185FA5;border-color:#185FA5;font-size:10px">Separar</button>':'')
        +(m.status==='reservado_pendente'?'<button class="btn btn-sm" data-rid="'+m.id+'" data-act="aguardar" style="color:#854F0B;border-color:#854F0B;font-size:10px">Aguard. chegada</button>':'')
        +'<button class="btn btn-sm" data-rid="'+m.id+'" data-act="cancelar" style="color:#A32D2D;border-color:#A32D2D;font-size:10px">Cancelar</button>'
      +'</td></tr>';
  }).join('');
  setTimeout(function(){
    rows.forEach(function(m){
      var bs=tb.querySelector('[data-rid="'+m.id+'"][data-act="separar"]');
      if(bs)bs.onclick=async function(){
        await almAtualizarMovimentoSeguro(m.id,{status:'separacao'});
      };
      var bag=tb.querySelector('[data-rid="'+m.id+'"][data-act="aguardar"]');
      if(bag)bag.onclick=function(){
        alert('Material marcado como aguardando chegada. Quando chegar, registre uma entrada e a reserva será atendida automaticamente.');
      };
      var bc=tb.querySelector('[data-rid="'+m.id+'"][data-act="cancelar"]');
      if(bc)bc.onclick=async function(){
        if(!confirm('Cancelar esta reserva?'))return;
        await almAtualizarMovimentoSeguro(m.id,{status:'cancelado'});
      };
    });
  },50);
}


