// MÓDULO ALMOXARIFADO / ESTOQUE
// ═══════════════════════════════════════════════════════════════

var alm_movimentos = []; // todas as movimentações
var alm_estoque    = []; // saldo calculado por material/contrato
var _almTabAtual   = 'estoque';

// Tipos de movimento
var ALM_TIPOS = {
  entrada:   {label:'Entrada',   cor:'#3B6D11', bg:'#EAF3DE', icon:'⬇'},
  saida:     {label:'Saída',     cor:'#185FA5', bg:'#E6F1FB', icon:'⬆'},
  aplicacao: {label:'Aplicação', cor:'#085041', bg:'#E1F5EE', icon:'✔'},
  devolucao: {label:'Devolução', cor:'#854F0B', bg:'#FEF3E2', icon:'↩'},
};

var ALM_ORIGENS = [
  'Compra empresa','Fornecido pelo cliente','Transferência entre contratos',
  'Devolução de campo','Ajuste de inventário','Outros'
];

var ALM_MOTIVOS_ENTRADA = [
  'Compra',
  'Reposição',
  'Remessa ENEL',
  'Remessa Equatorial',
  'Remessa Comgás',
  'Transferência interna',
  'Devolução de colaborador',
  'Outro'
];

function almMotivosEntradaHtml(selecionado){
  return ALM_MOTIVOS_ENTRADA.map(function(m){
    return '<option'+(selecionado&&selecionado===m?' selected':'')+'>'+escHtml(m)+'</option>';
  }).join('');
}

function almMotivoEntradaSugereFornecedor(motivo){
  if(!motivo) return '';
  if(/^Remessa ENEL/i.test(motivo)) return 'ENEL';
  if(/^Remessa Equatorial/i.test(motivo)) return 'Equatorial';
  if(/^Remessa Comg/i.test(motivo)) return 'Comgás';
  return '';
}

// ── Init ─────────────────────────────────────────────────────
function almInit(){
  // Popular filtro de contratos
  var sel = document.getElementById('alm-fil-cont');
  if(sel && sel.options.length <= 1){
    contratos.forEach(function(c){
      var o=document.createElement('option');
      o.value=c.id; o.textContent=c.nome;
      sel.appendChild(o);
    });
  }
  almCarregarMovimentos().then(function(){
    // Carregar reservas separadamente
    alm_reservas = alm_movimentos.filter(function(m){return m.status==='reservado'||m.status==='separacao';});
    almCalcularSaldo();
    almRenderMetricas();
    almRender();
  });
}

function almCarregarMovimentos(){
  if(DEMO){ alm_movimentos=[]; return Promise.resolve(); }
  var cid=(document.getElementById('alm-fil-cont')||{}).value||'';
  var filters=cid?['contrato_id=eq.'+cid]:[];
  return sbFetch('alm_movimentos',{filters:filters,order:'criado_em.desc'})
    .then(function(rows){ if(rows&&rows.length) alm_movimentos=rows; else alm_movimentos=[]; })
    .catch(function(){ alm_movimentos=[]; });
}

async function almRecarregarMovimentosSap(contratoId){
  if(DEMO){ almCalcularSaldo(); return; }
  try{
    var f = contratoId ? ['contrato_id=eq.'+contratoId] : [];
    var rows = await sbFetch('alm_movimentos', {filters:f, order:'criado_em.desc', limit:15000});
    if(contratoId){
      alm_movimentos = (alm_movimentos||[]).filter(function(m){
        return String(m.contrato_id||'')!==String(contratoId);
      }).concat(rows||[]);
    } else if(rows && rows.length) {
      alm_movimentos = rows;
    }
  }catch(e){ console.warn('almRecarregarMovimentosSap:', e); }
  almCalcularSaldo();
}

async function almSalvarMovimentoSeguro(mov){
  if(DEMO){
    alm_movimentos.unshift(mov);
    if(mov.status==='reservado'||mov.status==='separacao'||mov.status==='reservado_pendente'){
      alm_reservas.push(mov);
    }
    almCalcularSaldo();
    almRenderMetricas();
    almRender();
    return true;
  }
  try{
    var r=await sbInsert('alm_movimentos',_semId(mov));
    if(!r||!r.length){
      alert('Não foi possível salvar o movimento. Tente novamente.');
      return false;
    }
    if(r[0]&&r[0].id) mov.id=r[0].id;
    var saved=Object.assign({},mov,r[0]||{});
    alm_movimentos.unshift(saved);
    if(saved.status==='reservado'||saved.status==='separacao'||saved.status==='reservado_pendente'){
      alm_reservas.push(saved);
    }
    await almRecarregarMovimentosSap(saved.contrato_id||null);
    almRenderMetricas();
    almRender();
    return true;
  }catch(e){
    console.error('almSalvarMovimentoSeguro:',e);
    alert('Erro ao salvar movimento: '+(e.message||e));
    return false;
  }
}

async function almAtualizarMovimentoSeguro(movId,patch){
  var mov=alm_movimentos.find(function(m){return m.id===movId;});
  if(!mov){
    alert('Movimento não encontrado.');
    return false;
  }
  if(DEMO){
    Object.assign(mov,patch);
    var rsv=alm_reservas.find(function(r){return r.id===movId;});
    if(rsv){
      if(patch.status==='cancelado'){
        var idx=alm_reservas.indexOf(rsv);
        if(idx>=0) alm_reservas.splice(idx,1);
      }else{
        Object.assign(rsv,patch);
      }
    }
    almCalcularSaldo();
    almRenderMetricas();
    almRender();
    return true;
  }
  try{
    var ok=await sbUpdate('alm_movimentos',patch,'id=eq.'+movId);
    if(!ok){
      alert('Não foi possível atualizar o movimento. Tente novamente.');
      return false;
    }
    Object.assign(mov,patch);
    var rsv2=alm_reservas.find(function(r){return r.id===movId;});
    if(rsv2){
      if(patch.status==='cancelado'){
        var idx2=alm_reservas.indexOf(rsv2);
        if(idx2>=0) alm_reservas.splice(idx2,1);
      }else{
        Object.assign(rsv2,patch);
      }
    }
    almCalcularSaldo();
    almRenderMetricas();
    almRender();
    return true;
  }catch(e){
    console.error('almAtualizarMovimentoSeguro:',e);
    alert('Erro ao atualizar movimento: '+(e.message||e));
    return false;
  }
}

// ── Calcular saldo ───────────────────────────────────────────
function almNormSapText(s){
  return String(s||'').trim().toLowerCase().replace(/\s+/g,' ').replace(/,/g,',');
}
function almChaveSaldoSap(m){
  var cont = String(m.contrato_id||'geral');
  var cod = String(m.codigo_sap||'').trim();
  if(!cod && m.material_id){
    var catById = (catalogo_materiais||[]).find(function(x){ return String(x.id)===String(m.material_id); });
    if(catById && catById.codigo_sap) cod = String(catById.codigo_sap).trim();
  }
  if(!cod && m.material_desc){
    var hit = almEscolherMaterialSapCanonico((catalogo_materiais||[]).filter(function(x){
      return almNormSapText(x.descricao)===almNormSapText(m.material_desc);
    }));
    if(hit && hit.codigo_sap) cod = String(hit.codigo_sap).trim();
  }
  if(cod) return 'sap:'+cod+'|'+cont;
  var desc = almNormSapText(m.material_desc);
  if(desc) return 'desc:'+desc+'|'+cont;
  return 'id:'+String(m.material_id||'?')+'|'+cont;
}
function almEscolherMaterialSapCanonico(mats){
  if(!mats||!mats.length) return null;
  if(mats.length===1) return mats[0];
  var sorted = mats.slice().sort(function(a,b){
    var ac = String(a.codigo_sap||'').trim() ? 1 : 0;
    var bc = String(b.codigo_sap||'').trim() ? 1 : 0;
    if(bc!==ac) return bc-ac;
    return String(a.id||'').localeCompare(String(b.id||''));
  });
  return sorted[0];
}
function almMateriaisCatalogoUnicos(cid){
  var seen = {};
  var out = [];
  (catalogo_materiais||[]).filter(function(m){
    if(m.status==='Inativo') return false;
    if(cid){
      var cids = m.contratos_ids||[];
      if(cids.indexOf('todos')<0 && cids.indexOf(cid)<0) return false;
    }
    return true;
  }).forEach(function(m){
    var k = String(m.codigo_sap||'').trim() || almNormSapText(m.descricao);
    if(!k || seen[k]) return;
    seen[k] = true;
    out.push(m);
  });
  return out;
}
function almCalcularSaldo(){
  var mapa = {};

  alm_movimentos.forEach(function(m){
    var chave = almChaveSaldoSap(m);
    if(!mapa[chave]){
      mapa[chave]={
        material_id: m.material_id||'',
        material_desc: m.material_desc||'',
        codigo_sap: m.codigo_sap||'',
        contrato_id: m.contrato_id||'',
        unidade: m.unidade||'UN',
        valor_unitario: 0,
        entradas:0, saidas:0, aplicacoes:0, devolucoes:0
      };
    }
    var row = mapa[chave];
    if(m.codigo_sap && !row.codigo_sap) row.codigo_sap = m.codigo_sap;
    if(m.material_id && !row.material_id) row.material_id = m.material_id;
    if((m.material_desc||'').length > (row.material_desc||'').length) row.material_desc = m.material_desc;
    var vUnit = Number(m.valor_unitario)||0;
    if(m.tipo==='entrada' && vUnit>0) row.valor_unitario = vUnit;
    var qtd = Number(m.qtd)||0;
    if(m.tipo==='entrada')   row.entradas   += qtd;
    if(m.tipo==='saida')     row.saidas      += qtd;
    if(m.tipo==='aplicacao') row.aplicacoes  += qtd;
    if(m.tipo==='devolucao') row.devolucoes  += qtd;
  });

  alm_estoque = Object.values(mapa).map(function(e){
    e.em_campo   = e.saidas - e.aplicacoes - e.devolucoes;
    e.saldo      = e.entradas - e.saidas + e.devolucoes;
    e.valor_total = Math.round((e.saldo * (Number(e.valor_unitario)||0))*100)/100;
    if(!isFinite(e.em_campo)) e.em_campo = 0;
    if(!isFinite(e.saldo)) e.saldo = 0;
    if(!isFinite(e.valor_total)) e.valor_total = 0;
    return e;
  });
}

