// ETAPA 4.3–4.5 — DIAGNÓSTICO + CORREÇÃO ASSISTIDA + PLANO DE CORREÇÃO
// ═══════════════════════════════════════════════════════════════

var _almDiagResultado = null, _almDiagCorrigindo = false, _almDiagHistCorrecoes = [];

function almInitDiagnosticoEstoque(){
  if(!_almDiagResultado){
    var v=document.getElementById('diag-vazio'); if(v) v.style.display='';
    ['diag-resumo','diag-filtros','diag-tabela-wrap'].forEach(function(id){
      var el=document.getElementById(id); if(el) el.style.display='none';
    });
    var b1=document.getElementById('diag-btn-csv'); if(b1) b1.disabled=true;
    var b2=document.getElementById('diag-btn-copiar'); if(b2) b2.disabled=true;
  } else almRenderDiagnosticoEstoque();
}

function almDiagEsc(s){ return _escapeHtml(String(s==null?'':s)); }
function almDiagNum(n){ var x=Number(n); return isFinite(x)?x:0; }
function almDiagEhUuid(s){
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(s||'').trim());
}
function almDiagFmtTipoItem(t){
  var map={ferramenta:'Ferramenta',epc:'EPC',epi:'EPI',uniforme:'Uniforme',consumivel:'Consumível',material:'Material',patrimonio:'Patrimônio'};
  var k=String(t||'').toLowerCase();
  return map[k]||(t?String(t).charAt(0).toUpperCase()+String(t).slice(1):'');
}
function almDiagNomeItem(itemId, fallback){
  var fb=String(fallback||'').trim();
  if(fb&&!almDiagEhUuid(fb)&&fb.indexOf('Item ')!==0) return fb;
  var cat=almDiagCatItem(itemId);
  if(cat&&cat.nome) return cat.nome;
  if(fb&&!almDiagEhUuid(fb)) return fb;
  return itemId?('Item sem nome (ref. '+String(itemId).slice(0,8)+'…)'):'—';
}
function almDiagNomeMaterial(materialId, materialDesc, codigoSap){
  var d=String(materialDesc||'').trim();
  if(d&&!almDiagEhUuid(d)&&d.length>2) return d;
  if(codigoSap){
    var m=(catalogo_materiais||[]).find(function(x){ return String(x.codigo_sap)===String(codigoSap); });
    if(m&&m.descricao) return m.descricao;
    m=(mat_sap||[]).find(function(x){ return String(x.codigo_sap)===String(codigoSap); });
    if(m&&m.descricao) return m.descricao;
  }
  if(materialId){
    var est=(typeof alm_estoque!=='undefined'?alm_estoque:[]).find(function(x){ return String(x.material_id)===String(materialId); });
    if(est&&est.material_desc&&!almDiagEhUuid(est.material_desc)) return est.material_desc;
    var cat=(catalogo_materiais||[]).find(function(x){ return String(x.id)===String(materialId); });
    if(cat&&cat.descricao) return cat.descricao;
  }
  if(codigoSap) return 'Material SAP '+codigoSap;
  return 'Material sem descrição cadastrada';
}
function almDiagHumanizarTexto(s){
  if(!s) return '';
  return String(s)
    .replace(/\bitem_id\b/gi,'código do item')
    .replace(/\bcolaborador_id\b/gi,'colaborador')
    .replace(/\bfuncionario_id\b/gi,'funcionário')
    .replace(/\bresponsavel_id\b/gi,'responsável')
    .replace(/\bcontrato_id\b/gi,'contrato')
    .replace(/\bdeposito_id\b/gi,'depósito')
    .replace(/\bdata_mov\b/gi,'data da movimentação')
    .replace(/\btipo_item\b/gi,'categoria do item')
    .replace(/\bitens_catalogo\b/gi,'catálogo de itens')
    .replace(/\bdata_entrega\b/gi,'data de entrega')
    .replace(/\bNaN\b/g,'valor inválido')
    .replace(/\bqtd\b/gi,'quantidade')
    .replace(/\balm_estoque\b/g,'estoque SAP em memória')
    .replace(/\balmCalcularSaldo\(\)/g,'recálculo de saldo SAP')
    .replace(/\bmovimentacao_origem_id\b/gi,'movimentação de origem');
}

function almDiagPush(list, o){
  var itemNome=o.item_nome||'';
  if(o.origem==='SAP'||o.material_id||o.codigo_sap){
    itemNome=almDiagNomeMaterial(o.material_id,itemNome,o.codigo||o.codigo_sap);
  }else if(o.item_id&&(almDiagEhUuid(itemNome)||!itemNome||/^Item /.test(itemNome))){
    itemNome=almDiagNomeItem(o.item_id,itemNome);
  }
  list.push({
    criticidade:o.criticidade||'Média', origem:o.origem||'Patrimonial', tipo:o.tipo||'Inconsistência',
    item_id:o.item_id||'', item_nome:itemNome, codigo:o.codigo||'', ca:o.ca||'', lote:o.lote||'',
    colaborador_id:o.colaborador_id||'', colaborador_nome:o.colaborador_nome||'',
    contrato_id:o.contrato_id||'', contrato_nome:o.contrato_nome||'',
    deposito_id:o.deposito_id||'', deposito_nome:o.deposito_nome||'',
    saldo_sistema:almDiagNum(o.saldo_sistema), saldo_calculado:almDiagNum(o.saldo_calculado),
    diferenca:almDiagNum(o.diferenca),
    descricao:almDiagHumanizarTexto(o.descricao||''),
    recomendacao:almDiagHumanizarTexto(o.recomendacao||''),
    acao_sugerida:almDiagHumanizarTexto(o.acao_sugerida||'Revisar manualmente'),
    categoria:almDiagFmtTipoItem(o.categoria||''),
    mov_id:o.mov_id||'', estoque_id:o.estoque_id||'', material_id:o.material_id||''
  });
}

function almDiagCatItem(itemId){
  return (itens_catalogo||[]).find(function(i){ return String(i.id)===String(itemId); })||null;
}
function almDiagNomeDep(depId){
  if(!depId) return '—';
  var d=(depositos||[]).find(function(x){ return String(x.id)===String(depId); });
  return d?(d.nome||d.codigo||depId):('ID '+depId);
}
function almDiagNomeCont(cid){
  if(!cid) return '—';
  var c=(contratos||[]).find(function(x){ return String(x.id)===String(cid); });
  return c?almContratoLabel(c,false):cid;
}
function almDiagNomeColab(cid){
  if(!cid) return '—';
  var c=(colaboradores||[]).find(function(x){ return String(x.id)===String(cid); });
  if(c) return c.nome||cid;
  var f=(funcs||[]).find(function(x){ return String(x.id)===String(cid); });
  return f?(f.nome||cid):('ID '+cid);
}
function almDiagColabExiste(cid){
  if(!cid) return false;
  return (colaboradores||[]).some(function(c){ return String(c.id)===String(cid); })
    || (funcs||[]).some(function(f){ return String(f.id)===String(cid); });
}
function almDiagDepExiste(depId){
  if(!depId) return true;
  return (depositos||[]).some(function(d){ return String(d.id)===String(depId); });
}
function almDiagLedgerKey(itemId,depId,lote,ca){
  return String(itemId||'')+'|'+String(depId||'_')+'|'+String(lote||'')+'|'+String(ca||'');
}
function almDiagRefCatalogoEstoque(row){
  var nome=String(row.nome||'').trim().toLowerCase();
  var cod=String(row.codigo||'').trim();
  return (itens_catalogo||[]).find(function(c){
    if(cod&&c.codigo&&String(c.codigo).trim()===cod) return true;
    return nome&&String(c.nome||'').trim().toLowerCase()===nome;
  })||null;
}

function almDiagCalcLedgerPatrimonial(movs){
  var ledger={};
  function add(key,delta){ if(!key) return; ledger[key]=(ledger[key]||0)+delta; }
  (movs||[]).forEach(function(m){
    var q=Number(m.quantidade); if(!isFinite(q)||isNaN(q)) return;
    var iid=m.item_id; if(!iid) return;
    var dep=m.deposito_id||'_';
    var lote=m.lote||m.nota_fiscal||'';
    var ca=m.ca||'';
    var k=almDiagLedgerKey(iid,dep,lote,ca);
    var tm=String(m.tipo_mov||'');
    if(tm==='entrada') add(k,q);
    else if(tm==='devolucao'&&typeof almDevolucaoRetornaEstoque==='function'&&almDevolucaoRetornaEstoque(m.condicao||'')) add(k,q);
    else if(tm==='entrega') add(k,-q);
    else if(tm==='transferencia'){
      add(almDiagLedgerKey(iid,dep,lote,ca),-q);
      var destId=typeof almMovDestinoId==='function'?almMovDestinoId(m):m.destino_id;
      if(destId) add(almDiagLedgerKey(iid,destId,lote,ca),q);
    }
    else if(tm==='ajuste'){
      if(typeof almAjusteEhEntrada==='function'&&almAjusteEhEntrada(m.tipo_ajuste)) add(k,q);
      else add(k,-q);
    }
    else if(['perda','quebra','baixa','descarte'].indexOf(tm)>=0) add(k,-q);
  });
  return ledger;
}

function almDiagAnalisarPatrimonial(movs, divs){
  var estRows=(typeof estoque!=='undefined'?estoque:[]);
  var ledger=almDiagCalcLedgerPatrimonial(movs);
  var dupMap={};
  estRows.forEach(function(e){
    if((Number(e.saldo)||0)<0){
      var cat=almDiagRefCatalogoEstoque(e);
      almDiagPush(divs,{criticidade:'Crítica',origem:'Patrimonial',tipo:'Saldo negativo',item_id:cat?cat.id:'',item_nome:e.nome||'—',
        codigo:e.codigo||'',ca:e.ca||'',lote:e.lote||'',deposito_id:e.deposito_id||'',deposito_nome:almDiagNomeDep(e.deposito_id),
        estoque_id:e.id||'',
        contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),categoria:cat?cat.tipo_item:'',
        saldo_sistema:Number(e.saldo)||0,saldo_calculado:0,diferenca:Number(e.saldo)||0,
        descricao:'Linha de estoque com saldo negativo ('+(e.saldo)+').',recomendacao:'Conferir entradas/saídas e ajustar manualmente se necessário.',
        acao_sugerida:'Auditoria física + revisão de movimentações'});
    }
    var dk=String(e.deposito_id||'_')+'|'+(String(e.nome||'').toLowerCase())+'|'+(e.lote||'')+'|'+(e.ca||'');
    dupMap[dk]=(dupMap[dk]||0)+1;
  });
  Object.keys(dupMap).forEach(function(dk){
    if(dupMap[dk]<=1) return;
    var parts=dk.split('|');
    var sample=estRows.find(function(e){
      return String(e.deposito_id||'_')===parts[0]&&String(e.nome||'').toLowerCase()===parts[1];
    });
    if(!sample) return;
    var cat2=almDiagRefCatalogoEstoque(sample);
    almDiagPush(divs,{criticidade:'Alta',origem:'Patrimonial',tipo:'Duplicidade de saldo',item_id:cat2?cat2.id:'',item_nome:sample.nome||'—',
      codigo:sample.codigo||'',ca:sample.ca||'',lote:sample.lote||'',deposito_id:sample.deposito_id||'',deposito_nome:almDiagNomeDep(sample.deposito_id),
      saldo_sistema:dupMap[dk],saldo_calculado:0,diferenca:0,
      descricao:dupMap[dk]+' linhas de estoque duplicadas para o mesmo item/depósito/lote/CA.',recomendacao:'Consolidar em uma única linha de saldo.',
      acao_sugerida:'Consolidar linhas duplicadas'});
  });
  Object.keys(ledger).forEach(function(k){
    var p=k.split('|'); var iid=p[0], depId=p[1]==='_'?'':p[1];
    var calc=ledger[k]; if(Math.abs(calc)<0.0001) return;
    var cat=almDiagCatItem(iid);
    var sys=0;
    if(cat){
      (estRows||[]).filter(function(e){
        var c2=almDiagRefCatalogoEstoque(e);
        return c2&&String(c2.id)===String(iid)&&String(e.deposito_id||'')===String(depId||'');
      }).forEach(function(e){ sys+=Number(e.saldo)||0; });
    }
    if(Math.abs(sys-calc)>0.001){
      var crit=Math.abs(sys-calc)>=5?'Crítica':'Alta';
      almDiagPush(divs,{criticidade:crit,origem:'Patrimonial',tipo:'Saldo divergente',item_id:iid,item_nome:cat?cat.nome:'',
        codigo:cat?cat.codigo:'',categoria:cat?cat.tipo_item:'',deposito_id:depId,deposito_nome:almDiagNomeDep(depId),
        saldo_sistema:sys,saldo_calculado:calc,diferenca:sys-calc,
        descricao:'Saldo registrado ('+sys+') difere do saldo calculado pelas movimentações ('+calc+').',
        recomendacao:'Conferir entradas, entregas, devoluções e transferências deste item no depósito.',
        acao_sugerida:'Conciliação manual (sem correção automática)'});
    }
  });
  (movs||[]).forEach(function(m){
    if(!m.item_id){
      almDiagPush(divs,{criticidade:'Alta',origem:'Patrimonial',tipo:'Movimento órfão',item_nome:'—',
        descricao:'Movimentação patrimonial sem item vinculado ao catálogo.',deposito_id:m.deposito_id||'',deposito_nome:almDiagNomeDep(m.deposito_id),
        recomendacao:'Vincular ao catálogo ou excluir movimento inválido (futuro).',acao_sugerida:'Revisar movimentação'});
      return;
    }
    if(!almDiagCatItem(m.item_id)){
      almDiagPush(divs,{criticidade:'Alta',origem:'Patrimonial',tipo:'Item inválido',item_id:m.item_id,
        descricao:'O item referenciado não existe no catálogo patrimonial.',deposito_id:m.deposito_id||'',deposito_nome:almDiagNomeDep(m.deposito_id),
        acao_sugerida:'Cadastrar o item ou corrigir o vínculo da movimentação'});
    }
    if(m.deposito_id&&!almDiagDepExiste(m.deposito_id)){
      var cat3=almDiagCatItem(m.item_id);
      almDiagPush(divs,{criticidade:'Alta',origem:'Patrimonial',tipo:'Depósito inválido',item_id:m.item_id,item_nome:cat3?cat3.nome:'',
        deposito_id:m.deposito_id,deposito_nome:'Inexistente',descricao:'Movimentação referencia depósito inexistente.',
        acao_sugerida:'Ajustar depósito na movimentação'});
    }
    if(m.colaborador_id&&!almDiagColabExiste(m.colaborador_id)){
      var cat4=almDiagCatItem(m.item_id);
      almDiagPush(divs,{criticidade:'Crítica',origem:'Patrimonial',tipo:'Colaborador inexistente',item_id:m.item_id,item_nome:cat4?cat4.nome:'',
        colaborador_id:m.colaborador_id,colaborador_nome:'Inexistente',descricao:'Entrega ou devolução vinculada a colaborador inexistente no cadastro.',
        acao_sugerida:'Reconciliar cadastro de colaborador e funcionário SESMT'});
    }
    if(m.tipo_mov==='entrega'&&m.status==='Em uso'){
      var cat5=almDiagCatItem(m.item_id);
      var entAnt=(movs||[]).filter(function(x){ return String(x.item_id)===String(m.item_id)&&x.tipo_mov==='entrada'; });
      if(!entAnt.length){
        almDiagPush(divs,{criticidade:'Crítica',origem:'Patrimonial',tipo:'Entrega sem entrada',item_id:m.item_id,item_nome:cat5?cat5.nome:'',
          mov_id:m.id||'',
          colaborador_id:m.colaborador_id||'',colaborador_nome:almDiagNomeColab(m.colaborador_id),
          deposito_id:m.deposito_id||'',deposito_nome:almDiagNomeDep(m.deposito_id),saldo_sistema:0,saldo_calculado:-(Number(m.quantidade)||0),
          descricao:'Entrega Em uso sem entrada prévia registrada para o item.',acao_sugerida:'Registrar entrada retroativa ou corrigir entrega'});
      }
    }
    if(m.tipo_mov==='devolucao'&&typeof almDevolucaoRetornaEstoque==='function'&&almDevolucaoRetornaEstoque(m.condicao||'')){
      var cat6=almDiagCatItem(m.item_id);
      var orig=(movs||[]).find(function(x){ return String(x.id)===String(m.movimentacao_origem_id); });
      if(!orig){
        almDiagPush(divs,{criticidade:'Alta',origem:'Patrimonial',tipo:'Devolução órfã',item_id:m.item_id,item_nome:cat6?cat6.nome:'',
          mov_id:m.id||'',
          descricao:'Devolução sem movimentação de origem.',deposito_id:m.deposito_id||'',deposito_nome:almDiagNomeDep(m.deposito_id),
          acao_sugerida:'Vincular à entrega Em uso correspondente'});
      }
    }
    if(m.tipo_mov==='transferencia'){
      var destTr=typeof almMovDestinoId==='function'?almMovDestinoId(m):m.destino_id;
      if(destTr){
        var cat7=almDiagCatItem(m.item_id);
        var q=Number(m.quantidade)||0;
        var kDest=almDiagLedgerKey(m.item_id,destTr,'','');
        if((ledger[kDest]||0)<q*0.5){
          almDiagPush(divs,{criticidade:'Alta',origem:'Patrimonial',tipo:'Transferência incompleta',item_id:m.item_id,item_nome:cat7?cat7.nome:'',
            deposito_id:m.deposito_id||'',deposito_nome:almDiagNomeDep(m.deposito_id),
            descricao:'Transferência para depósito '+almDiagNomeDep(destTr)+' pode não ter reposto saldo no destino.',
            acao_sugerida:'Conferir saldo no depósito destino'});
        }
      }
    }
    if(!m.data_mov){
      almDiagPush(divs,{criticidade:'Média',origem:'Patrimonial',tipo:'Sem data',item_id:m.item_id,mov_id:m.id||'',
        item_nome:(almDiagCatItem(m.item_id)||{}).nome||'',descricao:'Movimentação sem data registrada.',acao_sugerida:'Informar a data da movimentação'});
    }
    var cat8=almDiagCatItem(m.item_id);
    if(cat8&&!cat8.tipo_item){
      almDiagPush(divs,{criticidade:'Média',origem:'Patrimonial',tipo:'Sem categoria',item_id:m.item_id,item_nome:cat8.nome,
        descricao:'Item cadastrado sem categoria (ferramenta, EPC, etc.).',acao_sugerida:'Completar cadastro do item'});
    }
  });
  (itens_catalogo||[]).filter(function(c){ return c.ativo!==false; }).forEach(function(c){
    var movItem=(movs||[]).some(function(m){ return String(m.item_id)===String(c.id); });
    var sal=estRows.filter(function(e){ var r=almDiagRefCatalogoEstoque(e); return r&&String(r.id)===String(c.id)&&Number(e.saldo)>0; });
    if(!movItem&&!sal.length){
      almDiagPush(divs,{criticidade:'Baixa',origem:'Patrimonial',tipo:'Sem movimentação',item_id:c.id,item_nome:c.nome,codigo:c.codigo||'',
        categoria:c.tipo_item||'',descricao:'Item cadastrado sem movimentações nem saldo.',acao_sugerida:'Normal se recém-cadastrado'});
    }
  });
}

function almDiagCalcSapLocal(movimentos){
  var mapa={};
  (movimentos||[]).forEach(function(m){
    var chave=almChaveSaldoSap(m);
    if(!mapa[chave]) mapa[chave]={material_id:m.material_id||'',material_desc:m.material_desc||'',codigo_sap:m.codigo_sap||'',
      contrato_id:m.contrato_id||'',entradas:0,saidas:0,aplicacoes:0,devolucoes:0,mov_count:0};
    var q=Number(m.qtd); if(!isFinite(q)||isNaN(q)) q=0;
    mapa[chave].mov_count++;
    if(m.tipo==='entrada') mapa[chave].entradas+=q;
    if(m.tipo==='saida') mapa[chave].saidas+=q;
    if(m.tipo==='aplicacao') mapa[chave].aplicacoes+=q;
    if(m.tipo==='devolucao') mapa[chave].devolucoes+=q;
  });
  return Object.values(mapa).map(function(e){
    e.em_campo=e.saidas-e.aplicacoes-e.devolucoes;
    e.saldo=e.entradas-e.saidas+e.devolucoes;
    if(!isFinite(e.em_campo)) e.em_campo=0;
    if(!isFinite(e.saldo)) e.saldo=0;
    return e;
  });
}

function almDiagAnalisarSap(movimentos, divs){
  var calc=almDiagCalcSapLocal(movimentos);
  var mem=(typeof alm_estoque!=='undefined'?alm_estoque:[]);
  calc.forEach(function(e){
    if(e.saldo<0){
      almDiagPush(divs,{criticidade:'Crítica',origem:'SAP',tipo:'Saldo negativo',material_id:e.material_id,item_nome:e.material_desc||'',
        codigo:e.codigo_sap||'',contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),
        saldo_sistema:e.saldo,saldo_calculado:e.saldo,diferenca:e.saldo,
        descricao:'Saldo SAP calculado negativo (entradas '+e.entradas+' − saídas '+e.saidas+' + devoluções '+e.devolucoes+').',
        recomendacao:'Revisar saídas/aplicações ou registrar entradas faltantes.',acao_sugerida:'Conciliação SAP'});
    }
    if(e.saidas>e.entradas+0.001){
      almDiagPush(divs,{criticidade:'Crítica',origem:'SAP',tipo:'Saída maior que entrada',item_nome:e.material_desc||'',
        contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),saldo_sistema:e.entradas,saldo_calculado:e.saidas,diferenca:e.entradas-e.saidas,
        descricao:'Total de saídas excede entradas.',acao_sugerida:'Verificar movimentos de saída'});
    }
    if(e.devolucoes>e.saidas+0.001){
      almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Devolução excessiva',item_nome:e.material_desc||'',
        contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),saldo_calculado:e.devolucoes,saldo_sistema:e.saidas,diferenca:e.saidas-e.devolucoes,
        descricao:'Devoluções superiores às saídas.',acao_sugerida:'Conferir devoluções duplicadas'});
    }
    if(e.aplicacoes>e.saidas+0.001){
      almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Aplicação excessiva',item_nome:e.material_desc||'',
        contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),
        descricao:'Aplicações maiores que saídas.',acao_sugerida:'Revisar aplicações em campo'});
    }
    if(e.em_campo<0){
      almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Em campo inconsistente',item_nome:e.material_desc||'',
        contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),saldo_calculado:e.em_campo,
        descricao:'Material em campo negativo (saídas − aplicações − devoluções).',acao_sugerida:'Conferir status em campo'});
    }
    var memRow=mem.find(function(x){
      return almChaveSaldoSap(x)===almChaveSaldoSap(e);
    });
    if(memRow&&Math.abs((memRow.saldo||0)-e.saldo)>0.001){
      almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Divergência memória',material_id:e.material_id,item_nome:e.material_desc||'',
        contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),
        saldo_sistema:memRow.saldo,saldo_calculado:e.saldo,diferenca:(memRow.saldo||0)-e.saldo,
        descricao:'Saldo exibido na tela difere do recálculo pelos movimentos SAP.',acao_sugerida:'Atualizar saldos SAP na tela'});
    }
  });
  (movimentos||[]).forEach(function(m){
    var q=Number(m.qtd);
    if(!isFinite(q)||isNaN(q)){
      almDiagPush(divs,{criticidade:'Crítica',origem:'SAP',tipo:'Quantidade inválida',material_id:m.material_id,item_nome:m.material_desc||'',
        contrato_id:m.contrato_id||'',contrato_nome:almDiagNomeCont(m.contrato_id),descricao:'Quantidade inválida em movimento de material SAP.',
        acao_sugerida:'Corrigir a quantidade do movimento'});
    }
    if(!m.material_id&&!m.material_desc){
      almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Sem material',contrato_id:m.contrato_id||'',
        descricao:'Movimento SAP sem código/descrição de material.',acao_sugerida:'Preencher material'});
    }
    if(!m.data){
      almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Sem data',item_nome:m.material_desc||'',
        descricao:'Movimento SAP sem data.',acao_sugerida:'Preencher data'});
    }
    if((m.tipo==='saida'||m.tipo==='reserva')&&!m.contrato_id){
      almDiagPush(divs,{criticidade:'Média',origem:'SAP',tipo:'Sem contrato',material_id:m.material_id,item_nome:m.material_desc||'',
        descricao:'Saída ou reserva de material sem contrato vinculado.',acao_sugerida:'Vincular o contrato ao movimento'});
    }
    if(m.status==='reservado'||m.status==='separacao'||m.status==='reservado_pendente'){
      if(!m.status){
        almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Reserva inconsistente',item_nome:m.material_desc||'',
          descricao:'Reserva/separação com status ambíguo.',acao_sugerida:'Revisar reserva'});
      }
    }
    if(m.status==='cancelado'){
      almDiagPush(divs,{criticidade:'Média',origem:'SAP',tipo:'Reserva cancelada',item_nome:m.material_desc||'',
        contrato_id:m.contrato_id||'',contrato_nome:almDiagNomeCont(m.contrato_id),
        descricao:'Movimento cancelado ainda registrado — verificar se o recálculo de saldo SAP deve ignorá-lo.',
        acao_sugerida:'Confirmar se ainda impacta o saldo'});
    }
  });
  var seen={};
  (movimentos||[]).forEach(function(m){
    var sig=[m.tipo,m.material_id,m.contrato_id,m.data,m.qtd,m.status].join('|');
    if(seen[sig]){
      almDiagPush(divs,{criticidade:'Alta',origem:'SAP',tipo:'Duplicidade',item_nome:m.material_desc||'',
        contrato_id:m.contrato_id||'',contrato_nome:almDiagNomeCont(m.contrato_id),
        descricao:'Possível movimento duplicado (mesma assinatura).',acao_sugerida:'Revisar duplicata'});
    }
    seen[sig]=1;
  });
}

function almDiagAnalisarPosse(movs, divs){
  var hoje=dataHojeLocal();
  (epis||[]).forEach(function(e){
    if(['Devolvido','Substituído','Cancelado'].indexOf(e.status||'')>=0) return;
    if(e.responsavel_id&&!((funcs||[]).some(function(f){ return String(f.id)===String(e.responsavel_id); }))){
      almDiagPush(divs,{criticidade:'Crítica',origem:'Posse',tipo:'EPI colaborador inexistente',item_nome:e.nome||'EPI',ca:e.ca||'',
        colaborador_id:e.responsavel_id||'',colaborador_nome:'Funcionário não encontrado',
        contrato_id:e.contrato_id||'',contrato_nome:almDiagNomeCont(e.contrato_id),
        descricao:'EPI ativo com responsável que não consta no cadastro de funcionários SESMT.',acao_sugerida:'Sincronizar RE entre colaborador e funcionário'});
    }
    var col=extratoFuncionarioPorRe&&e.responsavel_id?(colaboradores||[]).find(function(c){
      var f=(funcs||[]).find(function(x){ return String(x.id)===String(e.responsavel_id); });
      return f&&extratoNormRe(c.re)===extratoNormRe(f.matricula||f.re);
    }):null;
    if(col&&(col.dispensado||col.ativo===false)){
      almDiagPush(divs,{criticidade:'Média',origem:'Posse',tipo:'Colaborador dispensado',item_nome:e.nome||'EPI',
        colaborador_id:col.id,colaborador_nome:col.nome,descricao:'EPI em posse de colaborador dispensado/inativo.',
        acao_sugerida:'Desmobilização ou devolução'});
    }
    if(!e.data_entrega){
      almDiagPush(divs,{criticidade:'Média',origem:'Posse',tipo:'Entrega sem data',item_nome:e.nome||'EPI',
        colaborador_id:e.responsavel_id||'',colaborador_nome:fNome(e.responsavel_id),descricao:'EPI sem data de entrega registrada.'});
    }
    if(!e.ca&&(e.tipo||'EPI')==='EPI'){
      almDiagPush(divs,{criticidade:'Média',origem:'Posse',tipo:'EPI sem CA',item_nome:e.nome||'',
        colaborador_id:e.responsavel_id||'',colaborador_nome:fNome(e.responsavel_id),descricao:'EPI ativo sem CA registrado.'});
    }
    if((e.validade&&e.validade<hoje)||(e.ca_validade&&e.ca_validade<hoje)){
      almDiagPush(divs,{criticidade:'Média',origem:'Posse',tipo:'EPI/EPC vencido',item_nome:e.nome||'',ca:e.ca||'',
        colaborador_id:e.responsavel_id||'',colaborador_nome:fNome(e.responsavel_id),
        descricao:'Validade ou CA vencida.',acao_sugerida:'Substituir ou devolver'});
    }
    if(e.data_prevista_substituicao&&e.data_prevista_substituicao<hoje){
      almDiagPush(divs,{criticidade:'Média',origem:'Posse',tipo:'Previsão troca vencida',item_nome:e.nome||'',
        colaborador_id:e.responsavel_id||'',colaborador_nome:fNome(e.responsavel_id),descricao:'Previsão de troca ultrapassada.'});
    }
  });
  (uniformesEnt||[]).filter(function(u){ return u.ativo!==false; }).forEach(function(u){
    if(u.funcionario_id&&!((funcs||[]).some(function(f){ return String(f.id)===String(u.funcionario_id); }))){
      almDiagPush(divs,{criticidade:'Crítica',origem:'Posse',tipo:'Uniforme funcionário inválido',item_nome:typeof extratoUniLabel==='function'?extratoUniLabel(u):'Uniforme',
        colaborador_id:u.funcionario_id||'',descricao:'Uniforme ativo vinculado a funcionário inexistente no cadastro.'});
    }
  });
  (movs||[]).filter(function(m){ return m.tipo_mov==='entrega'&&m.status==='Em uso'; }).forEach(function(m){
    var cat=almDiagCatItem(m.item_id);
    var cid=m.colaborador_id||null;
    if(cid&&!almDiagColabExiste(cid)){
      almDiagPush(divs,{criticidade:'Crítica',origem:'Posse',tipo:'Patrimônio sem responsável',item_nome:cat?cat.nome:'',
        colaborador_id:cid,colaborador_nome:'Inexistente',deposito_id:m.deposito_id||'',deposito_nome:almDiagNomeDep(m.deposito_id),
        descricao:'Item em uso vinculado a colaborador inexistente no cadastro.',acao_sugerida:'Corrigir vínculo do colaborador'});
    }
    if(cid){
      var col=(colaboradores||[]).find(function(c){ return String(c.id)===String(cid); });
      if(col&&(col.dispensado||col.ativo===false)){
        almDiagPush(divs,{criticidade:'Média',origem:'Posse',tipo:'Item com dispensado',item_nome:cat?cat.nome:'',
          colaborador_id:col.id,colaborador_nome:col.nome,descricao:'Patrimônio Em uso de colaborador dispensado.'});
      }
    }
  });
}

function almDiagMontarResumo(divs){
  var r={total:divs.length,criticas:0,altas:0,medias:0,baixas:0,saldos_negativos:0,duplicidades:0,movimentos_orfaos:0,
    itens_sem_saldo:0,entregas_inconsistentes:0,reservas_inconsistentes:0};
  divs.forEach(function(d){
    if(d.criticidade==='Crítica') r.criticas++;
    else if(d.criticidade==='Alta') r.altas++;
    else if(d.criticidade==='Média') r.medias++;
    else r.baixas++;
    if((d.tipo||'').indexOf('negativo')>=0||d.saldo_sistema<0||d.saldo_calculado<0) r.saldos_negativos++;
    if((d.tipo||'').indexOf('Duplic')>=0) r.duplicidades++;
    if((d.tipo||'').indexOf('órf')>=0||(d.tipo||'').indexOf('orf')>=0) r.movimentos_orfaos++;
    if((d.tipo||'').indexOf('Sem moviment')>=0) r.itens_sem_saldo++;
    if((d.tipo||'').indexOf('Entrega')>=0) r.entregas_inconsistentes++;
    if((d.tipo||'').indexOf('Reserva')>=0||d.tipo==='Reserva cancelada') r.reservas_inconsistentes++;
  });
  return r;
}

async function almDiagnosticarDivergenciasEstoque(){
  if(typeof sesmtInit==='function') sesmtInit();
  if(!DEMO){
    if(typeof carregarModuloSESMT==='function'&&!_modSESMT) await carregarModuloSESMT();
    if(typeof sesmtCarregarDados==='function') await sesmtCarregarDados();
    if(typeof almCarregarMovimentos==='function') await almCarregarMovimentos();
  }
  var movsDiag=(movimentacoes_itens||[]).slice();
  if(!DEMO){
    try{
      var full=await sbFetch('movimentacoes_itens',{order:'data_mov.desc',limit:12000});
      if(full&&full.length&&typeof almMergeMovimentacoes==='function') movsDiag=almMergeMovimentacoes([movsDiag,full]);
      else if(full&&full.length) movsDiag=full;
    }catch(e){ console.warn('diag: movimentacoes',e); }
  }
  var sapMovs=(typeof alm_movimentos!=='undefined'?alm_movimentos:[]).slice();
  var divs=[];
  almDiagAnalisarPatrimonial(movsDiag,divs);
  almDiagAnalisarSap(sapMovs,divs);
  almDiagAnalisarPosse(movsDiag,divs);
  return {resumo:almDiagMontarResumo(divs),divergencias:divs,analisado_em:new Date().toISOString(),movs_analisados:movsDiag.length,sap_movs:sapMovs.length};
}

async function almExecutarDiagnosticoEstoque(){
  var btn=document.getElementById('diag-btn-analisar');
  if(btn){ btn.disabled=true; btn.textContent='⏳ Analisando...'; }
  try{
    _almDiagResultado=await almDiagnosticarDivergenciasEstoque();
    almRenderDiagnosticoEstoque();
    if(typeof progShowToast==='function') progShowToast('Diagnóstico: '+_almDiagResultado.resumo.total+' divergência(s) encontrada(s).');
  }catch(e){
    console.error('almExecutarDiagnosticoEstoque',e);
    if(typeof progShowToast==='function') progShowToast('Erro no diagnóstico.','erro');
  }
  if(btn){ btn.disabled=false; btn.textContent='🔍 Analisar divergências'; }
}

function almDiagCritCor(c){
  if(c==='Crítica') return '#A32D2D';
  if(c==='Alta') return '#854F0B';
  if(c==='Média') return '#185FA5';
  return '#888';
}

function almRenderDiagnosticoEstoque(resultado){
  if(resultado) _almDiagResultado=resultado;
  if(!_almDiagResultado) return;
  var r=_almDiagResultado, res=r.resumo||{};
  var v=document.getElementById('diag-vazio'); if(v) v.style.display='none';
  var box=document.getElementById('diag-resumo'); if(box){
    box.style.display='grid'; box.style.gridTemplateColumns='repeat(auto-fit,minmax(110px,1fr))'; box.style.gap='8px';
    var cards=[
      {l:'Total',v:res.total,c:'#534AB7'},{l:'Críticas',v:res.criticas,c:'#A32D2D'},{l:'Altas',v:res.altas,c:'#854F0B'},
      {l:'Médias',v:res.medias,c:'#185FA5'},{l:'Baixas',v:res.baixas,c:'#888'},{l:'Saldo neg.',v:res.saldos_negativos,c:'#A32D2D'},
      {l:'Duplic.',v:res.duplicidades,c:'#854F0B'},{l:'Órfãos',v:res.movimentos_orfaos,c:'#854F0B'},
      {l:'Sem saldo/mov',v:res.itens_sem_saldo,c:'#888'},{l:'Entregas',v:res.entregas_inconsistentes,c:'#A32D2D'},
      {l:'Reservas',v:res.reservas_inconsistentes,c:'#854F0B'}
    ];
    box.innerHTML=cards.map(function(c){
      return '<div class="card" style="padding:.6rem;text-align:center;border-top:3px solid '+c.c+'"><div style="font-size:18px;font-weight:700;color:'+c.c+'">'+c.v+'</div><div style="font-size:10px;color:#888">'+c.l+'</div></div>';
    }).join('');
  }
  var fil=document.getElementById('diag-filtros'); if(fil) fil.style.display='';
  var selC=document.getElementById('diag-fil-cont');
  if(selC&&selC.options.length<=1){
    selC.innerHTML='<option value="">Todos</option>'+(contratos||[]).map(function(c){ return '<option value="'+c.id+'">'+almContratoLabel(c,false)+'</option>'; }).join('');
  }
  var selD=document.getElementById('diag-fil-dep');
  if(selD&&selD.options.length<=1){
    selD.innerHTML='<option value="">Todos</option>'+(depositos||[]).map(function(d){ return '<option value="'+d.id+'">'+d.nome+'</option>'; }).join('');
  }
  var fo=(document.getElementById('diag-fil-origem')||{}).value||'';
  var fc=(document.getElementById('diag-fil-crit')||{}).value||'';
  var ft=(document.getElementById('diag-fil-tipo')||{}).value||'';
  var fcont=(document.getElementById('diag-fil-cont')||{}).value||'';
  var fdep=(document.getElementById('diag-fil-dep')||{}).value||'';
  var fitem=((document.getElementById('diag-fil-item')||{}).value||'').toLowerCase();
  var fcolab=((document.getElementById('diag-fil-colab')||{}).value||'').toLowerCase();
  var fneg=!!((document.getElementById('diag-fil-neg')||{}).checked);
  var fdup=!!((document.getElementById('diag-fil-dup')||{}).checked);
  var fcorr=!!((document.getElementById('diag-fil-corr')||{}).checked);
  var podeCorr=almDiagPodeCorrigir();
  var lista=(r.divergencias||[]).filter(function(d,i){
    d._idx=i;
    if(fo&&d.origem!==fo) return false;
    if(fc&&d.criticidade!==fc) return false;
    if(ft&&(d.tipo||'').toLowerCase().indexOf(ft.toLowerCase())<0) return false;
    if(fcont&&String(d.contrato_id||'')!==String(fcont)) return false;
    if(fdep&&String(d.deposito_id||'')!==String(fdep)) return false;
    if(fitem&&!(d.item_nome||'').toLowerCase().includes(fitem)&&!(d.codigo||'').toLowerCase().includes(fitem)) return false;
    if(fcolab&&!(d.colaborador_nome||'').toLowerCase().includes(fcolab)) return false;
    if(fneg&&!(d.saldo_sistema<0||d.saldo_calculado<0||(d.tipo||'').toLowerCase().indexOf('negativo')>=0)) return false;
    if(fdup&&(d.tipo||'').toLowerCase().indexOf('duplic')<0) return false;
    if(fcorr&&!almDiagTemCorrecao(d)) return false;
    return true;
  });
  var tb=document.getElementById('diag-tbody'); var wrap=document.getElementById('diag-tabela-wrap');
  if(wrap) wrap.style.display='';
  if(tb){
    tb.innerHTML=lista.length?lista.map(function(d){
      var acoes=almDiagAcoesCorrecao(d);
      var btnCorr=acoes.length&&podeCorr
        ? '<button class="btn btn-sm" style="font-size:10px;padding:2px 6px;background:#0F6E56;color:#fff;border-color:#0F6E56" onclick="almAbrirDiagnosticoDetalhe('+d._idx+',1)" title="Correção assistida">🔧</button> '
        : '';
      return '<tr>'
        +'<td><span style="font-weight:700;color:'+almDiagCritCor(d.criticidade)+';font-size:10px">'+almDiagEsc(d.criticidade)+'</span></td>'
        +'<td>'+almDiagEsc(d.origem)+'</td><td>'+almDiagEsc(d.tipo)+'</td>'
        +'<td style="max-width:140px">'+almDiagEsc(d.item_nome||'—')+'</td>'
        +'<td style="font-size:10px">'+almDiagEsc(d.codigo||d.ca||'—')+'</td>'
        +'<td style="font-size:10px">'+almDiagEsc(d.colaborador_nome||'—')+'</td>'
        +'<td style="font-size:10px">'+almDiagEsc(d.contrato_nome||'—')+'</td>'
        +'<td style="font-size:10px">'+almDiagEsc(d.deposito_nome||'—')+'</td>'
        +'<td style="text-align:right">'+d.saldo_sistema+'</td><td style="text-align:right">'+d.saldo_calculado+'</td>'
        +'<td style="text-align:right;font-weight:600;color:'+(d.diferenca?'#A32D2D':'#888')+'">'+d.diferenca+'</td>'
        +'<td style="max-width:200px;font-size:10px">'+almDiagEsc(d.descricao)+'</td>'
        +'<td style="white-space:nowrap">'+btnCorr+'<button class="btn btn-sm" style="font-size:10px;padding:2px 6px" onclick="almAbrirDiagnosticoDetalhe('+d._idx+')">Detalhe</button></td></tr>';
    }).join(''):'<tr><td colspan="13" style="padding:2rem;text-align:center;color:#0F6E56">✓ Nenhuma divergência com os filtros atuais.</td></tr>';
  }
  var b3=document.getElementById('diag-btn-lote-saldo');
  if(b3){
    var nSaldo=(r.divergencias||[]).filter(function(d){ return d.origem==='Patrimonial'&&d.tipo==='Saldo divergente'&&d.item_id; }).length;
    b3.disabled=!podeCorr||!nSaldo;
    b3.title=nSaldo?('Sincronizar '+nSaldo+' saldo(s) divergente(s)'):'Nenhum saldo divergente';
  }
  var b4=document.getElementById('diag-btn-lote-dup');
  if(b4){
    var nDup=(r.divergencias||[]).filter(function(d){ return d.origem==='Patrimonial'&&d.tipo==='Duplicidade de saldo'&&d.item_id; }).length;
    b4.disabled=!podeCorr||!nDup;
    b4.title=nDup?('Consolidar '+nDup+' duplicidade(s)'):'Nenhuma duplicidade';
  }
  var b5=document.getElementById('diag-btn-plano');
  if(b5){
    var nPlano=almDiagMontarPlano().length;
    b5.disabled=!podeCorr||!nPlano;
    b5.title=nPlano?(nPlano+' correção(ões) no plano'):'Sem correções automáticas';
  }
  var rod=document.getElementById('diag-rodape');
  if(rod) rod.textContent='Exibindo '+lista.length+' de '+r.divergencias.length+' · Patrimônio: '+r.movs_analisados+' movs · SAP: '+r.sap_movs+' movs · '+fmtD((r.analisado_em||'').slice(0,10));
  var b1=document.getElementById('diag-btn-csv'); if(b1) b1.disabled=!r.divergencias.length;
  var b2=document.getElementById('diag-btn-copiar'); if(b2) b2.disabled=!r.divergencias.length;
}

function almAbrirDiagnosticoDetalhe(idx, focoCorrecao){
  if(!_almDiagResultado||!_almDiagResultado.divergencias[idx]) return;
  var d=_almDiagResultado.divergencias[idx];
  var acoes=almDiagAcoesCorrecao(d);
  var btnsCorr='';
  if(acoes.length&&almDiagPodeCorrigir()){
    btnsCorr='<div style="margin-top:.75rem;padding:.75rem;background:#E8F5E9;border-radius:8px;border:1px solid #C8E6C9">'
      +'<div style="font-weight:700;font-size:12px;color:#1B5E20;margin-bottom:.5rem">🔧 Correção assistida (4.4 / 4.5)</div>'
      +'<div style="display:flex;flex-direction:column;gap:6px">'
      +acoes.map(function(a){
        return '<button class="btn btn-sm" style="text-align:left;font-size:11px;background:#fff;border-color:#0F6E56;color:#0F6E56"'
          +' onclick="almDiagExecutarCorrecao('+idx+',\''+a.id+'\')">'
          +'<strong>'+almDiagEsc(a.label)+'</strong>'
          +'<div style="font-size:10px;color:#666;font-weight:400;margin-top:2px">'+almDiagEsc(a.desc)+'</div></button>';
      }).join('')
      +'</div></div>';
  }else if(!almDiagPodeCorrigir()&&focoCorrecao){
    btnsCorr='<div style="margin-top:.75rem;padding:.65rem;background:#FFF8E6;border-radius:8px;font-size:11px;color:#854F0B">Correções assistidas: perfil admin ou almoxarife.</div>';
  }
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:560px">'
    +'<h3 style="margin:0 0 .75rem">🔍 '+almDiagEsc(d.tipo)+'</h3>'
    +'<div style="font-size:12px;display:grid;gap:6px">'
    +'<div><b>Criticidade:</b> <span style="color:'+almDiagCritCor(d.criticidade)+'">'+almDiagEsc(d.criticidade)+'</span></div>'
    +'<div><b>Origem:</b> '+almDiagEsc(d.origem)+'</div>'
    +'<div><b>Item:</b> '+almDiagEsc(d.item_nome||'—')+'</div>'
    +'<div><b>Colaborador:</b> '+almDiagEsc(d.colaborador_nome||'—')+'</div>'
    +'<div><b>Contrato:</b> '+almDiagEsc(d.contrato_nome||'—')+'</div>'
    +'<div><b>Depósito:</b> '+almDiagEsc(d.deposito_nome||'—')+'</div>'
    +'<div><b>Saldo sistema / calculado / dif:</b> '+d.saldo_sistema+' / '+d.saldo_calculado+' / '+d.diferenca+'</div>'
    +'<div style="margin-top:.5rem;padding:.65rem;background:#f9f9f7;border-radius:8px"><b>Descrição</b><br>'+almDiagEsc(d.descricao)+'</div>'
    +'<div style="padding:.65rem;background:#E6F1FB;border-radius:8px"><b>Recomendação</b><br>'+almDiagEsc(d.recomendacao||'—')+'</div>'
    +'<div style="padding:.65rem;background:#FFF8E6;border-radius:8px"><b>Ação sugerida</b><br>'+almDiagEsc(d.acao_sugerida||'—')+'</div>'
    +btnsCorr
    +'</div><div style="margin-top:1rem;text-align:right"><button class="btn" onclick="closeModal()">Fechar</button></div></div></div>');
}

function almExportarDiagnosticoCSV(){
  if(!_almDiagResultado||!_almDiagResultado.divergencias.length){ progShowToast('Execute o diagnóstico primeiro.'); return; }
  var cols=['origem','criticidade','tipo','item_nome','codigo','colaborador_nome','contrato_nome','deposito_nome','saldo_sistema','saldo_calculado','diferenca','descricao','recomendacao'];
  var linhas=[cols.join(';')];
  _almDiagResultado.divergencias.forEach(function(d){
    linhas.push(cols.map(function(k){ return '"'+String(d[k]==null?'':d[k]).replace(/"/g,'""')+'"'; }).join(';'));
  });
  var blob=new Blob(['\ufeff'+linhas.join('\n')],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download='diagnostico_estoque_'+dataHojeLocal()+'.csv'; a.click(); URL.revokeObjectURL(a.href);
  progShowToast('CSV exportado.');
}

function almCopiarDiagnosticoRelatorio(){
  if(!_almDiagResultado) return;
  var r=_almDiagResultado, s=r.resumo, txt=[];
  txt.push('DIAGNÓSTICO DE ESTOQUE — ERP CENA');
  txt.push('Data: '+new Date().toLocaleString('pt-BR'));
  txt.push('Total: '+s.total+' | Críticas: '+s.criticas+' | Negativos: '+s.saldos_negativos);
  txt.push('');
  (r.divergencias||[]).slice(0,200).forEach(function(d,i){
    txt.push((i+1)+'. ['+d.criticidade+'] '+d.origem+' — '+d.tipo+': '+d.item_nome);
    txt.push('   '+d.descricao);
  });
  var t=txt.join('\n');
  if(navigator.clipboard&&navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(function(){ progShowToast('Relatório copiado.'); });
  else{ var ta=document.createElement('textarea'); ta.value=t; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); progShowToast('Relatório copiado.'); }
}

function almDiagPodeCorrigir(){
  if(typeof DEMO!=='undefined'&&DEMO) return true;
  var p=(typeof usuarioLogado!=='undefined'&&usuarioLogado)?(usuarioLogado.perfil||usuarioLogado.role||''):'';
  return ['admin','almoxarife','supervisor'].indexOf(String(p).toLowerCase())>=0;
}

function almDiagAcoesCorrecao(d){
  if(!d||!almDiagPodeCorrigir()) return [];
  var acoes=[];
  if(d.origem==='Patrimonial'&&d.tipo==='Duplicidade de saldo'&&d.item_id){
    acoes.push({id:'consolidar_duplicata',label:'Consolidar linhas duplicadas',desc:'Une saldos repetidos do mesmo item no depósito (linhas extras ficam com saldo 0).'});
  }
  if(d.origem==='Patrimonial'&&d.tipo==='Devolução órfã'&&d.mov_id&&d.item_id){
    acoes.push({id:'vincular_devolucao',label:'Vincular à entrega Em uso',desc:'Associa esta devolução à entrega aberta do mesmo item.'});
  }
  if(d.origem==='Patrimonial'&&d.tipo==='Saldo divergente'&&d.item_id&&Math.abs(Number(d.diferenca)||0)>=0.001){
    acoes.push({id:'sync_saldo_mov',label:'Sincronizar saldo → '+d.saldo_calculado+' (via ajuste)',desc:'Cria movimento de ajuste para igualar o saldo registrado ao calculado pelas movimentações.'});
  }
  if(d.origem==='Patrimonial'&&d.tipo==='Saldo negativo'&&d.estoque_id){
    acoes.push({id:'zerar_negativo',label:'Corrigir saldo negativo (inventário +)',desc:'Registra ajuste positivo para zerar o saldo negativo desta linha.'});
  }
  if(d.origem==='SAP'&&d.tipo==='Divergência memória'){
    acoes.push({id:'recalc_sap',label:'Recalcular saldos SAP',desc:'Atualiza alm_estoque em memória a partir dos movimentos SAP.'});
  }
  if(d.origem==='Patrimonial'&&d.tipo==='Entrega sem entrada'&&d.item_id&&d.mov_id){
    acoes.push({id:'entrada_retroativa',label:'Registrar entrada retroativa',desc:'Cria entrada no depósito com a mesma quantidade da entrega Em uso.'});
  }
  if(d.origem==='Patrimonial'&&d.tipo==='Sem data'&&d.mov_id){
    acoes.push({id:'preencher_data_hoje',label:'Preencher data de hoje',desc:'Define data_mov como hoje nesta movimentação.'});
  }
  if(d.origem==='Patrimonial'&&d.tipo==='Sem categoria'&&d.item_id){
    acoes.push({id:'cat_ferramenta',label:'Definir categoria: Ferramenta',desc:'Atualiza tipo_item no catálogo patrimonial.'});
    acoes.push({id:'cat_epc',label:'Definir categoria: EPC',desc:'Atualiza tipo_item no catálogo patrimonial.'});
  }
  if(d.origem==='Posse'&&(d.tipo==='Colaborador dispensado'||d.tipo==='Item com dispensado'||d.tipo==='EPI colaborador inexistente')){
    acoes.push({id:'ir_desmob',label:'Abrir Desmobilização',desc:'Redireciona para recebimento de itens do colaborador.',nav:1});
  }
  if(d.origem==='Posse'&&d.tipo==='Patrimônio sem responsável'){
    acoes.push({id:'ir_extrato',label:'Abrir Extrato do Colaborador',desc:'Conferir vínculos e histórico.',nav:1});
  }
  return acoes;
}

function almDiagTemCorrecao(d){ return almDiagAcoesCorrecao(d).length>0; }

function almDiagDepFilial(depId){
  if(!depId) return null;
  var dep=(depositos||[]).find(function(x){ return String(x.id)===String(depId); });
  return dep?dep.filial_id:null;
}

async function almDiagSyncSaldoMov(d){
  var dif=Number(d.diferenca)||0;
  if(!d.item_id||Math.abs(dif)<0.001) return {ok:false,msg:'Nada a ajustar'};
  var qtd=Math.abs(dif);
  var depId=d.deposito_id||null;
  var filId=almDiagDepFilial(depId);
  var obs='Diagnóstico 4.4 — sync saldo (sist '+d.saldo_sistema+' → calc '+d.saldo_calculado+')';
  if(dif>0){
    return await almRegistrarAjustePatrimonio({item_id:d.item_id,quantidade:qtd,deposito_id:depId,filial_id:filId,
      tipo_ajuste:'Correção administrativa',motivo:obs,data_mov:dataHojeLocal()});
  }
  return await almRegistrarAjustePatrimonio({item_id:d.item_id,quantidade:qtd,deposito_id:depId,filial_id:filId,
    tipo_ajuste:'Inventário positivo',motivo:obs,data_mov:dataHojeLocal()});
}

async function almDiagZerarNegativo(d){
  var row=(typeof estoque!=='undefined'?estoque:[]).find(function(e){ return String(e.id)===String(d.estoque_id); });
  if(!row) return {ok:false,msg:'Linha de estoque não encontrada'};
  var sal=Number(row.saldo)||0;
  if(sal>=0) return {ok:false,msg:'Saldo já não é negativo'};
  var qtd=Math.abs(sal);
  var cat=almDiagCatItem(d.item_id)||{id:d.item_id,nome:row.nome};
  if(!d.item_id&&cat.id) d.item_id=cat.id;
  if(!d.item_id){
    var ref=almDiagRefCatalogoEstoque(row);
    if(ref) d.item_id=ref.id;
  }
  if(!d.item_id) return {ok:false,msg:'Item não vinculado ao catálogo — cadastre antes de ajustar'};
  return await almRegistrarAjustePatrimonio({item_id:d.item_id,quantidade:qtd,
    deposito_id:row.deposito_id||d.deposito_id,filial_id:row.filial_id||almDiagDepFilial(row.deposito_id),
    tipo_ajuste:'Inventário positivo',motivo:'Diagnóstico 4.4 — correção saldo negativo',data_mov:dataHojeLocal()});
}

async function almDiagEntradaRetroativa(d){
  var m=(movimentacoes_itens||[]).find(function(x){ return String(x.id)===String(d.mov_id); });
  if(!m) return {ok:false,msg:'Movimentação de entrega não encontrada'};
  if(!m.deposito_id) return {ok:false,msg:'Entrega sem depósito — informe o depósito antes de corrigir'};
  return await almRegistrarEntradaPatrimonio({item_id:m.item_id,quantidade:Number(m.quantidade)||1,
    deposito_id:m.deposito_id,filial_id:m.filial_id||almDiagDepFilial(m.deposito_id),
    data_mov:m.data_mov||dataHojeLocal(),motivo:'Entrada retroativa — Diagnóstico 4.4',
    obs:'Correção assistida: entrega sem entrada prévia'});
}

async function almDiagPreencherData(d){
  var m=(movimentacoes_itens||[]).find(function(x){ return String(x.id)===String(d.mov_id); });
  if(!m) return {ok:false,msg:'Movimentação não encontrada'};
  var dt=dataHojeLocal();
  if(DEMO){ m.data_mov=dt; return {ok:true,msg:'Data atualizada'}; }
  var ok=await sbUpdate('movimentacoes_itens',{data_mov:dt},'id=eq.'+m.id);
  if(!ok) return {ok:false,msg:'Falha ao atualizar data'};
  m.data_mov=dt;
  return {ok:true,msg:'Data definida: '+fmtD(dt)};
}

async function almDiagDefinirCategoria(d, tipo){
  var cat=almDiagCatItem(d.item_id);
  if(!cat) return {ok:false,msg:'Item não encontrado no catálogo'};
  tipo = almTipoCodigo(tipo) || tipo;
  if(DEMO){ cat.tipo_item=tipo; return {ok:true,msg:'Categoria: '+tipo}; }
  var ok=await sbUpdate('itens_catalogo',{tipo_item:tipo},'id=eq.'+d.item_id);
  if(!ok) return {ok:false,msg:'Falha ao atualizar catálogo'};
  cat.tipo_item=tipo;
  return {ok:true,msg:'Categoria definida: '+almDiagFmtTipoItem(tipo)};
}

async function almDiagConsolidarDuplicatas(d){
  var cat=almDiagCatItem(d.item_id);
  if(!cat){
    var row=(typeof estoque!=='undefined'?estoque:[]).find(function(e){
      return String(e.deposito_id||'')===String(d.deposito_id||'')
        &&String(e.nome||'').toLowerCase()===String(d.item_nome||'').toLowerCase();
    });
    if(row) cat=almDiagRefCatalogoEstoque(row);
  }
  if(!cat) return {ok:false,msg:'Item não identificado no catálogo — cadastre antes de consolidar'};
  var r=await almConsolidarEstoqueItemDeposito(cat,d.deposito_id||null,almDiagDepFilial(d.deposito_id));
  if(!r||!r.ok) return {ok:false,msg:'Falha ao consolidar'};
  if(!r.merged) return {ok:true,msg:'Nenhuma linha extra (já consolidado ou saldo único)'};
  return {ok:true,msg:'Consolidadas '+r.merged+' linha(s) duplicada(s)'};
}

async function almDiagVincularDevolucao(d){
  var dev=(movimentacoes_itens||[]).find(function(x){ return String(x.id)===String(d.mov_id); });
  if(!dev) return {ok:false,msg:'Devolução não encontrada'};
  if(dev.movimentacao_origem_id) return {ok:false,msg:'Devolução já possui origem'};
  var orig=(movimentacoes_itens||[]).find(function(x){
    return String(x.item_id)===String(dev.item_id)&&x.tipo_mov==='entrega'&&x.status==='Em uso'
      &&(!dev.colaborador_id||String(x.colaborador_id)===String(dev.colaborador_id));
  });
  if(!orig) return {ok:false,msg:'Nenhuma entrega Em uso correspondente encontrada'};
  if(DEMO){ dev.movimentacao_origem_id=orig.id; return {ok:true,msg:'Vinculada à entrega '+orig.id}; }
  var ok=await sbUpdate('movimentacoes_itens',{movimentacao_origem_id:orig.id},'id=eq.'+dev.id);
  if(!ok) return {ok:false,msg:'Falha ao vincular devolução'};
  dev.movimentacao_origem_id=orig.id;
  return {ok:true,msg:'Devolução vinculada à entrega de '+fmtD(orig.data_mov)};
}

function almDiagRegistrarHistorico(entry){
  _almDiagHistCorrecoes.unshift(Object.assign({em:new Date().toISOString()},entry));
  if(_almDiagHistCorrecoes.length>80) _almDiagHistCorrecoes.length=80;
  almDiagRenderHistorico();
}

function almDiagRenderHistorico(){
  var box=document.getElementById('diag-hist-wrap');
  if(!box) return;
  if(!_almDiagHistCorrecoes.length){ box.style.display='none'; box.innerHTML=''; return; }
  box.style.display='block';
  box.innerHTML='<div class="card" style="padding:.75rem 1rem;margin-bottom:1rem;border-left:3px solid #0F6E56">'
    +'<div style="font-weight:700;font-size:12px;color:#0F6E56;margin-bottom:.5rem">📜 Histórico de correções (sessão)</div>'
    +'<div style="max-height:140px;overflow-y:auto;font-size:11px">'
    +_almDiagHistCorrecoes.slice(0,25).map(function(h){
      var cor=h.ok?'#0F6E56':'#A32D2D';
      return '<div style="padding:4px 0;border-bottom:.5px solid #f0f0ee">'
        +'<span style="color:'+cor+'">'+(h.ok?'✓':'✗')+'</span> '
        +'<span style="color:#888">'+new Date(h.em).toLocaleTimeString('pt-BR')+'</span> — '
        +almDiagEsc(h.acao||'')+' · '+almDiagEsc(h.item||'')+''
        +(h.msg?(' <span style="color:#666">('+almDiagEsc(h.msg)+')</span>'):'')
        +'</div>';
    }).join('')
    +'</div></div>';
}

function almDiagMontarPlano(){
  if(!_almDiagResultado) return [];
  var ordem={Crítica:0,Alta:1,Média:2,Baixa:3};
  var plano=[], seen={};
  (_almDiagResultado.divergencias||[]).forEach(function(d,i){
    almDiagAcoesCorrecao(d).forEach(function(a){
      if(a.nav) return;
      var k=i+'|'+a.id;
      if(seen[k]) return;
      seen[k]=1;
      plano.push({idx:i,acaoId:a.id,label:a.label,desc:a.desc,item:d.item_nome||d.tipo,
        tipo:d.tipo,crit:ordem[d.criticidade]!=null?ordem[d.criticidade]:9});
    });
  });
  plano.sort(function(a,b){ return a.crit-b.crit||a.idx-b.idx; });
  return plano;
}

function almDiagAbrirPlanoCorrecao(){
  if(!almDiagPodeCorrigir()){ progShowToast('Sem permissão para correções.','erro'); return; }
  if(!_almDiagResultado){ progShowToast('Execute o diagnóstico primeiro.'); return; }
  var plano=almDiagMontarPlano();
  if(!plano.length){
    setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:520px">'
      +'<h3>📋 Plano de correção</h3><p style="font-size:13px;color:#888">Nenhuma correção automática disponível nas divergências atuais.</p>'
      +'<div style="text-align:right;margin-top:1rem"><button class="btn" onclick="closeModal()">Fechar</button></div></div></div>');
    return;
  }
  var rows=plano.map(function(p,n){
    return '<tr><td style="text-align:center">'+(n+1)+'</td>'
      +'<td><span style="font-size:10px;color:#888">'+almDiagEsc(p.tipo)+'</span><br><strong>'+almDiagEsc(p.item)+'</strong></td>'
      +'<td style="font-size:11px">'+almDiagEsc(p.label)+'</td></tr>';
  }).join('');
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:640px">'
    +'<h3 style="margin:0 0 .5rem">📋 Plano de correção (4.5)</h3>'
    +'<p style="font-size:12px;color:#666;margin:0 0 .75rem">'+plano.length+' ação(ões) automática(s), em ordem de criticidade. Revise antes de executar.</p>'
    +'<div style="max-height:50vh;overflow:auto;border:.5px solid #e0dfd8;border-radius:8px">'
    +'<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#f9f9f7;text-align:left"><th style="padding:6px 8px;width:32px">#</th><th style="padding:6px 8px">Item</th><th style="padding:6px 8px">Ação</th></tr></thead>'
    +'<tbody>'+rows+'</tbody></table></div>'
    +'<p style="font-size:11px;color:#854F0B;margin:.75rem 0 0">Cada passo exige confirmação implícita ao executar o plano. Recomendado testar em ambiente local primeiro.</p>'
    +'<div style="margin-top:1rem;display:flex;gap:8px;justify-content:flex-end">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" style="background:#0F6E56;border-color:#0F6E56" onclick="closeModal();almDiagExecutarPlano()">▶ Executar plano</button>'
    +'</div></div></div>');
}

async function almDiagExecutarCorrecaoCore(idx, acaoId){
  var d=_almDiagResultado.divergencias[idx];
  if(acaoId==='sync_saldo_mov') return await almDiagSyncSaldoMov(d);
  if(acaoId==='zerar_negativo') return await almDiagZerarNegativo(d);
  if(acaoId==='recalc_sap'){
    if(typeof almCalcularSaldo==='function') almCalcularSaldo();
    if(typeof almRender==='function') almRender();
    return {ok:true,msg:'Saldos SAP recalculados'};
  }
  if(acaoId==='entrada_retroativa') return await almDiagEntradaRetroativa(d);
  if(acaoId==='preencher_data_hoje') return await almDiagPreencherData(d);
  if(acaoId==='cat_ferramenta') return await almDiagDefinirCategoria(d,'ferramenta');
  if(acaoId==='cat_epc') return await almDiagDefinirCategoria(d,'epc');
  if(acaoId==='consolidar_duplicata') return await almDiagConsolidarDuplicatas(d);
  if(acaoId==='vincular_devolucao') return await almDiagVincularDevolucao(d);
  return {ok:false,msg:'Ação não implementada'};
}

async function almDiagReanalizarPosCorrecao(){
  if(typeof sesmtCarregarDados==='function') await sesmtCarregarDados();
  if(typeof almCarregarMovimentos==='function') await almCarregarMovimentos();
  if(typeof renderEstoque==='function') renderEstoque();
  _almDiagResultado=await almDiagnosticarDivergenciasEstoque();
  almRenderDiagnosticoEstoque();
}

async function almDiagExecutarCorrecao(idx, acaoId){
  if(_almDiagCorrigindo) return;
  if(!_almDiagResultado||!_almDiagResultado.divergencias[idx]) return;
  if(!almDiagPodeCorrigir()){ progShowToast('Sem permissão para correções.','erro'); return; }
  var d=_almDiagResultado.divergencias[idx];
  var acoes=almDiagAcoesCorrecao(d);
  var ac=acoes.find(function(a){ return a.id===acaoId; });
  if(!ac){ progShowToast('Ação indisponível.','erro'); return; }
  if(ac.nav){
    closeModal();
    if(acaoId==='ir_desmob'&&typeof navigate==='function') navigate('alm-desmobilizacao');
    else if(acaoId==='ir_extrato'&&typeof navigate==='function'){ window._extratoContext='almox'; navigate('alm-extrato-colaborador'); }
    return;
  }
  if(!confirm('Confirmar correção assistida?\n\n'+ac.label+'\n\n'+ac.desc+'\n\nItem: '+(d.item_nome||'—'))){
    return;
  }
  _almDiagCorrigindo=true;
  try{
    var res=await almDiagExecutarCorrecaoCore(idx, acaoId);
    if(res.ok){
      if(typeof auditLog==='function') auditLog('corrigir','almox','Diagnóstico: '+ac.label+' — '+(d.item_nome||d.tipo),{idx:idx,acao:acaoId});
      almDiagRegistrarHistorico({ok:true,acao:ac.label,item:d.item_nome||d.tipo,msg:res.msg||''});
      progShowToast('✓ '+(res.msg||res.nome||'Correção aplicada'));
      closeModal();
      await almDiagReanalizarPosCorrecao();
    }else{
      almDiagRegistrarHistorico({ok:false,acao:ac.label,item:d.item_nome||d.tipo,msg:res.msg||'Falha'});
      progShowToast('✗ '+(res.msg||'Falha na correção'),'erro');
    }
  }catch(e){
    console.error('almDiagExecutarCorrecao',e);
    progShowToast('Erro na correção.','erro');
  }
  _almDiagCorrigindo=false;
}

async function almDiagExecutarPlano(){
  if(_almDiagCorrigindo||!almDiagPodeCorrigir()) return;
  var plano=almDiagMontarPlano();
  if(!plano.length){ progShowToast('Plano vazio.'); return; }
  if(!confirm('Executar plano com '+plano.length+' correção(ões)?\n\nOrdem: criticidade → item.\nReanalisa ao final.')) return;
  _almDiagCorrigindo=true;
  var ok=0, fail=0;
  for(var i=0;i<plano.length;i++){
    var p=plano[i];
    try{
      var res=await almDiagExecutarCorrecaoCore(p.idx,p.acaoId);
      if(res&&res.ok){
        ok++;
        if(typeof auditLog==='function') auditLog('corrigir','almox','Plano 4.5: '+p.label+' — '+p.item,{acao:p.acaoId});
        almDiagRegistrarHistorico({ok:true,acao:p.label,item:p.item,msg:res.msg||''});
      }else{
        fail++;
        almDiagRegistrarHistorico({ok:false,acao:p.label,item:p.item,msg:(res&&res.msg)||'Falha'});
      }
    }catch(e){
      fail++;
      almDiagRegistrarHistorico({ok:false,acao:p.label,item:p.item,msg:String(e.message||e)});
    }
  }
  await almDiagReanalizarPosCorrecao();
  _almDiagCorrigindo=false;
  progShowToast('Plano concluído: '+ok+' ok, '+fail+' falha(s).');
}

async function almDiagCorrigirLoteSaldo(){
  if(!_almDiagResultado||!almDiagPodeCorrigir()) return;
  var lista=(_almDiagResultado.divergencias||[]).filter(function(d){
    return d.origem==='Patrimonial'&&d.tipo==='Saldo divergente'&&d.item_id&&Math.abs(Number(d.diferenca)||0)>=0.001;
  });
  if(!lista.length){ progShowToast('Nenhum saldo divergente para sincronizar.'); return; }
  if(!confirm('Sincronizar '+lista.length+' divergência(s) de saldo patrimonial?\n\nSerá criado um ajuste por item/depósito. Revise antes em produção.')) return;
  _almDiagCorrigindo=true;
  var ok=0, fail=0;
  for(var i=0;i<lista.length;i++){
    var r=await almDiagSyncSaldoMov(lista[i]);
    if(r&&r.ok){ ok++; almDiagRegistrarHistorico({ok:true,acao:'Sync saldo (lote)',item:lista[i].item_nome,msg:r.msg||''}); }
    else{ fail++; almDiagRegistrarHistorico({ok:false,acao:'Sync saldo (lote)',item:lista[i].item_nome,msg:(r&&r.msg)||'Falha'}); }
  }
  await almDiagReanalizarPosCorrecao();
  _almDiagCorrigindo=false;
  progShowToast('Lote saldos: '+ok+' ok, '+fail+' falha(s).');
}

async function almDiagConsolidarDuplicatasLote(){
  if(!_almDiagResultado||!almDiagPodeCorrigir()) return;
  var map={}, lista=[];
  (_almDiagResultado.divergencias||[]).forEach(function(d){
    if(d.origem!=='Patrimonial'||d.tipo!=='Duplicidade de saldo'||!d.item_id) return;
    var k=String(d.item_id)+'|'+String(d.deposito_id||'');
    if(map[k]) return;
    map[k]=1;
    lista.push(d);
  });
  if(!lista.length){ progShowToast('Nenhuma duplicidade de saldo para consolidar.'); return; }
  if(!confirm('Consolidar '+lista.length+' grupo(s) de linhas duplicadas?\n\nSaldos serão somados na linha principal.')) return;
  _almDiagCorrigindo=true;
  var ok=0, fail=0, merged=0;
  for(var i=0;i<lista.length;i++){
    var r=await almDiagConsolidarDuplicatas(lista[i]);
    if(r&&r.ok){
      ok++;
      merged+=Number((r.msg||'').match(/\d+/)||0);
      almDiagRegistrarHistorico({ok:true,acao:'Consolidar duplicatas (lote)',item:lista[i].item_nome,msg:r.msg||''});
    }else{
      fail++;
      almDiagRegistrarHistorico({ok:false,acao:'Consolidar duplicatas (lote)',item:lista[i].item_nome,msg:(r&&r.msg)||'Falha'});
    }
  }
  await almDiagReanalizarPosCorrecao();
  _almDiagCorrigindo=false;
  progShowToast('Consolidação: '+ok+' ok, '+fail+' falha(s).');
}

// ── Métricas ─────────────────────────────────────────────────
function almRenderMetricas(){
  var el = document.getElementById('alm-metricas'); if(!el) return;
  var totalItens  = alm_estoque.length;
  var totalEntrad = alm_movimentos.filter(function(m){return m.tipo==='entrada';}).length;
  var totalSaidas = alm_movimentos.filter(function(m){return m.tipo==='saida';}).length;
  var emCampo     = alm_movimentos.filter(function(m){return m.tipo==='saida'&&m.status==='em_campo';}).length;
  var retornoPend = alm_estoque.filter(function(e){return e.em_campo>0;}).length;
  // Valor total em estoque = saldo × valor_unitario
  var valorEstoque = alm_estoque.reduce(function(s,e){
    return s + ((e.saldo||0) * (e.valor_unitario||0));
  }, 0);

  var indicadores = [
    {l:'Itens no estoque',  v:totalItens,  c:'#555',     fmt:false},
    {l:'Entradas',          v:totalEntrad, c:'#3B6D11',  fmt:false},
    {l:'Saídas',            v:totalSaidas, c:'#185FA5',  fmt:false},
    {l:'Em campo',          v:emCampo,     c:'#854F0B',  fmt:false},
    {l:'Pendentes retorno', v:retornoPend, c:'#A32D2D',  fmt:false},
    {l:'Valor em estoque',  v:valorEstoque,c:'#085041',  fmt:true },
  ];

  el.innerHTML = indicadores.map(function(m){
    var display = m.fmt
      ? '<div style="font-size:13px;font-weight:700;color:'+m.c+'">R$ '+fmtMoeda(m.v)+'</div>'
      : '<div style="font-size:20px;font-weight:700;color:'+m.c+'">'+m.v+'</div>';
    return '<div style="background:#f9f9f7;border-radius:8px;padding:.6rem;text-align:center">'      +'<div style="font-size:10px;color:#888;margin-bottom:2px">'+m.l+'</div>'      +display      +'</div>';
  }).join('');
}

// ── Tabs ─────────────────────────────────────────────────────
function almMostrarTab(tab){
  _almTabAtual = tab;
  ['estoque','entradas','saidas','campo','retorno','reservas','nfs'].forEach(function(t){
    var btn=document.getElementById('alm-tab-'+t);
    var el =document.getElementById('alm-content-'+t);
    if(btn){btn.style.borderBottomColor=t===tab?'#1a1a18':'transparent';btn.style.color=t===tab?'#1a1a18':'#888';btn.style.fontWeight=t===tab?'700':'600';}
    if(el) el.style.display=t===tab?'':'none';
  });
  // ALM-NF-1: aquece o cache de NFs ao abrir Entradas/NFs (habilita 📄 Ver NF e a consulta)
  if((tab==='entradas'||tab==='nfs') && typeof almNfGarantirCache==='function'
     && typeof _almNfCache!=='undefined' && !_almNfCache.ok && _almNfCache.disponivel!==false){
    almNfGarantirCache().then(function(){ almRender(); });
  }
  almRender();
}

function almRender(){
  var cid   = (document.getElementById('alm-fil-cont')||{}).value||'';
  var busca = ((document.getElementById('alm-fil-busca')||{}).value||'').toLowerCase();

  if(_almTabAtual==='estoque')   almRenderEstoque(cid,busca);
  else if(_almTabAtual==='entradas') almRenderMovimentos('entrada',cid,busca);
  else if(_almTabAtual==='saidas')   almRenderMovimentos('saida',cid,busca);
  else if(_almTabAtual==='campo')    almRenderCampo(cid,busca);
  else if(_almTabAtual==='retorno')  almRenderRetorno(cid,busca);
  else if(_almTabAtual==='reservas') almRenderReservas(cid,busca);
  else if(_almTabAtual==='nfs'){ if(typeof almNfPopularFiltroDep==='function') almNfPopularFiltroDep(); if(typeof almNfRenderConsulta==='function') almNfRenderConsulta(); }
}

// ── Estoque atual ────────────────────────────────────────────
function almRenderEstoque(cid,busca){
  var tb=document.getElementById('alm-tbody-estoque');if(!tb)return;
  var rows=alm_estoque.filter(function(e){
    if(cid&&e.contrato_id!==cid&&e.contrato_id!=='geral'&&e.contrato_id!=='')return false;
    if(busca&&e.material_desc.toLowerCase().indexOf(busca)<0&&(e.codigo_sap||'').indexOf(busca)<0)return false;
    return true;
  });
  if(!rows.length){tb.innerHTML='<tr><td colspan="12" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum material no estoque. Use "+ Entrada" para registrar.</td></tr>';return;}
  tb.innerHTML=rows.map(function(e){
    var cont=contratos.find(function(c){return c.id===e.contrato_id;})||{codigo:'Geral'};
    var saldoCor=e.saldo<=0?'#A32D2D':e.saldo<=5?'#854F0B':'#3B6D11';
    return '<tr>'
      +'<td style="font-weight:500">'+e.material_desc+'</td>'
      +'<td style="font-family:monospace;font-size:11px">'+(e.codigo_sap||'—')+'</td>'
      +'<td><span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:11px">'+cont.codigo+'</span></td>'
      +'<td style="font-size:12px">'+e.unidade+'</td>'
      +'<td style="text-align:right;color:#3B6D11">'+e.entradas+'</td>'
      +'<td style="text-align:right;color:#185FA5">'+e.saidas+'</td>'
      +'<td style="text-align:right;color:#854F0B">'+e.em_campo+'</td>'
      +'<td style="text-align:right;color:#085041">'+e.devolucoes+'</td>'
      +'<td style="text-align:right;font-weight:700;font-size:14px;color:'+saldoCor+'">'+e.saldo+'</td>'
      +'<td style="text-align:right;font-size:12px;color:#555">'+(e.valor_unitario>0?'R$ '+fmtMoeda(e.valor_unitario):'—')+'</td>'
      +'<td style="text-align:right;font-size:12px;font-weight:700;color:'+(e.valor_total>0?'#3B6D11':'#aaa')+'">'+(e.valor_total>0?'R$ '+fmtMoeda(e.valor_total):'—')+'</td>'
      +'<td><button class="btn btn-sm" data-mat="'+e.material_id+'" data-cid="'+e.contrato_id+'" style="font-size:10px">Movimentar</button></td>'
      +'</tr>';
  }).join('');
  setTimeout(function(){
    rows.forEach(function(e){
      tb.querySelectorAll('[data-mat="'+e.material_id+'"]').forEach(function(b){
        b.onclick=function(){almMenuMovimento(e);};
      });
    });
  },50);
}

// ── Movimentos ───────────────────────────────────────────────
function almRenderMovimentos(tipo,cid,busca){
  var tbId = tipo==='entrada'?'alm-tbody-entradas':'alm-tbody-saidas';
  var tb=document.getElementById(tbId);if(!tb)return;
  var rows=alm_movimentos.filter(function(m){
    if(m.tipo!==tipo&&!(tipo==='saida'&&(m.tipo==='saida'||m.tipo==='aplicacao')))return false;
    if(cid&&m.contrato_id!==cid)return false;
    if(busca&&(m.material_desc||'').toLowerCase().indexOf(busca)<0)return false;
    return true;
  });
  if(!rows.length){tb.innerHTML='<tr><td colspan="9" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum registro.</td></tr>';return;}
  if(tipo==='entrada'){
    tb.innerHTML=rows.map(function(m){
      var cont=contratos.find(function(c){return c.id===m.contrato_id;})||{codigo:'Geral'};
      return '<tr>'
        +'<td style="font-size:12px">'+fmtD(m.data||m.criado_em.split('T')[0])+'</td>'
        +'<td style="font-weight:500">'+m.material_desc+'</td>'
        +'<td><span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:11px">'+cont.codigo+'</span></td>'
        +'<td style="font-size:12px">'+(m.origem||'—')+'</td>'
        +'<td style="text-align:right;color:#3B6D11;font-weight:600">'+m.qtd+'</td>'
        +'<td style="font-size:12px">'+m.unidade+'</td>'
        +'<td style="font-size:11px;color:#888">'+(m.nota_ref||'—')+'</td>'
        +'<td style="font-size:11px;color:#888">'+(m.registrado_por||'—')+'</td>'
        +'<td>'+((typeof almNfPorMovId==='function'&&almNfPorMovId(m.id,true))?'<button class="btn btn-sm" onclick="almNfAbrirDetalhe(\''+String((almNfPorMovId(m.id,true)||{}).id||'').replace(/[^a-zA-Z0-9_-]/g,'')+'\')" style="font-size:10px;margin-right:4px">📄 Ver NF</button>':'')+'<button class="btn btn-sm" data-mid="'+m.id+'" style="color:#A32D2D;border-color:#A32D2D;font-size:10px">Estornar</button></td>'
        +'</tr>';
    }).join('');
  } else {
    tb.innerHTML=rows.map(function(m){
      var stCor={em_campo:'#854F0B',aplicado:'#3B6D11',devolvido:'#185FA5'}[m.status]||'#555';
      var stLabel={em_campo:'Em campo',aplicado:'Aplicado',devolvido:'Devolvido'}[m.status]||m.status;
      return '<tr>'
        +'<td style="font-size:12px">'+fmtD(m.data||m.criado_em.split('T')[0])+'</td>'
        +'<td style="font-weight:500">'+m.material_desc+'</td>'
        +'<td style="font-size:12px">'+(m.projeto_nome||m.os_ref||'—')+'</td>'
        +'<td style="font-size:12px">'+(m.equipe_nome||'—')+'</td>'
        +'<td style="text-align:right;color:#185FA5;font-weight:600">'+m.qtd+'</td>'
        +'<td style="text-align:right;color:#3B6D11">'+(m.qtd_aplicada||0)+'</td>'
        +'<td style="text-align:right;color:#854F0B">'+(m.qtd_devolvida||0)+'</td>'
        +'<td><span style="background:'+stCor+'22;color:'+stCor+';border-radius:4px;padding:1px 6px;font-size:11px;font-weight:600">'+stLabel+'</span></td>'
        +'<td>'+(m.status==='em_campo'?'<button class="btn btn-sm" data-sid="'+m.id+'" style="color:#3B6D11;border-color:#3B6D11;font-size:10px">Baixar</button>':'')+'</td>'
        +'</tr>';
    }).join('');
    setTimeout(function(){
      rows.filter(function(m){return m.status==='em_campo';}).forEach(function(m){
        var b=tb.querySelector('[data-sid="'+m.id+'"]');
        if(b)b.onclick=function(){almAbrirBaixa(m.id);};
      });
    },50);
  }
}

// ── Em campo ─────────────────────────────────────────────────
function almRenderCampo(cid,busca){
  var tb=document.getElementById('alm-tbody-campo');if(!tb)return;
  var rows=alm_movimentos.filter(function(m){
    if(m.tipo!=='saida'||m.status!=='em_campo')return false;
    if(cid&&m.contrato_id!==cid)return false;
    if(busca&&(m.material_desc||'').toLowerCase().indexOf(busca)<0)return false;
    return true;
  });
  if(!rows.length){tb.innerHTML='<tr><td colspan="7" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum material em campo no momento.</td></tr>';return;}
  tb.innerHTML=rows.map(function(m){
    var qtdCampo=m.qtd-(m.qtd_aplicada||0)-(m.qtd_devolvida||0);
    return '<tr>'
      +'<td style="font-weight:500">'+m.material_desc+'</td>'
      +'<td style="font-size:12px">'+(m.projeto_nome||m.os_ref||'—')+'</td>'
      +'<td style="font-size:12px">'+(m.equipe_nome||'—')+'</td>'
      +'<td style="font-size:12px">'+fmtD(m.data||m.criado_em.split('T')[0])+'</td>'
      +'<td style="text-align:right;font-weight:700;color:#854F0B">'+qtdCampo+'</td>'
      +'<td style="font-size:12px">'+m.unidade+'</td>'
      +'<td><button class="btn btn-sm" data-sid="'+m.id+'" style="font-size:10px">Registrar baixa</button></td>'
      +'</tr>';
  }).join('');
  setTimeout(function(){
    rows.forEach(function(m){
      var b=tb.querySelector('[data-sid="'+m.id+'"]');
      if(b)b.onclick=function(){almAbrirBaixa(m.id);};
    });
  },50);
}

// ── Lista de retorno ──────────────────────────────────────────
function almRenderRetorno(cid,busca){
  var tb=document.getElementById('alm-tbody-retorno');if(!tb)return;
  var rows=alm_movimentos.filter(function(m){
    if(m.tipo!=='saida'||m.status!=='em_campo')return false;
    var qtdCampo=m.qtd-(m.qtd_aplicada||0)-(m.qtd_devolvida||0);
    if(qtdCampo<=0)return false;
    if(cid&&m.contrato_id!==cid)return false;
    if(busca&&(m.material_desc||'').toLowerCase().indexOf(busca)<0)return false;
    return true;
  });
  if(!rows.length){tb.innerHTML='<tr><td colspan="7" style="padding:1.5rem;text-align:center;color:#aaa;font-size:13px">✔ Nenhum material pendente de retorno.</td></tr>';return;}
  tb.innerHTML=rows.map(function(m){
    var qtdCampo=m.qtd-(m.qtd_aplicada||0)-(m.qtd_devolvida||0);
    return '<tr style="background:#FFFDF0">'
      +'<td style="font-weight:500">'+m.material_desc+'</td>'
      +'<td style="font-size:12px">'+(m.projeto_nome||m.os_ref||'—')+'</td>'
      +'<td style="font-size:12px">'+(m.equipe_nome||'—')+'</td>'
      +'<td style="font-size:12px">'+fmtD(m.data||m.criado_em.split('T')[0])+'</td>'
      +'<td style="text-align:right;font-weight:700;color:#A32D2D">'+qtdCampo+'</td>'
      +'<td style="font-size:12px">'+m.unidade+'</td>'
      +'<td><button class="btn btn-sm" data-sid="'+m.id+'" style="color:#3B6D11;border-color:#3B6D11;font-size:10px">↩ Devolver</button></td>'
      +'</tr>';
  }).join('');
  setTimeout(function(){
    rows.forEach(function(m){
      var b=tb.querySelector('[data-sid="'+m.id+'"]');
      if(b)b.onclick=function(){almAbrirBaixa(m.id,true);};
    });
  },50);
}

// ── MODAIS ────────────────────────────────────────────────────

function almGetMatOpts(cid){
  return almMateriaisCatalogoUnicos(cid).map(function(m){
    return '<option value="'+m.id+'" data-desc="'+escHtml(m.descricao)+'" data-sap="'+escHtml(m.codigo_sap||'')+'" data-un="'+(m.unidade||'UN')+'">'
      +escHtml(m.descricao)+(m.codigo_sap?' · SAP '+m.codigo_sap:'')+'</option>';
  }).join('');
}


function almAtualizarValorTotal(){
  var qtd  = parseFloat((document.getElementById('alm-e-qtd')||{}).value)||0;
  var unit = parseFloat((document.getElementById('alm-e-valor')||{}).value)||0;
  var tot  = document.getElementById('alm-e-vtotal');
  if(tot) tot.value = (qtd*unit>0 ? (qtd*unit).toFixed(2) : '');
}


function almAbrirEntrada(){
  openEntradaEstoque('sap');
}

function almAtualizarMatEntrada(){
  var cid=(document.getElementById('alm-e-cont')||{}).value||'';
  var sel=document.getElementById('alm-e-mat');if(!sel)return;
  sel.innerHTML='<option value="">Selecione ou busque...</option>'+almGetMatOpts(cid);
}

function almPreencherMatEntrada(){
  var sel=document.getElementById('alm-e-mat');if(!sel||!sel.value)return;
  var opt=sel.options[sel.selectedIndex];
  var d=document.getElementById('alm-e-desc');if(d)d.value=opt.getAttribute('data-desc')||'';
  var s=document.getElementById('alm-e-sap');if(s)s.value=opt.getAttribute('data-sap')||'';
  var u=document.getElementById('alm-e-un');if(u)u.value=opt.getAttribute('data-un')||'UN';
}

function almAbrirSaida(){
  var cid=(document.getElementById('alm-fil-cont')||{}).value||'';
  var matOpts=almGetMatOpts(cid);
  var projOpts=sot_projetos.filter(function(p){return !cid||p.contrato_id===cid;})
    .map(function(p){return '<option value="'+p.id+'">'+p.nome+'</option>';}).join('');
  var eqOpts=equipes_disp.filter(function(e){return !cid||e.contrato_id===cid;})
    .map(function(e){return '<option value="'+e.id+'">'+e.codigo+' — '+e.nome+'</option>';}).join('');
  var hoje=dataHoje();

  var html='<div class="modal-bg"><div class="modal" style="max-width:500px">'
    +'<h3>⬆ Saída de Material para Campo</h3>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-bottom:1rem">'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Material *</label>'
    +'<select class="inp" id="alm-s-mat" style="width:100%" onchange="almPreencherMatSaida()">'
    +'<option value="">Selecione...</option>'+matOpts+'</select></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição *</label>'
    +'<input class="inp" id="alm-s-desc" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Quantidade *</label>'
    +'<input class="inp" id="alm-s-qtd" type="number" min="0.001" step="0.001" style="width:100%" value="1"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Unidade</label>'
    +'<select class="inp" id="alm-s-un" style="width:100%">'
    +['UN','M','M²','KG','PC','CX','CJ','GL','PST','VÃO','H'].map(function(u){return '<option>'+u+'</option>';}).join('')
    +'</select></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Data</label>'
    +'<input class="inp" id="alm-s-data" type="date" style="width:100%" value="'+hoje+'"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">OS / Referência</label>'
    +'<input class="inp" id="alm-s-os" style="width:100%" placeholder="OS 12345"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Projeto</label>'
    +'<select class="inp" id="alm-s-proj" style="width:100%">'
    +'<option value="">Sem projeto vinculado</option>'+projOpts+'</select></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Equipe</label>'
    +'<select class="inp" id="alm-s-equipe" style="width:100%">'
    +'<option value="">Sem equipe vinculada</option>'+eqOpts+'</select></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação</label>'
    +'<textarea class="inp" id="alm-s-obs" style="width:100%;height:45px"></textarea></div>'
    +'</div>'
    +'<div style="background:#E6F1FB;border-radius:8px;padding:.6rem .75rem;margin-bottom:1rem;font-size:12px;color:#185FA5">'
    +'ℹ O material sairá com status <b>"Em campo"</b>. Ao retornar, registre a baixa informando o que foi aplicado e o que voltou.'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="alm-salvar-saida" style="flex:1;background:#185FA5;border-color:#185FA5">Registrar saída</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var btn=document.getElementById('alm-salvar-saida');if(!btn)return;
    btn.onclick=async function(){
      var g=function(id){return (document.getElementById(id)||{}).value||'';};
      var desc=g('alm-s-desc').trim();
      var qtd=parseFloat(g('alm-s-qtd'))||0;
      if(!desc||!qtd){alert('Informe material e quantidade.');return;}
      var projSel=document.getElementById('alm-s-proj');
      var projOpt=projSel&&projSel.value?projSel.options[projSel.selectedIndex]:null;
      var eqSel=document.getElementById('alm-s-equipe');
      var eqOpt=eqSel&&eqSel.value?eqSel.options[eqSel.selectedIndex]:null;
      var mov={
        id:'alm'+Date.now(),tipo:'saida',status:'em_campo',
        material_id:g('alm-s-mat'),material_desc:desc,
        unidade:g('alm-s-un')||'UN',
        contrato_id:cid,qtd:qtd,qtd_aplicada:0,qtd_devolvida:0,
        data:g('alm-s-data'),os_ref:g('alm-s-os'),
        projeto_id:g('alm-s-proj'),projeto_nome:projOpt?projOpt.text:'',
        equipe_id:g('alm-s-equipe'),equipe_nome:eqOpt?eqOpt.text.split(' — ')[0]:'',
        obs:g('alm-s-obs'),
        registrado_por:usuarioLogado?usuarioLogado.nome:'',
        criado_em:new Date().toISOString()
      };
      btn.disabled=true;
      btn.textContent='Salvando...';
      var ok=await almSalvarMovimentoSeguro(mov);
      if(ok) closeModal();
      else{ btn.disabled=false; btn.textContent='Registrar saída'; }
    };
  },50);
}

function almPreencherMatSaida(){
  var sel=document.getElementById('alm-s-mat');if(!sel||!sel.value)return;
  var opt=sel.options[sel.selectedIndex];
  var d=document.getElementById('alm-s-desc');if(d)d.value=opt.getAttribute('data-desc')||'';
  var u=document.getElementById('alm-s-un');if(u)u.value=opt.getAttribute('data-un')||'UN';
}

// ── Baixa (aplicação + devolução) ────────────────────────────
function almAbrirBaixa(movId, soDevolucao){
  var mov=alm_movimentos.find(function(m){return m.id===movId;});if(!mov)return;
  var qtdCampo=mov.qtd-(mov.qtd_aplicada||0)-(mov.qtd_devolvida||0);

  var html='<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3>'+(soDevolucao?'↩ Registrar Devolução':'📋 Baixa de Material')+'</h3>'
    +'<div style="background:#f9f9f7;border-radius:8px;padding:.75rem;margin-bottom:1rem;font-size:13px">'
    +'<b>'+mov.material_desc+'</b><br>'
    +'<span style="font-size:11px;color:#888">Em campo: '+qtdCampo+' '+mov.unidade+' • '+( mov.projeto_nome||mov.os_ref||'Sem projeto')+'</span>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-bottom:1rem">'
    +(soDevolucao?''
      :'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Quantidade aplicada</label>'
        +'<input class="inp" id="alm-b-aplic" type="number" min="0" max="'+qtdCampo+'" style="width:100%" value="0"/></div>')
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Quantidade devolvida</label>'
    +'<input class="inp" id="alm-b-devol" type="number" min="0" max="'+qtdCampo+'" style="width:100%" value="'+( soDevolucao?qtdCampo:0)+'"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação</label>'
    +'<textarea class="inp" id="alm-b-obs" style="width:100%;height:45px"></textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="alm-confirmar-baixa" style="flex:1">Confirmar</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var btn=document.getElementById('alm-confirmar-baixa');if(!btn)return;
    btn.onclick=async function(){
      var aplic=parseFloat((document.getElementById('alm-b-aplic')||{}).value)||0;
      var devol=parseFloat((document.getElementById('alm-b-devol')||{}).value)||0;
      var obs=(document.getElementById('alm-b-obs')||{}).value||'';
      if(aplic+devol>qtdCampo){alert('A soma não pode ser maior que a quantidade em campo ('+qtdCampo+').');return;}
      var novaQtdAplicada=(mov.qtd_aplicada||0)+aplic;
      var novaQtdDevolvida=(mov.qtd_devolvida||0)+devol;
      var novoStatus=(novaQtdAplicada+novaQtdDevolvida)>=mov.qtd?'concluido':'em_campo';
      var patch={qtd_aplicada:novaQtdAplicada,qtd_devolvida:novaQtdDevolvida,status:novoStatus};
      btn.disabled=true;
      btn.textContent='Salvando...';
      var ok=await almAtualizarMovimentoSeguro(movId,patch);
      if(!ok){ btn.disabled=false; btn.textContent='Confirmar'; return; }
      if(devol>0){
        var movDevol={
          id:'alm'+Date.now(),tipo:'devolucao',
          material_id:mov.material_id,material_desc:mov.material_desc,
          codigo_sap:mov.codigo_sap,unidade:mov.unidade,contrato_id:mov.contrato_id,qtd:devol,
          data:dataHojeLocal(),saida_ref:movId,
          projeto_id:mov.projeto_id,projeto_nome:mov.projeto_nome,
          obs:obs,registrado_por:usuarioLogado?usuarioLogado.nome:'',
          criado_em:new Date().toISOString(),status:'concluido'
        };
        ok=await almSalvarMovimentoSeguro(movDevol);
        if(!ok){ btn.disabled=false; btn.textContent='Confirmar'; return; }
      }
      closeModal();
    };
  },50);
}

function almAbrirDevolucao(){
  // Mostrar materiais em campo para devolver
  var emCampo=alm_movimentos.filter(function(m){return m.tipo==='saida'&&m.status==='em_campo';});
  if(!emCampo.length){alert('Nenhum material em campo para devolver.');return;}
  var cid=(document.getElementById('alm-fil-cont')||{}).value||'';
  var lista=emCampo.filter(function(m){return !cid||m.contrato_id===cid;});
  if(!lista.length){alert('Nenhum material em campo para este contrato.');return;}
  almMostrarTab('retorno');
}

function almMenuMovimento(estItem){
  // Mini menu para movimentar um item do estoque
  var html='<div class="modal-bg"><div class="modal" style="max-width:320px">'
    +'<h3>'+estItem.material_desc+'</h3>'
    +'<div style="font-size:13px;color:#888;margin-bottom:1rem">Saldo: <b style="color:#1a1a18">'+estItem.saldo+' '+estItem.unidade+'</b></div>'
    +'<div style="display:flex;flex-direction:column;gap:8px">'
    +'<button class="btn btn-pri" id="amv-entrada">⬇ Registrar entrada</button>'
    +'<button class="btn" id="amv-saida" style="color:#185FA5;border-color:#185FA5">⬆ Registrar saída para campo</button>'
    +'<button class="btn" onclick="closeModal()" style="color:#888">Cancelar</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var be=document.getElementById('amv-entrada');if(be)be.onclick=function(){closeModal();openEntradaEstoque('sap');};
    var bs=document.getElementById('amv-saida');if(bs)bs.onclick=function(){closeModal();almAbrirSaida();};
  },50);
}


