function isContratoObras(contrato_id){
  if(!contrato_id) return false;
  // Lista hardcoded (existente)
  if(CONTRATOS_OBRAS_IDS.indexOf(contrato_id) >= 0) return true;
  // Verificar no array de contratos carregados do banco
  var cont = contratos.find(function(c){ return c.id === contrato_id; });
  if(!cont) return false;
  // Incluir se modalidade for de obras ou se código/nome contiver palavras-chave
  var cod  = (cont.codigo||'').toUpperCase();
  var nome = (cont.nome||'').toUpperCase();
  var modalidade = (cont.modalidade_trabalho||cont.modalidade||'').toUpperCase();
  // Modalidade explícita
  if(modalidade.indexOf('OBRA')>=0 || modalidade.indexOf('SOT')>=0 || modalidade.indexOf('PROJETO')>=0) return true;
  // Código ou nome que indique obras
  var palavrasChave = ['OBRA','RDSE','RDSC','OUTFIT','PLPT','ETD','COMGAS','CTEEP','AUTOMAC','PARTICUL','SOT'];
  return palavrasChave.some(function(p){ return cod.indexOf(p)>=0 || nome.indexOf(p)>=0; });
}

// Identifica se o contrato é do tipo PLPT (usa esteira produtiva)
function isContratoPLPT(contrato_id){
  if(!contrato_id) return false;
  // Verificar pelo _plptProgCid ativo
  if(typeof _plptProgCid!=='undefined' && _plptProgCid && contrato_id===_plptProgCid) return true;
  var cont = contratos.find(function(c){ return c.id===contrato_id; });
  if(!cont) return false;
  var cod  = (cont.codigo||'').toUpperCase();
  var nome = (cont.nome||'').toUpperCase();
  var mod  = (cont.modalidade_trabalho||cont.modalidade||cont.tipo||'').toUpperCase();
  return cod.indexOf('PLPT')>=0 || nome.indexOf('PLPT')>=0 || mod.indexOf('PLPT')>=0;
}

// ── Entrar no painel de contrato ─────────────────────────────
function coVoltarParaObras(){
  // Voltar para pg-obras-projetos sem chamar showMain que esconde tudo
  document.querySelectorAll('[id^="pg-"]').forEach(function(el){
    if(el.id!=='pg-app'&&el.id!=='pg-login'&&el.id!=='pg-app-content')
      el.classList.add('hidden');
  });
  var pg=document.getElementById('pg-obras-projetos');
  if(pg) pg.style.display='';
  if(pg) pg.classList.remove('hidden');
}

function coPopularSeletor(){
  var sel = document.getElementById('co-contrato-selector');
  if(!sel) return;
  // Montar botões de contratos de obras em ordem alfabética
  var contratosObras = contratos.filter(function(c){
    return isContratoObras(c.id);
  }).sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||'','pt-BR',{sensitivity:'base'}); });

  var html = '<span style="font-size:10px;color:#888;white-space:nowrap;margin-right:4px">Contrato:</span>';
  contratosObras.forEach(function(c){
    var ativo = c.id === _coContratoAtual;
    html += '<button onclick="coAbrirContrato(\''+c.id+'\')" style="'
      +'padding:3px 10px;border-radius:5px;border:.5px solid '+(ativo?'#1a1a18':'#e0dfd8')+';'
      +'background:'+(ativo?'#1a1a18':'#fff')+';color:'+(ativo?'#fff':'#555')+';'
      +'font-size:11px;font-weight:'+(ativo?'700':'500')+';cursor:pointer;white-space:nowrap">'
      +c.nome+'</button>';
  });
  sel.innerHTML = html;
}

function coAbrirContrato(contrato_id){
  var cont = contratos.find(function(c){return c.id===contrato_id;});
  if(!cont) return;
  _coContratoAtual = contrato_id;
  window._filtroContrato = contrato_id;
  _progContrato = contrato_id;
  coPopularSeletor(); // atualiza seletor de contratos no topo

  // Atualizar header
  var badge = document.getElementById('co-badge');
  var nome  = document.getElementById('co-nome');
  var sub   = document.getElementById('co-sub');
  if(badge) badge.textContent = cont.codigo;
  if(nome)  nome.textContent  = cont.nome;
  if(sub)   sub.textContent   = 'Contrato de Obras • ' + new Date().toLocaleDateString('pt-BR');

  // Mostrar/ocultar aba SOT
  var tabProj = document.getElementById('co-tab-projetos');
  if(contrato_id === CONTRATO_SOT_ID && tabProj){
    tabProj.textContent = '🏗 Projetos SOT';
  } else if(tabProj){
    tabProj.textContent = '📋 Projetos';
  }

  // Mostrar a página
  document.querySelectorAll('[id^="pg-"]').forEach(function(el){
    if(el.id!=='pg-app'&&el.id!=='pg-login'&&el.id!=='pg-app-content')
      el.classList.add('hidden');
  });
  var pg = document.getElementById('pg-contrato-obras');
  if(pg) pg.classList.remove('hidden');

  // Carregar projetos do banco para este contrato antes de renderizar
  if(!DEMO && isContratoObras(contrato_id)){
    sbFetchPaged('sot_projetos',{filters:['contrato_id=eq.'+contrato_id],order:'criado_em.desc'})
      .then(function(rows){
        if(rows&&rows.length){
          rows.forEach(function(p){
            var idx = sot_projetos.findIndex(function(x){return x.id===p.id;});
            if(idx>=0) sot_projetos[idx]=p; else sot_projetos.push(p);
          });
        }
        coMostrarTab('projetos');
      }).catch(function(){ coMostrarTab('projetos'); });
  } else {
    coMostrarTab('projetos');
  }
}

// ── Navegação entre abas ─────────────────────────────────────
function coMostrarTab(tab){
  _coTabAtual = tab;
  var abas = ['projetos','equipe','programacao','servicos','materiais','indicadores'];
  abas.forEach(function(a){
    var btn = document.getElementById('co-tab-'+a);
    var el  = document.getElementById('co-content-'+a);
    if(btn){
      btn.style.borderBottomColor = a===tab ? '#1a1a18' : 'transparent';
      btn.style.color = a===tab ? '#1a1a18' : '#888';
      btn.style.fontWeight = a===tab ? '700' : '600';
    }
    if(el) el.style.display = a===tab ? '' : 'none';
  });

  var cid = _coContratoAtual;
  if(tab==='projetos')     coRenderProjetos();
  else if(tab==='equipe')  coRenderEquipe();
  else if(tab==='programacao') coRenderProgramacao();
  else if(tab==='servicos') coRenderServicos();
  else if(tab==='materiais'){
    // Reset fetch flag so fresh data is loaded each time
    if(window._coMatFetched) delete window._coMatFetched[_coContratoAtual];
    // Garantir composicao_dia e colaboradores carregados
    _coEnsureComposicao(function(){ coRenderMateriais(); });
  }
  else if(tab==='indicadores') coRenderIndicadores();
}

// ── Projetos ─────────────────────────────────────────────────
function coRenderProjetos(){
  var cid = _coContratoAtual;
  var wrap = document.getElementById('co-proj-lista');
  var metr = document.getElementById('co-proj-metricas');
  if(!wrap) return;

  var isSot = isContratoObras(cid);

  // Se contrato de obras, sempre buscar do banco para garantir dados frescos
  if(isSot && cid && !DEMO){
    var jaTemDoBanco = sot_projetos.some(function(p){ return p.contrato_id===cid&&p._carregado; });
    if(!jaTemDoBanco){
      wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Carregando projetos...</div>';
      sbFetchPaged('sot_projetos',{filters:['contrato_id=eq.'+cid],order:'criado_em.desc'})
        .then(function(rows){
          // Remover entradas antigas deste contrato e inserir as novas
          sot_projetos = sot_projetos.filter(function(p){ return p.contrato_id!==cid; });
          if(rows&&rows.length) rows.forEach(function(p){ p._carregado=true; sot_projetos.push(p); });
          coRenderProjetos();
        }).catch(function(){ coRenderProjetos(); });
      return;
    }
  }

  var stFil  = (document.getElementById('co-proj-status')||{}).value||'';
  var busca  = ((document.getElementById('co-proj-busca')||{}).value||'').toLowerCase();

  // Vincular botão novo
  var btnNovo = document.getElementById('co-proj-novo');
  if(btnNovo) btnNovo.onclick = function(){openNovoProjetoContrato(cid);};

  var tit = document.getElementById('co-proj-titulo');
  if(tit) tit.textContent = 'Projetos — ' + (contratos.find(function(c){return c.id===cid;})||{nome:''}).nome;

  // Todos contratos de obras usam sot_projetos
  var lista = isSot ? sot_projetos : projetos;
  var rows = lista.filter(function(p){
    if(p.contrato_id !== cid) return false;
    if(stFil && p.status !== stFil) return false;
    if(busca && p.nome.toLowerCase().indexOf(busca)<0 &&
       (p.codigo||p.codigo_cliente||'').toLowerCase().indexOf(busca)<0) return false;
    return true;
  });

  // Métricas
  if(metr){
    var total = rows.length;
    var emExec = rows.filter(function(p){return p.status==='Em execução'||p.status==='Executado';}).length;
    var concl  = rows.filter(function(p){return p.status==='Concluído'||p.status==='Faturado'||p.status==='Medido';}).length;
    var valPrev= rows.reduce(function(s,p){return s+(p.valor_previsto||0);},0);
    metr.innerHTML = [
      {l:'Total',v:total,c:'#555'},
      {l:'Em execução',v:emExec,c:'#3B6D11'},
      {l:'Concluídos',v:concl,c:'#085041'},
      {l:'Valor previsto',v:'R$\u00a0'+fmtMoeda(valPrev),c:'#185FA5'},
    ].map(function(m){
      return '<div style="background:#f9f9f7;border-radius:8px;padding:.6rem;text-align:center">'
        +'<div style="font-size:10px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:20px;font-weight:700;color:'+m.c+'">'+m.v+'</div>'
        +'</div>';
    }).join('');
  }

  if(!rows.length){
    wrap.innerHTML = '<div style="padding:3rem;text-align:center;color:#aaa">Nenhum projeto neste contrato.<br><br>'
      +'<button class="btn btn-pri" id="co-proj-novo2">+ Criar primeiro projeto</button></div>';
    setTimeout(function(){
      var b=document.getElementById('co-proj-novo2');
      if(b)b.onclick=isSot?sotAbrirNovoProjeto:function(){openNovoProjetoContrato(cid);};
    },50);
    return;
  }

  if(isSot){
    // Usar o render do SOT
    var oldSotWrap = document.getElementById('sot-lista-projetos');
    if(oldSotWrap) oldSotWrap = wrap;
    wrap.innerHTML = '<div style="display:flex;flex-direction:column;gap:.75rem">'
      + rows.map(sotRenderCardProjeto).join('') + '</div>';
    rows.forEach(function(p){
      var el=document.getElementById('sot-card-'+p.id);
      if(el)el.onclick=function(e){if(e.target.tagName==='BUTTON')return;sotAbrirProjeto(p.id);};
      var btnSt=document.getElementById('sot-btn-status-'+p.id);
      if(btnSt)btnSt.onclick=function(e){e.stopPropagation();sotAlterarStatus(p.id);};
    });
  } else {
    // Render tabela padrão
    wrap.innerHTML = '<div style="overflow-x:auto"><table class="tbl tbl-responsive">'
      +'<thead><tr><th>Código</th><th>Nome</th><th>Cliente</th><th>Início</th><th>Prazo</th><th>Status</th><th></th></tr></thead>'
      +'<tbody>'
      +rows.map(function(p){
        var stCor={Planejado:'#185FA5','Em execução':'#3B6D11',Concluído:'#085041',
          Suspenso:'#854F0B',Cancelado:'#A32D2D'}[p.status]||'#555';
        var hoje=dataHoje();
        var atrasado=p.data_fim&&p.data_fim<hoje&&p.status!=='Concluído'&&p.status!=='Cancelado';
        return '<tr>'
          +'<td style="font-family:monospace;font-size:12px">'+(p.codigo||'—')+'</td>'
          +'<td style="font-weight:500">'+p.nome+'</td>'
          +'<td style="font-size:12px;color:#888">'+(p.cliente||'—')+'</td>'
          +'<td style="font-size:12px">'+(p.data_inicio?fmtD(p.data_inicio):'—')+'</td>'
          +'<td style="font-size:12px;color:'+(atrasado?'#A32D2D':'inherit')+'">'
            +(p.data_fim?fmtD(p.data_fim):'—')+(atrasado?' ⚠':'')+'</td>'
          +'<td><span style="background:'+stCor+'22;color:'+stCor+';border-radius:4px;padding:1px 6px;font-size:11px;font-weight:600">'+(p.status||'—')+'</span></td>'
          +'<td><button class="btn btn-sm" data-pid="'+p.id+'">Ver</button></td>'
          +'</tr>';
      }).join('')
      +'</tbody></table></div>';
    setTimeout(function(){
      rows.forEach(function(p){
        wrap.querySelectorAll('[data-pid="'+p.id+'"]').forEach(function(b){
          b.onclick=function(){abrirDetalhesProjeto(p.id);};
        });
      });
    },50);
  }
}

// ── Equipe ───────────────────────────────────────────────────
function coRenderEquipe(){
  var cid = _coContratoAtual;
  var tbody = document.getElementById('co-eq-tbody');
  var resumo = document.getElementById('co-eq-resumo');
  if(!tbody) return;

  var busca = ((document.getElementById('co-eq-busca')||{}).value||'').toLowerCase();
  var cargo = (document.getElementById('co-eq-cargo')||{}).value||'';

  var rows = colaboradores.filter(function(c){
    if(c.contrato_id !== cid) return false;
    if(c.ativo===false||c.dispensado) return false;
    if(busca && c.nome.toLowerCase().indexOf(busca)<0) return false;
    if(cargo && c.cargo !== cargo) return false;
    return true;
  });

  // Popular select de cargos
  var cargoSel = document.getElementById('co-eq-cargo');
  if(cargoSel && cargoSel.options.length <= 1){
    var cargos = [...new Set(colaboradores.filter(function(c){return c.contrato_id===cid;})
      .map(function(c){return c.cargo;}).filter(Boolean))].sort();
    cargos.forEach(function(c){
      var o=document.createElement('option');o.value=c;o.textContent=c;cargoSel.appendChild(o);
    });
  }

  // Resumo
  if(resumo){
    var total = colaboradores.filter(function(c){return c.contrato_id===cid&&c.ativo!==false&&!c.dispensado;}).length;
    var motoristas = colaboradores.filter(function(c){return c.contrato_id===cid&&c.ativo!==false&&!c.dispensado&&(c.motorista||c.cnh_categoria);}).length;
    var equipes = equipes_disp.filter(function(e){return e.contrato_id===cid&&e.status==='Ativo';}).length;
    resumo.innerHTML = [
      {l:'Colaboradores ativos',v:total,c:'#3B6D11'},
      {l:'Com CNH',v:motoristas,c:'#185FA5'},
      {l:'Equipes',v:equipes,c:'#534AB7'},
      {l:'Disponíveis hoje',v:total,c:'#085041'},
    ].map(function(m){
      return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:.75rem;text-align:center">'
        +'<div style="font-size:11px;color:#888;margin-bottom:2px">'+m.l+'</div>'
        +'<div style="font-size:22px;font-weight:700;color:'+m.c+'">'+m.v+'</div>'
        +'</div>';
    }).join('');
  }

  if(!rows.length){
    tbody.innerHTML='<tr><td colspan="7" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum colaborador neste contrato.</td></tr>';
    return;
  }

  tbody.innerHTML = rows.map(function(c){
    var eq = equipes_disp.find(function(e){return e.id===c.equipe_id;})||{};
    var btnAv=(typeof avColModuloPermitido==='function'&&avColModuloPermitido())
      ?'<button class="btn btn-sm" onclick="avColAbrirDeCadastro(\''+c.id+'\')" style="color:#185FA5;border-color:#185FA5;margin-right:4px" title="Avaliação IEC">📊</button>':'';
    return '<tr>'
      +'<td style="font-size:12px;color:#888">'+(c.re||'—')+'</td>'
      +'<td style="font-weight:500">'+c.nome+'</td>'
      +'<td style="font-size:12px">'+(c.cargo||'—')+'</td>'
      +'<td style="font-size:12px">'+(eq.codigo?'<span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:11px">'+eq.codigo+'</span>':'—')+'</td>'
      +'<td style="font-size:12px">'+(c.cnh_categoria?'Cat.'+c.cnh_categoria:'—')+'</td>'
      +'<td><span class="bdg ok">Ativo</span></td>'
      +'<td style="white-space:nowrap">'+btnAv+'<button class="btn btn-sm" onclick="openEditarColaborador(\''+c.id+'\')">Editar</button></td>'
      +'</tr>';
  }).join('');
}

function openNovoColaboradorContrato(){
  openNovoColaboradorRapido();
}

// ── Programação ──────────────────────────────────────────────
function coRenderProgramacao(){
  var cid = _coContratoAtual;
  var wrap = document.getElementById('co-prog-quadro');
  if(!wrap) return;

  // Setar data padrão
  var dataEl = document.getElementById('co-prog-data');
  var data = dataEl ? dataEl.value : dataHojeLocal();
  if(dataEl && !dataEl.value) dataEl.value = data;

  // Usar progRenderQuadro mas com filtro de contrato
  window._filtroContrato = cid;
  var selCont = document.getElementById('prog-av-cont');
  if(selCont) selCont.value = cid;
  var selData = document.getElementById('prog-av-data');
  if(selData) selData.value = data;

  // Redirecionar para a aba de programação com contrato pré-selecionado
  wrap.innerHTML = '<div style="padding:1rem;text-align:center">'
    +'<div style="font-size:13px;color:#888;margin-bottom:1rem">A programação de equipes está disponível na aba Operacional.</div>'
    +'<button class="btn btn-pri" onclick="coAbrirProgramacaoCompleta()">Abrir Programação de Equipes</button>'
    +'</div>';

  // Mostrar resumo de equipes do contrato
  var eqs = equipes_disp.filter(function(e){return e.contrato_id===cid&&e.status==='Ativo';});
  var comps = composicao_dia.filter(function(c){
    return c.data===data && eqs.some(function(e){return e.id===c.equipe_id;});
  });

  var totalEqs = eqs.length;
  var programadas = comps.length;
  var STATUS_BLOQ = BLOQ_STATUS;

  wrap.innerHTML = '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:.75rem;margin-bottom:1rem">'
    +[
      {l:'Total equipes',v:totalEqs,c:'#555'},
      {l:'Programadas hoje',v:programadas,c:'#3B6D11'},
      {l:'Sem programação',v:totalEqs-programadas,c:'#A32D2D'},
    ].map(function(m){
      return '<div style="background:#f9f9f7;border-radius:8px;padding:.75rem;text-align:center">'
        +'<div style="font-size:11px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:22px;font-weight:700;color:'+m.c+'">'+m.v+'</div>'
        +'</div>';
    }).join('')
    +'</div>'
    +'<div style="text-align:center;padding:1rem">'
    +'<button class="btn btn-pri" onclick="coAbrirProgramacaoCompleta()" style="padding:12px 24px;font-size:14px">📅 Abrir quadro completo de programação</button>'
    +'</div>';
}

function coAbrirProgramacaoCompleta(){
  // Ir para programação com contrato pré-setado
  window._filtroContrato = _coContratoAtual;
  showMain('operacional');
  setTimeout(function(){showSub('programacao-equipes');},200);
}

