// ── Adicionar aba de contrato dinamicamente ──────────────────
function projAdicionarAbaContrato(cid, nomeAba){
  // Verificar se já existe
  var k = nomeAba.toLowerCase()
    .replace(/[^a-z0-9]/g, '_')
    .replace(/_+/g, '_');

  if(PROJ_TABS_CONTRATOS[k]) return; // já existe

  // Adicionar ao mapa
  PROJ_TABS_CONTRATOS[k] = cid;
  PROJ_TABS_ALL.push(k);

  // Adicionar botão na barra
  var bar = document.querySelector('#pg-obras-projetos > div:first-child');
  if(bar){
    var btn = document.createElement('button');
    btn.id = 'proj-tab-'+k;
    btn.style.cssText = 'padding:.5rem .85rem;border:none;border-bottom:2px solid transparent;color:#888;font-weight:600;background:none;cursor:pointer;font-size:11px;white-space:nowrap';
    btn.textContent = nomeAba;
    btn.onclick = function(){ projMostrarTab(k); };
    bar.appendChild(btn);
  }

  // Adicionar conteúdo
  var pg = document.getElementById('pg-obras-projetos');
  if(pg){
    var div = document.createElement('div');
    div.id = 'proj-tab-content-'+k;
    div.style.display = 'none';
    div.innerHTML = '<div class="card" style="margin-bottom:1rem">'
      +'<div class="ch"><span class="ct">📋 '+nomeAba+'</span>'
      +'<div style="display:flex;gap:6px">'
      +'<select class="inp" id="fil-proj-status-'+k+'" style="width:150px"><option value="">Todos os status</option></select>'
      +'<button class="btn btn-pri" id="proj-novo-'+k+'">+ Novo</button>'
      +'</div></div></div>'
      +'<div id="proj-lista-'+k+'"><div style="padding:2rem;text-align:center;color:#aaa">Clique para carregar</div></div>';
    pg.appendChild(div);
    // Vincular eventos
    var stSel = document.getElementById('fil-proj-status-'+k);
    if(stSel) stSel.onchange = (function(kk,cc){return function(){renderProjetosPorContrato(kk,cc);};})(k,cid);
    var btnN = document.getElementById('proj-novo-'+k);
    if(btnN) btnN.onclick = (function(cc){return function(){openNovoProjetoContrato(cc);};})(cid);
  }
  if(cid) verificarContratoObras(cid);
}

// Verificar contratos novos após carregarDados
function projVerificarContratosNovos(){
  contratos.forEach(function(c){
    if(!c.id || !c.nome) return;
    // Se é contrato de obras e não tem aba ainda, criar dinamicamente
    if(CONTRATOS_OBRAS_IDS.indexOf(c.id)>=0){
      var jaExiste = Object.values(PROJ_TABS_CONTRATOS).indexOf(c.id) >= 0;
      if(!jaExiste){
        projAdicionarAbaContrato(c.id, c.nome);
      }
    }
  });
}


function projMostrarTab(tab){
  var allKeys = ['tma','rdse','rdsc','out_fit','bt0','plpt','automacao','etd','rdse_novo','rdsc_novo','sot_obras','comgas','cteep_rocada','obras_particulares'];
  allKeys.forEach(function(t){
    var btn = document.getElementById('proj-tab-'+t);
    var el  = document.getElementById('proj-tab-content-'+t);
    if(btn){
      btn.style.borderBottomColor = t===tab ? '#1a1a18' : 'transparent';
      btn.style.color = t===tab ? '#1a1a18' : '#888';
      btn.style.fontWeight = t===tab ? '700' : '600';
    }
    if(el) el.style.display = t===tab ? '' : 'none';
  });

  var tabMap = {
  'tma': '04277076-baa5-4ea4-85dc-bddf55541e68',
  'rdse': '3925df4e-7e39-498d-8c96-891a7f4d415c',
  'rdsc': 'b9f2e0ca-ac8a-4123-b2bd-8f12ab943a17',
  'out_fit': '0b74fbb3-38fb-4d03-8c44-154479dde66d',
  'bt0': '65b27c8f-28a5-4137-9231-d3989791b536',
  'plpt': '430df4d5-6d0a-459f-ae82-92546ff9e57f',
  'automacao': 'db22cb0e-3472-448e-8b0e-2c1036d55549',
  'etd': 'c11f930f-01b8-4187-bd73-f754470c943a',
  'rdse_novo': 'c403dac6-753f-4f35-8113-21a12ccfeb27',
  'rdsc_novo': 'dd6633d5-b71d-48c0-b04d-7bcfdd9e6055',
  'sot_obras': 'fa896e2c-7c2c-47f4-a696-e86d62102db7',
  'comgas': '6eae5ac3-698b-433d-8ca9-6bf35d621946',
  'cteep_rocada': '60b1bdaf-afe1-4dae-8e03-f069052e4ce1',
  'obras_particulares': 'b3215a5a-e6e6-42bc-bf27-995dbff99af5'
  };
  var cid = tabMap[tab] || '';

  if(tab==='sot_obras'){
    verificarContratoObras('fa896e2c-7c2c-47f4-a696-e86d62102db7');
    window._filtroContrato = 'fa896e2c-7c2c-47f4-a696-e86d62102db7';
    sotInit();
  } else if(cid){
    coAbrirContrato(cid);
  }
}


function renderProjetosPorContrato(tab, contrato_id){
  var wrap = document.getElementById('proj-lista-'+tab);
  if(!wrap) return;

  var stSel = document.getElementById('fil-proj-status-'+tab);
  if(stSel && stSel.options.length <= 1){
    ['Planejado','Em execução','Concluído','Suspenso','Cancelado'].forEach(function(s){
      var o=document.createElement('option');o.value=s;o.textContent=s;stSel.appendChild(o);
    });
  }

  if(!contrato_id){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Contrato não localizado no banco.</div>';
    return;
  }

  var stFil  = stSel ? stSel.value : '';
  var buscaEl = document.getElementById('fil-proj-busca-'+tab);
  var busca   = buscaEl ? (buscaEl.value||'').toLowerCase() : '';

  var isSot = isContratoObras(contrato_id);
  var fonte  = isSot ? sot_projetos : projetos;

  var rows = fonte.filter(function(p){
    if(p.contrato_id !== contrato_id) return false;
    if(stFil && p.status !== stFil) return false;
    if(busca && (p.nome||'').toLowerCase().indexOf(busca)<0 &&
       (p.codigo||p.codigo_cliente||'').toLowerCase().indexOf(busca)<0) return false;
    return true;
  });

  // Métricas
  var total  = rows.length;
  var emExec = rows.filter(function(p){return p.status==='Em execução'||p.status==='Executado';}).length;
  var concl  = rows.filter(function(p){return p.status==='Concluído'||p.status==='Faturado';}).length;
  var valPrev= rows.reduce(function(s,p){return s+(p.valor_previsto||0);},0);

  var metrHtml = '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:.75rem">'
    +[{l:'Total',v:total,c:'#555'},{l:'Em execução',v:emExec,c:'#3B6D11'},
      {l:'Concluídos',v:concl,c:'#085041'},{l:'Valor previsto',v:'R$\u00a0'+fmtMoeda(valPrev),c:'#185FA5'}]
    .map(function(m){
      return '<div style="background:#f9f9f7;border-radius:8px;padding:.6rem;text-align:center">'
        +'<div style="font-size:10px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:18px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('')+'</div>';

  if(!rows.length){
    wrap.innerHTML = metrHtml
      +'<div style="padding:3rem;text-align:center;color:#aaa">Nenhum projeto encontrado.<br><br>'
      +'<button class="btn btn-pri" id="proj-novo-btn-'+tab+'">+ Criar primeiro projeto</button></div>';
    var nb=document.getElementById('proj-novo-btn-'+tab);
    if(nb)nb.onclick=function(){openNovoProjetoContrato(contrato_id);};
    return;
  }

  // Cards ricos para contratos SOT / Obras
  if(isSot){
    wrap.innerHTML = metrHtml
      +'<div style="display:flex;flex-direction:column;gap:.75rem">'
      +rows.map(sotRenderCardProjeto).join('')+'</div>';
    rows.forEach(function(p){
      var el=document.getElementById('sot-card-'+p.id);
      if(el)el.onclick=function(e){if(e.target.tagName==='BUTTON')return;sotAbrirProjeto(p.id);};
      var btnSt=document.getElementById('sot-btn-status-'+p.id);
      if(btnSt)btnSt.onclick=function(e){e.stopPropagation();sotAlterarStatus(p.id);};
    });
  } else {
    // Tabela para contratos não SOT
    var hoje=dataHoje();
    wrap.innerHTML = metrHtml
      +'<div style="overflow-x:auto"><table class="tbl tbl-responsive">'
      +'<thead><tr><th>Código</th><th>Nome</th><th>Cliente</th><th>Início</th><th>Prazo</th><th>Status</th><th></th></tr></thead>'
      +'<tbody>'
      +rows.map(function(p){
        var stCor={Planejado:'#185FA5','Em execução':'#3B6D11',Concluído:'#085041',
          Suspenso:'#854F0B',Cancelado:'#A32D2D'}[p.status]||'#555';
        var atrasado=p.data_fim&&p.data_fim<hoje&&p.status!=='Concluído'&&p.status!=='Cancelado';
        return '<tr>'
          +'<td style="font-family:monospace;font-size:12px">'+(p.codigo||'—')+'</td>'
          +'<td style="font-weight:500">'+p.nome+'</td>'
          +'<td style="font-size:12px;color:#888">'+(p.cliente||'—')+'</td>'
          +'<td style="font-size:12px">'+(p.data_inicio?fmtD(p.data_inicio):'—')+'</td>'
          +'<td style="font-size:12px;color:'+(atrasado?'#A32D2D':'inherit')+'">'
            +(p.data_fim?fmtD(p.data_fim):'—')+(atrasado?' ⚠':'')+'</td>'
          +'<td><span style="background:'+stCor+'22;color:'+stCor+';border-radius:4px;padding:1px 6px;font-size:11px;font-weight:600">'+(p.status||'—')+'</span></td>'
          +'<td><button class="btn btn-sm" data-pid="'+p.id+'">Ver</button></td>'
          +'</tr>';
      }).join('')
      +'</tbody></table></div>';
    setTimeout(function(){
      rows.forEach(function(p){
        var btns=wrap.querySelectorAll('[data-pid="'+p.id+'"]');
        btns.forEach(function(b){b.onclick=function(){abrirDetalhesProjeto(p.id);};});
      });
    },50);
  }
}

function openNovoProjetoContrato(contrato_id){
  if(isContratoObras(contrato_id)){
    _coContratoAtual = contrato_id;
    window._filtroContrato = contrato_id;
    _sotProjetoAtual = null;
    if(!contratos.length && !DEMO){
      sbFetch('contratos',{filters:['status=eq.Ativo'],order:'codigo'}).then(function(res){
        if(res&&res.length) contratos=res;
        sotModalProjeto(null);
      }).catch(function(){ sotModalProjeto(null); });
    } else {
      sotModalProjeto(null);
    }
  } else {
    openNovoProjeto();
    setTimeout(function(){
      var sel=document.getElementById('np-cont');
      if(sel && contrato_id) sel.value = contrato_id;
    }, 100);
  }
}

function sotCarregarProjetos(){
  if(DEMO){ sot_projetos=[]; return Promise.resolve(); }
  var cid = (window._filtroContrato)||(_coContratoAtual||'');
  var filters = cid ? ['contrato_id=eq.'+cid] : [];
  return sbFetchPaged('sot_projetos',{filters:filters,order:'criado_em.desc'})
    .then(function(rows){
      if(rows&&rows.length) sot_projetos=rows;
      else sot_projetos=[];
    }).catch(function(){ sot_projetos=[]; });
}

// ── Métricas ──────────────────────────────────────────────────
function sotRenderMetricas(){
  var el=document.getElementById('sot-metricas');if(!el)return;
  var total=sot_projetos.length;
  var emExec=sot_projetos.filter(function(p){return p.status==='Em execução';}).length;
  var executados=sot_projetos.filter(function(p){return p.status==='Executado'||p.status==='Em medição'||p.status==='Medido';}).length;
  var faturados=sot_projetos.filter(function(p){return p.status==='Faturado';}).length;
  var valPrev=sot_projetos.reduce(function(s,p){return s+(p.valor_previsto||0);},0);

  el.innerHTML=[
    {l:'Total',v:total,c:'#555'},
    {l:'Em execução',v:emExec,c:'#185FA5'},
    {l:'Executados/Medição',v:executados,c:'#3B6D11'},
    {l:'Valor previsto',v:'R$\u00a0'+fmtMoeda(valPrev),c:'#085041'},
  ].map(function(m){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.75rem;text-align:center">'
      +'<div style="font-size:11px;color:#888;margin-bottom:4px">'+m.l+'</div>'
      +'<div style="font-size:22px;font-weight:700;color:'+m.c+'">'+m.v+'</div>'
      +'</div>';
  }).join('');
}

