var _ativRapidas = []; // cached from DB

var ATIV_RAPIDA_CFG = {
  emergencia:  { label:'🚨 Emergência',    cor:'#A32D2D', bg:'#FCEBEB', icon:'🚨', temEnderecos:false },
  coleta_oleo: { label:'🛢 Coleta de Óleo', cor:'#854F0B', bg:'#FEF3E2', icon:'🛢', temEnderecos:true  },
  termografia: { label:'🌡 Termografia',   cor:'#185FA5', bg:'#EBF4FD', icon:'🌡', temEnderecos:true  },
};

// ── Abrir modal de nova atividade rápida ─────────────────────────────
function sotAbrirAtivRapida(tipo){
  var cfg = ATIV_RAPIDA_CFG[tipo];
  if(!cfg) return;

  var cid = (document.getElementById('sot-fil-cont')||{}).value||'';
  var contrOpts = (contratos||[]).filter(function(c){return c.status==='Ativo'||!c.status;})
    .map(function(c){ return '<option value="'+c.id+'"'+(c.id===cid?' selected':'')+'>'+escHtml(c.nome||c.numero||c.id)+'</option>'; }).join('');

  var equipeOpts = (equipes_disp||[]).map(function(e){
    return '<option value="'+e.id+'">'+escHtml(e.codigo+' — '+(e.nome_equipe||e.nome||''))+'</option>';
  }).join('');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:500px">'
    +'<h3 style="margin-bottom:.75rem">'+cfg.icon+' Nova '+cfg.label+'</h3>'
    +'<div style="display:grid;gap:.6rem">'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Contrato</label>'
    +'<select class="inp" id="ar-cont" style="width:100%"><option value="">Selecione...</option>'+contrOpts+'</select></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Data</label>'
    +'<input class="inp" id="ar-data" type="date" value="'+dataHojeLocal()+'" style="width:100%"/></div>'
    +'</div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Equipe</label>'
    +'<select class="inp" id="ar-equipe" style="width:100%"><option value="">Selecione...</option>'+equipeOpts+'</select></div>'
    +(cfg.temEnderecos
      ? '<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Endereços *</label>'
        +'<div id="ar-enderecos-wrap">'
        +'<div class="ar-end-row" style="display:flex;gap:4px;margin-bottom:4px">'
        +'<input class="inp ar-end-input" placeholder="Endereço 1" style="flex:1;font-size:12px"/>'
        +'<button onclick="sotAddEnderecoRapida()" style="background:none;border:.5px solid #185FA5;border-radius:6px;color:#185FA5;cursor:pointer;padding:2px 8px;font-size:18px" title="Adicionar">+</button>'
        +'</div></div></div>'
      : '')
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Observação</label>'
    +'<textarea class="inp" id="ar-obs" rows="2" style="width:100%;resize:none" placeholder="Opcional..."></textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="ar-salvar" style="flex:2">✅ Criar</button>'
    +'</div></div></div>');

  setTimeout(function(){
    var btn = document.getElementById('ar-salvar');
    if(!btn) return;
    btn.onclick = function(){ sotSalvarAtivRapida(tipo, cfg); };
  }, 50);
}

function sotAddEnderecoRapida(){
  var wrap = document.getElementById('ar-enderecos-wrap');
  if(!wrap) return;
  var count = wrap.querySelectorAll('.ar-end-input').length + 1;
  var row = document.createElement('div');
  row.className = 'ar-end-row';
  row.style.cssText = 'display:flex;gap:4px;margin-bottom:4px';
  row.innerHTML = '<input class="inp ar-end-input" placeholder="Endereço '+count+'" style="flex:1;font-size:12px"/>'
    +'<button onclick="this.parentElement.remove()" style="background:none;border:.5px solid #A32D2D;border-radius:6px;color:#A32D2D;cursor:pointer;padding:2px 8px;font-size:14px" title="Remover">✕</button>';
  wrap.appendChild(row);
}

function sotSalvarAtivRapida(tipo, cfg){
  var cid    = (document.getElementById('ar-cont')||{}).value||'';
  var data   = (document.getElementById('ar-data')||{}).value||dataHojeLocal();
  var eqId   = (document.getElementById('ar-equipe')||{}).value||'';
  var obs    = ((document.getElementById('ar-obs')||{}).value||'').trim();

  // Collect enderecos
  var enderecos = [];
  if(cfg.temEnderecos){
    document.querySelectorAll('.ar-end-input').forEach(function(inp){
      var v = (inp.value||'').trim();
      if(v) enderecos.push({endereco:v, obs:'', foto:null, status:'pendente'});
    });
    if(!enderecos.length){
      progShowToast('⚠ Informe pelo menos um endereço.','erro'); return;
    }
  }

  var nova = {
    id:          'ar'+Date.now(),
    tipo:        tipo,
    label:       cfg.label,
    contrato_id: cid,
    equipe_id:   eqId,
    data:        data,
    obs:         obs,
    enderecos:   enderecos,
    status:      'pendente',
    criado_em:   new Date().toISOString(),
    criado_por:  usuarioLogado ? usuarioLogado.nome : ''
  };

  _ativRapidas.push(nova);

  if(!DEMO){
    var payload = Object.assign({}, nova, {
      enderecos: JSON.stringify(enderecos),
      id: undefined
    });
    sbInsert('sot_ativ_rapidas', payload).then(function(r){
      if(r&&r[0]) nova.id = r[0].id;
    });
  }

  closeModal();
  progShowToast('✅ '+cfg.label+' criada!');
  sotRenderAtivRapidasLista();
}

// ── Renderizar lista de atividades rápidas ──────────────────────────
function sotRenderAtivRapidasLista(){
  var wrap = document.getElementById('sot-ativ-rapidas-lista');
  if(!wrap) return;

  var cid   = (document.getElementById('sot-fil-cont')||{}).value||'';
  var lista = _ativRapidas.filter(function(a){
    if(a.status==='concluido') return false;
    if(cid && a.contrato_id && a.contrato_id!==cid) return false;
    return true;
  });

  if(!lista.length){ wrap.innerHTML=''; return; }

  wrap.innerHTML = lista.map(function(ar){
    var cfg = ATIV_RAPIDA_CFG[ar.tipo]||{cor:'#555',bg:'#f5f5f3',icon:'📋',label:ar.tipo};
    var enderecos = [];
    try{ enderecos = typeof ar.enderecos==='string' ? JSON.parse(ar.enderecos) : (ar.enderecos||[]); }catch(e){}

    var endHtml = enderecos.length
      ? '<div style="margin-top:.5rem">'
        +enderecos.map(function(e,i){
          var stCor = e.status==='concluido' ? '#3B6D11' : e.status==='em_execucao' ? '#185FA5' : '#854F0B';
          return '<div style="display:flex;align-items:center;gap:6px;padding:3px 0;border-bottom:.5px solid #f5f5f3;font-size:11px">'
            +'<span style="color:'+stCor+';font-size:10px">●</span>'
            +'<span style="flex:1">'+escHtml(e.endereco)+'</span>'
            +(e.obs?'<span style="color:#888;font-size:10px">'+escHtml(e.obs.slice(0,30))+'</span>':'')
            +'<button onclick="sotEditarEnderecoRapida(\''+ar.id+'\','+i+')" style="background:none;border:none;cursor:pointer;font-size:11px;color:#185FA5">✎</button>'
            +'</div>';
        }).join('')
        +'</div>'
      : '';

    var eq = equipes_disp ? equipes_disp.find(function(e){return e.id===ar.equipe_id;}) : null;

    return '<div style="border-left:3px solid '+cfg.cor+';background:'+cfg.bg+';margin:.25rem .75rem;border-radius:0 8px 8px 0;padding:.6rem .75rem">'
      +'<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.4rem">'
      +'<div style="display:flex;align-items:center;gap:.5rem">'
      +'<span style="font-size:13px">'+cfg.icon+'</span>'
      +'<span style="font-weight:700;font-size:12px;color:'+cfg.cor+'">'+cfg.label+'</span>'
      +'<span style="font-size:10px;color:#888">'+fmtD(ar.data)+(eq?' · '+escHtml(eq.codigo):'')+'</span>'
      +'</div>'
      +'<div style="display:flex;gap:.3rem">'
      +'<button class="btn btn-sm" onclick="sotConcluirAtivRapida(\''+ar.id+'\')" style="font-size:10px;color:#3B6D11;border-color:#3B6D11">✅ Concluir</button>'
      +'<button class="btn btn-sm" onclick="sotExcluirAtivRapida(\''+ar.id+'\')" style="font-size:10px;color:#A32D2D;border-color:#A32D2D">✕</button>'
      +'</div></div>'
      +endHtml
      +(ar.obs?'<div style="font-size:11px;color:#888;margin-top:4px">'+escHtml(ar.obs)+'</div>':'')
      +'</div>';
  }).join('');
}

function sotEditarEnderecoRapida(arId, idx){
  var ar = _ativRapidas.find(function(a){return a.id===arId;});
  if(!ar) return;
  var ends = [];
  try{ ends = typeof ar.enderecos==='string' ? JSON.parse(ar.enderecos) : (ar.enderecos||[]); }catch(e){}
  var e = ends[idx];
  if(!e) return;

  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.75rem">✎ Editar Endereço</h3>'
    +'<div style="display:grid;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Endereço</label>'
    +'<input class="inp" id="ee-end" value="'+escHtml(e.endereco||'')+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Status</label>'
    +'<select class="inp" id="ee-status" style="width:100%">'
    +'<option value="pendente"'+(e.status==='pendente'?' selected':'')+'>⏳ Pendente</option>'
    +'<option value="em_execucao"'+(e.status==='em_execucao'?' selected':'')+'>⚡ Em Execução</option>'
    +'<option value="concluido"'+(e.status==='concluido'?' selected':'')+'>✅ Concluído</option>'
    +'</select></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Observação</label>'
    +'<textarea class="inp" id="ee-obs" rows="2" style="width:100%;resize:none">'+escHtml(e.obs||'')+'</textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="ee-salvar" style="flex:2">💾 Salvar</button>'
    +'</div></div></div>');

  setTimeout(function(){
    var btn = document.getElementById('ee-salvar');
    if(!btn) return;
    btn.onclick = function(){
      e.endereco = ((document.getElementById('ee-end')||{}).value||'').trim();
      e.status   = (document.getElementById('ee-status')||{}).value||'pendente';
      e.obs      = ((document.getElementById('ee-obs')||{}).value||'').trim();
      ends[idx] = e;
      ar.enderecos = ends;
      if(!DEMO && isUUID(arId)){
        sbUpdate('sot_ativ_rapidas',{enderecos:JSON.stringify(ends)},'id=eq.'+arId);
      }
      closeModal();
      sotRenderAtivRapidasLista();
      progShowToast('✅ Endereço atualizado!');
    };
  }, 50);
}

function sotConcluirAtivRapida(id){
  var ar = _ativRapidas.find(function(a){return a.id===id;});
  if(!ar) return;
  if(!confirm('Concluir esta atividade?')) return;
  ar.status = 'concluido';
  if(!DEMO && isUUID(id)) sbUpdate('sot_ativ_rapidas',{status:'concluido'},'id=eq.'+id);
  sotRenderAtivRapidasLista();
  progShowToast('✅ Atividade concluída!');
}

function sotExcluirAtivRapida(id){
  if(!confirm('Excluir esta atividade?')) return;
  _ativRapidas = _ativRapidas.filter(function(a){return a.id!==id;});
  if(!DEMO && isUUID(id)) sbDelete('sot_ativ_rapidas','id=eq.'+id);
  sotRenderAtivRapidasLista();
}

// ── Carregar atividades rápidas ao abrir obras ──────────────────────
function sotCarregarAtivRapidas(cid){
  if(DEMO){ _ativRapidas=[]; sotRenderAtivRapidasLista(); return; }
  var filters = ['status=neq.concluido'];
  if(cid) filters.push('contrato_id=eq.'+cid);
  sbFetch('sot_ativ_rapidas',{filters:filters,order:'criado_em.desc',limit:100})
    .then(function(rows){
      _ativRapidas = rows||[];
      sotRenderAtivRapidasLista();
    }).catch(function(){
      _ativRapidas=[];
    });
}


function sotRenderProjetos(){
  var wrap=document.getElementById('sot-lista-projetos');if(!wrap)return;
  var stFil=(document.getElementById('sot-fil-status')||{}).value||'';
  var busca=((document.getElementById('sot-fil-busca')||{}).value||'').toLowerCase();
  // Also render independent activities
  sotRenderAtivRapidasLista();

  var rows=sot_projetos.filter(function(p){
    if(stFil&&p.status!==stFil)return false;
    if(busca&&p.nome.toLowerCase().indexOf(busca)<0&&
       (p.codigo_cliente||'').toLowerCase().indexOf(busca)<0&&
       (p.cliente||'').toLowerCase().indexOf(busca)<0)return false;
    return true;
  });

  if(!rows.length){
    wrap.innerHTML='<div style="padding:3rem;text-align:center;color:#aaa">'
      +'Nenhum projeto encontrado.<br><br>'
      +'<button class="btn btn-pri" onclick="sotAbrirNovoProjeto()">+ Criar primeiro projeto</button>'
      +'</div>';
    return;
  }

  // Agrupar por status
  var grupos={};
  SOT_STATUS_LIST.forEach(function(s){grupos[s]=[];});
  rows.forEach(function(p){
    if(grupos[p.status]) grupos[p.status].push(p);
    else grupos['Recebido'].push(p);
  });

  // Se filtro de status ativo, mostrar só lista simples
  if(stFil||busca){
    wrap.innerHTML='<div style="display:flex;flex-direction:column;gap:.75rem">'
      +rows.map(sotRenderCardProjeto).join('')+'</div>';
  } else {
    // Kanban por grupos não-vazios
    var html='';
    SOT_STATUS_LIST.forEach(function(s){
      if(!grupos[s].length)return;
      var sc=SOT_STATUS_COR[s]||{bg:'#f5f5f3',cor:'#555'};
      html+='<div style="margin-bottom:1.5rem">'
        +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem">'
        +'<span style="background:'+sc.bg+';color:'+sc.cor+';border-radius:6px;padding:3px 10px;font-size:12px;font-weight:600">'+s+'</span>'
        +'<span style="font-size:11px;color:#aaa">'+grupos[s].length+' projeto(s)</span>'
        +'</div>'
        +'<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:.75rem">'
        +grupos[s].map(sotRenderCardProjeto).join('')
        +'</div></div>';
    });
    wrap.innerHTML=html;
  }

  // Vincular cliques
  rows.forEach(function(p){
    var el=document.getElementById('sot-card-'+p.id);
    if(el)el.onclick=function(e){
      if(e.target.tagName==='BUTTON')return;
      sotAbrirProjeto(p.id);
    };
    var btnSt=document.getElementById('sot-btn-status-'+p.id);
    if(btnSt)btnSt.onclick=function(e){e.stopPropagation();sotAlterarStatus(p.id);};
  });
}

function sotRenderCardProjeto(p){
  var sc=SOT_STATUS_COR[p.status]||{bg:'#f5f5f3',cor:'#555'};
  var prazo=p.prazo_previsto?fmtD(p.prazo_previsto):'—';
  var hoje=dataHoje();
  var atrasado=p.prazo_previsto&&p.prazo_previsto<hoje&&p.status!=='Faturado'&&p.status!=='Cancelado';
  var pct=p.valor_previsto>0?Math.round((p.valor_executado||0)/p.valor_previsto*100):0;

  var vPrev = p.valor_previsto   || 0;
  var vViab = p.valor_viabilizado|| 0;
  var vExec = p.valor_executado  || 0;
  var vMed  = p.valor_medido     || 0;
  var vFat  = p.valor_faturado   || 0;

  function fv(v){ return 'R$\u00a0'+fmtMoeda(v); }

  var financeiro = '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-bottom:8px">'
    +[
      {l:'Previsto',  v:vPrev, c:'#185FA5'},
      {l:'Viabiliz.', v:vViab, c:'#854F0B'},
      {l:'Executado', v:vExec, c:'#3B6D11'},
      {l:'Medido',    v:vMed,  c:'#085041'},
      {l:'Faturado',  v:vFat,  c:'#1a1a18'},
    ].map(function(m){
      return '<div style="background:#f9f9f7;border-radius:6px;padding:4px 3px;text-align:center">'
        +'<div style="font-size:9px;color:#aaa;margin-bottom:1px">'+m.l+'</div>'
        +'<div style="font-size:12px;font-weight:700;color:'+m.c+'">'+fv(m.v)+'</div>'
        +'</div>';
    }).join('')
    +'</div>';

  return '<div id="sot-card-'+p.id+'" style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;'
    +'overflow:hidden;cursor:pointer;transition:box-shadow .15s" '
    +'onmouseover="this.style.boxShadow=\'0 2px 12px rgba(0,0,0,.1)\'" '
    +'onmouseout="this.style.boxShadow=\'\'">'
    +'<div style="background:'+sc.bg+';padding:.6rem .85rem;display:flex;justify-content:space-between;align-items:center">'
    +'<div>'
    +'<div style="font-size:11px;color:'+sc.cor+';font-weight:600">'+(p.codigo_cliente||'S/N')+'</div>'
    +'<div style="font-size:10px;color:#888">'+(p.tipo_servico||'')+'</div>'
    +'</div>'
    +'<button id="sot-btn-status-'+p.id+'" style="background:'+sc.bg+';color:'+sc.cor+';border:.5px solid '+sc.cor+'44;'
    +'border-radius:6px;padding:2px 8px;font-size:10px;font-weight:600;cursor:pointer">'+p.status+' ▾</button>'
    +'</div>'
    +'<div style="padding:.75rem .85rem">'
    +'<div style="font-weight:600;font-size:14px;margin-bottom:4px;color:#1a1a18">'+p.nome+'</div>'
    +'<div style="font-size:12px;color:#888;margin-bottom:8px">'+(p.cliente||'Cliente não informado')
    +(p.cidade?' · '+p.cidade:'')+'</div>'
    +'<div style="display:flex;gap:12px;font-size:11px;margin-bottom:8px">'
    +'<div><span style="color:#888">Prazo: </span><span style="color:'+(atrasado?'#A32D2D':'#555')+';font-weight:'+(atrasado?'600':'400')+'">'+prazo+(atrasado?' ⚠':'')+'</span></div>'
    +'<div><span style="color:#888">Resp: </span><span>'+(p.responsavel_interno||'—')+'</span></div>'
    +'</div>'
    + financeiro
    +(vPrev>0
      ?'<div style="background:#f0f0ee;border-radius:4px;height:4px;margin-bottom:4px">'
        +'<div style="background:'+sc.cor+';width:'+Math.min(100,pct)+'%;height:100%;border-radius:4px;transition:width .3s"></div>'
        +'</div>'
        +'<div style="font-size:10px;color:#888;text-align:right">Executado: '+pct+'%</div>'
      :'')
    +'</div>'
    +'<div style="padding:.5rem .85rem;border-top:.5px solid #f5f5f3;display:flex;gap:6px">'
    +'<button class="btn btn-sm" onclick="sotAbrirProjeto(\''+p.id+'\')" style="font-size:11px;flex:1">Ver detalhes</button>'
    +'<button class="btn btn-sm" onclick="sotAlterarStatus(\''+p.id+'\')" style="font-size:11px">↑ Status</button>'
    +'<button class="btn btn-sm" onclick="sotIniciarAnaliseWL(\''+p.id+'\')" style="font-size:11px;color:#185FA5;border-color:#185FA5">🔍 WLs</button>'
    +'</div>'
    +'</div>';
}

// ── Abrir projeto (tela de detalhe) ──────────────────────────
function sotAbrirProjeto(projetoId){
  _sotProjetoAtual=projetoId;
  var p=sot_projetos.find(function(x){return x.id===projetoId;});
  if(!p)return;
  var sc=SOT_STATUS_COR[p.status]||{bg:'#f5f5f3',cor:'#555'};

  // Carregar atividades e materiais do projeto
  Promise.all([
    DEMO?Promise.resolve([]):sbFetch('sot_atividades',{filters:['projeto_id=eq.'+projetoId],order:'ordem_exec'}),
    DEMO?Promise.resolve([]):sbFetch('sot_materiais',{filters:['projeto_id=eq.'+projetoId,'deleted_at=is.null']}),
    DEMO?Promise.resolve([]):sbFetch('sot_documentos',{filters:['projeto_id=eq.'+projetoId],order:'criado_em.desc'}),
    DEMO?Promise.resolve([]):sbFetch('sot_projetos_historico',{filters:['projeto_id=eq.'+projetoId],order:'criado_em.desc'}),
    DEMO?Promise.resolve([]):sbFetch('sot_medicoes',{filters:['projeto_id=eq.'+projetoId],order:'numero'}),
    DEMO?Promise.resolve([]):sbFetch('sot_med_itens',{filters:['projeto_id=eq.'+projetoId]}),
  ]).then(function(res){
    sot_atividades     = res[0]||[];
    sot_materiais_proj = res[1]||[];
    var docs           = res[2]||[];
    sot_historico      = res[3]||[];
    sot_medicoes       = (res[4]||[]).filter(function(m){return m.projeto_id===projetoId;});
    sot_med_itens      = (res[5]||[]).filter(function(i){return i.projeto_id===projetoId;});

    // Enriquecer sot_materiais_proj com breakdown completo de plpt_requisicoes
    if(!DEMO && sot_materiais_proj.length){
      var hoje = dataHojeLocal ? dataHojeLocal() : new Date().toISOString().slice(0,10);
      var activeStatus = ['Aguardando aprovação','Adicional pendente de aprovação','Aprovada','Separação','Aguardando confirmação almox','Em campo','Devolvida'];
      Promise.all([
        sbFetch('plpt_requisicoes_materiais',{filters:['projeto_id=eq.'+projetoId],order:'criado_em.asc',limit:500}),
        sbFetch('sot_adicionais',{filters:['projeto_id=eq.'+projetoId,'tipo=eq.material','status=eq.aprovado']})
      ]).then(function(results){
        var reqs  = results[0]||[];
        var adics = results[1]||[];
        // Reset all counters
        sot_materiais_proj.forEach(function(m){
          m._res_ant=0; m._res_atual=0; m._aplic_ant=0; m._aplic_atual=0; m._dev_hoje=0; m._adicionado=0;
        });
        // Adicionais aprovados
        adics.forEach(function(a){
          var mat = sot_materiais_proj.find(function(m){
            return (m.codigo_sap && a.codigo_sap && m.codigo_sap===a.codigo_sap)
                || (m.descricao && a.descricao && m.descricao.toLowerCase()===a.descricao.toLowerCase());
          });
          if(mat) mat._adicionado = (mat._adicionado||0) + (a.qtd_aprovada||a.qtd_solicitada||0);
        });
        // Requisições PLPT — breakdown por data
        reqs.forEach(function(r){
          if(r.deleted_at) return;
          // Try multiple date fields
          var reqData = '';
          if(r.data) reqData = r.data.slice(0,10);
          else if(r.criado_em) reqData = r.criado_em.slice(0,10);
          else if(r.created_at) reqData = r.created_at.slice(0,10);
          var isHoje  = reqData === hoje;
          var itens   = parseJsonField(r.itens,[]);
          itens.forEach(function(it){
            var mat = sot_materiais_proj.find(function(m){
              return (m.codigo_sap && it.codigo && m.codigo_sap===it.codigo)
                  || (m.descricao && it.nome && m.descricao.toLowerCase()===it.nome.toLowerCase());
            });
            if(!mat) return;
            var qtdReserva = (it.adicional_pendente && it.qtd_prevista!=null)
              ? (it.qtd_prevista||0)
              : (it.qtd_req||0);
            var qtdRet = it.qtd_ret||qtdReserva;
            // Reservado
            if(activeStatus.includes(r.status)){
              if(isHoje) mat._res_atual = (mat._res_atual||0) + qtdReserva;
              else       mat._res_ant   = (mat._res_ant||0)  + qtdReserva;
            }
            // Aplicado/entregue ao campo
            if(r.status==='Em campo'||r.status==='Devolvida'){
              if(isHoje) mat._aplic_atual = (mat._aplic_atual||0) + qtdRet;
              else       mat._aplic_ant   = (mat._aplic_ant||0)   + qtdRet;
            }
            // Devolvido hoje
            if(isHoje && r.status==='Devolvida'){
              mat._dev_hoje = (mat._dev_hoje||0) + (it.qtd_devolvida||0);
            }
          });
        });
        // Sync sumários para aba Materiais
        sot_materiais_proj.forEach(function(m){
          m.qtd_requisitada = (m._res_ant||0) + (m._res_atual||0);
          m.qtd_entregue    = (m._aplic_ant||0) + (m._aplic_atual||0);
        });
        // If panel already rendered, just update current tab; else do full render
        var _tabPane = document.getElementById('sot-tab-content');
        if(_tabPane) sotAtualizarAbaAtual(projetoId);
        else sotRenderDetalhe(p, docs);
      }).catch(function(){
        var _tp = document.getElementById('sot-tab-content');
        if(_tp) sotAtualizarAbaAtual(projetoId); else sotRenderDetalhe(p, docs);
      });
    } else {
      sotRenderDetalhe(p, docs);
    }
  });
}


// ── Analisador de Relatório de Campo com IA ─────────────────────────────────
function sotAnalisarRelatorio(projetoId){
  var proj = sot_projetos.find(function(x){ return x.id===projetoId; });
  if(!proj){ progShowToast('⚠ Projeto não encontrado.','erro'); return; }

  var contId   = proj.contrato_id||'';
  var contNome = (contratos.find(function(c){return c.id===contId;})||{}).nome||'';
  var isUPS    = (proj.modalidade||'').toUpperCase().indexOf('UPS')>=0;

  // Build context: services for this contract
  var svcList = servicos.filter(function(s){ return !contId||s.contrato_id===contId; });
  // Limit to 100 services max to avoid payload too large
  var svcCtx  = svcList.length
    ? svcList.slice(0,100).map(function(s){
        return s.codigo+'|'+s.descricao+'|'+(s.unidade||'UN')
          +(isUPS ? '|qtd_ups:'+s.qtd_ups+'|valor_ups:R$'+s.valor_ups : '|valor:R$'+(s.valor_unitario||0));
      }).join('\n')
      +(svcList.length>100 ? '\n...e mais '+(svcList.length-100)+' serviços (total: '+svcList.length+')' : '')
    : '(sem serviços cadastrados para este contrato — carregue a lista de serviços antes)';

  // Build context: materials catalog
  var matList = typeof catalogo_materiais!=='undefined' ? catalogo_materiais : [];
  var matContrato = matList.filter(function(m){
    var cids=[]; try{cids=JSON.parse(m.contratos_ids||'[]');}catch(e){}
    return cids.indexOf('todos')>=0 || cids.indexOf(contId)>=0 || cids.length===0;
  });
  var matCtx = matContrato.slice(0,80).map(function(m){
    return (m.codigo_sap||m.codigo||'')+'|'+(m.descricao||m.nome||'')+'|'+(m.unidade||'UN');
  }).join('\n') || '(sem materiais no catálogo)';

  // Build context: current stock
  var estoqueCtx = (alm_estoque||[]).filter(function(e){
    return !contId || e.contrato_id===contId || e.contrato_id==='geral';
  }).map(function(e){
    return e.codigo_sap+'|'+e.material_desc+'|saldo:'+e.saldo+' '+e.unidade;
  }).join('\n') || '(estoque não carregado)';

  var svcTrim = svcCtx.length > 2000 ? svcCtx.slice(0,2000)+'\n...' : svcCtx;
  var matTrim = matCtx.length > 1000 ? matCtx.slice(0,1000)+'\n...' : matCtx;
  var systemPrompt =
    'Especialista CENA ERP. Contrato: '+contNome+'. Projeto: '+proj.codigo+'. Modalidade: '+(proj.modalidade||'N/A')+'\n\n'
    +'SERVICOS:\n'+svcTrim+'\n\n'
    +'MATERIAIS:\n'+matTrim+'\n\n'
    +'Analise o relatorio de campo: liste servicos com codigo exato e quantidade. '
    +(isUPS ? 'Calcule total = Qtd x QtdUPS x ValorUPS. ' : '')
    +'Liste materiais aplicados. Use tabelas. Seja breve.';

  // Render modal
  setModal('<div class="modal-bg"><div class="modal" style="max-width:780px;height:88vh;display:flex;flex-direction:column;padding:0;overflow:hidden">'
    // Header
    +'<div style="background:linear-gradient(135deg,#533AB7,#185FA5);color:#fff;padding:1rem 1.25rem;display:flex;align-items:center;justify-content:space-between;flex-shrink:0">'
    +'<div>'
    +'<div style="font-size:16px;font-weight:700">🤖 Análise de Relatório com IA</div>'
    +'<div style="font-size:11px;opacity:.85">'+proj.codigo+' — '+proj.nome+' · '+contNome+'</div>'
    +'</div>'
    +'<button onclick="closeModal()" style="background:rgba(255,255,255,.2);border:none;color:#fff;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:13px">✕</button>'
    +'</div>'
    // Context info bar
    +'<div style="background:#F0EEFF;padding:.5rem 1rem;font-size:11px;color:#533AB7;flex-shrink:0;border-bottom:.5px solid #e0dfd8">'
    +'📚 Contexto carregado: <strong>'+svcList.length+' serviços</strong> · <strong>'+matContrato.length+' materiais</strong> · <strong>'+(alm_estoque||[]).length+' itens em estoque</strong>'
    +'</div>'
    // Chat messages
    +'<div id="sar-msgs" style="flex:1;overflow-y:auto;padding:1rem;display:flex;flex-direction:column;gap:.75rem">'
    +'<div style="background:#f9f9f7;border-radius:10px;padding:.75rem 1rem;font-size:12px;color:#555;border-left:3px solid #533AB7">'
    +'<strong>Como usar:</strong> Cole o texto do relatório de campo abaixo e clique em <strong>Analisar</strong>. '
    +'O assistente irá identificar os serviços executados e cruzar com os códigos do seu contrato, '
    +'calculando quantidades e valores prontos para lançar no projeto.'
    +'</div>'
    +'</div>'
    // Input area
    +'<div style="padding:.75rem 1rem;border-top:.5px solid #e0dfd8;flex-shrink:0;background:#fff">'
    +'<textarea id="sar-input" placeholder="Cole aqui o texto do relatório de campo..." '
    +'style="width:100%;height:110px;border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem;font-size:12px;resize:none;box-sizing:border-box;font-family:inherit"></textarea>'
    +'<div style="display:flex;gap:8px;margin-top:.5rem;align-items:center">'
    +'<button onclick="sarLimpar()" class="btn" style="font-size:12px">🗑 Limpar</button>'
    +'<button onclick="sarImportarAtividades(\''+projetoId+'\')" id="sar-importar" class="btn" style="font-size:12px;display:none;background:#3B6D11;color:#fff;border-color:#3B6D11">✅ Lançar no projeto</button>'
    +'<button onclick="sarEnviar(\''+projetoId+'\')" id="sar-enviar" class="btn btn-pri" '
    +'style="margin-left:auto;font-size:12px;background:linear-gradient(135deg,#533AB7,#185FA5);border:none;padding:.5rem 1.5rem;font-weight:600">🔍 Analisar</button>'
    +'</div></div>'
    +'</div></div>');

  // Store system prompt and history for this session
  window._sarSystemPrompt = systemPrompt;
  window._sarHistorico    = [];
  window._sarProjetoId    = projetoId;
  window._sarResultado    = null;

  setTimeout(function(){
    var ta = document.getElementById('sar-input');
    if(ta){
      if(proj.relatorio_obras) ta.value = proj.relatorio_obras;
      ta.focus();
    }
  }, 100);
}

function sarLimpar(){
  var ta = document.getElementById('sar-input');
  if(ta) ta.value = '';
  var msgs = document.getElementById('sar-msgs');
  if(msgs) msgs.innerHTML = '<div style="background:#f9f9f7;border-radius:10px;padding:.75rem 1rem;font-size:12px;color:#555;border-left:3px solid #533AB7">'
    +'Cole o texto do relatório de campo e clique em <strong>Analisar</strong>.</div>';
  var imp = document.getElementById('sar-importar');
  if(imp) imp.style.display='none';
  window._sarHistorico = [];
  window._sarResultado = null;
}

function sarAdicionarMsg(role, html, id){
  var msgs = document.getElementById('sar-msgs');
  if(!msgs) return;
  var div = document.createElement('div');
  if(id) div.id = id;
  var isUser = role==='user';
  div.style.cssText = 'padding:.75rem 1rem;border-radius:10px;font-size:12px;line-height:1.6;'
    +(isUser
      ? 'background:linear-gradient(135deg,#F0EEFF,#EBF4FD);border-left:3px solid #533AB7;'
      : 'background:#fff;border:.5px solid #e0dfd8;border-left:3px solid #3B6D11;');
  div.innerHTML = (isUser
    ? '<div style="font-size:10px;color:#533AB7;font-weight:700;margin-bottom:4px">📋 RELATÓRIO</div>'
    : '<div style="font-size:10px;color:#3B6D11;font-weight:700;margin-bottom:4px">🤖 ANÁLISE CENA IA</div>')
    + html;
  msgs.appendChild(div);
  msgs.scrollTop = msgs.scrollHeight;
}

function sarEnviar(projetoId){
  var input = document.getElementById('sar-input');
  if(!input) return;
  var texto = input.value.trim();
  if(!texto){ progShowToast('⚠ Cole o texto do relatório antes de analisar.','erro'); return; }

  var btn = document.getElementById('sar-enviar');
  if(btn){ btn.disabled=true; btn.textContent='⏳ Analisando...'; }

  // Show user message
  sarAdicionarMsg('user', '<div style="white-space:pre-wrap;max-height:200px;overflow-y:auto">'+escHtml(texto.slice(0,2000))+(texto.length>2000?'\n[...'+Math.round((texto.length-2000)/1000,1)+'k chars restantes]':'')+'</div>');

  // Build message with full report text
  window._sarHistorico.push({role:'user', content:
    'Analise o seguinte relatório de campo e forneça:\n'
    +'1. Uma tabela com os SERVIÇOS a cobrar (código exato, descrição, qtd, valor calculado)\n'
    +'2. Uma tabela com os MATERIAIS aplicados (código SAP, descrição, qtd, unidade)\n'
    +'3. Itens sem código correspondente no sistema (para ação manual)\n\n'
    +'RELATÓRIO:\n'+texto
  });

  // Add typing indicator
  var typingId = 'sar-typing-'+Date.now();
  sarAdicionarMsg('ai',
    '<div id="'+typingId+'" style="display:flex;gap:4px;align-items:center">'
    +'<span style="width:6px;height:6px;background:#533AB7;border-radius:50%;animation:pulse 1s infinite"></span>'
    +'<span style="width:6px;height:6px;background:#533AB7;border-radius:50%;animation:pulse 1s infinite .2s"></span>'
    +'<span style="width:6px;height:6px;background:#533AB7;border-radius:50%;animation:pulse 1s infinite .4s"></span>'
    +'<span style="font-size:11px;color:#888;margin-left:4px">Analisando relatório...</span>'
    +'</div>');

  fetch('https://cena-proxy.marcos-afe.workers.dev', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      model:      'claude-sonnet-4-5',
      max_tokens: 2000,
      system:     window._sarSystemPrompt,
      messages:   window._sarHistorico
    })
  })
  .then(function(r){
    if(!r.ok){
      return r.text().then(function(txt){
        throw new Error('HTTP '+r.status+': '+txt.slice(0,200));
      });
    }
    return r.json();
  })
  .then(function(data){
    var typing = document.getElementById(typingId);
    if(typing) typing.parentElement && typing.parentElement.remove
      ? typing.parentElement.remove()
      : typing.remove();

    var resposta = (data.content&&data.content[0]&&data.content[0].text)||'Sem resposta.';
    window._sarHistorico.push({role:'assistant', content:resposta});
    window._sarResultado = resposta;

    // Render markdown-like response
    var html = resposta
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
      .replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')
      .replace(/\|([^\n]+)\|/g, function(m){
        var cells = m.split('|').filter(function(x){return x.trim();});
        return '<tr>'+cells.map(function(x){
          return '<td style="padding:3px 8px;border:.5px solid #e0dfd8">'+x.trim()+'</td>';
        }).join('')+'</tr>';
      })
      .replace(/(<tr>.*<\/tr>\n?)+/g, function(m){
        return '<table style="border-collapse:collapse;width:100%;margin:.5rem 0;font-size:11px">'+m+'</table>';
      })
      .replace(/^#{1,3} (.+)$/gm,'<div style="font-weight:700;font-size:13px;color:#533AB7;margin:.5rem 0 .25rem">$1</div>')
      .replace(/\n/g,'<br>');

    sarAdicionarMsg('ai', html);

    // Show import button
    var imp = document.getElementById('sar-importar');
    if(imp) imp.style.display='';

    if(btn){ btn.disabled=false; btn.textContent='🔍 Analisar novamente'; }

    // Enable follow-up question
    var ta = document.getElementById('sar-input');
    if(ta){ ta.value=''; ta.placeholder='Faça uma pergunta de acompanhamento ou cole outro relatório...'; }
  })
  .catch(function(e){
    var typing = document.getElementById(typingId);
    if(typing && typing.parentElement) typing.parentElement.remove();
    console.error('[SAR] fetch error:', e);
    sarAdicionarMsg('ai','<span style="color:#A32D2D">⚠ Erro: '+(e&&e.message||String(e))+'<br><small>Verifique o console para detalhes.</small></span>');
    if(btn){ btn.disabled=false; btn.textContent='🔍 Analisar'; }
  });
}

function sarImportarAtividades(projetoId){
  if(!window._sarResultado){ progShowToast('⚠ Analise um relatório primeiro.','erro'); return; }
  progShowToast('💡 Use o resultado acima para lançar manualmente via "+ Atividade" ou "📥 Importar lista". Em breve: importação automática!');
}



// ══════════════════════════════════════════════════════════════════════
// MÓDULO MEDIÇÃO DE OBRAS
// Status: rascunho → em_aprovacao → aprovado → emissao_liberada → nf_emitida
// ══════════════════════════════════════════════════════════════════════

var sot_medicoes     = []; // medições do projeto atual
var sot_med_itens    = []; // itens de cada medição

var MED_STATUS = {
  rascunho:         { label:'Rascunho',          cor:'#555',    bg:'#f0efe8', ico:'✏️'  },
  em_aprovacao:     { label:'Em Aprovação',       cor:'#854F0B', bg:'#FEF3E2', ico:'📤' },
  aprovado:         { label:'Aprovado',           cor:'#185FA5', bg:'#EBF4FD', ico:'✅' },
  emissao_liberada: { label:'Emissão Liberada',   cor:'#3B6D11', bg:'#EAF3DE', ico:'🔓' },
  nf_emitida:       { label:'NF Emitida',         cor:'#085041', bg:'#E6F4F1', ico:'🧾' },
};

// ── Renderizar aba de medições ─────────────────────────────────────────
function sotRenderTabMedicao(projetoId, container){
  if(!container) container = document.getElementById('sot-tab-content');
  if(!container) return;

  var proj  = sot_projetos.find(function(x){ return x.id===projetoId; });
  var isUPS = proj && (proj.modalidade||'').toUpperCase().indexOf('UPS')>=0;

  var meds  = sot_medicoes.filter(function(m){ return m.projeto_id===projetoId; });

  var html = '<div style="padding:.5rem 0">'

  // Header
  + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
  + '<span style="font-size:13px;font-weight:700;color:#1a1a18">📐 Medições do Projeto</span>'
  + '<button class="btn btn-pri" onclick="sotNovaMedicao(\''+projetoId+'\')" style="font-size:11px">+ Nova Medição</button>'
  + '</div>';

  if(!meds.length){
    html += '<div style="text-align:center;padding:2rem;color:#aaa;font-size:13px">'
    + '📐 Nenhuma medição cadastrada ainda.<br><br>'
    + '<button class="btn btn-pri" onclick="sotNovaMedicao(\''+projetoId+'\')" style="font-size:12px">+ Criar Primeira Medição</button>'
    + '</div>';
  } else {
    html += meds.sort(function(a,b){ return (a.numero||0)-(b.numero||0); }).map(function(med){
      var st  = MED_STATUS[med.status] || MED_STATUS.rascunho;
      var tot = (med.valor_total||0);
      return '<div style="border:.5px solid #e0dfd8;border-radius:10px;margin-bottom:.75rem;overflow:hidden">'
        // Card header
        + '<div style="background:'+st.bg+';padding:.6rem 1rem;display:flex;align-items:center;justify-content:space-between;cursor:pointer" '
        + 'onclick="sotToggleMedicao(\''+med.id+'\')">'
        + '<div style="display:flex;align-items:center;gap:.5rem">'
        + '<span style="font-weight:700;color:'+st.cor+'">'+st.ico+' Parcial '+med.numero+'</span>'
        + '<span style="font-size:10px;background:'+st.bg+';color:'+st.cor+';border:.5px solid '+st.cor+';border-radius:4px;padding:2px 7px;font-weight:600">'+st.label+'</span>'
        + (med.data_corte ? '<span style="font-size:10px;color:#888">Data corte: <b>'+fmtD(med.data_corte)+'</b></span>' : '')
        + '</div>'
        + '<div style="display:flex;align-items:center;gap:.5rem">'
        + '<span style="font-size:13px;font-weight:700;color:#185FA5">R$ '+fmtMoeda(tot)+'</span>'
        + '<span style="color:#aaa;font-size:14px">▾</span>'
        + '</div>'
        + '</div>'
        // Timeline
        + '<div style="display:flex;gap:0;border-bottom:.5px solid #f0efe8;padding:.4rem 1rem;background:#fafaf8;font-size:10px;color:#888;flex-wrap:wrap;gap:1rem">'
        + (med.data_envio     ? '<span>📤 Enviado: <b>'+fmtD(med.data_envio)+'</b></span>'     : '')
        + (med.data_aprovacao ? '<span>✅ Aprovado: <b>'+fmtD(med.data_aprovacao)+'</b></span>' : '')
        + (med.data_emissao   ? '<span>🔓 Liberado: <b>'+fmtD(med.data_emissao)+'</b></span>'  : '')
        + (med.data_nf        ? '<span>🧾 NF: <b>'+fmtD(med.data_nf)+'</b></span>'             : '')
        + (med.nfs            ? '<span>NF(s): <b>'+escHtml(med.nfs)+'</b></span>'               : '')
        + '</div>'
        // Body (collapsed by default, toggled)
        + '<div id="med-body-'+med.id+'" style="display:none">'
        + sotRenderMedicaoBody(med, projetoId, isUPS)
        + '</div>'
        + '</div>';
    }).join('');
  }

  html += '</div>';
  container.innerHTML = html;
}

function sotToggleMedicao(medId){
  var body = document.getElementById('med-body-'+medId);
  if(!body) return;
  body.style.display = body.style.display==='none' ? '' : 'none';
}

function sotRenderMedicaoBody(med, projetoId, isUPS){
  var itens = sot_med_itens.filter(function(i){ return i.medicao_id===med.id; });
  var st    = MED_STATUS[med.status] || MED_STATUS.rascunho;
  var podeEditar = med.status==='rascunho';

  var html = '<div style="padding:.75rem 1rem">';

  // Observations
  if(med.observacao){
    html += '<div style="background:#fff8e1;border-radius:6px;padding:.5rem .75rem;margin-bottom:.5rem;font-size:11px;color:#854F0B">📝 '+escHtml(med.observacao)+'</div>';
  }

  // Items table
  html += '<div style="overflow-x:auto;margin-bottom:.75rem">'
  + '<table style="width:100%;border-collapse:collapse;font-size:11px">'
  + '<thead><tr style="background:#f9f9f7;font-size:10px">'
  + '<th style="padding:5px 8px;text-align:left">Código</th>'
  + '<th style="padding:5px 8px;text-align:left">Descrição / Serviço</th>'
  + '<th style="padding:5px 8px;text-align:center">Un</th>'
  + (isUPS ? '<th style="padding:5px 8px;text-align:right">Qtd UPS</th><th style="padding:5px 8px;text-align:right">Vlr UPS</th>' : '<th style="padding:5px 8px;text-align:right">Vlr Unit.</th>')
  + '<th style="padding:5px 8px;text-align:right">Qtd Executada</th>'
  + '<th style="padding:5px 8px;text-align:right;color:'+(med.status==='aprovado'||med.status==='emissao_liberada'||med.status==='nf_emitida'?'#3B6D11':'#185FA5')+'">Qtd Medida</th>'
  + '<th style="padding:5px 8px;text-align:right;font-weight:700">Total</th>'
  + (podeEditar ? '<th style="padding:5px 8px"></th>' : '')
  + '</tr></thead><tbody>';

  if(!itens.length){
    html += '<tr><td colspan="8" style="padding:1rem;text-align:center;color:#aaa">Nenhum item ainda</td></tr>';
  } else {
    itens.forEach(function(item){
      var total = isUPS
        ? (item.qtd_medida||0) * (item.qtd_ups||1) * (item.valor_ups||0)
        : (item.qtd_medida||0) * (item.valor_unitario||0);
      html += '<tr style="border-bottom:.5px solid #f0efe8">'
        + '<td style="padding:5px 8px;font-size:10px;font-family:monospace;color:#888">'+(item.codigo||'—')+'</td>'
        + '<td style="padding:5px 8px;font-weight:500">'+escHtml(item.descricao||'')+'</td>'
        + '<td style="padding:5px 8px;text-align:center;color:#888">'+(item.unidade||'UN')+'</td>'
        + (isUPS
          ? '<td style="padding:5px 8px;text-align:right;color:#533AB7">'+(item.qtd_ups||1)+'</td>'
            +'<td style="padding:5px 8px;text-align:right;color:#533AB7">R$ '+fmtMoeda(item.valor_ups||0)+'</td>'
          : '<td style="padding:5px 8px;text-align:right">R$ '+fmtMoeda(item.valor_unitario||0)+'</td>')
        + '<td style="padding:5px 8px;text-align:right;color:#555">'+(item.qtd_executada||0)+'</td>'
        + '<td style="padding:5px 8px;text-align:right;font-weight:600;color:#185FA5">'
          + (podeEditar
            ? '<input type="number" step="0.01" min="0" value="'+(item.qtd_medida||0)+'" '
              + 'onchange="sotAtualizarQtdMedida(\''+item.id+'\',this.value,\''+med.id+'\',\''+projetoId+'\')" '
              + 'style="width:70px;border:.5px solid #e0dfd8;border-radius:4px;padding:2px 5px;text-align:right;font-size:11px">'
            : (item.qtd_medida||0))
          + '</td>'
        + '<td style="padding:5px 8px;text-align:right;font-weight:700;color:#3B6D11">R$ '+fmtMoeda(total)+'</td>'
        + (podeEditar ? '<td><button onclick="sotRemoverItemMedicao(\''+item.id+'\',\''+med.id+'\',\''+projetoId+'\')" style="background:none;border:none;cursor:pointer;color:#A32D2D;font-size:13px" title="Remover">✕</button></td>' : '')
        + '</tr>';
    });
  }

  // Totals row
  var totalGeral = itens.reduce(function(s,item){
    return s + (isUPS
      ? (item.qtd_medida||0)*(item.qtd_ups||1)*(item.valor_ups||0)
      : (item.qtd_medida||0)*(item.valor_unitario||0));
  }, 0);

  html += '<tr style="background:#f9f9f7;font-weight:700">'
    + '<td colspan="'+(isUPS?6:5)+'" style="padding:6px 8px;text-align:right;font-size:12px">Total da Parcial:</td>'
    + '<td style="padding:6px 8px;text-align:right;font-size:14px;color:#185FA5">R$ '+fmtMoeda(totalGeral)+'</td>'
    + (podeEditar ? '<td></td>' : '')
    + '</tr>';

  html += '</tbody></table></div>';

  // Actions based on status
  html += '<div style="display:flex;gap:.5rem;flex-wrap:wrap">';

  if(med.status==='rascunho'){
    html += '<button class="btn btn-sm" onclick="sotAdicionarItensMedicao(\''+med.id+'\',\''+projetoId+'\')" style="font-size:11px;color:#185FA5;border-color:#185FA5">➕ Adicionar itens</button>';
    html += '<button class="btn btn-sm" onclick="sotSugerirItensMedicao(\''+med.id+'\',\''+projetoId+'\')" style="font-size:11px">🔄 Sugerir do diário</button>';
    html += '<button class="btn btn-sm" onclick="sotAvancarMedicao(\''+med.id+'\',\'em_aprovacao\',\''+projetoId+'\')" style="font-size:11px;background:#854F0B;color:#fff;border-color:#854F0B">📤 Enviar p/ Aprovação</button>';
    html += '<button class="btn btn-sm" onclick="sotExcluirMedicao(\''+med.id+'\',\''+projetoId+'\')" style="font-size:11px;color:#A32D2D;border-color:#A32D2D">🗑 Excluir</button>';
  } else if(med.status==='em_aprovacao'){
    html += '<button class="btn btn-sm" onclick="sotAjustarMedicao(\''+med.id+'\',\''+projetoId+'\')" style="font-size:11px;color:#854F0B;border-color:#854F0B">✏️ Registrar Ajuste</button>';
    html += '<button class="btn btn-sm" onclick="sotAvancarMedicao(\''+med.id+'\',\'aprovado\',\''+projetoId+'\')" style="font-size:11px;background:#185FA5;color:#fff;border-color:#185FA5">✅ Registrar Aprovação</button>';
  } else if(med.status==='aprovado'){
    html += '<button class="btn btn-sm" onclick="sotAvancarMedicao(\''+med.id+'\',\'emissao_liberada\',\''+projetoId+'\')" style="font-size:11px;background:#3B6D11;color:#fff;border-color:#3B6D11">🔓 Liberar Emissão NF</button>';
  } else if(med.status==='emissao_liberada'){
    html += '<button class="btn btn-sm" onclick="sotRegistrarNF(\''+med.id+'\',\''+projetoId+'\')" style="font-size:11px;background:#085041;color:#fff;border-color:#085041">🧾 Registrar NF</button>';
  }

  html += '</div></div>';
  return html;
}

// ── Nova Medição ────────────────────────────────────────────────────────
function sotNovaMedicao(projetoId){
  var proj   = sot_projetos.find(function(x){ return x.id===projetoId; });
  var numero = sot_medicoes.filter(function(m){ return m.projeto_id===projetoId; }).length + 1;
  var hoje   = dataHojeLocal();

  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin-bottom:1rem">📐 Nova Medição — Parcial '+numero+'</h3>'
    +'<div style="display:grid;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Data de Corte *</label>'
    +'<input class="inp" id="nm-corte" type="date" value="'+hoje+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação</label>'
    +'<textarea class="inp" id="nm-obs" rows="2" style="width:100%;resize:none" placeholder="Descrição da parcial..."></textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="nm-salvar" style="flex:2">✅ Criar Medição</button>'
    +'</div></div></div>');

  setTimeout(function(){
    var btn = document.getElementById('nm-salvar');
    if(!btn) return;
    btn.onclick = function(){
      var corte = (document.getElementById('nm-corte')||{}).value||'';
      var obs   = (document.getElementById('nm-obs')||{}).value||'';
      if(!corte){ progShowToast('⚠ Informe a data de corte.','erro'); return; }

      var nova = {
        id:          'med'+Date.now(),
        projeto_id:  projetoId,
        numero:      numero,
        status:      'rascunho',
        data_corte:  corte,
        observacao:  obs,
        valor_total: 0,
        criado_em:   new Date().toISOString()
      };
      sot_medicoes.push(nova);
      closeModal();
      if(!DEMO){
        var p = Object.assign({},nova); delete p.id;
        sbInsert('sot_medicoes', p).then(function(r){
          if(r&&r[0]) nova.id=r[0].id;
          // Re-render after UUID is assigned so buttons have correct ID
          sotRenderTabMedicao(projetoId);
          setTimeout(function(){ sotToggleMedicao(nova.id); }, 100);
        }).catch(function(){
          sotRenderTabMedicao(projetoId);
          setTimeout(function(){ sotToggleMedicao(nova.id); }, 100);
        });
      } else {
        sotRenderTabMedicao(projetoId);
        setTimeout(function(){ sotToggleMedicao(nova.id); }, 100);
      }
    };
  }, 50);
}

// ── Sugerir itens do diário ────────────────────────────────────────────
function sotSugerirItensMedicao(medId, projetoId){
  var med   = sot_medicoes.find(function(m){ return m.id===medId; });
  if(!med || med.status!=='rascunho') return;
  var proj  = sot_projetos.find(function(x){ return x.id===projetoId; });
  var isUPS = proj && (proj.modalidade||'').toUpperCase().indexOf('UPS')>=0;

  // Get executed quantities from sot_atividades
  // Include all activities — prioritize executed, fallback to previewed
  var ativs = sot_atividades.filter(function(a){
    return a.projeto_id===projetoId && ((a.qtd_executada||0)>0 || (a.qtd_prevista||0)>0);
  });

  if(!ativs.length){
    progShowToast('⚠ Nenhuma atividade cadastrada neste projeto.','erro'); return;
  }

  // Check existing items in this medicao
  var existentes = sot_med_itens.filter(function(i){ return i.medicao_id===medId; });
  var added = 0;

  ativs.forEach(function(a){
    // Don't add if already in this medicao
    if(existentes.find(function(e){ return e.atividade_id===a.id; })) return;

    // Calculate how much was already measured in other parciais
    var jaMediado = sot_med_itens
      .filter(function(i){ return i.atividade_id===a.id && i.medicao_id!==medId; })
      .reduce(function(s,i){ return s+(i.qtd_medida||0); }, 0);

    var qtdBase   = (a.qtd_executada||0) > 0 ? (a.qtd_executada||0) : (a.qtd_prevista||0);
    var dispMedir = qtdBase - jaMediado;
    if(dispMedir <= 0) return;

    var novoItem = {
      id:             'mi'+Date.now()+added,
      medicao_id:     medId,
      projeto_id:     projetoId,
      atividade_id:   a.id,
      codigo:         a.codigo||'',
      descricao:      a.descricao||'',
      unidade:        a.unidade||'UN',
      qtd_executada:  a.qtd_executada||0,
      qtd_medida:     dispMedir,
      qtd_ups:        a.qtd_ups||1,
      valor_ups:      a.valor_ups||0,
      valor_unitario: a.valor_unitario||0
    };
    sot_med_itens.push(novoItem);
    if(!DEMO){
      var p = Object.assign({},novoItem); delete p.id;
      sbInsert('sot_med_itens', p).then(function(r){ if(r&&r[0]) novoItem.id=r[0].id; });
    }
    added++;
  });

  // Recalculate total
  sotRecalcTotalMedicao(medId, projetoId, isUPS);
  progShowToast('✅ '+added+' item(s) sugerido(s) do diário.');
  sotRenderTabMedicao(projetoId);
  setTimeout(function(){ sotToggleMedicao(medId); }, 100);
}

// ── Adicionar itens manualmente ─────────────────────────────────────────
function sotAdicionarItensMedicao(medId, projetoId){
  var proj  = sot_projetos.find(function(x){ return x.id===projetoId; });
  var isUPS = proj && (proj.modalidade||'').toUpperCase().indexOf('UPS')>=0;
  var ativs = sot_atividades.filter(function(a){ return a.projeto_id===projetoId; });
  var existentes = sot_med_itens.filter(function(i){ return i.medicao_id===medId; });

  var opts = ativs.map(function(a){
    var jaTem = existentes.find(function(e){ return e.atividade_id===a.id; });
    return '<option value="'+a.id+'"'+(jaTem?' disabled style="color:#aaa"':'')+'>'+escHtml((a.codigo?a.codigo+' — ':'')+a.descricao)+(jaTem?' (já incluído)':'')+'</option>';
  }).join('');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin-bottom:.75rem">➕ Adicionar Item à Medição</h3>'
    +'<div style="display:grid;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Atividade</label>'
    +'<select class="inp" id="ai-atv" style="width:100%" onchange="sotPreencherItemMedicao()"><option value="">Selecione...</option>'+opts+'</select></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Qtd Executada</label>'
    +'<input class="inp" id="ai-exec" type="number" readonly style="width:100%;background:#f9f9f7"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Qtd a Medir *</label>'
    +'<input class="inp" id="ai-medir" type="number" step="0.01" min="0" style="width:100%"/></div>'
    +'</div></div>'
    +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="ai-salvar" style="flex:2">✅ Adicionar</button>'
    +'</div></div></div>');

  // Store medId for the handler
  window._aiMedId     = medId;
  window._aiProjetoId = projetoId;
  window._aiIsUPS     = isUPS;

  setTimeout(function(){
    var btn = document.getElementById('ai-salvar');
    if(btn) btn.onclick = function(){
      var atvId = (document.getElementById('ai-atv')||{}).value;
      var qtd   = parseFloat((document.getElementById('ai-medir')||{}).value)||0;
      if(!atvId){ progShowToast('⚠ Selecione uma atividade.','erro'); return; }
      if(qtd<=0){ progShowToast('⚠ Informe a quantidade.','erro'); return; }

      var a = sot_atividades.find(function(x){ return x.id===atvId; });
      if(!a) return;

      var novoItem = {
        id:             'mi'+Date.now(),
        medicao_id:     window._aiMedId,
        projeto_id:     window._aiProjetoId,
        atividade_id:   a.id,
        codigo:         a.codigo||'',
        descricao:      a.descricao||'',
        unidade:        a.unidade||'UN',
        qtd_executada:  a.qtd_executada||0,
        qtd_medida:     qtd,
        qtd_ups:        a.qtd_ups||1,
        valor_ups:      a.valor_ups||0,
        valor_unitario: a.valor_unitario||0
      };
      sot_med_itens.push(novoItem);
      if(!DEMO){
        var p = Object.assign({},novoItem); delete p.id;
        sbInsert('sot_med_itens', p).then(function(r){ if(r&&r[0]) novoItem.id=r[0].id; });
      }
      sotRecalcTotalMedicao(window._aiMedId, window._aiProjetoId, window._aiIsUPS);
      closeModal();
      sotRenderTabMedicao(window._aiProjetoId);
      setTimeout(function(){ sotToggleMedicao(window._aiMedId); }, 100);
    };
  }, 50);
}

function sotPreencherItemMedicao(){
  var sel  = document.getElementById('ai-atv');
  var atvId= sel ? sel.value : '';
  var a    = sot_atividades.find(function(x){ return x.id===atvId; });
  var exec = document.getElementById('ai-exec');
  var med  = document.getElementById('ai-medir');
  if(exec) exec.value = a ? (a.qtd_executada||0) : '';
  if(med)  med.value  = a ? (a.qtd_executada||0) : '';
}

// ── Atualizar qtd medida inline ────────────────────────────────────────
function sotAtualizarQtdMedida(itemId, valor, medId, projetoId){
  var item = sot_med_itens.find(function(i){ return i.id===itemId; });
  if(!item) return;
  item.qtd_medida = parseFloat(valor)||0;
  if(!DEMO) sbUpdate('sot_med_itens',{qtd_medida:item.qtd_medida},'id=eq.'+itemId);
  var proj  = sot_projetos.find(function(x){ return x.id===projetoId; });
  var isUPS = proj && (proj.modalidade||'').toUpperCase().indexOf('UPS')>=0;
  sotRecalcTotalMedicao(medId, projetoId, isUPS);
}

// ── Remover item ────────────────────────────────────────────────────────
function sotRemoverItemMedicao(itemId, medId, projetoId){
  if(!confirm('Remover este item da medição?')) return;
  sot_med_itens = sot_med_itens.filter(function(i){ return i.id!==itemId; });
  if(!DEMO) sbDelete('sot_med_itens','id=eq.'+itemId);
  var proj  = sot_projetos.find(function(x){ return x.id===projetoId; });
  var isUPS = proj && (proj.modalidade||'').toUpperCase().indexOf('UPS')>=0;
  sotRecalcTotalMedicao(medId, projetoId, isUPS);
  sotRenderTabMedicao(projetoId);
  setTimeout(function(){ sotToggleMedicao(medId); }, 100);
}

// ── Recalcular total ────────────────────────────────────────────────────
function sotRecalcTotalMedicao(medId, projetoId, isUPS){
  var med   = sot_medicoes.find(function(m){ return m.id===medId; });
  if(!med) return;
  var itens = sot_med_itens.filter(function(i){ return i.medicao_id===medId; });
  med.valor_total = itens.reduce(function(s,item){
    return s + (isUPS
      ? (item.qtd_medida||0)*(item.qtd_ups||1)*(item.valor_ups||0)
      : (item.qtd_medida||0)*(item.valor_unitario||0));
  }, 0);
  if(!DEMO && isUUID(med.id))
    sbUpdate('sot_medicoes',{valor_total:med.valor_total},'id=eq.'+med.id);
}

// ── Avançar status ──────────────────────────────────────────────────────
function sotAvancarMedicao(medId, novoStatus, projetoId){
  var med = sot_medicoes.find(function(m){ return m.id===medId; });
  if(!med) return;

  var campos = {
    em_aprovacao:     {campo:'data_envio',     label:'Data de Envio ao Cliente', icon:'📤'},
    aprovado:         {campo:'data_aprovacao', label:'Data de Aprovação',        icon:'✅'},
    emissao_liberada: {campo:'data_emissao',   label:'Data de Liberação',        icon:'🔓'},
  };

  var cfg = campos[novoStatus];
  if(!cfg){ progShowToast('⚠ Status inválido.','erro'); return; }

  var hoje = dataHojeLocal();

  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.75rem">'+cfg.icon+' '+MED_STATUS[novoStatus].label+'</h3>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">'+cfg.label+' *</label>'
    +'<input class="inp" id="av-data" type="date" value="'+hoje+'" style="width:100%;margin-bottom:.6rem"/></div>'
    +(novoStatus==='em_aprovacao'
      ? '<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação</label>'
        +'<textarea class="inp" id="av-obs" rows="2" style="width:100%;resize:none" placeholder="Ex: Enviado por email para João em 24/05..."></textarea></div>'
      : '')
    +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="av-confirmar" style="flex:2">'+cfg.icon+' Confirmar</button>'
    +'</div></div></div>');

  window._avMedId     = medId;
  window._avStatus    = novoStatus;
  window._avProjId    = projetoId;
  window._avCampo     = cfg.campo;

  setTimeout(function(){
    var btn = document.getElementById('av-confirmar');
    if(!btn) return;
    btn.onclick = function(){
      var data = (document.getElementById('av-data')||{}).value;
      var obs  = (document.getElementById('av-obs')||{}).value||'';
      if(!data){ progShowToast('⚠ Informe a data.','erro'); return; }

      med.status = window._avStatus;
      med[window._avCampo] = data;
      if(obs) med.observacao = obs;

      var upd = {status: med.status};
      upd[window._avCampo] = data;
      if(obs) upd.observacao = obs;

      if(!DEMO && isUUID(med.id)) sbUpdate('sot_medicoes', upd, 'id=eq.'+med.id);
      closeModal();
      progShowToast('✅ Medição: '+MED_STATUS[med.status].label);
      sotRenderTabMedicao(window._avProjId);
      setTimeout(function(){ sotToggleMedicao(med.id); }, 100);
    };
  }, 50);
}

// ── Registrar ajuste do cliente ────────────────────────────────────────
function sotAjustarMedicao(medId, projetoId){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin-bottom:.75rem">✏️ Registrar Ajuste do Cliente</h3>'
    +'<p style="font-size:12px;color:#555;margin-bottom:.75rem">O cliente solicitou ajuste. Como deseja proceder?</p>'
    +'<div style="display:flex;flex-direction:column;gap:.5rem">'
    +'<button class="btn" onclick="sotAjusteApenasNaMedicao(\''+medId+'\',\''+projetoId+'\')" '
    +'style="text-align:left;padding:.75rem;font-size:12px">'
    +'<b>📐 Ajustar só na medição</b><br>'
    +'<span style="color:#888;font-size:11px">Altera a qtd medida. O restante entra na próxima parcial. Não altera o executado real.</span>'
    +'</button>'
    +'<button class="btn" onclick="sotAjusteNoExecutado(\''+medId+'\',\''+projetoId+'\')" '
    +'style="text-align:left;padding:.75rem;font-size:12px;border-color:#854F0B;color:#854F0B">'
    +'<b>⚠️ Ajustar o executado</b><br>'
    +'<span style="color:#888;font-size:11px">Altera o executado real. Requer justificativa. Use quando o serviço não foi realmente executado.</span>'
    +'</button>'
    +'</div>'
    +'<div style="margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'</div></div></div>');
}

function sotAjusteApenasNaMedicao(medId, projetoId){
  closeModal();
  // Re-open the medicao in edit mode (already editable in rascunho)
  // Just move back to rascunho so items can be edited
  var med = sot_medicoes.find(function(m){ return m.id===medId; });
  if(!med) return;
  if(!confirm('Voltar para Rascunho para editar as quantidades?')) return;
  med.status = 'rascunho';
  if(!DEMO && isUUID(med.id)) sbUpdate('sot_medicoes',{status:'rascunho'},'id=eq.'+med.id);
  progShowToast('✅ Medição voltou para Rascunho. Edite as quantidades e reenvie.');
  sotRenderTabMedicao(projetoId);
  setTimeout(function(){ sotToggleMedicao(med.id); }, 100);
}

function sotAjusteNoExecutado(medId, projetoId){
  closeModal();
  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.75rem">⚠️ Ajuste no Executado Real</h3>'
    +'<p style="font-size:12px;color:#854F0B;margin-bottom:.75rem">Esta ação altera o executado real no diário. Use apenas se o serviço <b>não foi realmente executado</b>.</p>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Justificativa *</label>'
    +'<textarea class="inp" id="ajex-just" rows="3" style="width:100%;resize:none" placeholder="Ex: Serviço não executado — cabo não chegou ao local. Corte reduzido de 150m para 80m."></textarea></div>'
    +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn" onclick="sotConfirmarAjusteExecutado(\''+medId+'\',\''+projetoId+'\')" '
    +'style="flex:2;background:#854F0B;color:#fff;border-color:#854F0B;font-size:12px">⚠️ Confirmar Ajuste</button>'
    +'</div></div></div>');
}

function sotConfirmarAjusteExecutado(medId, projetoId){
  var just = ((document.getElementById('ajex-just')||{}).value||'').trim();
  if(!just){ progShowToast('⚠ Justificativa obrigatória.','erro'); return; }
  var med = sot_medicoes.find(function(m){ return m.id===medId; });
  if(!med) return;
  med.status = 'rascunho';
  med.observacao = (med.observacao||'') + ' | AJUSTE: '+just;
  if(!DEMO && isUUID(med.id))
    sbUpdate('sot_medicoes',{status:'rascunho',observacao:med.observacao},'id=eq.'+med.id);
  closeModal();
  progShowToast('✅ Registrado. Edite as atividades e reenvie a medição.');
  sotRenderTabMedicao(projetoId);
  setTimeout(function(){ sotToggleMedicao(med.id); }, 100);
}

// ── Registrar NF ────────────────────────────────────────────────────────
function sotRegistrarNF(medId, projetoId){
  var med = sot_medicoes.find(function(m){ return m.id===medId; });
  if(!med) return;
  var hoje = dataHojeLocal();

  setModal('<div class="modal-bg"><div class="modal" style="max-width:440px">'
    +'<h3 style="margin-bottom:.75rem">🧾 Registrar Nota Fiscal</h3>'
    +'<div style="background:#EAF3DE;border-radius:8px;padding:.6rem .75rem;margin-bottom:.75rem;text-align:center">'
    +'<div style="font-size:11px;color:#888">Valor da Parcial</div>'
    +'<div style="font-size:20px;font-weight:700;color:#3B6D11">R$ '+fmtMoeda(med.valor_total||0)+'</div>'
    +'</div>'
    +'<div style="display:grid;gap:.6rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Número(s) da NF * <span style="font-weight:400;color:#888">(separe por vírgula se mais de uma)</span></label>'
    +'<input class="inp" id="nf-num" style="width:100%" placeholder="Ex: 12345 ou 12345, 12346"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Data de Emissão *</label>'
    +'<input class="inp" id="nf-data" type="date" value="'+hoje+'" style="width:100%"/></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Tipo</label>'
    +'<select class="inp" id="nf-tipo" style="width:100%"><option value="unico">Única NF</option><option value="opex_capex">Opex + Capex</option><option value="multipla">Múltiplas</option></select></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Valor Total NF(s) R$</label>'
    +'<input class="inp" id="nf-valor" type="number" step="0.01" value="'+(med.valor_total||0)+'" style="width:100%"/></div>'
    +'</div></div>'
    +'<div style="display:flex;gap:.5rem;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="nf-salvar" style="flex:2;background:#085041;border-color:#085041">🧾 Registrar</button>'
    +'</div></div></div>');

  window._nfMedId  = medId;
  window._nfProjId = projetoId;

  setTimeout(function(){
    var btn = document.getElementById('nf-salvar');
    if(!btn) return;
    btn.onclick = function(){
      var num   = ((document.getElementById('nf-num')||{}).value||'').trim();
      var data  = (document.getElementById('nf-data')||{}).value;
      var valor = parseFloat((document.getElementById('nf-valor')||{}).value)||0;
      if(!num)  { progShowToast('⚠ Informe o número da NF.','erro'); return; }
      if(!data) { progShowToast('⚠ Informe a data.','erro'); return; }

      med.status   = 'nf_emitida';
      med.nfs      = num;
      med.data_nf  = data;
      med.valor_nf = valor;

      if(!DEMO && isUUID(med.id))
        sbUpdate('sot_medicoes',{status:'nf_emitida',nfs:num,data_nf:data,valor_nf:valor},'id=eq.'+med.id);

      closeModal();
      progShowToast('🧾 NF registrada! Medição finalizada.');
      sotRenderTabMedicao(window._nfProjId);
    };
  }, 50);
}

// ── Excluir medição ─────────────────────────────────────────────────────
function sotExcluirMedicao(medId, projetoId){
  if(!confirm('Excluir esta medição? Os itens também serão removidos.')) return;
  sot_med_itens  = sot_med_itens.filter(function(i){ return i.medicao_id!==medId; });
  sot_medicoes   = sot_medicoes.filter(function(m){ return m.id!==medId; });
  if(!DEMO){
    sbDelete('sot_med_itens','medicao_id=eq.'+medId);
    sbDelete('sot_medicoes', 'id=eq.'+medId);
  }
  progShowToast('✅ Medição excluída.');
  sotRenderTabMedicao(projetoId);
}


function sotRenderDetalhe(p, docs){
  // Funciona tanto no SOT Obras quanto no painel co-* (PLPT etc.)
  var wrap = document.getElementById('co-proj-lista') || document.getElementById('sot-lista-projetos');
  if(!wrap) return;
  var sc=SOT_STATUS_COR[p.status]||{bg:'#f5f5f3',cor:'#555'};

  var valPrev=p.valor_previsto||sot_atividades.reduce(function(s,a){return s+(a.valor_total||a.qtd_prevista*a.valor_unitario||0);},0);
  var valViab=sot_atividades.reduce(function(s,a){return s+(a.qtd_viabilizada||0)*(a.valor_unitario||0);},0);
  var valExec=sot_atividades.reduce(function(s,a){return s+(a.qtd_executada||0)*(a.valor_unitario||0);},0);
  var valMed=sot_atividades.reduce(function(s,a){return s+(a.qtd_medida||0)*(a.valor_unitario||0);},0);
  var pct=valPrev>0?Math.round(valExec/valPrev*100):0;

  wrap.innerHTML=''
    // Breadcrumb
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:1rem">'
    +'<button class="btn btn-sm" onclick="document.getElementById(\'co-proj-lista\')?coRenderProjetos():sotInit()">← Projetos</button>'
    +'<span style="color:#aaa;font-size:12px">/</span>'
    +'<span style="font-size:13px;font-weight:500">'+p.nome+'</span>'
    +'<span style="background:'+sc.bg+';color:'+sc.cor+';border-radius:6px;padding:2px 8px;font-size:11px;font-weight:600;margin-left:auto">'+p.status+'</span>'
    +'<button class="btn btn-sm" onclick="sotAlterarStatus(\''+p.id+'\')" style="color:'+sc.cor+';border-color:'+sc.cor+'">'+(isContratoPLPT(p.contrato_id)?'⚡ Esteira':'↑ Status')+'</button>'
    +'<button class="btn btn-sm" onclick="sotAbrirEditarProjeto(\''+p.id+'\')" style="color:#185FA5;border-color:#185FA5">✎ Editar</button>'
    +'</div>'

    // Dados do projeto
    +'<div style="display:grid;grid-template-columns:2fr 1fr;gap:1rem;margin-bottom:1rem">'

    // Card principal
    +'<div class="card">'
    +'<div class="ch"><span class="ct">Dados do Projeto</span></div>'
    +'<div style="padding:1rem;display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    +[
      ['Cliente',p.cliente||'—'],['Código do cliente',p.codigo_cliente||'—'],
      ['Tipo de serviço',p.tipo_servico||'—'],['Local',p.local_endereco||'—'],
      ['Cidade',p.cidade||'—'],['Responsável',p.responsavel_interno||'—'],
      ['Supervisor',p.supervisor||'—'],['Encarregado',p.encarregado_previsto||'—'],
      ['Recebimento',p.data_recebimento?fmtD(p.data_recebimento):'—'],
      ['Prazo',p.prazo_previsto?fmtD(p.prazo_previsto):'—'],
    ].map(function(f){
      return '<div><div style="font-size:10px;color:#888">'+f[0]+'</div>'
        +'<div style="font-size:13px;font-weight:500">'+f[1]+'</div></div>';
    }).join('')
    +(p.relatorio_obras?'<div style="grid-column:span 2"><div style="font-size:10px;color:#888">Relatório de obras'
      +(p.relatorio_obras_at?' · '+plptFmtTs(p.relatorio_obras_at):'')
      +(p.relatorio_obras_por?' · '+escHtml(p.relatorio_obras_por):'')
      +'</div><div style="font-size:12px;color:#555;white-space:pre-wrap;max-height:80px;overflow-y:auto">'+escHtml(p.relatorio_obras)+'</div></div>':'')
    +(p.observacoes?'<div style="grid-column:span 2"><div style="font-size:10px;color:#888">Observações</div>'
      +'<div style="font-size:12px;color:#555">'+p.observacoes+'</div></div>':'')
    +'</div></div>'

    // Card financeiro
    +'<div style="display:flex;flex-direction:column;gap:.75rem">'
    +'<div class="card">'
    +'<div class="ch"><span class="ct">Financeiro</span></div>'
    +'<div style="padding:1rem">'
    +[
      ['Previsto',    valPrev, '#555'],
      ['Viabilizado', valViab, '#185FA5'],
      ['Executado',   valExec, '#3B6D11'],
      ['Medido',      valMed,  '#3B6D11'],
      ['Faturado',    p.valor_faturado||0, '#085041'],
    ].map(function(f){
      var pct2 = valPrev>0?Math.round(f[1]/valPrev*100):0;
      return '<div style="padding:5px 0;border-bottom:.5px solid #f5f5f3">'
        +'<div style="display:flex;justify-content:space-between;margin-bottom:2px">'
        +'<span style="font-size:12px;color:#888">'+f[0]+'</span>'
        +'<span style="font-size:13px;font-weight:600;color:'+f[2]+'">'+fmtMoeda(f[1])+'</span>'
        +'</div>'
        +(f[1]>0&&f[0]!=='Previsto'
          ?'<div style="background:#f0f0ee;border-radius:3px;height:3px">'
           +'<div style="background:'+f[2]+';width:'+pct2+'%;height:100%;border-radius:3px"></div>'
           +'</div>':'')
        +'</div>';
    }).join('')
    +'<div id="sot-val-prev" style="display:none">'+fmtMoeda(valPrev)+'</div>'
    +'<div id="sot-val-exec" style="display:none">'+fmtMoeda(valExec)+'</div>'
    +'<div style="margin-top:.75rem">'
    +'<div style="background:#f0f0ee;border-radius:6px;height:8px">'
    +'<div id="sot-barra-exec" style="background:'+sc.cor+';width:'+Math.min(100,pct)+'%;height:100%;border-radius:6px"></div>'
    +'</div>'
    +'<div style="text-align:right;font-size:10px;color:#888;margin-top:2px"><span id="sot-pct-exec">'+pct+'</span>% executado</div>'
    +'</div>'
    +'</div></div>'

    // Histórico de status
    +'<div class="card">'
    +'<div class="ch"><span class="ct">Histórico</span></div>'
    +'<div style="padding:.75rem;max-height:150px;overflow-y:auto">'
    +(sot_historico.length
      ? sot_historico.slice(0,5).map(function(h){
          var sc2=SOT_STATUS_COR[h.status_novo]||{cor:'#555'};
          return '<div style="display:flex;gap:6px;padding:4px 0;border-bottom:.5px solid #f5f5f3;font-size:11px">'
            +'<span style="color:'+sc2.cor+';font-weight:500">'+h.status_novo+'</span>'
            +'<span style="color:#aaa;margin-left:auto">'+fmtD(h.criado_em.split('T')[0])+'</span>'
            +'</div>';
        }).join('')
      : '<div style="color:#aaa;font-size:11px">Sem histórico</div>')
    +'</div></div>'
    +'</div></div>'

    // Card Croqui — fora do grid, largura total
    +(p.croqui_url
      ? '<div class="card" style="margin-bottom:.75rem">'
        +'<div class="ch"><span class="ct">🗺 Croqui do Projeto</span>'
        +'<button class="btn btn-pri btn-sm" onclick="sotIniciarAnaliseWL(\''+p.id+'\')" style="font-size:11px">🔍 Analisar WLs</button>'
        +'</div>'
        +'<div style="padding:1rem;text-align:center">'
        +(p.croqui_url.includes('.pdf')||p.croqui_url.startsWith('data:application/pdf')
          ? '<div style="background:#EBF4FD;border:.5px solid #185FA5;border-radius:8px;padding:1rem;display:inline-flex;align-items:center;gap:10px">'
            +'<span style="font-size:28px">📄</span>'
            +'<div style="text-align:left"><div style="font-size:13px;font-weight:600;color:#185FA5">Croqui em PDF</div>'
            +'<a href="'+p.croqui_url+'" target="_blank" style="font-size:11px;color:#185FA5">Abrir arquivo →</a></div></div>'
          : '<img src="'+p.croqui_url+'" style="max-width:100%;max-height:500px;border:.5px solid #e0dfd8;border-radius:8px;cursor:zoom-in" '
            +'onclick="window.open(this.src,\'_blank\')" title="Clique para ampliar">')
        +'</div></div>'
      : '')

    // Abas de detalhe
    +'<div class="card">'
    +'<div style="display:flex;border-bottom:.5px solid #e0dfd8;overflow-x:auto">'
    +['atividades','materiais','reserva','resumo','plano','documentos','adicional','medicao'].map(function(t,i){
      var labels={atividades:'📋 Atividades ('+sot_atividades.length+')',
        materiais:'📦 Materiais ('+sot_materiais_proj.length+')',
        reserva:'🧰 Reservar Materiais',
        resumo:'📊 Resumo',
        plano:'📋 Plano de Execução'+(sotPlanoContarWls(p)?' ('+sotPlanoContarWls(p)+' WLs)':''),
        documentos:'📄 Documentos ('+(docs.length)+')',
        adicional:'➕ Adicional', medicao:'📐 Medições'};
      return '<button id="sot-tab-'+t+'" onclick="sotMostrarTab(\''+t+'\')" '
        +'style="padding:.6rem 1rem;border:none;border-bottom:2px solid '+(i===0?sc.cor:'transparent')+';'
        +'background:none;cursor:pointer;font-size:12px;font-weight:600;color:'+(i===0?sc.cor:'#888')+';white-space:nowrap">'
        +labels[t]+'</button>';
    }).join('')
    +'<button id="sot-tab-validacoes" onclick="sotMostrarTab(\'validacoes\')" '
    +'style="padding:.6rem 1rem;border:none;border-bottom:2px solid transparent;background:none;cursor:pointer;font-size:12px;font-weight:600;color:#854F0B;white-space:nowrap">⏳ Campo</button>'
    +'<button class="btn btn-sm" onclick="sotGerarDeParaSOT(\''+p.id+'\')" '
      +'style="margin-left:auto;margin:.4rem .25rem;font-size:11px;background:#185FA5;color:#fff;border-color:#185FA5">📋 De Para</button>'
    +'<button class="btn btn-sm" onclick="sotAbrirNovaAtividade(\''+p.id+'\')" '
      +'style="font-size:11px;margin:.4rem .25rem">+ Atividade</button>'
    +'<button class="btn btn-sm" onclick="sotAbrirNovoMaterial(\''+p.id+'\')" '
      +'style="font-size:11px;margin:.4rem .25rem">+ Material</button>'
    +'<button class="btn btn-sm" onclick="sotAbrirAnexarDoc(\''+p.id+'\')" '
      +'style="font-size:11px;margin:.4rem .25rem;color:#185FA5;border-color:#185FA5">📎 Doc</button>'
    +'<button class="btn btn-sm" onclick="sotAnalisarRelatorio(\''+p.id+'\')" '
      +'style="font-size:11px;margin:.4rem .75rem;background:linear-gradient(135deg,#533AB7,#185FA5);color:#fff;border:none;font-weight:600">🤖 Analisar relatório</button>'
    +'</div>'

    // Conteúdo da aba
    +'<div id="sot-tab-content">'
    +sotRenderTabAtividades(p.id)
    +'</div></div>';

  // Guardar docs para uso nas abas
  window._sotDocs = docs;
}

// ── Atualizar aba ativa sem recarregar do banco ───────────────
// Usa os dados já em memória — evita reload completo após cada ação
function sotAtualizarAbaAtual(projetoId){
  var p = sot_projetos.find(function(x){ return x.id===projetoId; });
  if(!p) return;

  // Descobrir qual aba está visível
  var content = document.getElementById('sot-tab-content');
  if(!content){ sotAbrirProjeto(projetoId); return; }

  // Verificar qual aba está ativa — usar variável global ou border-bottom
  var tabAtiva = window._sotTabAtiva || 'atividades';
  if(!window._sotTabAtiva){
    ['atividades','materiais','reserva','resumo','plano','documentos','adicional','medicao'].forEach(function(t){
      var btn = document.getElementById('sot-tab-'+t);
      if(btn && (btn.style.fontWeight==='700' || btn.style.borderBottomColor==='rgb(26, 26, 24)' || btn.classList.contains('active')))
        tabAtiva = t;
    });
  }

  // Atualizar só o conteúdo da aba ativa
  if(tabAtiva==='atividades'){
    content.innerHTML = sotRenderTabAtividades(projetoId);
  } else if(tabAtiva==='materiais'){
    sotRenderTabMateriaisComSaldoAuto(projetoId, content);
  } else if(tabAtiva==='reserva'){
    sotRenderTabReserva(projetoId, content);
  } else if(tabAtiva==='resumo'){
    sotRenderTabResumo(projetoId, content);
  } else if(tabAtiva==='plano'){
    sotRenderTabPlano(projetoId, content);
  } else if(tabAtiva==='adicional'){
    sotRenderTabAdicional && sotRenderTabAdicional(projetoId, content);
  } else if(tabAtiva==='medicao'){
    sotRenderTabMedicao(projetoId, content);
  } else {
    content.innerHTML = sotRenderTabDocumentos(projetoId);
  }

  // Atualizar valores financeiros no cabeçalho sem re-renderizar tudo
  var valPrev = p.valor_previsto||sot_atividades.reduce(function(s,a){return s+(a.valor_total||a.qtd_prevista*a.valor_unitario||0);},0);
  var valViab = sot_atividades.reduce(function(s,a){return s+(a.qtd_viabilizada||0)*(a.valor_unitario||0);},0);
  var valExec = sot_atividades.reduce(function(s,a){return s+(a.qtd_executada||0)*(a.valor_unitario||0);},0);
  var pct = valPrev>0?Math.round(valExec/valPrev*100):0;

  var elPrev = document.getElementById('sot-val-prev');
  var elExec = document.getElementById('sot-val-exec');
  var elPct  = document.getElementById('sot-pct-exec');
  var elBarra= document.getElementById('sot-barra-exec');
  if(elPrev) elPrev.textContent = fmtMoeda(valPrev);
  if(elExec) elExec.textContent = fmtMoeda(valExec);
  if(elPct)  elPct.textContent  = pct+'%';
  if(elBarra)elBarra.style.width = Math.min(100,pct)+'%';
}

function sotMostrarTab(tab){
  var p=sot_projetos.find(function(x){return x.id===_sotProjetoAtual;});
  if(!p)return;
  window._sotTabAtiva = tab; // track active tab for sotAtualizarAbaAtual
  var sc=SOT_STATUS_COR[p.status]||{cor:'#555'};
  ['atividades','materiais','reserva','resumo','plano','documentos','adicional','medicao'].forEach(function(t){
    var btn=document.getElementById('sot-tab-'+t);
    if(btn){
      btn.style.borderBottomColor=t===tab?sc.cor:'transparent';
      btn.style.color=t===tab?sc.cor:'#888';
    }
  });
  var content=document.getElementById('sot-tab-content');
  if(!content)return;
  if(tab==='atividades')content.innerHTML=sotRenderTabAtividades(p.id);
  else if(tab==='materiais') sotRenderTabMateriaisComSaldoAuto(p.id, content);
  else if(tab==='documentos')content.innerHTML=sotRenderTabDocumentos(p.id);
  else if(tab==='reserva') sotRenderTabReserva(p.id, content);
  else if(tab==='resumo') sotRenderTabResumo(p.id, content);
  else if(tab==='plano') sotRenderTabPlano(p.id, content);
  else if(tab==='adicional')sotRenderTabAdicional(p.id,content);
  else if(tab==='validacoes'){
    content.innerHTML='<div style="padding:1rem"><div style="font-size:13px;font-weight:600;margin-bottom:.75rem;color:#854F0B">⏳ Lançamentos do campo — aguardando validação</div>'
      +'<div id="sot-validacoes-campo"><div style="color:#aaa;text-align:center;padding:1rem">Carregando...</div></div>'
      +'</div>';
    sotRenderValidacoesCampo(p.id);
  }
  else if(tab==='medicao') sotRenderTabMedicao(p.id, content);
}

function sotRenderTabAdicional(projId, container){
  var el = container || document.getElementById('sot-tab-content');
  if(!el) return;
  el.innerHTML='<div style="padding:.5rem;text-align:center;color:#aaa">Carregando adicionais...</div>';
  if(!DEMO){
    sbFetch('sot_adicionais',{filters:['projeto_id=eq.'+projId],order:'criado_em.desc'})
      .then(function(rows){
        var adics=rows||[];
        var cid=(sot_projetos.find(function(p){return p.id===projId;})||{}).contrato_id||'';
        el.innerHTML=_sotBuildAdicionalHtml(projId, adics, cid);
      }).catch(function(){ el.innerHTML='<div style="padding:1rem;color:#A32D2D">Erro ao carregar adicionais.</div>'; });
  } else {
    el.innerHTML=_sotBuildAdicionalHtml(projId, [], '');
  }
}

function _sotBuildAdicionalHtml(projId, adics, cid){
  var ativos   = adics.filter(function(a){return a.tipo==='atividade';});
  var materiais= adics.filter(function(a){return a.tipo==='material';});
  function row(a){
    return '<tr><td style="padding:6px 8px;font-size:12px">'+(a.codigo_sap||'—')+'</td>'
      +'<td style="padding:6px 8px;font-size:12px">'+a.descricao+'</td>'
      +'<td style="padding:6px 8px;font-size:12px;text-align:center">'+a.qtd_solicitada+' '+(a.unidade||'UN')+'</td>'
      +'<td style="padding:6px 8px;font-size:11px;color:#888">'+(a.observacoes||'')+'</td>'
      +'<td style="padding:6px 8px;font-size:11px;color:#888">'+(a.criado_por||'')+'</td>'
      +'<td style="padding:6px 8px;font-size:10px;color:#854F0B;font-weight:600">ADICIONAL</td>'
      +'</tr>';
  }
  var tblHdr='<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f9f9f7;font-size:10px;color:#888;text-transform:uppercase">'
    +'<th style="padding:6px 8px;text-align:left">Cód. SAP</th>'
    +'<th style="padding:6px 8px;text-align:left">Descrição</th>'
    +'<th style="padding:6px 8px;text-align:center">Qtd</th>'
    +'<th style="padding:6px 8px;text-align:left">Observações</th>'
    +'<th style="padding:6px 8px;text-align:left">Solicitado por</th>'
    +'<th style="padding:6px 8px;text-align:left">Status</th>'
    +'</tr></thead><tbody>';
  return '<div style="padding:.75rem">'
    +'<div style="display:flex;gap:8px;margin-bottom:1rem">'
    +'<button onclick="sotAbrirNovoAdicional(\''+projId+'\',\'material\')" class="btn btn-pri" style="font-size:12px">+ Material adicional</button>'
    +'<button onclick="sotAbrirNovoAdicional(\''+projId+'\',\'atividade\')" class="btn" style="font-size:12px;color:#185FA5;border-color:#185FA5">+ Atividade adicional</button>'
    +'<button onclick="sotGerarDeParaSOT(\''+projId+'\')" class="btn" style="font-size:12px;color:#185FA5;border-color:#185FA5;margin-left:auto">📋 Gerar De Para</button>'
    +'</div>'
    +(materiais.length?'<div style="font-weight:600;font-size:12px;margin-bottom:.5rem;color:#854F0B">📦 Materiais Adicionais ('+materiais.length+')</div>'+tblHdr+materiais.map(row).join('')+'</tbody></table><br>':'')
    +(ativos.length?'<div style="font-weight:600;font-size:12px;margin-bottom:.5rem;color:#185FA5">⚡ Atividades Adicionais ('+ativos.length+')</div>'+tblHdr+ativos.map(row).join('')+'</tbody></table><br>':'')
    +(!adics.length?'<div style="text-align:center;color:#aaa;padding:2rem;font-size:13px">Nenhum adicional registrado para este projeto.</div>':'')
    +'</div>';
}

function sotAbrirNovoAdicional(projId, tipo){
  // Reutiliza a função do diário PLPT adaptada para contexto SOT
  var mockPj={projeto_id:projId,_adicionais:[],_adicSub:tipo};
  var prevAtivo=_plptDiario.projetoAtivo;
  _plptDiario.projetoAtivo=mockPj;
  plptNovoAdicional(projId, tipo);
  // Sobrescrever o salvar para recarregar aba SOT ao invés do diário
  setTimeout(function(){
    var btnSalvar=document.querySelector('#modal-area .btn-pri');
    if(btnSalvar){
      var originalOnclick=btnSalvar.onclick;
      btnSalvar.onclick=function(){
        plptSalvarAdicional(projId, tipo);
        setTimeout(function(){
          _plptDiario.projetoAtivo=prevAtivo;
          sotRenderTabAdicional(projId);
        },300);
      };
    }
  },100);
}

function sotGerarDeParaSOT(projId){
  var _sotMats = (typeof sot_materiais!=='undefined') ? sot_materiais : [];
  var mats = _sotMats.filter(function(m){return m.projeto_id===projId;});
  if(!mats.length&&!DEMO){
    sbFetch('sot_materiais',{filters:['projeto_id=eq.'+projId,'deleted_at=is.null']}).then(function(rows){
      if(rows&&rows.length && typeof sot_materiais!=='undefined'){
        rows.forEach(function(m){if(!sot_materiais.find(function(x){return x.id===m.id;}))sot_materiais.push(m);});
      }
      sbFetch('sot_adicionais',{filters:['projeto_id=eq.'+projId,'tipo=eq.material']}).then(function(adics){
        _plptDiario.projetoAtivo={projeto_id:projId,_materiais:rows||[],_adicionais:adics||[]};
        plptGerarDePara(projId);
      });
    });
    return;
  }
  sbFetch('sot_adicionais',{filters:['projeto_id=eq.'+projId,'tipo=eq.material']}).then(function(adics){
    _plptDiario.projetoAtivo={projeto_id:projId,_materiais:mats,_adicionais:adics||[]};
    plptGerarDePara(projId);
  }).catch(function(){
    _plptDiario.projetoAtivo={projeto_id:projId,_materiais:mats,_adicionais:[]};
    plptGerarDePara(projId);
  });
}

function sotRenderTabAtividades(projetoId){
  var proj = sot_projetos.find(function(x){ return x.id===projetoId; });
  var isListaPrecos = proj && (proj.modalidade||'').toLowerCase().indexOf('lista')>=0;
  var isUPS = proj && (proj.modalidade||'').toUpperCase().indexOf('UPS')>=0;

  var btnArea = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:.75rem">'
    +'<button class="btn btn-pri" onclick="sotAbrirNovaAtividade(\''+projetoId+'\')">+ Adicionar atividade</button>'
    +'<button class="btn" onclick="sotImportarAtividades(\''+projetoId+'\')" style="color:#185FA5;border-color:#185FA5">📥 Importar lista (CSV/Excel)</button>'
    +'</div>';

  if(!sot_atividades.length){
    return btnArea+'<div style="padding:2rem;text-align:center;color:#aaa">'
      +'Nenhuma atividade cadastrada.</div>';
  }
  var valViab = sot_atividades.reduce(function(s,a){return s+(a.qtd_viabilizada||0)*(a.valor_unitario||0);},0);
  var valTotal = isUPS
    ? sot_atividades.reduce(function(s,a){return s+(a.qtd_prevista||0)*(a.qtd_ups||1)*(a.valor_ups||0);},0)
    : sot_atividades.reduce(function(s,a){return s+(a.qtd_prevista||0)*(a.valor_unitario||0);},0);
  return btnArea+'<div style="overflow-x:auto">'
    +'<table class="tbl" style="min-width:820px">'
    +'<thead><tr style="background:#f9f9f7">'
    +'<th style="width:30px">#</th><th>Código</th><th>Descrição</th>'
    +'<th>Etapa</th><th style="text-align:right">Qtd Prev.</th><th>Un</th>'
    +(isUPS
      ? '<th style="text-align:right;color:#533AB7" title="Qtd UPS do serviço">Qtd UPS</th>'
        +'<th style="text-align:right;color:#533AB7" title="Valor UPS do serviço">Valor UPS</th>'
      : '<th style="text-align:right">V.Unit.</th>')
    +'<th style="text-align:right;font-weight:700">Total</th>'
    +'<th style="text-align:right;color:#185FA5" title="Quantidade Viabilizada">Qtd Viab.</th>'
    +'<th style="text-align:right;color:#3B6D11" title="Quantidade Executada">Qtd Exec.</th>'
    +'<th>Status</th><th></th>'
    +'</tr></thead>'
    +'<tbody>'
    +sot_atividades.map(function(a){
      var st=a.status||'pendente';
      var stCor={pendente:'#888',em_execucao:'#185FA5',executada:'#3B6D11',
        executada_parcial:'#854F0B',cancelada:'#A32D2D',divergente:'#534AB7',
        viabilizado:'#185FA5'}[st]||'#555';
      var stLabel={pendente:'Pendente',em_execucao:'Em execução',executada:'Executada',
        executada_parcial:'Exec. parcial',cancelada:'Cancelada',divergente:'Divergente',
        viabilizado:'Viabilizado'}[st]||st;
      var pctViab = a.qtd_prevista>0?Math.min(100,Math.round((a.qtd_viabilizada||0)/a.qtd_prevista*100)):0;
      var pctExec = a.qtd_prevista>0?Math.min(100,Math.round((a.qtd_executada||0)/a.qtd_prevista*100)):0;
      return '<tr>'
        +'<td style="color:#888;font-size:11px">'+a.ordem_exec+'</td>'
        +'<td style="font-size:11px;font-family:monospace">'+(a.codigo||'—')+'</td>'
        +'<td style="font-weight:500;font-size:12px">'+a.descricao+'</td>'
        +'<td style="font-size:11px;color:#888">'+(a.etapa||'—')+'</td>'
        +'<td style="font-size:12px;text-align:right">'+(a.qtd_prevista||0)+'</td>'
        +'<td style="font-size:11px;color:#888">'+(a.unidade||'UN')+'</td>'
        +(isUPS
          ? '<td style="font-size:12px;text-align:right;color:#533AB7">'+(a.qtd_ups||1)+'</td>'
            +'<td style="font-size:12px;text-align:right;color:#533AB7">'+fmtMoeda(a.valor_ups||0)+'</td>'
          : '<td style="font-size:12px;text-align:right">'+fmtMoeda(a.valor_unitario||0)+'</td>'
        )
        +'<td style="font-size:12px;font-weight:600;text-align:right">'
        +(isUPS
          ? fmtMoeda((a.qtd_prevista||0) * (a.qtd_ups||1) * (a.valor_ups||0))
          : fmtMoeda((a.qtd_prevista||0) * (a.valor_unitario||0)))
        +'</td>'
        // Qtd Viab
        +'<td style="text-align:right">'
        +(a.qtd_viabilizada>0
          ?'<span style="font-size:12px;font-weight:600;color:#185FA5">'+(a.qtd_viabilizada||0)+'</span>'
          +'<span style="font-size:10px;color:#aaa;display:block">'+pctViab+'%</span>'
          :'<span style="color:#ccc;font-size:11px">—</span>')
        +'</td>'
        // Qtd Exec
        +'<td style="text-align:right">'
        +(a.qtd_executada>0
          ?'<span style="font-size:12px;font-weight:600;color:#3B6D11">'+(a.qtd_executada||0)+'</span>'
          +'<span style="font-size:10px;color:#aaa;display:block">'+pctExec+'%</span>'
          :'<span style="color:#ccc;font-size:11px">—</span>')
        +'</td>'
        +'<td><span style="background:'+stCor+'22;color:'+stCor+';border-radius:4px;padding:1px 6px;font-size:10px;font-weight:600">'+stLabel+'</span></td>'
        +'<td style="display:flex;gap:2px">'
        // Botão dropdown lançar
        +'<div style="position:relative;display:inline-block">'
        +'<button class="btn btn-sm btn-pri" style="font-size:10px;padding:3px 7px" '
        +'onclick="sotMenuLancamento(\''+a.id+'\',this)" title="Lançar">▶ Lançar</button>'
        +'</div>'
        +'<button class="btn btn-sm" onclick="sotEditarAtividade(\''+a.id+'\')" style="font-size:10px" title="Editar">✎</button>'
        +'<button class="btn btn-sm" onclick="if(confirm(\'Excluir atividade?\')){sot_atividades=sot_atividades.filter(function(x){return x.id!==\''+a.id+'\';});if(!DEMO)sbDelete(\'sot_atividades\',\'id=eq.'+a.id+'\');sotAtualizarAbaAtual(\''+a.projeto_id+'\');}" style="font-size:10px;color:#A32D2D" title="Excluir">🗑</button>'
        +'</td>'
        +'</tr>';
    }).join('')
    +'<tr style="background:#f9f9f7;font-weight:600">'
    +(isUPS
      ? '<td colspan="8" style="text-align:right;font-size:12px;padding:6px 8px">Totais:</td>'
      : '<td colspan="7" style="text-align:right;font-size:12px;padding:6px 8px">Totais:</td>')
    +'<td style="font-size:12px;text-align:right">'+fmtMoeda(valTotal)+'</td>'
    +'<td style="font-size:12px;text-align:right;color:#185FA5">'+fmtMoeda(valViab)+'</td>'
    +'<td colspan="3"></td></tr>'
    +'</tbody></table></div>';
}

function sotRenderTabMateriais(projetoId, saldosInfo){
  if(!sot_materiais_proj.length){
    return '<div style="padding:2rem;text-align:center;color:#aaa">'
      +'Nenhum material cadastrado.<br><br>'
      +'<button class="btn btn-pri" onclick="sotAbrirNovoMaterial(\''+projetoId+'\')">+ Adicionar material</button>'
    +'<button class="btn" onclick="sotImportarMateriais(\''+projetoId+'\')" style="color:#185FA5;border-color:#185FA5">📥 Importar (CSV/Excel)</button>'
      +'</div>';
  }
  var saldosMap = saldosInfo ? saldosInfo.map : {};
  var banner = saldosInfo ? sotBannerSaldoMateriais(saldosInfo.lista) : '';
  // ── Tabela com breakdown igual à aba Reservar ─────────────────────────────
  return banner
    +'<div style="overflow-x:auto">'
    +'<table style="width:100%;border-collapse:collapse;font-size:11px;min-width:1000px">'
    +'<thead>'
    +'<tr style="background:#1a1a18;color:#fff;font-size:10px">'
    +'<th rowspan="2" style="padding:5px 8px;text-align:left;min-width:90px">Cód. SAP</th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:left;min-width:160px">Descrição</th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:center;width:40px">Un</th>'
    +'<th colspan="3" style="padding:4px 8px;text-align:center;border-left:1px solid #333;background:#854F0B">PLANEJADO / ADICIONAIS</th>'
    +'<th colspan="4" style="padding:4px 8px;text-align:center;border-left:1px solid #333;background:#185FA5">PROGRAMADO / RESERVAS</th>'
    +'<th colspan="3" style="padding:4px 8px;text-align:center;border-left:1px solid #333;background:#085041">APLICAÇÃO</th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:center;border-left:1px solid #333;background:#533AB7;min-width:72px">Saldo<br>SAP</th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:center;border-left:1px solid #333;background:#854F0B;width:60px">Dev.<br>Hoje</th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:center;border-left:1px solid #333;width:80px">Ações</th>'
    +'</tr>'
    +'<tr style="background:#222;color:#ddd;font-size:10px">'
    +'<th style="padding:4px 6px;text-align:right;border-left:1px solid #333" title="Quantidade planejada">Plan.</th>'
    +'<th style="padding:4px 6px;text-align:right" title="Adicionais aprovados">Adic.</th>'
    +'<th style="padding:4px 6px;text-align:right;font-weight:700;color:#FFE0A3">Total</th>'
    +'<th style="padding:4px 6px;text-align:right;border-left:1px solid #333;color:#7CB8FF;font-weight:700" title="Quantidade programada (viabilizada)">Prog.</th>'
    +'<th style="padding:4px 6px;text-align:right;border-left:1px solid #333" title="Reservas anteriores">Ant.</th>'
    +'<th style="padding:4px 6px;text-align:right" title="Reservas de hoje">Hoje</th>'
    +'<th style="padding:4px 6px;text-align:right;font-weight:700;color:#B39DFF">Total</th>'
    +'<th style="padding:4px 6px;text-align:right;border-left:1px solid #333" title="Aplicado anteriormente">Ant.</th>'
    +'<th style="padding:4px 6px;text-align:right" title="Aplicado hoje">Hoje</th>'
    +'<th style="padding:4px 6px;text-align:right;font-weight:700;color:#81C995">Total</th>'
    +'</tr></thead><tbody>'
    +sot_materiais_proj.filter(function(m){return m.projeto_id===projetoId;}).map(function(m){
      var un          = escHtml(m.unidade||'UN');
      var prog        = m.qtd_projetada  || 0;
      var adicionado  = m._adicionado    || 0;
      var totalProg   = prog + adicionado;
      var resAnt      = m._res_ant       || 0;
      var resAtual    = m._res_atual     || 0;
      var totalRes    = resAnt + resAtual;
      var aplicAnt    = m._aplic_ant     || 0;
      var aplicAtual  = m._aplic_atual   || 0;
      var totalAplic  = aplicAnt + aplicAtual;
      var viab        = m.qtd_viabilizada || 0;
      var ehSubst     = totalProg===0 && viab>0;
      var devHoje     = m._dev_hoje      || 0;
      var saldo       = totalProg - totalAplic;
      var corSaldo    = saldo > 0 ? '#3B6D11' : saldo < 0 ? '#A32D2D' : '#888';
      var resOk       = totalRes <= totalProg || totalProg===0;
      var aplicOk     = totalAplic <= totalRes || totalRes===0;
      var sal         = saldosMap[m.id];
      var saldoHtml   = '<span style="color:#ccc;font-size:10px">…</span>';
      if(saldosInfo){
        if(!sal || sal.semSaldo){
          saldoHtml = '<span style="color:#888;font-size:9px">Sem SAP</span>';
        } else {
          var corSal = sal.ok ? '#3B6D11' : sal.parcial ? '#854F0B' : '#A32D2D';
          var bgSal  = sal.ok ? '#EAF3DE' : sal.parcial ? '#FEF3E2' : '#FCEBEB';
          saldoHtml = '<div style="background:'+bgSal+';border-radius:4px;padding:2px 4px">'
            +'<div style="font-weight:700;color:'+corSal+'">'+sal.saldoDisp+'</div>'
            +(sal.falta>0?'<div style="font-size:9px;color:#A32D2D">−'+sal.falta+'</div>':'')
            +'<div style="font-size:12px">'+(sal.ok?'✅':sal.parcial?'⚠':'❌')+'</div></div>';
        }
      }
      return '<tr style="border-bottom:.5px solid #f0efe8">'
        +'<td style="padding:6px 8px;font-size:10px;font-family:monospace;color:#888">'+(m.codigo_sap||'—')+'</td>'
        +'<td style="padding:6px 8px;font-weight:500">'+escHtml(m.descricao||'Material')+'</td>'
        +'<td style="padding:6px 8px;text-align:center;color:#888">'+un+'</td>'
        +'<td style="padding:6px 6px;text-align:right;color:#854F0B;border-left:1px solid #f0efe8">'+prog+'</td>'
        +'<td style="padding:6px 6px;text-align:right;color:'+(adicionado>0?'#854F0B':'#ccc')+'">'+( adicionado||'—')+'</td>'
        +'<td style="padding:6px 6px;text-align:right;font-weight:700;color:#854F0B">'+totalProg+'</td>'
        +'<td style="padding:6px 6px;text-align:right;border-left:1px solid #f0efe8;color:'+(viab>0?'#185FA5':'#ccc')+';font-weight:'+(viab>0?'700':'400')+'">'
        +(viab>0?viab+(ehSubst?'<div style="font-size:9px;color:#533AB7">Subst.</div>':'') :'—')+'</td>'
        +'<td style="padding:6px 6px;text-align:right;color:'+(resAnt>0?'#533AB7':'#ccc')+'">'+( resAnt||'—')+'</td>'
        +'<td style="padding:6px 6px;text-align:right;color:'+(resAtual>0?'#533AB7':'#ccc')+'">'+( resAtual||'—')+'</td>'
        +'<td style="padding:6px 6px;text-align:right;font-weight:700;color:'+(resOk?'#533AB7':'#A32D2D')+'">'+totalRes+'</td>'
        +'<td style="padding:6px 6px;text-align:right;color:'+(aplicAnt>0?'#085041':'#ccc')+';border-left:1px solid #f0efe8">'+( aplicAnt||'—')+'</td>'
        +'<td style="padding:6px 6px;text-align:right;color:'+(aplicAtual>0?'#085041':'#ccc')+'">'+( aplicAtual||'—')+'</td>'
        +'<td style="padding:6px 6px;text-align:right;font-weight:700;color:'+(aplicOk?'#085041':'#A32D2D')+'">'+totalAplic+'</td>'
        +'<td style="padding:6px 6px;text-align:center;border-left:1px solid #f0efe8;vertical-align:middle">'+saldoHtml+'</td>'
        +'<td style="padding:6px 6px;text-align:right;color:'+(devHoje>0?'#854F0B':'#ccc')+';border-left:1px solid #f0efe8">'+( devHoje||'—')+'</td>'
        +'<td style="padding:6px 8px;border-left:1px solid #f0efe8"><div style="display:flex;gap:3px">'
        +'<button class="btn btn-sm btn-pri" onclick="sotMenuLancamentoMat(\''+m.id+'\',this)" style="font-size:10px;background:linear-gradient(135deg,#185FA5,#3B6D11);border:none" title="Lançar">▶ Lançar</button>'
        +'<button class="btn btn-sm" onclick="sotEditarMaterial(\''+m.id+'\')" style="font-size:10px" title="Editar">✎</button>'
        +'</div></td></tr>';
    }).join('')
    +'</tbody></table></div>'
    +'<div style="margin-top:.5rem;display:flex;gap:.5rem;align-items:center;flex-wrap:wrap">'
    +'<button class="btn btn-pri" onclick="sotAbrirNovoMaterial(\''+projetoId+'\'  )" style="font-size:12px">+ Adicionar material</button>'
    +'<button class="btn" onclick="sotImportarMateriais(\''+projetoId+'\')" style="font-size:12px;color:#185FA5;border-color:#185FA5">📥 Importar CSV/Excel</button>'
    +'<button class="btn" id="btn-verificar-saldo" style="font-size:12px;color:#533AB7;border-color:#533AB7">📊 Atualizar saldo SAP</button>'
    +'</div>';
}

function sotRenderTabDocumentos(projetoId){
  var docs=window._sotDocs||[];
  if(!docs.length){
    return '<div style="padding:2rem;text-align:center;color:#aaa">'
      +'Nenhum documento anexado.<br><br>'
      +'<button class="btn btn-pri" onclick="sotAbrirAnexarDoc(\''+projetoId+'\')">📎 Anexar documento</button>'
      +'</div>';
  }
  var icone = function(d){
    var ext = (d.arquivo_nome||d.nome||'').split('.').pop().toLowerCase();
    var map = {pdf:'📄',kml:'🗺',kmz:'🗺',dwg:'📐',dxf:'📐',doc:'📝',docx:'📝',xml:'📋'};
    return map[ext] || '📎';
  };
  return '<div style="padding:1rem;display:flex;flex-direction:column;gap:.75rem">'
    +'<div style="display:flex;justify-content:flex-end;margin-bottom:.25rem">'
    +'<button class="btn btn-pri btn-sm" onclick="sotAbrirAnexarDoc(\''+projetoId+'\')">📎 Novo documento</button>'
    +'</div>'
    +docs.map(function(d, i){
      var link = d.arquivo_url||d.url||null;
      var b64  = d.arquivo_base64||null;
      var tipo = (d.arquivo_tipo||'').toLowerCase();
      var isPdf= tipo.includes('pdf')||(d.arquivo_nome||d.nome||'').toLowerCase().endsWith('.pdf');
      var href = link || (b64 ? 'data:'+(d.arquivo_tipo||'application/octet-stream')+';base64,'+b64 : null);
      return '<div style="border:.5px solid #e0dfd8;border-radius:8px;overflow:hidden" id="sot-doc-card-'+i+'">'
        // Header do card
        +'<div style="display:flex;align-items:center;gap:10px;padding:.6rem .75rem;background:#f9f9f7">'
        +'<div style="width:32px;height:32px;background:#E6F1FB;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0">'+icone(d)+'</div>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-weight:600;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+d.nome+'</div>'
        +'<div style="font-size:11px;color:#888">'+d.tipo+' • v'+(d.versao||'1.0')+' • '+fmtD((d.criado_em||'').split('T')[0])
        +(d.arquivo_tamanho?' • '+Math.round(d.arquivo_tamanho/1024)+'KB':'')
        +' • '+(d.enviado_por||'—')+'</div>'
        +(d.observacao?'<div style="font-size:11px;color:#555;margin-top:1px">'+d.observacao+'</div>':'')
        +'</div>'
        // Botões de ação
        +'<div style="display:flex;gap:4px;flex-shrink:0">'
        +(isPdf&&b64
          ? '<button onclick="sotVisualizarDocInline('+i+')" class="btn btn-sm" style="font-size:10px" title="Visualizar">👁 Ver</button>'
          : href
            ? '<a href="'+href+'" '+(link?'target="_blank"':'download="'+(d.arquivo_nome||d.nome||'arquivo')+'"')+' class="btn btn-sm" style="font-size:10px;text-decoration:none">'+(link?'Abrir ↗':'⬇ Baixar')+'</a>'
            : ''
        )
        +'<button onclick="sotExcluirDoc('+i+',\''+projetoId+'\')" class="btn btn-sm" style="font-size:10px;color:#A32D2D;border-color:#A32D2D" title="Excluir">🗑</button>'
        +'</div>'
        +'</div>'
        // Preview inline de PDF base64
        +(isPdf&&b64
          ? '<div id="sot-doc-preview-'+i+'" style="display:none;border-top:.5px solid #e0dfd8">'
            +'<iframe src="data:application/pdf;base64,'+b64+'" style="width:100%;height:500px;border:none;display:block"></iframe>'
            +'</div>'
          : '')
        +'</div>';
    }).join('')
    +'</div>';
}

function sotVisualizarDocInline(idx){
  var el = document.getElementById('sot-doc-preview-'+idx);
  if(!el) return;
  var aberto = el.style.display !== 'none';
  el.style.display = aberto ? 'none' : '';
  // Atualizar texto do botão
  var card = document.getElementById('sot-doc-card-'+idx);
  if(card){
    var btn = card.querySelector('button[onclick*="sotVisualizarDocInline"]');
    if(btn) btn.innerHTML = aberto ? '👁 Ver' : '✕ Fechar';
  }
}

function sotExcluirDoc(idx, projetoId){
  if(!confirm('Excluir este documento?')) return;
  var docs = window._sotDocs||[];
  var d = docs[idx]; if(!d) return;
  if(!DEMO && d.id && !d.id.toString().startsWith('sd')){
    sbDelete('sot_documentos','id=eq.'+d.id);
  }
  docs.splice(idx,1);
  window._sotDocs = docs;
  sotAtualizarAbaAtual(projetoId);
  progShowToast('🗑 Documento excluído');
}

// ── Criar / editar projeto ────────────────────────────────────
function sotAbrirNovoProjeto(){
  _sotProjetoAtual=null;
  if(!contratos.length){
    // Contratos não carregados ainda — tentar carregar
    if(!DEMO){
      sbFetch('contratos',{filters:['status=eq.Ativo'],order:'codigo'}).then(function(res){
        if(res&&res.length) contratos=res;
        sotModalProjeto(null);
      }).catch(function(){ sotModalProjeto(null); });
    } else {
      sotModalProjeto(null);
    }
    return;
  }
  sotModalProjeto(null);
}
function sotAbrirEditarProjeto(id){
  _sotProjetoAtual=id;
  var p=sot_projetos.find(function(x){return x.id===id;});
  if(!p) return;
  // Garantir que contratos e tipos estão carregados antes de abrir o modal
  var loadContratos = (!contratos.length && !DEMO)
    ? sbFetch('contratos',{filters:['status=eq.Ativo'],order:'codigo'}).then(function(r){ if(r&&r.length) contratos=r; }).catch(function(){})
    : Promise.resolve();
  var loadTipos = (!tipos_servico_cad.length && !DEMO)
    ? sbFetch('tipos_servico_cad',{order:'nome'}).then(function(r){ if(r&&r.length) tipos_servico_cad=r; }).catch(function(){})
    : Promise.resolve();
  Promise.all([loadContratos, loadTipos]).then(function(){
    sotModalProjeto(p);
  });
}

