// ── Parser DXF ──────────────────────────────────────────────────────────
// Extrai entidades TEXT, MTEXT, INSERT, POINT e CIRCLE do arquivo DXF
function parseDXF(text){
  var lines = text.split(/\r?\n/);
  var total = lines.length;
  var entities = [];
  var bounds = {minX:Infinity,maxX:-Infinity,minY:Infinity,maxY:-Infinity};
  var layers = {};
  var i = 0;

  // Limpar código MTEXT de formatação AutoCAD
  function cleanMText(s){
    return (s||'')
      .replace(/\\[OBUQH][^;]*;/g,'')           // formatação \B;\O;\U;
      .replace(/\{\\f[^}]+\}/g,'')               // fontes {\\f...}
      .replace(/\{\\[A-Za-z][^}]*\}/g,'')        // outros grupos
      .replace(/\\P/g,' ')                        // quebra de parágrafo
      .replace(/\\~/g,' ')                        // espaço não-quebrável
      .replace(/\\[A-Za-z];/g,'')                 // outros esc
      .replace(/[{}]/g,'')                        // chaves restantes
      .trim();
  }

  // Avançar até a seção ENTITIES
  while(i < total-1){
    if(lines[i].trim()==='0' && lines[i+1] && lines[i+1].trim()==='SECTION'){
      i+=2;
      if(lines[i].trim()==='2' && lines[i+1] && lines[i+1].trim()==='ENTITIES'){ i+=2; break; }
    } else { i++; }
  }

  // Coletar layers da seção TABLES (antes das entities)
  // já passou, não importa — vamos pegar do layer de cada entidade

  // Ler entidades
  while(i < total-1){
    var gc = lines[i]  ? lines[i].trim()  : '';
    var gv = lines[i+1]? lines[i+1].trim(): '';
    i+=2;

    if(gc==='0' && gv==='ENDSEC') break; // fim da seção

    if(gc==='0' && (gv==='TEXT'||gv==='MTEXT'||gv==='ATTDEF'||
                    gv==='INSERT'||gv==='POINT'||gv==='CIRCLE')){
      var ent = {type:gv,x:0,y:0,text:'',text2:'',layer:'0',block:'',radius:0,scale:1,rot:0};
      while(i < total-1){
        var ec = lines[i]  ? lines[i].trim()  : '';
        var ev = lines[i+1]? lines[i+1].trim(): '';
        if(ec==='0') break; // próxima entidade
        i+=2;
        switch(ec){
          case '8':  ent.layer  = ev; if(!layers[ev])layers[ev]=0; layers[ev]++; break;
          case '10': ent.x      = parseFloat(ev)||0; break;
          case '20': ent.y      = parseFloat(ev)||0; break;
          case '11': if(!ent.x2)ent.x2=parseFloat(ev)||0; break;
          case '21': if(!ent.y2)ent.y2=parseFloat(ev)||0; break;
          case '1':  ent.text   = ev; break;
          case '3':  ent.text2 += ev; break; // MTEXT continuação
          case '2':  ent.block  = ev; break; // block name
          case '40': ent.radius = parseFloat(ev)||0; break;
          case '41': ent.scale  = parseFloat(ev)||1; break;
          case '50': ent.rot    = parseFloat(ev)||0; break;
        }
      }
      // Limpar texto MTEXT
      if(ent.type==='MTEXT') ent.text = cleanMText((ent.text2||'')+ent.text);
      else ent.text = ent.text.trim();

      // Atualizar bounding box
      if(isFinite(ent.x)){
        bounds.minX=Math.min(bounds.minX,ent.x); bounds.maxX=Math.max(bounds.maxX,ent.x);
        bounds.minY=Math.min(bounds.minY,ent.y); bounds.maxY=Math.max(bounds.maxY,ent.y);
      }
      entities.push(ent);
    }
  }

  return {entities:entities, layers:layers, bounds:bounds, totalLines:total};
}

// Resumo legível do DXF para enviar à IA
function dxfToPromptText(parsed, nomeArquivo){
  var ents = parsed.entities;
  var bounds = parsed.bounds;

  // Textos com conteúdo relevante
  var texts = ents.filter(function(e){return (e.type==='TEXT'||e.type==='MTEXT'||e.type==='ATTDEF')&&e.text;})
    .map(function(e){
      var nx = isFinite(bounds.maxX-bounds.minX)&&(bounds.maxX-bounds.minX)>0 ? (e.x-bounds.minX)/(bounds.maxX-bounds.minX) : 0.5;
      var ny = isFinite(bounds.maxY-bounds.minY)&&(bounds.maxY-bounds.minY)>0 ? (e.y-bounds.minY)/(bounds.maxY-bounds.minY) : 0.5;
      return {texto:e.text, layer:e.layer, nx:Math.round(nx*100)/100, ny:Math.round(ny*100)/100};
    });

  // Inserções de blocos (pontos de serviço)
  var inserts = ents.filter(function(e){return e.type==='INSERT'&&e.block;})
    .map(function(e){
      var nx = isFinite(bounds.maxX-bounds.minX)&&(bounds.maxX-bounds.minX)>0 ? (e.x-bounds.minX)/(bounds.maxX-bounds.minX) : 0.5;
      var ny = isFinite(bounds.maxY-bounds.minY)&&(bounds.maxY-bounds.minY)>0 ? (e.y-bounds.minY)/(bounds.maxY-bounds.minY) : 0.5;
      return {bloco:e.block, layer:e.layer, nx:Math.round(nx*100)/100, ny:Math.round(ny*100)/100};
    });

  // Layers únicos
  var layerList = Object.keys(parsed.layers).join(', ');

  var out = '=== ARQUIVO DXF: '+nomeArquivo+' ===\n';
  out += 'Layers: '+layerList+'\n';
  out += 'Entidades: '+ents.length+' (textos:'+texts.length+', blocos:'+inserts.length+')\n\n';

  if(texts.length){
    out += '--- TEXTOS E ANOTAÇÕES ---\n';
    texts.forEach(function(t){
      out += '[Layer:'+t.layer+' | pos:'+t.nx+','+t.ny+'] '+t.texto+'\n';
    });
    out += '\n';
  }
  if(inserts.length){
    out += '--- BLOCOS (pontos de serviço) ---\n';
    inserts.slice(0,200).forEach(function(b){
      out += '[Layer:'+b.layer+' | bloco:'+b.bloco+' | pos:'+b.nx+','+b.ny+']\n';
    });
    if(inserts.length>200) out += '... e mais '+(inserts.length-200)+' blocos\n';
  }
  return out;
}

// ── Variável para croqui atual (imagem ou PDF) ──────────────
var _wlImagemDataUrl = null;
var _wlCroquiEhPdf = false;

function _wlArquivoEhPdf(mimeOuSrc, nome){
  var s = String(mimeOuSrc||'');
  var n = String(nome||'');
  return s === 'application/pdf' || s.indexOf('application/pdf') >= 0 || /\.pdf(\?|#|$)/i.test(s) || /\.pdf$/i.test(n);
}

function wlCarregarImagem(file){ wlCarregarCroqui(file); }

function wlCarregarCroqui(file){
  if(!file) return;
  if(!file.type.match(/^image\//) && !_wlArquivoEhPdf(file.type, file.name)){
    progShowToast('⚠ Use PDF, JPG, PNG ou WEBP.'); return;
  }
  var reader = new FileReader();
  reader.onload = function(ev){
    var dataUrl = ev.target.result;
    var ehPdf = _wlArquivoEhPdf(file.type, file.name) || dataUrl.indexOf('data:application/pdf') === 0;
    _wlImagemDataUrl = dataUrl;
    _wlCroquiEhPdf = ehPdf;
    _wlArquivos = [{
      nome: file.name,
      tipo: ehPdf ? 'application/pdf' : (file.type || 'image/jpeg'),
      tamanho: file.size,
      base64: dataUrl.split(',')[1],
      dataUrl: dataUrl,
      ehPdf: ehPdf
    }];
    wlExibirCroqui(dataUrl, ehPdf);
    var btn = document.getElementById('wl-btn-analisar');
    if(btn) btn.style.display = '';
  };
  reader.readAsDataURL(file);
}

function wlRestaurarCroquiProjeto(croquiSrc){
  var ehPdf = _wlArquivoEhPdf(croquiSrc, croquiSrc);
  _wlImagemDataUrl = croquiSrc;
  _wlCroquiEhPdf = ehPdf;
  setTimeout(function(){ wlExibirCroqui(croquiSrc, ehPdf); }, 100);

  function wlRegistrarArquivo(dataUrl, mime, b64, tamanho, nome){
    _wlArquivos = [{
      nome: nome || (ehPdf ? 'croqui_salvo.pdf' : 'croqui_salvo.jpg'),
      tipo: mime,
      tamanho: tamanho || 0,
      base64: b64,
      dataUrl: dataUrl,
      ehPdf: _wlArquivoEhPdf(mime, nome)
    }];
    _wlCroquiEhPdf = _wlArquivos[0].ehPdf;
    var btn = document.getElementById('wl-btn-analisar');
    if(btn) btn.style.display = '';
  }

  if(croquiSrc.indexOf('data:') === 0){
    var parts = croquiSrc.split(',');
    var mime  = (parts[0].match(/:(.*?);/) || [])[1] || (ehPdf ? 'application/pdf' : 'image/jpeg');
    var b64   = parts[1] || '';
    if(b64) setTimeout(function(){ wlRegistrarArquivo(croquiSrc, mime, b64, 0); }, 150);
  } else {
    fetch(croquiSrc).then(function(r){ return r.blob(); }).then(function(blob){
      var reader = new FileReader();
      reader.onload = function(e){
        var dataUrl = e.target.result;
        var parts   = dataUrl.split(',');
        var mime    = blob.type || (parts[0].match(/:(.*?);/) || [])[1] || (ehPdf ? 'application/pdf' : 'image/jpeg');
        var b64     = parts[1] || '';
        wlRegistrarArquivo(dataUrl, mime, b64, blob.size);
      };
      reader.readAsDataURL(blob);
    }).catch(function(){
      console.warn('Não foi possível carregar croqui_url como base64');
    });
  }
}

function wlExibirImagem(src){ wlExibirCroqui(src, false); }

function wlExibirCroqui(src, ehPdf){
  var panel = document.getElementById('wl-croqui-panel');
  var img   = document.getElementById('wl-croqui-img');
  var container = document.getElementById('wl-croqui-container');
  var area  = document.getElementById('wl-upload-area');
  if(!panel || !container) return;

  ehPdf = ehPdf || _wlArquivoEhPdf(src, src);
  _wlCroquiEhPdf = ehPdf;

  var iframeVelho = container.querySelector('iframe.wl-croqui-pdf');
  if(ehPdf){
    if(img){ img.style.display = 'none'; img.removeAttribute('src'); }
    var iframe = iframeVelho;
    if(!iframe){
      iframe = document.createElement('iframe');
      iframe.className = 'wl-croqui-pdf';
      iframe.style.cssText = 'display:block;width:100%;height:380px;border:none;pointer-events:none';
      container.insertBefore(iframe, img || container.firstChild);
    }
    iframe.src = src;
  } else {
    if(iframeVelho) iframeVelho.remove();
    if(img){
      img.style.display = 'block';
      img.src = src;
    }
  }

  panel.style.display = '';
  if(area) area.style.display = 'none';
  if(_wlDados.length) wlRenderMarcadores();
}

function wlTrocarImagem(){
  var panel = document.getElementById('wl-croqui-panel');
  var area  = document.getElementById('wl-upload-area');
  var container = document.getElementById('wl-croqui-container');
  if(panel) panel.style.display = 'none';
  if(area)  area.style.display  = 'block';
  if(container){
    var iframe = container.querySelector('iframe.wl-croqui-pdf');
    if(iframe) iframe.remove();
    var img = document.getElementById('wl-croqui-img');
    if(img){ img.style.display = 'block'; img.removeAttribute('src'); }
  }
  _wlImagemDataUrl = null;
  _wlCroquiEhPdf = false;
  _wlArquivos = [];
  var btn = document.getElementById('wl-btn-analisar');
  if(btn) btn.style.display = 'none';
}

function wlAnalisarIA(){
  if(!_wlArquivos.length){
    progShowToast('⚠ Carregue o croqui (PDF ou imagem) para analisar.'); return;
  }
  var btn = document.getElementById('wl-btn-analisar');
  if(btn){btn.textContent='⏳ Analisando...';btn.disabled=true;}
  wlSetStatus('Enviando croqui para análise...');

  var a = _wlArquivos[0];
  var ehPdf = a.ehPdf || _wlArquivoEhPdf(a.tipo, a.nome);
  var promptWl = 'Você é um especialista em planejamento de redes de distribuição elétrica TMA/MT/BT.\nAnalise este croqui (PDF ou imagem) de WLs (Work Lists / Ordens de Serviço).\n\nEXTRAIA para cada WL identificada:\n- numero: número da WL conforme marcado na imagem\n- tipo: tipo de serviço (ex: Religamento, Poda, MT, BT, Poste, Transformador, etc.)\n- regiao: bairro ou região identificada\n- complexidade: Baixa (simples, 1-2h) | Média (padrão, 3-4h) | Alta (estrutural, 5-6h) | Crítica (complexa, 7-8h+)\n- x: posição horizontal na imagem de 0.0 (esquerda) a 1.0 (direita) — baseado na localização visual da WL\n- y: posição vertical na imagem de 0.0 (topo) a 1.0 (base) — baseado na localização visual da WL\n- materiais: lista de materiais estimados [{"nome":"Poste 11m C200","qtd":1,"unidade":"un"},{"nome":"Cabo XLPE 95mm²","qtd":50,"unidade":"m"}]\n\nRECOMENDE:\n- Número ideal de equipes (cada equipe executa ~4 WLs Médias por turno de 8h; WL Alta = 2 WLs Médias; Crítica = 3)\n- Dias estimados com equipes recomendadas\n- Dias mínimos possíveis e quantas equipes seriam necessárias\n- Justificativa técnica considerando concentração geográfica, complexidade e tipo de serviço\n\nResponda SOMENTE com JSON válido sem markdown:\n{"wls":[{"numero":"1","tipo":"Religamento","regiao":"Centro","complexidade":"Media","x":0.3,"y":0.4,"materiais":[{"nome":"Ramal BT 2x16","qtd":15,"unidade":"m"}]}],"total":42,"equipes_recomendadas":5,"dias_estimados":9,"dias_minimos":4,"equipes_para_minimo":10,"justificativa":"texto"}';
  var contentBlocks = [];
  if(ehPdf){
    contentBlocks.push({type:'document', source:{type:'base64', media_type:'application/pdf', data:a.base64}});
  } else {
    var mime = (a.tipo && a.tipo.includes('image')) ? a.tipo : 'image/jpeg';
    var acceptedMime = ['image/jpeg','image/png','image/gif','image/webp'];
    if(acceptedMime.indexOf(mime) < 0) mime = 'image/jpeg';
    contentBlocks.push({type:'image', source:{type:'base64', media_type:mime, data:a.base64}});
  }
  contentBlocks.push({type:'text', text: promptWl});

  // Tentar proxy Netlify primeiro (produção); fallback direto (desenvolvimento)
  var _wlApiUrl = window.location.hostname === 'localhost' || window.location.protocol === 'file:'
    ? 'https://api.anthropic.com/v1/messages'
    : 'https://cena-proxy.marcos-afe.workers.dev';
  var _wlHeaders = {'Content-Type':'application/json'};
  if(_wlApiUrl.includes('anthropic.com')) _wlHeaders['anthropic-dangerous-direct-browser-access']='true';

  fetch(_wlApiUrl,{
    method:'POST',
    headers:_wlHeaders,
    body:JSON.stringify({
      model:'claude-sonnet-4-5',
      max_tokens:2000,
      messages:[{role:'user',content:contentBlocks}]
    })
  }).then(function(r){
    if(!r.ok) return r.text().then(function(t){ throw new Error('HTTP '+r.status+': '+t.substring(0,200)); });
    return r.json();
  }).then(function(data){
    var text = (data.content||[]).find(function(c){return c.type==='text';})||{};
    var raw = (text.text||'').replace(/```json|```/g,'').trim();
    var parsed;
    try{parsed=JSON.parse(raw);}catch(e){var m=raw.match(/\{[\s\S]*\}/);if(m)parsed=JSON.parse(m[0]);else throw new Error('JSON inválido: '+raw.substring(0,200));}

    _wlDados = (parsed.wls||[]).map(function(w,i){
      // Usar coordenadas da IA se disponíveis e válidas
      var wx = (typeof w.x === 'number' && w.x > 0 && w.x < 1) ? w.x : null;
      var wy = (typeof w.y === 'number' && w.y > 0 && w.y < 1) ? w.y : null;
      // Se IA não forneceu coordenadas válidas, distribuir em grade
      if(wx == null || wy == null){
        var cols = Math.ceil(Math.sqrt(parsed.wls.length));
        wx = Math.round(((i % cols + 0.5) / cols) * 100) / 100;
        wy = Math.round(((Math.floor(i / cols) + 0.5) / Math.ceil(parsed.wls.length / cols)) * 100) / 100;
      }
      return{
        id:i+1, numero:String(w.numero||i+1),
        x: wx, y: wy,
        complexidade: w.complexidade||'Média',
        regiao: w.regiao||'', tipo: w.tipo||'',
        materiais: w.materiais||[],
        equipe:0, bloqueada:false
      };
    });

    var nEq = parsed.equipes_recomendadas || Math.max(1,Math.ceil(_wlDados.length/4));
    _wlNumEquipes = nEq;
    var neq = document.getElementById('wl-num-eq');
    if(neq) neq.value = nEq;

    _wlRecomendacaoIA = {
      justificativa: parsed.justificativa || '',
      equipes_recomendadas: nEq,
      dias_estimados: parsed.dias_estimados || null,
      dias_minimos: parsed.dias_minimos || null,
      equipes_para_minimo: parsed.equipes_para_minimo || null,
      total_wls: _wlDados.length,
      analisado_em: new Date().toISOString()
    };

    wlRenderRecomendacaoIA(_wlRecomendacaoIA, _wlDados.length);

    wlSetStatus(_wlDados.length+' WLs analisadas · Recomendação: '+nEq+' equipes · '+parsed.dias_estimados+' dias');
    wlRenderLista();
    wlDistribuir();
    wlRenderMarcadores();
    if(btn){btn.textContent='✓ Analisado';btn.disabled=false;}
    var bs=document.getElementById('wl-btn-salvar');
    if(bs) bs.style.display='';

    if(_wlProjAtual){
      var planoAuto = sotMontarPlanoExecucao({
        projeto: _wlProjAtual.id,
        estrategia_ia: _wlRecomendacaoIA,
        wls: _wlDados,
        num_equipes: _wlNumEquipes,
        ajustes: {
          num_equipes: _wlNumEquipes,
          dias_previstos: parsed.dias_estimados || null,
          justificativa: '',
          observacoes: ''
        }
      });
      sotSalvarPlanoExecucao(_wlProjAtual.id, planoAuto, true).then(function(ok){
        if(ok) wlSetStatus(_wlDados.length+' WLs · Plano salvo — veja aba Plano de Execução no projeto');
      });
    }
  }).catch(function(e){
    var msg = '⚠ Erro na análise: ' + e.message;
    wlSetStatus(msg);
    progShowToast(msg);
    if(btn){btn.textContent='⚠ Tentar novamente';btn.disabled=false;}
  });
}


function wlClickCroqui(e, imgEl) {
  // Recalcula posição relativa à imagem
  var rect = imgEl.getBoundingClientRect();
  var x = (e.clientX - rect.left) / rect.width;
  var y = (e.clientY - rect.top)  / rect.height;
  // Se há WL selecionada na lista, reposiciona ela; senão seleciona a próxima sem posição
  var target = null;
  if (_wlWLSelecionada) {
    target = _wlDados.find(function(w){ return w.id === _wlWLSelecionada; });
  }
  if (!target) {
    // Selecionar a WL mais próxima do clique
    var minDist = Infinity;
    _wlDados.forEach(function(w) {
      var d = Math.sqrt(Math.pow(w.x - x, 2) + Math.pow(w.y - y, 2));
      if (d < minDist) { minDist = d; target = w; }
    });
  }
  if (target) {
    target.x = Math.round(x * 1000) / 1000;
    target.y = Math.round(y * 1000) / 1000;
    wlRenderMarcadores();
  }
}


function wlRenderLista(){
  var wrap=document.getElementById('wl-lista-wrap');
  if(!wrap) return;
  if(!_wlDados.length){wrap.innerHTML='';return;}
  wrap.innerHTML='<div style="overflow-x:auto"><table style="width:100%;font-size:12px;border-collapse:collapse"><thead><tr style="border-bottom:.5px solid #e0dfd8"><th style="text-align:left;padding:5px 8px">WL</th><th style="padding:5px 8px">Tipo/Serviço</th><th style="padding:5px 8px">Região</th><th style="padding:5px 8px">Complexidade</th><th style="padding:5px 8px">Equipe</th><th style="padding:5px 8px"></th></tr></thead><tbody>'
    +_wlDados.map(function(w){
      return '<tr style="border-bottom:.5px solid #f5f5f3;cursor:pointer" onclick="_wlWLSelecionada='+w.id+';wlRenderMarcadores()" title="Clique para selecionar e reposicionar no croqui">'
        +'<td style="padding:5px 8px;font-weight:600"><span style="background:'+WL_CORES[w.equipe%WL_CORES.length]+';color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:10px">'+w.numero+'</span></td>'
        +'<td style="padding:5px 8px;color:#666;font-size:11px">'+escHtml(w.tipo||'—')+'</td>'
        +'<td style="padding:5px 8px;color:#666">'+escHtml(w.regiao||'—')+'</td>'
        +'<td style="padding:5px 8px"><span style="font-size:11px;color:'+({Baixa:'#3B6D11',Média:'#854F0B',Alta:'#A32D2D',Crítica:'#533AB7'}[w.complexidade]||'#555')+';font-weight:500">'+w.complexidade+'</span></td>'
        +'<td style="padding:5px 8px;font-size:10px;color:#555">'
        +((w.materiais&&w.materiais.length)?w.materiais.map(function(m){return escHtml(m.qtd+' '+m.unidade+' '+m.nome);}).join('<br>'):'<span style="color:#aaa">—</span>')
        +'</td>'
        +'<td style="padding:5px 8px">E'+((w.equipe||0)+1)+'</td>'
        +'<td style="padding:5px 8px"><button class="btn" onclick="wlRemover('+w.id+')" style="font-size:10px;padding:2px 6px;color:#A32D2D;border-color:#F7C1C1">✕</button></td>'
        +'</tr>';
    }).join('')+'</tbody></table></div>';
}

function wlRenderMarcadores(){
  var img     = document.getElementById('wl-croqui-img');
  var layer   = document.getElementById('wl-markers-layer');
  var container = document.getElementById('wl-croqui-container');
  if(!layer) return;

  // Habilitar pointer events no layer para capturar clicks nas bolinhas
  layer.style.pointerEvents = 'auto';

  // Limpar marcadores anteriores
  layer.innerHTML = '';

  _wlDados.forEach(function(w){
    if(w.x == null || w.y == null) return;
    var cor       = WL_CORES[(w.equipe || 0) % WL_CORES.length];
    var selected  = _wlWLSelecionada && _wlWLSelecionada === w.id;
    var size      = selected ? 30 : 24;
    var fontSize  = selected ? 12 : 10;

    var m = document.createElement('div');
    m.className = 'wl-marker';
    m.setAttribute('data-id', w.id);
    m.style.cssText = [
      'position:absolute',
      'width:'  + size + 'px',
      'height:' + size + 'px',
      'border-radius:50%',
      'background:' + cor,
      'color:#fff',
      'font-size:' + fontSize + 'px',
      'font-weight:700',
      'display:flex',
      'align-items:center',
      'justify-content:center',
      'cursor:pointer',
      'border:' + (selected ? '3px solid #fff' : '2px solid rgba(255,255,255,.75)'),
      'box-shadow:0 2px 8px rgba(0,0,0,' + (selected ? '.6' : '.4') + ')',
      'left:calc(' + (w.x * 100) + '% - ' + (size / 2) + 'px)',
      'top:calc('  + (w.y * 100) + '% - ' + (size / 2) + 'px)',
      'z-index:' + (selected ? 20 : 10),
      'transition:all .15s ease',
      'user-select:none',
      'transform:' + (selected ? 'scale(1.15)' : 'scale(1)'),
    ].join(';');
    m.textContent = w.numero;
    m.title = [
      'WL ' + w.numero,
      'Equipe ' + ((w.equipe||0)+1),
      w.tipo || '',
      w.complexidade || '',
      w.regiao || '',
    ].filter(Boolean).join(' · ');

    m.addEventListener('click', function(e){
      e.stopPropagation();
      _wlWLSelecionada = (_wlWLSelecionada === w.id) ? null : w.id;
      wlRenderMarcadores();
      wlRenderLista();
    });

    layer.appendChild(m);
  });

  // Click no container (fora das bolinhas) move a WL selecionada
  if(container && !container._wlBound){
    container._wlBound = true;
    container.addEventListener('click', function(e){
      if(e.target.classList.contains('wl-marker')) return;
      var refEl = _wlCroquiEhPdf ? container : img;
      if(!refEl) return;
      var r = refEl.getBoundingClientRect();
      var x = Math.round(((e.clientX - r.left) / r.width)  * 1000) / 1000;
      var y = Math.round(((e.clientY - r.top)  / r.height) * 1000) / 1000;
      x = Math.max(0.01, Math.min(0.99, x));
      y = Math.max(0.01, Math.min(0.99, y));
      if(_wlWLSelecionada){
        var target = _wlDados.find(function(w){ return w.id === _wlWLSelecionada; });
        if(target){ target.x = x; target.y = y; wlRenderMarcadores(); wlRenderLista(); }
      }
    });
  }
}


function wlDistribuir(){
  var neq=document.getElementById('wl-num-eq');
  _wlNumEquipes=Math.max(1,parseInt((neq&&neq.value)||'4')||4);
  if(!_wlDados.length){progShowToast('⚠ Nenhuma WL para distribuir.');return;}
  var sorted=[..._wlDados].sort(function(a,b){return a.y-b.y||a.x-b.x;});
  var perEq=Math.ceil(sorted.length/_wlNumEquipes);
  sorted.forEach(function(w,i){var orig=_wlDados.find(function(x){return x.id===w.id;});if(orig&&!orig.bloqueada)orig.equipe=Math.floor(i/perEq);});
  wlRenderMarcadores();
  wlRenderLista();
  wlRenderEquipes();
  var bsalvar=document.getElementById('wl-btn-salvar');
  if(bsalvar)bsalvar.style.display='';
  wlSetStatus('Distribuídas '+_wlDados.length+' WLs em '+_wlNumEquipes+' equipes');
  wlRenderMarcadores();
}

function wlRenderEquipes(){
  var wrap=document.getElementById('wl-teams-wrap');
  if(!wrap) return;
  wrap.style.display='';
  var grid='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px">'
    +Array.from({length:_wlNumEquipes},function(_,i){
      var mine=_wlDados.filter(function(w){return w.equipe===i;});
      var nums=mine.map(function(w){return w.numero;}).sort(function(a,b){return Number(a)-Number(b);}).join(', ');
      var regs=[...new Set(mine.map(function(w){return w.regiao;}).filter(Boolean))].join(', ')||'—';
      var peso=mine.reduce(function(s,w){return s+(WL_COMPLEXIDADE_PESO[w.complexidade]||2);},0);
      var horas=mine.reduce(function(s,w){return s+(WL_HORAS_POR_COMPLEXIDADE[w.complexidade]||4);},0);
      var dias=Math.ceil(horas/WL_HORAS_TURNO);
      return '<div style="border-left:3px solid '+WL_CORES[i%WL_CORES.length]+';background:#fff;border-radius:8px;border:.5px solid #e0dfd8;padding:10px 12px">'
        +'<div style="display:flex;justify-content:space-between;margin-bottom:3px">'
        +'<span style="font-size:13px;font-weight:500">Equipe '+(i+1)+'</span>'
        +'<span style="font-size:11px;color:#888">'+mine.length+' WLs</span>'
        +'</div>'
        +'<div style="font-size:11px;color:#888;margin-bottom:3px">'+escHtml(regs)+'</div>'
        +'<div style="font-size:12px;margin-bottom:3px">'+escHtml(nums||'—')+'</div>'
        +'<div style="font-size:11px;color:#185FA5">~'+dias+' dia'+(dias>1?'s':'')+'</div>'
        +'</div>';
    }).join('')+'</div>';
  wrap.innerHTML=grid;
}

function wlEditarWL(id){
  var w=_wlDados.find(function(x){return x.id===id;});if(!w)return;
  var novaEq=prompt('WL '+w.numero+' — Mover para qual equipe? (1-'+_wlNumEquipes+')',w.equipe+1);
  if(novaEq===null)return;
  var n=parseInt(novaEq);
  if(!isNaN(n)&&n>=1&&n<=_wlNumEquipes){w.equipe=n-1;w.bloqueada=true;wlRenderMarcadores();wlRenderLista();wlRenderEquipes();}
}

function wlRemover(id){
  _wlDados=_wlDados.filter(function(w){return w.id!==id;});
  wlRenderMarcadores();wlRenderLista();
}

function wlAbrirAddManual(){
  var n=prompt('Número da WL:');
  if(!n)return;
  var tipo=prompt('Tipo de serviço (ex: Religamento, Poda, Manutenção):','')||'';
  var reg=prompt('Região/Bairro:','')||'';
  var neq=parseInt(prompt('Equipe (1-'+_wlNumEquipes+'):','1'));
  if(isNaN(neq)||neq<1)neq=1;
  _wlDados.push({id:Date.now(),numero:n.trim(),tipo:tipo,x:0.5,y:0.5,complexidade:'Média',regiao:reg,equipe:(neq-1),bloqueada:true});
  wlRenderMarcadores();wlRenderLista();wlRenderEquipes();
  wlSetStatus(_wlDados.length+' WLs');
}

function wlRenderRecomendacaoIA(estrategia, totalWls){
  var recWrap = document.getElementById('wl-recomendacao');
  if(!recWrap || !estrategia) return;
  var nEq = estrategia.equipes_recomendadas || 1;
  var total = totalWls != null ? totalWls : (estrategia.total_wls || 0);
  recWrap.style.display = '';
  recWrap.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin-bottom:10px">'
    +'<div style="text-align:center"><div style="font-size:26px;font-weight:600;color:#3B6D11">'+total+'</div><div style="font-size:11px;color:#666">WLs identificadas</div></div>'
    +'<div style="text-align:center"><div style="font-size:26px;font-weight:600;color:#185FA5">'+nEq+'</div><div style="font-size:11px;color:#666">Equipes recomendadas</div></div>'
    +'<div style="text-align:center"><div style="font-size:26px;font-weight:600;color:#854F0B">'+(estrategia.dias_estimados||'?')+'</div><div style="font-size:11px;color:#666">Dias estimados</div></div>'
    +(estrategia.dias_minimos?'<div style="text-align:center"><div style="font-size:26px;font-weight:600;color:#533AB7">'+estrategia.dias_minimos+'</div><div style="font-size:11px;color:#666">Dias mínimos<br><span style="font-size:10px">'+(estrategia.equipes_para_minimo||'?')+' equipes</span></div></div>':'')
    +'</div>'
    +(estrategia.justificativa?'<div style="font-size:12px;color:#444;padding-top:8px;border-top:.5px solid #92D050">💡 '+escHtml(estrategia.justificativa)+'</div>':'');
}

// ── Plano de Execução (persistência) ─────────────────────────
function sotParsePlanoExecucao(p){
  if(!p) return null;
  if(p.plano_execucao){
    try{
      var plano = typeof p.plano_execucao === 'string' ? JSON.parse(p.plano_execucao) : p.plano_execucao;
      if(plano && plano.wls) return plano;
    }catch(e){}
  }
  if(p.wl_distribuicao){
    try{
      var leg = typeof p.wl_distribuicao === 'string' ? JSON.parse(p.wl_distribuicao) : p.wl_distribuicao;
      if(leg && leg.wls && leg.wls.length){
        return {
          versao: 1,
          criado_em: leg.data || null,
          atualizado_em: leg.data || null,
          estrategia_ia: leg.estrategia_ia || null,
          ajustes: {
            num_equipes: leg.num_equipes || 4,
            dias_previstos: leg.dias_estimados || null,
            justificativa: (leg.ajustes && leg.ajustes.justificativa) || '',
            observacoes: (leg.ajustes && leg.ajustes.observacoes) || ''
          },
          wls: leg.wls,
          num_equipes: leg.num_equipes || 4
        };
      }
    }catch(e2){}
  }
  return null;
}

function sotMontarPlanoExecucao(opts){
  opts = opts || {};
  var p = opts.projeto ? sot_projetos.find(function(x){ return x.id===opts.projeto; }) : null;
  var existente = p ? sotParsePlanoExecucao(p) : null;
  var agora = new Date().toISOString();
  var usuario = usuarioLogado ? usuarioLogado.nome : '';
  var estrategia = opts.estrategia_ia != null ? opts.estrategia_ia : (existente && existente.estrategia_ia) || _wlRecomendacaoIA || null;
  var wls = opts.wls || (existente && existente.wls) || [];
  var numEq = opts.num_equipes != null ? opts.num_equipes : (existente && (existente.num_equipes || existente.ajustes && existente.ajustes.num_equipes)) || _wlNumEquipes || 4;
  var ajustesBase = (existente && existente.ajustes) || {};
  var ajustes = {
    num_equipes: opts.ajustes && opts.ajustes.num_equipes != null ? opts.ajustes.num_equipes : (ajustesBase.num_equipes != null ? ajustesBase.num_equipes : numEq),
    dias_previstos: opts.ajustes && opts.ajustes.dias_previstos != null ? opts.ajustes.dias_previstos : (ajustesBase.dias_previstos != null ? ajustesBase.dias_previstos : (estrategia && estrategia.dias_estimados) || null),
    justificativa: opts.ajustes && opts.ajustes.justificativa != null ? opts.ajustes.justificativa : (ajustesBase.justificativa || ''),
    observacoes: opts.ajustes && opts.ajustes.observacoes != null ? opts.ajustes.observacoes : (ajustesBase.observacoes || '')
  };
  return {
    versao: 1,
    criado_em: (existente && existente.criado_em) || agora,
    atualizado_em: agora,
    atualizado_por: usuario,
    estrategia_ia: estrategia,
    ajustes: ajustes,
    wls: wls,
    num_equipes: numEq
  };
}

function sotSalvarPlanoExecucao(projetoId, plano, silent){
  if(!projetoId || !plano) return Promise.resolve(false);
  var json = JSON.stringify(plano);
  var legado = JSON.stringify({wls: plano.wls, num_equipes: plano.num_equipes, data: plano.atualizado_em, estrategia_ia: plano.estrategia_ia, ajustes: plano.ajustes, dias_estimados: plano.ajustes && plano.ajustes.dias_previstos});
  var p = sot_projetos.find(function(x){ return x.id===projetoId; });
  if(p){
    p.plano_execucao = json;
    p.wl_distribuicao = legado;
  }
  if(DEMO){
    if(!silent) progShowToast('✅ Plano de execução salvo (demo).');
    return Promise.resolve(true);
  }
  return sbUpdate('sot_projetos', {plano_execucao: json, wl_distribuicao: legado}, 'id=eq.'+projetoId)
    .then(function(){
      if(!silent) progShowToast('✅ Plano de execução salvo.');
      if(window._sotTabAtiva==='plano' && _sotProjetoAtual===projetoId){
        sotRenderTabPlano(projetoId);
      }
      return true;
    })
    .catch(function(e){
      console.error('sotSalvarPlanoExecucao', e);
      if(!silent) progShowToast('⚠ Erro ao salvar plano. Execute sql_sot_plano_execucao.sql no Supabase.');
      return false;
    });
}

function sotPlanoContarWls(p){
  var plano = sotParsePlanoExecucao(p);
  return plano && plano.wls ? plano.wls.length : 0;
}

function wlSalvarDistribuicao(){
  if(!_wlProjAtual||!_wlDados.length){progShowToast('⚠ Nenhuma distribuição para salvar.');return;}
  var plano = sotMontarPlanoExecucao({
    projeto: _wlProjAtual.id,
    estrategia_ia: _wlRecomendacaoIA,
    wls: _wlDados,
    num_equipes: _wlNumEquipes
  });
  sotSalvarPlanoExecucao(_wlProjAtual.id, plano).then(function(){
    progShowToast('✅ Plano salvo — '+_wlDados.length+' WLs em '+_wlNumEquipes+' equipes. Veja a aba Plano de Execução.');
    closeModal();
  });
}

function wlSetStatus(msg){var el=document.getElementById('wl-status');if(el)el.textContent=msg;}


function sotCroquiHandleFile(file){
  if(!file) return;
  var tipos = ['application/pdf','image/png','image/jpeg','image/jpg','image/webp'];
  if(tipos.indexOf(file.type) < 0 && !file.name.match(/\.(pdf|png|jpg|jpeg|webp)$/i)){
    progShowToast('⚠ Formato não suportado. Use PDF, PNG ou JPG.'); return;
  }
  var status = document.getElementById('sot-croqui-status');
  var preview = document.getElementById('sot-croqui-preview');
  var drop = document.getElementById('sot-croqui-drop');
  var ehPdf = _sotArquivoEhPdf(file.type, file.name);
  if(status) status.textContent = '⏳ Carregando croqui...';

  var reader = new FileReader();
  reader.onload = function(e){
    var dataUrl = e.target.result;
    _sotCroquiBase64 = dataUrl.split(',')[1];
    _sotCroquiMime = ehPdf ? 'application/pdf' : (file.type || 'image/jpeg');
    var b64El = document.getElementById('sot-croqui-b64');
    var mimeEl = document.getElementById('sot-croqui-mime');
    if(b64El) b64El.value = _sotCroquiBase64;
    if(mimeEl) mimeEl.value = _sotCroquiMime;

    if(status) status.textContent = '⏳ Fazendo upload...';
    var path = 'croquis/'+Date.now()+'_'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');
    sbUpload(file, path).then(function(url){
      if(!url){ if(status) status.textContent = '❌ Falha no upload.'; return; }
      document.getElementById('sot-croqui-url').value = url;
      if(status) status.textContent = '✅ '+file.name;
      if(drop) drop.style.display = 'none';
      if(preview){
        if(ehPdf){
          preview.innerHTML = '<div style="background:#EBF4FD;border:.5px solid #185FA5;border-radius:8px;padding:.75rem 1rem;display:flex;align-items:center;gap:8px;margin-bottom:8px">'
            +'<span style="font-size:20px">📄</span>'
            +'<span style="font-size:12px;font-weight:500;color:#185FA5">'+escHtml(file.name)+'</span>'
            +'<button onclick="sotRemoverCroqui()" style="margin-left:auto;background:none;border:none;cursor:pointer;color:#c00;font-size:14px">✕</button>'
            +'</div>';
        } else {
          preview.innerHTML = '<div style="margin-bottom:8px;position:relative;display:inline-block">'
            +'<img src="'+dataUrl+'" style="max-width:100%;max-height:160px;border:.5px solid #e0dfd8;border-radius:8px;display:block">'
            +'<button onclick="sotRemoverCroqui()" style="position:absolute;top:4px;right:4px;background:rgba(0,0,0,.5);color:#fff;border:none;border-radius:50%;width:22px;height:22px;cursor:pointer;font-size:12px">✕</button>'
            +'</div>';
        }
        preview.style.display = 'block';
        var iaBtn = document.getElementById('sot-croqui-ia-btn');
        if(iaBtn) iaBtn.style.display = '';
        if(status) status.textContent = 'Clique em Preencher com IA para analisar o croqui';
      }
    });
  };
  reader.readAsDataURL(file);
}

function sotRemoverCroqui(){
  var url = document.getElementById('sot-croqui-url');
  var preview = document.getElementById('sot-croqui-preview');
  var drop = document.getElementById('sot-croqui-drop');
  var status = document.getElementById('sot-croqui-status');
  var iaBtn = document.getElementById('sot-croqui-ia-btn');
  _sotCroquiBase64 = null;
  _sotCroquiMime = null;
  var b64El = document.getElementById('sot-croqui-b64');
  var mimeEl = document.getElementById('sot-croqui-mime');
  if(b64El) b64El.value = '';
  if(mimeEl) mimeEl.value = '';
  if(url) url.value = '';
  if(preview){ preview.innerHTML = ''; preview.style.display = 'none'; }
  if(drop) drop.style.display = '';
  if(status) status.textContent = '';
  if(iaBtn) iaBtn.style.display = 'none';
}

