async function sotAnalisarListaIA(){
  var btn  = document.getElementById('sot-lista-ia-btn');
  var st   = document.getElementById('sot-lista-status');
  var b64  = _sotListaBase64 || document.getElementById('sot-lista-b64').value;
  var mime = _sotListaMime   || document.getElementById('sot-lista-mime').value || 'application/pdf';

  if(!b64){ if(st) st.textContent='⚠ Nenhum arquivo carregado.'; return; }
  if(btn){ btn.disabled=true; btn.textContent='⏳ Analisando...'; }
  if(st)  st.textContent = 'Enviando para IA...';

  // Buscar catálogos para contexto
  var matCat  = typeof catalogo_materiais!=='undefined' ? catalogo_materiais : [];
  var tsvList = typeof tipos_servico_cad!=='undefined'  ? tipos_servico_cad  : [];
  var matCodigos = matCat.slice(0,50).map(function(m){ return m.codigo+': '+m.nome; }).join('; ');
  var srvCodigos = tsvList.slice(0,30).map(function(t){ return t.id.slice(0,8)+': '+t.nome; }).join('; ');

  var isPDF = mime==='application/pdf' || mime.includes('pdf');
  var isImg = mime.startsWith('image/');

  // Claude API aceita: PDF (application/pdf) e imagens (image/*)
  // Excel/Word não são suportados — verificar e orientar o usuário
  var contentBlocks = [];
  var _skipPromptBlock = false;
  if(isPDF){
    contentBlocks.push({type:'document', source:{type:'base64',media_type:'application/pdf',data:b64}});
  } else if(isImg){
    // Normalizar mime para tipos aceitos
    var acceptedMime = ['image/jpeg','image/png','image/gif','image/webp'];
    var imgMime = acceptedMime.indexOf(mime) >= 0 ? mime : 'image/jpeg';
    contentBlocks.push({type:'image', source:{type:'base64',media_type:imgMime,data:b64}});
  } else {
    // Excel/Word: converter para texto via SheetJS antes de enviar
    if(st) st.textContent = '⏳ Convertendo Excel para texto...';
    try{
      var workbook = XLSX.read(b64, {type:'base64'});
      var textoFull = '';
      workbook.SheetNames.slice(0, 3).forEach(function(sheetName){  // máx 3 abas
        var ws = workbook.Sheets[sheetName];
        // Converter para array de arrays e filtrar linhas vazias
        var rows = XLSX.utils.sheet_to_json(ws, {header:1, defval:'', blankrows:false});
        var linhasUtil = rows.filter(function(row){
          return row.some(function(cell){ return String(cell||'').trim().length > 0; });
        }).slice(0, 200);  // máx 200 linhas
        textoFull += '=== ' + sheetName + ' ===\n';
        textoFull += linhasUtil.map(function(row){
          return row.slice(0,10).join('\t');  // máx 10 colunas
        }).join('\n');
        textoFull += '\n\n';
      });
      // Para Excel: enviar somente como texto (a IA não precisa de bloco document)
      var _promptTexto = 'Analise esta lista de materiais e serviços de projeto elétrico extraída de planilha Excel.\n\n'
        + 'Catálogo de materiais (código: nome): '+matCodigos+'\n'
        + 'Tipos de serviço (id: nome): '+srvCodigos+'\n\n'
        + 'Conteúdo da planilha:\n'
        + textoFull.slice(0, 4000)
        + '\n\nSepare em MATERIAL ou SERVIÇO. Use códigos do catálogo.\n'
        + 'Extraia: cliente, codigo_projeto, nome_projeto se presentes.\n'
        + 'Retorne SOMENTE JSON válido (sem markdown, sem vírgula final, escape aspas em strings):\n'
    + '{"info":{"cliente":"","codigo_projeto":"","nome_projeto":""},"materiais":[{"codigo":"","nome":"","qtd":0,"unidade":"","obs":""}],"servicos":[{"tipo_id":"","nome":"","qtd":0,"unidade":"","obs":""}]}';
      contentBlocks = [{type:'text', text: _promptTexto}];
      _skipPromptBlock = true;
    } catch(e){
      if(st) st.textContent = '⚠ Erro ao ler Excel. Tente converter para PDF.';
      if(btn){ btn.disabled=false; btn.textContent='🤖 Analisar e Lançar com IA'; }
      console.error('XLSX parse error:', e);
      return;
    }
  }

  if(!_skipPromptBlock) contentBlocks.push({type:'text', text:
    'Analise esta lista de materiais e serviços de um projeto elétrico.\n\n'
    +'Catálogo de materiais disponível (código: nome): '+matCodigos+'\n'
    +'Tipos de serviço disponíveis (id: nome): '+srvCodigos+'\n\n'
    +'Separe cada item em MATERIAL ou SERVIÇO.\n'
    +'Para materiais: tente encontrar o código no catálogo acima. Para serviços: tente encontrar o id acima.\n'
    +'Também extraia dados do cabeçalho se disponíveis: cliente, codigo_projeto, nome_projeto.\n\n'
    +'Retorne SOMENTE JSON válido sem markdown (sem vírgula final, escape aspas em strings):\n'
    +'{"info":{"cliente":"","codigo_projeto":"","nome_projeto":""},'
    +'"materiais":[{"codigo":"M001","nome":"Cabo 35mm²","qtd":100,"unidade":"m","obs":""}],'
    +'"servicos":[{"tipo_id":"tsv-xxx","nome":"Instalação de poste","qtd":5,"unidade":"un","obs":""}]}'
  });

  try{
    var resp = await fetch('https://cena-proxy.marcos-afe.workers.dev',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({model:'claude-haiku-4-5-20251001', max_tokens:4096, messages:[{role:'user',content:contentBlocks}]})
    });
    if(!resp.ok) throw new Error('HTTP '+resp.status);
    var data = await resp.json();
    var parsed = _sotNormalizarListaParsed(_sotParseJsonRespostaIA(_sotExtrairTextoRespostaIA(data)));

    _sotAplicarResultadoLista(parsed, st, btn);

  } catch(e){
    if(st) st.textContent = '⚠ Erro: '+e.message;
    console.error('sotAnalisarListaIA erro:', e);
  } finally {
    if(btn){ btn.disabled=false; btn.textContent='🤖 Analisar e Lançar com IA'; }
  }
}


function sotSalvarProjeto(id){
  var g=function(elId){return (document.getElementById(elId)||{}).value||'';};
  var nome=g('sot-p-nome').trim();
  if(!nome){alert('Informe o nome do projeto.');return;}
  var cliSel=document.getElementById('sot-p-cliente-id');
  var cliId=cliSel?cliSel.value:'';
  var cliObj=clientes.find(function(c){return c.id===cliId;})||{};
  var tsvSel=document.getElementById('sot-p-tipo-id');
  var tsvId=tsvSel?tsvSel.value:'';
  var tsvObj=tipos_servico_cad.find(function(t){return t.id===tsvId;})||{};

  if(!g('sot-p-cont')){alert('Selecione o contrato.');return;}
  if(!cliId){alert('Selecione o cliente.');return;}
  if(!tsvId){alert('Selecione o tipo de serviço.');return;}
  if(!g('sot-p-codigo').trim()){alert('Informe o código do projeto.');return;}

  var payload={
    contrato_id:g('sot-p-cont'),
    cliente_id:cliId,cliente:cliObj.razao_social||'',
    codigo_cliente:g('sot-p-codigo'),nome:nome,
    tipo_servico_id:tsvId,tipo_servico:tsvObj.nome||'',
    local_endereco:g('sot-p-local'),
    cidade:g('sot-p-cidade'),responsavel_interno:g('sot-p-resp'),
    supervisor:g('sot-p-sup'),encarregado_previsto:g('sot-p-enc'),
    data_recebimento:g('sot-p-receb')||null,prazo_previsto:g('sot-p-prazo')||null,
    status:g('sot-p-status')||'Recebido',
    observacoes:g('sot-p-obs'),criado_por:usuarioLogado?usuarioLogado.nome:'',
    croqui_url:g('sot-croqui-url')||null,
  };

  if(id){
    // UPDATE
    var idx=sot_projetos.findIndex(function(x){return x.id===id;});
    var stAnterior=idx>=0?sot_projetos[idx].status:'';
    if(idx>=0) Object.assign(sot_projetos[idx],payload);
    if(!DEMO){
      sbUpdate('sot_projetos',payload,'id=eq.'+id);
      // Registrar mudança de status no histórico
      if(stAnterior&&stAnterior!==payload.status){
        sbInsert('sot_projetos_historico',{
          projeto_id:id,status_anterior:stAnterior,status_novo:payload.status,
          usuario:usuarioLogado?usuarioLogado.nome:'',
          observacao:'Atualização manual'
        });
      }
    }
    closeModal();
    sotAbrirProjeto(id);
  } else {
    // INSERT
    var novo=Object.assign({id:'sp'+Date.now()},payload);
    sot_projetos.unshift(novo);
    if(!DEMO){
      sbInsert('sot_projetos',payload).then(function(res){
        if(res&&res[0]&&res[0].id){
          novo.id=res[0].id;
          sbInsert('sot_projetos_historico',{
            projeto_id:res[0].id,status_anterior:null,status_novo:payload.status,
            usuario:usuarioLogado?usuarioLogado.nome:'',observacao:'Projeto criado'
          });
        }
      });
    }
    closeModal();
    sotRenderMetricas();
    sotRenderProjetos();

    // Lançar materiais e serviços pendentes identificados pela IA
    if(window._sotPendingMateriais || window._sotPendingServicos){
      setTimeout(function(){
        var projetoId = _editandoProjetoId || null;
        // Tentar pegar o id do último projeto criado/editado
        if(!projetoId){
          var last = sot_projetos[sot_projetos.length-1];
          if(last) projetoId = last.id;
        }
        if(projetoId){
          _sotLancarPendentes(projetoId);
        }
        window._sotPendingMateriais = null;
        window._sotPendingServicos  = null;
      }, 500);
    }
  }
}

function _sotLancarPendentes(projetoId){
  var mats = window._sotPendingMateriais || [];
  var srvs = window._sotPendingServicos  || [];
  var lançados = 0;

  mats.forEach(function(m){
    var mat = catalogo_materiais.find(function(c){ return c.codigo===m.codigo; });
    var payload = {
      projeto_id: projetoId,
      catalogo_id: mat ? mat.id : null,
      codigo:      m.codigo || '',
      nome:        m.nome   || (mat ? mat.nome : ''),
      quantidade:  Number(m.qtd||0),
      unidade:     m.unidade || (mat ? mat.unidade : 'UN'),
      status:      'Pendente',
      observacoes: m.obs || 'Lançado pela IA',
    };
    sot_materiais = sot_materiais || [];
    sot_materiais.push(Object.assign({id:'sm'+Date.now()+lançados}, payload));
    if(!DEMO) sbInsert('sot_materiais', payload).catch(function(){});
    lançados++;
  });

  srvs.forEach(function(s){
    var tsv = tipos_servico_cad.find(function(t){ return t.id===s.tipo_id || t.nome===s.nome; });
    var payload = {
      projeto_id:     projetoId,
      tipo_servico_id: tsv ? tsv.id : null,
      nome:            s.nome || (tsv ? tsv.nome : ''),
      quantidade:      Number(s.qtd||0),
      unidade:         s.unidade || 'UN',
      status:          'Pendente',
      observacoes:     s.obs || 'Lançado pela IA',
    };
    sot_atividades = sot_atividades || [];
    sot_atividades.push(Object.assign({id:'sa'+Date.now()+lançados}, payload));
    if(!DEMO) sbInsert('sot_atividades', payload).catch(function(){});
    lançados++;
  });

  if(lançados > 0){
    progShowToast('✅ '+mats.length+' materiais e '+srvs.length+' serviços lançados no projeto');
    sotRenderProjetos();
  }
}

// ── Alterar status ────────────────────────────────────────────
function sotAlterarStatus(projetoId){
  var p=sot_projetos.find(function(x){return x.id===projetoId;});
  if(!p)return;
  // Se projeto PLPT (status na esteira produtiva OU contrato PLPT), usar modal dedicado
  if(PLPT_STATUS_ALL[p.status] || isContratoPLPT(p.contrato_id)){
    plptAlterarStatusEsteira(projetoId);
    return;
  }

  var html='<div class="modal-bg"><div class="modal" style="max-width:380px">'
    +'<h3>Alterar status</h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">'+p.nome+'</div>'
    +'<div style="display:flex;flex-direction:column;gap:5px;margin-bottom:1rem;max-height:320px;overflow-y:auto">'
    +SOT_STATUS_LIST.map(function(s){
      var c=SOT_STATUS_COR[s]||{bg:'#f5f5f3',cor:'#555'};
      var atual=s===p.status;
      return '<button id="sot-st-btn-'+s.replace(/\s/g,'_')+'" style="padding:8px 12px;border-radius:8px;background:'+c.bg+';'
        +'color:'+c.cor+';border:'+(atual?'2px solid '+c.cor:'.5px solid #e0dfd8')+';'
        +'cursor:pointer;text-align:left;font-size:12px;font-weight:'+(atual?'600':'400')+'">'
        +s+(atual?' ✓':'')+'</button>';
    }).join('')
    +'</div>'
    +'<div class="fg"><label style="font-size:11px">Observação</label>'
    +'<input id="sot-st-obs" class="inp" style="width:100%" placeholder="Motivo da mudança..."/></div>'
    +'<div style="display:flex;gap:8px;margin-top:1rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'</div></div></div>';
  setModal(html);

  setTimeout(function(){
    var novoStatus=p.status;
    SOT_STATUS_LIST.forEach(function(s){
      var btn=document.getElementById('sot-st-btn-'+s.replace(/\s/g,'_'));
      if(!btn)return;
      btn.onclick=function(){
        var obs=(document.getElementById('sot-st-obs')||{}).value||'';
        var stAnterior=p.status;
        p.status=s;
        if(!DEMO){
          sbUpdate('sot_projetos',{status:s,atualizado_em:new Date().toISOString()},'id=eq.'+projetoId);
          sbInsert('sot_projetos_historico',{
            projeto_id:projetoId,status_anterior:stAnterior,status_novo:s,
            obs:obs,usuario:usuarioLogado?usuarioLogado.nome:''
          });
        }
        closeModal();
        // Atualizar render no contexto correto (co-* ou SOT)
        if(document.getElementById('co-proj-lista')){
          coRenderProjetos();
        } else {
          sotRenderMetricas();
          sotRenderProjetos();
        }
        if(_sotProjetoAtual===projetoId) sotAbrirProjeto(projetoId);
      };
    });
  },50);
}

// ── Nova atividade ────────────────────────────────────────────
function sotAbrirNovaAtividade(projetoId){
  var proj = sot_projetos.find(function(x){return x.id===projetoId;});
  var contId = proj ? proj.contrato_id : '';
  var servsCont = servicos.filter(function(s){return !contId||s.contrato_id===contId;});

  var html='<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3 style="margin-bottom:.75rem">Nova Atividade</h3>'
    // Busca de serviço
    +'<div style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Serviço do contrato — pesquisar por código ou nome</label>'
    +'<div style="position:relative">'
    +'<input class="inp" id="sot-at-busca-serv" style="width:100%" placeholder="Digite o código ou nome do serviço..." oninput="sotFiltrarServicos(\''+contId+'\')" autocomplete="off"/>'
    +'<div id="sot-at-lista-serv" style="display:none;position:absolute;top:100%;left:0;right:0;background:#fff;border:.5px solid #e0dfd8;border-radius:0 0 8px 8px;max-height:200px;overflow-y:auto;z-index:999;box-shadow:0 4px 12px rgba(0,0,0,.1)"></div>'
    +'</div>'
    +'<div id="sot-at-serv-selecionado" style="display:none;margin-top:5px;padding:6px 10px;background:#EAF3DE;border-radius:6px;font-size:11px;color:#3B6D11;display:flex;justify-content:space-between;align-items:center">'
    +'<span id="sot-at-serv-label"></span>'
    +'<button onclick="sotLimparServico()" style="background:none;border:none;cursor:pointer;color:#A32D2D;font-size:12px">✕</button>'
    +'</div>'
    +'</div>'
    // Campos do form
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin-bottom:.75rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Código</label>'
    +'<input class="inp" id="sot-at-cod" style="width:100%" placeholder="Ex: 5020100055" oninput="sotBuscarPorCodigo(\''+contId+'\')"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Etapa</label>'
    +'<input class="inp" id="sot-at-etapa" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Descrição *</label>'
    +'<input class="inp" id="sot-at-desc" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Unidade</label>'
    +'<input class="inp" id="sot-at-un" value="UN" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Qtd prevista</label>'
    +'<input class="inp" id="sot-at-qtd" type="number" value="1" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Valor unitário (R$)</label>'
    +'<input class="inp" id="sot-at-vu" type="number" value="0" step="0.01" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Ordem</label>'
    +'<input class="inp" id="sot-at-ordem" type="number" value="'+(sot_atividades.length+1)+'" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Observações</label>'
    +'<input class="inp" id="sot-at-obs" style="width:100%"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-salvar-at" style="flex:1">Adicionar</button>'
    +'</div></div></div>';

  setModal(html);

  // Guardar serviços disponíveis para a busca
  window._sotServsDisp = servsCont;
  window._sotServSelecionadoId = null;

  setTimeout(function(){
    // Salvar atividade
    var btn = document.getElementById('sot-salvar-at');
    if(btn) btn.onclick = function(){
      var g = function(id){ return (document.getElementById(id)||{}).value||''; };
      var desc = g('sot-at-desc').trim();
      if(!desc){ alert('Informe a descrição.'); return; }
      var ativ = {
        id:'sa'+Date.now(), projeto_id:projetoId,
        codigo:g('sot-at-cod'), descricao:desc, etapa:g('sot-at-etapa'),
        unidade:g('sot-at-un')||'UN',
        qtd_prevista:parseFloat(g('sot-at-qtd'))||0,
        valor_unitario:parseFloat(g('sot-at-vu'))||0,
        ordem_exec:parseInt(g('sot-at-ordem'))||sot_atividades.length+1,
        observacoes:g('sot-at-obs'), status:'pendente',
        servico_id:window._sotServSelecionadoId||null
      };
      sot_atividades.push(ativ);
      if(!DEMO) sbInsert('sot_atividades',_semId(ativ)).then(function(r){if(r&&r[0]&&r[0].id)ativ.id=r[0].id;});
      closeModal();
      sotAtualizarAbaAtual(projetoId);
    };

    // Fechar dropdown ao clicar fora
    document.addEventListener('click', function fechaLista(e){
      var lista = document.getElementById('sot-at-lista-serv');
      var busca = document.getElementById('sot-at-busca-serv');
      if(lista && busca && !lista.contains(e.target) && e.target!==busca){
        lista.style.display='none';
        document.removeEventListener('click', fechaLista);
      }
    });
  }, 50);
}

// ── Busca de serviço por texto ────────────────────────────────
function sotFiltrarServicos(contId){
  var inp  = document.getElementById('sot-at-busca-serv'); if(!inp) return;
  var lista = document.getElementById('sot-at-lista-serv'); if(!lista) return;
  var termo = inp.value.trim().toLowerCase();
  if(!termo){ lista.style.display='none'; return; }

  var servsBase = window._sotServsDisp || servicos.filter(function(s){ return !contId||s.contrato_id===contId; });
  var filtrados = servsBase.filter(function(s){
    return (s.codigo||'').toLowerCase().indexOf(termo)>=0
        || (s.descricao||'').toLowerCase().indexOf(termo)>=0;
  }).slice(0,20);

  if(!filtrados.length){ lista.style.display='none'; return; }

  lista.innerHTML = filtrados.map(function(s){
    return '<div onclick="sotSelecionarServico(\''+s.id+'\')" '
      +'style="padding:8px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8;font-size:12px" '
      +'onmouseover="this.style.background=\'#f5f5f3\'" onmouseout="this.style.background=\'\'">'
      +'<span style="font-weight:600;color:#185FA5">'+(s.codigo||'')+'</span> '
      +'<span style="color:#555">'+s.descricao+'</span>'
      +'<span style="float:right;color:#888;font-size:11px">'+(s.unidade||'UN')+(s.valor_ups?' · '+fmtR(s.valor_ups):'')+'</span>'
      +'</div>';
  }).join('');
  lista.style.display='';
}

// ── Selecionar serviço do dropdown ────────────────────────────
function sotSelecionarServico(servId){
  var s = (window._sotServsDisp||servicos).find(function(x){ return x.id===servId; });
  if(!s) return;

  window._sotServSelecionadoId = servId;

  // Esconder busca, mostrar badge selecionado
  var lista = document.getElementById('sot-at-lista-serv'); if(lista) lista.style.display='none';
  var inp   = document.getElementById('sot-at-busca-serv'); if(inp) inp.value='';
  var badge = document.getElementById('sot-at-serv-selecionado');
  var label = document.getElementById('sot-at-serv-label');
  if(badge){ badge.style.display='flex'; }
  if(label){ label.textContent = (s.codigo||'')+' — '+s.descricao; }

  // Preencher campos
  var cod  = document.getElementById('sot-at-cod');
  var desc = document.getElementById('sot-at-desc');
  var vu   = document.getElementById('sot-at-vu');
  var un   = document.getElementById('sot-at-un');
  if(cod  && !cod.value)  cod.value  = s.codigo||'';
  if(desc && !desc.value) desc.value = s.descricao||'';
  if(vu) vu.value = s.valor_ups && s.valor_ups>0 ? s.valor_ups : (s.valor_hora||0);
  if(un) un.value = s.unidade||'UN';
}

// ── Limpar serviço selecionado ────────────────────────────────
function sotLimparServico(){
  window._sotServSelecionadoId = null;
  var badge = document.getElementById('sot-at-serv-selecionado');
  if(badge) badge.style.display='none';
  var inp = document.getElementById('sot-at-busca-serv');
  if(inp){ inp.value=''; inp.focus(); }
}

// ── Busca pelo campo Código (preenche serviço se encontrar) ───
function sotBuscarPorCodigo(contId){
  var inp = document.getElementById('sot-at-cod'); if(!inp) return;
  var cod = inp.value.trim().toUpperCase();
  if(cod.length < 3) return; // aguarda digitar pelo menos 3 chars

  var servsBase = window._sotServsDisp || servicos.filter(function(s){ return !contId||s.contrato_id===contId; });
  var encontrado = servsBase.find(function(s){
    return (s.codigo||'').toUpperCase() === cod;
  });
  if(!encontrado) return;

  // Preencher campos automaticamente
  var desc = document.getElementById('sot-at-desc');
  var vu   = document.getElementById('sot-at-vu');
  var un   = document.getElementById('sot-at-un');
  if(desc) desc.value = encontrado.descricao||'';
  if(vu)   vu.value   = encontrado.valor_ups && encontrado.valor_ups>0 ? encontrado.valor_ups : (encontrado.valor_hora||0);
  if(un)   un.value   = encontrado.unidade||'UN';

  // Mostrar badge
  window._sotServSelecionadoId = encontrado.id;
  var badge = document.getElementById('sot-at-serv-selecionado');
  var label = document.getElementById('sot-at-serv-label');
  if(badge) badge.style.display='flex';
  if(label) label.textContent = (encontrado.codigo||'')+' — '+encontrado.descricao;
}

// ── Catálogo Almoxarifado SAP para projeto obras ──────────────
function sotParseContratosIds(m){
  var cids = m.contratos_ids;
  if(typeof cids === 'string'){
    try{ cids = JSON.parse(cids||'[]'); }catch(e){ cids = []; }
  }
  return cids || [];
}

function sotFiltrarMatsContrato(rows, contId){
  return (rows||[]).filter(function(m){
    if(m.status==='Inativo') return false;
    if(!contId) return true;
    var cids = sotParseContratosIds(m);
    return cids.indexOf('todos')>=0 || cids.indexOf(contId)>=0;
  });
}

function sotBuildListaAlmSAP(contId){
  var map = {};
  function add(item){
    var sap = (item.codigo_sap||item.codigo||'').trim();
    var desc = item.descricao || item.material_desc || item.nome || '';
    if(!desc && !sap) return;
    var key = sap ? sap.toUpperCase() : desc.toLowerCase();
    if(map[key]) return;
    map[key] = {
      id: item.id || item.material_id || key,
      codigo_sap: sap,
      descricao: desc,
      unidade: item.unidade || item.unidade_medida || 'UN',
      saldo: item.saldo != null ? item.saldo : (item.saldo_disponivel != null ? item.saldo_disponivel : null)
    };
  }
  sotFiltrarMatsContrato(typeof catalogo_materiais!=='undefined' ? catalogo_materiais : [], contId)
    .forEach(function(m){ add(m); });
  (typeof alm_estoque!=='undefined' ? alm_estoque : []).forEach(function(e){
    if(contId && e.contrato_id && e.contrato_id !== contId && e.contrato_id !== 'geral') return;
    add({id:e.material_id, codigo_sap:e.codigo_sap, descricao:e.material_desc, unidade:e.unidade, saldo:e.saldo});
  });
  (typeof mat_sap!=='undefined' ? mat_sap : []).forEach(function(m){
    if(contId && m.contrato_id && m.contrato_id !== contId) return;
    add(m);
  });
  return Object.keys(map).map(function(k){ return map[k]; })
    .sort(function(a,b){ return (a.descricao||'').localeCompare(b.descricao||''); });
}

function sotCarregarCatalogoAlmSAP(contId, cb){
  function entregar(){
    var lista = sotBuildListaAlmSAP(contId);
    if(!lista.length) lista = sotBuildListaAlmSAP('');
    cb(lista);
  }
  if(DEMO){ entregar(); return; }
  var prom = Promise.resolve();
  if(typeof almCalcularSaldo === 'function' && alm_movimentos.length){
    almCalcularSaldo();
  } else if(!alm_movimentos.length){
    prom = (typeof almCarregarMovimentos === 'function' ? almCarregarMovimentos() : Promise.resolve())
      .then(function(){
        if(typeof almCalcularSaldo === 'function') almCalcularSaldo();
      });
  }
  prom.then(function(){
    if(sotBuildListaAlmSAP(contId).length){ entregar(); return; }
    return Promise.all([
      (!catalogo_materiais.length ? sbFetch('catalogo_materiais',{order:'descricao'}) : Promise.resolve(catalogo_materiais)),
      (!mat_sap.length ? sbFetch('materiais_sap',{order:'descricao'}) : Promise.resolve(mat_sap))
    ]).then(function(res){
      (res[0]||[]).forEach(function(r){
        r.contratos_ids = sotParseContratosIds(r);
        if(!catalogo_materiais.find(function(x){ return x.id === r.id; })) catalogo_materiais.push(r);
      });
      (res[1]||[]).forEach(function(m){
        if(!mat_sap.find(function(x){ return x.id === m.id; })) mat_sap.push(m);
      });
      entregar();
    });
  }).catch(function(){ entregar(); });
}

function sotLabelMatCatalogo(m){
  var lbl = m.descricao || 'Material';
  if(m.codigo_sap) lbl += ' ('+m.codigo_sap+')';
  if(m.saldo != null) lbl += ' · saldo '+m.saldo+' '+(m.unidade||'UN');
  return lbl;
}

function sotRenderOptsMatCatalogo(mats){
  return mats.map(function(m){
    return '<option value="'+m.id+'" data-sap="'+(m.codigo_sap||'')+'" data-un="'+(m.unidade||'UN')+'" data-desc="'+escHtml(m.descricao||'')+'">'
      +escHtml(sotLabelMatCatalogo(m))+'</option>';
  }).join('');
}

// ── Novo material ─────────────────────────────────────────────
function sotAbrirNovoMaterial(projetoId){
  var proj = sot_projetos.find(function(p){return p.id===projetoId;});
  var contId = proj ? proj.contrato_id : (_coContratoAtual||'');

  setModal('<div class="modal-bg"><div class="modal" style="max-width:520px;text-align:center;padding:2rem">'
    +'<div style="color:#888;font-size:13px">⏳ Carregando catálogo Almoxarifado SAP...</div></div></div>');

  sotCarregarCatalogoAlmSAP(contId, function(matsCat){
    window._sotMatCat = matsCat;
    var matOpts = sotRenderOptsMatCatalogo(matsCat);

    var html='<div class="modal-bg"><div class="modal" style="max-width:520px">'
      +'<h3>Adicionar Material ao Projeto</h3>'
      +(matsCat.length
        ?'<div style="background:#f0f7f0;border-radius:8px;padding:.75rem;margin-bottom:1rem">'
          +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:.4rem;color:#3B6D11">📦 Almoxarifado SAP — '+matsCat.length+' material(is)</label>'
          +'<div style="display:flex;gap:6px">'
          +'<input class="inp" id="sot-mat-busca" placeholder="Buscar por nome ou código SAP..." style="flex:1" oninput="sotFiltrarMatCatalogo(this.value)"/>'
          +'<button class="btn" id="sot-mat-limpar" style="font-size:11px">✕ Limpar</button>'
          +'</div>'
          +'<select class="inp" id="sot-mat-cat-sel" style="width:100%;margin-top:6px;height:110px" size="5" onchange="sotPreencherDosCatalogo()">'
          +matOpts
          +'</select>'
          +'<div style="font-size:10px;color:#888;margin-top:3px">Catálogo SAP + saldo em estoque · selecione ou preencha abaixo</div>'
          +'</div>'
        :'<div style="background:#FEF3E2;border-radius:8px;padding:.6rem .75rem;margin-bottom:1rem;font-size:12px;color:#854F0B">'
          +'⚠ Nenhum material no Almoxarifado SAP para este contrato. Cadastre em Almoxarifado → Materiais SAP.'
          +'</div>')
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-bottom:1rem">'
      +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição *</label>'
      +'<input class="inp" id="sot-m-desc" style="width:100%" placeholder="Descrição do material"/></div>'
      +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Código SAP</label>'
      +'<input class="inp" id="sot-m-sap" style="width:100%" placeholder="1234567" oninput="sotAutoFillBySAP(this.value)"/></div>'
      +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Unidade</label>'
      +'<select class="inp" id="sot-m-un" style="width:100%">'
      +['UN','M','M²','KG','PC','CX','CJ','GL','PST','VÃO','H'].map(function(u){return '<option>'+u+'</option>';}).join('')
      +'</select></div>'
      +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Qtd planejada</label>'
      +'<input class="inp" id="sot-m-proj" type="number" style="width:100%" value="0" min="0"/></div>'
      +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Qtd programada (viabilizada)</label>'
      +'<input class="inp" id="sot-m-viab" type="number" style="width:100%" value="0" min="0"/></div>'
      +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação</label>'
      +'<textarea class="inp" id="sot-m-obs" style="width:100%;height:50px"></textarea></div>'
      +'</div>'
      +'<div style="display:flex;gap:8px">'
      +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
      +'<button class="btn btn-pri" id="sot-salvar-mat" style="flex:1">Adicionar</button>'
      +'</div></div></div>';

    setModal(html);

    setTimeout(function(){
      var limpar=document.getElementById('sot-mat-limpar');
      if(limpar) limpar.onclick=function(){
        var bi=document.getElementById('sot-mat-busca'); if(bi) bi.value='';
        sotFiltrarMatCatalogo('');
      };
      var btn=document.getElementById('sot-salvar-mat');
      if(!btn) return;
      btn.onclick=function(){
        var desc=(document.getElementById('sot-m-desc')||{}).value.trim();
        if(!desc){ alert('Informe a descrição.'); return; }
        var mat={
          id:'sm'+Date.now(), projeto_id:projetoId,
          codigo_sap:(document.getElementById('sot-m-sap')||{}).value.trim(),
          descricao:desc,
          unidade:(document.getElementById('sot-m-un')||{}).value||'UN',
          qtd_projetada:parseFloat((document.getElementById('sot-m-proj')||{}).value)||0,
          qtd_viabilizada:parseFloat((document.getElementById('sot-m-viab')||{}).value)||0,
          qtd_requisitada:0,qtd_entregue:0,qtd_aplicada:0,qtd_devolvida:0,qtd_processada_sap:0,
          observacao:(document.getElementById('sot-m-obs')||{}).value||''
        };
        var isDup = sot_materiais_proj.some(function(x){
          if(x.projeto_id !== projetoId) return false;
          if(mat.codigo_sap && x.codigo_sap && mat.codigo_sap.trim()===x.codigo_sap.trim()) return true;
          if(!mat.codigo_sap && mat.descricao && x.descricao && mat.descricao.toLowerCase()===x.descricao.toLowerCase()) return true;
          return false;
        });
        if(isDup){ progShowToast('⚠ Este material já está cadastrado neste projeto.','erro'); return; }
        sot_materiais_proj.push(mat);
        if(!DEMO){
          sbInsert('sot_materiais',{
            projeto_id:mat.projeto_id, codigo_sap:mat.codigo_sap, descricao:mat.descricao, unidade:mat.unidade,
            qtd_projetada:mat.qtd_projetada, qtd_viabilizada:mat.qtd_viabilizada,
            qtd_requisitada:0,qtd_entregue:0,qtd_aplicada:0,qtd_devolvida:0,qtd_processada_sap:0,
            observacao:mat.observacao
          }).then(function(r){ if(r&&r[0]&&r[0].id) mat.id=r[0].id; });
        }
        closeModal();
        sotAtualizarAbaAtual(projetoId);
      };
    },50);
  });
}

function sotFiltrarMatCatalogo(busca){
  var sel=document.getElementById('sot-mat-cat-sel'); if(!sel) return;
  var mats=window._sotMatCat||[];
  var q=(busca||'').toLowerCase();
  var filtrados=mats.filter(function(m){
    return !q || (m.descricao||'').toLowerCase().indexOf(q)>=0 || (m.codigo_sap||'').toLowerCase().indexOf(q)>=0;
  });
  sel.innerHTML=sotRenderOptsMatCatalogo(filtrados);
}



function sotAutoFillEditBySAP(cod){
  if(!cod) return;
  var codUpper = cod.toUpperCase().trim();

  function _fill(mat){
    if(!mat||!mat.descricao) return;
    var desc = document.getElementById('sot-mat-desc');
    var un   = document.getElementById('sot-mat-un');
    if(desc){ desc.value=mat.descricao; desc.style.background='#f0f7f0'; setTimeout(function(){ desc.style.background=''; },1500); }
    if(un && mat.unidade) un.value = mat.unidade;
  }

  var mat = (typeof catalogo_materiais!=='undefined' ? catalogo_materiais : [])
    .find(function(m){ return (m.codigo_sap||'').toUpperCase()===codUpper; });
  if(mat){ _fill(mat); return; }

  var it = (typeof itens_catalogo!=='undefined' ? itens_catalogo : [])
    .find(function(m){ return (m.codigo||'').toUpperCase()===codUpper; });
  if(it){ _fill({descricao:it.nome||it.descricao||'', unidade:it.unidade_medida||it.unidade||'UN'}); return; }

  var mov = (typeof alm_movimentos!=='undefined' ? alm_movimentos : [])
    .find(function(m){ return (m.codigo_sap||'').toUpperCase()===codUpper && m.tipo==='entrada'; });
  if(mov){ _fill({descricao:mov.material_desc||'', unidade:mov.unidade||'UN'}); return; }

  var est = (typeof alm_estoque!=='undefined' ? alm_estoque : [])
    .find(function(e){ return (e.codigo_sap||'').toUpperCase()===codUpper; });
  if(est){ _fill({descricao:est.material_desc||'', unidade:est.unidade||'UN'}); return; }

  // Fetch from DB
  Promise.all([
    sbFetch('itens_catalogo', {filters:['codigo=eq.'+cod]}),
    sbFetch('alm_movimentos', {filters:['codigo_sap=eq.'+cod,'tipo=eq.entrada'], order:'criado_em.desc'})
  ]).then(function(res){
    var itRow=res[0]&&res[0][0], movRow=res[1]&&res[1][0];
    if(itRow) _fill({descricao:itRow.nome||itRow.descricao||'', unidade:itRow.unidade_medida||itRow.unidade||'UN'});
    else if(movRow) _fill({descricao:movRow.material_desc||'', unidade:movRow.unidade||'UN'});
  }).catch(function(){});
}


function sotAutoFillBySAP(cod){
  if(!cod) return;
  var codUpper = cod.toUpperCase().trim();

  function _aplicarFill(mat){
    if(!mat || !mat.descricao) return;
    var desc = document.getElementById('sot-m-desc');
    var un   = document.getElementById('sot-m-un');
    if(desc){ desc.value = mat.descricao; desc.style.background='#f0f7f0'; setTimeout(function(){ desc.style.background=''; },1500); }
    if(un && mat.unidade){
      for(var i=0;i<un.options.length;i++){
        if(un.options[i].value.toUpperCase()===(mat.unidade||'UN').toUpperCase()){
          un.selectedIndex=i; break;
        }
      }
    }
  }

  // 1. catalogo_materiais (local)
  var mat = (typeof catalogo_materiais!=='undefined' ? catalogo_materiais : [])
    .find(function(m){ return (m.codigo_sap||'').toUpperCase()===codUpper; });
  if(mat){ _aplicarFill(mat); return; }

  // 2. itens_catalogo (local)
  var it = (typeof itens_catalogo!=='undefined' ? itens_catalogo : [])
    .find(function(m){ return (m.codigo||'').toUpperCase()===codUpper; });
  if(it){ _aplicarFill({descricao: it.nome||it.descricao||'', unidade: it.unidade_medida||it.unidade||'UN'}); return; }

  // 3. alm_movimentos (local)
  var mov = (typeof alm_movimentos!=='undefined' ? alm_movimentos : [])
    .find(function(m){ return (m.codigo_sap||'').toUpperCase()===codUpper && m.tipo==='entrada'; });
  if(mov){ _aplicarFill({descricao: mov.material_desc||'', unidade: mov.unidade||'UN'}); return; }

  // 4. alm_estoque (local)
  var est = (typeof alm_estoque!=='undefined' ? alm_estoque : [])
    .find(function(e){ return (e.codigo_sap||'').toUpperCase()===codUpper; });
  if(est){ _aplicarFill({descricao: est.material_desc||'', unidade: est.unidade||'UN'}); return; }

  // 5. materiais_sap / mat_sap (local)
  var msap = (typeof mat_sap!=='undefined' ? mat_sap : [])
    .find(function(m){ return (m.codigo_sap||'').toUpperCase()===codUpper; });
  if(msap){ _aplicarFill({descricao: msap.descricao||'', unidade: msap.unidade||'UN'}); return; }

  // 6. Not found locally — fetch from DB
  var desc = document.getElementById('sot-m-desc');
  if(desc) desc.placeholder = 'Buscando...';
  Promise.all([
    sbFetch('itens_catalogo', {filters:['codigo=eq.'+cod]}),
    sbFetch('alm_movimentos', {filters:['codigo_sap=eq.'+cod,'tipo=eq.entrada'], order:'criado_em.desc'})
  ]).then(function(res){
    var itRow  = res[0]&&res[0][0];
    var movRow = res[1]&&res[1][0];
    if(itRow){
      if(itens_catalogo) itens_catalogo.push(itRow);
      _aplicarFill({descricao: itRow.nome||itRow.descricao||'', unidade: itRow.unidade_medida||itRow.unidade||'UN'});
    } else if(movRow){
      if(alm_movimentos) alm_movimentos.push(movRow);
      _aplicarFill({descricao: movRow.material_desc||'', unidade: movRow.unidade||'UN'});
    } else {
      if(desc) desc.placeholder = 'Código não encontrado — preencha manualmente';
    }
  }).catch(function(){
    if(desc) desc.placeholder = 'Erro ao buscar — preencha manualmente';
  });
}


function sotPreencherDosCatalogo(){
  var sel=document.getElementById('sot-mat-cat-sel');if(!sel||!sel.value)return;
  var opt=sel.options[sel.selectedIndex];if(!opt)return;
  var desc=opt.getAttribute('data-desc')||'';
  var sap=opt.getAttribute('data-sap')||'';
  var un=opt.getAttribute('data-un')||'UN';
  var d=document.getElementById('sot-m-desc');if(d)d.value=desc;
  var s=document.getElementById('sot-m-sap');if(s)s.value=sap;
  var u=document.getElementById('sot-m-un');if(u)u.value=un;
}


function sotAbrirAnexarDoc(projetoId){
  var tipoOpts=SOT_TIPOS_DOC.map(function(t){return '<option>'+t+'</option>';}).join('');
  var html='<div class="modal-bg"><div class="modal" style="max-width:460px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">📎 Anexar Documento</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#888">✕</button>'
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:.75rem;margin-bottom:1rem">'

    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Tipo *</label>'
    +'<select class="inp" id="sot-doc-tipo" style="width:100%">'+tipoOpts+'</select></div>'

    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Nome *</label>'
    +'<input class="inp" id="sot-doc-nome" style="width:100%" placeholder="Ex: APR_OS440209803.pdf"/></div>'

    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Versão</label>'
    +'<input class="inp" id="sot-doc-versao" style="width:100%" value="1.0"/></div>'

    // Upload de arquivo
    +'<div>'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Arquivo</label>'
    +'<label id="sot-doc-file-label" style="display:flex;align-items:center;gap:8px;border:.5px dashed #e0dfd8;border-radius:8px;padding:.75rem 1rem;cursor:pointer;background:#fafaf8">'
    +'<span style="font-size:20px">📁</span>'
    +'<span id="sot-doc-file-nome" style="font-size:12px;color:#888">Clique para escolher arquivo</span>'
    +'<span style="font-size:10px;color:#aaa;margin-left:auto">PDF, KML, KMZ, DOC, XML, DWG</span>'
    +'<input type="file" id="sot-doc-file" accept=".pdf,.kml,.kmz,.doc,.docx,.xml,.dwg,.dxf" style="display:none" onchange="sotDocFileChange(this)"/>'
    +'</label>'
    +'</div>'

    // URL alternativa
    +'<div>'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Ou URL externa</label>'
    +'<input class="inp" id="sot-doc-url" style="width:100%" placeholder="https://..."/>'
    +'</div>'

    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Observação</label>'
    +'<textarea class="inp" id="sot-doc-obs" style="width:100%;height:50px"></textarea></div>'
    +'</div>'

    +'<div id="sot-doc-progresso" style="display:none;margin-bottom:.75rem">'
    +'<div style="background:#f5f5f3;border-radius:4px;height:6px">'
    +'<div id="sot-doc-prog-bar" style="background:#185FA5;height:100%;border-radius:4px;width:0%;transition:width .3s"></div>'
    +'</div>'
    +'<div id="sot-doc-prog-txt" style="font-size:11px;color:#888;margin-top:4px;text-align:center">Processando...</div>'
    +'</div>'

    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-salvar-doc" style="flex:1">📎 Anexar</button>'
    +'</div></div></div>';

  setModal(html);

  // Dados do arquivo selecionado
  window._sotDocFile = null;

  setTimeout(function(){
    var btn=document.getElementById('sot-salvar-doc');
    if(!btn) return;
    btn.onclick = function(){
      var g=function(id){return(document.getElementById(id)||{}).value||'';};
      var nome=g('sot-doc-nome').trim();
      if(!nome){alert('Informe o nome do documento.');return;}

      var salvar = function(base64, arquivoNome, arquivoTipo, arquivoTamanho){
        var doc = {
          id:'sd'+Date.now(), projeto_id:projetoId,
          tipo:g('sot-doc-tipo'), nome:nome,
          arquivo_url:g('sot-doc-url')||null,
          arquivo_base64:base64||null,
          arquivo_nome:arquivoNome||null,
          arquivo_tipo:arquivoTipo||null,
          arquivo_tamanho:arquivoTamanho||null,
          versao:g('sot-doc-versao')||'1.0',
          observacao:g('sot-doc-obs'),
          enviado_por:usuarioLogado?usuarioLogado.nome:'',
          criado_em:new Date().toISOString()
        };
        if(!window._sotDocs) window._sotDocs=[];
        window._sotDocs.unshift(doc);
        if(!DEMO) sbInsert('sot_documentos',{
          projeto_id:doc.projeto_id, tipo:doc.tipo, nome:doc.nome,
          url:doc.arquivo_url, versao:doc.versao,
          observacao:doc.observacao, enviado_por:doc.enviado_por,
          arquivo_base64:doc.arquivo_base64,
          arquivo_nome:doc.arquivo_nome,
          arquivo_tipo:doc.arquivo_tipo,
          arquivo_tamanho:doc.arquivo_tamanho
        }).then(function(r){if(r&&r[0]&&r[0].id)doc.id=r[0].id;});
        closeModal();
        progShowToast('✅ Documento anexado');
        sotAtualizarAbaAtual(projetoId);
      };

      // Se tem arquivo selecionado, converter para base64
      if(window._sotDocFile){
        var f = window._sotDocFile;
        // Arquivo grande demais para base64 no Supabase (>1MB)
        if(f.size > 1024*1024){
          if(!confirm('O arquivo tem '+Math.round(f.size/1024)+'KB. Arquivos grandes podem ser lentos. Continuar?')) return;
        }
        var prog = document.getElementById('sot-doc-progresso');
        var bar  = document.getElementById('sot-doc-prog-bar');
        var txt  = document.getElementById('sot-doc-prog-txt');
        if(prog) prog.style.display='';
        if(bar) bar.style.width='30%';
        if(txt) txt.textContent='Lendo arquivo...';
        btn.disabled=true;

        var reader = new FileReader();
        reader.onprogress = function(e){
          if(e.lengthComputable && bar) bar.style.width=Math.round(e.loaded/e.total*80)+'%';
        };
        reader.onload = function(e){
          if(bar) bar.style.width='100%';
          if(txt) txt.textContent='Salvando...';
          var base64 = e.target.result.split(',')[1]; // remover data:mime;base64,
          salvar(base64, f.name, f.type, f.size);
        };
        reader.onerror = function(){
          alert('Erro ao ler o arquivo.');
          btn.disabled=false;
          if(prog) prog.style.display='none';
        };
        reader.readAsDataURL(f);
      } else {
        salvar(null, null, null, null);
      }
    };
  }, 50);
}

function sotDocFileChange(inp){
  var f = inp && inp.files && inp.files[0];
  if(!f) return;
  window._sotDocFile = f;
  var label = document.getElementById('sot-doc-file-nome');
  if(label) label.textContent = f.name + ' (' + Math.round(f.size/1024) + 'KB)';
  // Preencher nome automaticamente se vazio
  var nomeInp = document.getElementById('sot-doc-nome');
  if(nomeInp && !nomeInp.value) nomeInp.value = f.name.replace(/\.[^.]+$/, '');
}

// Alias para edição
function sotEditarAtividade(id){
  var a = sot_atividades.find(function(x){ return x.id===id; });
  if(!a) return;
  var proj = sot_projetos.find(function(x){ return x.id===a.projeto_id; });
  var contId = proj ? proj.contrato_id : '';
  var servsCont = servicos.filter(function(s){ return !contId||s.contrato_id===contId; });

  var html = '<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<h3 style="margin-bottom:.75rem">Editar Atividade</h3>'
    +'<div style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Serviço do contrato — pesquisar por código ou nome</label>'
    +'<div style="position:relative">'
    +'<input class="inp" id="sot-at-busca-serv" style="width:100%" placeholder="Digite para buscar..." oninput="sotFiltrarServicos(\''+contId+'\')" autocomplete="off"/>'
    +'<div id="sot-at-lista-serv" style="display:none;position:absolute;top:100%;left:0;right:0;background:#fff;border:.5px solid #e0dfd8;border-radius:0 0 8px 8px;max-height:200px;overflow-y:auto;z-index:999;box-shadow:0 4px 12px rgba(0,0,0,.1)"></div>'
    +'</div>'
    +'<div id="sot-at-serv-selecionado" style="'+(a.servico_id?'':'display:none;')+'margin-top:5px;padding:6px 10px;background:#EAF3DE;border-radius:6px;font-size:11px;color:#3B6D11;display:flex;justify-content:space-between;align-items:center">'
    +'<span id="sot-at-serv-label">'+(a.servico_id?(function(){ var s=servicos.find(function(x){return x.id===a.servico_id;}); return s?(s.codigo||'')+' — '+s.descricao:'Serviço vinculado';})():'')+'</span>'
    +'<button onclick="sotLimparServico()" style="background:none;border:none;cursor:pointer;color:#A32D2D;font-size:12px">✕</button>'
    +'</div></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin-bottom:.75rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Código</label>'
    +'<input class="inp" id="sot-at-cod" value="'+(a.codigo||'')+'" style="width:100%" oninput="sotBuscarPorCodigo(\''+contId+'\')"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Etapa</label>'
    +'<input class="inp" id="sot-at-etapa" value="'+(a.etapa||'')+'" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Descrição *</label>'
    +'<input class="inp" id="sot-at-desc" value="'+(a.descricao||'')+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Unidade</label>'
    +'<input class="inp" id="sot-at-un" value="'+(a.unidade||'UN')+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Qtd prevista</label>'
    +'<input class="inp" id="sot-at-qtd" type="number" value="'+(a.qtd_prevista||0)+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Valor unitário (R$)</label>'
    +'<input class="inp" id="sot-at-vu" type="number" value="'+(a.valor_unitario||0)+'" step="0.01" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Ordem</label>'
    +'<input class="inp" id="sot-at-ordem" type="number" value="'+(a.ordem_exec||1)+'" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Observações</label>'
    +'<input class="inp" id="sot-at-obs" value="'+(a.observacoes||'')+'" style="width:100%"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn" id="sot-excluir-at" style="flex:1;color:#A32D2D;border-color:#A32D2D">🗑 Excluir</button>'
    +'<button class="btn btn-pri" id="sot-salvar-at" style="flex:2">Salvar alterações</button>'
    +'</div></div></div>';

  setModal(html);
  window._sotServsDisp = servsCont;
  window._sotServSelecionadoId = a.servico_id || null;

  setTimeout(function(){
    // Salvar
    var btnSalvar = document.getElementById('sot-salvar-at');
    if(btnSalvar) btnSalvar.onclick = function(){
      var g = function(id){ return (document.getElementById(id)||{}).value||''; };
      var desc = g('sot-at-desc').trim();
      if(!desc){ alert('Informe a descrição.'); return; }
      a.codigo        = g('sot-at-cod');
      a.descricao     = desc;
      a.etapa         = g('sot-at-etapa');
      a.unidade       = g('sot-at-un')||'UN';
      a.qtd_prevista  = parseFloat(g('sot-at-qtd'))||0;
      a.valor_unitario= parseFloat(g('sot-at-vu'))||0;
      a.ordem_exec    = parseInt(g('sot-at-ordem'))||1;
      a.observacoes   = g('sot-at-obs');
      a.servico_id    = window._sotServSelecionadoId||null;
      if(!DEMO) sbUpdate('sot_atividades',{
        codigo:a.codigo,descricao:a.descricao,etapa:a.etapa,
        unidade:a.unidade,qtd_prevista:a.qtd_prevista,valor_unitario:a.valor_unitario,
        ordem_exec:a.ordem_exec,observacoes:a.observacoes,servico_id:a.servico_id
      },'id=eq.'+id);
      closeModal();
      sotAtualizarAbaAtual(a.projeto_id);
    };

    // Excluir
    var btnExcluir = document.getElementById('sot-excluir-at');
    if(btnExcluir) btnExcluir.onclick = function(){
      if(!confirm('Excluir a atividade "'+a.descricao+'"? Esta ação não pode ser desfeita.')) return;
      sot_atividades = sot_atividades.filter(function(x){ return x.id!==id; });
      if(!DEMO) sbDelete('sot_atividades','id=eq.'+id);
      closeModal();
      sotAtualizarAbaAtual(a.projeto_id);
    };
  },50);
}

// ── Menu dropdown de lançamento ───────────────────────────────

// ── Menu de Lançamento de Materiais ──────────────────────────────────────────
function sotMenuLancamentoMat(id, btn){
  // Remove any stale menus (modal might have closed without menu cleanup)
  var old = document.getElementById('sot-menu-lanc-mat');
  if(old){
    // If menu exists AND button is the same, toggle off
    if(old.dataset.forId === id){ old.remove(); return; }
    // Otherwise remove stale and show new
    old.remove();
  }

  var menu = document.createElement('div');
  menu.id = 'sot-menu-lanc-mat';
  menu.dataset.forId = id;
  menu.style.cssText = 'position:fixed;background:#fff;border:.5px solid #e0dfd8;border-radius:8px;'
    +'box-shadow:0 4px 16px rgba(0,0,0,.15);z-index:9999;min-width:200px;overflow:hidden';

  var rect = btn.getBoundingClientRect();
  menu.style.top  = (rect.bottom+4)+'px';
  menu.style.left = rect.left+'px';

  menu.innerHTML =
    '<div style="padding:4px 0">'
    +'<button onclick="sotMenuLancamentoMat(\''+id+'\');sotLancarViabilidadeMaterial(\''+id+'\')" '
    +'style="display:flex;align-items:center;gap:8px;width:100%;padding:8px 14px;border:none;background:transparent;cursor:pointer;font-size:12px;color:#185FA5;text-align:left" '
    +'onmouseover="this.style.background=\'#f0f5ff\'" onmouseout="this.style.background=\'\'"> '
    +'<span>📋</span><span><b>Lançar Viabilizado</b><br><span style="font-size:10px;color:#888">Qtd aprovada/viabilizada</span></span>'
    +'</button>'
    +'<div style="border-top:.5px solid #f0efe8"></div>'
    +'<button onclick="sotMenuLancamentoMat(\''+id+'\');sotLancarAplicacaoMaterial(\''+id+'\')" '
    +'style="display:flex;align-items:center;gap:8px;width:100%;padding:8px 14px;border:none;background:transparent;cursor:pointer;font-size:12px;color:#3B6D11;text-align:left" '
    +'onmouseover="this.style.background=\'#f0fff4\'" onmouseout="this.style.background=\'\'"> '
    +'<span>⚡</span><span><b>Lançar Aplicado</b><br><span style="font-size:10px;color:#888">Qtd efetivamente aplicada</span></span>'
    +'</button>'
    +'</div>';

  document.body.appendChild(menu);
  menu.dataset.ts = Date.now();
  setTimeout(function(){
    document.addEventListener('click', function fechar(e){
      var m = document.getElementById('sot-menu-lanc-mat');
      if(!m){ document.removeEventListener('click',fechar); return; }
      if(Date.now() - parseInt(m.dataset.ts||0) < 200) return;
      if(!m.contains(e.target)){ m.remove(); document.removeEventListener('click',fechar); }
    });
  },50);
}

function sotLancarViabilidadeMaterial(id){
  var m = sot_materiais_proj.find(function(x){ return x.id===id; });
  if(!m){
    // Try to find by position if ID changed after re-render
    progShowToast('⚠ Recarregando dados...','erro');
    return;
  }

  var html = '<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.25rem">📋 Lançar Viabilizado</h3>'
    +'<div style="font-size:12px;font-weight:500;color:#555;margin-bottom:.75rem">'+(m.codigo_sap?m.codigo_sap+' — ':'')+escHtml(m.descricao)+'</div>'
    +'<div style="background:#f5f5f3;border-radius:8px;padding:.6rem .75rem;margin-bottom:.75rem;display:grid;grid-template-columns:repeat(3,1fr);gap:4px;text-align:center">'
    +'<div><div style="font-size:10px;color:#888">Programado</div><div style="font-weight:600">'+(m.qtd_projetada||0)+' '+(m.unidade||'UN')+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Já viabilizado</div><div style="font-weight:600;color:#185FA5">'+(m.qtd_viabilizada||0)+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Aplicado</div><div style="font-weight:600;color:#3B6D11">'+(m.qtd_aplicada||0)+'</div></div>'
    +'</div>'
    +'<label style="font-size:12px;font-weight:500;display:block;margin-bottom:4px">Quantidade a viabilizar</label>'
    +'<input class="inp" id="sot-mat-viab-qtd" type="number" step="0.01" min="0" style="width:100%;margin-bottom:.75rem" placeholder="0" />'
    +'<div style="font-size:11px;color:#888;margin-bottom:.75rem">Pode ser maior ou menor que o programado.</div>'
    +'<div style="display:flex;gap:.5rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-mat-viab-salvar" style="flex:2">✅ Confirmar</button>'
    +'</div></div></div>';

  setModal(html);
  setTimeout(function(){
    var inp = document.getElementById('sot-mat-viab-qtd');
    var btn = document.getElementById('sot-mat-viab-salvar');
    if(inp) inp.focus();
    if(btn) btn.onclick = function(){
      var qtd = parseFloat((document.getElementById('sot-mat-viab-qtd')||{}).value)||0;
      if(qtd<=0){ progShowToast('⚠ Informe uma quantidade maior que zero.','erro'); return; }
      m.qtd_viabilizada = qtd; // substitui (não acumula)
      if(!DEMO){
        sbUpdate('sot_materiais',{qtd_viabilizada:m.qtd_viabilizada},'id=eq.'+id)
          .then(function(ok){
            if(ok) progShowToast('✅ Viabilizado: '+qtd+' '+(m.unidade||'UN'));
            else progShowToast('⚠ Erro ao salvar — verifique o console.','erro');
          });
      }
      var menuMat = document.getElementById('sot-menu-lanc-mat');
      if(menuMat) menuMat.remove();
      closeModal();
      sotAtualizarAbaAtual(m.projeto_id);
    };
  },50);
}

function sotLancarAplicacaoMaterial(id){
  var m = sot_materiais_proj.find(function(x){ return x.id===id; });
  if(!m) return;

  var saldo = (m.qtd_viabilizada||0) - (m.qtd_aplicada||0);

  var html = '<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.25rem">⚡ Lançar Aplicado</h3>'
    +'<div style="font-size:12px;font-weight:500;color:#555;margin-bottom:.75rem">'+(m.codigo_sap?m.codigo_sap+' — ':'')+escHtml(m.descricao)+'</div>'
    +'<div style="background:#f5f5f3;border-radius:8px;padding:.6rem .75rem;margin-bottom:.75rem;display:grid;grid-template-columns:repeat(3,1fr);gap:4px;text-align:center">'
    +'<div><div style="font-size:10px;color:#888">Viabilizado</div><div style="font-weight:600;color:#185FA5">'+(m.qtd_viabilizada||0)+' '+(m.unidade||'UN')+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Já aplicado</div><div style="font-weight:600;color:#3B6D11">'+(m.qtd_aplicada||0)+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Saldo</div><div style="font-weight:600;color:'+(saldo>=0?'#085041':'#A32D2D')+'">'+saldo+'</div></div>'
    +'</div>'
    +'<label style="font-size:12px;font-weight:500;display:block;margin-bottom:4px">Quantidade aplicada</label>'
    +'<input class="inp" id="sot-mat-aplic-qtd" type="number" step="0.01" min="0" style="width:100%;margin-bottom:.75rem" placeholder="0" />'
    +'<div style="display:flex;gap:.5rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-mat-aplic-salvar" style="flex:2;background:#3B6D11;border-color:#3B6D11">⚡ Confirmar</button>'
    +'</div></div></div>';

  setModal(html);
  setTimeout(function(){
    var inp = document.getElementById('sot-mat-aplic-qtd');
    var btn = document.getElementById('sot-mat-aplic-salvar');
    if(inp) inp.focus();
    if(btn) btn.onclick = function(){
      var qtd = parseFloat((document.getElementById('sot-mat-aplic-qtd')||{}).value)||0;
      if(qtd<=0){ progShowToast('⚠ Informe uma quantidade maior que zero.','erro'); return; }
      m.qtd_aplicada = (m.qtd_aplicada||0) + qtd;
      if(!DEMO){
        sbUpdate('sot_materiais',{qtd_aplicada:m.qtd_aplicada},'id=eq.'+id)
          .then(function(ok){
            if(ok) progShowToast('✅ Aplicado: '+qtd+' '+(m.unidade||'UN'));
            else progShowToast('⚠ Erro ao salvar — verifique o console.','erro');
          });
      }
      closeModal();
      sotAtualizarAbaAtual(m.projeto_id);
    };
  },50);
}


function sotMenuLancamento(id, btn){
  // Remove stale menu — if for same id, toggle off; otherwise replace
  var old = document.getElementById('sot-menu-lanc');
  if(old){
    if(old.dataset.forId === id){ old.remove(); return; }
    old.remove();
  }

  var menu = document.createElement('div');
  menu.id = 'sot-menu-lanc';
  menu.dataset.forId = id;
  menu.style.cssText = 'position:fixed;background:#fff;border:.5px solid #e0dfd8;border-radius:8px;'
    +'box-shadow:0 4px 16px rgba(0,0,0,.15);z-index:9999;min-width:180px;overflow:hidden';

  var rect = btn.getBoundingClientRect();
  menu.style.top  = (rect.bottom+4)+'px';
  menu.style.left = rect.left+'px';

  menu.innerHTML =
    '<div style="padding:4px 0">'
    +'<button onclick="sotMenuLancamento(\''+id+'\');sotLancarViabilidadeAtividade(\''+id+'\')" '
    +'style="display:flex;align-items:center;gap:8px;width:100%;padding:8px 14px;border:none;background:transparent;cursor:pointer;font-size:12px;color:#185FA5;text-align:left" '
    +'onmouseover="this.style.background=\'#f0f5ff\'" onmouseout="this.style.background=\'\'">'
    +'<span>📋</span><span><b>Lançar Viabilizado</b><br><span style="font-size:10px;color:#888">Qtd aprovada/viabilizada</span></span>'
    +'</button>'
    +'<div style="border-top:.5px solid #f0efe8"></div>'
    +'<button onclick="sotMenuLancamento(\''+id+'\');sotLancarExecucaoAtividade(\''+id+'\')" '
    +'style="display:flex;align-items:center;gap:8px;width:100%;padding:8px 14px;border:none;background:transparent;cursor:pointer;font-size:12px;color:#3B6D11;text-align:left" '
    +'onmouseover="this.style.background=\'#f0fff4\'" onmouseout="this.style.background=\'\'">'
    +'<span>⚡</span><span><b>Lançar Executado</b><br><span style="font-size:10px;color:#888">Qtd efetivamente executada</span></span>'
    +'</button>'
    +'</div>';

  document.body.appendChild(menu);

  // Fechar ao clicar fora — marca timestamp para evitar fechar menu recém-aberto
  menu.dataset.ts = Date.now();
  setTimeout(function(){
    document.addEventListener('click', function fechar(e){
      var m = document.getElementById('sot-menu-lanc');
      if(!m){ document.removeEventListener('click',fechar); return; }
      // Ignorar cliques no primeiro 200ms (evita fechar imediatamente)
      if(Date.now() - parseInt(m.dataset.ts||0) < 200) return;
      if(!m.contains(e.target)){ m.remove(); document.removeEventListener('click',fechar); }
    });
  },50);
}

// ── Lançamento de atividades pelo campo (Diário de Bordo) ─────
var _dbLancamentos = []; // lançamentos do turno atual

function dbMostrarLancamentos(){
  var wrap = document.getElementById('db-lancamentos-wrap');
  if(wrap) wrap.style.display = '';
  dbRenderLancamentos();
}

function dbRenderLancamentos(){
  var el = document.getElementById('db-lancamentos-lista');
  if(!el) return;
  if(!_dbLancamentos.length){
    el.innerHTML='<div style="color:#aaa;font-size:12px;text-align:center">Nenhum lançamento hoje</div>';
    return;
  }
  el.innerHTML = _dbLancamentos.map(function(l,i){
    var cor = l.tipo==='executado'?'#3B6D11':'#185FA5';
    var bg  = l.tipo==='executado'?'#EAF3DE':'#E6F1FB';
    return '<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:.5px solid #f0efe8">'
      +'<span style="background:'+bg+';color:'+cor+';padding:2px 7px;border-radius:20px;font-size:10px;font-weight:600;flex-shrink:0">'+(l.tipo==='executado'?'⚡ Exec.':'📋 Viab.')+'</span>'
      +'<span style="font-family:monospace;font-size:11px;color:#185FA5;flex-shrink:0">'+l.codigo+'</span>'
      +'<span style="font-size:12px;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+l.descricao+'</span>'
      +'<span style="font-size:12px;font-weight:600;flex-shrink:0">'+l.qtd+' '+l.unidade+'</span>'
      +'<button onclick="_dbLancamentos.splice('+i+',1);dbRenderLancamentos()" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:14px;flex-shrink:0">✕</button>'
      +'</div>';
  }).join('');
}

function dbAbrirLancamentoAtividades(){
  // Buscar projeto vinculado à equipe/ordem atual
  var ordemAtual = _dbSessao && _dbSessao.ordem_id;
  var projetoId  = _dbSessao && _dbSessao.projeto_id;
  var servsCont  = servicos; // todos os serviços (sem filtro de contrato pois campo não sabe)

  var html = '<div class="modal-bg"><div class="modal" style="max-width:500px">'
    +'<h3 style="margin-bottom:.25rem">⚡ Lançar Atividade do Campo</h3>'
    +'<div style="font-size:11px;color:#888;margin-bottom:.75rem">Lançamento será enviado para validação da área técnica</div>'

    // Tipo
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-bottom:.75rem">'
    +'<button id="db-btn-viab" onclick="dbSelTipoLanc(\'viabilizado\')" '
    +'style="padding:10px;border:2px solid #185FA5;border-radius:8px;background:#E6F1FB;color:#185FA5;font-weight:600;cursor:pointer;font-size:12px">📋 Viabilizado</button>'
    +'<button id="db-btn-exec" onclick="dbSelTipoLanc(\'executado\')" '
    +'style="padding:10px;border:2px dashed #3B6D11;border-radius:8px;background:#fff;color:#3B6D11;font-weight:600;cursor:pointer;font-size:12px">⚡ Executado</button>'
    +'</div>'
    +'<input type="hidden" id="db-lanc-tipo" value="viabilizado"/>'

    // Busca de serviço
    +'<div style="margin-bottom:.6rem">'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Serviço — buscar por código ou nome</label>'
    +'<div style="position:relative">'
    +'<input class="inp" id="db-lanc-busca" style="width:100%" placeholder="Digite código ou nome..." oninput="dbFiltrarServsLanc()" autocomplete="off"/>'
    +'<div id="db-lanc-lista-serv" style="display:none;position:absolute;top:100%;left:0;right:0;background:#fff;border:.5px solid #e0dfd8;border-radius:0 0 8px 8px;max-height:180px;overflow-y:auto;z-index:999;box-shadow:0 4px 12px rgba(0,0,0,.1)"></div>'
    +'</div>'
    +'<div id="db-lanc-serv-badge" style="display:none;margin-top:4px;padding:5px 10px;background:#EAF3DE;border-radius:6px;font-size:11px;color:#3B6D11;display:flex;justify-content:space-between">'
    +'<span id="db-lanc-serv-label"></span>'
    +'<button onclick="dbLimparServLanc()" style="background:none;border:none;color:#A32D2D;cursor:pointer">✕</button>'
    +'</div>'
    +'</div>'
    +'<input type="hidden" id="db-lanc-servid"/>'

    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-bottom:.75rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Código</label>'
    +'<input class="inp" id="db-lanc-cod" style="width:100%" oninput="dbBuscarCodLanc()"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:2px">Quantidade *</label>'
    +'<input class="inp" id="db-lanc-qtd" type="number" min="0" step="0.01" value="1" style="width:100%;font-size:16px;font-weight:600"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Descrição</label>'
    +'<input class="inp" id="db-lanc-desc" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Unidade</label>'
    +'<input class="inp" id="db-lanc-un" value="UN" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Observação</label>'
    +'<input class="inp" id="db-lanc-obs" style="width:100%" placeholder="Opcional..."/></div>'
    +'</div>'

    // Importar lista
    +'<details style="margin-bottom:.75rem">'
    +'<summary style="cursor:pointer;font-size:12px;font-weight:600;color:#185FA5;padding:4px 0">📥 Importar lista (vários de uma vez)</summary>'
    +'<div style="margin-top:.5rem">'
    +'<div style="font-size:11px;color:#888;margin-bottom:4px">Formato: CÓDIGO ; QUANTIDADE (uma por linha, ou cole do Excel)</div>'
    +'<textarea id="db-lanc-lista" class="inp" style="width:100%;height:80px;font-family:monospace;font-size:11px;resize:vertical" placeholder="5020100055 ; 3\n5024000068 ; 1"></textarea>'
    +'</div>'
    +'</details>'

    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="dbConfirmarLancamento()" style="flex:2">✅ Adicionar lançamento</button>'
    +'</div></div></div>';

  setModal(html);
  setTimeout(function(){ var i=document.getElementById('db-lanc-busca'); if(i)i.focus(); },100);
}

function dbSelTipoLanc(tipo){
  document.getElementById('db-lanc-tipo').value = tipo;
  var bv=document.getElementById('db-btn-viab');
  var be=document.getElementById('db-btn-exec');
  if(tipo==='viabilizado'){
    bv.style.background='#E6F1FB'; bv.style.border='2px solid #185FA5';
    be.style.background='#fff'; be.style.border='2px dashed #3B6D11';
  } else {
    be.style.background='#EAF3DE'; be.style.border='2px solid #3B6D11';
    bv.style.background='#fff'; bv.style.border='2px dashed #185FA5';
  }
}

function dbFiltrarServsLanc(){
  var inp  = document.getElementById('db-lanc-busca'); if(!inp)return;
  var lista= document.getElementById('db-lanc-lista-serv'); if(!lista)return;
  var q    = inp.value.trim().toLowerCase();
  if(!q){ lista.style.display='none'; return; }
  var res  = servicos.filter(function(s){
    return (s.codigo||'').toLowerCase().indexOf(q)>=0||(s.descricao||'').toLowerCase().indexOf(q)>=0;
  }).slice(0,15);
  if(!res.length){ lista.style.display='none'; return; }
  lista.innerHTML = res.map(function(s){
    return '<div onclick="dbSelecionarServLanc(\''+s.id+'\')" '
      +'style="padding:7px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8;font-size:12px" '
      +'onmouseover="this.style.background=\'#f5f5f3\'" onmouseout="this.style.background=\'\'">'
      +'<span style="font-weight:600;color:#185FA5">'+(s.codigo||'')+'</span> '
      +'<span>'+s.descricao+'</span>'
      +'<span style="float:right;font-size:10px;color:#888">'+(s.unidade||'UN')+'</span>'
      +'</div>';
  }).join('');
  lista.style.display='';
}

function dbSelecionarServLanc(id){
  var s = servicos.find(function(x){return x.id===id;});
  if(!s) return;
  var lista = document.getElementById('db-lanc-lista-serv'); if(lista)lista.style.display='none';
  var inp   = document.getElementById('db-lanc-busca'); if(inp)inp.value='';
  document.getElementById('db-lanc-servid').value = id;
  var badge = document.getElementById('db-lanc-serv-badge');
  var label = document.getElementById('db-lanc-serv-label');
  if(badge)badge.style.display='flex';
  if(label)label.textContent=(s.codigo||'')+' — '+s.descricao;
  var cod=document.getElementById('db-lanc-cod'); if(cod&&!cod.value)cod.value=s.codigo||'';
  var desc=document.getElementById('db-lanc-desc'); if(desc)desc.value=s.descricao||'';
  var un=document.getElementById('db-lanc-un'); if(un)un.value=s.unidade||'UN';
}

function dbLimparServLanc(){
  document.getElementById('db-lanc-servid').value='';
  var badge=document.getElementById('db-lanc-serv-badge'); if(badge)badge.style.display='none';
  var inp=document.getElementById('db-lanc-busca'); if(inp){inp.value='';inp.focus();}
}

function dbBuscarCodLanc(){
  var inp=document.getElementById('db-lanc-cod'); if(!inp)return;
  var cod=inp.value.trim().toUpperCase();
  if(cod.length<4)return;
  var s=servicos.find(function(x){return(x.codigo||'').toUpperCase()===cod;});
  if(!s)return;
  document.getElementById('db-lanc-servid').value=s.id;
  var desc=document.getElementById('db-lanc-desc'); if(desc)desc.value=s.descricao||'';
  var un=document.getElementById('db-lanc-un'); if(un)un.value=s.unidade||'UN';
  var badge=document.getElementById('db-lanc-serv-badge');
  var label=document.getElementById('db-lanc-serv-label');
  if(badge)badge.style.display='flex';
  if(label)label.textContent=cod+' — '+s.descricao;
}

function dbConfirmarLancamento(){
  var tipo  = (document.getElementById('db-lanc-tipo')||{}).value||'executado';
  var servId= (document.getElementById('db-lanc-servid')||{}).value||'';
  var cod   = ((document.getElementById('db-lanc-cod')||{}).value||'').trim().toUpperCase();
  var desc  = ((document.getElementById('db-lanc-desc')||{}).value||'').trim();
  var qtd   = parseFloat((document.getElementById('db-lanc-qtd')||{}).value)||0;
  var un    = ((document.getElementById('db-lanc-un')||{}).value||'UN').trim();
  var obs   = ((document.getElementById('db-lanc-obs')||{}).value||'').trim();
  var lista = ((document.getElementById('db-lanc-lista')||{}).value||'').trim();

  var itens = [];

  // Processar lista se preenchida
  if(lista){
    lista.split('\n').forEach(function(linha){
      linha=linha.trim(); if(!linha)return;
      var p=linha.split(/[;,\t|]+/);
      if(p.length<2)return;
      var c=p[0].trim().toUpperCase();
      var q=parseFloat((p[1]||'0').replace(',','.').trim());
      if(!c||isNaN(q)||q<=0)return;
      var s=servicos.find(function(x){return(x.codigo||'').toUpperCase()===c;});
      itens.push({tipo:tipo,codigo:c,descricao:s?s.descricao:c,
        qtd:q,unidade:s?(s.unidade||'UN'):'UN',obs:obs,servico_id:s?s.id:null});
    });
  } else {
    // Item único
    if(!cod&&!desc){alert('Informe o código ou a descrição.');return;}
    if(qtd<=0){alert('Informe a quantidade.');return;}
    itens.push({tipo:tipo,codigo:cod,descricao:desc||cod,qtd:qtd,unidade:un,obs:obs,servico_id:servId||null});
  }

  if(!itens.length){alert('Nenhum item válido.');return;}

  // Salvar lançamentos
  var equipeId = _dbSessao&&_dbSessao.equipe_id||'';
  var ordemId  = _dbSessao&&_dbSessao.ordem_id||'';
  var hoje     = dataHojeLocal();

  itens.forEach(function(item){
    var lanc = Object.assign({},item,{
      id:'lanc'+Date.now()+Math.random().toString(36).slice(2),
      equipe_id:equipeId, ordem_id:ordemId,
      encarregado_id:usuarioLogado?usuarioLogado.id:'',
      encarregado_nome:usuarioLogado?usuarioLogado.nome:'',
      data:hoje, status_validacao:'pendente',
      criado_em:new Date().toISOString()
    });
    _dbLancamentos.push(lanc);
    if(!DEMO) sbInsert('sot_lancamentos_campo',{
      tipo:lanc.tipo, codigo:lanc.codigo, descricao:lanc.descricao,
      qtd:lanc.qtd, unidade:lanc.unidade, obs:lanc.obs,
      servico_id:lanc.servico_id, equipe_id:lanc.equipe_id,
      ordem_id:lanc.ordem_id, encarregado_id:lanc.encarregado_id,
      encarregado_nome:lanc.encarregado_nome,
      data:lanc.data, status_validacao:'pendente'
    }).catch(function(){});
  });

  closeModal();
  dbMostrarLancamentos();
  progShowToast('✅ '+itens.length+' lançamento(s) enviado(s) para validação');
}

// ── Validação pela área técnica no projeto ────────────────────
function sotRenderValidacoesCampo(projetoId){
  var wrap = document.getElementById('sot-validacoes-campo');
  if(!wrap) return;

  // Buscar lançamentos pendentes para este projeto
  if(!DEMO){
    sbFetch('sot_lancamentos_campo',{
      filters:['status_validacao=eq.pendente'],
      order:'criado_em.asc'
    }).then(function(rows){
      window._sotLancamentosPend = rows||[];
      sotRenderListaValidacoes(projetoId, rows||[]);
    }).catch(function(){});
  } else {
    sotRenderListaValidacoes(projetoId, []);
  }
}

function sotRenderListaValidacoes(projetoId, rows){
  var wrap = document.getElementById('sot-validacoes-campo');
  if(!wrap) return;

  var relevantes = rows.filter(function(r){
    // Relacionar com o projeto pelo código do serviço
    return sot_atividades.some(function(a){
      return a.projeto_id===projetoId && (a.codigo||'').toUpperCase()===(r.codigo||'').toUpperCase();
    });
  });

  if(!relevantes.length){
    wrap.innerHTML='<div style="font-size:12px;color:#aaa;text-align:center;padding:1rem">Nenhum lançamento pendente de validação</div>';
    return;
  }

  wrap.innerHTML = relevantes.map(function(r){
    var cor = r.tipo==='executado'?'#3B6D11':'#185FA5';
    var bg  = r.tipo==='executado'?'#EAF3DE':'#E6F1FB';
    return '<div style="border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .75rem;margin-bottom:.5rem" id="val-'+r.id+'">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.4rem;flex-wrap:wrap">'
      +'<span style="background:'+bg+';color:'+cor+';padding:2px 8px;border-radius:20px;font-size:10px;font-weight:600">'+(r.tipo==='executado'?'⚡ Executado':'📋 Viabilizado')+'</span>'
      +'<span style="font-family:monospace;font-size:11px;font-weight:600">'+r.codigo+'</span>'
      +'<span style="font-size:12px;flex:1">'+r.descricao+'</span>'
      +'<span style="font-size:11px;color:#888">'+r.encarregado_nome+' · '+(r.data||'')+'</span>'
      +'</div>'
      +'<div style="display:flex;align-items:center;gap:8px">'
      +'<label style="font-size:11px;color:#555;flex-shrink:0">Qtd lançada: <b>'+r.qtd+' '+r.unidade+'</b> → Qtd aprovada:</label>'
      +'<input type="number" id="val-qtd-'+r.id+'" value="'+r.qtd+'" min="0" step="0.01" class="inp" style="width:90px;font-size:13px;font-weight:600"/>'
      +'<span style="flex:1"></span>'
      +'<button onclick="sotValidarLancamento(\''+r.id+'\',\''+projetoId+'\',true)" class="btn btn-sm" style="background:#3B6D11;color:#fff;border-color:#3B6D11;font-size:11px">✅ Aprovar</button>'
      +'<button onclick="sotValidarLancamento(\''+r.id+'\',\''+projetoId+'\',false)" class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D;font-size:11px">❌ Rejeitar</button>'
      +'</div>'
      +(r.obs?'<div style="font-size:11px;color:#888;margin-top:3px">Obs: '+r.obs+'</div>':'')
      +'</div>';
  }).join('');
}

function sotValidarLancamento(lancId, projetoId, aprovar){
  var lanc = (window._sotLancamentosPend||[]).find(function(x){return x.id===lancId;});
  if(!lanc) return;

  if(!aprovar){
    var motivo = prompt('Motivo da rejeição:');
    if(motivo===null)return;
    if(!DEMO) sbUpdate('sot_lancamentos_campo',{status_validacao:'rejeitado',obs_validacao:motivo},'id=eq.'+lancId);
    window._sotLancamentosPend = (window._sotLancamentosPend||[]).filter(function(x){return x.id!==lancId;});
    var el=document.getElementById('val-'+lancId); if(el)el.remove();
    progShowToast('Lançamento rejeitado.');
    return;
  }

  // Qtd aprovada pode ter sido editada
  var qtdAprov = parseFloat((document.getElementById('val-qtd-'+lancId)||{}).value)||lanc.qtd;

  // Encontrar atividade pelo código
  var ativ = sot_atividades.find(function(a){
    return a.projeto_id===projetoId && (a.codigo||'').toUpperCase()===(lanc.codigo||'').toUpperCase();
  });

  if(!ativ){
    if(!confirm('Atividade com código "'+lanc.codigo+'" não encontrada no projeto.\nDeseja criar automaticamente?'))return;
    ativ = {
      id:'sa'+Date.now(), projeto_id:projetoId,
      codigo:lanc.codigo, descricao:lanc.descricao,
      unidade:lanc.unidade||'UN', qtd_prevista:0,
      qtd_viabilizada:0, qtd_executada:0, status:'pendente', servico_id:lanc.servico_id
    };
    sot_atividades.push(ativ);
    if(!DEMO) sbInsert('sot_atividades',_semId(ativ)).then(function(r){if(r&&r[0]&&r[0].id)ativ.id=r[0].id;});
  }

  // Somar na coluna correta
  if(lanc.tipo==='executado'){
    ativ.qtd_executada = (ativ.qtd_executada||0) + qtdAprov;
    if(!DEMO) sbUpdate('sot_atividades',{qtd_executada:ativ.qtd_executada},'id=eq.'+ativ.id);
  } else {
    ativ.qtd_viabilizada = (ativ.qtd_viabilizada||0) + qtdAprov;
    if(!DEMO) sbUpdate('sot_atividades',{qtd_viabilizada:ativ.qtd_viabilizada},'id=eq.'+ativ.id);
  }

  // Marcar lançamento como validado
  if(!DEMO) sbUpdate('sot_lancamentos_campo',{
    status_validacao:'aprovado', qtd_aprovada:qtdAprov,
    validado_por:usuarioLogado?usuarioLogado.nome:'',
    validado_em:new Date().toISOString()
  },'id=eq.'+lancId);

  window._sotLancamentosPend = (window._sotLancamentosPend||[]).filter(function(x){return x.id!==lancId;});
  var el=document.getElementById('val-'+lancId); if(el)el.remove();
  sotAtualizarAbaAtual(projetoId);
  progShowToast('✅ Lançamento aprovado: '+qtdAprov+' '+( ativ.unidade||'UN')+' somado em '+(lanc.tipo==='executado'?'Executado':'Viabilizado'));
}
function sotLancarViabilidadeAtividade(id){
  var a = sot_atividades.find(function(x){ return x.id===id; });
  if(!a) return;

  var html = '<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.25rem">📋 Lançar Viabilizado</h3>'
    +'<div style="font-size:12px;font-weight:500;color:#555;margin-bottom:.75rem">'+(a.codigo?a.codigo+' — ':'')+a.descricao+'</div>'
    +'<div style="background:#f5f5f3;border-radius:8px;padding:.6rem .75rem;margin-bottom:.75rem;display:grid;grid-template-columns:repeat(3,1fr);gap:4px;text-align:center">'
    +'<div><div style="font-size:10px;color:#888">Previsto</div><div style="font-weight:600">'+(a.qtd_prevista||0)+' '+(a.unidade||'UN')+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Já viabilizado</div><div style="font-weight:600;color:#185FA5">'+(a.qtd_viabilizada||0)+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Saldo</div><div style="font-weight:600;color:#854F0B">'+((a.qtd_prevista||0)-(a.qtd_viabilizada||0))+'</div></div>'
    +'</div>'
    +'<div style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Qtd viabilizada neste lançamento *</label>'
    +'<input class="inp" id="sot-viab-qtd" type="number" min="0" step="0.01" value="0" style="width:100%;font-size:16px;font-weight:600"/>'
    +'</div>'
    +'<div style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação</label>'
    +'<input class="inp" id="sot-viab-obs" style="width:100%" placeholder="Ex: Aprovado pelo cliente, trecho X..."/>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-confirmar-viab" style="flex:2;background:#185FA5">✅ Confirmar viabilizado</button>'
    +'</div></div></div>';

  setModal(html);
  setTimeout(function(){
    var inp = document.getElementById('sot-viab-qtd');
    if(inp) inp.focus();
    var btn = document.getElementById('sot-confirmar-viab');
    if(!btn) return;
    btn.onclick = function(){
      var qtd = parseFloat((document.getElementById('sot-viab-qtd')||{}).value)||0;
      var obs = (document.getElementById('sot-viab-obs')||{}).value||'';
      if(qtd<=0){ alert('Informe a quantidade viabilizada.'); return; }
      a.qtd_viabilizada = (a.qtd_viabilizada||0) + qtd;
      if(!a.status||a.status==='pendente') a.status = 'viabilizado';
      if(!DEMO) sbUpdate('sot_atividades',{qtd_viabilizada:a.qtd_viabilizada,status:a.status},'id=eq.'+id);
      var _menuAtv = document.getElementById('sot-menu-lanc');
      if(_menuAtv) _menuAtv.remove();
      closeModal();
      sotAtualizarAbaAtual(a.projeto_id);
      progShowToast('Viabilizado: '+qtd+' '+( a.unidade||'UN')+' — '+a.descricao.substring(0,30));
    };
  },50);
}
function sotLancarExecucaoAtividade(id){
  var a = sot_atividades.find(function(x){ return x.id===id; });
  if(!a) return;

  var pct = a.qtd_prevista>0 ? Math.round((a.qtd_executada||0)/a.qtd_prevista*100) : 0;

  var STATUS_ATIV = [
    {v:'pendente',       l:'Pendente',        c:'#888'},
    {v:'em_execucao',    l:'Em execução',     c:'#185FA5'},
    {v:'executada',      l:'Executada',       c:'#3B6D11'},
    {v:'executada_parcial', l:'Exec. parcial',c:'#854F0B'},
    {v:'cancelada',      l:'Cancelada',       c:'#A32D2D'},
    {v:'divergente',     l:'Divergente',      c:'#534AB7'},
  ];

  var html = '<div class="modal-bg"><div class="modal" style="max-width:440px">'
    +'<h3 style="margin-bottom:.25rem">▶ Lançar Execução</h3>'
    +'<div style="font-size:12px;font-weight:500;color:#555;margin-bottom:.75rem">'+(a.codigo?a.codigo+' — ':'')+a.descricao+'</div>'
    // Resumo
    +'<div style="background:#f5f5f3;border-radius:8px;padding:.6rem .75rem;margin-bottom:.75rem;display:grid;grid-template-columns:repeat(3,1fr);gap:4px;text-align:center">'
    +'<div><div style="font-size:10px;color:#888">Qtd prevista</div><div style="font-weight:600">'+(a.qtd_prevista||0)+' '+(a.unidade||'UN')+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Já executado</div><div style="font-weight:600;color:#3B6D11">'+(a.qtd_executada||0)+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">% concluído</div><div style="font-weight:600;color:'+(pct>=100?'#3B6D11':pct>0?'#185FA5':'#888')+'">'+pct+'%</div></div>'
    +'</div>'
    // Barra de progresso
    +(a.qtd_prevista>0
      ?'<div style="background:#e0dfd8;border-radius:4px;height:6px;margin-bottom:.75rem">'
        +'<div style="background:#3B6D11;width:'+Math.min(100,pct)+'%;height:100%;border-radius:4px;transition:width .3s"></div>'
        +'</div>':'')
    // Campos
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin-bottom:.75rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Qtd executada nesta baixa *</label>'
    +'<input class="inp" id="sot-exec-qtd" type="number" min="0" step="0.01" value="0" style="width:100%;font-size:14px;font-weight:600"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Novo status</label>'
    +'<select class="inp" id="sot-exec-status" style="width:100%">'
    +STATUS_ATIV.map(function(s){
      return '<option value="'+s.v+'"'+(s.v===(a.status||'pendente')?' selected':'')+'>'+s.l+'</option>';
    }).join('')
    +'</select></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Data de execução</label>'
    +'<input class="inp" id="sot-exec-data" type="date" value="'+dataHojeLocal()+'" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação / Ocorrência</label>'
    +'<input class="inp" id="sot-exec-obs" style="width:100%" placeholder="Ex: Executado trecho X, pendência Y..."/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-confirmar-exec" style="flex:2">✅ Confirmar execução</button>'
    +'</div></div></div>';

  setModal(html);

  setTimeout(function(){
    var btn = document.getElementById('sot-confirmar-exec');
    if(!btn) return;
    btn.onclick = function(){
      var qtd    = parseFloat((document.getElementById('sot-exec-qtd')||{}).value)||0;
      var status = (document.getElementById('sot-exec-status')||{}).value||'em_execucao';
      var data   = (document.getElementById('sot-exec-data')||{}).value||'';
      var obs    = (document.getElementById('sot-exec-obs')||{}).value||'';

      if(qtd<=0){ alert('Informe a quantidade executada.'); return; }

      // Acumular executado
      a.qtd_executada = (a.qtd_executada||0) + qtd;
      a.status = status;

      // Se atingiu ou superou o previsto, marcar como executada automaticamente
      if(a.qtd_prevista>0 && a.qtd_executada>=a.qtd_prevista && status==='em_execucao'){
        a.status = 'executada';
        var selSt = document.getElementById('sot-exec-status');
        if(selSt) selSt.value='executada';
      }

      if(!DEMO){
        sbUpdate('sot_atividades',{
          qtd_executada: a.qtd_executada,
          status: a.status
        },'id=eq.'+id);
        // Histórico
        sbInsert('sot_atividades_historico',{
          atividade_id:id, projeto_id:a.projeto_id,
          qtd_lancada:qtd, status_novo:a.status,
          data_execucao:data, obs:obs,
          usuario:usuarioLogado?usuarioLogado.nome:''
        }).catch(function(){});
      }

      var _menuAtvE = document.getElementById('sot-menu-lanc');
      if(_menuAtvE) _menuAtvE.remove();
      closeModal();
      sotAtualizarAbaAtual(a.projeto_id);
      progShowToast('Execução lançada: '+qtd+' '+( a.unidade||'UN')+' — '+a.descricao.substring(0,30));
    };
  },50);
}

// ── Importar atividades ───────────────────────────────────────
function sotImportarAtividades(projetoId){
  var proj = sot_projetos.find(function(x){ return x.id===projetoId; });
  var isListaPrecos = proj&&(proj.modalidade||'').toLowerCase().indexOf('lista')>=0;
  var contId = proj?proj.contrato_id:'';

  var html='<div class="modal-bg"><div class="modal" style="max-width:560px">'
    +'<h3 style="margin-bottom:.5rem">📥 Importar Atividades</h3>'
    +(isListaPrecos?'<div style="font-size:11px;color:#3B6D11;background:#EAF3DE;padding:4px 8px;border-radius:6px;margin-bottom:.75rem">✓ Lista de Preços — duplicatas somadas automaticamente</div>':'')
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-bottom:.75rem">'
    // Opção 1 — arquivo
    +'<div style="border:2px dashed #185FA5;border-radius:10px;padding:1rem;text-align:center;cursor:pointer" onclick="document.getElementById(\'sot-imp-file\').click()">'
    +'<div style="font-size:28px;margin-bottom:.3rem">📂</div>'
    +'<div style="font-weight:600;font-size:13px;color:#185FA5">Importar planilha</div>'
    +'<div style="font-size:11px;color:#888">.CSV · .XLSX · .XLS</div>'
    +'<input type="file" id="sot-imp-file" accept=".csv,.xlsx,.xls,.txt" style="display:none" onchange="sotLerArquivoAtividades()"/>'
    +'</div>'
    // Opção 2 — colar
    +'<div style="border:2px dashed #854F0B;border-radius:10px;padding:1rem;text-align:center;cursor:pointer" onclick="document.getElementById(\'sot-imp-texto\').focus()">'
    +'<div style="font-size:28px;margin-bottom:.3rem">📋</div>'
    +'<div style="font-weight:600;font-size:13px;color:#854F0B">Ctrl+C / Ctrl+V</div>'
    +'<div style="font-size:11px;color:#888">Cole direto do Excel</div>'
    +'</div>'
    +'</div>'
    +'<div style="background:#f5f5f3;border-radius:8px;padding:.4rem .75rem;font-size:11px;margin-bottom:.6rem">'
    +'Formatos aceitos: <code>CÓDIGO ; QTD</code> ou <code>CÓDIGO ; DESCRIÇÃO ; QTD</code> (CSV com aspas OK)<br>'
    +'Separador: <code>;</code> <code>,</code> ou TAB — linha de cabeçalho ignorada automaticamente'
    +'</div>'
    +'<textarea id="sot-imp-texto" class="inp" style="width:100%;height:130px;resize:vertical;font-family:monospace;font-size:12px;margin-bottom:.5rem" '
    +'placeholder="Cole aqui ou carregue um arquivo:\n\n5020100055 ; 10\n5020100059 ; 5\n5027000029 ; 8" '
    +'oninput="sotPreviewImportacao(\''+projetoId+'\')"></textarea>'
    +'<div id="sot-imp-preview" style="display:none;margin-bottom:.75rem;border:.5px solid #e0dfd8;border-radius:8px;max-height:200px;overflow-y:auto"></div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" style="flex:2" onclick="sotConfirmarImportacao(\''+projetoId+'\')">✅ Importar</button>'
    +'</div></div></div>';

  setModal(html);
  setTimeout(function(){ var t=document.getElementById('sot-imp-texto'); if(t)t.focus(); },100);
}

function sotLerArquivoAtividades(){
  var inp=document.getElementById('sot-imp-file');
  if(!inp||!inp.files.length)return;
  var file=inp.files[0], nome=file.name.toLowerCase();
  if(nome.endsWith('.csv')||nome.endsWith('.txt')){
    var r=new FileReader();
    r.onload=function(e){
      var ta=document.getElementById('sot-imp-texto');
      if(ta){ta.value=e.target.result;ta.dispatchEvent(new Event('input'));}
    };
    r.readAsText(file,'UTF-8');
  } else {
    var r2=new FileReader();
    r2.onload=function(e){
      try{
        if(typeof XLSX!=='undefined'){
          var wb=XLSX.read(e.target.result,{type:'array'});
          var ws=wb.Sheets[wb.SheetNames[0]];
          var rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:'',blankrows:false});
          var linhas=rows.filter(function(r){return r&&r[0];})
            .map(function(r){
              var cod=String(r[0]||'').trim();
              var qtd=r.length>=3?r[r.length-1]:r[1];
              return cod+'\t'+String(qtd||'').trim();
            }).join('\n');
          var ta=document.getElementById('sot-imp-texto');
          if(ta){ta.value=linhas;ta.dispatchEvent(new Event('input'));}
        } else { alert('Use CSV ou cole o conteúdo diretamente.'); }
      }catch(e){alert('Erro ao ler Excel: '+e.message);}
    };
    r2.readAsArrayBuffer(file);
  }
}

function _sotSplitCamposLinha(linha){
  var parts=[], cur='', inQ=false;
  for(var i=0;i<=linha.length;i++){
    var c=i<linha.length?linha[i]:'\n';
    if(inQ){
      if(c==='"'){
        if(linha[i+1]==='"'){ cur+='"'; i++; continue; }
        inQ=false;
      } else cur+=c;
    } else {
      if(c==='"'){ inQ=true; continue; }
      if(c===','||c===';'||c==='\t'||c==='|'){
        parts.push(cur.trim());
        cur='';
        continue;
      }
      cur+=c;
    }
  }
  if(cur.trim()||parts.length) parts.push(cur.trim());
  return parts;
}

function _sotLinhaEhCabecalhoImport(parts){
  if(!parts||!parts.length) return true;
  var txt=parts.join(' ').toLowerCase();
  if(/sku|c[oó]digo|descri|quantidade|\bqtd\b|unidade/.test(txt) && parts.every(function(p){
    return isNaN(parseFloat(String(p).replace(',','.')));
  })) return true;
  return false;
}

function _sotExtrairCodQtdLinha(parts){
  if(!parts||parts.length<2) return null;
  var cod=String(parts[0]||'').trim().replace(/^["']|["']$/g,'');
  if(!cod) return null;
  var qtd=null;
  if(parts.length>=3){
    for(var i=parts.length-1;i>=1;i--){
      var v=parseFloat(String(parts[i]).replace(/^["']|["']$/g,'').replace(',','.').trim());
      if(!isNaN(v)&&v>0){ qtd=v; break; }
    }
  } else {
    qtd=parseFloat(String(parts[1]).replace(/^["']|["']$/g,'').replace(',','.').trim());
  }
  if(!cod||isNaN(qtd)||qtd<=0) return null;
  return {codigo:cod.toUpperCase(), qtd:qtd};
}

function sotParsarLinhasImportacao(){
  var ta=document.getElementById('sot-imp-texto');
  if(!ta||!ta.value.trim())return[];
  var res={};
  ta.value.split(/\r?\n/).forEach(function(linha){
    linha=linha.trim();
    if(!linha||linha.startsWith('#'))return;
    var parts=_sotSplitCamposLinha(linha);
    if(_sotLinhaEhCabecalhoImport(parts)) return;
    var item=_sotExtrairCodQtdLinha(parts);
    if(!item) return;
    res[item.codigo]=(res[item.codigo]||0)+item.qtd;
  });
  return Object.keys(res).map(function(c){return{codigo:c,qtd:res[c]};});
}

function sotPreviewImportacao(projetoId){
  var itens=sotParsarLinhasImportacao();
  var prev=document.getElementById('sot-imp-preview');
  if(!prev)return;
  if(!itens.length){prev.style.display='none';return;}
  var proj=sot_projetos.find(function(x){return x.id===projetoId;});
  var contId=proj?proj.contrato_id:'';
  var sc=servicos.filter(function(s){return !contId||s.contrato_id===contId;});
  var rows=itens.map(function(item){
    var serv=sc.find(function(s){return(s.codigo||'').toUpperCase()===item.codigo;});
    var ja=sot_atividades.find(function(a){return(a.codigo||'').toUpperCase()===item.codigo;});
    return{item:item,serv:serv,ja:ja};
  });
  var ok=rows.filter(function(r){return r.serv;}).length;
  var sem=rows.filter(function(r){return!r.serv;}).length;
  var dup=rows.filter(function(r){return r.ja;}).length;
  var tot=rows.reduce(function(s,r){return s+(r.serv?(r.serv.valor_ups||r.serv.valor_hora||0)*r.item.qtd:0);},0);
  prev.style.display='';
  prev.innerHTML='<div style="padding:.4rem .75rem;background:#f9f9f7;border-bottom:.5px solid #e0dfd8;font-size:11px;display:flex;gap:10px;flex-wrap:wrap">'
    +'<span style="color:#3B6D11;font-weight:600">✓ '+ok+' encontrados</span>'
    +(sem?'<span style="color:#A32D2D">⚠ '+sem+' sem cadastro</span>':'')
    +(dup?'<span style="color:#854F0B">🔁 '+dup+' serão somados</span>':'')
    +(tot?'<span style="margin-left:auto;font-weight:600">'+fmtMoeda(tot)+'</span>':'')
    +'</div>'
    +'<table style="width:100%;font-size:11px;border-collapse:collapse">'
    +'<tr style="background:#f0efe8"><th style="padding:3px 8px;text-align:left">Código</th><th style="padding:3px 8px;text-align:left">Descrição</th><th style="padding:3px 8px;text-align:right">Qtd</th><th style="padding:3px 8px;text-align:right">V.Unit.</th><th style="padding:3px 8px;text-align:right">Total</th></tr>'
    +rows.map(function(r){
      var cor=r.serv?'':'color:#A32D2D';
      var vu=r.serv?(r.serv.valor_ups||r.serv.valor_hora||0):0;
      return '<tr style="border-top:.5px solid #f0efe8">'
        +'<td style="padding:3px 8px;font-family:monospace;'+cor+'">'+r.item.codigo+(r.ja?' 🔁':'')+'</td>'
        +'<td style="padding:3px 8px;'+cor+'">'+(r.serv?r.serv.descricao:'⚠ não cadastrado')+'</td>'
        +'<td style="padding:3px 8px;text-align:right">'+r.item.qtd+'</td>'
        +'<td style="padding:3px 8px;text-align:right">'+(vu?fmtMoeda(vu):'—')+'</td>'
        +'<td style="padding:3px 8px;text-align:right">'+(vu?fmtMoeda(vu*r.item.qtd):'—')+'</td>'
        +'</tr>';
    }).join('')+'</table>';
}

function sotConfirmarImportacao(projetoId){
  var itens=sotParsarLinhasImportacao();
  if(!itens.length){alert('Nenhuma linha válida para importar.');return;}
  var proj=sot_projetos.find(function(x){return x.id===projetoId;});
  var contId=proj?proj.contrato_id:'';
  var sc=servicos.filter(function(s){return !contId||s.contrato_id===contId;});
  var imp=0,som=0;
  itens.forEach(function(item){
    var serv=sc.find(function(s){return(s.codigo||'').toUpperCase()===item.codigo;});
    var ja=sot_atividades.find(function(a){return(a.codigo||'').toUpperCase()===item.codigo;});
    if(ja){
      ja.qtd_prevista=(ja.qtd_prevista||0)+item.qtd;
      if(!DEMO)sbUpdate('sot_atividades',{qtd_prevista:ja.qtd_prevista},'id=eq.'+ja.id);
      som++;
    } else {
      var _qups = serv?(serv.qtd_ups||1):1;
      var _vups = serv?(serv.valor_ups||serv.valor_hora||0):0;
      var nova={id:'sa'+Date.now()+Math.random().toString(36).slice(2),
        projeto_id:projetoId,codigo:item.codigo,
        descricao:serv?serv.descricao:item.codigo,
        unidade:serv?(serv.unidade||'UN'):'UN',
        qtd_prevista:item.qtd,qtd_executada:0,
        qtd_ups:_qups, valor_ups:_vups,
        valor_unitario:_vups,
        status:'pendente',servico_id:serv?serv.id:null,
        ordem_exec:sot_atividades.length+1};
      sot_atividades.push(nova);
      if(!DEMO)sbInsert('sot_atividades',_semId(nova)).then(function(r){if(r&&r[0]&&r[0].id)nova.id=r[0].id;});
      imp++;
    }
  });
  closeModal();
  sotAtualizarAbaAtual(projetoId);
  progShowToast('✅ '+imp+' importada(s) · '+som+' somada(s)');
}

