async function _sotCarregarArqMat(input){
  var file=input.files[0]; if(!file) return;
  var txt=document.getElementById('imp-mat-txt');
  if(file.name.match(/\.xlsx?$/i) && typeof XLSX!=='undefined'){
    var b64=await new Promise(function(res,rej){
      var r=new FileReader();r.onload=function(e){res(e.target.result.split(',')[1]);};r.onerror=rej;r.readAsDataURL(file);
    });
    var wb=XLSX.read(b64,{type:'base64'});
    var ws=wb.Sheets[wb.SheetNames[0]];
    var rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:'',blankrows:false}).slice(0,300);
    if(txt) txt.value=rows.map(function(r){return r.slice(0,5).join(';');}).join('\n');
  } else {
    var reader=new FileReader();
    reader.onload=function(e){if(txt)txt.value=e.target.result;};
    reader.readAsText(file,'UTF-8');
  }
}

function sotProcessarImportacaoMat(projetoId){
  var raw=(document.getElementById('imp-mat-txt')||{}).value||'';
  var linhas=raw.split('\n').map(function(l){return l.trim();}).filter(Boolean);
  if(!linhas.length){progShowToast('⚠ Nenhuma linha.','erro');return;}
  var n=0;
  linhas.forEach(function(linha){
    var sep=linha.indexOf(';')>=0?';':'\t';
    var cols=linha.split(sep).map(function(x){return x.trim();});
    var desc=cols[1]||cols[0]||''; if(!desc) return;
    var m={
      id:'sm'+Date.now()+n, projeto_id:projetoId,
      codigo_sap:cols[0]||'', descricao:desc,
      unidade:cols[3]||'UN', qtd_projetada:parseFloat(cols[2])||1,
      qtd_viabilizada:0, qtd_requisitada:0, qtd_entregue:0,
      qtd_aplicada:0, qtd_devolvida:0, qtd_processada_sap:0,
    };
    sot_materiais_proj.push(m);
    if(!DEMO){
      var p=Object.assign({},m); delete p.id;
      sbInsert('sot_materiais',p).then(function(r){if(r&&r[0])m.id=r[0].id;}).catch(function(){});
    }
    n++;
  });
  closeModal();
  sotAtualizarAbaAtual(projetoId);
  progShowToast('✅ '+n+' material(is) importado(s)');
}



// ── Reserva de materiais SOT — cálculo de saldo e adicional ───────────────
// Sem alteração de schema: flags qtd_prevista/qtd_adicional/adicional_pendente no JSON itens
function sotCalcReservaMat(m){
  var prog       = Number(m.qtd_projetada)||0;
  var adicionado = Number(m._adicionado)||0;
  var totalProg  = prog + adicionado;
  var resAnt     = Number(m._res_ant)||0;
  var resAtual   = Number(m._res_atual)||0;
  var totalRes   = resAnt + resAtual;
  var aplicAnt   = Number(m._aplic_ant)||0;
  var aplicAtual = Number(m._aplic_atual)||0;
  var totalAplic = aplicAnt + aplicAtual;
  var saldoPrevisto = Math.max(0, totalProg - totalRes - totalAplic);
  return {
    prog:prog, adicionado:adicionado, totalProg:totalProg,
    resAnt:resAnt, resAtual:resAtual, totalRes:totalRes,
    aplicAnt:aplicAnt, aplicAtual:aplicAtual, totalAplic:totalAplic,
    saldoPrevisto:saldoPrevisto
  };
}
function sotReservaStatusHtml(calc, novaQtd){
  novaQtd = Number(novaQtd)||0;
  if(novaQtd<=0) return '<span style="font-size:9px;color:#aaa">—</span>';
  if(novaQtd <= calc.saldoPrevisto){
    return '<span style="font-size:9px;color:#3B6D11;font-weight:600">✓ Dentro do previsto</span>';
  }
  var exc = +(novaQtd - calc.saldoPrevisto).toFixed(4);
  var prev = calc.saldoPrevisto;
  return '<span style="font-size:9px;color:#854F0B;font-weight:600">Excedente: '+exc+'</span>'
    +(prev>0?'<div style="font-size:9px;color:#3B6D11">Previsto: '+prev+'</div>':'')
    +'<div style="font-size:9px;color:#A32D2D;font-weight:600">⚠ Adicional pendente</div>';
}
function sotSplitReservaQtd(m, novaQtd){
  var calc = sotCalcReservaMat(m);
  novaQtd = Math.max(0, Number(novaQtd)||0);
  var qtdPrevista = Math.min(novaQtd, calc.saldoPrevisto);
  var qtdAdicional = Math.max(0, novaQtd - calc.saldoPrevisto);
  return {
    calc:calc, novaQtd:novaQtd,
    qtd_prevista:qtdPrevista, qtd_adicional:qtdAdicional,
    temAdicional:qtdAdicional > 0
  };
}
function sotAtualizarStatusReservaLinha(i){
  var mats = window._sotReservaItensMats||[];
  var m = mats[i];
  if(!m) return;
  var inp = document.getElementById('sot-rsv-qtd-'+i);
  var el  = document.getElementById('sot-rsv-status-'+i);
  if(!el) return;
  var calc = sotCalcReservaMat(m);
  var novaQtd = inp ? (parseFloat(inp.value)||0) : 0;
  el.innerHTML = sotReservaStatusHtml(calc, novaQtd);
}
function sotAbrirModalAdicionalReserva(projetoId, excessItens, ctx, onOk){
  var motivos = ['Urgência operacional','Erro de programação','Necessidade não prevista','Cliente solicitou','Outro'];
  var rows = excessItens.map(function(x,i){
    return '<div style="background:#FFF8EC;border:.5px solid #F5D78E;border-radius:8px;padding:.65rem;margin-bottom:.5rem">'
      +'<div style="font-weight:600;font-size:12px;margin-bottom:4px">'+escHtml(x.mat.descricao||x.mat.nome||'Material')+'</div>'
      +(x.mat.codigo_sap?'<div style="font-size:10px;color:#888;font-family:monospace">'+escHtml(x.mat.codigo_sap)+'</div>':'')
      +'<div style="font-size:11px;color:#555;margin:.35rem 0">'
      +'Dentro do previsto: <b style="color:#3B6D11">'+x.qtd_prevista+'</b> '+escHtml(x.mat.unidade||'UN')
      +' · Adicional: <b style="color:#854F0B">'+x.qtd_adicional+'</b> '+escHtml(x.mat.unidade||'UN')
      +'</div>'
      +'<div class="fg" style="margin-bottom:.4rem"><label style="font-size:11px;font-weight:600">Motivo *</label>'
      +'<select class="inp" id="sot-adic-mot-'+i+'" style="width:100%">'
      +motivos.map(function(mo){ return '<option>'+mo+'</option>'; }).join('')
      +'</select></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Justificativa *</label>'
      +'<textarea class="inp" id="sot-adic-just-'+i+'" rows="2" style="width:100%;resize:vertical" placeholder="Descreva por que precisa de material acima do previsto..."></textarea>'
      +'</div></div>';
  }).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:520px;max-height:90vh;overflow-y:auto">'
    +'<h3 style="margin:0 0 .5rem;color:#854F0B">📦 Material adicional obrigatório</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">A quantidade solicitada ultrapassa o saldo previsto do projeto. '
    +'Informe motivo e justificativa — o excedente será registrado como <b>adicional pendente de aprovação</b>.</div>'
    +rows
    +'<div style="display:flex;gap:8px;margin-top:.5rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-adic-reserva-ok" style="flex:2;background:#854F0B;border-color:#854F0B">Confirmar e solicitar</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var btn = document.getElementById('sot-adic-reserva-ok');
    if(!btn) return;
    btn.onclick = function(){
      var meta = [];
      for(var i=0;i<excessItens.length;i++){
        var motivo = ((document.getElementById('sot-adic-mot-'+i)||{}).value||'').trim();
        var justif = ((document.getElementById('sot-adic-just-'+i)||{}).value||'').trim();
        if(!justif){ progShowToast('⚠ Informe a justificativa para todos os itens adicionais.','erro'); return; }
        meta.push({ motivo:motivo, justificativa:justif });
      }
      closeModal();
      onOk(meta);
    };
  }, 0);
}
function sotPersistirRequisicaoMateriais(projetoId, itensSel, ctx, adicionalMeta){
  adicionalMeta = adicionalMeta || [];
  var temAdicional = itensSel.some(function(it){ return it.qtd_adicional > 0; });
  var metaIdx = 0;
  var promAdic = [];
  if(!DEMO && temAdicional){
    itensSel.forEach(function(it){
      if(!it.qtd_adicional || it.qtd_adicional<=0) return;
      var meta = adicionalMeta[metaIdx++] || {};
      var obsAdic = '[Reserva material] Motivo: '+(meta.motivo||'—')+' | '+ (meta.justificativa||'');
      promAdic.push(
        sbInsert('sot_adicionais', {
          projeto_id: projetoId, tipo:'material',
          catalog_id: it.mat_id||null,
          descricao: it.nome, codigo_sap: it.codigo||null, unidade: it.unidade,
          qtd_solicitada: it.qtd_adicional, observacoes: obsAdic,
          criado_por: usuarioLogado ? usuarioLogado.nome : '',
          status: 'pendente'
        }).then(function(r){
          if(r && r[0] && r[0].id) it.adicional_id = r[0].id;
        })
      );
    });
  } else if(DEMO && temAdicional){
    itensSel.forEach(function(it){
      if(it.qtd_adicional>0) it.adicional_id = 'adic-demo-'+Date.now();
    });
  }
  Promise.all(promAdic).then(function(){
    var payload = {
      projeto_id: projetoId,
      equipe_id: ctx.equipeId,
      data: ctx.dataRetir,
      status: temAdicional ? 'Adicional pendente de aprovação' : 'Aguardando aprovação',
      solicitante: usuarioLogado ? usuarioLogado.nome : '',
      observacoes: ctx.obs,
      itens: JSON.stringify(itensSel),
      criado_em: new Date().toISOString()
    };
    if(DEMO){
      progShowToast('✅ Requisição enviada'+(temAdicional?' (com adicional pendente)':'')+' (demo)');
      return;
    }
    sbInsert('plpt_requisicoes_materiais', payload)
      .then(function(){
        progShowToast(temAdicional
          ? '✅ Solicitação enviada — parte adicional aguarda aprovação do gestor.'
          : '✅ Requisição enviada! Aguardando aprovação do gerente.');
        var content = document.getElementById('sot-tab-content');
        if(content) sotRenderTabReserva(projetoId, content);
        else if(typeof sotAtualizarAbaAtual==='function') sotAtualizarAbaAtual(projetoId);
      })
      .catch(function(e){ progShowToast('⚠ Erro: '+(e&&e.message||e),'erro'); });
  });
}
function sotLiberarRequisicoesAdicional(projId, descricao, codigoSap){
  if(DEMO) return;
  sbFetch('plpt_requisicoes_materiais', {
    filters:['projeto_id=eq.'+projId,'status=eq.Adicional pendente de aprovação','deleted_at=is.null'],
    limit:50
  }).then(function(rows){
    (rows||[]).forEach(function(r){
      var itens = parseJsonField(r.itens, []);
      var changed = false;
      itens.forEach(function(it){
        var match = (descricao && it.nome && it.nome.toLowerCase()===descricao.toLowerCase())
          || (codigoSap && it.codigo && it.codigo===codigoSap);
        if(match && it.adicional_pendente){
          it.adicional_pendente = false;
          it.qtd_req = (it.qtd_prevista||0) + (it.qtd_adicional||0);
          changed = true;
        }
      });
      if(!changed) return;
      var stillPending = itens.some(function(it){ return it.adicional_pendente; });
      var patch = { itens: JSON.stringify(itens) };
      if(!stillPending) patch.status = 'Aguardando aprovação';
      sbUpdate('plpt_requisicoes_materiais', patch, 'id=eq.'+r.id);
    });
  }).catch(function(){});
}

function sotRenderTabPlano(projetoId, container){
  var el = container || document.getElementById('sot-tab-content');
  if(!el) return;
  var p = sot_projetos.find(function(x){ return x.id===projetoId; });
  if(!p){ el.innerHTML='<div style="padding:1rem;color:#A32D2D">Projeto não encontrado.</div>'; return; }

  var plano = sotParsePlanoExecucao(p);
  window._sotPlanoEdit = plano ? JSON.parse(JSON.stringify(plano)) : null;

  if(!plano || !plano.wls || !plano.wls.length){
    el.innerHTML = '<div style="padding:2rem;text-align:center">'
      +'<div style="font-size:40px;margin-bottom:.5rem">📋</div>'
      +'<div style="font-size:14px;font-weight:600;color:#444;margin-bottom:.5rem">Nenhum plano de execução</div>'
      +'<div style="font-size:12px;color:#888;margin-bottom:1rem">Analise o croqui com IA para gerar a estratégia e distribuição de WLs por equipe.</div>'
      +(p.croqui_url
        ? '<button class="btn btn-pri" onclick="sotIniciarAnaliseWL(\''+projetoId+'\')">🔍 Analisar croqui com IA</button>'
        : '<div style="font-size:11px;color:#854F0B">Anexe o croqui no cadastro do projeto primeiro.</div>')
      +'</div>';
    return;
  }

  var ia = plano.estrategia_ia || {};
  var aj = plano.ajustes || {};
  var numEq = aj.num_equipes != null ? aj.num_equipes : (plano.num_equipes || 1);
  var wls = plano.wls;

  var html = '<div style="padding:.75rem">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:.75rem">'
    +'<div><div style="font-size:14px;font-weight:700">📋 Plano de Execução</div>'
    +'<div style="font-size:11px;color:#888">'+(plano.atualizado_em ? 'Atualizado '+fmtD(plano.atualizado_em.split('T')[0])+(plano.atualizado_por?' · '+escHtml(plano.atualizado_por):'') : '')+'</div></div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
    +'<button class="btn btn-sm" onclick="sotIniciarAnaliseWL(\''+projetoId+'\')" style="font-size:11px">🔍 Reanalisar croqui</button>'
    +'<button class="btn btn-sm" onclick="sotPlanoRedistribuir(\''+projetoId+'\')" style="font-size:11px">↺ Redistribuir WLs</button>'
    +'<button class="btn btn-pri btn-sm" onclick="sotPlanoSalvar(\''+projetoId+'\')" style="font-size:11px">💾 Salvar ajustes</button>'
    +'</div></div>';

  if(ia.justificativa || ia.equipes_recomendadas){
    html += '<div style="background:#EAF3DE;border:.5px solid #92D050;border-radius:10px;padding:12px 16px;margin-bottom:.75rem">'
      +'<div style="font-size:12px;font-weight:700;color:#3B6D11;margin-bottom:8px">🤖 Estratégia definida pela IA</div>'
      +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px;margin-bottom:8px">'
      +'<div style="text-align:center"><div style="font-size:22px;font-weight:600;color:#3B6D11">'+(ia.total_wls||wls.length)+'</div><div style="font-size:10px;color:#666">WLs</div></div>'
      +'<div style="text-align:center"><div style="font-size:22px;font-weight:600;color:#185FA5">'+(ia.equipes_recomendadas||'—')+'</div><div style="font-size:10px;color:#666">Equipes IA</div></div>'
      +'<div style="text-align:center"><div style="font-size:22px;font-weight:600;color:#854F0B">'+(ia.dias_estimados||'—')+'</div><div style="font-size:10px;color:#666">Dias estimados</div></div>'
      +(ia.dias_minimos?'<div style="text-align:center"><div style="font-size:22px;font-weight:600;color:#533AB7">'+ia.dias_minimos+'</div><div style="font-size:10px;color:#666">Dias mín. ('+(ia.equipes_para_minimo||'?')+' eq.)</div></div>':'')
      +'</div>'
      +(ia.justificativa?'<div style="font-size:12px;color:#444;line-height:1.5;border-top:.5px solid #92D050;padding-top:8px">'+escHtml(ia.justificativa)+'</div>':'')
      +'</div>';
  }

  html += '<div style="background:#F5F8FF;border:.5px solid #c0cfe8;border-radius:10px;padding:12px 16px;margin-bottom:.75rem">'
    +'<div style="font-size:12px;font-weight:700;color:#185FA5;margin-bottom:10px">✏️ Ajustes do programador</div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.75rem;margin-bottom:.75rem">'
    +'<div><label style="font-size:10px;font-weight:600;color:#666;display:block;margin-bottom:3px">Equipes planejadas</label>'
    +'<input type="number" id="sot-plano-eq" class="inp" min="1" max="30" value="'+numEq+'" style="width:100%;font-size:13px"></div>'
    +'<div><label style="font-size:10px;font-weight:600;color:#666;display:block;margin-bottom:3px">Dias previstos</label>'
    +'<input type="number" id="sot-plano-dias" class="inp" min="1" max="365" value="'+(aj.dias_previstos||ia.dias_estimados||'')+'" style="width:100%;font-size:13px" placeholder="Dias"></div>'
    +'</div>'
    +'<div style="margin-bottom:.75rem"><label style="font-size:10px;font-weight:600;color:#666;display:block;margin-bottom:3px">Estratégia / ajustes operacionais</label>'
    +'<textarea id="sot-plano-just" class="inp" rows="3" style="width:100%;font-size:12px" placeholder="Descreva ajustes na estratégia, sequência de execução, restrições...">'+escHtml(aj.justificativa||'')+'</textarea></div>'
    +'<div><label style="font-size:10px;font-weight:600;color:#666;display:block;margin-bottom:3px">Observações para programação</label>'
    +'<textarea id="sot-plano-obs" class="inp" rows="2" style="width:100%;font-size:12px" placeholder="Observações internas...">'+escHtml(aj.observacoes||'')+'</textarea></div>'
    +'</div>';

  html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-bottom:.75rem">';
  for(var ei=0; ei<numEq; ei++){
    var mine = wls.filter(function(w){ return (w.equipe||0)===ei; });
    var nums = mine.map(function(w){ return w.numero; }).join(', ') || '—';
    var horas = mine.reduce(function(s,w){ return s+(WL_HORAS_POR_COMPLEXIDADE[w.complexidade]||4); }, 0);
    var diasEq = Math.ceil(horas/WL_HORAS_TURNO) || 0;
    html += '<div style="border-left:3px solid '+WL_CORES[ei%WL_CORES.length]+';background:#fff;border-radius:8px;border:.5px solid #e0dfd8;padding:10px 12px">'
      +'<div style="display:flex;justify-content:space-between;margin-bottom:3px"><span style="font-size:12px;font-weight:600">Equipe '+(ei+1)+'</span><span style="font-size:10px;color:#888">'+mine.length+' WLs</span></div>'
      +'<div style="font-size:11px;color:#555;margin-bottom:3px">'+escHtml(nums)+'</div>'
      +'<div style="font-size:10px;color:#185FA5">~'+diasEq+' dia'+(diasEq!==1?'s':'')+'</div></div>';
  }
  html += '</div>';

  html += '<div style="overflow-x:auto"><table style="width:100%;font-size:12px;border-collapse:collapse;min-width:640px">'
    +'<thead><tr style="border-bottom:.5px solid #e0dfd8;background:#fafaf8">'
    +'<th style="text-align:left;padding:6px 8px">WL</th><th style="padding:6px 8px;text-align:left">Tipo</th><th style="padding:6px 8px">Região</th>'
    +'<th style="padding:6px 8px">Complexidade</th><th style="padding:6px 8px">Equipe</th><th style="padding:6px 8px;text-align:left">Materiais</th>'
    +'</tr></thead><tbody>'
    +wls.map(function(w){
      var eqOpts = '';
      for(var q=0; q<numEq; q++){
        eqOpts += '<option value="'+q+'"'+(w.equipe===q?' selected':'')+'>Equipe '+(q+1)+'</option>';
      }
      var mats = (w.materiais&&w.materiais.length)
        ? w.materiais.map(function(m){ return escHtml((m.qtd||'')+' '+(m.unidade||'')+' '+(m.nome||'')); }).join('<br>')
        : '<span style="color:#aaa">—</span>';
      return '<tr style="border-bottom:.5px solid #f0f0ee">'
        +'<td style="padding:6px 8px;font-weight:600">'+escHtml(w.numero)+'</td>'
        +'<td style="padding:6px 8px;color:#555">'+escHtml(w.tipo||'—')+'</td>'
        +'<td style="padding:6px 8px;color:#666">'+escHtml(w.regiao||'—')+'</td>'
        +'<td style="padding:6px 8px;font-size:11px">'+escHtml(w.complexidade||'Média')+'</td>'
        +'<td style="padding:6px 8px"><select class="inp sot-plano-wl-eq" data-wl-id="'+w.id+'" style="font-size:11px;padding:3px 6px">'+eqOpts+'</select></td>'
        +'<td style="padding:6px 8px;font-size:10px;color:#666">'+mats+'</td></tr>';
    }).join('')
    +'</tbody></table></div></div>';

  el.innerHTML = html;
}

function sotPlanoColetarWlsDoForm(){
  var wls = (window._sotPlanoEdit && window._sotPlanoEdit.wls) ? JSON.parse(JSON.stringify(window._sotPlanoEdit.wls)) : [];
  document.querySelectorAll('.sot-plano-wl-eq').forEach(function(sel){
    var id = parseInt(sel.getAttribute('data-wl-id'), 10);
    var w = wls.find(function(x){ return x.id===id; });
    if(w) w.equipe = parseInt(sel.value, 10) || 0;
  });
  return wls;
}

function sotPlanoRedistribuir(projetoId){
  var numEq = parseInt((document.getElementById('sot-plano-eq')||{}).value, 10) || 1;
  var wls = sotPlanoColetarWlsDoForm();
  if(!wls.length){ progShowToast('⚠ Nenhuma WL no plano.'); return; }
  var sorted = wls.slice().sort(function(a,b){ return (a.y||0)-(b.y||0) || (a.x||0)-(b.x||0); });
  var perEq = Math.ceil(sorted.length / numEq);
  sorted.forEach(function(w, i){
    if(!w.bloqueada) w.equipe = Math.floor(i / perEq);
  });
  if(window._sotPlanoEdit) window._sotPlanoEdit.wls = wls;
  var p = sot_projetos.find(function(x){ return x.id===projetoId; });
  if(p){
    var plano = sotParsePlanoExecucao(p) || {};
    plano.wls = wls;
    plano.num_equipes = numEq;
    if(!p.plano_execucao) p.plano_execucao = JSON.stringify(plano);
    else {
      try{
        var cur = typeof p.plano_execucao==='string' ? JSON.parse(p.plano_execucao) : p.plano_execucao;
        cur.wls = wls; cur.num_equipes = numEq;
        p.plano_execucao = JSON.stringify(cur);
      }catch(e){}
    }
  }
  sotRenderTabPlano(projetoId);
  progShowToast('↺ WLs redistribuídas — clique em Salvar ajustes para gravar.');
}

function sotPlanoSalvar(projetoId){
  var wls = sotPlanoColetarWlsDoForm();
  var numEq = parseInt((document.getElementById('sot-plano-eq')||{}).value, 10) || 1;
  var dias = parseInt((document.getElementById('sot-plano-dias')||{}).value, 10);
  var just = (document.getElementById('sot-plano-just')||{}).value || '';
  var obs = (document.getElementById('sot-plano-obs')||{}).value || '';
  if(!wls.length){ progShowToast('⚠ Nenhuma WL para salvar.'); return; }

  var plano = sotMontarPlanoExecucao({
    projeto: projetoId,
    wls: wls,
    num_equipes: numEq,
    ajustes: {
      num_equipes: numEq,
      dias_previstos: isNaN(dias) ? null : dias,
      justificativa: just,
      observacoes: obs
    }
  });
  sotSalvarPlanoExecucao(projetoId, plano);
}

function sotRenderTabResumo(projetoId, container){
  var el = container || document.getElementById('sot-tab-content');
  if(!el) return;
  el.innerHTML = '<div style="padding:1rem;text-align:center;color:#aaa">⏳ Carregando resumo...</div>';
  var p = sot_projetos.find(function(x){ return x.id===projetoId; }) || {};
  Promise.all([
    DEMO ? Promise.resolve(sot_atividades||[]) : sbFetch('sot_atividades',{filters:['projeto_id=eq.'+projetoId],order:'ordem_exec'}),
    DEMO ? Promise.resolve(sot_materiais_proj||[]) : sbFetch('sot_materiais',{filters:['projeto_id=eq.'+projetoId,'deleted_at=is.null']}),
    DEMO ? Promise.resolve([]) : sbFetch('plpt_requisicoes_materiais',{filters:['projeto_id=eq.'+projetoId,'deleted_at=is.null'],order:'criado_em.asc',limit:100}),
  ]).then(function(res){
    var pjStub = {_requisicoes: res[2]||[], _relatorioObras: p.relatorio_obras||''};
    el.innerHTML = '<div style="padding:.75rem">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem">'
      +'<div style="font-size:14px;font-weight:700">📊 Resumo operacional</div>'
      +'<button class="btn btn-sm" onclick="sotAnalisarRelatorio(\''+projetoId+'\')" '
      +'style="background:linear-gradient(135deg,#533AB7,#185FA5);color:#fff;border:none;font-size:11px">🤖 Analisar relatório IA</button>'
      +'</div>'
      + plptRenderResumoOperacoes(projetoId, pjStub, p, res[0]||[], res[1]||[])
      +'</div>';
  }).catch(function(){
    el.innerHTML = '<div style="padding:1rem;color:#A32D2D">Erro ao carregar resumo.</div>';
  });
}

function sotRenderTabReserva(projetoId, container){
  var mats = (typeof sot_materiais_proj!=='undefined' ? sot_materiais_proj : [])
    .filter(function(m){ return m.projeto_id===projetoId; });

  if(!mats.length){
    if(!DEMO){
      if(container) container.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">⏳ Carregando...</div>';
      sbFetch('sot_materiais',{filters:['projeto_id=eq.'+projetoId,'deleted_at=is.null']})
        .then(function(rows){
          if(rows&&rows.length) rows.forEach(function(r){
            if(!sot_materiais_proj.find(function(x){return x.id===r.id;})) sot_materiais_proj.push(r);
          });
          sotRenderTabReserva(projetoId, container);
        }).catch(function(){
          if(container) container.innerHTML='<div style="padding:1.5rem;color:#A32D2D">Erro ao carregar materiais.</div>';
        });
      return;
    }
    if(container) container.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Nenhum material programado.</div>';
    return;
  }

  var html = '<div style="padding:.5rem">';

  // ── Cabeçalho informativo ──────────────────────────────────────────────
  html += '<div style="background:#F0EEFF;border-radius:10px;padding:.75rem 1rem;margin-bottom:.75rem">'
    +'<div style="font-weight:700;font-size:13px;color:#533AB7;margin-bottom:.4rem">📤 Nova Requisição de Materiais</div>'
    +'<div style="font-size:11px;color:#666">Selecione os materiais e informe a quantidade a usar. '
    +'O <strong>saldo previsto</strong> = Total programado − Reservado − Aplicado. '
    +'Acima do saldo exige <strong>material adicional</strong> com motivo e justificativa.</div>'
    +'</div>';

  // ── Tabela com todas as colunas ────────────────────────────────────────
  html += '<div style="overflow-x:auto;margin-bottom:.75rem">'
    +'<table style="width:100%;border-collapse:collapse;font-size:11px;min-width:900px">'
    +'<thead>'
    // Grupo headers
    +'<tr style="background:#1a1a18;color:#fff;font-size:10px">'
    +'<th rowspan="2" style="padding:5px 8px;width:28px"></th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:left;min-width:140px">Material</th>'
    // PROGRAMAÇÃO → PLANEJADO / ADICIONAIS + PROGRAMADO / RESERVAS
    +'<th colspan="3" style="padding:4px 8px;text-align:center;border-left:1px solid #333;background:#854F0B">PLANEJADO / ADICIONAIS</th>'
    +'<th colspan="4" style="padding:4px 8px;text-align:center;border-left:1px solid #333;background:#185FA5">PROGRAMADO / RESERVAS</th>'
    // APLICAÇÃO
    +'<th colspan="3" style="padding:4px 8px;text-align:center;border-left:1px solid #333;background:#085041">APLICAÇÃO</th>'
    // HOJE
    +'<th rowspan="2" style="padding:5px 8px;text-align:center;border-left:1px solid #333;background:#854F0B;min-width:65px">Dev.<br>Hoje</th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:center;border-left:1px solid #333;min-width:90px">Status</th>'
    +'<th rowspan="2" style="padding:5px 8px;text-align:center;border-left:1px solid #333;min-width:75px">Qtd a usar</th>'
    +'</tr>'
    +'<tr style="background:#222;color:#ddd;font-size:10px">'
    // PLANEJADO / ADICIONAIS
    +'<th style="padding:4px 6px;text-align:right;border-left:1px solid #333" title="Quantidade planejada">Plan.</th>'
    +'<th style="padding:4px 6px;text-align:right" title="Adicionais aprovados">Adic.</th>'
    +'<th style="padding:4px 6px;text-align:right;font-weight:700;color:#FFE0A3" title="Planejado + Adicionais">Total</th>'
    // PROGRAMADO / RESERVAS
    +'<th style="padding:4px 6px;text-align:right;border-left:1px solid #333;color:#7CB8FF;font-weight:700" title="Quantidade programada (viabilizada)">Prog.</th>'
    +'<th style="padding:4px 6px;text-align:right" title="Reservas de dias anteriores">Ant.</th>'
    +'<th style="padding:4px 6px;text-align:right" title="Reserva de hoje">Hoje</th>'
    +'<th style="padding:4px 6px;text-align:right;font-weight:700;color:#B39DFF" title="Total Reservado — nunca > Total Programado">Total</th>'
    // APLICAÇÃO sub
    +'<th style="padding:4px 6px;text-align:right;border-left:1px solid #333" title="Aplicação acumulada de dias anteriores">Ant.</th>'
    +'<th style="padding:4px 6px;text-align:right" title="Aplicação de hoje">Hoje</th>'
    +'<th style="padding:4px 6px;text-align:right;font-weight:700;color:#81C995" title="Total Aplicado — nunca > Total Reservado">Total</th>'
    +'</tr>'
    +'</thead><tbody>';

  mats.forEach(function(m, i){
    var un = escHtml(m.unidade||'UN');
    var calc = sotCalcReservaMat(m);
    var prog       = calc.prog;
    var adicionado = calc.adicionado;
    var totalProg  = calc.totalProg;
    var resAnt     = calc.resAnt;
    var resAtual   = calc.resAtual;
    var totalRes   = calc.totalRes;
    var resOk      = totalRes <= totalProg;
    var aplicAnt   = calc.aplicAnt;
    var aplicAtual = calc.aplicAtual;
    var totalAplic = calc.totalAplic;
    var aplicOk    = totalAplic <= totalRes;
    var devHoje    = m._dev_hoje || 0;
    var viab       = m.qtd_viabilizada || 0;
    var saldo      = calc.saldoPrevisto;
    var corSaldo   = saldo > 0 ? '#3B6D11' : saldo === 0 ? '#888' : '#A32D2D';

    html += '<tr style="border-bottom:.5px solid #f0efe8">'
      +'<td style="padding:6px 8px"><input type="checkbox" id="sot-rsv-chk-'+i+'" '
      +'onchange="sotReservaToggle('+i+')" style="cursor:pointer;width:16px;height:16px"/></td>'
      +'<td style="padding:6px 8px">'
      +(m.codigo_sap?'<div style="font-size:10px;color:#888;font-family:monospace">'+escHtml(m.codigo_sap)+'</div>':'')
      +'<div style="font-weight:500">'+escHtml(m.descricao||'Material')+'</div>'
      +'</td>'
      // PLANEJADO / ADICIONAIS
      +'<td style="padding:6px 6px;text-align:right;color:#854F0B;border-left:1px solid #f0efe8">'+prog+'</td>'
      +'<td style="padding:6px 6px;text-align:right;color:'+(adicionado>0?'#854F0B':'#ccc')+'">'+( adicionado>0?adicionado:'—')+'</td>'
      +'<td style="padding:6px 6px;text-align:right;font-weight:700;color:#854F0B">'+totalProg+' <span style="font-size:9px;font-weight:400">'+un+'</span></td>'
      // PROGRAMADO / RESERVAS
      +'<td style="padding:6px 6px;text-align:right;border-left:1px solid #f0efe8;color:'+(viab>0?'#185FA5':'#ccc')+';font-weight:'+(viab>0?'700':'400')+'">'+(viab>0?viab:'—')+'</td>'
      +'<td style="padding:6px 6px;text-align:right;color:'+(resAnt>0?'#533AB7':'#ccc')+'">'+( resAnt>0?resAnt:'—')+'</td>'
      +'<td style="padding:6px 6px;text-align:right;color:'+(resAtual>0?'#533AB7':'#ccc')+'">'+( resAtual>0?resAtual:'—')+'</td>'
      +'<td style="padding:6px 6px;text-align:right;font-weight:700;color:'+(resOk?'#533AB7':'#A32D2D')+'">'
      +totalRes+' <span style="font-size:9px;font-weight:400">'+un+'</span>'
      +(!resOk?'<div style="font-size:9px;color:#A32D2D">⚠ > Prog</div>':'')+'</td>'
      // APLICAÇÃO
      +'<td style="padding:6px 6px;text-align:right;color:'+(aplicAnt>0?'#085041':'#ccc')+';border-left:1px solid #f0efe8">'+( aplicAnt>0?aplicAnt:'—')+'</td>'
      +'<td style="padding:6px 6px;text-align:right;color:'+(aplicAtual>0?'#085041':'#ccc')+'">'+( aplicAtual>0?aplicAtual:'—')+'</td>'
      +'<td style="padding:6px 6px;text-align:right;font-weight:700;color:'+(aplicOk?'#085041':'#A32D2D')+'">'
      +totalAplic+' <span style="font-size:9px;font-weight:400">'+un+'</span>'
      +(!aplicOk?'<div style="font-size:9px;color:#A32D2D">⚠ > Res</div>':'')+'</td>'
      // DEVOLVIDO HOJE
      +'<td style="padding:6px 6px;text-align:right;color:'+(devHoje>0?'#854F0B':'#ccc')+';border-left:1px solid #f0efe8">'+( devHoje>0?devHoje:'—')+'</td>'
      +'<td style="padding:6px 6px;text-align:center;border-left:1px solid #f0efe8;vertical-align:middle" id="sot-rsv-status-'+i+'">'
      +'<span style="font-size:9px;color:#aaa">—</span></td>'
      +'<td style="padding:6px 8px;text-align:center;border-left:1px solid #f0efe8">'
      +'<div style="font-size:10px;color:'+corSaldo+';font-weight:600;margin-bottom:2px" title="Prog − Reservado − Aplicado">Saldo prev.: '+saldo+'</div>'
      +'<input type="number" id="sot-rsv-qtd-'+i+'" min="0" step="0.01" value="0" disabled '
      +'style="width:65px;padding:4px;border:.5px solid #e0dfd8;border-radius:6px;text-align:center;font-size:12px" '
      +'oninput="sotReservaQtd('+i+',this.value)"/>'
      +(saldo===0?'<div style="font-size:9px;color:#888;margin-top:2px">Sem saldo previsto</div>':'')
      +'</td></tr>';
  });

  html += '</tbody></table></div>';

  // Equipe options — somente equipes do contrato do projeto
  var _sotProjRsv = (typeof sot_projetos!=='undefined' ? sot_projetos : []).find(function(p){ return p.id===projetoId; });
  var _podeEditarEq = usuarioLogado && ['admin','gestor','coordenador'].indexOf(usuarioLogado.perfil)>=0;
  var _eqOptsHtml = rsvEquipesOptsHtml(_sotProjRsv && _sotProjRsv.contrato_id, {selectedId: _sotProjRsv && _sotProjRsv.equipe_id});
  var _hoje = dataHojeLocal();

  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-bottom:.5rem">'
    +'<div class="fg"><label style="font-size:11px;font-weight:600">Equipe responsável *</label>'
    +'<select class="inp" id="sot-rsv-equipe" style="width:100%"'+(_podeEditarEq?'':' disabled')+'>'+_eqOptsHtml+'</select></div>'
    +'<div class="fg"><label style="font-size:11px;font-weight:600">Data prevista de retirada</label>'
    +'<input class="inp" id="sot-rsv-data" type="date" value="'+_hoje+'" style="width:100%"/></div>'
    +'</div>';

  html += '<div style="display:grid;grid-template-columns:1fr auto;gap:.5rem;align-items:end">'
    +'<div class="fg"><label style="font-size:11px;font-weight:600">Observações</label>'
    +'<input class="inp" id="sot-rsv-obs" placeholder="Urgência, local de entrega..." style="width:100%"/></div>'
    +'<button class="btn btn-pri" onclick="sotEnviarRequisicao(\''+projetoId+'\')" '
    +'style="background:#533AB7;border-color:#533AB7;white-space:nowrap;height:38px">📤 Solicitar</button>'
    +'</div>';

  html += '</div>';
  html += '<div id="sot-rsv-historico"><div style="padding:1rem;text-align:center;color:#aaa;font-size:12px">⏳ Carregando histórico...</div></div>';
  html += '</div>';

  if(container) container.innerHTML = html;
  window._sotReservaItensMats = mats;
  window._sotReservaProjId    = projetoId;
  sotCarregarHistoricoRequisicoes(projetoId);
  // Event delegation for mover-req buttons (avoids inline onclick quote issues)
  if(container){
    container.addEventListener('click', function(e){
      var btn = e.target.closest('.sot-mover-req');
      if(btn){ sotMoverReq(btn.dataset.id, btn.dataset.status); }
    });
  }
}



function sotReservaToggle(i){
  var chk = document.getElementById('sot-rsv-chk-'+i);
  var inp = document.getElementById('sot-rsv-qtd-'+i);
  if(!chk||!inp) return;
  inp.disabled = !chk.checked;
  var mats = window._sotReservaItensMats||[];
  if(chk.checked && Number(inp.value)===0 && mats[i]){
    var saldo = sotCalcReservaMat(mats[i]).saldoPrevisto;
    inp.value = saldo > 0 ? saldo : 0;
  }
  if(!chk.checked) inp.value=0;
  sotAtualizarStatusReservaLinha(i);
}

function sotReservaQtd(i, val){
  var inp = document.getElementById('sot-rsv-qtd-'+i);
  if(inp && Number(val)<0) inp.value = 0;
  sotAtualizarStatusReservaLinha(i);
}

function sotEnviarRequisicao(projetoId){
  var mats = window._sotReservaItensMats||[];
  var itensSel = [];
  var excessItens = [];
  mats.forEach(function(m,i){
    var chk = document.getElementById('sot-rsv-chk-'+i);
    var inp = document.getElementById('sot-rsv-qtd-'+i);
    if(chk&&chk.checked&&inp){
      var novaQtd = parseFloat(inp.value)||0;
      if(novaQtd<=0) return;
      var split = sotSplitReservaQtd(m, novaQtd);
      var item = {
        mat_id:m.id, codigo:m.codigo_sap||'', nome:m.descricao||'',
        unidade:m.unidade||'UN',
        qtd_prog:split.calc.totalProg,
        qtd_req:novaQtd,
        qtd_prevista:split.qtd_prevista,
        qtd_adicional:split.qtd_adicional,
        adicional_pendente:split.temAdicional
      };
      itensSel.push(item);
      if(split.temAdicional){
        excessItens.push({
          mat:m, calc:split.calc, novaQtd:novaQtd,
          qtd_prevista:split.qtd_prevista, qtd_adicional:split.qtd_adicional
        });
      }
    }
  });
  if(!itensSel.length){
    progShowToast('⚠ Selecione ao menos um material com quantidade.','erro');
    return;
  }
  var obs         = (document.getElementById('sot-rsv-obs')||{}).value||'';
  var equipeIdSel = (document.getElementById('sot-rsv-equipe')||{}).value||null;
  var dataRetir   = (document.getElementById('sot-rsv-data')||{}).value||dataHojeLocal();

  if(!equipeIdSel){
    progShowToast('⚠ Selecione a equipe responsável pela retirada.','erro');
    return;
  }
  var ctx = { equipeId:equipeIdSel, dataRetir:dataRetir, obs:obs };
  if(excessItens.length){
    sotAbrirModalAdicionalReserva(projetoId, excessItens, ctx, function(adicionalMeta){
      sotPersistirRequisicaoMateriais(projetoId, itensSel, ctx, adicionalMeta);
    });
    return;
  }
  sotPersistirRequisicaoMateriais(projetoId, itensSel, ctx, []);
}


// ── Mover status de requisição (almoxarife/gestor) ──────────────────────────
function sotMoverReq(reqId, novoStatus){
  if(novoStatus==='Separação'){
    var _bloqueado = false;
    if(!DEMO){
      sbFetch('plpt_requisicoes_materiais',{filters:['id=eq.'+reqId],limit:1}).then(function(rows){
        var r = rows && rows[0];
        if(r && r.status==='Adicional pendente de aprovação'){
          progShowToast('⚠ Separação bloqueada — material adicional ainda pendente de aprovação.','erro');
          return;
        }
        _sotMoverReqExec(reqId, novoStatus);
      });
      return;
    }
  }
  _sotMoverReqExec(reqId, novoStatus);
}
function _sotMoverReqExec(reqId, novoStatus){
  var confirmar = novoStatus==='Reprovada' ? confirm('Reprovar esta requisição?') : true;
  if(!confirmar) return;
  if(!DEMO){
    sbUpdate('plpt_requisicoes_materiais', {status:novoStatus}, 'id=eq.'+reqId)
      .then(function(ok){
        if(ok){
          progShowToast('✅ Status atualizado: '+novoStatus);
          // Refresh the reservation tab
          var p = sot_projetos.find(function(x){ return x.id===_sotProjetoAtual; });
          if(p) sotCarregarHistoricoRequisicoes(p.id);
        } else {
          progShowToast('⚠ Erro ao atualizar status.','erro');
        }
      });
  }
}


function sotCarregarHistoricoRequisicoes(projetoId){
  var el = document.getElementById('sot-rsv-historico');
  if(!el) return;
  if(DEMO){ el.innerHTML=''; return; }
  sbFetch('plpt_requisicoes_materiais',{
    filters:['projeto_id=eq.'+projetoId,'deleted_at=is.null'],
    order:'criado_em.desc', limit:20
  }).then(function(rows){
    if(!rows||!rows.length){ el.innerHTML=''; return; }
    var STATUS_COR={'Aguardando aprovação':{bg:'#FEF3E2',c:'#854F0B'},
      'Adicional pendente de aprovação':{bg:'#FFF0E0',c:'#A32D2D'},
      'Aprovada':{bg:'#EAF3DE',c:'#3B6D11'},'Separação':{bg:'#EBF4FD',c:'#185FA5'},
      'Em campo':{bg:'#F0EEFF',c:'#533AB7'},'Devolvida':{bg:'#f5f5f3',c:'#888'},
      'Reprovada':{bg:'#FFF0F0',c:'#A32D2D'}};
    el.innerHTML = '<div style="margin-top:.5rem">'
      +'<div style="font-size:12px;font-weight:700;color:#555;margin-bottom:.5rem">Histórico de Requisições</div>'
      +rows.map(function(r){
        var sc=STATUS_COR[r.status]||{bg:'#f5f5f3',c:'#555'};
        var itens=parseJsonField(r.itens,[]);
        var eqNome = '';
        if(r.equipe_id){
          var _projEq = (typeof sot_projetos!=='undefined'?sot_projetos:[]).find(function(p){ return p.id===r.projeto_id; });
          var _eq = rsvEquipePorId(r.equipe_id, _projEq && _projEq.contrato_id);
          eqNome = _eq ? (_eq.codigo||_eq.nome_equipe||_eq.nome||'') : r.equipe_id.slice(0,8);
        }
        var _isAlmox = usuarioLogado && (usuarioLogado.cargo||'').toLowerCase().indexOf('almox')>=0;
        var _isGestor = usuarioLogado && ['admin','gestor','coordenador'].indexOf(usuarioLogado.perfil)>=0;
        var _acoes = '';
        if(_isAlmox || _isGestor){
          if(r.status==='Aguardando aprovação')
            _acoes += '<button class="btn btn-sm sot-mover-req" data-id="'+r.id+'" data-status="Aprovada" style="font-size:10px;background:#3B6D11;color:#fff;border-color:#3B6D11">✅ Aprovar</button> ';
          if(r.status==='Aprovada' && _isAlmox)
            _acoes += '<button class="btn btn-sm sot-mover-req" data-id="'+r.id+'" data-status="Separação" style="font-size:10px;background:#185FA5;color:#fff;border-color:#185FA5">📦 Separar</button> ';
          if(r.status==='Adicional pendente de aprovação')
            _acoes += '<span style="font-size:10px;color:#A32D2D;font-weight:600">⏳ Aprove o adicional na aba Adicional</span> ';
          if(r.status!=='Adicional pendente de aprovação')
            _acoes += '<button class="btn btn-sm sot-mover-req" data-id="'+r.id+'" data-status="Reprovada" style="font-size:10px;color:#A32D2D;border-color:#A32D2D">✕</button>';
        }
        return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .85rem;margin-bottom:.4rem">'
          +'<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:.5rem;margin-bottom:.2rem">'
          +'<div>'
          +'<div style="font-size:12px;font-weight:600">'+fmtD(r.data_retirada||r.data)
          +(r.solicitante?' · '+escHtml(r.solicitante):'')+'</div>'
          +'<div style="font-size:11px;color:#888">'+itens.length+' item(ns)'
          +(eqNome?' · 👥 '+escHtml(eqNome):' · <span style="color:#A32D2D">⚠ sem equipe</span>')
          +(r.observacoes?' · '+escHtml(r.observacoes.slice(0,50)):'')+'</div>'
          +'</div>'
          +'<span style="background:'+sc.bg+';color:'+sc.c+';border-radius:8px;padding:2px 10px;font-size:11px;font-weight:600">'+r.status+'</span>'
          +'</div>'
          +(_acoes?'<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:.3rem">'+_acoes+'</div>':'')
          +'</div>';
      }).join('')
      +'</div>';
  }).catch(function(){ el.innerHTML=''; });
}


function sotLancarBaixaMaterial(id){
  var m = sot_materiais_proj.find(function(x){ return x.id===id; });
  if(!m) return;

  // Calcular emCampo buscando de plpt_requisicoes_materiais em tempo real
  function _abrirBaixaModal(qtdEntregueReal){
    var _qtdEntregue = qtdEntregueReal || (m.qtd_entregue||0);
    var emCampo = _qtdEntregue - (m.qtd_aplicada||0) - (m.qtd_devolvida||0);
    if(emCampo < 0) emCampo = 0; // nunca negativo
  var html = '<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.25rem">📥 Baixa de Material</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem;font-weight:500">'+m.descricao+'</div>'
    // Resumo atual
    +'<div style="background:#f5f5f3;border-radius:8px;padding:.6rem .75rem;margin-bottom:.75rem;display:grid;grid-template-columns:repeat(4,1fr);gap:4px;text-align:center">'
    +'<div><div style="font-size:10px;color:#888">Projetado</div><div style="font-weight:600">'+(m.qtd_projetada||0)+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Entregue</div><div style="font-weight:600;color:#185FA5">'+_qtdEntregue+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Aplicado</div><div style="font-weight:600;color:#3B6D11">'+(m.qtd_aplicada||0)+'</div></div>'
    +'<div><div style="font-size:10px;color:#888">Saldo campo</div><div style="font-weight:600;color:'+(emCampo>0?'#854F0B':emCampo<0?'#A32D2D':'#888')+'">'+emCampo+'</div></div>'
    +'</div>'
    // Campos de lançamento
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin-bottom:.75rem">'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Qtd aplicada *</label>'
    +'<input class="inp" id="sot-baixa-aplic" type="number" min="0" step="0.01" value="0" style="width:100%;font-size:14px;font-weight:600"/></div>'
    +'<div><label style="font-size:11px;font-weight:600;display:block;margin-bottom:3px">Qtd devolvida</label>'
    +'<input class="inp" id="sot-baixa-dev" type="number" min="0" step="0.01" value="0" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Observação</label>'
    +'<input class="inp" id="sot-baixa-obs" style="width:100%" placeholder="Ex: Aplicado na rede trecho A-B..."/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="sot-confirmar-baixa" style="flex:2">✅ Confirmar baixa</button>'
    +'</div></div></div>';

  setModal(html);
  setTimeout(function(){
    var btn = document.getElementById('sot-confirmar-baixa');
    if(!btn) return;
    btn.onclick = function(){
      var aplic = parseFloat((document.getElementById('sot-baixa-aplic')||{}).value)||0;
      var dev   = parseFloat((document.getElementById('sot-baixa-dev')||{}).value)||0;
      var obs   = (document.getElementById('sot-baixa-obs')||{}).value||'';

      if(aplic<=0 && dev<=0){ alert('Informe ao menos a quantidade aplicada ou devolvida.'); return; }

      // Acumular sobre os valores existentes
      m.qtd_aplicada  = (m.qtd_aplicada||0) + aplic;
      m.qtd_devolvida = (m.qtd_devolvida||0) + dev;

      if(!DEMO){
        sbUpdate('sot_materiais',{
          qtd_aplicada:  m.qtd_aplicada,
          qtd_devolvida: m.qtd_devolvida
        },'id=eq.'+id);
        // Registrar no histórico se a tabela existir
        sbInsert('sot_materiais_historico',{
          material_id:id, projeto_id:m.projeto_id,
          qtd_aplicada:aplic, qtd_devolvida:dev,
          obs:obs, usuario:usuarioLogado?usuarioLogado.nome:'',
          criado_em:new Date().toISOString()
        }).catch(function(){});
      }

      closeModal();
      sotAtualizarAbaAtual(m.projeto_id);
      progShowToast('Baixa registrada: '+aplic+' '+m.unidade+' aplicado(s)');
    };
  },50);
  } // end _abrirBaixaModal

  // Buscar qtd real entregue de plpt_requisicoes_materiais
  if(!DEMO && m.projeto_id){
    sbFetch('plpt_requisicoes_materiais',{
      filters:['projeto_id=eq.'+m.projeto_id,'status=eq.Em campo'],
      limit:20
    }).then(function(reqs){
      var qtdRet = 0;
      (reqs||[]).forEach(function(r){
        var itens = parseJsonField(r.itens,[]);
        itens.forEach(function(it){
          if(it.codigo===m.codigo_sap || it.nome===m.descricao){
            qtdRet += (it.qtd_ret||it.qtd_req||0);
          }
        });
      });
      // Sincronizar qtd_entregue se diferente
      if(qtdRet > 0 && qtdRet !== (m.qtd_entregue||0)){
        m.qtd_entregue = qtdRet;
        sbUpdate('sot_materiais',{qtd_entregue:qtdRet},'id=eq.'+m.id).catch(function(){});
      }
      _abrirBaixaModal(qtdRet || m.qtd_entregue || 0);
    }).catch(function(){ _abrirBaixaModal(m.qtd_entregue||0); });
  } else {
    _abrirBaixaModal(m.qtd_entregue||0);
  }
}


function sotRecusarAdicional(projId, adicId){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:380px">'
    +'<h3 style="margin-bottom:.5rem;color:#A32D2D">❌ Recusar Adicional</h3>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Motivo da recusa *</label>'
    +'<textarea class="inp" id="recusa-motivo" rows="3" style="width:100%;resize:vertical" placeholder="Explique o motivo..."></textarea>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="recusa-confirmar" style="flex:2;background:#A32D2D;border-color:#A32D2D">❌ Confirmar Recusa</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var btn = document.getElementById('recusa-confirmar');
    if(!btn) return;
    btn.onclick = function(){
      var motivo = ((document.getElementById('recusa-motivo')||{}).value||'').trim();
      if(!motivo){ progShowToast('⚠ Informe o motivo.','erro'); return; }
      closeModal();
      if(!DEMO){
        sbUpdate('sot_adicionais',{
          status:'recusado',
          observacoes: 'RECUSADO: '+motivo,
          aprovado_em: new Date().toISOString(),
          aprovado_por: usuarioLogado?usuarioLogado.nome:'',
        },'id=eq.'+adicId).then(function(){
          progShowToast('❌ Adicional recusado.');
          sotAtualizarAbaAtual(projId);
        }).catch(function(e){ progShowToast('⚠ Erro: '+(e&&e.message||e),'erro'); });
      }
    };
  },50);
}


function sotPersistirAdicionalMaterial(m, qtdAdic, callback){
  var qtd = Math.max(0, parseFloat(qtdAdic)||0);
  m._adicionado = qtd;
  if(DEMO){ if(callback) callback(); return; }
  var projId = m.projeto_id;
  var tag = 'Via edição material';
  sbFetch('sot_adicionais',{
    filters:['projeto_id=eq.'+projId,'tipo=eq.material'],
    order:'criado_em.desc', limit:200
  }).then(function(rows){
    var matches = (rows||[]).filter(function(a){
      if(m.codigo_sap && a.codigo_sap && m.codigo_sap===a.codigo_sap) return true;
      if(m.descricao && a.descricao && m.descricao.toLowerCase()===a.descricao.toLowerCase()) return true;
      return false;
    });
    var manual = matches.find(function(a){ return (a.observacoes||'').indexOf(tag)>=0; });
    var others = matches.filter(function(a){
      return a !== manual && (a.status==='aprovado' || a.status==='Aprovado');
    });
    var sumOthers = others.reduce(function(s, a){
      return s + (parseFloat(a.qtd_aprovada||a.qtd_solicitada)||0);
    }, 0);
    var manualQtd = Math.max(0, qtd - sumOthers);
    if(manualQtd <= 0){
      if(manual && manual.id) sbDelete('sot_adicionais','id=eq.'+manual.id).finally(function(){
        m._adicionado = sumOthers;
        if(callback) callback();
      });
      else {
        m._adicionado = sumOthers;
        if(callback) callback();
      }
      return;
    }
    var payload = {
      qtd_solicitada: manualQtd,
      qtd_aprovada:   manualQtd,
      status:         'aprovado',
      codigo_sap:     m.codigo_sap||'',
      descricao:      m.descricao,
      unidade:        m.unidade||'UN',
      observacoes:    tag,
      aprovado_por:   usuarioLogado ? usuarioLogado.nome : '',
      aprovado_em:    new Date().toISOString(),
    };
    m._adicionado = sumOthers + manualQtd;
    if(manual && manual.id){
      sbUpdate('sot_adicionais', payload, 'id=eq.'+manual.id).then(function(){ if(callback) callback(); });
    } else {
      sbInsert('sot_adicionais', Object.assign({
        projeto_id: projId,
        tipo:       'material',
        criado_por: usuarioLogado ? usuarioLogado.nome : '',
      }, payload)).then(function(){ if(callback) callback(); });
    }
  }).catch(function(e){
    console.error('sotPersistirAdicionalMaterial:', e);
    if(callback) callback();
  });
}

function sotEditarMaterial(id){
  var m = sot_materiais_proj.find(function(x){ return x.id===id; });
  if(!m) return;
  var qtdAdic = m._adicionado != null ? m._adicionado : 0;
  setModal('<div class="modal-bg"><div class="modal" style="max-width:460px">'
    +'<h3 style="margin-bottom:.75rem">Editar Material</h3>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin-bottom:.75rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Código SAP</label>'
    +'<input class="inp" id="sot-mat-cod" value="'+(m.codigo_sap||'')+'" style="width:100%" oninput="sotAutoFillEditBySAP(this.value)"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Unidade</label>'
    +'<input class="inp" id="sot-mat-un" value="'+(m.unidade||'UN')+'" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Descrição *</label>'
    +'<input class="inp" id="sot-mat-desc" value="'+escHtml(m.descricao||'')+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Qtd Projetada</label>'
    +'<input class="inp" id="sot-mat-qtd" type="number" step="0.01" value="'+(m.qtd_projetada||0)+'" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Qtd Adicional</label>'
    +'<input class="inp" id="sot-mat-adic" type="number" step="0.01" min="0" value="'+qtdAdic+'" style="width:100%"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:2px">Observação</label>'
    +'<input class="inp" id="sot-mat-obs" value="'+escHtml(m.observacao||'')+'" style="width:100%"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:.5rem">'
    +'<button class="btn" id="sot-excluir-mat" style="color:#A32D2D;border-color:#A32D2D">Excluir</button>'
    +'<button class="btn btn-pri" id="sot-salvar-mat" style="flex:2">Salvar</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var btnS = document.getElementById('sot-salvar-mat');
    if(btnS) btnS.onclick = function(){
      var g=function(id){return(document.getElementById(id)||{}).value||'';};
      var desc=g('sot-mat-desc').trim();
      if(!desc){progShowToast('⚠ Informe a descrição.','erro');return;}
      m.codigo_sap      = g('sot-mat-cod').trim();
      m.descricao       = desc;
      m.unidade         = g('sot-mat-un')||'UN';
      m.qtd_projetada   = parseFloat(g('sot-mat-qtd'))||0;
      var qtdAdicSalvar = parseFloat(g('sot-mat-adic'))||0;
      m.observacao      = g('sot-mat-obs');
      var projId = m.projeto_id;
      function _finalizarEdicao(){
        closeModal();
        sotAtualizarAbaAtual(projId);
        progShowToast('✅ Material atualizado.');
      }
      if(!DEMO){
        var _payload={codigo_sap:m.codigo_sap,descricao:m.descricao,unidade:m.unidade,
          qtd_projetada:m.qtd_projetada,
          observacao:m.observacao};
        function _aposMaterial(){
          sotPersistirAdicionalMaterial(m, qtdAdicSalvar, _finalizarEdicao);
        }
        if(isUUID(id)){
          sbUpdate('sot_materiais',_payload,'id=eq.'+id).then(function(ok){
            if(!ok) progShowToast('⚠ Erro ao salvar material no banco.','erro');
            _aposMaterial();
          }).catch(function(e){
            console.error('Edit mat:',e);
            progShowToast('⚠ Erro: '+(e&&e.message||e),'erro');
            _aposMaterial();
          });
        } else {
          sbFetch('sot_materiais',{filters:['projeto_id=eq.'+m.projeto_id,'codigo_sap=eq.'+m.codigo_sap,'deleted_at=is.null']})
            .then(function(rows){
              if(rows&&rows[0]&&rows[0].id){
                m.id=rows[0].id;
                sbUpdate('sot_materiais',_payload,'id=eq.'+rows[0].id).then(_aposMaterial);
              } else {
                var ins=Object.assign({projeto_id:m.projeto_id,
                  qtd_requisitada:0,qtd_entregue:0,qtd_aplicada:0,
                  qtd_devolvida:0,qtd_processada_sap:0,qtd_viabilizada:0},_payload);
                sbInsert('sot_materiais',ins).then(function(r){
                  if(r&&r[0]) m.id=r[0].id;
                  _aposMaterial();
                }).catch(function(e){ progShowToast('⚠ Erro ao inserir: '+(e&&e.message||e),'erro'); _aposMaterial(); });
              }
            }).catch(function(e){
              console.error('Edit mat lookup:',e);
              progShowToast('⚠ Erro ao buscar material: '+(e&&e.message||e),'erro');
              _aposMaterial();
            });
        }
      } else {
        m._adicionado = qtdAdicSalvar;
        _finalizarEdicao();
      }
      return;
    };
    var btnE = document.getElementById('sot-excluir-mat');
    if(btnE) btnE.onclick = function(){
      if(!confirm('Excluir "'+m.descricao+'"?')) return;
      var projId = m.projeto_id;
      // Remove from local array immediately
      sot_materiais_proj = sot_materiais_proj.filter(function(x){ return x.id !== id; });
      closeModal();
      sotAtualizarAbaAtual(projId);
      if(!DEMO){
        // sbDelete is async — wait for result
        Promise.resolve(sbDelete('sot_materiais','id=eq.'+id))
          .then(function(){
            progShowToast('✅ Material excluído.');
          })
          .catch(function(e){
            // Rollback: re-add to local array
            progShowToast('⚠ Erro ao excluir: '+(e&&e.message||e),'erro');
          });
      } else {
        progShowToast('✅ Material excluído (demo).');
      }
    };
  },50);
}

var _ajudaAberto = false;
var _ajudaHistorico = [];
var CENA_SYSTEM_PROMPT = 'Você é o Assistente CENA, especializado no ERP CENA para gestão de contratos de obras e serviços elétricos. Conheça todos os módulos: Operacional (TMA, PLPT, Programação de Projetos), SESMT, Frotas, Financeiro, Almoxarifado SAP, SOT/Projetos de Obras. Responda sempre em português, seja direto e objetivo.'
  + ' NAVEGAÇÃO: quando o usuário perguntar o caminho para um módulo/tela ou como chegar em alguma função, explique o caminho em texto e, no FINAL da resposta, inclua um marcador de navegação no formato [[IR:destino]] usando EXATAMENTE um destes destinos válidos (não invente outros): '
  + 'dashboard, contratos, operacional, financeiro, viabilidade, almoxarifado, frotas, sesmt, relatorios, cadastros, plr, gestao-pessoas, programacao (Programação de Equipes/TMA), treinamentos, entradas-almox (Entradas no Almoxarifado), ferramentas, epis, uniformes, estoque-almox, extrato-colaborador, celulares (cadastro de celulares), novo-lancamento (novo lançamento financeiro), frotas-manutencoes, portaria. '
  + 'Use no máximo 1 ou 2 marcadores por resposta, só quando fizer sentido navegar. Se nenhum destino se aplicar, não inclua marcador. Data atual: '+new Date().toLocaleDateString('pt-BR')+'.';

function cenaAjudaAbrir(){
  var panel = document.getElementById('cena-ajuda-panel');
  if(!panel) return;
  panel.style.display = 'flex';
  _ajudaAberto = true;
  var input = document.getElementById('cena-ajuda-input');
  if(input) setTimeout(function(){input.focus();},100);
}

function cenaAjudaFechar(){
  var panel = document.getElementById('cena-ajuda-panel');
  if(panel) panel.style.display = 'none';
  _ajudaAberto = false;
}

function cenaAjudaPerguntar(texto){
  var input = document.getElementById('cena-ajuda-input');
  if(input) input.value = texto;
  cenaAjudaEnviar();
}

function cenaAjudaEnviar(){
  var input = document.getElementById('cena-ajuda-input');
  if(!input) return;
  var texto = input.value.trim();
  if(!texto) return;
  input.value = '';

  // Adicionar mensagem do usuário
  cenaAjudaAdicionarMsg('user', texto);

  // Adicionar ao histórico
  _ajudaHistorico.push({role:'user', content:texto});

  // Mostrar indicador de digitação
  var typingId = 'typing-' + Date.now();
  cenaAjudaAdicionarMsg('typing', '...', typingId);

  // Atualizar status
  var st = document.getElementById('cena-ajuda-status');
  if(st) st.textContent = 'Pensando...';

  var btn = document.getElementById('cena-ajuda-send');
  if(btn) btn.disabled = true;

  // Chamar API Claude
  fetch('https://cena-proxy.marcos-afe.workers.dev', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 1000,
      system: CENA_SYSTEM_PROMPT,
      messages: _ajudaHistorico
    })
  })
  .then(function(r){ return r.json(); })
  .then(function(data){
    // Remover typing
    var typingEl = document.getElementById(typingId);
    if(typingEl) typingEl.remove();

    var resposta = data.content && data.content[0] && data.content[0].text
      ? data.content[0].text
      : 'Desculpe, não consegui processar sua pergunta. Tente novamente.';

    // Adicionar ao histórico
    _ajudaHistorico.push({role:'assistant', content:resposta});

    // Mostrar resposta
    cenaAjudaAdicionarMsg('assistant', resposta);

    if(st) st.textContent = 'Pronto para ajudar';
    if(btn) btn.disabled = false;
  })
  .catch(function(err){
    var typingEl = document.getElementById(typingId);
    if(typingEl) typingEl.remove();
    cenaAjudaAdicionarMsg('assistant', 'Erro ao conectar com o assistente. Verifique sua conexão e tente novamente.');
    if(st) st.textContent = 'Pronto para ajudar';
    if(btn) btn.disabled = false;
    console.error('Ajuda erro:', err);
  });
}

function cenaAjudaAdicionarMsg(tipo, texto, id){
  var msgs = document.getElementById('cena-ajuda-msgs');
  if(!msgs) return;

  var div = document.createElement('div');
  if(id) div.id = id;
  div.style.cssText = 'display:flex;gap:8px;align-items:flex-start';

  if(tipo === 'user'){
    div.style.flexDirection = 'row-reverse';
    div.innerHTML = '<div style="width:28px;height:28px;background:#185FA5;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;flex-shrink:0">'
      +(usuarioLogado?usuarioLogado.nome[0].toUpperCase():'U')+'</div>'
      +'<div style="background:#1a1a18;color:#fff;border-radius:12px 12px 2px 12px;padding:10px 14px;font-size:13px;max-width:260px;line-height:1.5">'+_escapeHtml(texto)+'</div>';
  } else if(tipo === 'typing'){
    div.innerHTML = '<div style="width:28px;height:28px;background:#1a1a18;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">🤖</div>'
      +'<div style="background:#f5f5f3;border-radius:12px 12px 12px 2px;padding:10px 14px;font-size:20px;color:#aaa;letter-spacing:4px">···</div>';
  } else {
    // Extrair marcadores de navegação [[IR:destino]] → botões clicáveis (lista branca)
    var _botoes = '';
    var _raw = String(texto).replace(/\[\[IR:([a-z0-9\-]+)\]\]/gi, function(m, rid){
      var r = CENA_AJUDA_ROTAS[(rid||'').toLowerCase()];
      if(r){
        _botoes += '<button onclick="cenaAjudaNavegar(\''+rid.toLowerCase()+'\')" '
          +'style="margin-top:8px;display:block;width:100%;text-align:left;background:#185FA5;color:#fff;'
          +'border:none;border-radius:8px;padding:8px 12px;font-size:12px;font-weight:600;cursor:pointer">'
          +'📍 Abrir '+_escapeHtml(r.label)+' →</button>';
      }
      return '';
    });
    // Formatar resposta: negrito para **texto**
    var html = _escapeHtml(_raw)
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/\n(\d+)\. /g, '<br><span style="color:#185FA5;font-weight:700">$1.</span> ')
      .replace(/\n- /g, '<br>• ')
      .replace(/\n/g, '<br>')
      + _botoes;
    div.innerHTML = '<div style="width:28px;height:28px;background:#1a1a18;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">🤖</div>'
      +'<div style="background:#f5f5f3;border-radius:12px 12px 12px 2px;padding:10px 14px;font-size:13px;color:#1a1a18;max-width:280px;line-height:1.6">'+html+'</div>';
  }

  msgs.appendChild(div);
  msgs.scrollTop = msgs.scrollHeight;
}

function _escapeHtml(text){
  return String(text==null?'':text).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

