function cenaAjudaNavegar(id){
  var rota = CENA_AJUDA_ROTAS[(id||'').toLowerCase()];
  if(!rota){ console.warn('cenaAjudaNavegar: destino desconhecido:', id); return; }
  try{ if(typeof cenaAjudaFechar==='function') cenaAjudaFechar(); }catch(e){}
  try{ rota.fn(); }catch(e){ console.error('cenaAjudaNavegar erro:', e); }
}

