// ── WhatsApp Programação ─────────────────────────────────
function enviarWhatsAppProg(eqId, data){
  var eq=equipes_disp.find(function(e){return e.id===eqId;});
  if(!eq)return;
  var comp=composicao_dia.find(function(c){return c.equipe_id===eqId&&c.data===data;});
  if(!comp){alert('Equipe sem programacao para enviar.');return;}
  var tipo=tipos_equipe.find(function(t){return t.id===eq.tipo_id;});
  var tNome=tipo?tipo.nome:'';
  var ids=parseColabIds(comp.colaborador_ids)
  var cols=ids.map(function(cid){var col=colaboradores.find(function(x){return x.id===cid;});return col?col.nome:'Colaborador';});
  var urlSistema=window.location.href.split('?')[0];
  var dataFmt=fmtD(data);
  var ds=['Domingo','Segunda','Terca','Quarta','Quinta','Sexta','Sabado'];
  var diaSemana=ds[new Date(data+'T12:00:00').getDay()];
  var NL='%0A';var B='*';
  var msg=B+'CENA - Programacao do Dia'+B+NL+NL;
  msg+='Data: '+B+diaSemana+', '+dataFmt+B+NL;
  msg+='Equipe: '+B+eq.codigo+(tNome?' ('+tNome+')':'')+' - '+(comp.turno||'Manha')+B+NL+NL;
  if(cols.length){msg+=B+'Composicao:'+B+NL;cols.forEach(function(n,i){msg+=(i+1)+'. '+n+NL;});msg+=NL;}
  msg+='Acesse o sistema:'+NL+urlSistema+NL+'Faca login e registre seu turno.';
  window.open('https://wa.me/?text='+msg,'_blank');
}

function enviarWhatsAppTodos(){
  var cid=(document.getElementById('fil-prog-cont')||{}).value||'';
  var data=(document.getElementById('fil-prog-data')||{}).value||dataHojeLocal();
  var eqs=equipes_disp.filter(function(e){return e.status==='Ativo'&&(!cid||e.contrato_id===cid);});
  var comps=eqs.filter(function(eq){return composicao_dia.some(function(c){return c.equipe_id===eq.id&&c.data===data;});});
  if(!comps.length){alert('Nenhuma equipe programada para enviar.');return;}
  var tipo_map={};tipos_equipe.forEach(function(t){tipo_map[t.id]=t.nome;});
  var dataFmt=fmtD(data);
  var ds=['Domingo','Segunda','Terca','Quarta','Quinta','Sexta','Sabado'];
  var diaSemana=ds[new Date(data+'T12:00:00').getDay()];
  var urlSistema=window.location.href.split('?')[0];
  var NL='%0A';var B='*';
  var msg=B+'CENA - Programacao do Dia'+B+NL;
  msg+='Data: '+B+diaSemana+', '+dataFmt+B+NL;
  msg+=comps.length+' equipe(s) programada(s)'+NL+NL;
  comps.forEach(function(eq){
    var comp=composicao_dia.find(function(c){return c.equipe_id===eq.id&&c.data===data;});
    var ids=parseColabIds(comp.colaborador_ids)
    var cols=ids.map(function(cid){var col=colaboradores.find(function(x){return x.id===cid;});return col?col.nome:'Colaborador';});
    msg+=B+eq.codigo+B+(tipo_map[eq.tipo_id]?' ('+tipo_map[eq.tipo_id]+')':'')+' - '+(comp.turno||'Manha')+NL;
    cols.forEach(function(n){msg+='- '+n+NL;});
    msg+=NL;
  });
  msg+='Acesse: '+urlSistema+NL+'Faca login e registre seu turno.';
  window.open('https://wa.me/?text='+msg,'_blank');
}



