function mostrarVersao(){
  var html='<div class="modal-bg"><div class="modal" style="max-width:540px;max-height:88vh;display:flex;flex-direction:column;overflow:hidden">'
    // Header fixo
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem;flex-shrink:0">'
    +'<h3 style="margin:0">🏷 Histórico de versões</h3>'
    +'<button class="btn btn-sm" onclick="closeModal()">✕ Fechar</button>'
    +'</div>'
    // Card versão atual fixo
    +'<div style="background:#1a1a18;color:#fff;border-radius:10px;padding:.75rem 1rem;margin-bottom:.75rem;flex-shrink:0">'
    +'<div style="display:flex;justify-content:space-between;align-items:center">'
    +'<div><div style="font-size:22px;font-weight:700">v'+APP_VERSAO.numero+'</div>'
    +'<div style="font-size:11px;opacity:.6">Build '+APP_VERSAO.build+'</div></div>'
    +'<div style="text-align:right"><div style="font-size:11px;opacity:.6">Última atualização</div>'
    +'<div style="font-size:13px;font-weight:600">'+APP_VERSAO.data+'</div></div>'
    +'</div></div>'
    // Área com scroll — mais novo primeiro
    +'<div style="overflow-y:auto;flex:1;padding-right:4px">'
    +APP_VERSAO.log.map(function(v, i){
      return '<div style="margin-bottom:.6rem;border:.5px solid #e0dfd8;border-radius:8px;overflow:hidden">'
        +'<div style="background:'+(i===0?'#EAF3DE':'#f9f9f7')+';padding:.45rem .75rem;display:flex;justify-content:space-between;align-items:center">'
        +'<div style="display:flex;align-items:center;gap:8px">'
        +'<span style="font-weight:700;color:'+(i===0?'#3B6D11':'#555')+'">v'+v.v+'</span>'
        +(i===0?'<span style="font-size:10px;background:#3B6D11;color:#fff;padding:1px 7px;border-radius:20px">ATUAL</span>':'')
        +'</div>'
        +'<span style="font-size:11px;color:#888">'+v.d+'</span>'
        +'</div>'
        +'<ul style="margin:0;padding:.45rem .75rem .45rem 1.5rem;font-size:12px;color:#555">'
        +v.itens.map(function(item){ return '<li style="padding:1px 0">'+item+'</li>'; }).join('')
        +'</ul></div>';
    }).join('')
    +'</div>'
    +'</div></div>';
  setModal(html);
  setTimeout(function(){
    document.querySelectorAll('.mn-full-btn').forEach(function(btn){
      btn.onclick=function(){
        closeModal();
        var i=parseInt(this.getAttribute('data-mi'));
        if(itensMenu[i]) itensMenu[i].acao();
      };
    });
    // Bind do campo data de retorno
    var inpData=document.getElementById('retorno-data');
    if(inpData){
      var _orig=inpData.getAttribute('data-original')||'';
      inpData.addEventListener('change',function(){ progVerificarMudancaData(this,_orig); });
    }
  },50);
}

// ══ ESCALAS MODELO ═══════════════════════════════════════════

var _CORES_MODELO = {
  amarelo: { label:'Amarelo', bg:'#FFF9C4', cor:'#856400', border:'#FFD700', emoji:'🟡' },
  verde:   { label:'Verde',   bg:'#E8F5E9', cor:'#2E7D32', border:'#66BB6A', emoji:'🟢' },
  azul:    { label:'Azul',    bg:'#E3F2FD', cor:'#1565C0', border:'#42A5F5', emoji:'🔵' }
};

async function escalasModeloCarregar(){
  if(_modelosCarregados) return;
  try{
    var rows = await sbFetch('escalas_modelo', {filters:[], limit:10});
    if(rows && rows.length){
      rows.forEach(function(r){
        if(_modelos[r.cor]) _modelos[r.cor] = r.composicao||{};
      });
    }
    _modelosCarregados = true;
  } catch(e){ console.warn('escalasModelo carregar erro:', e); }
}

function escalasModeloAbrir(){
  escalasModeloCarregar().then(function(){ escalasModeloRenderPainel(); });
}

function escalasModeloRenderPainel(){
  var html = '<div id="em-overlay" style="position:fixed;top:0;left:0;width:100%;height:100%;background:#f5f5f3;z-index:3000;display:flex;flex-direction:column;overflow:hidden">'
    // Header
    +'<div style="background:#1a1a18;color:#fff;padding:10px 16px;display:flex;align-items:center;gap:12px;flex-shrink:0">'
    +'<span style="font-size:16px;font-weight:700">🗓 Escalas Modelo</span>'
    +'<span style="font-size:12px;opacity:.6;flex:1">Defina as equipes padrão por cor de folga — implante com um clique</span>'
    +'<button onclick="escalasModeloFechar()" style="background:none;border:none;color:#fff;font-size:20px;cursor:pointer;line-height:1;padding:0 4px">✕</button>'
    +'</div>'
    // Tabs das cores
    +'<div style="background:#fff;border-bottom:1px solid #e0dfd8;padding:0 16px;display:flex;gap:0;flex-shrink:0">'
    +Object.keys(_CORES_MODELO).map(function(cor){
        var c=_CORES_MODELO[cor];
        var ativo = cor===(_modeloEditandoCor||'amarelo');
        return '<button onclick="escalasModeloAbaSelecionar(\''+cor+'\')" '
          +'style="padding:10px 20px;border:none;border-bottom:3px solid '+(ativo?c.border:'transparent')+';background:none;font-size:13px;font-weight:'+(ativo?'700':'500')+';color:'+(ativo?c.cor:'#555')+';cursor:pointer">'
          +c.emoji+' '+c.label+'</button>';
      }).join('')
    +'</div>'
    // Corpo (grid + pool)
    +'<div style="flex:1;display:flex;gap:0;overflow:hidden">'
    // Pool lateral
    +'<div id="em-pool" style="width:200px;flex-shrink:0;background:#fff;border-right:1px solid #e0dfd8;display:flex;flex-direction:column;overflow:hidden">'
    +'<div style="padding:8px;border-bottom:.5px solid #e0dfd8;flex-shrink:0">'
    +'<input id="em-busca" class="inp" placeholder="🔍 Colaborador..." style="width:100%;font-size:12px" oninput="escalasModeloFiltrarPool()">'
    +'</div>'
    +'<div id="em-pool-lista" style="flex:1;overflow-y:auto;padding:6px"></div>'
    +'</div>'
    // Grid de equipes
    +'<div id="em-grid" style="flex:1;overflow:auto;padding:12px"></div>'
    +'</div>'
    // Footer
    +'<div style="background:#fff;border-top:1px solid #e0dfd8;padding:10px 16px;display:flex;gap:8px;justify-content:flex-end;flex-shrink:0">'
    +'<button class="btn" onclick="escalasModeloFechar()">✕ Fechar</button>'
    +'<button class="btn btn-pri" onclick="escalasModeloSalvar()" style="background:#3B6D11;border-color:#3B6D11">💾 Salvar Modelo</button>'
    +'</div>'
    +'</div>';

  var div = document.createElement('div');
  div.id = 'em-overlay-wrap';
  div.innerHTML = html;
  document.body.appendChild(div);

  if(!_modeloEditandoCor) _modeloEditandoCor = 'amarelo';
  escalasModeloRenderGrid(_modeloEditandoCor);
  escalasModeloRenderPool(_modeloEditandoCor);
}

function escalasModeloFechar(){
  var w = document.getElementById('em-overlay-wrap');
  if(w) w.remove();
}

function escalasModeloAbaSelecionar(cor){
  _modeloEditandoCor = cor;
  escalasModeloRenderGrid(cor);
  escalasModeloRenderPool(cor);
  // Update tab highlight
  var tabs = document.querySelectorAll('#em-overlay [onclick^="escalasModeloAbaSelecionar"]');
  tabs.forEach(function(btn){
    var btnCor = btn.getAttribute('onclick').replace("escalasModeloAbaSelecionar('","").replace("')","");
    var c = _CORES_MODELO[btnCor];
    var ativo = btnCor===cor;
    btn.style.borderBottomColor = ativo ? c.border : 'transparent';
    btn.style.fontWeight = ativo ? '700' : '500';
    btn.style.color = ativo ? c.cor : '#555';
  });
}

function escalasModeloRenderGrid(cor){
  var grid = document.getElementById('em-grid');
  if(!grid) return;
  var modelo = _modelos[cor]||{};
  var cid = progGetCont ? progGetCont() : (_progContrato||'');
  var c = _CORES_MODELO[cor];

  var equipes = (equipes_disp||[]).filter(function(e){
    return (!cid||e.contrato_id===cid) && e.status==='Ativo';
  });
  if(!equipes.length){ grid.innerHTML='<div style="padding:2rem;color:#888;text-align:center">Nenhuma equipe encontrada para este contrato.</div>'; return; }

  // Opções de veículos e celulares do contrato
  var veics = (frt_veiculos||[]).filter(function(v){
    return (!cid||v.contrato_id===cid) && (v.status||'').toLowerCase().indexOf('dispon')>=0;
  });
  var cels = celularesDoContrato(cid);

  var html = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px">';
  equipes.forEach(function(eq){
    var entry = modelo[eq.id] || { ids:[null,null], veiculo_id:null, celular_id:null };
    if(Array.isArray(entry)) entry = { ids:entry, veiculo_id:null, celular_id:null };
    var slots = entry.ids || [null,null];
    while(slots.length<2) slots.push(null);

    var veicOpts = '<option value="">— sem veículo —</option>'
      + veics.map(function(v){ return '<option value="'+v.id+'"'+(entry.veiculo_id===v.id?' selected':'')+'>'+escHtml(v.placa+(v.modelo?' '+v.modelo:''))+'</option>'; }).join('');
    var celOpts = '<option value="">— sem celular —</option>'
      + cels.map(function(cl){ return '<option value="'+cl.id+'"'+(entry.celular_id===cl.id?' selected':'')+'>'+escHtml(cl.numero+(cl.modelo?' '+cl.modelo:''))+'</option>'; }).join('');

    html += '<div style="background:#fff;border:1.5px solid #e0dfd8;border-radius:8px;overflow:hidden">'
      // Cabeçalho equipe
      +'<div style="background:#1a1a18;color:#fff;padding:6px 10px;font-size:12px;font-weight:700;display:flex;justify-content:space-between;align-items:center">'
      +'<span>'+escHtml(eq.codigo||eq.nome||'')+'</span>'
      +'<span style="font-size:10px;opacity:.6">'+(eq.hora_inicio||'')+(eq.hora_fim?' – '+eq.hora_fim:'')+'</span>'
      +'</div>'
      // Slots T1/T2
      +'<div style="padding:6px;display:flex;gap:6px">';

    [0,1].forEach(function(pos){
      var cId = slots[pos]||null;
      var col = cId ? (colaboradores||[]).find(function(x){return x.id===cId;}) : null;
      if(col){
        html += '<div style="flex:1;background:'+c.bg+';border:1.5px solid '+c.border+';border-radius:6px;padding:4px 6px;position:relative" '
          +'ondragover="event.preventDefault()" ondrop="escalasModeloDrop(event,\''+eq.id+'\','+pos+')">'
          +'<div style="font-size:11px;font-weight:600;color:'+c.cor+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-right:14px">'+escHtml(col.nome||'')+'</div>'
          +'<div style="font-size:9px;color:#888">RE '+(col.re||'—')+'</div>'
          +'<div style="position:absolute;top:2px;right:4px;font-size:13px;cursor:pointer;color:#A32D2D;font-weight:700;line-height:1" '
          +'onclick="escalasModeloRemover(\''+eq.id+'\','+pos+')">✕</div>'
          +'</div>';
      } else {
        html += '<div style="flex:1;border:1.5px dashed #ccc;border-radius:6px;padding:4px 6px;text-align:center;color:#aaa;font-size:11px;cursor:pointer;min-height:44px;display:flex;align-items:center;justify-content:center" '
          +'ondragover="event.preventDefault()" ondrop="escalasModeloDrop(event,\''+eq.id+'\','+pos+')" '
          +'onclick="escalasModeloBuscarParaSlot(\''+eq.id+'\','+pos+')">'
          +'<span>T'+(pos+1)+'</span>'
          +'</div>';
      }
    });

    html += '</div>'
      // Veículo + Celular
      +'<div style="padding:0 6px 6px 6px;display:flex;gap:6px">'
      +'<div style="flex:1">'
      +'<div style="font-size:9px;color:#888;margin-bottom:2px">🚗 Veículo</div>'
      +'<select class="inp" style="width:100%;font-size:11px;padding:3px 5px" '
      +'onchange="escalasModeloSetVeiculo(\''+eq.id+'\',this.value)">'+veicOpts+'</select>'
      +'</div>'
      +'<div style="flex:1">'
      +'<div style="font-size:9px;color:#888;margin-bottom:2px">📱 Celular</div>'
      +'<select class="inp" style="width:100%;font-size:11px;padding:3px 5px" '
      +'onchange="escalasModeloSetCelular(\''+eq.id+'\',this.value)">'+celOpts+'</select>'
      +'</div>'
      +'</div>'
      +'</div>';
  });
  html += '</div>';
  grid.innerHTML = html;
}

function escalasModeloRenderPool(cor){
  var lista = document.getElementById('em-pool-lista');
  if(!lista) return;
  var cid = progGetCont ? progGetCont() : (_progContrato||'');
  var busca = ((document.getElementById('em-busca')||{}).value||'').toLowerCase();
  var modelo = _modelos[cor]||{};
  var jaUsados = {};
  Object.values(modelo).forEach(function(entry){ var ids=Array.isArray(entry)?entry:(entry.ids||[]); ids.forEach(function(id){if(id)jaUsados[id]=true;}); });
  var BLOQ = ['ferias','afastado','treinamento','demitido','fraude','falta','verificar','inapto'];

  var cols = (colaboradores||[]).filter(function(c){
    if(c.ativo===false||c.dispensado) return false;
    if(cid && c.contrato_id!==cid) return false;
    var st = (_progStatus||{})[c.id]||'';
    if(st && BLOQ.indexOf(st)>=0) return false;
    if(busca && !(c.nome||'').toLowerCase().includes(busca) && !(c.re||'').includes(busca)) return false;
    return true;
  });

  if(!cols.length){ lista.innerHTML='<div style="padding:8px;color:#aaa;font-size:11px;text-align:center">Sem colaboradores</div>'; return; }

  var corInfo = _CORES_MODELO[cor]||{bg:'#f5f5f5',cor:'#333',border:'#ccc',emoji:'⬜'};
  var folguistas = cols.filter(function(c){ return (c.cor_escala||'').toLowerCase()===cor; });
  var outros = cols.filter(function(c){ return (c.cor_escala||'').toLowerCase()!==cor; });

  function renderCard(c, isFolg){
    var usado = jaUsados[c.id];
    var bg = usado ? '#f0f8e8' : (isFolg ? corInfo.bg : '#fafaf8');
    var borderColor = usado ? '#8BC34A' : (isFolg ? corInfo.border : '#e0dfd8');
    var nameColor = usado ? '#3B6D11' : (isFolg ? corInfo.cor : '#333');
    return '<div draggable="true" data-colab-id="'+c.id+'" '
      +'ondragstart="escalasModeloDragStart(event,\''+c.id+'\')" '
      +'style="padding:5px 8px;margin-bottom:3px;background:'+bg+';border:.5px solid '+borderColor+';border-radius:5px;cursor:grab;font-size:11px">'
      +'<div style="font-weight:600;color:'+nameColor+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+(usado?'✓ ':'')+(isFolg&&!usado?corInfo.emoji+' ':'')+escHtml(c.nome||'')+'</div>'
      +'<div style="font-size:9px;color:#888">RE '+(c.re||'—')+(c.cargo?' · '+c.cargo:'')+'</div>'
      +'</div>';
  }

  var html = '';
  if(folguistas.length){
    html += '<div style="font-size:10px;font-weight:700;color:'+corInfo.cor+';padding:4px 2px 2px;margin-bottom:2px;border-bottom:1px solid '+corInfo.border+'">🏖 Folguistas '+corInfo.label+'</div>';
    html += folguistas.map(function(c){ return renderCard(c,true); }).join('');
  }
  if(outros.length){
    if(folguistas.length) html += '<div style="font-size:10px;font-weight:700;color:#666;padding:6px 2px 2px;margin-top:4px;border-bottom:1px solid #ddd">👤 Disponíveis</div>';
    html += outros.map(function(c){ return renderCard(c,false); }).join('');
  }
  lista.innerHTML = html;
}

function escalasModeloFiltrarPool(){
  escalasModeloRenderPool(_modeloEditandoCor||'amarelo');
}

var _emDragColabId = null;
function escalasModeloDragStart(event, colabId){
  _emDragColabId = colabId;
  event.dataTransfer.setData('text/plain', colabId);
}

function escalasModeloDrop(event, eqId, pos){
  event.preventDefault();
  var colabId = _emDragColabId || event.dataTransfer.getData('text/plain');
  if(!colabId) return;
  escalasModeloAtribuir(eqId, pos, colabId);
}

function escalasModeloAtribuir(eqId, pos, colabId){
  var cor = _modeloEditandoCor||'amarelo';
  if(!_modelos[cor]) _modelos[cor]={};
  var entry = _modelos[cor][eqId];
  if(!entry||Array.isArray(entry)) entry = { ids: Array.isArray(entry)?entry.slice():[null,null], veiculo_id:null, celular_id:null };
  while(entry.ids.length<2) entry.ids.push(null);
  entry.ids[pos] = colabId;
  _modelos[cor][eqId] = entry;
  escalasModeloRenderGrid(cor);
  escalasModeloRenderPool(cor);
}

function escalasModeloSetVeiculo(eqId, veicId){
  var cor = _modeloEditandoCor||'amarelo';
  if(!_modelos[cor]) _modelos[cor]={};
  if(!_modelos[cor][eqId]) _modelos[cor][eqId]={ ids:[null,null], veiculo_id:null, celular_id:null };
  if(Array.isArray(_modelos[cor][eqId])) _modelos[cor][eqId]={ ids:_modelos[cor][eqId].slice(), veiculo_id:null, celular_id:null };
  _modelos[cor][eqId].veiculo_id = veicId||null;
}

function escalasModeloSetCelular(eqId, celId){
  var cor = _modeloEditandoCor||'amarelo';
  if(!_modelos[cor]) _modelos[cor]={};
  if(!_modelos[cor][eqId]) _modelos[cor][eqId]={ ids:[null,null], veiculo_id:null, celular_id:null };
  if(Array.isArray(_modelos[cor][eqId])) _modelos[cor][eqId]={ ids:_modelos[cor][eqId].slice(), veiculo_id:null, celular_id:null };
  _modelos[cor][eqId].celular_id = celId||null;
}


function escalasModeloRemover(eqId, pos){
  var cor = _modeloEditandoCor||'amarelo';
  if(!_modelos[cor]||!_modelos[cor][eqId]) return;
  var entry = _modelos[cor][eqId];
  if(Array.isArray(entry)) entry = { ids:entry.slice(), veiculo_id:null, celular_id:null };
  entry.ids[pos] = null;
  if(!entry.ids[0]&&!entry.ids[1]&&!entry.veiculo_id&&!entry.celular_id) delete _modelos[cor][eqId];
  else _modelos[cor][eqId] = entry;
  escalasModeloRenderGrid(cor);
  escalasModeloRenderPool(cor);
}


function escalasModeloBuscarParaSlot(eqId, pos){
  var cor = _modeloEditandoCor||'amarelo';
  var cid = progGetCont ? progGetCont() : (_progContrato||'');
  var busca = '';
  var cols = (colaboradores||[]).filter(function(c){ return c.ativo!==false && !c.dispensado && (!cid||c.contrato_id===cid); });

  function renderLista(q){
    var fil = q ? cols.filter(function(c){ return (c.nome||'').toLowerCase().includes(q)||(c.re||'').includes(q); }) : cols.slice(0,30);
    return fil.map(function(c){
      return '<div onclick="escalasModeloAtribuir(\''+eqId+'\','+pos+',\''+c.id+'\');closeModal()" '
        +'style="padding:6px 8px;cursor:pointer;border-radius:5px;margin-bottom:2px;background:#fafaf8;border:.5px solid #e0dfd8">'
        +'<div style="font-size:12px;font-weight:600">'+escHtml(c.nome||'')+'</div>'
        +'<div style="font-size:10px;color:#888">RE '+(c.re||'—')+(c.cargo?' · '+c.cargo:'')+'</div>'
        +'</div>';
    }).join('') || '<div style="color:#aaa;font-size:12px;padding:8px">Nenhum encontrado</div>';
  }

  var eq = (equipes_disp||[]).find(function(e){return e.id===eqId;})||{};
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:340px">'
    +'<div style="font-size:13px;font-weight:700;margin-bottom:.5rem">Selecionar — '+escHtml(eq.codigo||'')+'  T'+(pos+1)+'</div>'
    +'<input id="em-slot-busca" class="inp" style="width:100%;margin-bottom:8px" placeholder="Buscar colaborador..." oninput="document.getElementById(\'em-slot-lista\').innerHTML=escalasModeloBuscarRender(\''+eqId+'\','+pos+',this.value)">'
    +'<div id="em-slot-lista" style="max-height:300px;overflow-y:auto">'+renderLista('')+'</div>'
    +'<button class="btn" onclick="closeModal()" style="width:100%;margin-top:8px">Cancelar</button>'
    +'</div></div>');
}

function escalasModeloBuscarRender(eqId, pos, q){
  var cor = _modeloEditandoCor||'amarelo';
  var cid = progGetCont ? progGetCont() : (_progContrato||'');
  var cols = (colaboradores||[]).filter(function(c){ return c.ativo!==false && !c.dispensado && (!cid||c.contrato_id===cid); });
  q = (q||'').toLowerCase();
  var fil = q ? cols.filter(function(c){ return (c.nome||'').toLowerCase().includes(q)||(c.re||'').includes(q); }) : cols.slice(0,30);
  return fil.map(function(c){
    return '<div onclick="escalasModeloAtribuir(\''+eqId+'\','+pos+',\''+c.id+'\');closeModal()" '
      +'style="padding:6px 8px;cursor:pointer;border-radius:5px;margin-bottom:2px;background:#fafaf8;border:.5px solid #e0dfd8">'
      +'<div style="font-size:12px;font-weight:600">'+escHtml(c.nome||'')+'</div>'
      +'<div style="font-size:10px;color:#888">RE '+(c.re||'—')+(c.cargo?' · '+c.cargo:'')+'</div>'
      +'</div>';
  }).join('') || '<div style="color:#aaa;font-size:12px;padding:8px">Nenhum encontrado</div>';
}

async function escalasModeloSalvar(){
  var cor = _modeloEditandoCor||'amarelo';
  var modelo = _modelos[cor]||{};
  progShowToast('💾 Salvando modelo '+cor+'...');
  try{
    var rows = await sbFetch('escalas_modelo',{filters:['cor=eq.'+cor],limit:1});
    if(rows&&rows.length){
      await sbUpdate('escalas_modelo',{composicao:modelo},'cor=eq.'+cor);
    } else {
      await sbInsert('escalas_modelo',{cor:cor,composicao:modelo});
    }
    progShowToast('✅ Modelo '+cor+' salvo!');
  } catch(e){
    progShowToast('❌ Erro ao salvar: '+e.message);
  }
}

function escalasModeloImplantar(){
  var data = progGetData ? progGetData() : '';
  if(!data){ progShowToast('Selecione uma data na programação.'); return; }
  if(data < dataHojeLocal()){ progShowToast('⛔ Escala modelo só pode ser implantada em hoje ou datas futuras.','erro'); return; }
  var corDia = (_calDados&&_calDados[data])||CAL_CORES_2026[data]||'';
  if(!corDia){ progShowToast('⚠ Este dia não tem cor de folga no calendário. Selecione um modelo manualmente.'); escalasModeloAbrirImplantar(data); return; }
  escalasModeloAbrirImplantar(data, corDia);
}

function escalasModeloAbrirImplantar(data, corSugerida){
  if(data < dataHojeLocal()){ progShowToast('⛔ Escala modelo só pode ser implantada em hoje ou datas futuras.','erro'); return; }
  var dataBR = (data||'').split('-').reverse().join('/');
  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:380px">'
    +'<div style="font-size:15px;font-weight:700;margin-bottom:.5rem">⚡ Implantar Escala Modelo</div>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.85rem">Data: <b>'+dataBR+'</b>'+(corSugerida?' · Cor do dia: <b>'+corSugerida+'</b>':'')+'</div>'
    +'<div class="fg" style="margin-bottom:.85rem">'
    +'<label style="font-size:11px;font-weight:500">Qual modelo implantar?</label>'
    +'<select id="imp-cor" class="inp" style="width:100%">'
    +Object.keys(_CORES_MODELO).map(function(c){
        var cc=_CORES_MODELO[c];
        var eqs=Object.keys(_modelos[c]||{}).length;
        return '<option value="'+c+'" '+(c===corSugerida?'selected':'')+'>'+cc.emoji+' '+cc.label+' ('+eqs+' equipes)</option>';
      }).join('')
    +'</select>'
    +'</div>'
    +'<div style="background:#FEF3E2;border-radius:8px;padding:10px 12px;font-size:12px;color:#854F0B;margin-bottom:.85rem">'
    +'⚠ As equipes que já têm composição salva para este dia não serão sobrescritas.'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="imp-conf" style="flex:2">⚡ Implantar</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var btn=document.getElementById('imp-conf');
    if(!btn) return;
    btn.onclick=function(){
      var cor=(document.getElementById('imp-cor')||{}).value||'amarelo';
      closeModal();
      escalasModeloAplicar(data, cor);
    };
  },50);
}

function escalasModeloAplicar(data, cor, sobrescrever){
  if(data < dataHojeLocal()){ progShowToast('⛔ Não é possível implantar modelo em data passada ('+(data||'').split('-').reverse().join('/')+').','erro'); return; }
  var modelo = _modelos[cor]||{};
  var eqIds = Object.keys(modelo);
  if(!eqIds.length){ progShowToast('Modelo '+cor+' está vazio. Edite-o primeiro.'); return; }

  // Mapear quais já têm membros salvos
  var comMembroIds = eqIds.filter(function(eqId){
    return composicao_dia.find(function(c){
      if(c.equipe_id!==eqId||c.data!==data||c.deleted_at) return false;
      return parseColabIds(c.colaborador_ids).filter(Boolean).length>0;
    });
  });

  // Se há equipes com membros e ainda não decidimos, perguntar
  if(comMembroIds.length && sobrescrever===undefined){
    var corInfo = _CORES_MODELO[cor]||{emoji:'',label:cor};
    var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
      +'<div class="modal" style="max-width:370px">'
      +'<div style="font-size:15px;font-weight:700;margin-bottom:.5rem">⚡ Confirmar Implantação</div>'
      +'<div style="font-size:12px;color:#555;margin-bottom:.85rem">'
      +corInfo.emoji+' Modelo <b>'+corInfo.label+'</b> · '+eqIds.length+' equipe(s)</div>'
      +'<div style="background:#FEF3E2;border-radius:8px;padding:10px 12px;font-size:12px;color:#854F0B;margin-bottom:.85rem">'
      +'⚠ <b>'+comMembroIds.length+' equipe(s)</b> já têm colaboradores escalados neste dia.<br>'
      +'O que deseja fazer?</div>'
      +'<div style="display:flex;flex-direction:column;gap:8px">'
      +'<button class="btn btn-pri" onclick="closeModal();escalasModeloAplicar(\''+data+'\',\''+cor+'\',true)" style="font-size:12px">🔄 Sobrescrever todas ('+eqIds.length+')</button>'
      +'<button class="btn" onclick="closeModal();escalasModeloAplicar(\''+data+'\',\''+cor+'\',false)" style="font-size:12px">⏭ Pular as que já têm · aplicar só as vazias ('+(eqIds.length-comMembroIds.length)+')</button>'
      +'<button class="btn" onclick="closeModal()" style="font-size:12px;color:#999">Cancelar</button>'
      +'</div></div></div>';
    setModal(html);
    return;
  }

  var aplicados=0, pulados=0;
  eqIds.forEach(function(eqId){
    var entry = modelo[eqId]||{};
    var ids = Array.isArray(entry)?[entry[0]||null,entry[1]||null]:[(entry.ids||[])[0]||null,(entry.ids||[])[1]||null];
    var veicId = Array.isArray(entry)?null:(entry.veiculo_id||null);
    var celId  = Array.isArray(entry)?null:(entry.celular_id||null);

    var jaExiste = composicao_dia.find(function(c){
      if(c.equipe_id!==eqId||c.data!==data||c.deleted_at) return false;
      return parseColabIds(c.colaborador_ids).filter(Boolean).length>0;
    });
    if(jaExiste && !sobrescrever){ pulados++; return; }

    aplicados++;
    var payload = {colaborador_ids:ids,turno:'Manha',confirmada:false};
    if(veicId) payload.veiculo_id=veicId;
    if(celId)  payload.celular_id=celId;

    var comp = composicao_dia.find(function(c){return c.equipe_id===eqId&&c.data===data&&!c.deleted_at;});
    if(comp){
      Object.assign(comp, payload);
      comp.colaborador_ids = JSON.stringify(ids);
      if(!DEMO) sbUpdate('composicao_dia', payload, 'id=eq.'+comp.id);
    } else {
      var nova=Object.assign({id:'local_'+eqId+'_'+data,equipe_id:eqId,data:data,_local:true},payload);
      composicao_dia.push(nova);
      if(!DEMO) sbInsert('composicao_dia',Object.assign({equipe_id:eqId,data:data},payload))
        .then(function(r){if(r&&r[0]){nova.id=r[0].id;nova._local=false;}});
    }
  });
  progRenderQuadro();
  var msg = '✅ Modelo '+(_CORES_MODELO[cor]||{label:cor}).label+' implantado: '+aplicados+' equipe(s)';
  if(pulados) msg += ' · '+pulados+' pulada(s) (já tinham membros)';
  progShowToast(msg);
}

// Mostrar/ocultar botão de implantação conforme cor do dia
function escalasModeloAtualizarBtnImplantar(){
  var btn=document.getElementById('btn-implantar-modelo');
  if(!btn) return;
  var data=progGetData?progGetData():'';
  var corDia=data?((_calDados&&_calDados[data])||CAL_CORES_2026[data]||''):'';
  var futuro = data && data>=dataHojeLocal();
  btn.style.display=(corDia&&futuro)?'':'none';
  if(corDia&&futuro){
    var c=_CORES_MODELO[corDia]||{};
    btn.textContent='⚡ Implantar '+(c.emoji||'')+' '+corDia.charAt(0).toUpperCase()+corDia.slice(1);
    btn.style.color=c.cor||'#533AB7';
    btn.style.borderColor=(c.cor||'#533AB7')+'88';
    btn.onclick=function(){ escalasModeloAbrirImplantar(data, corDia); };
  }
}
// ══ MÓDULO PROGRAMAÇÃO DE EQUIPES ════════════════════════════
// Variáveis de estado
var _progData          = null;  // data selecionada (YYYY-MM-DD)
var _progContrato      = null;  // contrato selecionado
var _progTipoFiltro    = '';    // tipo de equipe filtro
var _progStatus        = {};    // {colabId: 'disponivel'|'falta'|'folga'|...}
var _progStatusInfo    = {};    // {colabId: {retorno:'YYYY-MM-DD'}}
var _progOverrides     = {};    // {data_eqId: [colabId1, colabId2]}
var _progFiltroColab   = '';    // busca por colaborador
var _progSoIncompletas = false; // mostrar só equipes incompletas
var _progSoProgramadas = false; // mostrar só equipes com escala salva (confirmada)
var _progRenderTimer   = null;  // debounce timer
var _dragColabId       = null;  // drag & drop
var _dragFromEquipeId  = null;

/** Escala salva/confirmada no dia (mesma regra do relatório TMA Saída). */
function progCompEstaProgramada(comp){
  if(!comp) return false;
  return comp.confirmada===true || comp.confirmada==='true' || comp.confirmada===1 || comp.confirmada==='t';
}
function progEquipeProgramadaNoDia(eqId, data){
  if(!eqId||!data) return false;
  var d=String(data).split('T')[0];
  var comp=(composicao_dia||[]).find(function(c){
    return String(c.equipe_id)===String(eqId) && String(c.data||'').split('T')[0]===d && !c.deleted_at;
  });
  return progCompEstaProgramada(comp);
}

