function _pontoTemEntrada(p){
  if(!p) return false;
  // Só presença com batida real de entrada — não usa status "presente" nem pré-marcação de almoço
  var h=_pontoExtrairHorarios(p);
  return !!h.entrada;
}
/** Horário de entrada real (já filtra pré-marcação de almoço). */
function _pontoEntradaReal(p, data){
  if(!p) return '';
  return (_pontoExtrairHorarios(p, data)||{}).entrada||'';
}
function _pontoDeveMostrarAusente(p, data){
  if(!p||_pontoTemEntrada(p)) return false;
  if(p.status==='falta'){
    var hoje=dataHoje();
    if(data&&data>hoje) return false;
    var hp=p.horario_previsto||{};
    return !hp.entrada||pontoHorarioPassou(hp,data);
  }
  if(p.status==='sem_registro'){
    var hp2=p.horario_previsto||{};
    return !!(hp2.entrada&&pontoHorarioPassou(hp2,data));
  }
  return false;
}
function _pontoBadgeHtml(p, data, compact){
  if(!p) return '';
  if(_pontoTemEntrada(p)){
    var h=_pontoExtrairHorarios(p, data);
    var lbl=compact?('✓ '+(h.entrada||'')):('✓ Presente'+(h.entrada?' '+h.entrada:''));
    var st=compact?'margin-left:2px;background:#3B6D11;color:#fff;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700':'margin-top:2px;background:#3B6D11;color:#fff;border-radius:4px;padding:1px 6px;font-size:9px;font-weight:700;display:inline-block';
    var html=(compact?'<span':'<div')+' style="'+st+'">'+lbl+(compact?'</span>':'</div>');
    if(h.saida){
      var stS=compact?'margin-left:2px;background:#185FA5;color:#fff;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700':'margin-top:1px;background:#185FA5;color:#fff;border-radius:4px;padding:1px 6px;font-size:9px;font-weight:700;display:inline-block';
      html+=(compact?'<span':'<div')+' style="'+stS+'">'+(compact?'↗ '+h.saida:'↗ Saída '+h.saida)+(compact?'</span>':'</div>');
    }
    return html;
  }
  if(_pontoDeveMostrarAusente(p,data)){
    var st2=compact?'margin-left:2px;background:#A32D2D;color:#fff;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700':'margin-top:2px;background:#A32D2D;color:#fff;border-radius:4px;padding:1px 6px;font-size:9px;font-weight:700;display:inline-block';
    return (compact?'<span':'<div')+' style="'+st2+'">'+(compact?'● Aus':'● Ausente')+(compact?'</span>':'</div>');
  }
  return '';
}

// Invalidar cache para forçar nova consulta
function pontoInvalidarCache(){
  _pontoCache = {};
  console.log('[Ponto] Cache invalidado — nova consulta agendada');
}

// Agendador de ponto
// - Não escalados: consulta a cada 2 minutos (localizar quem está na empresa)
// - Escalados: consulta nos horários fixos
var _pontoTimerNaoEscalados = null;

function pontoIniciarAgendador(){
  // Timer 1: horários fixos — dispara sync em lote via progSyncPonto (sem N requests simultâneos)
  setInterval(function(){
    if(pontoDeveConsultar()){
      var agora = Date.now();
      if(_pontoUltimaConsulta && (agora - _pontoUltimaConsulta) < 4*60*1000) return;
      _pontoUltimaConsulta = agora;
      // Sync controlado em lotes (igual ao botão manual) — atualiza Supabase e depois os badges
      if(typeof progSyncPonto==='function' && !window._progSyncPontoAtivo){
        progSyncPonto({todos:true, automatico:true});
      } else {
        // Se sync já está ativo, apenas recarrega do Supabase
        var _d = typeof progGetData==='function' ? progGetData() : dataHoje();
        if(_d) progCarregarPontoDoSupabase(_d, function(){
          if(typeof progCarregarBadgesPonto==='function') progCarregarBadgesPonto();
        });
      }
    }
  }, 60000);

  // Timer 2: a cada 5 minutos recarrega dados do Supabase (não consulta API diretamente)
  setInterval(function(){
    var data = typeof progGetData==='function' ? progGetData() : dataHoje();
    if(!data) return;
    progCarregarPontoDoSupabase(data, function(){
      if(typeof progCarregarBadgesPonto==='function'){
        progCarregarBadgesPonto();
      }
    });
  }, 5*60*1000); // a cada 5 minutos

  // Timer 3: ping a cada 10 minutos para evitar cold start do Azure App Service
  // Só em landtec/localhost — pages.dev não está no CORS do Azure e o console enchia de erro.
  setInterval(function(){
    if(window.location.protocol==='file:') return;
    var o=window.location.origin||'';
    if(!/^https:\/\/(www\.)?landtec\.com\.br$/i.test(o) && !/^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/i.test(o)) return;
    fetch(pontoApiBase()+'/api/v1/health',{method:'GET',mode:'cors'}).catch(function(){});
  }, 10*60*1000);
}

// Buscar dados de ponto de um colaborador (com cache)
function pontoConsultar(re, data, callback){
  var key = pontoCacheKey(re, data);
  // Cache hit — retornar imediatamente
  if(_pontoCache[key] !== undefined){
    callback(_pontoCache[key]);
    return;
  }
  // Já está carregando — NÃO fazer loop, só registrar callback
  if(_pontoLoading[key]){
    _pontoLoading[key].push(callback);
    return;
  }
  // Iniciar consulta
  _pontoLoading[key] = [callback];
  pontoFetchApi('/api/v1/ponto', {
    method: 'POST',
    body: JSON.stringify({matricula: String(re), data: data})
  })
  .then(function(d){
    pontoCacheSet(re, data, d);
    var cbs = _pontoLoading[key] || [];
    delete _pontoLoading[key];
    cbs.forEach(function(cb){ try{ cb(d); }catch(e){} });
  })
  .catch(function(e){
    console.warn('[Ponto] consulta RE', re, e&&e.message||e);
    pontoCacheSet(re, data, null);
    var cbs = _pontoLoading[key] || [];
    delete _pontoLoading[key];
    cbs.forEach(function(cb){ try{ cb(null); }catch(ex){} });
  });
}

// Verificar se horário de entrada já passou para o colaborador
function pontoHorarioPassou(horarioPrevisto, data){
  if(!horarioPrevisto || !horarioPrevisto.entrada) return false;
  var hoje = dataHoje();
  // Se for dia anterior — sempre passou o horário
  if(data && data < hoje) return true;
  var agora = new Date();
  var partes = horarioPrevisto.entrada.split(':');
  var horaEnt = new Date();
  horaEnt.setHours(parseInt(partes[0]), parseInt(partes[1]), 0, 0);
  // 1 hora de tolerância
  horaEnt.setMinutes(horaEnt.getMinutes() + 60);
  return agora >= horaEnt;
}

// ── PROTEÇÃO DE COMPOSIÇÃO CONFIRMADA ────────────────────────────────────
// Verifica se uma composição está confirmada antes de alterar membros
// Retorna true se pode alterar, false se está bloqueada
function _podeAlterarComposicao(comp, operacao){
  if(!comp) return true;
  if(!comp.confirmada) return true;
  var eq = equipes_disp.find(function(e){ return e.id === comp.equipe_id; });
  var nomeEq = eq ? eq.codigo : 'equipe';
  progShowToast(
    '🔒 <b>'+nomeEq+'</b> está <b>Programada</b> — não é possível '+(operacao||'alterar membros')+'.<br>'+
    'Clique em <b>Desprogramar</b> primeiro para fazer alterações.',
    'erro'
  );
  return false;
}

// Salvar estado atual no cache por data
function _progSalvarCacheDia(data){
  if(!data) return;
  _progStatusPorDia[data] = {
    status: Object.assign({}, _progStatus),
    info:   Object.assign({}, _progStatusInfo)
  };
}
// Restaurar estado do cache para uma data
function _progRestaurarCacheDia(data){
  var cached = _progStatusPorDia[data];
  if(cached){
    _progStatus     = Object.assign({}, cached.status);
    _progStatusInfo = Object.assign({}, cached.info);
    return true;
  }
  return false;
}

function progCarregarStatus(data){
  // Não sobrescrever estado se houve alteração manual recente (evita race condition)
  if(window._progStatusUltimoSave && (Date.now()-window._progStatusUltimoSave) < 5000){
    console.log('[progCarregarStatus] ignorado — save recente (<5s)');
    progRenderQuadro();
    return;
  }
  // Salvar estado do dia anterior no cache antes de trocar
  if(_progData && _progData !== data) _progSalvarCacheDia(_progData);

  // Tentar restaurar do cache em memória (instantâneo, sem hit no banco)
  if(_progRestaurarCacheDia(data)){
    progAplicarPersistentes(data);
    progRenderQuadro();
    // Ainda busca do banco para atualizar, mas não trava a tela
    if(_progStatusDateCache !== data && !DEMO){
      _progStatusDateCache = data; // marcar já para não buscar de novo se voltar rápido
      // Busca silenciosa em background
      Promise.all([
        sbFetch('prog_status_diario', {filters:['data=eq.'+data,'deleted_at=is.null']}),
        sbFetch('prog_status_diario', {
          filters:progFiltrosStatusPersistentes(data),
          order:'data.desc', limit:500
        })
      ]).then(function(res){
        if(res[0]===null) return;
        progAplicarStatusDoBanco(res[0]||[], res[1]||[], data);
        progAplicarPersistentes(data);
        _progSalvarCacheDia(data);
        _progLS.salvarStatus(data);
        progRenderQuadro();
      }).catch(function(){});
    }
    return;
  }

  // RESET completo — cada dia começa limpo
  _progStatus = {}; _progStatusInfo = {};

  // 1. localStorage primeiro (instantâneo — renderiza imediato)
  var saved = _progLS.carregarStatus(data);
  if(saved){
    if(saved.status) _progStatus    = Object.assign({}, saved.status);
    if(saved.info)   _progStatusInfo = Object.assign({}, saved.info);
  }
  Object.keys(_progStatus).forEach(function(id){ if(_progStatus[id]==='faltou') _progStatus[id]='falta'; });
  progAplicarPersistentes(data);
  progRenderQuadro(); // render imediato com localStorage

  // 2. Banco: SE já carregado para esse dia, não buscar de novo
  if(_progStatusDateCache === data) return;

  if(!DEMO){
    // Uma única chamada paralela: status do dia + persistentes ativos
    Promise.all([
      sbFetch('prog_status_diario', {filters:['data=eq.'+data,'deleted_at=is.null']}),
      sbFetch('prog_status_diario', {
        filters:progFiltrosStatusPersistentes(data),
        order:'data.desc', limit:500
      }),
      progFetchVeiculosDia(data)
    ]).then(function(res){
      var rowsDia      = res[0];
      var persistRows  = res[1] || [];
      var veicRows     = res[2] || [];
      // Limpar cache do dia antes de popular — evita veículos fantasma após remoção
      progLimparVeiculosDia(data);
      (veicRows||[]).forEach(function(r){
        if(!r.equipe_id||!r.placa||r.deleted_at) return;
        var key = String(r.slot||'1')==='2'
          ? progVeiculoKeyB(r.equipe_id, r.data||data)
          : progVeiculoKey(r.equipe_id, r.data||data);
        _progVeiculos[key] = {id:r.veiculo_id,placa:r.placa,modelo:r.modelo,
          justificativa:r.justificativa,alterado_por:r.alterado_por};
      });
      progPersistVeiculosLocal(data);
      window._veicEscCache = {};

      if(rowsDia === null){ return; } // erro de API — manter localStorage

      progAplicarStatusDoBanco(rowsDia||[], persistRows||[], data);
      progAplicarPersistentes(data);
      // Atualizar prog_status_<data> localStorage com dados do banco
      try{
        localStorage.setItem('prog_status_'+data,
          JSON.stringify({status:_progStatus, info:_progStatusInfo}));
      }catch(e){}

      // Sincronizar prog_persistentes com o banco — sempre limpar localStorage
      // para refletir o estado real do banco (elimina "fantasmas" de status antigos)
      try{
        var lsPers=JSON.parse(localStorage.getItem('prog_persistentes')||'{}');
        var alterado=false;
        // Construir set de colaboradores que o banco considera ainda em status persistente
        var colabsComStatusBanco={};
        persistRows.forEach(function(r){colabsComStatusBanco[r.colaborador_id]=r.status;});
        rowsDia.forEach(function(r){
          if(PROG_STATUS_PERSISTENTES.indexOf(r.status)>=0)
            colabsComStatusBanco[r.colaborador_id]=r.status;
        });
        Object.keys(_progStatus||{}).forEach(function(id){
          if(PROG_STATUS_PERSISTENTES.indexOf(_progStatus[id])>=0)
            colabsComStatusBanco[id]=_progStatus[id];
        });
        // Só limpa o cache local — não apaga o status já aplicado do banco
        Object.keys(lsPers).forEach(function(colabId){
          if(!colabsComStatusBanco[colabId]){
            delete lsPers[colabId]; alterado=true;
          }
        });
        // Atualizar localStorage para refletir o banco
        if(alterado){
          localStorage.setItem('prog_persistentes',JSON.stringify(lsPers));
          progRenderQuadro();
        }
      }catch(e){}

      _progStatusDateCache = data; // marcar como carregado
      progRenderQuadro();
    }).catch(function(){ progRenderQuadro(); });
  }
}

