/** Normaliza texto/placa para busca (sem acento, sem hífen/espaço). */
function progNormBuscaTxt(s){
  return String(s||'').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[-\s._]/g,'');
}

/** Indica se a equipe casa com a busca atual (escopo colaborador/equipe/placa/status/todos). */
function progEquipeMatchBusca(eq, data, texto, scope){
  if(!texto) return true;
  var q=String(texto).trim().toLowerCase();
  var qNorm=progNormBuscaTxt(texto);
  if(!q) return true;
  scope=scope||'todos';

  var matchEq=false, matchColab=false, matchPlaca=false, matchStatus=false;

  // Equipe (código / nome)
  var cod=String(eq.codigo||'').toLowerCase();
  var nomeEq=String(eq.nome||eq.nome_equipe||'').toLowerCase();
  matchEq = cod.indexOf(q)>=0 || nomeEq.indexOf(q)>=0 || progNormBuscaTxt(cod).indexOf(qNorm)>=0;

  // Colaboradores do dia + vinculados à equipe
  var comp = (typeof progFindCompDia==='function')
    ? progFindCompDia(eq.id, data)
    : (composicao_dia||[]).find(function(c){
        return String(c.equipe_id)===String(eq.id) && String(c.data||'').split('T')[0]===String(data||'').split('T')[0];
      });
  var idsComp=[];
  if(comp){
    idsComp = (typeof parseColabIds==='function')
      ? parseColabIds(comp.colaborador_ids)
      : (Array.isArray(comp.colaborador_ids)?comp.colaborador_ids:[]);
    idsComp = (idsComp||[]).filter(Boolean);
  }
  var todos=[];
  var seen={};
  function _addCol(c){
    if(!c||!c.id||seen[c.id]) return;
    seen[c.id]=true; todos.push(c);
  }
  (colaboradores||[]).forEach(function(c){
    if(String(c.equipe_id)===String(eq.id) && c.ativo!==false) _addCol(c);
  });
  idsComp.forEach(function(id){
    _addCol((colaboradores||[]).find(function(c){ return String(c.id)===String(id); }));
  });

  matchColab = todos.some(function(c){
    var nm=String(c.nome||'').toLowerCase();
    var re=String(c.re||'').toLowerCase();
    return nm.indexOf(q)>=0 || re.indexOf(q)>=0 || progNormBuscaTxt(nm).indexOf(qNorm)>=0;
  });

  // Status (chave + label + alias comum)
  matchStatus = todos.some(function(c){
    var st=String(_progStatus[c.id]||'disponivel').toLowerCase();
    var lab=((PROG_STATUS[st]&&PROG_STATUS[st].label)||st).toLowerCase();
    var labN=progNormBuscaTxt(lab);
    return st.indexOf(q)>=0 || lab.indexOf(q)>=0 || labN.indexOf(qNorm)>=0
      || (qNorm==='faltou'&&st==='falta')
      || (qNorm==='ferias'&&st==='ferias')
      || (qNorm==='disp'&&st==='disponivel');
  });

  // Placa (mapa do dia + composição)
  var veic = (typeof progGetVeiculo==='function') ? progGetVeiculo(eq.id, data) : null;
  var placa = (veic&&veic.placa) || (comp&&(comp.placa||comp.veiculo_placa)) || eq.placa || '';
  var placaB = '';
  if(typeof progGetVeiculoB==='function'){
    var vb=progGetVeiculoB(eq.id, data);
    if(vb&&vb.placa) placaB=vb.placa;
  }
  matchPlaca = progNormBuscaTxt(placa).indexOf(qNorm)>=0
    || (placaB && progNormBuscaTxt(placaB).indexOf(qNorm)>=0);

  if(scope==='colaborador') return matchColab;
  if(scope==='equipe') return matchEq;
  if(scope==='placa') return matchPlaca;
  if(scope==='status') return matchStatus;
  return matchColab || matchEq || matchPlaca || matchStatus;
}

