function progInit(){
  if(typeof _progTmaOpsLastFetch!=='undefined') _progTmaOpsLastFetch='';
  _progData = dataHojeLocal();
  if(window._filtroContrato) _progContrato = window._filtroContrato;
  progAtualizarBadgeContTma();
  var _dataInit = _progData;
  vtAtualizarAbaAlerta(); // Verificar se há pendências de tratamento
  // Fixar cabeçalho via scroll listener
  setTimeout(function(){
    var container = document.getElementById('app-content-area');
    var header    = document.getElementById('prog-header-fixo');
    if(!container || !header) return;
    var headerOffsetTop = null;
    container.addEventListener('scroll', function(){
      if(!header) return;
      if(headerOffsetTop === null){
        headerOffsetTop = header.offsetTop;
      }
      if(container.scrollTop > headerOffsetTop){
        var cRect = container.getBoundingClientRect();
        header.style.position = 'fixed';
        header.style.top = cRect.top + 'px';
        header.style.left = cRect.left + 'px';
        header.style.width = container.clientWidth + 'px';
        header.style.zIndex = '200';
        header.style.boxShadow = '0 4px 16px #0004';
        header.style.borderRadius = '0';
        var ph = document.getElementById('prog-header-placeholder');
        if(ph) ph.style.height = header.offsetHeight + 'px';
      } else {
        header.style.position = '';
        header.style.top = '';
        header.style.left = '';
        header.style.width = '';
        header.style.boxShadow = '';
        header.style.borderRadius = '';
        var ph = document.getElementById('prog-header-placeholder');
        if(ph) ph.style.height = '0';
      }
    }, {passive: true});
  }, 800);
  // Carregar dados de ponto do Supabase ao abrir a programação
  var _dataInit2 = progGetData();
  setTimeout(function(){
    progCarregarPontoDoSupabase(_dataInit2, function(){
      progCarregarBadgesPonto();
    });
  }, 1000);
  // Iniciar agendador de consultas de ponto nos horários definidos
  setTimeout(pontoIniciarAgendador, 2000);
  // Forçar refresh completo na primeira abertura (dados frescos do banco)
  // progAtualizarQuadro já inclui status + veículos + composicao em Promise.all
  setTimeout(function(){
    _progVeiculosDateCache = null;
    progAtualizarQuadro();
  }, 300); // pequeno delay para DOM estar pronto

  // Carregar calendário de escala se ainda não carregado
  if(!Object.keys(_calDados||{}).length){
    _calDados = Object.assign({}, CAL_CORES_2026);
    if(!DEMO){
      sbFetch('calendario_escala',{filters:['data=gte.2026-01-01','data=lte.2026-12-31'],order:'data'})
        .then(function(res){ if(res&&res.length) res.forEach(function(r){ _calDados[r.data]=r.cor; }); })
        .catch(function(){});
    }
  }

  // Carregar frota completa (inclui Baixado) — ativo=eq.true escondia placas baixadas da escala
  if(!DEMO){
    progGarantirFrotaCompleta(function(){
      try{ progRenderQuadro(); }catch(e){}
    });
  }

  var selData = document.getElementById('prog-av-data');
  if(selData) selData.value = _progData;
  progCarregarStatus(_progData);
  progAtualizarPillsTipo();

  // Garantir colaboradores carregados para contratos de disponibilidade
  if(!DEMO){
    var cids = _contratosVisiveis().filter(function(c){
      return (c.modalidade_trabalho||'').toLowerCase().includes('disponibilidade');
    }).map(function(c){return c.id;});
    if(cids.length){
      var cidsSet={}; cids.forEach(function(id){cidsSet[id]=true;});
      var jaTemColabs = colaboradores.some(function(c){return cidsSet[c.contrato_id];});
      if(!jaTemColabs){
        var filtro = cids.length===1 ? 'contrato_id=eq.'+cids[0] : 'contrato_id=in.('+cids.join(',')+')';
        sbFetch('colaboradores',{filters:[filtro,'ativo=eq.true'],order:'nome',limit:500})
          .then(function(rows){
            if(rows&&rows.length) colabMergePreservarInativos(rows);
            progRenderQuadro();
          }).catch(function(){progRenderQuadro();});
        return;
      }
    }
  }
  progRenderQuadro();
}

