function progNavData(dias){
  var el = document.getElementById('prog-av-data');
  if(!el) return;
  var atual = el.value || _progData || dataHojeLocal();
  var anterior = _progData || atual;
  var nova = typeof dataAddDias==='function' ? dataAddDias(atual, dias) : (function(){
    var d=new Date(atual+'T12:00:00'); d.setDate(d.getDate()+dias);
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  })();
  if(!nova || nova===atual){
    // fallback forçado se cálculo falhar
    nova = dataAddDias(atual, dias);
  }
  el.value = nova;
  // Guarda cache do dia anterior antes de trocar _progData
  if(anterior && anterior!==nova && typeof _progSalvarCacheDia==='function'){
    try{ _progSalvarCacheDia(anterior); }catch(eC){}
  }
  _progData = nova;
  _progStatusDateCache = null;
  _progVeiculosDateCache = null;
  progCarregarStatus(nova);
}

