// Sources: {label, table, filters, statusField, statusValue, linkFn}
function notifGetSources(){
  var perfil  = usuarioLogado ? usuarioLogado.perfil : '';
  var isAlmox = perfil==='almoxarife' || (usuarioLogado&&(usuarioLogado.cargo||'').toLowerCase().includes('almox'));
  var isGestor= ['admin','gestor','coordenador'].includes(perfil);

  var sources = [];

  if(isAlmox || isGestor){
    sources.push({label:'📦 Reservas de Materiais',table:'plpt_requisicoes_materiais',
      filters:['status=eq.Aguardando aprovação'],linkId:'reservas-mat',linkLabel:'Ver Reservas'});
  }
  // Solicitações de manutenção aguardando avaliação da equipe frotas
  sources.push({label:'🔧 Solicitações de Manutenção',table:'frotas_manutencoes',
    filters:['status=eq.Solicitada'],linkId:'manutencoes',linkLabel:'Ver Chamados'});

  // Validade periódica (ensaio etc.): vencidas e a vencer em 20 dias
  var hojeVal=typeof dataHojeLocal==='function'?dataHojeLocal():new Date().toISOString().slice(0,10);
  var em20=new Date(hojeVal+'T12:00:00'); em20.setDate(em20.getDate()+20);
  var em20Str=em20.toISOString().slice(0,10);
  sources.push({
    label:'⏰ Manutenção — validade vencida',
    table:'frotas_manutencoes',
    filters:['validade=not.is.null','validade=lt.'+hojeVal],
    order:'validade.asc',
    linkId:'manutencoes',
    linkLabel:'Ver Manutenções'
  });
  sources.push({
    label:'⚠️ Manutenção — validade a vencer (20 dias)',
    table:'frotas_manutencoes',
    filters:['validade=not.is.null','validade=gte.'+hojeVal,'validade=lte.'+em20Str],
    order:'validade.asc',
    linkId:'manutencoes',
    linkLabel:'Ver Manutenções'
  });

  if(isGestor){
    sources.push({label:'📐 Medições Aguardando Aprovação',table:'sot_medicoes',
      filters:['status=eq.em_aprovacao'],linkId:'medicoes',linkLabel:'Ver Medições'});
  }
  if(isGestor){
    sources.push({label:'➕ Adicionais Pendentes',table:'sot_adicionais',
      filters:['status=eq.pendente'],linkId:'adicionais',linkLabel:'Ver Adicionais'});
  }
  if(isGestor){
    sources.push({label:'💰 Lançamentos Financeiros',table:'lancamentos',
      filters:['status=eq.Aguardando aprovação','deleted_at=is.null'],linkId:'lancamentos',linkLabel:'Ver Aprovações'});
  }

  // Transferências de veículos pendentes para os contratos deste gestor
  if(isGestor && usuarioLogado){
    var meusCids = (usuarioLogado.contrato_id||'').split(',').map(function(s){return s.trim();}).filter(Boolean);
    if(meusCids.length){
      // Uma source por contrato para filtrar corretamente
      meusCids.forEach(function(cid){
        var cont = (contratos||[]).find(function(c){return c.id===cid;});
        var nomeC = cont ? (cont.codigo||cont.nome) : 'seu contrato';
        sources.push({
          label:     '🚗 Transferência de Veículo → '+nomeC,
          table:     'frotas_transferencias',
          filters:   ['status=eq.pendente','contrato_destino_id=eq.'+cid],
          order:     'solicitado_em.desc',
          linkId:    'transf-veiculos',
          linkLabel: 'Autorizar'
        });
        sources.push({
          label:     '🔐 Aprovação Frota (placa/status) → '+nomeC,
          table:     'frotas_veiculo_aprovacoes',
          filters:   ['status=eq.pendente','contrato_id=eq.'+cid],
          order:     'solicitado_em.desc',
          linkId:    'aprov-veiculos',
          linkLabel: 'Autorizar'
        });
      });
    } else {
      // Admin sem contrato específico: vê todas
      sources.push({
        label:     '🚗 Transferências de Veículos',
        table:     'frotas_transferencias',
        filters:   ['status=eq.pendente'],
        order:     'solicitado_em.desc',
        linkId:    'transf-veiculos',
        linkLabel: 'Autorizar'
      });
      sources.push({
        label:     '🔐 Aprovações Frota (placa / status)',
        table:     'frotas_veiculo_aprovacoes',
        filters:   ['status=eq.pendente'],
        order:     'solicitado_em.desc',
        linkId:    'aprov-veiculos',
        linkLabel: 'Autorizar'
      });
    }
  }

  return sources;
}

// ═══════════════════════════════════════════════════
// USUÁRIOS ONLINE — heartbeat a cada 2 minutos
// ═══════════════════════════════════════════════════
var _onlineInterval = null;
var _onlineUnloadBound = false;
var ONLINE_JANELA_MS = 10*60*1000; // ping recente = online (abas em background atrasam o timer)

function onlineHeartbeat(){
  if(DEMO || !usuarioLogado) return Promise.resolve(null);
  if(typeof _cenaAuthInvalid !== 'undefined' && _cenaAuthInvalid) return Promise.resolve(null);
  // AUTH-PERSIST-1: sem token válido não faz upsert (evita loop 401)
  if(_cenaAuthHadSession || _sbAuthToken){
    if(!sbAuthJwtIsAuthenticated(_sbAuthToken)){
      return cenaAuthGetValidToken({requireAuth:true, forceLogin:true, reason:'onlineHeartbeat'}).then(function(tok){
        if(!tok || _cenaAuthInvalid) return null;
        return onlineHeartbeatDo();
      });
    }
  } else {
    // legado MD5 sem Auth: não insistir em usuarios_online protegido
    return Promise.resolve(null);
  }
  return onlineHeartbeatDo();
}
function onlineHeartbeatDo(){
  if(DEMO || !usuarioLogado) return Promise.resolve(null);
  if(typeof _cenaAuthInvalid !== 'undefined' && _cenaAuthInvalid) return Promise.resolve(null);
  var modulo = (typeof _mainAtual !== 'undefined' ? _mainAtual : '') || 'sistema';
  var payload = {
    usuario_id:   usuarioLogado.id,
    nome:         usuarioLogado.nome,
    perfil:       usuarioLogado.perfil||'',
    sessao_id:    window._sessaoId||'',
    ultimo_ping:  new Date().toISOString(),
    modulo_atual: modulo
  };
  return sbUpsert('usuarios_online', payload, 'usuario_id', {requireAuth:true});
}

function onlineOffline(){
  if(_onlineInterval){ clearInterval(_onlineInterval); _onlineInterval = null; }
  if(DEMO || !usuarioLogado) return;
  if(typeof _cenaAuthInvalid !== 'undefined' && _cenaAuthInvalid) return;
  var uid = usuarioLogado.id;
  if(!uid) return;
  // Não enviar JWT expirado no unload — só se token ainda válido
  if(!sbAuthJwtIsAuthenticated(_sbAuthToken)) return;
  var url = SB.url+'/rest/v1/usuarios_online?usuario_id=eq.'+encodeURIComponent(uid);
  var h = {
    'apikey': SB.key,
    'Authorization': 'Bearer '+_sbAuthToken,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  };
  var body = JSON.stringify({ultimo_ping:'1970-01-01T00:00:00Z'});
  try{
    fetch(url, {method:'PATCH', headers:h, body:body, keepalive:true}).catch(function(){});
  }catch(e){}
}

function onlineInit(){
  if(DEMO || !usuarioLogado) return;
  if(typeof _cenaAuthInvalid !== 'undefined' && _cenaAuthInvalid) return;
  // Só inicia heartbeat autenticado se houver sessão Auth
  if(!_sbAuthToken && !_cenaAuthHadSession) return;
  onlineHeartbeat();
  if(_onlineInterval) clearInterval(_onlineInterval);
  _onlineInterval = setInterval(onlineHeartbeat, 2*60*1000);
  if(!_onlineUnloadBound){
    _onlineUnloadBound = true;
    window.addEventListener('beforeunload', function(){
      onlineOffline();
    });
  }
}

async function onlineGetAtivos(){
  if(DEMO) return [];
  try{
    var limite = new Date(Date.now()-ONLINE_JANELA_MS).toISOString();
    var rows = await sbFetch('usuarios_online',{
      filters:['ultimo_ping=gte.'+limite],
      order:'nome.asc',
      limit:500
    });
    var list = rows||[];
    var seen = {};
    return list.filter(function(u){
      var id = String(u.usuario_id||'');
      if(!id || seen[id]) return false;
      seen[id] = 1;
      return true;
    }).sort(function(a,b){
      return String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR');
    });
  }catch(e){ return []; }
}

