    // Mostrar botão voltar ao TMA
    var btnBack = document.getElementById('prog-eq-back-tma');
    if(btnBack) btnBack.style.display='block';
    // Garantir que a aba escala está visível (pode estar oculta se veio do Calendário/Relatórios)
    var escala = document.getElementById('prog-aba-escala');
    var cal    = document.getElementById('prog-aba-calendario');
