    if(btnE){btnE.style.borderBottomColor='#1a1a18';btnE.style.color='#1a1a18';btnE.style.fontWeight='600';}
    if(btnC){btnC.style.borderBottomColor='transparent';btnC.style.color='#888';btnC.style.fontWeight='500';}
    if(btnR){btnR.style.borderBottomColor='transparent';btnR.style.color='#888';btnR.style.fontWeight='500';}
    if(btnV){btnV.style.borderBottomColor='transparent';btnV.style.color='#888';btnV.style.fontWeight='500';}
    // Scroll ao topo
