// Dados de abertura de turno
var turnos_abertos = []; // {id, equipe_id, data, km_inicial, km_final, status:'aberto'|'encerrado', checklist_epi_ok, checklist_vei_ok, placa, observacao}

function renderChecklistsTemplates(){
  var pg = document.getElementById('pg-campo-checklist');
  if(!pg) return;

  // ── Filtros ────────────────────────────────────────────────────────
  if(!document.getElementById('ck-fil-cont')){
    var card = pg.querySelector('.card');
    var fDiv = document.createElement('div');
    fDiv.style.cssText = 'padding:.75rem 1rem 0';
    fDiv.innerHTML =
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-bottom:.75rem">'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Contrato</label>'
      +'<select id="ck-fil-cont" class="inp" style="width:100%" onchange="renderChecklistsTemplates()">'
      +'<option value="">Todos</option>'
      +contratos.map(function(c){return '<option value="'+c.id+'">'+escHtml(c.codigo||c.nome)+'</option>';}).join('')
      +'</select></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Equipe</label>'
      +'<select id="ck-fil-eq" class="inp" style="width:100%" onchange="renderChecklistsTemplates()">'
      +'<option value="">Todas</option>'
      +equipes_disp.map(function(e){return '<option value="'+e.id+'">'+escHtml(e.codigo||e.nome||'')+'</option>';}).join('')
      +'</select></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">De</label>'
      +'<input type="date" id="ck-fil-de" class="inp" style="width:100%" onchange="renderChecklistsTemplates()"/></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Até</label>'
      +'<input type="date" id="ck-fil-ate" class="inp" style="width:100%" onchange="renderChecklistsTemplates()" value="'+dataHojeLocal()+'"/></div>'
      +'</div>'
      +'<div style="display:flex;gap:8px;margin-bottom:.75rem">'
      +'<button id="ck-tab-epi" class="btn btn-sm" onclick="ckMostrarTipo(\'EPI\')" style="background:#3B6D11;color:#fff;border-color:#3B6D11">🦺 EPI</button>'
      +'<button id="ck-tab-vei" class="btn btn-sm" onclick="ckMostrarTipo(\'Veicular\')" style="background:#f5f5f3;color:#555">🚗 Veicular</button>'
      +'<button id="ck-tab-all" class="btn btn-sm" onclick="ckMostrarTipo(\'\')" style="background:#f5f5f3;color:#555">Todos</button>'
      +'</div>';
    if(card) card.insertBefore(fDiv, card.querySelector('.ch').nextSibling);
  }

  window._ckTipoAtivo = window._ckTipoAtivo || 'EPI';
  _ckRenderLista();
}

function ckMostrarTipo(tipo){
  window._ckTipoAtivo = tipo;
  // Atualizar botões
  ['epi','vei','all'].forEach(function(k){
    var el = document.getElementById('ck-tab-'+k);
    if(!el) return;
    var ativo = (k==='epi'&&tipo==='EPI')||(k==='vei'&&tipo==='Veicular')||(k==='all'&&tipo==='');
    el.style.background = ativo ? '#1a1a18' : '#f5f5f3';
    el.style.color      = ativo ? '#fff'    : '#555';
  });
  _ckRenderLista();
}

function _ckRenderLista(){
  var lista = document.getElementById('lista-checklists-templates');
  if(!lista) return;

  // Para perfil equipe: pré-seleciona própria equipe e data de hoje
  var _perfilEq = usuarioLogado && usuarioLogado.perfil==='equipe';
  if(_perfilEq && _dbEquipe && _dbEquipe.id){
    var _ckEqSel = document.getElementById('ck-fil-eq');
    if(_ckEqSel && !_ckEqSel.value) _ckEqSel.value = _dbEquipe.id;
    var _ckDeSel = document.getElementById('ck-fil-de');
    if(_ckDeSel && !_ckDeSel.value) _ckDeSel.value = dataHojeLocal();
    var _ckAteSel = document.getElementById('ck-fil-ate');
    if(_ckAteSel && !_ckAteSel.value) _ckAteSel.value = dataHojeLocal();
  }

  var cid   = (document.getElementById('ck-fil-cont')||{}).value||'';
  var eqId  = (document.getElementById('ck-fil-eq')||{}).value||'';
  var de    = (document.getElementById('ck-fil-de')||{}).value||'';
  var ate   = (document.getElementById('ck-fil-ate')||{}).value||dataHojeLocal();
  var tipo  = window._ckTipoAtivo||'';

  lista.innerHTML='<div style="padding:1.5rem;text-align:center;color:#aaa;font-size:12px">⏳ Carregando...</div>';

  // Buscar turnos do banco
  var filters = ['data=lte.'+ate];
  if(de)   filters.push('data=gte.'+de);
  if(eqId) filters.push('equipe_id=eq.'+eqId);

  if(DEMO){ _ckRenderComTurnos([], cid, eqId, de, ate, tipo); return; }

  sbFetch('turnos_abertos',{filters:filters, order:'data.desc', limit:300}).then(function(rows){
    if(rows&&rows.length){
      rows.forEach(function(t){
        t.respostas_epi = parseJsonField(t.respostas_epi,[]);
        t.respostas_vei = parseJsonField(t.respostas_vei,[]);
        var i = turnos_abertos.findIndex(function(x){return x.id===t.id;});
        if(i>=0) turnos_abertos[i]=t; else turnos_abertos.push(t);
      });
    }
    _ckRenderComTurnos(rows||[], cid, eqId, de, ate, tipo);
  }).catch(function(){
    _ckRenderComTurnos(turnos_abertos, cid, eqId, de, ate, tipo);
  });
}

function _ckRenderComTurnos(rows, cid, eqId, de, ate, tipo){
  var lista = document.getElementById('lista-checklists-templates');
  if(!lista) return;

  // Filtrar por contrato
  if(cid){
    rows = rows.filter(function(t){
      var eq = equipes_disp.find(function(e){return e.id===t.equipe_id;});
      return eq && eq.contrato_id===cid;
    });
  }

  // Tipos a mostrar
  var tiposMostrar = tipo ? [tipo] : ['EPI','Veicular'];
  var secoes = tiposMostrar.map(function(tp){
    var campo    = tp==='EPI' ? 'respostas_epi' : 'respostas_vei';
    var okFlag   = tp==='EPI' ? 'checklist_epi_ok' : 'checklist_vei_ok';
    var corBadge = tp==='EPI' ? 'ok' : 'info';
    var icone    = tp==='EPI' ? '🦺' : '🚗';

    // Filtrar templates do tipo
    var templates = checklists_templates.filter(function(t){return t.tipo===tp;});
    if(!templates.length){
      // Mesmo sem template cadastrado, mostrar os preenchidos
      templates = [{id:'__'+tp, nome: icone+' '+tp, tipo:tp, itens:[]}];
    }

    var rows_tipo = rows.filter(function(t){
      var resp = t[campo];
      return resp && (Array.isArray(resp) ? resp.length : false);
    });

    if(!rows_tipo.length) return '<div style="color:#aaa;font-size:12px;padding:.5rem 0 1rem">Nenhum preenchimento de '+tp+' no período.</div>';

    var html = '<div style="margin-bottom:1.25rem">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem">'
      +'<span class="bdg '+corBadge+'" style="font-size:12px">'+icone+' '+tp+'</span>'
      +'<span style="font-size:11px;color:#888">'+rows_tipo.length+' preenchimento(s)</span>'
      +'</div>';

    html += rows_tipo.map(function(t){
      var eq       = equipes_disp.find(function(e){return e.id===t.equipe_id;});
      var cont     = contratos.find(function(c){return c.id===(eq?eq.contrato_id:null);});
      var respostas= t[campo]||[];
      var ok       = !!t[okFlag];
      var nokItens = respostas.filter(function(r){return r.resposta==='N';}).length;
      var fotos    = respostas.filter(function(r){return r.foto && r.foto.length>10 && r.foto.indexOf('blob:')<0;});

      return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.85rem 1rem;margin-bottom:.5rem">'
        +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
        +'<div style="flex:1;min-width:0">'
        +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">'
        +'<span class="bdg '+(ok?'ok':'danger')+'" style="font-size:10px">'+(ok?'✅ OK':'❌ NOK')+'</span>'
        +(nokItens>0?'<span class="bdg danger" style="font-size:10px">'+nokItens+' não conformes</span>':'')
        +(fotos.length?'<span style="font-size:11px">📷 '+fotos.length+'</span>':'')
        +'</div>'
        +'<div style="font-weight:600;font-size:13px">'+(eq?escHtml(eq.codigo+(eq.nome?' — '+eq.nome:'')):'<span style="color:#aaa">—</span>')+'</div>'
        +'<div style="font-size:11px;color:#888;margin-top:2px;display:flex;gap:10px;flex-wrap:wrap">'
        +'<span>📅 '+fmtD(t.data)+'</span>'
        +(cont?'<span>📋 '+escHtml(cont.codigo||cont.nome||'')+'</span>':'')
        +(t.placa?'<span>🚗 '+escHtml(t.placa)+'</span>':'')
        +'</div>'
        +'</div>'
        +'<button class="btn btn-sm" id="ck-ver-'+tp+'-'+t.id+'" style="flex-shrink:0">👁 Ver</button>'
        +'</div>'
        // Fotos thumbnail
        +(fotos.length?'<div style="display:flex;gap:4px;margin-top:.5rem;flex-wrap:wrap">'
          +fotos.map(function(r){
            return '<img src="'+r.foto+'" style="width:56px;height:56px;border-radius:6px;object-fit:cover;border:.5px solid #e0dfd8;cursor:pointer" '
              +'onclick="_ckVerFotoFull(\''+encodeURIComponent(r.foto)+'\')" title="'+(r.pergunta||'')+'"/>';
          }).join('')
          +'</div>':'')
        +'</div>';
    }).join('');

    html += '</div>';
    return html;
  }).join('');

  lista.innerHTML = secoes || '<div style="padding:2rem;text-align:center;color:#aaa">Nenhum checklist no período.</div>';

  // Bind "Ver" buttons
  rows.forEach(function(t){
    ['EPI','Veicular'].forEach(function(tp){
      var btn = document.getElementById('ck-ver-'+tp+'-'+t.id);
      if(btn) btn.onclick = function(){ _ckVerDetalhe(t, tp); };
    });
  });
}

function _ckVerFotoFull(encSrc){
  var src = decodeURIComponent(encSrc);
  setModal(
    '<div class="modal-bg"><div class="modal" style="max-width:700px;padding:.5rem">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.5rem">'
    +'<span style="font-weight:600;font-size:13px">📷 Foto</span>'
    +'<button class="btn btn-sm" onclick="closeModal()">✕ Fechar</button>'
    +'</div>'
    +'<img src="'+src+'" style="width:100%;border-radius:8px;max-height:70vh;object-fit:contain"/>'
    +'</div></div>'
  );
}

function _ckVerDetalhe(turno, tipo){
  var campo    = tipo==='EPI' ? 'respostas_epi' : 'respostas_vei';
  var okFlag   = tipo==='EPI' ? 'checklist_epi_ok' : 'checklist_vei_ok';
  var eq       = equipes_disp.find(function(e){return e.id===turno.equipe_id;});
  var respostas= turno[campo]||[];
  var ok       = !!turno[okFlag];
  var icone    = tipo==='EPI'?'🦺':'🚗';

  var resLabels = {C:'✅ Conforme', N:'❌ Não conforme', A:'N/A', S:'✅ Sim', s:'✅ Sim'};

  var itensHtml = respostas.map(function(r, i){
    var resp   = r.resposta||'';
    var label  = resLabels[resp] || resp || '—';
    var corBg  = resp==='N'?'background:#FFF0F0;border-color:#F5C6CB'
                :resp==='C'||resp==='S'||resp==='s'?'background:#F0FFF4;border-color:#C3E6CB'
                :'background:#f9f9f7;border-color:#e0dfd8';
    return '<div style="border:.5px solid;border-radius:8px;padding:.55rem .75rem;margin-bottom:.4rem;'+corBg+'">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
      +'<div style="font-size:12px;flex:1">'+(i+1)+'. '+(r.pergunta||'Item '+(i+1))+'</div>'
      +'<span style="font-size:11px;white-space:nowrap;flex-shrink:0">'+label+'</span>'
      +'</div>'
      +(r.obs?'<div style="font-size:11px;color:#777;margin-top:3px">📝 '+escHtml(r.obs||'')+'</div>':'')
      +(r.foto&&r.foto.indexOf('blob:')<0
        ?'<div style="margin-top:.5rem">'
          +'<img src="'+r.foto+'" style="width:80px;height:80px;border-radius:8px;object-fit:cover;border:.5px solid #e0dfd8;cursor:pointer" onclick="_ckVerFotoFull(\''+encodeURIComponent(r.foto)+'\')" />'
          +'</div>'
        :'')
      +'</div>';
  }).join('');

  if(!itensHtml) itensHtml='<div style="color:#aaa;font-size:12px;padding:1rem;text-align:center">Nenhuma resposta registrada.</div>';

  setModal(
    '<div class="modal-bg"><div class="modal" style="max-width:580px">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem">'
    +'<div>'
    +'<div style="font-weight:700;font-size:14px">'+icone+' Checklist '+tipo+'</div>'
    +'<div style="font-size:12px;color:#888;margin-top:3px">'
    +(eq?escHtml(eq.codigo+(eq.nome?' — '+eq.nome:'')):'—')+' &nbsp;|&nbsp; '+fmtD(turno.data)
    +(turno.placa?' &nbsp;|&nbsp; 🚗 '+turno.placa:'')
    +'</div>'
    +'</div>'
    +'<span class="bdg '+(ok?'ok':'danger')+'" style="font-size:12px;padding:5px 12px">'+(ok?'✅ OK':'❌ NOK')+'</span>'
    +'</div>'
    +'<div style="max-height:450px;overflow-y:auto">'+itensHtml+'</div>'
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>'
  );
}

function abrirDetalheChecklist(clId, turnoId){
  var t=checklists_templates.find(function(x){return x.id===clId;});
  if(!t)return;
  var corTipoMap={EPI:'ok',Veicular:'info',APR:'warn'};
  var turno=turnoId?turnos_abertos.find(function(x){return x.id===turnoId;}):null;
  var campo=t.tipo==='EPI'?'respostas_epi':'respostas_vei';
  var respostas=turno?parseJsonField(turno[campo],[]):[];
  var eq=turno?equipes_disp.find(function(e){return e.id===turno.equipe_id;}):null;
  var resLabels={C:'✅ Conforme',N:'❌ Não conforme',A:'— N/A'};
  var corBgMap={C:'background:#F0FFF4;border-color:#C3E6CB',N:'background:#FFF0F0;border-color:#F5C6CB',A:'background:#f9f9f7;border-color:#e0dfd8'};

  var itensHtml=t.itens.map(function(it,i){
    var resp=respostas.find(function(r){return r.item_id===it.id;})||respostas[i];
    var resLabel=resp?(resLabels[resp.resposta]||resp.resposta):'—';
    var corBg=resp?(corBgMap[resp.resposta]||corBgMap['A']):corBgMap['A'];
    var foto=resp&&resp.foto&&resp.foto.indexOf('blob:')<0?resp.foto:null;
    return '<div style="border:.5px solid;border-radius:8px;padding:.65rem .85rem;margin-bottom:.4rem;'+corBg+'">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
      +'<div style="font-size:13px;font-weight:500;flex:1">'+(i+1)+'. '+it.pergunta
      +(it.obrigatorio?'<span style="color:#A32D2D"> *</span>':'')+'</div>'
      +'<div style="display:flex;gap:4px;flex-shrink:0">'
      +(turno?'<span style="font-size:12px;font-weight:600">'+resLabel+'</span>':'')
      +(it.foto_obrigatoria&&!turno?'<span class="bdg info" style="font-size:10px">📷</span>':'')
      +'</div></div>'
      +(foto?'<div style="margin-top:6px"><img src="'+foto+'" data-src="'+encodeURIComponent(foto)+'" style="width:72px;height:72px;border-radius:8px;object-fit:cover;border:.5px solid #e0dfd8;cursor:pointer" title="Clique para ampliar"/></div>':'')
      +'</div>';
  }).join('');

  var cabHtml=turno
    ?'<div style="background:#f9f9f7;border-radius:8px;padding:.65rem .85rem;margin-bottom:.75rem;font-size:12px">'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">'
      +'<div><span style="color:#888">Equipe</span><br><b>'+(eq?eq.codigo+' — '+eq.nome:'—')+'</b></div>'
      +'<div><span style="color:#888">Data</span><br><b>'+fmtD(turno.data)+'</b></div>'
      +'<div><span style="color:#888">Placa</span><br><b>'+(turno.placa||'—')+'</b></div>'
      +'<div><span style="color:#888">KM inicial</span><br><b>'+(turno.km_inicial||'—')+'</b></div>'
      +'</div></div>'
    :'';

  var okVal=t.tipo==='EPI'?turno&&turno.checklist_epi_ok:turno&&turno.checklist_vei_ok;
  setModal(
    '<div class="modal-bg"><div class="modal" style="max-width:520px">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem">'
    +'<div><h3 style="margin:0">'+t.nome+'</h3>'
    +'<span class="bdg '+(corTipoMap[t.tipo]||'gray')+'" style="margin-top:4px;display:inline-block">'+t.tipo+'</span></div>'
    +'<div style="text-align:right">'
    +'<div style="font-size:12px;color:#888">'+t.itens.length+' itens</div>'
    +(turno?'<span class="bdg '+(okVal?'ok':'danger')+'" style="font-size:11px">'+(okVal?'✓ Aprovado':'✗ Reprovado')+'</span>':'')
    +'</div></div>'
    +cabHtml
    +'<div style="max-height:380px;overflow-y:auto">'+itensHtml+'</div>'
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>'
  );
}

function filtrarChecklists(tipo){
  ['EPI','Veicular','APR',''].forEach(function(t){
    var btn=document.getElementById('tab-cl-'+(t||'todos'));
    if(btn){btn.style.background=t===tipo?'#1a1a18':'';btn.style.color=t===tipo?'#fff':'';}
  });
  renderChecklistsTemplates(tipo);
}

function openNovoChecklist(){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px"><h3>Novo Checklist</h3>'
    +'<div class="g2">'
    +'<div class="fg" style="grid-column:1/-1"><label>Nome do checklist</label><input id="ncl-nome" placeholder="Ex: EPI — Eletricista TMA" style="width:100%"/></div>'
    +'<div class="fg"><label>Tipo</label><select id="ncl-tipo" style="width:100%"><option value="EPI">🦺 EPI</option><option value="Veicular">🚗 Veicular</option><option value="APR">⚠️ APR</option></select></div>'
    +'</div>'
    +'<div style="margin:.75rem 0 .4rem;font-size:12px;font-weight:600;color:#555">Itens do checklist</div>'
    +'<div id="ncl-itens-lista" style="max-height:250px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px;padding:6px;margin-bottom:.5rem"></div>'
    +'<button class="btn btn-sm" id="btn-add-item-cl">+ Adicionar item</button>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="btn-salvar-ncl">Salvar checklist</button></div></div></div>');
  window._nclItens=[];
  renderNclItens();
  setTimeout(function(){
    document.getElementById('btn-add-item-cl').onclick=function(){
      window._nclItens.push({id:'ni'+Date.now(),pergunta:'',obrigatorio:true,foto_obrigatoria:false});
      renderNclItens();
    };
    document.getElementById('btn-salvar-ncl').onclick=function(){
      var nome=(document.getElementById('ncl-nome')||{}).value.trim();
      var tipo=(document.getElementById('ncl-tipo')||{}).value;
      if(!nome)return alert('Informe o nome.');
      if(!window._nclItens.length)return alert('Adicione ao menos um item.');
      var novo={id:'ct'+Date.now(),nome:nome,tipo:tipo,itens:window._nclItens.slice()};
      checklists_templates.push(novo);
      if(!DEMO)sbInsert('checklists_templates',Object.assign({},novo,{itens:JSON.stringify(novo.itens),id:undefined}));
      closeModal();renderChecklistsTemplates();
    };
  },50);
}

function renderNclItens(){
  var lista=document.getElementById('ncl-itens-lista');if(!lista)return;
  if(!window._nclItens.length){lista.innerHTML='<div style="color:#aaa;font-size:12px;padding:.5rem">Nenhum item. Clique em + Adicionar item.</div>';return;}
  lista.innerHTML=window._nclItens.map(function(it,i){
    return '<div style="display:flex;gap:6px;align-items:center;padding:5px 0;border-bottom:.5px solid #f5f5f3">'
      +'<span style="font-size:11px;color:#aaa;min-width:18px">'+(i+1)+'.</span>'
      +'<input value="'+it.pergunta+'" placeholder="Descreva o item..." style="flex:1;font-size:12px;border:.5px solid #e0dfd8;border-radius:6px;padding:4px 8px" id="nclp-'+i+'"/>'
      +'<label style="font-size:11px;white-space:nowrap;display:flex;align-items:center;gap:3px"><input type="checkbox" '+(it.obrigatorio?'checked':'')+' id="nclo-'+i+'"/> Obrig.</label>'
      +'<label style="font-size:11px;white-space:nowrap;display:flex;align-items:center;gap:3px"><input type="checkbox" '+(it.foto_obrigatoria?'checked':'')+' id="nclf-'+i+'"/> Foto</label>'
      +'<button style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:14px" id="rm-ni-'+i+'">✕</button>'
      +'</div>';
  }).join('');
  window._nclItens.forEach(function(it,i){
    var inp=document.getElementById('nclp-'+i);if(inp)inp.oninput=function(){window._nclItens[i].pergunta=this.value;};
    var chkO=document.getElementById('nclo-'+i);if(chkO)chkO.onchange=function(){window._nclItens[i].obrigatorio=this.checked;};
    var chkF=document.getElementById('nclf-'+i);if(chkF)chkF.onchange=function(){window._nclItens[i].foto_obrigatoria=this.checked;};
    var btn=document.getElementById('rm-ni-'+i);if(btn)btn.onclick=function(){window._nclItens.splice(i,1);renderNclItens();};
  });
}

function openEditarChecklist(cid){
  var t=checklists_templates.find(function(x){return x.id===cid;});if(!t)return;
  window._nclItens=t.itens.map(function(i){return Object.assign({},i);});
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px"><h3>Editar Checklist — '+t.nome+'</h3>'
    +'<div class="g2">'
    +'<div class="fg" style="grid-column:1/-1"><label>Nome</label><input id="ncl-nome" value="'+t.nome+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Tipo</label><select id="ncl-tipo" style="width:100%"><option value="EPI"'+(t.tipo==='EPI'?' selected':'')+'>🦺 EPI</option><option value="Veicular"'+(t.tipo==='Veicular'?' selected':'')+'>🚗 Veicular</option><option value="APR"'+(t.tipo==='APR'?' selected':'')+'>⚠️ APR</option></select></div>'
    +'</div>'
    +'<div style="margin:.75rem 0 .4rem;font-size:12px;font-weight:600;color:#555">Itens</div>'
    +'<div id="ncl-itens-lista" style="max-height:250px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px;padding:6px;margin-bottom:.5rem"></div>'
    +'<button class="btn btn-sm" id="btn-add-item-cl">+ Adicionar item</button>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" id="btn-salvar-ncl">Salvar</button></div></div></div>');
  renderNclItens();
  setTimeout(function(){
    document.getElementById('btn-add-item-cl').onclick=function(){
      window._nclItens.push({id:'ni'+Date.now(),pergunta:'',obrigatorio:true,foto_obrigatoria:false});
      renderNclItens();
    };
    document.getElementById('btn-salvar-ncl').onclick=function(){
      t.nome=(document.getElementById('ncl-nome')||{}).value.trim()||t.nome;
      t.tipo=(document.getElementById('ncl-tipo')||{}).value||t.tipo;
      t.itens=window._nclItens.slice();
      if(!DEMO)sbUpdate('checklists_templates',{nome:t.nome,tipo:t.tipo,itens:JSON.stringify(t.itens)},'id=eq.'+cid);
      closeModal();renderChecklistsTemplates();
    };
  },50);
}

// ══════════════════════════════════════════════════════════
// ABERTURA DE TURNO (Desktop — visão admin)
// ══════════════════════════════════════════════════════════
function renderAberturaTurno(){
  var wrap=document.getElementById('turno-content');if(!wrap)return;
  var hoje=dataHoje();

  wrap.innerHTML=
    // Filtros padronizados: contrato, equipe, data
    '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:1rem">'
    +'<div class="fg"><label style="font-size:11px">Contrato</label>'
    +'<select id="fil-turno-cont" style="width:100%" onchange="renderTurnoEquipes()">'
    +'<option value="">Todos</option>'
    +contratos.map(function(c){return '<option value="'+c.id+'">'+c.nome+'</option>';}).join('')
    +'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Equipe</label>'
    +'<select id="fil-turno-eq" style="width:100%" onchange="renderTurnoEquipes()">'
    +'<option value="">Todas</option>'
    +equipes_disp.map(function(e){return '<option value="'+e.id+'">'+e.codigo+' — '+e.nome+'</option>';}).join('')
    +'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Data</label>'
    +'<input type="date" id="fil-turno-data" value="'+hoje+'" style="width:100%" onchange="renderTurnoEquipes()"/>'
    +'</div>'
    +'</div>'
    +'<div id="turno-equipes-wrap"><div style="color:#aaa;font-size:12px;text-align:center;padding:1rem">Selecione os filtros acima.</div></div>'
    +'<div style="margin-top:1.5rem">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem;padding-bottom:.5rem;border-bottom:.5px solid #e0dfd8">'
    +'<div style="font-size:12px;font-weight:600;color:#555">📋 Histórico de turnos</div>'
    +'<button id="btn-atualizar-turnos" style="background:none;border:.5px solid #e0dfd8;border-radius:8px;padding:5px 10px;font-size:12px;cursor:pointer;color:#555">↻ Atualizar</button>'
    +'</div>'
    +'<div id="turno-historico-wrap"></div></div>';

  // Auto-selecionar contrato único
  if(contratos.length===1){
    var sel=document.getElementById('fil-turno-cont');
    if(sel) sel.value=contratos[0].id;
  }

  var btnAt=document.getElementById('btn-atualizar-turnos');
  if(btnAt) btnAt.onclick=_atualizarTurnosAdmin;

  _atualizarTurnosAdmin();
}


async function _atualizarTurnosAdmin(){
  var btn=document.getElementById('btn-atualizar-turnos');
  if(btn){btn.textContent='↻ Atualizando...';btn.disabled=true;}
  if(!DEMO){
    try{
      var semAtras=(function(_ms){var _d=new Date(_ms);return _d.getFullYear()+'-'+String(_d.getMonth()+1).padStart(2,'0')+'-'+String(_d.getDate()).padStart(2,'0');})(Date.now()-7*86400000);
      var res=await Promise.all([
        sbFetch('sessoes_disponibilidade',{filters:['data=gte.'+semAtras],order:'data.desc'}),
        sbFetch('turnos_abertos',{filters:['data=gte.'+semAtras],order:'data.desc'}),
        sbFetch('ordens_diario',{filters:['data=gte.'+semAtras],order:'data.desc'}),
      ]);
      if(res[0]&&res[0].length) res[0].forEach(function(s){
        s.eventos=parseJsonField(s.eventos,[]); s.placa=s.placa||'';
        s.km_inicial=s.km_inicial||0; s.km_final=s.km_final||0;
        var i=sessoes_disp.findIndex(function(x){return x.id===s.id;});
        if(i>=0) sessoes_disp[i]=s; else sessoes_disp.push(s);
      });
      if(res[1]&&res[1].length) res[1].forEach(function(t){
        t.respostas_epi=parseJsonField(t.respostas_epi,[]);
        t.respostas_vei=parseJsonField(t.respostas_vei,[]);
        var i=turnos_abertos.findIndex(function(x){return x.id===t.id;});
        if(i>=0) turnos_abertos[i]=t; else turnos_abertos.push(t);
      });
      if(res[2]&&res[2].length) res[2].forEach(function(o){
        o.eventos=parseJsonField(o.eventos,[]);
        // Limpar blob URLs expiradas dos eventos
        o.eventos.forEach(function(ev){
          if(ev.foto&&ev.foto.indexOf('blob:')===0) ev.foto=null;
        });
        if(!ordens_db.find(function(x){return x.id===o.id;})) ordens_db.push(o);
      });
    }catch(e){console.error('Erro ao atualizar turnos:',e);}
  }
  if(btn){btn.textContent='↻ Atualizar';btn.disabled=false;}
  renderTurnoEquipes();
  _renderHistoricoTurnos();
}

function _renderHistoricoTurnos(){
  var wrap=document.getElementById('turno-historico-wrap');if(!wrap)return;
  // Combinar turnos e sessões para ter histórico completo
  var recentes=sessoes_disp.slice().sort(function(a,b){return b.data>a.data?1:-1;}).slice(0,30);
  if(!recentes.length){
    wrap.innerHTML='<div style="color:#aaa;font-size:12px;padding:.5rem">Nenhum turno registrado ainda.</div>';return;
  }
  function fmtTs(ts){if(!ts)return '—';var d=new Date(ts);return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');}
  wrap.innerHTML='<div style="overflow-x:auto"><table class="tbl tbl-responsive"><thead><tr>'
    +'<th>Data</th><th>Equipe</th><th>Início</th><th>Fim</th><th>Horas fat.</th><th>Placa</th><th>KM ini</th><th>KM fin</th><th>EPI</th><th>Veicular</th><th>Status</th>'
    +'</tr></thead><tbody>'
    +recentes.map(function(s){
      var eq=equipes_disp.find(function(e){return e.id===s.equipe_id;});
      var turno=turnos_abertos.find(function(t){return t.equipe_id===s.equipe_id&&t.data===s.data;});
      var placa=(turno&&turno.placa)||(s.placa)||'—';
      var kmIni=(turno&&turno.km_inicial)||(s.km_inicial)||'—';
      var kmFin=(turno&&turno.km_final)||(s.km_final)||'—';
      var epiOk=turno&&turno.checklist_epi_ok;
      var veiOk=turno&&turno.checklist_vei_ok;
      var minFat=s.minutos_faturados||0;
      var hFat=Math.floor(minFat/60);var mFat=minFat%60;
      var stLabel=s.logout_ts?'Encerrado':'Em andamento';
      return '<tr>'
        +'<td data-label="Data">'+fmtD(s.data)+'</td>'
        +'<td data-label="Equipe" style="font-weight:500">'+(eq?eq.codigo+' — '+eq.nome:'—')+'</td>'
        +'<td data-label="Início">'+fmtTs(s.login_ts)+'</td>'
        +'<td data-label="Fim">'+fmtTs(s.logout_ts)+'</td>'
        +'<td data-label="Horas fat." style="font-weight:600;color:#185FA5">'+(minFat?String(hFat).padStart(2,'0')+':'+String(mFat).padStart(2,'0'):'—')+'</td>'
        +'<td data-label="Placa">'+placa+'</td>'
        +'<td data-label="KM ini">'+kmIni+'</td>'
        +'<td data-label="KM fin">'+kmFin+'</td>'
        +'<td data-label="EPI"><span class="bdg '+(turno?(epiOk?'ok':'danger'):'gray')+'">'+(turno?(epiOk?'✓':'✗'):'—')+'</span></td>'
        +'<td data-label="Veicular"><span class="bdg '+(turno?(veiOk?'ok':'danger'):'gray')+'">'+(turno?(veiOk?'✓':'✗'):'—')+'</span></td>'
        +'<td data-label="Status"><span class="bdg '+(s.logout_ts?'teal':'ok')+'">'+stLabel+'</span></td>'
        +'</tr>';
    }).join('')+'</tbody></table></div>';
}

function renderTurnoEquipes(){
  var cid=(document.getElementById('fil-turno-cont')||{}).value||'';
  var eqId=(document.getElementById('fil-turno-eq')||{}).value||'';
  var data=(document.getElementById('fil-turno-data')||{}).value||dataHojeLocal();
  var wrap=document.getElementById('turno-equipes-wrap');if(!wrap)return;
  var eqs=equipes_disp.filter(function(e){
    if(e.status!=='Ativo') return false;
    if(cid && e.contrato_id!==cid) return false;
    if(eqId && e.id!==eqId) return false;
    return true;
  });
  if(!eqs.length){wrap.innerHTML='<div style="color:#aaa;font-size:12px;text-align:center;padding:2rem">Nenhuma equipe encontrada para os filtros selecionados.</div>';return;}

  function fmtTs(ts){
    if(!ts)return '—';
    var d=new Date(ts);
    return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
  }

  if(!eqs.filter(function(eq){
    return turnos_abertos.some(function(t){return t.equipe_id===eq.id&&t.data===data;})
        || sessoes_disp.some(function(s){return s.equipe_id===eq.id&&s.data===data;});
  }).length && data){
    // Nenhum turno neste dia — mostrar cards vazios igualmente
  }

  wrap.innerHTML=eqs.map(function(eq){
    var turno=turnos_abertos.find(function(t){return t.equipe_id===eq.id&&t.data===data;});
    var sessao=sessoes_disp.find(function(s){return s.equipe_id===eq.id&&s.data===data;});
    var tipo=tipos_equipe.find(function(t){return t.id===eq.tipo_id;});

    var stLabel=sessao&&sessao.logout_ts?'Encerrado':sessao&&sessao.login_ts?'Em andamento':'Não iniciado';
    var stCls=stLabel==='Em andamento'?'ok':stLabel==='Encerrado'?'teal':'gray';

    var placa=(turno&&turno.placa)||(sessao&&sessao.placa)||'—';
    var kmIni=(turno&&turno.km_inicial)||(sessao&&sessao.km_inicial)||0;
    var kmFin=(turno&&turno.km_final)||(sessao&&sessao.km_final)||0;
    var kmRod=kmFin&&kmIni?(kmFin-kmIni):0;

    var hrIni=sessao?fmtTs(sessao.login_ts):'—';
    var hrFim=sessao&&sessao.logout_ts?fmtTs(sessao.logout_ts):'—';
    var hrAlm=sessao&&sessao.almoco_ts?fmtTs(sessao.almoco_ts):'—';
    var hrRet=sessao&&sessao.retorno_ts?fmtTs(sessao.retorno_ts):'—';
    var temAlmoco=sessao&&sessao.almoco_ts;

    var minFat=sessao?(sessao.minutos_faturados||0):0;
    var hFat=Math.floor(minFat/60);var mFat=minFat%60;
    var horasFat=minFat?String(hFat).padStart(2,'0')+':'+String(mFat).padStart(2,'0'):'—';

    var epiOk=turno&&turno.checklist_epi_ok;
    var veiOk=turno&&turno.checklist_vei_ok;

    var nOrdens=ordens_db.filter(function(o){return o.equipe_id===eq.id&&o.data===data;}).length;
    var nEnc=ordens_db.filter(function(o){return o.equipe_id===eq.id&&o.data===data&&o.status==='encerrada';}).length;

    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:12px;padding:1rem;margin-bottom:.75rem">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem">'
      +'<div><div style="font-weight:700;font-size:14px">'+eq.codigo+' — '+eq.nome+'</div>'
      +'<div style="font-size:11px;color:#888;margin-top:2px">'+(tipo?tipo.nome:'—')+'</div></div>'
      +'<span class="bdg '+stCls+'">'+stLabel+'</span>'
      +'</div>'
      +'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:.75rem">'
      +'<div style="background:#f9f9f7;border-radius:8px;padding:.5rem .75rem"><div style="font-size:10px;color:#888">Início</div><div style="font-size:13px;font-weight:600">'+hrIni+'</div></div>'
      +'<div style="background:#f9f9f7;border-radius:8px;padding:.5rem .75rem"><div style="font-size:10px;color:#888">Encerramento</div><div style="font-size:13px;font-weight:600">'+hrFim+'</div></div>'
      +'<div style="background:#f9f9f7;border-radius:8px;padding:.5rem .75rem"><div style="font-size:10px;color:#888">Almoço / Retorno</div><div style="font-size:12px;font-weight:500">'+(temAlmoco?hrAlm+' / '+hrRet:'Não registrado')+'</div></div>'
      +'<div style="background:#E6F1FB;border-radius:8px;padding:.5rem .75rem"><div style="font-size:10px;color:#888">Horas faturáveis</div><div style="font-size:14px;font-weight:700;color:#185FA5">'+horasFat+'</div></div>'
      +'</div>'
      +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:.75rem">'
      +'<div style="background:#f9f9f7;border-radius:8px;padding:.5rem .75rem"><div style="font-size:10px;color:#888">Placa</div><div style="font-size:13px;font-weight:600">'+placa+'</div></div>'
      +'<div style="background:#f9f9f7;border-radius:8px;padding:.5rem .75rem"><div style="font-size:10px;color:#888">KM inicial → final</div><div style="font-size:12px;font-weight:600">'+(kmIni?kmIni:'—')+(kmFin?' → '+kmFin:'')+'</div></div>'
      +'<div style="background:#f9f9f7;border-radius:8px;padding:.5rem .75rem"><div style="font-size:10px;color:#888">KM rodado</div><div style="font-size:13px;font-weight:600">'+(kmRod?kmRod+'km':'—')+'</div></div>'
      +'</div>'
      +'<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">'
      +'<div style="display:flex;gap:6px">'
      +'<span class="bdg '+(turno?(epiOk?'ok':'danger'):'gray')+'" style="font-size:11px">'+(turno?(epiOk?'✓ EPI':'✗ EPI'):'EPI: —')+'</span>'
      +'<span class="bdg '+(turno?(veiOk?'ok':'danger'):'gray')+'" style="font-size:11px">'+(turno?(veiOk?'✓ Veicular':'✗ Veicular'):'Veicular: —')+'</span>'
      +'</div>'
      +'<div style="font-size:12px;color:#555">'+(nOrdens?'<b>'+nEnc+'</b>/'+nOrdens+' ordens':'Nenhuma ordem')+'</div>'
      +'</div>'
      +'</div>';
  }).join('');
}

// ══════════════════════════════════════════════════════════
// APR — visualização admin
// ══════════════════════════════════════════════════════════
function renderAPRs(){
  var pg  = document.getElementById('pg-campo-apr');
  if(!pg) return;

  // ── Montar filtros se ainda não existem ───────────────────────────
  if(!document.getElementById('apr-fil-cont')){
    var card = pg.querySelector('.card');
    var fDiv = document.createElement('div');
    fDiv.style.cssText = 'padding:.75rem 1rem 0';
    fDiv.innerHTML =
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;margin-bottom:.75rem">'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Contrato</label>'
      +'<select id="apr-fil-cont" class="inp" style="width:100%" onchange="renderAPRs()">'
      +'<option value="">Todos</option>'
      +contratos.map(function(c){return '<option value="'+c.id+'">'+escHtml(c.codigo||c.nome)+'</option>';}).join('')
      +'</select></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Equipe</label>'
      +'<select id="apr-fil-eq" class="inp" style="width:100%" onchange="renderAPRs()">'
      +'<option value="">Todas</option>'
      +equipes_disp.concat(equipes).map(function(e){return '<option value="'+e.id+'">'+escHtml(e.codigo||e.nome||'')+'</option>';}).join('')
      +'</select></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">De</label>'
      +'<input type="date" id="apr-fil-de" class="inp" style="width:100%" onchange="renderAPRs()"/></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Até</label>'
      +'<input type="date" id="apr-fil-ate" class="inp" style="width:100%" onchange="renderAPRs()" value="'+dataHojeLocal()+'"/></div>'
      +'<div class="fg"><label style="font-size:11px;font-weight:600">Tipo</label>'
      +'<select id="apr-fil-tipo" class="inp" style="width:100%" onchange="renderAPRs()">'
      +'<option value="">Todos</option>'
      +'<option value="APR-EQTL">⚡ APR Equatorial</option>'
      +'<option value="APR">APR Padrão</option>'
      +'</select></div>'
      +'</div>';
    if(card) card.insertBefore(fDiv, card.querySelector('.ch').nextSibling);
  }

  // For equipe profile: default to their own equipe and today
  var _perfilEq = usuarioLogado && usuarioLogado.perfil==='equipe';
  if(_perfilEq && _dbEquipe && _dbEquipe.id){
    var _eqSel = document.getElementById('apr-fil-eq');
    if(_eqSel && !_eqSel.value) _eqSel.value = _dbEquipe.id;
    var _deSel = document.getElementById('apr-fil-de');
    if(_deSel && !_deSel.value) _deSel.value = dataHojeLocal();
  }

  var cid  = (document.getElementById('apr-fil-cont')||{}).value||'';
  var eqId = (document.getElementById('apr-fil-eq')||{}).value||'';
  var de   = (document.getElementById('apr-fil-de')||{}).value||'';
  var ate  = (document.getElementById('apr-fil-ate')||{}).value||dataHojeLocal();
  var tipo = (document.getElementById('apr-fil-tipo')||{}).value||'';

  var lista = document.getElementById('apr-lista');
  if(!lista) return;
  lista.innerHTML = '<div style="padding:1.5rem;text-align:center;color:#aaa;font-size:12px">⏳ Carregando APRs...</div>';

  if(DEMO){ _renderAPRsLista([]); return; }

  // Buscar do banco sempre
  var filters = ['data=lte.'+ate];
  if(de)   filters.push('data=gte.'+de);
  if(eqId) filters.push('equipe_id=eq.'+eqId);
  if(tipo) filters.push('tipo=eq.'+tipo);

  Promise.all([
    sbFetch('aprs_registradas', {filters:filters, order:'data.desc,criado_em.desc', limit:200}),
  ]).then(function(res){
    var rows = res[0]||[];
    // Merge no array local
    rows.forEach(function(a){
      a.respostas = parseJsonField(a.respostas, []);
      var i = aprs_registradas.findIndex(function(x){return x.id===a.id;});
      if(i>=0) aprs_registradas[i]=a; else aprs_registradas.push(a);
    });
    // Filtrar por contrato (client-side, pois equipe_id→contrato precisa do array)
    if(cid){
      rows = rows.filter(function(a){
        var eq = equipes_disp.find(function(e){return e.id===a.equipe_id;})
               ||equipes.find(function(e){return e.id===a.equipe_id;});
        return eq && eq.contrato_id===cid;
      });
    }
    _renderAPRsLista(rows);
  }).catch(function(e){
    lista.innerHTML='<div style="padding:1.5rem;text-align:center;color:#A32D2D;font-size:12px">⚠ Erro ao carregar APRs. Verifique o console.</div>';
    console.error('renderAPRs erro:', e);
  });
}

function _renderAPRsLista(rows){
  var lista = document.getElementById('apr-lista');
  if(!lista) return;
  if(!rows.length){
    lista.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa;font-size:13px">Nenhuma APR registrada no período.</div>';
    return;
  }

  lista.innerHTML = rows.map(function(a){
    var eq   = equipes_disp.find(function(e){return e.id===a.equipe_id;})
             ||equipes.find(function(e){return e.id===a.equipe_id;});
    var cont = contratos.find(function(c){
      return c.id===(eq?eq.contrato_id:null)||c.id===a.contrato_id;
    });
    var respostas = parseJsonField(a.respostas,[]);
    var isEqtl    = _aprIsEqtl(a);
    var isObjArr  = respostas.length && typeof respostas[0]==='object';
    var aprSt     = _aprStatusLabel(a);

    // Para APR-EQTL: respostas é {q1:'S', q2:'N'...} dentro de JSON string direto
    var dadosEqtl = null;
    if(isEqtl && !isObjArr){
      dadosEqtl = _aprMetaFromRespostas(a);
      if(!dadosEqtl || !Object.keys(dadosEqtl).length){
        try{ dadosEqtl = JSON.parse(a.respostas); } catch(e){}
      }
      if(!dadosEqtl && typeof a.respostas==='object') dadosEqtl = a.respostas;
    }

    var nokCount = 0;
    var temFoto  = false;
    if(isObjArr){
      nokCount = respostas.filter(function(r){return r.resposta==='N';}).length;
      temFoto  = respostas.some(function(r){return r.foto&&r.foto.length>10;});
    } else if(dadosEqtl && dadosEqtl.respostas){
      var rrs = dadosEqtl.respostas;
      Object.keys(rrs).forEach(function(k){
        if(typeof rrs[k]==='string' && rrs[k]==='N' && k.indexOf('_obs')<0) nokCount++;
      });
    }

    var tipoLabel = isEqtl ? '<span class="bdg info" style="font-size:10px">⚡ EQTL</span>'
                            : '<span class="bdg warn" style="font-size:10px">APR</span>';
    var resultBdg = aprSt==='recusada'
      ? '<span class="bdg danger" style="font-size:10px">⛔ Recusada</span>'
      : aprSt==='aprovada'
        ? '<span class="bdg ok" style="font-size:10px">✅ Aprovada</span>'
        : (a.resultado
          ? '<span class="bdg '+(a.resultado==='OK'?'ok':'danger')+'" style="font-size:10px">'+a.resultado+'</span>'
          : '');

    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.85rem 1rem;margin-bottom:.5rem">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
      +'<div style="flex:1;min-width:0">'
      +'<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:3px">'
      +tipoLabel
      +(resultBdg||'')
      +(nokCount>0?'<span class="bdg danger" style="font-size:10px">'+nokCount+' NOK</span>':'')
      +(temFoto?'<span style="font-size:11px">📷</span>':'')
      +'</div>'
      +'<div style="font-weight:600;font-size:13px">'
      +(eq?escHtml(eq.codigo+(eq.nome?' — '+eq.nome:'')):'<span style="color:#aaa">Equipe não encontrada</span>')
      +'</div>'
      +'<div style="font-size:11px;color:#888;margin-top:2px;display:flex;gap:10px;flex-wrap:wrap">'
      +'<span>📅 '+fmtD(a.data)+'</span>'
      +(cont?'<span>📋 '+escHtml(cont.codigo||cont.nome||'')+'</span>':'')
      +(a.numero_os||a.ordem_id?'<span>🔧 OS: '+escHtml(a.numero_os||a.ordem_id||'')+'</span>':'')
      +(isEqtl&&dadosEqtl&&dadosEqtl.local?'<span>📍 '+escHtml(dadosEqtl.local)+'</span>':'')
      +(isEqtl&&dadosEqtl&&dadosEqtl.servico?'<span>⚙️ '+escHtml(dadosEqtl.servico)+'</span>':'')
      +'</div>'
      +'</div>'
      +'<button class="btn btn-sm" id="apr-ver-'+a.id+'" style="flex-shrink:0">👁 Ver</button>'
      +'</div>'
      +'</div>';
  }).join('');

  // Bind buttons
  rows.forEach(function(a){
    var btn = document.getElementById('apr-ver-'+a.id);
    if(btn) btn.onclick = function(){
      if(_aprIsEqtl(a)) _verDetalheAPREqtl(a);
      else abrirDetalheAPR(a.id);
    };
  });
}

function _verDetalheAPREqtl(a){
  var eq   = equipes_disp.find(function(e){return e.id===a.equipe_id;})
           ||equipes.find(function(e){return e.id===a.equipe_id;});
  var dados = null;
  try{ dados = JSON.parse(a.respostas); } catch(e){}
  if(!dados && typeof a.respostas==='object') dados = a.respostas;
  if(!dados){ abrirDetalheAPR(a.id); return; }

  var resps = dados.respostas||{};
  var cor   = {S:'background:#F0FFF4;color:#3B6D11', N:'background:#FFF0F0;color:#A32D2D', NA:'background:#f9f9f7;color:#888'};
  var lbl   = {S:'SIM', N:'NÃO', NA:'N.A.'};

  var secsHtml = _APR_EQTL_SECOES.map(function(sec){
    var html = '<div style="margin-bottom:.5rem">'
      +'<div style="background:#E8F0FE;color:#185FA5;font-size:11px;font-weight:700;padding:.3rem .6rem;border-radius:5px;margin-bottom:3px">'+sec.titulo+'</div>';
    sec.perguntas.forEach(function(p){
      var resp = resps[p.id]||'';
      var obs  = resps[p.id+'_obs']||'';
      var estilo = cor[resp]||'background:#f5f5f3;color:#888';
      html += '<div style="display:grid;grid-template-columns:1fr 56px;gap:6px;padding:.35rem .5rem;border-bottom:.5px solid #f5f5f3;align-items:start">'
        +'<div style="font-size:11px">'
        +'<span style="font-weight:500">'+p.texto+'</span>'
        +(obs?'<div style="color:#777;font-size:10px;margin-top:2px">📝 '+escHtml(obs)+'</div>':'')
        +'</div>'
        +'<div style="text-align:center">'
        +'<span style="'+estilo+';border-radius:5px;padding:2px 7px;font-size:10px;font-weight:700">'+( lbl[resp]||'—')+'</span>'
        +'</div>'
        +'</div>';
    });
    html += '</div>';
    return html;
  }).join('');

  var eqLabel  = eq ? escHtml(eq.codigo+(eq.nome?' — '+eq.nome:'')) : '—';
  var nokTotal = 0;
  Object.keys(resps).forEach(function(k){
    if(resps[k]==='N' && k.indexOf('_obs')<0) nokTotal++;
  });

  setModal(
    '<div class="modal-bg"><div class="modal" style="max-width:640px;max-height:90vh;overflow-y:auto">'
    +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:.75rem">'
    +'<div>'
    +'<div style="font-weight:700;font-size:14px">⚡ APR Equatorial — NP_00078_EQTL</div>'
    +'<div style="font-size:11px;color:#888;margin-top:3px">'+eqLabel+' &nbsp;|&nbsp; '+fmtD(a.data)+'</div>'
    +'</div>'
    +'<div style="display:flex;gap:6px;align-items:center">'
    +(nokTotal>0?'<span class="bdg danger">'+nokTotal+' NOK</span>':'<span class="bdg ok">✅ Sem NOK</span>')
    +(_aprStatusLabel(a)==='recusada'?'<span class="bdg danger">⛔ Recusada</span>':'<span class="bdg ok">Aprovada</span>')
    +'</div>'
    +'</div>'
    // Cabeçalho
    +'<div style="background:#f9f9f7;border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .85rem;margin-bottom:.75rem;display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;font-size:11px">'
    +'<div><span style="color:#888">Empresa</span><div style="font-weight:600">'+(dados.empresa||'CENA')+'</div></div>'
    +'<div><span style="color:#888">Data</span><div style="font-weight:600">'+fmtD(dados.data||a.data)+'</div></div>'
    +'<div><span style="color:#888">Serviço</span><div style="font-weight:600">'+(dados.servico||'—')+'</div></div>'
    +'<div><span style="color:#888">Equipe</span><div style="font-weight:600">'+eqLabel+'</div></div>'
    +'<div><span style="color:#888">Nº OS</span><div style="font-weight:600">'+(dados.os_numero||'—')+'</div></div>'
    +'<div><span style="color:#888">Local</span><div style="font-weight:600">'+(dados.local||'—')+'</div></div>'
    +'</div>'
    // Perguntas
    +secsHtml
    // Croqui
    +(dados.croqui?'<div style="margin:.5rem 0;padding:.5rem .75rem;background:#f5f5f3;border-radius:6px"><div style="font-size:10px;font-weight:700;color:#533AB7;margin-bottom:4px">📐 CROQUI</div><div style="font-size:12px">'+escHtml(dados.croqui)+'</div></div>':'')
    // Responsáveis
    +(dados.resp_tensao||dados.resp_aterr?
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:.5rem 0;font-size:11px">'
      +(dados.resp_tensao?'<div><span style="color:#888">Resp. ausência de tensão</span><div style="font-weight:600">'+escHtml(dados.resp_tensao)+'</div></div>':'')
      +(dados.resp_aterr?'<div><span style="color:#888">Resp. aterramento</span><div style="font-weight:600">'+escHtml(dados.resp_aterr)+'</div></div>':'')
      +'</div>':'')
    // Direito de recusa
    +'<div style="background:'+(dados.recusa_sim?'#FFF0F0':'#F0FFF4')+';border-radius:8px;padding:.5rem .75rem;margin:.5rem 0;font-size:11px">'
    +'<b>Atividade segura:</b> '+(dados.atividade_segura===true?'✅ SIM':dados.atividade_segura===false?'⛔ NÃO':'—')
    +(dados.motivo_nao?' — '+escHtml(dados.motivo_nao):'')
    +'<br><b>Direito de recusa:</b> '+(dados.recusa_sim?'⚠️ SIM':'NÃO')
    +(dados.recusa_desc?' — '+escHtml(dados.recusa_desc):'')
    +'</div>'
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>'
  );
}

function _renderAPRsTabela(cid,mes,tb,eqId,data){
  var rows=aprs_registradas.filter(function(a){
    if(data&&a.data!==data)return false;
    if(!data&&mes&&a.data.indexOf(mes)<0)return false;
    if(eqId&&a.equipe_id!==eqId)return false;
    if(cid){var eq=equipes_disp.find(function(e){return e.id===a.equipe_id;});if(!eq||eq.contrato_id!==cid)return false;}
    return true;
  });

  if(!rows.length){
    var totalLocal=aprs_registradas.length;
    tb.innerHTML='<tr><td colspan="6" style="padding:1.5rem;text-align:center;color:#aaa">'
      +'Nenhuma APR registrada'+(mes?' em '+mes:'')+'.'
      +(totalLocal>0?'<br><span style="font-size:11px">'+totalLocal+' APR(s) em outros períodos.</span>':'')
      +'</td></tr>';
    return;
  }
  // continua abaixo
  var stCls={OK:'ok',NOK:'danger'};
  tb.innerHTML=rows.map(function(a){
    var eq=equipes_disp.find(function(e){return e.id===a.equipe_id;});
    var cl=checklists_templates.find(function(c){return c.id===a.checklist_id;});
    var respostas=parseJsonField(a.respostas,[]);
    var nokItens=respostas.filter(function(r){return r.resposta==='N';}).length;
    var temFotos=respostas.some(function(r){return r.foto;});
    return '<tr>'
      +'<td data-label="Data" style="font-size:11px">'+fmtD(a.data)+'</td>'
      +'<td data-label="Equipe" style="font-weight:500">'+(eq?eq.codigo+' — '+eq.nome:'—')+'</td>'
      +'<td data-label="Ordem" style="font-size:11px">'+(a.ordem_id||'—')+'</td>'
      +'<td data-label="Checklist" style="font-size:12px">'+(cl?cl.nome:'—')+'</td>'
      +'<td data-label="Resultado">'
        +'<span class="bdg '+(stCls[a.resultado]||'gray')+'">'+(a.resultado||'—')+'</span>'
        +(nokItens>0?'<span class="bdg danger" style="font-size:10px;margin-left:4px">'+nokItens+' NOK</span>':'')
        +(temFotos?'<span style="font-size:10px;color:#185FA5;margin-left:4px">📷</span>':'')
      +'</td>'
      +'<td><button class="btn btn-sm" id="btn-ver-apr-'+a.id+'">Ver detalhes</button></td>'
      +'</tr>';
  }).join('');
  rows.forEach(function(a){
    var btn=document.getElementById('btn-ver-apr-'+a.id);
    if(btn)btn.onclick=function(){abrirDetalheAPR(a.id);};
  });
// -- função renderAPRs encerrada acima, _renderAPRsTabela continua:
if(false){
}
// fim _renderAPRsTabela
}


// ═══════════════════════════════════════════════════════════════════════
// APR EQUATORIAL — Análise Preliminar de Riscos (NP_00078_EQTL)
// Construção de Rede de Distribuição e Linha de Transmissão
// ═══════════════════════════════════════════════════════════════════════

// IDs de contratos/clientes Equatorial
var _EQTL_CONTRATO_CODIGOS = ['EQUATORIAL','EQTL','4600003971','4600004482','RDSC','RDSE'];

function _isContratoEquatorial(contratoId){
  if(!contratoId) return false;
  var c = contratos.find(function(x){ return x.id===contratoId; });
  if(!c) return false;
  var nome = ((c.nome||'')+(c.codigo||'')+(c.cliente||'')).toUpperCase();
  return nome.includes('EQUATORIAL') || nome.includes('EQTL') ||
    _EQTL_CONTRATO_CODIGOS.some(function(cod){ return (c.codigo||'').toUpperCase()===cod; });
}

// Dados da APR em memória (sessão atual)
var _aprEqtlDados = null;

function abrirAPREquatorial(contratoId, equipeId, data, osNumero){
  _aprEqtlDados = {
    id:          'apr-eqtl-'+Date.now(),
    contrato_id: contratoId||'',
    equipe_id:   equipeId||(_dbEquipe&&_dbEquipe.id)||'',
    data:        data||dataHojeLocal(),
    os_numero:   osNumero||'',
    empresa:     'CENA',
    servico:     '',
    local:       '',
    respostas:   {},  // {q1: 'S'|'N'|'NA', ...}
    responsavel_tensao:   '',
    responsavel_aterr:    '',
    assinatura_tensao:    '',
    assinatura_aterr:     '',
    colaboradores:        [],
    croqui_url:           '',
    recusa_sim:           false,
    recusa_desc:          '',
    atividade_segura:     null,
    criado_em:            new Date().toISOString(),
    salvo:                false,
  };
  _renderModalAPREqtl();
}

var _APR_EQTL_SECOES = [
  {
    titulo: 'Verificação do risco de acidente trânsito',
    perguntas: [
      {id:'q1', texto:'1. Será necessário reposicionar o veículo para maior segurança?', medida:'Manobrar veículo de acordo com o CTB e o POP.00110.EQTL - Atividades Preliminares de Segurança'},
      {id:'q2', texto:'2. Existe risco de colisão?', medida:'Sinalizar veículo com cone e ligar pisca alerta de acordo com o POP.00110.EQTL'},
      {id:'q3', texto:'3. Existe risco de atropelamento?', medida:'Ficar atento ao fluxo de veículos e não utilizar celular/PDA/tablet na via. Não dar passos para trás em direção à via. Fazer corredor seguro para pedestre.'},
      {id:'q4', texto:'4. Existe o risco do veículo deslocar-se acidentalmente?', medida:'Manter veículo com freio estacionário acionado e calçar rodas conforme POP.00110.EQTL'},
    ]
  },
  {
    titulo: 'Verificação do risco de ataque de animais',
    perguntas: [
      {id:'q5', texto:'5. Existe casa de abelhas, marimbondos ou similar no local ou proximidades?', medida:'Não atacar a casa de abelhas/marimbondos. Utilizar vestimenta de apicultor para remoção. Utilizar luvas de vaqueta.'},
      {id:'q6', texto:'6. Existe risco de ataque de animais?', medida:'Não se aproximar do animal, não agredir ou brincar. Utilizar calçado de segurança, perneira, luvas de vaqueta e vestimentas adequadas.'},
    ]
  },
  {
    titulo: 'Verificação dos riscos do local de trabalho em solo',
    perguntas: [
      {id:'q7', texto:'7. O local de trabalho é irregular, com desníveis, buracos, obstáculos ou superfície lisa?', medida:'Utilizar botina de segurança devidamente calçada. Ficar atento por onde pisa, não correr ou saltar. Não caminhar utilizando celular/tablet/PDA.'},
      {id:'q8', texto:'8. No local de trabalho possui objetos cortantes e perfurantes?', medida:'Remover objetos com luvas vaqueta. Caminhar atento ao local e utilizar calçado de segurança.'},
      {id:'q9', texto:'9. Existe risco de contato com superfície abrasiva, escoriante, perfurante e cortante no manuseio de ferramentas?', medida:'Guardar e transportar ferramentas de corte em bainha. Utilizar luvas de vaqueta.'},
    ]
  },
  {
    titulo: 'Verificação do risco durante acesso à carroceria e cabine suplementar',
    perguntas: [
      {id:'q10', texto:'10. Existe risco de queda durante a subida ou descida da carroceria do caminhão?', medida:'Não saltar da carroceria. Utilizar escada móvel. Manter sempre 3 pontos de apoio. Manter degraus livres de graxa/óleo/lama.'},
      {id:'q11', texto:'11. Existe risco de queda durante a permanência em cima da carroceria?', medida:'Não movimentar veículo com colaborador em cima. Manter materiais organizados. Não correr ou saltar obstáculos.'},
      {id:'q12', texto:'12. Existe risco de queda durante a subida ou descida da cabine suplementar?', medida:'Não saltar da cabine. Utilizar escada. Manter sempre 3 pontos de apoio. Manter degraus livres de graxa/óleo/lama.'},
    ]
  },
  {
    titulo: 'Verificação do risco de trabalho em altura',
    perguntas: [
      {id:'q13', texto:'13. Existe risco de queda de materiais e ferramentas?', medida:'Manter ferramentas em balde de lona. Não arremessar objetos. Sinalizar e isolar área. Utilizar capacete com jugular.'},
      {id:'q14', texto:'14. A estrutura de apoio da escada oferece condições de acesso seguro?', medida:'Fazer inspeção visual conforme POP 00111.EQTL. Verificar engastamento, danos estruturais, ângulo de inclinação, sinais de descarga atmosférica e podridão.'},
      {id:'q15', texto:'15. Existe risco de queda de altura?', medida:'Verificar condições de acesso. Amarrar escada na parte inferior e superior. Utilizar SPIQ (cinto paraquedista, trava-quedas, talabarte). Não sair da caçamba durante atividade. Conectar talabarte no ponto definido pelo fabricante.'},
      {id:'q16', texto:'16. A estrutura sofreu danos críticos durante a movimentação?', medida:'Não implantar estrutura danificada.'},
    ]
  },
  {
    titulo: 'Verificação do risco de choque elétrico e arco elétrico',
    perguntas: [
      {id:'q17', texto:'17. A atividade será realizada com rede próxima energizada? Existe risco de choque elétrico?', medida:'Utilizar ferramentas e coberturas isolantes. Utilizar luvas/manga de borracha. Utilizar capacete classe B com jugular, vestimenta RF e calçado com proteção.'},
      {id:'q18', texto:'18. Existe risco de contato acidental com partes energizadas de outra rede?', medida:'Analisar áreas vivas de contato. Verificar distâncias de segurança. Manter distância segura. Utilizar ferramentas isoladas. Evitar movimentos bruscos.'},
      {id:'q19', texto:'19. O trabalho será realizado com instalação desenergizada? Existe risco de energização acidental?', medida:'Seccionar → Impedir reenergização → Constatar ausência de tensão → Instalar aterramento temporário → Proteger elementos energizados → Instalar sinalização (conforme POP.00112.EQTL)'},
      {id:'q20', texto:'20. O local pode sofrer energização acidental por outro circuito?', medida:'Verificar fonte de energização acidental. Instalar placa de advertência. Proteger zona com aterramento temporário conforme POP.00112.EQTL.'},
      {id:'q21', texto:'21. Durante energização da rede existe risco de falha de comunicação com o COI?', medida:'Manter contato permanente com o COI até finalização conforme POP.006.EQTL. Solicitar ao controlador que informe troca de turno.'},
      {id:'q22', texto:'22. O COI tem conhecimento de que a equipe está no local para realizar a energização?', medida:'Informar nome do controlador e horário do contato. Solicitar aviso de troca de turno.'},
    ]
  },
  {
    titulo: 'Verificação do risco de movimentação de materiais',
    perguntas: [
      {id:'q23', texto:'23. A área de trabalho permite movimentação segura do material?', medida:'Manter na área apenas trabalhadores diretamente envolvidos. Sinalizar e isolar local conforme POP.00110.EQTL.'},
      {id:'q24', texto:'24. Os acessórios para movimentação estão disponíveis e em condições seguras?', medida:'Selecionar acessórios adequados e em bom estado. Inspecionar antes e após o uso e substituir itens danificados.'},
      {id:'q25', texto:'25. O equipamento de elevação de cargas está em condições seguras?', medida:'Verificar indício de perda de força, vazamento de óleo hidráulico e componentes comprometidos.'},
      {id:'q26', texto:'26. Existe risco de tombamento do caminhão durante movimentação da carga?', medida:'Verificar resistência do solo. Posicionar veículo em local seguro. Manter estabilizadores acionados em base resistente. Não exceder capacidade de carga conforme POP.085.EQTL.'},
      {id:'q27', texto:'27. Existe risco de esmagamento ou ser atingido por carga em movimento?', medida:'Não ficar sob carga suspensa. Não ficar no raio de movimentação. Não permanecer sobre carroceria com carga içada. Utilizar corda guia. Manter visão permanente sobre a carga.'},
      {id:'q28', texto:'28. Existe risco de queda, prensamento ou esmagamento durante movimentação manual?', medida:'Não movimentar manualmente cargas pesadas. Utilizar luvas vaqueta e calçado de segurança. Não arremessar objetos próximo a colaboradores.'},
      {id:'q29', texto:'29. Existe risco de energização do equipamento de guindar por indução ou contato acidental?', medida:'Desenergizar circuito onde pode ocorrer aproximação/contato acidental. Instalar coberturas isolantes.'},
    ]
  },
  {
    titulo: 'Verificação dos riscos na escavação, montagem e nivelamento de cabos',
    perguntas: [
      {id:'q30', texto:'30. Existe risco de impacto ou corte/perfuração durante escavação manual?', medida:'Manter no local apenas trabalhador diretamente envolvido. Sinalizar e isolar área. Utilizar luvas de raspa, calçado, óculos e capacete. Instalar sinalização noturna se necessário.'},
      {id:'q31', texto:'31. Existe risco de esmagamento durante montagem de estruturas em solo?', medida:'Não manter estrutura suspensa somente pelo guindauto. Apoiar em cavalete resistente até final da montagem.'},
      {id:'q32', texto:'32. Há risco de colapso de estrutura durante tensionamento/nivelamento de cabos?', medida:'Instalar estai provisório. Não permanecer em cima de estrutura durante tensionamento. Manter supervisão permanente.'},
    ]
  },
  {
    titulo: 'Verificação de outros riscos',
    perguntas: [
      {id:'q33', texto:'33. Todos os membros da equipe estão em condições de realizar a atividade?', medida:'Descrever motivo de não estar apto:', obs:true},
      {id:'q34', texto:'34. Existe outro risco não identificado acima?', medida:'Descrever:', obs:true},
    ]
  },
];

function _renderModalAPREqtl(){
  // Remove modal anterior
  var old = document.getElementById('modal-apr-eqtl');
  if(old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'modal-apr-eqtl';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-start;justify-content:center;overflow-y:auto;padding:1rem';

  var inner = document.createElement('div');
  inner.style.cssText = 'background:#fff;border-radius:14px;width:100%;max-width:800px;padding:0;margin:auto;overflow:hidden;box-shadow:0 8px 40px rgba(0,0,0,.2)';

  // Header
  var hdr = '<div style="background:#1a1a18;padding:1rem 1.25rem;display:flex;justify-content:space-between;align-items:center">'
    + '<div>'
    + '<div style="color:#fff;font-weight:700;font-size:15px">⚡ APR — Análise Preliminar de Riscos</div>'
    + '<div style="color:#aaa;font-size:11px;margin-top:2px">Equatorial — Construção de RD e LT (NP_00078_EQTL)</div>'
    + '</div>'
    + '<button onclick="var m=document.getElementById(\'modal-apr-eqtl\');if(m)m.remove();" style="background:none;border:none;color:#fff;font-size:20px;cursor:pointer;padding:4px 8px">✕</button>'
    + '</div>';

  // Cabeçalho da APR
  var cab = '<div style="padding:1rem 1.25rem;border-bottom:.5px solid #e0dfd8;background:#f9f9f7">'
    + '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:8px">'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">Empresa</label><input class="inp" id="apr-eq-empresa" value="CENA" style="width:100%"/></div>'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">Data</label><input class="inp" type="date" id="apr-eq-data" value="'+(_aprEqtlDados.data||dataHojeLocal())+'" style="width:100%"/></div>'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">Serviço / Tipo</label><input class="inp" id="apr-eq-servico" placeholder="Ex: Construção de RD" style="width:100%"/></div>'
    + '</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px">'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">Equipe</label><input class="inp" id="apr-eq-equipe" value="'+(_dbEquipe?(_dbEquipe.codigo||_dbEquipe.nome||''):'')+'" style="width:100%"/></div>'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">Nº da OS</label><input class="inp" id="apr-eq-os" value="'+(_aprEqtlDados.os_numero||'')+'" placeholder="Número da OS" style="width:100%"/></div>'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">Local / Endereço</label><input class="inp" id="apr-eq-local" placeholder="Endereço do serviço" style="width:100%"/></div>'
    + '</div>'
    + '</div>';

  // Tabela de perguntas
  var tabela = '<div style="padding:1rem 1.25rem">'
    + '<div style="background:#1a1a18;color:#fff;padding:.5rem .75rem;border-radius:8px 8px 0 0;font-size:11px;font-weight:700;display:grid;grid-template-columns:1fr 80px 80px 80px;gap:4px;text-align:center">'
    + '<div style="text-align:left">RESPONDA ANTES DE INICIAR — MEDIDA DE CONTROLE</div>'
    + '<div>SIM</div><div>NÃO</div><div>N.A.</div>'
    + '</div>';

  _APR_EQTL_SECOES.forEach(function(sec){
    tabela += '<div style="background:#E8F0FE;padding:.4rem .75rem;font-size:11px;font-weight:700;color:#185FA5;border-bottom:.5px solid #d0d8f0">'
      + sec.titulo + '</div>';
    sec.perguntas.forEach(function(p){
      var id = p.id;
      tabela += '<div style="border-bottom:.5px solid #f0efe8;padding:.5rem .75rem;display:grid;grid-template-columns:1fr 80px 80px 80px;gap:4px;align-items:start">'
        + '<div>'
        + '<div style="font-size:12px;font-weight:500;margin-bottom:2px">'+p.texto+'</div>'
        + '<div style="font-size:10px;color:#777;font-style:italic">'+p.medida+'</div>'
        + (p.obs ? '<input class="inp" id="apr-eq-obs-'+id+'" placeholder="Descrever..." style="width:100%;margin-top:4px;font-size:11px"/>' : '')
        + '</div>'
        + '<div style="text-align:center;padding-top:2px"><input type="radio" name="apr-'+id+'" value="S" id="apr-'+id+'-s" style="cursor:pointer;width:16px;height:16px"/></div>'
        + '<div style="text-align:center;padding-top:2px"><input type="radio" name="apr-'+id+'" value="N" id="apr-'+id+'-n" style="cursor:pointer;width:16px;height:16px"/></div>'
        + '<div style="text-align:center;padding-top:2px"><input type="radio" name="apr-'+id+'" value="NA" id="apr-'+id+'-na" style="cursor:pointer;width:16px;height:16px"/></div>'
        + '</div>';
    });
  });
  tabela += '</div>';

  // Croqui + Notas NR-10
  var croqui = '<div style="padding:0 1.25rem 1rem">'
    + '<div style="font-size:11px;font-weight:700;color:#533AB7;margin-bottom:4px">📐 CROQUI DA LINHA</div>'
    + '<div style="font-size:10px;color:#777;margin-bottom:6px">Faça um croqui da linha onde irá trabalhar e identifique onde serão instalados aterramentos temporários e possíveis fontes de energização acidental.</div>'
    + '<textarea id="apr-eq-croqui" class="inp" rows="3" placeholder="Descreva ou descreva o croqui..." style="width:100%;font-size:12px"></textarea>'
    + '</div>';

  // Responsáveis
  var resp = '<div style="padding:0 1.25rem 1rem;display:grid;grid-template-columns:1fr 1fr;gap:12px">'
    + '<div class="fg"><label style="font-size:11px;font-weight:700">32. Responsável pela constatação de ausência de tensão</label>'
    + '<input class="inp" id="apr-eq-resp-tensao" placeholder="Nome" style="width:100%;margin-top:4px"/></div>'
    + '<div class="fg"><label style="font-size:11px;font-weight:700">33. Responsável pela instalação do aterramento temporário</label>'
    + '<input class="inp" id="apr-eq-resp-aterr" placeholder="Nome" style="width:100%;margin-top:4px"/></div>'
    + '</div>';

  // Direito de Recusa + Atividade Segura
  var recusa = '<div style="padding:0 1.25rem 1rem;background:#FEF3E2;border:.5px solid #F9A825;border-radius:8px;margin:0 1.25rem 1rem">'
    + '<div style="font-size:11px;font-weight:700;color:#854F0B;margin-bottom:6px">⚠ DIREITO DE RECUSA</div>'
    + '<div style="font-size:10px;color:#7B4F00;margin-bottom:8px">O trabalhador poderá interromper suas atividades quando constatar situação de risco grave e iminente, informando imediatamente ao superior hierárquico.</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">34. Após avaliação, é possível realizar a atividade com segurança?</label>'
    + '<div style="display:flex;gap:12px;margin-top:4px">'
    + '<label style="display:flex;align-items:center;gap:4px;font-size:12px"><input type="radio" name="apr-ativ-segura" value="S" id="apr-ativ-s"> SIM</label>'
    + '<label style="display:flex;align-items:center;gap:4px;font-size:12px"><input type="radio" name="apr-ativ-segura" value="N" id="apr-ativ-n"> NÃO</label>'
    + '</div>'
    + '<input class="inp" id="apr-eq-motivo-nao" placeholder="Se NÃO, descrever motivo..." style="width:100%;margin-top:4px;font-size:11px"/>'
    + '</div>'
    + '<div class="fg"><label style="font-size:11px;font-weight:600">35. Necessita utilizar Direito de Recusa?</label>'
    + '<div style="display:flex;gap:12px;margin-top:4px">'
    + '<label style="display:flex;align-items:center;gap:4px;font-size:12px"><input type="radio" name="apr-recusa" value="S" id="apr-recusa-s"> SIM</label>'
    + '<label style="display:flex;align-items:center;gap:4px;font-size:12px"><input type="radio" name="apr-recusa" value="N" id="apr-recusa-n"> NÃO</label>'
    + '</div>'
    + '<input class="inp" id="apr-eq-recusa-desc" placeholder="Se SIM, registrar nome do superior e providências tomadas..." style="width:100%;margin-top:4px;font-size:11px"/>'
    + '</div>'
    + '</div>'
    + '</div>';

  // Colaboradores que participaram
  var colabs = '<div style="padding:0 1.25rem 1rem">'
    + '<div style="font-size:11px;font-weight:700;margin-bottom:6px">👥 COLABORADORES QUE PARTICIPARAM DA APR</div>'
    + '<div id="apr-eq-colabs-lista" style="display:grid;grid-template-columns:1fr 1fr;gap:8px"></div>'
    + '</div>';

  // Botões finais
  var btns = '<div style="padding:1rem 1.25rem;border-top:.5px solid #e0dfd8;display:flex;gap:8px;justify-content:flex-end;background:#f9f9f7">'
    + '<button class="btn" onclick="var m=document.getElementById(\'modal-apr-eqtl\');if(m)m.remove();">Cancelar</button>'
    + '<button class="btn btn-pri" onclick="salvarAPREquatorial()" style="background:#185FA5">💾 Salvar APR</button>'
    + '</div>';

  inner.innerHTML = hdr + cab + tabela + croqui + resp + recusa + colabs + btns;
  modal.appendChild(inner);
  document.body.appendChild(modal);

  // Preencher colaboradores da equipe
  setTimeout(function(){
    var lista = document.getElementById('apr-eq-colabs-lista');
    if(lista && _dbEquipe){
      var comp = composicao_dia.find(function(c){ return c.equipe_id===_dbEquipe.id; });
      var ids  = comp ? parseJsonField(comp.colaborador_ids,[]) : [];
      var cols = colaboradores.filter(function(c){ return ids.indexOf(c.id)>=0; });
      if(cols.length){
        lista.innerHTML = cols.map(function(c,i){
          return '<div class="fg"><label style="font-size:11px">Matrícula '+(i+1)+'</label>'
            + '<input class="inp" value="'+(c.re||c.matricula||'')+'  —  '+c.nome+'" readonly style="width:100%;font-size:11px"/>'
            + '</div>';
        }).join('');
      } else {
        lista.innerHTML = '<div style="color:#aaa;font-size:12px">Nenhum colaborador na composição do dia.</div>';
      }
    }
  }, 100);
}

function salvarAPREquatorial(){
  if(!_aprEqtlDados){ progShowToast('⚠ Dados da APR não encontrados'); return; }
  var d = _aprEqtlDados;
  d.empresa   = (document.getElementById('apr-eq-empresa')||{}).value||'CENA';
  d.data      = (document.getElementById('apr-eq-data')||{}).value||dataHojeLocal();
  d.servico   = (document.getElementById('apr-eq-servico')||{}).value||'';
  d.local     = (document.getElementById('apr-eq-local')||{}).value||'';
  d.os_numero = (document.getElementById('apr-eq-os')||{}).value||'';
  d.croqui    = (document.getElementById('apr-eq-croqui')||{}).value||'';
  d.resp_tensao = (document.getElementById('apr-eq-resp-tensao')||{}).value||'';
  d.resp_aterr  = (document.getElementById('apr-eq-resp-aterr')||{}).value||'';
  d.motivo_nao  = (document.getElementById('apr-eq-motivo-nao')||{}).value||'';
  d.recusa_desc = (document.getElementById('apr-eq-recusa-desc')||{}).value||'';
  // Atividade segura
  var ativS = document.getElementById('apr-ativ-s');
  var ativN = document.getElementById('apr-ativ-n');
  d.atividade_segura = ativS&&ativS.checked ? true : (ativN&&ativN.checked ? false : null);
  // Recusa
  var recS = document.getElementById('apr-recusa-s');
  d.recusa_sim = recS&&recS.checked;
  // Respostas de cada pergunta
  d.respostas = {};
  _APR_EQTL_SECOES.forEach(function(sec){
    sec.perguntas.forEach(function(p){
      var el = document.querySelector('input[name="apr-'+p.id+'"]:checked');
      d.respostas[p.id] = el ? el.value : '';
      if(p.obs){
        var obs = document.getElementById('apr-eq-obs-'+p.id);
        if(obs) d.respostas[p.id+'_obs'] = obs.value;
      }
    });
  });
  d.salvo = true;
  d.criado_em = new Date().toISOString();

  // Salvar no banco como APR registrada
  if(!DEMO){
    var dSave=Object.assign({},d,{tipo:'APR-EQTL',tipo_apr:'APR-EQTL',os_numero:d.os_numero});
    sbInsertAprsRegistradas({
      equipe_id:   d.equipe_id,
      data:        d.data,
      ordem_id:    String(d.os_numero||''),
      tipo:        'APR-EQTL',
      status:      d.atividade_segura===false ? 'recusada' : 'aprovada',
      resultado:   d.atividade_segura===false ? 'NOK' : 'OK',
      respostas:   dSave,
      criado_em:   d.criado_em,
    }).then(function(res){
      if(res&&res[0]){ d.id_banco = res[0].id; }
    }).catch(function(){});
  }
  document.getElementById('modal-apr-eqtl').remove();
  progShowToast('✅ APR Equatorial salva com sucesso!');
  // Registrar evento na sessão
  if(_dbSessao){
    var ev = {tipo:'APR', ts:Date.now(), obs:'APR EQTL salva — OS '+d.os_numero};
    _dbSessao.eventos = _dbSessao.eventos||[];
    _dbSessao.eventos.push(ev);
  }
}

// ── Abrir APR correta conforme contrato ────────────────────────────
// Chamada quando equipe clica em "APR" no diário de bordo
function dbAbrirAPR(osNumero){
  var cid = _dbEquipe ? _dbEquipe.contrato_id : (usuarioLogado&&usuarioLogado.contrato_id||'');
  if(_isContratoEquatorial(cid)){
    abrirAPREquatorial(cid, _dbEquipe&&_dbEquipe.id, dataHojeLocal(), osNumero||'');
  } else {
    // APR padrão (modal existente)
    showSub('campo-apr');
  }
}


function abrirDetalheAPR(aprId){
  var a=aprs_registradas.find(function(x){return x.id===aprId;});
  if(!a)return;
  var eq=equipes_disp.find(function(e){return e.id===a.equipe_id;});
  var cl=checklists_templates.find(function(c){return c.id===a.checklist_id;});
  var respostas=parseJsonField(a.respostas,[]);
  var stCls={OK:'ok',NOK:'danger'};
  var resLabels={C:'✅ Conforme',N:'❌ Não conforme',A:'— Não se aplica'};

  var itensHtml=respostas.map(function(r,i){
    var template_item=cl?cl.itens.find(function(it){return it.id===r.item_id;}):null;
    var pergunta=r.pergunta||(template_item?template_item.pergunta:'Item '+(i+1));
    var resLabel=resLabels[r.resposta]||r.resposta||'—';
    var corBg=r.resposta==='N'?'background:#FFF0F0;border-color:#F5C6CB':
               r.resposta==='C'?'background:#F0FFF4;border-color:#C3E6CB':'background:#f9f9f7;border-color:#e0dfd8';
    return '<div style="border:.5px solid;border-radius:8px;padding:.65rem .85rem;margin-bottom:.5rem;'+corBg+'">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
      +'<div style="font-size:12px;font-weight:500;flex:1">'+(i+1)+'. '+pergunta+'</div>'
      +'<span style="font-size:12px;white-space:nowrap;flex-shrink:0">'+resLabel+'</span>'
      +'</div>'
      +(r.foto
        ?'<div style="margin-top:.6rem">'
          +'<img src="'+r.foto+'" style="width:72px;height:72px;border-radius:8px;object-fit:cover;border:.5px solid #e0dfd8;display:block;margin-bottom:4px"/>'
          +'<button class="btn-foto-full" data-src="'+encodeURIComponent(r.foto)+'" style="font-size:11px;color:#185FA5;background:none;border:.5px solid #185FA5;border-radius:6px;padding:4px 10px;cursor:pointer;margin-top:2px">🔍 Ver foto completa</button>'
          +'</div>'
        :'')
      +'</div>';
  }).join('');

  if(!itensHtml){
    itensHtml='<div style="color:#aaa;font-size:12px;padding:1rem;text-align:center">Nenhuma resposta registrada nesta APR.</div>';
  }

  setModal(
    '<div class="modal-bg"><div class="modal" style="max-width:560px">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem">'
    +'<div>'
    +'<h3 style="margin:0">APR — Análise Preliminar de Risco</h3>'
    +'<div style="font-size:12px;color:#888;margin-top:3px">'
    +(eq?eq.codigo+' — '+eq.nome:'—')+' &nbsp;|&nbsp; '+fmtD(a.data)
    +(a.ordem_id?' &nbsp;|&nbsp; Ordem: '+a.ordem_id:'')
    +'</div>'
    +'</div>'
    +'<span class="bdg '+(stCls[a.resultado]||'gray')+'" style="font-size:13px;padding:5px 12px">'+(a.resultado||'—')+'</span>'
    +'</div>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">'
    +'Checklist: <b>'+(cl?cl.nome:'—')+'</b>'
    +'</div>'
    +'<div style="max-height:420px;overflow-y:auto">'
    +itensHtml
    +'</div>'
    +(a.foto?'<div style="margin-top:.75rem;padding-top:.75rem;border-top:.5px solid #e0dfd8"><div style="font-size:11px;color:#888;margin-bottom:.35rem">📷 Foto geral da APR</div><img src="'+a.foto+'" style="width:100%;border-radius:8px;max-height:200px;object-fit:cover"/></div>':'')
    +'<div class="ma" style="margin-top:1rem">'
    +'<button class="btn" onclick="closeModal()">Fechar</button>'
    +'</div>'
    +'</div></div>'
  );
}

// ══════════════════════════════════════════════════════════
// REQUISIÇÃO DE MATERIAIS — OBRAS
// ══════════════════════════════════════════════════════════
var requisicoes_obras = []; // {id,projeto_id,solicitante,material_id,descricao,qtd,unidade,motivo,status,data}

function renderRequisicaoObras(){
  var tb=document.getElementById('tbody-req-obras');if(!tb)return;
  var filtStatus = (document.getElementById('fil-req-status')||{}).value||'';
  var rows=requisicoes_obras.concat(sol_materiais||[]);
  if(filtStatus) rows = rows.filter(function(r){ return r.status===filtStatus; });
  if(!rows.length){
    tb.innerHTML='<tr><td colspan="8" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma requisição encontrada</td></tr>';
    return;
  }
  var stCls={Pendente:'warn',Aprovada:'ok',Recusada:'danger','Em separação':'info',Entregue:'teal'};
  tb.innerHTML=rows.map(function(r){
    var fil = (typeof filiais!=='undefined' && r.filial_id)
      ? (filiais.find(function(f){return f.id===r.filial_id;})||{}).nome||'—' : '—';
    var dep = (typeof depositos!=='undefined' && r.deposito_id)
      ? (depositos.find(function(d){return d.id===r.deposito_id;})||{}).nome||'—' : '—';
    return '<tr>'
      +'<td style="font-size:11px">'+fmtD(r.data||r.data_necessidade||r.criado_em)+'</td>'
      +'<td style="font-size:11px">'+fNomeProj(r.projeto_id)+'</td>'
      +'<td>'+(r.solicitante||r.encarregado_nome||'—')+'</td>'
      +'<td style="font-weight:500">'+(r.descricao||'—')+'</td>'
      +'<td>'+r.qtd+' '+(r.unidade||'UN')+'</td>'
      +'<td style="font-size:11px">'+fil+(dep!=='—'?' / '+dep:'')+'</td>'
      +'<td><span class="bdg '+(stCls[r.status]||'gray')+'">'+r.status+'</span></td>'
      +'<td style="display:flex;gap:4px">'
      +(r.status==='Pendente'?'<button class="btn btn-sm" id="apr-req-'+r.id+'">✓ Aprovar</button><button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" id="rec-req-'+r.id+'">✗ Recusar</button>':'')
      +(r.status==='Aprovada'?'<button class="btn btn-sm" style="color:#185FA5;border-color:#185FA5" id="sep-req-'+r.id+'">📦 Separar</button>':'')
      +(r.status==='Em separação'?'<button class="btn btn-sm" style="color:#3B6D11;border-color:#3B6D11" id="ent-req-'+r.id+'">✓ Entregar</button>':'')
      +'</td></tr>';
  }).join('');
  rows.forEach(function(r){
    if(r.status==='Pendente'){
      var ba=document.getElementById('apr-req-'+r.id);
      if(ba)ba.onclick=function(){r.status='Aprovada';if(!DEMO)sbUpdate('sol_materiais',{status:'Aprovada'},'id=eq.'+r.id);renderRequisicaoObras();};
      var br=document.getElementById('rec-req-'+r.id);
      if(br)br.onclick=function(){r.status='Recusada';if(!DEMO)sbUpdate('sol_materiais',{status:'Recusada'},'id=eq.'+r.id);renderRequisicaoObras();};
    }
    if(r.status==='Aprovada'){
      var bs=document.getElementById('sep-req-'+r.id);
      if(bs)bs.onclick=function(){r.status='Em separação';if(!DEMO)sbUpdate('sol_materiais',{status:'Em separação'},'id=eq.'+r.id);renderRequisicaoObras();progShowToast('📦 Material em separação');};
    }
    if(r.status==='Em separação'){
      var be=document.getElementById('ent-req-'+r.id);
      if(be)be.onclick=function(){r.status='Entregue';if(!DEMO)sbUpdate('sol_materiais',{status:'Entregue'},'id=eq.'+r.id);renderRequisicaoObras();progShowToast('✅ Material entregue à equipe');};
    }
  });
}

