function dbAbrirAPR(){
  if(!_dbOrdemAtual)return;
  var aprs=checklists_templates.filter(function(c){return c.tipo==='APR';});
  if(!aprs.length){alert('Nenhum checklist APR cadastrado. Configure em Campo > Checklists.');return;}

  var opts=aprs.map(function(a){return '<option value="'+a.id+'">'+a.nome+'</option>';}).join('');
  var ma=document.getElementById('modal-area');
  ma.style.pointerEvents='auto';
  ma.innerHTML='<div class="modal-bg"><div class="modal" style="max-width:500px">'
    +'<h3>⚠️ APR — Análise Preliminar de Risco</h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">Ordem #'+_dbOrdemAtual.numero_ordem+'</div>'
    +'<div class="fg"><label>Selecione o checklist APR</label>'
    +'<select id="apr-sel" style="width:100%">'+opts+'</select></div>'
    +'<div id="apr-itens" style="margin-top:.75rem"></div>'
    +'<div class="ma"><button class="btn" id="btn-cancelar-apr">Cancelar</button>'
    +'<button class="btn btn-pri" id="btn-salvar-apr">Salvar APR</button></div>'
    +'</div></div>';

  // Armazenar fotos por item: {itemIndex: base64}
  var aprFotos = {};

  function loadAprItens(){
    aprFotos = {};
    var sel=document.getElementById('apr-sel');
    var tid=sel?sel.value:'';
    var t=checklists_templates.find(function(x){return x.id===tid;});
    var div=document.getElementById('apr-itens');
    if(!div||!t)return;

    div.innerHTML=t.itens.map(function(it,i){
      return '<div style="padding:10px 0;border-bottom:.5px solid #f0efe8">'
        // Pergunta
        +'<div style="font-size:13px;font-weight:500;margin-bottom:6px">'
        +(i+1)+'. '+it.pergunta
        +(it.obrigatorio?'<span style="color:#A32D2D"> *</span>':'')
        +'</div>'
        // Respostas
        +'<div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:6px">'
        +'<label style="font-size:13px;display:flex;align-items:center;gap:6px;cursor:pointer;padding:5px 8px;border-radius:8px;border:1.5px solid #e0dfd8;min-width:90px">'
        +'<input type="radio" name="apr-'+i+'" value="C" style="width:16px;height:16px"/> ✅ Conforme</label>'
        +'<label style="font-size:13px;display:flex;align-items:center;gap:6px;cursor:pointer;padding:5px 8px;border-radius:8px;border:1.5px solid #e0dfd8;min-width:110px">'
        +'<input type="radio" name="apr-'+i+'" value="N" style="width:16px;height:16px"/> ❌ Não conforme</label>'
        +'<label style="font-size:13px;display:flex;align-items:center;gap:6px;cursor:pointer;padding:5px 8px;border-radius:8px;border:1.5px solid #e0dfd8;min-width:90px">'
        +'<input type="radio" name="apr-'+i+'" value="A" style="width:16px;height:16px"/> — N/A</label>'
        +'</div>'
        // Botão de foto
        +(it.foto_obrigatoria
          ?'<div style="display:flex;align-items:center;gap:8px;margin-top:4px">'
            +'<input type="file" accept="image/*" capture="environment" id="apr-foto-input-'+i+'" style="display:none"/>'
            +'<button class="btn" id="apr-foto-btn-'+i+'" style="font-size:12px;padding:6px 12px;border-color:#854F0B;color:#854F0B">📷 Tirar foto (obrigatório)</button>'
            +'<div id="apr-foto-preview-'+i+'" style="display:none">'
            +'<img id="apr-foto-img-'+i+'" style="width:50px;height:50px;border-radius:6px;object-fit:cover;border:.5px solid #e0dfd8"/>'
            +'<span style="font-size:10px;color:#3B6D11;margin-left:4px">✓ Foto adicionada</span>'
            +'</div>'
            +'</div>'
          :'')
        +'</div>';
    }).join('');

    // Vincular eventos dos botões de foto
    t.itens.forEach(function(it,i){
      if(!it.foto_obrigatoria)return;
      var btn=document.getElementById('apr-foto-btn-'+i);
      var inp=document.getElementById('apr-foto-input-'+i);
      var prev=document.getElementById('apr-foto-preview-'+i);
      var img=document.getElementById('apr-foto-img-'+i);
      if(btn&&inp){
        btn.onclick=function(){inp.click();};
        inp.onchange=function(e){
          var file=e.target.files[0];
          if(!file)return;
          var reader=new FileReader();
          reader.onload=function(ev){
            comprimirImagem(ev.target.result, function(comprimida){
              aprFotos[i]=comprimida;
              if(img)img.src=comprimida;
              if(prev)prev.style.display='flex';
              if(btn){btn.textContent='📷 Trocar foto';btn.style.borderColor='#3B6D11';btn.style.color='#3B6D11';}
            });
          };
          reader.readAsDataURL(file);
        };
      }
    });
  }

  document.getElementById('apr-sel').onchange=loadAprItens;
  var btnCancelApr=document.getElementById('btn-cancelar-apr');
  if(btnCancelApr)btnCancelApr.onclick=function(){ma.innerHTML='';ma.style.pointerEvents='none';};
  loadAprItens();
  // Scroll para o modal no diário
  setTimeout(function(){
    var modalEl=ma.querySelector('.modal');
    if(modalEl) modalEl.scrollIntoView({behavior:'smooth',block:'start'});
  },100);

  document.getElementById('btn-salvar-apr').onclick=function(){
    var sel=document.getElementById('apr-sel');
    var tid=sel?sel.value:'';
    var t=checklists_templates.find(function(x){return x.id===tid;});
    if(!t)return;
    // Verificar respostas obrigatórias e fotos obrigatórias
    var erros=[];
    t.itens.forEach(function(it,i){
      if(it.obrigatorio){
        var resp=document.querySelector('input[name="apr-'+i+'"]:checked');
        if(!resp)erros.push('Item '+(i+1)+': resposta obrigatória');
      }
      if(it.foto_obrigatoria && !aprFotos[i]){
        erros.push('Item '+(i+1)+': foto obrigatória');
      }
    });
    if(erros.length){
      alert('Corrija os seguintes itens:\n\n• '+erros.join('\n• '));
      return;
    }

    var respostas=t.itens.map(function(it,i){
      var resp=document.querySelector('input[name="apr-'+i+'"]:checked');
      return {
        item_id:it.id,
        pergunta:it.pergunta,
        resposta:resp?resp.value:'',
        foto:aprFotos[i]||null
      };
    });
    var nok=respostas.some(function(r){return r.resposta==='N';});
    var resultado=nok?'NOK':'OK';
    var hoje=dataHoje();
    var nova={id:'apr'+Date.now(),
      equipe_id:_dbEquipe?_dbEquipe.id:'',
      data:hoje,
      ordem_id:_dbOrdemAtual?_dbOrdemAtual.numero_ordem:'',
      checklist_id:tid,
      respostas:respostas,
      resultado:resultado,
      foto:null};
    aprs_registradas.push(nova);

    // Salvar APR no banco
    if(!DEMO){
      var isUUIDfn=function(v){return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);};
      // Enviar sempre - colunas são TEXT após fix SQL
      var aprPayload={
        equipe_id:String(nova.equipe_id||''),
        data:nova.data,
        ordem_id:String(nova.ordem_id||''),
        checklist_id:String(nova.checklist_id||''),
        checklist_nome:(checklists_templates.find(function(c){return c.id===nova.checklist_id;})||{}).nome||nova.checklist_id||'',
        respostas:JSON.stringify(respostas),
        resultado:nova.resultado,
        foto:nova.foto||null
      };

      console.log('Salvando APR:', aprPayload);
      sbInsertAprsRegistradas(aprPayload).then(function(res){
        console.log('APR salva:', res);
        if(res&&res[0]&&res[0].id){
          var local=aprs_registradas.find(function(x){return x.id===nova.id;});
          if(local)local.id=res[0].id;
        }
      }).catch(function(e){console.error('Erro ao salvar APR:',e);});
    }

    _dbOrdemAtual.eventos.push({tipo:'APR preenchida',ts:Date.now(),obs:'Resultado: '+resultado,foto:null});
    if(!DEMO)sbUpdate('ordens_diario',{eventos:JSON.stringify(_dbOrdemAtual.eventos)},'id=eq.'+_dbOrdemAtual.id);
    ma.innerHTML='';
    ma.style.pointerEvents='none';
    if(nok){
      alert('⚠️ APR com itens NÃO CONFORMES. O serviço pode continuar, mas o supervisor foi notificado.');
    } else {
      alert('✓ APR aprovada! Pode iniciar as atividades.');
    }
    renderDbOrdemAtual();
  };
}



