function renderChecklistsCad(filtro){
  var lista=document.getElementById('lista-checklists-cad');if(!lista)return;
  var rows=filtro?checklists_templates.filter(function(c){return c.tipo===filtro;}):checklists_templates;
  lista.innerHTML=rows.map(function(t){
    var cor={EPI:'ok',Veicular:'info',APR:'warn'}[t.tipo]||'gray';
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.85rem;margin-bottom:.5rem;display:flex;justify-content:space-between;align-items:center">'
      +'<div><div style="font-weight:600;font-size:13px">'+t.nome+'</div>'
      +'<div style="display:flex;gap:6px;margin-top:3px"><span class="bdg '+cor+'">'+t.tipo+'</span><span style="font-size:11px;color:#888">'+t.itens.length+' itens</span></div></div>'
      +'<div style="display:flex;gap:6px">'
      +'<button class="btn btn-sm" id="cedit-cl-'+t.id+'">Editar</button>'
      +'<button class="btn btn-sm" style="color:#A32D2D;border-color:#A32D2D" id="cdel-cl-'+t.id+'">Excluir</button>'
      +'</div></div>';
  }).join('')||'<div style="color:#aaa;font-size:12px;padding:1rem;text-align:center">Nenhum checklist cadastrado</div>';
  rows.forEach(function(t){
    var be=document.getElementById('cedit-cl-'+t.id);if(be)be.onclick=function(){openEditarChecklist(t.id);};
    var bd=document.getElementById('cdel-cl-'+t.id);if(bd)bd.onclick=function(){
      if(!confirm('Excluir "'+t.nome+'"?'))return;
      checklists_templates=checklists_templates.filter(function(x){return x.id!==t.id;});
      renderChecklistsCad(filtro);renderCadastros();
    };
  });
}
function filtrarChecklistsCad(tipo){renderChecklistsCad(tipo);}


// ═══════════════════════════════════════════════════════
// MENU MOBILE — hambúrguer + painel lateral
// ═══════════════════════════════════════════════════════
var _mobileMenuOpen = false;

function toggleMobileMenu(){
  _mobileMenuOpen = !_mobileMenuOpen;
  renderMobileMenu();
  var panel = document.getElementById('mob-panel');
  var overlay = document.getElementById('mob-overlay');
  var btn = document.getElementById('btn-hamburger');
  if(panel) panel.classList.toggle('open', _mobileMenuOpen);
  if(overlay) overlay.classList.toggle('open', _mobileMenuOpen);
  if(btn) btn.classList.toggle('open', _mobileMenuOpen);
  document.body.style.overflow = _mobileMenuOpen ? 'hidden' : '';
}

function closeMobileMenu(){
  _mobileMenuOpen = false;
  var panel = document.getElementById('mob-panel');
  var overlay = document.getElementById('mob-overlay');
  var btn = document.getElementById('btn-hamburger');
  if(panel) panel.classList.remove('open');
  if(overlay) overlay.classList.remove('open');
  if(btn) btn.classList.remove('open');
  document.body.style.overflow = '';
}

function renderMobileMenu(){
  var wrap = document.getElementById('nav-mobile-items');
  if(!wrap) return;
  var modules = [
    {id:'dashboard',   label:'Dashboard',  icon:'📊', cls:'nc-dash'},
    {id:'contratos',   label:'Contratos',  icon:'📁', cls:'nc-cont'},
    {id:'movimentacao',label:'Financeiro', icon:'💰', cls:'nc-lanc'},
    {id:'operacional', label:'Operacional',icon:'🏗️', cls:'nc-oper'},
    {id:'campo',       label:'Em Campo',   icon:'📍', cls:''},
    {id:'obras',       label:'Obras',      icon:'🏚️', cls:'nc-obras'},
    {id:'relatorios',  label:'Relatórios', icon:'📈', cls:'nc-rel'},
    {id:'cadastros',   label:'Cadastros',  icon:'⚙️', cls:'nc-cad'},
  ];
  var currentMain = window._currentMain || 'dashboard';
  var html = '';
  modules.forEach(function(m){
    var isActive = currentMain === m.id;
    var subs = MAIN_CONFIG[m.id] ? MAIN_CONFIG[m.id].subs : [];
    var btnClass = 'nav-main-btn ' + m.cls + (isActive ? ' on' : '');
    html += '<div data-mod="'+m.id+'">';
    html += '<button class="'+btnClass+'" style="width:100%;border-radius:8px;border:.5px solid #e0dfd8;border-bottom:.5px solid #e0dfd8;margin-bottom:2px;flex-direction:row;justify-content:flex-start;gap:10px;padding:10px 12px;font-size:13px" data-main="'+m.id+'" data-action="main">';
    html += '<span style="font-size:16px">'+m.icon+'</span><span>'+m.label+'</span></button>';
    if(isActive && subs.length){
      html += '<div class="nav-mobile-subs">';
      subs.forEach(function(s){
        var subOn = window._currentTab === s.id ? ' on' : '';
        html += '<button class="nav-mobile-sub-btn'+subOn+'" data-main="'+m.id+'" data-sub="'+s.id+'" data-action="sub">'+s.label+'</button>';
      });
      html += '</div>';
    }
    html += '</div>';
  });
  wrap.innerHTML = html;
  // Event delegation
  wrap.onclick = function(e){
    var btn = e.target.closest('[data-action]');
    if(!btn) return;
    var action = btn.getAttribute('data-action');
    if(action === 'main') mobileNavMain(btn.getAttribute('data-main'));
    if(action === 'sub') mobileNavSub(btn);
  };
}

function mobileNavMain(id){
  window._currentMain = id;
  renderMobileMenu(); // re-render para mostrar sub-abas
  // Se não tem sub-abas, já navega e fecha
  var subs = MAIN_CONFIG[id] ? MAIN_CONFIG[id].subs : [];
  if(!subs.length){
    showMain(id);
    closeMobileMenu();
  }
}

function mobileNavSub(btn){
  var mainId = btn.getAttribute('data-main');
  var subId = btn.getAttribute('data-sub');
  showMain(mainId);
  setTimeout(function(){ showTab(subId); }, 50);
  closeMobileMenu();
}

// ── Sub-abas mobile (scroll horizontal abaixo do header) ──
function renderSubAbasMobile(mainId){
  var wrap = document.getElementById('nav-sub-mobile');
  if(!wrap) return;
  var isMobile = window.innerWidth < 768;
  if(!isMobile){ wrap.style.display='none'; return; }
  var subs = MAIN_CONFIG[mainId] ? MAIN_CONFIG[mainId].subs : [];
  if(!subs.length){ wrap.style.display='none'; return; }
  wrap.style.display = 'flex';
    var subHtml = '';
  subs.forEach(function(s){
    var on = window._currentTab === s.id ? ' on' : '';
    subHtml += '<button class="nav-sub-mobile-btn'+on+'" data-tab="'+s.id+'" id="msub-'+s.id+'">'+s.label+'</button>';
  });
  wrap.innerHTML = subHtml;
  wrap.onclick = function(e){
    var btn = e.target.closest('[data-tab]');
    if(btn) showTab(btn.getAttribute('data-tab'));
  };
}

// ── Data-labels automáticos para tabelas responsivas ──
function aplicarDataLabels(){
  document.querySelectorAll('table.tbl-responsive').forEach(function(tbl){
    var headers = Array.from(tbl.querySelectorAll('thead th')).map(function(th){ return th.textContent.trim(); });
    tbl.querySelectorAll('tbody tr').forEach(function(tr){
      Array.from(tr.querySelectorAll('td')).forEach(function(td, i){
        if(headers[i]) td.setAttribute('data-label', headers[i]);
      });
    });
  });
}

// ── Detectar resize para ajustar layout ──
window.addEventListener('resize', function(){
  // Reaplica display do nav-main conforme largura
  var nm=document.getElementById('nav-main');
  if(nm){
    if(window.innerWidth>=768){
      if(nm.style.display==='none'||!nm.style.display) nm.style.display='flex';
    }
  }
  var isMobile = window.innerWidth < 768;
  var navMain = document.getElementById('nav-main');
  var navSub = document.getElementById('nav-sub');
  if(navMain) navMain.style.display = isMobile ? 'none' : '';
  if(navSub) navSub.style.display = isMobile ? 'none' : '';
  if(!isMobile) closeMobileMenu();
  renderSubAbasMobile(window._currentMain || 'dashboard');
});

// ── Ajustes mobile no header (esconder botões verbosos) ──
function ajustarHeaderMobile(){
  var isMobile = window.innerWidth < 768;
  var btnNovoLanc = document.querySelector('[onclick*="openNovoLancamento"]');
  var btnAlmox = document.querySelector('a[href*="netlify"]');
  if(isMobile){
    if(btnNovoLanc) btnNovoLanc.style.display = 'none';
    if(btnAlmox) btnAlmox.style.display = 'none';
  } else {
    if(btnNovoLanc) btnNovoLanc.style.display = '';
    if(btnAlmox) btnAlmox.style.display = '';
  }
}


