async function garantirColaboradoresCarregados(contrato_id){
  // Se não há colaboradores do contrato no array local, busca do banco
  var temLocal = colaboradores.some(function(c){ return c.contrato_id === contrato_id; });
  if(!temLocal && !DEMO){
    try{
      var res = await sbFetch('colaboradores', {
        filters:['contrato_id=eq.'+contrato_id, 'ativo=eq.true'],
        order:'nome'
      });
      if(res && res.length){
        // Adicionar ao array sem duplicar
        res.forEach(function(c){
          if(!colaboradores.find(function(x){return x.id===c.id;})){
            colaboradores.push(c);
          }
        });
      }
    } catch(e){ console.error('Erro ao carregar colaboradores:',e); }
  }
}


async function _recarregarDiarioAdmin(){
  var hoje = dataHoje();
  if(!DEMO){
    try{
      var res = await Promise.all([
        sbFetch('sessoes_disponibilidade',{filters:['data=eq.'+hoje],order:'login_ts.desc'}),
        sbFetch('turnos_abertos',{filters:['data=eq.'+hoje]}),
        sbFetch('ordens_diario',{filters:['data=eq.'+hoje]}),
      ]);
      if(res[0]&&res[0].length) sessoes_disp = res[0].map(function(s){
        s.eventos=parseJsonField(s.eventos,[]);
        s.placa=s.placa||''; s.km_inicial=s.km_inicial||0; s.km_final=s.km_final||0;
        return s;
      });
      if(res[1]&&res[1].length) turnos_abertos = res[1].map(function(t){
        t.respostas_epi=parseJsonField(t.respostas_epi,[]);
        t.respostas_vei=parseJsonField(t.respostas_vei,[]);
        t.placa=t.placa||''; t.km_inicial=t.km_inicial||0; t.km_final=t.km_final||0;
        return t;
      });
      if(res[2]&&res[2].length) ordens_db = res[2].map(function(o){
        o.eventos=parseJsonField(o.eventos,[]); return o;
      });
    } catch(e){ console.error('Erro ao recarregar diário:',e); }
  }
  _renderDiarioAdmin();
}


// ═══════════════════════════════════════════════════════
// PRODUÇÃO AUTOMÁTICA — gera prod_diaria das equipes TMA
// ═══════════════════════════════════════════════════════
function gerarProducaoAutomatica(cid, ini, fim){
  // Para cada dia no período, para cada equipe TMA do contrato,
  // calcula horas faturáveis da sessão e ordens encerradas
  var eqsTMA = equipes_disp.filter(function(e){
    return (!cid||e.contrato_id===cid) && e.status==='Ativo';
  });
  var datas = [];
  var cur = new Date(ini+'T00:00:00');
  var end = new Date(fim+'T00:00:00');
  while(cur<=end){datas.push((function(){var _d=cur;return _d.getFullYear()+'-'+String(_d.getMonth()+1).padStart(2,'0')+'-'+String(_d.getDate()).padStart(2,'0');})());cur.setDate(cur.getDate()+1);}

  var novos = [];
  eqsTMA.forEach(function(eq){
    datas.forEach(function(data){
      // Verificar se já existe lançamento
      var existe = prod_diaria.find(function(p){
        return p.equipe_id===eq.id && p.data===data;
      });
      if(existe) return; // não sobrescrever manual

      var sessao = sessoes_disp.find(function(s){
        return s.equipe_id===eq.id && s.data===data;
      });
      if(!sessao) return; // sem sessão neste dia

      var ordens = ordens_db.filter(function(o){
        return o.equipe_id===eq.id && o.data===data;
      });
      var ordensEnc = ordens.filter(function(o){return o.status==='encerrada';}).length;

      // Meta diária fixa = 8h faturáveis
      // Se a equipe não registrou almoço, pode faturar mais que 8h (até 9h)
      var META_DIARIA = 8;

      // Produção = horas faturáveis da sessão (já descontou almoço se houve)
      var minFat = sessao.minutos_faturados || 0;
      var horasFat = Math.round(minFat/60*100)/100;

      // ORÇ = meta diária do tipo de equipe (configurável)
      var tipo = tipos_equipe.find(function(t){return t.id===eq.tipo_id;});
      var metaMes = tipo ? tipo.meta_horas_mes : 176;
      var metaDia = Math.round(metaMes/22*100)/100; // para ORÇ
      // META do dia = 8h fixas (independente do mês)
      var metaDiaFixa = META_DIARIA;

      var novo = {
        id: 'pd_auto_'+eq.id+'_'+data,
        contrato_id: eq.contrato_id,
        equipe_id: eq.id,
        data: data,
        orc: metaDia,         // ORÇ = meta configurada no tipo
        meta: metaDiaFixa,    // META = 8h fixas por dia
        prog: horasFat,       // PROG = horas realizadas
        prod: horasFat,       // PROD = horas realizadas
        observacao: 'Auto: '+ordensEnc+' ordens | '+(sessao.almoco_ts?'c/ almoço':'s/ almoço'),
        _auto: true
      };
      prod_diaria.push(novo);
      novos.push(novo);
    });
  });
  return novos;
}

function sincronizarProducaoAuto(){
  var cid = (document.getElementById('fil-oper-cont')||{}).value||'';
  var ini = (document.getElementById('fil-oper-ini')||{}).value||'';
  var fim = (document.getElementById('fil-oper-fim')||{}).value||'';
  if(!ini||!fim) return;
  var novos = gerarProducaoAutomatica(cid, ini, fim);
  // Salvar no banco
  if(!DEMO && novos.length){
    novos.forEach(function(n){
      sbInsert('prod_diaria',{
        contrato_id:n.contrato_id, equipe_id:n.equipe_id, data:n.data,
        orc:n.orc, meta:n.meta, prog:n.prog, prod:n.prod, observacao:n.obs
      }).then(function(res){
        if(res&&res[0]&&res[0].id){
          var local=prod_diaria.find(function(x){return x.id===n.id;});
          if(local)local.id=res[0].id;
        }
      });
    });
  }
  renderOperacional();
  if(novos.length){
    var d=document.createElement('div');
    d.style.cssText='position:fixed;bottom:16px;right:16px;background:#3B6D11;color:#fff;padding:10px 16px;border-radius:10px;font-size:13px;z-index:9999;box-shadow:0 4px 12px rgba(0,0,0,.15)';
    d.textContent='✓ '+novos.length+' registros de produção gerados automaticamente';
    document.body.appendChild(d);
    setTimeout(function(){if(d.parentNode)d.remove();},4000);
  } else {
    alert('Nenhum registro novo — todas as equipes já têm produção lançada no período.');
  }
}


