// Compressar imagem antes de salvar (reduz para max 400x400, qualidade 0.7)
function comprimirImagem(base64, callback){
  var img=new Image();
  img.onload=function(){
    var canvas=document.createElement('canvas');
    var max=400;
    var w=img.width; var h=img.height;
    if(w>max||h>max){
      if(w>h){h=Math.round(h*max/w);w=max;}
      else{w=Math.round(w*max/h);h=max;}
    }
    canvas.width=w; canvas.height=h;
    var ctx=canvas.getContext('2d');
    ctx.drawImage(img,0,0,w,h);
    callback(canvas.toDataURL('image/jpeg',0.7));
  };
  img.src=base64;
}


function abrirFotoFullscreen(src){
  if(!src) return;
  // Overlay no próprio app — window.open(data:) / URLs longas abre aba branca
  var overlay=document.createElement('div');
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.92);z-index:10050;display:flex;align-items:center;justify-content:center;cursor:zoom-out;padding:1rem';
  overlay.setAttribute('data-overlay','1');
  var wrap=document.createElement('div');
  wrap.style.cssText='position:relative;max-width:100%;max-height:100%';
  var img=document.createElement('img');
  img.alt='Foto';
  img.style.cssText='max-width:100%;max-height:90vh;border-radius:8px;display:block;margin:auto;background:#111';
  img.src=src;
  img.onerror=function(){
    wrap.innerHTML='<div style="color:#fff;font-size:14px;text-align:center;padding:2rem">Não foi possível carregar a foto.</div>';
  };
  var btn=document.createElement('button');
  btn.type='button';
  btn.textContent='✕';
  btn.setAttribute('aria-label','Fechar');
  btn.style.cssText='position:absolute;top:-12px;right:-12px;background:#fff;border:none;border-radius:50%;width:28px;height:28px;font-size:16px;cursor:pointer;line-height:28px;text-align:center;z-index:1';
  btn.onclick=function(ev){ ev.stopPropagation(); overlay.remove(); };
  wrap.appendChild(img);
  wrap.appendChild(btn);
  overlay.appendChild(wrap);
  overlay.onclick=function(e){ if(e.target===overlay) overlay.remove(); };
  document.body.appendChild(overlay);
}


