// ─── CALC ─────────────────────────────────────────────────────
function plrCalcCrit(c,val){
  var m=c.maxMes;
  if(c.tipo==='faltas'){if(val<=1)return m;if(val<=3)return m*.5;if(val<=5)return 0;return -1;}
  if(c.tipo==='oc')return Math.max(0,m*(1-val*.3));
  if(c.tipo==='sel')return m*(c.fatores[Math.min(val,c.fatores.length-1)]||0);
  if(c.tipo==='meta')return c.vals[Math.min(val,c.vals.length-1)]||0;
  return 0;
}
function plrCalcTotal(scores){
  var tot=0;var parts={};
  for(var c of PLR_CRITERIOS){
    var v=plrCalcCrit(c,scores[c.id]||0);
    if(v===-1)return{total:0,perdido:true,parts:{}};
    parts[c.id]=Math.round(v*100)/100;tot+=v;
  }
  return{total:Math.round(tot*100)/100,perdido:false,parts};
}
function plrFmtR(v){return 'R$'+(Math.round(v)).toLocaleString('pt-BR');}
function plrPctColor(p){return p>=80?'#b5c98a':p>=50?'#e8a030':'#e05050';}
function plrInitials(n){return n.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function plrTodayISO(){return dataHojeLocal();}

