// Retorna true se o contrato (uuid ou codigo) tem fluxo Projeto+Diário
function contratoTemFluxoProjeto(contratoIdOuCodigo){
  if(!contratoIdOuCodigo) return false;
  // Verificar por código direto na lista de contratos com fluxo de projeto
  var upper = contratoIdOuCodigo.toUpperCase();
  for(var i=0; i<CONTRATOS_FLUXO_CODIGOS.length; i++){
    var c = CONTRATOS_FLUXO_CODIGOS[i].toUpperCase();
    if(upper === c || upper.indexOf(c) >= 0) return true;
  }
  // Verificar nos contratos carregados do banco pelo código
  var contrato = contratos.find(function(c){ return c.id===contratoIdOuCodigo||c.codigo===contratoIdOuCodigo; });
  if(contrato){
    var cod = (contrato.codigo||'').toUpperCase();
    for(var j=0; j<CONTRATOS_FLUXO_CODIGOS.length; j++){
      if(cod === CONTRATOS_FLUXO_CODIGOS[j].toUpperCase() || cod.indexOf(CONTRATOS_FLUXO_CODIGOS[j].toUpperCase()) >= 0) return true;
    }
    // Se o contrato tem modalidade_trabalho diferente de Disponibilidade, usa fluxo projeto
    var mod = (contrato.modalidade_trabalho||'').toLowerCase();
    if(mod && mod !== 'disponibilidade') return true;
  }
  return false; // padrão: fluxo de OS (Disponibilidade) — TMA e similares
}

// Retorna o UUID do contrato pelo codigo ou pelo próprio uuid
function contratoUUID(idOuCodigo){
  if(!idOuCodigo) return null;
  // já é UUID?
  if(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(idOuCodigo)) return idOuCodigo;
  // Verificar no mapa estático
  var upper = idOuCodigo.toUpperCase();
  for(var key in CONTRATOS_UUID_MAP){
    if(upper === key || upper.indexOf(key) >= 0) return CONTRATOS_UUID_MAP[key];
  }
  // Verificar nos contratos carregados
  var c = contratos.find(function(x){ return x.codigo===idOuCodigo||x.nome===idOuCodigo; });
  return c ? c.id : null;
}

