    +'<div style="padding:1rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px">'
    +vbeFieldContratoRef('Data de assinatura',fin.data_assinatura,'contratos.data_inicio')
