    +vbeFieldMoeda('vbe-pr-saldo','Saldo contratual',fin.saldo_contratual,ro,'',true)
    +vbeFieldMoeda('vbe-pr-verba','Verba mensal disponível',fin.verba_mensal_disponivel,ro,'',true)
