    +vbeFieldMoeda('vbe-pr-fat-esp','Valor previsto de faturamento',pe.faturamento_mensal_esperado,ro,vbeBadgeOrigem('faturamento_mensal_esperado',orig)||' <span class="bdg info" style="font-size:9px">Valores previstos · DRE da Viabilidade</span>')
