function vbeFieldMoeda(id,label,val,ro,badge,auto){
  var disp=vbePodeVerFinanceiro()?vbeFmtMoedaInput(val):'***';
  var roAttr=(ro||auto)?' readonly style="background:#f5f5f2;color:#333"':'';
  var badgeAuto=auto?' <span class="bdg info" style="font-size:9px">Auto</span>':'';
  return '<div class="fg"><label style="font-size:11px;font-weight:600">'+label+(badge||'')+badgeAuto+'</label>'
    +'<div style="display:flex;align-items:center;gap:6px">'
    +'<span style="font-size:13px;color:#666;font-weight:600;flex-shrink:0">R$</span>'
    +'<input class="inp vbe-inp-moeda" id="'+id+'" type="text" inputmode="decimal" autocomplete="off" style="width:100%" value="'+disp+'"'+roAttr+'/></div></div>';
}

function vbeBindMoedaInputs(){
  document.querySelectorAll('.vbe-inp-moeda:not([readonly])').forEach(function(el){
    el.onblur=function(){
      if(!vbePodeVerFinanceiro()) return;
      var v=vbeParseMoeda(el.value);
      el.value=v!=null?vbeFmtMoedaInput(v):'';
    };
  });
}

function vbePremissasRecalcFinanceiro(){
  if(!vbePodeVerFinanceiro()) return;
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid) return;
  var fin=vbePremissasFinanceiroCalc(cid,null,null,{
    valor_total:vbeParseMoeda((document.getElementById('vbe-pr-valor-total')||{}).value),
    valor_faturado_acumulado:vbeParseMoeda((document.getElementById('vbe-pr-fat-acum')||{}).value)
  });
  var sel=document.getElementById('vbe-pr-saldo'); if(sel) sel.value=vbeFmtMoedaInput(fin.saldo_contratual);
  var vel=document.getElementById('vbe-pr-verba'); if(vel) vel.value=vbeFmtMoedaInput(fin.verba_mensal_disponivel);
  var hint=document.getElementById('vbe-pr-meses-hint');
  if(hint) hint.textContent=(fin.meses_restantes>0
    ?fin.meses_restantes+' meses restantes (término '+fmtD(fin.data_validade)+')'
    :(fin.data_validade?'Prazo encerrado em '+fmtD(fin.data_validade):'Informe data término em Contratos'))
    +' · Verba = saldo ÷ meses restantes';
}

function vbeBindPremissasCalculos(){
  var recalc=vbePremissasRecalcFinanceiro;
  ['vbe-pr-valor-total','vbe-pr-fat-acum'].forEach(function(id){
    var el=document.getElementById(id);
    if(!el) return;
    el.addEventListener('input',recalc);
    el.addEventListener('change',recalc);
    if(el.classList.contains('vbe-inp-moeda')) el.addEventListener('blur',recalc);
  });
}

function vbeFieldNum(id,label,val,ro,badge){
  return '<div class="fg"><label style="font-size:11px;font-weight:600">'+label+(badge||'')+'</label>'
    +'<input class="inp" id="'+id+'" type="number" step="any" style="width:100%" value="'+(val!=null&&val!==''?val:'')+'"'+(ro||'')+'/></div>';
}
function vbeFieldSel(id,label,val,opts){
  return '<div class="fg"><label style="font-size:11px;font-weight:600">'+label+'</label><select class="inp" id="'+id+'" style="width:100%">'
    +opts.map(function(o){return '<option value="'+escHtml(o.v)+'"'+(String(val)===String(o.v)?' selected':'')+'>'+escHtml(o.l)+'</option>';}).join('')
    +'</select></div>';
}

async function vbePremissasAutoFill(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid) return;
  var c=(contratos||[]).find(function(x){return x.id===cid;});
  if(!c) return;
  await vbeEnsureDadosProdutividade();
  var set=function(id,v){var el=document.getElementById(id);if(el&&v!=null&&v!=='') el.value=v;};
  var setMoeda=function(id,v){var el=document.getElementById(id);if(el&&v!=null) el.value=vbeFmtMoedaInput(v);};
  var orig=vbeParseOrigemCampos(vbePremissaDoContrato(cid));
  if(vbePodeVerFinanceiro()){
    setMoeda('vbe-pr-valor-total',c.valor_total);
    set('vbe-pr-modelo',c.modalidade_trabalho||'');
    var fatErp=vbeCalcFaturadoAcumulado(cid);
    if(fatErp!=null){
      setMoeda('vbe-pr-fat-acum',fatErp);
      orig.valor_faturado_acumulado='erp';
    } else if(c.valor_total&&c.valor_faturado!=null){
      setMoeda('vbe-pr-fat-acum',Number(c.valor_faturado||0));
      orig.valor_faturado_acumulado='erp';
    }
    var oel=document.getElementById('vbe-pr-origem-json');
    if(oel) oel.value=JSON.stringify(orig);
    vbePremissasRecalcFinanceiro();
  }
  if(typeof progShowToast==='function') progShowToast('Dados comerciais do contrato preenchidos.');
}

async function vbeSincronizarOperacionalERP(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid){ progShowToast('Selecione um contrato.','erro'); return; }
  var comp=_vbeCompetencia||vbeGetCompSel();
  await vbeEnsureColaboradoresContrato(cid);
  await vbeEnsureDadosOperacionais(comp);
  // Recarrega frota fresca (tipo/modelo) antes de contar veículos por tipo
  if(!DEMO){
    try{
      var fv=await sbFetch('frotas_veiculos',{filters:['status=neq.Inativo'],order:'placa',limit:3000}).catch(function(){return[];});
      if(fv&&fv.length) frt_veiculos=fv;
    }catch(eFv){}
  }
  var ops=vbeColetarDadosOperacionais(cid,comp);
  var orig=vbeParseOrigemCampos(vbePremissaDoContrato(cid));
  var vinc=vbeColaboradoresPorVinculo(cid);
  var set=function(id,v){var el=document.getElementById(id);if(el&&v!=null&&v!=='') el.value=v;};
  if(ops.equipes_cadastradas){ set('vbe-pr-eq-alvo',ops.equipes_cadastradas); orig.equipes_alvo='erp'; }
  set('vbe-pr-col-campo',vinc.campo);
  set('vbe-pr-col-interno',vinc.interno);
  set('vbe-pr-col-disp',vinc.campo+vinc.interno);
  orig.colaboradores_campo_disponiveis='cadastro';
  orig.colaboradores_internos_disponiveis='cadastro';
  orig.colaboradores_disponiveis='cadastro';
  var veiInfo=ops.veiculos_por_tipo||vbeContarVeiculosPorTipoOperacional(cid);
  set('vbe-pr-vei-disp', veiInfo.total);
  var vej=document.getElementById('vbe-pr-vei-json'); if(vej) vej.value=JSON.stringify(veiInfo);
  var wrapV=document.getElementById('vbe-pr-vei-tipos-wrap'); if(wrapV) wrapV.innerHTML=vbeHtmlVeiculosPorTipo(cid,{hint:false});
  orig.veiculos_disponiveis='erp';
  if(ops.equipes_entregues_media!=null){ set('vbe-pr-eq-ent',ops.equipes_entregues_media); orig.equipes_entregues_media='erp'; }
  if(ops.equipes_cadastradas&&ops.colaboradores_disponiveis){
    set('vbe-pr-col-eq',Math.round((ops.colaboradores_disponiveis/ops.equipes_cadastradas)*100)/100);
  }
  var folhaOp=vbeCalcFolhaOperacionalGrade(cid);
  if(folhaOp>0){
    var elFo=document.getElementById('vbe-pr-folha-op');
    if(elFo && (!elFo.value||vbeParseMoeda(elFo.value)===0)){
      if(typeof vbeFmtMoedaInput==='function') elFo.value=vbeFmtMoedaInput(folhaOp);
      else elFo.value=String(folhaOp);
    }
  }
  var oel=document.getElementById('vbe-pr-origem-json');
  if(oel) oel.value=JSON.stringify(orig);
  var msg='Operação ERP: '+ops.equipes_cadastradas+' equipes · '+vinc.campo+' campo · '+vinc.interno+' interno · '+veiInfo.total+' veíc.';
  if(veiInfo.itens&&veiInfo.itens.length) msg+=' ('+veiInfo.itens.map(function(it){return it.tipo+': '+it.qtd;}).join(', ')+')';
  if(ops.equipes_entregues_media!=null) msg+=' · média '+ops.equipes_entregues_media+' eq/dia ('+ops.dias_composicao+' dias c/ formação)';
  if(typeof progShowToast==='function') progShowToast(msg);
}

async function vbeSincronizarFaturamentoERP(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid){ progShowToast('Selecione um contrato.','erro'); return; }
  await vbeEnsureDadosProdutividade();
  var comp=_vbeCompetencia||vbeGetCompSel();
  var prod=vbeColetarDadosProdutividade(cid,comp);
  if(!prod.tem_dados){
    progShowToast('Sem dados de produtividade/faturamento no ERP para '+comp.slice(0,7)+'.','erro');
    return;
  }
  var orig=vbeParseOrigemCampos(vbePremissaDoContrato(cid));
  var set=function(id,v){var el=document.getElementById(id);if(el&&v!=null&&v!=='') el.value=v;};
  if(prod.meta_prod>0){ set('vbe-pr-meta',prod.meta_prod); orig.meta_faturamento_mensal='erp'; }
  if(prod.faturamento_efetivo>0){ set('vbe-pr-fat-esp',prod.faturamento_efetivo); orig.faturamento_mensal_esperado='erp'; }
  else if(prod.prod_prevista>0){ set('vbe-pr-fat-esp',prod.prod_prevista); orig.faturamento_mensal_esperado='erp'; }
  var oel=document.getElementById('vbe-pr-origem-json');
  if(oel) oel.value=JSON.stringify(orig);
  var msg='Faturamento ERP: '+vbeLabelFonteFat(prod.fonte_faturamento);
  if(prod.faturamento_efetivo>0) msg+=' · '+vbeFmtValor(prod.faturamento_efetivo);
  if(prod.meta_prod>0) msg+=' · meta '+vbeFmtValor(prod.meta_prod);
  if(typeof progShowToast==='function') progShowToast(msg);
}

async function vbeSalvarPremissas(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid){ progShowToast('Selecione um contrato.','erro'); return; }
  var g=function(id){return (document.getElementById(id)||{}).value;};
  var gm=function(id){return vbeParseMoeda(g(id));};
  var gn=function(id){var v=parseFloat(g(id)); return isNaN(v)?null:v;};
  var valTotal=gm('vbe-pr-valor-total');
  var fatAcum=gm('vbe-pr-fat-acum');
  var fin=vbePremissasFinanceiroCalc(cid,null,null,{
    valor_total:valTotal, valor_faturado_acumulado:fatAcum
  });
  var antes=vbePremissaDoContrato(cid);
  var orig=(function(){try{return JSON.parse(g('vbe-pr-origem-json')||'{}');}catch(e){return{};}})();
  var row={
    contrato_id:cid,
    valor_total_contrato:valTotal,
    valor_faturado_acumulado:fatAcum,
    saldo_contratual:fin.saldo_contratual,
    verba_mensal_disponivel:fin.verba_mensal_disponivel,
    meta_faturamento_mensal:gm('vbe-pr-meta'),
    faturamento_mensal_esperado:gm('vbe-pr-fat-esp'),
    prazo_medio_pagamento_dias:parseInt(g('vbe-pr-prazo-pg'),10)||30,
    retencao_percentual:gn('vbe-pr-retencao'),
    glosa_media_percentual:gn('vbe-pr-glosa'),
    regime_tributario:g('vbe-pr-regime')||'presumido',
    iss_percentual:gn('vbe-pr-iss')!=null?gn('vbe-pr-iss'):5,
    modelo_medicao:g('vbe-pr-modelo')||null,
    equipes_minimas_exigidas:gn('vbe-pr-eq-min'),
    equipes_alvo:gn('vbe-pr-eq-alvo'),
    equipes_limite:gn('vbe-pr-eq-lim'),
    equipes_entregues_media:gn('vbe-pr-eq-ent'),
    colaboradores_por_equipe:gn('vbe-pr-col-eq')||2,
    veiculos_por_equipe:gn('vbe-pr-vei-eq')||1,
    colaboradores_disponiveis:gn('vbe-pr-col-disp'),
    veiculos_disponiveis:gn('vbe-pr-vei-disp'),
    percentual_reserva_folguista:(gn('vbe-pr-reserva')||15)/100,
    percentual_absenteismo:(gn('vbe-pr-abs')||5)/100,
    faturamento_esperado_por_equipe:gm('vbe-pr-fat-eq'),
    folha_operacional_total:gm('vbe-pr-folha-op'),
    folha_backoffice_total:gm('vbe-pr-folha-bo'),
    status_analise:g('vbe-pr-status'),
    observacoes_comerciais:g('vbe-pr-obs')||'',
    responsavel_id:(usuarioLogado||{}).id||null,
    origem_campos_json:orig
  };
  try{
    var veiJsonRaw=g('vbe-pr-vei-json');
    if(veiJsonRaw) row.veiculos_por_tipo_json=typeof veiJsonRaw==='string'?JSON.parse(veiJsonRaw):veiJsonRaw;
  }catch(eJ){ row.veiculos_por_tipo_json=vbeContarVeiculosPorTipoOperacional(cid); }
  // refresca contagem ERP no momento do save
  try{
    var veiNow=vbeContarVeiculosPorTipoOperacional(cid);
    row.veiculos_disponiveis=veiNow.total;
    row.veiculos_por_tipo_json=veiNow;
  }catch(eV){}
  row.nivel_confianca=vbeCalcConfianca(row,vbeCustosComp(cid,_vbeCompetencia||vbeGetCompSel()));
  try{
    var salvarRow=async function(payload){
      if(antes&&antes.id){
        if(!DEMO) await sbUpdate('contrato_viabilidade_premissas',payload,'id=eq.'+antes.id);
        Object.assign(antes,payload);
      } else {
        if(!DEMO){ var ins=await sbInsert('contrato_viabilidade_premissas',payload); if(ins&&ins[0]) payload=Object.assign(payload,ins[0]); }
        else { payload.id='vbep'+Date.now(); vbePremissas.push(payload); }
        row=payload;
        if(row.id&&!vbePremissas.find(function(p){return p.id===row.id;})) vbePremissas.push(row);
      }
    };
    try{
      await salvarRow(row);
    }catch(eCol){
      var msgCol=String((eCol&&(eCol.message||eCol.msg))||eCol||'');
      if(/regime_tributario|iss_percentual|PGRST204|column/i.test(msgCol)){
        var rowSemTrib=Object.assign({},row);
        delete rowSemTrib.regime_tributario; delete rowSemTrib.iss_percentual;
        await salvarRow(rowSemTrib);
        if(antes){ antes.regime_tributario=row.regime_tributario; antes.iss_percentual=row.iss_percentual; }
        console.warn('[VBE] regime/ISS não persistidos — rode sql_viabilidade_regime_tributario.sql');
        if(typeof progShowToast==='function') progShowToast('Premissas salvas (regime/ISS só local — rode sql_viabilidade_regime_tributario.sql).','aviso');
      } else throw eCol;
    }
    if(!DEMO) vbePremissas=await sbFetch('contrato_viabilidade_premissas',{order:'contrato_id'})||vbePremissas;
    // Após fetch, restaura regime/ISS em memória se colunas ainda não existem no banco
    try{
      var _prTrib=vbePremissaDoContrato(cid);
      if(_prTrib){
        if(row.regime_tributario) _prTrib.regime_tributario=row.regime_tributario;
        if(row.iss_percentual!=null) _prTrib.iss_percentual=row.iss_percentual;
      }
    }catch(_t){}
    // Fase 1 — colaboradores por vínculo (não-fatal: requer colunas do SQL Fase 1)
    try{
      var _pid=(antes&&antes.id)||row.id;
      var _campo=parseInt(g('vbe-pr-col-campo'),10)||0, _int=parseInt(g('vbe-pr-col-interno'),10)||0;
      if(_pid&&!DEMO) await sbUpdate('contrato_viabilidade_premissas',{colaboradores_campo_disponiveis:_campo,colaboradores_internos_disponiveis:_int},'id=eq.'+_pid);
      var _pr=vbePremissaDoContrato(cid);
      if(_pr){ _pr.colaboradores_campo_disponiveis=_campo; _pr.colaboradores_internos_disponiveis=_int; }
    }catch(_e){ console.warn('colaboradores vínculo (aplicar SQL Fase 1):',_e); }
    await vbeHistoricoRegistrar(cid,antes?'premissas_alterar':'premissas_criar','Premissas salvas',antes,row);
    var analise=vbeAnalisarContrato(cid,_vbeCompetencia||vbeGetCompSel());
    if(analise) await vbeSalvarSnapshot(cid,_vbeCompetencia||vbeGetCompSel(),analise);
    progShowToast('Premissas salvas.');
    vbeRenderPremissas();
  }catch(e){
    console.error(e);
    var msg=String((e&&(e.message||e.msg))||e||'');
    if(/folha_|veiculos_por_tipo|regime_tributario|iss_percentual/i.test(msg)||/column|schema|PGRST204/i.test(msg))
      progShowToast('Erro ao salvar: rode sql_viabilidade_regime_tributario.sql (ou sql_viabilidade_folha_veiculos_tipos.sql) no Supabase.','erro');
    else progShowToast('Erro ao salvar premissas.','erro');
  }
}

function vbeRenderCapacidade(){
  var cid=vbeContratoFiltroAtual();
  var wrap=document.getElementById('vbe-capacidade-wrap'); if(!wrap) return;
  if(!cid){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">'
      +'<div style="font-size:14px;margin-bottom:6px">Selecione um contrato no filtro acima.</div>'
      +'<div style="font-size:12px">A opção <b>Todos os contratos</b> não exibe Capacidade — escolha um contrato específico.</div></div>';
    return;
  }
  wrap.innerHTML='<div style="padding:1.5rem;text-align:center;color:#888">Carregando capacidade e realizado por tipo…</div>';
  var comp=_vbeCompetencia||vbeGetCompSel();
  Promise.resolve(vbeEnsureSessoesCompetencia(comp)).then(function(){
    vbeRenderCapacidadeCore(cid,comp);
  }).catch(function(e){
    console.warn('[VBE] capacidade',e);
    vbeRenderCapacidadeCore(cid,comp);
  });
}
function vbeRenderCapacidadeCore(cid,comp){
  var wrap=document.getElementById('vbe-capacidade-wrap'); if(!wrap) return;
  var p;
  try{p=vbeObterPremissasEfetivas(cid,comp);}catch(eP){console.warn('[VBE] premissas efetivas',eP);p=null;}
  if(!p){ wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">Sem dados operacionais para <b>'+escHtml(vbeNomeContrato(cid))+'</b>. Vincule equipes ao contrato ou cadastre premissas.</div>'; return; }
  var cap;
  try{
    cap=vbeCalcCapacidade(p);
    cap=vbeAplicarIcoComposicao(cid,p,cap,comp);
  }catch(eC){console.warn('[VBE] calc capacidade',eC);wrap.innerHTML='<div style="padding:2rem;color:#A32D2D">Erro ao calcular capacidade. Veja o console (F12).</div>';return;}
  var icoCor=vbeClassCorIco(cap.ico_score);
  var ops=p._ops;
  var simHtml='';
  try{simHtml=vbeSimulacaoIcoHtml(cid,comp)||'';}catch(eSim){console.warn('[VBE] simulação ICO',eSim);simHtml='<div class="card" style="padding:1rem;color:#A32D2D;font-size:12px;margin-bottom:1rem">Simulação ICO indisponível neste momento.</div>';}
  var compHtml='';
  try{compHtml=vbeCapacidadeComposicaoHtml(cid,p,comp)||'';}catch(eComp){console.warn('[VBE] composição html',eComp);}
  var modoComp=cap._ico_modo==='composicao';
  wrap.innerHTML='<div class="card" style="margin-bottom:1rem;border-left:4px solid '+icoCor+'">'
    +'<div style="padding:1rem;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">'
    +'<div><div style="font-size:12px;color:#888">ICO — Índice de Capacidade Operacional — '+escHtml(vbeNomeContrato(cid))+'</div>'
    +'<div style="font-size:36px;font-weight:700;color:'+icoCor+'">'+cap.ico_score+'</div>'
    +'<div style="font-size:13px;font-weight:600">'+escHtml(cap.classificacao_capacidade)+'</div>'
    +(p._ico_fonte?'<div style="font-size:10px;color:#185FA5;margin-top:4px">Fonte oficial: '+escHtml(String(p._ico_fonte).replace(/\+/g,' · '))+'</div>':'')
    +(modoComp?'<div style="font-size:10px;color:#085041;margin-top:2px">ICO oficial = <b>ponderado por composição</b>'
      +(cap._ico_agregado!=null?' (agregado anterior: '+cap._ico_agregado+')':'')+'</div>':'')
    +'</div>'
    +'<div style="max-width:420px;font-size:12px;color:#555">'+escHtml(cap.recomendacao)+'</div></div></div>'
    +(ops?'<div style="padding:.65rem 1rem;margin-bottom:1rem;font-size:11px;color:#185FA5;background:#EBF4FD;border-radius:8px">'
      +'Fonte operacional ERP · '+comp.slice(0,7)+': '+ops.equipes_cadastradas+' equipes · '
      +ops.colaboradores_disponiveis+' colaboradores · '+ops.veiculos_disponiveis+' veículos'
      +(ops.veiculos_por_tipo&&ops.veiculos_por_tipo.itens&&ops.veiculos_por_tipo.itens.length
        ?(' — '+ops.veiculos_por_tipo.itens.map(function(it){return it.tipo+': '+it.qtd;}).join(', '))
        :'')
      +(ops.equipes_entregues_media!=null?' · média entregue '+ops.equipes_entregues_media+' eq/dia':'')
      +((p._vinc&&p._vinc.campo!=null)?' · ICO usa <b>'+p._vinc.campo+' campo</b>':'')
      +'</div>':'')
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;margin-bottom:1rem">'
    +vbeMetricCard('Equipes exigidas',cap.equipes_exigidas,'#185FA5')
    +vbeMetricCard('Equipes alvo',cap.equipes_alvo,'#185FA5')
    +vbeMetricCard('Equipes limite',cap.equipes_limite,'#555')
    +vbeMetricCard('Equipes entregues (média)',cap.equipes_entregues_media,'#3B6D11')
    +vbeMetricCard('% atendimento',(cap.percentual_atendimento!=null?cap.percentual_atendimento+'%':'—'),'#854F0B')
    +vbeMetricCard('Colaboradores disp.',cap.colaboradores_disponiveis,'#555')
    +vbeMetricCard('Colaboradores necessários',Math.round(cap.colaboradores_necessarios),'#555')
    +vbeMetricCard('Déficit colaboradores',cap.deficit_colaboradores,'#A32D2D')
    +vbeMetricCard('Veículos (total)',cap.veiculos_disponiveis,'#555')
    +vbeMetricCard('Veículos necessários',cap.veiculos_necessarios,'#555')
    +vbeMetricCard('Déficit veículos',cap.deficit_veiculos,'#A32D2D')
    +vbeMetricCard('Capacidade real (equipes)',cap.capacidade_real_equipes,'#085041')
    +vbeMetricCard('Fat. perdido est.',vbeFmtValor(cap.faturamento_perdido_estimado),'#A32D2D')
    +vbeMetricCard('Fat. potencial limite',vbeFmtValor(cap.faturamento_potencial_limite),'#085041')
    +(cap._composicao&&cap._composicao.resumo.atingimento_meta!=null
      ?vbeMetricCard('Ating. meta composição',cap._composicao.resumo.atingimento_meta+'%',cap._composicao.resumo.atingimento_meta>=80?'#3B6D11':'#A32D2D')
      :'')
    +'</div>'
    +(ops&&ops.veiculos_por_tipo?'<div class="card" style="margin-bottom:1rem;padding:1rem"><div style="font-size:12px;font-weight:600;margin-bottom:8px">Veículos por tipo operacional</div>'
      +vbeHtmlVeiculosPorTipo(cid)+'</div>':'')
    +compHtml
    +simHtml
    +'<div style="font-size:11px;color:#888;padding:0 .5rem 1rem">'
    +(modoComp
      ?'ICO oficial = ponderado por composição (meta/custo × score de cada tipo), com realizado das sessões. Sem remuneração/meta na grade, volta ao ICO agregado.'
      :'ICO agregado = campo + grade. Preencha Remuneração/Meta na grade para adotar o ICO por composição.')
    +'</div>';
}

function vbeMetricCard(l,v,c){
  return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.75rem;text-align:center">'
    +'<div style="font-size:10px;color:#888;margin-bottom:4px">'+l+'</div>'
    +'<div style="font-size:18px;font-weight:700;color:'+(c||'#333')+'">'+v+'</div></div>';
}

/** Etapa F — rótulos amigáveis das categorias gerenciais. */
var VBE_LABEL_CAT_DESPESA={
  salarios:'Salários',encargos:'Encargos',horas_extras_adicionais:'Horas extras / adicionais',
  beneficios:'Benefícios',vale_refeicao:'Vale refeição',vale_alimentacao:'Vale alimentação',
  vale_transporte:'Vale transporte',plano_saude:'Plano de saúde',plano_odontologico:'Plano odontológico',
  seguro_vida:'Seguro de vida',cesta_basica:'Cesta básica',diarias_hospedagens:'Diárias / hospedagens',
  treinamentos:'Treinamentos',uniformes:'Uniformes',epi:'EPI',epc:'EPC',
  combustivel:'Combustível',pedagios:'Pedágios',locacao_frota:'Locação frota',manutencao_frota:'Manutenção frota',
  pneus:'Pneus',documentacao_frota:'Documentação frota',seguros_frota:'Seguros frota',
  materiais:'Materiais',ferramentas:'Ferramentas',
  alugueis_imoveis:'Aluguéis imóveis',energia:'Energia',agua:'Água',telefonia_internet:'Telefonia / internet',
  sistemas:'Sistemas',juridico_contabilidade:'Jurídico / contabilidade',servicos_terceiros:'Serviços de terceiros',
  administrativo:'Administrativo',tributos_nao_faturamento:'Tributos (não fat.)',multas_juros:'Multas / juros',
  outros:'Outros'
};
function vbeLabelCatDespesa(cat){
  if(VBE_LABEL_CAT_DESPESA[cat]) return VBE_LABEL_CAT_DESPESA[cat];
  return String(cat||'').replace(/_/g,' ');
}

function vbeHtmlLinhasCatGrupo(obj){
  if(!obj) return '';
  var html='';
  Object.keys(obj).forEach(function(k){
    if(k==='total') return;
    var v=Number(obj[k]||0);
    if(v<0.005) return;
    html+='<tr><td style="padding:3px 12px 3px 1.75rem;font-size:11px;color:#555">'+escHtml(vbeLabelCatDespesa(k))+'</td>'
      +'<td style="text-align:right;padding:3px 1rem;font-size:11px;color:#333">'+vbeFmtValor(v)+'</td></tr>';
  });
  return html;
}

function vbeHtmlGrupoDespesaDetails(titulo, total, innerRows, aberto){
  total=Number(total||0);
  if(total<0.005&&!innerRows) return '';
  return '<tr><td colspan="2" style="padding:0;border-bottom:.5px solid #eee">'
    +'<details'+(aberto?' open':'')+'>'
    +'<summary style="cursor:pointer;padding:8px 1rem;display:flex;justify-content:space-between;align-items:center;gap:8px;list-style:none">'
    +'<span style="font-weight:600">(−) '+escHtml(titulo)
    +' <span style="font-size:10px;font-weight:500;color:#888;margin-left:4px">▾</span></span>'
    +'<span style="font-weight:600">'+vbeFmtValor(total)+'</span></summary>'
    +'<table style="width:100%;border-collapse:collapse"><tbody>'
    +(innerRows||'<tr><td style="padding:4px 1.75rem;font-size:11px;color:#888" colspan="2">Sem detalhe</td></tr>')
    +'</tbody></table></details></td></tr>';
}

/**
 * Etapa F — DRE expansível por grupo gerencial (pessoal/frota/materiais/backoffice/tributos/outros).
 */
function vbeHtmlDespesasDreExpansivel(desp){
  if(!desp||Number(desp.custo_total||0)<0.005) return '';
  var html='';
  html+=vbeHtmlGrupoDespesaDetails('Pessoal',desp.pessoal&&desp.pessoal.total,vbeHtmlLinhasCatGrupo(desp.pessoal),true);
  html+=vbeHtmlGrupoDespesaDetails('Frota',desp.frota&&desp.frota.total,vbeHtmlLinhasCatGrupo(desp.frota),false);
  html+=vbeHtmlGrupoDespesaDetails('Materiais / equipamentos',desp.materiais_equipamentos&&desp.materiais_equipamentos.total,vbeHtmlLinhasCatGrupo(desp.materiais_equipamentos),false);
  html+=vbeHtmlGrupoDespesaDetails('Backoffice',desp.backoffice&&desp.backoffice.total,vbeHtmlLinhasCatGrupo(desp.backoffice),false);
  html+=vbeHtmlGrupoDespesaDetails('Tributos / financeiro',desp.tributos_financeiro&&desp.tributos_financeiro.total,vbeHtmlLinhasCatGrupo(desp.tributos_financeiro),false);
  var outrosInner='';
  if(Number(desp.outros&&desp.outros.valor||0)>0.005){
    outrosInner='<tr><td style="padding:3px 12px 3px 1.75rem;font-size:11px;color:#555">Não classificados / outros'
      +(desp.outros.quantidade?' ('+desp.outros.quantidade+' it.)':'')+'</td>'
      +'<td style="text-align:right;padding:3px 1rem;font-size:11px">'+vbeFmtValor(desp.outros.valor)+'</td></tr>';
  }
  html+=vbeHtmlGrupoDespesaDetails('Outros',desp.outros&&desp.outros.valor,outrosInner,false);
  html+='<tr style="background:#f9f9f7;font-weight:700"><td style="padding:8px 1rem">= Custo total (grupos)</td>'
    +'<td style="text-align:right;padding:8px 1rem">'+vbeFmtValor(desp.custo_total)+'</td></tr>';
  return html;
}

/** Cards resumo dos grupos (Etapa F). */
function vbeHtmlCardsGruposDespesa(desp){
  if(!desp||Number(desp.custo_total||0)<0.005) return '';
  var items=[
    {l:'Pessoal',v:desp.pessoal&&desp.pessoal.total,c:'#185FA5'},
    {l:'Frota',v:desp.frota&&desp.frota.total,c:'#854F0B'},
    {l:'Materiais',v:desp.materiais_equipamentos&&desp.materiais_equipamentos.total,c:'#3B6D11'},
    {l:'Backoffice',v:desp.backoffice&&desp.backoffice.total,c:'#534AB7'},
    {l:'Tributos',v:desp.tributos_financeiro&&desp.tributos_financeiro.total,c:'#A32D2D'},
    {l:'Outros',v:desp.outros&&desp.outros.valor,c:'#555'},
    {l:'Total',v:desp.custo_total,c:'#085041'}
  ].filter(function(x){return Number(x.v||0)>0.005;});
  if(!items.length) return '';
  return '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(96px,1fr));gap:6px;padding:.5rem .75rem 0">'
    +items.map(function(m){return vbeMetricCard(m.l,vbeFmtValor(m.v),m.c);}).join('')
    +'</div>';
}

