  var comp=vbeGetCompSel(); _vbeCompetencia=comp;
  var wrap=document.getElementById('vbe-custos-wrap'); if(!wrap) return;
  if(!cid){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">'
      +'<div style="font-size:14px;margin-bottom:6px">Selecione um contrato no filtro acima.</div>'
      +'<div style="font-size:12px">A opção <b>Todos os contratos</b> não exibe Custos — escolha um contrato específico.</div></div>';
    return;
  }
  wrap.innerHTML='<div style="padding:1.5rem;text-align:center;color:#888">Carregando custos ERP…</div>';
  await vbeEnsureDadosCustosERP(comp);
  var nDup=await vbeDedupCustosMensais(cid,comp);
  if(nDup>0&&typeof progShowToast==='function') progShowToast(nDup+' custo(s) duplicado(s) removido(s) automaticamente.');
  var custos=vbeCustosComp(cid,comp);
  var erp=vbeColetarCustosERP(cid,comp);
  var totDir=0,totInd=0;
