    +(estado==='prejuizo'||estado==='critico'?'⚠ ':estado==='positivo'?'✓ ':estado==='atencao'?'● ':'○ ')
    +escHtml(config.estadoTexto||vbeEstadoLegenda(estado))+'</span>'
