function vbeCenarioCampoAusente(cen, campo){
  if(!cen) return true;
  return cen[campo]===undefined || cen[campo]===null;
}

function vbeHtmlComparativoCenarios(painel){
  var cen=(painel&&painel.cenarios)||{};
  var p=cen.previsto, c=cen.comprometido, r=cen.realizado;
  function cel(cenObj, campo, tipo){
    return vbeFormatarValorPainel(cenObj?cenObj[campo]:null, tipo, {ausente:vbeCenarioCampoAusente(cenObj,campo)});
  }
  function desvioCls(val, favoravelQuandoPositivo){
    if(val==null||!isFinite(Number(val))) return 'neutro';
    var n=Number(val);
    if(n===0) return 'neutro';
    var bom=favoravelQuandoPositivo ? n>0 : n<0;
    return bom?'positivo':(Math.abs(n)>0?'atencao':'neutro');
  }
  function desvioTxt(val, tipo, favPos){
    if(val==null||!isFinite(Number(val))) return '—';
    var n=Number(val);
    var txt=vbeFormatarValorPainel(n, tipo);
    var st=desvioCls(n, favPos);
    var leg=st==='positivo'?'Favorável':(st==='atencao'?'Desfavorável':'Neutro');
    return '<span class="estado vbe-st-'+st+'">'+escHtml(txt)+' · '+leg+'</span>';
  }
  var dCusto=null, dRes=null, dMarg=null;
  if(r&&p&&!vbeCenarioCampoAusente(r,'custo_total')&&!vbeCenarioCampoAusente(p,'custo_total')){
    dCusto=Number(r.custo_total)-Number(p.custo_total);
  }
  if(r&&p&&!vbeCenarioCampoAusente(r,'resultado_liquido')&&!vbeCenarioCampoAusente(p,'resultado_liquido')){
    dRes=Number(r.resultado_liquido)-Number(p.resultado_liquido);
  }
  if(r&&p&&!vbeCenarioCampoAusente(r,'margem_liquida_percentual')&&!vbeCenarioCampoAusente(p,'margem_liquida_percentual')){
    dMarg=Number(r.margem_liquida_percentual)-Number(p.margem_liquida_percentual);
  }
  var rows=[
    ['Receita líquida','receita_liquida','moeda'],
    ['Custo total','custo_total','moeda'],
    ['Resultado líquido','resultado_liquido','moeda'],
    ['Margem líquida','margem_liquida_percentual','pct']
  ];
  var body=rows.map(function(row){
    return '<tr><td>'+escHtml(row[0])+'</td>'
      +'<td>'+escHtml(cel(p,row[1],row[2]))+'</td>'
      +'<td>'+escHtml(cel(c,row[1],row[2]))+'</td>'
      +'<td>'+escHtml(cel(r,row[1],row[2]))+'</td></tr>';
  }).join('');
  return '<div class="vbe-bloco-tit">Previsto × Comprometido × Realizado</div>'
    +'<div class="vbe-cenarios-wrap" role="region" aria-label="Comparativo de cenários">'
    +'<table class="vbe-cenarios-tbl"><thead><tr>'
    +'<th scope="col">Indicador</th><th scope="col">Previsto</th><th scope="col">Comprometido</th><th scope="col">Realizado</th>'
    +'</tr></thead><tbody>'+body+'</tbody></table></div>'
    +'<div class="vbe-desvios" aria-label="Desvios Realizado versus Previsto">'
    +'<div class="vbe-desvio-item"><div style="font-size:10px;color:#888;font-weight:600">Desvio de custo (R−P)</div>'
    +'<div style="margin-top:4px">'+desvioTxt(dCusto,'moeda',false)+'</div></div>'
    +'<div class="vbe-desvio-item"><div style="font-size:10px;color:#888;font-weight:600">Desvio de resultado (R−P)</div>'
    +'<div style="margin-top:4px">'+desvioTxt(dRes,'moeda',true)+'</div></div>'
    +'<div class="vbe-desvio-item"><div style="font-size:10px;color:#888;font-weight:600">Desvio de margem (R−P)</div>'
    +'<div style="margin-top:4px">'+desvioTxt(dMarg,'pct',true)+'</div></div>'
    +'</div>';
}

function vbeHtmlQualidadePainel(painel){
  var q=(painel&&painel.qualidade)||{};
  var pct=q.percentual_conciliado;
  var conf=q.confiabilidade||'—';
  var dif=q.diferenca_nao_conciliada;
  var st=conf==='Alta'?'positivo':(conf==='Boa'?'neutro':(conf==='Atenção'?'atencao':'critico'));
  return '<div class="vbe-bloco-tit" id="vbe-qualidade-painel">Confiabilidade da Viabilidade</div>'
    +'<div class="vbe-qual-grid">'
    +'<div class="vbe-card-m vbe-st-borda-'+st+'"><div class="tit">Percentual conciliado</div>'
    +'<div class="val">'+escHtml(vbeFormatarValorPainel(pct,'pct'))+'</div></div>'
    +'<div class="vbe-card-m vbe-st-borda-'+st+'"><div class="tit">Qualidade</div>'
    +'<div class="val" style="font-size:20px">'+escHtml(conf)+'</div>'
    +'<span class="estado vbe-st-'+st+'">'+escHtml(conf)+'</span></div>'
    +'<div class="vbe-card-m vbe-st-borda-'+(dif!=null&&Math.abs(Number(dif))>=0.01?'atencao':'neutro')+'">'
    +'<div class="tit">Diferença não conciliada</div>'
    +'<div class="val" style="font-size:16px">'+escHtml(vbeFormatarValorPainel(dif,'moeda'))+'</div></div>'
    +'</div>';
}

function vbeScrollAncoraResultado(ancoraId){
  var el=document.getElementById(ancoraId);
  if(!el) el=document.getElementById('vbe-resultado-legado');
  if(el){
    try{ el.scrollIntoView({behavior:'smooth',block:'start'}); }catch(e){ el.scrollIntoView(true); }
    el.style.outline='2px solid #185FA5';
    setTimeout(function(){ if(el) el.style.outline=''; }, 1600);
  }
}

function vbeHtmlPendenciasPainel(painel){
  var q=(painel&&painel.qualidade)||{};
  var itens=[
    {k:'sem_contrato',t:'Sem contrato',anc:'vbe-diag-despesas'},
    {k:'sem_competencia',t:'Sem competência',anc:'vbe-diag-despesas'},
    {k:'nao_classificados',t:'Não classificadas',anc:'vbe-diag-despesas'},
    {k:'duplicidades',t:'Possíveis duplicidades',anc:'vbe-diag-despesas'},
    {k:'pagamento_parcial_incompleto',t:'Pagamento parcial incompleto',anc:'vbe-diag-despesas'},
    {k:'fora_competencia',t:'Fora da competência',anc:'vbe-diag-despesas'}
  ];
  var html=itens.map(function(it){
    var blk=q[it.k]||{};
    var qtd=blk.quantidade!=null?blk.quantidade:0;
    var val=blk.valor!=null?blk.valor:0;
    return '<button type="button" class="vbe-pend-card" aria-label="'+escHtml(it.t+': '+qtd+' lançamentos, '+vbeFormatarValorPainel(val,'moeda'))+'" '
      +'onclick="vbeScrollAncoraResultado(\''+it.anc+'\')">'
      +'<div style="font-size:12px;font-weight:700">'+escHtml(it.t)+'</div>'
      +'<div class="pq">'+escHtml(vbeFormatarValorPainel(qtd,'qtd'))+' lançamento(s)</div>'
      +'<div class="pv">'+escHtml(vbeFormatarValorPainel(val,'moeda'))+'</div>'
      +'</button>';
  }).join('');
  return '<div class="vbe-bloco-tit">Pendências de classificação e filtro</div>'
    +'<div class="vbe-pend-grid">'+html+'</div>';
}

function vbeOrdenarAlertasPainel(alertas){
  var prio={
    prejuizo:0, diferenca_nao_conciliada:1, sem_contrato:2, duplicidade:3,
    pagamento_parcial_incompleto:4, nao_classificados:5, receita_inexistente:6
  };
  return (alertas||[]).slice().sort(function(a,b){
    var ca=String((a&&a.codigo)||'').toLowerCase();
    var cb=String((b&&b.codigo)||'').toLowerCase();
    var pa=prio[ca]!=null?prio[ca]:50;
    var pb=prio[cb]!=null?prio[cb]:50;
    if(pa!==pb) return pa-pb;
    return Math.abs(Number((b&&b.valor)||0))-Math.abs(Number((a&&a.valor)||0));
  });
}

function vbeHtmlAlertasPainel(painel){
  var lista=vbeOrdenarAlertasPainel(painel&&painel.alertas);
  var top=lista.slice(0,6);
  if(!top.length){
    return '<div class="vbe-bloco-tit">Atenções do contrato</div>'
      +'<div class="vbe-vazio" style="padding:.85rem">Nenhuma pendência material identificada para o período.</div>';
  }
  var html=top.map(function(a){
    var crit=a.nivel==='erro'||a.codigo==='diferenca_nao_conciliada'||/prejuizo/i.test(a.codigo||'');
    return '<div class="vbe-alerta-item'+(crit?' critico':'')+'" role="status">'
      +'<div style="font-weight:700">'+(a.titulo?escHtml(a.titulo):escHtml(String(a.codigo||'Alerta').replace(/_/g,' ')))+'</div>'
      +'<div style="margin-top:2px">'+escHtml(a.mensagem||a.descricao||'')+'</div>'
      +(a.valor!=null?'<div style="margin-top:4px;font-size:11px"><b>Valor:</b> '+escHtml(vbeFormatarValorPainel(a.valor,'moeda'))
        +(a.quantidade!=null?' · '+escHtml(vbeFormatarValorPainel(a.quantidade,'qtd'))+' item(ns)':'')
        +'</div>':'')
      +(a.competencia||a.contrato_id?'<div style="font-size:10px;margin-top:2px;opacity:.85">'
        +escHtml([a.competencia,a.contrato_id].filter(Boolean).join(' · '))+'</div>':'')
      +'</div>';
  }).join('');
  return '<div class="vbe-bloco-tit">Atenções do contrato</div>'
    +'<div class="vbe-alertas-lista">'+html+'</div>';
}

function vbeHtmlIvecComplementar(opts){
  opts=opts||{};
  var iv=opts.ivec||{};
  var conf=opts.confianca||'—';
  if(!iv||iv.ivec_score==null){
    return '<div class="vbe-complementares" id="vbe-ivec-complementar">'
      +'<div class="vbe-bloco-tit" style="margin-top:0">Indicadores complementares</div>'
      +'<div style="font-size:12px;color:#888">IVEC indisponível neste momento.</div></div>';
  }
  var cor=typeof vbeClassCorIvec==='function'?vbeClassCorIvec(iv.ivec_score):'#555';
  var scoreTxt=(typeof vbePodeVerFinanceiro==='function'&&!vbePodeVerFinanceiro())?'Restrito':String(iv.ivec_score);
  return '<div class="vbe-complementares" id="vbe-ivec-complementar">'
    +'<div class="vbe-bloco-tit" style="margin-top:0">Indicadores complementares</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:12px;align-items:flex-start;justify-content:space-between">'
    +'<div><div style="font-size:11px;color:#888">IVEC — índice complementar (não substitui a margem)</div>'
    +'<div style="font-size:28px;font-weight:700;color:'+cor+'">'+escHtml(scoreTxt)+'</div>'
    +'<div style="font-weight:600;font-size:13px">'+escHtml(iv.classificacao||'')+'</div>'
    +'<span class="bdg gray" style="margin-top:4px">Confiança: '+escHtml(conf)+'</span></div>'
    +'<div style="font-size:12px;max-width:420px;color:#555">'+escHtml(iv.recomendacao||'')+'</div>'
    +'</div>'
    +(iv._componentes&&typeof vbePodeVerFinanceiro==='function'&&vbePodeVerFinanceiro()
      ?'<div style="margin-top:8px;font-size:11px;color:#555">Componentes: margem '+vbeFmtNum(iv._componentes.margem,0)
        +' · potencial '+vbeFmtNum(iv._componentes.potencial,0)
        +' · saldo '+vbeFmtNum(iv._componentes.saldo,0)
        +' · prazo '+vbeFmtNum(iv._componentes.prazo,0)
        +' · produtividade '+vbeFmtNum(iv._componentes.produtividade,0)
        +' · capacidade(ICO) '+vbeFmtNum(iv._componentes.capacidade,0)
        +' · risco '+vbeFmtNum(iv._componentes.risco,0)
        +' · fluxo '+vbeFmtNum(iv._componentes.fluxo,0)+'</div>':'')
    +'</div>';
}

/**
 * Painel Margem Etapa C — DRE gerencial + rastreio.
 * Só organiza/apresenta dados de painel_margem (não recalcula economia).
 */
var _vbePainelMargemAtual=null;
var _vbeDreFiltros={};
var _vbeDreFiltroSeq=0;

function vbeRegFiltroDre(filtro){
  var id='f'+(++_vbeDreFiltroSeq);
  _vbeDreFiltros[id]=filtro||{};
  return id;
}
function vbeAbrirDetalhamentoPorId(fid){
  vbeAbrirDetalhamentoValor(_vbeDreFiltros[fid]||{});
}

function vbeMapGrupoFiltroDetalhe(grupoKey){
  var g=String(grupoKey||'').toLowerCase();
  if(g==='pessoal'||g==='diretos_pessoal') return ['pessoal'];
  if(g==='frota'||g==='diretos_frota') return ['frota'];
  if(g==='materiais'||g==='materiais_equipamentos') return ['materiais_equipamentos','materiais','ferramentas'];
  if(g==='servicos'||g==='servicos_operacionais') return ['servicos_terceiros','servicos_operacionais','outros'];
  if(g==='backoffice'||g==='indiretos') return ['backoffice','administrativo'];
  if(g==='administrativo') return ['administrativo'];
  if(g==='financeiro'||g==='despesas_financeiras'||g==='tributos_financeiro') return ['tributos_financeiro','multas_juros','despesas_financeiras'];
  if(g==='tributos'||g==='tributos_resultado') return ['tributos','tributos_financeiro','tributos_resultado'];
  if(g==='outros') return ['outros'];
  return [g];
}

function vbeFiltrarItensDetalhePainel(painel, filtro){
  filtro=filtro||{};
  var det=(painel&&painel.detalhamento)||{};
  var pool=[];
  var fontes=filtro.fontes;
  if(!fontes||!fontes.length){
    if(filtro.cenario==='realizado') fontes=['realizados','incluidos'];
    else if(filtro.cenario==='comprometido') fontes=['comprometidos'];
    else if(filtro.cenario==='previsto') fontes=['incluidos'];
    else fontes=['incluidos','realizados','comprometidos','nao_classificados'];
  }
  fontes.forEach(function(f){
    (det[f]||[]).forEach(function(it){ pool.push(it); });
  });
  // dedup por id
  var seen={};
  pool=pool.filter(function(it){
    var id=String(it&&it.id||'');
    if(!id) return true;
    if(seen[id]) return false;
    seen[id]=true;
    return true;
  });
  var gruposOk=null;
  if(filtro.grupo){
    gruposOk=vbeMapGrupoFiltroDetalhe(filtro.grupo);
  }
  var cat=filtro.categoria?String(filtro.categoria).toLowerCase():'';
  var statusFiltro=filtro.status?String(filtro.status).toLowerCase():'';
  var compFiltro=filtro.competencia?String(filtro.competencia).slice(0,7):'';
  return pool.filter(function(it){
    if(!it) return false;
    if(gruposOk){
      var g=String(it.grupo_dre||it.categoria_gerencial||'').toLowerCase();
      var hit=gruposOk.some(function(x){ return g===x || g.indexOf(x)>=0; });
      if(!hit && filtro.grupo==='outros'){
        hit=!!(it.motivo_inclusao&&String(it.motivo_inclusao).indexOf('outros')>=0) || g==='outros' || !g;
      }
      if(!hit) return false;
    }
    if(cat){
      var c=String(it.categoria_gerencial||it.categoria||it.subcategoria||'').toLowerCase();
      if(c!==cat && c.indexOf(cat)<0 && String(it.categoria||'').toLowerCase().indexOf(cat)<0) return false;
    }
    if(statusFiltro){
      var st=String(it.status||'').toLowerCase();
      if(st!==statusFiltro && st.indexOf(statusFiltro)<0) return false;
    }
    if(compFiltro){
      var yc=String(it.competencia_normalizada||it.competencia_original||'').slice(0,7);
      if(yc && yc!==compFiltro) return false;
    }
    return true;
  });
}

function vbeHtmlLinhaDreSimples(label, valorTxt, cls){
  return '<tr class="'+(cls||'')+'"><td>'+label+'</td><td class="v">'+valorTxt+'</td></tr>';
}

function vbeHtmlLinhasCatGrupoClicaveis(obj, grupoKey){
  if(!obj) return '';
  var html='';
  Object.keys(obj).forEach(function(k){
    if(k==='total') return;
    var v=Number(obj[k]||0);
    if(Math.abs(v)<0.005) return;
    var lab=typeof vbeLabelCatDespesa==='function'?vbeLabelCatDespesa(k):k;
    var fid=vbeRegFiltroDre({grupo:grupoKey,categoria:k,titulo:lab});
    html+='<tr><td><button type="button" class="vbe-dre-cat-btn" aria-label="Detalhar '+escHtml(lab)+'" '
      +'onclick="vbeAbrirDetalhamentoPorId(\''+fid+'\')">'+escHtml(lab)+'</button></td>'
      +'<td class="v">'+escHtml(vbeFormatarValorPainel(v,'moeda'))+'</td></tr>';
  });
  return html||'<tr><td colspan="2" style="color:#888">Sem detalhe de categoria</td></tr>';
}

function vbeHtmlGrupoDreExpansivel(titulo, total, innerHtml, grupoKey, aberto){
  var tot=Number(total||0);
  var fid=vbeRegFiltroDre({grupo:grupoKey,titulo:titulo});
  return '<tr><td colspan="2" style="padding:0">'
    +'<details'+(aberto?' open':'')+'>'
    +'<summary>'
    +'<span>(−) '+escHtml(titulo)+'<span class="mark">▾</span>'
    +' <button type="button" class="vbe-dre-cat-btn" style="font-size:10px;margin-left:6px;font-weight:500" '
    +'onclick="event.preventDefault();event.stopPropagation();vbeAbrirDetalhamentoPorId(\''+fid+'\')" '
    +'aria-label="Ver lançamentos de '+escHtml(titulo)+'">ver lançamentos</button></span>'
    +'<span>'+escHtml(vbeFormatarValorPainel(tot,'moeda'))+'</span>'
    +'</summary>'
    +'<table class="vbe-dre-sub"><tbody>'+(innerHtml||'')+'</tbody></table>'
    +'</details></td></tr>';
}

/**
 * Monta estrutura de exibição do DRE a partir do painel (sem recalcular).
 */
function vbeMontarDreGerencial(painel){
  painel=painel||{};
  var rec=painel.receita||{};
  var cust=painel.custos||{};
  var res=painel.resultado||{};
  var marg=painel.margens||{};
  var det=(cust.grupos&&cust.grupos.detalhe)||{};
  return {
    receita_bruta:rec.bruta,
    impostos_faturamento:rec.impostos_faturamento,
    deducoes:rec.deducoes,
    receita_liquida:rec.liquida,
    diretos:cust.diretos||{},
    indiretos:cust.indiretos||{},
    despesas_financeiras:cust.despesas_financeiras||{},
    tributos_resultado:cust.tributos_resultado||{},
    detalhe_grupos:det,
    margem_bruta_valor:res.margem_bruta_valor,
    resultado_operacional:res.resultado_operacional,
    resultado_antes_tributos:res.resultado_antes_tributos,
    resultado_liquido:res.resultado_liquido,
    margem_liquida_percentual:marg.liquida_percentual,
    classificacao:marg.classificacao,
    conciliacao:painel.conciliacao||null,
    contexto:painel.contexto||{}
  };
}

function vbeHtmlConciliacaoDrePainel(conc){
  if(!conc) return '';
  var ok=!!conc.conciliado;
  function L(lab,val,menos){
    return '<div class="linha"><span>'+(menos?'(−) ':'')+escHtml(lab)+'</span><span>'+escHtml(vbeFormatarValorPainel(val,'moeda'))+'</span></div>';
  }
  return '<div class="vbe-dre-conc" id="vbe-conciliacao-dre">'
    +'<div style="font-weight:700;margin-bottom:6px">Conciliação das despesas do contrato</div>'
    +L('Total de despesas encontradas',conc.total_encontrado,false)
    +L('Fora da competência',conc.fora_competencia,true)
    +L('Outro contrato',conc.outro_contrato,true)
    +L('Canceladas ou reprovadas',conc.cancelado_reprovado,true)
    +L('Ignoradas por duplicidade',conc.ignorado_duplicidade,true)
    +L('Sem contrato',conc.sem_contrato,true)
    +L('Sem competência',conc.sem_competencia,true)
    +L('Pendentes de classificação',conc.pendente_classificacao,true)
    +(conc.comprometido_aberto!=null?L('Comprometido em aberto (não no DRE realizado)',conc.comprometido_aberto,true):'')
    +'<div class="linha" style="font-weight:700;border-top:.5px solid #ddd;margin-top:4px;padding-top:4px">'
    +'<span>= Total considerado no DRE</span><span>'+escHtml(vbeFormatarValorPainel(conc.total_considerado_dre,'moeda'))+'</span></div>'
    +'<div class="linha" style="margin-top:4px;color:'+(ok?'#3B6D11':'#A32D2D')+'">'
    +'<span>'+(ok?'✓ Conciliado':'⚠ Diferença não conciliada')+'</span>'
    +'<span>'+escHtml(vbeFormatarValorPainel(conc.diferenca,'moeda'))+'</span></div>'
    +(!ok?'<div style="margin-top:6px;font-size:11px;color:#A32D2D">Alerta: existe diferença não conciliada entre as despesas encontradas e o DRE. O valor não foi forçado a zero.</div>':'')
    +'</div>';
}

