    +(Number(d.deducoes||0)>0.005?vbeHtmlLinhaDreSimples('(−) Deduções', escHtml(vbeFormatarValorPainel(d.deducoes,'moeda'))):'')
    +vbeHtmlLinhaDreSimples('= Receita líquida', escHtml(vbeFormatarValorPainel(d.receita_liquida,'moeda')),'tot')
    +vbeHtmlGrupoDreExpansivel('Custos diretos — Pessoal', dir.pessoal, vbeHtmlLinhasCatGrupoClicaveis(det.pessoal,'pessoal'), 'pessoal', true)
    +vbeHtmlGrupoDreExpansivel('Custos diretos — Frota', dir.frota, vbeHtmlLinhasCatGrupoClicaveis(det.frota,'frota'), 'frota', false)
    +vbeHtmlGrupoDreExpansivel('Custos diretos — Materiais / equipamentos', dir.materiais_equipamentos, vbeHtmlLinhasCatGrupoClicaveis(det.materiais_equipamentos,'materiais_equipamentos'), 'materiais_equipamentos', false)
    +vbeHtmlGrupoDreExpansivel('Custos diretos — Serviços operacionais', dir.servicos_operacionais, vbeHtmlLinhasCatGrupoClicaveis(det.backoffice,'servicos_operacionais'), 'servicos_operacionais', false)
