function vbeAbrirDetalhamentoValor(filtro){
  filtro=filtro||{};
  if(typeof filtro==='string'){
    try{ filtro=JSON.parse(filtro); }catch(e){ filtro={titulo:filtro}; }
  }
  var painel=_vbePainelMargemAtual;
  if(!painel){
    if(typeof progShowToast==='function') progShowToast('Painel de margem não disponível. Reabra a aba Resultado.','erro');
    return;
  }
  var itens=vbeFiltrarItensDetalhePainel(painel, filtro);
  var titulo=filtro.titulo||filtro.categoria||filtro.grupo||'Detalhamento';
  var tot=itens.reduce(function(s,it){return s+Number(it.valor_considerado!=null?it.valor_considerado:it.valor_total||0);},0);
  var rows=itens.map(function(it){
    return '<tr>'
      +'<td>'+escHtml(it.competencia_normalizada||it.competencia_original||'—')+'</td>'
      +'<td>'+escHtml(it.descricao||'—')+'</td>'
      +'<td>'+escHtml(it.fornecedor||'—')+'</td>'
      +'<td>'+escHtml(it.categoria||'—')+(it.subcategoria?' / '+escHtml(it.subcategoria):'')+'</td>'
      +'<td>'+escHtml(it.categoria_gerencial||'—')+'</td>'
      +'<td>'+escHtml(it.grupo_dre||'—')+'</td>'
      +'<td>'+escHtml(it.status||'—')+'</td>'
      +'<td style="text-align:right">'+escHtml(vbeFormatarValorPainel(it.valor_total,'moeda'))+'</td>'
      +'<td style="text-align:right">'+escHtml(vbeFormatarValorPainel(it.valor_considerado,'moeda'))+'</td>'
      +'<td style="text-align:right">'+(it.valor_pago!=null?escHtml(vbeFormatarValorPainel(it.valor_pago,'moeda')):'—')+'</td>'
      +'<td>'+escHtml(it.origem||'—')+'</td>'
      +'<td style="font-size:10px">'+escHtml(it.motivo_inclusao||it.motivo_exclusao||'—')+'</td>'
      +'<td style="font-size:10px;font-family:monospace">'+escHtml(String(it.id||'').slice(0,8))+'</td>'
      +'</tr>';
  }).join('');
  var aviso='';
  if(!itens.length){
    aviso='<div style="padding:12px;color:#854F0B;background:#FAEEDA;border-radius:8px;margin-bottom:8px;font-size:12px">'
      +'Nenhum lançamento financeiro encontrado neste filtro. O valor pode vir de módulo (frota, combustível, locações, premissa) ou de rateio sem item em detalhamento.'
      +'</div>';
  }
  var html='<div class="modal-bg vbe-detalhe-modal" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:960px;max-height:90vh;overflow:auto" role="dialog" aria-label="Detalhamento '+escHtml(titulo)+'">'
    +'<h3 style="margin:0 0 .35rem">🔎 '+escHtml(titulo)+'</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">'
    +itens.length+' lançamento(s) · total considerado <b>'+escHtml(vbeFormatarValorPainel(tot,'moeda'))+'</b>'
    +(filtro.grupo?' · grupo '+escHtml(filtro.grupo):'')
    +(filtro.categoria?' · cat. '+escHtml(filtro.categoria):'')
    +(filtro.cenario?' · cenário '+escHtml(filtro.cenario):'')
    +(filtro.status?' · status '+escHtml(filtro.status):'')
    +'</div>'
    +aviso
    +'<div style="overflow:auto;max-height:55vh;border:.5px solid #e0dfd8;border-radius:8px">'
    +'<table class="tbl" style="margin:0;min-width:900px"><thead><tr>'
    +'<th>Competência</th><th>Descrição</th><th>Fornecedor</th><th>Cat. financeira</th>'
    +'<th>Cat. gerencial</th><th>Grupo DRE</th><th>Status</th>'
    +'<th style="text-align:right">Valor total</th><th style="text-align:right">Considerado</th>'
    +'<th style="text-align:right">Valor pago</th><th>Fonte</th><th>Motivo</th><th>Id</th>'
    +'</tr></thead><tbody>'
    +(rows||'<tr><td colspan="13" style="text-align:center;color:#888;padding:1rem">Sem itens</td></tr>')
    +'</tbody></table></div>'
    +'<div style="display:flex;justify-content:flex-end;margin-top:12px">'
    +'<button class="btn btn-pri" onclick="closeModal()">Fechar</button></div>'
    +'</div></div>';
  if(typeof setModal==='function') setModal(html);
  else alert(titulo+': '+itens.length+' itens');
}

function vbeRenderDreGerencialPainel(painel){
  _vbePainelMargemAtual=painel||null;
  _vbeDreFiltros={};
  _vbeDreFiltroSeq=0;
  try{ return vbeHtmlDreGerencial(painel); }
  catch(e){ console.warn('[VBE] DRE gerencial',e); return '<div class="vbe-vazio">Erro ao montar o DRE gerencial.</div>'; }
}

/* ========== Painel Margem — Etapa D: Previsto × Comprometido × Realizado ========== */
var VBE_GRUPOS_CENARIO_ORDEM=[
  {key:'pessoal',label:'Pessoal'},
  {key:'frota',label:'Frota'},
  {key:'materiais_equipamentos',label:'Materiais e equipamentos'},
  {key:'servicos_operacionais',label:'Serviços operacionais'},
  {key:'backoffice',label:'Backoffice'},
  {key:'administrativo',label:'Administrativo'},
  {key:'despesas_financeiras',label:'Despesas financeiras'},
  {key:'tributos',label:'Tributos'},
  {key:'outros',label:'Outros'}
];

function vbeFormatarPontosPercentuais(valor){
  if(valor===undefined||valor===null||valor===''||!isFinite(Number(valor))) return '—';
  var n=Number(valor);
  var abs=Math.abs(n).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  var sinal=n>0?'+':(n<0?'-':'');
  return sinal+abs+' p.p.';
}

/**
 * Classifica desvio conforme tipo do indicador.
 * custo: positivo = desfavorável; receita/resultado/margem: positivo = favorável.
 */
function vbeClassificarDesvio(valor, tipoIndicador){
  if(valor===undefined||valor===null||!isFinite(Number(valor))){
    return {codigo:'neutro',texto:'Neutro',favoravel:null,icone:'○'};
  }
  var n=Number(valor);
  if(Math.abs(n)<0.005){
    return {codigo:'neutro',texto:'Neutro',favoravel:null,icone:'○'};
  }
  var tipo=String(tipoIndicador||'custo').toLowerCase();
  var positivoFavoravel=(tipo==='receita'||tipo==='resultado'||tipo==='margem');
  var fav=positivoFavoravel ? n>0 : n<0;
  return {
    codigo:fav?'favoravel':'desfavoravel',
    texto:fav?'Favorável':'Desfavorável',
    favoravel:fav,
    icone:fav?'✓':'⚠',
    sinal:n>0?'+':'-'
  };
}

function vbeCampoCenarioPresente(cen, campo){
  if(!cen) return false;
  var v=cen[campo];
  return v!==undefined && v!==null && v!=='';
}

function vbeLerGrupoCenario(grupos, key){
  if(!grupos || !Object.prototype.hasOwnProperty.call(grupos, key)){
    return {presente:false, valor:null};
  }
  var v=grupos[key];
  if(v===undefined||v===null||v==='') return {presente:false, valor:null};
  var n=Number(v);
  if(!isFinite(n)) return {presente:false, valor:null};
  return {presente:true, valor:n};
}

function vbeCalcularDesviosCenarios(painel){
  painel=painel||{};
  var cen=painel.cenarios||{};
  var prev=cen.previsto||{};
  var comp=cen.comprometido||{};
  var real=cen.realizado||{};
  var conc=painel.conciliacao||{};

  function deltaCampo(a, b, campo){
    if(!vbeCampoCenarioPresente(a,campo)||!vbeCampoCenarioPresente(b,campo)) return null;
    return Number(b[campo])-Number(a[campo]);
  }

  var desvioReceita=deltaCampo(prev, real, 'receita_liquida');
  var desvioCusto=deltaCampo(prev, real, 'custo_total');
  var desvioResultado=deltaCampo(prev, real, 'resultado_liquido');
  var desvioMargem=deltaCampo(prev, real, 'margem_liquida_percentual');

  var comprometidoAberto=null;
  if(comp.custo_aberto!=null&&isFinite(Number(comp.custo_aberto))){
    comprometidoAberto=Number(comp.custo_aberto);
  } else if(conc.comprometido_aberto!=null&&isFinite(Number(conc.comprometido_aberto))){
    comprometidoAberto=Number(conc.comprometido_aberto);
  } else if(vbeCampoCenarioPresente(comp,'custo_total')&&vbeCampoCenarioPresente(real,'custo_total')){
    comprometidoAberto=Number(comp.custo_total)-Number(real.custo_total);
  }

  return {
    desvio_receita:desvioReceita,
    desvio_custo:desvioCusto,
    desvio_resultado:desvioResultado,
    desvio_margem:desvioMargem,
    desvio_receita_cls:vbeClassificarDesvio(desvioReceita,'receita'),
    desvio_custo_cls:vbeClassificarDesvio(desvioCusto,'custo'),
    desvio_resultado_cls:vbeClassificarDesvio(desvioResultado,'resultado'),
    desvio_margem_cls:vbeClassificarDesvio(desvioMargem,'margem'),
    comprometido_aberto:comprometidoAberto,
    receita_comprometida_disponivel:comp.receita_comprometida_disponivel===true && vbeCampoCenarioPresente(comp,'receita_liquida')
  };
}

function vbeMontarComparativoCenarios(painel){
  painel=painel||{};
  var cen=painel.cenarios||{};
  var prev=cen.previsto||null;
  var comp=cen.comprometido||null;
  var real=cen.realizado||null;
  var desvios=vbeCalcularDesviosCenarios(painel);
  var gPrev=(prev&&prev.grupos)||{};
  var gComp=(comp&&comp.grupos)||{};
  var gReal=(real&&real.grupos)||{};
  var baseMat=Math.max(
    vbeCampoCenarioPresente(prev,'custo_total')?Math.abs(Number(prev.custo_total)):0,
    vbeCampoCenarioPresente(real,'custo_total')?Math.abs(Number(real.custo_total)):0,
    1
  );

  var linhas=[];
  var somaPrev=0, somaComp=0, somaReal=0;
  var temSomaPrev=false, temSomaComp=false, temSomaReal=false;
  // Partição para consistência (administrativo ⊂ backoffice; desp.fin ⊂ tributos)
  var keysParticao={pessoal:1,frota:1,materiais_equipamentos:1,servicos_operacionais:1,backoffice:1,tributos:1,outros:1};

  VBE_GRUPOS_CENARIO_ORDEM.forEach(function(meta){
    var lp=vbeLerGrupoCenario(gPrev, meta.key);
    var lc=vbeLerGrupoCenario(gComp, meta.key);
    var lr=vbeLerGrupoCenario(gReal, meta.key);
    var saldo=null;
    if(lc.presente&&lr.presente) saldo=lc.valor-lr.valor;
    else if(lc.presente&&!lr.presente) saldo=lc.valor;
    var desvioReal=null;
    var desvioPct=null;
    var semBasePrevista=false;
    if(lp.presente&&lr.presente){
      desvioReal=lr.valor-lp.valor;
      if(Math.abs(lp.valor)<0.0000001){
        desvioPct=null;
        if(Math.abs(lr.valor)>=0.005) semBasePrevista=true;
      } else {
        desvioPct=(lr.valor-lp.valor)/lp.valor*100;
      }
    } else if(!lp.presente&&lr.presente&&Math.abs(lr.valor)>=0.005){
      desvioReal=lr.valor;
      desvioPct=null;
      semBasePrevista=true;
    }
    var desvioComp=null;
    if(lp.presente&&lc.presente) desvioComp=lc.valor-lp.valor;

    if(keysParticao[meta.key]){
      if(lp.presente){ somaPrev+=lp.valor; temSomaPrev=true; }
      if(lc.presente){ somaComp+=lc.valor; temSomaComp=true; }
      if(lr.presente){ somaReal+=lr.valor; temSomaReal=true; }
    }

    var material=false;
    if(desvioReal!=null){
      material=typeof vbeEhMaterial==='function'
        ? vbeEhMaterial(desvioReal, lp.presente?lp.valor:baseMat)
        : Math.abs(desvioReal)>=1000;
    }

    linhas.push({
      key:meta.key,
      label:meta.label,
      previsto:lp,
      comprometido:lc,
      realizado:lr,
      saldo_a_realizar:saldo,
      desvio_realizado:desvioReal,
      desvio_percentual:desvioPct,
      desvio_comprometido:desvioComp,
      sem_base_prevista:semBasePrevista,
      classificacao:vbeClassificarDesvio(desvioReal,'custo'),
      material:material
    });
  });

  function checkSoma(soma, temSoma, cenObj){
    if(!temSoma||!cenObj||!vbeCampoCenarioPresente(cenObj,'custo_total')){
      return {ok:true, soma:temSoma?soma:null, total:cenObj&&vbeCampoCenarioPresente(cenObj,'custo_total')?Number(cenObj.custo_total):null, diff:null};
    }
    var tot=Number(cenObj.custo_total);
    var diff=soma-tot;
    return {ok:Math.abs(diff)<0.02, soma:soma, total:tot, diff:diff};
  }

  var cons={
    previsto:checkSoma(somaPrev, temSomaPrev, prev),
    comprometido:checkSoma(somaComp, temSomaComp, comp),
    realizado:checkSoma(somaReal, temSomaReal, real)
  };
  var alertaConsistencia=null;
  if(!cons.previsto.ok||!cons.comprometido.ok||!cons.realizado.ok){
    alertaConsistencia='A soma dos grupos não fecha com o custo total do cenário (tolerância de centavos). Os totais canônicos do painel foram mantidos — valores não foram forçados.';
  }

  var maiores=linhas
    .filter(function(L){ return L.desvio_realizado!=null && L.material; })
    .slice()
    .sort(function(a,b){ return Math.abs(b.desvio_realizado)-Math.abs(a.desvio_realizado); })
    .slice(0,5);

  return {
    previsto:prev,
    comprometido:comp,
    realizado:real,
    desvios:desvios,
    grupos:linhas,
    maiores_desvios:maiores,
    consistencia:cons,
    alerta_consistencia:alertaConsistencia,
    limitacoes:[
      !desvios.receita_comprometida_disponivel
        ? 'Receita comprometida indisponível na base atual (não se copia previsto/realizado).'
        : null,
      !prev ? 'Cenário previsto ausente.' : null,
      !comp ? 'Cenário comprometido ausente.' : null,
      !real ? 'Cenário realizado ausente.' : null
    ].filter(Boolean),
    contexto:(painel&&painel.contexto)||{}
  };
}

function vbeHtmlTextoDesvio(valor, tipoFmt, tipoIndicador, opcoes){
  opcoes=opcoes||{};
  if(valor===undefined||valor===null||!isFinite(Number(valor))){
    return '<span class="vbe-tag-neut" title="'+(opcoes.title||'Sem desvio calculável')+'">—</span>';
  }
  var cls=vbeClassificarDesvio(valor, tipoIndicador);
  var txt;
  if(tipoFmt==='pp') txt=vbeFormatarPontosPercentuais(valor);
  else {
    txt=vbeFormatarValorPainel(valor, tipoFmt||'moeda');
    if(Number(valor)>0 && txt.charAt(0)!=='+' && txt.charAt(0)!=='-') txt='+'+txt;
  }
  var tagCls=cls.codigo==='favoravel'?'vbe-tag-fav':(cls.codigo==='desfavoravel'?'vbe-tag-desfav':'vbe-tag-neut');
  var title=(opcoes.title||cls.texto)+(opcoes.extraTitle?' · '+opcoes.extraTitle:'');
  return '<span class="'+tagCls+'" title="'+escHtml(title)+'">'+escHtml(cls.icone+' '+txt)+' <span style="font-weight:600;font-size:10px">'+escHtml(cls.texto)+'</span></span>';
}

function vbeHtmlCelulaCenarioMoeda(info, grupoKey, cenario){
  if(!info||!info.presente){
    return '<span title="Sem dados para este grupo/cenário">—</span>';
  }
  var txt=vbeFormatarValorPainel(info.valor,'moeda');
  if(Math.abs(Number(info.valor))<0.005){
    return '<span title="Valor explícito zero">'+escHtml(txt)+'</span>';
  }
  var gEsc=String(grupoKey||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
  var cEsc=String(cenario||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
  return '<button type="button" class="cell-btn" onclick="vbeAbrirDetalhamentoCenario(\''+gEsc+'\',\''+cEsc+'\')" '
    +'aria-label="Detalhar '+escHtml(grupoKey)+' '+escHtml(cenario)+'">'+escHtml(txt)+'</button>';
}

function vbeAbrirDetalhamentoCenario(grupo, cenario, fid){
  if(fid){ vbeAbrirDetalhamentoPorId(fid); return; }
  var rotulo=cenario==='realizado'?'Realizado':(cenario==='comprometido'?'Comprometido':'Previsto');
  vbeAbrirDetalhamentoValor({
    grupo:grupo,
    cenario:cenario,
    titulo:rotulo+' — '+grupo
  });
}

function vbeHtmlResumoComparativoCenarios(comparativo){
  comparativo=comparativo||{};
  var p=comparativo.previsto||{};
  var c=comparativo.comprometido||{};
  var r=comparativo.realizado||{};
  var d=comparativo.desvios||{};
  function celCen(cen, campo, tipo, forcarAusente){
    if(forcarAusente||!vbeCampoCenarioPresente(cen,campo)) return '—';
    return vbeFormatarValorPainel(cen[campo], tipo);
  }
  var recCompAusente=!d.receita_comprometida_disponivel;
  var rows=[
    {
      lab:'Receita líquida',
      prev:celCen(p,'receita_liquida','moeda'),
      comp:celCen(c,'receita_liquida','moeda', recCompAusente),
      real:celCen(r,'receita_liquida','moeda'),
      desvioHtml:vbeHtmlTextoDesvio(d.desvio_receita,'moeda','receita')
    },
    {
      lab:'Custo total',
      prev:celCen(p,'custo_total','moeda'),
      comp:celCen(c,'custo_total','moeda'),
      real:celCen(r,'custo_total','moeda'),
      desvioHtml:vbeHtmlTextoDesvio(d.desvio_custo,'moeda','custo')
    },
    {
      lab:'Resultado líquido',
      prev:celCen(p,'resultado_liquido','moeda'),
      comp:celCen(c,'resultado_liquido','moeda', true),
      real:celCen(r,'resultado_liquido','moeda'),
      desvioHtml:vbeHtmlTextoDesvio(d.desvio_resultado,'moeda','resultado')
    },
    {
      lab:'Margem líquida',
      prev:celCen(p,'margem_liquida_percentual','pct'),
      comp:celCen(c,'margem_liquida_percentual','pct', true),
      real:celCen(r,'margem_liquida_percentual','pct'),
      desvioHtml:vbeHtmlTextoDesvio(d.desvio_margem,'pp','margem')
    }
  ];
  var body=rows.map(function(row){
    return '<tr><td>'+escHtml(row.lab)+'</td>'
      +'<td>'+escHtml(row.prev)+'</td>'
      +'<td>'+escHtml(row.comp)+'</td>'
      +'<td>'+escHtml(row.real)+'</td>'
      +'<td>'+row.desvioHtml+'</td></tr>';
  }).join('');
  return '<div class="vbe-tbl-scroll" role="region" aria-label="Resumo Previsto Comprometido Realizado">'
    +'<table class="vbe-tbl-cen"><thead><tr>'
    +'<th scope="col">Indicador</th><th scope="col">Previsto</th><th scope="col">Comprometido</th>'
    +'<th scope="col">Realizado</th><th scope="col">Desvio Realizado × Previsto</th>'
    +'</tr></thead><tbody>'+body+'</tbody></table></div>';
}

function vbeHtmlCardsDesvioCenarios(comparativo){
  var d=(comparativo&&comparativo.desvios)||{};
  function card(titulo, valorHtml, cls, sub){
    return '<div class="vbe-desvio-card '+cls+'" role="group" aria-label="'+escHtml(titulo)+'">'
      +'<div class="t">'+escHtml(titulo)+'</div>'
      +'<div class="v">'+valorHtml+'</div>'
      +(sub?'<div class="s">'+escHtml(sub)+'</div>':'')
      +'</div>';
  }
  function clsDe(c){
    if(!c) return 'neut';
    if(c.codigo==='favoravel') return 'fav';
    if(c.codigo==='desfavoravel') return 'desfav';
    return 'neut';
  }
  function valMoeda(v, tipoInd){
    if(v==null||!isFinite(Number(v))) return '—';
    var t=vbeFormatarValorPainel(v,'moeda');
    if(Number(v)>0 && t.charAt(0)!=='+') t='+'+t;
    var c=vbeClassificarDesvio(v, tipoInd);
    return escHtml(c.icone+' '+t);
  }
  var aberto=d.comprometido_aberto;
  return '<div class="vbe-desvio-cards" aria-label="Cards de desvio">'
    +card('Desvio de receita', valMoeda(d.desvio_receita,'receita'), clsDe(d.desvio_receita_cls), d.desvio_receita_cls&&d.desvio_receita_cls.texto)
    +card('Desvio de custo', valMoeda(d.desvio_custo,'custo'), clsDe(d.desvio_custo_cls), d.desvio_custo_cls&&d.desvio_custo_cls.texto)
    +card('Desvio de resultado', valMoeda(d.desvio_resultado,'resultado'), clsDe(d.desvio_resultado_cls), d.desvio_resultado_cls&&d.desvio_resultado_cls.texto)
    +card('Desvio de margem', d.desvio_margem!=null?escHtml((d.desvio_margem_cls&&d.desvio_margem_cls.icone||'')+' '+vbeFormatarPontosPercentuais(d.desvio_margem)):'—',
      clsDe(d.desvio_margem_cls), d.desvio_margem_cls&&d.desvio_margem_cls.texto)
    +card('Comprometido ainda não realizado',
      aberto!=null?escHtml(vbeFormatarValorPainel(aberto,'moeda')):'—',
      aberto!=null&&Math.abs(Number(aberto))>=0.005?'aten':'neut',
      'custo comprometido − realizado')
    +'</div>';
}

function vbeHtmlTabelaGruposCenarios(comparativo){
  comparativo=comparativo||{};
  var linhas=comparativo.grupos||[];
  var p=comparativo.previsto||{};
  var c=comparativo.comprometido||{};
  var r=comparativo.realizado||{};
  var body=linhas.map(function(L){
    var tipComp=L.desvio_comprometido!=null
      ?('Desvio comprometido×previsto: '+vbeFormatarValorPainel(L.desvio_comprometido,'moeda'))
      :'Sem desvio comprometido calculável';
    var desvioPctTxt='—';
    var desvioPctTitle='';
    if(L.sem_base_prevista){
      desvioPctTxt='—';
      desvioPctTitle='sem base prevista';
    } else if(L.desvio_percentual!=null&&isFinite(L.desvio_percentual)){
      var pct=L.desvio_percentual;
      var pctFmt=vbeFormatarValorPainel(pct,'pct');
      if(pct>0 && pctFmt.charAt(0)!=='+' && pctFmt.charAt(0)!=='-') pctFmt='+'+pctFmt;
      desvioPctTxt=pctFmt;
    }
    var clsDesv=L.classificacao||{};
    var tag=clsDesv.codigo==='favoravel'?'vbe-tag-fav':(clsDesv.codigo==='desfavoravel'?'vbe-tag-desfav':'vbe-tag-neut');
    var desvioTxt=L.desvio_realizado==null?'—'
      :((Number(L.desvio_realizado)>0?'+':'')+vbeFormatarValorPainel(L.desvio_realizado,'moeda'));
    return '<tr title="'+escHtml(tipComp)+'">'
      +'<td>'+escHtml(L.label)+'</td>'
      +'<td>'+vbeHtmlCelulaCenarioMoeda(L.previsto,L.key,'previsto')+'</td>'
      +'<td>'+vbeHtmlCelulaCenarioMoeda(L.comprometido,L.key,'comprometido')+'</td>'
      +'<td>'+vbeHtmlCelulaCenarioMoeda(L.realizado,L.key,'realizado')+'</td>'
      +'<td>'+(L.saldo_a_realizar==null?'—':escHtml(vbeFormatarValorPainel(L.saldo_a_realizar,'moeda')))+'</td>'
      +'<td><span class="'+tag+'" title="'+escHtml((clsDesv.texto||'')+(L.sem_base_prevista?' · sem base prevista':''))+'">'
      +escHtml((clsDesv.icone?clsDesv.icone+' ':'')+desvioTxt)+'</span>'
      +(L.sem_base_prevista?' <span class="vbe-tag-aten" title="sem base prevista">sem base prevista</span>':'')
      +'</td>'
      +'<td title="'+escHtml(desvioPctTitle||'')+'">'+(L.sem_base_prevista?'<span class="vbe-tag-aten">—</span>':escHtml(desvioPctTxt))+'</td>'
      +'</tr>';
  }).join('');

  function totCel(cen){
    return vbeCampoCenarioPresente(cen,'custo_total')?escHtml(vbeFormatarValorPainel(cen.custo_total,'moeda')):'—';
  }
  var saldoTot=null;
  if(vbeCampoCenarioPresente(c,'custo_total')&&vbeCampoCenarioPresente(r,'custo_total')){
    saldoTot=Number(c.custo_total)-Number(r.custo_total);
  } else if(comparativo.desvios&&comparativo.desvios.comprometido_aberto!=null){
    saldoTot=comparativo.desvios.comprometido_aberto;
  }
  var desvioTot=comparativo.desvios?comparativo.desvios.desvio_custo:null;
  var desvioTotPct=null;
  var semBaseTot=false;
  if(vbeCampoCenarioPresente(p,'custo_total')&&vbeCampoCenarioPresente(r,'custo_total')){
    var pv=Number(p.custo_total), rv=Number(r.custo_total);
    if(Math.abs(pv)<0.0000001){ semBaseTot=Math.abs(rv)>=0.005; }
    else desvioTotPct=(rv-pv)/pv*100;
  }
  var clsTot=vbeClassificarDesvio(desvioTot,'custo');
  var tagTot=clsTot.codigo==='favoravel'?'vbe-tag-fav':(clsTot.codigo==='desfavoravel'?'vbe-tag-desfav':'vbe-tag-neut');
  var desvioTotTxt=desvioTot==null?'—':((Number(desvioTot)>0?'+':'')+vbeFormatarValorPainel(desvioTot,'moeda'));
  var pctTotTxt='—';
  if(!semBaseTot&&desvioTotPct!=null){
    pctTotTxt=vbeFormatarValorPainel(desvioTotPct,'pct');
    if(desvioTotPct>0&&pctTotTxt.charAt(0)!=='+'&&pctTotTxt.charAt(0)!=='-') pctTotTxt='+'+pctTotTxt;
  }

  body+='<tr class="tot"><td>Total</td>'
    +'<td>'+totCel(p)+'</td><td>'+totCel(c)+'</td><td>'+totCel(r)+'</td>'
    +'<td>'+(saldoTot==null?'—':escHtml(vbeFormatarValorPainel(saldoTot,'moeda')))+'</td>'
    +'<td><span class="'+tagTot+'">'+escHtml((clsTot.icone?clsTot.icone+' ':'')+desvioTotTxt)+'</span></td>'
    +'<td>'+(semBaseTot?'<span class="vbe-tag-aten">—</span>':escHtml(pctTotTxt))+'</td></tr>';

  var alerta='';
  if(comparativo.alerta_consistencia){
    alerta='<div style="margin-top:8px;padding:8px 10px;background:#FAEEDA;border-radius:8px;font-size:11px;color:#854F0B">'
      +'⚠ '+escHtml(comparativo.alerta_consistencia)+'</div>';
  }

  return '<div class="vbe-bloco-tit" style="margin-top:4px">Custos por grupo</div>'
    +'<div class="vbe-tbl-scroll" role="region" aria-label="Tabela de grupos Previsto Comprometido Realizado">'
    +'<table class="vbe-tbl-cen"><thead><tr>'
    +'<th scope="col">Grupo</th><th scope="col">Previsto</th><th scope="col">Comprometido</th>'
    +'<th scope="col">Realizado</th><th scope="col">Saldo a realizar</th>'
    +'<th scope="col">Desvio realizado</th><th scope="col">Desvio %</th>'
    +'</tr></thead><tbody>'+body+'</tbody></table></div>'
    +alerta;
}

function vbeHtmlMaioresDesvios(comparativo){
  var lista=(comparativo&&comparativo.maiores_desvios)||[];
  if(!lista.length){
    return '<div class="vbe-bloco-tit">Maiores desvios de custo</div>'
      +'<div style="font-size:12px;color:#555;padding:6px 0">Nenhum desvio material identificado no período.</div>';
  }
  var items=lista.map(function(L,i){
    var n=Number(L.desvio_realizado);
    var absTxt=vbeFormatarValorPainel(Math.abs(n),'moeda');
    var sinal=n>0?'+':'−';
    var lado=n>0?'acima do previsto':(n<0?'abaixo do previsto':'no previsto');
    if(L.sem_base_prevista) lado='sem base prevista';
    var cls=n>0?'vbe-tag-desfav':'vbe-tag-fav';
    return '<div class="vbe-maior-item"><span class="'+cls+'">'+(i+1)+'. '+escHtml(L.label)+': '
      +escHtml(sinal+absTxt)+' '+escHtml(lado)+'</span></div>';
  }).join('');
  return '<div class="vbe-bloco-tit">Maiores desvios de custo</div>'
    +'<div class="vbe-maiores-lista" aria-label="Maiores desvios materiais">'+items+'</div>';
}

function vbeHtmlComparativoCenariosDetalhado(painel){
  if(!painel||!painel.cenarios){
    return '<div class="vbe-cenarios-d" id="vbe-cenarios-desvios"><div class="body">'
      +'<div class="vbe-vazio">Não há cenários consolidados para comparar Previsto × Comprometido × Realizado.</div>'
      +'</div></div>';
  }
  var cmp=vbeMontarComparativoCenarios(painel);
  var limHtml='';
  if(cmp.limitacoes&&cmp.limitacoes.length){
    limHtml='<div style="font-size:11px;color:#854F0B;margin-bottom:10px">'
      +cmp.limitacoes.map(function(t){ return '· '+escHtml(t); }).join('<br>')
      +'</div>';
  }
  var ctx=cmp.contexto||{};
  return '<div class="vbe-cenarios-d" id="vbe-cenarios-desvios" role="region" aria-label="Previsto Comprometido Realizado">'
    +'<div class="head"><div class="vbe-bloco-tit" style="margin:0">Previsto × Comprometido × Realizado</div>'
    +'<div style="font-size:11px;color:#888;margin-top:2px">Fonte: painel_margem.cenarios · '
    +escHtml(ctx.contrato_nome||'')+' · '+escHtml(vbeFormatarValorPainel(ctx.competencia_referencia,'competencia'))
    +' · Previsto ≠ Comprometido ≠ Realizado</div></div>'
    +'<div class="body">'
    +limHtml
    +vbeHtmlCardsDesvioCenarios(cmp)
    +vbeHtmlResumoComparativoCenarios(cmp)
    +vbeHtmlTabelaGruposCenarios(cmp)
    +vbeHtmlMaioresDesvios(cmp)
    +'</div></div>';
}

function vbeRenderComparativoCenariosPainel(painel){
  try{ return vbeHtmlComparativoCenariosDetalhado(painel); }
  catch(e){
    console.warn('[VBE] comparativo cenários Etapa D',e);
    return '<div class="vbe-cenarios-d"><div class="body"><div class="vbe-vazio">Erro ao montar o comparativo de cenários.</div></div></div>';
  }
}

/**
 * Resumo executivo — lê apenas painel_margem (+ IVEC já calculado, sem recalcular economia).
 */
function vbeRenderResumoExecutivoMargem(painel, opts){
  opts=opts||{};
  if(!painel){
    return '<div class="vbe-resumo-exec"><div class="vbe-vazio">'
      +(opts.msgVazio||'Não foi possível consolidar os dados deste contrato.')
      +'</div></div>';
  }
  var rec=painel.receita||{};
  var avisoReceita='';
  if(rec.liquida==null || Number(rec.liquida)===0){
    avisoReceita='<div class="vbe-vazio" style="padding:.7rem;margin-bottom:10px">Não há dados suficientes para calcular a margem realizada (receita líquida zerada ou inexistente nesta competência).</div>';
  }
  return '<div class="vbe-resumo-exec" id="vbe-resumo-executivo">'
    +vbeHtmlCabecalhoResumoMargem(painel)
    +avisoReceita
    +vbeHtmlCardsPrincipaisMargem(painel)
    +vbeHtmlCardsSecundariosMargem(painel)
    +vbeHtmlComparativoCenarios(painel)
    +vbeHtmlQualidadePainel(painel)
    +vbeHtmlPendenciasPainel(painel)
    +vbeHtmlAlertasPainel(painel)
    +vbeHtmlIvecComplementar({ivec:opts.ivec, confianca:opts.confianca})
    +'</div>';
}

function vbeRenderResultadoBody(cid,comp,wrap){
  wrap=wrap||document.getElementById('vbe-resultado-wrap'); if(!wrap) return;
  if(!cid){
    wrap.innerHTML='<div class="vbe-vazio">Selecione um contrato e uma competência para visualizar a margem.</div>';
    return;
  }
  var a=vbeAnalisarContrato(cid,comp);
  if(!a){ wrap.innerHTML='<div class="vbe-vazio">Sem dados para análise. Sincronize operação (ERP) ou cadastre premissas.</div>'; return; }
  var r=a.resultado, iv=a.ivec, cap=a.capacidade;
  var prev=r.previsto||r, real=r.realizado||r;
  var prod=r.produtividade||{};
  var painel=a.painel_margem||null;
  var resumoHtml='';
  var dreViabHtml='';
  var dreGerHtml='';
  var cenariosDHtml='';
  var conciliacaoHtml='';
  try{
    var dreViab=vbeMontarDreViabilidade(cid,comp);
    dreViabHtml=vbeHtmlDreViabilidade(dreViab);
  }catch(eViab){
    console.warn('[VBE] DRE da Viabilidade',eViab);
    dreViabHtml='';
  }
  try{
    resumoHtml=vbeRenderResumoExecutivoMargem(painel,{ivec:iv,confianca:a.nivel_confianca});
  }catch(eResumo){
    console.warn('[VBE] resumo executivo',eResumo);
    resumoHtml='<div class="vbe-vazio">Não foi possível consolidar os dados deste contrato.</div>';
  }
  try{
    dreGerHtml=vbeRenderDreGerencialPainel(painel);
  }catch(eDre){
    console.warn('[VBE] DRE gerencial render',eDre);
    dreGerHtml='';
  }
  try{
    cenariosDHtml=vbeRenderComparativoCenariosPainel(painel);
  }catch(eCen){
    console.warn('[VBE] cenários Etapa D',eCen);
    cenariosDHtml='';
  }
  try{
    conciliacaoHtml=vbeHtmlConciliacaoDrePainel(painel&&painel.conciliacao);
  }catch(eConc){
    console.warn('[VBE] conciliação',eConc);
    conciliacaoHtml='';
  }
  var delta=r.delta_faturamento||0;
  var deltaCor=delta>=0?'#3B6D11':'#A32D2D';
  var dRes=r.delta_resultado||0;
  var dResCor=dRes>=0?'#3B6D11':'#A32D2D';
  var serieHtml='';
  try{serieHtml=vbeSerieMensalHtml(cid,6);}catch(eSer){console.warn('[VBE] série',eSer);}
  function dreLinhasDespesa(bloco){
    var desp=(bloco&&bloco.despesas)||(bloco&&bloco.despesas_detalhe&&bloco.despesas_detalhe.despesas)||null;
    // Etapa F: detalhe expansível por grupo quando estrutura gerencial existe
    if(desp&&Number(desp.custo_total||0)>0.005&&typeof vbeHtmlDespesasDreExpansivel==='function'){
      var legadoHint='';
      if(bloco.folha_operacional!=null){
        legadoHint='<tr style="color:#888;font-size:10px"><td style="padding:4px 1rem" colspan="2">'
          +'Razão legada: folha op. '+vbeFmtValor(bloco.folha_operacional||0)
          +' · BO '+vbeFmtValor(bloco.folha_backoffice||0)
          +' · comb. '+vbeFmtValor(bloco.combustivel||0)
          +' · loc. '+vbeFmtValor(bloco.locacao||0)
          +' · manut. '+vbeFmtValor(bloco.manutencao_frota||0)
          +(Number(bloco.outras_despesas||0)>0.005?' · outras '+vbeFmtValor(bloco.outras_despesas):'')
          +'</td></tr>';
      }
      return vbeHtmlDespesasDreExpansivel(desp)+legadoHint;
    }
    if(bloco.folha_operacional!=null||bloco.despesas_detalhe){
      var outras=Number(bloco.outras_despesas||0);
      if(outras<0.005&&bloco.custo_total!=null){
        var cinco=(Number(bloco.folha_operacional||0)+Number(bloco.folha_backoffice||0)+Number(bloco.combustivel||0)+Number(bloco.locacao||0)+Number(bloco.manutencao_frota||0));
        outras=Math.max(0,Number(bloco.custo_total||0)-cinco);
      }
      return vbeDreRow('(−) Folha operacional',vbeFmtValor(bloco.folha_operacional||0))
        +vbeDreRow('(−) Folha backoffice',vbeFmtValor(bloco.folha_backoffice||0))
        +vbeDreRow('(−) Combustível',vbeFmtValor(bloco.combustivel||0))
        +vbeDreRow('(−) Locação total',vbeFmtValor(bloco.locacao||0))
        +vbeDreRow('(−) Manutenção frota',vbeFmtValor(bloco.manutencao_frota||0))
        +(outras>0.005?vbeDreRow('(−) Outras despesas',vbeFmtValor(outras)):'');
    }
    return vbeDreRow('(−) Custo direto',vbeFmtValor(bloco.custo_direto))
      +vbeDreRow('(−) Custo indireto',vbeFmtValor(bloco.custo_indireto));
  }
  function dreCard(titulo, bloco, corBorda, fonteTxt){
    var desp=(bloco&&bloco.despesas)||(bloco&&bloco.despesas_detalhe&&bloco.despesas_detalhe.despesas)||null;
    var cardsGrp=(vbePodeVerFinanceiro()&&typeof vbeHtmlCardsGruposDespesa==='function')?vbeHtmlCardsGruposDespesa(desp):'';
    return '<div class="card" style="margin:0;border-left:4px solid '+corBorda+'">'
      +'<div class="ch"><span class="ct">'+titulo+'</span>'
      +'<span style="font-size:10px;color:#888">'+escHtml(fonteTxt||'')+'</span></div>'
      +'<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px;padding:.5rem .75rem">'
      +vbeMetricCard('Receita bruta',vbeFmtValor(bloco.receita_bruta),'#185FA5')
      +vbeMetricCard('Impostos s/ fat.',vbeFmtValor(bloco.impostos_faturamento||0),'#534AB7')
      +vbeMetricCard('Resultado líquido',vbeFmtValor(bloco.resultado_mensal),(bloco.resultado_mensal>=0?'#085041':'#A32D2D'))
      +vbeMetricCard('Margem op.',vbeFmtPct(bloco.margem_operacional_percentual),'#3B6D11')
      +'</div>'
      +cardsGrp
      +'<table class="tbl" style="margin:0"><tbody>'
      +vbeDreRow('Receita bruta',vbeFmtValor(bloco.receita_bruta))
      +vbeDreRow('(−) Impostos s/ faturamento ('+escHtml(bloco.regime_label||'')+' · '+vbeFmtNum(bloco.carga_fat_pct||0,2)+'%)',vbeFmtValor(bloco.impostos_faturamento||0))
      +vbeDreRow('= Receita após impostos',vbeFmtValor(bloco.receita_liquida),true)
      +dreLinhasDespesa(bloco)
      +vbeDreRow('= Resultado antes IR/CSLL',vbeFmtValor(bloco.resultado_antes_ir!=null?bloco.resultado_antes_ir:bloco.resultado_mensal))
      +vbeDreRow('(−) IRPJ/CSLL',vbeFmtValor(bloco.irpj_csll||0))
      +vbeDreRow('= Resultado líquido',vbeFmtValor(bloco.resultado_mensal),true)
      +'<tr style="color:#888;font-size:11px"><td style="padding:6px 1rem" colspan="2">Retenção/glosa '
      +vbeFmtValor(bloco.retencao_glosa!=null?bloco.retencao_glosa:0)
      +' — informativo (não abate o lucro nem a base de IR; retenção é receita futura)</td></tr>'
      +'</tbody></table></div>';
  }
  var trib=vbeTributacaoDePremissas(a.premissas||{});
  var ymRef=String(comp||'').slice(0,7);
  var fontePrev='Receita: Premissas · Folha: Premissas/grade · Comb/Manut/Frota: real do mês (sem premissa) · Locação: Locações/ERP · '+trib.label;
  var fonteReal='Receita: Financeiro (Faturado) · Despesas: lançamentos Pago (+ parcial) + combustível + frota + Locações · Aprovado=comprometido · '+trib.label;
  var compTot=Number(r.custo_comprometido||(r.comprometido&&r.comprometido.custo_total)||0);
  var cam=r.camadas||(r.comprometido&&r.comprometido.camadas)||null;
  var faixaComp='';
  if(vbePodeVerFinanceiro()&&compTot>0.005){
    faixaComp='<div style="padding:.65rem 1rem;margin-bottom:1rem;font-size:11px;color:#854F0B;background:#FAEEDA;border-radius:8px;border:.5px solid #E8D4B8">'
      +'<b>Comprometido (não abate o lucro)</b> — Lançado / Em análise / Aprovado'
      +(cam&&cam.qtd_parcial?' · saldo de Pago parcial':'')
      +': <b>'+vbeFmtValor(compTot)+'</b>'
      +(cam?(
        (cam.qtd_aprovado?' · '+cam.qtd_aprovado+' aprovado(s)':'')
        +(cam.qtd_em_analise?' · '+cam.qtd_em_analise+' em análise':'')
        +(cam.qtd_lancado?' · '+cam.qtd_lancado+' lançado(s)':'')
        +(cam.qtd_parcial?' · '+cam.qtd_parcial+' parcial(is)':'')
        +(cam.qtd_parcial_sem_valor_pago?' · '+cam.qtd_parcial_sem_valor_pago+' parcial sem valor_pago (usou total)':'')
      ):'')
      +' · se baixasse: resultado ≈ '+vbeFmtValor((r.comprometido&&r.comprometido.resultado_se_baixado)!=null?r.comprometido.resultado_se_baixado:((real.resultado_mensal||0)-compTot))
      +'</div>';
  }
  var faixaDiag='';
  try{
    if(vbePodeVerFinanceiro()&&typeof vbeHtmlDiagnosticoDespesas==='function'){
      faixaDiag=vbeHtmlDiagnosticoDespesas(r.diagnostico||(real.despesas_detalhe&&real.despesas_detalhe.diagnostico)||null);
    }
  }catch(eDiag){console.warn('[VBE] diagnostico',eDiag);}
  if(faixaDiag){
    faixaDiag='<div id="vbe-diag-despesas">'+faixaDiag+'</div>';
  } else {
    faixaDiag='<div id="vbe-diag-despesas"></div>';
  }
  wrap.innerHTML=dreViabHtml
    +resumoHtml
    +dreGerHtml
    +cenariosDHtml
    +conciliacaoHtml
    +'<div class="vbe-legado-sep" id="vbe-resultado-legado">Detalhamento legado (DRE, simulação e série)</div>'
    +'<div style="padding:.65rem 1rem;margin-bottom:1rem;font-size:11px;color:#185FA5;background:#EBF4FD;border-radius:8px">'
      +'<b>Comparativo coerente</b> — <b>Previsto</b> (Premissas) · <b>Realizado</b> (Pago / parcial pago) · <b>Comprometido</b> (Aprovado e pendentes, informativo).'
      +' · Fat. previsto '+vbeFmtValor(r.faturamento_esperado_premissa)
      +' · Fat. realizado '+vbeFmtValor(r.faturamento_realizado)
      +' · Δ fat. <span style="color:'+deltaCor+';font-weight:600">'+(delta>=0?'+':'')+vbeFmtValor(delta)+'</span>'
      +' · Δ resultado <span style="color:'+dResCor+';font-weight:600">'+(dRes>=0?'+':'')+vbeFmtValor(dRes)+'</span>'
      +(prod.qtd_medicoes?' · '+prod.qtd_medicoes+' medição(ões)':'')
      +'</div>'
    +faixaComp
    +faixaDiag
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-bottom:1rem">'
    +dreCard('Previsto Mês — '+ymRef, prev, '#185FA5', fontePrev)
    +dreCard('Realizado Mês — '+ymRef, real, '#085041', fonteReal)
    +'</div>'
    +(vbePodeVerFinanceiro()?vbeHtmlSimulacaoReceitaResultado(a,prev,real,comp):'')
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:1rem">'
    +vbeMetricCard('ICO',cap.ico_score,vbeClassCorIco(cap.ico_score))
    +vbeMetricCard('Ponto eq. (previsto)',vbeFmtValor(prev.ponto_equilibrio),'#555')
    +vbeMetricCard('Ponto eq. (real)',vbeFmtValor(real.ponto_equilibrio),'#555')
    +vbeMetricCard('Receita/eq. (prev.)',vbeFmtValor(prev.receita_por_equipe),'#555')
    +vbeMetricCard('Custo/eq. (prev.)',vbeFmtValor(prev.custo_por_equipe),'#555')
    +vbeMetricCard('Δ custo R×P',vbeFmtValor(r.delta_custo||0),((r.delta_custo||0)>0?'#A32D2D':'#3B6D11'))
    +'</div>'
    +serieHtml;
  if(vbePodeVerFinanceiro()) setTimeout(vbeBindSimulacaoReceitaResultado, 30);
}

/** Painel what-if: altera faturamento; despesas previstas ficam na mesma razão (Folha/Comb/Loc/Manut). */
var _vbeResSimCtx=null;
function vbeHtmlSimulacaoReceitaResultado(a, prev, real, comp){
  var p=a.premissas||{};
  var ret=Number(p.retencao_percentual||0)/100;
  var glosa=Number(p.glosa_media_percentual||0)/100;
  var eqEnt=Number(p.equipes_entregues_media||0)||Number(p.equipes_alvo||0)||1;
  var trib=vbeTributacaoDePremissas(p);
  var baseKey='prev'; // simulação usa despesas previstas; só muda faturamento
  var base=prev||{};
  var recIni=Number(base.receita_bruta||0)||0;
  function packDesp(b){
    var fo=Number(b.folha_operacional||0), fbo=Number(b.folha_backoffice||0);
    var cb=Number(b.combustivel||0), loc=Number(b.locacao||0), man=Number(b.manutencao_frota||0);
    var ct=Number(b.custo_total||0);
    var cinco=fo+fbo+cb+loc+man;
    var outras=Number(b.outras_despesas||0);
    if(outras<0.005 && ct>0) outras=Math.max(0, Math.round((ct-cinco)*100)/100);
    return {
      folha_operacional:fo, folha_backoffice:fbo, combustivel:cb, locacao:loc, manutencao_frota:man,
      outras_despesas:outras,
      custo_direto:Number(b.custo_direto||0),
      custo_indireto:Number(b.custo_indireto||0),
      custo_total:ct>0?ct:Math.round((cinco+outras)*100)/100
    };
  }
  var despPrev=packDesp(prev||{});
  var despReal=packDesp(real||{});
  _vbeResSimCtx={
    ret:ret, glosa:glosa, eqEnt:eqEnt, iss:trib.iss,
    regime_salvo:trib.regime,
    prev:{receita:Number(prev.receita_bruta||0), desp:despPrev},
    real:{receita:Number(real.receita_bruta||0), desp:despReal},
    base:baseKey,
    receita_base:recIni,
    desp:despPrev
  };
  var fmt=(typeof vbeFmtMoedaInput==='function')?vbeFmtMoedaInput:function(v){return String(v||0);};
  var d=despPrev;
  return '<div class="card" style="margin-bottom:1rem;border-left:4px solid #534AB7">'
    +'<div class="ch"><span class="ct">Simular faturamento</span>'
    +'<span style="font-size:10px;color:#888">What-if · despesas previstas fixas · '+escHtml(String(comp||'').slice(0,7))+'</span></div>'
    +'<div style="padding:.65rem 1rem;font-size:11px;color:#555;background:#F0EEFF;margin:0 1rem;border-radius:8px">'
    +'Altere só a <b>receita bruta</b>. Despesas: Folha op + Folha BO + Combustível + Locação + Manutenção + <b>Outras</b> (materiais, admin. e demais lançamentos do Financeiro que entram no custo total). '
    +'Retenção <b>não abate</b> o resultado (receita futura). Para gravar bases: '
    +'<button type="button" class="btn btn-sm" style="font-size:10px;padding:2px 8px" onclick="vbeMostrarAba(\'premissas\')">Premissas →</button>'
    +'</div>'
    +'<div style="padding:1rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;align-items:end">'
    +'<div class="fg"><label style="font-size:11px;font-weight:600">Receita bruta simulada (R$)</label>'
    +'<input class="inp" id="vbe-res-sim-rec" style="width:100%;font-weight:700;font-size:15px;color:#185FA5" value="'+escHtml(fmt(recIni))+'"/></div>'
    +'<div class="fg"><label style="font-size:11px;font-weight:600">Regime tributário</label>'
    +'<select class="inp" id="vbe-res-sim-regime" style="width:100%" data-nosort="1">'
    +'<option value="presumido"'+(trib.regime==='presumido'?' selected':'')+'>Lucro Presumido</option>'
    +'<option value="real"'+(trib.regime==='real'?' selected':'')+'>Lucro Real</option>'
    +'</select></div>'
    +'<div class="fg"><label style="font-size:11px;font-weight:600">Base da receita</label>'
    +'<select class="inp" id="vbe-res-sim-base" style="width:100%" data-nosort="1">'
    +'<option value="prev" selected>Receita prevista</option>'
    +'<option value="real">Receita realizada</option>'
    +'</select></div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:end">'
    +'<button type="button" class="btn btn-sm" onclick="vbeResSimUsar(\'prev\')">Usar previsto</button>'
    +'<button type="button" class="btn btn-sm" onclick="vbeResSimUsar(\'real\')">Usar realizado</button>'
    +'<button type="button" class="btn btn-sm" onclick="vbeResSimUsar(\'base\')">Reset</button>'
    +'</div></div>'
    +'<div style="padding:0 1rem .75rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:6px;font-size:11px;color:#555">'
    +'<div>Folha op: <b>'+vbeFmtValor(d.folha_operacional)+'</b></div>'
    +'<div>Folha BO: <b>'+vbeFmtValor(d.folha_backoffice)+'</b></div>'
    +'<div>Combustível: <b>'+vbeFmtValor(d.combustivel)+'</b></div>'
    +'<div>Locação: <b>'+vbeFmtValor(d.locacao)+'</b></div>'
    +'<div>Manutenção: <b>'+vbeFmtValor(d.manutencao_frota)+'</b></div>'
    +'<div>Outras: <b>'+vbeFmtValor(d.outras_despesas)+'</b></div>'
    +'<div>Total desp.: <b style="color:#854F0B">'+vbeFmtValor(d.custo_total)+'</b></div>'
    +'</div>'
    +'<div id="vbe-res-sim-out" style="padding:0 1rem 1rem"></div>'
    +'<div style="font-size:10px;color:#888;padding:0 1rem 1rem">Somente simulação — não grava. Retenção '
    +vbeFmtNum((ret||0)*100,2)+'% · glosa '+vbeFmtNum((glosa||0)*100,2)+'% (informativo) · ISS '+vbeFmtNum(trib.iss,2)+'%.</div></div>';
}
function vbeResSimParseMoeda(el){
  if(!el) return 0;
  if(typeof vbeParseMoeda==='function') return vbeParseMoeda(el.value)||0;
  return parseFloat(String(el.value||'0').replace(/\./g,'').replace(',','.'))||0;
}
function vbeResSimUsar(modo){
  if(!_vbeResSimCtx) return;
  var src=modo==='real'?_vbeResSimCtx.real:(modo==='prev'?_vbeResSimCtx.prev:null);
  var rec;
  if(src){ rec=src.receita; }
  else { rec=_vbeResSimCtx.receita_base; }
  // Despesas sempre as previstas (razão oficial da simulação)
  _vbeResSimCtx.desp=_vbeResSimCtx.prev.desp;
  var fmt=(typeof vbeFmtMoedaInput==='function')?vbeFmtMoedaInput:String;
  var elR=document.getElementById('vbe-res-sim-rec');
  var selB=document.getElementById('vbe-res-sim-base');
  if(elR) elR.value=fmt(rec);
  if(selB && (modo==='prev'||modo==='real')) selB.value=modo;
  vbeAtualizarSimulacaoReceitaResultado();
}
function vbeResSimUsarRegime(modo){
  if(!_vbeResSimCtx) return;
  var sel=document.getElementById('vbe-res-sim-regime'); if(!sel) return;
  if(modo==='salvo') sel.value=_vbeResSimCtx.regime_salvo||'presumido';
  else sel.value=modo;
  vbeAtualizarSimulacaoReceitaResultado();
}
function vbeBindSimulacaoReceitaResultado(){
  function bindMoeda(id){
    var el=document.getElementById(id); if(!el) return;
    el.oninput=function(){ vbeAtualizarSimulacaoReceitaResultado(); };
    el.onchange=function(){
      var n=vbeResSimParseMoeda(el);
      if(typeof vbeFmtMoedaInput==='function') el.value=vbeFmtMoedaInput(n);
      vbeAtualizarSimulacaoReceitaResultado();
    };
  }
  bindMoeda('vbe-res-sim-rec');
  var selR=document.getElementById('vbe-res-sim-regime');
  var selB=document.getElementById('vbe-res-sim-base');
  if(selR) selR.onchange=function(){ vbeAtualizarSimulacaoReceitaResultado(); };
  if(selB) selB.onchange=function(){
    if(_vbeResSimCtx) _vbeResSimCtx.base=selB.value||'prev';
    vbeResSimUsar(selB.value||'prev');
  };
  vbeAtualizarSimulacaoReceitaResultado();
}
function vbeAtualizarSimulacaoReceitaResultado(){
  var out=document.getElementById('vbe-res-sim-out'); if(!out||!_vbeResSimCtx) return;
  var selR=document.getElementById('vbe-res-sim-regime');
  var rec=vbeResSimParseMoeda(document.getElementById('vbe-res-sim-rec'));
  var desp=_vbeResSimCtx.desp||_vbeResSimCtx.prev.desp||{};
  var regime=(selR&&selR.value)||_vbeResSimCtx.regime_salvo||'presumido';
  var trib=vbeAliquotasRegime(regime, _vbeResSimCtx.iss);
  var dre=vbeMontarDreBloco(rec, desp.custo_direto, desp.custo_indireto, _vbeResSimCtx.ret, _vbeResSimCtx.glosa, _vbeResSimCtx.eqEnt, trib, desp);
  var baseRec=_vbeResSimCtx.receita_base||0;
  var baseDesp=_vbeResSimCtx.prev.desp||desp;
  var baseDre=vbeMontarDreBloco(baseRec, baseDesp.custo_direto, baseDesp.custo_indireto, _vbeResSimCtx.ret, _vbeResSimCtx.glosa, _vbeResSimCtx.eqEnt, vbeAliquotasRegime(_vbeResSimCtx.regime_salvo, _vbeResSimCtx.iss), baseDesp);
  var dRes=dre.resultado_mensal-baseDre.resultado_mensal;
  var dRec=rec-baseRec;
  // Outras = custo_total − (5 linhas clássicas); era abatido no resultado sem aparecer na tabela
  var cincoVis=(Number(dre.folha_operacional||0)+Number(dre.folha_backoffice||0)+Number(dre.combustivel||0)+Number(dre.locacao||0)+Number(dre.manutencao_frota||0));
  var outrasVis=Number(dre.outras_despesas||0);
  if(outrasVis<0.005) outrasVis=Math.max(0, Math.round((Number(dre.custo_total||0)-cincoVis)*100)/100);
  // Caixa: resultado líquido contábil − retenção/glosa (retenção continua fora do lucro contábil)
  var retGlosaAmt=Number(dre.retencao_glosa||0)||0;
  var resultadoCaixa=Math.round((Number(dre.resultado_mensal||0)-retGlosaAmt)*100)/100;
  var retPct=((Number(_vbeResSimCtx.ret||0)+Number(_vbeResSimCtx.glosa||0))*100);
  var corCaixa=resultadoCaixa>=0?'#085041':'#A32D2D';
  out.innerHTML='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;margin-bottom:.75rem">'
    +vbeMetricCard('Receita bruta',vbeFmtValor(dre.receita_bruta),'#185FA5')
    +vbeMetricCard('Impostos s/ fat.',vbeFmtValor(dre.impostos_faturamento),'#534AB7')
    +vbeMetricCard('Despesas',vbeFmtValor(dre.custo_total),'#854F0B')
    +vbeMetricCard('IRPJ/CSLL',vbeFmtValor(dre.irpj_csll),'#854F0B')
    +vbeMetricCard('Resultado líquido',vbeFmtValor(dre.resultado_mensal),(dre.resultado_mensal>=0?'#085041':'#A32D2D'))
    +vbeMetricCard('Resultado caixa (após retenção)',vbeFmtValor(resultadoCaixa),corCaixa)
    +'</div>'
    +'<table class="tbl" style="margin:0"><tbody>'
    +vbeDreRow('Receita bruta',vbeFmtValor(dre.receita_bruta))
    +vbeDreRow('(−) ISS '+vbeFmtNum(trib.iss,2)+'%',vbeFmtValor(dre.impostos_iss))
    +vbeDreRow('(−) PIS '+vbeFmtNum(trib.pis,2)+'%',vbeFmtValor(dre.impostos_pis))
    +vbeDreRow('(−) COFINS '+vbeFmtNum(trib.cofins,2)+'%',vbeFmtValor(dre.impostos_cofins))
    +vbeDreRow('= Receita após impostos',vbeFmtValor(dre.receita_liquida),true)
    +vbeDreRow('(−) Folha operacional',vbeFmtValor(dre.folha_operacional||0))
    +vbeDreRow('(−) Folha backoffice',vbeFmtValor(dre.folha_backoffice||0))
    +vbeDreRow('(−) Combustível',vbeFmtValor(dre.combustivel||0))
    +vbeDreRow('(−) Locação total',vbeFmtValor(dre.locacao||0))
    +vbeDreRow('(−) Manutenção frota',vbeFmtValor(dre.manutencao_frota||0))
    +(outrasVis>0.005?vbeDreRow('(−) Outras despesas (materiais, admin., demais lançamentos)',vbeFmtValor(outrasVis)):'')
    +vbeDreRow('= Resultado antes IR/CSLL',vbeFmtValor(dre.resultado_antes_ir))
    +vbeDreRow('(−) IRPJ/CSLL ('+escHtml(trib.label)+')',vbeFmtValor(dre.irpj_csll))
    +vbeDreRow('= Resultado líquido simulado',vbeFmtValor(dre.resultado_mensal),true)
    +vbeDreRow('(−) Retenção/glosa ('+vbeFmtNum(retPct,2)+'% da receita bruta)',vbeFmtValor(retGlosaAmt))
    +'<tr style="font-weight:700;background:'+(resultadoCaixa<0?'#FCEBEB':'#EAF3DE')+'">'
    +'<td style="padding:10px 1rem;color:'+corCaixa+'">= Resultado de caixa (após retenção)</td>'
    +'<td style="text-align:right;padding:10px 1rem;color:'+corCaixa+';font-size:15px">'+vbeFmtValor(resultadoCaixa)+'</td></tr>'
    +'<tr style="color:#888;font-size:11px"><td style="padding:6px 1rem" colspan="2">'
    +'O resultado líquido é contábil (retenção não abate o lucro — é receita futura). '
    +'O <b>resultado de caixa</b> mostra o efeito imediato se a retenção/glosa for retida no mês'
    +(resultadoCaixa<0?' — <span style="color:#A32D2D">caixa negativo neste cenário</span>':'')
    +'.</td></tr>'
    +'</tbody></table>'
    +'<div style="font-size:11px;color:#555;margin-top:8px">Δ receita vs base: <b style="color:'+(dRec>=0?'#3B6D11':'#A32D2D')+'">'+(dRec>=0?'+':'')+vbeFmtValor(dRec)+'</b>'
    +' · Δ resultado líquido vs base: <b style="color:'+(dRes>=0?'#3B6D11':'#A32D2D')+'">'+(dRes>=0?'+':'')+vbeFmtValor(dRes)+'</b>'
    +' · carga s/ fat. <b>'+vbeFmtNum(trib.carga_fat_pct,2)+'%</b>'
    +' · ponto de equilíbrio: <b>'+vbeFmtValor(dre.ponto_equilibrio)+'</b></div>';
}

function vbeDreRow(l,v,bold){
  return '<tr'+(bold?' style="font-weight:700;background:#f9f9f7"':'')+'><td style="padding:8px 1rem">'+l+'</td><td style="text-align:right;padding:8px 1rem">'+v+'</td></tr>';
}

function vbeRenderProdutividade(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  var comp=_vbeCompetencia||vbeGetCompSel();
  var wrap=document.getElementById('vbe-produtividade-wrap'); if(!wrap) return;
  if(!cid){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">Selecione um contrato no filtro superior.</div>';
    return;
  }
  var prod=vbeColetarDadosProdutividade(cid,comp);
  var porEq=vbeProdutividadePorEquipe(cid,comp);
  var delta=(prod.faturamento_efetivo||0)-(prod.prod_prevista||prod.meta_prod||0);
  var deltaCor=delta>=0?'#3B6D11':'#A32D2D';
  var atingMeta=prod.meta_prod>0?Math.round((prod.prod_realizada/prod.meta_prod)*1000)/10:null;
  var html='';
  html+='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:1rem">'
    +'<button class="btn btn-sm" onclick="vbeSincronizarFaturamentoERP();setTimeout(function(){vbeMostrarAba(\'premissas\');},300)">↻ Sincronizar → Premissas</button>'
    +'<button class="btn btn-sm" onclick="showMain(\'movimentacao\');setTimeout(function(){showSub(\'metas\');},200)">Abrir Metas / Realizado</button>'
    +'</div>';
  html+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;margin-bottom:1rem">';
  html+=[
    {l:'Meta produtividade',v:vbeFmtValor(prod.meta_prod),c:'#185FA5'},
    {l:'Previsto',v:vbeFmtValor(prod.prod_prevista),c:'#555'},
    {l:'Realizado',v:vbeFmtValor(prod.prod_realizada),c:atingMeta!=null&&atingMeta>=90?'#3B6D11':'#854F0B'},
    {l:'Faturado',v:vbeFmtValor(prod.valor_faturado),c:'#3B6D11'},
    {l:'Oportunidade',v:vbeFmtValor(prod.receita_oportunidade),c:'#534AB7'},
    {l:'Total receita',v:vbeFmtValor(prod.receita_total),c:'#085041'},
    {l:'Fat. financeiro',v:vbeFmtValor(prod.faturamento_financeiro_bruto),c:'#185FA5'},
    {l:'Fat. efetivo (DRE)',v:vbeFmtValor(prod.faturamento_efetivo),c:'#085041'}
  ].map(function(m){return vbeMetricCard(m.l,m.v,m.c);}).join('');
  html+='</div>';
  html+='<div style="padding:.65rem 1rem;margin-bottom:1rem;font-size:11px;color:#185FA5;background:#EBF4FD;border-radius:8px">'
    +'Fonte do faturamento efetivo: <strong>'+escHtml(vbeLabelFonteFat(prod.fonte_faturamento))+'</strong>'
    +' · '+comp.slice(0,7)
    +(prod.execucoes_mes?' · '+prod.execucoes_mes+' execução(ões) de obra':'')
    +(prod.prod_diaria_rows?' · '+prod.prod_diaria_rows+' registro(s) produção diária ('+prod.prod_diaria.dias+' dias)':'')
    +(delta?(' · delta previsto/realizado <span style="color:'+deltaCor+'">'+(delta>=0?'+':'')+vbeFmtValor(delta)+'</span>'):'')
    +'</div>';
  if(!prod.tem_dados){
    html+='<div class="card" style="padding:2rem;text-align:center;color:#888;margin-bottom:1rem">'
      +'Sem dados de produtividade/faturamento no ERP para esta competência.<br>'
      +'<span style="font-size:11px">Lance em Metas/Realizado, registre medições faturadas ou faturamentos financeiros.</span></div>';
  }
  html+='<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">Produtividade por equipe — '+comp.slice(0,7)+'</span></div>';
  if(!porEq.length){
    html+='<div style="padding:1.5rem;text-align:center;color:#888">Nenhuma equipe vinculada ao contrato.</div>';
  } else {
    html+='<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>Equipe</th><th>Módulo</th><th>Dias</th><th>Meta (COD X)</th><th>Prod. real.</th><th>% meta</th><th>Ordens</th><th>Status</th>'
      +'</tr></thead><tbody>';
    porEq.forEach(function(row){
      html+='<tr><td><strong>'+escHtml(row.equipe.nome)+'</strong></td><td style="font-size:11px">'+escHtml(row.equipe.modulo)+'</td>'
        +'<td style="text-align:center">'+row.dias_trabalhados+'</td>'
        +'<td style="text-align:right">'+vbeFmtValor(row.meta)+'</td>'
        +'<td style="text-align:right">'+vbeFmtValor(row.prod_realizada)+'</td>'
        +'<td style="text-align:center">'+(row.pct_meta!=null?row.pct_meta+'%':'—')+'</td>'
        +'<td style="text-align:center">'+row.ordens+'</td>'
        +'<td><span class="bdg" style="background:'+row.status_cor+'22;color:'+row.status_cor+'">'+escHtml(row.status)+'</span></td></tr>';
    });
    html+='</tbody></table></div>';
  }
  html+='</div>';
  if(prod.medicoes_faturadas.length){
    html+='<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">Medições faturadas ('+prod.medicoes_faturadas.length+')</span></div>'
      +'<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>Título</th><th>Faturado em</th><th style="text-align:right">Valor</th><th>NF</th>'
      +'</tr></thead><tbody>';
    prod.medicoes_faturadas.forEach(function(m){
      html+='<tr><td>'+escHtml(m.titulo||m.tipo||'—')+'</td><td style="font-size:11px">'+fmtD(m.faturado_em)+'</td>'
        +'<td style="text-align:right">'+vbeFmtValor(m.total_medido)+'</td><td style="font-size:11px">'+escHtml(m.nf_numero||'—')+'</td></tr>';
    });
    html+='</tbody></table></div></div>';
  }
  if(prod.faturamentos_financeiro.length){
    html+='<div class="card"><div class="ch"><span class="ct">Faturamentos financeiros ('+prod.faturamentos_financeiro.length+')</span></div>'
      +'<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>Emissão</th><th>Tipo</th><th>Status</th><th style="text-align:right">Bruto</th><th style="text-align:right">Líquido</th>'
      +'</tr></thead><tbody>';
    prod.faturamentos_financeiro.forEach(function(f){
      html+='<tr><td style="font-size:11px">'+fmtD(f.data_emissao)+'</td><td>'+escHtml(f.tipo||'—')+'</td>'
        +'<td><span class="bdg gray">'+escHtml(f.status||'—')+'</span></td>'
        +'<td style="text-align:right">'+vbeFmtValor(f.valor_bruto)+'</td>'
        +'<td style="text-align:right">'+vbeFmtValor(f.valor_liquido)+'</td></tr>';
    });
    html+='</tbody></table></div></div>';
  }
  html+='<div style="font-size:11px;color:#888;margin-top:8px">Fase 3: dados de produtividade, medições faturadas, produção diária e financeiro (últimos 90 dias carregados no login lazy).</div>';
  wrap.innerHTML=html;
}

function vbeRenderEstrutura(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  var wrap=document.getElementById('vbe-estrutura-wrap'); if(!wrap) return;
  if(!cid){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">Selecione um contrato no filtro superior.</div>';
    return;
  }
  var comp=_vbeCompetencia||vbeGetCompSel();
  var ops=vbeColetarDadosOperacionais(cid,comp);
  var tipos=(vbeTiposEquipe||[]).filter(function(t){return t.contrato_id===cid&&t.ativo!==false;});
  var html='';
  html+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;margin-bottom:1rem">';
  html+=[{l:'Equipes',v:ops.equipes_cadastradas,c:'#185FA5'},{l:'Colaboradores',v:ops.colaboradores_disponiveis,c:'#3B6D11'},
    {l:'Veículos',v:ops.veiculos_disponiveis,c:'#854F0B'},{l:'Média eq./dia',v:ops.equipes_entregues_media!=null?ops.equipes_entregues_media:'—',c:'#555'},
    {l:'Dias c/ programação',v:ops.dias_composicao,c:'#555'}].map(function(m){return vbeMetricCard(m.l,m.v,m.c);}).join('');
  html+='</div>';
  if(ops.veiculos_por_tipo&&ops.veiculos_por_tipo.itens&&ops.veiculos_por_tipo.itens.length){
    html+='<div class="card" style="margin-bottom:1rem;padding:1rem"><div style="font-size:12px;font-weight:600;margin-bottom:8px">Veículos por tipo operacional</div>'
      +vbeHtmlVeiculosPorTipo(cid)+'</div>';
  }
  html+='<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">Equipes vinculadas (ERP)</span>'
    +'<button class="btn btn-sm" onclick="vbeSincronizarOperacionalERP();setTimeout(function(){vbeMostrarAba(\'premissas\');},300)">↻ Sincronizar → Premissas</button></div>';
  if(!ops.equipes.length){
    html+='<div style="padding:1.5rem;text-align:center;color:#888">Nenhuma equipe PLPT ou TMA vinculada a este contrato.</div>';
  } else {
    html+='<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>Equipe</th><th>Módulo</th><th>Tipo</th><th>Colaboradores</th><th>Veículo</th><th>Supervisor</th>'
      +'</tr></thead><tbody>';
    ops.equipes.forEach(function(e){
      html+='<tr><td><strong>'+escHtml(e.nome)+'</strong></td><td>'+escHtml(e.modulo)+'</td><td>'+escHtml(e.tipo)+'</td>'
        +'<td style="text-align:center">'+e.qtd_colaboradores+'</td><td>'+escHtml(e.veiculo||'—')+'</td><td style="font-size:11px">'+escHtml(e.supervisor)+'</td></tr>';
    });
    html+='</tbody></table></div>';
  }
  html+='</div>';
  html+='<div class="card"><div class="ch"><span class="ct">Premissas por tipo de equipe</span>'
    +'<div style="display:flex;gap:6px"><button class="btn btn-sm" onclick="vbeImportarTiposDoERP()">↻ Importar tipos do ERP</button>'
    +'<button class="btn btn-pri btn-sm" onclick="vbeOpenModalTipoEq()">+ Tipo de equipe</button></div></div>';
  if(!tipos.length){
    html+='<div style="padding:1.5rem;text-align:center;color:#888">Nenhuma premissa por tipo cadastrada. Importe do ERP ou adicione manualmente.</div>';
  } else {
    html+='<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>Tipo</th><th>Composição</th><th>Colab.</th><th>Veículo</th><th>Custo mensal</th><th>Fat. esperado</th><th></th>'
      +'</tr></thead><tbody>';
    tipos.forEach(function(t){
      html+='<tr><td><strong>'+escHtml(t.tipo_equipe)+'</strong></td><td style="font-size:11px">'+escHtml(t.composicao_padrao||'—')+'</td>'
        +'<td style="text-align:center">'+vbeFmtNum(t.qtd_colaboradores_padrao,1)+'</td><td style="font-size:11px">'+escHtml(t.veiculo_padrao||'—')+'</td>'
        +'<td style="text-align:right">'+vbeFmtValor(t.custo_mensal_estimado)+'</td><td style="text-align:right">'+vbeFmtValor(t.faturamento_mensal_esperado)+'</td>'
        +'<td><button class="btn btn-sm" onclick="vbeOpenModalTipoEq(\''+escHtml(t.id)+'\')">✏</button> '
        +'<button class="btn btn-sm" style="color:#c0392b" onclick="vbeExcluirTipoEq(\''+escHtml(t.id)+'\')">🗑</button></td></tr>';
    });
    html+='</tbody></table></div>';
  }
  html+='</div>';
  wrap.innerHTML=html;
}

function vbeOpenModalTipoEq(id){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid){ progShowToast('Selecione um contrato.','erro'); return; }
  var t=(vbeTiposEquipe||[]).find(function(x){return x.id===id;})||{};
  var tipoOpts=vbeOptsTipoEquipeSelect(t.tipo_equipe||'');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:520px"><h3>'+(id?'Editar':'Novo')+' tipo de equipe</h3>'
    +'<div class="fg"><label>Tipo de equipe <span style="font-weight:400;color:#888">(cadastro Tipos de Equipe)</span></label><select class="inp" id="vbe-te-tipo" style="width:100%" data-nosort="1">'+tipoOpts+'</select></div>'
    +'<div class="fg"><label>Composição padrão</label><input class="inp" id="vbe-te-comp" style="width:100%" value="'+escHtml(t.composicao_padrao||'')+'" placeholder="Ex.: Encarregado + 2 Eletricistas"/></div>'
    +'<div class="g2"><div class="fg"><label>Qtd colaboradores</label><input class="inp" id="vbe-te-col" type="number" step="0.1" value="'+(t.qtd_colaboradores_padrao||2)+'"/></div>'
    +'<div class="fg"><label>Veículos por equipe</label><input class="inp" id="vbe-te-vei-eq" type="number" step="0.1" value="'+(t.veiculos_por_equipe||1)+'"/></div></div>'
    +'<div class="fg"><label>Veículo padrão</label><input class="inp" id="vbe-te-vei" style="width:100%" value="'+escHtml(t.veiculo_padrao||'')+'" placeholder="Ex.: Fiorino, Moto"/></div>'
    +'<div class="g2"><div class="fg"><label>Custo mensal estimado (R$)</label><input class="inp" id="vbe-te-custo" type="number" step="0.01" value="'+(t.custo_mensal_estimado||'')+'"/></div>'
    +'<div class="fg"><label>Faturamento mensal esperado (R$)</label><input class="inp" id="vbe-te-fat" type="number" step="0.01" value="'+(t.faturamento_mensal_esperado||'')+'"/></div></div>'
    +'<div class="fg"><label>Produtividade esperada</label><input class="inp" id="vbe-te-prod" type="number" step="0.01" value="'+(t.produtividade_esperada||'')+'"/></div>'
    +'<div class="fg"><label>Observações</label><input class="inp" id="vbe-te-obs" style="width:100%" value="'+escHtml(t.observacoes||'')+'"/></div>'
    +'<div style="margin-top:1rem;text-align:right;display:flex;gap:6px;justify-content:flex-end">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="vbeSalvarTipoEq(\''+escHtml(id||'')+'\')">Salvar</button></div></div></div>');
}

async function vbeSalvarTipoEq(id){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  var antes=(vbeTiposEquipe||[]).find(function(x){return x.id===id;});
  var row={
    contrato_id:cid,
    tipo_equipe:vbeCanonTipoEquipeNome((document.getElementById('vbe-te-tipo')||{}).value),
    composicao_padrao:(document.getElementById('vbe-te-comp')||{}).value,
    qtd_colaboradores_padrao:parseFloat((document.getElementById('vbe-te-col')||{}).value)||2,
    veiculos_por_equipe:parseFloat((document.getElementById('vbe-te-vei-eq')||{}).value)||1,
    veiculo_padrao:(document.getElementById('vbe-te-vei')||{}).value||null,
    custo_mensal_estimado:parseFloat((document.getElementById('vbe-te-custo')||{}).value)||null,
    faturamento_mensal_esperado:parseFloat((document.getElementById('vbe-te-fat')||{}).value)||null,
    produtividade_esperada:parseFloat((document.getElementById('vbe-te-prod')||{}).value)||null,
    observacoes:(document.getElementById('vbe-te-obs')||{}).value||'',
    ativo:true
  };
  try{
    if(id&&antes){
      if(!DEMO) await sbUpdate('contrato_tipos_equipe_premissas',row,'id=eq.'+id);
      Object.assign(antes,row);
    } else {
      if(!DEMO){ var ins=await sbInsert('contrato_tipos_equipe_premissas',row); if(ins&&ins[0]) vbeTiposEquipe.push(ins[0]); }
      else { row.id='vbet'+Date.now(); vbeTiposEquipe.push(row); }
    }
    if(!DEMO) vbeTiposEquipe=await sbFetch('contrato_tipos_equipe_premissas',{filters:['ativo=eq.true']})||vbeTiposEquipe;
    await vbeHistoricoRegistrar(cid,id?'tipo_eq_alterar':'tipo_eq_criar','Tipo equipe '+row.tipo_equipe,antes,row);
    closeModal(); vbeRenderEstrutura();
    progShowToast('Tipo de equipe salvo.');
  }catch(e){ console.error(e); progShowToast('Erro ao salvar tipo.','erro'); }
}

async function vbeExcluirTipoEq(id){
  if(!confirm('Excluir premissa deste tipo de equipe?')) return;
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  var antes=(vbeTiposEquipe||[]).find(function(x){return x.id===id;});
  try{
    if(!DEMO) await sbUpdate('contrato_tipos_equipe_premissas',{ativo:false},'id=eq.'+id);
    vbeTiposEquipe=vbeTiposEquipe.filter(function(x){return x.id!==id;});
    await vbeHistoricoRegistrar(cid,'tipo_eq_excluir','Tipo equipe removido',antes,null);
    vbeRenderEstrutura();
    progShowToast('Tipo removido.');
  }catch(e){ progShowToast('Erro ao excluir.','erro'); }
}

async function vbeImportarTiposDoERP(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid) return;
  await vbeEnsureDadosOperacionais();
  var ops=vbeColetarDadosOperacionais(cid,_vbeCompetencia||vbeGetCompSel());
  var map={};
  ops.equipes.forEach(function(e){
    if(!map[e.tipo]) map[e.tipo]={tipo:e.tipo,qtd:0,col:0,veiculos:{}};
    map[e.tipo].qtd++;
    map[e.tipo].col+=e.qtd_colaboradores;
    if(e.veiculo) map[e.tipo].veiculos[e.veiculo]=true;
  });
  var criados=0, atualizados=0;
  for(var tipo in map){
    if(!map.hasOwnProperty(tipo)) continue;
    var info=map[tipo];
    var tipoCanon=vbeCanonTipoEquipeNome(tipo);
    var existente=(vbeTiposEquipe||[]).find(function(t){
      return String(t.contrato_id)===String(cid)&&t.ativo!==false
        &&(vbeMatchTipoNome(t.tipo_equipe,tipoCanon)||vbeNormTipoTxt(t.tipo_equipe)===vbeNormTipoTxt(tipoCanon));
    });
    if(existente){
      if(existente.tipo_equipe!==tipoCanon){
        existente.tipo_equipe=tipoCanon;
        try{ if(!DEMO) await sbUpdate('contrato_tipos_equipe_premissas',{tipo_equipe:tipoCanon},'id=eq.'+existente.id); atualizados++; }catch(eU){}
      }
      continue;
    }
    var row={
      contrato_id:cid, tipo_equipe:tipoCanon, ativo:true,
      qtd_colaboradores_padrao:info.qtd?Math.round((info.col/info.qtd)*10)/10:2,
      veiculos_por_equipe:1,
      veiculo_padrao:Object.keys(info.veiculos)[0]||null,
      composicao_padrao:info.qtd+' equipe(s) cadastrada(s) no ERP'
    };
    try{
      if(!DEMO){ var ins=await sbInsert('contrato_tipos_equipe_premissas',row); if(ins&&ins[0]) vbeTiposEquipe.push(ins[0]); }
      else { row.id='vbet'+Date.now()+criados; vbeTiposEquipe.push(row); }
      criados++;
    }catch(e){ console.warn('vbeImportarTiposDoERP:',e); }
  }
  if(!DEMO&&(criados||atualizados)) vbeTiposEquipe=await sbFetch('contrato_tipos_equipe_premissas',{filters:['ativo=eq.true']})||vbeTiposEquipe;
  (vbeTiposEquipe||[]).forEach(function(t){
    if(t&&t.tipo_equipe){ var c=vbeCanonTipoEquipeNome(t.tipo_equipe); if(c!==t.tipo_equipe) t.tipo_equipe=c; }
  });
  vbeRenderEstrutura();
  var msg=[];
  if(criados) msg.push(criados+' tipo(s) importado(s)');
  if(atualizados) msg.push(atualizados+' nome(s) corrigido(s) pelo de-para');
  progShowToast(msg.length?msg.join(' · ')+'.':'Nenhum tipo novo — já existem ou sem equipes.');
}

function vbeRenderSimulador(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  var comp=_vbeCompetencia||vbeGetCompSel();
  var wrap=document.getElementById('vbe-simulador-wrap'); if(!wrap) return;
  if(!cid){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">Selecione um contrato no filtro superior para simular crescimento.</div>';
    return;
  }
  var p=vbeObterPremissasEfetivas(cid,comp);
  if(!p){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">Sem premissas ou dados operacionais. Cadastre premissas ou sincronize o ERP antes de simular.</div>';
    return;
  }
  var sp=_vbeSimParams[cid]||vbeSimParamsDefault(cid,p);
  _vbeSimParams[cid]=sp;
  var sim=vbeCalcCenarioCrescimento(cid,comp,sp);
  var ro=vbePodeVerFinanceiro()?'':' disabled title="Sem permissão financeira"';
  var html='';
  html+='<div class="card" style="margin-bottom:1rem;border-left:4px solid #185FA5">'
    +'<div style="padding:.65rem 1rem;font-size:12px;color:#185FA5;background:#EBF4FD;border-radius:8px">'
    +'<strong>Simulador de crescimento</strong> — '+escHtml(vbeNomeContrato(cid))+' · '+comp.slice(0,7)
    +'. Ajuste equipes e custos para ver impacto em IVEC, ICO, margem, payback e saldo contratual. Decisão final depende de análise humana.'
    +'</div></div>';
  html+='<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">Parâmetros do cenário</span>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
    +'<button class="btn btn-sm" onclick="vbeSimPreset(1)">+1 equipe</button>'
    +'<button class="btn btn-sm" onclick="vbeSimPreset(2)">+2 equipes</button>'
    +'<button class="btn btn-sm" onclick="vbeSimPreset(0)">Zerar</button>'
    +'<button class="btn btn-pri btn-sm" onclick="vbeSimSalvar()">💾 Salvar cenário</button>'
    +'</div></div>'
    +'<div style="padding:1rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px">'
    +vbeSimField('vbe-sim-eq','Equipes adicionais',sp.qtd_equipes_adicionais,'',ro)
    +vbeSimField('vbe-sim-tipo','Tipo de equipe (rótulo)',sp.tipo_equipe,'text',ro)
    +vbeSimField('vbe-sim-fat-eq','Faturamento por equipe/mês (R$)',sp.faturamento_por_equipe,'',ro)
    +vbeSimField('vbe-sim-custo-eq','Custo mensal por equipe (R$)',sp.custo_mensal_por_equipe,'',ro)
    +vbeSimField('vbe-sim-custo-ini','Custo inicial mobilização (R$)',sp.custo_inicial,'',ro)
    +vbeSimField('vbe-sim-vei','Veículos necessários',sp.necessidade_veiculos,'',ro)
    +vbeSimField('vbe-sim-col','Colaboradores necessários',sp.necessidade_colaboradores,'',ro)
    +'</div>'
    +'<div style="padding:0 1rem 1rem"><label style="font-size:11px;font-weight:600">Observações / treinamentos</label>'
    +'<textarea class="inp" id="vbe-sim-obs" rows="2" style="width:100%;margin-top:4px" onchange="vbeSimOnChange()"'+ro+'>'
    +escHtml(sp.necessidade_treinamentos||'')+'</textarea></div></div>';
  if(sim){
    var d=sim.delta, bl=sim.baseline, ce=sim.cenario;
    var ivecCor=vbeClassCorIvec(ce.ivec);
    var recCor=sim.recomendacao_ok?'#085041':'#854F0B';
    html+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:1rem">';
    html+=[
      {l:'IVEC atual',v:bl.ivec,c:vbeClassCorIvec(bl.ivec)},
      {l:'IVEC simulado',v:ce.ivec,c:ivecCor},
      {l:'Δ IVEC',v:(d.ivec>=0?'+':'')+d.ivec,c:d.ivec>=0?'#3B6D11':'#A32D2D'},
      {l:'ICO atual',v:bl.ico,c:vbeClassCorIco(bl.ico)},
      {l:'ICO simulado',v:ce.ico,c:vbeClassCorIco(ce.ico)},
      {l:'Margem atual',v:vbeFmtPct(bl.margem),c:'#555'},
      {l:'Margem simulada',v:vbeFmtPct(ce.margem),c:'#555'},
      {l:'Payback',v:sim.payback_meses!=null?sim.payback_meses+' meses':'—',c:'#185FA5'},
      {l:'Impacto saldo',v:vbeFmtValor(sim.impacto_saldo_contratual),c:'#085041'}
    ].map(function(m){return vbeMetricCard(m.l,m.v,m.c);}).join('');
    html+='</div>';
    html+='<div style="padding:.65rem 1rem;margin-bottom:1rem;font-size:12px;border-radius:8px;background:'+(sim.recomendacao_ok?'#EAF5EA':'#FFF8E6')+';color:'+recCor+'">'
      +'<strong>Recomendação:</strong> '+escHtml(sim.recomendacao)+'</div>';
    html+='<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">Comparativo mensal</span></div>'
      +'<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>Indicador</th><th style="text-align:right">Atual</th><th style="text-align:right">Simulado</th><th style="text-align:right">Δ</th>'
      +'</tr></thead><tbody>';
    html+=vbeSimCmpRow('Receita bruta',bl.receita_bruta,ce.receita_bruta);
    html+=vbeSimCmpRow('Custo total',bl.custo_total,ce.custo_total,true);
    html+=vbeSimCmpRow('Resultado mensal',bl.resultado,ce.resultado);
    html+=vbeSimCmpRow('Margem incremental',0,sim.margem_incremental_mensal);
    html+=vbeSimCmpRow('Equipes alvo',bl.equipes_alvo,ce.equipes_alvo,false,true);
    html+=vbeSimCmpRow('Equipes entregues (média)',bl.equipes_entregues,ce.equipes_entregues,false,true);
    html+='</tbody></table></div></div>';
    if(sim.projecao&&sim.projecao.length){
      html+='<div class="card" style="margin-bottom:1rem"><div class="ch"><span class="ct">Projeção incremental ('+sim.projecao.length+' meses)</span></div>'
        +'<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
        +'<th>Mês</th><th style="text-align:right">Fat. adicional</th><th style="text-align:right">Custo adicional</th>'
        +'<th style="text-align:right">Resultado incr.</th><th style="text-align:right">Acumulado</th><th style="text-align:right">Payback?</th>'
        +'</tr></thead><tbody>';
      sim.projecao.forEach(function(row){
        html+='<tr><td>'+row.mes+'</td>'
          +'<td style="text-align:right">'+vbeFmtValor(row.fat_add)+'</td>'
          +'<td style="text-align:right">'+vbeFmtValor(row.custo_add)+'</td>'
          +'<td style="text-align:right;color:'+(row.resultado_incr>=0?'#3B6D11':'#A32D2D')+'">'+vbeFmtValor(row.resultado_incr)+'</td>'
          +'<td style="text-align:right;font-weight:600">'+vbeFmtValor(row.acumulado)+'</td>'
          +'<td style="text-align:center">'+(row.payback_atingido?'✓':'')+'</td></tr>';
      });
      html+='</tbody></table></div></div>';
    }
  }
  var salvas=(vbeSimulacoes||[]).filter(function(s){return s.contrato_id===cid;});
  html+='<div class="card"><div class="ch"><span class="ct">Cenários salvos ('+salvas.length+')</span></div>';
  if(!salvas.length){
    html+='<div style="padding:1.5rem;text-align:center;color:#888">Nenhum cenário salvo para este contrato.</div>';
  } else {
    html+='<div style="overflow-x:auto"><table class="tbl tbl-r"><thead><tr>'
      +'<th>Nome</th><th>Eq. +</th><th style="text-align:right">Fat./mês est.</th><th style="text-align:right">Payback</th>'
      +'<th style="text-align:right">Impacto saldo</th><th>Recomendação</th><th></th>'
      +'</tr></thead><tbody>';
    salvas.forEach(function(s){
      html+='<tr><td><strong>'+escHtml(s.nome_simulacao)+'</strong>'
        +(s.descricao?'<div style="font-size:10px;color:#888">'+escHtml(s.descricao)+'</div>':'')+'</td>'
        +'<td style="text-align:center">'+vbeFmtNum(s.qtd_equipes_adicionais,1)+'</td>'
        +'<td style="text-align:right">'+vbeFmtValor(s.faturamento_mensal_estimado)+'</td>'
        +'<td style="text-align:right">'+(s.payback_meses!=null?s.payback_meses+' m':'—')+'</td>'
        +'<td style="text-align:right">'+vbeFmtValor(s.impacto_saldo_contratual)+'</td>'
        +'<td style="font-size:11px">'+escHtml((s.recomendacao||'—').slice(0,80))+'</td>'
        +'<td style="white-space:nowrap"><button class="btn btn-sm" onclick="vbeSimCarregar(\''+escHtml(s.id)+'\')">Carregar</button> '
        +'<button class="btn btn-sm" style="color:#c0392b" onclick="vbeSimExcluir(\''+escHtml(s.id)+'\')">🗑</button></td></tr>';
    });
    html+='</tbody></table></div>';
  }
  html+='</div>';
  html+='<div style="font-size:11px;color:#888;margin-top:8px">Fase 4: simulação local com premissas/custos atuais. Não altera dados operacionais até decisão e mobilização real.</div>';
  wrap.innerHTML=html;
  ['vbe-sim-eq','vbe-sim-fat-eq','vbe-sim-custo-eq','vbe-sim-custo-ini','vbe-sim-vei','vbe-sim-col'].forEach(function(id){
    var el=document.getElementById(id);
    if(el) el.oninput=vbeSimOnChange;
  });
  var tel=document.getElementById('vbe-sim-tipo');
  if(tel) tel.onchange=vbeSimOnChange;
}

function vbeSimField(id,label,val,type,ro){
  type=type||'number';
  if(type==='text'){
    return '<div class="fg"><label style="font-size:11px;font-weight:600">'+label+'</label>'
      +'<input class="inp" id="'+id+'" type="text" style="width:100%" value="'+escHtml(val||'')+'"'+(ro||'')+'/></div>';
  }
  return '<div class="fg"><label style="font-size:11px;font-weight:600">'+label+'</label>'
    +'<input class="inp" id="'+id+'" type="number" step="any" style="width:100%" value="'+(val!=null&&val!==''?val:'')+'"'+(ro||'')+'/></div>';
}

function vbeSimCmpRow(label,atual,sim,invert,isNum){
  var d=Number(sim||0)-Number(atual||0);
  var cor=d>0?(invert?'#A32D2D':'#3B6D11'):d<0?(invert?'#3B6D11':'#A32D2D'):'#555';
  var fmt=isNum?function(v){return vbeFmtNum(v,1);}:vbeFmtValor;
  return '<tr><td>'+label+'</td><td style="text-align:right">'+fmt(atual)+'</td>'
    +'<td style="text-align:right">'+fmt(sim)+'</td>'
    +'<td style="text-align:right;color:'+cor+';font-weight:600">'+(d>=0?'+':'')+fmt(d)+'</td></tr>';
}

function vbeSimParamsDefault(cid,p){
  p=p||vbeObterPremissasEfetivas(cid)||{};
  var tipos=(vbeTiposEquipe||[]).filter(function(t){return t.contrato_id===cid&&t.ativo!==false;});
  var fatEq=Number(p.faturamento_esperado_por_equipe||0);
  var custoEq=0, tipoNome='Equipe padrão';
  if(tipos.length){
    fatEq=fatEq||tipos.reduce(function(s,t){return s+Number(t.faturamento_mensal_esperado||0);},0)/tipos.length;
    custoEq=tipos.reduce(function(s,t){return s+Number(t.custo_mensal_estimado||0);},0)/tipos.length;
    tipoNome=tipos[0].tipo_equipe||tipoNome;
  }
  if(!custoEq){
    var a=vbeAnalisarContrato(cid,_vbeCompetencia||vbeGetCompSel());
    if(a&&a.resultado.custo_por_equipe) custoEq=a.resultado.custo_por_equipe;
  }
  var colEq=Number(p.colaboradores_por_equipe||2);
  var veiEq=Number(p.veiculos_por_equipe||1);
  return {
    qtd_equipes_adicionais:0, tipo_equipe:tipoNome,
    faturamento_por_equipe:Math.round(fatEq*100)/100||0,
    custo_mensal_por_equipe:Math.round(custoEq*100)/100||0,
    custo_inicial:0, necessidade_veiculos:0, necessidade_colaboradores:0,
    necessidade_treinamentos:''
  };
}

function vbeSimLerParams(cid){
  var g=function(id){return (document.getElementById(id)||{}).value;};
  var gn=function(id){var v=parseFloat(g(id)); return isNaN(v)?0:v;};
  var prev=_vbeSimParams[cid]||{};
  var eq=gn('vbe-sim-eq');
  var colEq=Number((vbeObterPremissasEfetivas(cid)||{}).colaboradores_por_equipe||2);
  var veiEq=Number((vbeObterPremissasEfetivas(cid)||{}).veiculos_por_equipe||1);
  var custoIni=gn('vbe-sim-custo-ini');
  if(!custoIni&&eq>0&&!prev._custo_ini_manual) custoIni=eq*12000;
  return {
    qtd_equipes_adicionais:eq,
    tipo_equipe:g('vbe-sim-tipo')||prev.tipo_equipe||'',
    faturamento_por_equipe:gn('vbe-sim-fat-eq'),
    custo_mensal_por_equipe:gn('vbe-sim-custo-eq'),
    custo_inicial:custoIni,
    _custo_ini_manual:!!(document.getElementById('vbe-sim-custo-ini')||{}).value,
    necessidade_veiculos:gn('vbe-sim-vei')||eq*veiEq,
    necessidade_colaboradores:gn('vbe-sim-col')||eq*colEq,
    necessidade_treinamentos:g('vbe-sim-obs')||''
  };
}

function vbeSimOnChange(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid) return;
  _vbeSimParams[cid]=vbeSimLerParams(cid);
  vbeRenderSimulador();
}

function vbeSimPreset(n){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid) return;
  var sp=_vbeSimParams[cid]||vbeSimParamsDefault(cid);
  sp.qtd_equipes_adicionais=n;
  var colEq=Number((vbeObterPremissasEfetivas(cid)||{}).colaboradores_por_equipe||2);
  var veiEq=Number((vbeObterPremissasEfetivas(cid)||{}).veiculos_por_equipe||1);
  sp.necessidade_colaboradores=n*colEq;
  sp.necessidade_veiculos=n*veiEq;
  sp.custo_inicial=n>0?n*12000:0;
  _vbeSimParams[cid]=sp;
  vbeRenderSimulador();
}

function vbeCalcCenarioCrescimento(cid,comp,params){
  params=params||{};
  var baseAn=vbeAnalisarContrato(cid,comp);
  if(!baseAn) return null;
  var p=Object.assign({},baseAn.premissas);
  var eqExtra=Math.max(0,Number(params.qtd_equipes_adicionais||0));
  var fatPorEq=Number(params.faturamento_por_equipe||p.faturamento_esperado_por_equipe||0);
  var custoPorEq=Number(params.custo_mensal_por_equipe||0);
  if(!custoPorEq&&baseAn.resultado.custo_por_equipe) custoPorEq=baseAn.resultado.custo_por_equipe;
  var fatAddBruto=eqExtra*fatPorEq;
  var fatAddLiq=fatAddBruto; // retenção não abate (receita futura)
  var custoAdd=eqExtra*custoPorEq;
  var margemIncr=fatAddLiq-custoAdd;
  var custoInicial=Number(params.custo_inicial||0);
  var payback=margemIncr>0?Math.round((custoInicial/margemIncr)*10)/10:null;
  var pSim=Object.assign({},p);
  pSim.equipes_alvo=Number(p.equipes_alvo||0)+eqExtra;
  pSim.equipes_entregues_media=Number(p.equipes_entregues_media||0)+eqExtra;
  pSim.faturamento_mensal_esperado=Number(p.faturamento_mensal_esperado||0)+fatAddBruto;
  var custosSim=(baseAn.custos||[]).slice();
  if(custoAdd>0){
    custosSim.push({
      categoria_custo:'folha', descricao:'Simulação: +'+eqExtra+' equipe(s)',
      valor:custoAdd, origem:'Calculado', nivel_confianca:'Média'
    });
  }
  var capSim=vbeCalcCapacidade(pSim);
  var resSim=vbeCalcResultado(pSim,custosSim,comp);
  var ivecSim=vbeCalcIVEC(pSim,resSim,capSim);
  var bl={
    ivec:baseAn.ivec.ivec_score, ico:baseAn.capacidade.ico_score,
    margem:baseAn.resultado.margem_operacional_percentual,
    resultado:baseAn.resultado.resultado_mensal,
    receita_bruta:baseAn.resultado.receita_bruta,
    custo_total:baseAn.resultado.custo_total,
    equipes_alvo:Number(p.equipes_alvo||0),
    equipes_entregues:Number(p.equipes_entregues_media||0)
  };
  var ce={
    ivec:ivecSim.ivec_score, ico:capSim.ico_score,
    margem:resSim.margem_operacional_percentual,
    resultado:resSim.resultado_mensal,
    receita_bruta:resSim.receita_bruta,
    custo_total:resSim.custo_total,
    equipes_alvo:pSim.equipes_alvo,
    equipes_entregues:pSim.equipes_entregues_media
  };
  var saldo=Number(p.saldo_contratual||0)||(Number(p.valor_total_contrato||0)-Number(p.valor_faturado_acumulado||0));
  var mesesRest=0;
  var c=(contratos||[]).find(function(x){return x.id===cid;});
  if(c&&c.data_termino) mesesRest=Math.max(0,Math.round((new Date(c.data_termino+'T00:00:00')-new Date())/86400000/30));
  var impactoSaldo=fatAddBruto*mesesRest;
  var horizonte=Math.min(12,mesesRest||12);
  if(horizonte<1) horizonte=6;
  var projecao=[], acum=0, paybackOk=false;
  for(var i=1;i<=horizonte;i++){
    acum+=margemIncr;
    if(!paybackOk&&custoInicial>0&&acum>=custoInicial) paybackOk=true;
    projecao.push({
      mes:i, fat_add:fatAddLiq, custo_add:custoAdd,
      resultado_incr:margemIncr, acumulado:acum, payback_atingido:paybackOk
    });
  }
  var recomendacao='', ok=false;
  if(eqExtra<=0){
    recomendacao='Informe equipes adicionais para simular.';
  } else if(margemIncr<=0){
    recomendacao='Cenário inviável: custo incremental supera receita líquida adicional.';
  } else if(capSim.ico_score<50){
    recomendacao='Margem positiva, mas capacidade operacional insuficiente (ICO '+capSim.ico_score+'). Avaliar mobilização antes de crescer.';
    ok=margemIncr>0;
  } else if(ivecSim.ivec_score>=65&&payback!=null&&payback<=mesesRest){
    recomendacao='Cenário favorável: IVEC '+ivecSim.ivec_score+', payback ~'+payback+' meses, saldo contratual absorve crescimento.';
    ok=true;
  } else if(ivecSim.ivec_score>=50){
    recomendacao='Cenário moderado: avaliar payback ('+(payback!=null?payback+' meses':'—')+') e saldo restante ('+vbeFmtValor(saldo)+').';
    ok=ivecSim.ivec_score>=55;
  } else {
    recomendacao='Cenário desfavorável: IVEC cai para '+ivecSim.ivec_score+'. Renegociar preço ou reduzir custo por equipe.';
  }
  return {
    baseline:bl, cenario:ce,
    delta:{
      ivec:Math.round((ce.ivec-bl.ivec)*10)/10,
      ico:Math.round((ce.ico-bl.ico)*10)/10,
      resultado:ce.resultado-bl.resultado,
      margem:Math.round((ce.margem-bl.margem)*10)/10
    },
    margem_incremental_mensal:margemIncr,
    payback_meses:payback,
    impacto_saldo_contratual:impactoSaldo,
    meses_restantes:mesesRest,
    projecao:projecao,
    recomendacao:recomendacao,
    recomendacao_ok:ok,
    params_used:params
  };
}

async function vbeSimSalvar(){
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  if(!cid){ progShowToast('Selecione um contrato.','erro'); return; }
  var comp=_vbeCompetencia||vbeGetCompSel();
  var sp=_vbeSimParams[cid]||vbeSimLerParams(cid);
  var sim=vbeCalcCenarioCrescimento(cid,comp,sp);
  if(!sim||!Number(sp.qtd_equipes_adicionais||0)){
    progShowToast('Configure equipes adicionais antes de salvar.','erro'); return;
  }
  var nome=prompt('Nome do cenário:',(sp.tipo_equipe||'Cenário')+' +'+sp.qtd_equipes_adicionais+' eq.');
  if(!nome) return;
  var row={
    contrato_id:cid, nome_simulacao:nome.trim(),
    descricao:'Simulação '+comp.slice(0,7)+' — IVEC '+sim.cenario.ivec+' (Δ '+(sim.delta.ivec>=0?'+':'')+sim.delta.ivec+')',
    qtd_equipes_adicionais:sp.qtd_equipes_adicionais,
    tipo_equipe:sp.tipo_equipe||null,
    custo_inicial:sp.custo_inicial||null,
    custo_mensal_adicional:sp.custo_mensal_por_equipe*sp.qtd_equipes_adicionais,
    faturamento_mensal_estimado:sp.faturamento_por_equipe*sp.qtd_equipes_adicionais,
    margem_estimada:sim.cenario.margem,
    payback_meses:sim.payback_meses,
    necessidade_veiculos:sp.necessidade_veiculos||null,
    necessidade_colaboradores:sp.necessidade_colaboradores||null,
    necessidade_treinamentos:sp.necessidade_treinamentos||null,
    impacto_saldo_contratual:sim.impacto_saldo_contratual,
    impacto_prazo:sim.meses_restantes?sim.meses_restantes+' meses restantes':null,
    recomendacao:sim.recomendacao,
    criado_por:(usuarioLogado||{}).id||null
  };
  try{
    if(!DEMO){
      var ins=await sbInsert('contrato_simulacoes_crescimento',row);
      if(ins&&ins[0]) vbeSimulacoes.unshift(ins[0]);
      else vbeSimulacoes=await sbFetch('contrato_simulacoes_crescimento',{order:'criado_em.desc',limit:500})||vbeSimulacoes;
    } else {
      row.id='vbesim'+Date.now(); row.criado_em=new Date().toISOString();
      vbeSimulacoes.unshift(row);
    }
    await vbeHistoricoRegistrar(cid,'simulacao_criar','Cenário salvo: '+nome,null,row);
    progShowToast('Cenário salvo.');
    vbeRenderSimulador();
  }catch(e){ console.error(e); progShowToast('Erro ao salvar cenário. Rode o SQL Fase 1 se a tabela não existir.','erro'); }
}

function vbeSimCarregar(id){
  var s=(vbeSimulacoes||[]).find(function(x){return x.id===id;});
  if(!s) return;
  _vbeContratoAtual=s.contrato_id;
  var sel=document.getElementById('vbe-fil-contrato'); if(sel) sel.value=s.contrato_id;
  var eq=Number(s.qtd_equipes_adicionais||0);
  _vbeSimParams[s.contrato_id]={
    qtd_equipes_adicionais:eq,
    tipo_equipe:s.tipo_equipe||'',
    faturamento_por_equipe:eq>0?Number(s.faturamento_mensal_estimado||0)/eq:0,
    custo_mensal_por_equipe:eq>0?Number(s.custo_mensal_adicional||0)/eq:0,
    custo_inicial:Number(s.custo_inicial||0),
    necessidade_veiculos:Number(s.necessidade_veiculos||0),
    necessidade_colaboradores:Number(s.necessidade_colaboradores||0),
    necessidade_treinamentos:s.necessidade_treinamentos||'',
    _custo_ini_manual:true
  };
  vbeRenderSimulador();
  progShowToast('Cenário carregado: '+s.nome_simulacao);
}

async function vbeSimExcluir(id){
  if(!confirm('Excluir este cenário salvo?')) return;
  var s=(vbeSimulacoes||[]).find(function(x){return x.id===id;});
  try{
    if(!DEMO) await sbDelete('contrato_simulacoes_crescimento','id=eq.'+id);
    vbeSimulacoes=vbeSimulacoes.filter(function(x){return x.id!==id;});
    if(s) await vbeHistoricoRegistrar(s.contrato_id,'simulacao_excluir','Cenário excluído: '+s.nome_simulacao,s,null);
    vbeRenderSimulador();
    progShowToast('Cenário excluído.');
  }catch(e){ progShowToast('Erro ao excluir.','erro'); }
}

function vbeRenderHistorico(){
  var wrap=document.getElementById('vbe-historico-wrap'); if(!wrap) return;
  var cid=_vbeContratoAtual||(document.getElementById('vbe-fil-contrato')||{}).value;
  var lista=(vbeHistorico||[]).slice();
  if(cid) lista=lista.filter(function(h){return h.contrato_id===cid;});
  if(!lista.length){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#888">Nenhum evento registrado ainda.</div>';
    return;
  }
  wrap.innerHTML='<div class="card"><table class="tbl tbl-r"><thead><tr>'
    +'<th>Data/hora</th><th>Tipo</th><th>Contrato</th><th>Usuário</th><th>Descrição</th>'
    +'</tr></thead><tbody>'
    +lista.slice(0,100).map(function(h){
      var dt=h.criado_em?new Date(h.criado_em).toLocaleString('pt-BR'):'—';
      return '<tr><td style="white-space:nowrap;font-size:11px">'+dt+'</td>'
        +'<td><span class="bdg gray">'+escHtml(h.tipo_evento||'—')+'</span></td>'
        +'<td style="font-size:11px">'+escHtml(vbeNomeContrato(h.contrato_id))+'</td>'
        +'<td style="font-size:11px">'+escHtml(h.usuario_nome||'Sistema')+'</td>'
        +'<td style="font-size:12px">'+escHtml(h.descricao||'—')+'</td></tr>';
    }).join('')+'</tbody></table></div>';
}

// INVENTARIO ATIVOS FASE1–5 MODULE
var _ativosCache=[],_ativosCatCache=[],_ativosLoaded=false;
var ATIVOS_STATUS=['Disponível','Em uso','Em manutenção','Reservado','Transferido','Aguardando baixa','Baixado','Extraviado','Vendido','Descartado'];
var ATIVOS_CONDICAO=['Novo','Bom','Regular','Ruim','Inutilizado'];
var ATIVOS_LOC_TIPOS=['Base','Almoxarifado','Escritório','Veículo','Obra','Contrato','Colaborador','Fornecedor/manutenção','Outro'];
var ATIVOS_RESP_TIPOS=['Colaborador','Equipe','Setor','Base','Contrato','Fornecedor','Outro'];

function ativosPodeEditar(){
  if(!usuarioLogado) return false;
  return ['admin','gestor','administrativo','almoxarife'].indexOf(String(usuarioLogado.perfil||''))>=0;
}
function ativosPodeExcluir(){
  if(!usuarioLogado) return false;
  var p=String(usuarioLogado.perfil||'');
  return p==='admin'||p==='gestor';
}
function ativosApplyPermUI(){
  var ed=ativosPodeEditar();
  var mv=typeof ativosPodeMovimentar==='function'?ativosPodeMovimentar():ed;
  var b1=document.getElementById('ativos-btn-novo');
  var b2=document.getElementById('ativos-cat-novo');
  var b3=document.getElementById('ativos-mov-nova');
  var b4=document.getElementById('ativos-manut-nova');
  var b5=document.getElementById('ativos-doc-novo');
  var b6=document.getElementById('ativos-invfis-novo');
  if(b1) b1.style.display=ed?'':'none';
  if(b2) b2.style.display=ed?'':'none';
  if(b3) b3.style.display=mv?'':'none';
  if(b4) b4.style.display=ed?'':'none';
  if(b5) b5.style.display=ed?'':'none';
  if(b6) b6.style.display=ed?'':'none';
}
async function ativosCarregar(force){
  // Recarrega se forçado, ainda não carregou, ou categorias vieram vazias (ex.: falha silenciosa no 1º fetch)
  if(_ativosLoaded&&!force&&(_ativosCatCache||[]).length) return;
  if(DEMO){
    if(!_ativosCatCache.length) _ativosCatCache=[
      {id:'cat-ti',nome:'TI / Tecnologia',ativo:true,exige_numero_serie:true},
      {id:'cat-ferr',nome:'Ferramentas Patrimoniais',ativo:true},
      {id:'cat-campo',nome:'Equipamentos de Campo',ativo:true},
      {id:'cat-med',nome:'Instrumentos de Medição',ativo:true},
      {id:'cat-sesmt',nome:'Equipamentos de Segurança / SESMT',ativo:true},
      {id:'cat-mov',nome:'Móveis e Utensílios',ativo:true},
      {id:'cat-maq',nome:'Máquinas e Equipamentos',ativo:true},
      {id:'cat-veic',nome:'Equipamentos Veiculares',ativo:true},
      {id:'cat-com',nome:'Equipamentos de Comunicação',ativo:true},
      {id:'cat-esc',nome:'Equipamentos de Escritório',ativo:true},
      {id:'cat-ener',nome:'Equipamentos de Energia',ativo:true},
      {id:'cat-arm',nome:'Equipamentos de Armazenamento',ativo:true},
      {id:'cat-obra',nome:'Equipamentos de Obra',ativo:true},
      {id:'cat-topo',nome:'Equipamentos de Topografia',ativo:true},
      {id:'cat-infra',nome:'Ativos de Infraestrutura',ativo:true},
      {id:'cat-out',nome:'Outros',ativo:true}
    ];
    _ativosLoaded=true; return;
  }
  try{
    var cats=await sbFetch('ativos_categorias',{filters:['deleted_at=is.null'],order:'nome.asc',limit:2000});
    if(cats===null){
      // Fallback: tabela sem deleted_at / schema API desatualizado / erro HTTP
      cats=await sbFetch('ativos_categorias',{order:'nome.asc',limit:2000});
    }
    if(cats===null){
      console.warn('[Ativos] categorias: sbFetch retornou null (404/403?). Confira tabela + GRANT + reload schema API.');
      _ativosCatCache=[];
      if(typeof progShowToast==='function') progShowToast('⚠ API não acessa ativos_categorias. Rode SQLS/sql_ativos_rls_fix.sql','erro');
    } else {
      _ativosCatCache=Array.isArray(cats)?cats.filter(function(c){return !c.deleted_at;}):[];
      if(!_ativosCatCache.length && typeof progShowToast==='function')
        progShowToast('⚠ API retornou 0 categorias (SQL Editor pode mostrar dados com RLS). Rode SQLS/sql_ativos_rls_fix.sql','erro');
    }
  }catch(e){
    console.warn('[Ativos] categorias',e); _ativosCatCache=[];
    if(typeof progShowToast==='function') progShowToast('⚠ Erro ao carregar categorias.','erro');
  }
  try{
    var rows=await sbFetch('ativos_inventario',{filters:['deleted_at=is.null'],order:'descricao.asc',limit:5000});
    if(rows===null) rows=await sbFetch('ativos_inventario',{order:'descricao.asc',limit:5000});
    _ativosCache=Array.isArray(rows)?rows.filter(function(a){return !a.deleted_at;}):[];
  }catch(e){ console.warn('[Ativos] inventario',e); _ativosCache=[]; }
  _ativosLoaded=true;
}
function ativosCatNome(id){
  if(!id) return '—';
  var c=_ativosCatCache.find(function(x){return String(x.id)===String(id);});
  return c?c.nome:'—';
}
function ativosFmtR(v){
  var n=Number(v); if(isNaN(n)) return '—';
  return n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
}
function ativosAtivosAtivos(){ return (_ativosCache||[]).filter(function(a){return !a.deleted_at;}); }
function ativosCatsAtivas(){ return (_ativosCatCache||[]).filter(function(c){return !c.deleted_at&&c.ativo!==false;}); }
function ativosPopularFiltroCat(){
  var sel=document.getElementById('ativos-fil-cat'); if(!sel) return;
  var cur=sel.value;
  sel.innerHTML='<option value="">Todas categorias</option>'+ativosCatsAtivas().map(function(c){
    return '<option value="'+escHtml(String(c.id))+'">'+escHtml(c.nome)+'</option>';
  }).join('');
  if(cur) sel.value=cur;
}
async function ativosDashRender(){
  ativosApplyPermUI();
  await ativosCarregar(true);
  if(typeof ativosCarregarMov==='function') await ativosCarregarMov(!_ativosMovLoaded);
  if(typeof ativosCarregarManut==='function') await ativosCarregarManut(!_ativosManutLoaded);
  if(typeof ativosCarregarDoc==='function') await ativosCarregarDoc(!_ativosDocLoaded);
  var rows=ativosAtivosAtivos();
  var pend=typeof ativosTermosPendentes==='function'?ativosTermosPendentes().length:0;
  var movN=(_ativosMovCache||[]).filter(function(m){return !m.deleted_at;}).length;
  var manutAbertas=(_ativosManutCache||[]).filter(function(m){return !m.deleted_at&&typeof ativosManutAberta==='function'&&ativosManutAberta(m.status);}).length;
  var docsN=(_ativosDocCache||[]).filter(function(d){return !d.deleted_at;}).length;
  var cards=[
    {l:'Total',v:rows.length,c:'#555'},
    {l:'Disponíveis',v:rows.filter(function(a){return a.status==='Disponível';}).length,c:'#3B6D11'},
    {l:'Em uso',v:rows.filter(function(a){return a.status==='Em uso';}).length,c:'#185FA5'},
    {l:'Em manutenção',v:rows.filter(function(a){return a.status==='Em manutenção';}).length,c:'#854F0B'},
    {l:'Baixados',v:rows.filter(function(a){return a.status==='Baixado';}).length,c:'#888'},
    {l:'Sem responsável',v:rows.filter(function(a){return !(a.responsavel_nome||a.responsavel_id);}).length,c:'#A32D2D'},
    {l:'Sem localização',v:rows.filter(function(a){return !(a.localizacao_descricao||a.base||a.localizacao_tipo);}).length,c:'#A32D2D'},
    {l:'Valor patrimonial',v:ativosFmtR(rows.reduce(function(s,a){return s+(Number(a.valor_aquisicao)||0);},0)),c:'#533AB7'},
    {l:'Movimentações',v:movN,c:'#185FA5'},
    {l:'Termos pendentes',v:pend,c:pend?'#A32D2D':'#3B6D11'},
    {l:'Manut. abertas',v:manutAbertas,c:'#854F0B'},
    {l:'Documentos',v:docsN,c:'#555'}
  ];
  var wrap=document.getElementById('ativos-dash-cards');
  if(wrap) wrap.innerHTML=cards.map(function(x){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:.65rem .5rem;text-align:center">'
      +'<div style="font-size:9px;color:#888;margin-bottom:2px">'+x.l+'</div>'
      +'<div style="font-size:16px;font-weight:700;color:'+x.c+'">'+x.v+'</div></div>';
  }).join('');
  function groupCount(fn){
    var m={}; rows.forEach(function(a){ var k=fn(a)||'—'; m[k]=(m[k]||0)+1; });
    return Object.keys(m).sort().map(function(k){return {k:k,v:m[k]};});
  }
  function fillTb(id,arr){
    var tb=document.getElementById(id); if(!tb) return;
    if(!arr.length){ tb.innerHTML='<tr><td colspan="2" style="color:#aaa;text-align:center">Sem dados</td></tr>'; return; }
    tb.innerHTML=arr.map(function(r){ return '<tr><td>'+escHtml(r.k)+'</td><td style="text-align:right;font-weight:600">'+r.v+'</td></tr>'; }).join('');
  }
  fillTb('ativos-dash-cat',groupCount(function(a){return ativosCatNome(a.categoria_id);}));
  fillTb('ativos-dash-status',groupCount(function(a){return a.status||'—';}));
  fillTb('ativos-dash-base',groupCount(function(a){return a.base||'—';}));
}
async function ativosListaRender(){
  ativosApplyPermUI();
  await ativosCarregar(!_ativosLoaded);
  ativosPopularFiltroCat();
  var q=((document.getElementById('ativos-fil-q')||{}).value||'').trim().toLowerCase();
  var cat=(document.getElementById('ativos-fil-cat')||{}).value||'';
  var st=(document.getElementById('ativos-fil-status')||{}).value||'';
  var base=((document.getElementById('ativos-fil-base')||{}).value||'').trim().toLowerCase();
  var resp=((document.getElementById('ativos-fil-resp')||{}).value||'').trim().toLowerCase();
  var cond=(document.getElementById('ativos-fil-cond')||{}).value||'';
  var rows=ativosAtivosAtivos().filter(function(a){
    if(cat&&String(a.categoria_id)!==String(cat)) return false;
    if(st&&a.status!==st) return false;
    if(cond&&a.condicao!==cond) return false;
    if(base&&String(a.base||'').toLowerCase().indexOf(base)<0) return false;
    if(resp&&String(a.responsavel_nome||'').toLowerCase().indexOf(resp)<0) return false;
    if(q){
      var blob=[a.codigo_ativo,a.numero_patrimonial,a.descricao,a.marca,a.modelo,a.numero_serie,a.imei,a.placa].join(' ').toLowerCase();
      if(blob.indexOf(q)<0) return false;
    }
    return true;
  });
  var tb=document.getElementById('ativos-tbody'); if(!tb) return;
  var ed=ativosPodeEditar(), ex=ativosPodeExcluir();
  if(!rows.length){ tb.innerHTML='<tr><td colspan="13" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum ativo encontrado.</td></tr>'; return; }
  tb.innerHTML=rows.map(function(a){
    var id=String(a.id||'').replace(/'/g,"\\'");
    var mm=[a.marca,a.modelo].filter(Boolean).join(' / ')||'—';
    var loc=[a.localizacao_tipo,a.localizacao_descricao].filter(Boolean).join(' · ')||'—';
    var mv=typeof ativosPodeMovimentar==='function'&&ativosPodeMovimentar();
    var acoes='<button class="btn btn-sm" onclick="ativosAbrirForm(\''+id+'\',true)" style="font-size:10px">Ver</button> ';
    if(ed) acoes+='<button class="btn btn-sm" onclick="ativosAbrirForm(\''+id+'\')" style="font-size:10px">Editar</button> ';
    if(mv) acoes+='<button class="btn btn-sm" onclick="ativosMovAbrirForm(\''+id+'\')" style="font-size:10px;color:#185FA5;border-color:#B5D0E8">Movimentar</button> ';
    if(ed) acoes+='<button class="btn btn-sm" onclick="ativosManutAbrirForm(null,\''+id+'\')" style="font-size:10px;color:#854F0B;border-color:#E8D5B5">Manutenção</button> ';
    acoes+='<button class="btn btn-sm" onclick="ativosDocsAtivo(\''+id+'\')" style="font-size:10px">Docs</button> ';
    acoes+='<button class="btn btn-sm" onclick="ativosEtiqImprimir([\''+id+'\'])" style="font-size:10px">Etiqueta</button> ';
    acoes+='<button class="btn btn-sm" onclick="ativosHistAtivo(\''+id+'\')" style="font-size:10px">Histórico</button> ';
    if(ex) acoes+='<button class="btn btn-sm" onclick="ativosInativar(\''+id+'\')" style="font-size:10px;color:#A32D2D;border-color:#E1A9A9">Inativar</button>';
    return '<tr>'
      +'<td style="font-family:monospace;font-size:11px">'+escHtml(a.codigo_ativo||'—')+'</td>'
      +'<td style="font-family:monospace;font-size:11px;font-weight:600">'+escHtml(a.numero_patrimonial||'—')+'</td>'
      +'<td style="font-size:12px">'+escHtml(a.descricao||'—')+'</td>'
      +'<td style="font-size:11px">'+escHtml(ativosCatNome(a.categoria_id))+'</td>'
      +'<td style="font-size:11px;color:#666">'+escHtml(mm)+'</td>'
      +'<td style="font-size:11px;font-family:monospace">'+escHtml(a.numero_serie||'—')+'</td>'
      +'<td><span class="bdg" style="font-size:10px">'+escHtml(a.status||'—')+'</span></td>'
      +'<td style="font-size:11px">'+escHtml(a.condicao||'—')+'</td>'
      +'<td style="font-size:11px">'+escHtml(a.base||'—')+'</td>'
      +'<td style="font-size:11px;max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+escHtml(loc)+'">'+escHtml(loc)+'</td>'
      +'<td style="font-size:11px">'+escHtml(a.responsavel_nome||'—')+'</td>'
      +'<td style="text-align:right;font-size:11px">'+ativosFmtR(a.valor_aquisicao)+'</td>'
      +'<td style="white-space:nowrap">'+acoes+'</td></tr>';
  }).join('');
}
function ativosListaExportCsv(){
  var rows=ativosAtivosAtivos();
  if(!rows.length){ progShowToast('Nada para exportar.'); return; }
  var cols=['codigo_ativo','numero_patrimonial','descricao','categoria','marca','modelo','numero_serie','status','condicao','base','localizacao','responsavel_nome','valor_aquisicao'];
  var lines=[cols.join(';')];
  rows.forEach(function(a){
    var loc=[a.localizacao_tipo,a.localizacao_descricao].filter(Boolean).join(' ');
    lines.push([a.codigo_ativo,a.numero_patrimonial,a.descricao,ativosCatNome(a.categoria_id),a.marca,a.modelo,a.numero_serie,a.status,a.condicao,a.base,loc,a.responsavel_nome,a.valor_aquisicao]
      .map(function(x){return '"'+String(x==null?'':x).replace(/"/g,'""')+'"';}).join(';'));
  });
  var blob=new Blob([lines.join('\n')],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download='ativos_inventario_'+new Date().toISOString().slice(0,10)+'.csv'; a.click();
  setTimeout(function(){URL.revokeObjectURL(a.href);},500);
}
function ativosGerarCodigo(){ return 'AT-'+Date.now().toString(36).toUpperCase(); }
function ativosOptsCat(selId){
  return '<option value="">Selecione...</option>'+ativosCatsAtivas().map(function(c){
    return '<option value="'+escHtml(String(c.id))+'"'+(String(c.id)===String(selId||'')?' selected':'')+'>'+escHtml(c.nome)+'</option>';
  }).join('');
}
function ativosOptsList(arr,sel){
  return arr.map(function(s){ return '<option'+(s===sel?' selected':'')+'>'+escHtml(s)+'</option>'; }).join('');
}
function ativosOptsContrato(sel){
  var list=(contratos||[]).filter(function(c){return c.ativo!==false;});
  return '<option value="">—</option>'+list.map(function(c){
    return '<option value="'+escHtml(String(c.id))+'"'+(String(c.id)===String(sel||'')?' selected':'')+'>'+escHtml(c.nome||c.codigo||c.id)+'</option>';
  }).join('');
}
function ativosOptsFornecedor(sel){
  var list=(typeof fornecedores!=='undefined'?fornecedores:[]).slice(0,500);
  return '<option value="">—</option>'+list.map(function(f){
    var id=f.id||f.cnpj||'';
    var nome=f.razao_social||f.nome||f.nome_fantasia||id;
    return '<option value="'+escHtml(String(id))+'"'+(String(id)===String(sel||'')?' selected':'')+'>'+escHtml(nome)+'</option>';
  }).join('');
}
