function ativosG(id){ return ((document.getElementById(id)||{}).value||'').trim(); }
async function ativosSalvar(id){
  if(!ativosPodeEditar()){ progShowToast('Sem permissão.','erro'); return; }
  var desc=ativosG('at-desc');
  if(!desc){ progShowToast('Informe a descrição.','erro'); return; }
  var pat=ativosG('at-pat');
  if(pat){
    var dup=_ativosCache.some(function(a){ return !a.deleted_at&&String(a.numero_patrimonial||'')===pat&&String(a.id)!==String(id||''); });
    if(dup){ progShowToast('Nº patrimonial já cadastrado.','erro'); return; }
  }
  var user=(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||'sistema';
  var payload={
    codigo_ativo:ativosG('at-codigo')||ativosGerarCodigo(), numero_patrimonial:pat||null,
    categoria_id:ativosG('at-cat')||null, subcategoria:ativosG('at-sub')||null, descricao:desc,
    marca:ativosG('at-marca')||null, modelo:ativosG('at-modelo')||null, numero_serie:ativosG('at-serie')||null,
    imei:ativosG('at-imei')||null, placa:ativosG('at-placa')||null, tipo_ativo:ativosG('at-tipo')||null,
    data_aquisicao:ativosG('at-daq')||null, valor_aquisicao:ativosG('at-valor')!==''?Number(ativosG('at-valor')):null,
    fornecedor_id:ativosG('at-forn')||null, numero_nf:ativosG('at-nf')||null,
    vida_util_meses:ativosG('at-vida')!==''?parseInt(ativosG('at-vida'),10):null,
    valor_residual:ativosG('at-residual')!==''?Number(ativosG('at-residual')):null,
    centro_custo:ativosG('at-cc')||null, contrato_id:ativosG('at-contrato')||null, base:ativosG('at-base')||null,
    localizacao_tipo:ativosG('at-loctipo')||null, localizacao_descricao:ativosG('at-locdesc')||null,
    responsavel_tipo:ativosG('at-resptipo')||null, responsavel_nome:ativosG('at-respnome')||null,
    status:ativosG('at-status')||'Disponível', condicao:ativosG('at-cond')||'Bom',
    origem_modulo:ativosG('at-origmod')||null, origem_id:ativosG('at-origid')||null,
    foto_url:ativosG('at-foto')||null, observacoes:ativosG('at-obs')||null,
    updated_at:new Date().toISOString(), updated_by:user
  };
  var btn=document.getElementById('at-salvar');
  if(btn){ btn.disabled=true; btn.textContent='Salvando...'; }
  try{
    if(id){
      if(DEMO){ var ix=_ativosCache.findIndex(function(x){return String(x.id)===String(id);}); if(ix>=0) _ativosCache[ix]=Object.assign({},_ativosCache[ix],payload); }
      else {
        var ok=await sbUpdate('ativos_inventario',payload,'id=eq.'+id);
        if(ok===false) throw new Error('Falha ao atualizar');
        var ix2=_ativosCache.findIndex(function(x){return String(x.id)===String(id);});
        if(ix2>=0) _ativosCache[ix2]=Object.assign({},_ativosCache[ix2],payload);
      }
      progShowToast('Ativo atualizado');
    } else {
      payload.created_by=user; payload.created_at=new Date().toISOString();
      if(DEMO){ payload.id='at-'+Date.now(); _ativosCache.unshift(payload); }
      else {
        var ins=await sbInsert('ativos_inventario',payload);
        if(!ins) throw new Error('Falha ao inserir — rode sql_ativos_inventario_fase1.sql');
        var row=Array.isArray(ins)?ins[0]:ins;
        if(row) _ativosCache.unshift(row); else { _ativosLoaded=false; await ativosCarregar(true); }
      }
      progShowToast('Ativo cadastrado');
    }
    closeModal(); ativosListaRender();
  }catch(e){
    console.warn('[Ativos] salvar',e);
    progShowToast('Erro ao salvar: '+(e&&e.message||e),'erro');
    if(btn){ btn.disabled=false; btn.textContent='Salvar'; }
  }
}
async function ativosInativar(id){
  if(!ativosPodeExcluir()){ progShowToast('Somente admin/gestor.','erro'); return; }
  if(!confirm('Inativar este ativo? Soft-delete (deleted_at).')) return;
  if(DEMO) _ativosCache=_ativosCache.filter(function(a){return String(a.id)!==String(id);});
  else { await sbDelete('ativos_inventario','id=eq.'+id); _ativosCache=_ativosCache.filter(function(a){return String(a.id)!==String(id);}); }
  progShowToast('Ativo inativado.');
  ativosListaRender();
}
async function ativosCatRender(){
  ativosApplyPermUI();
  await ativosCarregar(!_ativosLoaded);
  var tb=document.getElementById('ativos-cat-tbody'); if(!tb) return;
  var rows=(_ativosCatCache||[]).filter(function(c){return !c.deleted_at;});
  var ed=ativosPodeEditar(), ex=ativosPodeExcluir();
  if(!rows.length){ tb.innerHTML='<tr><td colspan="10" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma categoria.</td></tr>'; return; }
  function sn(v){ return v?'Sim':'—'; }
  tb.innerHTML=rows.map(function(c){
    var id=String(c.id||'').replace(/'/g,"\\'");
    var acoes='';
    if(ed) acoes+='<button class="btn btn-sm" onclick="ativosCatAbrirForm(\''+id+'\')" style="font-size:10px">Editar</button> ';
    if(ex) acoes+='<button class="btn btn-sm" onclick="ativosCatInativar(\''+id+'\')" style="font-size:10px;color:#A32D2D;border-color:#E1A9A9">Inativar</button>';
    return '<tr><td style="font-weight:600">'+escHtml(c.nome||'—')+'</td><td style="font-size:11px;color:#666">'+escHtml(c.descricao||'—')+'</td>'
      +'<td style="text-align:center">'+sn(c.exige_numero_serie)+'</td><td style="text-align:center">'+sn(c.exige_termo_responsabilidade)+'</td>'
      +'<td style="text-align:center">'+sn(c.exige_manutencao_preventiva)+'</td><td style="text-align:center">'+sn(c.exige_inventario_periodico)+'</td>'
      +'<td style="text-align:center">'+sn(c.permite_depreciacao)+'</td><td style="text-align:center">'+(c.vida_util_padrao_meses!=null?c.vida_util_padrao_meses:'—')+'</td>'
      +'<td>'+(c.ativo===false?'Inativa':'Ativa')+'</td><td style="white-space:nowrap">'+acoes+'</td></tr>';
  }).join('');
}
