// INVENTARIO ATIVOS FASE5 — QR/etiqueta + depreciação + vínculos
var ATIVOS_ORIGEM_MODULOS=['celulares','ferramentas','frotas_veiculos','almox','outro'];

function ativosQrPayload(a){
  var base=location.href.split('#')[0].split('?')[0];
  return base+'#ativo='+encodeURIComponent(String(a.id||''));
}
function ativosQrImgUrl(text, size){
  size=size||160;
  return 'https://api.qrserver.com/v1/create-qr-code/?size='+size+'x'+size+'&data='+encodeURIComponent(text);
}
function ativosDepreciacaoCalc(a){
  var va=Number(a.valor_aquisicao);
  var vr=Number(a.valor_residual||0);
  var meses=parseInt(a.vida_util_meses,10);
  if(isNaN(va)||va<=0||!meses||meses<=0) return null;
  if(isNaN(vr)||vr<0) vr=0;
  if(vr>va) vr=va;
  var mensal=(va-vr)/meses;
  var decorridos=0;
  if(a.data_aquisicao){
    var d0=new Date(String(a.data_aquisicao).slice(0,10)+'T00:00:00');
    var d1=new Date();
    if(!isNaN(d0.getTime())){
      decorridos=(d1.getFullYear()-d0.getFullYear())*12+(d1.getMonth()-d0.getMonth());
      if(d1.getDate()<d0.getDate()) decorridos--;
      if(decorridos<0) decorridos=0;
    }
  }
  var maxAcum=va-vr;
  var acum=Math.min(decorridos*mensal, maxAcum);
  var cont=va-acum;
  return {
    valor_aquisicao:va, valor_residual:vr, vida_util_meses:meses,
    meses_decorridos:decorridos, deprec_mensal:mensal,
    deprec_acumulada:acum, valor_contabil:cont,
    esgotada:acum>=maxAcum-0.0001
  };
}
function ativosOrigemLabel(mod, id){
  if(!mod&&!id) return '—';
  var nome='';
  if(mod==='celulares'&&typeof _celulares!=='undefined'){
    var c=(_celulares||[]).find(function(x){return String(x.id)===String(id);});
    if(c) nome=(c.numero||c.imei||'')+' '+(c.modelo||c.marca||'');
  } else if(mod==='ferramentas'){
    var list=(typeof ferramentas!=='undefined'?ferramentas:[]).concat(typeof itens_catalogo!=='undefined'?itens_catalogo.filter(function(i){return /ferrament/i.test(String(i.categoria||i.tipo||''));}):[]);
    var f=list.find(function(x){return String(x.id)===String(id);});
    if(f) nome=f.nome||f.descricao||f.codigo||'';
  } else if(mod==='frotas_veiculos'){
    var vlist=(typeof frt_veiculos!=='undefined'&&frt_veiculos.length)?frt_veiculos:(typeof veiculos!=='undefined'?veiculos:[]);
    var v=vlist.find(function(x){return String(x.id)===String(id);});
    if(v) nome=(v.placa||'')+' '+(v.modelo||v.marca||'');
  }
  return (mod||'?')+(id?(' · '+(nome||String(id).slice(0,8))):'');
}
function ativosOptsOrigemIds(mod, sel){
  var opts='<option value="">— selecione —</option>';
  if(mod==='celulares'){
    (typeof _celulares!=='undefined'?_celulares:[]).slice(0,800).forEach(function(c){
      var lab=(c.numero||'')+' — '+(c.modelo||c.marca||c.imei||c.id);
      opts+='<option value="'+escHtml(String(c.id))+'"'+(String(c.id)===String(sel||'')?' selected':'')+'>'+escHtml(lab)+'</option>';
    });
  } else if(mod==='ferramentas'){
    var list=[];
    if(typeof ferramentas!=='undefined'&&ferramentas.length) list=ferramentas;
    else if(typeof itens_catalogo!=='undefined') list=itens_catalogo.filter(function(i){return /ferrament/i.test(String(i.categoria||i.tipo||i.grupo||''));});
    list.slice(0,800).forEach(function(f){
      var lab=(f.codigo||f.patrimonio||'')+' — '+(f.nome||f.descricao||f.id);
      opts+='<option value="'+escHtml(String(f.id))+'"'+(String(f.id)===String(sel||'')?' selected':'')+'>'+escHtml(lab)+'</option>';
    });
  } else if(mod==='frotas_veiculos'){
    var vlist=(typeof frt_veiculos!=='undefined'&&frt_veiculos.length)?frt_veiculos:(typeof veiculos!=='undefined'?veiculos:[]);
    vlist.slice(0,800).forEach(function(v){
      var lab=(v.placa||'')+' — '+(v.modelo||v.marca||v.id);
      opts+='<option value="'+escHtml(String(v.id))+'"'+(String(v.id)===String(sel||'')?' selected':'')+'>'+escHtml(lab)+'</option>';
    });
  }
  return opts;
}

