function ativosEtiqIdsSelecionados(){
  return Array.prototype.slice.call(document.querySelectorAll('.ativos-etiq-chk:checked')).map(function(c){return c.value;});
}
async function ativosEtiqImprimirSelecionados(){
  var ids=ativosEtiqIdsSelecionados();
  if(!ids.length){ progShowToast('Selecione ao menos um ativo.'); return; }
  await ativosEtiqImprimir(ids);
}
async function ativosEtiqImprimir(ids){
  await ativosCarregar(!_ativosLoaded);
  var list=ids.map(function(id){return (_ativosCache||[]).find(function(a){return String(a.id)===String(id);});}).filter(Boolean);
  if(!list.length){ progShowToast('Ativos não encontrados.','erro'); return; }
  var html='<!DOCTYPE html><html><head><meta charset="utf-8"><title>Etiquetas Ativos</title>'
    +'<style>@page{margin:8mm}body{font-family:Arial,sans-serif;margin:0}'
    +'.grid{display:flex;flex-wrap:wrap;gap:8px;padding:8px}'
    +'.lbl{width:70mm;min-height:40mm;border:1px solid #333;border-radius:4px;padding:6px 8px;box-sizing:border-box;display:flex;gap:8px;align-items:center;page-break-inside:avoid}'
    +'.meta{flex:1;font-size:11px;line-height:1.35}.meta b{font-size:13px}.qr{width:28mm;height:28mm}'
    +'@media print{.noprint{display:none}}</style></head><body>'
    +'<div class="noprint" style="padding:8px"><button onclick="window.print()">Imprimir</button></div><div class="grid">';
  list.forEach(function(a){
    var url=ativosQrPayload(a);
    var desc=(a.descricao||'').slice(0,60);
    html+='<div class="lbl"><div class="meta">'
      +'<div style="font-size:10px;color:#555">CENA BR</div>'
      +'<b>'+escHtml(a.numero_patrimonial||a.codigo_ativo||'S/N')+'</b><br>'
      +escHtml(desc)+'<br>'
      +'<span style="font-size:9px;color:#666">'+escHtml(a.codigo_ativo||'')+'</span>'
      +'</div><img class="qr" src="'+ativosQrImgUrl(url,180)+'" alt="QR"/></div>';
  });
  html+='</div></body></html>';
  var w=window.open('','_blank','width=900,height=700');
  if(!w){ progShowToast('Permita pop-ups para imprimir.','erro'); return; }
  w.document.write(html); w.document.close();
  var user=(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||'sistema';
  var now=new Date().toISOString();
  for(var i=0;i<list.length;i++){
    var a=list[i];
    var upd={etiqueta_gerada_em:now,updated_at:now,updated_by:user};
    if(DEMO){
      var ix=_ativosCache.findIndex(function(x){return String(x.id)===String(a.id);});
      if(ix>=0) _ativosCache[ix]=Object.assign({},_ativosCache[ix],upd);
    } else {
      try{ await sbUpdate('ativos_inventario',upd,'id=eq.'+a.id); }catch(e){}
      var ix2=_ativosCache.findIndex(function(x){return String(x.id)===String(a.id);});
      if(ix2>=0) _ativosCache[ix2]=Object.assign({},_ativosCache[ix2],upd);
    }
  }
  if(document.getElementById('pg-ativos-etiquetas')&&!document.getElementById('pg-ativos-etiquetas').classList.contains('hidden')) ativosEtiqRender();
}

async function ativosDeprecRender(){
  ativosApplyPermUI();
  await ativosCarregar(!_ativosLoaded);
  var soDep=document.getElementById('ativos-deprec-so')&&document.getElementById('ativos-deprec-so').checked;
  var q=((document.getElementById('ativos-deprec-q')||{}).value||'').trim().toLowerCase();
  var rows=ativosAtivosAtivos().map(function(a){
    var calc=ativosDepreciacaoCalc(a);
    return {a:a, calc:calc};
  }).filter(function(r){
    if(soDep&&!r.calc) return false;
    if(q){
      var blob=[r.a.codigo_ativo,r.a.numero_patrimonial,r.a.descricao].join(' ').toLowerCase();
      if(blob.indexOf(q)<0) return false;
    }
    return true;
  });
  var tb=document.getElementById('ativos-deprec-tbody'); if(!tb) return;
  var totAq=0, totAc=0, totCb=0, n=0;
  if(!rows.length){ tb.innerHTML='<tr><td colspan="9" style="text-align:center;color:#aaa;padding:1.5rem">Sem dados.</td></tr>'; return; }
  tb.innerHTML=rows.map(function(r){
    var a=r.a, c=r.calc;
    if(c){ totAq+=c.valor_aquisicao; totAc+=c.deprec_acumulada; totCb+=c.valor_contabil; n++; }
    return '<tr>'
      +'<td style="font-size:11px;font-family:monospace">'+escHtml(a.codigo_ativo||'—')+'</td>'
      +'<td style="font-size:12px">'+escHtml(a.descricao||'—')+'</td>'
      +'<td style="font-size:11px">'+(a.data_aquisicao||'—')+'</td>'
      +'<td style="text-align:right;font-size:11px">'+ativosFmtR(a.valor_aquisicao)+'</td>'
      +'<td style="text-align:center;font-size:11px">'+(a.vida_util_meses!=null?a.vida_util_meses:'—')+'</td>'
      +'<td style="text-align:right;font-size:11px">'+(c?ativosFmtR(c.deprec_mensal):'—')+'</td>'
      +'<td style="text-align:right;font-size:11px">'+(c?ativosFmtR(c.deprec_acumulada):'—')+'</td>'
      +'<td style="text-align:right;font-size:11px;font-weight:600">'+(c?ativosFmtR(c.valor_contabil):'—')+'</td>'
      +'<td style="font-size:11px">'+(c?(c.esgotada?'Esgotada':(c.meses_decorridos+' meses')):'Sem vida útil/valor')+'</td></tr>';
  }).join('');
  var sum=document.getElementById('ativos-deprec-sum');
  if(sum) sum.textContent=n+' ativos calculados · Aquisição '+ativosFmtR(totAq)+' · Deprec. acum. '+ativosFmtR(totAc)+' · Valor contábil '+ativosFmtR(totCb);
  window._ativosDeprecLast=rows;
}
function ativosDeprecExport(){
  var rows=window._ativosDeprecLast||[];
  if(!rows.length){ progShowToast('Gere a lista primeiro.'); return; }
  var data=[['Código','Patrimônio','Descrição','Data aq.','Valor aq.','Residual','Vida útil','Meses decorridos','Deprec. mensal','Deprec. acum.','Valor contábil']];
  rows.forEach(function(r){
    var a=r.a, c=r.calc||{};
    data.push([a.codigo_ativo,a.numero_patrimonial,a.descricao,a.data_aquisicao,a.valor_aquisicao,a.valor_residual,a.vida_util_meses,c.meses_decorridos,c.deprec_mensal,c.deprec_acumulada,c.valor_contabil]);
  });
  if(typeof ativosExportDownload==='function') ativosExportDownload('ativos_depreciacao.xlsx', data, 'Depreciacao');
  else progShowToast('Exportação indisponível.');
}

async function ativosVincRender(){
  ativosApplyPermUI();
  await ativosCarregar(!_ativosLoaded);
  // best-effort load helpers
  if(typeof _celulares!=='undefined'&&(!_celulares||!_celulares.length)&&typeof sbFetch==='function'&&!DEMO){
    try{ var cels=await sbFetch('celulares_empresa',{order:'numero',limit:2000}); if(cels) _celulares=cels; }catch(e){}
  }
  var q=((document.getElementById('ativos-vinc-q')||{}).value||'').trim().toLowerCase();
  var so=(document.getElementById('ativos-vinc-fil')||{}).value||'';
  var rows=ativosAtivosAtivos().filter(function(a){
    if(so==='com'&&!(a.origem_modulo||a.origem_id)) return false;
    if(so==='sem'&&(a.origem_modulo||a.origem_id)) return false;
    if(q){
      var blob=[a.codigo_ativo,a.descricao,a.origem_modulo,a.origem_id].join(' ').toLowerCase();
      if(blob.indexOf(q)<0) return false;
    }
    return true;
  });
  var tb=document.getElementById('ativos-vinc-tbody'); if(!tb) return;
  var ed=ativosPodeEditar();
  if(!rows.length){ tb.innerHTML='<tr><td colspan="5" style="text-align:center;color:#aaa;padding:1.5rem">Nenhum ativo.</td></tr>'; return; }
  tb.innerHTML=rows.map(function(a){
    var id=String(a.id||'').replace(/'/g,"\\'");
    return '<tr>'
      +'<td style="font-size:11px;font-family:monospace">'+escHtml(a.codigo_ativo||'—')+'</td>'
      +'<td style="font-size:12px">'+escHtml(a.descricao||'—')+'</td>'
      +'<td style="font-size:11px">'+escHtml(ativosOrigemLabel(a.origem_modulo,a.origem_id))+'</td>'
      +'<td style="font-size:11px">'+escHtml(a.status||'—')+'</td>'
      +'<td>'+(ed?'<button class="btn btn-sm" onclick="ativosVincAbrir(\''+id+'\')" style="font-size:10px">Vincular</button>':'')+'</td></tr>';
  }).join('');
  // candidatos informativos
  var box=document.getElementById('ativos-vinc-candidatos'); if(!box) return;
  var linked={};
  ativosAtivosAtivos().forEach(function(a){ if(a.origem_modulo&&a.origem_id) linked[a.origem_modulo+'|'+a.origem_id]=1; });
  var cand=[];
  (typeof _celulares!=='undefined'?_celulares:[]).slice(0,50).forEach(function(c){
    if(!linked['celulares|'+c.id]) cand.push({mod:'celulares',id:c.id,lab:'📱 '+(c.numero||'')+' '+(c.modelo||'')});
  });
  var vlist=(typeof frt_veiculos!=='undefined'&&frt_veiculos.length)?frt_veiculos:[];
  vlist.slice(0,30).forEach(function(v){
    if(!linked['frotas_veiculos|'+v.id]) cand.push({mod:'frotas_veiculos',id:v.id,lab:'🚗 '+(v.placa||'')+' '+(v.modelo||'')});
  });
  if(typeof ferramentas!=='undefined'){
    ferramentas.slice(0,30).forEach(function(f){
      if(!linked['ferramentas|'+f.id]) cand.push({mod:'ferramentas',id:f.id,lab:'🔧 '+(f.nome||f.descricao||f.id)});
    });
  }
  box.innerHTML='<div style="font-size:12px;font-weight:600;margin-bottom:.4rem">Candidatos sem vínculo no inventário (somente leitura — sem migração)</div>'
    +(cand.length?('<div style="display:flex;flex-wrap:wrap;gap:6px">'+cand.slice(0,40).map(function(x){
      return '<span style="font-size:11px;background:#F8F6F0;padding:3px 8px;border-radius:6px">'+escHtml(x.lab)+'</span>';
    }).join('')+'</div>'):'<div style="font-size:11px;color:#888">Nenhum candidato carregado (abra Cadastros/Celulares ou Frotas para popular cache).</div>')
    +'<div style="font-size:11px;color:#888;margin-top:.5rem">Use Vincular em um ativo existente para apontar origem_modulo/origem_id. Não cria cópia dos registros.</div>';
}
function ativosVincAbrir(ativoId){
  if(!ativosPodeEditar()){ progShowToast('Sem permissão.','erro'); return; }
  var a=(_ativosCache||[]).find(function(x){return String(x.id)===String(ativoId);})||{};
  var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:480px">'
    +'<h3 style="margin:0 0 .75rem">Vínculo — '+escHtml(a.descricao||'')+'</h3>'
    +'<div class="fg" style="margin-bottom:.5rem"><label style="font-size:11px;font-weight:600">Módulo de origem</label>'
    +'<select class="inp" id="atv-mod" style="width:100%" onchange="ativosVincOnMod()">'
    +'<option value="">—</option>'+ATIVOS_ORIGEM_MODULOS.map(function(m){return '<option'+(m===(a.origem_modulo||'')?' selected':'')+'>'+m+'</option>';}).join('')
    +'</select></div>'
    +'<div class="fg" style="margin-bottom:.5rem"><label style="font-size:11px;font-weight:600">Registro de origem</label>'
    +'<select class="inp" id="atv-id" style="width:100%">'+ativosOptsOrigemIds(a.origem_modulo||'',a.origem_id||'')+'</select></div>'
    +'<div class="fg" style="margin-bottom:.75rem"><label style="font-size:11px;font-weight:600">ID manual (se não listar)</label>'
    +'<input class="inp" id="atv-idman" style="width:100%" value="'+escHtml(a.origem_id||'')+'"/></div>'
    +'<div style="display:flex;gap:8px"><button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn" onclick="ativosVincSalvar(\''+String(ativoId).replace(/'/g,"\\'")+'\',true)" style="flex:1">Limpar</button>'
    +'<button class="btn btn-pri" id="atv-salvar" style="flex:1.5">Salvar</button></div></div></div>';
  setModal(html);
  setTimeout(function(){
    var btn=document.getElementById('atv-salvar');
    if(btn) btn.onclick=function(){ ativosVincSalvar(ativoId,false); };
  },40);
}
function ativosVincOnMod(){
  var mod=ativosG('atv-mod');
  var sel=document.getElementById('atv-id');
  if(sel) sel.innerHTML=ativosOptsOrigemIds(mod,'');
}
async function ativosVincSalvar(ativoId, limpar){
  if(!ativosPodeEditar()) return;
  var user=(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||'sistema';
  var payload={
    origem_modulo:limpar?null:(ativosG('atv-mod')||null),
    origem_id:limpar?null:(ativosG('atv-id')||ativosG('atv-idman')||null),
    updated_at:new Date().toISOString(), updated_by:user
  };
  try{
    if(DEMO){
      var ix=_ativosCache.findIndex(function(x){return String(x.id)===String(ativoId);});
      if(ix>=0) _ativosCache[ix]=Object.assign({},_ativosCache[ix],payload);
    } else {
      var ok=await sbUpdate('ativos_inventario',payload,'id=eq.'+ativoId);
      if(ok===false) throw new Error('Falha ao salvar');
      var ix2=_ativosCache.findIndex(function(x){return String(x.id)===String(ativoId);});
      if(ix2>=0) _ativosCache[ix2]=Object.assign({},_ativosCache[ix2],payload);
    }
    progShowToast(limpar?'Vínculo removido':'Vínculo salvo');
    closeModal(); ativosVincRender();
  }catch(e){ progShowToast('Erro: '+(e&&e.message||e),'erro'); }
}

function ativosDeepLinkFromHash(){
  var m=(window.location.hash||'').match(/^#ativo=([^&]+)/i);
  if(!m) return;
  var id=decodeURIComponent(m[1]);
  if(!id||!usuarioLogado) return;
  try{
    if(typeof showMain==='function') showMain('inventario-ativos');
    if(typeof showPage==='function') showPage('ativos-lista');
    setTimeout(function(){
      if(typeof ativosCarregar==='function'){
        ativosCarregar(true).then(function(){
          if(typeof ativosAbrirForm==='function') ativosAbrirForm(id,true);
        });
      }
    },400);
  }catch(e){ console.warn('[Ativos] deeplink',e); }
}
if(typeof document!=='undefined'){
  document.addEventListener('cena:logged-in', function(){ setTimeout(ativosDeepLinkFromHash, 600); });
  window.addEventListener('hashchange', function(){ if(usuarioLogado) ativosDeepLinkFromHash(); });
}




