function sesmtVoltar(){
  // Garantir que o módulo está marcado como carregado antes de navegar
  _mainAtual = 'sesmt';
  // Ocultar todas as páginas SESMT
  ocultarPaginasSESMTAlmoxarifado();
  // Mostrar sidebar com itens do SESMT
  sidebarMostrarItens('sesmt', _subAtual['sesmt'] || 'sesmt-dashboard');
  // Navegar para o último sub visitado ou o dashboard
  var destino = _subAtual['sesmt'] || 'sesmt-dashboard';
  _precisaModulo('sesmt', function(){
    showSub(destino);
  });
}

