  ferramentas:'almoxarifado', estoque:'almoxarifado', alm_movimentos:'almoxarifado', alm_estoque:'almoxarifado',
  celulares_empresa:'operacional', uniformes:'almoxarifado', locacoes:'almoxarifado', depositos:'almoxarifado', filiais:'almoxarifado',
  composicao_dia:'operacional', prog_status_diario:'operacional', sessoes_disponibilidade:'operacional',
  prog_escala_modelo:'operacional', plpt_prog_dia:'operacional', plpt_equipe_membros:'operacional', plpt_prog_projetos:'operacional',
  equipes_disp:'cadastros', equipes:'cadastros', escalas_cad:'cadastros', sesmt_cursos:'cadastros', cargos:'cadastros',
  rh_cargo_requisitos:'rh', rh_cargo_requisitos_cnh:'rh', rh_cargo_requisitos_nrs:'rh',
  rh_cargo_requisitos_treinamentos:'rh', rh_cargo_requisitos_documentos:'rh', rh_cargo_requisitos_testes:'rh',
  rh_vagas:'rh', rh_vaga_candidatos:'rh', rh_candidato_entrevistas:'rh',
  rh_candidato_integridade:'rh', rh_candidato_integridade_itens:'rh', rh_integridade_fontes:'rh',
  rh_candidato_resultado_selecao:'rh',
  rh_testes:'rh', rh_teste_questoes:'rh', rh_teste_tentativas:'rh', rh_teste_resultados:'rh',
