function showTab(name){
  // mapear nome antigo para novo sistema
  var mainMap = {
    dashboard:'dashboard', contratos:'contratos', verbas:'operacional',
    lancamentos:'movimentacao', aprovacao:'movimentacao',
    relatorios:'relatorios', cadastros:'cadastros',
    produtividade:'operacional', adiantamentos:'contratos', operacional:'operacional',
  };
  var subMap = {
    contratos:'contratos-lista', verbas:'verbas',
    lancamentos:'lancamentos', aprovacao:'aprovacao',
    produtividade:'metas', adiantamentos:'adiantamentos',
    operacional:'operacional-prod',
  };
  var main = mainMap[name] || name;
  _mainAtual = main;
  showMain(main);
  if(subMap[name]) showSub(subMap[name]);
}


