function renderExecucao(){
  var selProj = document.getElementById('fil-exec-proj');
  // Popular select de projetos se ainda não populado
  if(selProj && selProj.options.length <= 1){
    selProj.innerHTML = '<option value="">Todos os projetos</option>'
      + projetos.map(function(p){ return '<option value="'+p.id+'">'+p.codigo+' — '+p.nome+'</option>'; }).join('');
  }

  var pid = (selProj||{}).value||'';
  var statusFil = (document.getElementById('fil-exec-status')||{}).value||'';

  var rows = execucoes.filter(function(e){
    if(pid && e.projeto_id !== pid) return false;
    if(statusFil && e.status_exec !== statusFil) return false;
    return true;
  });

  // Métricas
  var metr = document.getElementById('exec-metricas');
  if(metr){
    var total   = rows.length;
    var emExec  = rows.filter(function(e){ return e.status_exec==='Em execução'; }).length;
    var concl   = rows.filter(function(e){ return e.status_exec==='Totalmente executado'; }).length;
    var parcial = rows.filter(function(e){ return e.status_exec==='Parcialmente executado'; }).length;
    metr.innerHTML = [
      {l:'Total de registros', v:total,   c:'#555'},
      {l:'Em execução',        v:emExec,  c:'#185FA5'},
      {l:'Totalmente exec.',   v:concl,   c:'#3B6D11'},
      {l:'Parcialmente',       v:parcial, c:'#854F0B'},
    ].map(function(m){
      return '<div class="card" style="padding:.5rem;text-align:center">'
        +'<div style="font-size:10px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:20px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }

  var stCls = {'Totalmente executado':'teal','Parcialmente executado':'warn','Não iniciado':'gray','Em execução':'ok'};
  var tb = document.getElementById('tbody-exec'); if(!tb) return;

  if(!rows.length){
    tb.innerHTML = '<tr><td colspan="9" style="padding:2rem;text-align:center;color:#aaa">'
      +(execucoes.length ? 'Nenhum registro para os filtros selecionados.'
        : 'Nenhum registro de execução. Clique em <strong>+ Novo registro</strong> para começar.')
      +'</td></tr>';
    return;
  }

  tb.innerHTML = rows.map(function(e){
    var servs = exec_servicos.filter(function(s){return s.execucao_id===e.id;}).length;
    var mats  = mov_sap.filter(function(m){return m.projeto_id===e.projeto_id&&m.tipo!=='Devolução';}).length;
    var nFotos= e.fotos ? e.fotos.length : 0;
    return '<tr>'
      +'<td style="font-size:11px">'+fmtD(e.data)+'</td>'
      +'<td style="font-size:11px">'+fNomeProj(e.projeto_id)+'</td>'
      +'<td style="font-size:11px">'+e.nome_enc+'</td>'
      +'<td>'+e.atividade+'</td>'
      +'<td><span class="bdg '+(stCls[e.status_exec]||'gray')+'">'+e.status_exec+'</span></td>'
      +'<td style="text-align:center">'+(e.origem==='PLPT'?'<span class="bdg info" style="font-size:10px">⚡ PLPT</span>':'<span class="bdg gray" style="font-size:10px">Campo</span>')+'</td>'
      +'<td style="text-align:center">'+servs+'</td>'
      +'<td style="text-align:center">'+mats+'</td>'
      +'<td style="text-align:center">'+(nFotos?'📷 '+nFotos:'—')+'</td>'
      +'<td><button class="btn btn-sm" onclick="openVerExecucao(\''+e.id+'\')">Ver</button></td>'
      +'</tr>';
  }).join('');
}

function openNovaExecucao(pid_pre){
  var projOpts=projetos.map(function(p){return '<option value="'+p.id+'"'+(p.id===pid_pre?' selected':'')+'>'+p.codigo+' — '+p.nome+'</option>';}).join('');
  var stOpts=['Não iniciado','Em execução','Parcialmente executado','Totalmente executado'].map(function(s){return '<option>'+s+'</option>';}).join('');
  setModal('<div class="modal-bg"><div class="modal" style="max-width:560px"><h3>Novo Registro de Execução</h3>'    +'<div class="g2">'    +'<div class="fg" style="grid-column:1/-1"><label>Projeto</label><select id="ne-proj">'+projOpts+'</select></div>'    +'<div class="fg" style="grid-column:1/-1"><label>Encarregado</label><input id="ne-enc" placeholder="Nome do encarregado"/></div>'    +'<div class="fg"><label>Data</label><input id="ne-data" type="date" value="'+dataHojeLocal()+'"/></div>'    +'<div class="fg"><label>Status execução</label><select id="ne-st">'+stOpts+'</select></div>'    +'<div class="fg" style="grid-column:1/-1"><label>Descrição da atividade</label><input id="ne-atv" placeholder="Descreva o que foi executado"/></div>'    +'</div>'    +'<div class="fg"><label>Observações / Relatório</label><textarea id="ne-obs" style="height:80px"></textarea></div>'    +'<div class="fg"><label>📷 Fotos (tire com o celular)</label><input id="ne-fotos" type="file" accept="image/*" multiple capture="environment" style="font-size:12px"/></div>'    +'<div id="ne-fotos-prev" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"></div>'    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-salvar-exec">Salvar</button></div></div></div>');
  // Preview fotos
  document.getElementById('ne-fotos').onchange=function(ev){
    var prev=document.getElementById('ne-fotos-prev');prev.innerHTML='';
    Array.from(ev.target.files).forEach(function(f){
      var url=URL.createObjectURL(f);
      prev.innerHTML+='<img src="'+url+'" style="width:60px;height:60px;object-fit:cover;border-radius:6px;border:.5px solid #e0dfd8"/>';
    });
  };
  document.getElementById('btn-salvar-exec').onclick=async function(){
    var pid=(document.getElementById('ne-proj')||{}).value||'';
    var enc=(document.getElementById('ne-enc')||{}).value.trim()||'';
    var atv=(document.getElementById('ne-atv')||{}).value.trim()||'';
    if(!pid||!enc||!atv)return alert('Preencha projeto, encarregado e atividade.');
    var fotosUrls=[];
    var arquivos=document.getElementById('ne-fotos').files;
    if(arquivos&&arquivos.length&&!DEMO){
      for(var i=0;i<arquivos.length;i++){
        var url=await sbUpload(arquivos[i],'obras/'+pid+'/'+Date.now()+'_'+arquivos[i].name);
        if(url)fotosUrls.push(url);
      }
    }
    var novo={id:'ex'+Date.now(),projeto_id:pid,encarregado_id:'',nome_enc:enc,
      data:(document.getElementById('ne-data')||{}).value||dataHojeLocal(),
      atividade:atv,
      status_exec:(document.getElementById('ne-st')||{}).value||'Em execução',
      obs:(document.getElementById('ne-obs')||{}).value||'',
      fotos:fotosUrls};
    execucoes.push(novo);
    if(!DEMO)sbInsert('execucoes_obra',Object.assign({},novo,{fotos:JSON.stringify(fotosUrls),id:undefined}));
    closeModal();renderExecucao();
  };
}

function openVerExecucao(eid){
  var e=execucoes.find(function(x){return x.id===eid;});if(!e)return;
  var servs=exec_servicos.filter(function(s){return s.execucao_id===eid;});
  var stCls={'Totalmente executado':'teal','Parcialmente executado':'warn','Não iniciado':'gray','Em execução':'ok'};
  var fotosHtml=(e.fotos&&e.fotos.length)?'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px">'    +e.fotos.map(function(u){return '<a href="'+u+'" target="_blank"><img src="'+u+'" style="width:70px;height:70px;object-fit:cover;border-radius:6px;border:.5px solid #e0dfd8"/></a>';}).join('')    +'</div>':'<span style="color:#aaa;font-size:12px">Sem fotos</span>';
  var servsHtml=servs.length?'<table class="tbl"><thead><tr><th>Serviço</th><th>Qtd</th><th>Un.</th><th>Valor unit.</th><th>Total</th></tr></thead><tbody>'    +servs.map(function(s){return '<tr><td>'+s.descricao+'</td><td>'+s.qtd+'</td><td>'+(s.unidade||'—')+'</td><td>'+fmtR(s.valor_unit)+'</td><td style="font-weight:500">'+fmtR(s.qtd*s.valor_unit)+'</td></tr>';}).join('')    +'</tbody></table>':'<span style="color:#aaa;font-size:12px">Nenhum serviço lançado</span>';
  setModal('<div class="modal-bg"><div class="modal" style="max-width:620px"><h3>Execução — '+fNomeProj(e.projeto_id)+'</h3>'    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:.75rem">'    +'<span class="bdg info">'+fmtD(e.data)+'</span>'    +'<span class="bdg gray">'+e.nome_enc+'</span>'    +'<span class="bdg '+(stCls[e.status_exec]||'gray')+'">'+e.status_exec+'</span>'    +'</div>'    +'<div style="font-size:13px;font-weight:500;margin-bottom:.5rem">'+e.atividade+'</div>'    +(e.obs?'<div style="font-size:12px;color:#555;background:#f9f9f7;border-radius:8px;padding:.75rem;margin-bottom:.75rem">'+e.obs+'</div>':'')    +'<div style="font-size:11px;font-weight:600;color:#888;margin-bottom:.5rem">SERVIÇOS EXECUTADOS</div>'    +servsHtml    +'<div style="font-size:11px;font-weight:600;color:#888;margin:.75rem 0 .5rem">FOTOS</div>'    +fotosHtml    +'<div class="ma">'    +'<button class="btn" id="btn-add-serv-exec">+ Serviço</button>'    +'<button class="btn" id="btn-add-foto-exec">+ Foto</button>'    +'<button class="btn btn-pri" onclick="closeModal()">Fechar</button>'    +'</div></div></div>');
  document.getElementById('btn-add-serv-exec').onclick=function(){openAdicionarServicoExec(eid);};
  document.getElementById('btn-add-foto-exec').onclick=function(){openAdicionarFotoExec(eid);};
}

function openAdicionarServicoExec(eid){
  var e=execucoes.find(function(x){return x.id===eid;});if(!e)return;
  var proj=projetos.find(function(x){return x.id===e.projeto_id;});
  var servsCont=servicos.filter(function(s){return s.contrato_id===(proj?proj.contrato_id:'');});
  var servOpts=servsCont.length?servsCont.map(function(s){return '<option value="'+s.id+'" data-desc="'+s.descricao+'" data-uni="'+(s.unidade||'UN')+'" data-val="'+(s.valor_ups||0)+'">'+s.codigo+' — '+s.descricao+'</option>';}).join(''):'<option value="">Nenhum serviço cadastrado</option>';
  setModal('<div class="modal-bg"><div class="modal"><h3>Lançar Serviço Executado</h3>'    +'<div class="fg"><label>Serviço</label><select id="es-serv" onchange="preencherServicoExec()">'+servOpts+'</select></div>'    +'<div class="g2">'    +'<div class="fg"><label>Qtd executada</label><input id="es-qtd" type="number" step="0.01" placeholder="0"/></div>'    +'<div class="fg"><label>Valor unitário (R$)</label><input id="es-val" type="number" step="0.01" placeholder="0,00"/></div>'    +'</div>'    +'<div class="ma"><button class="btn" onclick="openVerExecucao(\''+eid+'\')">Voltar</button>'    +'<button class="btn btn-pri" id="btn-salvar-es">Salvar</button></div></div></div>');
  preencherServicoExec();
  document.getElementById('btn-salvar-es').onclick=function(){
    var sel=document.getElementById('es-serv');
    var opt=sel?sel.options[sel.selectedIndex]:null;
    var novo={id:'es'+Date.now(),execucao_id:eid,
      servico_id:(sel||{}).value||'',
      descricao:opt?opt.text:'',
      unidade:opt?opt.getAttribute('data-uni')||'UN':'UN',
      qtd:parseFloat((document.getElementById('es-qtd')||{}).value)||0,
      valor_unit:parseFloat((document.getElementById('es-val')||{}).value)||0};
    if(!novo.qtd)return alert('Informe a quantidade.');
    exec_servicos.push(novo);
    if(!DEMO)sbInsert('exec_servicos',_semId(novo));
    openVerExecucao(eid);
  };
}

function preencherServicoExec(){
  var sel=document.getElementById('es-serv');if(!sel)return;
  var opt=sel.options[sel.selectedIndex];
  var val=document.getElementById('es-val');
  if(val&&opt)val.value=opt.getAttribute('data-val')||'';
}

function openAdicionarFotoExec(eid){
  setModal('<div class="modal-bg"><div class="modal"><h3>Adicionar Fotos</h3>'    +'<div class="fg"><label>📷 Selecionar / tirar fotos</label><input id="add-fotos" type="file" accept="image/*" multiple capture="environment" style="font-size:12px"/></div>'    +'<div id="add-fotos-prev" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"></div>'    +'<div class="ma"><button class="btn" onclick="openVerExecucao(\''+eid+'\')">Cancelar</button>'    +'<button class="btn btn-pri" id="btn-salvar-fotos">Salvar fotos</button></div></div></div>');
  document.getElementById('add-fotos').onchange=function(ev){
    var prev=document.getElementById('add-fotos-prev');prev.innerHTML='';
    Array.from(ev.target.files).forEach(function(f){
      var url=URL.createObjectURL(f);
      prev.innerHTML+='<img src="'+url+'" style="width:70px;height:70px;object-fit:cover;border-radius:6px;border:.5px solid #e0dfd8"/>';
    });
  };
  document.getElementById('btn-salvar-fotos').onclick=async function(){
    var e=execucoes.find(function(x){return x.id===eid;});if(!e)return;
    var arquivos=document.getElementById('add-fotos').files;
    if(!arquivos||!arquivos.length)return alert('Selecione ao menos uma foto.');
    if(!e.fotos)e.fotos=[];
    if(!DEMO){
      for(var i=0;i<arquivos.length;i++){
        var url=await sbUpload(arquivos[i],'obras/'+e.projeto_id+'/'+Date.now()+'_'+arquivos[i].name);
        if(url)e.fotos.push(url);
      }
      sbUpdate('execucoes_obra',{fotos:JSON.stringify(e.fotos)},'id=eq.'+eid);
    }
    openVerExecucao(eid);
  };
}

// MOVIMENTAÇÃO SAP
function _movSapEnsureUi(){
  var wrap=document.getElementById('movsap-wrap');
  if(!wrap||document.getElementById('tbody-movsap')) return;
  wrap.innerHTML='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:1rem;padding:0 .5rem">'
    +'<select class="inp" id="fil-movsap-proj" style="width:220px" onchange="renderMovSAP()"><option value="">Todos projetos</option></select>'
    +'<input class="inp" id="fil-movsap-enc" placeholder="Buscar encarregado, OS, material..." style="flex:1;min-width:160px" oninput="renderMovSAP()"/>'
    +'</div>'
    +'<div style="overflow-x:auto;padding:0 .5rem"><table class="tbl tbl-responsive"><thead><tr>'
    +'<th>Data</th><th>Projeto</th><th>OS</th><th>Material</th><th>Qtd</th><th>Retirada</th><th>Baixa</th><th>Devolução</th><th>Almox.</th><th>Encarregado</th><th>Status</th><th></th>'
    +'</tr></thead><tbody id="tbody-movsap"></tbody></table></div>'
    +'<div style="margin-top:1.5rem;padding:0 .5rem"><div style="font-size:13px;font-weight:600;margin-bottom:.5rem">Saldo por encarregado</div><div id="saldo-enc-wrap"></div></div>';
}
function renderMovSAP(){
  _movSapEnsureUi();
  popularFiltrosMovSAP();
  var pid=(document.getElementById('fil-movsap-proj')||{}).value||'';
  var busca=((document.getElementById('fil-movsap-enc')||{}).value||'').toLowerCase();
  var agora=Date.now();
  var rows=mov_sap.filter(function(m){
    if(pid&&m.projeto_id!==pid)return false;
    if(busca){
      var txt=(m.nome_enc+' '+(m.funcao_operacional||'')+' '+(m.ordem_id||'')+' '+m.descricao_mat).toLowerCase();
      if(txt.indexOf(busca)<0)return false;
    }
    return true;
  });
  // Status sequência lógica
  var stOrd={'Aguardando Retirada':0,'Em Campo':1,'Confirmado':2};
  var stCls={'Aguardando Retirada':'warn','Em Campo':'info','Confirmado':'ok'};
  var tb=document.getElementById('tbody-movsap');if(!tb)return;
  tb.innerHTML=rows.map(function(m){
    // Alerta 24h: material "Em Campo" há mais de 24h
    var alerta24='';
    if(m.status==='Em Campo'&&m.data){
      var dataMs=new Date(m.data+'T00:00:00').getTime();
      var diff=(agora-dataMs)/3600000;
      if(diff>24)alerta24='<span class="bdg danger" style="font-size:10px;margin-left:4px" title="Material em campo há mais de 24h sem movimentação">⚠ +24h</span>';
    }
    var osLbl=m.ordem_id?('#'+m.ordem_id):(m.funcao_operacional&&m.funcao_operacional.indexOf('OS #')===0?m.funcao_operacional.replace('OS ',''):'—');
    return '<tr'+(m.status==='Em Campo'&&alerta24?' style="background:#FFF8E1"':'')+'>'
      +'<td style="font-size:11px">'+fmtD(m.data)+'</td>'
      +'<td style="font-size:11px">'+fNomeProj(m.projeto_id)+'</td>'
      +'<td style="font-size:11px;font-weight:600;color:#185FA5">'+osLbl+'</td>'
      +'<td style="font-weight:500">'+m.descricao_mat+'</td>'
      +'<td style="font-size:11px">'+m.qtd+' '+(m.unidade||'')+'</td>'
      +'<td style="font-size:11px;color:#888">'+(m.tipo==='Retirada'?m.qtd:'-')+'</td>'
      +'<td style="font-size:11px;color:#888">'+(m.tipo==='Baixa aplicação'?m.qtd:'-')+'</td>'
      +'<td style="font-size:11px;color:#888">'+(m.tipo==='Devolução'?m.qtd:'-')+'</td>'
      +'<td style="font-size:11px">'+(m.resp_almox||'—')+'</td>'
      +'<td style="font-size:11px">'+(m.nome_enc||'—')+'</td>'
      +'<td><span class="bdg '+(stCls[m.status]||'gray')+'">'+m.status+'</span>'+alerta24+'</td>'
      +'<td style="display:flex;gap:4px">'
      +(m.status==='Aguardando Retirada'?'<button class="btn btn-sm" id="ms-ret-'+m.id+'" style="font-size:10px">Retirar</button>':'')
      +(m.status==='Em Campo'?'<button class="btn btn-sm" id="ms-conf-'+m.id+'" style="font-size:10px;color:#3B6D11;border-color:#3B6D11">Confirmar</button>':'')
      +'</td></tr>';
  }).join('')||'<tr><td colspan="12" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma movimentação</td></tr>';
  // Vincular botões
  rows.forEach(function(m){
    var br=document.getElementById('ms-ret-'+m.id);
    if(br)br.onclick=function(){m.status='Em Campo';if(!DEMO)sbUpdate('mov_sap',{status:'Em Campo'},'id=eq.'+m.id);renderMovSAP();};
    var bc=document.getElementById('ms-conf-'+m.id);
    if(bc)bc.onclick=function(){m.status='Confirmado';if(!DEMO)sbUpdate('mov_sap',{status:'Confirmado'},'id=eq.'+m.id);renderMovSAP();};
  });

  // Saldo por encarregado
  var saldoMap={};
  rows.forEach(function(m){
    var key=m.nome_enc+'||'+m.descricao_mat;
    if(!saldoMap[key])saldoMap[key]={enc:m.nome_enc,mat:m.descricao_mat,uni:m.unidade,ret:0,baixa:0,dev:0};
    if(m.tipo==='Retirada')saldoMap[key].ret+=Number(m.qtd||0);
    else if(m.tipo==='Baixa aplicação')saldoMap[key].baixa+=Number(m.qtd||0);
    else if(m.tipo==='Devolução')saldoMap[key].dev+=Number(m.qtd||0);
  });
  var sw=document.getElementById('saldo-enc-wrap');
  if(sw){
    var items=Object.values(saldoMap);
    if(!items.length){sw.innerHTML='<div style="color:#aaa;font-size:12px;padding:.5rem">Nenhuma movimentação</div>';return;}
    sw.innerHTML='<div style="overflow-x:auto"><table class="tbl"><thead><tr>'      +'<th>Encarregado</th><th>Material</th><th>Retirado</th><th>Baixado</th><th>Devolvido</th><th>Saldo responsabilidade</th>'      +'</tr></thead><tbody>'      +items.map(function(r){
        var saldo=r.ret-r.baixa-r.dev;
        return '<tr><td style="font-weight:500">'+r.enc+'</td><td>'+r.mat+'</td>'          +'<td>'+r.ret+' '+r.uni+'</td><td>'+r.baixa+' '+r.uni+'</td><td>'+r.dev+' '+r.uni+'</td>'          +'<td style="font-weight:600;color:'+(saldo>0?'#854F0B':saldo<0?'#A32D2D':'#3B6D11')+'">'+saldo+' '+r.uni+'</td></tr>';
      }).join('')      +'</tbody></table></div>';
  }
}

// função SAP antiga removida

function usarDemo(){DEMO=true;usuarioLogado={id:'u0',nome:'Demo Admin',perfil:'admin'};
  if(!usuarios_lista.length)usuarios_lista=[{id:'u0',nome:'Demo Admin',email:'admin@demo.com',perfil:'admin',equipe_id:'',equipe_codigo:'',ativo:true}];document.getElementById('pg-login').classList.add('hidden');document.getElementById('pg-app').classList.remove('hidden');document.getElementById('topbar-user').textContent='Demo Admin';document.getElementById('db-status').textContent='Modo demo';carregarDados().then(function(){
    if(usuarioLogado && usuarioLogado.perfil==='portaria'){
      showMain('frotas');
      setTimeout(function(){ showSub('frotas-portaria'); }, 300);
    } else {
      showMain('dashboard');
    }
  });}
function fazerLogout(){
  auditLog('logout','sistema','Logout do sistema');
  // Circuit breaker ANTES de qualquer coisa — impede refresh pós-logout
  _cenaAuthInvalid = true;
  // Para timers autenticados + WebSocket ANTES de limpar token
  try{ if(typeof cenaAuthStopAuthenticatedLoops==='function') cenaAuthStopAuthenticatedLoops(); }catch(eStop){}
  // Tira da lista de online antes de limpar o token (só se JWT ainda válido)
  try{ onlineOffline(); }catch(e){}
  // Encerrar sessão no Supabase Auth (se existir)
  _sbAuthToken = null;
  _cenaAuthHadSession = false;
  // NÃO resetar _cenaAuthInvalid aqui — só no próximo login Auth válido
  try{ if(supabaseClient) supabaseClient.auth.signOut(); }catch(e){}
  document.body.classList.remove('perfil-equipe');
  if(typeof limparClassesPerfilBody==='function') limparClassesPerfilBody();
  // Resetar estado do diário de bordo completamente
  _dbEquipe=null;
  _dbSessao=null;
  _dbOrdemAtual=null;
  _dbPlaca='';
  window._dbKmInicial=0;
  if(window._dbTimerInterval){clearInterval(window._dbTimerInterval);window._dbTimerInterval=null;}
  usuarioLogado=null;
  _gestorContAtivo=null;
  _gestorContratos=[];
  window._filtroContrato=null;
  try{localStorage.removeItem('cena_user');}catch(e){}
  // Restaurar elementos que podem ter sido escondidos
  var bm=document.getElementById('bloco-metricas');if(bm)bm.style.display='';
  var nm=document.getElementById('nav-main');if(nm)nm.style.display='';
  var gb=document.getElementById('gestor-bar');if(gb)gb.style.display='none';
  var btn=document.getElementById('btn-voltar-painel');if(btn)btn.style.display='none';
  document.getElementById('pg-app').classList.add('hidden');
  document.getElementById('pg-login').classList.remove('hidden');
  document.body.classList.add('sem-login');
}

