var _pp = {
  data:          dataHojeLocal(),
  cid:           '',
  projetoIds:    [],    // IDs dos projetos selecionados
  tipoFiltro:    '',
  filtroColab:   '',
  soIncompletas: false,
  soProgramadas: false,
  filtroPonto:   'todos', // todos | presentes | ausentes
  dragging:      null,
  fromEq:        null,
};

// Status reutilizado da Programação de Equipes
// PROG_STATUS já declarado — não duplicar

function progProjGetData(){ return (document.getElementById('pp-data')||{}).value || _pp.data; }

function ppNavData(dias){
  var el = document.getElementById('pp-data');
  if(!el) return;
  var atual = el.value || dataHojeLocal();
  var nova = typeof dataAddDias==='function' ? dataAddDias(atual, dias) : (function(){
    var d=new Date(atual+'T12:00:00'); d.setDate(d.getDate()+dias);
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  })();
  el.value = nova;
  _pp.data = nova;
  progProjRenderQuadro();
}

function ppNavHoje(){
  var el = document.getElementById('pp-data');
  if(!el) return;
  var hoje = dataHojeLocal();
  el.value = hoje;
  _pp.data = hoje;
  progProjRenderQuadro();
}
function progProjGetCid(){  return (document.getElementById('pp-cont')||{}).value || ''; }

// ══ progProjetoCore — motor Programação de Projetos (não usar em TMA) ══
var PROG_PROJETO_CTX = {
  modo:                  'projeto',
  pageId:                'pg-programacao-projetos',
  fonteEquipes:          'equipes',
  tabelaComposicao:      'composicao_dia',
  maxSlots:              7,
  exigeVeiculo:          true,
  exigeCelularEquipe:    true,
  permiteHoraExtraFolga: true
};

function progProjetoCoreGetContext(){
  return PROG_PROJETO_CTX;
}

/** Equipes do fluxo projeto — somente tabela equipes; nunca equipes_disp. */
function progProjetoCoreGetEquipes(cid, opts){
  opts = opts || {};
  if(!cid) return [];
  if(typeof contratoTemFluxoProjeto === 'function' && !contratoTemFluxoProjeto(cid)){
    console.warn('[progProjetoCore] contrato sem fluxo projeto:', cid);
    return [];
  }
  var lista = (equipes || []).filter(function(e){
    return e.status === 'Ativo' && e.contrato_id === cid;
  });
  if(opts.filtroTurno){
    lista = lista.filter(function(e){
      var t = e.turno_tipo || calcularTurnoTipo(e.hora_inicio || '') || 'Manhã';
      return t === opts.filtroTurno;
    });
  }
  if(opts.filtroEscala){
    lista = lista.filter(function(e){ return e.escala === opts.filtroEscala; });
  }
  return lista;
}

/** Merge item composicao_dia — reutiliza helper TMA sem alterá-lo; preserva motorista se confirmada. */
function progProjetoCoreMergeComposicaoItem(localComp, serverComp){
  if(!serverComp) return localComp;
  if(!localComp) return serverComp;
  var merged = Object.assign({}, serverComp);
  merged.colaborador_ids = progMergeColaboradorIdsConfirmada(localComp, serverComp);
  if(localComp.confirmada){
    merged.confirmada = true;
    if(localComp.motorista_id != null && localComp.motorista_id !== ''){
      merged.motorista_id = localComp.motorista_id;
    }
    if(localComp.projeto_ids){
      var nLocal = parseJsonField(localComp.projeto_ids, []).length;
      var nServer = parseJsonField(serverComp.projeto_ids || '[]', []).length;
      if(nLocal > nServer) merged.projeto_ids = localComp.projeto_ids;
    }
    if(localComp.placa && !serverComp.placa) merged.placa = localComp.placa;
    if(localComp.veiculo_id && !serverComp.veiculo_id) merged.veiculo_id = localComp.veiculo_id;
  }
  return merged;
}

/** Aplica merge seguro no refresh de Projetos — equipes confirmadas não perdem composição. */
function progProjetoCoreMergeComposicaoRefresh(compsFromServer){
  if(!compsFromServer || !compsFromServer.length) return;
  var compMap = {};
  compsFromServer.forEach(function(c){
    var copy = Object.assign({}, c);
    copy.colaborador_ids = parseJsonField(c.colaborador_ids, []);
    compMap[c.id] = copy;
  });
  composicao_dia.forEach(function(c, i){
    if(!compMap[c.id]) return;
    composicao_dia[i] = progProjetoCoreMergeComposicaoItem(c, compMap[c.id]);
  });
  compsFromServer.forEach(function(c){
    if(!composicao_dia.find(function(x){ return x.id === c.id; })){
      var copy = Object.assign({}, c);
      copy.colaborador_ids = parseJsonField(c.colaborador_ids, []);
      composicao_dia.push(copy);
    }
  });
}

/** Wrapper — lista equipes ativas do contrato (Programação de Projetos). */
function progProjGetEquipesAtivas(cid, opts){
  return progProjetoCoreGetEquipes(cid, opts || {});
}

/** Busca equipe só na tabela equipes (nunca equipes_disp). */
function progProjetoCoreFindEquipe(eqId){
  return (equipes || []).find(function(e){ return e.id === eqId; }) || null;
}

/** Persiste composição parcial — desconfirma; grava em composicao_dia. */
function progProjetoCorePersistirComposicao(eqId, data, ids){
  var comp = progFindCompDia(eqId, data);
  var payloadIds = Array.isArray(ids) ? ids : parseJsonField(ids, []);
  var projetoIds = JSON.stringify(_pp.projetoIds || []);
  if(comp){
    comp.colaborador_ids = JSON.stringify(payloadIds);
    comp.projeto_ids = projetoIds;
    comp.confirmada = false;
    if(!DEMO){
      var isLocal = comp._local || !comp.id || String(comp.id).startsWith('local_');
      if(isLocal){
        sbInsert('composicao_dia', {equipe_id: eqId, data: data, colaborador_ids: payloadIds, projeto_ids: projetoIds, turno: 'Manha', confirmada: false})
          .then(function(r){ if(r && r[0] && r[0].id){ comp.id = r[0].id; comp._local = false; } });
      } else {
        sbUpdate('composicao_dia', {colaborador_ids: payloadIds, projeto_ids: projetoIds, confirmada: false}, 'id=eq.' + comp.id);
      }
    }
  } else {
    var nova = {id: 'local_pp_' + eqId + '_' + data, equipe_id: eqId, data: data,
      colaborador_ids: JSON.stringify(payloadIds), projeto_ids: projetoIds, turno: 'Manha', confirmada: false, _local: true};
    composicao_dia.push(nova);
    if(!DEMO){
      sbInsert('composicao_dia', {equipe_id: eqId, data: data, colaborador_ids: payloadIds, projeto_ids: projetoIds, turno: 'Manha', confirmada: false})
        .then(function(r){ if(r && r[0] && r[0].id){ nova.id = r[0].id; nova._local = false; } });
    }
  }
  return payloadIds.filter(Boolean).length;
}

/** Confirma programação da equipe (fluxo projeto). */
function progProjetoCoreSalvarEquipe(eqId){
  var data = progProjGetData();
  var eq = progProjetoCoreFindEquipe(eqId);
  if(!eq){
    progShowToast('⚠ Equipe não encontrada no contrato de projetos.');
    return;
  }
  if(equipeEstaEmFolga(eq, data)){
    if(!(_pp._horaExtraAuth && _pp._horaExtraAuth[eqId])){
      progShowToast('🏖 Equipe está em período de folga conforme escala cadastrada.');
      return;
    }
  }
  var comp = composicao_dia.find(function(c){
    var cd = (c.data || '').split('T')[0];
    return c.equipe_id === eqId && (cd === data || c.data === data);
  });
  if(!comp){ progShowToast('⚠ Nenhum colaborador escalado — use Auto Escalar primeiro.'); return; }
  var ids = parseJsonField(comp.colaborador_ids, []).filter(Boolean);
  if(!ids.length){ progShowToast('⚠ Equipe sem colaboradores escalados.'); return; }
  var minCol = progMinColaboradoresEquipe(eq);
  if(ids.length < minCol){
    progShowToast(progMsgMinColaboradores(eq, 0));
    return;
  }
  var veicDiaPP = progGetVeiculo(eqId, data);
  var errPlacaPP = progValidarPlacaObrigatoria(eq, eqId, data);
  if(errPlacaPP){ progShowToast(errPlacaPP); return; }
  if(!telefoneEquipeValido(eq.telefone)){
    progShowToast(MSG_CEL_OBRIG);
    return;
  }
  var errMotPP = progValidarMotoristaObrigatorio(comp, ids, eqId, data);
  if(errMotPP){ progShowToast(errMotPP); return; }
  comp.confirmada = true;
  if(!DEMO){
    var isLocal = comp._local || !comp.id || comp.id.startsWith('local_');
    var _veicPPBase = progGetVeiculo(eqId, data);
    var _payloadPP = {equipe_id: eqId, data: data,
      colaborador_ids: ids, turno: 'Manha', confirmada: true,
      motorista_id: comp.motorista_id || null,
      veiculo_id: _veicPPBase ? (_veicPPBase.id || null) : null,
      placa: _veicPPBase ? (_veicPPBase.placa || '') : '',
      modelo: _veicPPBase ? (_veicPPBase.modelo || '') : ''};
    if(isLocal){
      sbFetch('composicao_dia', {filters: ['equipe_id=eq.' + eqId, 'data=eq.' + data], limit: 1})
        .then(function(ex){
          if(ex && ex.length){
            comp.id = ex[0].id; comp._local = false;
            sbUpdate('composicao_dia', _payloadPP, 'id=eq.' + ex[0].id);
          } else {
            sbInsert('composicao_dia', _payloadPP)
              .then(function(r){ if(r && r[0] && r[0].id){ comp.id = r[0].id; comp._local = false; } });
          }
        });
    } else {
      sbUpdate('composicao_dia', {confirmada: true, colaborador_ids: ids,
        motorista_id: comp.motorista_id || null,
        veiculo_id: _payloadPP.veiculo_id, placa: _payloadPP.placa, modelo: _payloadPP.modelo}, 'id=eq.' + comp.id);
    }
  }
  var _veicPP = progGetVeiculo(eqId, data);
  var _veicPPPromise = (_veicPP && !DEMO)
    ? progSalvarVeiculoNoBanco(eqId, data, _veicPP, 1)
    : Promise.resolve(true);
  _veicPPPromise.then(function(veicOk2){
    if(!veicOk2) progShowToast('⚠ Erro ao confirmar veículo no banco.', 'erro');
    var _veicPPB = progGetVeiculoB(eqId, data);
    if(_veicPPB && !DEMO) progSalvarVeiculoNoBanco(eqId, data, _veicPPB, 2);
    if(_veicPP){
      comp.veiculo_id = _veicPP.id || null;
      comp.placa = _veicPP.placa || '';
      comp.modelo = _veicPP.modelo || '';
    }
    progProjRenderQuadro();
    progShowToast('✅ Equipe programada com sucesso');
  });
}

// ── Dashboard Programação de Projetos ────────────────────────
var _ppAba = 'programacao';

function ppSetAba(aba){
  _ppAba = aba;
  // Usar style.display diretamente — mais confiável que classList
  var paineis = {
    'dashboard':   document.getElementById('pp-painel-dashboard'),
    'programacao': document.getElementById('pp-painel-programacao'),
    'requisicoes': document.getElementById('pp-painel-requisicoes'),
    'obras':       document.getElementById('pp-painel-obras')
  };
  var tabs = {
    'dashboard':   document.getElementById('pp-tab-dashboard'),
    'programacao': document.getElementById('pp-tab-programacao'),
    'requisicoes': document.getElementById('pp-tab-requisicoes'),
    'obras':       document.getElementById('pp-tab-obras')
  };
  // Esconder todos
  Object.keys(paineis).forEach(function(a){
    if(paineis[a]){
      paineis[a].style.display = 'none';
      paineis[a].classList.add('hidden');
    }
    if(tabs[a]){
      tabs[a].style.borderBottomColor = 'transparent';
      tabs[a].style.color = '#888';
      tabs[a].style.fontWeight = '500';
    }
  });
  // Mostrar o selecionado
  if(paineis[aba]){
    paineis[aba].style.display = 'block';
    paineis[aba].classList.remove('hidden');
  }
  if(tabs[aba]){
    tabs[aba].style.borderBottomColor = '#1a1a18';
    tabs[aba].style.color = '#1a1a18';
    tabs[aba].style.fontWeight = '700';
  }
  // Chamar render da aba
  if(aba==='dashboard')   ppRenderDashboard();
  if(aba==='programacao') progProjRenderQuadro && progProjRenderQuadro();
  if(aba==='requisicoes') plptRenderRequisicoes();
  if(aba==='obras')       _ppRenderObras();
}

function ppRenderDashboard(){
  var el = document.getElementById('pp-dash-inner'); if(!el) return;
  var hoje    = dataHojeLocal();
  var dataIni = (document.getElementById('pp-dash-ini')||{}).value || hoje;
  var dataFim = (document.getElementById('pp-dash-fim')||{}).value || hoje;
  if(dataIni > dataFim){ var t=dataIni; dataIni=dataFim; dataFim=t; }

  // Contratos de Projetos (excluir Disponibilidade/TMA)
  var contsProj = contratos.filter(function(c){
    return !(c.modalidade_trabalho||'').toLowerCase().includes('disponibilidade');
  }).sort(function(a,b){return(a.codigo||'').localeCompare(b.codigo||'');});

  // Status no período — ler localStorage para cada dia
  var statusPor = {}; // {cid: {colabId: {falta:N,folga:N,ferias:N,escalado:N,outros:N,disponivel:N}}}
  var d = new Date(dataIni+'T12:00:00'), dF = new Date(dataFim+'T12:00:00');
  while(d <= dF){
    var ds = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    try{
      var sv = JSON.parse(localStorage.getItem('pp_status_'+ds)||'{}');
      Object.keys(sv).forEach(function(id){
        var col = colaboradores.find(function(c){return c.id===id;}); if(!col) return;
        var cid = col.contrato_id||'sem_cont';
        if(!statusPor[cid]) statusPor[cid]={};
        if(!statusPor[cid][id]) statusPor[cid][id]={falta:0,folga:0,ferias:0,escalado:0,outros:0,disponivel:0};
        var st = sv[id];
        if(st==='falta')         statusPor[cid][id].falta++;
        else if(st==='folga')    statusPor[cid][id].folga++;
        else if(st==='ferias')   statusPor[cid][id].ferias++;
        else if(st==='disponivel') statusPor[cid][id].disponivel++;
        else                     statusPor[cid][id].outros++;
      });
    }catch(e){}
    d.setDate(d.getDate()+1);
  }

  // Composições no período
  var compsPeríodo = composicao_dia.filter(function(c){
    var dd=(c.data||'').split('T')[0]; return dd>=dataIni&&dd<=dataFim;
  });

  // Sessões no campo no período
  var sessPer = sessoes_disp.filter(function(s){
    var dd=(s.data||'').split('T')[0]; return dd>=dataIni&&dd<=dataFim&&s.login_ts;
  });

  // ── Montar linha por contrato ──
  var filtroHtml = '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:1rem">'
    +'<label style="font-size:11px;font-weight:600;color:#555">Período:</label>'
    +'<input type="date" class="inp" id="pp-dash-ini" value="'+dataIni+'" style="width:145px" onchange="ppRenderDashboard()"/>'
    +'<span style="font-size:12px;color:#888">até</span>'
    +'<input type="date" class="inp" id="pp-dash-fim" value="'+dataFim+'" style="width:145px" onchange="ppRenderDashboard()"/>'
    +'<button class="btn" onclick="ppRenderDashboard()" style="color:#185FA5;border-color:#185FA5">🔄 Atualizar</button>'
    +'</div>';

  if(!contsProj.length){
    el.innerHTML = filtroHtml+'<div style="padding:2rem;text-align:center;color:#aaa">Nenhum contrato de projetos encontrado.</div>';
    return;
  }

  var rows = contsProj.map(function(cont){
    var cid = cont.id;

    // Equipes deste contrato
    var eqs = equipes.filter(function(e){return e.contrato_id===cid&&e.status!=='Inativo';});
    var qtdEquipes = eqs.length;

    // Equipes programadas (com composição no período)
    var eqsComComp = new Set(compsPeríodo.filter(function(c){
      var eq = equipes.find(function(e){return e.id===c.equipe_id;});
      return eq && eq.contrato_id===cid;
    }).map(function(c){return c.equipe_id;}));
    var qtdProgramadas = eqsComComp.size;

    // Colaboradores do contrato
    var colabs = colaboradores.filter(function(c){return c.contrato_id===cid&&c.ativo!==false;});
    var qtdColabs = colabs.length;

    // Status agregados do período (via localStorage)
    var stCont = statusPor[cid]||{};
    var totFalta=0, totFolga=0, totFerias=0, totEscalado=0, totOutros=0;
    Object.keys(stCont).forEach(function(id){
      var s=stCont[id];
      totFalta    += s.falta;
      totFolga    += s.folga;
      totFerias   += s.ferias;
      totEscalado += s.disponivel; // disponível = escalado (no quadro está alocado)
      totOutros   += s.outros;
    });
    // Escalados = colaboradores com composição no período
    var escaladosSet = new Set();
    compsPeríodo.forEach(function(comp){
      var eq = equipes.find(function(e){return e.id===comp.equipe_id;});
      if(!eq||eq.contrato_id!==cid) return;
      var ids = parseColabIds(comp.colaborador_ids);
      ids.forEach(function(id){escaladosSet.add(id);});
    });
    var qtdEscalado = escaladosSet.size;

    // Em campo = sessões ativas do período para equipes deste contrato
    var qtdCampo = sessPer.filter(function(s){
      var eq = equipes.find(function(e){return e.id===s.equipe_id;});
      return eq && eq.contrato_id===cid;
    }).length;

    return {
      nome: escHtml(cont.nome||'—'),
      qtdEquipes, qtdProgramadas, qtdColabs,
      totFalta, totFolga, totFerias, qtdEscalado, totOutros, qtdCampo
    };
  });

  var tabelaHtml = '<div class="card" style="overflow-x:auto;padding:0"><table style="width:100%;border-collapse:collapse;font-size:12px;min-width:860px">'
    +'<thead>'
    +'<tr style="background:#1a1a18">'
    +'<th style="color:#fff;text-align:left;padding:10px 14px;font-size:12px;border-radius:0">Contrato</th>'
    +'<th style="color:#ccc;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">👥 Equipes</th>'
    +'<th style="color:#ccc;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">📅 Programadas</th>'
    +'<th style="color:#ccc;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">👷 Colaboradores</th>'
    +'<th style="color:#FF9999;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">❌ Faltas</th>'
    +'<th style="color:#FFD580;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">🏖 Folgas</th>'
    +'<th style="color:#90EE90;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">✅ Escalados</th>'
    +'<th style="color:#87CEEB;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">🌴 Férias</th>'
    +'<th style="color:#FFB347;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">⚙ Outros</th>'
    +'<th style="color:#C9B1FF;text-align:center;padding:10px 8px;font-size:11px;white-space:nowrap">🚌 Em Campo</th>'
    +'</tr></thead><tbody>'
    +rows.map(function(r, i){
      var bg = i%2===0 ? '#fff' : '#fafaf8';
      var pct = r.qtdEquipes ? Math.round(r.qtdProgramadas/r.qtdEquipes*100) : 0;
      var corPct = pct>=80?'#3B6D11':pct>=50?'#854F0B':'#A32D2D';
      var bgPct  = pct>=80?'#EAF3DE':pct>=50?'#FEF3E2':'#FCEBEB';
      return '<tr style="background:'+bg+';border-bottom:.5px solid #f0efe8" onmouseenter="this.style.background=\'#F0F4FF\'" onmouseleave="this.style.background=\''+bg+'\'">'
        +'<td style="padding:9px 14px;font-weight:700;font-size:12px;color:#1a1a18;border-left:3px solid #1a1a18">'+r.nome+'</td>'
        +'<td style="text-align:center;padding:9px 8px"><span style="font-weight:600">'+r.qtdEquipes+'</span></td>'
        +'<td style="text-align:center;padding:9px 8px">'
          +'<span style="background:'+bgPct+';color:'+corPct+';border-radius:12px;padding:2px 9px;font-weight:700;font-size:11px">'+r.qtdProgramadas+' <small style="font-weight:400;font-size:10px">('+pct+'%)</small></span>'
        +'</td>'
        +'<td style="text-align:center;padding:9px 8px;font-weight:500">'+r.qtdColabs+'</td>'
        +'<td style="text-align:center;padding:9px 8px">'+(r.totFalta>0?'<span style="background:#FCEBEB;color:#A32D2D;border-radius:12px;padding:2px 9px;font-weight:700">'+r.totFalta+'</span>':'<span style="color:#ddd">—</span>')+'</td>'
        +'<td style="text-align:center;padding:9px 8px;color:#555">'+(r.totFolga>0?r.totFolga:'<span style="color:#ddd">—</span>')+'</td>'
        +'<td style="text-align:center;padding:9px 8px">'+(r.qtdEscalado>0?'<span style="background:#EAF3DE;color:#3B6D11;border-radius:12px;padding:2px 9px;font-weight:700">'+r.qtdEscalado+'</span>':'<span style="color:#ddd">—</span>')+'</td>'
        +'<td style="text-align:center;padding:9px 8px">'+(r.totFerias>0?'<span style="background:#E6F1FB;color:#185FA5;border-radius:12px;padding:2px 9px;font-weight:700">'+r.totFerias+'</span>':'<span style="color:#ddd">—</span>')+'</td>'
        +'<td style="text-align:center;padding:9px 8px">'+(r.totOutros>0?'<span style="background:#FEF3E2;color:#854F0B;border-radius:12px;padding:2px 9px;font-weight:700">'+r.totOutros+'</span>':'<span style="color:#ddd">—</span>')+'</td>'
        +'<td style="text-align:center;padding:9px 8px">'+(r.qtdCampo>0?'<span style="background:#F0EEFF;color:#533AB7;border-radius:12px;padding:2px 9px;font-weight:700">'+r.qtdCampo+'</span>':'<span style="color:#ddd">—</span>')+'</td>'
        +'</tr>';
    }).join('')
    +'<tr style="background:#f0efe8;border-top:2px solid #e0dfd8">'
    +'<td style="padding:10px 14px;font-weight:800;font-size:12px;color:#1a1a18">TOTAL</td>'
    +[
      {k:'qtdEquipes',   cor:'#555'},
      {k:'qtdProgramadas',cor:'#555'},
      {k:'qtdColabs',    cor:'#555'},
      {k:'totFalta',     cor:'#A32D2D'},
      {k:'totFolga',     cor:'#555'},
      {k:'qtdEscalado',  cor:'#3B6D11'},
      {k:'totFerias',    cor:'#185FA5'},
      {k:'totOutros',    cor:'#854F0B'},
      {k:'qtdCampo',     cor:'#533AB7'},
    ].map(function(x){
      var total = rows.reduce(function(s,r){return s+(r[x.k]||0);},0);
      return '<td style="text-align:center;padding:10px 8px;font-weight:800;color:'+x.cor+';font-size:13px">'+total+'</td>';
    }).join('')
    +'</tr>'
    +'</tbody></table></div>';

  el.innerHTML = filtroHtml + tabelaHtml;
}


function _ppRenderObras(){
  var inner = document.getElementById('pp-obras-inner');
  if(!inner) return;
  inner.innerHTML = '<div style="padding:2rem;text-align:center;color:#aaa">⏳ Carregando Projetos de Obras...</div>';

  // Load the obras module and render into pp-obras-inner
  _precisaModulo('obras', function(){
    // Render the obras-projetos content directly into pp-obras-inner
    // Re-use the existing pg-obras-projetos page but embed its content here
    var pgObras = document.getElementById('pg-obras-projetos');
    if(pgObras){
      // Clone content into our panel
      inner.innerHTML = '';
      // Instead of cloning, just show the existing page inside a scrollable div
      inner.style.cssText = 'min-height:500px';
      // Use popularFiltrosObras to initialize
      if(typeof popularFiltrosObras === 'function') popularFiltrosObras();
      if(typeof projMostrarTab === 'function') projMostrarTab('tma');
      // Render the obras projetos table inside our panel
      _ppRenderObrasProjetos(inner);
    } else {
      inner.innerHTML = '<div style="padding:2rem;text-align:center;color:#aaa">Módulo Obras não disponível.</div>';
    }
  });
}

function _ppRenderObrasProjetos(container){
  // Show contract selector + projects list inline
  var conts = typeof _contratosVisiveis==='function' ? _contratosVisiveis() : contratos;

  var html = '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.75rem;margin-bottom:.75rem">'
    +'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    +'<label style="font-size:11px;font-weight:600">Contrato</label>'
    +'<select class="inp" id="pp-obras-cont" style="min-width:200px" onchange="_ppObrasCarregarProjetos()">'
    +'<option value="">Selecione...</option>'
    +conts.map(function(ct){
      return '<option value="'+ct.id+'">'+escHtml(ct.nome||ct.codigo||ct.id)+'</option>';
    }).join('')
    +'</select>'
    +'<input class="inp" id="pp-obras-busca" placeholder="Buscar projeto..." style="min-width:180px" oninput="_ppObrasCarregarProjetos()"/>'
    +'</div>'
    +'</div>'
    +'<div id="pp-obras-lista"></div>';

  container.innerHTML = html;
}

function _ppObrasCarregarProjetos(){
  var cid   = (document.getElementById('pp-obras-cont')||{}).value||'';
  var busca = ((document.getElementById('pp-obras-busca')||{}).value||'').toLowerCase().trim();
  var lista = document.getElementById('pp-obras-lista');
  if(!lista) return;

  if(!cid){ lista.innerHTML = '<div style="padding:1.5rem;text-align:center;color:#aaa">Selecione um contrato.</div>'; return; }

  lista.innerHTML = '<div style="padding:1rem;text-align:center;color:#aaa">⏳ Carregando...</div>';

  // Load sot_projetos for this contract
  var projs = typeof sot_projetos!=='undefined'
    ? sot_projetos.filter(function(p){ return p.contrato_id===cid; })
    : [];

  var render = function(projs){
    if(busca) projs = projs.filter(function(p){
      return (p.codigo_cliente||p.codigo||p.nome||'').toLowerCase().includes(busca)
          || (p.nome||'').toLowerCase().includes(busca);
    });
    if(!projs.length){
      lista.innerHTML = '<div style="padding:1.5rem;text-align:center;color:#aaa">Nenhum projeto encontrado.</div>';
      return;
    }
    lista.innerHTML = projs.map(function(p){
      return '<div style="display:flex;align-items:center;justify-content:space-between;padding:.6rem .75rem;border-bottom:.5px solid #f0efe8;cursor:pointer;background:#fff;border-radius:6px;margin-bottom:4px" '
        +'onclick="coAbrirContrato(\''+cid+'\');setTimeout(function(){sotAbrirProjeto(\''+p.id+'\');},400)">'
        +'<div>'
        +'<div style="font-weight:600;font-size:13px">'+escHtml(p.codigo_cliente||p.codigo||p.nome||p.id)+'</div>'
        +(p.nome?'<div style="font-size:11px;color:#888">'+escHtml(p.nome)+'</div>':'')
        +'</div>'
        +'<div style="font-size:10px;color:#185FA5;font-weight:600">→ Abrir</div>'
        +'</div>';
    }).join('');
  };

  if(!projs.length && !DEMO){
    sbFetch('sot_projetos',{filters:['contrato_id=eq.'+cid],order:'codigo_cliente'})
      .then(function(rows){
        if(rows&&rows.length) rows.forEach(function(p){
          if(!sot_projetos.find(function(x){return x.id===p.id;})) sot_projetos.push(p);
        });
        render(rows||[]);
      }).catch(function(){ render([]); });
  } else {
    render(projs);
  }
}


function progProjInit(opts){
  opts = opts || {};
  ppSetAba(_ppAba || 'programacao');
  var selData = document.getElementById('pp-data');
  if(selData && selData.value) _pp.data = selData.value;
  else if(!_pp.data) _pp.data = dataHojeLocal();
  if(selData) selData.value = _pp.data;

  // Carregar frota completa (inclui Baixado) para permitir escalar na programação
  if(!DEMO){
    progGarantirFrotaCompleta();
  }

  var selCont = document.getElementById('pp-cont');
  if(selCont){
    // Ocultar contratos de modalidade Disponibilidade
    var contsPrj = _contratosVisiveis().filter(function(c){
      return !(c.modalidade_trabalho||'').toLowerCase().includes('disponibilidade');
    });
    var _cidAtual = selCont.value || (_pp&&_pp.cid) || '';
    selCont.innerHTML = '<option value="">Selecione o contrato...</option>'
      + contsPrj.map(function(c){
          return '<option value="'+c.id+'">'+c.nome+'</option>';
        }).join('');
  }
    if(_cidAtual && selCont) selCont.value = _cidAtual;
  progProjAtualizarPillsTipo();
  progProjRenderQuadro();
}

function progProjMudarContrato(){
  _pp.cid = progProjGetCid();
  _pp.projetoIds = [];
  progProjAtualizarProjLista();
  progProjAtualizarPillsTipo();
  progProjCarregarStatus(progProjGetData());
  progProjCarregarStatusBanco(progProjGetData(), function(){ progProjRenderQuadro(); });
}

// ── Projetos ─────────────────────────────────────────────────

function _progIrParaProjeto(projId){
  var proj = (typeof sot_projetos!=='undefined' ? sot_projetos : []).find(function(p){return p.id===projId;})
          || projetos.find(function(p){return p.id===projId;});
  if(!proj){ progShowToast('⚠ Projeto não encontrado na memória. Acesse via Projetos de Obras.','erro'); return; }

  var contId = proj.contrato_id;

  // Navegar para pg-contrato-obras e abrir o projeto
  showPage('obras-projetos');
  setTimeout(function(){
    if(typeof coAbrirContrato==='function'){
      coAbrirContrato(contId);
      setTimeout(function(){
        if(typeof sotAbrirProjeto==='function') sotAbrirProjeto(projId);
      }, 600);
    }
  }, 400);
}


function progProjGetProjetos(cid){
  if(!cid) return [];
  var lista = [];
  var idsVistos = {};

  // REGRA: cada contrato usa apenas a sua tabela correta
  // PLPT/programação usa sot_projetos (RDSE, RDSC, PLPT, COMGAS, SOT, etc.)
  // Contratos puramente de Obras usam projetos_obra
  var usaSOT = contratoTemFluxoProjeto(cid);

  if(usaSOT && typeof sot_projetos!=='undefined'){
    sot_projetos
      .filter(function(p){ return p.contrato_id===cid && p.status!=='Cancelado'; })
      .forEach(function(p){
        if(idsVistos[p.id]) return;
        idsVistos[p.id] = true;
        lista.push({ id:p.id, nome:p.codigo_cliente||p.nome||p.codigo||p.descricao||p.id,
                     status:p.status, origem:'sot' });
      });
  }

  if(!usaSOT && typeof projetos!=='undefined'){
    projetos
      .filter(function(p){ return p.contrato_id===cid && p.status!=='Cancelado'; })
      .forEach(function(p){
        if(idsVistos[p.id]) return;
        idsVistos[p.id] = true;
        lista.push({ id:p.id, nome:p.codigo_cliente||p.codigo||p.nome||p.descricao||p.id,
                     status:p.status, origem:'obra' });
      });
  }

  // Vazio — buscar do banco
  if(!lista.length && !DEMO){
    if(usaSOT){
      sbFetchPaged('sot_projetos',{filters:['contrato_id=eq.'+cid],order:'nome'})
        .then(function(rows){
          if(!rows||!rows.length) return;
          rows.forEach(function(r){
            if(sot_projetos.findIndex(function(x){return x.id===r.id;})<0) sot_projetos.push(r);
          });
          if(typeof progProjRenderQuadro==='function') progProjRenderQuadro();
        }).catch(function(){});
    } else {
      sbFetch('projetos_obra',{filters:['contrato_id=eq.'+cid],order:'criado_em.desc'})
        .then(function(rows){
          if(!rows||!rows.length) return;
          rows.forEach(function(r){
            if(projetos.findIndex(function(x){return x.id===r.id;})<0) projetos.push(r);
          });
          if(typeof progProjRenderQuadro==='function') progProjRenderQuadro();
        }).catch(function(){});
    }
  }

  return lista;
}

function progProjAtualizarProjLista(){
  var cid = progProjGetCid();
  var vazio = document.getElementById('pp-proj-vazio');
  var lista = document.getElementById('pp-proj-lista');
  if(!lista) return;

  if(!cid){
    if(vazio) vazio.style.display='';
    lista.innerHTML='';
    return;
  }
  if(vazio) vazio.style.display='none';

  lista.innerHTML = _pp.projetoIds.map(function(pid){
    var projs = progProjGetProjetos(cid);
    var p = projs.find(function(x){return x.id===pid;});
    return p ? '<span style="background:#EBF4FD;color:#185FA5;padding:2px 8px;border-radius:6px;font-size:11px;display:flex;align-items:center;gap:4px">'
      + p.nome
      + '<button onclick="progProjRemoverProjeto(\''+pid+'\')" style="background:none;border:none;color:#A32D2D;cursor:pointer;font-size:13px;line-height:1;padding:0 0 0 2px">✕</button>'
      + '</span>' : '';
  }).join('');
}

function progProjRemoverProjeto(pid){
  _pp.projetoIds = _pp.projetoIds.filter(function(id){return id!==pid;});
  progProjAtualizarProjLista();
  progProjRenderQuadro();
}

function progProjSelecionarProjetos(){
  var cid = progProjGetCid();
  if(!cid){ alert('Selecione um contrato primeiro.'); return; }
  var projs = progProjGetProjetos(cid);
  if(!projs.length){
    alert('Nenhum projeto encontrado para este contrato.\nOs projetos são carregados de Projetos de Obras e SOT Projetos.');
    return;
  }

  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:500px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">'
    +'<h3 style="margin:0">🗂 Selecionar Projetos</h3>'
    +'<button onclick="closeModal()" style="background:none;border:none;font-size:20px;cursor:pointer">✕</button>'
    +'</div>'
    +'<input class="inp" id="pp-busca-proj" placeholder="Buscar projeto..." style="width:100%;margin-bottom:.5rem" oninput="ppFiltrarProjs()"/>'
    +'<div style="max-height:320px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px" id="pp-proj-modal-lista">'
    + projs.map(function(p){
        var sel = _pp.projetoIds.indexOf(p.id)>=0;
        var stCor = p.status==='Em execução'||p.status==='Programado'?'#3B6D11':p.status==='Concluído'?'#185FA5':'#888';
        return '<label style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8;font-size:12px">'
          +'<input type="checkbox" class="pp-proj-cb" value="'+p.id+'" '+(sel?'checked':'')+' style="width:15px;height:15px"/>'
          +'<span style="flex:1">'+p.nome+'</span>'
          +'<span style="font-size:10px;color:'+stCor+'">'+(p.status||'')+'</span>'
          +'</label>';
      }).join('')
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="pp-proj-ok" style="flex:1">✓ Confirmar</button>'
    +'</div></div></div>';

  setModal(html);

  window.ppFiltrarProjs = function(){
    var q = ((document.getElementById('pp-busca-proj')||{}).value||'').toLowerCase();
    document.querySelectorAll('#pp-proj-modal-lista label').forEach(function(el){
      el.style.display = el.textContent.toLowerCase().includes(q)?'':'none';
    });
  };

  var btn = document.getElementById('pp-proj-ok');
  if(btn) btn.onclick = function(){
    var cbs = document.querySelectorAll('#modal-area .pp-proj-cb:checked');
    _pp.projetoIds = Array.from(cbs).map(function(cb){return cb.value;});
    closeModal();
    progProjAtualizarProjLista();
    progProjRenderQuadro();
  };
}

// ── Pills de tipo ─────────────────────────────────────────────
function progProjAtualizarPillsTipo(){
  var cid = progProjGetCid();
  var wrap = document.getElementById('pp-tipos-btns'); if(!wrap) return;
  var tipos = [...new Set(
    progProjetoCoreGetEquipes(cid, {})
      .map(function(e){ return e.cargo||''; }).filter(Boolean)
  )].sort();
  wrap.innerHTML = '<button class="btn prog-tipo-btn" data-tipo="" onclick="progProjFiltrarTipo(\'\')" style="font-size:11px;'
    +(_pp.tipoFiltro===''?'background:#1a1a18;color:#fff':'')+'">Todos</button>'
    + tipos.map(function(t){
        return '<button class="btn prog-tipo-btn" data-tipo="'+t+'" onclick="progProjFiltrarTipo(\''+t+'\')" style="font-size:11px;'
          +(_pp.tipoFiltro===t?'background:#1a1a18;color:#fff':'')+'">'+t+'</button>';
      }).join('');
}

function progProjFiltrarTipo(tipo){
  _pp.tipoFiltro = tipo;
  progProjAtualizarPillsTipo();
  progProjRenderQuadro();
}

function progProjFiltrarColab(texto){
  _pp.filtroColab = texto.toLowerCase().trim();
  _pp.filtroScope = (document.getElementById('pp-busca-scope')||{}).value||'todos';
  progProjRenderQuadro();
}

function progProjToggleIncompletas(){
  _pp.soIncompletas = !_pp.soIncompletas;
  var btn = document.getElementById('pp-btn-incompletas');
  if(btn) btn.style.background = _pp.soIncompletas ? '#1a1a18' : '';
  if(btn) btn.style.color      = _pp.soIncompletas ? '#fff'    : '';
  progProjRenderQuadro();
}

function progProjToggleSoProgramadas(checked){
  _pp.soProgramadas = !!checked;
  var chk=document.getElementById('pp-chk-programadas');
  if(chk) chk.checked=_pp.soProgramadas;
  var lbl=document.getElementById('pp-lbl-programadas');
  if(lbl){
    lbl.style.background=_pp.soProgramadas?'#EAF3DE':'#fff';
    lbl.style.borderColor=_pp.soProgramadas?'#3B6D11':'#e0dfd8';
    lbl.style.color=_pp.soProgramadas?'#3B6D11':'';
    lbl.style.fontWeight=_pp.soProgramadas?'600':'';
  }
  progProjRenderQuadro();
}

function progProjLimparFiltros(){
  _pp.filtroColab=''; _pp.tipoFiltro=''; _pp.soIncompletas=false; _pp.soProgramadas=false; _pp.filtroPonto='todos';
  var b = document.getElementById('pp-busca'); if(b) b.value='';
  var bi = document.getElementById('pp-btn-incompletas');
  if(bi){ bi.style.background=''; bi.style.color=''; }
  var chk=document.getElementById('pp-chk-programadas');
  if(chk) chk.checked=false;
  var lbl=document.getElementById('pp-lbl-programadas');
  if(lbl){ lbl.style.background='#fff'; lbl.style.borderColor='#e0dfd8'; lbl.style.color=''; lbl.style.fontWeight=''; }
  progProjAtualizarPillsTipo();
  progProjRenderQuadro();
}

// ── Status Programação de Projetos — Fase 2: fonte única _progStatus ──
// _ppStatus / _ppStatusInfo: alias legado (leitura/escrita por chave → mesmo objeto)
var PP_MENU_STATUS = ['ferias','afastado','treinamento','patio','verificar','demitido','observacao'];

function progProjetoCoreInitStatusAlias(){
  if(window.__ppStatusAliasInit) return;
  try{
    Object.defineProperty(window, '_ppStatus', {
      configurable: true, enumerable: true,
      get: function(){ return _progStatus; }
    });
    Object.defineProperty(window, '_ppStatusInfo', {
      configurable: true, enumerable: true,
      get: function(){ return _progStatusInfo; }
    });
    window.__ppStatusAliasInit = true;
  }catch(e){ console.warn('[progProjetoCore] alias _ppStatus:', e); }
}
progProjetoCoreInitStatusAlias();

function progProjetoCoreStatusColab(colabId){
  return _progStatus[colabId] || 'disponivel';
}
function progProjetoCoreStatusInfoColab(colabId){
  return _progStatusInfo[colabId] || {};
}

function progProjCarregarStatus(data){
  try{
    var s = localStorage.getItem('pp_status_'+data);
    if(s){
      var leg = JSON.parse(s);
      Object.keys(leg||{}).forEach(function(id){
        if(leg[id]) _progStatus[id] = leg[id];
        else delete _progStatus[id];
      });
    }
    var si = localStorage.getItem('pp_statusinfo_'+data);
    if(si){
      var legi = JSON.parse(si);
      Object.keys(legi||{}).forEach(function(id){
        _progStatusInfo[id] = Object.assign(_progStatusInfo[id]||{}, legi[id]);
      });
    }
    var saved = _progLS.carregarStatus(data);
    if(saved){
      if(saved.status) Object.keys(saved.status).forEach(function(id){
        if(saved.status[id]) _progStatus[id] = saved.status[id];
        else delete _progStatus[id];
      });
      if(saved.info) Object.keys(saved.info).forEach(function(id){
        _progStatusInfo[id] = Object.assign(_progStatusInfo[id]||{}, saved.info[id]);
      });
    }
  }catch(e){}
}

function progProjSalvarStatus(){
  var data = progProjGetData();
  try{
    _progLS.salvarStatus(data);
    localStorage.setItem('pp_status_'+data, JSON.stringify(_progStatus));
    localStorage.setItem('pp_statusinfo_'+data, JSON.stringify(_progStatusInfo));
  }catch(e){}
}

// Carrega o status REAL do banco (prog_status_diario) para _progStatus/_progStatusInfo
// — fonte usada por ppRenderPainelDisp. Sem isso, status (verificar/falta) e observação
// salvos pelo menu de status não aparecem na Programação de Projetos.
function progProjCarregarStatusBanco(data, cb){
  if(DEMO){ if(cb) cb(); return; }
  Promise.all([
    sbFetch('prog_status_diario',{filters:['data=eq.'+data,'deleted_at=is.null']}),
    sbFetch('prog_status_diario',{filters:progFiltrosStatusPersistentes(data),order:'data.desc',limit:500})
  ]).then(function(res){
    if(res[0]===null){ if(cb) cb(); return; }
    var localRecente = (window._progStatusUltimoSave && (Date.now()-window._progStatusUltimoSave)<30000) ? Object.assign({}, _progStatus) : null;
    progAplicarStatusDoBanco(res[0]||[], res[1]||[], data);
    if(localRecente){ Object.keys(localRecente).forEach(function(id){ if(localRecente[id] && !_progStatus[id]) _progStatus[id]=localRecente[id]; }); }
    if(cb) cb();
  }).catch(function(){ if(cb) cb(); });
}

// ── Render quadro ─────────────────────────────────────────────
function progProjAtualizarQuadro(){
  _progStatusDateCache = null;
  _progVeiculosDateCache = null;
  var btn = document.querySelector('[onclick="progProjAtualizarQuadro()"]');
  if(btn){ btn.textContent = '⏳ Atualizando...'; btn.disabled = true; }
  var data = progProjGetData();
  var cid  = progProjGetCid();
  if(!cid){
    progShowToast('Selecione um contrato primeiro');
    if(btn){ btn.textContent = '🔄 Atualizar'; btn.disabled = false; }
    return;
  }
  if(_pp){ _pp.data = data; _pp.cid = cid; }
  progProjCarregarStatus(data);

  if(!DEMO){
    Promise.all([
      sbFetch('prog_status_diario',{filters:['data=eq.'+data,'deleted_at=is.null']}),
      sbFetch('prog_status_diario',{
        filters:progFiltrosStatusPersistentes(data),
        order:'data.desc', limit:500
      }),
      sbFetch('composicao_dia',{filters:['data=eq.'+data]}),
      sbFetch('colaboradores',{filters:['contrato_id=eq.'+cid,'ativo=eq.true'],order:'nome',limit:500}),
      sbFetch('equipes',{filters:['contrato_id=eq.'+cid,'status=eq.Ativo'],order:'nome_equipe'}),
    ]).then(function(res){
      var rowsDia     = res[0]||[];
      var persistRows = res[1]||[];
      var comps       = res[2]||[];
      var colabs      = res[3]||[];
      var eqs         = res[4]||[];

      if(colabs.length){
        colabMergePreservarInativos(colabs);
      }
      if(eqs.length){
        var eqMap={};
        eqs.forEach(function(e){ eqMap[e.id]=e; });
        equipes.forEach(function(e,i){ if(eqMap[e.id]) equipes[i]=eqMap[e.id]; });
        eqs.forEach(function(e){
          if(!equipes.find(function(x){return x.id===e.id;})) equipes.push(e);
        });
      }
      if(comps.length){
        progProjetoCoreMergeComposicaoRefresh(comps);
      }

      progAplicarStatusDoBanco(rowsDia, persistRows, data);

      progProjSalvarStatus();

      progCarregarVeiculos(data);
      progCarregarPontoDoSupabase(data, function(){
        progProjRenderQuadro();
        progShowToast('✅ Quadro atualizado!');
        setTimeout(function(){ progCarregarBadgesPonto(); }, 200);
      });
    }).catch(function(e){
      console.error('progProjAtualizarQuadro erro:', e);
      progProjRenderQuadro();
      progShowToast('⚠ Erro ao atualizar — verifique a conexão.','erro');
    }).finally(function(){
      var btn2 = document.querySelector('[onclick="progProjAtualizarQuadro()"]');
      if(btn2){ btn2.textContent = '🔄 Atualizar'; btn2.disabled = false; }
    });
  } else {
    progProjRenderQuadro();
    if(btn){ btn.textContent = '🔄 Atualizar'; btn.disabled = false; }
  }
}

function ppNavScroll(sec){ var el=document.getElementById('pp-sec-'+sec); if(el){el.scrollIntoView({behavior:'smooth',block:'start'});el.style.outline='2px solid #185FA5';setTimeout(function(){el.style.outline='';},1500);}else{var q=document.getElementById('pp-quadro');if(q)q.scrollIntoView({behavior:'smooth',block:'start'});} }

function ppSyncPonto(){
  var data = (document.getElementById('pp-data')||{}).value || dataHojeLocal();
  var cid = (document.getElementById('pp-cont')||{}).value || '';
  if(!cid){ progShowToast('Selecione um contrato primeiro'); return; }
  var btn = document.getElementById('pp-btn-sync-ponto');
  if(btn){ btn.textContent='⏳ Sincronizando...'; btn.disabled=true; }

  var colsContrato = progFiltrarColsProgramacao(cid).filter(function(c){ return c.re; });

  if(!colsContrato.length){
    progShowToast('Nenhum colaborador com RE encontrado');
    if(btn){ btn.textContent='🔄 Sync Ponto'; btn.disabled=false; }
        if(typeof _autoRefresh !== 'undefined') _autoRefresh.retomar();
    return;
  }

  var total = colsContrato.length;
  var sincronizados = 0;
  var erros = 0;
  var BATCH = 10;

  function processarLote(idx){
    if(idx >= colsContrato.length){
        progCarregarPontoDoSupabase(data, function(){
        var corrigidos = 0;
        colsContrato.forEach(function(col){
          var st = _progStatus[col.id]||'disponivel';
          if(st !== 'falta') return;
          var ponto = pontoCacheGet(col.re, data);
          if(!ponto) return;
          var temEnt = _pontoTemEntrada(ponto);
          if(!temEnt) return;
          _progStatus[col.id] = 'disponivel';
          if(!DEMO) sbDelete('prog_status_diario','colaborador_id=eq.'+col.id+'&data=eq.'+data).catch(function(){});
          corrigidos++;
        });
        if(typeof progProjRenderQuadro==='function') progProjRenderQuadro();
        else if(typeof progCarregarBadgesPonto==='function') progCarregarBadgesPonto();
        var msg = '✅ Sync concluído — '+sincronizados+'/'+total;
        if(corrigidos > 0) msg += ' | '+corrigidos+' falta(s) corrigida(s)';
        if(erros > 0) msg += ' | '+erros+' erro(s)';
        progShowToast(msg);
        if(btn){ btn.textContent='🔄 Sync Ponto'; btn.disabled=false; }
      });
      return;
    }

    var lote = colsContrato.slice(idx, idx+BATCH);
    Promise.all(lote.map(function(col){
      return fetch('https://cena-ponto-api-ecbnckaufzdqgxf5.brazilsouth-01.azurewebsites.net/api/v1/ponto', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body:JSON.stringify({matricula:col.re, data:data})
      }).then(function(r){return r.json();}).then(function(){sincronizados++;}).catch(function(){erros++;});
    })).then(function(){
      if(btn) btn.textContent='⏳ '+sincronizados+'/'+total+'...';
      processarLote(idx+BATCH);
    });
  }

  processarLote(0);
}

function plptSyncPonto(){
  var data = _plptProgData;
  if(!data){ progShowToast('Selecione uma data primeiro'); return; }
  var btn = document.getElementById('plpt-btn-sync-ponto');
  if(btn){ btn.textContent='⏳ Sincronizando...'; btn.disabled=true; }
  if(typeof _autoRefresh !== 'undefined') _autoRefresh.pausar();

  // Coletar todos os REs dos colaboradores do contrato atual
  var colsContrato = colaboradores.filter(function(c){
    return c.contrato_id===_plptProgCid && c.ativo!==false && c.re;
  });

  if(!colsContrato.length){
    progShowToast('Nenhum colaborador com RE encontrado');
    if(btn){ btn.textContent='🔄 Sync Ponto'; btn.disabled=false; }
    return;
  }

  // Chamar API para cada colaborador (em lotes de 10)
  var total = colsContrato.length;
  var sincronizados = 0;
  var erros = 0;
  var BATCH = 10;

  function processarLote(idx){
    if(idx >= colsContrato.length){
      // Finalizado — carregar do Supabase
      progCarregarPontoDoSupabase(data, function(){
        // Corrigir faltas que bateram ponto
        var corrigidos = 0;
        colsContrato.forEach(function(col){
          var st = _progStatus[col.id]||'disponivel';
          if(st !== 'falta') return;
          var key = col.re+'_'+data;
          var ponto = _pontoCache[key];
          if(!ponto) return;
          var temEnt = ponto.entrada||(ponto.todas_marcacoes&&ponto.todas_marcacoes.some(function(m){return m.tipo==='Entrada';}));
          if(!temEnt) return;
          _progStatus[col.id] = 'disponivel';
          if(!DEMO) sbDelete('prog_status_diario','colaborador_id=eq.'+col.id+'&data=eq.'+data).catch(function(){});
          corrigidos++;
        });
        plptProgRender();
        var msg = '✅ Sync concluído — '+sincronizados+'/'+total+' colaboradores';
        if(corrigidos > 0) msg += ' | '+corrigidos+' falta(s) corrigida(s)';
        if(erros > 0) msg += ' | '+erros+' erro(s)';
        progShowToast(msg);
        if(btn){ btn.textContent='🔄 Sync Ponto'; btn.disabled=false; }
      });
      return;
    }

    var lote = colsContrato.slice(idx, idx+BATCH);
    var promises = lote.map(function(col){
      return fetch('https://cena-ponto-api-ecbnckaufzdqgxf5.brazilsouth-01.azurewebsites.net/api/v1/ponto', {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({matricula:col.re, data:data})
      }).then(function(r){return r.json();}).then(function(){sincronizados++;}).catch(function(){erros++;});
    });

    Promise.all(promises).then(function(){
      if(btn) btn.textContent='⏳ '+sincronizados+'/'+total+'...';
      processarLote(idx+BATCH);
    });
  }

  processarLote(0);
}

function plptLimparFiltros(){
  var busca = document.getElementById('plpt-busca-texto');
  var scope = document.getElementById('plpt-busca-scope');
  var status = document.getElementById('plpt-filtro-status');
  var tipo = document.getElementById('plpt-prog-tipo');
  if(busca) busca.value = '';
  if(scope) scope.value = 'todos';
  if(status) status.value = '';
  if(tipo) tipo.value = '';
  plptProgRender();
}

function plptAtualizarQuadro(){
  var btn = document.querySelector('[onclick="plptAtualizarQuadro()"]');
  if(btn){ btn.textContent='⏳ Atualizando...'; btn.disabled=true; }
  var cid  = (document.getElementById('plpt-prog-contrato')||{}).value||'';
  var data = (document.getElementById('plpt-prog-data')||{}).value||dataHojeLocal();
  if(!cid){ progShowToast('Selecione um contrato.','erro'); if(btn){btn.textContent='🔄 Atualizar';btn.disabled=false;} return; }
  if(DEMO){ plptProgRender(); if(btn){btn.textContent='🔄 Atualizar';btn.disabled=false;} return; }
  Promise.all([
    sbFetch('equipes',{filters:['contrato_id=eq.'+cid,'status=eq.Ativo'],order:'nome_equipe'}),
    sbFetch('colaboradores',{filters:['contrato_id=eq.'+cid,'ativo=eq.true'],order:'nome'}),
    sbFetch('plpt_prog_dia',{filters:['contrato_id=eq.'+cid,'data=eq.'+data]}),
    sbFetch('composicao_dia',{filters:['data=eq.'+data]}),
  ]).then(function(res){
    if(res[0]&&res[0].length) res[0].forEach(function(e){
      var i=equipes.findIndex(function(x){return x.id===e.id;}); if(i>=0) equipes[i]=e; else equipes.push(e);
    });
    if(res[1]&&res[1].length) res[1].forEach(function(c){
      var i=colaboradores.findIndex(function(x){return x.id===c.id;}); if(i>=0) colaboradores[i]=c; else colaboradores.push(c);
    });
    plptProgInit();
    progShowToast('✅ Programação PLPT atualizada!');
  }).catch(function(e){
    console.error('plptAtualizarQuadro erro:',e);
    plptProgRender();
    progShowToast('⚠ Erro ao atualizar.','erro');
  }).finally(function(){
    var btn2=document.querySelector('[onclick="plptAtualizarQuadro()"]');
    if(btn2){btn2.textContent='🔄 Atualizar';btn2.disabled=false;}
  });
}

function progProjRenderQuadro(){
  var data = progProjGetData();
  var cid  = progProjGetCid();

  if(data !== _pp.data){
    _pp.data = data;
    progProjCarregarStatus(data);
  }
  _pp.data = data;
  progAplicarTreinoTurmas(_progStatus, _progStatusInfo, data);

  // Carregar veículos do banco se ainda não carregados para esta data
  if(data && !DEMO && !Object.keys(_progVeiculos).some(function(k){return k.endsWith('_'+data);})){
    sbFetch('prog_veiculos_dia',{filters:['data=eq.'+data]}).then(function(rows){
      if(rows&&rows.length){
        rows.forEach(function(r){
          if(!r.equipe_id||!r.placa) return;
          var _k = r.slot===2 ? progVeiculoKeyB(r.equipe_id, data) : progVeiculoKey(r.equipe_id, data);
          _progVeiculos[_k]={
            placa:r.placa, modelo:r.modelo, id:r.veiculo_id,
            justificativa:r.justificativa, alterado_por:r.alterado_por
          };
        });
      }
      _progProjRenderQuadroInterno(data, cid);
    }).catch(function(){ _progProjRenderQuadroInterno(data, cid); });
    return;
  }

  _progProjRenderQuadroInterno(data, cid);
}

function _progProjRenderQuadroInterno(data, cid){
  var wrap = document.getElementById('pp-quadro'); if(!wrap) return;
  // Âncora de topo para scroll
  var _topoAnchor = '<div id="pp-sec-topo"></div>';

  if(!cid){
    wrap.innerHTML='<div style="padding:3rem;text-align:center;color:#aaa">Selecione um contrato e uma data para ver o quadro.</div>';
    return;
  }

  // Filtros adicionais de turno e escala (persistidos em _pp)
  var filtroTurno = _pp.filtroTurno||'';
  var filtroEscala = _pp.filtroEscala||'';

  // Equipes do contrato — somente equipes (fluxo projeto); nunca equipes_disp
  var todasEqsCid = progProjetoCoreGetEquipes(cid, {
    filtroTurno:  filtroTurno,
    filtroEscala: filtroEscala
  });

  var eqs = todasEqsCid.filter(function(e){
    if(_pp.tipoFiltro && (e.tipo||e.cargo||'')!==_pp.tipoFiltro) return false;
    return true;
  });

  // Filtro por colaborador / equipe / placa / status
  if(_pp.filtroColab){
    var scPp = _pp.filtroScope||'todos';
    eqs = eqs.filter(function(eq){
      return progEquipeMatchBusca(eq, data, _pp.filtroColab, scPp);
    });
  }

  // Filtro só incompletas (excluir folgas)
  if(_pp.soIncompletas){
    var BLOQ = ['ferias','afastado','treinamento','falta'];
    eqs = eqs.filter(function(eq){
      if(equipeEstaEmFolga(eq,data)) return false;
      var comp = composicao_dia.find(function(c){return c.equipe_id===eq.id&&c.data===data;});
      var ids = comp?parseJsonField(comp.colaborador_ids,[]):[];
      if(!comp||!ids.filter(Boolean).length) return true;
      var ativos = ids.filter(function(id){ return id&&BLOQ.indexOf(progProjetoCoreStatusColab(id))<0; }).length;
      return ativos < progMinColaboradoresEquipe(eq);
    });
  }

  // Filtro só programadas (escala salva/confirmada)
  if(_pp.soProgramadas){
    eqs = eqs.filter(function(eq){ return progEquipeProgramadaNoDia(eq.id, data); });
  }

  if(!eqs.length){
    wrap.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">'
      +(_pp.soProgramadas?'Nenhuma equipe programada (salva) neste dia.':'Nenhuma equipe encontrada para este contrato.')
      +'</div>';
    return;
  }

  // ── Resumo ──────────────────────────────────────
  var rTotal=0,rProgramadas=0,rCompletas=0,rIncompletas=0,rParadas=0,rFolga=0;
  todasEqsCid.forEach(function(eq){
    rTotal++;
    if(equipeEstaEmFolga(eq,data)){rFolga++;return;}
    var comp=composicao_dia.find(function(c){return c.equipe_id===eq.id&&c.data===data;});
    if(!comp){ rParadas++; return; }
    if(comp.confirmada){ rProgramadas++; return; }
    var ids=parseJsonField(comp.colaborador_ids,[]).filter(Boolean);
    if(!ids.length){ rParadas++; return; }
    var ativos=ids.filter(function(id){
      var col=colaboradores.find(function(c){return c.id===id;});
      return col&&(_progStatus[id]||'disponivel')==='disponivel';
    }).length;
    if(ativos>=progMinColaboradoresEquipe(eq)) rCompletas++;
    else if(ativos===1 && progMinColaboradoresEquipe(eq)>1) rIncompletas++;
    else rParadas++;
  });
  var pct=rTotal?Math.round((rProgramadas+rCompletas)/rTotal*100):0;
  var corPct=pct>=90?'#3B6D11':pct>=70?'#854F0B':'#A32D2D';

  var resumoHtml='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:8px;margin-bottom:.75rem">'
    +[{l:'Total',v:rTotal,c:'#555'},{l:'✓ Programadas',v:rProgramadas,c:'#3B6D11'},
      {l:'Completas',v:rCompletas,c:'#185FA5'},{l:'Incompletas',v:rIncompletas,c:'#854F0B'},
      {l:'Não prog.',v:rParadas,c:'#A32D2D'},{l:'🏖 Folga',v:rFolga,c:'#888'},
      {l:'Aproveit.',v:pct+'%',c:corPct}]
    .map(function(m){
      return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.6rem;text-align:center">'
        +'<div style="font-size:10px;color:#888;margin-bottom:3px">'+m.l+'</div>'
        +'<div style="font-size:20px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('')+'</div>';

  // ── Filtros por turno e escala ───────────────────
  var TURNOS=['Manhã','Tarde','Noite 1','Noite 2','Noite'];
  var ESCALAS=['4x1','4x2','3x2','3x3'];
  var turnoIcons={'Manhã':'🌅','Tarde':'☀️','Noite':'🌙'};
  var filtrosHtml='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:.75rem;align-items:center">'
    +'<span style="font-size:11px;color:#888">Turno:</span>'
    +TURNOS.map(function(t){
      var ativo=filtroTurno===t;
      return '<button onclick="_ppSetFiltroTurno(\''+t+'\')" style="padding:3px 10px;border-radius:6px;border:.5px solid '+(ativo?'#185FA5':'#e0dfd8')+';background:'+(ativo?'#185FA5':'#fff')+';color:'+(ativo?'#fff':'#555')+';font-size:11px;cursor:pointer">'+turnoIcons[t]+' '+t+'</button>';
    }).join('')
    +(filtroTurno?'<button onclick="_ppSetFiltroTurno(\'\')" style="padding:3px 8px;border-radius:6px;border:.5px solid #e0dfd8;background:#f5f5f3;color:#888;font-size:11px;cursor:pointer">✕</button>':'')
    +'<span style="font-size:11px;color:#888;margin-left:8px">Escala:</span>'
    +ESCALAS.map(function(s){
      var ativo=filtroEscala===s;
      return '<button onclick="_ppSetFiltroEscala(\''+s+'\')" style="padding:3px 10px;border-radius:6px;border:.5px solid '+(ativo?'#3B6D11':'#e0dfd8')+';background:'+(ativo?'#3B6D11':'#fff')+';color:'+(ativo?'#fff':'#555')+';font-size:11px;cursor:pointer">'+s+'</button>';
    }).join('')
    +(filtroEscala?'<button onclick="_ppSetFiltroEscala(\'\')" style="padding:3px 8px;border-radius:6px;border:.5px solid #e0dfd8;background:#f5f5f3;color:#888;font-size:11px;cursor:pointer">✕</button>':'')
    +'</div>';

  // ── Separar folga vs ativas ──────────────────────
  var emFolga=eqs.filter(function(eq){return equipeEstaEmFolga(eq,data);});
  var ativas =eqs.filter(function(eq){return !equipeEstaEmFolga(eq,data);});

  // ── Agrupar ativas por turno → cargo ────────────
  var porTurno={};
  TURNOS.forEach(function(t){porTurno[t]={};});
  ativas.forEach(function(eq){
    var turno=eq.turno_tipo||calcularTurnoTipo(eq.hora_inicio||'')||'Manhã';
    var cargo=eq.cargo||'Sem tipo';
    if(!porTurno[turno][cargo]) porTurno[turno][cargo]=[];
    porTurno[turno][cargo].push(eq);
  });

  // ── Projetos banner ───────────────────────────────
  var projBanner='';
  if(_pp.projetoIds.length){
    var projs=progProjGetProjetos(cid);
    projBanner='<div style="background:#EBF4FD;border:.5px solid #185FA5;border-radius:8px;padding:.5rem 1rem;margin-bottom:.75rem;font-size:12px">'
      +'<span style="font-weight:600;color:#185FA5">📋 Projetos do dia: </span>'
      +_pp.projetoIds.map(function(pid){
        var p=projs.find(function(x){return x.id===pid;});
        return p?'<span style="background:#185FA5;color:#fff;border-radius:4px;padding:1px 6px;margin-left:4px">'+p.nome+'</span>':'';
      }).join('')
      +'</div>';
  }

  // ── Quadro por turno → cargo ───────────────────
  var corTurno={'Manhã':'#185FA5','Tarde':'#854F0B','Noite':'#1a1a18'};
  var quadroHtml=TURNOS.map(function(turno){
    var cargos=porTurno[turno]||{};
    if(!Object.keys(cargos).length) return '';
    var eqsDoTurno=[];
    Object.keys(cargos).forEach(function(c){cargos[c].forEach(function(e){eqsDoTurno.push(e);});});
    var hInis=eqsDoTurno.filter(function(e){return e.hora_inicio;}).map(function(e){return e.hora_inicio;}).sort();
    var hFims=eqsDoTurno.filter(function(e){return e.hora_fim;}).map(function(e){return e.hora_fim;}).sort();
    var horaLabel=hInis.length?' <span style="opacity:.7;font-size:11px">'+hInis[0]+'–'+(hFims[hFims.length-1]||'—')+'</span>':'';

    return '<div style="margin-bottom:1.5rem">'
      +'<div style="background:'+corTurno[turno]+';color:#fff;padding:.6rem 1rem;border-radius:8px;margin-bottom:.5rem;display:flex;align-items:center;justify-content:space-between">'
      +'<span style="font-weight:700;font-size:14px">'+turnoIcons[turno]+' Turno '+turno+horaLabel+'</span>'
      +'<span style="font-size:11px;opacity:.7">'+eqsDoTurno.length+' equipe(s)</span>'
      +'</div>'
      +Object.keys(cargos).sort().map(function(cargo){
        var eqsG=cargos[cargo];
        var maxSlots=3;
        eqsG.forEach(function(eq){
          var comp=composicao_dia.find(function(c){var cd=(c.data||'').split('T')[0];return c.equipe_id===eq.id&&(cd===data||c.data===data);});
          var allIds=comp?parseJsonField(comp.colaborador_ids,[]):[];
          var ns=Math.min(7,Math.max(3,allIds.length));
          if(ns>maxSlots)maxSlots=ns;
        });
        var rows=eqsG.map(function(eq){return ppRenderEquipeRow(eq,data,cid,maxSlots);}).join('');
        var thSlots='';
        for(var ti=0;ti<maxSlots;ti++) thSlots+='<th style="padding:6px 10px;text-align:left;min-width:100px">T'+(ti+1)+'</th>';
        return '<div style="margin-bottom:.75rem">'
          +'<div style="font-size:11px;font-weight:700;color:#555;padding:4px 8px;background:#f5f5f3;border-radius:4px;margin-bottom:4px">'+cargo+'</div>'
          +'<div style="border:.5px solid #e0dfd8;border-radius:0 0 8px 8px;overflow-x:auto">'
          +'<table style="width:100%;border-collapse:collapse;min-width:700px">'
          +'<thead><tr style="background:#f9f9f7;font-size:10px;color:#888;text-transform:uppercase">'
          +'<th style="padding:6px 10px;text-align:left;width:100px;position:sticky;left:0;background:#f9f9f7">Equipe</th>'
          +thSlots
          +'<th style="padding:6px 4px;width:34px"></th>'
          +'<th style="padding:6px 10px;text-align:left;min-width:120px">🚗 Veículo</th>'
          +'<th style="padding:6px 10px;text-align:left;min-width:150px">📋 Projetos</th>'
          +'<th style="padding:6px 10px;text-align:center;width:90px">Status</th>'
          +'<th style="padding:6px 10px;width:120px"></th>'
          +'</tr></thead><tbody>'+rows+'</tbody></table></div></div>';
      }).join('')
      +'</div>';
  }).join('');

  // ── Equipes em folga ─────────────────────────────
  var folgaHtml=emFolga.length
    ?'<div style="margin-bottom:1.5rem">'
      +'<div style="background:#888;color:#fff;padding:.6rem 1rem;border-radius:8px;margin-bottom:.5rem;display:flex;align-items:center;justify-content:space-between">'
      +'<span style="font-weight:700">🏖 Em Folga</span><span style="font-size:11px;opacity:.7">'+emFolga.length+' equipe(s)</span></div>'
      +'<div style="border:.5px solid #e0dfd8;border-radius:8px;overflow:hidden">'
      +'<table style="width:100%;border-collapse:collapse">'
      +'<tbody>'
      +emFolga.map(function(eq){
        var turno=eq.turno_tipo||calcularTurnoTipo(eq.hora_inicio||'');
        var escLabel={'4x1':'4x1 (sex)','4x2':'4x2 (qua/qui)','3x2':'3x2 (seg/ter)','3x3':'3x3 (sab/dom)'}[eq.escala]||eq.escala||'—';
        return '<tr style="background:#f9f9f7;opacity:.7">'
          +'<td style="padding:8px 10px;font-weight:600;font-size:12px;color:#888">'+eq.nome_equipe+'</td>'
          +'<td style="padding:8px 10px;font-size:11px;color:#888">'+turnoIcons[turno]+' '+turno+'</td>'
          +'<td style="padding:8px 10px;font-size:11px;color:#888">'+escLabel+'</td>'
          +'<td style="padding:8px 10px;font-size:11px;color:#888">'+(eq.hora_inicio||'—')+'–'+(eq.hora_fim||'—')+'</td>'
          +'<td style="padding:8px 10px">'
          +'<span style="background:#e0dfd8;color:#888;font-size:10px;font-weight:600;padding:2px 8px;border-radius:4px">🏖 Folga</span>'
          +'<button onclick="ppAutorizarHoraExtra(\''+eq.id+'\')" style="margin-left:6px;padding:2px 8px;font-size:10px;border:.5px solid #854F0B;color:#854F0B;background:#fff;border-radius:4px;cursor:pointer">⚠ HE</button>'
          +'</td></tr>';
      }).join('')
      +'</tbody></table></div></div>'
    :'';

  // ── Painel de disponíveis ────────────────────────
  var dispHtml=ppRenderPainelDisp(ativas,data,cid);
  var veicHtmlP=progVeicPainel(cid,data);

  wrap.innerHTML=resumoHtml+filtrosHtml+projBanner+quadroHtml+folgaHtml+dispHtml+veicHtmlP;
  ppBindDrag();
  (function(){
    var _dataBadge=progProjGetData();
    function _ppRefreshBadgesPonto(){
      if(typeof progCarregarBadgesPonto==='function') progCarregarBadgesPonto();
    }
    if(typeof progCarregarPontoDoSupabase!=='function') return;
    if(_pontoCacheTemDia(_dataBadge)) setTimeout(_ppRefreshBadgesPonto,0);
    else progCarregarPontoDoSupabase(_dataBadge,_ppRefreshBadgesPonto);
  })();
  // Bindar botões de status e filtro dos veículos (re-render só do painel)
  setTimeout(function(){ progBindVeicPainel(wrap, cid, data); },80);
}

function _ppSetFiltroTurno(t){
  _pp.filtroTurno=t||'';
  progProjRenderQuadro();
}
function _ppSetFiltroEscala(e){
  _pp.filtroEscala=e||'';
  progProjRenderQuadro();
}
function ppAutorizarHoraExtra(eqId){
  var eq=equipes.find(function(x){return x.id===eqId;}); if(!eq)return;
  if(!confirm('Autorizar hora extra para '+eq.nome_equipe+'?\n\nA equipe está em folga conforme escala '+eq.escala+'.\nAo confirmar, ela será incluída na programação como hora extra.')){return;}
  // Marcar temporariamente como autorizado (na sessão)
  if(!_pp._horaExtraAuth) _pp._horaExtraAuth={};
  _pp._horaExtraAuth[eqId]=true;
  progShowToast('✅ Hora extra autorizada para '+eq.nome_equipe);
  progProjRenderQuadro();
}

function ppSalvarEquipe(eqId){
  return progProjetoCoreSalvarEquipe(eqId);
}

function ppRenderEquipeRow(eq, data, cid, maxSlots){
  return progProjetoCoreRenderEquipeRow(eq, data, cid, maxSlots);
}

function progProjetoCoreRenderEquipeRow(eq, data, cid, maxSlots){
  var dataNorm=(data||'').split('T')[0];
  var comp = composicao_dia.find(function(c){
    var cd=(c.data||'').split('T')[0];
    return c.equipe_id===eq.id&&(cd===dataNorm||c.data===data);
  });
  var allIds = comp ? parseJsonField(comp.colaborador_ids,[]) : [];
  var STATUS_BLOQ = BLOQ_STATUS;
  var emOutraEq  = {};
  var emOutraEqNome = {};
  composicao_dia.forEach(function(c){
    var cd=(c.data||'').split('T')[0];
    if(cd!==dataNorm||c.equipe_id===eq.id) return;
    parseJsonField(c.colaborador_ids,[]).forEach(function(id){
      if(!id) return;
      emOutraEq[id]=true;
      var eqO=progProjetoCoreFindEquipe?progProjetoCoreFindEquipe(c.equipe_id):null;
      emOutraEqNome[id]=eqO?(eqO.nome_equipe||eqO.codigo||'outra'):'outra equipe';
    });
  });
  // numSlots para esta equipe; padiar até maxSlots do grupo para alinhar colunas
  var vincCount = progFiltrarColsProgramacao(cid).filter(function(c){ return String(c.equipe_id)===String(eq.id); }).length;
  var minSlotsEq = progEquipeEhViabilidade(eq) ? 1 : 3;
  var eqSlots = Math.min(7, Math.max(minSlotsEq, allIds.length, vincCount||0));
  var numSlots = maxSlots ? Math.max(eqSlots, maxSlots) : eqSlots;
  numSlots = Math.min(numSlots, 7);

  // Slots posicionais (T1/T2/T3…) — null preserva vaga; não compactar (evita deslocar para esquerda)
  var slotIds = parseColabIdsSlots(comp ? comp.colaborador_ids : '[]', numSlots);
  while(slotIds.length < numSlots) slotIds.push(null);
  var idsOcupados = slotIds.filter(Boolean);

  var slots = [];
  var slotsMeta = []; // {motivo:'bloq'|'outra'|'memoria'|null, status, outraNome}
  for(var si=0; si<numSlots; si++){
    var sid = slotIds[si] || null;
    var scol=sid?colaboradores.find(function(c){return c.id===sid;}):null;
    var meta={motivo:null, status:null, outraNome:null, sid:sid};
    if(sid && !scol){
      meta.motivo='memoria';
    } else if(scol){
      var sst=_progStatus[scol.id]||'disponivel';
      meta.status=sst;
      if(BLOQ_STATUS.indexOf(sst)>=0){
        meta.motivo='bloq';
        // Mantém o colaborador visível (opaco) — não “some” do slot
      } else if(emOutraEq[scol.id]){
        meta.motivo='outra';
        meta.outraNome=emOutraEqNome[scol.id]||'outra equipe';
      }
    }
    slots.push(scol);
    slotsMeta.push(meta);
  }
  var confirmada = comp && comp.confirmada;
  function renderSlot(col,pos,eqId){
    var lbl='T'+(pos+1);
    var meta=slotsMeta[pos]||{};
    if(confirmada){
      if(!col){
        if(meta.motivo==='memoria'&&meta.sid){
          return '<td style="padding:4px 8px"><div style="border:1.5px solid #F5C4C4;border-radius:6px;padding:5px 8px;min-width:80px;color:#A32D2D;font-size:10px;text-align:center;background:#FFF5F5" title="ID na escala mas colaborador não carregado na memória">⚠ '+lbl+' sumiu</div></td>';
        }
        return '<td style="padding:4px 8px"><div style="border:1.5px solid #e0dfd8;border-radius:6px;padding:5px 8px;min-width:80px;color:#bbb;font-size:11px;text-align:center;background:#f5f5f3">'+lbl+'</div></td>';
      }
      var si2=PROG_STATUS[progProjetoCoreStatusColab(col.id)]||PROG_STATUS.disponivel;
      var cnhBConf=_progColabCnhBadge(col);
      var _pontoBadge2=_pontoBadgeSlotHtml(col,data);
      return '<td style="padding:4px 8px"><div style="background:'+si2.bg+';border:.5px solid '+si2.cor+'44;border-radius:6px;padding:4px 8px;min-width:90px;font-size:11px;opacity:.85;position:relative" title="'+escHtml(col.nome)+'"><div style="position:absolute;top:2px;right:3px;font-size:10px">🔒</div><div style="font-weight:600;color:'+si2.cor+';font-size:11px;padding-right:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center">'+cnhBConf+escHtml(col.nome)+'</div><div style="font-size:9px;color:#888">RE '+(col.re||'—')+'</div><div style="font-size:9px;color:#666;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px">'+(col.cargo||'')+'</div><div style="font-size:9px;color:'+si2.cor+';margin-top:1px">'+si2.label+'</div>'+_pontoBadge2+'</div></td>';
    }
    if(!col){
      if(meta.motivo==='memoria'&&meta.sid){
        return '<td style="padding:4px 8px"><div style="border:1.5px solid #F5C4C4;border-radius:6px;padding:5px 8px;min-width:90px;color:#A32D2D;font-size:10px;background:#FFF5F5" title="Colaborador está na composição do banco mas não está carregado na tela. Clique em Atualizar.">⚠ '+lbl+' na escala (não carregou)<div style="font-size:8px;margin-top:2px;opacity:.8">ID…'+String(meta.sid).slice(0,8)+'</div></div></td>';
      }
      return '<td style="padding:4px 8px">'
        +'<div class="pp-slot pp-slot-vazio" id="ppslot-vz-'+eqId+'-'+pos+'" '
        +'data-eq="'+eqId+'" data-pos="'+pos+'" '
        +'style="border:1.5px dashed #aaa;border-radius:6px;padding:5px 8px;min-width:80px;color:#666;font-size:11px;text-align:center;cursor:pointer;background:#fafaf8" '
        +'ondragover="ppDragOver(event)" ondrop="ppDrop(event,\''+eqId+'\','+pos+')">'
        +'<b style="font-size:14px;opacity:.5">+</b> '+lbl+'</div></td>';
    }
    var st2=progProjetoCoreStatusColab(col.id);
    var stI=PROG_STATUS[st2]||PROG_STATUS.disponivel;
    var pp=(col.nome||'').split(' ');
    var nm=pp.length>=3?pp[0]+' '+pp[1]+' '+pp[pp.length-1]:col.nome;
    var isFolg2 = pos>=2;
    var BG_F2='#FFF0E0', COR_F2='#E65C00';
    var isBloqSlot = meta.motivo==='bloq';
    var isOutraSlot = meta.motivo==='outra';
    var compSlotPP = composicao_dia.find(function(c){return c.equipe_id===eqId&&((c.data||'').split('T')[0]===dataNorm||c.data===data);});
    var isMotPP = compSlotPP && compSlotPP.motorista_id === col.id;
    var motBadgePP = isMotPP ? '<div style="margin-top:2px;background:#185FA5;color:#fff;border-radius:4px;padding:1px 5px;font-size:9px;font-weight:700;display:inline-block">🚗 Dirigida</div>' : '';
    if(isMotPP && typeof fmdAvaliarCnh==='function') motBadgePP += fmdBadgeHtml(fmdAvaliarCnh(col));
    var ppInfo = progProjetoCoreStatusInfoColab(col.id);
    var cnhBadgePP = _progColabCnhBadge(col);
    var warnExtra = isBloqSlot
      ? '<div style="margin-top:2px;font-size:9px;color:#A32D2D;font-weight:700">⚠ Ocultava por status — '+stI.label+'</div>'
      : (isOutraSlot ? '<div style="margin-top:2px;font-size:9px;color:#854F0B;font-weight:700">⚠ Também em '+escHtml(meta.outraNome||'outra')+'</div>' : '');
    var slotOpacity = (isBloqSlot||isOutraSlot) ? 'opacity:.7;' : '';
    var slotBorder = isBloqSlot ? '#A32D2D' : (isOutraSlot ? '#854F0B' : (isFolg2?COR_F2:stI.cor+'44'));
    return '<td style="padding:4px 8px">'
      +'<div class="pp-slot" id="ppslot-'+eqId+'-'+pos+'" draggable="true" '
      +'data-colab="'+col.id+'" data-eq="'+eqId+'" data-pos="'+pos+'" '
      +'ondragstart="ppDragStart(event,\''+col.id+'\',\''+eqId+'\')" '
      +'ondragover="ppDragOver(event)" ondrop="ppDrop(event,\''+eqId+'\','+pos+')" '
      +'title="'+escHtml(col.nome)+'" style="'+slotOpacity+'background:'+(isFolg2?BG_F2:stI.bg)+';border:1.5px solid '+slotBorder+';border-radius:6px;padding:4px 8px;min-width:90px;cursor:grab;font-size:11px;position:relative">'
      +'<div style="font-weight:600;color:'+(isFolg2?COR_F2:stI.cor)+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:11px;padding-right:14px;display:flex;align-items:center">'+(isFolg2?'<span style="font-size:9px;background:'+COR_F2+';color:#fff;border-radius:3px;padding:0 3px;margin-right:3px">T'+(pos+1)+'</span>':'')+cnhBadgePP+escHtml(col.nome)+'</div>'
      +'<div style="font-size:9px;color:#888;margin-top:1px">RE '+(col.re||'—')+'</div>'
      +'<div style="font-size:9px;color:#666;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px">'+(col.cargo||'')+'</div>'
      +'<div style="font-size:9px;color:'+(isFolg2?COR_F2:stI.cor)+';margin-top:2px">'+stI.label+'</div>'
      +warnExtra
      +(progObsCardPorStatus(st2, ppInfo, stI))
      +motBadgePP
      +_pontoBadgeSlotHtml(col, data)
      +'<div style="position:absolute;top:1px;right:3px;cursor:pointer;font-size:14px;font-weight:900;color:#333;line-height:1;user-select:none" '
      +'onclick="ppMenuSlot(\''+col.id+'\',\''+eqId+'\','+pos+')">⋮</div>'
      +'</div></td>';
  }
  var ativos=slots.filter(function(c,i){
    if(!c) return false;
    var m=slotsMeta[i]||{};
    if(m.motivo==='bloq'||m.motivo==='outra') return false;
    return (_progStatus[c.id]||'disponivel')==='disponivel';
  }).length;
  var ocultos=slotsMeta.filter(function(m){return m&&(m.motivo==='bloq'||m.motivo==='outra'||m.motivo==='memoria');}).length;
  var emFolgaEq = equipeEstaEmFolga(eq, data);
  var heAuth = _pp._horaExtraAuth && _pp._horaExtraAuth[eq.id];
  var st,stBg,stTxt;
  var minColPP = progMinColaboradoresEquipe(eq);
  if(emFolgaEq && !heAuth){ st='🏖 Folga';stBg='#f0f0f0';stTxt='#888'; }
  else if(confirmada)        { st='✓ Programada';stBg='#EAF3DE';stTxt='#3B6D11'; }
  else if(!idsOcupados.length) { st='Não prog.';   stBg='#f5f5f3';stTxt='#888'; }
  else if(ocultos>0 && ativos<minColPP){ st='⚠ Conflito/status'; stBg='#FEF3E2';stTxt='#854F0B'; }
  else if(ativos>=minColPP)  { st='Completa';    stBg='#D4EDDA';stTxt='#3B6D11'; }
  else if(ativos===1 && minColPP>1) { st='Falta 1'; stBg='#FEF3E2';stTxt='#854F0B'; }
  else                       { st='Parada';      stBg='#FCEBEB';stTxt='#A32D2D'; }

  // Info de turno e escala para exibir na célula da equipe
  var turnoEq=eq.turno_tipo||calcularTurnoTipo(eq.hora_inicio||'');
  var turnoLabel=eq.hora_inicio?turnoEq+' '+eq.hora_inicio+(eq.hora_fim?'–'+eq.hora_fim:''):'';
  var escalaLabel=eq.escala?'📅 '+eq.escala:'';
  var heLabel=heAuth?'<span style="font-size:9px;background:#854F0B;color:#fff;border-radius:3px;padding:1px 4px;margin-left:3px">HE</span>':'';

  // Verificar conflito de veículo programado para esta equipe
  var veicProg=progGetVeiculo(eq.id, data);
  var conflito=null;
  if(veicProg&&veicProg.id&&eq.hora_inicio&&eq.hora_fim){
    conflito=verificarConflitoVeiculo(veicProg.id,eq.id,eq.hora_inicio,eq.hora_fim,data);
  }
  var ppPIds=[]; try{ppPIds=JSON.parse((comp&&comp.projeto_ids)||'[]');}catch(e){}
  if(!Array.isArray(ppPIds))ppPIds=[];
  var ppProjs=typeof progProjGetProjetos==='function'?progProjGetProjetos(cid):[];
  var ppPH='<div style="display:flex;flex-direction:column;gap:1px">'
    +ppPIds.map(function(pid){var p=ppProjs.find(function(x){return x.id===pid;});return p?'<div style="display:flex;align-items:center;gap:2px;background:#EBF4FD;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:10px;margin:1px 0">'+p.nome+'<span onclick="ppEqRemoverProjeto(\''+eq.id+'\',\''+pid+'\')" style="cursor:pointer;color:#A32D2D;margin-left:3px">&#x2715;</span></div>':'';}).join('')
    +'<div onclick="ppEqSelecionarProjetos(\''+eq.id+'\')" style="cursor:pointer;background:#f5f5f3;border:.5px dashed #bbb;border-radius:4px;padding:2px 7px;font-size:10px;color:#888;margin-top:2px;display:inline-block">+ projeto</div></div>';
  var addCol=(!confirmada&&numSlots<7)
    ?'<td style="padding:4px 4px;vertical-align:middle;text-align:center"><button onclick="ppAdicionarSlot(\''+eq.id+'\')" title="T'+(numSlots+1)+'" style="width:26px;height:26px;border-radius:50%;border:2px dashed #185FA5;background:#EBF4FD;color:#185FA5;cursor:pointer;font-size:16px;font-weight:700;line-height:1;display:inline-flex;align-items:center;justify-content:center">+</button></td>'
    :'<td style="width:30px"></td>';
  var ppSupConf = comp && comp.sup_confirmada;
  var ppTrStyle = ppSupConf
    ? 'background:#EDF5FD;border-left:3px solid #185FA5;border-bottom:.5px solid #c3dff7;vertical-align:top'
    : 'border-bottom:.5px solid #f5f5f3;vertical-align:top'+(emFolgaEq&&!heAuth?';opacity:.65;background:#f9f9f7':'');
  return '<tr style="'+ppTrStyle+'" id="pprow-eq-'+eq.id+'">'
    +'<td style="padding:4px 10px;font-weight:700;font-size:12px;white-space:nowrap;position:sticky;left:0;background:#fff">'+eq.nome_equipe+heLabel
    +'<div style="font-size:10px;color:#888;font-weight:400">'+eq.supervisor+'</div>'
    +(turnoLabel?'<div style="font-size:9px;color:#185FA5">'+turnoLabel+'</div>':'')
    +(escalaLabel?'<div style="font-size:9px;color:#3B6D11">'+escalaLabel+'</div>':'')
    +(emFolgaEq&&!heAuth?'':_telCellHtml(eq, confirmada, 'ppSalvarTelefoneEquipe'))
    +'</td>'
    +slots.map(function(col,pos){return renderSlot(col,pos,eq.id);}).join('')
    +addCol
    +'<td style="padding:4px 6px;min-width:120px;vertical-align:top" id="pp-veic-cell-'+eq.id+'">'
    +(emFolgaEq&&!heAuth
      ?'<div style="font-size:10px;color:#aaa;padding:4px 6px">—</div>'
      :(confirmada?progRenderVeiculoCellBloqueado(eq,data):progRenderVeiculoCell(eq,data))
    )
    +(conflito?'<div style="font-size:9px;color:#A32D2D;margin-top:2px">⚠ Conflito: '+conflito.nome_equipe+'</div>':'')
    +'</td>'
    +'<td style="padding:4px 6px;vertical-align:top">'+ppPH+'</td>'
    +'<td style="padding:4px 8px;text-align:center;vertical-align:top"><span style="background:'+stBg+';color:'+stTxt+';font-size:10px;font-weight:600;padding:2px 6px;border-radius:4px">'+st+'</span></td>'
    +'<td style="padding:4px 6px;vertical-align:top;display:flex;flex-direction:column;gap:3px">'
    +(emFolgaEq&&!heAuth
      ?'<button onclick="ppAutorizarHoraExtra(\''+eq.id+'\')" style="font-size:10px;padding:3px 6px;border:.5px solid #854F0B;color:#854F0B;background:#fff;border-radius:4px;cursor:pointer;white-space:nowrap">⚠ HE</button>'
      :confirmada
        ?'<button class="btn btn-sm" onclick="ppDesprogramarEquipe(\''+eq.id+'\')" style="font-size:10px;padding:2px 6px;white-space:nowrap;color:#A32D2D;border-color:#A32D2D">↩ Desprog.</button>'
         +(ppSupConf?'<button class="btn btn-sm" onclick="ppSupConfirmar(\''+eq.id+'\',false)" style="font-size:10px;padding:2px 6px;white-space:nowrap;background:#185FA5;color:#fff;border-color:#185FA5">✓ Saída OK</button>':'<button class="btn btn-sm" onclick="ppSupConfirmar(\''+eq.id+'\',true)" style="font-size:10px;padding:2px 6px;white-space:nowrap;color:#185FA5;border-color:#185FA5">☐ Conf. saída</button>')
         +'<button onclick="ppEnviarWhatsApp(\''+eq.id+'\')" style="font-size:10px;padding:2px 6px;border:.5px solid #25D366;color:#25D366;background:#fff;border-radius:4px;cursor:pointer;white-space:nowrap">📲</button>'
        :'<button class="btn btn-sm" onclick="ppAutoEscalarEquipe(\''+eq.id+'\')" style="font-size:10px;padding:2px 6px;white-space:nowrap">Auto Escalar</button>'
         +'<button class="btn btn-sm btn-pri" onclick="ppSalvarEquipe(\''+eq.id+'\')" style="font-size:10px;padding:2px 6px;white-space:nowrap">💾 Salvar</button>'
    )+'</td></tr>';
}

// ══════════════════════════════════════════════════════════════
// MODO MOBILE — PROGRAMAÇÃO DE PROJETOS
// ══════════════════════════════════════════════════════════════
var _ppMobileAtivo = false;

function ppMobileToggle(){
  _ppMobileAtivo = !_ppMobileAtivo;
  var btn = document.getElementById('pp-btn-mobile');
  var painel = document.getElementById('pp-painel-programacao');
  var mobile = document.getElementById('pp-mobile-view');
  if(_ppMobileAtivo){
    if(painel) painel.style.display = 'none';
    if(mobile) mobile.style.display = '';
    if(btn){ btn.style.background='#533AB7'; btn.style.color='#fff'; btn.textContent='🖥 Desktop'; }
    ppMobileRenderLista();
  } else {
    if(painel) painel.style.display = '';
    if(mobile) mobile.style.display = 'none';
    if(btn){ btn.style.background=''; btn.style.color='#533AB7'; btn.textContent='📱 Mobile'; }
  }
}

function ppMobileRenderLista(){
  var mobile = document.getElementById('pp-mobile-view');
  if(!mobile) return;
  var data = progProjGetData();
  var cid = progProjGetCid();
  // Se supervisor tem contrato único, usar o dele
  if(!cid && usuarioLogado && usuarioLogado.contrato_id){
    var cids = (usuarioLogado.contrato_id||'').split(',').map(function(s){return s.trim();}).filter(Boolean);
    if(cids.length === 1) cid = cids[0];
  }

  var buscaAtual = (document.getElementById('pp-mob-busca')||{}).value || '';
  var tipoAtual = window._ppMobTipo || '';

  var html = '<div style="padding:8px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">'
    +'<div style="font-size:15px;font-weight:700">📋 Projetos — '+fmtD(data)+'</div>'
    +'<div style="display:flex;gap:4px">'
    +'<button id="pp-mob-prev" style="padding:5px 8px;border-radius:6px;border:.5px solid #e0dfd8;background:#fff;cursor:pointer">◀</button>'
    +'<button id="pp-mob-next" style="padding:5px 8px;border-radius:6px;border:.5px solid #e0dfd8;background:#fff;cursor:pointer">▶</button>'
    +'</div></div>'
    // Filtros de tipo
    +'<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px">'
    +[{v:'',l:'Todos'},{v:'LM',l:'Linha Morta'},{v:'LV',l:'Linha Viva'},{v:'VIA',l:'Viabilidade'}].map(function(t){
      var a = tipoAtual===t.v;
      return '<button class="pp-mob-tipo" data-tipo="'+t.v+'" style="padding:5px 10px;border-radius:16px;font-size:11px;font-weight:600;cursor:pointer;border:none;background:'+(a?'#1A1A18':'#fff')+';color:'+(a?'#fff':'#555')+(a?'':';border:.5px solid #e0dfd8')+'">'+t.l+'</button>';
    }).join('')
    +'</div>'
    +'<input id="pp-mob-busca" placeholder="🔍 Buscar equipe..." value="'+escHtml(buscaAtual)+'" '
    +'style="width:100%;padding:10px;border:.5px solid #e0dfd8;border-radius:8px;font-size:14px;margin-bottom:8px;box-sizing:border-box">'
    +'<div id="pp-mob-lista"></div>'
    +'</div>';

  mobile.innerHTML = html;

  // Eventos
  var btnPrev = document.getElementById('pp-mob-prev');
  var btnNext = document.getElementById('pp-mob-next');
  var inp = document.getElementById('pp-mob-busca');

  if(btnPrev) btnPrev.addEventListener('click', function(){ ppNavData(-1); setTimeout(ppMobileRenderLista, 200); });
  if(btnNext) btnNext.addEventListener('click', function(){ ppNavData(1); setTimeout(ppMobileRenderLista, 200); });
  if(inp) inp.addEventListener('input', function(){ ppMobileAtualizarLista(this.value, window._ppMobTipo||''); });

  mobile.querySelectorAll('.pp-mob-tipo').forEach(function(btn){
    btn.addEventListener('click', function(){
      window._ppMobTipo = this.getAttribute('data-tipo');
      ppMobileRenderLista();
    });
  });

  ppMobileAtualizarLista(buscaAtual, tipoAtual);
}

function ppMobileAtualizarLista(busca, tipo){
  var container = document.getElementById('pp-mob-lista');
  if(!container) return;
  var data = progProjGetData();
  var cid = progProjGetCid();
  if(!cid && usuarioLogado && usuarioLogado.contrato_id){
    var cids = (usuarioLogado.contrato_id||'').split(',').map(function(s){return s.trim();}).filter(Boolean);
    if(cids.length === 1) cid = cids[0];
  }
  var b = (busca||'').toLowerCase();

  var eqs = progProjetoCoreGetEquipes(cid, {}).filter(function(e){
    if(tipo && (e.tipo||e.cargo||'').indexOf(tipo)<0 && e.nome_equipe.indexOf(tipo)<0) return false;
    if(b && (e.nome_equipe||'').toLowerCase().indexOf(b)<0) return false;
    return true;
  });

  if(!eqs.length){ container.innerHTML='<div style="text-align:center;padding:2rem;color:#aaa">Nenhuma equipe encontrada</div>'; return; }

  container.innerHTML = eqs.map(function(eq){
    var comp = composicao_dia.find(function(c){return c.equipe_id===eq.id&&(c.data||'').slice(0,10)===data&&!c.deleted_at;});
    var ids = comp ? parseJsonField(comp.colaborador_ids,[]).filter(Boolean) : [];
    var membros = ids.map(function(id){return colaboradores.find(function(c){return c.id===id;});}).filter(Boolean);
    var confirmada = comp && comp.confirmada;
    var supConf = comp && comp.sup_confirmada;
    var bgCard = supConf?'#EDF5FD':confirmada?'#F0FAF0':'#fff';
    var statusLabel = supConf?'✅ Saída OK':confirmada?'✅ Programada':(ids.length?'📝 Rascunho':'⬜ Vazia');
    var statusCor = supConf?'#185FA5':confirmada?'#3B6D11':(ids.length?'#854F0B':'#aaa');
    var statusBg  = supConf?'#EDF5FD':confirmada?'#EAF3DE':(ids.length?'#FEF3E2':'#f5f5f3');

    return '<div style="background:'+bgCard+';border:.5px solid #e0dfd8;border-radius:10px;padding:12px;margin-bottom:8px;box-shadow:0 1px 4px #0001'+(supConf?';border-left:3px solid #185FA5':'')+'">'
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">'
      +'<div style="font-size:15px;font-weight:700">'+escHtml(eq.nome_equipe)+'</div>'
      +'<span style="font-size:10px;font-weight:600;padding:2px 8px;border-radius:10px;background:'+statusBg+';color:'+statusCor+'">'+statusLabel+'</span>'
      +'</div>'
      +'<div style="font-size:12px;color:#555;margin-bottom:8px">👥 '+membros.length+' colaborador'+(membros.length!==1?'es':'')
      +(membros.length?': '+membros.map(function(m){
        var key=(m.re||'')+'_'+data; var p=_pontoCache[key];
        var ent=p&&(p.entrada||(p.todas_marcacoes&&p.todas_marcacoes.some(function(x){return x.tipo==='Entrada';})));
        var badge=ent?'<span style="background:#3B6D11;color:#fff;border-radius:3px;padding:0 3px;font-size:8px">✓</span>':(p&&p.status==='falta'?'<span style="background:#A32D2D;color:#fff;border-radius:3px;padding:0 3px;font-size:8px">●</span>':'');
        return escHtml(m.nome.split(' ')[0])+' '+badge;
      }).join(' / '):'')
      +'</div>'
      +(confirmada
        ?'<div style="display:flex;gap:6px">'
          +'<button data-eq="'+eq.id+'" class="pp-mob-btn-conf" style="flex:1;padding:10px;border-radius:8px;border:none;background:'+(supConf?'#185FA5':'#fff')+';color:'+(supConf?'#fff':'#185FA5')+';font-size:13px;font-weight:600;cursor:pointer;border:.5px solid #185FA5">'+(supConf?'✓ Saída OK':'☐ Confirmar saída')+'</button>'
          +'</div>'
        :'<button data-eq="'+eq.id+'" class="pp-mob-btn-edit" style="width:100%;padding:10px;border-radius:8px;border:none;background:#1A1A18;color:#fff;font-size:13px;font-weight:600;cursor:pointer">✏️ Ver equipe</button>'
      )
      +'</div>';
  }).join('');

  // Eventos
  container.querySelectorAll('.pp-mob-btn-conf').forEach(function(btn){
    btn.addEventListener('click', function(){
      var eqId = this.getAttribute('data-eq');
      var comp = composicao_dia.find(function(c){return c.equipe_id===eqId&&(c.data||'').slice(0,10)===data&&!c.deleted_at;});
      var novoVal = !(comp&&comp.sup_confirmada);
      ppSupConfirmar(eqId, novoVal);
      setTimeout(ppMobileRenderLista, 300);
    });
  });

  container.querySelectorAll('.pp-mob-btn-edit').forEach(function(btn){
    btn.addEventListener('click', function(){
      ppMobileToggle(); // Voltar para desktop e ir para a equipe
      setTimeout(function(){
        var el = document.getElementById('pprow-eq-'+btn.getAttribute('data-eq'));
        if(el) el.scrollIntoView({behavior:'smooth', block:'center'});
      }, 400);
    });
  });
}

function ppSupConfirmar(eqId, confirmar){
  var data = progProjGetData();
  var comp = composicao_dia.find(function(c){
    return c.equipe_id===eqId && (c.data||'').slice(0,10)===data && !c.deleted_at;
  });
  if(!comp){ progShowToast('Equipe não encontrada'); return; }
  if(!comp.confirmada){ progShowToast('Salve a programação antes de confirmar saída'); return; }
  comp.sup_confirmada = confirmar;
  if(!DEMO){
    sbUpdate('composicao_dia', {sup_confirmada: confirmar}, 'id=eq.'+comp.id)
      .then(function(){
        progShowToast(confirmar ? '✅ Saída confirmada' : '↩ Confirmação removida');
        progProjRenderQuadro();
      });
  } else {
    progShowToast(confirmar ? '✅ Saída confirmada' : '↩ Confirmação removida');
    progProjRenderQuadro();
  }
}

function ppAdicionarSlot(eqId){
  var data = progProjGetData() || dataHoje();
  if(!data){ progShowToast('⚠ Selecione uma data primeiro'); return; }
  var comp = composicao_dia.find(function(c){return c.equipe_id===eqId&&c.data===data;});
  if(!comp){
    comp = {id:'local_pp_'+eqId+'_'+data, equipe_id:eqId, data:data,
      colaborador_ids:JSON.stringify([null,null,null]), confirmada:false, _local:true};
    composicao_dia.push(comp);
  }
  var ids = parseJsonField(comp.colaborador_ids, []);
  if(ids.length >= 7){ progShowToast('Máximo de 7 slots por equipe'); return; }
  ids.push(null);
  comp.colaborador_ids = JSON.stringify(ids);
  if(!DEMO && !comp._local && comp.id && !comp.id.startsWith('local_')){
    sbUpdate('composicao_dia',{colaborador_ids:ids},'id=eq.'+comp.id);
  }
  progProjRenderQuadro();
  progShowToast('T'+(ids.length)+' adicionado');
}

function ppDesprogramarEquipe(eqId){
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:380px">'
    +'<h3 style="margin-bottom:.75rem">↩ Desprogramar equipe</h3>'
    +'<p style="font-size:13px;color:#555;margin-bottom:1rem">A equipe voltará ao status <b>Completa</b> e os integrantes e veículo poderão ser alterados.</p>'
    +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn" onclick="ppConfirmarDesprogramar(\''+eqId+'\')" style="color:#A32D2D;border-color:#A32D2D">↩ Confirmar</button>'
    +'</div></div></div>');
}

function ppConfirmarDesprogramar(eqId){
  var data=progProjGetData()||dataHoje();
  var comp=composicao_dia.find(function(c){
    var cd=(c.data||'').split('T')[0];
    return c.equipe_id===eqId&&(cd===data||c.data===data);
  });
  if(comp){
    comp.confirmada=false;
    if(!DEMO&&!comp._local&&comp.id&&!comp.id.startsWith('local_'))
      sbUpdate('composicao_dia',{confirmada:false},'id=eq.'+comp.id);
  }
  closeModal();
  progProjRenderQuadro();
  progShowToast('↩ Equipe desprogramada');
}


function ppRenderPainelDisp(eqs, data, cid){
  // Usar _progStatus (compartilhado com Prog. Equipes) para manter status sincronizado
  var statusRef = _progStatus; // fonte única — _progStatus é a verdade

  var cols = progFiltrarColsProgramacao(cid);

  // Agrupar por status
  var grupos_st = {};
  Object.keys(PROG_STATUS).forEach(function(k){ grupos_st[k]=[]; });
  cols.forEach(function(c){
    var st = statusRef[c.id]||'disponivel';
    if(grupos_st[st]) grupos_st[st].push(c);
    else grupos_st['disponivel'].push(c);
  });

  // Quem já está escalado hoje
  var escalados = {};
  composicao_dia.forEach(function(comp){
    var cd=(comp.data||'').split('T')[0];
    if(cd!==data && comp.data!==data) return;
    parseJsonField(comp.colaborador_ids,[]).filter(Boolean).forEach(function(id){ escalados[id]=true; });
  });

  var disp  = grupos_st['disponivel'];
  var livres = disp.filter(function(c){ return !escalados[c.id]; });

  // Indisponíveis (status bloqueante: verificar, falta, férias, etc.) — exibidos com observação abaixo do nome
  var INDISP_ST = ['folga','ferias','afastado','treinamento','falta','faltou','integracao','patio','verificar','fraude','demitido'];
  var indisp = cols.filter(function(c){ return INDISP_ST.indexOf(statusRef[c.id]||'disponivel')>=0; });
  var indispHtml = indisp.length
    ? '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:.75rem 1rem;margin-bottom:1rem">'
      +'<div style="font-size:13px;font-weight:600;color:#888;margin-bottom:.5rem">Indisponíveis ('+indisp.length+')</div>'
      +'<div style="display:flex;flex-wrap:wrap;gap:4px">'
      +indisp.map(function(c){
          var st=statusRef[c.id]||'disponivel';
          var s=PROG_STATUS[st]||{label:st,cor:'#555',bg:'#f5f5f3'};
          var info=(_progStatusInfo||{})[c.id]||{};
          var obs=info.obs||info.justificativa||'';
          var ret=info.retorno?' · retorno '+fmtD(info.retorno):'';
          return '<div style="display:inline-flex;flex-direction:column;background:'+s.bg+';border:.5px solid '+s.cor+'44;border-radius:6px;padding:4px 8px;font-size:11px;max-width:230px">'
            +'<div style="display:flex;align-items:center;gap:4px">'
            +'<span style="color:'+s.cor+';font-weight:500">'+nomeAbrev(c.nome)+'</span>'
            +'<span style="color:'+s.cor+';font-size:9px;font-weight:600">'+s.label+ret+'</span>'
            +(st==='verificar'?'<span onclick="progAbrirVerificar(\''+c.id+'\')" title="Tratar caso" style="cursor:pointer;color:#8B1A6B;font-size:10px">🔍</span>':'')
            +'<span onclick="progMenuSlot(\''+c.id+'\',null,undefined)" title="Alterar status" style="cursor:pointer;color:#888;font-size:11px;margin-left:auto">⋮</span>'
            +'</div>'
            +(obs?progObsLinhaHtml(obs, info, s):'')
            +'</div>';
        }).join('')
      +'</div></div>'
    : '';

  // Badges de contagem por status
  var countHtml = Object.keys(PROG_STATUS).map(function(k){
    var n = grupos_st[k].length;
    if(!n) return '';
    var s = PROG_STATUS[k];
    return '<div onclick="ppMostrarListaStatus(\''+k+'\')" '
      +'style="display:flex;align-items:center;gap:4px;padding:4px 8px;background:'+s.bg
      +';border-radius:6px;font-size:11px;color:'+s.cor+';font-weight:600;cursor:pointer;'
      +'border:.5px solid '+s.cor+'44">'+n+' '+s.label+' ▾</div>';
  }).join('');

  // Filtro de ponto nos disponíveis (botões — select "Todos" não disparava onchange se já parecia selecionado)
  var _filtroPontoDisp = _pp.filtroPonto || 'todos';
  if(_filtroPontoDisp!=='presentes' && _filtroPontoDisp!=='ausentes') _filtroPontoDisp='todos';
  var livresFiltrados = livres;
  if(_filtroPontoDisp === 'presentes'){
    livresFiltrados = livres.filter(function(c){
      var p=(typeof pontoCacheGet==='function')?pontoCacheGet(c.re,data):_pontoCache[(c.re||'')+'_'+data];
      return p&&(p.entrada||(p.todas_marcacoes&&p.todas_marcacoes.some(function(x){return x.tipo==='Entrada';})));
    });
  } else if(_filtroPontoDisp === 'ausentes'){
    livresFiltrados = livres.filter(function(c){
      var p=(typeof pontoCacheGet==='function')?pontoCacheGet(c.re,data):_pontoCache[(c.re||'')+'_'+data];
      return !p||(!p.entrada&&!(p.todas_marcacoes&&p.todas_marcacoes.some(function(x){return x.tipo==='Entrada';})));
    });
  }
  // Chips dos disponíveis
  var livresHtml = livresFiltrados.length
    ? livresFiltrados.map(function(c){
        return '<div class="pp-colab-chip" draggable="true" id="pp-chip-'+c.id+'" '
          +'data-colab="'+c.id+'" '
          +'ondragstart="ppDragStart(event,\''+c.id+'\',null)" '
          +'style="display:inline-flex;align-items:center;gap:4px;background:#EAF3DE;'
          +'border:.5px solid #3B6D1144;border-radius:6px;padding:4px 8px;font-size:11px;cursor:grab;margin:2px">'
          +'<span style="color:#3B6D11;font-weight:500">'+nomeAbrev(c.nome)+'</span>'
          +'<span style="color:#aaa;font-size:9px">'+(c.re||'')+'</span>'
          +(function(){ var _p=(typeof pontoCacheGet==='function')?pontoCacheGet(c.re,data):_pontoCache[(c.re||'')+'_'+data]; if(!_p) return ''; var _e=_p.entrada||(_p.todas_marcacoes&&_p.todas_marcacoes.some(function(x){return x.tipo==='Entrada';})); if(_e) return '<span style="background:#3B6D11;color:#fff;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700">✓ '+(_p.entrada||'')+'</span>'; if(_p.status==='falta'){var _hp=_p.horario_previsto||{};if(_hp.entrada&&pontoHorarioPassou(_hp,data))return '<span style="background:#A32D2D;color:#fff;border-radius:3px;padding:0 4px;font-size:8px;font-weight:700">● Aus</span>';} return ''; }())
          +'<span onclick="progMenuSlot(\''+c.id+'\',null,undefined)" title="Alterar status" '
          +'style="cursor:pointer;color:#888;font-size:12px;margin-left:2px;user-select:none" '
          +'ondragstart="event.stopPropagation()">⋮</span>'
          +'</div>';
      }).join('')
    : '<div style="color:#aaa;font-size:12px">'
      +(_filtroPontoDisp==='presentes'?'Nenhum presente no ponto entre os disponíveis.'
        :(_filtroPontoDisp==='ausentes'?'Nenhum ausente no ponto entre os disponíveis.'
          :'Todos escalados'))
      +'</div>';

  function _ppBtnPonto(val, label){
    var on=_filtroPontoDisp===val;
    return '<button type="button" onclick="ppSetFiltroPonto(\''+val+'\')" '
      +'style="font-size:11px;padding:3px 8px;border-radius:6px;cursor:pointer;'
      +'border:.5px solid '+(on?'#185FA5':'#e0dfd8')+';background:'+(on?'#185FA5':'#fff')+';'
      +'color:'+(on?'#fff':'#555')+';font-weight:'+(on?'600':'400')+'">'+label+'</button>';
  }

  return indispHtml
    +'<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:1rem;margin-bottom:1rem" id="pp-painel-disp">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem;flex-wrap:wrap;gap:6px">'
    +'<span style="font-size:13px;font-weight:600">Colaboradores disponíveis não escalados ('+livresFiltrados.length+(livresFiltrados.length!==livres.length?'/'+livres.length:'')+')</span>'
    +'<div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center">'+countHtml
    +_ppBtnPonto('todos','👥 Todos')
    +_ppBtnPonto('presentes','✓ Presentes')
    +_ppBtnPonto('ausentes','● Ausentes')
    +'</div>'
    +'</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:4px;min-height:40px;padding:8px;'
    +'background:#f9f9f7;border-radius:6px;border:.5px solid #e0dfd8" '
    +'id="pp-pool" ondragover="ppDragOver(event)" ondrop="ppDropPool(event)">'
    +livresHtml
    +'</div></div>';
}
function ppSetFiltroPonto(val){
  var v=(val||'todos').toString();
  if(v!=='presentes' && v!=='ausentes') v='todos';
  _pp.filtroPonto = v;
  // Re-render completo do quadro (garante lista + botões sincronizados)
  if(typeof progProjRenderQuadro==='function') progProjRenderQuadro();
  else if(typeof _progProjRenderQuadroInterno==='function')
    _progProjRenderQuadroInterno(progProjGetData(), progProjGetCid());
}

function ppMostrarListaStatus(status){
  var s = PROG_STATUS[status]||{label:status,cor:'#555',bg:'#f5f5f3'};
  var statusRef = _progStatus;
  var _ppCidAtual = progProjGetCid();
  var data = progProjGetData() || dataHojeLocal();
  var lista = progFiltrarColsProgramacao(_ppCidAtual).filter(function(c){
    return (statusRef[c.id]||'disponivel')===status;
  });
  var pontoRes=progListaStatusPontoResumo(lista, data);
  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:400px">'
    +'<h3 style="margin-bottom:.25rem;color:'+s.cor+'">'+s.label+' ('+lista.length+')</h3>'
    +progListaStatusPontoResumoHtml(pontoRes)
    +'<div style="max-height:350px;overflow-y:auto;display:flex;flex-direction:column;gap:4px">'
    +lista.map(function(c){
      var info = progProjetoCoreStatusInfoColab(c.id);
      return '<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;'
        +'background:'+s.bg+';border-radius:6px;font-size:12px">'
        +'<div style="flex:1;min-width:0"><div style="font-weight:600;color:'+s.cor+'">'+escHtml(c.nome)+'</div>'
        +'<div style="font-size:10px;color:#888">RE '+(c.re||'—')+' · '+(c.cargo||'')+(info.retorno?' · Retorno: '+fmtD(info.retorno):'')+'</div></div>'
        +'<div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0">'
        +progListaStatusPontoBadge(c, data)
        +'<button onclick="ppDefinirStatus(\''+c.id+'\',\'disponivel\',null)" '
        +'style="font-size:10px;padding:2px 6px;border-radius:4px;border:.5px solid #3B6D11;'
        +'background:#EAF3DE;color:#3B6D11;cursor:pointer">Liberado</button>'
        +'</div>'
        +'</div>';
    }).join('')
    +'</div><button class="btn" onclick="closeModal()" style="width:100%;margin-top:.75rem">Fechar</button>'
    +'</div></div>';
  setModal(html);
  setTimeout(function(){
    document.querySelectorAll('.mn-full-btn').forEach(function(btn){
      btn.onclick=function(){
        closeModal();
        var i=parseInt(this.getAttribute('data-mi'));
        if(itensMenu[i]) itensMenu[i].acao();
      };
    });
    // Bind do campo data de retorno
    var inpData=document.getElementById('retorno-data');
    if(inpData){
      var _orig=inpData.getAttribute('data-original')||'';
      inpData.addEventListener('change',function(){ progVerificarMudancaData(this,_orig); });
    }
  },50);
}

// ── Drag and Drop — progProjetoCore (fluxo projeto; TMA usa progDrag*) ──
var _ppDragColabId = null;
var _ppDragFromEq  = null;

function ppDragStart(event, colabId, fromEqId){
  return progProjetoCoreDragStart(event, colabId, fromEqId);
}
function progProjetoCoreDragStart(event, colabId, fromEqId){
  _ppDragColabId = colabId;
  _ppDragFromEq  = fromEqId;
  event.dataTransfer.effectAllowed = 'move';
  event.dataTransfer.setData('text/plain', colabId);
  setTimeout(function(){ if(event.target) event.target.style.opacity = '0.4'; }, 0);
}

function ppDragOver(event){
  return progProjetoCoreDragOver(event);
}
function progProjetoCoreDragOver(event){
  event.preventDefault();
  event.dataTransfer.dropEffect = 'move';
  event.currentTarget.style.outline = '2px solid #185FA5';
}

function ppDrop(event, toEqId, toPos){
  return progProjetoCoreDrop(event, toEqId, toPos);
}
function progProjetoCoreDrop(event, toEqId, toPos){
  event.preventDefault();
  event.currentTarget.style.outline = '';
  if(!_ppDragColabId) return;
  var data = progProjGetData();
  var col  = colaboradores.find(function(c){ return c.id === _ppDragColabId; });
  if(!col) return;

  var jaNaEscala = null;
  if(_ppDragFromEq && _ppDragFromEq !== toEqId){
    jaNaEscala = _ppDragFromEq;
  } else if(!_ppDragFromEq){
    composicao_dia.forEach(function(c){
      if(c.data !== data || c.equipe_id === toEqId) return;
      if(parseJsonField(c.colaborador_ids, []).indexOf(_ppDragColabId) >= 0) jaNaEscala = c.equipe_id;
    });
  }

  if(jaNaEscala){
    var eqOrig = progProjetoCoreFindEquipe(jaNaEscala);
    var eqDest = progProjetoCoreFindEquipe(toEqId);
    var dp = {cid: _ppDragColabId, from: jaNaEscala, to: toEqId, pos: toPos};
    setModal('<div class="modal-bg"><div class="modal" style="max-width:380px">'
      +'<h3>Mover ou Duplicar?</h3>'
      +'<p style="font-size:13px;color:#555"><b>'+nomeAbrev(col.nome)+'</b> já está em <b>'+(eqOrig ? eqOrig.nome_equipe : 'outra equipe')+'</b>.</p>'
      +'<div style="display:flex;flex-direction:column;gap:8px">'
      +'<button class="btn btn-pri" id="pp-drop-mv">Mover — remover da origem</button>'
      +'<button class="btn" id="pp-drop-dp">Duplicar — manter nas duas</button>'
      +'<button class="btn" onclick="closeModal()" style="color:#888">Cancelar</button>'
      +'</div>'
      +'<div style="margin-top:.5rem;padding:.5rem;background:#FEF3E2;border-radius:6px;font-size:11px;color:#854F0B">Duplicar pode causar conflito. Use com cuidado.</div>'
      +'</div></div>');
    setTimeout(function(){
      var bm = document.getElementById('pp-drop-mv');
      if(bm) bm.onclick = function(){ closeModal(); progProjetoCoreEfetuarDrop(dp.cid, dp.from, dp.to, dp.pos, false); };
      var bd = document.getElementById('pp-drop-dp');
      if(bd) bd.onclick = function(){ closeModal(); progProjetoCoreEfetuarDrop(dp.cid, dp.from, dp.to, dp.pos, true); };
    }, 50);
    _ppDragColabId = null; _ppDragFromEq = null;
    return;
  }
  progProjetoCoreEfetuarDrop(_ppDragColabId, _ppDragFromEq, toEqId, toPos, false);
  _ppDragColabId = null; _ppDragFromEq = null;
}

function ppDropPool(event){
  return progProjetoCoreDropPool(event);
}
function progProjetoCoreDropPool(event){
  event.preventDefault();
  var pool = document.getElementById('pp-pool');
  if(pool) pool.style.outline = '';
  if(!_ppDragColabId || !_ppDragFromEq) return;
  var data = progProjGetData();
  composicao_dia.forEach(function(comp){
    if(comp.data !== data) return;
    var ids = parseJsonField(comp.colaborador_ids, []);
    if(ids.indexOf(_ppDragColabId) < 0) return;
    ids = ids.map(function(id){ return id === _ppDragColabId ? null : id; });
    comp.colaborador_ids = JSON.stringify(ids);
    if(!DEMO) sbUpdate('composicao_dia', {colaborador_ids: ids}, 'id=eq.' + comp.id);
  });
  _ppDragColabId = null; _ppDragFromEq = null;
  progProjRenderQuadro();
}

function ppEfetuarDrop(colabId, fromEqId, toEqId, toPos, duplicar){
  return progProjetoCoreEfetuarDrop(colabId, fromEqId, toEqId, toPos, duplicar);
}
function progProjetoCoreEfetuarDrop(colabId, fromEqId, toEqId, toPos, duplicar){
  var data=progProjGetData();
  var dataNorm=(data||'').split('T')[0];
  var isUUID=function(id){return id&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);};
  if(!duplicar){
    composicao_dia.forEach(function(comp){
      var cd=(comp.data||'').split('T')[0];
      if(cd!==dataNorm && comp.data!==data) return;
      var ids=parseJsonField(comp.colaborador_ids,[]);
      if(ids.indexOf(colabId)<0) return;
      if(comp.equipe_id===toEqId){
        var pa=ids.indexOf(colabId);
        if(pa===toPos) return;
        ids=ids.map(function(id,i){return (id===colabId&&i!==toPos)?null:id;});
      } else {
        ids=ids.map(function(id){return id===colabId?null:id;});
      }
      comp.colaborador_ids=JSON.stringify(ids);
      if(!DEMO&&isUUID(comp.id)) sbUpdate('composicao_dia',{colaborador_ids:ids},'id=eq.'+comp.id);
    });
  }
  var comp=progFindCompDia(toEqId, data);
  var rawLen=comp?parseJsonField(comp.colaborador_ids,[]).length:0;
  var slotCount=Math.min(7, Math.max(toPos+1, rawLen, 3));
  var ids=parseColabIdsSlots(comp?comp.colaborador_ids:'[]', slotCount);
  while(ids.length<=toPos) ids.push(null);
  ids[toPos]=colabId;
  if(comp){
    comp.colaborador_ids=JSON.stringify(ids);
    if(!DEMO){
      if(isUUID(comp.id)){
        sbUpdate('composicao_dia',{colaborador_ids:ids},'id=eq.'+comp.id);
      } else {
        // Composição local — inserir no banco agora
        var payload={equipe_id:toEqId,data:data,colaborador_ids:ids,turno:'Manha',confirmada:false};
        sbInsert('composicao_dia',payload).then(function(res){
          if(res&&res[0]&&res[0].id){comp.id=res[0].id;comp._local=false;}
        });
      }
    }
  } else {
    var nova={id:'local_pp_'+toEqId+'_'+data,equipe_id:toEqId,data:data,
      colaborador_ids:ids,turno:'Manha',confirmada:false,_local:true};
    composicao_dia.push(nova);
    if(!DEMO){
      sbInsert('composicao_dia',{equipe_id:toEqId,data:data,colaborador_ids:ids,turno:'Manha',confirmada:false})
        .then(function(res){if(res&&res[0]&&res[0].id){nova.id=res[0].id;nova._local=false;}});
    }
  }
  progProjRenderQuadro();
}

function ppBindDrag(){
  return progProjetoCoreBindDrag();
}
function progProjetoCoreBindDrag(){
  var data = progProjGetData();
  document.querySelectorAll('.pp-slot-vazio[id^="ppslot-vz-"]').forEach(function(el){
    var eqId=el.getAttribute('data-eq');
    var pos=parseInt(el.getAttribute('data-pos'));
    el.onclick=function(){ progProjetoCoreBuscarParaSlot(eqId,pos); };
  });
  // Vincular botões de veículo (reutiliza a mesma função da Prog. Equipes)
  document.querySelectorAll('[id^="prog-veic-btn-"]').forEach(function(el){
    var eqId = el.id.replace('prog-veic-btn-','');
    el.onclick = function(){ progAbrirSelecionarVeiculo(eqId, data); };
  });
  document.querySelectorAll('.pp-slot,.pp-slot-vazio,.pp-slot-pool,#pp-pool').forEach(function(el){
    el.addEventListener('dragleave',function(){ el.style.outline=''; });
  });
}

function ppBuscarParaSlot(eqId, pos){
  return progProjetoCoreBuscarParaSlot(eqId, pos);
}
function progProjetoCoreBuscarParaSlot(eqId, pos){
  var cid=progProjGetCid();
  var data=progProjGetData();
  var emEscala={};
  composicao_dia.forEach(function(c){
    if(c.data!==data) return;
    parseJsonField(c.colaborador_ids,[]).forEach(function(id){if(id&&BLOQ_STATUS.indexOf(_progStatus[id]||'disponivel')<0)emEscala[id]=true;});
  });
  var STATUS_BLOQ = BLOQ_STATUS;
  var disponiveis=progFiltrarColsProgramacao(cid).filter(function(c){
    return STATUS_BLOQ.indexOf(progProjetoCoreStatusColab(c.id))<0
      && !emEscala[c.id];
  });

  var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.5rem">Buscar colaborador</h3>'
    +'<input class="inp" id="pp-slot-busca" placeholder="Buscar..." style="width:100%;margin-bottom:.5rem" oninput="ppFiltrarSlot()"/>'
    +'<div style="max-height:300px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px" id="pp-slot-lista">'
    +disponiveis.map(function(c){
      return '<div onclick="ppEscolherParaSlot(\''+eqId+'\','+pos+',\''+c.id+'\')" '
        +'style="padding:8px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8;font-size:12px;display:flex;justify-content:space-between" '
        +'onmouseover="this.style.background=\'#f5f5f3\'" onmouseout="this.style.background=\'\'">'
        +'<span style="font-weight:500">'+c.nome+'</span>'
        +'<span style="color:#888;font-size:11px">'+(c.cargo||c.re||'')+'</span></div>';
    }).join('')+(disponiveis.length===0?'<div style="padding:1rem;text-align:center;color:#aaa">Nenhum disponível</div>':'')
    +'</div>'
    +'<button class="btn" onclick="closeModal()" style="margin-top:.5rem;width:100%">Cancelar</button>'
    +'</div></div>';
  setModal(html);
  window.ppFiltrarSlot=function(){
    var q=((document.getElementById('pp-slot-busca')||{}).value||'').toLowerCase();
    document.querySelectorAll('#pp-slot-lista div[onclick]').forEach(function(el){
      el.style.display=el.textContent.toLowerCase().includes(q)?'':'none';
    });
  };
}

function ppEscolherParaSlot(eqId,pos,colabId){
  return progProjetoCoreEscolherParaSlot(eqId,pos,colabId);
}
function progProjetoCoreEscolherParaSlot(eqId,pos,colabId){
  closeModal();
  progProjetoCoreEfetuarDrop(colabId,null,eqId,pos,false);
}

