function ppEqSelecionarProjetos(eqId){
  var cid = progProjGetCid();
  var data = progProjGetData();
  var projs = typeof progProjGetProjetos==='function' ? progProjGetProjetos(cid) : [];
  if(!projs.length){ alert('Nenhum projeto encontrado para este contrato.'); return; }

  var comp = composicao_dia.find(function(c){return c.equipe_id===eqId&&c.data===data;});
  var selecionados=[]; try{selecionados=JSON.parse((comp&&comp.projeto_ids)||'[]');}catch(e){}
  if(!Array.isArray(selecionados)) selecionados=[];

  var html='<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:460px">'
    +'<h3 style="margin-bottom:.5rem">📋 Projetos da equipe</h3>'
    +'<input class="inp" id="pp-eq-proj-busca" placeholder="Buscar projeto..." style="width:100%;margin-bottom:.5rem" oninput="ppEqFiltrarProjs()"/>'
    +'<div style="max-height:300px;overflow-y:auto;border:.5px solid #e0dfd8;border-radius:8px" id="pp-eq-proj-lista">'
    +projs.map(function(p){
      var sel=selecionados.indexOf(p.id)>=0;
      return '<label style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;border-bottom:.5px solid #f0efe8;font-size:12px">'
        +'<input type="checkbox" class="pp-eq-proj-cb" value="'+p.id+'" '+(sel?'checked':'')+' style="width:14px;height:14px"/>'
        +'<span style="flex:1">'+p.nome+'</span>'
        +'<span style="font-size:10px;color:#888">'+(p.status||'')+'</span>'
        +'</label>';
    }).join('')
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="pp-eq-proj-ok" style="flex:1">✓ Confirmar</button>'
    +'</div></div></div>';
  setModal(html);

  window.ppEqFiltrarProjs=function(){
    var q=((document.getElementById('pp-eq-proj-busca')||{}).value||'').toLowerCase();
    document.querySelectorAll('#pp-eq-proj-lista label').forEach(function(el){
      el.style.display=el.textContent.toLowerCase().includes(q)?'':'none';
    });
  };

  var btn=document.getElementById('pp-eq-proj-ok');
  if(btn) btn.onclick=function(){
    var cbs=document.querySelectorAll('#modal-area .pp-eq-proj-cb:checked');
    var novos=Array.from(cbs).map(function(cb){return cb.value;});
    if(!comp){
      comp={id:'local_'+eqId+'_'+data,equipe_id:eqId,data:data,
        colaborador_ids:'[null,null,null]',projeto_ids:JSON.stringify(novos),
        turno:'Manha',confirmada:false,_local:true};
      composicao_dia.push(comp);
    } else {
      comp.projeto_ids=JSON.stringify(novos);
    }
    if(!DEMO&&comp.id&&!comp._local)
      sbUpdate('composicao_dia',{projeto_ids:JSON.stringify(novos)},'id=eq.'+comp.id);
    closeModal();
    progProjRenderQuadro();
  };
}

function ppEqRemoverProjeto(eqId, projetoId){
  var data=progProjGetData();
  var comp=composicao_dia.find(function(c){return c.equipe_id===eqId&&c.data===data;});
  if(!comp) return;
  var ids=[]; try{ids=JSON.parse(comp.projeto_ids||'[]');}catch(e){}
  ids=ids.filter(function(id){return id!==projetoId;});
  comp.projeto_ids=JSON.stringify(ids);
  if(!DEMO&&!comp._local)sbUpdate('composicao_dia',{projeto_ids:JSON.stringify(ids)},'id=eq.'+comp.id);
  progProjRenderQuadro();
}

function ppEnviarWhatsApp(eqId){
  var data = progProjGetData();
  var eq   = equipes.find(function(e){return e.id===eqId;});
  if(!eq) return;

  var comp = composicao_dia.find(function(c){
    var cd=(c.data||'').split('T')[0];
    return c.equipe_id===eqId && (cd===data||c.data===data);
  });
  if(!comp){ alert('Equipe sem composição para enviar.'); return; }

  var ids = parseJsonField(comp.colaborador_ids,[]).filter(Boolean);
  var cols = ids.map(function(id){
    var col=colaboradores.find(function(c){return c.id===id;});
    return col ? col.nome+' (RE '+( col.re||'—')+')' : 'Colaborador';
  });

  // Projetos do dia
  var projIds = parseJsonField(comp.projeto_ids,[]).filter(Boolean);
  var projs = projIds.map(function(pid){
    var p = sot_projetos.find(function(x){return x.id===pid;})||{};
    return (p.codigo_cliente||p.codigo||p.nome||pid);
  });

  // Veículo
  var veic = progGetVeiculo(eqId, data);
  var veicStr = veic ? (veic.placa+' — '+(veic.modelo||'')) : '—';

  var urlSistema = window.location.href.split('?')[0];
  var ds = ['Domingo','Segunda','Terca','Quarta','Quinta','Sexta','Sabado'];
  var diaSemana = ds[new Date(data+'T12:00:00').getDay()];
  var dataFmt = fmtD(data);
  var NL='%0A', B='*', T='-';

  var turno = eq.turno_tipo||calcularTurnoTipo(eq.hora_inicio||'');
  var horario = eq.hora_inicio ? eq.hora_inicio+(eq.hora_fim?'–'+eq.hora_fim:'') : '';

  var msg = B+'CENA — Programação de Projetos'+B+NL+NL;
  msg += 'Data: '+B+diaSemana+', '+dataFmt+B+NL;
  msg += 'Equipe: '+B+eq.nome_equipe+B+NL;
  msg += 'Turno: '+turno+(horario?' ('+horario+')':'')+NL;
  if(eq.escala) msg += 'Escala: '+eq.escala+NL;
  msg += 'Veículo: '+veicStr+NL+NL;

  if(cols.length){
    msg += B+'Composição:'+B+NL;
    cols.forEach(function(n,i){ msg += (i+1)+'. '+n+NL; });
    msg += NL;
  }

  if(projs.length){
    msg += B+'Projetos do dia:'+B+NL;
    projs.forEach(function(p,i){ msg += (i+1)+'. '+p+NL; });
    msg += NL;
  }

  msg += 'Acesse o sistema:'+NL+urlSistema+NL;
  msg += 'Faça login e registre seu turno.';

  var telD = telefoneEquipeDigitos(eq.telefone);
  var waNum = telefoneEquipeValido(telD) ? '55'+telD : '';
  window.open('https://wa.me/'+waNum+'?text='+msg,'_blank');
}

function ppEnviarWhatsAppTodos(){
  var data = progProjGetData();
  var cid  = progProjGetCid();
  if(!cid){ alert('Selecione um contrato primeiro.'); return; }

  var eqs = equipes.filter(function(e){
    return e.status==='Ativo' && e.contrato_id===cid;
  });
  var programadas = eqs.filter(function(eq){
    return composicao_dia.some(function(c){
      var cd=(c.data||'').split('T')[0];
      return c.equipe_id===eq.id && (cd===data||c.data===data) && c.confirmada;
    });
  });

  if(!programadas.length){ alert('Nenhuma equipe confirmada para enviar.'); return; }

  var ds = ['Domingo','Segunda','Terca','Quarta','Quinta','Sexta','Sabado'];
  var diaSemana = ds[new Date(data+'T12:00:00').getDay()];
  var dataFmt = fmtD(data);
  var urlSistema = window.location.href.split('?')[0];
  var NL='%0A', B='*';

  var msg = B+'CENA — Programação de Projetos'+B+NL;
  msg += 'Data: '+B+diaSemana+', '+dataFmt+B+NL;
  msg += programadas.length+' equipe(s) programada(s)'+NL+NL;

  // Agrupar por turno
  var porTurno = {};
  programadas.forEach(function(eq){
    var turno = eq.turno_tipo||calcularTurnoTipo(eq.hora_inicio||'')||'Manhã';
    if(!porTurno[turno]) porTurno[turno]=[];
    porTurno[turno].push(eq);
  });

  ['Manhã','Tarde','Noite'].forEach(function(turno){
    var eqsT = porTurno[turno]||[];
    if(!eqsT.length) return;
    msg += B+'Turno '+turno+B+NL;
    eqsT.forEach(function(eq){
      var comp = composicao_dia.find(function(c){
        var cd=(c.data||'').split('T')[0];
        return c.equipe_id===eq.id&&(cd===data||c.data===data);
      });
      var ids = comp?parseJsonField(comp.colaborador_ids,[]).filter(Boolean):[];
      var veic = progGetVeiculo(eq.id, data);
      var projIds = comp?parseJsonField(comp.projeto_ids,[]).filter(Boolean):[];
      var projs = projIds.map(function(pid){
        var p=sot_projetos.find(function(x){return x.id===pid;})||{};
        return (p.codigo_cliente||p.codigo||p.nome||'');
      }).filter(Boolean);

      msg += B+eq.nome_equipe+B;
      if(eq.hora_inicio) msg += ' ('+eq.hora_inicio+(eq.hora_fim?'–'+eq.hora_fim:'')+')';
      msg += NL;
      if(veic) msg += '🚗 '+veic.placa+(veic.modelo?' — '+veic.modelo:'')+NL;
      if(projs.length) msg += '📋 '+projs.join(', ')+NL;
      ids.forEach(function(id){
        var col=colaboradores.find(function(c){return c.id===id;});
        if(col) msg += '- '+col.nome+(col.re?' (RE '+col.re+')':'')+NL;
      });
      msg += NL;
    });
  });

  msg += 'Acesse: '+urlSistema+NL+'Faça login e registre seu turno.';

  window.open('https://wa.me/?text='+msg,'_blank');
}

// ── Auto-escalar Projetos — vinculados da equipe + slots dinâmicos ──
function ppVinculadosDisponiveisEq(eqId, data, cid, emEscala){
  emEscala = emEscala || {};
  var STATUS_BLOQ = BLOQ_STATUS;
  var corDia = (_calDados&&_calDados[data]) || CAL_CORES_2026[data] || '';
  return progFiltrarColsProgramacao(cid).filter(function(c){
    if(String(c.equipe_id)!==String(eqId)) return false;
    var st = progProjetoCoreStatusColab(c.id);
    if(STATUS_BLOQ.indexOf(st)>=0) return false;
    if(corDia && c.cor_escala && c.cor_escala===corDia && st==='disponivel') return false;
    if(emEscala[c.id]) return false;
    return true;
  }).sort(function(a,b){ return (a.nome||'').localeCompare(b.nome||''); });
}

function ppNumSlotsParaMembros(qtd, eq){
  var n=qtd||0;
  if(progEquipeEhViabilidade(eq)){
    if(n<=0) return 1;
    return Math.min(7, Math.max(1, n));
  }
  if(n<=0) return 3;
  return Math.min(7, Math.max(3, n));
}

function ppMontarIdsSlots(vinculados, eq){
  var n=ppNumSlotsParaMembros(vinculados.length, eq);
  var ids = [];
  for(var i=0;i<n;i++) ids.push(vinculados[i]?vinculados[i].id:null);
  return ids;
}

function ppPersistirComposicao(eqId, data, ids){
  return progProjetoCorePersistirComposicao(eqId, data, ids);
}

function ppAutoEscalarEquipe(eqId){
  var cid=progProjGetCid();
  var data=progProjGetData()||dataHoje();
  if(data < dataHojeLocal()){ progShowToast('⛔ Auto Escalar não disponível para datas passadas.','erro'); return; }
  var comp=progFindCompDia(eqId, data);
  if(comp && comp.confirmada){
    progShowToast('⛔ Equipe já programada — desprogramar antes de auto escalar.');
    return;
  }
  if(comp && parseJsonField(comp.colaborador_ids,[]).filter(Boolean).length>0){
    progShowToast('⚠ Equipe já tem colaboradores escalados. Limpe a escala antes de Auto Escalar.');
    return;
  }
  var emEscala={};
  composicao_dia.forEach(function(c){
    var cd=(c.data||'').split('T')[0];
    if(cd!==data && c.data!==data) return;
    if(String(c.equipe_id)===String(eqId)) return;
    parseJsonField(c.colaborador_ids,[]).filter(Boolean).forEach(function(id){
      if(id && BLOQ_STATUS.indexOf(_progStatus[id]||'disponivel')<0) emEscala[id]=true;
    });
  });
  var eq=equipes.find(function(e){return e.id===eqId;});
  var vinculados=ppVinculadosDisponiveisEq(eqId, data, cid, emEscala);
  var minCol=progMinColaboradoresEquipe(eq);
  if(vinculados.length<minCol){
    progShowToast(minCol===1
      ? '⚠ Equipe sem colaborador vinculado disponível.'
      : '⚠ Equipe sem colaboradores vinculados suficientes disponíveis (mín. 2).');
    return;
  }
  var ids=ppMontarIdsSlots(vinculados, eq);
  var n=ppPersistirComposicao(eqId, data, ids);
  progProjRenderQuadro();
  progShowToast('✅ '+n+' vinculado(s) escalado(s) em '+ids.length+' slots (T1–T'+ids.length+')');
}


function ppMenuSlot(colabId, eqId, pos){
  return progProjetoCoreMenuSlot(colabId, eqId, pos);
}

function progProjetoCoreMenuSlot(colabId, eqId, pos){
  var col = colaboradores.find(function(c){return c.id===colabId;})||{nome:colabId};
  var st  = progProjetoCoreStatusColab(colabId);
  var info = progProjetoCoreStatusInfoColab(colabId);
  var data = progProjGetData();

  var motHtml = '';
  if(eqId){
    var comp = progFindCompDia(eqId, data);
    var eq = progProjetoCoreFindEquipe(eqId);
    var veicProg = progGetVeiculo(eqId, data);
    var veic = veicProg && veicProg.id ? ((frt_veiculos||[]).find(function(v){return v.id===veicProg.id;})||veicProg) : null;
    if(!veic && eq && eq.veiculo_padrao_id && frt_veiculos){
      veic = frt_veiculos.find(function(v){return v.id===eq.veiculo_padrao_id;});
    }
    var tipoVeic = veic ? (veic.tipo||veic.modelo||'').toLowerCase() : '';
    var cnh = (col.cnh_categoria||'').toUpperCase();
    var CNH_COMPAT = {
      'moto':        ['A','AB','AD','AC','AE'],
      'fiorino':     ['AB','AD','AC','B','C','D','E'],
      'caminhão':    ['D','E','AD'],
      'cesto aéreo': ['AD','D','E'],
      'caminhonete': ['B','C','D','E','AB','AD','AC','AE'],
    };
    var veicKey = Object.keys(CNH_COMPAT).find(function(k){ return tipoVeic.includes(k); });
    var compat = !veic ? true : (veicKey ? CNH_COMPAT[veicKey].indexOf(cnh)>=0 : !!cnh);
    var motorAtual = comp && comp.motorista_id === colabId;
    var motChkId = 'pp-mot-'+eqId+'-'+colabId;
    motHtml = '<div style="background:#EBF4FD;border-radius:8px;padding:10px 12px;margin-bottom:8px">'
      +'<div style="font-size:11px;font-weight:600;color:#185FA5;margin-bottom:6px">🚗 Dirigida</div>'
      +(veic?'<div style="font-size:11px;color:#555;margin-bottom:6px">Veículo: <b>'+(veic.placa||'')+'</b> — '+(veic.modelo||'')+(veic.tipo?' ('+veic.tipo+')':'')+'</div>'
        :'<div style="font-size:10px;color:#854F0B;margin-bottom:6px">⚠ Selecione o veículo da equipe para validar CNH.</div>')
      +'<div style="font-size:11px;color:#555;margin-bottom:6px">CNH: <b>'+(cnh||'Sem CNH')+'</b>'
      +(veic&&veicKey?' · '+veicKey:'')+(veic?(compat?' <span style="color:#3B6D11">✓ compatível</span>':'<span style="color:#A32D2D"> ✗ incompatível</span>'):'')
      +(typeof fmdAvaliarCnh==='function'?fmdBadgeHtml(fmdAvaliarCnh(col)):'')
      +'</div>'
      +(typeof fmdAvaliarCnh==='function'&&typeof fmdAlertaBoxHtml==='function'?fmdAlertaBoxHtml(fmdAvaliarCnh(col)):'')
      +'<label style="display:flex;align-items:center;gap:8px;cursor:'+(compat?'pointer':'not-allowed')+'">'
      +'<input type="checkbox" id="'+motChkId+'" '+(motorAtual?'checked':'')+(compat?'':' disabled')
      +' style="width:16px;height:16px" onchange="ppDefinirMotorista(\''+colabId+'\',\''+eqId+'\',this.checked)"/>'
      +'<span style="font-size:12px;font-weight:500;color:'+(compat?'#185FA5':'#aaa')+'">Motorista do dia</span>'
      +'</label>'
      +'</div>';
  }

  var escalaHistHtml = typeof progColabUltimasEscalasHtml==='function' ? progColabUltimasEscalasHtml(colabId, data) : '';

  var html = '<div class="modal-bg" onclick="if(event.target===this)closeModal()">'
    +'<div class="modal" style="max-width:340px;max-height:92vh;overflow-y:auto">'
    +'<div style="font-weight:700;font-size:13px;margin-bottom:.25rem">'+nomeAbrev(col.nome)+'</div>'
    +'<div style="font-size:11px;color:#888;margin-bottom:.75rem">RE '+(col.re||'—')+' · '+(col.cargo||'')+(col.cnh_categoria?' · CNH '+col.cnh_categoria:'')+'</div>'
    +escalaHistHtml
    +motHtml
    +'<div style="display:flex;flex-direction:column;gap:5px">'
    +'<button onclick="ppRetirarDaEquipe(\''+colabId+'\',\''+eqId+'\','+pos+')" '
    +'style="background:#EAF3DE;color:#3B6D11;border:.5px solid #3B6D1144;border-radius:6px;padding:8px 12px;cursor:pointer;font-size:12px;text-align:left;font-weight:600">'
    +'✅ Disponível — retirar da equipe</button>'
    +'<button onclick="closeModal();ppEmprestarColab(\''+colabId+'\',\''+eqId+'\')" '
    +'style="background:#EBF4FF;color:#185FA5;border:.5px solid #185FA544;border-radius:6px;padding:8px 12px;cursor:pointer;font-size:12px;text-align:left;font-weight:600">'
    +'🔄 Emprestar para outra equipe</button>'
    + PP_MENU_STATUS.map(function(k){
        var s=PROG_STATUS[k];
        var ativo = k===st;
        return '<button data-st="'+k+'" onclick="ppSetStatusMenu(\''+colabId+'\',\''+k+'\')" '
          +'style="background:'+(ativo?s.bg:'#fff')+';color:'+(ativo?s.cor:'#555')+';border:.5px solid '+(ativo?s.cor+'88':'#e0dfd8')+';border-radius:6px;padding:8px 12px;cursor:pointer;font-size:12px;text-align:left;display:flex;justify-content:space-between;align-items:center">'
          +'<span>'+s.label+'</span>'+(ativo?'<span style="font-weight:700;font-size:14px">✓</span>':'')+'</button>';
      }).join('')
    +'</div>'
    +'<div id="pp-retorno-wrap" style="display:'+(['ferias','afastado','treinamento'].indexOf(st)>=0?'block':'none')+';margin-top:8px;padding:10px 12px;background:#FFF8E1;border-radius:8px">'
    +'<label style="font-size:11px;font-weight:600;color:#854F0B;display:block;margin-bottom:4px">📅 Data prevista de retorno</label>'
    +'<input type="date" id="pp-st-retorno" value="'+progDataRetornoStr(info.retorno)+'" class="inp" style="width:100%"/>'
    +'<div style="font-size:10px;color:#888;margin-top:3px">Status se repete automaticamente até esta data</div>'
    +'</div>'
    +'<div id="pp-obs-status-wrap" style="display:'+(PP_MENU_STATUS.indexOf(st)>=0&&['patio','verificar','observacao'].indexOf(st)>=0?'block':'none')+';margin-top:8px">'
    +'<label style="font-size:11px;font-weight:600;color:#555;display:block;margin-bottom:4px">📝 Observação'+(st==='observacao'?' <span style="color:#A32D2D">*</span>':'')+'</label>'
    +'<textarea id="pp-obs-status-input" class="inp" style="width:100%;height:60px;font-size:12px" placeholder="'+(st==='observacao'?'Motivo da observação (ex.: restrição médica leve, atenção...)':st==='verificar'?'O que precisa ser verificado...':'Motivo / observação...')+'">'+(info.obs||'')+'</textarea>'
    +'</div>'
    +'<div style="display:flex;gap:6px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Fechar</button>'
    +'<button class="btn btn-pri" onclick="ppSalvarMenuStatus(\''+colabId+'\')" style="flex:1">💾 Salvar</button>'
    +'</div>'
    +'</div></div>';
  setModal(html);
}

function ppDefinirMotorista(colabId, eqId, checked){
  return progProjetoCoreDefinirMotorista(colabId, eqId, checked);
}
function progProjetoCoreDefinirMotorista(colabId, eqId, checked){
  var data = progProjGetData();
  var comp = progFindCompDia(eqId, data);
  if(!comp){
    comp={id:'local_'+eqId+'_'+data,equipe_id:eqId,data:data,
      colaborador_ids:'[]',turno:'Manha',confirmada:false,_local:true};
    composicao_dia.push(comp);
  }

  if(checked){
    var col    = colaboradores.find(function(c){return c.id===colabId;});
    var veic   = progGetVeiculo(eqId, data);
    var cnh    = col ? (col.cnh_categoria||'') : '';
    var tipo   = veic ? (veic.tipo || (frt_veiculos&&frt_veiculos.find(function(v){return v.id===veic.id;})||{}).tipo||'') : '';
    if(!tipo && veic && veic.id){
      var fv = (frt_veiculos||[]).find(function(v){return v.id===veic.id;});
      if(fv) tipo = fv.tipo||'';
    }
    var compat = veic ? cnhCompatibilidadeVeiculo(cnh, tipo) : 'ok';
    var motChkId = 'pp-mot-'+eqId+'-'+colabId;
    if(compat === 'bloqueado'){
      var cnhLabel = cnh || 'sem CNH';
      progShowToast('🚫 ' + (col?col.nome:'Colaborador') + ' (CNH ' + cnhLabel + ') não está habilitado para dirigir ' + (tipo||'este veículo') + '. Selecione outro motorista.');
      var chk = document.getElementById(motChkId);
      if(chk) chk.checked = false;
      return;
    }
    if(compat === 'justificativa'){
      var motivo = prompt('⚠ CNH ' + cnh + ' em veículo ' + (tipo||'leve') + '. Isso é permitido mas exige justificativa. Informe o motivo:');
      if(!motivo){
        var chk2 = document.getElementById(motChkId);
        if(chk2) chk2.checked = false;
        return;
      }
      progShowToast('⚠ CNH ' + cnh + ' em ' + (tipo||'veículo leve') + ' registrado. Justificativa: ' + motivo);
    }

    // CNH: validade não bloqueia escala (Projetos) — só observação
    if(typeof fmdAvaliarCnh==='function'){
      var avPp=fmdAvaliarCnh(col||colabId);
      if(avPp && (avPp.nivel==='vencida'||avPp.nivel==='sem_validade'||avPp.nivel==='aviso'||avPp.nivel==='sem')){
        var msgObsPp=avPp.msg||avPp.badge||'Observação de CNH';
        if(avPp.nivel==='vencida'){
          msgObsPp='Observação: CNH vencida. Escala permitida — atualize o cadastro da validade.';
        } else if(avPp.nivel==='sem_validade'){
          msgObsPp='Observação: falta a data de validade da CNH. Escala permitida — cadastre a validade.';
        }
        progShowToast((avPp.nivel==='aviso'?'⏰ ':'⚠ ')+msgObsPp);
      }
    }
  }

  comp.motorista_id = checked ? colabId : null;
  if(!DEMO&&!comp._local) sbUpdate('composicao_dia',{motorista_id:checked?colabId:null},'id=eq.'+comp.id);
  progProjRenderQuadro();
}

function ppSetStatusMenu(colabId, status){
  return progProjetoCoreSetStatusMenu(colabId, status);
}
function progProjetoCoreSetStatusMenu(colabId, status){
  _progStatus[colabId] = status;
  var PEDE_OBS_PP = ['patio','verificar','observacao'];
  var rw = document.getElementById('pp-retorno-wrap');
  if(rw) rw.style.display = ['ferias','afastado','treinamento'].indexOf(status)>=0 ? 'block' : 'none';
  var ow = document.getElementById('pp-obs-status-wrap');
  if(ow) ow.style.display = PEDE_OBS_PP.indexOf(status)>=0 ? 'block' : 'none';
  var oi = document.getElementById('pp-obs-status-input');
  if(oi){
    var ph = status==='verificar'?'O que precisa ser verificado...'
           : status==='observacao'?'Motivo da observação (ex.: restrição médica leve, atenção...)'
           : 'Motivo / observação...';
    oi.placeholder = ph;
  }
  document.querySelectorAll('button[data-st]').forEach(function(b){
    var k = b.getAttribute('data-st');
    var s = PROG_STATUS[k]||{};
    var ativo = k===status;
    b.style.background  = ativo ? s.bg  : '#fff';
    b.style.color       = ativo ? s.cor : '#555';
    b.style.border      = ativo ? '.5px solid '+s.cor+'88' : '.5px solid #e0dfd8';
    b.style.fontWeight  = ativo ? '600' : '400';
    var spans = b.querySelectorAll('span');
    if(spans.length>=2) spans[1].textContent = ativo ? '✓' : '';
  });
}

function ppEmprestarColab(colabId, fromEqId){
  progEmprestarColab(colabId, fromEqId);
}

function ppSalvarMenuStatus(colabId){
  return progProjetoCoreSalvarMenuStatus(colabId);
}
function progProjetoCoreSalvarMenuStatus(colabId){
  var novoSt  = progProjetoCoreStatusColab(colabId);
  var obsInput = (document.getElementById('pp-obs-status-input')||{}).value||'';
  var retorno = progDataRetornoStr(((document.getElementById('pp-st-retorno')||{}).value||'')
    || ((_progStatusInfo[colabId]||{}).retorno||''));
  if(novoSt==='observacao' && !obsInput.trim()){ progShowToast('⚠ Informe o motivo da observação.','erro'); return; }
  if(['ferias','afastado','treinamento'].indexOf(novoSt)>=0 && !retorno){
    progShowToast('⚠ Informe a data prevista de retorno.','erro');
    return;
  }
  if(obsInput){
    if(!_progStatusInfo[colabId]) _progStatusInfo[colabId]={};
    _progStatusInfo[colabId].obs = obsInput;
  }
  var data = progProjGetData();

  if(novoSt==='disponivel'){
    progRemoverPersistente(colabId);
    delete _progStatus[colabId];
    delete _progStatusInfo[colabId];
    _progStatusDateCache = null;
    if(!DEMO){
      sbUpsert('prog_status_diario',{
        colaborador_id:colabId, data:data, status:'disponivel',
        data_retorno:null, obs:null,
        registrado_por:usuarioLogado?usuarioLogado.nome:''
      },'prog_status_diario_colaborador_id_data_key');
    }
  } else {
    progSalvarPersistente(colabId, novoSt, data, retorno||'', '');
    _progStatus[colabId] = novoSt;
    if(!_progStatusInfo[colabId]) _progStatusInfo[colabId]={};
    if(obsInput) _progStatusInfo[colabId].obs = obsInput;
    if(retorno) _progStatusInfo[colabId].retorno = retorno;
    progMarcarAutorStatus(colabId);
    progSalvarStatus();
    progProjSalvarStatus();
    if(!DEMO){
      var _obsParaSalvar = obsInput || (_progStatusInfo[colabId]||{}).obs || '';
      sbUpsert('prog_status_diario',{
        colaborador_id:colabId, data:data, status:novoSt,
        data_retorno:retorno||null,
        obs:_obsParaSalvar||null,
        registrado_por:usuarioLogado?usuarioLogado.nome:''
      },'prog_status_diario_colaborador_id_data_key').then(function(){
        progShowToast('✅ Status salvo.');
        if(novoSt==='verificar'){
          vtGarantirTratamento(colabId, data, _obsParaSalvar||'');
          vtAtualizarAbaAlerta();
        }
        if(['ferias','afastado','treinamento','demitido'].indexOf(novoSt)>=0) _progStatusDateCache = null;
      }).catch(function(e){
        console.error('ppSalvarMenuStatus erro:', e);
        progShowToast('⚠️ Erro ao salvar no banco.','erro');
      });
    }
  }
  closeModal();
  progProjRenderQuadro();
}

function ppRetirarDaEquipe(colabId, eqId, pos){
  return progProjetoCoreRetirarDaEquipe(colabId, eqId, pos);
}
function progProjetoCoreRetirarDaEquipe(colabId, eqId, pos){
  var data=progProjGetData();
  var comp=progFindCompDia(eqId, data);
  if(comp){
    var ids=parseJsonField(comp.colaborador_ids,[]);
    if(typeof pos==='number' && pos>=0 && pos<ids.length && ids[pos]===colabId){
      ids[pos]=null;
    } else {
      ids=ids.map(function(id){return id===colabId?null:id;});
    }
    comp.colaborador_ids=JSON.stringify(ids);
    if(comp.motorista_id===colabId){
      comp.motorista_id=null;
      if(!DEMO) sbUpdate('composicao_dia',{motorista_id:null},'id=eq.'+comp.id);
    }
    if(!DEMO)sbUpdate('composicao_dia',{colaborador_ids:ids},'id=eq.'+comp.id);
  }
  delete _progStatus[colabId];
  delete _progStatusInfo[colabId];
  progProjSalvarStatus();
  progSalvarStatus();
  closeModal();
  progProjRenderQuadro();
  progShowToast('✅ Colaborador movido para disponíveis');
}

function ppToggleStatus(colabId){
  var atual = progProjetoCoreStatusColab(colabId);
  var col   = colaboradores.find(function(c){return c.id===colabId;})||{nome:colabId};
  var info  = progProjetoCoreStatusInfoColab(colabId);
  var opcoes = Object.keys(PROG_STATUS);
  var html = '<div class="modal-bg"><div class="modal" style="max-width:340px">'
    +'<h3>Status</h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">'+col.nome+'</div>'
    +'<div style="display:flex;flex-direction:column;gap:6px;margin-bottom:1rem">'
    +opcoes.map(function(k){
      var s=PROG_STATUS[k];
      var sel=k===atual?'border:2px solid '+s.cor:'border:.5px solid #e0dfd8';
      var extra=PROG_STATUS_REQUER_DATA.indexOf(k)>=0?' [previsão req.]':'';
      return '<button id="pp-st-btn-'+k+'" style="padding:8px 12px;border-radius:8px;background:'+s.bg+';color:'+s.cor+';font-weight:600;cursor:pointer;text-align:left;'+sel+'">'
        +s.label+extra+(k===atual?' (atual)':'')+'</button>';
    }).join('')
    +'</div>'
    +'<div id="pp-st-data-wrap" style="display:none;background:#f9f9f7;border-radius:8px;padding:.75rem;margin-bottom:.75rem">'
    +'<label style="font-size:12px;font-weight:500;display:block;margin-bottom:4px">Previsão de retorno *</label>'
    +'<input type="date" id="pp-st-data-retorno" class="inp" style="width:100%" value="'+(info.retorno||'')+'"/>'
    +'<div style="font-size:11px;color:#888;margin-top:4px">Volta automaticamente para a escala nessa data.</div>'
    +'</div>'
    +'<div style="display:flex;gap:6px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="pp-st-confirmar" style="flex:1">Confirmar</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    var statusSel = atual;
    opcoes.forEach(function(k){
      var btn = document.getElementById('pp-st-btn-'+k);
      if(!btn) return;
      btn.onclick = function(){
        opcoes.forEach(function(j){
          var b=document.getElementById('pp-st-btn-'+j); if(!b) return;
          b.style.border = j===k ? '2px solid '+PROG_STATUS[j].cor : '.5px solid #e0dfd8';
        });
        statusSel = k;
        var wrap = document.getElementById('pp-st-data-wrap');
        if(wrap) wrap.style.display = PROG_STATUS_REQUER_DATA.indexOf(k)>=0 ? '' : 'none';
      };
    });
    var btnConf = document.getElementById('pp-st-confirmar');
    if(btnConf) btnConf.onclick = function(){
      if(PROG_STATUS_REQUER_DATA.indexOf(statusSel)>=0){
        var dr = (document.getElementById('pp-st-data-retorno')||{}).value||'';
        if(!dr){ alert('Informe a previsão de retorno.'); return; }
        ppDefinirStatus(colabId, statusSel, dr);
      } else {
        ppDefinirStatus(colabId, statusSel, null);
      }
    };
  },50);
}

function ppDefinirStatus(colabId, status, dataRetorno){
  if(status==='disponivel'){
    delete _progStatus[colabId];
    delete _progStatusInfo[colabId];
    progRemoverPersistente(colabId);
    _progStatusDateCache = null;
    var dataPP = progProjGetData();
    if(!DEMO){
      sbUpsert('prog_status_diario',{
        colaborador_id:colabId, data:dataPP, status:'disponivel',
        data_retorno:null, obs:null,
        registrado_por:usuarioLogado?usuarioLogado.nome:''
      },'prog_status_diario_colaborador_id_data_key');
      sbDelete('prog_status_diario',
        'colaborador_id=eq.'+colabId+'&data=neq.'+dataPP+
        '&status=in.(ferias,afastado,treinamento,demitido)');
    }
  } else {
    _progStatus[colabId] = status;
    if(!_progStatusInfo[colabId]) _progStatusInfo[colabId]={};
    if(dataRetorno) _progStatusInfo[colabId].retorno = progDataRetornoStr(dataRetorno);
    else delete (_progStatusInfo[colabId]||{}).retorno;
    var dataPP2 = progProjGetData();
    if(!DEMO) sbUpsert('prog_status_diario',{
      colaborador_id:colabId, data:dataPP2, status:status,
      data_retorno:progDataRetornoStr(dataRetorno)||null, obs:null,
      registrado_por:usuarioLogado?usuarioLogado.nome:''
    },'prog_status_diario_colaborador_id_data_key');
  }
  progProjSalvarStatus();
  progSalvarStatus();
  closeModal();
  progProjRenderQuadro();
}

// ── Salvar equipe — ver ppSalvarEquipe acima ──────────────────

// ── Auto-escalar ──────────────────────────────────────────────
function progProjAutoEscalar(){
  var cid=progProjGetCid();
  var data=progProjGetData();
  if(!cid){ alert('Selecione um contrato.'); return; }
  if(data < dataHojeLocal()){ progShowToast('⛔ Auto Escalar não disponível para datas passadas.','erro'); return; }

  var emEscalaGlobal={};
  composicao_dia.forEach(function(c){
    var cd=(c.data||'').split('T')[0];
    if(cd!==data && c.data!==data) return;
    parseJsonField(c.colaborador_ids,[]).filter(Boolean).forEach(function(id){
      if(id && BLOQ_STATUS.indexOf(_progStatus[id]||'disponivel')<0) emEscalaGlobal[id]=true;
    });
  });

  var eqs=equipes.filter(function(e){return e.contrato_id===cid&&e.status==='Ativo';});
  var ok=0, falha=0, puladas=0;

  eqs.forEach(function(eq){
    var comp=progFindCompDia(eq.id, data);
    if(comp && comp.confirmada){ puladas++; return; }
    if(comp && parseJsonField(comp.colaborador_ids,[]).filter(Boolean).length>0){ puladas++; return; }

    var vinculados=ppVinculadosDisponiveisEq(eq.id, data, cid, emEscalaGlobal);
    if(vinculados.length<progMinColaboradoresEquipe(eq)){ falha++; return; }

    var ids=ppMontarIdsSlots(vinculados, eq);
    ids.filter(Boolean).forEach(function(id){ emEscalaGlobal[id]=true; });
    ok += ppPersistirComposicao(eq.id, data, ids);
  });

  progProjRenderQuadro();
  var msg='✅ Auto-escalado: '+ok+' colaborador(es) vinculado(s)';
  if(puladas) msg+=' · '+puladas+' equipe(s) já montadas';
  if(falha) msg+=' · '+falha+' sem vinculados suficientes';
  progShowToast(msg);
}

function progProjVerificarSemEscala(){
  var cid=progProjGetCid(); var data=progProjGetData();
  if(!cid){ alert('Selecione um contrato.'); return; }
  var STATUS_BLOQ = BLOQ_STATUS;
  var emEscala={};
  composicao_dia.forEach(function(c){
    if(c.data!==data) return;
    parseJsonField(c.colaborador_ids,[]).forEach(function(id){if(id&&BLOQ_STATUS.indexOf(_progStatus[id]||'disponivel')<0)emEscala[id]=true;});
  });
  var semEscala=progFiltrarColsProgramacao(cid).filter(function(c){
    return STATUS_BLOQ.indexOf(progProjetoCoreStatusColab(c.id))<0
      &&!emEscala[c.id];
  });
  if(!semEscala.length){ progShowToast('✅ Todos escalados!'); return; }
  alert('⚠ '+semEscala.length+' colaboradores sem escala:\n\n'+semEscala.map(function(c){return '• '+c.nome;}).join('\n'));
}

// ── Adicionar projeto_ids ao SQL se não existir ───────────────
// ALTER TABLE composicao_dia ADD COLUMN IF NOT EXISTS projeto_ids text;


// ═══════════════════════════════════════════════════════════════

// Mapa: equipe_id+data → {veiculo_id, placa, modelo, justificativa, alterado_por}
var _progVeiculos = {}; // carregado do banco ou localStorage

function progVeiculoKey(eqId, data){
  return eqId + '_' + (data||'').split('T')[0];
}
function progVeiculoKeyB(eqId, data){
  return eqId + '_' + (data||'').split('T')[0] + '_b';
}
function progVeiculoKeyEhDoDia(k, data){
  var d=(data||'').split('T')[0];
  return k===d || k.endsWith('_'+d) || k.endsWith('_'+d+'_b');
}
function progLimparVeiculosDia(data){
  var d=(data||'').split('T')[0];
  Object.keys(_progVeiculos||{}).forEach(function(k){
    if(progVeiculoKeyEhDoDia(k, d)) delete _progVeiculos[k];
  });
}
/** Persiste no localStorage só as placas do dia (não o mapa inteiro de outras datas). */
function progLimparCacheVeiculosAntigos(opts){
  opts = opts || {};
  var keepDays = opts.keepDays != null ? opts.keepDays : 7;
  var maxKeys = opts.maxKeys != null ? opts.maxKeys : 10;
  var re = /^prog_veic_\d{4}-\d{2}-\d{2}$/;
  var keys = [];
  try{
    for(var i=0;i<localStorage.length;i++){
      var k = localStorage.key(i);
      if(k && re.test(k)) keys.push(k);
    }
  }catch(eList){ return 0; }
  if(!keys.length) return 0;
  keys.sort(); // YYYY-MM-DD lexicográfico = cronológico
  var corte = null;
  try{
    var d = new Date();
    d.setHours(0,0,0,0);
    d.setDate(d.getDate() - keepDays);
    corte = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }catch(eC){}
  var removed = 0;
  keys.forEach(function(k){
    var dia = k.slice('prog_veic_'.length);
    if(corte && dia < corte){
      try{ localStorage.removeItem(k); removed++; }catch(eR){}
    }
  });
  // Releitura após remoção por data
  keys = [];
  try{
    for(var j=0;j<localStorage.length;j++){
      var k2 = localStorage.key(j);
      if(k2 && re.test(k2)) keys.push(k2);
    }
  }catch(e2){}
  keys.sort();
  while(keys.length > maxKeys){
    var oldest = keys.shift();
    try{ localStorage.removeItem(oldest); removed++; }catch(e3){}
  }
  if(removed) console.log('[prog_veic] limpeza cache local:', removed, 'chave(s)');
  return removed;
}
function progPersistVeiculosLocal(data){
  var d=(data||'').split('T')[0];
  var slice={};
  Object.keys(_progVeiculos||{}).forEach(function(k){
    if(progVeiculoKeyEhDoDia(k, d)) slice[k]=_progVeiculos[k];
  });
  var key = 'prog_veic_'+d;
  var raw = JSON.stringify(slice);
  try{
    localStorage.setItem(key, raw);
  }catch(e){
    var isQuota = e && (e.name==='QuotaExceededError' || e.code===22 || e.code===1014 ||
      /quota|exceeded/i.test(String(e.message||e)));
    if(isQuota){
      console.warn('[prog_veic] QuotaExceeded — limpando caches antigos');
      progLimparCacheVeiculosAntigos({keepDays:3, maxKeys:5});
      try{ localStorage.setItem(key, raw); }
      catch(e2){ console.warn('[prog_veic] não persistiu cache (quota); banco permanece fonte de verdade'); }
    }
  }
}
function progDiaSeguinte(data){
  var d=(data||'').split('T')[0];
  var p=d.split('-');
  var dt=new Date(Date.UTC(+p[0], +p[1]-1, +p[2]));
  dt.setUTCDate(dt.getUTCDate()+1);
  return dt.toISOString().slice(0,10);
}
/** Busca veículos do dia no banco (date ou timestamptz) sem incluir soft-deleted. */
function progFetchVeiculosDia(data, eqId){
  var d=(data||'').split('T')[0];
  var filters=['data=gte.'+d,'data=lt.'+progDiaSeguinte(d),'deleted_at=is.null'];
  if(eqId) filters.unshift('equipe_id=eq.'+eqId);
  return sbFetch('prog_veiculos_dia',{filters:filters,limit:eqId?50:5000}).then(function(rows){
    if(rows&&rows.length) return rows;
    // Fallback legado: data=eq.YYYY-MM-DD
    var f2=['data=eq.'+d];
    if(eqId) f2.unshift('equipe_id=eq.'+eqId);
    return sbFetch('prog_veiculos_dia',{filters:f2,limit:eqId?50:5000}).then(function(r2){
      return (r2||[]).filter(function(x){ return !x.deleted_at; });
    });
  }).catch(function(){ return []; });
}
/** Limpa placa também na composição do dia (fonte que reaparece após Atualizar). */
function progLimparPlacaComposicao(eqId, data){
  var d=(data||'').split('T')[0];
  var comp=typeof progFindCompDia==='function'?progFindCompDia(eqId, d):null;
  if(!comp){
    comp=(composicao_dia||[]).find(function(c){
      return String(c.equipe_id)===String(eqId) && (c.data||'').split('T')[0]===d && !c.deleted_at;
    })||null;
  }
  if(comp){
    comp.placa=null;
    comp.veiculo_id=null;
    comp.veiculo_placa=null;
    comp.modelo=null;
  }
  if(DEMO) return Promise.resolve(true);
  var payload={placa:null,veiculo_id:null,modelo:null};
  if(comp && comp.id && typeof isUUID==='function' && isUUID(comp.id)){
    return sbUpdate('composicao_dia',payload,'id=eq.'+comp.id).catch(function(e){
      console.warn('progLimparPlacaComposicao',e);
      return false;
    });
  }
  // Sem id em memória: localiza no banco e limpa
  return sbFetch('composicao_dia',{
    filters:['equipe_id=eq.'+eqId,'data=gte.'+d,'data=lt.'+progDiaSeguinte(d),'deleted_at=is.null'],
    limit:5
  }).then(function(rows){
    if(!rows||!rows.length){
      return sbFetch('composicao_dia',{filters:['equipe_id=eq.'+eqId,'data=eq.'+d],limit:5});
    }
    return rows;
  }).then(function(rows){
    if(!rows||!rows.length) return true;
    return Promise.all(rows.map(function(r){
      if(!r.id) return null;
      var mem=(composicao_dia||[]).find(function(c){return c.id===r.id;});
      if(mem){ mem.placa=null; mem.veiculo_id=null; mem.veiculo_placa=null; mem.modelo=null; }
      return sbUpdate('composicao_dia',payload,'id=eq.'+r.id);
    }));
  }).catch(function(e){
    console.warn('progLimparPlacaComposicao',e);
    return false;
  });
}

function progFindCompDia(eqId, data){
  var d=(typeof _compDataStr==='function')?_compDataStr(data):String(data||'').split('T')[0];
  var matches=(composicao_dia||[]).filter(function(c){
    if(!c) return false;
    var cd=(typeof _compDataStr==='function')?_compDataStr(c.data):String(c.data||'').split('T')[0];
    return String(c.equipe_id)===String(eqId) && cd===d;
  });
  if(!matches.length) return null;
  function nGente(c){
    try{ return parseColabIds(c.colaborador_ids).length; }catch(e){ return 0; }
  }
  function vivo(c){ return !c.deleted_at && !c._deleted; }
  matches.sort(function(a,b){
    var ga=nGente(a), gb=nGente(b);
    if(ga!==gb) return gb-ga;
    var va=vivo(a)?1:0, vb=vivo(b)?1:0;
    if(va!==vb) return vb-va;
    return 0;
  });
  return matches[0];
}

function progGetVeiculo(eqId, data){
  var d=(data||'').split('T')[0];
  var v=_progVeiculos[progVeiculoKey(eqId, d)] || null;
  if(v && String(v.placa||'').trim()) return v;
  var comp=typeof progFindCompDia==='function' ? progFindCompDia(eqId, d) : null;
  var placa=comp && String(comp.placa||comp.veiculo_placa||'').trim();
  if(!placa) return v;
  v={id:comp.veiculo_id||null, placa:placa, modelo:comp.modelo||''};
  _progVeiculos[progVeiculoKey(eqId, d)]=v;
  return v;
}
function progGetVeiculoB(eqId, data){
  return _progVeiculos[progVeiculoKeyB(eqId, data)] || null;
}

/** Tem placa no mapa do dia OU na composição (fonte alternativa). */
function progEquipeTemPlaca(eqId, data){
  var v = progGetVeiculo(eqId, data);
  if(v && String(v.placa||'').trim()) return true;
  var comp = typeof progFindCompDia==='function' ? progFindCompDia(eqId, data) : null;
  if(comp && (String(comp.placa||'').trim() || String(comp.veiculo_placa||'').trim())) return true;
  return false;
}

/** Retorna mensagem de erro se faltar placa; null se OK. Moto Dupla exige 2 placas. */
function progValidarPlacaObrigatoria(eq, eqId, data){
  var v = progGetVeiculo(eqId, data);
  var temPlaca = !!(v && String(v.placa||'').trim());
  if(!temPlaca){
    var comp = typeof progFindCompDia==='function' ? progFindCompDia(eqId, data) : null;
    if(comp && (String(comp.placa||'').trim() || String(comp.veiculo_placa||'').trim())){
      // Rehidrata mapa a partir da composição para o save gravar em prog_veiculos_dia
      _progVeiculos[progVeiculoKey(eqId, data)] = {
        id: comp.veiculo_id || null,
        placa: comp.placa || comp.veiculo_placa || '',
        modelo: comp.modelo || ''
      };
      temPlaca = true;
    }
  }
  if(!temPlaca){
    return '⚠ Selecione a placa do veículo antes de salvar a programação.';
  }
  if(typeof isMotoDupla==='function' && isMotoDupla(eq)){
    var v2 = progGetVeiculoB(eqId, data);
    if(!v2 || !String(v2.placa||'').trim()){
      return '⚠ Moto Dupla: selecione as duas placas (Moto 1 e Moto 2) antes de salvar.';
    }
  }
  return null;
}

// Retorna true se a equipe é do tipo "Moto Dupla"
function isMotoDupla(eq){
  if(!eq) return false;
  var nomeT = '';
  if(eq.tipo_id){
    var t = (tipos_equipe||[]).find(function(t){return t.id===eq.tipo_id;});
    nomeT = t ? (t.nome||'').toLowerCase() : '';
  }
  var nomeE = (eq.nome||'').toLowerCase();
  return nomeT.indexOf('moto dupla')>=0 || nomeE.indexOf('moto dupla')>=0;
}


function progVeicRowDoSlot(r, slotNum){
  if(!r) return false;
  var s=r.slot;
  if(slotNum===1 || slotNum==='1') return s==null || s==='' || Number(s)===1 || String(s)==='1';
  return Number(s)===Number(slotNum) || String(s)===String(slotNum);
}
/** Busca registros da equipe no dia, inclusive soft-deleted (o UNIQUE ignora deleted_at). */
function progFetchVeiculosDiaEquipeAll(eqId, data){
  var d=(data||'').split('T')[0];
  var f1=['equipe_id=eq.'+eqId,'data=gte.'+d,'data=lt.'+progDiaSeguinte(d)];
  return sbFetch('prog_veiculos_dia',{filters:f1,limit:50}).then(function(rows){
    if(rows&&rows.length) return rows;
    return sbFetch('prog_veiculos_dia',{filters:['equipe_id=eq.'+eqId,'data=eq.'+d],limit:50}).then(function(r2){ return r2||[]; });
  }).catch(function(){ return []; });
}

// ── Salvar veículo no banco de forma confiável (UPDATE se já existe; nunca INSERT duplicado) ──
function progSalvarVeiculoNoBanco(eqId, data, veiculoObj, slot){
  if(DEMO||!veiculoObj||!veiculoObj.placa) return Promise.resolve(true);
  var slotNum   = slot===2||slot==='2' ? 2 : 1;
  var dataStr   = (data||'').split('T')[0];
  var placa     = (veiculoObj.placa||'').trim().toUpperCase().replace(/[-\s]/g,'');
  var logCtx    = {eqId:eqId,data:dataStr,slot:slotNum,placa:placa};
  var updatePayload = {
    veiculo_id  : veiculoObj.id||null,
    placa       : placa,
    modelo      : veiculoObj.modelo||'',
    slot        : slotNum,
    alterado_por: veiculoObj.alterado_por||(usuarioLogado?usuarioLogado.nome:'')
  };
  var insertPayload = Object.assign({
    equipe_id:eqId, data:dataStr,
    justificativa:veiculoObj.justificativa||''
  }, updatePayload);

  function pickExisting(rows){
    var list=rows||[];
    return list.find(function(r){ return progVeicRowDoSlot(r, slotNum); }) || null;
  }
  function doUpdate(existing){
    if(!existing||!existing.id) return Promise.resolve(false);
    var payload=Object.assign({}, updatePayload);
    if(existing.deleted_at) payload.deleted_at=null;
    return sbUpdate('prog_veiculos_dia', payload, 'id=eq.'+existing.id)
      .then(function(ok){ return ok!==false; })
      .catch(function(){
        if(payload.deleted_at===null){
          delete payload.deleted_at;
          return sbUpdate('prog_veiculos_dia', payload, 'id=eq.'+existing.id).then(function(ok){ return ok!==false; });
        }
        return false;
      });
  }

  function doUpsert(){
    var payload=Object.assign({}, insertPayload, {deleted_at:null});
    return sbUpsert('prog_veiculos_dia', payload, 'equipe_id,data,slot')
      .then(function(u){
        if(u&&u.length) return 'upserted';
        delete payload.deleted_at;
        return sbUpsert('prog_veiculos_dia', payload, 'equipe_id,data,slot')
          .then(function(u2){ return (u2&&u2.length)?'upserted':'upsert-empty'; });
      });
  }

  return progFetchVeiculosDiaEquipeAll(eqId, dataStr)
  .then(function(rows){
    var existing=pickExisting(rows);
    if(existing&&existing.id){
      return doUpdate(existing).then(function(ok){ return ok ? 'updated' : doUpsert(); });
    }
    return doUpsert();
  })
  .then(function(op){
    var ok = op==='updated'||op==='upserted';
    if(ok) console.log('[veic save OK]', Object.assign({},logCtx,{op:op}));
    else console.warn('[veic save]', Object.assign({},logCtx,{op:op}));
    return ok;
  })
  .catch(function(e){
    console.error('[progSalvarVeiculoNoBanco] exception:',logCtx,e);
    return false;
  });
}

function progSetVeiculo(eqId, data, veiculoObj){
  // Invalidar cache de veículos escalados
  if(window._veicEscCache && window._veicEscCache[data]) delete window._veicEscCache[data];
  // Checar conflito — mesmo veículo em outra equipe no mesmo dia
  if(veiculoObj&&veiculoObj.placa){
    var _conf=Object.keys(_progVeiculos).filter(function(k){
      return k!==progVeiculoKey(eqId,data)&&k.indexOf('_'+data)>=0&&!k.endsWith('_b');
    }).filter(function(k){
      return (_progVeiculos[k]||{}).placa===veiculoObj.placa;
    });
    if(_conf.length) progShowToast('⚠️ Veículo '+veiculoObj.placa+' já está escalado em outra equipe neste dia! Verifique o painel de veículos.');
  }
  _progVeiculos[progVeiculoKey(eqId, data)] = veiculoObj;
  progPersistVeiculosLocal(data);
  window._veicEscCache = {}; // Invalida cache de status

  // Verificar conflito de horário de veículo compartilhado
  if(veiculoObj && veiculoObj.id){
    var eq = equipes_disp.find(function(e){return e.id===eqId;});
    if(eq && eq.hora_inicio && eq.hora_fim){
      var conflito = verificarConflitoVeiculo(veiculoObj.id, eqId, eq.hora_inicio, eq.hora_fim, data);
      if(conflito){
        progShowToast('⚠️ Veículo já alocado para '+conflito.codigo
          +' ('+conflito.hora_inicio+'–'+conflito.hora_fim
          +'). Horários conflitantes. Verifique antes de confirmar.');
      }
    }
  }

  // Salvar também em composicao_dia imediatamente (fallback garantido)
  if(!DEMO){
    var _compVeic = typeof progFindCompDia==='function'
      ? progFindCompDia(eqId, data)
      : composicao_dia.find(function(c){
          var cd=(c.data||'').split('T')[0];
          return String(c.equipe_id)===String(eqId)&&(cd===data||c.data===data);
        });
    if(_compVeic){
      _compVeic.veiculo_id = veiculoObj.id||null;
      _compVeic.placa      = veiculoObj.placa||'';
      _compVeic.modelo     = veiculoObj.modelo||'';
      if(_compVeic.id && !_compVeic._local){
        sbUpdate('composicao_dia',{
          veiculo_id:_compVeic.veiculo_id,
          placa:_compVeic.placa,
          modelo:_compVeic.modelo
        },'id=eq.'+_compVeic.id);
      }
    }
  }
  return progSalvarVeiculoNoBanco(eqId, data, veiculoObj, 1);
}

// ── Salvar veículo no slot B (2ª moto da Moto Dupla) ──────────
function progSetVeiculoB(eqId, data, veiculoObj){
  _progVeiculos[progVeiculoKeyB(eqId, data)] = veiculoObj;
  progPersistVeiculosLocal(data);
  return progSalvarVeiculoNoBanco(eqId, data, veiculoObj, 2);
}

function progRemoverVeiculoB(eqId, data){
  var d=(data||'').split('T')[0];
  var compB = typeof progFindCompDia==='function' ? progFindCompDia(eqId, d) : null;
  if(compB && (compB.confirmada===true || compB.confirmada==='true' || compB.confirmada===1)){
    progShowToast('🔒 Equipe já programada — desprograme antes de remover a placa.','erro');
    return;
  }
  if(!confirm('Remover 2ª moto desta equipe?')) return;
  delete _progVeiculos[progVeiculoKeyB(eqId, d)];
  progPersistVeiculosLocal(d);
  window._veicEscCache = {};
  if(!DEMO){
    var h={'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)};
    progFetchVeiculosDia(d, eqId).then(function(res){
      (res||[]).forEach(function(row){
        if(String(row.slot||'1')!=='2') return;
        if(row.id && isUUID(row.id)){
          fetch(SB.url+'/rest/v1/prog_veiculos_dia?id=eq.'+row.id,{method:'DELETE',headers:h})
            .catch(function(e){console.error('progRemoverVeiculoB DELETE erro',e);});
        }
      });
    }).catch(function(e){console.error('progRemoverVeiculoB fetch erro',e);});
  }
  closeModal();
  var eq = equipes_disp.find(function(e){return e.id===eqId;});
  var cell = document.getElementById('prog-veic-cell-'+eqId);
  if(cell) cell.innerHTML = progRenderVeiculoCell(eq||{id:eqId}, d);
  var btn = document.getElementById('prog-veic-btn-'+eqId);
  if(btn) btn.onclick = function(){progAbrirSelecionarVeiculo(eqId, d, 'a');};
  var btn2 = document.getElementById('prog-veic-btn2-'+eqId);
  if(btn2) btn2.onclick = function(){progAbrirSelecionarVeiculo(eqId, d, 'b');};
}

var _progVeiculosDateCache = null;

function progCarregarVeiculos(data){
  var d=(data||'').split('T')[0];

  // Sempre buscar do banco — banco é a fonte de verdade (localStorage NÃO restaura placa removida)
  if(DEMO){
    try{
      var savedDemo = localStorage.getItem('prog_veic_'+d);
      if(savedDemo){
        progLimparVeiculosDia(d);
        Object.assign(_progVeiculos, JSON.parse(savedDemo));
      }
    }catch(e){}
    return;
  }

  progFetchVeiculosDia(d).then(function(rows){
    _progVeiculosDateCache = d;
    var pending={};
    Object.keys(_progVeiculos||{}).forEach(function(k){
      if(progVeiculoKeyEhDoDia(k, d) && _progVeiculos[k] && String(_progVeiculos[k].placa||'').trim()){
        pending[k]=_progVeiculos[k];
      }
    });
    progLimparVeiculosDia(d);
    var loaded = 0;
    var eqComRegistro = {};
    (rows||[]).forEach(function(r){
      if(!r.equipe_id||!r.placa||r.deleted_at) return;
      eqComRegistro[String(r.equipe_id)] = true;
      var key = String(r.slot||'1')==='2' ? progVeiculoKeyB(r.equipe_id, d) : progVeiculoKey(r.equipe_id, d);
      _progVeiculos[key] = {id:r.veiculo_id,placa:r.placa,modelo:r.modelo,
        justificativa:r.justificativa,alterado_por:r.alterado_por};
      loaded++;
    });
    Object.keys(pending).forEach(function(k){
      if(!_progVeiculos[k]){ _progVeiculos[k]=pending[k]; loaded++; }
    });
    // Fallback composicao_dia só para equipes SEM registro em prog_veiculos_dia
    var compsFallback = 0;
    (composicao_dia||[]).forEach(function(c){
      var cd=(c.data||'').split('T')[0];
      if(cd!==d && c.data!==d) return;
      if(!c.placa || c.deleted_at) return;
      if(eqComRegistro[String(c.equipe_id)]) return;
      var key = progVeiculoKey(c.equipe_id, d);
      if(!_progVeiculos[key]){
        _progVeiculos[key]={id:c.veiculo_id,placa:c.placa,modelo:c.modelo||''};
        loaded++;
        compsFallback++;
      }
    });
    console.log('[veic load]',{data:d,prog_veiculos_dia:(rows&&rows.length)||0,composicao_fallback:compsFallback,total:loaded});
    progPersistVeiculosLocal(d);
    window._veicEscCache = {};
    progRenderQuadro();
  }).catch(function(e){
    console.error('[veic load] ERRO:',e);
    progRenderQuadro();
  });
}

/**
 * Recupera placas de equipes programadas sem veículo:
 * 1) composicao_dia.placa do próprio dia
 * 2) prog_veiculos_dia / composicao do dia anterior (mesma equipe)
 */
function progRecuperarPlacasDia(dataOpt){
  var data = (dataOpt || (typeof progGetData==='function'?progGetData():'') || '').split('T')[0];
  if(!data){ progShowToast('⚠ Informe a data da programação.'); return; }
  if(DEMO){ progShowToast('Indisponível no demo.'); return; }
  progShowToast('🔍 Buscando placas para recuperar…');
  var p=data.split('-');
  var dt=new Date(Date.UTC(+p[0], +p[1]-1, +p[2]));
  dt.setUTCDate(dt.getUTCDate()-1);
  var diaAnt = dt.toISOString().slice(0,10);

  function listarSemPlaca(comps){
    return (comps||[]).filter(function(c){
      var cd=(c.data||'').split('T')[0];
      if(cd!==data || c.deleted_at) return false;
      if(!(c.confirmada===true||c.confirmada==='true'||c.confirmada===1)) return false;
      return !progEquipeTemPlaca(c.equipe_id, data);
    });
  }

  var comps = (composicao_dia||[]).filter(function(c){
    return (c.data||'').split('T')[0]===data && !c.deleted_at;
  });
  var go = function(compsDia){
    var semPlaca = listarSemPlaca(compsDia);
    if(!semPlaca.length){
      progShowToast('✅ Nenhuma equipe programada sem placa neste dia.');
      return;
    }
    Promise.all([
      progFetchVeiculosDia(diaAnt),
      sbFetch('composicao_dia',{filters:['data=eq.'+diaAnt,'deleted_at=is.null'],limit:500}).catch(function(){return[];})
    ]).then(function(res){
      var veicsAnt = res[0]||[];
      var compsAnt = res[1]||[];
      var recuperados = 0, falhas = 0;
      var chain = Promise.resolve();
      semPlaca.forEach(function(comp){
        chain = chain.then(function(){
          var eqId = comp.equipe_id;
          var placa = (comp.placa||comp.veiculo_placa||'').trim();
          var veicId = comp.veiculo_id||null;
          var modelo = comp.modelo||'';
          if(!placa){
            var pv = veicsAnt.find(function(r){
              return String(r.equipe_id)===String(eqId) && (!r.slot||r.slot===1||r.slot==='1') && r.placa;
            });
            if(pv){ placa=pv.placa; veicId=pv.veiculo_id||veicId; modelo=pv.modelo||modelo; }
          }
          if(!placa){
            var ca = compsAnt.find(function(c){
              return String(c.equipe_id)===String(eqId) && (c.placa||c.veiculo_placa);
            });
            if(ca){ placa=ca.placa||ca.veiculo_placa; veicId=ca.veiculo_id||veicId; modelo=ca.modelo||modelo; }
          }
          if(!placa){ falhas++; return; }
          if(!veicId && (frt_veiculos||[]).length){
            var fv=(frt_veiculos||[]).find(function(v){
              return String(v.placa||'').toUpperCase().replace(/[-\s]/g,'')===String(placa).toUpperCase().replace(/[-\s]/g,'');
            });
            if(fv){ veicId=fv.id; modelo=modelo||fv.modelo||''; }
          }
          var veicObj={id:veicId,placa:placa,modelo:modelo,alterado_por:(usuarioLogado&&usuarioLogado.nome)||'Recuperação'};
          return Promise.resolve(progSetVeiculo(eqId, data, veicObj)).then(function(ok){
            if(ok){
              recuperados++;
              comp.placa=placa; comp.veiculo_id=veicId; comp.modelo=modelo;
              if(comp.id && !comp._local){
                return sbUpdate('composicao_dia',{placa:placa,veiculo_id:veicId,modelo:modelo},'id=eq.'+comp.id);
              }
            } else falhas++;
          });
        });
      });
      return chain.then(function(){
        progCarregarVeiculos(data);
        progShowToast('🚗 Recuperadas: '+recuperados+' · sem fonte: '+falhas+' (de '+semPlaca.length+' sem placa)');
      });
    }).catch(function(e){
      console.error('progRecuperarPlacasDia',e);
      progShowToast('⚠ Erro ao recuperar placas.','erro');
    });
  };

  if(!comps.length){
    sbFetch('composicao_dia',{filters:['data=eq.'+data,'confirmada=eq.true','deleted_at=is.null'],limit:500})
      .then(function(rows){
        (rows||[]).forEach(function(r){
          if(!(composicao_dia||[]).some(function(c){return c.id===r.id;})) composicao_dia.push(r);
        });
        go(composicao_dia);
      });
  } else {
    go(comps);
  }
}

// ── Renderiza mini-card de um slot de veículo (a=moto1, b=moto2) ─
function _progVeicKitBadgeHtml(frtV){
  if(!frtV) return '';
  var st=(frtV.status_kit_materiais||'').trim();
  var stHtml='';
  if(st){
    var lbl=(typeof VIST_KIT_ST!=='undefined'&&VIST_KIT_ST[st])?VIST_KIT_ST[st]:st;
    var cor=st==='em_operacao'?'#3B6D11':((typeof _dbStatusKitCargaPendente==='function'&&_dbStatusKitCargaPendente(st))?'#854F0B':'#533AB7');
    stHtml='<div style="font-size:9px;color:'+cor+';font-weight:600">'+escHtml(lbl)+'</div>';
  }
  var tipoOp=(frtV.tipo_operacional||'').trim();
  var n=typeof almResolverKitVeiculo==='function'?almResolverKitVeiculo(frtV.id,tipoOp||null,frtV.contrato_id||null).length:0;
  if(!tipoOp&&!n) return stHtml||'<div style="font-size:9px;color:#854F0B;font-weight:600">⚠ sem tipo/kit</div>';
  if(!n) return stHtml+'<div style="font-size:9px;color:#854F0B;font-weight:600">⚠ sem kit mat.</div>';
  return stHtml+'<div style="font-size:9px;color:#3B6D11">📦 '+n+' mat.</div>';
}
function _renderVeicSlot(eqId, data, v, slot, conflitos){
  conflitos = conflitos||{};
  var btnId = slot==='b' ? 'prog-veic-btn2-'+eqId : 'prog-veic-btn-'+eqId;
  var lbl   = slot==='b' ? '🏍 Moto 2' : '🏍 Moto 1';
  if(!v){
    return '<button id="'+btnId+'" data-eq="'+eqId+'" data-dt="'+data+'" data-slot="'+slot+'" '
      +'onclick="progAbrirSelecionarVeiculo(this.dataset.eq,this.dataset.dt,this.dataset.slot)" '
      +'style="background:#f5f5f3;border:.5px dashed #ccc;border-radius:6px;padding:3px 6px;'
      +'font-size:10px;color:#888;cursor:pointer;width:100%;white-space:nowrap">+ '+lbl+'</button>';
  }
  var temConflito = !!(v.placa && conflitos[v.placa]);
  var borda = temConflito ? 'border:2px solid #A32D2D;' : '';
  var corTexto = temConflito ? '#A32D2D' : '#185FA5';
  return '<div id="'+btnId+'" data-eq="'+eqId+'" data-dt="'+data+'" data-slot="'+slot+'" '
    +'onclick="progAbrirSelecionarVeiculo(this.dataset.eq,this.dataset.dt,this.dataset.slot)" '
    +'style="background:#E6F1FB;border-radius:6px;padding:3px 6px;cursor:pointer;'+borda+'">'
    +'<div style="font-size:9px;color:'+corTexto+';font-weight:600">'+lbl+'</div>'
    +'<div style="font-family:monospace;font-size:11px;font-weight:700;color:'+corTexto+'">'+v.placa+(temConflito?' ⚠':'')+'</div>'
    +'<div style="font-size:10px;color:#888">'+v.modelo+'</div>'
    +_progVeicKitBadgeHtml((frt_veiculos||[]).find(function(x){return x.placa===v.placa;}))
    +(temConflito?'<div style="font-size:9px;color:#A32D2D;font-weight:700">Duplicado!</div>':'')
    +(v.justificativa?'<div style="font-size:9px;color:#854F0B" title="'+v.justificativa+'">✎ alterado</div>':'')
    +'</div>';
}

// ── Renderiza a célula de veículo no card da equipe ──────────
function progRenderVeiculoCell(eq, data){
  var v = progGetVeiculo(eq.id, data);
  var conflitos = progVeicConflitos(data);

  // Moto Dupla → 2 slots lado a lado
  if(isMotoDupla(eq)){
    var v2 = progGetVeiculoB(eq.id, data);
    return '<div style="display:flex;gap:4px">'
      +_renderVeicSlot(eq.id, data, v,  'a', conflitos)
      +_renderVeicSlot(eq.id, data, v2, 'b', conflitos)
      +'</div>';
  }
  // Equipe comum — 1 slot
  if(!v){
    return '<button id="prog-veic-btn-'+eq.id+'" data-eq="'+eq.id+'" data-dt="'+data+'" data-slot="a" '
      +'onclick="progAbrirSelecionarVeiculo(this.dataset.eq,this.dataset.dt,this.dataset.slot)" '
      +'style="background:#f5f5f3;border:.5px dashed #ccc;border-radius:6px;padding:3px 8px;font-size:11px;color:#888;cursor:pointer;width:100%">+ Veículo</button>';
  }
  var frtV = frt_veiculos ? frt_veiculos.find(function(x){return x.placa===v.placa;}) : null;
  var temConflito = !!(v.placa && conflitos[v.placa]);
  var bordaConflito = temConflito ? 'border:2px solid #A32D2D;' : '';
  return '<div style="background:#E6F1FB;border-radius:6px;padding:3px 6px;cursor:pointer;'+bordaConflito+'" id="prog-veic-btn-'+eq.id+'" '
    +'data-eq="'+eq.id+'" data-dt="'+data+'" data-slot="a" '
    +'onclick="progAbrirSelecionarVeiculo(this.dataset.eq,this.dataset.dt,this.dataset.slot)">'
    +'<div style="font-family:monospace;font-size:11px;font-weight:700;color:'+(temConflito?'#A32D2D':'#185FA5')+'">'+v.placa+(temConflito?' ⚠':'')+' </div>'
    +'<div style="font-size:10px;color:#888">'+v.modelo+'</div>'
    +_progVeicKitBadgeHtml(frtV)
    +(temConflito?'<div style="font-size:9px;color:#A32D2D;font-weight:700">Veículo duplicado!</div>':'')
    +(v.justificativa?'<div style="font-size:9px;color:#854F0B" title="'+v.justificativa+'">✎ alterado</div>':'')
    +'</div>';
}

// ── Abrir modal de seleção de veículo ────────────────────────
// Verifica se dois turnos se sobrepõem (suporte a turnos overnight)
function turnsoSeSobrepoe(ini1, fim1, ini2, fim2){
  function toMin(h){
    if(!h) return 0;
    var p=(h||'').replace(/[^\d:]/g,'').split(':');
    return (parseInt(p[0])||0)*60+(parseInt(p[1])||0);
  }
  var s1=toMin(ini1), e1=toMin(fim1);
  var s2=toMin(ini2), e2=toMin(fim2);
  // Turno overnight: fim < início → adicionar 24h ao fim
  if(e1>0 && e1<=s1) e1+=24*60;
  if(e2>0 && e2<=s2) e2+=24*60;
  // Se ainda sem fim definido, assume turno de 8h
  if(!e1) e1=s1+480;
  if(!e2) e2=s2+480;
  return s1<e2 && s2<e1;
}

function progAbrirSelecionarVeiculo(eqId, data, slot){
  slot = slot || 'a'; // 'a' = slot 1, 'b' = slot 2 (Moto Dupla)
  if(!DEMO && typeof progGarantirFrotaCompleta==='function' && !window._progFrotaBaixadosOk){
    window._progFrotaBaixadosOk=true;
    if(!(frt_veiculos||[]).some(function(v){ return progVeicEhBaixado(v); })){
      progGarantirFrotaCompleta(function(){ progAbrirSelecionarVeiculo(eqId, data, slot); });
      return;
    }
  }
  // Aceita equipes de equipes_disp (Disponibilidade) OU equipes (Projetos)
  var eq = equipes_disp.find(function(e){return e.id===eqId;})
        || equipes.find(function(e){return e.id===eqId;});
  if(!eq) return;
  var _compLock = typeof progFindCompDia==='function' ? progFindCompDia(eqId, data) : null;
  if(_compLock && (_compLock.confirmada===true||_compLock.confirmada==='true'||_compLock.confirmada===1)){
    progShowToast('🔒 Equipe já programada — desprograme para alterar a placa.');
    return;
  }
  var vAtual = slot==='b' ? progGetVeiculoB(eqId, data) : progGetVeiculo(eqId, data);
  var perfil = usuarioLogado ? usuarioLogado.perfil : '';
  var precisaJustif = vAtual && perfil !== 'programador' && perfil !== 'gestor' && perfil !== 'administrador';

  // Determinar tipo de veículo esperado para a equipe
  var _tipoEq = '';
  if(eq.tipo_id){
    var _tipoObj = tipos_equipe.find(function(t){return t.id===eq.tipo_id;});
    _tipoEq = _tipoObj ? (_tipoObj.nome||'').toLowerCase() : '';
  } else {
    _tipoEq = (eq.nome||'').toLowerCase();
  }
  // Mapeamento: tipo de equipe → tipos de veículo compatíveis
  var _veicTiposCompativeis = null; // null = sem filtro (todos)
  if(_tipoEq.includes('cesto') || _tipoEq.includes('aéreo') || _tipoEq.includes('aereo')){
    _veicTiposCompativeis = ['Caminhão cesto','Caminhão munck','Caminhão'];
  } else if(_tipoEq.includes('moto')){
    _veicTiposCompativeis = ['Motocicleta'];
  } else if(_tipoEq.includes('van')){
    _veicTiposCompativeis = ['Van','Carro leve','Caminhonete'];
  }
  // Se houver filtro, separar compatíveis de incompatíveis
  // Inclui Baixado (pode escalar); oculta demais inativos (Vendido, Descartado, etc.)
  var veicsFrota = (frt_veiculos || []).filter(function(v){
    if(progVeicEhBaixado(v)) return true;
    if(v.ativo===false) return false;
    var st=String(v.status||'').toLowerCase();
    if(st==='vendido'||st==='descartado'||st==='extraviado'||st==='inativo') return false;
    return true;
  });
  if(_veicTiposCompativeis){
    // Compatíveis primeiro, depois incompatíveis com badge de aviso
    var _compat = veicsFrota.filter(function(v){ return _veicTiposCompativeis.indexOf(v.tipo||'') >= 0; });
    var _incompat = veicsFrota.filter(function(v){ return _veicTiposCompativeis.indexOf(v.tipo||'') < 0; });
    veicsFrota = _compat.concat(_incompat);
  }
  var veicsClassif = veicsFrota.map(function(v){
    var classe, cor, bg, icone, titulo;
    // Incompatível com tipo de equipe?
    var tipoIncompat = _veicTiposCompativeis && _veicTiposCompativeis.indexOf(v.tipo||'') < 0;

    // Já programado para outra equipe no mesmo dia?
    // Verificar sobreposição de turnos — se turnos não se sobrepõem, não bloquear
    var outraEquipe = null;
    var turnoConflito = false;
    Object.keys(_progVeiculos).forEach(function(k){
      var kData = k.split('_').pop();
      var kEqId = k.replace('_'+kData,'');
      if(kData === data && kEqId !== eqId && _progVeiculos[k] && _progVeiculos[k].placa === v.placa){
        var eqOutra = equipes_disp.find(function(e){return e.id===kEqId;})||{codigo:'outra equipe'};
        outraEquipe = eqOutra;
        // Checar sobreposição de horários
        var hIniAtual = eq ? (eq.hora_inicio||'').substring(0,5) : '';
        var hFimAtual = eq ? (eq.hora_fim||'').substring(0,5) : '';
        var hIniOutra = eqOutra.hora_inicio ? (eqOutra.hora_inicio||'').substring(0,5) : '';
        var hFimOutra = eqOutra.hora_fim ? (eqOutra.hora_fim||'').substring(0,5) : '';
        if(hIniAtual && hFimAtual && hIniOutra && hFimOutra){
          turnoConflito = turnsoSeSobrepoe(hIniAtual, hFimAtual, hIniOutra, hFimOutra);
        } else {
          turnoConflito = true; // sem horário definido, assume conflito
        }
      }
    });

    var emManutencao = ['Em manutenção','Aguardando peça','Aguardando oficina',
      'Solicitação de manutenção','Em análise pela frota'].indexOf(v.status)>=0;
    var bloqueado = ['Bloqueado','Em quarentena'].indexOf(v.status)>=0;
    var ehBaixado = progVeicEhBaixado(v);

    if(outraEquipe && turnoConflito){
      classe = 'red'; cor = '#A32D2D'; bg = '#FCEBEB'; icone = '🔴';
      titulo = '⛔ Conflito de turno com ' + outraEquipe.codigo;
    } else if(outraEquipe && !turnoConflito){
      classe = 'yellow'; cor = '#854F0B'; bg = '#FEF3E2'; icone = '🟡';
      titulo = 'Compartilhado com ' + outraEquipe.codigo + ' (turnos diferentes ✓)';
    } else if(bloqueado){
      classe = 'red';
      cor = '#A32D2D';
      bg = '#FCEBEB';
      icone = '🔴';
      titulo = v.status;
    } else if(ehBaixado){
      classe = 'gray';
      cor = '#555';
      bg = '#f0f0ee';
      icone = '⚪';
      titulo = 'Baixado — pode escalar';
    } else if(emManutencao){
      classe = 'yellow';
      cor = '#854F0B';
      bg = '#FEF3E2';
      icone = '🟡';
      titulo = v.status;
    } else if(v.status === 'Em uso'){
      // Em uso na portaria — verificar se é do mesmo contrato da equipe
      var mesmoContrato = eq && v.contrato_id && v.contrato_id === eq.contrato_id;
      classe = mesmoContrato ? 'yellow' : 'red';
      cor    = mesmoContrato ? '#854F0B' : '#A32D2D';
      bg     = mesmoContrato ? '#FEF3E2' : '#FCEBEB';
      icone  = mesmoContrato ? '🟡' : '🔴';
      titulo = mesmoContrato ? 'Em uso (mesmo contrato)' : 'Em uso (outro contrato)';
    } else {
      // Verificar se é do mesmo contrato da equipe
      var mesmoContr = !eq || !eq.contrato_id || !v.contrato_id || v.contrato_id === eq.contrato_id;
      if(!mesmoContr){
        classe = 'brown';
        cor    = '#7B4A1E';
        bg     = '#F5EBE0';
        icone  = '🟤';
        titulo = 'Outro contrato — uso esporádico';
      } else {
        classe = 'green';
        cor    = '#3B6D11';
        bg     = '#EAF3DE';
        icone  = '🟢';
        titulo = v.status === 'Disponível' ? 'Disponível' : v.status;
      }
    }

    return {v:v, classe:classe, cor:cor, bg:bg, icone:icone, titulo:titulo,
      tipoIncompat: tipoIncompat,
      bloqueado: bloqueado || (outraEquipe !== null && turnoConflito) || (v.status==='Em uso' && !(eq && v.contrato_id && v.contrato_id===eq.contrato_id))};
  });

  // Ordenar: do contrato → outro contrato → baixado → manutenção → bloqueados
  veicsClassif.sort(function(a,b){
    var ordem = {green:0, brown:1, gray:2, yellow:3, red:4};
    var oa = ordem[a.classe]||0, ob = ordem[b.classe]||0;
    if(oa!==ob) return oa-ob;
    // Dentro do mesmo grupo, ordenar por placa
    return (a.v.placa||'').localeCompare(b.v.placa||'');
  });

  // Montar lista com separadores entre grupos
  var grupoAtual = null;
  var grupoCores = {
    green:  {label:'✅ Do contrato — disponíveis', cor:'#3B6D11'},
    brown:  {label:'🟤 Outro contrato — uso esporádico/provisório', cor:'#7B4A1E'},
    gray:   {label:'⚪ Baixado no cadastro — pode escalar', cor:'#555'},
    yellow: {label:'🟡 Em manutenção / Em uso', cor:'#854F0B'},
    red:    {label:'🔴 Bloqueado / Outra equipe', cor:'#A32D2D'},
  };

  var listaHtml = veicsClassif.length
    ? veicsClassif.map(function(item){
        var v = item.v;
        var selecionado = vAtual && vAtual.placa === v.placa;
        var posse = v.posse==='Alugado'?'<span style="font-size:9px;background:#E6F1FB;color:#185FA5;border-radius:3px;padding:1px 4px;margin-left:4px">Alug.</span>':'';
        var separador = '';
        if(item.classe !== grupoAtual){
          grupoAtual = item.classe;
          var g = grupoCores[item.classe]||{label:item.classe, cor:'#888'};
          separador = '<div style="font-size:10px;font-weight:700;color:'+g.cor
            +';padding:6px 2px 3px;margin-top:'+(grupoAtual!=='green'?'8px':'0')+'">'+g.label+'</div>';
        }
        return separador
          +'<div class="frt-veic-item" data-placa="'+v.placa+'" data-modelo="'+v.modelo+'" data-id="'+(v.id||'')+'"'
          +' style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;cursor:'
          +(item.bloqueado?'not-allowed':'pointer')+';border:.5px solid '+(selecionado?item.cor:item.bg)+';'
          +'background:'+(selecionado?item.bg+'dd':'#fff')+';margin-bottom:5px;opacity:'+(item.bloqueado?'0.6':'1')+'">'
          +'<span style="font-size:16px">'+item.icone+'</span>'
          +'<div style="flex:1;min-width:0">'
          +'<div style="font-family:monospace;font-weight:700;font-size:13px;color:'+item.cor+'">'+v.placa+posse+'</div>'
          +'<div style="font-size:11px;color:#888">'+v.modelo+' — '+v.tipo+(item.tipoIncompat?' <span style="background:#FEF3E2;color:#854F0B;border-radius:3px;padding:1px 4px;font-size:9px;font-weight:700">⚠ Tipo diferente</span>':'')+'</div>'
          +'</div>'
          +'<div style="text-align:right">'
          +'<div style="font-size:10px;font-weight:600;color:'+item.cor+'">'+item.titulo+'</div>'
          +(v.km_atual?'<div style="font-size:10px;color:#aaa">'+(v.km_atual||0).toLocaleString('pt-BR')+' km</div>':'')
          +'</div>'
          +(selecionado?'<span style="font-size:16px">✅</span>':'')
          +'</div>';
      }).join('')
    : '<div style="padding:1.5rem;text-align:center;color:#aaa;font-size:12px">Nenhum veículo cadastrado no módulo Frotas.<br>Cadastre em 🚗 Frotas → Veículos.</div>';

  // ── Legenda ───────────────────────────────────────────────
  var legendaHtml = '<div style="display:flex;gap:10px;font-size:10px;flex-wrap:wrap;margin-bottom:.75rem;padding:.5rem .75rem;background:#f9f9f7;border-radius:8px">'
    +'<span>🟢 Do contrato</span>'
    +'<span>🟤 Outro contrato (esporádico)</span>'
    +'<span>⚪ Baixado (pode escalar)</span>'
    +'<span>🟡 Manutenção / Em uso</span>'
    +'<span>🔴 Bloqueado / Outra equipe</span>'
    +'</div>';

  var _slotLbl = isMotoDupla(eq) ? (slot==='b' ? ' — 🏍 Moto 2' : ' — 🏍 Moto 1') : '';
  var html = '<div class="modal-bg"><div class="modal" style="max-width:440px">'
    +'<h3>🚗 Veículo'+_slotLbl+' — <b>'+eq.codigo+'</b></h3>'
    +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">'+fmtD(data)+'</div>'

    // Aviso se precisa justificativa
    +(precisaJustif
      ?'<div style="background:#FEF3E2;border-radius:8px;padding:.6rem;margin-bottom:.75rem;font-size:12px;color:#854F0B">'
        +'⚠ Veículo já definido. Alteração exige justificativa.</div>'
      :'')

    // Busca rápida
    +'<div style="margin-bottom:.5rem">'
    +'<input class="inp" id="pv-busca" placeholder="Filtrar por placa ou modelo..." style="width:100%" oninput="progFiltrarListaVeiculos()"/>'
    +'</div>'

    // Legenda
    + legendaHtml

    // Lista de veículos
    +'<div id="pv-lista" style="max-height:320px;overflow-y:auto;margin-bottom:.75rem">'
    + listaHtml
    +'</div>'

    // Campo placa manual (se frota vazia ou veículo não listado)
    +'<details style="margin-bottom:.75rem">'
    +'<summary style="font-size:11px;color:#888;cursor:pointer;padding:4px">Ou informe a placa manualmente</summary>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-top:.5rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Placa</label>'
    +'<input class="inp" id="pv-placa" style="width:100%;text-transform:uppercase;font-family:monospace" '
    +'value="'+(vAtual?vAtual.placa:'')+'" placeholder="ABC-1234"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Modelo</label>'
    +'<input class="inp" id="pv-modelo" style="width:100%" value="'+(vAtual?vAtual.modelo:'')+'" placeholder="Ranger..."/></div>'
    +'</div></details>'

    // Justificativa
    +(precisaJustif
      ?'<div style="margin-bottom:.75rem"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Justificativa *</label>'
        +'<textarea class="inp" id="pv-just" style="width:100%;height:55px" placeholder="Motivo da alteração..."></textarea></div>'
      :'')

    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +(vAtual?'<button class="btn" id="pv-remover" style="color:#A32D2D;border-color:#A32D2D">✕ Remover</button>':'')
    +'<button class="btn btn-pri" id="pv-salvar" style="flex:1">Confirmar</button>'
    +'</div></div></div>';

  // Guardar referência para o modal
  window._pvEqId = eqId;
  window._pvData = data;
  window._pvSlot = slot;
  window._pvJustif = precisaJustif;
  window._pvVeicsClassif = veicsClassif;

  setModal(html);

  setTimeout(function(){
    // Clicar em item da lista seleciona
    document.querySelectorAll('.frt-veic-item').forEach(function(el){
      el.onclick = function(){
        var placa = el.getAttribute('data-placa');
        var modelo = el.getAttribute('data-modelo');
        var item = (window._pvVeicsClassif||[]).find(function(x){return x.v.placa===placa;});
        if(item && item.bloqueado){
          alert('⚠ Este veículo está '+item.titulo+' e não pode ser selecionado.');
          return;
        }
        // Desmarcar todos
        document.querySelectorAll('.frt-veic-item').forEach(function(x){
          x.style.border = '.5px solid '+( (window._pvVeicsClassif||[]).find(function(i){return i.v.placa===x.getAttribute('data-placa');})||{bg:'#f9f9f7'}).bg;
          x.style.background = '#fff';
          // Remover check
          var chk = x.querySelector('span[style*="font-size:16px"]:last-child');
          if(chk && chk.textContent==='✅') chk.remove();
        });
        // Marcar selecionado
        el.style.border = '.5px solid '+(item?item.cor:'#3B6D11');
        el.style.background = item?item.bg+'dd':'#EAF3DE';
        var chk = document.createElement('span');
        chk.style.cssText = 'font-size:16px';
        chk.textContent = '✅';
        el.appendChild(chk);
        // Preencher campos manuais
        var p=document.getElementById('pv-placa');if(p)p.value=placa;
        var m=document.getElementById('pv-modelo');if(m)m.value=modelo;
      };
    });

    // Salvar
    var btnSalvar = document.getElementById('pv-salvar');
    if(btnSalvar) btnSalvar.onclick = function(){
      var placa = (document.getElementById('pv-placa')||{}).value.trim().toUpperCase();
      var modelo = (document.getElementById('pv-modelo')||{}).value.trim();
      if(!placa){ alert('Selecione ou informe a placa.'); return; }
      if(window._pvJustif){
        var just = (document.getElementById('pv-just')||{}).value.trim();
        if(!just){ alert('Informe a justificativa.'); return; }
      }
      // Verificar conflito de turno com veículo já alocado
      var conflito = false;
      var compartilhado = false;
      Object.keys(_progVeiculos).forEach(function(k){
        var kData = k.split('_').pop();
        var kEqId = k.replace('_'+kData,'');
        if(kData===data && kEqId!==eqId && _progVeiculos[k] && _progVeiculos[k].placa===placa){
          var eqOutra = equipes_disp.find(function(e){return e.id===kEqId;});
          var hIA=eq?(eq.hora_inicio||'').substring(0,5):'';
          var hFA=eq?(eq.hora_fim||'').substring(0,5):'';
          var hIO=eqOutra?(eqOutra.hora_inicio||'').substring(0,5):'';
          var hFO=eqOutra?(eqOutra.hora_fim||'').substring(0,5):'';
          if(hIA&&hFA&&hIO&&hFO){
            if(turnsoSeSobrepoe(hIA,hFA,hIO,hFO)) conflito=true;
            else compartilhado=true;
          } else { conflito=true; }
        }
      });
      if(conflito && !confirm('⚠ Este veículo tem conflito de horário com outra equipe.\nConfirmar mesmo assim?')) return;
      if(compartilhado) progShowToast('ℹ Veículo compartilhado em turnos diferentes.');

      var itemSel = (window._pvVeicsClassif||[]).find(function(x){return x.v.placa===placa;});
      var _slotAtual = window._pvSlot || 'a';
      var _veicPayload = {
        id: itemSel?itemSel.v.id:null,
        placa: placa, modelo: modelo,
        justificativa: (document.getElementById('pv-just')||{}).value||'',
        alterado_por: usuarioLogado?usuarioLogado.nome:''
      };
      // Bloquear modal até banco confirmar
      var _btnSalvarEl = document.getElementById('pv-salvar');
      if(_btnSalvarEl){ _btnSalvarEl.disabled=true; _btnSalvarEl.textContent='Salvando...'; }

      var _savePromise = _slotAtual==='b'
        ? progSetVeiculoB(eqId, data, _veicPayload)
        : progSetVeiculo(eqId, data, _veicPayload);

      _savePromise.then(function(ok){
        if(!ok){
          if(_btnSalvarEl){ _btnSalvarEl.disabled=false; _btnSalvarEl.textContent='Confirmar'; }
          progShowToast('⚠ Erro ao salvar veículo no banco. Tente novamente.','erro');
          return;
        }
        closeModal();
        var _eqObj = equipes_disp.find(function(e){return e.id===eqId;})||{id:eqId};
        var cell = document.getElementById('prog-veic-cell-'+eqId);
        if(cell) cell.innerHTML = progRenderVeiculoCell(_eqObj, data);
        var _btn1 = document.getElementById('prog-veic-btn-'+eqId);
        if(_btn1) _btn1.onclick = function(){progAbrirSelecionarVeiculo(eqId, data, 'a');};
        var _btn2b = document.getElementById('prog-veic-btn2-'+eqId);
        if(_btn2b) _btn2b.onclick = function(){progAbrirSelecionarVeiculo(eqId, data, 'b');};
      });
    };

    // Remover
    var btnRem = document.getElementById('pv-remover');
    if(btnRem) btnRem.onclick = function(){
      var _slotR = window._pvSlot || 'a';
      if(_slotR==='b') progRemoverVeiculoB(eqId, data);
      else progRemoverVeiculo(eqId, data);
    };
  },50);
}

function progFiltrarListaVeiculos(){
  var busca = ((document.getElementById('pv-busca')||{}).value||'').toLowerCase();
  var buscaNorm = busca.replace(/[-\s]/g,'');
  document.querySelectorAll('.frt-veic-item').forEach(function(el){
    var placa = (el.getAttribute('data-placa')||'').toLowerCase();
    var placaNorm = placa.replace(/[-\s]/g,'');
    var modelo = (el.getAttribute('data-modelo')||'').toLowerCase();
    var ok = !busca || placa.indexOf(busca)>=0 || placaNorm.indexOf(buscaNorm)>=0 || modelo.indexOf(busca)>=0;
    el.style.display = ok?'':'none';
  });
}



function progPreencherVeicSel(){
  var sel = document.getElementById('pv-sel'); if(!sel||!sel.value) return;
  var opt = sel.options[sel.selectedIndex];
  var p = document.getElementById('pv-placa'); if(p) p.value = opt.getAttribute('data-placa')||'';
  var m = document.getElementById('pv-modelo'); if(m) m.value = opt.getAttribute('data-modelo')||'';
}

function progRemoverVeiculo(eqId, data){
  var d=(data||'').split('T')[0];
  var comp = typeof progFindCompDia==='function' ? progFindCompDia(eqId, d) : null;
  if(comp && (comp.confirmada===true || comp.confirmada==='true' || comp.confirmada===1)){
    progShowToast('🔒 Equipe já programada — desprograme antes de remover a placa.','erro');
    return;
  }
  if(!confirm('Remover veículo desta equipe?')) return;

  delete _progVeiculos[progVeiculoKey(eqId, d)];
  progPersistVeiculosLocal(d);
  window._veicEscCache = {};

  closeModal();
  var cell = document.getElementById('prog-veic-cell-'+eqId);
  if(cell) cell.innerHTML = progRenderVeiculoCell({id:eqId}, d);
  var btn = document.getElementById('prog-veic-btn-'+eqId);
  if(btn) btn.onclick = function(){progAbrirSelecionarVeiculo(eqId, d);};

  // Persistir remoção: composição (fonte do Atualizar) + prog_veiculos_dia
  if(DEMO) return;
  var _h = {'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key)};
  Promise.all([
    progLimparPlacaComposicao(eqId, d),
    progFetchVeiculosDia(d, eqId).then(function(res){
      return Promise.all((res||[]).map(function(row){
        var rowSlot = row.slot===undefined||row.slot===null||row.slot===1||row.slot==='1';
        if(!rowSlot || !row.id || !isUUID(row.id)) return null;
        return fetch(SB.url+'/rest/v1/prog_veiculos_dia?id=eq.'+row.id,{method:'DELETE',headers:_h})
          .catch(function(e){console.error('progRemoverVeiculo DELETE erro',e);});
      }));
    })
  ]).catch(function(e){ console.error('progRemoverVeiculo persist erro', e); });
}

// Vincular botões de veículo após render do quadro
function progBindVeiculos(){
  var data = progGetData();
  equipes_disp.forEach(function(eq){
    var btn = document.getElementById('prog-veic-btn-'+eq.id);
    if(btn) btn.onclick = function(){progAbrirSelecionarVeiculo(eq.id, data);};
  });
}

// ═══════════════════════════════════════════════════════════════
// FOTO DO ODÔMETRO — IA lê e converte em número
// ═══════════════════════════════════════════════════════════════

function dbAbrirCameraOdometro(targetInputId, label){
  // Criar input file oculto para câmera
  var inp = document.createElement('input');
  inp.type = 'file';
  inp.accept = 'image/*';
  inp.capture = 'environment'; // câmera traseira
  inp.style.display = 'none';
  document.body.appendChild(inp);

  inp.onchange = function(){
    if(!inp.files||!inp.files[0]) return;
    var file = inp.files[0];
    document.body.removeChild(inp);

    // Mostrar preview e loading
    var targetInput = document.getElementById(targetInputId);
    if(targetInput){
      targetInput.placeholder = '📷 Analisando foto...';
      targetInput.disabled = true;
    }

    var toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#1a1a18;color:#fff;padding:10px 20px;border-radius:10px;font-size:13px;z-index:9999';
    toast.textContent = '📷 Lendo odômetro com IA...';
    document.body.appendChild(toast);

    // Converter imagem para base64
    var reader = new FileReader();
    reader.onload = function(e){
      var base64 = e.target.result.split(',')[1];
      var mediaType = file.type || 'image/jpeg';

      // Chamar API Claude Vision
      fetch('https://cena-proxy.marcos-afe.workers.dev', {
        method: 'POST',
        headers: {'Content-Type':'application/json'},
        body: JSON.stringify({
          model: 'claude-sonnet-4-5',
          max_tokens: 100,
          messages:[{
            role:'user',
            content:[
              {type:'image', source:{type:'base64', media_type:mediaType, data:base64}},
              {type:'text', text:'Esta é uma foto do odômetro de um veículo. Responda APENAS com o número inteiro do KM mostrado no odômetro, sem pontos, vírgulas ou texto. Exemplo: 45230. Se não conseguir ler, responda: ERRO'}
            ]
          }]
        })
      })
      .then(function(r){ return r.json(); })
      .then(function(data){
        document.body.removeChild(toast);
        var resp = data.content&&data.content[0]?data.content[0].text.trim():'ERRO';
        var km = parseInt(resp.replace(/\D/g,''));

        if(isNaN(km)||resp==='ERRO'){
          // Falhou - abrir input manual
          if(targetInput){
            targetInput.disabled = false;
            targetInput.placeholder = 'Ex: 45230';
          }
          alert('Não foi possível ler o odômetro automaticamente. Por favor, informe o KM manualmente.');
        } else {
          // Sucesso - preencher campo
          if(targetInput){
            targetInput.value = km;
            targetInput.disabled = false;
            targetInput.style.background = '#EAF3DE';
            targetInput.style.color = '#3B6D11';
          }
          // Toast de confirmação
          var t2 = document.createElement('div');
          t2.style.cssText = 'position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#3B6D11;color:#fff;padding:10px 20px;border-radius:10px;font-size:13px;z-index:9999';
          t2.innerHTML = '✅ KM lido: <b>'+km.toLocaleString('pt-BR')+' km</b> — Confirme se está correto';
          document.body.appendChild(t2);
          setTimeout(function(){ if(document.body.contains(t2)) document.body.removeChild(t2); }, 4000);
        }
      })
      .catch(function(err){
        document.body.removeChild(toast);
        if(targetInput){ targetInput.disabled=false; targetInput.placeholder='Ex: 45230'; }
        alert('Erro ao processar a foto. Informe o KM manualmente.');
        console.error('Odômetro IA erro:', err);
      });
    };
    reader.readAsDataURL(file);
  };

  inp.click();
}


