// ── Dados em memória ─────────────────────────────────────────
// ══ MÓDULO CONTROLE DE PNEUS ══════════════════════════════════
var pneus_dados      = [];
var pneus_vidas      = [];
var pneus_posicoes   = [];
var pneus_movimentos = [];
var pneus_config_eixos = {};
var _pneusAbaAtiva   = 'estoque';

var PNEU_STATUS = {
  'novo':                  {label:'Novo',                   cor:'#3B6D11', bg:'#EAF3DE'},
  'usado':                 {label:'Usado',                  cor:'#555',    bg:'#f0efe8'},
  'recapado':              {label:'Ressolado',              cor:'#854F0B', bg:'#FEF3E2'},
  'em_uso':                {label:'Em uso',                 cor:'#185FA5', bg:'#E6F1FB'},
  'estoque':               {label:'Em estoque',             cor:'#555',    bg:'#f5f5f3'},
  'em_recapagem':          {label:'Em recapagem',           cor:'#7C3AED', bg:'#F3E8FF'},
  'aguardando_avaliacao':  {label:'Aguardando avaliação',   cor:'#B54708', bg:'#FFF4ED'},
  'descartado':            {label:'Descartado',             cor:'#A32D2D', bg:'#FCEBEB'},
};
var PNEU_MOVIMENTOS = ['Instalação','Remoção','Rodízio','Substituição','Envio para recapagem','Retorno de recapagem','Retorno para estoque','Descarte','Alteração cadastro'];

function pneusNormStatus(st){
  var s=String(st||'').trim().toLowerCase().replace(/\s+/g,'_');
  if(s==='em_estoque'||s==='emestoque') return 'estoque';
  if(s==='ressolado') return 'recapado';
  if(s==='em_uso'||s==='emuso') return 'em_uso';
  if(s==='em_recapagem'||s==='emrecapagem') return 'em_recapagem';
  if(s==='aguardando_avaliacao'||s==='aguardandoavaliacao') return 'aguardando_avaliacao';
  if(PNEU_STATUS[s]) return s;
  if(PNEU_STATUS[st]) return st;
  return st||'estoque';
}
function pneusStatusLabel(st){
  var k=pneusNormStatus(st);
  return (PNEU_STATUS[k]&&PNEU_STATUS[k].label)||st||'—';
}
function pneusStatusMeta(st){
  var k=pneusNormStatus(st);
  return PNEU_STATUS[k]||{label:st||'—',cor:'#888',bg:'#f5f5f3'};
}
function pneusRecapLabel(n){
  var v=parseInt(n,10); if(isNaN(v)||v<0) v=0;
  var map={0:'0 — Novo',1:'1 — Primeira',2:'2 — Segunda',3:'3 — Terceira',4:'4 — Quarta'};
  return map[v]||(v+'ª');
}
function pneusFogoValor(p){
  if(!p) return '';
  var f=String(p.numero_fogo||'').trim();
  if(f) return f;
  return String(p.codigo||'').trim();
}
function pneusProximoNumeroFogo(){
  var nums=[], ultimoTxt='', ultimoNum=-1;
  (pneus_dados||[]).forEach(function(p){
    var f=pneusFogoValor(p); if(!f) return;
    if(!ultimoTxt) ultimoTxt=f;
    var digits=f.replace(/\D/g,'');
    if(digits){
      var n=parseInt(digits,10);
      if(!isNaN(n)){
        nums.push(n);
        if(n>=ultimoNum){ ultimoNum=n; ultimoTxt=f; }
      }
    } else if(!nums.length && f>ultimoTxt){
      ultimoTxt=f;
    }
  });
  var proximo = nums.length ? (Math.max.apply(null, nums)+1) : 1;
  return { ultimo: ultimoTxt||'—', proximo: String(proximo), ultimoNum: ultimoNum };
}
function pneusValidarNumeroFogo(fogo, excludeId){
  var n=String(fogo||'').trim();
  if(!n) return {ok:false, msg:'Número de fogo é obrigatório.'};
  var hit=(pneus_dados||[]).find(function(p){
    if(excludeId && p.id===excludeId) return false;
    return String(p.numero_fogo||'').trim().toLowerCase()===n.toLowerCase()
        || (!p.numero_fogo && String(p.codigo||'').trim().toLowerCase()===n.toLowerCase());
  });
  if(hit) return {ok:false, msg:'Já existe pneu com número de fogo "'+n+'" (único no histórico, inclusive descartados).'};
  return {ok:true};
}
/** Fase 2 — item patrimonial de pneu (kill-switch: window._PNEUS_FASE2=false). */
function pneusEhItemPneu(it){
  if(window._PNEUS_FASE2===false) return false;
  if(!it) return false;
  if(it.eh_pneu===true) return true;
  return eeNormalizaTipo(it.tipo_item||it.tipo)==='pneu';
}
function pneusParseFogosTexto(txt){
  return String(txt||'').split(/[\n,;]+/).map(function(s){ return s.trim(); }).filter(Boolean);
}
function pneusValidarListaFogosEntrada(fogos, qtd){
  var list=(fogos||[]).map(function(f){ return String(f||'').trim(); }).filter(Boolean);
  var n=Math.max(1, parseInt(qtd,10)||0);
  if(list.length!==n) return {ok:false, msg:'Informe exatamente '+n+' número(s) de fogo (1 por unidade).'};
  var seen={};
  for(var i=0;i<list.length;i++){
    var k=list[i].toLowerCase();
    if(seen[k]) return {ok:false, msg:'Fogo duplicado na entrada: "'+list[i]+'"'};
    seen[k]=true;
  }
  return {ok:true, fogos:list};
}
function pneusBuscarPorFogoLocal(fogo){
  var n=String(fogo||'').trim().toLowerCase();
  if(!n) return null;
  return (pneus_dados||[]).find(function(p){
    return String(p.numero_fogo||'').trim().toLowerCase()===n
        || (!p.numero_fogo && String(p.codigo||'').trim().toLowerCase()===n);
  })||null;
}
async function pneusGarantirDadosCarregados(){
  if(DEMO) return true;
  if(window._pneusCacheOk && Array.isArray(pneus_dados) && pneus_dados.length) return true;
  try{
    var rows=await sbFetch('pneus',{order:'codigo',limit:5000});
    if(rows){ pneus_dados=rows; window._pneusCacheOk=true; }
  }catch(e){ console.warn('pneusGarantirDadosCarregados', e); }
  return true;
}
/** Após entrada Almox OK: cria ficha nova ou só vincula fogo existente (sem baixar saldo). */
async function pneusCriarDaEntradaAlmox(opts){
  opts=opts||{};
  var fogos=opts.fogos||[];
  var itemCat=opts.itemCat||null;
  var estoqueId=opts.estoqueId||null;
  var depositoId=opts.depositoId||null;
  var filialId=opts.filialId||null;
  var custo=opts.custo!=null?Number(opts.custo):null;
  if(!fogos.length) return {ok:false, msg:'Nenhum fogo informado'};
  await pneusGarantirDadosCarregados();
  var marca=(itemCat&&(itemCat.nome||'').trim())||'PNEU';
  var medida='A DEFINIR';
  var criados=0, vinculados=0, erros=[];
  for(var i=0;i<fogos.length;i++){
    var fogo=String(fogos[i]||'').trim();
    if(!fogo){ erros.push('Fogo vazio na posição '+(i+1)); continue; }
    var existente=pneusBuscarPorFogoLocal(fogo);
    if(existente){
      var patchVinculo={
        item_id: itemCat?itemCat.id:existente.item_id||null,
        estoque_id: estoqueId||existente.estoque_id||null,
        deposito_id: depositoId||existente.deposito_id||null,
        filial_id: filialId||existente.filial_id||null,
        atualizado_em: new Date().toISOString()
      };
      Object.assign(existente, patchVinculo);
      if(!DEMO){
        var okUp=await sbUpdate('pneus', patchVinculo, 'id=eq.'+existente.id);
        if(!okUp){ erros.push('Falha ao vincular fogo '+fogo+' ao Almox'); continue; }
      }
      vinculados++;
      continue;
    }
    var payload={
      numero_fogo:fogo,
      codigo:fogo,
      marca:marca,
      modelo:'',
      medida:medida,
      status:'estoque',
      item_id: itemCat?itemCat.id:null,
      estoque_id: estoqueId||null,
      deposito_id: depositoId||null,
      filial_id: filialId||null,
      recapagem_atual:0,
      recapagem_maxima:4,
      vida_util_km:80000,
      custo_compra: (custo!=null&&!isNaN(custo)&&custo>0)?custo:null,
      ativo:true,
      atualizado_em:new Date().toISOString()
    };
    if(DEMO){
      payload.id='pneu_'+Date.now()+'_'+i;
      pneus_dados.push(payload);
      pneus_vidas.push({pneu_id:payload.id,numero_vida:1,km_inicial:0,km_rodado:0,status:'ativa'});
      criados++;
      continue;
    }
    var ins=await sbInsert('pneus', _semId?_semId(payload):payload);
    if(!ins||!ins[0]){
      erros.push('Falha ao criar pneu fogo '+fogo+(ins===null?' (rede/unique?)':''));
      continue;
    }
    var row=Object.assign({}, payload, ins[0]);
    pneus_dados.push(row);
    var v1={pneu_id:row.id,numero_vida:1,km_inicial:0,km_rodado:0,status:'ativa'};
    pneus_vidas.push(v1);
    await sbInsert('pneus_vidas', v1);
    criados++;
  }
  if(erros.length && !criados && !vinculados) return {ok:false, msg:erros.join('; ')};
  return {ok:true, criados:criados, vinculados:vinculados, erros:erros};
}
function pneusRenderFogoCard(){
  var el=document.getElementById('pneu-fogo-card'); if(!el) return;
  var info=pneusProximoNumeroFogo();
  el.innerHTML='<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:.75rem">'
    +'<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.65rem .85rem">'
    +'<div style="font-size:10px;color:#888;font-weight:600;text-transform:uppercase;letter-spacing:.02em">Último nº de fogo utilizado</div>'
    +'<div style="font-size:22px;font-weight:700;font-family:monospace;color:#1a1a18;margin-top:2px">'+escHtml(info.ultimo)+'</div></div>'
    +'<div style="background:#EAF3DE;border:.5px solid #3B6D11;border-radius:10px;padding:.65rem .85rem">'
    +'<div style="font-size:10px;color:#3B6D11;font-weight:600;text-transform:uppercase;letter-spacing:.02em">Próximo número sugerido</div>'
    +'<div style="font-size:22px;font-weight:700;font-family:monospace;color:#3B6D11;margin-top:2px">'+escHtml(info.proximo)+'</div>'
    +'<div style="font-size:10px;color:#666;margin-top:2px">Sugestão — pode digitar outro se livre</div></div>'
    +'</div>';
}

function pneusInit(){
  if(!DEMO){
    Promise.all([
      sbFetch('pneus',{order:'codigo'}),
      sbFetch('pneus_vidas',{order:'pneu_id,numero_vida'}),
      sbFetch('pneus_posicoes'),
      sbFetch('pneus_movimentos',{order:'data_hora.desc',limit:500}),
      sbFetch('pneus_config_eixos'),
    ]).then(function(res){
      pneus_dados=res[0]||[]; pneus_vidas=res[1]||[];
      pneus_posicoes=res[2]||[]; pneus_movimentos=res[3]||[];
      window._pneusCacheOk=true;
      pneus_config_eixos={};
      (res[4]||[]).forEach(function(c){
        if(!c||!c.veiculo_id) return;
        if(!pneus_config_eixos[c.veiculo_id]) pneus_config_eixos[c.veiculo_id]=[];
        var arr=pneus_config_eixos[c.veiculo_id];
        var nEixo=parseInt(c.numero_eixo,10)||0;
        var ix=arr.findIndex(function(x){ return (parseInt(x.numero_eixo,10)||0)===nEixo; });
        // Mantém o registro mais recente se houver duplicata no banco
        if(ix>=0){
          var oldTs=String(arr[ix].atualizado_em||arr[ix].criado_em||arr[ix].id||'');
          var newTs=String(c.atualizado_em||c.criado_em||c.id||'');
          if(newTs>=oldTs) arr[ix]=c;
        } else {
          arr.push(c);
        }
      });
      Object.keys(pneus_config_eixos).forEach(function(vid){
        pneus_config_eixos[vid].sort(function(a,b){
          return (parseInt(a.numero_eixo,10)||0)-(parseInt(b.numero_eixo,10)||0);
        });
      });
      pneusRender();
    }).catch(function(){pneusRender();});
  } else { pneusRender(); }
}

function pneusAba(aba){
  _pneusAbaAtiva=aba;
  ['estoque','veiculos','movimentos','alertas','relatorios'].forEach(function(a){
    var b=document.getElementById('pneu-tab-'+a);
    if(b){b.style.background=a===aba?'#1a1a18':'';b.style.color=a===aba?'#fff':'';}
  });
  pneusRender();
}

function pneusRender(){
  pneusRenderFogoCard();
  pneusRenderMetricas();
  pneusRenderAlertasBanner();
  var div=document.getElementById('pneu-conteudo'); if(!div)return;
  if(_pneusAbaAtiva==='estoque')    pneusRenderEstoque(div);
  else if(_pneusAbaAtiva==='veiculos')   pneusRenderVeiculos(div);
  else if(_pneusAbaAtiva==='movimentos') pneusRenderMovimentos(div);
  else if(_pneusAbaAtiva==='alertas')    pneusRenderAlertasAba(div);
  else if(_pneusAbaAtiva==='relatorios') pneusRenderRelatorios(div);
}

function pneusRenderMetricas(){
  var el=document.getElementById('pneu-metricas'); if(!el)return;
  var t=pneus_dados.length;
  var u=pneus_dados.filter(function(p){return pneusNormStatus(p.status)==='em_uso';}).length;
  var s=pneus_dados.filter(function(p){var st=pneusNormStatus(p.status);return st==='estoque'||st==='novo'||st==='usado'||st==='recapado';}).length;
  var r=pneus_dados.filter(function(p){var st=pneusNormStatus(p.status);return st==='recapado'||st==='em_recapagem';}).length;
  var d=pneus_dados.filter(function(p){return pneusNormStatus(p.status)==='descartado';}).length;
  el.innerHTML=[{l:'Total',v:t,c:'#555'},{l:'Em uso',v:u,c:'#185FA5'},{l:'Disponíveis',v:s,c:'#3B6D11'},{l:'Ressol./Recap.',v:r,c:'#854F0B'},{l:'Descartado',v:d,c:'#A32D2D'}]
    .map(function(m){return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.6rem;text-align:center"><div style="font-size:11px;color:#888;margin-bottom:3px">'+m.l+'</div><div style="font-size:20px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';}).join('');
}

function pneusGetAlertas(){
  var list=[];
  pneus_dados.forEach(function(p){
    var vidas=pneus_vidas.filter(function(v){return v.pneu_id===p.id;});
    var va=vidas.find(function(v){return !v.km_final;});
    if(va&&(va.km_rodado||0)>(p.vida_util_km||80000)*0.9) list.push((pneusFogoValor(p)||p.codigo)+' — próximo do limite ('+va.km_rodado+' km)');
    if(pneusNormStatus(p.status)==='em_uso'&&!pneus_posicoes.find(function(po){return po.pneu_id===p.id;})) list.push((pneusFogoValor(p)||p.codigo)+' — em uso mas sem posição definida');
  });
  frt_veiculos.forEach(function(v){
    var cfg=pneus_config_eixos[v.id]; if(!cfg||!cfg.length)return;
    var totalPos=cfg.reduce(function(s,e){return s+(e.pneus_eixo||2);},0);
    var emPos=pneus_posicoes.filter(function(p){return p.veiculo_id===v.id;}).length;
    if(emPos<totalPos) list.push(v.placa+' — '+(totalPos-emPos)+' pneu(s) faltando no mapa');
  });
  return list;
}

function pneusRenderAlertasBanner(){
  var el=document.getElementById('pneu-alertas-banner'); if(!el)return;
  var al=pneusGetAlertas();
  if(!al.length){el.innerHTML='';return;}
  el.innerHTML='<div style="background:#FEF3E2;border:.5px solid #EF9F27;border-radius:10px;padding:.75rem 1rem;margin-bottom:.5rem">'
    +'<div style="font-size:12px;font-weight:700;color:#854F0B;margin-bottom:6px">⚠️ '+al.length+' alerta(s)</div>'
    +al.slice(0,3).map(function(a){return '<div style="font-size:11px;color:#854F0B">• '+a+'</div>';}).join('')
    +(al.length>3?'<div style="font-size:11px;color:#854F0B">+ '+(al.length-3)+' outros...</div>':'')
    +'</div>';
}

function pneusRenderEstoque(div){
  div.innerHTML='<div class="card">'
    +'<div class="ch" style="margin-bottom:.75rem">'
    +'<input class="inp" id="pneu-busca" placeholder="Buscar fogo, código, marca, série..." style="flex:1;max-width:320px" oninput="pneusFiltrarEstoque()"/>'
    +'<select class="inp" id="pneu-fil-status" style="width:180px" onchange="pneusFiltrarEstoque()">'
    +'<option value="">Todos os status</option>'
    +Object.keys(PNEU_STATUS).map(function(k){return '<option value="'+k+'">'+PNEU_STATUS[k].label+'</option>';}).join('')
    +'</select></div>'
    +'<div id="pneu-tabela-estoque"></div></div>';
  pneusFiltrarEstoque();
}

function pneusFiltrarEstoque(){
  var busca=((document.getElementById('pneu-busca')||{}).value||'').toLowerCase();
  var st=(document.getElementById('pneu-fil-status')||{}).value||'';
  var fil=pneus_dados.filter(function(p){
    var stN=pneusNormStatus(p.status);
    if(st && stN!==st && p.status!==st) return false;
    if(!busca) return true;
    var blob=[p.numero_fogo,p.codigo,p.marca,p.modelo,p.serie,p.medida,p.dot,p.calibracao].join(' ').toLowerCase();
    return blob.indexOf(busca)>=0;
  });
  var el=document.getElementById('pneu-tabela-estoque'); if(!el)return;
  if(!fil.length){el.innerHTML='<div style="padding:2rem;text-align:center;color:#aaa">Nenhum pneu encontrado</div>';return;}
  el.innerHTML='<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Nº fogo</th><th>Código</th><th>Marca/Modelo</th><th>Medida</th><th>Sulco</th><th>Recap.</th><th>Status</th><th>Posição</th><th></th></tr></thead><tbody>'
    +fil.map(function(p){
      var pos=pneus_posicoes.find(function(po){return po.pneu_id===p.id;});
      var veicPos=pos?((frt_veiculos.find(function(v){return v.id===pos.veiculo_id;})||{}).placa||'—')+' · '+(pos.descricao_posicao||'—'):'—';
      var s=pneusStatusMeta(p.status);
      var fogo=pneusFogoValor(p)||'—';
      var sulco=(p.mm_atual!=null&&p.mm_atual!=='')?(p.mm_atual+' mm'):'—';
      var badgeAlmox=p.item_id?' <span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:1px 5px;font-size:9px;font-weight:700;margin-left:4px">Almox</span>':'';
      return '<tr><td style="font-weight:700;font-size:12px;font-family:monospace">'+escHtml(fogo)+badgeAlmox+'</td>'
        +'<td style="font-size:11px;color:#888">'+escHtml(p.codigo||'—')+'</td>'
        +'<td><div style="font-size:12px;font-weight:600">'+escHtml(p.marca||'')+'</div><div style="font-size:10px;color:#888">'+escHtml(p.modelo||'')+'</div></td>'
        +'<td style="font-size:12px;font-weight:600">'+escHtml(p.medida||'—')+'</td>'
        +'<td style="font-size:12px">'+escHtml(sulco)+'</td>'
        +'<td style="font-size:11px">'+escHtml(pneusRecapLabel(p.recapagem_atual!=null?p.recapagem_atual:0))+'</td>'
        +'<td><span style="background:'+s.bg+';color:'+s.cor+';border-radius:4px;padding:2px 7px;font-size:10px;font-weight:600">'+s.label+'</span></td>'
        +'<td style="font-size:11px">'+escHtml(veicPos)+'</td>'
        +'<td style="display:flex;gap:4px"><button class="btn btn-sm" onclick="pneusVerPneu(\''+p.id+'\')">Ver</button>'
        +'<button class="btn btn-sm" onclick="pneusMover(\''+p.id+'\')">Mover</button></td></tr>';
    }).join('')+'</tbody></table></div>';
}

function pneusRenderVeiculos(div){
  div.innerHTML='<div style="display:grid;grid-template-columns:220px 1fr;gap:1rem">'
    +'<div class="card" style="padding:.5rem"><div style="font-size:11px;color:#888;font-weight:600;margin-bottom:.5rem">VEÍCULOS</div>'
    +frt_veiculos.map(function(v){
      var totalPos=(pneus_config_eixos[v.id]||[]).reduce(function(s,e){return s+(e.pneus_eixo||2);},0);
      var emPos=pneus_posicoes.filter(function(p){return p.veiculo_id===v.id;}).length;
      var cor=totalPos>0&&emPos>=totalPos?'#3B6D11':totalPos>0&&emPos>0?'#854F0B':'#aaa';
      return '<div onclick="pneusVerMapaVeiculo(\''+v.id+'\')" style="padding:.5rem .75rem;border-radius:8px;cursor:pointer;margin-bottom:4px;border:.5px solid #e0dfd8;background:#fff">'
        +'<div style="font-size:12px;font-weight:700">'+v.placa+'</div>'
        +'<div style="font-size:10px;color:#888">'+v.modelo+'</div>'
        +'<div style="font-size:10px;color:'+cor+'">'+(totalPos?emPos+'/'+totalPos+' pneus':'Sem config.')+'</div></div>';
    }).join('')
    +'</div><div id="pneu-mapa-conteudo"><div style="padding:2rem;text-align:center;color:#aaa">Selecione um veículo</div></div></div>';
}

function pneusVerMapaVeiculo(vId){
  var v=frt_veiculos.find(function(x){return x.id===vId;}); if(!v)return;
  var cfg=pneus_config_eixos[vId]||[];
  var div=document.getElementById('pneu-mapa-conteudo'); if(!div)return;

  if(!cfg.length){
    div.innerHTML='<div class="card"><div class="ch" style="margin-bottom:1rem">'
      +'<div><div style="font-size:15px;font-weight:700">'+v.placa+'</div><div style="font-size:11px;color:#888">'+v.modelo+'</div></div>'
      +'<button class="btn btn-sm btn-pri" onclick="pneusConfigurarEixos(\''+vId+'\')">Configurar eixos</button></div>'
      +'<div style="background:#FFF3E0;border:.5px solid #EF9F27;border-radius:8px;padding:1rem;text-align:center;font-size:12px;color:#854F0B">'
      +'Configure os eixos para ver o mapa visual.</div></div>';
    return;
  }

  var totalPos=cfg.reduce(function(s,e){return s+(e.pneus_eixo||2);},0);
  var emPos=pneus_posicoes.filter(function(p){return p.veiculo_id===vId;}).length;

  var mapaHtml='<div style="display:flex;flex-direction:column;gap:12px">';
  cfg.sort(function(a,b){return a.numero_eixo-b.numero_eixo;}).forEach(function(eixo){
    var isDupla=!!eixo.rodagem_dupla;
    var posicoes=pneusGetPosicoesEixo(vId,eixo.numero_eixo,eixo.pneus_eixo||2,isDupla);
    var esqPos=posicoes.filter(function(p){return p.lado==='esq'||p.lado==='centro';});
    var dirPos=posicoes.filter(function(p){return p.lado==='dir';});

    function renderTire(pos){
      var posReg=pneus_posicoes.find(function(po){return po.veiculo_id===vId&&po.eixo===eixo.numero_eixo&&po.posicao===pos.posicao;});
      var pneu=posReg?pneus_dados.find(function(p){return p.id===posReg.pneu_id;}):null;
      var vidas=pneu?pneus_vidas.filter(function(vd){return vd.pneu_id===pneu.id;}):[];
      var va=pneu?(vidas.find(function(vd){return !vd.km_final;})||{}):null;
      var isAlerta=pneu&&va&&(va.km_rodado||0)>(pneu.vida_util_km||80000)*0.9;
      var cor=pneu?(isAlerta?'#854F0B':'#3B6D11'):'#bbb';
      var bg=pneu?(isAlerta?'#FEF3E2':'#EAF3DE'):'var(--color-background-secondary)';
      var w=isDupla?'36px':'50px'; var h=isDupla?'56px':'70px';
      var onclick=pneu?'pneusVerPneu(\''+pneu.id+'\')':'pneusInstalarPosicao(\''+vId+'\','+eixo.numero_eixo+','+pos.posicao+')';
      return '<div style="text-align:center">'
        +'<div style="font-size:7px;color:#888;margin-bottom:1px;white-space:nowrap">'+pos.label.replace('Esq. ','').replace('Dir. ','')+'</div>'
        +'<div onclick="'+onclick+'" style="width:'+w+';height:'+h+';border-radius:6px;border:2.5px solid '+cor+';background:'+bg
        +';display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;margin:0 auto">'
        +(pneu
          ?'<div style="font-size:8px;font-weight:700;color:'+cor+'">'+pneu.codigo+'</div>'
           +(isDupla?'':'<div style="font-size:7px;color:#555">'+((pneu.medida||'').split('/')[0])+'</div>')
           +'<div style="font-size:7px;color:#888">'+(vidas.length||1)+'a</div>'
           +(isAlerta?'<div style="font-size:10px;color:#854F0B;font-weight:700">!</div>':'')
          :'<div style="font-size:16px;color:#ccc">+</div>')
        +'</div></div>';
    }

    var esqHtml='<div style="display:flex;flex-direction:'+(isDupla?'row':'column')+';gap:3px;align-items:flex-end">'
      +esqPos.map(renderTire).join('')+'</div>';
    var dirHtml=dirPos.length?'<div style="display:flex;flex-direction:'+(isDupla?'row':'column')+';gap:3px;align-items:flex-end">'
      +dirPos.map(renderTire).join('')+'</div>':'';

    mapaHtml+='<div style="background:var(--color-background-secondary);border-radius:10px;padding:.75rem">'
      +'<div style="font-size:10px;font-weight:700;color:#555;margin-bottom:8px;text-align:center">'
      +'Eixo '+eixo.numero_eixo+' - '+eixo.descricao_eixo
      +(isDupla?' <span style="background:#E6F1FB;color:#185FA5;font-size:8px;padding:1px 5px;border-radius:3px">Dupla</span>':'')
      +'</div>'
      +'<div style="display:flex;align-items:center;justify-content:center;gap:6px">'
      +esqHtml
      +'<div style="display:flex;flex-direction:column;align-items:center;gap:2px">'
      +'<div style="width:'+(isDupla?50:60)+'px;height:3px;background:var(--color-border-secondary);border-radius:2px"></div>'
      +'<div style="width:10px;background:#888;border-radius:4px;height:'+(isDupla?60:50)+'px"></div>'
      +'<div style="width:'+(isDupla?50:60)+'px;height:3px;background:var(--color-border-secondary);border-radius:2px"></div>'
      +'</div>'
      +dirHtml
      +'</div>'
      +(eixo.tem_estepe?'<div style="text-align:center;margin-top:8px">'
        +'<div style="font-size:7px;color:#888;margin-bottom:2px">ESTEPE</div>'
        +'<div style="width:38px;height:38px;border-radius:50%;border:2px dashed #888;background:var(--color-background-primary);display:flex;align-items:center;justify-content:center;margin:0 auto;font-size:8px;color:#888;cursor:pointer">EST</div></div>'
        :'')
      +'</div>';
  mapaHtml+="</div>";
  });

  var verifHtml="<div style=\"display:flex;flex-direction:column;gap:8px\">";
  pneus_posicoes.filter(function(po){return po.veiculo_id===vId;}).forEach(function(po){
    var pneu=pneus_dados.find(function(p){return p.id===po.pneu_id;})||{codigo:"---",status:"---"};
    var vidas=pneus_vidas.filter(function(vd){return vd.pneu_id===pneu.id;});
    var va=vidas.find(function(vd){return !vd.km_final;})||{};
    var isAlerta=(va.km_rodado||0)>(pneu.vida_util_km||80000)*0.9;
    verifHtml+="<div id=\"vfitem-"+po.id+"\" onclick=\"pneuToggleVerif(\'"+po.id+"\')\""
      +" style=\"display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:8px;cursor:pointer;"
      +"border:.5px solid "+(isAlerta?"#854F0B":"var(--color-border-tertiary)")
      +";background:"+(isAlerta?"#FEF3E222":"var(--color-background-primary)")+"\">"
      +"<div style=\"width:32px;height:32px;border-radius:50%;background:"+(isAlerta?"#FEF3E2":"var(--color-background-secondary)")
      +";display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:"+(isAlerta?"#854F0B":"#555")+"\">"
      +(isAlerta?"!":pneu.codigo.slice(-2))+"</div>"
      +"<div style=\"flex:1\"><div style=\"font-size:12px;font-weight:500\">"+po.descricao_posicao+"</div>"
      +"<div style=\"font-size:10px;color:"+(isAlerta?"#854F0B":"#888")+"\">"
      +pneu.codigo+(isAlerta?" - Proximo do limite!":"")+"</div></div>"
      +"<div id=\"vfck-"+po.id+"\" style=\"font-size:20px;color:var(--color-border-secondary)\">O</div>"
      +"</div>";
  });
  verifHtml+="</div>"
    +"<button onclick=\"pneuFinalizarVerif(\'"+vId+"\')\""
    +" style=\"width:100%;padding:11px;background:#1a1a18;color:#fff;border:none;border-radius:8px;margin-top:12px;font-size:13px;cursor:pointer\">Confirmar verificacao</button>";

  div.innerHTML="<div class=\"card\">"
    +"<div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem\">"
    +"<div><div style=\"font-size:15px;font-weight:700\">"+v.placa+"</div><div style=\"font-size:11px;color:#888\">"+v.modelo+" - "+v.marca+"</div></div>"
    +"<div style=\"display:flex;gap:6px;align-items:center\">"
    +"<span style=\"background:#EAF3DE;color:#3B6D11;font-size:10px;font-weight:700;padding:2px 8px;border-radius:4px\">"+emPos+"/"+totalPos+"</span>"
    +"<button class=\"btn btn-sm\" onclick=\"pneusConfigurarEixos(\'"+vId+"\')\">Eixos</button></div></div>"
    +"<div style=\"display:flex;border-bottom:.5px solid var(--color-border-tertiary);margin-bottom:.75rem\">"
    +"<div id=\"pm-tab-mapa-"+vId+"\" onclick=\"pneusMapaAba(\'"+vId+"\',\'mapa\')\" style=\"flex:1;padding:8px 4px;font-size:12px;text-align:center;cursor:pointer;border-bottom:2px solid #185FA5;color:#185FA5;font-weight:500\">Mapa Visual</div>"
    +"<div id=\"pm-tab-verif-"+vId+"\" onclick=\"pneusMapaAba(\'"+vId+"\',\'verif\')\" style=\"flex:1;padding:8px 4px;font-size:12px;text-align:center;cursor:pointer;color:#888;border-bottom:2px solid transparent\">Verificar</div>"
    +"</div>"
    +"<div id=\"pm-mapa-"+vId+"\">"+mapaHtml+"</div>"
    +"<div id=\"pm-verif-"+vId+"\" style=\"display:none\">"+verifHtml+"</div>"
    +"</div>";
}

function pneuToggleVerif(poId){
  var el=document.getElementById("vfitem-"+poId);
  var ck=document.getElementById("vfck-"+poId);
  if(!el||!ck)return;
  var done=el.dataset.done==="1";
  el.dataset.done=done?"0":"1";
  if(!done){ck.textContent="v";ck.style.color="#3B6D11";}
  else{ck.textContent="O";ck.style.color="var(--color-border-secondary)";}
}

function pneusMapaAba(vId,aba){
  var dm=document.getElementById("pm-mapa-"+vId);
  var dv=document.getElementById("pm-verif-"+vId);
  var tm=document.getElementById("pm-tab-mapa-"+vId);
  var tv=document.getElementById("pm-tab-verif-"+vId);
  if(!dm||!dv)return;
  if(aba==="mapa"){
    dm.style.display=""; dv.style.display="none";
    tm.style.borderBottomColor="#185FA5"; tm.style.color="#185FA5"; tm.style.fontWeight="500";
    tv.style.borderBottomColor="transparent"; tv.style.color="#888"; tv.style.fontWeight="400";
  } else {
    dm.style.display="none"; dv.style.display="";
    tv.style.borderBottomColor="#185FA5"; tv.style.color="#185FA5"; tv.style.fontWeight="500";
    tm.style.borderBottomColor="transparent"; tm.style.color="#888"; tm.style.fontWeight="400";
  }
}

function pneuFinalizarVerif(vId){
  var items=document.querySelectorAll("[data-done]");
  var done=[].filter.call(items,function(i){return i.dataset.done==="1";}).length;
  progShowToast("Verificacao registrada: "+done+" pneus conferidos");
}

function pneusGetPosicoesEixo(vId, numEixo, pneusEixo, rodagemDupla){
  // rodagemDupla: true = 2 pneus por lado (interno + externo)
  if(rodagemDupla){
    return [
      {posicao:1, lado:'esq', camada:'ext', label:'Esq. Externo'},
      {posicao:2, lado:'esq', camada:'int', label:'Esq. Interno'},
      {posicao:3, lado:'dir', camada:'int', label:'Dir. Interno'},
      {posicao:4, lado:'dir', camada:'ext', label:'Dir. Externo'},
    ];
  }
  // Simples: 1 pneu por lado
  if(pneusEixo===1){
    return [{posicao:1, lado:'centro', camada:'ext', label:'Central'}];
  }
  return [
    {posicao:1, lado:'esq', camada:'ext', label:'Esquerdo'},
    {posicao:2, lado:'dir', camada:'ext', label:'Direito'},
  ];
}

function pneusRenderMovimentos(div){
  div.innerHTML='<div class="card"><div class="ch" style="margin-bottom:.75rem">'
    +'<span class="ct">Histórico de Movimentações</span>'
    +'<button class="btn btn-pri" onclick="pneusNovaMovimentacao()">+ Nova movimentação</button></div>'
    +(pneus_movimentos.length?'<div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Data</th><th>Pneu</th><th>Tipo</th><th>Veículo</th><th>KM</th><th>Responsável</th></tr></thead><tbody>'
      +pneus_movimentos.slice(0,100).map(function(m){
        var p=pneus_dados.find(function(x){return x.id===m.pneu_id;})||{codigo:'—'};
        var v=frt_veiculos.find(function(x){return x.id===m.veiculo_id;})||{placa:'—'};
        return '<tr><td style="font-size:11px">'+fmtD(m.data_hora&&m.data_hora.split('T')[0])+'</td><td style="font-weight:600">'+p.codigo+'</td><td>'+m.tipo+'</td><td>'+v.placa+'</td><td style="text-align:right">'+((m.km_evento||0).toLocaleString('pt-BR'))+'</td><td style="font-size:11px;color:#888">'+m.responsavel+'</td></tr>';
      }).join('')+'</tbody></table></div>'
    :'<div style="padding:2rem;text-align:center;color:#aaa">Nenhuma movimentação</div>')+'</div>';
}

function pneusRenderAlertasAba(div){
  var al=pneusGetAlertas();
  div.innerHTML='<div class="card"><div class="ct" style="margin-bottom:1rem">⚠️ Alertas</div>'
    +(al.length?al.map(function(a){return '<div style="display:flex;gap:10px;padding:.6rem .75rem;border-bottom:.5px solid #f5f5f3"><span style="color:#854F0B">⚠️</span><span style="font-size:13px">'+a+'</span></div>';}).join('')
    :'<div style="padding:2rem;text-align:center;color:#3B6D11">✅ Sem alertas</div>')+'</div>';
}

function pneusRenderRelatorios(div){
  div.innerHTML='<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:1rem">'
    +['Pneus por veículo','Pneus em estoque','Pneus descartados','Custo por pneu','Custo por km rodado','Histórico de rodízios','Vida útil média por marca','Próximos do limite','Vidas por resolagem']
    .map(function(r){return '<div class="card" style="cursor:pointer;text-align:center;padding:1.5rem" onclick="progShowToast(\'📊 '+r+' — em breve\')">'
      +'<div style="font-size:24px;margin-bottom:.5rem">📄</div><div style="font-size:13px;font-weight:600">'+r+'</div></div>';}).join('')+'</div>';
}

function pneusNovoPneu(pneuId){
  var p=pneuId?pneus_dados.find(function(x){return x.id===pneuId;})||{}:{};
  var sug=pneusProximoNumeroFogo();
  var fogoIni=p.numero_fogo||(!pneuId?sug.proximo:'')||'';
  var stSel=pneusNormStatus(p.status||(!pneuId?'novo':'estoque'));
  var pos=pneuId?pneus_posicoes.find(function(po){return po.pneu_id===pneuId;}):null;
  var veic=pos?frt_veiculos.find(function(v){return v.id===pos.veiculo_id;}):null;
  var recapOpts=[0,1,2,3,4].map(function(n){
    var sel=(parseInt(p.recapagem_atual,10)||0)===n?' selected':'';
    return '<option value="'+n+'"'+sel+'>'+pneusRecapLabel(n)+'</option>';
  }).join('');
  var statusOpts=Object.keys(PNEU_STATUS).map(function(k){
    return '<option value="'+k+'"'+(stSel===k?' selected':'')+'>'+PNEU_STATUS[k].label+'</option>';
  }).join('');
  var itensPneu=(itens_catalogo||[]).filter(function(i){ return pneusEhItemPneu(i) && i.ativo!==false; });
  var catOpts='<option value="">— Sem vínculo Almox —</option>'
    +itensPneu.map(function(i){
      return '<option value="'+i.id+'"'+(String(p.item_id||'')===String(i.id)?' selected':'')+'>'
        +escHtml((i.codigo?i.codigo+' — ':'')+(i.nome||''))+'</option>';
    }).join('');
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:640px;max-height:90vh;overflow-y:auto">'
    +'<h3 style="margin-bottom:.5rem">'+(pneuId?'✏️ Editar':'+ Cadastrar')+' Pneu</h3>'
    +(!pneuId?'<div style="font-size:11px;color:#3B6D11;background:#EAF3DE;border-radius:6px;padding:.4rem .6rem;margin-bottom:.75rem">Sugestão nº fogo: <b style="font-family:monospace">'+escHtml(sug.proximo)+'</b> · último: '+escHtml(sug.ultimo)+'</div>':'')
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem">'
    +'<div class="fg"><label>Número de fogo *</label><input class="inp" id="pn-fogo" value="'+escHtml(fogoIni)+'" style="width:100%;font-family:monospace;font-weight:700" placeholder="Obrigatório"/></div>'
    +'<div class="fg"><label>Código (legado)</label><input class="inp" id="pn-codigo" value="'+escHtml(p.codigo||'')+'" style="width:100%"/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Item Almox (opcional)</label><select class="inp" id="pn-item-id" style="width:100%" data-nosort="1">'+catOpts+'</select>'
    +'<div style="font-size:10px;color:#888;margin-top:2px">Vínculo ao catálogo PNEU — não cria saldo; saldo vem da entrada no Almox.</div></div>'
    +'<div class="fg"><label>Marca *</label><input class="inp" id="pn-marca" value="'+escHtml(p.marca||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Medida *</label><input class="inp" id="pn-medida" placeholder="295/80R22.5" value="'+escHtml(p.medida||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Modelo</label><input class="inp" id="pn-modelo" value="'+escHtml(p.modelo||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>DOT</label><input class="inp" id="pn-dot" placeholder="Ex: 4821" value="'+escHtml(p.dot||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Calibração</label><input class="inp" id="pn-calibracao" value="'+escHtml(p.calibracao||'')+'" placeholder="Ex: 110 psi" style="width:100%"/></div>'
    +'<div class="fg"><label>Nº de série</label><input class="inp" id="pn-serie" value="'+escHtml(p.serie||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>MM sulco de fábrica</label><input class="inp" id="pn-sulco-fab" type="number" step="0.1" value="'+(p.mm_sulco_fabrica!=null?p.mm_sulco_fabrica:'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>MM atual</label><input class="inp" id="pn-sulco-atual" type="number" step="0.1" value="'+(p.mm_atual!=null?p.mm_atual:'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Status</label><select class="inp" id="pn-status" style="width:100%">'+statusOpts+'</select></div>'
    +'<div class="fg"><label>Recapagem atual</label><select class="inp" id="pn-recap-atual" style="width:100%">'+recapOpts+'</select></div>'
    +'<div class="fg"><label>Recapagem máxima</label><input class="inp" id="pn-recap-max" type="number" min="0" max="10" value="'+(p.recapagem_maxima!=null?p.recapagem_maxima:4)+'" style="width:100%"/></div>'
    +'<div class="fg"><label>KM do cadastro</label><input class="inp" id="pn-km-cad" type="number" value="'+(p.km_cadastro!=null?p.km_cadastro:'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Data de compra</label><input class="inp" id="pn-compra" type="date" value="'+(p.data_compra||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Vida útil estimada (km)</label><input class="inp" id="pn-vida-util" type="number" value="'+(p.vida_util_km||80000)+'" style="width:100%"/></div>'
    +'<div class="fg"><label>Custo de compra (R$)</label><input class="inp" id="pn-custo" type="number" step="0.01" value="'+(p.custo_compra||'')+'" style="width:100%"/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Observação técnica</label><textarea class="inp" id="pn-obs-tec" style="width:100%;height:55px">'+escHtml(p.observacao_tecnica||'')+'</textarea></div>'
    +'</div>'
    +(pos?'<div style="margin-top:.85rem;background:#E6F1FB;border-radius:8px;padding:.65rem .75rem">'
      +'<div style="font-size:11px;font-weight:600;color:#185FA5;margin-bottom:.4rem">📍 Instalado no veículo (somente leitura)</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;font-size:12px">'
      +'<div><div style="font-size:10px;color:#888">Placa / Veículo</div><div style="font-weight:600">'+escHtml(veic?((veic.placa||'')+' — '+(veic.modelo||'')):'—')+'</div></div>'
      +'<div><div style="font-size:10px;color:#888">Posição</div><div style="font-weight:600">'+escHtml(pos.descricao_posicao||'—')+'</div></div>'
      +'<div><div style="font-size:10px;color:#888">KM instalação</div><div style="font-weight:600">'+(pos.km_instalacao!=null?pos.km_instalacao:(p.km_instalacao!=null?p.km_instalacao:'—'))+'</div></div>'
      +'</div></div>':'')
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="pneusSalvar(\''+(pneuId||'')+'\')">💾 Salvar</button></div></div></div>');
}

function pneusSalvar(pneuId){
  var g=function(id){return((document.getElementById(id)||{}).value||'').trim();};
  var fogo=g('pn-fogo');
  var val=pneusValidarNumeroFogo(fogo, pneuId||null);
  if(!val.ok){ alert(val.msg); return; }
  if(!g('pn-marca')||!g('pn-medida')){ alert('Preencha: Marca e Medida'); return; }
  var codigo=g('pn-codigo')||fogo;
  var prev=pneuId?pneus_dados.find(function(x){return x.id===pneuId;}):null;
  var fogoAnt=prev?String(prev.numero_fogo||'').trim():'';
  var num=function(id){ var v=g(id); return v===''?null:(parseFloat(v.replace(',','.'))||null); };
  var itemAlmox=g('pn-item-id')||null;
  var payload={
    numero_fogo:fogo,
    codigo:codigo,
    marca:g('pn-marca'),
    modelo:g('pn-modelo'),
    medida:g('pn-medida'),
    serie:g('pn-serie'),
    dot:g('pn-dot'),
    calibracao:g('pn-calibracao')||null,
    mm_sulco_fabrica:num('pn-sulco-fab'),
    mm_atual:num('pn-sulco-atual'),
    status:pneusNormStatus(g('pn-status')||'novo'),
    recapagem_atual:parseInt(g('pn-recap-atual'),10)||0,
    recapagem_maxima:parseInt(g('pn-recap-max'),10)||4,
    km_cadastro:num('pn-km-cad'),
    observacao_tecnica:g('pn-obs-tec')||null,
    data_compra:g('pn-compra')||null,
    vida_util_km:parseInt(g('pn-vida-util'),10)||80000,
    custo_compra:parseFloat(g('pn-custo'))||null,
    item_id:itemAlmox||null,
    ativo:true,
    atualizado_em:new Date().toISOString()
  };
  if(payload.recapagem_atual>payload.recapagem_maxima){
    alert('Recapagem atual não pode ultrapassar a máxima ('+payload.recapagem_maxima+').');
    return;
  }
  var afterOk=function(){
    closeModal(); pneusRender();
    progShowToast('✅ Pneu '+(pneuId?'atualizado':'cadastrado')+' — fogo '+fogo);
  };
  if(pneuId){
    var idx=pneus_dados.findIndex(function(p){return p.id===pneuId;});
    if(idx>=0) Object.assign(pneus_dados[idx],payload);
    var histPromise=Promise.resolve();
    if(fogoAnt && fogoAnt!==fogo){
      var mov={id:'mov_'+Date.now(),pneu_id:pneuId,tipo:'Alteração cadastro',veiculo_id:null,
        km_evento:0,responsavel:usuarioLogado?usuarioLogado.nome:'Sistema',
        observacao:'Número de fogo: '+fogoAnt+' → '+fogo,data_hora:new Date().toISOString()};
      pneus_movimentos.unshift(mov);
      if(!DEMO) histPromise=sbInsert('pneus_movimentos',mov).then(function(){return null;});
    }
    if(!DEMO){
      sbUpdate('pneus',payload,'id=eq.'+pneuId).then(function(ok){
        if(!ok){
          progShowToast('⚠ Erro ao salvar. Rode sql_frotas_pneus_fase1.sql se faltarem colunas.','erro');
          return;
        }
        return histPromise.then(afterOk);
      });
    } else afterOk();
  } else {
    payload.id='pneu_'+Date.now();
    pneus_dados.push(payload);
    if(!DEMO){
      sbInsert('pneus',_semId?_semId(payload):payload).then(function(r){
        if(r&&r[0]&&r[0].id) payload.id=r[0].id;
        else if(!r){
          progShowToast('⚠ Erro ao criar. Rode sql_frotas_pneus_fase1.sql (e verifique duplicidade de fogo).','erro');
          pneus_dados=pneus_dados.filter(function(x){return x!==payload;});
          return;
        }
        var v1={pneu_id:payload.id,numero_vida:1,km_inicial:0,km_rodado:0,status:'ativa'};
        pneus_vidas.push(v1);
        sbInsert('pneus_vidas',v1);
        afterOk();
      });
    } else {
      var v1d={pneu_id:payload.id,numero_vida:1,km_inicial:0,km_rodado:0,status:'ativa'};
      pneus_vidas.push(v1d);
      afterOk();
    }
  }
}

function pneusVerPneu(pneuId){
  var p=pneus_dados.find(function(x){return x.id===pneuId;}); if(!p)return;
  var vidas=pneus_vidas.filter(function(v){return v.pneu_id===pneuId;});
  var movs=pneus_movimentos.filter(function(m){return m.pneu_id===pneuId;});
  var pos=pneus_posicoes.find(function(po){return po.pneu_id===pneuId;});
  var veic=pos?frt_veiculos.find(function(v){return v.id===pos.veiculo_id;}):null;
  var km=vidas.reduce(function(s,v){return s+(v.km_rodado||0);},0);
  var s=pneusStatusMeta(p.status);
  var fogo=pneusFogoValor(p)||'—';
  var catAlm=p.item_id?(itens_catalogo||[]).find(function(x){return String(x.id)===String(p.item_id);}):null;
  var depAlm=p.deposito_id?(typeof depositos!=='undefined'?depositos:[]).find(function(d){return String(d.id)===String(p.deposito_id);}):null;
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:560px;max-height:90vh;overflow-y:auto">'
    +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:1rem">'
    +'<div><h3 style="margin:0">⚫ Fogo '+escHtml(fogo)+(p.item_id?' <span style="background:#E6F1FB;color:#185FA5;border-radius:4px;padding:2px 6px;font-size:10px;font-weight:700;vertical-align:middle">Almox</span>':'')+'</h3>'
    +'<div style="font-size:12px;color:#888">'+escHtml((p.marca||'')+' '+(p.modelo||'')+' · '+(p.medida||''))+'</div>'
    +'<div style="font-size:11px;color:#888">Código: '+escHtml(p.codigo||'—')+' · DOT: '+escHtml(p.dot||'—')+' · Calibração: '+escHtml(p.calibracao||'—')+'</div></div>'
    +'<span style="background:'+s.bg+';color:'+s.cor+';font-size:10px;font-weight:700;padding:3px 8px;border-radius:4px">'+s.label+'</span></div>'
    +(p.item_id?'<div style="background:#F0F7FF;border:.5px solid #B5D4F4;border-radius:8px;padding:.55rem .75rem;margin-bottom:.75rem;font-size:11px">'
      +'<b style="color:#185FA5">Vínculo Almox</b> — catálogo: '+escHtml(catAlm?(catAlm.nome||'—'):'—')
      +(depAlm?' · depósito: '+escHtml(depAlm.nome||depAlm.codigo||'—'):'')
      +(p.estoque_id?' · estoque_id: '+escHtml(String(p.estoque_id).slice(0,8))+'…':'')
      +'</div>':'')
    +'<div style="background:#E6F1FB;border-radius:8px;padding:.6rem .9rem;margin-bottom:1rem;font-size:12px">'
    +'📍 '+(veic?escHtml(veic.placa)+' · '+escHtml(pos.descricao_posicao||'—')+(pos.km_instalacao!=null?' · KM inst. '+pos.km_instalacao:''):'Sem posição / Estoque')+'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:1rem">'
    +[{l:'Sulco atual',v:(p.mm_atual!=null?p.mm_atual+' mm':'—')},
      {l:'Sulco fábrica',v:(p.mm_sulco_fabrica!=null?p.mm_sulco_fabrica+' mm':'—')},
      {l:'Recapagem',v:pneusRecapLabel(p.recapagem_atual!=null?p.recapagem_atual:0)+' / máx '+(p.recapagem_maxima!=null?p.recapagem_maxima:4)},
      {l:'KM total',v:km.toLocaleString('pt-BR')}]
    .map(function(m){return '<div style="background:#f9f9f7;border-radius:8px;padding:.5rem;text-align:center"><div style="font-size:10px;color:#888">'+m.l+'</div><div style="font-size:13px;font-weight:700">'+m.v+'</div></div>';}).join('')+'</div>'
    +(p.observacao_tecnica?'<div style="font-size:12px;margin-bottom:1rem;background:#f9f9f7;border-radius:8px;padding:.5rem .75rem"><b>Obs. técnica:</b> '+escHtml(p.observacao_tecnica)+'</div>':'')
    +'<div style="font-size:12px;font-weight:600;color:#555;margin-bottom:.5rem">Histórico por vida</div>'
    +vidas.map(function(v){
      return '<div style="border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .75rem;margin-bottom:.5rem">'
        +'<div style="display:flex;justify-content:space-between"><span style="font-weight:700;font-size:12px">'+v.numero_vida+'ª vida</span>'
        +'<span style="font-size:11px;color:#888">'+(v.km_rodado||0).toLocaleString('pt-BR')+' km</span></div>'
        +'<div style="font-size:10px;color:#888;margin-top:3px">KM ini: '+(v.km_inicial||0).toLocaleString('pt-BR')
        +(v.km_final?' · KM fim: '+v.km_final.toLocaleString('pt-BR'):'')
        +(v.motivo_retirada?' · '+v.motivo_retirada:'')+'</div></div>';
    }).join('')
    +(movs.length?'<div style="font-size:12px;font-weight:600;color:#555;margin:.75rem 0 .5rem">Movimentações</div>'
      +movs.slice(0,8).map(function(m){return '<div style="display:flex;gap:8px;font-size:11px;padding:4px 0;border-bottom:.5px solid #f5f5f3"><span style="color:#888;width:80px;flex-shrink:0">'+fmtD(m.data_hora&&m.data_hora.split('T')[0])+'</span><span>'+escHtml(m.tipo)+'</span><span style="color:#888;margin-left:auto">'+escHtml(m.responsavel||'')+'</span></div>';}).join(''):'')
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Fechar</button>'
    +'<button class="btn" onclick="closeModal();pneusNovoPneu(\''+pneuId+'\')">✏️ Editar</button>'
    +'<button class="btn btn-pri" onclick="closeModal();pneusMover(\''+pneuId+'\')">🔄 Movimentar</button></div></div></div>');
}

function pneusMover(pneuId){
  var p=pneuId?pneus_dados.find(function(x){return x.id===pneuId;}):null;
  var lbl=p?(pneusFogoValor(p)||p.codigo):'';
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:440px">'
    +'<h3 style="margin-bottom:1rem">🔄 Movimentar Pneu'+(p?' — '+escHtml(lbl):'')+'</h3>'
    +(pneuId?'':'<div class="fg"><label>Pneu *</label><select class="inp" id="pmov-pneu" style="width:100%"><option value="">Selecione...</option>'+pneus_dados.map(function(x){return '<option value="'+x.id+'">'+escHtml(pneusFogoValor(x)||x.codigo)+' — '+escHtml(x.marca||'')+' '+escHtml(x.medida||'')+'</option>';}).join('')+'</select></div>')
    +'<div class="fg"><label>Tipo *</label><select class="inp" id="pmov-tipo" style="width:100%">'+PNEU_MOVIMENTOS.filter(function(m){return m!=='Alteração cadastro';}).map(function(m){return '<option>'+m+'</option>';}).join('')+'</select></div>'
    +'<div class="fg"><label>Veículo</label><select class="inp" id="pmov-veic" style="width:100%"><option value="">— Estoque —</option>'+frt_veiculos.map(function(v){return '<option value="'+v.id+'">'+v.placa+' — '+v.modelo+'</option>';}).join('')+'</select></div>'
    +'<div class="fg"><label>KM do evento</label><input class="inp" id="pmov-km" type="number" style="width:100%"/></div>'
    +'<div class="fg"><label>Responsável</label><input class="inp" id="pmov-resp" value="'+(usuarioLogado?usuarioLogado.nome:'')+'" style="width:100%"/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label>Observação</label><textarea class="inp" id="pmov-obs" style="width:100%;height:60px"></textarea></div>'
    +'<div class="ma" style="margin-top:1rem"><button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="pneusConfirmarMovimento(\''+( pneuId||'')+'\')">✓ Confirmar</button></div></div></div>');
}

function pneusNovaMovimentacao(){ pneusMover(null); }

function pneusConfirmarMovimento(pneuId){
  var g=function(id){return((document.getElementById(id)||{}).value||'').trim();};
  var pid=pneuId||g('pmov-pneu'); if(!pid){alert('Selecione o pneu');return;}
  var tipo=g('pmov-tipo'); if(!tipo)return;
  var mov={id:'mov_'+Date.now(),pneu_id:pid,tipo:tipo,veiculo_id:g('pmov-veic')||null,
    km_evento:parseInt(g('pmov-km'))||0,responsavel:g('pmov-resp'),observacao:g('pmov-obs'),data_hora:new Date().toISOString()};
  pneus_movimentos.unshift(mov);
  var p=pneus_dados.find(function(x){return x.id===pid;});
  if(p){
    if(tipo==='Instalação') p.status='em_uso';
    else if(tipo==='Descarte') p.status='descartado';
    else if(tipo==='Envio para recapagem') p.status='em_recapagem';
    else if(tipo==='Retorno de recapagem') p.status='recapado';
    else if(tipo==='Retorno para estoque'||tipo==='Remoção') p.status='estoque';
    if(!DEMO) sbUpdate('pneus',{status:p.status,atualizado_em:new Date().toISOString()},'id=eq.'+pid);
  }
  if(!DEMO) sbInsert('pneus_movimentos',mov);
  closeModal(); pneusRender();
  progShowToast('✅ Movimentação registrada');
}

function pneusConfigurarEixos(vId){
  var v=frt_veiculos.find(function(x){return x.id===vId;}); if(!v)return;
  var cfg=(pneus_config_eixos[vId]||[]).slice().sort(function(a,b){
    return (parseInt(a.numero_eixo,10)||0)-(parseInt(b.numero_eixo,10)||0);
  });
  // Usa o maior numero_eixo (não o length — evita “monte de eixos” por duplicatas no banco)
  var qtd=cfg.reduce(function(m,c){ return Math.max(m, parseInt(c.numero_eixo,10)||0); }, 0) || 2;
  if(qtd>7) qtd=7;

  function renderEixosForm(){
    var rows='';
    for(var i=1;i<=qtd;i++){
      var e=cfg.find(function(c){return (parseInt(c.numero_eixo,10)||0)===i;})||{};
      var isDupla=!!(e.rodagem_dupla);
      rows+='<div style="background:var(--color-background-secondary);border-radius:8px;padding:.6rem .75rem;margin-bottom:8px">'
        +'<div style="display:grid;grid-template-columns:60px 1fr;gap:8px;align-items:center;margin-bottom:6px">'
        +'<span style="font-size:12px;font-weight:700;color:#185FA5">Eixo '+i+'</span>'
        +'<input class="inp" id="eixo-desc-'+i+'" placeholder="Ex: Dianteiro, Traseiro..." value="'+escHtml(e.descricao_eixo||'')+'" style="font-size:12px"/>'
        +'</div>'
        +'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
        +'<div style="display:flex;gap:4px">'
        +'<button type="button" id="eixo-simples-'+i+'" onclick="pneusSetRodagem('+i+',false)" '
        +'style="padding:5px 10px;font-size:11px;border-radius:6px;cursor:pointer;border:.5px solid #185FA5;'+(isDupla?'background:transparent;color:#185FA5':'background:#185FA5;color:#fff')+'">'
        +'⬤ Simples</button>'
        +'<button type="button" id="eixo-dupla-'+i+'" onclick="pneusSetRodagem('+i+',true)" '
        +'style="padding:5px 10px;font-size:11px;border-radius:6px;cursor:pointer;border:.5px solid #185FA5;'+(isDupla?'background:#185FA5;color:#fff':'background:transparent;color:#185FA5')+'">'
        +'⬤⬤ Dupla</button>'
        +'</div>'
        +'<input type="hidden" id="eixo-rodagem-'+i+'" value="'+(isDupla?'1':'0')+'"/>'
        +'<label style="display:flex;align-items:center;gap:4px;font-size:11px;color:#555;margin-left:auto">'
        +'<input type="checkbox" id="eixo-estepe-'+i+'"'+(e.tem_estepe?' checked':'')+'/> Estepe</label>'
        +'</div>'
        +'<div id="eixo-preview-'+i+'" style="margin-top:6px;display:flex;justify-content:center;gap:4px;align-items:center">'
        +pneusPreviewEixo(isDupla)
        +'</div>'
        +'</div>';
    }
    var el=document.getElementById('eixos-form-inner'); if(el)el.innerHTML=rows;
  }

  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:500px">'
    +'<h3 style="margin-bottom:.5rem">⚙️ Configurar Eixos — '+escHtml(v.placa||'')+'</h3>'
    +'<div style="font-size:11px;color:#888;margin-bottom:1rem">'+escHtml(v.modelo||'')+'</div>'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:1rem">'
    +'<label style="font-size:12px">Quantidade de eixos:</label>'
    +'<input id="qtd-eixos-inp" type="number" min="1" max="7" value="'+qtd+'" '
    +'style="width:60px;padding:4px;border:.5px solid #e0dfd8;border-radius:6px;font-size:14px;text-align:center"/>'
    +'</div>'
    +'<div id="eixos-form-inner"></div>'
    +'<div class="ma" style="margin-top:1rem">'
    +'<button class="btn" onclick="closeModal()">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="pneusSalvarEixos(\''+vId+'\')">💾 Salvar configuração</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var inp=document.getElementById('qtd-eixos-inp');
    if(inp){
      inp.oninput=function(){
        var n=parseInt(this.value,10)||1;
        if(n<1) n=1; if(n>7) n=7;
        this.value=n; qtd=n; renderEixosForm();
      };
    }
    renderEixosForm();
  }, 40);
}

function pneusPreviewEixo(isDupla){
  var tireSt='width:18px;height:28px;border-radius:4px;border:2px solid #888;background:var(--color-background-primary);display:inline-block';
  var axle='width:40px;height:3px;background:#888;border-radius:1px;display:inline-block;vertical-align:middle';
  var body='width:8px;height:36px;background:#555;border-radius:3px;display:inline-block;vertical-align:middle';
  if(isDupla){
    return '<div style="'+tireSt+';margin-right:2px"></div>'
      +'<div style="'+tireSt+'"></div>'
      +'<div style="'+axle+'"></div>'
      +'<div style="'+body+'"></div>'
      +'<div style="'+axle+'"></div>'
      +'<div style="'+tireSt+';margin-right:2px"></div>'
      +'<div style="'+tireSt+'"></div>';
  }
  return '<div style="'+tireSt+'"></div>'
    +'<div style="'+axle+'"></div>'
    +'<div style="'+body+'"></div>'
    +'<div style="'+axle+'"></div>'
    +'<div style="'+tireSt+'"></div>';
}

function pneusSetRodagem(eixoNum, isDupla){
  var inp=document.getElementById('eixo-rodagem-'+eixoNum);
  if(inp) inp.value=isDupla?'1':'0';
  var btnS=document.getElementById('eixo-simples-'+eixoNum);
  var btnD=document.getElementById('eixo-dupla-'+eixoNum);
  if(btnS){ btnS.style.background=isDupla?'transparent':'#185FA5'; btnS.style.color=isDupla?'#185FA5':'#fff'; }
  if(btnD){ btnD.style.background=isDupla?'#185FA5':'transparent'; btnD.style.color=isDupla?'#fff':'#185FA5'; }
  var prev=document.getElementById('eixo-preview-'+eixoNum);
  if(prev) prev.innerHTML=pneusPreviewEixo(isDupla);
}

function pneusSalvarEixos(vId){
  var qtd=parseInt(((document.getElementById('qtd-eixos-inp')||{}).value)||2,10);
  if(qtd<1) qtd=1; if(qtd>7) qtd=7;
  var nova=[];
  for(var i=1;i<=qtd;i++){
    var desc=((document.getElementById('eixo-desc-'+i)||{}).value||'Eixo '+i).trim();
    var isDupla=((document.getElementById('eixo-rodagem-'+i)||{}).value||'0')==='1';
    var estepe=!!(document.getElementById('eixo-estepe-'+i)||{}).checked;
    var pneusQtd=isDupla?4:2;
    nova.push({veiculo_id:vId,numero_eixo:i,descricao_eixo:desc,pneus_eixo:pneusQtd,rodagem_dupla:isDupla,tem_estepe:estepe});
  }
  pneus_config_eixos[vId]=nova;
  var finish=function(){
    closeModal(); pneusVerMapaVeiculo(vId);
    progShowToast('✅ Eixos configurados ('+qtd+')');
  };
  if(DEMO){ finish(); return; }
  // Substitui a config do veículo (evita acumular eixos duplicados a cada salvar)
  sbDelete('pneus_config_eixos','veiculo_id=eq.'+vId).then(function(){
    var chain=Promise.resolve();
    nova.forEach(function(c){
      chain=chain.then(function(){ return sbInsert('pneus_config_eixos',c); });
    });
    return chain;
  }).then(finish).catch(function(e){
    console.error('pneusSalvarEixos',e);
    progShowToast('⚠ Erro ao salvar eixos. Tente novamente.','erro');
  });
}

function pneusInstalarPosicao(vId,eixo,posicao){
  var disponiveis=pneus_dados.filter(function(p){
    var st=pneusNormStatus(p.status);
    return st==='estoque'||st==='novo'||st==='usado'||st==='recapado';
  });
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:400px">'
    +'<h3 style="margin-bottom:1rem">Instalar — Eixo '+eixo+' Pos.'+posicao+'</h3>'
    +(disponiveis.length
      ?'<select class="inp" id="inst-pneu-id" style="width:100%;margin-bottom:1rem"><option value="">Selecione...</option>'
        +disponiveis.map(function(p){return '<option value="'+p.id+'">'+escHtml(pneusFogoValor(p)||p.codigo)+' — '+escHtml(p.marca||'')+' '+escHtml(p.modelo||'')+' '+escHtml(p.medida||'')+'</option>';}).join('')+'</select>'
        +'<input class="inp" id="inst-km" type="number" placeholder="KM do veículo" style="width:100%;margin-bottom:1rem"/>'
        +'<div class="ma"><button class="btn" onclick="closeModal()">Cancelar</button>'
        +'<button class="btn btn-pri" onclick="pneusConfirmarInstalacao(\''+vId+'\','+eixo+','+posicao+')">✓ Instalar</button></div>'
      :'<div style="padding:1rem;text-align:center;color:#aaa">Nenhum pneu em estoque</div><div class="ma"><button class="btn" onclick="closeModal()">Fechar</button></div>')
    +'</div></div>');
}

function pneusConfirmarInstalacao(vId,eixo,posicao){
  var pid=((document.getElementById('inst-pneu-id')||{}).value||'');
  var km=parseInt(((document.getElementById('inst-km')||{}).value)||0);
  if(!pid){alert('Selecione um pneu');return;}
  var eixoCfg=(pneus_config_eixos[vId]||[]).find(function(e){return e.numero_eixo===eixo;})||{};
  var posLabel=(pneusGetPosicoesEixo(vId,eixo,eixoCfg.pneus_eixo||2).find(function(p){return p.posicao===posicao;})||{}).label||'Pos.'+posicao;
  var desc='Eixo '+eixo+' — '+posLabel;
  var pos={id:'pos_'+Date.now(),pneu_id:pid,veiculo_id:vId,eixo:eixo,posicao:posicao,descricao_posicao:desc,km_instalacao:km};
  pneus_posicoes.push(pos);
  if(!DEMO)sbInsert('pneus_posicoes',pos);
  var mov={id:'mov_'+Date.now(),pneu_id:pid,tipo:'Instalação',veiculo_id:vId,km_evento:km,
    responsavel:usuarioLogado?usuarioLogado.nome:'Sistema',observacao:desc,data_hora:new Date().toISOString()};
  pneus_movimentos.unshift(mov);
  var p=pneus_dados.find(function(x){return x.id===pid;});
  if(p){
    p.status='em_uso';
    p.km_instalacao=km;
    if(!DEMO) sbUpdate('pneus',{status:'em_uso',km_instalacao:km,atualizado_em:new Date().toISOString()},'id=eq.'+pid);
  }
  if(!DEMO)sbInsert('pneus_movimentos',mov);
  closeModal(); pneusVerMapaVeiculo(vId);
  progShowToast('✅ Pneu instalado em '+desc);
}
