/** Carrega frota completa (paginado) — sbFetch padrão corta em 1000 e some placas no meio/fim do alfabeto. */

function frtFetchDocumentosCompleto(){
  if(DEMO) return Promise.resolve(frt_documentos||[]);
  function apply(rows){
    rows=(rows||[]).filter(function(d){ return d && (typeof fdocDocAtivo!=='function' || fdocDocAtivo(d)); });
    return typeof fdocNormRows==='function'?fdocNormRows(rows):rows;
  }
  function viaLimit(){
    return sbFetch('frotas_documentos',{order:'id.desc',limit:5000}).then(function(r){ return apply(r||[]); }).catch(function(){
      return sbFetch('frotas_documentos',{order:'validade',limit:5000}).then(function(r){ return apply(r||[]); }).catch(function(){ return []; });
    });
  }
  if(typeof sbFetchAll==='function'){
    return sbFetchAll('frotas_documentos',{order:'id.desc',maxPages:20})
      .then(function(r){ return (r&&r.length)?apply(r):viaLimit(); })
      .catch(viaLimit);
  }
  return viaLimit();
}
function frtFetchVeiculosCompleto(){
  if(DEMO) return Promise.resolve(frt_veiculos||[]);
  if(typeof sbFetchAll==='function'){
    return sbFetchAll('frotas_veiculos',{order:'placa',maxPages:10})
      .then(function(r){ return r||[]; })
      .catch(function(){
        return sbFetch('frotas_veiculos',{order:'placa',limit:5000}).then(function(r){return r||[];}).catch(function(){return[];});
      });
  }
  return sbFetch('frotas_veiculos',{order:'placa',limit:5000}).then(function(r){return r||[];}).catch(function(){return[];});
}
function frtFetchManutencoesCompleto(){
  if(DEMO) return Promise.resolve(frt_manutencoes||[]);
  function _ok(r){ return (r&&r.length)?r:[]; }
  function _viaSbFetch(){
    return sbFetch('frotas_manutencoes',{order:'data.desc',limit:5000}).then(_ok).catch(function(){
      return sbFetch('frotas_manutencoes',{order:'data_solicitacao.desc',limit:5000}).then(_ok).catch(function(){return[];});
    });
  }
  if(typeof sbFetchAll==='function'){
    return sbFetchAll('frotas_manutencoes',{order:'data.desc',maxPages:5})
      .then(function(r){ return (r&&r.length)?r:sbFetchAll('frotas_manutencoes',{order:'data_solicitacao.desc',maxPages:5}).then(_ok); })
      .then(function(r){ return (r&&r.length)?r:_viaSbFetch(); })
      .catch(_viaSbFetch);
  }
  return _viaSbFetch();
}
/** Placa efetiva do chamado (campo placa ou cadastro do veículo). */
function frtManutPlacaOf(m){
  if(!m) return '';
  if(m.placa) return String(m.placa);
  if(m.veiculo_id){
    var v=(frt_veiculos||[]).find(function(x){return String(x.id)===String(m.veiculo_id);});
    if(v&&v.placa) return String(v.placa);
  }
  return '';
}
function frtManutMergeRows(extra){
  if(!extra||!extra.length) return 0;
  var byId={}; (frt_manutencoes||[]).forEach(function(m){ if(m&&m.id) byId[String(m.id)]=true; });
  var n=0;
  extra.forEach(function(m){
    if(!m) return;
    if(m.id&&byId[String(m.id)]) return;
    if(!frt_manutencoes) frt_manutencoes=[];
    frt_manutencoes.push(m);
    if(m.id) byId[String(m.id)]=true;
    n++;
  });
  return n;
}
/** Busca chamados no banco por trecho de placa (ex.: 9D41). */
function frtManutBuscarPlacaNoBanco(busca){
  var safe=String(busca||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  if(DEMO||safe.length<2) return Promise.resolve([]);
  return sbFetch('frotas_manutencoes',{filters:['placa=ilike.*'+safe+'*'],order:'data.desc',limit:300})
    .then(function(rows){
      frtManutMergeRows(rows||[]);
      return rows||[];
    })
    .catch(function(){ return []; });
}
/** Separa placas coladas do Excel (quebra de linha, tab, vírgula, ponto-e-vírgula). */
function frtParsePlacasBusca(busca){
  var raw=String(busca||'').trim();
  if(!raw) return [];
  var hasBreak=/[\n\r\t,;]/.test(raw);
  var parts;
  if(hasBreak){
    parts=raw.split(/[\n\r\t,;]+/).map(function(s){return s.trim();}).filter(Boolean);
  } else {
    var toks=raw.split(/\s+/).filter(Boolean);
    function isPlacaTok(t){
      var n=String(t).toUpperCase().replace(/[^A-Z0-9]/g,'');
      return n.length>=5 && n.length<=8 && /[A-Z]/.test(n) && /[0-9]/.test(n);
    }
    if(toks.length>1 && toks.filter(isPlacaTok).length>=2) parts=toks.filter(isPlacaTok);
    else parts=[raw];
  }
  var seen={}, out=[];
  parts.forEach(function(p){
    var k=(typeof frtNormPlaca==='function'?frtNormPlaca(p):p.toUpperCase().replace(/[-\s]/g,''));
    if(!k||seen[k]) return;
    seen[k]=true; out.push(p);
  });
  return out;
}

/** Placa bate na busca ignorando hífen/espaço (FTM9D41 ≡ FTM-9D41). Lista colada = qualquer placa da lista. */
function frtPlacaMatchBusca(placa, busca){
  if(!busca) return true;
  var tokens=frtParsePlacasBusca(busca);
  var p=String(placa||'').toLowerCase().replace(/[-\s]/g,'');
  if(tokens.length<=1){
    var b=String(busca).toLowerCase().replace(/[-\s\n\r\t,;]/g,'');
    if(p.indexOf(b)>=0) return true;
    return String(placa||'').toLowerCase().indexOf(String(busca).toLowerCase())>=0;
  }
  var pNorm=(typeof frtNormPlaca==='function'?frtNormPlaca(placa):p.toUpperCase());
  for(var i=0;i<tokens.length;i++){
    var t=(typeof frtNormPlaca==='function'?frtNormPlaca(tokens[i]):String(tokens[i]).toUpperCase().replace(/[-\s]/g,''));
    if(t && pNorm===t) return true;
  }
  return false;
}

function frtHintFiltroPlacas(el){
  if(!el) return;
  var n=frtParsePlacasBusca(el.value).length;
  var hint=el.nextElementSibling;
  if(!hint || hint.getAttribute('data-frt-placa-hint')!=='1'){
    if(n<=1) return;
    hint=document.createElement('span');
    hint.setAttribute('data-frt-placa-hint','1');
    hint.style.cssText='font-size:10px;color:#185FA5;font-weight:600;white-space:nowrap';
    el.insertAdjacentElement('afterend', hint);
  }
  if(n>1){
    hint.textContent=n+' placas';
    hint.style.display='inline';
    el.title=n+' placas no filtro. Cole do Excel (Ctrl+V) — uma por linha.';
    el.style.minWidth='220px';
  } else {
    hint.textContent='';
    hint.style.display='none';
  }
}

function frtPasteFiltroPlacas(e, renderFn){
  var txt='';
  try{ txt=((e.clipboardData||window.clipboardData).getData('text')||''); }catch(err){ return; }
  var placas=frtParsePlacasBusca(txt);
  if(placas.length<2) return;
  e.preventDefault();
  var el=e.target;
  el.value=placas.join(', ');
  frtHintFiltroPlacas(el);
  if(typeof renderFn==='function') renderFn();
  if(typeof progShowToast==='function') progShowToast(placas.length+' placas coladas no filtro');
}

function frtInit(subpage){
  // Mover TODAS as páginas de frotas para dentro do app-content-area de uma vez
  ['frotas-dashboard','frotas-veiculos','frotas-pneus','frotas-portaria',
   'frotas-programacao','frotas-manutencoes','frotas-combustivel','frotas-pedagios','frotas-multas',
   'frotas-avarias','frotas-documentos','frotas-ociosidade','frotas-custos',
   'frotas-conduta','frotas-auditoria','frotas-integracoes','frotas-relatorios'].forEach(function(sub){
    _ensureInACA('pg-'+sub);
  });

  // Carregar dados e renderizar após carregar
  var p = function(t,o){ return sbFetch(t,o||{}).then(function(r){return r||[];}).catch(function(){return [];}); };

  // Transferências + aprovações sensíveis pendentes
  frtCarregarTransferencias();
  if(typeof frtCarregarVeicAprovacoes==='function') frtCarregarVeicAprovacoes();

  // Veículos primeiro (frota completa — sem corte 1000)
  frtFetchVeiculosCompleto().then(function(rows){
    if(rows&&rows.length) frt_veiculos = rows;
    try{ frtMigrarFiorinosUtilitario(); }catch(eMig){ console.warn('frtMigrarFiorinosUtilitario',eMig); }

    frtPopularSelects();

    if(subpage==='frotas-dashboard')    frtDashRender();
    else if(subpage==='frotas-veiculos') frtVeiculosRender();
    else if(subpage==='frotas-pneus')   pneusInit();
    else if(subpage==='frotas-portaria'){
      if(typeof portOffInit==='function') portOffInit();
      portCarregarConfigs();
      // Garantir que composicao_dia e equipes estão carregados
      _precisaModulo('diario', function(){
        // Carregar veículos programados para hoje
        var hoje=dataHojeLocal();
        if(!DEMO && Object.keys(_progVeiculos).filter(function(k){return k.endsWith('_'+hoje);}).length===0){
          sbFetch('prog_veiculos_dia',{filters:['data=eq.'+hoje,'deleted_at=is.null']}).then(function(rows){
            if(rows&&rows.length) rows.forEach(function(r){
              _progVeiculos[r.equipe_id+'_'+hoje]={placa:r.placa,modelo:r.modelo||'',id:r.veiculo_id};
            });
          }).catch(function(){});
        }
        setTimeout(function(){
          portRenderSeletorAtiva();
          var saved=localStorage.getItem('port_ativa_id');
          if(saved) portDefinirAtiva(saved);
          // Auto-filtrar pela filial do usuário logado (se portaria)
          if(usuarioLogado && usuarioLogado.perfil==='portaria' && usuarioLogado.filial_id){
            var selFil=document.getElementById('port-eq-filial');
            if(selFil) selFil.value=usuarioLogado.filial_id;
          }
          portMostrarAba('equipes');
        },150);
      });
    }
    else if(subpage==='frotas-programacao') frtProgRender();
    else if(subpage==='frotas-manutencoes') frtManutRender();
    else if(subpage==='frotas-combustivel'){
      frtCombRender();
      if(typeof frtCombCarregarInconsistencias==='function'){
        frtCombCarregarInconsistencias().then(function(){ frtCombRender(); });
      }
    }
    else if(subpage==='frotas-pedagios'){
      if(typeof frtPedInit==='function') frtPedInit();
      else if(typeof frtPedRender==='function') frtPedRender();
    }
    else if(subpage==='frotas-multas'){
      // Fase 5 — redireciona para Documentos > Multas
      window._fdocAbaInicial='multas';
      var pgMul=document.getElementById('pg-frotas-documentos');
      if(pgMul){ pgMul.classList.remove('hidden'); }
      var pgOld=document.getElementById('pg-frotas-multas');
      if(pgOld) pgOld.classList.add('hidden');
      fdocAba('multas');
    }
    else if(subpage==='frotas-avarias')  frtAvarRender();
    else if(subpage==='frotas-documentos') {
      var abaDoc=window._fdocAbaInicial||'dashboard';
      window._fdocAbaInicial=null;
      fdocAba(abaDoc);
    }
    else if(subpage==='frotas-ociosidade'){
      frtOcioRender();
      // Ativar layout interno de scroll da ociosidade
      var pgOcio = document.getElementById('pg-frotas-ociosidade');
      var aca    = document.getElementById('app-content-area');
      if(pgOcio) pgOcio.classList.add('ocio-ativa');
      if(aca)    aca.style.overflow = 'hidden';
    }
    else if(subpage==='frotas-custos')   frtCustosRender();
    else if(subpage==='frotas-conduta')  fcdRender();
    else if(subpage==='frotas-auditoria') frtAuditoriaRender();
    else if(subpage==='frotas-integracoes') frtIntegracoesRender();

    // Carregar demais tabelas em background (condutas: só sob demanda em fcdEnsureLoaded)
    Promise.all([
      p('frotas_portaria_saidas',{select:PORT_SAIDA_SEL_LISTA,order:'data_saida.desc',limit:5000,filters:['deleted_at=is.null','data_saida=gte.'+(function(_ms){var _d=new Date(_ms);return _d.getFullYear()+'-'+String(_d.getMonth()+1).padStart(2,'0')+'-'+String(_d.getDate()).padStart(2,'0');})(Date.now()-30*86400000)]}),
      frtFetchManutencoesCompleto(),
      sbFetchAll('frotas_combustivel',{order:'data.desc'}).catch(function(){return[];}),
      p('frotas_multas',{order:'data_infracao.desc'}),
      p('frotas_avarias',{order:'data.desc'}),
      frtFetchDocumentosCompleto(),
      p('frotas_riscos_auditoria',{filters:['status=neq.Resolvido'],order:'criado_em.desc'}),
      p('frotas_motorista_documentos',{order:'atualizado_em.desc',limit:3000}),
      p('frotas_veiculo_implementos',{order:'criado_em.asc',limit:5000}),
      p('frotas_implemento_tipos',{order:'nome.asc',limit:500}),
    ]).then(function(res){
      if(res[0]&&res[0].length) portMesclarSaidas(res[0]);
      if(res[1]&&res[1].length) frt_manutencoes = res[1];
      if(res[2]&&res[2].length) frt_combustivel = res[2];
      if(res[3]&&res[3].length) frt_multas      = res[3];
      if(res[4]&&res[4].length) frt_avarias     = res[4];
      if(res[5]&&res[5].length) frt_documentos  = (typeof fdocNormRows==='function'?fdocNormRows(res[5]):res[5]);
      if(res[6]&&res[6].length) frt_riscos      = res[6];
      if(res[7]){ frt_motorista_docs = res[7]||[]; _fmdLoaded=true; }
      if(res[8]){ frt_implementos = res[8]||[]; _fviLoaded=true; }
      if(res[9]){ frt_impl_tipos_extra = (res[9]||[]).filter(function(t){return t.ativo!==false;}).map(function(t){return t.nome;}); }
      if(subpage==='frotas-documentos' || subpage==='frotas-multas'){
        try{
          var abaMul=document.getElementById('fdoc-aba-multas');
          if(abaMul && abaMul.style.display!=='none' && typeof fdocRenderMultas==='function') fdocRenderMultas();
          else if(typeof fdocRenderDocs==='function') fdocRenderDocs();
          else if(typeof frtDocRender==='function') frtDocRender();
        }catch(eR){}
      }
      // Re-renderizar dashboard se estiver nele (agora com dados completos)
      if(subpage==='frotas-dashboard') frtDashRender();
      if(subpage==='frotas-veiculos') frtVeiculosRender();
      if(subpage==='frotas-manutencoes') frtManutRender();
      if(subpage==='frotas-combustivel'){
        frtCombRender();
        if(typeof frtCombCorrigirContratosAgo2026==='function') frtCombCorrigirContratosAgo2026({auto:true});
      }
      if(subpage==='frotas-pedagios' && typeof frtPedInit==='function') frtPedInit();
      if(subpage==='frotas-conduta') fcdEnsureLoaded().then(function(){ fcdRender(); });
      // Re-renderizar aba Retorno se estiver visível
      var _retEl = document.getElementById('port-aba-retorno');
      if(_retEl && _retEl.style.display !== 'none') portRenderRetorno();
    });
  }).catch(function(e){
    console.error('frtInit erro:', e);
  });
}

function frtCarregarDados(){
  if(DEMO){ frtGerarDemoData(); return Promise.resolve(); }
  // Carregar veículos primeiro (obrigatório) depois demais tabelas (opcionais)
  return frtFetchVeiculosCompleto().then(function(rows){
    if(rows&&rows.length) frt_veiculos = rows;
    try{ frtMigrarFiorinosUtilitario(); }catch(eMig){}
    // Carregar demais tabelas em paralelo sem bloquear
    var p = function(t,o){ return sbFetch(t,o).catch(function(){return[];}); };
    Promise.all([
      p('frotas_portaria_saidas',{select:PORT_SAIDA_SEL_LISTA,order:'data_saida.desc',limit:5000,filters:['deleted_at=is.null','data_saida=gte.'+(function(_ms){var _d=new Date(_ms);return _d.getFullYear()+'-'+String(_d.getMonth()+1).padStart(2,'0')+'-'+String(_d.getDate()).padStart(2,'0');})(Date.now()-30*86400000)]}),
      frtFetchManutencoesCompleto(),
      sbFetchAll('frotas_combustivel',{order:'data.desc'}).catch(function(){return[];}),
      p('frotas_multas',{order:'data_infracao.desc'}),
      p('frotas_avarias',{order:'data.desc'}),
      frtFetchDocumentosCompleto(),
      p('frotas_riscos_auditoria',{filters:['status=neq.Resolvido'],order:'criado_em.desc'}),
      p('frotas_motorista_documentos',{order:'atualizado_em.desc',limit:3000}),
    ]).then(function(res){
      if(res[0]&&res[0].length) portMesclarSaidas(res[0]);
      if(res[1]&&res[1].length) frt_manutencoes = res[1];
      if(res[2]&&res[2].length) frt_combustivel = res[2];
      if(res[3]&&res[3].length) frt_multas      = res[3];
      if(res[4]&&res[4].length) frt_avarias     = res[4];
      if(res[5]&&res[5].length) frt_documentos  = (typeof fdocNormRows==='function'?fdocNormRows(res[5]):res[5]);
      if(res[6]&&res[6].length) frt_riscos      = res[6];
      if(res[7]){ frt_motorista_docs = res[7]||[]; _fmdLoaded=true; }
    });
  }).catch(function(e){
    console.error('Erro ao carregar veículos:', e);
  });
}

