function portResolverEquipeSaida(p, data){
  if(!p) return null;
  var eq=portBuscarEquipe(p.equipe_id||p.equipe);
  if(eq) return eq;
  var placa=portNormPlaca(p.placa);
  if(!placa) return null;
  var hoje=dataHojeLocal();
  var ontem=(typeof _diasAtras==='function')?_diasAtras(1):hoje;
  var dias=[portDiaISO(data)||hoje];
  if(dias[0]===hoje){
    portDiasViradaPortaria(hoje).forEach(function(d){ if(dias.indexOf(d)<0) dias.push(d); });
  } else if(ontem && ontem!==hoje) dias.push(ontem);
  for(var i=0;i<dias.length;i++){
    var comps=portCompsProgramadasDia(dias[i]);
    for(var j=0;j<comps.length;j++){
      var c=comps[j];
      var pl=portNormPlaca(c.placa||c.veiculo_placa||'');
      if(!pl && typeof _progVeiculos!=='undefined'){
        var pv=_progVeiculos[c.equipe_id+'_'+dias[i]];
        if(pv) pl=portNormPlaca(pv.placa);
      }
      if(pl && pl===placa){
        eq=portBuscarEquipe(c.equipe_id);
        if(eq) return eq;
      }
    }
  }
  return null;
}
function portEnsureDadosPortariaDia(data){
  var dia=portDiaISO(data)||dataHojeLocal();
  var hoje=dataHojeLocal();
  var virada=portDiasViradaPortaria(hoje);
  var desde=virada.length?virada[virada.length-1]:((typeof _diasAtras==='function')?_diasAtras(1):hoje);
  if(DEMO) return Promise.resolve();
  if(!window._portEqDiaBuscado) window._portEqDiaBuscado={};
  // OFFLINE: hidrata da memória local (snapshot da última vez online) e MARCA como buscado,
  // para o render sair do "⏳ Buscando…" e exibir a relação local — sem re-buscar em loop.
  if(typeof portOffIsOnline==='function' && !portOffIsOnline()){
    var _marcarBuscado=function(){
      window._portEqDiaBuscado['c:'+dia]=true;
      window._portEqDiaBuscado['p:'+dia]=true;
      window._portEqDiaBuscado['p:em_campo']=true;
      (virada||[]).forEach(function(d){ if(d) window._portEqDiaBuscado['c:'+d]=true; });
    };
    if(typeof portOffHidatarCache==='function'){
      return portOffHidatarCache().then(_marcarBuscado, _marcarBuscado);
    }
    _marcarBuscado();
    return Promise.resolve();
  }
  var jobs=[];
  function precisaComp(d){
    if(!d || window._portEqDiaBuscado['c:'+d]) return false;
    return !(composicao_dia||[]).some(function(c){ return portDiaISO(c.data)===d; });
  }
  function fetchComp(d){
    if(!d || !precisaComp(d)){ if(d) window._portEqDiaBuscado['c:'+d]=true; return; }
    window._portEqDiaBuscado['c:'+d]=true;
    jobs.push(sbFetch('composicao_dia',{filters:['data=eq.'+d],limit:2000}).then(function(rows){ portMesclarComposicao(rows); }));
  }
  fetchComp(dia);
  if(dia===hoje) virada.forEach(fetchComp);
  if(!window._portEqDiaBuscado['p:'+dia]){
    window._portEqDiaBuscado['p:'+dia]=true;
    jobs.push(sbFetch('frotas_portaria_saidas',{filters:portFiltrosDataSaida(dia,dia),order:'data_saida.desc',limit:2000}).then(function(rows){ portMesclarSaidas(rows); }));
  }
  // Virada: EM CAMPO de ontem→hoje (turno da noite). Recorte fino no cliente.
  if(dia===hoje && !window._portEqDiaBuscado['p:em_campo']){
    window._portEqDiaBuscado['p:em_campo']=true;
    jobs.push(sbFetch('frotas_portaria_saidas',{
      filters:[portFiltroStatusEmCampo()].concat(portFiltrosDataSaida(desde, hoje)),
      order:'data_saida.desc', limit:800
    }).then(function(rows){ portMesclarSaidas(rows); }));
  }
  if(!jobs.length) return Promise.resolve();
  return Promise.all(jobs).then(function(){
    if(typeof portOffSnapshotCache==='function') portOffSnapshotCache();
  }).catch(function(){
    if(typeof portOffHidatarCache==='function') return portOffHidatarCache();
  });
}
/** JPEG em coluna *_b64, ou pacote {v:1,carga,km,extras} gravado em foto_carga_saida_b64 quando km/extras falham. */
