  var aU=typeof isUUID==='function' && isUUID(String(a.id||''));
  var bU=typeof isUUID==='function' && isUUID(String(b.id||''));
  if(aU && !bU) return a;
  if(bU && !aU) return b;
  if(a.km_retorno!=null && a.km_retorno!=='' && (b.km_retorno==null || b.km_retorno==='')) return a;
  if(b.km_retorno!=null && b.km_retorno!=='' && (a.km_retorno==null || a.km_retorno==='')) return b;
  if((a.offline_event_id||'') && !(b.offline_event_id||'')) return a;
