// PORTARIA — AUTORIZADOS (cadastro ≠ portaria; liberação no tablet)
// ══════════════════════════════════════════════════════════════════
var portaria_autorizados = [];
var portaria_autorizados_loaded = false;

function portPodeCadastrarAutorizado(){
  var p = (usuarioLogado && usuarioLogado.perfil) || '';
  return p !== 'portaria';
}

function portAuthCpfDigits(v){ return String(v||'').replace(/\D/g,''); }
function portAuthCpfMask(v){
  var d = portAuthCpfDigits(v).slice(0,11);
  if(d.length<=3) return d;
  if(d.length<=6) return d.slice(0,3)+'.'+d.slice(3);
  if(d.length<=9) return d.slice(0,3)+'.'+d.slice(3,6)+'.'+d.slice(6);
  return d.slice(0,3)+'.'+d.slice(3,6)+'.'+d.slice(6,9)+'-'+d.slice(9);
}
function portAuthCpfValido(v){
  var c = portAuthCpfDigits(v);
  if(c.length!==11 || /^(\d)\1+$/.test(c)) return false;
  var s=0,i;
  for(i=0;i<9;i++) s+=parseInt(c.charAt(i),10)*(10-i);
  var r=(s*10)%11; if(r===10) r=0; if(r!==parseInt(c.charAt(9),10)) return false;
  s=0; for(i=0;i<10;i++) s+=parseInt(c.charAt(i),10)*(11-i);
  r=(s*10)%11; if(r===10) r=0; return r===parseInt(c.charAt(10),10);
}
function portAuthPlacaFmt(v){
  return String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,7);
}
function portAuthEhCpfPendente(v){
  return /^PENDENTE/i.test(String(v||'').trim()) || !portAuthCpfDigits(v);
}
function portAuthBuscarFrotaPorPlaca(placa){
  var n = portAuthPlacaFmt(placa);
  if(!n) return null;
  var src = (typeof frt_veiculos!=='undefined' && frt_veiculos && frt_veiculos.length)
    ? frt_veiculos
    : ((typeof veiculos!=='undefined' && veiculos) ? veiculos : []);
  return src.find(function(v){
    return portAuthPlacaFmt(v.placa||v.placa_atual||'')===n;
  }) || null;
}
function portAuthBuscarColabPorNome(nome){
  var n = String(nome||'').toUpperCase().replace(/\s+/g,' ').trim();
  if(!n) return null;
  var hits = (colaboradores||[]).filter(function(c){
    if(c.ativo===false || c.dispensado) return false;
    return String(c.nome||'').toUpperCase().replace(/\s+/g,' ').trim()===n;
  });
  return hits.length===1 ? hits[0] : null;
}

