async function portAuthImportarLoteLista(){
  if(!portPodeCadastrarAutorizado()){
    progShowToast('⚠ Importação só para usuário fora do perfil Portaria.','erro');
    return;
  }
  if(!confirm('Importar 17 autorizados da lista?\n\n• Cruza placa com frota da empresa (só referência)\n• NÃO cadastra veículo novo na frota\n• CPF/RG/setor/fotos ficam para completar depois se não achar colaborador')) return;

  await portCarregarAutorizados(true);
  if(typeof frt_veiculos==='undefined' || !frt_veiculos || !frt_veiculos.length){
    try{
      var rows=await sbFetch('frotas_veiculos',{filters:['status=neq.Inativo'],order:'placa',limit:5000});
      if(rows&&rows.length) frt_veiculos=rows;
    }catch(e){}
  }
  if(!(colaboradores||[]).length && !DEMO){
    try{
      var cols=await sbFetch('colaboradores',{filters:['ativo=eq.true'],order:'nome',limit:8000});
      if(cols&&cols.length) colaboradores=cols;
    }catch(e){}
  }

  var userNome=(usuarioLogado&&(usuarioLogado.nome||usuarioLogado.email))||'';
  var ok=0, skip=0, err=0, frotaN=0, extN=0;

  for(var i=0;i<PORT_AUTH_LOTE_20260911.length;i++){
    var item=PORT_AUTH_LOTE_20260911[i];
    var placa=portAuthPlacaFmt(item.placa);
    var exist=(portaria_autorizados||[]).find(function(a){
      return a.ativo!==false && portAuthPlacaFmt(a.veiculo_placa)===placa;
    });
    var fv=portAuthBuscarFrotaPorPlaca(placa);
    var col=portAuthBuscarColabPorNome(item.nome);
    var cpfDigits=col ? portAuthCpfDigits(col.cpf||col.bro||'') : '';
    var dados={
      nome: item.nome,
      rg: (col && (col.rg||'')) || null,
      cpf: cpfDigits ? portAuthCpfMask(cpfDigits) : ('PENDENTE-'+placa),
      cpf_digits: cpfDigits || null,
      setor: (col && (col.setor||col.area||col.cargo)) || 'A completar',
      veiculo_placa: placa,
      veiculo_marca: fv ? (fv.marca||null) : null,
      veiculo_modelo: (fv && fv.modelo) ? fv.modelo : item.modelo,
      veiculo_cor: fv ? (fv.cor||null) : null,
      veiculo_id: fv ? String(fv.id) : null,
      frota_empresa: !!fv,
      colaborador_id: col ? String(col.id) : null,
      dados_completos: false,
      status_acesso: exist ? (exist.status_acesso||'Fora') : 'Fora',
      ativo: true,
      atualizado_por: userNome||'import_lista',
      obs: fv ? 'Vinculado à frota empresa' : 'Veículo particular/externo (não cadastrado na frota)'
    };
    if(fv) frotaN++; else extN++;

    try{
      if(exist){
        if(DEMO){
          Object.assign(exist, dados);
        } else {
          await sbUpdate('portaria_autorizados', dados, 'id=eq.'+exist.id);
        }
        skip++;
      } else {
        dados.criado_por = userNome||'import_lista';
        if(DEMO){
          dados.id='auth'+Date.now()+i;
          portaria_autorizados.unshift(dados);
        } else {
          await sbInsert('portaria_autorizados', dados);
        }
        ok++;
      }
    }catch(e){
      err++;
      console.warn('auth import', placa, e);
    }
  }

  portaria_autorizados_loaded=false;
  await portCarregarAutorizados(true);
  portRenderAutorizados();
  progShowToast('Importação: '+ok+' novos, '+skip+' atualizados, '+frotaN+' com frota, '+extN+' externos'+(err?', '+err+' erro(s)':'')+'.');
}

function portCarregarAutorizados(force){
  if(DEMO){ portaria_autorizados_loaded=true; return Promise.resolve(portaria_autorizados); }
  if(portaria_autorizados_loaded && !force) return Promise.resolve(portaria_autorizados);
  return sbFetch('portaria_autorizados',{ order:'nome.asc' }).then(function(rows){
    portaria_autorizados = Array.isArray(rows) ? rows : [];
    portaria_autorizados_loaded = true;
    return portaria_autorizados;
  }).catch(function(err){
    console.warn('portaria_autorizados:', err);
    if(typeof portOffHidatarCache==='function'){
      return portOffHidatarCache().then(function(){
        portaria_autorizados_loaded = true;
        return portaria_autorizados;
      });
    }
    portaria_autorizados_loaded = true;
    return portaria_autorizados;
  });
}

function portRenderAutorizados(){
  var aviso = document.getElementById('auth-aviso-portaria');
  if(aviso) aviso.style.display = portPodeCadastrarAutorizado() ? 'none' : 'block';

  portCarregarAutorizados().then(function(){
    var busca = ((document.getElementById('auth-busca')||{}).value||'').toLowerCase().trim();
    var stFil = (document.getElementById('auth-status-fil')||{}).value||'';
    var atFil = (document.getElementById('auth-ativo-fil')||{}).value;
    if(atFil===undefined || atFil===null) atFil='1';

    var lista = (portaria_autorizados||[]).filter(function(a){
      if(atFil==='1' && a.ativo===false) return false;
      if(atFil==='0' && a.ativo!==false) return false;
      if(stFil && (a.status_acesso||'Fora')!==stFil) return false;
      if(busca){
        var blob = [(a.nome||''),(a.cpf||''),(a.rg||''),(a.setor||''),(a.veiculo_placa||''),(a.veiculo_modelo||'')].join(' ').toLowerCase();
        if(blob.indexOf(busca)<0 && portAuthCpfDigits(a.cpf).indexOf(portAuthCpfDigits(busca))<0) return false;
      }
      return true;
    });

    var resumo = document.getElementById('auth-resumo');
    if(resumo){
      var nAtivos = (portaria_autorizados||[]).filter(function(a){return a.ativo!==false;}).length;
      var nLocal  = (portaria_autorizados||[]).filter(function(a){return a.ativo!==false && a.status_acesso==='No local';}).length;
      function chip(icon,label,val,cor,bg){
        return '<div style="background:'+(bg||'#f5f5f3')+';border-radius:8px;padding:5px 12px;display:flex;align-items:center;gap:6px">'
          +'<span style="font-size:16px">'+icon+'</span>'
          +'<div><div style="font-size:16px;font-weight:700;color:'+(cor||'#555')+'">'+val+'</div>'
          +'<div style="font-size:10px;color:#888">'+label+'</div></div></div>';
      }
      resumo.innerHTML = chip('🚗','Ativos',nAtivos,'#555','#f5f5f3')
        +chip('🟢','No local',nLocal,'#3B6D11','#EAF3DE')
        +chip('📋','Listados',lista.length,'#185FA5','#E6F1FB');
    }

    var tbody = document.getElementById('auth-tbody');
    if(!tbody) return;
    if(!lista.length){
      tbody.innerHTML='<tr><td colspan="8" style="padding:2rem;text-align:center;color:#aaa">Nenhum autorizado encontrado.'
        +(portPodeCadastrarAutorizado()?' Use “+ Cadastrar autorizado”.':'')+'</td></tr>';
      return;
    }

    var podeCad = portPodeCadastrarAutorizado();
    tbody.innerHTML = lista.map(function(a){
      var st = a.status_acesso||'Fora';
      var cor = st==='No local'?'#3B6D11':'#854F0B';
      var bg  = st==='No local'?'#EAF3DE':'#FEF3E2';
      var fotoP = a.foto_pessoa
        ? '<img src="'+a.foto_pessoa+'" style="width:38px;height:38px;border-radius:50%;object-fit:cover;border:1.5px solid #e0dfd8">'
        : '<div style="width:38px;height:38px;border-radius:50%;background:#f0efe8;display:flex;align-items:center;justify-content:center;font-size:16px">👤</div>';
      var fotoV = a.foto_veiculo
        ? '<img src="'+a.foto_veiculo+'" style="width:44px;height:32px;border-radius:6px;object-fit:cover;border:1.5px solid #e0dfd8">'
        : '<div style="width:44px;height:32px;border-radius:6px;background:#f0efe8;display:flex;align-items:center;justify-content:center;font-size:14px">🚙</div>';
      var veicTxt = [a.veiculo_placa, a.veiculo_marca, a.veiculo_modelo, a.veiculo_cor].filter(Boolean).join(' · ') || '—';
      var frotaBadge = a.frota_empresa
        ? '<span style="background:#E6F1FB;color:#185FA5;border-radius:10px;padding:1px 7px;font-size:9px;font-weight:600;margin-left:4px">Frota</span>'
        : '<span style="background:#f5f5f3;color:#888;border-radius:10px;padding:1px 7px;font-size:9px;font-weight:600;margin-left:4px">Externo</span>';
      var pendBadge = (portAuthEhCpfPendente(a.cpf) || a.setor==='A completar' || !a.foto_pessoa || !a.foto_veiculo)
        ? '<div style="font-size:9px;color:#854F0B;margin-top:2px">Completar dados</div>' : '';
      var btns = '';
      if(a.ativo!==false){
        if(st!=='No local'){
          btns += '<button class="btn btn-sm" onclick="portAuthLiberar(\''+a.id+'\',\'entrada\')" style="color:#3B6D11;border-color:#3B6D11;font-size:10px">➡ Entrada</button> ';
        } else {
          btns += '<button class="btn btn-sm" onclick="portAuthLiberar(\''+a.id+'\',\'saida\')" style="color:#185FA5;border-color:#185FA5;font-size:10px">↩ Saída</button> ';
        }
      }
      btns += '<button class="btn btn-sm" onclick="portVerAutorizado(\''+a.id+'\')" style="font-size:10px">👁</button> ';
      if(podeCad){
        btns += '<button class="btn btn-sm port-auth-cadastro" onclick="portNovoAutorizado(\''+a.id+'\')" style="font-size:10px">✎</button>';
      }
      return '<tr style="border-bottom:.5px solid #f0efe8'+(a.ativo===false?';opacity:.55':'')+'" onmouseenter="this.style.background=\'#F0F4FF\'" onmouseleave="this.style.background=\'\'">'
        +'<td style="padding:6px 8px">'+fotoP+'</td>'
        +'<td style="padding:6px 8px">'+fotoV+'</td>'
        +'<td style="padding:6px 8px;font-weight:600">'+escHtml(a.nome||'—')+pendBadge+'</td>'
        +'<td style="padding:6px 8px;font-size:11px"><div>'+(portAuthEhCpfPendente(a.cpf)?'<span style="color:#854F0B">CPF pendente</span>':escHtml(portAuthCpfMask(a.cpf)||'—'))+'</div><div style="color:#888">RG '+escHtml(a.rg||'—')+'</div></td>'
        +'<td style="padding:6px 8px;font-size:11px">'+escHtml(a.setor||'—')+'</td>'
        +'<td style="padding:6px 8px;font-size:11px;font-family:monospace">'+escHtml(veicTxt)+frotaBadge+'</td>'
        +'<td style="padding:6px 8px"><span style="background:'+bg+';color:'+cor+';border-radius:12px;padding:2px 9px;font-size:10px;font-weight:600">'
          +(a.ativo===false?'Inativo':escHtml(st))+'</span></td>'
        +'<td style="padding:6px 8px;white-space:nowrap">'+btns+'</td></tr>';
    }).join('');
  });
}

function portNovoAutorizado(id){
  if(!portPodeCadastrarAutorizado()){
    progShowToast('⚠ Cadastro de autorizados não é permitido para o perfil Portaria.','erro');
    return;
  }
  portCarregarAutorizados().then(function(){
    var a = id ? portaria_autorizados.find(function(x){return String(x.id)===String(id);}) : null;
    var isNew = !a; a = a||{};
    var setoresOpts = [];
    try{
      (colaboradores||[]).forEach(function(c){
        var s = (c.setor||'').trim();
        if(s && setoresOpts.indexOf(s)<0) setoresOpts.push(s);
      });
      setoresOpts.sort();
    }catch(e){}

    setModal('<div class="modal-bg"><div class="modal" style="max-width:620px;max-height:92vh;overflow-y:auto">'
      +'<h3 style="margin-bottom:1rem">'+(isNew?'🚗 Cadastrar autorizado':'✏ Editar autorizado')+'</h3>'
      +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.5rem;text-transform:uppercase;letter-spacing:.5px">Pessoa</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1rem">'
      +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Nome completo <span style="color:#A32D2D">*</span></label>'
      +'<input class="inp" id="auth-nome" style="width:100%" value="'+escHtml(a.nome||'')+'"/></div>'
      +'<div class="fg"><label style="font-size:11px">CPF <span style="color:#A32D2D">*</span></label>'
      +'<input class="inp" id="auth-cpf" style="width:100%" value="'+escHtml(portAuthCpfMask(a.cpf)||'')+'" placeholder="000.000.000-00" oninput="this.value=portAuthCpfMask(this.value)"/></div>'
      +'<div class="fg"><label style="font-size:11px">RG <span style="color:#A32D2D">*</span></label>'
      +'<input class="inp" id="auth-rg" style="width:100%" value="'+escHtml(a.rg||'')+'"/></div>'
      +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Setor <span style="color:#A32D2D">*</span></label>'
      +'<input class="inp" id="auth-setor" list="auth-setor-dl" style="width:100%" value="'+escHtml(a.setor||'')+'" placeholder="Setor / área"/>'
      +'<datalist id="auth-setor-dl">'+setoresOpts.map(function(s){return '<option value="'+escHtml(s)+'">';}).join('')+'</datalist></div>'
      +'</div>'

      +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.5rem;text-transform:uppercase;letter-spacing:.5px">Fotos</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1rem">'
      +'<div>'
        +'<label style="font-size:11px;display:block;margin-bottom:4px">📷 Foto da pessoa <span style="color:#A32D2D">*</span></label>'
        +'<div id="auth-foto-p-prev" style="width:100%;height:130px;background:#f5f5f3;border-radius:8px;border:1.5px dashed #e0dfd8;display:flex;align-items:center;justify-content:center;cursor:pointer;overflow:hidden" onclick="document.getElementById(\'auth-foto-p-inp\').click()">'
          +(a.foto_pessoa?'<img src="'+a.foto_pessoa+'" style="width:100%;height:100%;object-fit:cover">':'<span style="color:#aaa;font-size:12px;text-align:center">Clique para capturar</span>')
        +'</div>'
        +'<input type="file" id="auth-foto-p-inp" accept="image/*" capture="user" style="display:none" onchange="portFotoPreview(this,\'auth-foto-p-prev\',\'auth-foto-p-data\')">'
        +'<input type="hidden" id="auth-foto-p-data" value="">'
      +'</div>'
      +'<div>'
        +'<label style="font-size:11px;display:block;margin-bottom:4px">🚙 Foto do veículo <span style="color:#A32D2D">*</span></label>'
        +'<div id="auth-foto-v-prev" style="width:100%;height:130px;background:#f5f5f3;border-radius:8px;border:1.5px dashed #e0dfd8;display:flex;align-items:center;justify-content:center;cursor:pointer;overflow:hidden" onclick="document.getElementById(\'auth-foto-v-inp\').click()">'
          +(a.foto_veiculo?'<img src="'+a.foto_veiculo+'" style="width:100%;height:100%;object-fit:cover">':'<span style="color:#aaa;font-size:12px;text-align:center">Clique para capturar</span>')
        +'</div>'
        +'<input type="file" id="auth-foto-v-inp" accept="image/*" capture="environment" style="display:none" onchange="portFotoPreview(this,\'auth-foto-v-prev\',\'auth-foto-v-data\')">'
        +'<input type="hidden" id="auth-foto-v-data" value="">'
      +'</div>'
      +'</div>'

      +'<div style="font-size:11px;font-weight:700;color:#185FA5;margin-bottom:.5rem;text-transform:uppercase;letter-spacing:.5px">Veículo</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1rem">'
      +'<div class="fg"><label style="font-size:11px">Placa <span style="color:#A32D2D">*</span></label>'
      +'<input class="inp" id="auth-placa" style="width:100%;text-transform:uppercase;font-family:monospace;letter-spacing:1px" value="'+escHtml(a.veiculo_placa||'')+'" oninput="this.value=portAuthPlacaFmt(this.value)" onblur="portAuthPreencherFrotaNoForm()"/>'
      +'<div id="auth-frota-hint" style="font-size:10px;color:#888;margin-top:3px"></div></div>'
      +'<div class="fg"><label style="font-size:11px">Cor</label>'
      +'<input class="inp" id="auth-cor" style="width:100%" value="'+escHtml(a.veiculo_cor||'')+'"/></div>'
      +'<div class="fg"><label style="font-size:11px">Marca</label>'
      +'<input class="inp" id="auth-marca" style="width:100%" value="'+escHtml(a.veiculo_marca||'')+'"/></div>'
      +'<div class="fg"><label style="font-size:11px">Modelo</label>'
      +'<input class="inp" id="auth-modelo" style="width:100%" value="'+escHtml(a.veiculo_modelo||'')+'"/></div>'
      +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Obs. veículo</label>'
      +'<input class="inp" id="auth-veic-obs" style="width:100%" value="'+escHtml(a.veiculo_obs||'')+'"/></div>'
      +'</div>'

      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1.25rem">'
      +'<div class="fg"><label style="font-size:11px">Status cadastro</label>'
      +'<select class="inp" id="auth-ativo" style="width:100%"><option value="1"'+(a.ativo===false?'':' selected')+'>Ativo</option><option value="0"'+(a.ativo===false?' selected':'')+'>Inativo</option></select></div>'
      +'<div class="fg"><label style="font-size:11px">Observações</label>'
      +'<input class="inp" id="auth-obs" style="width:100%" value="'+escHtml(a.obs||'')+'"/></div>'
      +'</div>'

      +'<div style="display:flex;gap:8px">'
      +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
      +'<button class="btn btn-pri" id="auth-salvar-btn" style="flex:2">'+(isNew?'✅ Cadastrar':'Salvar')+'</button>'
      +'</div></div></div>');

    setTimeout(function(){
      if(a.foto_pessoa) portFotoGuardar('auth-foto-p-data', a.foto_pessoa);
      if(a.foto_veiculo) portFotoGuardar('auth-foto-v-data', a.foto_veiculo);
      var btn = document.getElementById('auth-salvar-btn'); if(!btn) return;
      btn.onclick = function(){
        if(!portPodeCadastrarAutorizado()){
          progShowToast('⚠ Sem permissão para cadastrar.','erro'); return;
        }
        var g = function(i){ return (document.getElementById(i)||{}).value||''; };
        var nome = g('auth-nome').trim();
        var cpfRaw = g('auth-cpf').trim();
        var cpf  = portAuthCpfDigits(cpfRaw);
        var rg   = g('auth-rg').trim();
        var setor= g('auth-setor').trim();
        var placa= portAuthPlacaFmt(g('auth-placa'));
        var fotoP = portFotoLer('auth-foto-p-data') || a.foto_pessoa || null;
        var fotoV = portFotoLer('auth-foto-v-data') || a.foto_veiculo || null;
        var fv = portAuthBuscarFrotaPorPlaca(placa);
        if(!nome){ progShowToast('⚠ Informe o nome.','erro'); return; }
        if(!placa){ progShowToast('⚠ Informe a placa do veículo.','erro'); return; }
        if(!setor){ progShowToast('⚠ Informe o setor.','erro'); return; }
        var cpfSave;
        if(portAuthEhCpfPendente(cpfRaw) || !cpf){
          cpfSave = 'PENDENTE-'+placa;
        } else if(!portAuthCpfValido(cpf)){
          progShowToast('⚠ CPF inválido.','erro'); return;
        } else {
          cpfSave = portAuthCpfMask(cpf);
        }
        // Fotos: obrigatórias só no cadastro “completo”; permite salvar carga parcial
        var incompleto = portAuthEhCpfPendente(cpfSave) || !rg || !fotoP || !fotoV;

        var dupPlaca = (portaria_autorizados||[]).find(function(x){
          return x.ativo!==false && portAuthPlacaFmt(x.veiculo_placa)===placa && String(x.id)!==String(id||'');
        });
        if(dupPlaca){ progShowToast('⚠ Já existe autorizado ativo com esta placa.','erro'); return; }

        var userNome = (usuarioLogado && (usuarioLogado.nome||usuarioLogado.email)) || '';
        var dados = {
          nome: nome,
          rg: rg||null,
          cpf: cpfSave,
          cpf_digits: portAuthEhCpfPendente(cpfSave) ? null : cpf,
          setor: setor,
          veiculo_placa: placa,
          veiculo_marca: g('auth-marca').trim()|| (fv&&fv.marca) ||null,
          veiculo_modelo: g('auth-modelo').trim()|| (fv&&fv.modelo) ||null,
          veiculo_cor: g('auth-cor').trim()|| (fv&&fv.cor) ||null,
          veiculo_obs: g('auth-veic-obs').trim()||null,
          veiculo_id: fv ? String(fv.id) : (a.veiculo_id||null),
          frota_empresa: !!fv || !!a.frota_empresa,
          foto_pessoa: fotoP,
          foto_veiculo: fotoV,
          dados_completos: !incompleto,
          ativo: g('auth-ativo')!=='0',
          obs: g('auth-obs').trim()|| (fv?'Vinculado à frota empresa':null),
          atualizado_por: userNome
        };

        btn.disabled = true;
        btn.textContent = 'Salvando…';

        function ok(msg){
          closeModal();
          portaria_autorizados_loaded = false;
          progShowToast(msg);
          portRenderAutorizados();
        }
        function fail(err){
          btn.disabled = false;
          btn.textContent = isNew?'✅ Cadastrar':'Salvar';
          var m = (err && (err.message||err.hint||err.details)) || String(err||'');
          progShowToast('Erro ao salvar'+(m?': '+m:'')+'. Confirme se o SQL sql_portaria_autorizados.sql foi aplicado.','erro');
        }

        if(isNew){
          dados.status_acesso = 'Fora';
          dados.criado_por = userNome;
          dados.filial_id = (usuarioLogado && usuarioLogado.filial_id) || null;
          dados.portaria_id = _portAtiva ? _portAtiva.id : null;
          if(DEMO){
            dados.id = 'auth'+Date.now();
            portaria_autorizados.unshift(dados);
            ok('✅ Autorizado cadastrado: '+nome);
            return;
          }
          sbInsert('portaria_autorizados', dados).then(function(){ ok('✅ Autorizado cadastrado: '+nome); }).catch(fail);
        } else {
          if(DEMO){
            var idx = portaria_autorizados.findIndex(function(x){return String(x.id)===String(id);});
            if(idx>=0) portaria_autorizados[idx] = Object.assign({}, portaria_autorizados[idx], dados);
            ok('✅ Autorizado atualizado.');
            return;
          }
          sbUpdate('portaria_autorizados', dados, 'id=eq.'+id).then(function(){ ok('✅ Autorizado atualizado.'); }).catch(fail);
        }
      };
    }, 40);
  });
}

function portVerAutorizado(id){
  portCarregarAutorizados().then(function(){
    var a = portaria_autorizados.find(function(x){return String(x.id)===String(id);});
    if(!a) return;
    var st = a.status_acesso||'Fora';
    var cor = st==='No local'?'#3B6D11':'#854F0B';
    var bg  = st==='No local'?'#EAF3DE':'#FEF3E2';
    setModal('<div class="modal-bg"><div class="modal" style="max-width:480px;max-height:92vh;overflow-y:auto">'
      +'<div style="display:flex;gap:1rem;align-items:flex-start;margin-bottom:1rem">'
      +(a.foto_pessoa
        ?'<img src="'+a.foto_pessoa+'" style="width:72px;height:72px;border-radius:50%;object-fit:cover;border:2px solid #185FA5;flex-shrink:0">'
        :'<div style="width:72px;height:72px;border-radius:50%;background:#f0efe8;display:flex;align-items:center;justify-content:center;font-size:36px;flex-shrink:0">👤</div>')
      +'<div>'
      +'<div style="font-size:18px;font-weight:700">'+escHtml(a.nome||'—')+'</div>'
      +'<div style="font-size:12px;color:#888">CPF '+escHtml(portAuthCpfMask(a.cpf))+' · RG '+escHtml(a.rg||'—')+'</div>'
      +'<span style="background:'+bg+';color:'+cor+';border-radius:12px;padding:2px 10px;font-size:11px;font-weight:600">'+(a.ativo===false?'Inativo':escHtml(st))+'</span>'
      +'</div></div>'
      +'<table style="width:100%;font-size:12px;border-collapse:collapse">'
      +[
        ['🏢 Setor', a.setor],
        ['🚙 Placa', a.veiculo_placa],
        ['🏷️ Marca/Modelo', [a.veiculo_marca,a.veiculo_modelo].filter(Boolean).join(' ')||'—'],
        ['🎨 Cor', a.veiculo_cor],
        ['📝 Obs.', a.obs]
      ].map(function(row){
        return '<tr style="border-bottom:.5px solid #f5f5f3"><td style="padding:6px 8px;color:#888;width:120px">'+row[0]+'</td>'
          +'<td style="padding:6px 8px;font-weight:500">'+escHtml(row[1]||'—')+'</td></tr>';
      }).join('')
      +'</table>'
      +(a.foto_veiculo?'<div style="margin-top:.75rem"><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Veículo</label><img src="'+a.foto_veiculo+'" style="width:100%;border-radius:8px;max-height:200px;object-fit:contain;background:#f5f5f3"></div>':'')
      +'<div style="margin-top:1rem;display:flex;gap:8px;flex-wrap:wrap">'
      +'<button class="btn" onclick="closeModal()" style="flex:1">Fechar</button>'
      +(a.ativo!==false && st!=='No local'
        ?'<button class="btn btn-pri" style="flex:1;background:#3B6D11;border-color:#3B6D11" onclick="closeModal();portAuthLiberar(\''+a.id+'\',\'entrada\')">➡ Liberar entrada</button>'
        :'')
      +(a.ativo!==false && st==='No local'
        ?'<button class="btn btn-pri" style="flex:1" onclick="closeModal();portAuthLiberar(\''+a.id+'\',\'saida\')">↩ Liberar saída</button>'
        :'')
      +(portPodeCadastrarAutorizado()
        ?'<button class="btn port-auth-cadastro" style="flex:1" onclick="closeModal();portNovoAutorizado(\''+a.id+'\')">✎ Editar</button>'
        :'')
      +'</div></div></div>');
  });
}

function portAuthPreencherFrotaNoForm(){
  var placaEl=document.getElementById('auth-placa');
  var hint=document.getElementById('auth-frota-hint');
  if(!placaEl) return;
  var fv=portAuthBuscarFrotaPorPlaca(placaEl.value);
  if(hint){
    hint.textContent = fv
      ? ('✓ Encontrado na frota empresa: '+(fv.modelo||fv.marca||fv.placa))
      : 'Veículo externo — não será cadastrado na frota da empresa';
    hint.style.color = fv ? '#3B6D11' : '#854F0B';
  }
  if(!fv) return;
  var m=document.getElementById('auth-modelo'); if(m && !m.value) m.value=fv.modelo||'';
  var k=document.getElementById('auth-marca'); if(k && !k.value) k.value=fv.marca||'';
  var c=document.getElementById('auth-cor'); if(c && !c.value && fv.cor) c.value=fv.cor;
}

function portAuthLiberar(id, tipo){
  tipo = (tipo==='saida') ? 'saida' : 'entrada';
  portCarregarAutorizados().then(function(){
    var a = portaria_autorizados.find(function(x){return String(x.id)===String(id);});
    if(!a){ progShowToast('Autorizado não encontrado.','erro'); return; }
    if(a.ativo===false){ progShowToast('Autorizado inativo.','erro'); return; }
    var st = a.status_acesso||'Fora';
    if(tipo==='entrada' && st==='No local'){ progShowToast('Já está no local. Use Saída.','erro'); return; }
    if(tipo==='saida' && st!=='No local'){ progShowToast('Não está no local. Use Entrada.','erro'); return; }

    var agora = new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
    var novoStatus = tipo==='entrada' ? 'No local' : 'Fora';
    var userNome = (usuarioLogado && (usuarioLogado.nome||usuarioLogado.email)) || '';
    var mov = {
      autorizado_id: a.id,
      tipo: tipo,
      data: dataHojeLocal(),
      hora: agora,
      portaria_id: _portAtiva ? _portAtiva.id : null,
      liberado_por: userNome,
      observacao: null
    };

    function aplicarLocal(){
      a.status_acesso = novoStatus;
      progShowToast((tipo==='entrada'?'✅ Entrada':'✅ Saída')+' liberada: '+a.nome+' ('+agora+')');
      portRenderAutorizados();
    }

    if(DEMO){
      aplicarLocal();
      return;
    }

    if(typeof portOffTravar==='function' && !portOffTravar('AUTH:'+a.id+':'+tipo)){
      progShowToast('Aguarde, esta liberação já está em andamento.');
      return;
    }

    aplicarLocal();
    if(typeof portOffRegistrarAuth==='function'){
      portOffRegistrarAuth(mov, a);
      return;
    }

    sbUpdate('portaria_autorizados', { status_acesso: novoStatus, atualizado_por: userNome }, 'id=eq.'+a.id)
      .then(function(){
        return sbInsert('portaria_autorizados_mov', mov);
      })
      .catch(function(err){
        var m = (err && (err.message||err.hint)) || '';
        progShowToast('Erro na liberação'+(m?': '+m:'')+'.','erro');
      });
  });
}

function portToggleFotoAvaria(val){
  var label = document.getElementById('fpr-avaria-label');
  if(label){
    label.textContent = val==='sim' ? '⚠ Registre a avaria na foto' : 'Veículo sem avarias';
    label.style.color = val==='sim' ? '#A32D2D' : '#3B6D11';
  }
}


window._portFotoMem = window._portFotoMem || {};
function portFotoGuardar(id, dataUrl){
  window._portFotoMem = window._portFotoMem || {};
  if(id) window._portFotoMem[id] = dataUrl || null;
  var hid = document.getElementById(id);
  if(!hid) return;
  try{
    if(dataUrl && dataUrl.length < 60000) hid.value = dataUrl;
    else hid.value = dataUrl ? '[mem]' : '';
  }catch(e){ try{ hid.value=''; }catch(e2){} }
}
function portFotoLer(id){
  var mem = (window._portFotoMem||{})[id];
  if(mem && (String(mem).indexOf('data:image')===0 || /^https?:\/\//i.test(String(mem)))) return mem;
  var hid = document.getElementById(id);
  var v = hid && hid.value;
  if(v && String(v).indexOf('data:image')===0) return v;
  if(id==='port-km-foto' && _portKmOcr && _portKmOcr.km_foto_url) return _portKmOcr.km_foto_url;
  return null;
}
function portComprimirArquivo(file, opts){
  opts = opts || {};
  var MAX = opts.max || 480;      // lado máx. (px) — reduzido p/ tablets fracos
  var Q = opts.q || 0.5;          // qualidade JPEG inicial
  var LIMITE = opts.limite || 80000; // ~80KB por foto (base64 menor = sync mais leve)
  return new Promise(function(resolve){
    function canvasDe(imgW, imgH, draw){
      var w=imgW, h=imgH;
      if(w>MAX||h>MAX){ if(w>h){h=Math.round(h*MAX/w);w=MAX;} else {w=Math.round(w*MAX/h);h=MAX;} }
      var canvas=document.createElement('canvas');
      canvas.width=w; canvas.height=h;
      try{ draw(canvas.getContext('2d'), w, h); }catch(eD){ resolve(''); return; }
      var q=Q, out='';
      try{ out=canvas.toDataURL('image/jpeg', q); }catch(e){ try{canvas.width=canvas.height=0;}catch(_e){} resolve(''); return; }
      while(out && out.length>LIMITE && q>0.35){
        q-=0.08;
        try{ out=canvas.toDataURL('image/jpeg', q); }catch(e2){ break; }
      }
      try{ canvas.width=canvas.height=0; }catch(_c){} // libera a memória do canvas
      resolve(out||'');
    }
    // Tablets fracos reiniciavam ao decodificar a foto em resolução cheia (12MP).
    // createImageBitmap com resizeWidth decodifica JÁ reduzido (usa o downscale do
    // próprio decodificador JPEG) e não materializa a imagem inteira na memória.
    if(typeof createImageBitmap==='function'){
      createImageBitmap(file, {resizeWidth: MAX, resizeQuality: 'medium'}).then(function(bmp){
        canvasDe(bmp.width, bmp.height, function(ctx,w,h){ ctx.drawImage(bmp,0,0,w,h); });
        if(bmp.close) try{ bmp.close(); }catch(e){}
      }).catch(function(){
        // Fallback 1: createImageBitmap sem resize (WebView que ignora as opções)
        createImageBitmap(file).then(function(bmp){
          canvasDe(bmp.width, bmp.height, function(ctx,w,h){ ctx.drawImage(bmp,0,0,w,h); });
          if(bmp.close) try{ bmp.close(); }catch(e){}
        }).catch(function(){ viaReader(); });
      });
    } else viaReader();
    function viaReader(){
      var reader=new FileReader();
      reader.onload=function(e){
        var img=new Image();
        img.onload=function(){
          canvasDe(img.width, img.height, function(ctx,w,h){ ctx.drawImage(img,0,0,w,h); });
        };
        img.onerror=function(){ resolve(''); };
        img.src=e.target.result;
      };
      reader.onerror=function(){ resolve(''); };
      reader.readAsDataURL(file);
    }
  });
}

function portFotoPreview(input, previewId, hiddenId){
  var file = input.files && input.files[0]; if(!file) return;
  portComprimirArquivo(file).then(function(b64){
    if(!b64){ progShowToast('Não foi possível ler a foto. Tire de novo.','erro'); return; }
    portFotoGuardar(hiddenId, b64);
    var prev = document.getElementById(previewId);
    if(prev) prev.innerHTML = '<img src="'+b64+'" style="width:100%;height:100%;object-fit:cover">';
  });
}

// ══ FASE 2 — KM Portaria com foto / OCR ═══════════════════════
var _portKmOcr={km_lido_ocr:null,km_foto_url:null,km_ocr_confianca:null,targetId:null};
var PORT_KM_SALTO_ALERTA=5000; // km
var PORT_KM_CONF_BAIXA=0.5;

function portKmResetOcr(){
  _portKmOcr={km_lido_ocr:null,km_foto_url:null,km_ocr_confianca:null,targetId:null};
  if(typeof portFotoGuardar==='function') portFotoGuardar('port-km-foto', null);
}
function portKmParseTs(d){
  if(d==null || d==='') return 0;
  if(typeof d==='number') return isNaN(d)?0:d;
  var s=String(d).trim();
  if(!s) return 0;
  var t=new Date(s).getTime();
  if(!isNaN(t)) return t;
  t=new Date(s.replace(' ','T')).getTime();
  return isNaN(t)?0:t;
}
function portKmTsRegistro(p){
  if(!p) return 0;
  return portKmParseTs(p.data_retorno || p.data_saida || p.atualizado_em || p.criado_em || p.km_ajustado_em);
}
function portKmAjusteMaisRecente(placa, opts){
  opts = opts||{};
  var pl = portNormPlaca(placa);
  if(!pl) return null;
  var best=null, bestT=-1;
  (frt_portaria||[]).forEach(function(p){
    if(!p || portNormPlaca(p.placa)!==pl) return;
    if(opts.excluirId && String(p.id)===String(opts.excluirId)) return;
    if(p.status==='Cancelado' || p.deleted_at) return;
    var tm=portKmParseTs(p.km_ajustado_em);
    if(tm>bestT){ bestT=tm; best=p; }
  });
  return bestT>0 ? best : null;
}
/** Último registro cronológico da placa (saída/retorno). Ajuste de KM nele redefine a base. */
function portKmUltimoRegistroPlaca(placa, opts){
  opts = opts||{};
  var pl = portNormPlaca(placa);
  if(!pl) return null;
  var list = (frt_portaria||[]).filter(function(p){
    if(portNormPlaca(p.placa)!==pl) return false;
    if(opts.excluirId && String(p.id)===String(opts.excluirId)) return false;
    if(p.status==='Cancelado' || p.deleted_at) return false;
    return true;
  });
  if(!list.length) return null;
  list.sort(function(a,b){
    var ta=portKmTsRegistro(a), tb=portKmTsRegistro(b);
    if(tb!==ta) return tb-ta;
    return String(b.id||'').localeCompare(String(a.id||''));
  });
  return list[0];
}
function portKmValorDoRegistro(p){
  if(!p) return 0;
  var saida=parseFloat(p.km_saida)||0;
  var ret=parseFloat(p.km_retorno)||0;
  try{
    var hist=typeof portKmAjustesLista==='function'?portKmAjustesLista(p):[];
    var ev=hist.length?hist[hist.length-1]:null;
    if(ev){
      if(ev.km_saida_depois!=null && ev.km_saida_depois!=='') saida=parseFloat(ev.km_saida_depois)||saida;
      if(ev.km_retorno_depois!=null && ev.km_retorno_depois!=='') ret=parseFloat(ev.km_retorno_depois)||ret;
    }
  }catch(eAj){}
  return Math.max(saida, ret);
}
/** Saída ainda sem retorno (qualquer dia) — exceção ao liberar nova saída. */
/** Rebusca as saídas recentes de UMA placa e reconcilia a memória (status atualizado por
 *  outro tablet/turno). Evita bloqueio falso por dado velho na memória. */
function portRefrescarSaidasPlaca(placa){
  if(DEMO || typeof sbFetch!=='function' || !placa) return Promise.resolve();
  var sel=(typeof PORT_SAIDA_SEL_LISTA!=='undefined')?PORT_SAIDA_SEL_LISTA:'*';
  return sbFetch('frotas_portaria_saidas',{select:sel, filters:['placa=eq.'+encodeURIComponent(placa)], order:'data_saida.desc', limit:60})
    .then(function(rows){ if(rows && rows.length && typeof portMesclarSaidas==='function') portMesclarSaidas(rows); })
    .catch(function(){});
}
function portKmSaidaAbertaSemRetorno(placa, opts){
  opts = opts||{};
  var pl = portNormPlaca(placa);
  if(!pl) return null;
  var list = (frt_portaria||[]).filter(function(p){
    if(portNormPlaca(p.placa)!==pl) return false;
    if(opts.excluirId && String(p.id)===String(opts.excluirId)) return false;
    if(p.status==='Cancelado' || p.deleted_at) return false;
    // FECHADA = status Retornado OU tem data_retorno OU tem km_retorno.
    // Inclui encerramento administrativo (Retornado + data_retorno, SEM km) — que antes
    // era tratado como "aberta" por não ter km_retorno e travava novas saídas.
    if(p.status==='Retornado') return false;
    if(p.data_retorno) return false;
    var temRet = p.km_retorno!=null && p.km_retorno!=='' && !isNaN(parseFloat(p.km_retorno));
    return !temRet;
  });
  if(!list.length) return null;
  list.sort(function(a,b){
    var ta=portKmTsRegistro(a), tb=portKmTsRegistro(b);
    if(tb!==ta) return tb-ta;
    return String(b.id||'').localeCompare(String(a.id||''));
  });
  return list[0];
}
/**
 * Última KM da placa = KM do último registro (saída ou retorno).
 * Ajuste no último registro passa a valer; registros anteriores não elevam a base.
 */
function portKmUltimoRegistrado(placa, opts){
  opts = opts||{};
  var reg = portKmUltimoRegistroPlaca(placa, opts);
  var aj = typeof portKmAjusteMaisRecente==='function' ? portKmAjusteMaisRecente(placa, opts) : null;
  var veic=(frt_veiculos||[]).find(function(v){return portNormPlaca(v.placa)===portNormPlaca(placa);});
  var fromVeic = veic && parseFloat(veic.km_atual)>0 ? parseFloat(veic.km_atual) : 0;
  var fromReg = portKmValorDoRegistro(reg);
  var fromAj = portKmValorDoRegistro(aj);
  if(aj && fromAj>0){
    var ajEhUltimo = !reg || String(reg.id)===String(aj.id);
    var mesmaViagem = false;
    if(reg && !ajEhUltimo){
      var ta=portKmTsRegistro(aj), tb=portKmTsRegistro(reg);
      if(ta && tb && Math.abs(ta-tb)<=120000) mesmaViagem=true;
      else {
        var da=typeof portDiaLocal==='function'?portDiaLocal(aj.data_saida):String(aj.data_saida||'').slice(0,10);
        var db=typeof portDiaLocal==='function'?portDiaLocal(reg.data_saida):String(reg.data_saida||'').slice(0,10);
        var ea=aj.equipe_id||aj.equipe||'';
        var eb=reg.equipe_id||reg.equipe||'';
        if(da && da===db && ea && String(ea)===String(eb)) mesmaViagem=true;
      }
    }
    if(ajEhUltimo || mesmaViagem) return fromAj;
  }
  if(fromReg>0 && fromVeic>0 && fromVeic<fromReg && aj) return fromVeic;
  if(fromReg>0) return fromReg;
  return fromVeic||0;
}
/**
 * Valida KM informado vs histórico/OCR.
 * @returns {{ok:boolean, msgs:string[], bloqueia:boolean, saidaAberta:object|null, sugestaoKm:number|null}}
 */
function portKmValidarAlertas(placa, kmInformado, confianca){
  var msgs=[], bloqueia=false;
  var km=parseFloat(kmInformado)||0;
  var saidaAberta=null, sugestaoKm=null;
  saidaAberta = portKmSaidaAbertaSemRetorno(placa);
  if(saidaAberta){
    var kmAb0 = parseFloat(saidaAberta.km_saida)||0;
    sugestaoKm = kmAb0 || null;
    var quando0 = saidaAberta.data_saida
      ? (typeof fmtDT==='function'?fmtDT(saidaAberta.data_saida):String(saidaAberta.data_saida).slice(0,16))
      : '—';
    msgs.push('Não foi dado retorno da saída anterior'
      +(saidaAberta.equipe?' ('+saidaAberta.equipe+')':'')
      +' em '+quando0
      +' com KM de saída '+kmAb0.toLocaleString('pt-BR')
      +'. Informe KM igual ao da saída anterior ('+kmAb0.toLocaleString('pt-BR')+') ou registre o retorno antes.');
  }
  if(!km){
    msgs.push('Informe o KM do odômetro.');
    bloqueia=true;
    return {ok:false,msgs:msgs,bloqueia:true,saidaAberta:saidaAberta,sugestaoKm:sugestaoKm};
  }
  if(saidaAberta){
    var kmAb = parseFloat(saidaAberta.km_saida)||0;
    if(kmAb>0 && km<kmAb){
      msgs.push('KM informado ('+km.toLocaleString('pt-BR')+') é menor que o KM da saída sem retorno ('+kmAb.toLocaleString('pt-BR')+').');
      bloqueia=true;
    }
  }

  var ultimo=portKmUltimoRegistrado(placa);
  if(ultimo>0 && km<ultimo){
    msgs.push('KM informado ('+km.toLocaleString('pt-BR')+') é menor que a última KM registrada desta placa ('+ultimo.toLocaleString('pt-BR')+'). Corrija o odômetro — a saída está bloqueada.');
    bloqueia=true;
  }
  if(ultimo>0 && (km-ultimo)>PORT_KM_SALTO_ALERTA){
    msgs.push('Salto de KM muito grande: +'+(km-ultimo).toLocaleString('pt-BR')+' km desde o último registro ('+ultimo.toLocaleString('pt-BR')+').');
  }
  if(confianca!=null && confianca<PORT_KM_CONF_BAIXA){
    msgs.push('Confiança da leitura OCR baixa ('+Math.round(confianca*100)+'%). Revise o KM antes de liberar.');
  }
  return {ok:msgs.length===0, msgs:msgs, bloqueia:bloqueia, saidaAberta:saidaAberta, sugestaoKm:sugestaoKm};
}
/** Próxima saída da placa DEPOIS desta (vizinho cronológico à frente). Base p/ o teto do KM de retorno em back-fill. */
function portKmProxSaidaApos(placa, saida){
  var pl=portNormPlaca(placa);
  var t0=saida&&saida.data_saida?new Date(saida.data_saida).getTime():0;
  if(!pl||!t0||isNaN(t0)) return null;
  var cands=(frt_portaria||[]).filter(function(p){
    if(!p || portNormPlaca(p.placa)!==pl) return false;
    if(saida && String(p.id)===String(saida.id)) return false;
    if(p.status==='Cancelado' || p.deleted_at) return false;
    var t=p.data_saida?new Date(p.data_saida).getTime():0;
    return t && !isNaN(t) && t>t0;
  });
  if(!cands.length) return null;
  cands.sort(function(a,b){ return new Date(a.data_saida).getTime()-new Date(b.data_saida).getTime(); });
  return cands[0];
}
/** Faixa válida do KM de retorno: entre o KM de saída dela e o KM da PRÓXIMA saída da placa. */
function portKmFaixaRetorno(saida){
  var min=parseFloat(saida&&saida.km_saida)||0;
  var prox=portKmProxSaidaApos(saida&&saida.placa, saida);
  var max=prox?(parseFloat(prox.km_saida)||0):0;
  return {min:min, max:(max>0?max:null), prox:prox};
}
/** KM de retorno: entre o KM de saída (mín.) e o KM da PRÓXIMA saída da placa (teto). NÃO usa a última KM (que pode ser muito maior num back-fill). */
function portKmValidarRetorno(saida, kmInformado){
  var msgs=[], bloqueia=false;
  var km=parseFloat(kmInformado)||0;
  if(!km){ return {ok:false, msgs:['Informe o KM de retorno do odômetro.'], bloqueia:true}; }
  var faixa=portKmFaixaRetorno(saida);
  if(faixa.min>0 && km<faixa.min){
    msgs.push('KM retorno ('+km.toLocaleString('pt-BR')+') é menor que o KM de saída ('+faixa.min.toLocaleString('pt-BR')+').');
    bloqueia=true;
  }
  if(faixa.max!=null && km>faixa.max){
    var qP=faixa.prox&&faixa.prox.data_saida?(typeof fmtDT==='function'?fmtDT(faixa.prox.data_saida):String(faixa.prox.data_saida).slice(0,16)):'—';
    msgs.push('KM retorno ('+km.toLocaleString('pt-BR')+') é maior que o KM da próxima saída desta placa ('+faixa.max.toLocaleString('pt-BR')+' em '+qP+'). O retorno deve ficar entre '+faixa.min.toLocaleString('pt-BR')+' e '+faixa.max.toLocaleString('pt-BR')+'.');
    bloqueia=true;
  }
  return {ok:!bloqueia, msgs:msgs, bloqueia:bloqueia, faixa:faixa};
}
/** Bloco HTML: campo KM + foto odômetro + OCR (reuso Diário). */
function portKmWidgetHtml(inputId, opts){
  opts=opts||{};
  var label=opts.label||'KM saída / odômetro';
  var val=opts.value!=null?opts.value:'';
  var req=opts.obrigatorio!==false;
  return '<div class="fg" style="margin-bottom:.5rem" id="port-km-wrap">'
    +'<label style="font-size:11px;font-weight:600">'+escHtml(label)+(req?' <span style="color:#A32D2D">*</span>':'')+'</label>'
    +'<div style="display:flex;gap:6px;align-items:center">'
    +'<input class="inp" id="'+inputId+'" type="number" style="flex:1" placeholder="Ex: 45230" value="'+escHtml(String(val))+'"'
    +' oninput="portKmOnManualEdit(\''+inputId+'\')"/>'
    +'<button type="button" class="btn" onclick="portAbrirCameraOdometro(\''+inputId+'\')" title="Fotografar odômetro e ler com IA"'
    +' style="background:#3B6D11;color:#fff;border-color:#3B6D11;white-space:nowrap;padding:8px 12px">📷 OCR</button>'
    +'</div>'
    +'<div style="display:flex;gap:8px;align-items:flex-start;margin-top:6px">'
    +'<label style="cursor:pointer;background:#185FA5;color:#fff;border-radius:8px;padding:6px 10px;font-size:11px;font-weight:600;white-space:nowrap">'
    +'📸 Foto odômetro'
    +'<input type="file" accept="image/*" capture="environment" style="display:none" '
    +'onchange="portKmFotoManual(this,\''+inputId+'\')">'
    +'</label>'
    +'<div id="port-km-prev" style="width:72px;height:54px;background:#f0f0f0;border-radius:6px;overflow:hidden;border:.5px solid #e0dfd8;flex-shrink:0">'
    +'<div style="display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:9px;text-align:center">Sem<br>foto</div>'
    +'</div>'
    +'</div>'
    +'<input type="hidden" id="port-km-foto" value=""/>'
    +'<input type="hidden" id="port-km-ocr" value=""/>'
    +'<input type="hidden" id="port-km-conf" value=""/>'
    +'<div id="port-km-status" style="font-size:10px;color:#888;margin-top:4px">Tire foto do odômetro. OCR preenche o KM — revise antes de liberar. KM menor que o último da placa bloqueia a saída.</div>'
    +'<div id="port-km-alertas" style="display:none;margin-top:6px"></div>'
    +'</div>';
}
function portKmOnManualEdit(inputId){
  // Usuário revisou/corrigiu — mantém foto e km_lido_ocr originais
  var st=document.getElementById('port-km-status');
  if(st && _portKmOcr.km_lido_ocr!=null){
    st.textContent='KM editado manualmente após OCR ('+_portKmOcr.km_lido_ocr+'). Confirme antes de liberar.';
    st.style.color='#854F0B';
  }
  portKmMostrarAlertasPlaca(inputId);
}
function portKmMostrarAlertasPlaca(inputId){
  var inp=document.getElementById(inputId);
  var box=document.getElementById('port-km-alertas');
  if(!inp||!box) return;
  var placa=((document.getElementById('port-chk-placa')||{}).value)
    || ((document.querySelector('[data-port-placa]')||{}).getAttribute&&document.querySelector('[data-port-placa]').getAttribute('data-port-placa'))
    || window._portKmPlacaCtx || '';
  var conf=parseFloat((document.getElementById('port-km-conf')||{}).value);
  if(isNaN(conf)) conf=_portKmOcr.km_ocr_confianca;
  var v=portKmValidarAlertas(placa, inp.value, conf);
  if(!v.msgs.length){ box.style.display='none'; box.innerHTML=''; return; }
  box.style.display='block';
  var bg=v.bloqueia?'#FCEBEB':'#FEF3E2';
  var bd=v.bloqueia?'#A32D2D55':'#F59E0B55';
  var cor=v.bloqueia?'#A32D2D':'#854F0B';
  var ico=v.bloqueia?'🚫':'⚠';
  var sugHtml='';
  if(v.sugestaoKm!=null && v.sugestaoKm>0){
    sugHtml='<div style="margin-top:6px"><button type="button" class="btn btn-sm" style="background:#854F0B;color:#fff;border-color:#854F0B"'
      +' onclick="(function(){var el=document.getElementById(\''+String(inputId).replace(/'/g,"\\'")+'\');'
      +'if(el){el.value=\''+v.sugestaoKm+'\';portKmMostrarAlertasPlaca(\''+String(inputId).replace(/'/g,"\\'")+'\');}})()">Usar KM '+Number(v.sugestaoKm).toLocaleString('pt-BR')+' (saída sem retorno)</button></div>';
  }
  box.innerHTML='<div style="background:'+bg+';border:.5px solid '+bd+';border-radius:6px;padding:6px 8px;font-size:11px;color:'+cor+'">'
    +v.msgs.map(function(m){return ico+' '+escHtml(m);}).join('<br>')+sugHtml+'</div>';
}
function portKmSetPreview(b64){
  var prev=document.getElementById('port-km-prev');
  portFotoGuardar('port-km-foto', b64||null);
  _portKmOcr.km_foto_url=b64||null;
  if(prev){
    if(b64) prev.innerHTML='<img src="'+b64+'" style="width:100%;height:100%;object-fit:cover">';
    else prev.innerHTML='<div style="display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:9px;text-align:center">Sem<br>foto</div>';
  }
}
function portKmFotoManual(input, targetInputId){
  var file=input.files&&input.files[0]; if(!file) return;
  portComprimirArquivo(file,{max:520,q:0.5}).then(function(b64){
    if(!b64){ progShowToast('Não foi possível ler a foto do odômetro. Tire de novo.','erro'); return; }
    portKmSetPreview(b64);
    var st=document.getElementById('port-km-status');
    if(st){ st.textContent='Foto anexada. Informe o KM manualmente ou use OCR.'; st.style.color='#185FA5'; }
  });
}
/** OCR odômetro — mesmo proxy do Diário de Bordo; grava evidência + confiança. */
function portAbrirCameraOdometro(targetInputId){
  portKmResetOcr();
  _portKmOcr.targetId=targetInputId;
  var inp=document.createElement('input');
  inp.type='file'; inp.accept='image/*'; inp.capture='environment'; inp.style.display='none';
  document.body.appendChild(inp);
  inp.onchange=function(){
    if(!inp.files||!inp.files[0]){ document.body.removeChild(inp); return; }
    var file=inp.files[0];
    document.body.removeChild(inp);
    if(file.size>4*1024*1024){ progShowToast('Foto muito grande (máx. ~4 MB).','erro'); return; }
    var target=document.getElementById(targetInputId);
    var st=document.getElementById('port-km-status');
    if(target){ target.placeholder='📷 Analisando...'; target.disabled=true; }
    if(st){ st.textContent='📷 Lendo odômetro com IA...'; st.style.color='#555'; }
    var reader=new FileReader();
    reader.onload=function(e){
      var dataUrl=e.target.result;
      portComprimirArquivo(file,{max:480,q:0.5}).then(function(b64Prev){
        if(b64Prev) portKmSetPreview(b64Prev);
        else progShowToast('Não foi possível compactar a foto do odômetro. Tire de novo.','erro');
      });

      var base64=String(dataUrl).split(',')[1];
      var mediaType=file.type||'image/jpeg';
      fetch('https://cena-proxy.marcos-afe.workers.dev',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({
          model:'claude-sonnet-4-5',
          max_tokens:100,
          messages:[{
            role:'user',
            content:[
              {type:'image', source:{type:'base64', media_type:mediaType, data:base64}},
              {type:'text', text:'Esta é uma foto do odômetro de um veículo. Responda APENAS com o número inteiro do KM mostrado no odômetro, sem pontos, vírgulas ou texto. Exemplo: 45230. Se não conseguir ler, responda: ERRO'}
            ]
          }]
        })
      })
      .then(function(r){ return r.json(); })
      .then(function(data){
        if(target){ target.disabled=false; target.placeholder='Ex: 45230'; }
        var resp=data.content&&data.content[0]?String(data.content[0].text||'').trim():'ERRO';
        var km=parseInt(resp.replace(/\D/g,''),10);
        if(isNaN(km)||resp==='ERRO'){
          _portKmOcr.km_lido_ocr=null;
          _portKmOcr.km_ocr_confianca=0;
          var hO=document.getElementById('port-km-ocr'); if(hO) hO.value='';
          var hC=document.getElementById('port-km-conf'); if(hC) hC.value='0';
          if(st){ st.textContent='Não foi possível ler o odômetro. Informe o KM manualmente (foto já salva).'; st.style.color='#A32D2D'; }
          progShowToast('OCR não leu o KM. Digite manualmente e revise.','erro');
        } else {
          _portKmOcr.km_lido_ocr=km;
          _portKmOcr.km_ocr_confianca=0.85;
          var hO2=document.getElementById('port-km-ocr'); if(hO2) hO2.value=String(km);
          var hC2=document.getElementById('port-km-conf'); if(hC2) hC2.value='0.85';
          if(target){
            target.value=km;
            target.style.background='#EAF3DE';
            target.style.color='#3B6D11';
          }
          if(st){ st.textContent='✅ KM lido: '+km.toLocaleString('pt-BR')+' — revise e confirme antes de liberar.'; st.style.color='#3B6D11'; }
          progShowToast('KM lido: '+km.toLocaleString('pt-BR')+' km — confirme se está correto.');
          portKmMostrarAlertasPlaca(targetInputId);
        }
      })
      .catch(function(err){
        console.warn('[Portaria OCR]',err);
        if(target){ target.disabled=false; target.placeholder='Ex: 45230'; }
        _portKmOcr.km_ocr_confianca=0;
        var hC3=document.getElementById('port-km-conf'); if(hC3) hC3.value='0';
        if(st){ st.textContent='OCR indisponível. Informe o KM manualmente (foto já salva como evidência).'; st.style.color='#854F0B'; }
        progShowToast('OCR indisponível. Digite o KM e mantenha a foto.','erro');
      });
    };
    reader.readAsDataURL(file);
  };
  inp.click();
}
/** Coleta metadados KM/OCR dos campos ocultos + estado. */
function portKmColetarMeta(){
  var foto=portFotoLer('port-km-foto')||_portKmOcr.km_foto_url||null;
  var ocrRaw=((document.getElementById('port-km-ocr')||{}).value);
  var confRaw=((document.getElementById('port-km-conf')||{}).value);
  var ocr=ocrRaw!==''&&ocrRaw!=null?parseFloat(ocrRaw):( _portKmOcr.km_lido_ocr!=null?_portKmOcr.km_lido_ocr:null);
  var conf=confRaw!==''&&confRaw!=null?parseFloat(confRaw):(_portKmOcr.km_ocr_confianca!=null?_portKmOcr.km_ocr_confianca:null);
  return {
    km_foto_url: foto||null,
    km_lido_ocr: (ocr!=null && !isNaN(ocr))?ocr:null,
    km_ocr_confianca: (conf!=null && !isNaN(conf))?conf:null,
    km_confirmado_por: portNomePorteiroAtual(),
    km_confirmado_em: new Date().toISOString()
  };
}
/**
 * Valida KM+foto antes de liberar. Retorna meta ou null se bloqueado.
 * @param {string} placa
 * @param {number|string} kmInformado
 * @param {{fotoObrigatoria?:boolean}} opts
 */
function portKmPrepararLiberacao(placa, kmInformado, opts){
  opts=opts||{};
  var meta=portKmColetarMeta();
  var fotoObr=opts.fotoObrigatoria!==false;
  if(fotoObr && !meta.km_foto_url){
    progShowToast('⚠ Obrigatório: foto do odômetro antes de liberar (OCR ou foto manual).','erro');
    return null;
  }
  var v=portKmValidarAlertas(placa, kmInformado, meta.km_ocr_confianca);
  if(v.bloqueia){
    progShowToast(v.msgs[0]||'KM inválido.','erro');
    return null;
  }
  if(v.msgs.length){
    var ok=confirm('Alertas de KM:\n\n• '+v.msgs.join('\n• ')+'\n\nDeseja liberar mesmo assim?');
    if(!ok) return null;
  }
  return meta;
}
function portKmAnexarSaida(saida, meta){
  if(!saida||!meta) return saida;
  saida.km_lido_ocr=meta.km_lido_ocr;
  saida.km_foto_url=meta.km_foto_url||null;
  saida.km_ocr_confianca=meta.km_ocr_confianca;
  saida.km_confirmado_por=meta.km_confirmado_por||portNomePorteiroAtual();
  saida.km_confirmado_em=meta.km_confirmado_em;
  return saida;
}

function portPickCols(obj, keys){
  var o={};
  (keys||[]).forEach(function(k){
    if(obj[k]!==undefined && obj[k]!==null && obj[k]!=='') o[k]=obj[k];
  });
  return o;
}
function portOptsContratoHtml(selectedId){
  var list=(contratos||[]).filter(function(c){ return c && c.ativo!==false; });
  return '<option value="">Selecione o contrato...</option>'+list.map(function(c){
    var lab=((c.codigo||c.numero)?(c.codigo||c.numero)+' — ':'')+(c.nome||c.id);
    return '<option value="'+escHtml(String(c.id))+'"'+(String(c.id)===String(selectedId||'')?' selected':'')+'>'+escHtml(lab)+'</option>';
  }).join('');
}
function portFotoEncolher(dataUrl, maxLen){
  maxLen=maxLen||100000;
  return new Promise(function(resolve){
    if(!dataUrl || String(dataUrl).indexOf('data:image')!==0){ resolve(dataUrl||''); return; }
    if(dataUrl.length<=maxLen){ resolve(dataUrl); return; }
    var img=new Image();
    img.onload=function(){
      function tryDraw(side, q){
        var w=img.width, h=img.height;
        if(w>side||h>side){ if(w>h){h=Math.round(h*side/w);w=side;} else {w=Math.round(w*side/h);h=side;} }
        var canvas=document.createElement('canvas');
        canvas.width=w; canvas.height=h;
        canvas.getContext('2d').drawImage(img,0,0,w,h);
        try{ return canvas.toDataURL('image/jpeg', q); }catch(e){ return ''; }
      }
      var q=0.6, side=520, out=tryDraw(side,q);
      while(out && out.length>maxLen && (q>0.34 || side>260)){
        if(q>0.34) q-=0.08;
        else { side=Math.round(side*0.75); q=0.52; }
        out=tryDraw(side,q);
      }
      resolve(out||dataUrl);
    };
    img.onerror=function(){ resolve(dataUrl); };
    img.src=dataUrl;
  });
}
function portDataUrlToBlob(dataUrl, nome){
  if(!dataUrl || String(dataUrl).indexOf('data:')!==0) return null;
  var parts=String(dataUrl).split(',');
  var mime=(parts[0].match(/:(.*?);/)||[])[1]||'image/jpeg';
  try{
    var bin=atob(parts[1]||'');
    var u8=new Uint8Array(bin.length);
    for(var i=0;i<bin.length;i++) u8[i]=bin.charCodeAt(i);
    try{ return new File([u8], nome||'foto.jpg', {type:mime}); }
    catch(e1){ var b=new Blob([u8],{type:mime}); b.name=nome||'foto.jpg'; return b; }
  }catch(e){ return null; }
}
async function portUploadFotoSaida(dataUrl, prefixo){
  if(!dataUrl) return null;
  var s=String(dataUrl);
  if(s.charAt(0)==='[') return null;
  if(/^https?:\/\//i.test(s)) return s;
  if(s.indexOf('data:')!==0) return null;
  var compact=s;
  try{ compact=await portFotoEncolher(s, 100000); }catch(e){ compact=s; }
  if(!(compact && compact.indexOf('data:image')===0)) compact=s;
  // Storage é opcional e em segundo plano: o Ver mostra o JPEG gravado no registro
  // (URL pública do bucket costuma dar 403 no tablet — a foto de retorno já funciona assim).
  try{
    var blob=portDataUrlToBlob(compact, (prefixo||'foto')+'.jpg');
    if(blob && typeof SB!=='undefined' && SB.url){
      var dia=(typeof dataHojeLocal==='function'?dataHojeLocal():'dia');
      var path='frotas/portaria/'+dia+'/'+Date.now()+'_'+Math.random().toString(36).slice(2,8)+'_'+(prefixo||'foto')+'.jpg';
      var tipo=(blob.type && String(blob.type).indexOf('image/')===0)?blob.type:'image/jpeg';
      var enc=path.split('/').map(encodeURIComponent).join('/');
      var url=SB.url+'/storage/v1/object/cena-docs/'+enc;
      var h={'apikey':SB.key,'Authorization':'Bearer '+(_sbAuthToken||SB.key),'Content-Type':tipo,'x-upsert':'true'};
      fetch(url,{method:'POST',headers:h,body:blob}).catch(function(){});
    }
  }catch(e){}
  return compact;
}

async function portPatchFotoCampo(id, campo, valor){
  if(!id || !campo || valor==null || valor==='') return false;
  if(typeof isUUID==='function' && !isUUID(String(id))) return false;
  var o={}; o[campo]=valor;
  var ok=await sbUpdate('frotas_portaria_saidas', o, 'id=eq.'+id);
  return !!ok;
}
function portFotoCampoSrc(f){
  if(!f) return '';
  if(typeof f==='string') return f;
  return f.url||f.b64||f.src||'';
}

/** Insere uma NOVA saída e grava cada foto no mesmo formato da carga (texto). */
async function portInsertSaidaDB(saida){
  if(DEMO||!saida) return null;
  var kmUrl=await portUploadFotoSaida(saida.km_foto_url,'km');
  var cargaUrl=await portUploadFotoSaida(saida.foto_carga_saida_b64,'carga');
  var extras=[];
  var extraSrc=Array.isArray(saida.fotos_carga_extras)?saida.fotos_carga_extras:[];
  for(var i=0;i<extraSrc.length;i++){
    var f=extraSrc[i];
    var src=portFotoCampoSrc(f);
    var url=await portUploadFotoSaida(src,'extra_'+i);
    if(url) extras.push({i:i, nome:(f&&f.nome)||('extra_'+(i+1)), url:url, b64:url});
  }
  if(kmUrl) saida.km_foto_url=kmUrl;
  if(cargaUrl) saida.foto_carga_saida_b64=cargaUrl;
  saida.fotos_carga_extras=extras;

  var coreKeys=['id','placa','modelo','tipo_liberacao','destino','km_saida','data_saida','status',
    'previsao_retorno','equipe','equipe_id','motorista','contrato_id','contrato_nome',
    'base_saida','quem_saiu','liberado_por','obs','veiculo_id'];
  // Colunas do sql_portaria_offline_1 (offline_event_id/dispositivo_id/sincronizado_em/etc.) NÃO
  // existem na tabela (SQL não aplicado) — não enviar, senão o insert dá 400 PGRST204.
  var core=portPickCols(saida, coreKeys);
  if(core.equipe_id && typeof isUUID==='function' && !isUUID(String(core.equipe_id))) delete core.equipe_id;
  if(core.id && typeof isUUID==='function' && !isUUID(String(core.id))) delete core.id;

  var r=await sbInsert('frotas_portaria_saidas', core, {silent:true});
  if(!r){
    var semOff=portPickCols(saida, ['id','placa','modelo','tipo_liberacao','destino','km_saida','data_saida','status',
      'previsao_retorno','equipe','equipe_id','motorista','contrato_id','contrato_nome',
      'base_saida','quem_saiu','liberado_por','obs','veiculo_id']);
    if(semOff.equipe_id && typeof isUUID==='function' && !isUUID(String(semOff.equipe_id))) delete semOff.equipe_id;
    if(semOff.id && typeof isUUID==='function' && !isUUID(String(semOff.id))) delete semOff.id;
    r=await sbInsert('frotas_portaria_saidas', semOff, {silent:true});
  }
  if(!r){
    var mini=portPickCols(saida, ['placa','km_saida','data_saida','status','equipe','equipe_id','motorista','liberado_por','obs','base_saida','contrato_id','contrato_nome','destino']);
    r=await sbInsert('frotas_portaria_saidas', mini, {silent:true});
  }
  if(!r) r=await sbInsert('frotas_portaria_saidas', core);
  if(r && r[0] && r[0].id) saida.id=r[0].id;
  var id=saida.id;
  if(id && typeof isUUID==='function' && isUUID(String(id))){
    var km=saida.km_foto_url;
    var carga=saida.foto_carga_saida_b64;
    var okKm=await portPatchFotoCampo(id,'km_foto_url', km);
    if(!okKm) okKm=await portPatchFotoCampo(id,'foto_odometro_b64', km);
    var okCarga=await portPatchFotoCampo(id,'foto_carga_saida_b64', carga);
    await portPatchFotoCampo(id,'foto_carga_saida_ts', saida.foto_carga_saida_ts);
    var okEx=true;
    if(extras.length){
      okEx=await portPatchFotoCampo(id,'fotos_carga_extras', extras);
      var e0=portFotoCampoSrc(extras[0]);
      var e1=extras[1]?portFotoCampoSrc(extras[1]):'';
      var okE1=e0?await portPatchFotoCampo(id,'foto_extra_1_b64', e0):true;
      var okE2=e1?await portPatchFotoCampo(id,'foto_extra_2_b64', e1):true;
      if(!okEx) okEx=okE1 && (!e1 || okE2);
    }
    if((km && !okKm) || (extras.length && !okEx)){
      var pack=JSON.stringify({v:1, carga:carga||null, km:km||null, extras:extras||[]});
      var okPack=await portPatchFotoCampo(id,'foto_carga_saida_b64', pack);
      if(!okPack && carga && !okCarga) await portPatchFotoCampo(id,'foto_carga_saida_b64', carga);
    }
    await portPatchFotoCampo(id,'km_lido_ocr', saida.km_lido_ocr);
    await portPatchFotoCampo(id,'km_ocr_confianca', saida.km_ocr_confianca);
    await portPatchFotoCampo(id,'km_confirmado_por', saida.km_confirmado_por);
    await portPatchFotoCampo(id,'tem_materiais_saida', saida.tem_materiais_saida);
  }
  return r;
}

function portFotosExtraAdd(input){
  var files=input&&input.files?Array.prototype.slice.call(input.files):[];
  if(!files.length) return;
  var arr=portFotosExtraColetar();
  var pending=files.length;
  files.forEach(function(file){
    portComprimirArquivo(file,{max:480,q:0.5}).then(function(b64){
      if(b64) arr.push({nome:file.name||('foto.jpg'), b64:b64});
      pending--;
      portFotosExtraPersist(arr);
      if(pending<=0 && input) input.value='';
    });
  });
}
function portFotosExtraPersist(arr){
  window._portFotoMem = window._portFotoMem || {};
  window._portFotoMem['lib-fotos-extra-json'] = arr;
  var hid=document.getElementById('lib-fotos-extra-json');
  var wrap=document.getElementById('lib-fotos-extra-prev');
  try{
    if(hid){
      var js=JSON.stringify(arr);
      hid.value = js.length<50000 ? js : JSON.stringify(arr.map(function(f,i){return {nome:f.nome,i:i,tem:true};}));
    }
  }catch(e){ if(hid) hid.value='[]'; }
  if(wrap){
    wrap.innerHTML=(arr||[]).map(function(f,i){
      var src=f.b64||f.url||'';
      return '<div style="position:relative;width:72px;height:54px;border-radius:6px;overflow:hidden;border:.5px solid #e0dfd8">'
        +'<img src="'+src+'" style="width:100%;height:100%;object-fit:cover"/>'
        +'<button type="button" onclick="portFotosExtraDel('+i+')" style="position:absolute;top:2px;right:2px;background:#A32D2D;color:#fff;border:0;border-radius:3px;font-size:10px;padding:0 4px;cursor:pointer">×</button>'
        +'</div>';
    }).join('');
  }
}
function portFotosExtraDel(idx){
  var arr=portFotosExtraColetar();
  arr.splice(idx,1);
  portFotosExtraPersist(arr);
}
function portFotosExtraColetar(){
  var mem=(window._portFotoMem||{})['lib-fotos-extra-json'];
  if(Array.isArray(mem) && mem.length) return mem.slice();
  var hid=document.getElementById('lib-fotos-extra-json');
  try{ var a=JSON.parse((hid&&hid.value)||'[]'); return Array.isArray(a)?a:[]; }catch(e){ return []; }
}

function portCarregarConfigs(){
  try{ var s=localStorage.getItem('portaria_configs'); if(s) portaria_configs=JSON.parse(s); }catch(e){}
  if(!portaria_configs.length&&!DEMO){
    sbFetch('portaria_configs',{filters:['status=eq.Ativo'],order:'nome'})
      .then(function(rows){ if(rows&&rows.length){ portaria_configs=rows; portRenderSeletorAtiva(); }})
      .catch(function(){});
  }
  // Garantir que filiais estão carregadas
  if(!filiais.length&&!DEMO){
    sbFetch('filiais',{filters:['ativa=eq.true'],order:'nome'})
      .then(function(rows){ if(rows&&rows.length) filiais=rows; })
      .catch(function(){});
  }
  // Popular filtro de bases nos registros
  var selBase=document.getElementById('frt-port-base');
  if(selBase && selBase.options.length<=1){
    var bases=new Set();
    frt_portaria.forEach(function(p){if(p.base_saida)bases.add(p.base_saida);});
    portaria_configs.forEach(function(p){if(p.nome)bases.add(p.nome);});
    bases.forEach(function(b){
      var o=document.createElement('option'); o.value=b; o.textContent=b;
      selBase.appendChild(o);
    });
  }
}

function portSalvarConfigs(){
  try{ localStorage.setItem('portaria_configs',JSON.stringify(portaria_configs)); }catch(e){}
}

function portRenderSeletorAtiva(){
  var el=document.getElementById('port-seletor-ativa'); if(!el) return;
  if(!portaria_configs.length){
    el.innerHTML='<div style="font-size:11px;color:#aaa">Nenhuma portaria configurada. Configure na aba ⚙</div>';
    return;
  }
  var opts=portaria_configs.map(function(p){
    var fil=filiais.find(function(f){return f.id===p.filial_id;})||{};
    return '<option value="'+p.id+'"'+((_portAtiva&&_portAtiva.id===p.id)?' selected':'')+'>'+escHtml(fil.codigo?fil.codigo+' — ':'')+''+escHtml(p.nome)+'</option>';
  }).join('');
  el.innerHTML='<select class="inp" id="port-sel-ativa" style="width:260px;font-weight:600" onchange="portDefinirAtiva(this.value)">'
    +'<option value="">Selecione a portaria...</option>'+opts+'</select>';
  // Restaurar seleção salva
  var saved=localStorage.getItem('port_ativa_id');
  if(saved){var sel=document.getElementById('port-sel-ativa');if(sel)sel.value=saved;}
}

function portDefinirAtiva(id){
  _portAtiva=portaria_configs.find(function(p){return p.id===id;})||null;
  localStorage.setItem('port_ativa_id',id||'');
  var el=document.getElementById('port-ativa-label');
  if(el){
    if(_portAtiva){
      var fil=filiais.find(function(f){return f.id===_portAtiva.filial_id;})||{};
      el.textContent='📍 '+(_portAtiva.nome||'')+(fil.nome?' — '+fil.nome:'');
      el.style.display='';
    } else {
      el.style.display='none';
    }
  }
}

