// MÓDULO DOCUMENTOS DA FROTA — COMPLETO
// ═══════════════════════════════════════════════════════════

// Fase 5A — tipos de documento do veículo (sem Multa)
var FDOC_TIPOS_VEICULO = [
  'Taxa Municipal','IPVA','Licenciamento','Inspeção','Seguro',
  'Cronotacógrafo','AET','Teste Dielétrico','Teste Acústico','Outros'
];
// Compat: leitura de registros legados + Multa (aba própria)
var FDOC_TIPOS = FDOC_TIPOS_VEICULO.concat(['Multa','CRLV','ANTT','Contrato de locação','Tacógrafo','Taxa municipal']);
var FDOC_STATUS = ['Pendente','Pago','Vencido','Cancelado','Parcelado','Em recurso'];
var FDOC_STATUS_DOC = ['Pendente','Pago','Vencido','Cancelado']; // seletor + Documento (roadmap 5A)
var FDOC_GRAVIDADE = ['Leve','Média','Grave','Gravíssima'];
var FDOC_GRAVIDADE_PONTOS = {'Leve':3,'Média':4,'Grave':5,'Gravíssima':7};
var FDOC_TIPO_INFRACAO = ['Velocidade','Estacionamento / Parada','Sinalização / Semáforo','Uso de celular','Cinto de segurança','Documentação','Ultrapassagem','Faixa exclusiva','Conversão / Preferência','Faróis / Iluminação','Outros'];
var FDOC_MULTA_EXTRA_COLS = ['municipio_infracao','codigo_infracao','tipo_infracao','gravidade','valor_desconto','exclusao_justificativa','excluido_por'];
var FDOC_STATUS_COR = {
  Pendente:  {bg:'#FEF3E2',cor:'#854F0B'},
  Pago:      {bg:'#E6F1FB',cor:'#185FA5'},
  Vencido:   {bg:'#FCEBEB',cor:'#A32D2D'},
  Parcelado: {bg:'#EEEDFE',cor:'#533AB7'},
  'Em recurso':{bg:'#FEF0E2',cor:'#B45C0A'},
  Cancelado: {bg:'#f5f5f3',cor:'#888'},
  Regular:   {bg:'#EAF3DE',cor:'#3B6D11'},
};
var FDOC_GRUPO1 = {'Taxa Municipal':1,'IPVA':1,'Licenciamento':1,'Inspeção':1,'Outros':1,'CRLV':1,'ANTT':1,'Contrato de locação':1,'Taxa municipal':1};
var FDOC_GRUPO2 = {'Seguro':2,'Cronotacógrafo':2,'Tacógrafo':2};
var FDOC_GRUPO3 = {'AET':3,'Teste Dielétrico':3,'Teste Acústico':3};

function fdocNormTipo(tipo){
  if(tipo==='Tacógrafo') return 'Cronotacógrafo';
  if(tipo==='Taxa municipal') return 'Taxa Municipal';
  return tipo||'';
}
function fdocGrupoTipo(tipo){
  var t=fdocNormTipo(tipo);
  if(FDOC_GRUPO3[t]||FDOC_GRUPO3[tipo]) return 3;
  if(FDOC_GRUPO2[t]||FDOC_GRUPO2[tipo]) return 2;
  return 1;
}
function fdocOptsTipoVeiculoHtml(selected){
  var sel=fdocNormTipo(selected)||'';
  var tipos=FDOC_TIPOS_VEICULO.slice();
  // Manter tipo legado selecionável na edição se não estiver na lista nova
  if(sel && tipos.indexOf(sel)<0 && sel!=='Multa') tipos=tipos.concat([sel]);
  return tipos.map(function(t){return '<option'+(sel===t?' selected':'')+'>'+t+'</option>';}).join('');
}

function fdocCorVenc(venc, hoje, em30){
  if(!venc) return {bg:'#f5f5f3',cor:'#888',label:'Sem vencimento'};
  if(venc < hoje)  return {bg:'#FCEBEB',cor:'#A32D2D',label:'Vencido'};
  if(venc <= em30) return {bg:'#FEF3E2',cor:'#854F0B',label:'Vence em breve'};
  return {bg:'#EAF3DE',cor:'#3B6D11',label:'Regular'};
}

/** Alinha colunas legadas (numero/emissao/validade) com aliases da UI (numero_documento/data_*). */
function fdocNormRow(d){
  if(!d) return d;
  var num=d.numero_documento||d.numero||'';
  var emi=d.data_emissao||d.emissao||null;
  var venc=d.data_vencimento||d.validade||d.data_validade||null;
  d.numero=d.numero||num||null;
  d.numero_documento=num||null;
  d.emissao=d.emissao||emi||null;
  d.data_emissao=emi||null;
  d.validade=d.validade||venc||null;
  d.data_vencimento=venc||null;
  return d;
}
function fdocNormRows(rows){
  return (rows||[]).map(function(r){ return fdocNormRow(Object.assign({},r)); });
}
/** Payload com nomes de coluna reais do Supabase. */
function fdocPayloadDb(dados){
  var p={
    placa:dados.placa||null,
    tipo:dados.tipo||null,
    numero:dados.numero_documento||dados.numero||null,
    emissao:dados.data_emissao||dados.emissao||null,
    validade:dados.data_vencimento||dados.validade||null,
    status:dados.status||null
  };
  // valor só existe após sql_frotas_documentos_valor.sql — não enviar se o schema recusou
  if(window._frotasDocsTemValor!==false && dados.valor!=null && dados.valor!==''){
    var nVal=Number(dados.valor);
    if(!isNaN(nVal)) p.valor=nVal;
  }
  // observacao só se a coluna existir (sql_frotas_documentos_observacao.sql)
  if(dados.observacao!=null && String(dados.observacao).trim()!=='' && window._frotasDocsTemObservacao){
    p.observacao=dados.observacao;
  }
  ['modelo','anexo_url','data_validade','empresa_executora','laudo_certificado','colaborador_id',
   'numero_auto','orgao_emissor','data_infracao','hora_infracao','local_infracao','condutor_responsavel',
   'pontos_cnh','desconto_disponivel','status_recurso','pago','data_pagamento',
   'municipio_infracao','codigo_infracao','tipo_infracao','gravidade','valor_desconto',
   'exclusao_justificativa','excluido_por'].forEach(function(k){
    if(dados[k]!==undefined&&dados[k]!==null&&dados[k]!=='') p[k]=dados[k];
  });
  if(window._frotasDocsTemMultaExtra===false){
    FDOC_MULTA_EXTRA_COLS.forEach(function(k){ delete p[k]; });
  }
  return p;
}

function fdocDocAtivo(d){
  return !!(d && !d.deleted_at);
}
function fdocOptsTipoInfracao(sel){
  var html='<option value="">Selecione</option>';
  var found=false;
  (FDOC_TIPO_INFRACAO||[]).forEach(function(t){
    var is=sel===t;
    if(is) found=true;
    html+='<option'+(is?' selected':'')+'>'+escHtml(t)+'</option>';
  });
  if(sel && !found) html+='<option selected>'+escHtml(sel)+'</option>';
  return html;
}
function fdocOptsGravidade(sel){
  var html='<option value="">Selecione</option>';
  (FDOC_GRAVIDADE||[]).forEach(function(g){
    html+='<option'+(sel===g?' selected':'')+'>'+g+'</option>';
  });
  return html;
}
function fdocToggleValorDesconto(){
  var ck=document.getElementById('fdoc-desconto');
  var wrap=document.getElementById('fdoc-valor-desc-wrap');
  if(!wrap) return;
  wrap.style.display=(ck&&ck.checked)?'':'none';
}
function fdocOnGravidadeChange(){
  var g=((document.getElementById('fdoc-gravidade')||{}).value||'');
  var pEl=document.getElementById('fdoc-pontos');
  if(!pEl) return;
  var pts=FDOC_GRAVIDADE_PONTOS[g];
  if(pts!=null) pEl.value=pts;
}

function fdocDiasVenc(venc, hoje){
  if(!venc) return null;
  return Math.floor((new Date(venc)-new Date(hoje))/86400000);
}

function fdocAba(aba){
  var aca=document.getElementById('app-content-area');if(aca)aca.scrollTop=0;
  ['dashboard','docs','motoristas','multas','alertas'].forEach(function(a){
    var el=document.getElementById('fdoc-aba-'+a);
    var btn=document.getElementById('fdoc-tab-'+a);
    if(el) el.style.display = a===aba?'':'none';
    if(btn){
      var isAt=a===aba;
      btn.style.color=isAt?'#185FA5':'#888';
      btn.style.borderBottomColor=isAt?'#185FA5':'transparent';
      btn.style.fontWeight=isAt?'600':'500';
    }
  });
  if(aba==='dashboard') fdocRenderDashboard();
  if(aba==='docs')      { fdocPopularContratos(); fdocRenderDocs(); }
  if(aba==='motoristas'){ fmdEnsureLoaded().then(function(){ fmdRender(); }); }
  if(aba==='multas')    { fdocPopularContratos(); fdocRenderMultas(); }
  if(aba==='alertas')   fdocRenderAlertas();
}

// ══ FASE 1 — Documentos de Motoristas / CNH ═══════════════════
var FMD_TIPOS=['CNH','Termo de Direção','Política de Frotas','Treinamento de Direção','Autorização de Condução','Outros'];
var FMD_STATUS=['Válida','A vencer','Vencida','Cancelada','Pendente','Sem documento'];
var FMD_STATUS_COR={
  'Válida':{bg:'#EAF3DE',cor:'#3B6D11'},
  'A vencer':{bg:'#FEF3E2',cor:'#854F0B'},
  'Vencida':{bg:'#FCEBEB',cor:'#A32D2D'},
  'Cancelada':{bg:'#f5f5f3',cor:'#888'},
  'Pendente':{bg:'#E6F1FB',cor:'#185FA5'},
  'Sem documento':{bg:'#FEF0E2',cor:'#B45C0A'}
};
var FMD_ANEXO_MAX=2.5*1024*1024; // 2.5 MB
var _fmdLoaded=false;
var _portCnhExcecao=null; // {colaborador_id, motivo, liberado_em, ...} sessão atual

function fmdHoje(){ return dataHojeLocal(); }
function fmdDiasAte(venc, hoje){
  if(!venc) return null;
  hoje=hoje||fmdHoje();
  return Math.floor((new Date(String(venc).slice(0,10)+'T12:00:00')-new Date(hoje+'T12:00:00'))/86400000);
}
/** Recalcula status a partir da data_vencimento (exceto Cancelada/Pendente sem vencimento). */
function fmdCalcStatus(doc, hoje){
  if(!doc) return 'Sem documento';
  if(doc.status==='Cancelada') return 'Cancelada';
  var dias=fmdDiasAte(doc.data_vencimento, hoje||fmdHoje());
  if(dias==null) return doc.status==='Pendente'?'Pendente':'Pendente';
  if(dias<0) return 'Vencida';
  if(dias<=30) return 'A vencer';
  return 'Válida';
}
function fmdMsgAlerta(dias, opts){
  opts=opts||{};
  if(dias==null){
    if(opts.temCategoria){
      return 'Motorista com CNH cadastrada (cat. '+(opts.categoria||'?')+'), mas sem data de validade. Cadastre a validade em Colaboradores ou em Frotas → Documentos → Motoristas.';
    }
    return 'Motorista sem CNH cadastrada no sistema. Verifique a documentação.';
  }
  if(dias<0){
    if(opts.contexto==='portaria'){
      return 'Motorista com CNH vencida. Saída bloqueada. Solicite liberação de responsável autorizado.';
    }
    return 'Observação: CNH vencida. Atualize o cadastro da validade. Escala permitida.';
  }
  // Aviso principal: 5 dias (atualizar cadastro)
  if(dias===0) return 'CNH vence hoje. Atualize o cadastro da validade.';
  if(dias<=5) return 'CNH vence em '+dias+' dia'+(dias===1?'':'s')+'. Atualize o cadastro da validade.';
  if(dias<=15) return 'CNH vence em '+dias+' dias. Atualize o cadastro quando possível.';
  if(dias<=30) return 'CNH vence em '+dias+' dias.';
  return '';
}
/**
 * Avalia CNH do colaborador.
 * Fonte: frotas_motorista_documentos (CNH ativa); fallback colaboradores.cnh_validade.
 * @returns {{ok,bloqueia,bloqueia_programacao,nivel,dias,msg,badge,doc,fonte,vencimento,categoria}}
 * nivel: ok | aviso | vencida | sem | sem_validade
 * Programação/escala NÃO bloqueia por validade — só observação (bloqueia_programacao=false).
 * Portaria continua bloqueando vencida/sem_validade via bloqueia=true.
 */
function fmdAvaliarCnh(colabIdOrObj){
  var col=typeof colabIdOrObj==='object'&&colabIdOrObj?colabIdOrObj
    :(colaboradores||[]).find(function(c){return String(c.id)===String(colabIdOrObj);});
  var colId=col?col.id:colabIdOrObj;
  var hoje=fmdHoje();
  var doc=(frt_motorista_docs||[]).find(function(d){
    return String(d.colaborador_id)===String(colId)&&d.tipo_documento==='CNH'&&d.status!=='Cancelada';
  })||null;
  var venc=doc&&doc.data_vencimento?String(doc.data_vencimento).slice(0,10):(col&&col.cnh_validade?String(col.cnh_validade).slice(0,10):null);
  var cat=doc&&doc.categoria_cnh?doc.categoria_cnh:(col?col.cnh_categoria:'');
  var catTrim=String(cat||'').trim();
  var fonte=doc?'documento':(venc?'cadastro':'nenhuma');
  if(!venc){
    // Tem categoria/carta mas falta validade → observação (escala ok); Portaria ainda bloqueia
    if(catTrim || (col&&col.motorista)){
      return {
        ok:false,bloqueia:true,bloqueia_programacao:false,nivel:'sem_validade',dias:null,
        msg:fmdMsgAlerta(null,{temCategoria:!!catTrim,categoria:catTrim||'—'}),
        badge:'Sem validade CNH',doc:doc,fonte:fonte,vencimento:null,categoria:catTrim,colaborador:col
      };
    }
    return {
      ok:true,bloqueia:false,bloqueia_programacao:false,nivel:'sem',dias:null,
      msg:fmdMsgAlerta(null),badge:'Sem CNH',doc:doc,fonte:fonte,vencimento:null,categoria:'',colaborador:col
    };
  }
  var dias=fmdDiasAte(venc,hoje);
  if(dias<0){
    return {
      ok:false,bloqueia:true,bloqueia_programacao:false,nivel:'vencida',dias:dias,
      msg:fmdMsgAlerta(dias),badge:'CNH vencida',doc:doc,fonte:fonte,vencimento:venc,categoria:catTrim,colaborador:col
    };
  }
  if(dias<=5){
    return {
      ok:true,bloqueia:false,bloqueia_programacao:false,nivel:'aviso',dias:dias,
      msg:fmdMsgAlerta(dias),badge:dias===0?'CNH hoje':('CNH '+dias+'d'),
      doc:doc,fonte:fonte,vencimento:venc,categoria:catTrim,colaborador:col
    };
  }
  if(dias<=30){
    var badge=dias<=15?'CNH 15d':'CNH 30d';
    return {
      ok:true,bloqueia:false,bloqueia_programacao:false,nivel:'aviso',dias:dias,
      msg:fmdMsgAlerta(dias),badge:badge,doc:doc,fonte:fonte,vencimento:venc,categoria:catTrim,colaborador:col
    };
  }
  return {
    ok:true,bloqueia:false,bloqueia_programacao:false,nivel:'ok',dias:dias,msg:'',badge:'',
    doc:doc,fonte:fonte,vencimento:venc,categoria:catTrim,colaborador:col
  };
}
function fmdBadgeHtml(av){
  if(!av||!av.badge) return '';
  var cor=av.nivel==='vencida'?'#A32D2D':(av.nivel==='sem'||av.nivel==='sem_validade'?'#B45C0A':'#854F0B');
  var bg=av.nivel==='vencida'?'#FCEBEB':(av.nivel==='sem'||av.nivel==='sem_validade'?'#FEF0E2':'#FEF3E2');
  return '<span style="background:'+bg+';color:'+cor+';border-radius:4px;padding:1px 6px;font-size:9px;font-weight:700;margin-left:4px" title="'+escHtml(av.msg||'')+'">'+escHtml(av.badge)+'</span>';
}
function fmdAlertaBoxHtml(av){
  if(!av||av.nivel==='ok') return '';
  // Programação: vencida/sem_validade são observação (não “bloqueio visual”)
  var isObs=av.nivel==='vencida'||av.nivel==='sem_validade'||av.nivel==='sem';
  var bg=isObs?'#FEF0E2':(av.bloqueia?'#FCEBEB':'#FEF3E2');
  var cor=isObs?'#B45C0A':(av.bloqueia?'#A32D2D':'#854F0B');
  var icon=isObs?'⚠':(av.bloqueia?'🚫':'⏰');
  return '<div style="background:'+bg+';border:.5px solid '+cor+'44;border-radius:8px;padding:8px 10px;margin:.5rem 0;font-size:12px;color:'+cor+'">'
    +'<b>'+icon+' '+escHtml(av.msg)+'</b>'
    +(av.vencimento?'<div style="font-size:11px;margin-top:3px">Vencimento: '+fmtD(av.vencimento)+(av.categoria?' · Cat. '+escHtml(av.categoria):'')+'</div>':'')
    +(av.nivel==='sem_validade'?'<div style="font-size:11px;margin-top:4px">Preencha a data de validade da CNH ou peça um documento atualizado ao motorista.</div>':'')
    +(av.nivel==='vencida'?'<div style="font-size:11px;margin-top:4px">Escala permitida. Atualize o cadastro para remover esta observação.</div>':'')
    +(av.nivel==='aviso'&&av.dias!=null&&av.dias<=5?'<div style="font-size:11px;margin-top:4px">Atualize o cadastro da validade nos próximos dias.</div>':'')
    +'</div>';
}
function fmdPodeLiberarExcecao(){
  var p=(usuarioLogado&&usuarioLogado.perfil)||'';
  return ['admin','gestor','coordenador','supervisor'].indexOf(p)>=0;
}
function fmdEnsureLoaded(){
  if(DEMO){_fmdLoaded=true;return Promise.resolve(frt_motorista_docs);}
  if(_fmdLoaded&&frt_motorista_docs&&frt_motorista_docs.length>=0){
    // ainda assim refresca se vazio na 1ª vez após SQL
  }
  return sbFetch('frotas_motorista_documentos',{order:'atualizado_em.desc',limit:3000}).then(function(rows){
    frt_motorista_docs=rows||[];
    _fmdLoaded=true;
    return frt_motorista_docs;
  }).catch(function(e){
    console.warn('[FMD] load',e);
    frt_motorista_docs=frt_motorista_docs||[];
    _fmdLoaded=true;
    return frt_motorista_docs;
  });
}
function fmdColabLabel(c){
  if(!c) return '—';
  return (c.nome||'—')+(c.re?' · RE '+c.re:'');
}
function fmdMotoristasLista(){
  return (colaboradores||[]).filter(function(c){
    if(c.ativo===false||c.dispensado) return false;
    return !!(c.motorista||c.cnh_categoria||c.cnh_validade);
  }).sort(function(a,b){return (a.nome||'').localeCompare(b.nome||'','pt-BR');});
}
function fmdRender(){
  var wrap=document.getElementById('fmd-lista-wrap'); if(!wrap) return;
  var busca=String((document.getElementById('fmd-fil-busca')||{}).value||'').trim().toLowerCase();
  var tipo=(document.getElementById('fmd-fil-tipo')||{}).value||'';
  var status=(document.getElementById('fmd-fil-status')||{}).value||'';
  var atalho=(document.getElementById('fmd-fil-atalho')||{}).value||'';

  var rows=(frt_motorista_docs||[]).map(function(d){
    var st=fmdCalcStatus(d);
    return Object.assign({},d,{_status:st,_dias:fmdDiasAte(d.data_vencimento)});
  }).filter(function(d){
    if(tipo&&d.tipo_documento!==tipo) return false;
    if(status&&d._status!==status) return false;
    if(atalho==='vencida'&&!(d.tipo_documento==='CNH'&&d._status==='Vencida')) return false;
    if(atalho==='avencer'&&!(d.tipo_documento==='CNH'&&d._status==='A vencer')) return false;
    if(busca){
      var col=(colaboradores||[]).find(function(c){return String(c.id)===String(d.colaborador_id);})||{};
      var blob=((col.nome||'')+' '+(col.re||'')+' '+(col.cpf||'')+' '+(d.colaborador_re||'')+' '+(d.numero_documento||'')).toLowerCase();
      if(blob.indexOf(busca)<0) return false;
    }
    return true;
  });

  var cnhs=(frt_motorista_docs||[]).filter(function(d){return d.tipo_documento==='CNH'&&d.status!=='Cancelada';});
  var nVenc=0,nAv=0;
  cnhs.forEach(function(d){ var s=fmdCalcStatus(d); if(s==='Vencida')nVenc++; else if(s==='A vencer')nAv++; });
  var motIds={}; fmdMotoristasLista().forEach(function(c){motIds[c.id]=true;});
  var comCnh={}; cnhs.forEach(function(d){comCnh[d.colaborador_id]=true;});
  var semCnh=Object.keys(motIds).filter(function(id){return !comCnh[id];}).length;

  var met=document.getElementById('fmd-metricas');
  if(met){
    met.innerHTML=[
      {l:'Documentos',v:rows.length,c:'#555'},
      {l:'CNH vencidas',v:nVenc,c:'#A32D2D'},
      {l:'CNH a vencer',v:nAv,c:'#854F0B'},
      {l:'Motoristas sem CNH',v:semCnh,c:'#B45C0A'}
    ].map(function(m){
      return '<div style="background:#f9f9f7;border-radius:8px;padding:.5rem;text-align:center">'
        +'<div style="font-size:10px;color:#888">'+m.l+'</div>'
        +'<div style="font-size:18px;font-weight:700;color:'+m.c+'">'+m.v+'</div></div>';
    }).join('');
  }

  var tb=document.getElementById('fmd-tbody'); if(!tb) return;
  if(!rows.length){
    tb.innerHTML='<tr><td colspan="10" style="padding:1.5rem;text-align:center;color:#aaa">Nenhum documento encontrado. Clique em + Documento.</td></tr>';
    return;
  }
  tb.innerHTML=rows.map(function(d){
    var col=(colaboradores||[]).find(function(c){return String(c.id)===String(d.colaborador_id);})||{};
    var sc=FMD_STATUS_COR[d._status]||{bg:'#f5f5f3',cor:'#888'};
    return '<tr>'
      +'<td style="font-size:12px"><b>'+escHtml(col.nome||'—')+'</b></td>'
      +'<td style="font-size:11px">'+escHtml(col.re||d.colaborador_re||'—')+'</td>'
      +'<td style="font-size:12px">'+escHtml(d.tipo_documento)+'</td>'
      +'<td style="font-size:11px;font-family:monospace">'+escHtml(d.numero_documento||'—')+'</td>'
      +'<td style="font-size:11px">'+(d.tipo_documento==='CNH'?escHtml(d.categoria_cnh||'—'):'—')+'</td>'
      +'<td style="font-size:11px">'+(d.data_emissao?fmtD(d.data_emissao):'—')+'</td>'
      +'<td style="font-size:11px">'+(d.data_vencimento?fmtD(d.data_vencimento):'—')+'</td>'
      +'<td><span style="background:'+sc.bg+';color:'+sc.cor+';border-radius:4px;padding:1px 6px;font-size:10px;font-weight:600">'+escHtml(d._status)+'</span></td>'
      +'<td style="font-size:11px">'+(d.arquivo_url?'<a href="'+escHtml(d.arquivo_url)+'" target="_blank" rel="noopener">📎 Ver</a>':'—')+'</td>'
      +'<td style="white-space:nowrap">'
      +'<button class="btn btn-sm" onclick="fmdAbrirModal(\''+d.id+'\')" style="font-size:10px">✎</button> '
      +(d.status!=='Cancelada'?'<button class="btn btn-sm" onclick="fmdCancelarDoc(\''+d.id+'\')" style="font-size:10px;color:#A32D2D">Cancelar</button>':'')
      +'</td></tr>';
  }).join('');
}
function fmdAbrirModal(id){
  var doc=id?(frt_motorista_docs||[]).find(function(d){return String(d.id)===String(id);}):null;
  var mots=fmdMotoristasLista();
  var opts=mots.map(function(c){
    return '<option value="'+c.id+'"'+(doc&&String(doc.colaborador_id)===String(c.id)?' selected':'')+'>'+escHtml(fmdColabLabel(c))+'</option>';
  }).join('');
  var tipo=doc?doc.tipo_documento:'CNH';
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:520px">'
    +'<h3 style="margin:0 0 .75rem">'+(doc?'✎ Editar documento':'+ Documento de motorista')+'</h3>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    +'<div class="fg" style="grid-column:1/-1"><label style="font-size:11px">Motorista *</label>'
    +'<select class="inp" id="fmd-colab" style="width:100%" '+(doc?'disabled':'')+'><option value="">Selecione...</option>'+opts+'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Tipo *</label>'
    +'<select class="inp" id="fmd-tipo" style="width:100%" onchange="fmdToggleCnhFields()">'
    +FMD_TIPOS.map(function(t){return '<option'+(tipo===t?' selected':'')+'>'+t+'</option>';}).join('')
    +'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Nº documento</label>'
    +'<input class="inp" id="fmd-num" style="width:100%" value="'+escHtml(doc&&doc.numero_documento||'')+'"/></div>'
    +'<div class="fg" id="fmd-wrap-cat"><label style="font-size:11px">Categoria CNH</label>'
    +'<select class="inp" id="fmd-cat" style="width:100%">'
    +['','A','B','AB','C','D','E','AD','AE'].map(function(c){return '<option'+(doc&&doc.categoria_cnh===c?' selected':'')+'>'+c+'</option>';}).join('')
    +'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Emissão</label>'
    +'<input class="inp" id="fmd-emissao" type="date" style="width:100%" value="'+(doc&&doc.data_emissao?String(doc.data_emissao).slice(0,10):'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Vencimento</label>'
    +'<input class="inp" id="fmd-venc" type="date" style="width:100%" value="'+(doc&&doc.data_vencimento?String(doc.data_vencimento).slice(0,10):'')+'"/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label style="font-size:11px">Anexo (PDF/imagem, máx. 2,5 MB)</label>'
    +'<input type="file" id="fmd-file" accept=".pdf,image/*" class="inp" style="width:100%"/>'
    +(doc&&doc.arquivo_url?'<div style="font-size:11px;margin-top:4px"><a href="'+escHtml(doc.arquivo_url)+'" target="_blank">Anexo atual</a></div>':'')
    +'<input type="hidden" id="fmd-arquivo" value=""/></div>'
    +'<div class="fg" style="grid-column:1/-1"><label style="font-size:11px">Observação</label>'
    +'<textarea class="inp" id="fmd-obs" rows="2" style="width:100%">'+escHtml(doc&&doc.observacao||'')+'</textarea></div>'
    +'</div>'
    +'<div id="fmd-err" style="display:none;color:#A32D2D;font-size:12px;margin-top:8px"></div>'
    +'<div style="display:flex;gap:8px;margin-top:1rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="fmd-salvar" style="flex:2">💾 Salvar</button>'
    +'</div></div></div>');
  setTimeout(function(){
    fmdToggleCnhFields();
    var fi=document.getElementById('fmd-file');
    if(fi) fi.onchange=function(){
      var f=fi.files&&fi.files[0]; if(!f) return;
      if(f.size>FMD_ANEXO_MAX){
        progShowToast('Arquivo maior que 2,5 MB. Reduza o tamanho.','erro');
        fi.value=''; return;
      }
      var reader=new FileReader();
      reader.onload=function(){ var el=document.getElementById('fmd-arquivo'); if(el) el.value=reader.result; };
      reader.readAsDataURL(f);
    };
    var btn=document.getElementById('fmd-salvar');
    if(btn) btn.onclick=function(){ fmdSalvar(doc?doc.id:null); };
  },40);
}
function fmdToggleCnhFields(){
  var tipo=(document.getElementById('fmd-tipo')||{}).value||'';
  var w=document.getElementById('fmd-wrap-cat');
  if(w) w.style.display=tipo==='CNH'?'':'none';
}
async function fmdSalvar(id){
  var err=document.getElementById('fmd-err');
  var g=function(i){return (document.getElementById(i)||{}).value||'';};
  var colabId=g('fmd-colab');
  var tipo=g('fmd-tipo');
  if(!colabId||!tipo){ if(err){err.textContent='Motorista e tipo são obrigatórios.';err.style.display='';} return; }
  var col=(colaboradores||[]).find(function(c){return String(c.id)===String(colabId);});
  var venc=g('fmd-venc')||null;
  var row={
    colaborador_id:colabId,
    colaborador_re:col?String(col.re||''):'',
    tipo_documento:tipo,
    numero_documento:g('fmd-num')||null,
    categoria_cnh:tipo==='CNH'?(g('fmd-cat')||null):null,
    data_emissao:g('fmd-emissao')||null,
    data_vencimento:venc,
    observacao:g('fmd-obs')||null,
    atualizado_em:new Date().toISOString()
  };
  row.status=fmdCalcStatus(row);
  var arqNovo=g('fmd-arquivo');
  if(arqNovo) row.arquivo_url=arqNovo;
  if(!id){
    row.criado_por=(usuarioLogado&&usuarioLogado.nome)||'Sistema';
    row.criado_em=new Date().toISOString();
  }

  // CNH: cancelar ativa anterior se for nova
  if(tipo==='CNH'&&!DEMO){
    var outras=(frt_motorista_docs||[]).filter(function(d){
      return String(d.colaborador_id)===String(colabId)&&d.tipo_documento==='CNH'&&d.status!=='Cancelada'&&String(d.id)!==String(id||'');
    });
    for(var i=0;i<outras.length;i++){
      await sbUpdate('frotas_motorista_documentos',{status:'Cancelada',atualizado_em:new Date().toISOString()},'id=eq.'+outras[i].id).catch(function(){});
      outras[i].status='Cancelada';
    }
  }

  try{
    if(id){
      if(!DEMO) await sbUpdate('frotas_motorista_documentos',row,'id=eq.'+id);
      var ex=(frt_motorista_docs||[]).find(function(d){return String(d.id)===String(id);});
      if(ex) Object.assign(ex,row,{id:id});
      else frt_motorista_docs.unshift(Object.assign({id:id},row));
    } else {
      var ins=DEMO?[{id:'fmd'+Date.now()}]:await sbInsert('frotas_motorista_documentos',row);
      var nid=ins&&ins[0]?ins[0].id:('fmd'+Date.now());
      frt_motorista_docs.unshift(Object.assign({id:nid},row,ins&&ins[0]?ins[0]:{}));
    }
    // Sync cadastro colaborador (CNH)
    if(tipo==='CNH'&&col){
      col.cnh_categoria=row.categoria_cnh||col.cnh_categoria;
      col.cnh_validade=row.data_vencimento||col.cnh_validade;
      if(!DEMO){
        await sbUpdate('colaboradores',{cnh_categoria:col.cnh_categoria,cnh_validade:col.cnh_validade},'id=eq.'+col.id).catch(function(e){console.warn('[FMD] sync colab',e);});
      }
    }
    closeModal();
    fmdRender();
    progShowToast('Documento salvo.');
  }catch(e){
    console.error(e);
    if(err){err.textContent='Erro ao salvar. Rode o SQL sql_frotas_motorista_documentos.sql se a tabela não existir.';err.style.display='';}
  }
}
async function fmdCancelarDoc(id){
  if(!confirm('Cancelar este documento?')) return;
  var d=(frt_motorista_docs||[]).find(function(x){return String(x.id)===String(id);});
  if(!d) return;
  d.status='Cancelada'; d.atualizado_em=new Date().toISOString();
  if(!DEMO) await sbUpdate('frotas_motorista_documentos',{status:'Cancelada',atualizado_em:d.atualizado_em},'id=eq.'+id).catch(function(){});
  fmdRender();
  progShowToast('Documento cancelado.');
}

/** Resolve motorista da composição (motorista_id ou 1º escalado). */
function portResolverMotoristaComp(comp){
  if(!comp) return null;
  if(comp.motorista_id){
    return (colaboradores||[]).find(function(c){return String(c.id)===String(comp.motorista_id);})||null;
  }
  var ids=parseColabIds(comp.colaborador_ids).filter(Boolean);
  if(!ids.length) return null;
  return (colaboradores||[]).find(function(c){return String(c.id)===String(ids[0]);})||null;
}

/** Liberação excepcional CNH vencida ainda válida nesta sessão (mesmo motorista). */
function portCnhExcecaoAtiva(colabId){
  if(!_portCnhExcecao||!colabId) return false;
  return String(_portCnhExcecao.colaborador_id)===String(colabId);
}

/**
 * Valida CNH antes de liberar saída.
 * @returns {{ok:boolean, av:object|null, precisaExcecao:boolean}}
 */
function portValidarCnhSaida(mot){
  if(!mot) return {ok:true,av:null,precisaExcecao:false};
  var av=fmdAvaliarCnh(mot);
  if(!av) return {ok:true,av:null,precisaExcecao:false};
  // Portaria: mensagem específica de bloqueio de saída
  if(av.nivel==='vencida'){
    av=Object.assign({},av,{msg:fmdMsgAlerta(av.dias,{contexto:'portaria'})});
  }
  if(!av.bloqueia) return {ok:true,av:av,precisaExcecao:false};
  if(portCnhExcecaoAtiva(mot.id)) return {ok:true,av:av,precisaExcecao:false};
  return {ok:false,av:av,precisaExcecao:true};
}

/** Modal de liberação excepcional (CNH vencida). */
function portAbrirLiberacaoCnhExcecao(av, placa, onLiberado){
  var col=av&&av.colaborador;
  var nome=col?(col.nome||'—'):'—';
  var pode=fmdPodeLiberarExcecao();
  if(!pode){
    progShowToast('Motorista com CNH vencida. Saída bloqueada. Solicite liberação de responsável autorizado.','erro');
    return;
  }
  setModal('<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:460px">'
    +'<h3 style="margin:0 0 .5rem;color:#A32D2D">🚫 Liberação excepcional — CNH vencida</h3>'
    +'<div style="font-size:12px;color:#555;margin-bottom:.75rem">'
    +'<div><b>Motorista:</b> '+escHtml(nome)+'</div>'
    +'<div><b>Placa:</b> '+escHtml(placa||'—')+'</div>'
    +'<div><b>Vencimento CNH:</b> '+(av.vencimento?fmtD(av.vencimento):'—')+(av.categoria?' · Cat. '+escHtml(av.categoria):'')+'</div>'
    +'<div style="margin-top:6px;color:#A32D2D;font-weight:600">'+escHtml(av.msg||'')+'</div>'
    +'</div>'
    +'<div class="fg"><label style="font-size:11px;font-weight:600">Justificativa * (mín. 10 caracteres)</label>'
    +'<textarea class="inp" id="port-cnh-just" rows="3" style="width:100%" placeholder="Descreva o motivo da liberação emergencial..."></textarea></div>'
    +'<div id="port-cnh-err" style="display:none;color:#A32D2D;font-size:12px;margin-top:6px"></div>'
    +'<div style="display:flex;gap:8px;margin-top:1rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="port-cnh-ok" style="flex:2;background:#854F0B;border-color:#854F0B">⚠ Liberar com exceção</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var btn=document.getElementById('port-cnh-ok');
    if(!btn) return;
    btn.onclick=async function(){
      var just=((document.getElementById('port-cnh-just')||{}).value||'').trim();
      var errEl=document.getElementById('port-cnh-err');
      if(just.length<10){
        if(errEl){errEl.textContent='Justificativa obrigatória com no mínimo 10 caracteres.';errEl.style.display='block';}
        return;
      }
      var perfil=(usuarioLogado&&usuarioLogado.perfil)||'';
      var liberadoPor=(usuarioLogado&&usuarioLogado.nome)||'Sistema';
      var row={
        placa:placa||null,
        colaborador_id:col?col.id:null,
        colaborador_nome:nome,
        cnh_documento_id:av.doc?av.doc.id:null,
        cnh_vencimento:av.vencimento||null,
        motivo:just,
        liberado_por:liberadoPor,
        liberado_por_id:usuarioLogado&&usuarioLogado.id?usuarioLogado.id:null,
        liberado_perfil:perfil,
        liberado_em:new Date().toISOString(),
        base_saida:(function(){
          var p=portConfigAtiva();
          return p.nome||p.base||null;
        })()
      };
      try{
        if(!DEMO) await sbInsert('frotas_portaria_liberacoes_cnh',row);
      }catch(e){
        console.warn('[Portaria CNH] liberação',e);
        if(errEl){errEl.textContent='Erro ao gravar liberação. Rode o SQL sql_frotas_motorista_documentos.sql.';errEl.style.display='block';}
        return;
      }
      _portCnhExcecao={
        colaborador_id:col?col.id:null,
        motivo:just,
        liberado_em:row.liberado_em,
        liberado_por:liberadoPor,
        liberado_perfil:perfil,
        placa:placa,
        cnh_vencimento:av.vencimento
      };
      closeModal();
      progShowToast('Liberação excepcional registrada. Pode liberar a saída.');
      if(typeof onLiberado==='function') onLiberado();
    };
  },40);
}

function fdocPopularContratos(){
  var ids=['fdoc-fil-cont','mul-fil-cont','frt-man-cont','frt-avar-cont'];
  var lista=(contratos||[]).slice().sort(function(a,b){return String(a.codigo||a.nome||'').localeCompare(String(b.codigo||b.nome||''),'pt');});
  ids.forEach(function(id){
    var sel=document.getElementById(id);
    if(!sel) return;
    if(sel.options.length>1) return;
    lista.forEach(function(c){
      var o=document.createElement('option'); o.value=c.id; o.textContent=c.nome||c.codigo||c.id; sel.appendChild(o);
    });
  });
}

// ── Dashboard ─────────────────────────────────────────────
function fdocRenderDashboard(){
  var hoje=dataHojeLocal();
  var em7  =_diasAdiante(7);
  var em15 =_diasAdiante(15);
  var em30 =_diasAdiante(30);
  var todos=(frt_documentos||[]).filter(fdocDocAtivo);
  var multas=todos.filter(function(d){return d.tipo==='Multa';});

  // Auto-calcular vencidos
  todos.forEach(function(d){
    if(d.status!=='Pago'&&d.status!=='Cancelado'&&d.data_vencimento&&d.data_vencimento<hoje) d.status='Vencido';
  });

  var nVenc   =todos.filter(function(d){return d.status==='Vencido';}).length;
  var nAvenc30=todos.filter(function(d){return d.status!=='Pago'&&d.status!=='Cancelado'&&d.data_vencimento&&d.data_vencimento>=hoje&&d.data_vencimento<=em30;}).length;
  var nIPVA   =todos.filter(function(d){return d.tipo==='IPVA'&&d.status==='Pendente';}).length;
  var nLic    =todos.filter(function(d){return d.tipo==='Licenciamento'&&d.status==='Pendente';}).length;
  var nSeg    =todos.filter(function(d){return d.tipo==='Seguro'&&d.data_vencimento&&d.data_vencimento<=em30;}).length;
  var nMult   =multas.filter(function(d){return d.status==='Pendente';}).length;
  var vlMult  =multas.filter(function(d){return d.status==='Pendente';}).reduce(function(s,d){return s+(d.valor||0);},0);
  var vlPago  =todos.filter(function(d){return d.status==='Pago';}).reduce(function(s,d){return s+(d.valor||0);},0);

  var cards=document.getElementById('fdoc-dash-cards');
  if(cards) cards.innerHTML=[
    {icon:'📄',l:'Total documentos', v:todos.length,              c:'#555'},
    {icon:'🚨',l:'Vencidos',         v:nVenc,                     c:nVenc>0?'#A32D2D':'#3B6D11'},
    {icon:'⚠' ,l:'Vencendo (30d)',   v:nAvenc30,                  c:nAvenc30>0?'#854F0B':'#3B6D11'},
    {icon:'🚗',l:'IPVA pendente',    v:nIPVA,                     c:nIPVA>0?'#854F0B':'#3B6D11'},
    {icon:'📋',l:'Licenciamento',    v:nLic,                      c:nLic>0?'#854F0B':'#3B6D11'},
    {icon:'🛡',l:'Seguros c/ alerta',v:nSeg,                      c:nSeg>0?'#854F0B':'#3B6D11'},
    {icon:'🚦',l:'Multas pendentes', v:nMult,                     c:nMult>0?'#A32D2D':'#3B6D11'},
    {icon:'💸',l:'Valor multas pend.',v:'R$'+vlMult.toLocaleString('pt-BR',{minimumFractionDigits:2}),c:'#A32D2D'},
    {icon:'✅',l:'Total pago',       v:'R$'+vlPago.toLocaleString('pt-BR',{minimumFractionDigits:2}),c:'#185FA5'},
  ].map(function(x){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:10px;padding:.75rem;display:flex;flex-direction:column;gap:4px">'
      +'<div style="font-size:18px">'+x.icon+'</div>'
      +'<div style="font-size:10px;color:#888">'+x.l+'</div>'
      +'<div style="font-size:16px;font-weight:700;color:'+x.c+'">'+x.v+'</div>'
      +'</div>';
  }).join('');

  // Vencidos
  var vencEl=document.getElementById('fdoc-dash-vencidos');
  var vencList=todos.filter(function(d){return d.status==='Vencido';}).sort(function(a,b){return(a.data_vencimento||'')<(b.data_vencimento||'')?-1:1;});
  if(vencEl) vencEl.innerHTML=vencList.length
    ? vencList.slice(0,10).map(function(d){
        var dias=fdocDiasVenc(d.data_vencimento,hoje);
        return '<div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:.5px solid #f5f5f3">'
          +'<span style="font-family:monospace;font-size:12px;font-weight:600;width:80px;flex-shrink:0">'+escHtml(d.placa||'—')+'</span>'
          +'<span style="font-size:11px;flex:1">'+escHtml(d.tipo)+'</span>'
          +'<span style="font-size:11px;font-weight:600;color:#A32D2D">'+(dias!==null?Math.abs(dias)+'d atrás':'vencido')+'</span>'
          +'</div>';
      }).join('')+(vencList.length>10?'<div style="font-size:11px;color:#aaa;margin-top:4px">e mais '+(vencList.length-10)+'...</div>':'')
    : '<div style="color:#3B6D11;font-size:12px;text-align:center;padding:.75rem">✅ Nenhum documento vencido.</div>';

  // A vencer
  var avEl=document.getElementById('fdoc-dash-avencer');
  var avList=todos.filter(function(d){return d.status!=='Pago'&&d.status!=='Cancelado'&&d.data_vencimento&&d.data_vencimento>=hoje&&d.data_vencimento<=em30;})
    .sort(function(a,b){return(a.data_vencimento||'')<(b.data_vencimento||'')?-1:1;});
  if(avEl) avEl.innerHTML=avList.length
    ? avList.slice(0,10).map(function(d){
        var dias=fdocDiasVenc(d.data_vencimento,hoje);
        var cor=dias<=7?'#A32D2D':dias<=15?'#854F0B':'#533AB7';
        return '<div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:.5px solid #f5f5f3">'
          +'<span style="font-family:monospace;font-size:12px;font-weight:600;width:80px;flex-shrink:0">'+escHtml(d.placa||'—')+'</span>'
          +'<span style="font-size:11px;flex:1">'+escHtml(d.tipo)+'</span>'
          +'<span style="font-size:11px;font-weight:700;color:'+cor+'">'+dias+'d</span>'
          +'</div>';
      }).join('')+(avList.length>10?'<div style="font-size:11px;color:#aaa;margin-top:4px">e mais '+(avList.length-10)+'...</div>':'')
    : '<div style="color:#3B6D11;font-size:12px;text-align:center;padding:.75rem">✅ Nenhum vencimento próximo.</div>';

  // Tabela por veículo
  fdocRenderDashVeiculos(hoje, em30);
}

function fdocRenderDashVeiculos(hoje, em30){
  var wrap=document.getElementById('fdoc-dash-veiculos'); if(!wrap) return;
  var busca=((document.getElementById('fdoc-dash-busca')||{}).value||'').toUpperCase();
  var veics=frt_veiculos.filter(function(v){return !busca||(v.placa||'').indexOf(busca)>=0;}).slice(0,40);
  var TIPOS_CHAVE=['IPVA','Licenciamento','Seguro','Taxa Municipal'];

  if(!veics.length){wrap.innerHTML='<div style="color:#aaa;font-size:12px;text-align:center;padding:1rem">Nenhum veículo encontrado.</div>';return;}

  var html='<table class="tbl" style="font-size:11px"><thead><tr><th>Placa</th><th>Modelo</th>'
    +TIPOS_CHAVE.map(function(t){return '<th>'+t+'</th>';}).join('')
    +'<th>Multas</th><th>Outros</th></tr></thead><tbody>';

  veics.forEach(function(v){
    var docs=frt_documentos.filter(function(d){return d.placa===v.placa;});
    html+='<tr>';
    html+='<td style="font-family:monospace;font-weight:700">'+v.placa+'</td>';
    html+='<td style="font-size:11px">'+escHtml(v.modelo||'—')+'</td>';
    TIPOS_CHAVE.forEach(function(tipo){
      var d=docs.filter(function(x){return fdocNormTipo(x.tipo)===tipo;}).sort(function(a,b){return(b.data_vencimento||'')>(a.data_vencimento||'')?1:-1;})[0];
      if(!d){html+='<td><span style="color:#aaa;font-size:10px">—</span></td>';return;}
      var cv=fdocCorVenc(d.data_vencimento,hoje,em30);
      var dias=fdocDiasVenc(d.data_vencimento,hoje);
      html+='<td><span style="background:'+cv.bg+';color:'+cv.cor+';border-radius:4px;padding:1px 7px;font-size:10px;font-weight:600">'
        +(dias===null?'Sem vencim.':dias<0?Math.abs(dias)+'d atrás':dias+'d')
        +'</span></td>';
    });
    var nMult=docs.filter(function(x){return x.tipo==='Multa'&&x.status==='Pendente';}).length;
    html+='<td style="text-align:center;font-weight:'+(nMult>0?'700':'400')+';color:'+(nMult>0?'#A32D2D':'#888')+'">'+(nMult>0?nMult+'⚠':'—')+'</td>';
    var nOutros=docs.filter(function(x){return TIPOS_CHAVE.indexOf(fdocNormTipo(x.tipo))<0&&x.tipo!=='Multa'&&x.status!=='Pago';}).length;
    html+='<td style="text-align:center;color:#888">'+(nOutros||'—')+'</td>';
    html+='</tr>';
  });
  wrap.innerHTML=html+'</tbody></table>';
}

// ── Aba Documentos (consulta manutenções + anexos Laudo/Documento/Garantia) ─
function frtManutParseDocs(m){
  if(!m) return [];
  var d=m.documentos_anexos;
  if(typeof d==='string'){
    try{ d=JSON.parse(d); }catch(e){ d=[]; }
  }
  if(!Array.isArray(d)) d=[];
  return d.filter(function(x){ return x && x.url; }).map(function(x,i){
    return {
      id: x.id || ('doc_'+i+'_'+String(x.url).slice(-8)),
      nome: x.nome || x.name || 'Documento',
      url: x.url,
      tipo: x.tipo || 'Documento',
      criado_em: x.criado_em || x.created_at || ''
    };
  });
}
/** Migra anexo_compra_url legado para documentos_anexos (em memória). */
function frtManutEnsureDocsMigrated(m){
  if(!m) return [];
  var docs=frtManutParseDocs(m);
  var urlLegado=(m.anexo_compra_url||'').trim();
  if(urlLegado){
    var ja=docs.some(function(d){ return String(d.url)===urlLegado; });
    if(!ja){
      docs.push({
        id:'migrado_'+Date.now(),
        nome:'Anexo OC/RC (migrado)',
        url:urlLegado,
        tipo:'Documento',
        criado_em:new Date().toISOString()
      });
    }
    m.anexo_compra_url=null;
    m._docsDirty=true;
  }
  m.documentos_anexos=docs;
  return docs;
}
function fdocManutTemAnexo(m){
  if(!m) return false;
  if(frtManutParseDocs(m).length>0) return true;
  // Legado até rodar SQL / abrir Controle (migra anexo_compra_url)
  return !!(m.anexo_compra_url&&String(m.anexo_compra_url).trim());
}
function fdocManutAnexosHtml(m){
  var docs=frtManutParseDocs(m);
  if(!docs.length && m.anexo_compra_url){
    docs=[{nome:'Anexo OC/RC (pendente migração)',url:m.anexo_compra_url,tipo:'Documento'}];
  }
  if(!docs.length) return '<span style="color:#ccc;font-size:11px">—</span>';
  return docs.map(function(d){
    var rot=escHtml((d.tipo?d.tipo+': ':'')+(d.nome||'Documento'));
    return '<a href="'+escHtml(d.url)+'" target="_blank" rel="noopener" style="font-size:11px;color:#185FA5;margin-right:6px;display:inline-block" onclick="event.stopPropagation()" title="'+rot+'">📎 '+rot+'</a>';
  }).join(' ');
}
function frtManutDocsListaHtml(docs){
  docs=docs||[];
  if(!docs.length){
    return '<div style="font-size:11px;color:#888;padding:4px 0">Nenhum documento anexado.</div>';
  }
  return '<div style="display:flex;flex-direction:column;gap:6px">'+docs.map(function(d){
    var id=escHtml(String(d.id||''));
    return '<div style="display:flex;align-items:center;gap:8px;background:#fff;border:.5px solid #e0dfd8;border-radius:6px;padding:6px 8px">'
      +'<span style="font-size:10px;font-weight:700;color:#534AB7;background:#EEEDFE;border-radius:4px;padding:1px 6px;white-space:nowrap">'+escHtml(d.tipo||'Documento')+'</span>'
      +'<a href="'+escHtml(d.url)+'" target="_blank" rel="noopener" style="flex:1;font-size:12px;color:#185FA5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+escHtml(d.nome||'')+'">'+escHtml(d.nome||'Documento')+'</a>'
      +'<button type="button" class="btn btn-sm" data-fc-doc-del="'+id+'" style="font-size:10px;color:#A32D2D;border-color:#E1A9A9;padding:1px 7px" title="Excluir documento">✕</button>'
      +'</div>';
  }).join('')+'</div>';
}
function frtManutBindDocsUI(m){
  var list=document.getElementById('fc-docs-lista');
  var fileInp=document.getElementById('fc-docs-file');
  var tipoSel=document.getElementById('fc-docs-tipo');
  if(!list||!m) return;
  function refresh(){
    var docs=frtManutParseDocs(m);
    list.innerHTML=frtManutDocsListaHtml(docs);
    list.querySelectorAll('[data-fc-doc-del]').forEach(function(btn){
      btn.onclick=function(e){
        e.preventDefault(); e.stopPropagation();
        var id=this.getAttribute('data-fc-doc-del');
        if(!confirm('Excluir este documento da manutenção?')) return;
        m.documentos_anexos=frtManutParseDocs(m).filter(function(d){ return String(d.id)!==String(id); });
        m._docsDirty=true;
        refresh();
      };
    });
  }
  refresh();
  if(fileInp){
    fileInp.onchange=async function(){
      var files=Array.prototype.slice.call(fileInp.files||[]);
      if(!files.length) return;
      var tipo=(tipoSel&&tipoSel.value)||'Documento';
      var statusEl=document.getElementById('fc-docs-status');
      for(var i=0;i<files.length;i++){
        var file=files[i];
        if(statusEl) statusEl.textContent='Enviando '+(i+1)+'/'+files.length+': '+file.name+'…';
        var url='';
        if(typeof sbUpload==='function'&&!DEMO){
          try{
            url=await sbUpload(file,'frotas/manutencao/docs/'+Date.now()+'_'+file.name);
          }catch(err){ console.warn('fc docs upload',err); }
        } else {
          // DEMO: object URL local
          try{ url=URL.createObjectURL(file); }catch(e2){ url='#'; }
        }
        if(!url){
          if(statusEl) statusEl.textContent='Falha ao enviar '+file.name;
          continue;
        }
        var docs=frtManutParseDocs(m);
        docs.push({
          id:'doc_'+Date.now()+'_'+i,
          nome:file.name,
          url:url,
          tipo:tipo,
          criado_em:new Date().toISOString()
        });
        m.documentos_anexos=docs;
        m._docsDirty=true;
      }
      fileInp.value='';
      if(statusEl) statusEl.textContent=files.length?('✅ '+files.length+' arquivo(s) adicionado(s). Salve o controle para gravar.'):'';
      refresh();
    };
  }
}
function fdocRenderDocs(opts){
  opts=opts||{};
  var hoje=dataHojeLocal();
  var em30=_diasAdiante(30);
  var tb=document.getElementById('frt-doc-tbody'); if(!tb) return;
  var busca =((document.getElementById('fdoc-fil-placa')||{}).value||'').trim();
  var tipo  =(document.getElementById('fdoc-fil-tipo')||{}).value||'';
  var status=(document.getElementById('fdoc-fil-status')||{}).value||'';
  var anexo =(document.getElementById('fdoc-fil-anexo')||{}).value||'';
  var cid   =(document.getElementById('fdoc-fil-cont')||{}).value||'';

  // Garante manutenções carregadas
  if(!opts._skipDb && !DEMO && typeof frtFetchManutencoesCompleto==='function'){
    var precisa=!(frt_manutencoes&&frt_manutencoes.length);
    var precisaBusca=!!busca && String(busca).replace(/[^A-Za-z0-9]/g,'').length>=2;
    if(precisa || precisaBusca){
      if(window._fdocManutLock) return;
      window._fdocManutLock=true;
      tb.innerHTML='<tr><td colspan="9" style="padding:1.5rem;text-align:center;color:#888">Carregando documentos de manutenção...</td></tr>';
      var p=precisa?frtFetchManutencoesCompleto().then(function(r){ if(r&&r.length) frt_manutencoes=r; }):Promise.resolve();
      p.then(function(){
        if(precisaBusca && typeof frtManutBuscarPlacaNoBanco==='function') return frtManutBuscarPlacaNoBanco(busca);
      }).then(function(){
        window._fdocManutLock=false;
        fdocRenderDocs({_skipDb:true});
      }).catch(function(){
        window._fdocManutLock=false;
        fdocRenderDocs({_skipDb:true});
      });
      return;
    }
  }

  var rows=(frt_manutencoes||[]).filter(function(m){
    if(tipo && String(m.tipo||'')!==tipo) return false;
    if(status && String(m.status||'')!==status) return false;
    var tem=fdocManutTemAnexo(m);
    if(anexo==='com' && !tem) return false;
    if(anexo==='sem' && tem) return false;
    if(busca){
      var placa=typeof frtManutPlacaOf==='function'?frtManutPlacaOf(m):(m.placa||'');
      var nPlacas=frtParsePlacasBusca(busca).length;
      if(nPlacas>1){
        var okLista=(typeof frtPlacaMatchBusca==='function')
          ? (frtPlacaMatchBusca(placa,busca)||frtPlacaMatchBusca(m.placa,busca))
          : false;
        if(!okLista) return false;
      } else {
        var okPlaca=(typeof frtPlacaMatchBusca==='function')
          ? (frtPlacaMatchBusca(placa,busca)||frtPlacaMatchBusca(m.placa,busca))
          : (String(placa).toUpperCase().indexOf(busca.toUpperCase())>=0);
        var okMod=String(m.modelo||'').toLowerCase().indexOf(busca.toLowerCase())>=0;
        var okDesc=String(m.descricao||'').toLowerCase().indexOf(busca.toLowerCase())>=0;
        if(!okPlaca && !okMod && !okDesc) return false;
      }
    }
    if(cid){
      var placa2=typeof frtManutPlacaOf==='function'?frtManutPlacaOf(m):(m.placa||'');
      var v=(frt_veiculos||[]).find(function(x){ return String(x.placa||'')===String(placa2||'') || String(x.id)===String(m.veiculo_id||''); });
      if(!v || String(v.contrato_id||'')!==String(cid)) return false;
    }
    return true;
  });

  // mais recentes primeiro
  rows=rows.slice().sort(function(a,b){
    var da=String(a.data||a.data_solicitacao||a.created_at||'');
    var db=String(b.data||b.data_solicitacao||b.created_at||'');
    return db.localeCompare(da);
  });

  var nCom=rows.filter(fdocManutTemAnexo).length;
  var nValVenc=rows.filter(function(m){
    var i=typeof frtManutValidadeInfo==='function'?frtManutValidadeInfo(m):null;
    return i&&i.nivel==='vencida';
  }).length;
  var nValAv=rows.filter(function(m){
    var i=typeof frtManutValidadeInfo==='function'?frtManutValidadeInfo(m):null;
    return i&&(i.nivel==='d10'||i.nivel==='d20');
  }).length;

  var banner=document.getElementById('frt-doc-alerta-banner');
  if(banner){
    if(busca || nCom || nValVenc){
      banner.style.display='';
      banner.textContent=(busca?('Filtro: '+busca+' · '):'')+rows.length+' manutenção(ões) · '+nCom+' com anexo'
        +(nValVenc?(' · '+nValVenc+' validade vencida'):'')
        +(nValAv?(' · '+nValAv+' validade a vencer'):'');
    } else banner.style.display='none';
  }

  var met=document.getElementById('fdoc-docs-metricas');
  if(met) met.innerHTML=[
    {l:'Total', v:rows.length, c:'#555'},
    {l:'Com anexo', v:nCom, c:'#185FA5'},
    {l:'Sem anexo', v:rows.length-nCom, c:'#888'},
    {l:'Val. a vencer', v:nValAv, c:'#854F0B'},
    {l:'Val. vencida', v:nValVenc, c:'#A32D2D'},
  ].map(function(x){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .5rem;text-align:center">'
      +'<div style="font-size:9px;color:#888;margin-bottom:2px">'+x.l+'</div>'
      +'<div style="font-size:17px;font-weight:700;color:'+x.c+'">'+x.v+'</div></div>';
  }).join('');

  if(!rows.length){
    tb.innerHTML='<tr><td colspan="9" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma manutenção encontrada. Ajuste os filtros ou cadastre em Frotas → Manutenções.</td></tr>';
    return;
  }

  tb.innerHTML=rows.map(function(m){
    var placa=typeof frtManutPlacaOf==='function'?frtManutPlacaOf(m):(m.placa||'—');
    var modelo=m.modelo||'';
    if(!modelo){
      var v=(frt_veiculos||[]).find(function(x){ return String(x.placa||'')===String(placa)||String(x.id)===String(m.veiculo_id||''); });
      if(v) modelo=v.modelo||'';
    }
    var data=m.data||m.data_solicitacao||'';
    var valInfo=typeof frtManutValidadeInfo==='function'?frtManutValidadeInfo(m):null;
    var valHtml=typeof frtManutValidadeBadgeHtml==='function'?frtManutValidadeBadgeHtml(valInfo):(m.validade?fmtD(m.validade):'—');
    var st=m.status||'—';
    var mid=String(m.id||'').replace(/'/g,"\\'");
    return '<tr>'
      +'<td style="font-family:monospace;font-weight:700">'+escHtml(placa||'—')+'</td>'
      +'<td style="font-size:12px">'+escHtml(modelo||'—')+'</td>'
      +'<td style="font-size:12px">'+escHtml(m.tipo||'—')+'</td>'
      +'<td style="font-size:12px">'+(data?fmtD(String(data).slice(0,10)):'—')+'</td>'
      +'<td style="font-size:11px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+escHtml(m.descricao||'')+'">'+escHtml((m.descricao||'—').slice(0,80))+'</td>'
      +'<td style="font-size:11px">'+valHtml+'</td>'
      +'<td><span class="bdg" style="font-size:11px">'+escHtml(st)+'</span></td>'
      +'<td style="white-space:nowrap">'+fdocManutAnexosHtml(m)+'</td>'
      +'<td style="white-space:nowrap">'
        +'<button class="btn btn-sm" onclick="event.stopPropagation();frtAbrirFichaManutencao(\''+mid+'\')" style="font-size:10px">Ficha</button> '
        +'<button class="btn btn-sm" onclick="event.stopPropagation();frtAbrirControleManutencao(\''+mid+'\')" style="font-size:10px">Controle</button>'
      +'</td></tr>';
  }).join('');
}

// ── Aba Multas ─────────────────────────────────────────────
function fdocRenderMultas(){
  var hoje=dataHojeLocal();
  var tb=document.getElementById('fdoc-mul-tbody'); if(!tb) return;
  var placa =((document.getElementById('mul-fil-placa')||{}).value||'').toUpperCase();
  var status=(document.getElementById('mul-fil-status')||{}).value||'';
  var mes   =(document.getElementById('mul-fil-mes')||{}).value||'';
  var motQ  =(document.getElementById('mul-fil-motorista')||{}).value||'';
  var cid   =(document.getElementById('mul-fil-cont')||{}).value||'';

  var multas=(frt_documentos||[]).filter(function(d){return d.tipo==='Multa' && fdocDocAtivo(d);});
  multas.forEach(function(d){
    if(d.status!=='Pago'&&d.status!=='Cancelado'&&d.data_vencimento&&d.data_vencimento<hoje) d.status='Vencido';
  });

  var rows=multas.filter(function(d){
    if(placa && !frtPlacaMatchBusca(d.placa, placa)) return false;
    if(status&&d.status!==status) return false;
    if(mes&&!(d.data_infracao||d.data_emissao||'').startsWith(mes)) return false;
    if(!frtFiltroMotorista(motQ, [d.condutor_responsavel], d.colaborador_id)) return false;
    if(!frtFiltroContratoVeiculo(d.placa, d.veiculo_id, cid)) return false;
    return true;
  });

  var nPend=rows.filter(function(d){return d.status==='Pendente';}).length;
  var vlPend=rows.filter(function(d){return d.status==='Pendente';}).reduce(function(s,d){return s+(d.valor||0);},0);
  var nPago=rows.filter(function(d){return d.status==='Pago';}).length;
  var nRec =rows.filter(function(d){return d.status==='Em recurso';}).length;
  var vlTotal=rows.reduce(function(s,d){return s+(d.valor||0);},0);

  var met=document.getElementById('fdoc-multas-metricas');
  if(met) met.innerHTML=[
    {l:'Total multas',    v:rows.length,               c:'#555'},
    {l:'Pendentes',       v:nPend,                     c:nPend>0?'#A32D2D':'#888'},
    {l:'Valor pendente',  v:'R$'+vlPend.toLocaleString('pt-BR',{minimumFractionDigits:2}), c:'#A32D2D'},
    {l:'Em recurso',      v:nRec,                      c:'#854F0B'},
    {l:'Pagas',           v:nPago,                     c:'#3B6D11'},
    {l:'Valor total',     v:'R$'+vlTotal.toLocaleString('pt-BR',{minimumFractionDigits:2}),c:'#555'},
  ].map(function(x){
    return '<div style="background:#fff;border:.5px solid #e0dfd8;border-radius:8px;padding:.6rem .5rem;text-align:center">'
      +'<div style="font-size:9px;color:#888;margin-bottom:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+x.l+'</div>'
      +'<div style="font-size:15px;font-weight:700;color:'+x.c+'">'+x.v+'</div></div>';
  }).join('');

  if(!rows.length){tb.innerHTML='<tr><td colspan="13" style="padding:1.5rem;text-align:center;color:#aaa">Nenhuma multa encontrada.</td></tr>';return;}

  tb.innerHTML=rows.map(function(d){
    var sc=FDOC_STATUS_COR[d.status]||{bg:'#f5f5f3',cor:'#888'};
    return '<tr>'
      +'<td style="font-family:monospace;font-weight:700">'+escHtml(d.placa||'—')+'</td>'
      +'<td style="font-size:11px;font-family:monospace">'+escHtml(d.numero_auto||d.numero_documento||'—')
      +(d.codigo_infracao?'<div style="font-size:10px;color:#888">'+escHtml(d.codigo_infracao)+(d.tipo_infracao?' · '+escHtml(d.tipo_infracao):'')+'</div>':'')
      +'</td>'
      +'<td style="font-size:11px">'+escHtml(d.orgao_emissor||'—')+'</td>'
      +'<td style="font-size:12px">'+(d.data_infracao?fmtD(d.data_infracao):d.data_emissao?fmtD(d.data_emissao):'—')+'</td>'
      +'<td style="font-size:11px;color:#888;max-width:160px;overflow:hidden;text-overflow:ellipsis" title="'+escHtml([d.municipio_infracao,d.local_infracao].filter(Boolean).join(' — '))+'">'
      +(d.municipio_infracao?'<div style="color:#555;font-weight:600">'+escHtml(d.municipio_infracao)+'</div>':'')
      +escHtml(d.local_infracao||(d.municipio_infracao?'':'—'))+'</td>'
      +'<td style="font-size:12px">'+escHtml(d.condutor_responsavel||'—')+'</td>'
      +'<td style="text-align:center;font-size:12px;color:#A32D2D;font-weight:600">'+(d.pontos_cnh||'—')
      +(d.gravidade?'<div style="font-size:10px;color:#888;font-weight:500">'+escHtml(d.gravidade)+'</div>':'')
      +'</td>'
      +'<td style="text-align:right;font-weight:600;color:#A32D2D">'+(d.valor?'R$'+Number(d.valor).toLocaleString('pt-BR',{minimumFractionDigits:2}):'—')+'</td>'
      +'<td style="font-size:12px">'+(d.data_vencimento?fmtD(d.data_vencimento):'—')+'</td>'
      +'<td style="text-align:center">'+(d.desconto_disponivel
        ?('<span style="color:#3B6D11;font-weight:600">Sim</span>'+(d.valor_desconto!=null&&d.valor_desconto!==''?'<div style="font-size:10px;color:#3B6D11">R$'+Number(d.valor_desconto).toLocaleString('pt-BR',{minimumFractionDigits:2})+'</div>':''))
        :'—')+'</td>'
      +'<td><span class="bdg" style="background:'+sc.bg+';color:'+sc.cor+';font-size:11px">'+escHtml(d.status||'Pendente')+'</span></td>'
      +'<td style="font-size:11px;color:#888">'+escHtml(d.status_recurso||'—')+'</td>'
      +'<td style="white-space:nowrap">'
      +'<button class="btn btn-sm" onclick="fdocVerDoc(\''+d.id+'\')" style="font-size:10px">Ver</button>'
      +(d.status==='Pendente'?'<button class="btn btn-sm" onclick="fdocPagarDoc(\''+d.id+'\')" style="font-size:10px;color:#3B6D11;border-color:#3B6D11;margin-left:3px">Pagar</button>':'')
      +'</td></tr>';
  }).join('');
}

// ── Aba Alertas ────────────────────────────────────────────
function fdocRenderAlertas(){
  var hoje=dataHojeLocal();
  var em7 =_diasAdiante(7);
  var em15=_diasAdiante(15);
  var em30=_diasAdiante(30);
  var todos=(frt_documentos||[]).filter(function(d){return d.tipo!=='Multa';});
  var wrap=document.getElementById('fdoc-alertas-lista'); if(!wrap) return;

  var grupos=[
    {label:'🚨 Vencidos — ação imediata',       cor:'#A32D2D', bg:'#FCEBEB',
     items:todos.filter(function(d){return d.status==='Vencido';}).sort(function(a,b){return(a.data_vencimento||'')<(b.data_vencimento||'')?-1:1;})},
    {label:'⚠ Vencem em até 7 dias',            cor:'#A32D2D', bg:'#FEF0EE',
     items:todos.filter(function(d){return d.status!=='Pago'&&d.status!=='Cancelado'&&d.data_vencimento&&d.data_vencimento>=hoje&&d.data_vencimento<=em7;})},
    {label:'🟠 Vencem entre 8 e 15 dias',       cor:'#854F0B', bg:'#FEF3E2',
     items:todos.filter(function(d){return d.status!=='Pago'&&d.status!=='Cancelado'&&d.data_vencimento&&d.data_vencimento>em7&&d.data_vencimento<=em15;})},
    {label:'🟡 Vencem entre 16 e 30 dias',      cor:'#854F0B', bg:'#FEFCEE',
     items:todos.filter(function(d){return d.status!=='Pago'&&d.status!=='Cancelado'&&d.data_vencimento&&d.data_vencimento>em15&&d.data_vencimento<=em30;})},
  ];

  var html='';
  var totalAlertas=0;
  grupos.forEach(function(g){
    if(!g.items.length) return;
    totalAlertas+=g.items.length;
    html+='<div class="card">'
      +'<div class="ch" style="background:'+g.bg+';border-radius:8px 8px 0 0">'
      +'<span class="ct" style="color:'+g.cor+'">'+g.label+'</span>'
      +'<span style="background:'+g.cor+';color:#fff;border-radius:10px;padding:1px 10px;font-size:11px;font-weight:700">'+g.items.length+'</span>'
      +'</div>'
      +'<div style="padding:.5rem;display:grid;gap:4px">'
      +g.items.map(function(d){
        var dias=fdocDiasVenc(d.data_vencimento,hoje);
        var v=frt_veiculos.find(function(x){return x.placa===d.placa;})||{};
        return '<div style="display:flex;align-items:center;gap:10px;padding:6px 8px;background:#fff;border-radius:7px;border:.5px solid #f0efe8">'
          +'<span style="font-family:monospace;font-size:12px;font-weight:700;width:85px;flex-shrink:0">'+escHtml(d.placa||'—')+'</span>'
          +'<span style="font-size:11px;color:#888;flex-shrink:0;width:60px">'+escHtml(v.modelo||'—').slice(0,8)+'</span>'
          +'<span style="font-size:12px;flex:1">'+escHtml(d.tipo)+'</span>'
          +'<span style="font-size:11px;color:#888">'+(d.numero_documento||'—')+'</span>'
          +'<span style="font-size:12px;font-weight:700;color:'+g.cor+';flex-shrink:0">'
            +(dias===null?'—':dias<0?Math.abs(dias)+'d atrás':dias===0?'Hoje!':dias+'d')
          +'</span>'
          +'<button class="btn btn-sm" onclick="fdocVerDoc(\''+d.id+'\')" style="font-size:10px;flex-shrink:0">Ver</button>'
          +(d.status!=='Pago'?'<button class="btn btn-sm" onclick="fdocPagarDoc(\''+d.id+'\')" style="font-size:10px;color:#3B6D11;border-color:#3B6D11;flex-shrink:0">Pagar</button>':'')
          +'</div>';
      }).join('')
      +'</div></div>';
  });

  if(!totalAlertas){
    html='<div class="card" style="text-align:center;padding:2rem;color:#3B6D11">'
      +'<div style="font-size:40px;margin-bottom:.5rem">✅</div>'
      +'<div style="font-size:14px;font-weight:600">Nenhum alerta de vencimento!</div>'
      +'<div style="font-size:12px;color:#888;margin-top:4px">Todos os documentos estão em dia nos próximos 30 dias.</div>'
      +'</div>';
  }
  wrap.innerHTML=html;
}

// ── Modais ─────────────────────────────────────────────────
function fdocNovoDoc(){ fdocAbrirModal(null, false); }
function fdocNovaMulta(){
  try{ fdocAbrirModal(null, true); }
  catch(e){
    console.error('fdocNovaMulta', e);
    if(typeof progShowToast==='function') progShowToast('Não foi possível abrir a multa. Recarregue a página.','erro');
  }
}
function fdocVerDoc(id){
  var d=(frt_documentos||[]).find(function(x){return x.id===id;});
  if(d) fdocAbrirModal(d, d.tipo==='Multa');
}

function fdocAbrirModal(d, isMulta){
  var isNew=!d; d=d||{};
  var tipoIni=isMulta?'Multa':fdocNormTipo(d.tipo||'');
  var optsTipo=isMulta?'<option selected>Multa</option>':fdocOptsTipoVeiculoHtml(tipoIni);
  var statusList=isMulta?FDOC_STATUS:FDOC_STATUS_DOC;
  var optsStatus=statusList.map(function(s){return '<option'+(d.status===s?' selected':'')+'>'+s+'</option>';}).join('');
  var placaIni=d.placa||'';
  var veicIni=(frt_veiculos||[]).find(function(v){return frtNormPlaca(v.placa)===frtNormPlaca(placaIni);});
  var placaLabel=veicIni?(veicIni.placa+' — '+(veicIni.modelo||'')):placaIni;

  var extraMulta=isMulta?''
    +'<div class="fg"><label style="font-size:11px">Nº Auto de Infração</label><input class="inp" id="fdoc-num-auto" style="width:100%" value="'+escHtml(d.numero_auto||'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Órgão emissor</label><input class="inp" id="fdoc-orgao" style="width:100%" value="'+escHtml(d.orgao_emissor||'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Data da infração</label><input class="inp" type="date" id="fdoc-data-inf" value="'+(d.data_infracao||(isNew?dataHojeLocal():''))+'" style="width:100%" onchange="fdocAtualizarCondutorAuto()"/></div>'
    +'<div class="fg"><label style="font-size:11px">Hora</label><input class="inp" type="time" id="fdoc-hora-inf" value="'+(d.hora_infracao||'')+'" style="width:100%" onchange="fdocAtualizarCondutorAuto()"/></div>'
    +'<div class="fg"><label style="font-size:11px">Local da infração</label><input class="inp" id="fdoc-local-inf" style="width:100%" value="'+escHtml(d.local_infracao||'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Município da infração</label><input class="inp" id="fdoc-municipio" style="width:100%" value="'+escHtml(d.municipio_infracao||'')+'" placeholder="Cidade / UF"/></div>'
    +'<div class="fg" style="grid-column:span 2;position:relative"><label style="font-size:11px">Condutor responsável *</label>'
    +'<input class="inp" id="fdoc-condutor-busca" placeholder="Busca automática pela escala; se não achar, digite nome ou RE..." autocomplete="off" style="width:100%" value="'+escHtml(d.condutor_responsavel||'')+'"/>'
    +'<div id="fdoc-condutor-lista" style="display:none;position:absolute;left:0;right:0;top:100%;z-index:21;border:.5px solid #e0dfd8;border-radius:6px;background:#fff;max-height:200px;overflow-y:auto;box-shadow:0 4px 12px rgba(0,0,0,.08)"></div>'
    +'<input type="hidden" id="fdoc-condutor" value="'+escHtml(d.condutor_responsavel||'')+'"/>'
    +'<input type="hidden" id="fdoc-colab-id" value="'+escHtml(d.colaborador_id||'')+'"/>'
    +'<div id="fdoc-condutor-info" style="font-size:11px;padding:8px;margin-top:6px;background:#f9f9f7;border-radius:6px;border:.5px solid #e0dfd8">Informe placa e data da infração — o sistema busca o motorista do veículo naquele dia.</div></div>'
    +'<div class="fg"><label style="font-size:11px">Código</label><input class="inp" id="fdoc-cod-inf" style="width:100%" value="'+escHtml(d.codigo_infracao||'')+'" placeholder="Ex.: 745-50"/></div>'
    +'<div class="fg"><label style="font-size:11px">Tipo de infração</label><select class="inp" id="fdoc-tipo-inf" data-nosort style="width:100%">'+fdocOptsTipoInfracao(d.tipo_infracao||'')+'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Pontos CNH</label><input class="inp" type="number" id="fdoc-pontos" style="width:100%" value="'+(d.pontos_cnh||0)+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Gravidade</label><select class="inp" id="fdoc-gravidade" data-nosort style="width:100%" onchange="fdocOnGravidadeChange()">'+fdocOptsGravidade(d.gravidade||'')+'</select></div>'
    +'<div class="fg" style="display:flex;align-items:center;gap:8px;padding-top:1.2rem">'
    +'<input type="checkbox" id="fdoc-desconto" '+(d.desconto_disponivel?'checked':'')+' style="width:16px;height:16px" onchange="fdocToggleValorDesconto()">'
    +'<label for="fdoc-desconto" style="font-size:12px;cursor:pointer">Desconto disponível (pagamento antecipado)</label></div>'
    +'<div class="fg" id="fdoc-valor-desc-wrap" style="'+(d.desconto_disponivel?'':'display:none')+'"><label style="font-size:11px">Valor C/ Desconto (R$)</label>'
    +'<input class="inp" type="number" step="0.01" id="fdoc-valor-desc" style="width:100%" value="'+(d.valor_desconto!=null&&d.valor_desconto!==''?d.valor_desconto:'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Status do recurso</label>'
    +'<select class="inp" id="fdoc-status-rec" data-nosort style="width:100%"><option value="">Sem recurso</option>'
    +'<option'+(d.status_recurso==='Apresentado'?' selected':'')+'>Apresentado</option>'
    +'<option'+(d.status_recurso==='Deferido'?' selected':'')+'>Deferido</option>'
    +'<option'+(d.status_recurso==='Indeferido'?' selected':'')+'>Indeferido</option></select></div>'
    : '';

  var anexoHtml=!isMulta?''
    +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Anexo</label>'
    +'<input type="file" id="fdoc-anexo-file" accept="image/*,.pdf,application/pdf" style="width:100%;font-size:12px"/>'
    +'<input type="hidden" id="fdoc-anexo-url" value="'+escHtml(d.anexo_url||'')+'"/>'
    +'<div id="fdoc-anexo-info" style="font-size:11px;margin-top:4px;color:#555">'
    +(d.anexo_url?'📎 <a href="'+escHtml(d.anexo_url)+'" target="_blank" rel="noopener">Ver anexo atual</a>':'Nenhum anexo')
    +'</div></div>'
    : '';

  setModal('<div class="modal-bg"><div class="modal" style="max-width:640px;max-height:90vh;overflow-y:auto">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:1rem">'
    +'<h3 style="margin:0;font-size:15px">'+(isNew?(isMulta?'🚦 Nova Multa':'📄 Novo Documento'):(isMulta?'🚦 Editar Multa':'📄 Editar Documento'))+'</h3>'
    +'<button class="btn" onclick="closeModal()" style="margin-left:auto;padding:3px 9px">✕</button>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1rem">'
    +'<div class="fg" style="grid-column:span 2;position:relative"><label style="font-size:11px">Veículo (placa) *</label>'
    +'<input class="inp" id="fdoc-placa-busca" placeholder="Digite a placa ou modelo..." autocomplete="off" style="width:100%" value="'+escHtml(placaLabel)+'"/>'
    +'<div id="fdoc-placa-lista" style="display:none;position:absolute;left:0;right:0;top:100%;z-index:20;border:.5px solid #e0dfd8;border-radius:6px;background:#fff;max-height:180px;overflow-y:auto;box-shadow:0 4px 12px rgba(0,0,0,.08)"></div>'
    +'<input type="hidden" id="fdoc-placa" value="'+escHtml(placaIni)+'"/>'
    +'<div id="fdoc-placa-info" style="font-size:11px;color:#3B6D11;font-weight:600;margin-top:3px;'+(placaIni?'':'display:none')+'">'+(placaIni?'✅ '+escHtml(placaLabel):'')+'</div></div>'
    +'<div class="fg"><label style="font-size:11px">Tipo de documento *</label>'
    +'<select class="inp" id="fdoc-tipo" style="width:100%"'+(isMulta?'':' onchange="fdocAtualizarCamposTipo()"')+'><option value="">Selecione</option>'+optsTipo+'</select></div>'
    +'<div class="fg"><label style="font-size:11px">Nº Documento</label>'
    +'<input class="inp" id="fdoc-numero" style="width:100%" value="'+escHtml(d.numero_documento||d.numero||'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Data de emissão</label>'
    +'<input class="inp" type="date" id="fdoc-emissao" value="'+(d.data_emissao||d.emissao||'')+'" style="width:100%"/></div>'
    +'<div class="fg"><label style="font-size:11px">Data de vencimento</label>'
    +'<input class="inp" type="date" id="fdoc-vencimento" value="'+(d.data_vencimento||d.validade||'')+'" style="width:100%"/></div>'
    +'<div id="fdoc-campos-dinamicos" style="display:contents"></div>'
    +'<div class="fg"><label style="font-size:11px">Valor (R$)</label>'
    +'<input class="inp" type="number" step="0.01" id="fdoc-valor" style="width:100%" value="'+(d.valor||'')+'"/></div>'
    +'<div class="fg"><label style="font-size:11px">Status</label>'
    +'<select class="inp" id="fdoc-status" data-nosort style="width:100%">'+optsStatus+'</select></div>'
    +extraMulta
    +anexoHtml
    +'<div class="fg" style="grid-column:span 2"><label style="font-size:11px">Observação</label>'
    +'<textarea class="inp" id="fdoc-obs" style="width:100%;height:52px;resize:vertical">'+escHtml(d.observacao||'')+'</textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +(!isNew&&isMulta?'<button type="button" class="btn" id="fdoc-excluir-btn" style="color:#A32D2D;border-color:#A32D2D">Excluir</button>':'')
    +'<button class="btn btn-pri" id="fdoc-salvar-btn" style="flex:2">Salvar</button>'
    +'</div></div></div>');

  // Guardar valores iniciais para campos dinâmicos
  window._fdocEditVals={
    data_validade:d.data_validade||'',
    empresa_executora:d.empresa_executora||'',
    laudo_certificado:d.laudo_certificado||''
  };
  setTimeout(function(){
    // Busca digitável de placa (parcial — placa/modelo/marca)
    (function(){
      var inp=document.getElementById('fdoc-placa-busca');
      var lista=document.getElementById('fdoc-placa-lista');
      var hid=document.getElementById('fdoc-placa');
      var info=document.getElementById('fdoc-placa-info');
      if(!inp||!lista||!hid) return;

      function selecionar(v){
        hid.value=v.placa||'';
        inp.value=(v.placa||'')+(v.modelo?' — '+v.modelo:'');
        if(info){ info.style.display='block'; info.innerHTML='✅ '+escHtml(inp.value); }
        lista.style.display='none';
        if(isMulta){
          var di=document.getElementById('fdoc-data-inf');
          if(di && !di.value) di.value=dataHojeLocal();
          fdocAtualizarCondutorAuto();
        }
      }

      function renderLista(busca){
        var raw=String(busca||'');
        // Se o campo já está no formato "PLACA — modelo", filtrar só pela placa
        if(raw.indexOf('—')>=0) raw=raw.split('—')[0];
        var b=raw.toLowerCase().replace(/[^a-z0-9]/gi,'');
        var q=raw.toLowerCase().trim();
        var rows=(frt_veiculos||[]).filter(function(v){
          if(v.ativo===false) return false;
          var placa=String(v.placa||'').toLowerCase().replace(/[^a-z0-9]/gi,'');
          var modelo=String(v.modelo||'').toLowerCase();
          var marca=String(v.marca||'').toLowerCase();
          if(!b && !q) return true;
          return (b && placa.indexOf(b)>=0) || (q && (modelo.indexOf(q)>=0 || marca.indexOf(q)>=0));
        }).slice(0,12);
        if(!rows.length){
          lista.innerHTML='<div style="padding:8px 12px;font-size:12px;color:#aaa">Nenhum veículo encontrado</div>';
          lista.style.display='block';
          return;
        }
        lista.innerHTML=rows.map(function(v){
          return '<div data-placa="'+escHtml(v.placa)+'" style="padding:8px 12px;cursor:pointer;border-bottom:.5px solid #f5f5f3;font-size:12px;display:flex;justify-content:space-between;gap:8px">'
            +'<span><b style="font-family:monospace">'+escHtml(v.placa)+'</b> — '+escHtml(v.modelo||'')+'</span>'
            +'<span style="font-size:10px;color:#888">'+escHtml(v.status||'')+'</span></div>';
        }).join('');
        lista.style.display='block';
        lista.querySelectorAll('[data-placa]').forEach(function(el){
          el.onmousedown=function(e){
            e.preventDefault();
            var v=(frt_veiculos||[]).find(function(x){return x.placa===el.getAttribute('data-placa');});
            if(v) selecionar(v);
          };
          el.onmouseover=function(){ this.style.background='#f0f5ff'; };
          el.onmouseout=function(){ this.style.background=''; };
        });
      }

      inp.addEventListener('input', function(){
        hid.value='';
        if(info) info.style.display='none';
        renderLista(inp.value);
      });
      inp.addEventListener('focus', function(){ renderLista(inp.value); });
      inp.addEventListener('blur', function(){ setTimeout(function(){ lista.style.display='none'; }, 150); });
      inp.addEventListener('keydown', function(e){
        if(e.key==='Enter'){
          e.preventDefault();
          var first=lista.querySelector('[data-placa]');
          if(first){
            var v=(frt_veiculos||[]).find(function(x){return x.placa===first.getAttribute('data-placa');});
            if(v) selecionar(v);
          }
        }
      });
    })();

    if(isMulta){
      fdocBindCondutorBusca(d);
      if(!(d.colaborador_id||d.condutor_responsavel) && (d.placa||placaIni) && (d.data_infracao||isNew)) fdocAtualizarCondutorAuto();
    } else {
      fdocAtualizarCamposTipo();
    }
    var bx=document.getElementById('fdoc-excluir-btn');
    if(bx) bx.onclick=function(){ fdocExcluirMulta(d.id); };
    var btn=document.getElementById('fdoc-salvar-btn');
    if(!btn) return;
    btn.onclick=async function(){
      var placa   =(document.getElementById('fdoc-placa')||{}).value||'';
      if(!placa){
        var dig=((document.getElementById('fdoc-placa-busca')||{}).value||'').trim();
        if(dig){
          var match=(frt_veiculos||[]).find(function(v){
            return frtNormPlaca(v.placa)===frtNormPlaca(dig.split('—')[0].trim())
              || frtNormPlaca(v.placa)===frtNormPlaca(dig);
          });
          if(match) placa=match.placa;
        }
      }
      var tipo    =fdocNormTipo((document.getElementById('fdoc-tipo')||{}).value||'');
      var numero  =(document.getElementById('fdoc-numero')||{}).value||'';
      var emissao =(document.getElementById('fdoc-emissao')||{}).value||null;
      var venc    =(document.getElementById('fdoc-vencimento')||{}).value||null;
      var valorRaw=((document.getElementById('fdoc-valor')||{}).value||'').trim();
      var valor   =valorRaw===''?null:(parseFloat(valorRaw));
      if(valor!=null && isNaN(valor)) valor=null;
      var status  =(document.getElementById('fdoc-status')||{}).value||'Pendente';
      var obs     =(document.getElementById('fdoc-obs')||{}).value||'';
      if(!placa||!tipo){progShowToast('⚠ Selecione a placa na lista e o tipo.');return;}
      if(isMulta===false && tipo==='Multa'){progShowToast('⚠ Use a aba Multas para registrar multa.');return;}
      var dados={
        placa:placa, tipo:tipo, numero_documento:numero, numero:numero,
        data_emissao:emissao, emissao:emissao,
        data_vencimento:venc, validade:venc,
        valor:valor, status:status, observacao:obs
      };
      if(!isMulta){
        var g=fdocGrupoTipo(tipo);
        var valEl=document.getElementById('fdoc-validade');
        var empEl=document.getElementById('fdoc-empresa');
        var lauEl=document.getElementById('fdoc-laudo');
        if(g>=2) dados.data_validade=(valEl&&valEl.value)||null;
        if(g===3){
          dados.empresa_executora=(empEl&&empEl.value)||'';
          dados.laudo_certificado=(lauEl&&lauEl.value)||'';
        }
        var anexoUrl=(document.getElementById('fdoc-anexo-url')||{}).value||'';
        var fileInp=document.getElementById('fdoc-anexo-file');
        var file=fileInp&&fileInp.files&&fileInp.files[0]?fileInp.files[0]:null;
        if(file&&typeof sbUpload==='function'&&!DEMO){
          btn.disabled=true; btn.textContent='Enviando anexo...';
          try{
            var up=await sbUpload(file,'frotas/documentos/'+Date.now()+'_'+file.name);
            if(up) anexoUrl=up;
          }catch(e){ console.warn('fdoc anexo',e); }
          btn.disabled=false; btn.textContent='Salvar';
        }
        if(anexoUrl) dados.anexo_url=anexoUrl;
      }
      if(isMulta){
        fdocResolverCondutorDigitado();
        var colabHid=(document.getElementById('fdoc-colab-id')||{}).value||'';
        var condutorNome=(document.getElementById('fdoc-condutor')||{}).value||'';
        if(!colabHid && !condutorNome){
          progShowToast('⚠ Não achei motorista na escala desse veículo/dia. Busque o colaborador por nome ou RE.','erro');
          fdocAbrirListaCondutor(true);
          return;
        }
        var temDesc=!!(document.getElementById('fdoc-desconto')||{}).checked;
        var descRaw=((document.getElementById('fdoc-valor-desc')||{}).value||'').trim();
        var valorDesc=descRaw===''?null:parseFloat(descRaw);
        if(valorDesc!=null && isNaN(valorDesc)) valorDesc=null;
        Object.assign(dados,{
          numero_auto:(document.getElementById('fdoc-num-auto')||{}).value||'',
          orgao_emissor:(document.getElementById('fdoc-orgao')||{}).value||'',
          data_infracao:(document.getElementById('fdoc-data-inf')||{}).value||null,
          hora_infracao:(document.getElementById('fdoc-hora-inf')||{}).value||'',
          local_infracao:(document.getElementById('fdoc-local-inf')||{}).value||'',
          municipio_infracao:(document.getElementById('fdoc-municipio')||{}).value||'',
          codigo_infracao:(document.getElementById('fdoc-cod-inf')||{}).value||'',
          tipo_infracao:(document.getElementById('fdoc-tipo-inf')||{}).value||'',
          gravidade:(document.getElementById('fdoc-gravidade')||{}).value||'',
          condutor_responsavel:condutorNome,
          colaborador_id:colabHid||null,
          pontos_cnh:parseInt((document.getElementById('fdoc-pontos')||{}).value)||0,
          desconto_disponivel:temDesc,
          valor_desconto:temDesc?valorDesc:null,
          status_recurso:(document.getElementById('fdoc-status-rec')||{}).value||'',
        });
      }
      if(isNew){
        dados.id=Date.now().toString();
        if(!frt_documentos) frt_documentos=[];
        frt_documentos.unshift(fdocNormRow(dados));
      } else {
        var idx=(frt_documentos||[]).findIndex(function(x){return x.id===d.id;});
        if(idx>=0) frt_documentos[idx]=fdocNormRow(Object.assign({},d,dados));
      }
      var afterSave=function(){
        closeModal();
        if(isMulta) fdocRenderMultas(); else frtDocRender();
        if(typeof avColInvalidarCacheFrota==='function') avColInvalidarCacheFrota(); // recalc da avaliação relê multas
        progShowToast('✅ Documento salvo.');
      };
      if(DEMO){ afterSave(); return; }
      btn.disabled=true; btn.textContent='Salvando...';
      var payload=fdocPayloadDb(dados);
      ['created_at','updated_at','data_emissao','data_vencimento','numero_documento','observacao'].forEach(function(k){ delete payload[k]; });
      var gravar=function(p, silent){
        return Promise.resolve(isNew?sbInsert('frotas_documentos',p,{silent:!!silent}):sbUpdate('frotas_documentos',p,'id=eq.'+d.id,{silent:!!silent}));
      };
      gravar(payload, true).then(function(res){
        if(!fdocSaveOk(res) && payload.valor!=null){
          window._frotasDocsTemValor=false;
          var pVal=Object.assign({},payload);
          delete pVal.valor;
          return gravar(pVal, true);
        }
        return res;
      }).then(function(res){
        if(!fdocSaveOk(res)){
          window._frotasDocsTemMultaExtra=false;
          var pExtra=Object.assign({},payload);
          delete pExtra.valor;
          FDOC_MULTA_EXTRA_COLS.forEach(function(k){ delete pExtra[k]; });
          return gravar(pExtra, true);
        }
        return res;
      }).then(function(res){
        if(!fdocSaveOk(res)){
          var p2=Object.assign({},payload);
          delete p2.valor;
          ['colaborador_id','anexo_url','data_validade','empresa_executora','laudo_certificado','observacao',
           'numero_auto','orgao_emissor','data_infracao','hora_infracao','local_infracao','condutor_responsavel',
           'pontos_cnh','desconto_disponivel','status_recurso','pago','data_pagamento',
           'municipio_infracao','codigo_infracao','tipo_infracao','gravidade','valor_desconto',
           'exclusao_justificativa','excluido_por',
           'created_at','updated_at','data_emissao','data_vencimento','numero_documento'].forEach(function(k){ delete p2[k]; });
          return gravar(p2, false);
        }
        return res;
      }).then(function(res){
        btn.disabled=false; btn.textContent='Salvar';
        if(!fdocSaveOk(res)){
          if(isNew) frt_documentos=(frt_documentos||[]).filter(function(x){return String(x.id)!==String(dados.id);});
          progShowToast('Não foi possível gravar. Se o erro for coluna valor, rode sql_frotas_documentos_valor.sql (não aplicado pelo ERP).','erro');
          return;
        }
        var saved=Array.isArray(res)?res[0]:res;
        if(isNew && saved && saved.id){
          var first=frt_documentos[0];
          if(first && String(first.id)===String(dados.id)) first.id=saved.id;
        }
        afterSave();
      }).catch(function(){
        btn.disabled=false; btn.textContent='Salvar';
        progShowToast('Erro ao gravar o documento.','erro');
      });
    };
  },50);
}

function fdocAtualizarCamposTipo(){
  var wrap=document.getElementById('fdoc-campos-dinamicos');
  if(!wrap) return;
  var tipo=fdocNormTipo((document.getElementById('fdoc-tipo')||{}).value||'');
  var g=fdocGrupoTipo(tipo);
  var v=window._fdocEditVals||{};
  var html='';
  if(g>=2){
    html+='<div class="fg"><label style="font-size:11px">Data de validade</label>'
      +'<input class="inp" type="date" id="fdoc-validade" value="'+(v.data_validade||'')+'" style="width:100%"/></div>';
  }
  if(g===3){
    html+='<div class="fg"><label style="font-size:11px">Empresa executora</label>'
      +'<input class="inp" id="fdoc-empresa" style="width:100%" value="'+escHtml(v.empresa_executora||'')+'"/></div>'
      +'<div class="fg"><label style="font-size:11px">Laudo / Certificado</label>'
      +'<input class="inp" id="fdoc-laudo" style="width:100%" value="'+escHtml(v.laudo_certificado||'')+'"/></div>';
  }
  wrap.innerHTML=html;
}


async function fdocInsertComFallback(payload){
  var p=Object.assign({}, payload||{});
  ['created_at','updated_at','data_emissao','data_vencimento','numero_documento','observacao','id','_linha','_placaCad','_condFonte'].forEach(function(k){ delete p[k]; });
  var nuclear=['colaborador_id','anexo_url','data_validade','empresa_executora','laudo_certificado',
    'numero_auto','orgao_emissor','data_infracao','hora_infracao','local_infracao','condutor_responsavel',
    'pontos_cnh','desconto_disponivel','status_recurso','pago','data_pagamento'];
  var extra=(typeof FDOC_MULTA_EXTRA_COLS!=='undefined'?FDOC_MULTA_EXTRA_COLS:[]);
  for(var tentativa=0; tentativa<12; tentativa++){
    var res=await sbInsert('frotas_documentos', p, {silent:true});
    if(typeof fdocSaveOk==='function'?fdocSaveOk(res):(res&&(res.length||res===true))) return res;
    var err=String(window._sbLastInsertErr||'');
    var m=err.match(/Could not find the '([^']+)' column/i);
    if(m && m[1] && Object.prototype.hasOwnProperty.call(p, m[1])){
      if(m[1]==='valor') window._frotasDocsTemValor=false;
      if(extra.indexOf(m[1])>=0) window._frotasDocsTemMultaExtra=false;
      delete p[m[1]];
      continue;
    }
    if(p.valor!=null){ window._frotasDocsTemValor=false; delete p.valor; continue; }
    var tinha=false;
    extra.forEach(function(k){ if(k in p){ tinha=true; delete p[k]; } });
    if(tinha){ window._frotasDocsTemMultaExtra=false; continue; }
    nuclear.forEach(function(k){ delete p[k]; });
    return sbInsert('frotas_documentos', p, {silent:true});
  }
  return null;
}

async function fdocUpdateComFallback(id, payload){
  if(!id) return false;
  if(typeof isUUID==='function' && !isUUID(id)) return false;
  var p=Object.assign({}, payload||{});
  ['created_at','updated_at','data_emissao','data_vencimento','numero_documento','observacao','id','_linha','_placaCad','_condFonte','_existId','_acao','tipo'].forEach(function(k){ delete p[k]; });
  var extra=(typeof FDOC_MULTA_EXTRA_COLS!=='undefined'?FDOC_MULTA_EXTRA_COLS:[]);
  for(var tentativa=0; tentativa<12; tentativa++){
    if(!Object.keys(p).length) return false;
    var ok=await sbUpdate('frotas_documentos', p, 'id=eq.'+id, {silent:true});
    if(ok) return true;
    var err=String(window._sbLastUpdateErr||window._sbLastInsertErr||'');
    var m=err.match(/Could not find the '([^']+)' column/i);
    if(m && m[1] && Object.prototype.hasOwnProperty.call(p, m[1])){
      if(m[1]==='valor') window._frotasDocsTemValor=false;
      if(extra.indexOf(m[1])>=0) window._frotasDocsTemMultaExtra=false;
      delete p[m[1]];
      continue;
    }
    if(p.valor!=null){ window._frotasDocsTemValor=false; delete p.valor; continue; }
    var tinha=false;
    extra.forEach(function(k){ if(k in p){ tinha=true; delete p[k]; } });
    if(tinha){ window._frotasDocsTemMultaExtra=false; continue; }
    return false;
  }
  return false;
}
function fdocSaveOk(res){
  if(res===true) return true;
  if(!res || res===false) return false;
  if(Array.isArray(res)) return res.length>0;
  return true;
}
function fdocNormBuscaColab(s){
  try{ return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim(); }
  catch(e){ return String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(); }
}
function fdocColabPassaBusca(c, q){
  if(!c) return false;
  if(c.ativo===false || c.dispensado) return false;
  var nq=fdocNormBuscaColab(q);
  var dig=String(q||'').replace(/\D/g,'');
  if(!nq && !dig) return false;
  var nome=fdocNormBuscaColab(c.nome);
  if(nq && nome.indexOf(nq)>=0) return true;
  var re=String(c.re||c.matricula||'').replace(/\D/g,'');
  if(dig && re){
    var reN=re.replace(/^0+/,'')||'0';
    var digN=dig.replace(/^0+/,'')||'0';
    if(re.indexOf(dig)>=0 || reN===digN || reN.indexOf(digN)>=0) return true;
  }
  return false;
}
function fdocFiltrarColabs(q){
  return (colaboradores||[]).filter(function(c){ return fdocColabPassaBusca(c, q); }).slice(0,20);
}
function fdocSelecionarCondutor(col, origem){
  if(!col) return;
  var busca=document.getElementById('fdoc-condutor-busca');
  var hidNome=document.getElementById('fdoc-condutor');
  var hidId=document.getElementById('fdoc-colab-id');
  var lista=document.getElementById('fdoc-condutor-lista');
  var info=document.getElementById('fdoc-condutor-info');
  var label=(col.nome||'')+(col.re?' · RE '+col.re:'');
  if(busca) busca.value=label;
  if(hidNome) hidNome.value=col.nome||'';
  if(hidId) hidId.value=col.id||'';
  if(lista) lista.style.display='none';
  if(info){
    var fonte=origem==='escala'?'encontrado na escala/portaria do dia':'selecionado na busca (nome/RE)';
    info.innerHTML='<span style="color:#3B6D11;font-weight:600">✅ '+escHtml(col.nome||'—')+'</span>'
      +'<div style="font-size:10px;color:#666;margin-top:2px">'+(col.re?'RE '+escHtml(String(col.re))+' · ':'')+fonte+'</div>';
  }
}
function fdocRenderCondutorLista(q, abrir){
  var lista=document.getElementById('fdoc-condutor-lista');
  if(!lista) return;
  var rows=String(q||'').trim()?fdocFiltrarColabs(q):[];
  if(!rows.length){
    lista.innerHTML='<div style="padding:10px 12px;font-size:12px;color:#854F0B">Nenhum colaborador. Digite o nome ou o RE para buscar.</div>';
    lista.style.display=abrir?'block':'none';
    return;
  }
  lista.innerHTML=rows.map(function(c){
    return '<div data-cid="'+escHtml(String(c.id))+'" style="padding:8px 12px;cursor:pointer;border-bottom:.5px solid #f5f5f3;font-size:12px;display:flex;justify-content:space-between;gap:8px">'
      +'<span><b>'+escHtml(c.nome||'')+'</b></span>'
      +'<span style="font-size:10px;color:#888">RE '+escHtml(String(c.re||'—'))+'</span></div>';
  }).join('');
  lista.style.display='block';
  lista.querySelectorAll('[data-cid]').forEach(function(el){
    el.onmousedown=function(e){
      e.preventDefault();
      var col=(colaboradores||[]).find(function(x){return String(x.id)===el.getAttribute('data-cid');});
      if(col) fdocSelecionarCondutor(col, 'manual');
    };
    el.onmouseover=function(){ this.style.background='#f0f5ff'; };
    el.onmouseout=function(){ this.style.background=''; };
  });
}
function fdocAbrirListaCondutor(limpar){
  var busca=document.getElementById('fdoc-condutor-busca');
  if(limpar){
    var hidNome=document.getElementById('fdoc-condutor');
    var hidId=document.getElementById('fdoc-colab-id');
    if(hidNome) hidNome.value='';
    if(hidId) hidId.value='';
    if(busca) busca.value='';
  }
  if(busca) busca.focus();
  fdocRenderCondutorLista(busca?busca.value:'', true);
}
function fdocResolverCondutorDigitado(){
  var hidId=document.getElementById('fdoc-colab-id');
  if(hidId && hidId.value) return;
  var q=((document.getElementById('fdoc-condutor-busca')||{}).value||'').trim();
  if(!q) return;
  var hits=fdocFiltrarColabs(q);
  if(hits.length===1) fdocSelecionarCondutor(hits[0], 'manual');
}
function fdocBindCondutorBusca(d){
  var inp=document.getElementById('fdoc-condutor-busca');
  var lista=document.getElementById('fdoc-condutor-lista');
  if(!inp||!lista) return;
  if(d && d.colaborador_id){
    var col=(colaboradores||[]).find(function(c){return String(c.id)===String(d.colaborador_id);});
    if(col){
      inp.value=(col.nome||'')+(col.re?' · RE '+col.re:'');
      var hidNome=document.getElementById('fdoc-condutor');
      var hidId=document.getElementById('fdoc-colab-id');
      if(hidNome) hidNome.value=col.nome||d.condutor_responsavel||'';
      if(hidId) hidId.value=col.id;
    }
  }
  inp.addEventListener('input', function(){
    var hidNome=document.getElementById('fdoc-condutor');
    var hidId=document.getElementById('fdoc-colab-id');
    if(hidNome) hidNome.value='';
    if(hidId) hidId.value='';
    fdocRenderCondutorLista(inp.value, true);
  });
  inp.addEventListener('focus', function(){ fdocRenderCondutorLista(inp.value, true); });
  inp.addEventListener('blur', function(){ setTimeout(function(){ lista.style.display='none'; }, 180); });
  inp.addEventListener('keydown', function(e){
    if(e.key==='Enter'){
      e.preventDefault();
      var first=lista.querySelector('[data-cid]');
      if(first){
        var col=(colaboradores||[]).find(function(x){return String(x.id)===first.getAttribute('data-cid');});
        if(col) fdocSelecionarCondutor(col, 'manual');
      }
    }
  });
}

function fdocAtualizarCondutorAuto(){
  var placa=(document.getElementById('fdoc-placa')||{}).value||'';
  var data=(document.getElementById('fdoc-data-inf')||{}).value||'';
  var hora=(document.getElementById('fdoc-hora-inf')||{}).value||'';
  var info=document.getElementById('fdoc-condutor-info');
  if(!info) return;
  if(!placa||!data){
    info.innerHTML='<span style="color:#888">Informe placa e data da infração — o sistema busca o motorista do veículo naquele dia.</span>';
    return;
  }
  info.innerHTML='<span style="color:#888">⏳ Buscando motorista na escala/portaria do dia...</span>';
  frtMotoristaEscalaBuscar(placa, data, function(hit){
    if(hit&&(hit.colaborador_id||hit.nome)){
      var col=hit.colaborador_id?(colaboradores||[]).find(function(c){return String(c.id)===String(hit.colaborador_id);}):null;
      if(!col && hit.nome){
        var nomeN=fdocNormBuscaColab(hit.nome);
        col=(colaboradores||[]).find(function(c){ return fdocNormBuscaColab(c.nome)===nomeN; });
      }
      if(col){
        fdocSelecionarCondutor(col, 'escala');
        var extra=(hit.equipe?' · Equipe '+escHtml(hit.equipe):'')+' · fonte: '+escHtml(hit.fonte||'escala');
        info.innerHTML='<span style="color:#3B6D11;font-weight:600">✅ '+escHtml(col.nome)+'</span>'
          +'<div style="font-size:10px;color:#666;margin-top:2px">'+(col.re?'RE '+escHtml(String(col.re)):'')+extra+'</div>';
        return;
      }
      var hidNome=document.getElementById('fdoc-condutor');
      var hidId=document.getElementById('fdoc-colab-id');
      var busca=document.getElementById('fdoc-condutor-busca');
      if(hidNome) hidNome.value=hit.nome||'';
      if(hidId) hidId.value=hit.colaborador_id||'';
      if(busca) busca.value=hit.nome||'';
      info.innerHTML='<span style="color:#854F0B;font-weight:600">⚠ Motorista na escala: '+escHtml(hit.nome||'—')+'</span>'
        +'<div style="font-size:10px;color:#666;margin-top:2px">Não achei esse nome no cadastro. Busque o colaborador por nome ou RE.</div>';
      fdocAbrirListaCondutor(false);
    } else {
      info.innerHTML='<span style="color:#854F0B">⚠ Nenhum motorista encontrado para '+escHtml(placa)+' em '+fmtD(data)+(hora?' '+escHtml(hora):'')+'.</span>'
        +'<div style="font-size:10px;color:#666;margin-top:2px">Digite o nome ou o RE do colaborador para inserir.</div>';
      fdocAbrirListaCondutor(true);
    }
  }, hora);
}

function fdocPagarDoc(id){
  var d=(frt_documentos||[]).find(function(x){return x.id===id;});
  if(!d)return;
  var vlPag=(d.desconto_disponivel && d.valor_desconto!=null)?d.valor_desconto:d.valor;
  var conf=confirm('Confirmar pagamento de '+escHtml(d.tipo)+' do veículo '+escHtml(d.placa||'')+'?'+(vlPag?' Valor: R$'+Number(vlPag).toLocaleString('pt-BR',{minimumFractionDigits:2}):''));
  if(!conf)return;
  d.status='Pago';d.pago=true;d.data_pagamento=dataHojeLocal();
  if(!DEMO)sbUpdate('frotas_documentos',{status:'Pago',pago:true,data_pagamento:d.data_pagamento},'id=eq.'+id);
  if(d.tipo==='Multa') fdocRenderMultas(); else frtDocRender();
  progShowToast('✅ Pagamento registrado — '+d.tipo+' '+d.placa);
}

function fdocExcluirMulta(id){
  var d=(frt_documentos||[]).find(function(x){return String(x.id)===String(id);});
  if(!d){ progShowToast('Multa não encontrada.','erro'); return; }
  var nomeUser=(typeof usuarioLogado!=='undefined'&&usuarioLogado)?(usuarioLogado.nome||''):'';
  setModal('<div class="modal-bg"><div class="modal" style="max-width:420px">'
    +'<h3 style="margin-bottom:.5rem;color:#A32D2D">🗑 Excluir multa</h3>'
    +'<div style="background:#FFF0F0;border:.5px solid #F7C1C1;border-radius:8px;padding:10px 14px;margin-bottom:.75rem;font-size:12px">'
    +'<div>A multa <b>'+escHtml(d.numero_auto||d.numero_documento||d.placa||'')+'</b> sai da lista operacional. O registro fica no histórico (soft-delete) com a justificativa.</div>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Justificativa obrigatória *</label>'
    +'<textarea class="inp" id="fdoc-excl-just" placeholder="Motivo da exclusão..." rows="3" style="width:100%;resize:vertical"></textarea>'
    +'</div>'
    +'<div class="fg" style="margin-bottom:.75rem">'
    +'<label style="font-size:11px;font-weight:600">Seu nome *</label>'
    +'<input class="inp" id="fdoc-excl-nome" value="'+escHtml(nomeUser)+'" style="width:100%"/>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" id="fdoc-excl-voltar">Voltar</button>'
    +'<button class="btn btn-pri" id="fdoc-excl-confirmar" style="flex:2;background:#A32D2D;border-color:#A32D2D">🗑 Confirmar exclusão</button>'
    +'</div></div></div>');

  setTimeout(function(){
    var voltar=document.getElementById('fdoc-excl-voltar');
    if(voltar) voltar.onclick=function(){ fdocAbrirModal(d, true); };
    var btn=document.getElementById('fdoc-excl-confirmar');
    if(!btn) return;
    btn.onclick=function(){
      var just=((document.getElementById('fdoc-excl-just')||{}).value||'').trim();
      var nome=((document.getElementById('fdoc-excl-nome')||{}).value||'').trim();
      if(!just){ progShowToast('⚠ Informe a justificativa.','erro'); return; }
      if(!nome){ progShowToast('⚠ Informe seu nome.','erro'); return; }
      btn.disabled=true; btn.textContent='Excluindo...';
      var now=new Date().toISOString();
      d.deleted_at=now;
      d.exclusao_justificativa=just;
      d.excluido_por=nome;
      d.status='Cancelado';
      var after=function(){
        frt_documentos=(frt_documentos||[]).filter(function(x){return String(x.id)!==String(id);});
        closeModal();
        fdocRenderMultas();
        if(typeof avColInvalidarCacheFrota==='function') avColInvalidarCacheFrota();
        progShowToast('✅ Multa excluída.');
      };
      if(DEMO){ after(); return; }
      var extra={
        exclusao_justificativa:just,
        excluido_por:nome,
        status:'Cancelado'
      };
      var gravarJust=function(p){
        return Promise.resolve(sbUpdate('frotas_documentos', p, 'id=eq.'+id, {silent:true}));
      };
      gravarJust(extra).then(function(ok){
        if(!ok) return gravarJust({status:'Cancelado'});
        return ok;
      }).then(function(){
        return Promise.resolve(sbDelete('frotas_documentos','id=eq.'+id));
      }).then(function(){
        after();
      }).catch(function(e){
        btn.disabled=false; btn.textContent='🗑 Confirmar exclusão';
        progShowToast('⚠ Erro ao excluir: '+(e&&e.message||e),'erro');
      });
    };
  },50);
}

function fdocRelatorioMultas(){
  var multas=(frt_documentos||[]).filter(function(d){return d.tipo==='Multa' && fdocDocAtivo(d);});
  var linhas=['Placa;Nº Auto;Órgão;Data Infração;Município;Local;Código;Tipo Infração;Gravidade;Condutor;Pontos;Valor;Valor C/ Desconto;Vencimento;Status;Recurso'];
  multas.forEach(function(d){
    linhas.push([d.placa,d.numero_auto||d.numero_documento||'',d.orgao_emissor||'',d.data_infracao||d.data_emissao||'',
      (d.municipio_infracao||'').replace(/;/g,','),(d.local_infracao||'').replace(/;/g,','),
      d.codigo_infracao||'',d.tipo_infracao||'',d.gravidade||'',
      d.condutor_responsavel||'',d.pontos_cnh||0,d.valor||0,d.valor_desconto||'',
      d.data_vencimento||'',d.status,d.status_recurso||''].join(';'));
  });
  var csv=linhas.join('\n');
  var blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a');a.href=url;a.download='relatorio_multas_'+dataHojeLocal()+'.csv';
  document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
  progShowToast('✅ Relatório de multas exportado.');
}

var _fdocMulImport=null;
function fdocImportarMultas(){
  setModal('<div class="modal-bg"><div class="modal" style="max-width:780px;max-height:90vh;overflow-y:auto">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">'
    +'<h3 style="margin:0">📥 Importar multas (Excel)</h3>'
    +'<button class="btn" onclick="closeModal()" style="padding:3px 9px">✕</button></div>'
    +'<div style="font-size:12px;color:#666;margin-bottom:.6rem;line-height:1.5">Planilha <b>.xlsx / .xls / .csv</b>. Coluna obrigatória: <b>Placa</b>. Se a multa já existir (<b>placa + nº auto</b>), a planilha <b>atualiza o valor</b> e os demais campos — não duplica e não dá erro. Com <b>Data Infração</b> (e Hora), busca o motorista na escala/portaria. Reconhecidas também: Nº Auto, Órgão, Hora, Município, Local, Código, Tipo de Infração, Gravidade, Pontos, Valor, Valor C/ Desconto, Desconto, Vencimento, Status, Recurso, Condutor, RE, Observação.</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:.6rem">'
    +'<button class="btn" onclick="fdocMultaBaixarModelo()">⬇ Baixar modelo</button>'
    +'</div>'
    +'<input type="file" id="fdoc-mul-imp-file" accept=".xlsx,.xls,.csv" class="inp" style="width:100%;margin-bottom:.6rem"/>'
    +'<div id="fdoc-mul-imp-preview" style="font-size:12px"></div>'
    +'<div style="display:flex;gap:8px;margin-top:.75rem">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" id="fdoc-mul-imp-btn" style="flex:2;display:none">Confirmar importação</button>'
    +'</div></div></div>');
  setTimeout(function(){
    var f=document.getElementById('fdoc-mul-imp-file');
    if(f) f.onchange=function(e){ fdocMultaLerArquivo(e.target.files[0]); };
    var btn=document.getElementById('fdoc-mul-imp-btn');
    if(btn) btn.onclick=function(){ fdocMultaImportConfirm(); };
  },50);
}
function fdocMultaBaixarModelo(){
  var headers=['Placa','Nº Auto','Órgão','Data Infração','Hora','Município','Local','Código','Tipo de Infração','Gravidade','Pontos','Valor','Valor C/ Desconto','Desconto','Vencimento','Status','Recurso','Condutor','RE','Observação'];
  var exemplo=['ABC1D23','E-123456','DETRAN-SP','21/09/2026','14:30','São Paulo/SP','Av. Paulista, 1000','745-50','Velocidade','Média','4','195.23','156.18','Sim','30/09/2026','Pendente','','JOÃO SILVA','1078','Pagamento antecipado'];
  if(typeof XLSX==='undefined'){
    var csv=[headers.join(';'),exemplo.join(';')].join('\n');
    var blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});
    var url=URL.createObjectURL(blob);
    var a=document.createElement('a'); a.href=url; a.download='modelo_importacao_multas.csv';
    document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
    return;
  }
  var ws=XLSX.utils.aoa_to_sheet([headers,exemplo]);
  var wb=XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Multas');
  XLSX.writeFile(wb, 'modelo_importacao_multas.xlsx');
}
function fdocMultaLerArquivo(file){
  if(!file) return;
  var prev=document.getElementById('fdoc-mul-imp-preview');
  if(prev) prev.innerHTML='<div style="color:#888;padding:.5rem">Processando...</div>';
  var reader=new FileReader();
  reader.onload=function(e){
    try{
      if(typeof XLSX==='undefined'){ if(prev)prev.innerHTML='<div style="color:#A32D2D">Biblioteca de Excel não carregada.</div>'; return; }
      var wb=XLSX.read(e.target.result,{type:'array',cellDates:true});
      var ws=wb.Sheets[wb.SheetNames[0]];
      var rows=XLSX.utils.sheet_to_json(ws,{defval:''});
      fdocMultaImportPreview(rows);
    }catch(err){ if(prev)prev.innerHTML='<div style="color:#A32D2D">Erro ao ler: '+escHtml(String(err&&err.message||err))+'</div>'; }
  };
  reader.readAsArrayBuffer(file);
}
function fdocMultaPnum(v){
  if(v==null||v==='') return null;
  var s=String(v).replace(/[^0-9,.-]/g,'').replace(/\.(?=\d{3}(\D|$))/g,'').replace(',','.');
  var n=parseFloat(s);
  return isNaN(n)?null:n;
}
function fdocMultaPdata(v){
  if(v instanceof Date && !isNaN(v.getTime())) return v.getFullYear()+'-'+String(v.getMonth()+1).padStart(2,'0')+'-'+String(v.getDate()).padStart(2,'0');
  var s=String(v||'').trim().split(/[ T]/)[0];
  var m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if(m){ var y=m[3].length===2?'20'+m[3]:m[3]; return y+'-'+String(m[2]).padStart(2,'0')+'-'+String(m[1]).padStart(2,'0'); }
  m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m?m[0]:'';
}
function fdocMultaPhora(v){
  if(v instanceof Date && !isNaN(v.getTime())) return String(v.getHours()).padStart(2,'0')+':'+String(v.getMinutes()).padStart(2,'0');
  var s=String(v||'').trim();
  var m=s.match(/^(\d{1,2}):(\d{2})/);
  return m?String(m[1]).padStart(2,'0')+':'+m[2]:'';
}
function fdocMultaMatchPlaca(pl){
  var n=typeof frtNormPlaca==='function'?frtNormPlaca(pl):String(pl||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  if(!n) return null;
  return (frt_veiculos||[]).find(function(v){
    var pv=typeof frtNormPlaca==='function'?frtNormPlaca(v.placa):String(v.placa||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
    return pv===n;
  })||null;
}
function fdocMultaMatchColab(nome, re){
  var dig=String(re||'').replace(/\D/g,'');
  if(dig){
    var hit=(colaboradores||[]).find(function(c){
      if(c.ativo===false||c.dispensado) return false;
      var r=String(c.re||c.matricula||'').replace(/\D/g,'');
      if(!r) return false;
      var rN=r.replace(/^0+/,'')||'0';
      var dN=dig.replace(/^0+/,'')||'0';
      return r===dig || rN===dN;
    });
    if(hit) return hit;
  }
  var q=String(nome||'').trim();
  if(!q || typeof fdocFiltrarColabs!=='function') return null;
  var hits=fdocFiltrarColabs(q);
  return hits.length?hits[0]:null;
}
function fdocMultaImportPreview(rows){
  var prev=document.getElementById('fdoc-mul-imp-preview');
  var btn=document.getElementById('fdoc-mul-imp-btn');
  if(btn) btn.style.display='none';
  _fdocMulImport=null;
  if(!rows||!rows.length){ if(prev)prev.innerHTML='<div style="color:#A32D2D">Planilha vazia.</div>'; return; }
  var headers=Object.keys(rows[0]);
  function col(re){ for(var i=0;i<headers.length;i++){ if(re.test(String(headers[i]||''))) return headers[i]; } return null; }
  var cPlaca=col(/placa/i);
  if(!cPlaca){ if(prev)prev.innerHTML='<div style="color:#A32D2D">Não encontrei a coluna obrigatória <b>Placa</b>.</div>'; return; }
  var cAuto=col(/auto|ait|infrac[aã]o.*n|n[úu]mero/i);
  var cOrgao=col(/[óo]rg[aã]o|detran|emissor/i);
  var cData=col(/data.*infra|infra.*data|^data$/i)||col(/data/i);
  var cHora=col(/hora/i);
  var cMun=col(/munic[ií]pio|cidade/i);
  var cLocal=col(/local/i);
  var cCod=col(/c[oó]digo/i);
  var cTipo=col(/tipo/i);
  var cGrav=col(/gravidade/i);
  var cPts=col(/pontos/i);
  var cValor=null;
  headers.forEach(function(h){
    var s=String(h||'').toLowerCase();
    try{ s=s.normalize('NFD').replace(/[\u0300-\u036f]/g,''); }catch(eN){}
    if(/^valor$/.test(s) || /^valor\s*(r\$|da multa|infracao|multa)/.test(s) || /^vl\.?\s*(infrac|multa)?$/.test(s)){
      if(!cValor) cValor=h;
    }
  });
  if(!cValor){
    headers.forEach(function(h){
      var s=String(h||'').toLowerCase();
      if(/valor/.test(s) && !/desc/.test(s) && !cValor) cValor=h;
    });
  }
  var cVDesc=col(/desc/i);
  var cDescFlag=col(/^desconto$|desconto\?|antecip/i);
  var cVenc=col(/venc/i);
  var cEmi=col(/emiss/i);
  var cSt=col(/status$/i);
  var cRec=col(/recurso/i);
  var cCond=col(/condutor|motorista|nome/i);
  var cRe=col(/^re$|matricula|matr[ií]cula/i);
  var cObs=col(/obs|observa/i);
  var ja={};
  (frt_documentos||[]).forEach(function(d){
    if(String(d.tipo||'')!=='Multa' || d.deleted_at) return;
    var auto=String(d.numero_auto||d.numero||'').trim();
    if(!auto) return;
    var k=(typeof frtNormPlaca==='function'?frtNormPlaca(d.placa):String(d.placa||'').toUpperCase())+'|'+auto;
    ja[k]=d;
  });
  var recs=[], semPlaca=0, dups=0, semCad=[];
  rows.forEach(function(r, idx){
    var placaRaw=String(r[cPlaca]||'').trim();
    if(!placaRaw){ semPlaca++; return; }
    var veic=fdocMulMatchPlacaSafe(placaRaw);
    var placa=veic?(veic.placa||placaRaw):placaRaw;
    var auto=cAuto?String(r[cAuto]||'').trim():'';
    var key=(typeof frtNormPlaca==='function'?frtNormPlaca(placa):placa.toUpperCase())+'|'+auto;
    var exist=null;
    if(auto && ja[key]){
      if(ja[key]._seenSheet){ dups++; return; }
      exist=ja[key].id?ja[key]:null;
    }
    var grav=cGrav?String(r[cGrav]||'').trim():'';
    if(grav){
      var gl=grav.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
      if(gl.indexOf('graviss')>=0) grav='Gravíssima';
      else if(gl.indexOf('grave')>=0) grav='Grave';
      else if(gl.indexOf('media')>=0||gl.indexOf('média')>=0) grav='Média';
      else if(gl.indexOf('leve')>=0) grav='Leve';
    }
    var pts=cPts?parseInt(r[cPts],10):NaN;
    if(isNaN(pts)) pts=(FDOC_GRAVIDADE_PONTOS[grav]!=null)?FDOC_GRAVIDADE_PONTOS[grav]:0;
    var valor=cValor?fdocMultaPnum(r[cValor]):null;
    var vDesc=cVDesc?fdocMultaPnum(r[cVDesc]):null;
    var descTxt=cDescFlag?String(r[cDescFlag]||'').trim().toLowerCase():'';
    var temDesc=!!vDesc || /^(s|sim|yes|true|1|x)$/i.test(descTxt);
    var st=cSt?String(r[cSt]||'').trim():'';
    if(FDOC_STATUS.indexOf(st)<0) st='Pendente';
    var condNome=cCond?String(r[cCond]||'').trim():'';
    var condRe=cRe?String(r[cRe]||'').trim():'';
    var col=fdocMultaMatchColab(condNome, condRe);
    if(!veic) semCad.push(placaRaw);
    recs.push({
      _linha:idx+2,
      _placaCad:!!veic,
      placa:placa,
      tipo:'Multa',
      numero_documento:auto,
      numero:auto,
      numero_auto:auto,
      orgao_emissor:cOrgao?String(r[cOrgao]||'').trim():'',
      data_infracao:cData?fdocMultaPdata(r[cData]):'',
      data_emissao:cEmi?fdocMultaPdata(r[cEmi]):(cData?fdocMultaPdata(r[cData]):''),
      emissao:cEmi?fdocMultaPdata(r[cEmi]):(cData?fdocMultaPdata(r[cData]):''),
      hora_infracao:cHora?fdocMultaPhora(r[cHora]):'',
      municipio_infracao:cMun?String(r[cMun]||'').trim():'',
      local_infracao:cLocal?String(r[cLocal]||'').trim():'',
      codigo_infracao:cCod?String(r[cCod]||'').trim():'',
      tipo_infracao:cTipo?String(r[cTipo]||'').trim():'',
      gravidade:grav,
      pontos_cnh:pts||0,
      valor:valor,
      valor_desconto:temDesc?vDesc:null,
      desconto_disponivel:temDesc,
      data_vencimento:cVenc?fdocMultaPdata(r[cVenc]):'',
      validade:cVenc?fdocMultaPdata(r[cVenc]):'',
      status:st,
      status_recurso:cRec?String(r[cRec]||'').trim():'',
      condutor_responsavel:col?(col.nome||condNome):condNome,
      colaborador_id:col?col.id:null,
      observacao:cObs?String(r[cObs]||'').trim():'',
      _existId:exist&&exist.id?exist.id:null,
      _acao:exist&&exist.id?'atualizar':'nova'
    });
    if(auto) ja[key]={_seenSheet:true, id:exist&&exist.id?exist.id:null};
  });
  _fdocMulImport=recs;
  var nAtu=recs.filter(function(d){return d._acao==='atualizar';}).length;
  var nNov=recs.length-nAtu;
  fdocMultaImportMostrarPreview(recs, {dups:dups, semPlaca:semPlaca, semCad:semCad, atualizar:nAtu, novas:nNov, buscando:!!recs.length});
  if(!recs.length) return;
  fdocMultaVincularRecs(recs).then(function(st){
    fdocMultaImportMostrarPreview(recs, {dups:dups, semPlaca:semPlaca, semCad:semCad, atualizar:nAtu, novas:nNov, vinculo:st});
  }).catch(function(){
    fdocMultaImportMostrarPreview(recs, {dups:dups, semPlaca:semPlaca, semCad:semCad, atualizar:nAtu, novas:nNov});
  });
}
function fdocMulMatchPlacaSafe(pl){
  try{ return fdocMultaMatchPlaca(pl); }catch(e){ return null; }
}

function fdocMultaAplicarHit(rec, hit){
  if(!rec || !hit) return false;
  var col=null;
  if(hit.colaborador_id){
    col=(colaboradores||[]).find(function(c){return String(c.id)===String(hit.colaborador_id);});
  }
  if(!col && hit.nome){
    var nomeN=typeof fdocNormBuscaColab==='function'?fdocNormBuscaColab(hit.nome):String(hit.nome||'').toLowerCase().trim();
    col=(colaboradores||[]).find(function(c){
      var n=typeof fdocNormBuscaColab==='function'?fdocNormBuscaColab(c.nome):String(c.nome||'').toLowerCase().trim();
      return n && n===nomeN;
    });
  }
  if(col){
    rec.colaborador_id=col.id;
    rec.condutor_responsavel=col.nome||hit.nome||rec.condutor_responsavel||'';
    rec._condFonte=hit.fonte||'escala';
    return true;
  }
  if(hit.nome){
    rec.condutor_responsavel=hit.nome;
    rec.colaborador_id=hit.colaborador_id||rec.colaborador_id||null;
    rec._condFonte=hit.fonte||'escala';
    return !!rec.colaborador_id;
  }
  return false;
}
function fdocMultaCarregarEscalaDatas(datas){
  var uniq=[], seen={};
  (datas||[]).forEach(function(d){
    var ds=typeof _compDataStr==='function'?_compDataStr(d):String(d||'').slice(0,10);
    if(ds && !seen[ds]){ seen[ds]=true; uniq.push(ds); }
  });
  if(!uniq.length || (typeof DEMO!=='undefined' && DEMO) || typeof sbFetch!=='function') return Promise.resolve();
  function chunk(arr,n){ var o=[]; for(var i=0;i<arr.length;i+=n) o.push(arr.slice(i,i+n)); return o; }
  var jobs=[];
  chunk(uniq, 40).forEach(function(part){
    var inn=part.join(',');
    jobs.push(sbFetch('composicao_dia',{filters:['data=in.('+inn+')'],limit:3000}).then(function(rows){
      (rows||[]).forEach(function(c){
        c.colaborador_ids=typeof parseJsonField==='function'?parseJsonField(c.colaborador_ids,[]):c.colaborador_ids;
        if(typeof _mergeComposicaoDia==='function') _mergeComposicaoDia(c);
      });
    }).catch(function(){}));
    jobs.push(sbFetch('prog_veiculos_dia',{filters:['data=in.('+inn+')'],limit:3000}).then(function(rows){
      (rows||[]).forEach(function(r){
        var dataStr=typeof _compDataStr==='function'?_compDataStr(r.data):String(r.data||'').slice(0,10);
        if(r.equipe_id&&r.placa){
          if(typeof _progVeiculos==='undefined' || !_progVeiculos) window._progVeiculos={};
          var slotKey=r.equipe_id+'_'+dataStr+(r.slot===2||r.slot==='2'?'_b':'');
          _progVeiculos[slotKey]={id:r.veiculo_id,placa:r.placa,modelo:r.modelo||''};
          if(!r.slot||r.slot===1) _progVeiculos[r.equipe_id+'_'+dataStr]={id:r.veiculo_id,placa:r.placa,modelo:r.modelo||''};
        }
      });
    }).catch(function(){}));
  });
  uniq.sort();
  var min=uniq[0], max=uniq[uniq.length-1];
  var selPort=(typeof PORT_SAIDA_SEL_LISTA==='string'&&PORT_SAIDA_SEL_LISTA)?PORT_SAIDA_SEL_LISTA:undefined;
  jobs.push(sbFetch('frotas_portaria_saidas',{
    filters:['data_saida=gte.'+min,'data_saida=lte.'+max+'T23:59:59'],
    select:selPort, limit:4000
  }).then(function(rows){
    if(rows&&rows.length && typeof portMesclarSaidas==='function') portMesclarSaidas(rows);
  }).catch(function(){}));
  return Promise.all(jobs);
}
function fdocMultaVincularRecs(recs, opts){
  opts=opts||{};
  var need=(recs||[]).filter(function(d){
    if(!d || !d.placa || !(d.data_infracao||d.data_emissao)) return false;
    if(opts.soSemCondutor && d.colaborador_id) return false;
    return true;
  });
  if(!need.length) return Promise.resolve({ok:0, miss:0, skip:(recs||[]).length});
  var datas=need.map(function(d){ return d.data_infracao||d.data_emissao; });
  return fdocMultaCarregarEscalaDatas(datas).then(function(){
    var ok=0, miss=0;
    need.forEach(function(d){
      var hit=typeof frtMotoristaEscalaLocal==='function'
        ? frtMotoristaEscalaLocal(d.placa, d.data_infracao||d.data_emissao, d.hora_infracao)
        : null;
      if(fdocMultaAplicarHit(d, hit)) ok++; else miss++;
    });
    return {ok:ok, miss:miss, skip:(recs||[]).length-need.length};
  });
}
function fdocMultaImportMostrarPreview(recs, meta){
  var prev=document.getElementById('fdoc-mul-imp-preview');
  var btn=document.getElementById('fdoc-mul-imp-btn');
  meta=meta||{};
  if(btn) btn.style.display=(recs&&recs.length)?'':'none';
  var h='<div style="background:#f7f9fb;border:.5px solid #e3e8ee;border-radius:8px;padding:.6rem .75rem;margin-bottom:.5rem;display:flex;gap:14px;flex-wrap:wrap">'
    +'<span>🟢 A importar: <b>'+(recs?recs.length:0)+'</b></span>'
    +(meta.dups?'<span style="color:#854F0B">Duplicadas (puladas): <b>'+meta.dups+'</b></span>':'')
    +(meta.semPlaca?'<span style="color:#854F0B">Sem placa: <b>'+meta.semPlaca+'</b></span>':'')
    +(meta.semCad&&meta.semCad.length?'<span style="color:#A32D2D">Placa fora do cadastro: <b>'+meta.semCad.length+'</b></span>':'')
    +(meta.novas?'<span>Novas: <b>'+meta.novas+'</b></span>':'')
    +(meta.atualizar?'<span style="color:#185FA5">Atualizar valor: <b>'+meta.atualizar+'</b></span>':'')
    +(meta.buscando?'<span style="color:#185FA5">⏳ Buscando motorista na escala/portaria…</span>':'')
    +(meta.vinculo?'<span style="color:#3B6D11">🚗 Vinculados pela escala: <b>'+meta.vinculo.ok+'</b></span>'
      +(meta.vinculo.miss?'<span style="color:#854F0B">Sem motorista: <b>'+meta.vinculo.miss+'</b></span>':''):'')
    +'</div>';
  if(!recs||!recs.length){ if(prev) prev.innerHTML=h+'<div style="color:#A32D2D">Nenhuma linha válida para importar.</div>'; return; }
  h+='<div style="overflow-x:auto;max-height:240px"><table class="tbl" style="font-size:11px"><thead><tr>'
    +'<th>Placa</th><th>Auto</th><th>Data</th><th>Condutor</th><th>Valor</th><th>Status</th></tr></thead><tbody>'
    +recs.slice(0,12).map(function(d){
      var cond=d.condutor_responsavel||'—';
      var fonte=d._condFonte?(d._condFonte.indexOf('portaria')>=0?'portaria':'escala'):(d.colaborador_id?'planilha':'');
      return '<tr>'
        +'<td style="font-family:monospace;font-weight:700">'+(d._placaCad?'':'⚠ ')+escHtml(d.placa)+(d._acao==='atualizar'?'<div style="font-size:10px;color:#185FA5;font-weight:600">atualizar</div>':'')+'</td>'
        +'<td>'+escHtml(d.numero_auto||'—')+'</td>'
        +'<td>'+(d.data_infracao?fmtD(d.data_infracao):'—')+'</td>'
        +'<td>'+(d.colaborador_id||d.condutor_responsavel?escHtml(cond):'<span style="color:#854F0B">—</span>')
        +(fonte?'<div style="font-size:10px;color:#888">'+escHtml(fonte)+'</div>':'')+'</td>'
        +'<td>'+(d.valor!=null?('R$'+Number(d.valor).toLocaleString('pt-BR',{minimumFractionDigits:2})):'—')+'</td>'
        +'<td>'+escHtml(d.status)+'</td></tr>';
    }).join('')
    +(recs.length>12?'<tr><td colspan="6" style="color:#888">… +'+(recs.length-12)+' linha(s)</td></tr>':'')
    +'</tbody></table></div>';
  if(prev) prev.innerHTML=h;
}
async function fdocMultaVincularMotoristas(){
  var rows=(frt_documentos||[]).filter(function(d){return d.tipo==='Multa' && fdocDocAtivo(d);});
  var placa=((document.getElementById('mul-fil-placa')||{}).value||'').toUpperCase();
  var status=(document.getElementById('mul-fil-status')||{}).value||'';
  var mes=(document.getElementById('mul-fil-mes')||{}).value||'';
  var motQ=(document.getElementById('mul-fil-motorista')||{}).value||'';
  var cid=(document.getElementById('mul-fil-cont')||{}).value||'';
  var filtradas=rows.filter(function(d){
    if(placa && typeof frtPlacaMatchBusca==='function' && !frtPlacaMatchBusca(d.placa, placa)) return false;
    if(status&&d.status!==status) return false;
    if(mes&&!(d.data_infracao||d.data_emissao||'').startsWith(mes)) return false;
    if(!frtFiltroMotorista(motQ, [d.condutor_responsavel], d.colaborador_id)) return false;
    if(!frtFiltroContratoVeiculo(d.placa, d.veiculo_id, cid)) return false;
    return true;
  });
  var alvo=filtradas.filter(function(d){ return !d.colaborador_id && d.placa && (d.data_infracao||d.data_emissao); });
  if(!alvo.length){
    if(typeof progShowToast==='function') progShowToast('Nenhuma multa da lista está sem condutor para vincular.');
    return;
  }
  if(!confirm('Vincular motorista pela escala/portaria em '+alvo.length+' multa(s) sem condutor?\n\nUsa placa + data + hora da infração. Multas que já têm colaborador não são alteradas.')) return;
  if(typeof progShowToast==='function') progShowToast('⏳ Buscando motoristas na escala/portaria…');
  var st=await fdocMultaVincularRecs(alvo, {soSemCondutor:true});
  var gravados=0, falhas=0;
  for(var i=0;i<alvo.length;i++){
    var d=alvo[i];
    if(!d.colaborador_id && !d.condutor_responsavel) continue;
    if(typeof DEMO!=='undefined' && DEMO){ gravados++; continue; }
    if(typeof isUUID==='function' && !isUUID(d.id)){ gravados++; continue; }
    var payload={condutor_responsavel:d.condutor_responsavel||null};
    if(d.colaborador_id) payload.colaborador_id=d.colaborador_id;
    try{
      var ok=await sbUpdate('frotas_documentos', payload, 'id=eq.'+d.id, {silent:true});
      if(ok) gravados++; else falhas++;
    }catch(e){ falhas++; }
  }
  if(typeof avColInvalidarCacheFrota==='function') avColInvalidarCacheFrota();
  fdocRenderMultas();
  var msg='🚗 Motorista: '+st.ok+' vinculado(s)';
  if(st.miss) msg+=' · '+st.miss+' sem escala/portaria';
  if(falhas) msg+=' · '+falhas+' falha(s) ao gravar';
  if(typeof progShowToast==='function') progShowToast(msg, (st.ok||gravados)?undefined:'erro');
}
async function fdocMultaImportConfirm(){
  var recs=_fdocMulImport||[];
  if(!recs.length){ progShowToast('Nada para importar.','erro'); return; }
  var btn=document.getElementById('fdoc-mul-imp-btn');
  var prev=document.getElementById('fdoc-mul-imp-preview');
  if(btn){ btn.disabled=true; btn.textContent='Vinculando motoristas...'; }
  window._frotasDocsTemValor=undefined;
  window._frotasDocsTemMultaExtra=undefined;
  try{
    var stVin=await fdocMultaVincularRecs(recs);
    if(stVin && (stVin.ok||stVin.miss) && prev){
      fdocMultaImportMostrarPreview(recs, {vinculo:stVin});
    }
  }catch(e){}
  if(btn){ btn.textContent='Importando...'; }
  if(!frt_documentos) frt_documentos=[];
  var ok=0, fail=0;
  for(var i=0;i<recs.length;i++){
    var dados=Object.assign({}, recs[i]);
    var existId=dados._existId||null;
    var acao=dados._acao||'nova';
    delete dados._linha; delete dados._placaCad; delete dados._condFonte; delete dados._existId; delete dados._acao;
    if(DEMO){
      if(existId){
        var di=(frt_documentos||[]).findIndex(function(x){return String(x.id)===String(existId);});
        if(di>=0) frt_documentos[di]=fdocNormRow(Object.assign({},frt_documentos[di],dados,{id:existId}));
      } else {
        dados.id='mul'+Date.now()+'_'+i;
        frt_documentos.unshift(fdocNormRow(dados));
      }
      ok++;
      continue;
    }
    var payload=fdocPayloadDb(dados);
    var res;
    if(existId){
      res=await fdocUpdateComFallback(existId, payload);
      if(res===true || fdocSaveOk(res)){
        var idxU=(frt_documentos||[]).findIndex(function(x){return String(x.id)===String(existId);});
        if(idxU>=0) frt_documentos[idxU]=fdocNormRow(Object.assign({},frt_documentos[idxU],dados,{id:existId}));
        ok++;
      } else fail++;
    } else {
      res=await fdocInsertComFallback(payload);
      if(fdocSaveOk(res)){
        var saved=Array.isArray(res)?res[0]:res;
        if(saved&&saved.id) dados.id=saved.id;
        else dados.id='mul'+Date.now()+'_'+i;
        frt_documentos.unshift(fdocNormRow(dados));
        ok++;
      } else fail++;
    }
    if(btn) btn.textContent='Importando... '+(i+1)+'/'+recs.length;
  }
  if(typeof avColInvalidarCacheFrota==='function') avColInvalidarCacheFrota();
  closeModal();
  fdocRenderMultas();
  _fdocMulImport=null;
  var nMot=0, nSem=0;
  recs.forEach(function(d){ if(d.colaborador_id||d.condutor_responsavel) nMot++; else nSem++; });
  var nAtuOk=recs.filter(function(d){return d._acao==='atualizar';}).length;
  var extra=nMot?(' · '+nMot+' com motorista'):'';
  if(nSem) extra+=' · '+nSem+' sem motorista (use Vincular motorista)';
  var msgBase=nAtuOk?('✅ '+ok+' multa(s) processada(s) (inclui atualização de valor)'):('✅ '+ok+' multa(s) importada(s)');
  progShowToast(fail?('⚠ Processadas '+ok+' · falhas '+fail+extra):(msgBase+extra), fail?'erro':undefined);
}

function _diasAdiante(n){
  var d=new Date(Date.now()+n*86400000);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

