function frtIntegracoesRender(){
  var wrap=document.getElementById('frt-int-lista');if(!wrap)return;
  var statusCor={
    'não configurada':'#888','aguardando credenciais':'#854F0B',
    'ativa':'#3B6D11','erro':'#A32D2D'
  };
  wrap.innerHTML=FRT_INTEGRACOES.map(function(int){
    var cor=statusCor[int.status]||'#555';
    var logs=JSON.parse(localStorage.getItem('frt_int_log_'+int.id)||'[]');
    var ultima=localStorage.getItem('frt_int_ultima_'+int.id)||'Nunca';
    var qtd=localStorage.getItem('frt_int_qtd_'+int.id)||'0';
    return '<div class="card">'
      +'<div class="ch">'
      +'<span class="ct">'+int.icon+' '+int.nome+'</span>'
      +'<span style="font-size:11px;color:#888">'+int.tipo+'</span>'
      +'</div>'
      +'<div style="padding:.75rem 1rem">'
      +'<div style="font-size:12px;color:#888;margin-bottom:.75rem">'+int.desc+'</div>'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:.5rem">'
      +'<span style="width:8px;height:8px;background:'+cor+';border-radius:50%;flex-shrink:0"></span>'
      +'<span style="font-size:12px;font-weight:500;color:'+cor+'">'+int.status.charAt(0).toUpperCase()+int.status.slice(1)+'</span>'
      +'</div>'
      +'<div style="font-size:11px;color:#888;margin-bottom:.5rem">Última sync: '+ultima+'</div>'
      +'<div style="font-size:11px;color:#888;margin-bottom:.75rem">'+qtd+' registros importados</div>'
      +'<div style="display:flex;gap:6px">'
      +'<button class="btn btn-sm btn-pri" data-fn="'+int.fn+'" style="font-size:11px">🔄 Sincronizar</button>'
      +'<button class="btn btn-sm" data-cfg="'+int.id+'" style="font-size:11px">⚙ Configurar</button>'
      +'</div>'
      +(logs.length?'<div style="margin-top:.5rem;background:#f9f9f7;border-radius:6px;padding:.5rem;font-size:10px;color:#888;max-height:60px;overflow-y:auto">'+logs.slice(-3).join('<br>')+'</div>':'')
      +'</div></div>';
  }).join('');

  setTimeout(function(){
    FRT_INTEGRACOES.forEach(function(int){
      var bs=wrap.querySelector('[data-fn="'+int.fn+'"]');
      if(bs)bs.onclick=function(){frtSyncIntegracao(int);};
      var bc=wrap.querySelector('[data-cfg="'+int.id+'"]');
      if(bc)bc.onclick=function(){frtConfigurarIntegracao(int);};
    });
  },50);
}

function frtSyncIntegracao(int){
  var msg='Sincronizando '+int.nome+'...';
  alert(msg+'\n\nEsta integração aguarda configuração das credenciais e endpoints da API '+int.nome+'.\nFunção a implementar: '+int.fn+'()');
}

function frtConfigurarIntegracao(int){
  var html='<div class="modal-bg"><div class="modal" style="max-width:440px">'
    +'<h3>⚙ '+int.nome+' — Configuração</h3>'
    +'<div style="background:#FEF3E2;border-radius:8px;padding:.75rem;margin-bottom:1rem;font-size:12px;color:#854F0B">'
    +'⚠ Esta integração aguarda documentação oficial e credenciais da plataforma '+int.nome+'.'
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:.75rem;margin-bottom:1rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Endpoint API</label>'
    +'<input class="inp" id="frt-cfg-endpoint" style="width:100%" placeholder="https://api.'+int.id+'.com/v1/..." /></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Token / API Key</label>'
    +'<input class="inp" id="frt-cfg-token" type="password" style="width:100%" placeholder="••••••••••••" /></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Empresa / CNPJ</label>'
    +'<input class="inp" id="frt-cfg-empresa" style="width:100%" /></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button class="btn btn-pri" onclick="frtSalvarConfig(\''+int.id+'\')" style="flex:1">Salvar configuração</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    document.querySelectorAll('.mn-full-btn').forEach(function(btn){
      btn.onclick=function(){
        closeModal();
        var i=parseInt(this.getAttribute('data-mi'));
        if(itensMenu[i]) itensMenu[i].acao();
      };
    });
    // Bind do campo data de retorno
    var inpData=document.getElementById('retorno-data');
    if(inpData){
      var _orig=inpData.getAttribute('data-original')||'';
      inpData.addEventListener('change',function(){ progVerificarMudancaData(this,_orig); });
    }
  },50);
}

function frtSalvarConfig(intId){
  alert('Configuração salva (simulada). Aguardando credenciais reais da plataforma.');
  closeModal();
}

