      var _pisoKm=(typeof portKmUltimoRegistrado==='function'&&veic)?portKmUltimoRegistrado(veic.placa):(veic&&veic.km_atual)||0; if(veic&&_pisoKm>0&&km<_pisoKm){alert('KM saida nao pode ser menor que a ultima KM da placa ('+_pisoKm.toLocaleString('pt-BR')+').');return;}
      var contSel=document.getElementById('fps-cont');
