      var saida={id:'ps'+Date.now(),
        veiculo_id:veicSel.value,placa:veic?veic.placa:'',modelo:veic?veic.modelo:'',
        motorista:g('fps-motorista'),base_saida:g('fps-base'),
        data_saida:g('fps-dt')||new Date().toISOString(),
        previsao_retorno:g('fps-retorno')||null,km_saida:km,
        contrato_id:g('fps-cont'),contrato_nome:contNome,
        obs:g('fps-obs'),status:'Em campo'};
      frt_portaria.unshift(saida);
