    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Combustível</label>'
    +'<select class="inp" id="fcomb-tipo" style="width:100%">'+FRT_COMBUSTIVEIS.map(function(c){return '<option>'+c+'</option>';}).join('')+'</select></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Litros *</label>'
    +'<input class="inp" id="fcomb-litros" type="number" step="0.1" style="width:100%" oninput="frtCalcComb()"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">R$/litro</label>'
    +'<input class="inp" id="fcomb-rl" type="number" step="0.01" style="width:100%" value="6.00" oninput="frtCalcComb()"/></div>'
    +'<div style="grid-column:span 2"><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Valor total</label>'
    +'<input class="inp" id="fcomb-total" type="number" step="0.01" style="width:100%;background:#f9f9f7" readonly/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">KM no abastecimento</label>'
    +'<input class="inp" id="fcomb-km" type="number" style="width:100%" oninput="frtCalcComb()"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Média consumo (km/L)</label>'
    +'<input class="inp" id="fcomb-media" style="width:100%;background:#f9f9f7" readonly placeholder="—"/>'
    +'<div id="fcomb-media-hint" style="font-size:10px;color:#888;margin-top:2px"></div></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Posto</label>'
    +'<input class="inp" id="fcomb-posto" style="width:100%"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Motorista</label>'
    +'<input class="inp" id="fcomb-mot" style="width:100%"/></div>'
