function frtPlacaCompMatch(comp, placaNorm, veicId){
  if(!comp||!placaNorm) return false;
  if(comp.placa&&frtNormPlaca(comp.placa)===placaNorm) return true;
  if(comp.veiculo_placa&&frtNormPlaca(comp.veiculo_placa)===placaNorm) return true;
  if(veicId&&comp.veiculo_id&&String(comp.veiculo_id)===String(veicId)) return true;
  return false;
}

function frtMotoristaFromComp(comp){
  if(!comp||!comp.motorista_id) return null;
  var col=(colaboradores||[]).find(function(c){return String(c.id)===String(comp.motorista_id);});
  var eq=(equipes_disp||[]).concat(equipes||[]).find(function(e){return String(e.id)===String(comp.equipe_id);});
  return {
    colaborador_id:comp.motorista_id,
    nome:col?(col.nome||''):'(ID escalado)',
    re:col?(col.re||''):'',
    equipe:eq?(eq.codigo||eq.nome_equipe||eq.nome||''):'',
    fonte:'composicao_dia'
  };
}

function frtMotoristaFromPortaria(placa, dataStr, horaStr){
  var placaNorm=frtNormPlaca(placa);
  var candidatos=(frt_portaria||[]).filter(function(r){
    var ds=_compDataStr(r.data_saida||r.data);
    return ds===dataStr&&frtNormPlaca(r.placa)===placaNorm&&r.motorista;
  });
  if(!candidatos.length) return null;
  var p=candidatos[0];
  if(horaStr){
    var hhmm=String(horaStr).slice(0,5);
    var infMs=Date.parse(dataStr+'T'+hhmm+':00');
    if(!isNaN(infMs)){
      var melhor=null, melhorDiff=Infinity;
      candidatos.forEach(function(r){
        var sai=new Date(r.data_saida||r.data).getTime();
        if(isNaN(sai)) return;
        // Preferir saída imediatamente anterior à infração; senão a mais próxima
        var diff=infMs-sai;
        var score=diff>=0?diff:(Math.abs(diff)+86400000);
        if(score<melhorDiff){ melhorDiff=score; melhor=r; }
      });
      if(melhor) p=melhor;
    }
  }
  var colId=p.colaborador_id||p.motorista_id||null;
  if(!colId && p.motorista){
    var col=(colaboradores||[]).find(function(c){
      return String(c.nome||'').toLowerCase()===String(p.motorista).toLowerCase();
    });
    if(col) colId=col.id;
  }
  return {colaborador_id:colId,nome:p.motorista,re:'',equipe:p.equipe||'',fonte:horaStr?'portaria_hora':'portaria'};
}

function frtMotoristaEscalaLocal(placa, data, hora){
  var placaNorm=frtNormPlaca(placa);
  var dataStr=_compDataStr(data);
  if(!placaNorm||!dataStr) return null;
  var veic=(frt_veiculos||[]).find(function(v){return frtNormPlaca(v.placa)===placaNorm;});
  var veicId=veic?veic.id:null;
  var i, comp, m;

  // Com hora: portaria tem prioridade (saída mais próxima / imediatamente anterior)
  if(hora){
    var porPort=frtMotoristaFromPortaria(placa, dataStr, hora);
    if(porPort) return porPort;
  }

  var comps=(composicao_dia||[]).filter(function(c){
    return _compDataStr(c.data)===dataStr&&frtPlacaCompMatch(c, placaNorm, veicId);
  });
  for(i=0;i<comps.length;i++){
    m=frtMotoristaFromComp(comps[i]);
    if(m) return m;
  }

  var hit=null;
  Object.keys(_progVeiculos||{}).forEach(function(k){
    if(hit) return;
    var idx=k.lastIndexOf('_'+dataStr);
    if(idx<0) return;
    var pv=_progVeiculos[k];
    if(!pv||frtNormPlaca(pv.placa)!==placaNorm) return;
    var eqId=k.substring(0, idx);
    comp=(composicao_dia||[]).find(function(c){
      return String(c.equipe_id)===String(eqId)&&_compDataStr(c.data)===dataStr;
    });
    hit=frtMotoristaFromComp(comp);
  });
  if(hit) return hit;

  return frtMotoristaFromPortaria(placa, dataStr, hora);
}

function frtMotoristaEscalaBuscar(placa, data, cb, hora){
  var local=frtMotoristaEscalaLocal(placa, data, hora);
  if(local){ cb(local); return; }
  if(DEMO){ cb(null); return; }
  var dataStr=_compDataStr(data);
  Promise.all([
    sbFetch('composicao_dia',{filters:['data=eq.'+dataStr],limit:800}),
    sbFetch('prog_veiculos_dia',{filters:['data=eq.'+dataStr],limit:800}),
    sbFetch('frotas_portaria_saidas',{filters:['data_saida=gte.'+dataStr,'data_saida=lte.'+dataStr+'T23:59:59'],limit:500})
  ]).then(function(res){
    (res[0]||[]).forEach(function(c){
      c.colaborador_ids=typeof parseJsonField==='function'?parseJsonField(c.colaborador_ids,[]):c.colaborador_ids;
      if(typeof _mergeComposicaoDia==='function') _mergeComposicaoDia(c);
    });
    (res[1]||[]).forEach(function(r){
      if(r.equipe_id&&r.placa){
        var slotKey=r.equipe_id+'_'+dataStr+(r.slot===2||r.slot==='2'?'_b':'');
        _progVeiculos[slotKey]={id:r.veiculo_id,placa:r.placa,modelo:r.modelo||''};
        if(!r.slot||r.slot===1) _progVeiculos[r.equipe_id+'_'+dataStr]={id:r.veiculo_id,placa:r.placa,modelo:r.modelo||''};
      }
    });
    if(res[2]&&res[2].length && typeof portMesclarSaidas==='function') portMesclarSaidas(res[2]);
    cb(frtMotoristaEscalaLocal(placa, data, hora)||frtMotoristaFromPortaria(placa, dataStr, hora));
  }).catch(function(){ cb(null); });
}

function frtAtualizarMotEscalaModal(prefix){
  var veicSel=document.getElementById(prefix+'-veic');
  var dataInp=document.getElementById(prefix+'-data');
  var infoEl=document.getElementById(prefix+'-mot-info');
  var motInp=document.getElementById(prefix+'-mot');
  var colInp=document.getElementById(prefix+'-colab-id');
  if(!infoEl) return;
  var veic=veicSel?frt_veiculos.find(function(v){return v.id===veicSel.value;}):null;
  var data=(dataInp&&dataInp.value)?dataInp.value.split('T')[0]:'';
  if(!veic||!data){
    infoEl.innerHTML='<span style="color:#888">Informe veículo e data para buscar o motorista na escala.</span>';
    if(motInp) motInp.value='';
    if(colInp) colInp.value='';
    return;
  }
  infoEl.innerHTML='<span style="color:#888">⏳ Buscando motorista na escala...</span>';
  frtMotoristaEscalaBuscar(veic.placa, data, function(hit){
    if(hit){
      if(motInp) motInp.value=hit.nome||'';
      if(colInp) colInp.value=hit.colaborador_id||'';
      var det=(hit.re?'RE '+escHtml(hit.re)+' · ':'')+(hit.equipe?'Equipe '+escHtml(hit.equipe)+' · ':'')+'fonte: '+escHtml(hit.fonte||'escala');
      infoEl.innerHTML='<span style="color:#3B6D11;font-weight:600">✅ '+escHtml(hit.nome||'—')+'</span>'
        +'<div style="font-size:10px;color:#666;margin-top:2px">'+det+'</div>';
    } else {
      if(motInp) motInp.value='';
      if(colInp) colInp.value='';
      infoEl.innerHTML='<span style="color:#854F0B">⚠ Nenhum motorista encontrado na escala para '+escHtml(veic.placa)+' em '+fmtD(data)+'. Verifique a programação do dia.</span>';
    }
  });
}

