var FRT_AVAR_TIPOS=['Avaria leve','Avaria grave','Colisão','Roubo/Furto','Mau uso','Desgaste natural','Terceiro envolvido'];
var FRT_AVAR_STATUS=['Aberto','Em andamento','Concluído','Mau uso'];

function frtAbrirNovaAvaria(){ frtAbrirAvaria(null); }

function frtAvarMontarPayload(orig){
  var g=function(id){return (document.getElementById(id)||{}).value||'';};
  var vs=document.getElementById('favar-veic');
  var veicId=vs?vs.value:'';
  var veic=(frt_veiculos||[]).find(function(v){return String(v.id)===String(veicId);})||null;
  if(!veic && orig && String(orig.veiculo_id||'')===String(veicId)){
    veic={id:orig.veiculo_id,placa:orig.placa,modelo:orig.modelo};
  }
  if(!veic||!g('favar-desc').trim()){
    if(typeof progShowToast==='function') progShowToast('Veículo e descrição são obrigatórios.','erro');
    else alert('Veículo e descrição são obrigatórios.');
    return null;
  }
  var est=parseFloat(g('favar-custo')); if(isNaN(est)) est=0;
  var fin=parseFloat(g('favar-custo-final')); if(isNaN(fin)) fin=(orig&&orig.custo_final)||0;
  return {
    placa:veic.placa, modelo:veic.modelo||'', veiculo_id:veic.id||null,
    motorista:g('favar-mot')||(orig&&orig.motorista)||'',
    colaborador_id:g('favar-colab-id')||(orig&&orig.colaborador_id)||null,
    tipo:g('favar-tipo'), descricao:g('favar-desc').trim(),
    data:g('favar-data'), custo_estimado:est, custo_final:fin,
    status:g('favar-status')||'Aberto',
    contrato_nome:(orig&&orig.contrato_nome)||veic.contrato_nome||''
  };
}

async function frtAvarGravarSupabase(isNew, avar, origId){
  if(DEMO) return true;
  if(isNew){
    var r=await sbInsert('frotas_avarias',_semId(avar));
    if(!(r&&r.length) && avar.colaborador_id){
      var avarSemCol=Object.assign({},avar); delete avarSemCol.colaborador_id;
      r=await sbInsert('frotas_avarias',_semId(avarSemCol));
    }
    if(r&&r.length){
      if(r[0]&&r[0].id) avar.id=r[0].id;
      return true;
    }
    return false;
  }
  if(!origId || !isUUID(origId)) return true;
  var payload={
    placa:avar.placa, modelo:avar.modelo, veiculo_id:avar.veiculo_id||null,
    motorista:avar.motorista||null, colaborador_id:avar.colaborador_id||null,
    tipo:avar.tipo, descricao:avar.descricao, data:avar.data,
    custo_estimado:avar.custo_estimado, custo_final:avar.custo_final, status:avar.status
  };
  var ok=await sbUpdate('frotas_avarias', payload, 'id=eq.'+origId);
  if(!ok && avar.colaborador_id){
    delete payload.colaborador_id;
    ok=await sbUpdate('frotas_avarias', payload, 'id=eq.'+origId);
  }
  return !!ok;
}

function frtAbrirAvaria(id){
  var orig=id?(frt_avarias||[]).find(function(x){return String(x.id)===String(id);}):null;
  if(id && !orig){
    if(typeof progShowToast==='function') progShowToast('Registro de sinistro não encontrado.','erro');
    return;
  }
  var isNew=!orig;
  var veicSel='';
  if(orig){
    veicSel=orig.veiculo_id||'';
    if(!veicSel && orig.placa){
      var vHit=(frt_veiculos||[]).find(function(v){return String(v.placa)===String(orig.placa);});
      if(vHit) veicSel=vHit.id;
    }
  }
  var veicOpts='<option value="">Selecione...</option>'
    +(frt_veiculos||[]).map(function(v){
      return '<option value="'+escHtml(v.id)+'"'+(String(v.id)===String(veicSel)?' selected':'')+'>'
        +escHtml(v.placa)+' — '+escHtml(v.modelo||'')+'</option>';
    }).join('');
  if(veicSel && !(frt_veiculos||[]).some(function(v){return String(v.id)===String(veicSel);})){
    veicOpts='<option value="'+escHtml(veicSel)+'" selected>'+escHtml((orig&&orig.placa)||'Veículo')+' — '+escHtml((orig&&orig.modelo)||'')+'</option>'+veicOpts;
  }
  var tipoSel=orig?orig.tipo:'Avaria leve';
  var tipoOpts=FRT_AVAR_TIPOS.slice();
  if(tipoSel && tipoOpts.indexOf(tipoSel)<0) tipoOpts=tipoOpts.concat([tipoSel]);
  var stSel=orig?(orig.status||'Aberto'):'Aberto';
  var stOpts=FRT_AVAR_STATUS.slice();
  if(stSel && stOpts.indexOf(stSel)<0) stOpts=stOpts.concat([stSel]);
  var html='<div class="modal-bg"><div class="modal" style="max-width:480px">'
    +'<h3>🔨 '+(isNew?'Registrar avaria':'Editar sinistro / avaria')+'</h3>'
    +'<p style="font-size:11px;color:#888;margin-bottom:.75rem">'
    +(isNew?'Informe placa e data — o motorista responsável é buscado na escala do dia.'
      :'Altere os dados e salve. Excluir remove o registro da lista e do banco.')+'</p>'
    +'<div style="display:flex;flex-direction:column;gap:.75rem;margin-bottom:1rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Veículo (placa) *</label>'
    +'<select class="inp" id="favar-veic" style="width:100%" onchange="frtAtualizarMotEscalaModal(\'favar\')">'+veicOpts+'</select></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Data *</label>'
    +'<input class="inp" id="favar-data" type="date" style="width:100%" value="'+escHtml(String((orig&&orig.data)||dataHojeLocal()).slice(0,10))+'" onchange="frtAtualizarMotEscalaModal(\'favar\')"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Tipo *</label>'
    +'<select class="inp" id="favar-tipo" style="width:100%">'
    +tipoOpts.map(function(t){return '<option'+(t===tipoSel?' selected':'')+'>'+escHtml(t)+'</option>';}).join('')
    +'</select></div></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Status</label>'
    +'<select class="inp" id="favar-status" style="width:100%">'
    +stOpts.map(function(s){return '<option'+(s===stSel?' selected':'')+'>'+escHtml(s)+'</option>';}).join('')
    +'</select></div>'
    +'<div id="favar-mot-info" style="font-size:11px;padding:8px;background:#f9f9f7;border-radius:6px;border:.5px solid #e0dfd8">Informe veículo e data para buscar o motorista na escala.</div>'
    +'<input type="hidden" id="favar-mot" value="'+escHtml((orig&&orig.motorista)||'')+'"/>'
    +'<input type="hidden" id="favar-colab-id" value="'+escHtml((orig&&orig.colaborador_id)||'')+'"/>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Descrição *</label>'
    +'<textarea class="inp" id="favar-desc" style="width:100%;height:70px">'+escHtml((orig&&orig.descricao)||'')+'</textarea></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem">'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Custo estimado</label>'
    +'<input class="inp" id="favar-custo" type="number" step="0.01" style="width:100%" value="'+escHtml(String((orig&&orig.custo_estimado)!=null?orig.custo_estimado:''))+'"/></div>'
    +'<div><label style="font-size:11px;font-weight:500;display:block;margin-bottom:3px">Custo final</label>'
    +'<input class="inp" id="favar-custo-final" type="number" step="0.01" style="width:100%" value="'+escHtml(String((orig&&orig.custo_final)!=null?orig.custo_final:''))+'"/></div>'
    +'</div></div>'
    +'<div style="display:flex;gap:8px;align-items:center">'
    +(isNew?'':'<button type="button" class="btn" id="favar-excluir" style="color:#A32D2D;border-color:#A32D2D">Excluir</button>')
    +'<button type="button" class="btn" onclick="closeModal()" style="flex:1">Cancelar</button>'
    +'<button type="button" class="btn btn-pri" id="favar-salvar" style="flex:1">'+(isNew?'Registrar':'Salvar')+'</button>'
    +'</div></div></div>';
  setModal(html);
  setTimeout(function(){
    if(isNew) frtAtualizarMotEscalaModal('favar');
    else {
      var mot=(orig.motorista||'');
      var info=document.getElementById('favar-mot-info');
      if(info){
        info.innerHTML=mot
          ? '<span style="color:#3B6D11;font-weight:600">✅ '+escHtml(mot)+'</span>'
            +'<div style="font-size:10px;color:#666;margin-top:2px">Motorista do registro. Altere veículo/data para buscar de novo na escala.</div>'
          : '<span style="color:#854F0B">⚠ Sem motorista neste registro. Informe veículo e data para buscar na escala.</span>';
      }
    }
    var btn=document.getElementById('favar-salvar');
    if(btn) btn.onclick=async function(){
      var avar=frtAvarMontarPayload(orig);
      if(!avar) return;
      btn.disabled=true;
      btn.textContent='Salvando...';
      if(isNew) avar.id='av'+Date.now();
      else avar.id=orig.id;
      var ok=await frtAvarGravarSupabase(isNew, avar, isNew?null:orig.id);
      if(!ok){
        btn.disabled=false;
        btn.textContent=isNew?'Registrar':'Salvar';
        return;
      }
      if(isNew) frt_avarias.unshift(avar);
      else {
        var idx=(frt_avarias||[]).findIndex(function(x){return String(x.id)===String(orig.id);});
        if(idx>=0) frt_avarias[idx]=Object.assign({}, orig, avar, {id:orig.id});
      }
      closeModal(); frtAvarRender();
      if(typeof avColInvalidarCacheFrota==='function') avColInvalidarCacheFrota(); // recalc da avaliação relê avarias
      if(typeof progShowToast==='function') progShowToast(isNew?'Avaria registrada.':'Sinistro atualizado.');
    };
    var bx=document.getElementById('favar-excluir');
    if(bx) bx.onclick=function(){ frtExcluirAvaria(orig.id); };
  },50);
}

async function frtExcluirAvaria(id){
  if(!id) return;
  if(!confirm('Excluir este registro de sinistro/avaria? Esta ação não pode ser desfeita.')) return;
  var bx=document.getElementById('favar-excluir');
  if(bx){ bx.disabled=true; bx.textContent='Excluindo...'; }
  if(!DEMO && isUUID(id)){
    try{ await sbDelete('frotas_avarias','id=eq.'+id); }
    catch(eDel){ console.warn('frtExcluirAvaria', eDel); }
  }
  frt_avarias=(frt_avarias||[]).filter(function(x){return String(x.id)!==String(id);});
  closeModal();
  frtAvarRender();
  if(typeof progShowToast==='function') progShowToast('Sinistro excluído.');
}

