// ── Helpers ───────────────────────────────────────────────────
function fmtDT(iso){
  if(!iso)return '—';
  try{return new Date(iso).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'});}catch(e){return iso;}
}

function frtGerarRisco(tipo,gravidade,placa,motorista,desc){
  // Não gerar duplicata
  if(frt_riscos.some(function(r){return r.tipo===tipo&&r.placa===placa&&r.status==='Aberto';})) return;
  frt_riscos.unshift({id:'risk'+Date.now(),tipo:tipo,gravidade:gravidade,
    placa:placa,motorista:motorista,descricao:desc,
    status:'Aberto',criado_em:new Date().toISOString()});
}

// ── Integração com Programação de Equipes ─────────────────────
// Chamada quando equipe é escalada com veículo
function frtRegistrarProgramacaoEquipe(equipeId,veiculoId,data,motorista,contrato_id){
  var veic=frt_veiculos.find(function(v){return v.id===veiculoId;});if(!veic)return;
  // Verificar se veículo está disponível
  if(veic.status==='Bloqueado'||veic.status==='Em manutenção'){
    progShowToast('⚠ Veículo '+veic.placa+' não disponível ('+veic.status+'). Selecione outro.',true);
    return false;
  }
  // Verificar duplicidade
  var jaProgramado=frt_programacoes.some(function(p){
    return p.veiculo_id===veiculoId&&p.data===data&&p.status!=='Cancelada';
  });
  if(jaProgramado){
    progShowToast('⚠ Veículo '+veic.placa+' já programado para '+data+'.',true);
    return false;
  }
  veic.status='Reservado';
  frt_programacoes.push({id:'fp'+Date.now(),veiculo_id:veiculoId,placa:veic.placa,
    equipe_id:equipeId,motorista:motorista,contrato_id:contrato_id,
    data:data,status:'Aguardando validação da portaria'});
  return true;
}

// ── Integração com Diário de Bordo ───────────────────────────
function frtRegistrarKMDiario(placa,km_inicial,km_final,data){
  var veic=frt_veiculos.find(function(v){return v.placa===placa;});if(!veic)return;
  if(km_final<km_inicial){
    return {erro:'KM final não pode ser menor que KM inicial.'};
  }
  var km_rodado=km_final-km_inicial;
  veic.km_atual=km_final;
  if(!DEMO)sbUpdate('frotas_veiculos',{km_atual:km_final},'placa=eq.'+placa);
  // Verificar divergência com rastreador (futura integração)
  if(veic.km_rastreador&&Math.abs(km_rodado-(veic.km_rastreador)>100)){
    frtGerarRisco('Divergência de KM','Média',placa,'','KM manual difere do rastreador em mais de 100km');
  }
  return {km_rodado:km_rodado};
}


window.addEventListener('load',async function(){
  // RH-SEL-1B: portal público ANTES de login / app administrativa
  if(typeof rhPortalCandidatoBoot==='function' && rhPortalCandidatoBoot()){
    return;
  }

  var elSenha=document.getElementById('login-senha');
  var elEmail=document.getElementById('login-email');
  if(elSenha)elSenha.addEventListener('keydown',function(e){if(e.key==='Enter')fazerLogin();});
  if(elEmail)elEmail.addEventListener('keydown',function(e){if(e.key==='Enter')fazerLogin();});

  // ── Tentar restaurar sessão Supabase Auth ────────────────────────────
  try{ if(typeof progLimparCacheVeiculosAntigos==='function') progLimparCacheVeiculosAntigos(); }catch(ePv){}
  var _restoredViaAuth = false;
  if(supabaseClient && !DEMO){
    try{
      var sessRes = await supabaseClient.auth.getSession();
      var sess = sessRes && sessRes.data && sessRes.data.session;
      if(sess && sess.access_token){
        _sbAuthToken = sess.access_token;
        _cenaAuthHadSession = true;
        // Se token perto de expirar, renovar antes de abrir o ERP
        if(!sbAuthJwtIsAuthenticated(_sbAuthToken)){
          var okRefRest = await cenaAuthRefreshSession();
          if(!okRefRest || !sbAuthJwtIsAuthenticated(_sbAuthToken)){
            console.warn('[Auth] restore: refresh falhou — novo login necessário');
            _sbAuthToken = null;
            sess = null;
          }
        }
      }
      if(sess && sbAuthJwtIsAuthenticated(_sbAuthToken)){
        var userEmail = sess.user.email;
        var uRes = await sbFetch('usuarios_sistema',{filters:['email=eq.'+encodeURIComponent(userEmail),'ativo=eq.true']});
        if(!(uRes&&uRes.length) && sess.user && sess.user.id){
          uRes = await sbFetch('usuarios_sistema',{filters:['auth_user_id=eq.'+sess.user.id,'ativo=eq.true']});
        }
        if(uRes && uRes.length){
          usuarioLogado = uRes[0];
          _restoredViaAuth = true;
          var _authUidRest = sess.user && sess.user.id;
          if(_authUidRest && !usuarioLogado.auth_user_id){
            try{
              await sbUpdate('usuarios_sistema',{auth_user_id:_authUidRest},'id=eq.'+usuarioLogado.id);
              usuarioLogado.auth_user_id = _authUidRest;
            }catch(eLink){ console.warn('[Auth] auto-vinculo restore falhou:', eLink); }
          }
          console.log('[Auth] Sessão Supabase restaurada — perfil:',usuarioLogado.perfil);
          cenaAuthClearTerminalInvalid();
          cenaAuthConfirmPersistiu();
          try{localStorage.setItem('cena_user',JSON.stringify({
            id:usuarioLogado.id,nome:usuarioLogado.nome,email:usuarioLogado.email,
            perfil:usuarioLogado.perfil,contrato_id:usuarioLogado.contrato_id||'',
            equipe_id:usuarioLogado.equipe_id||'',equipe_codigo:usuarioLogado.equipe_codigo||'',
            auth_user_id:usuarioLogado.auth_user_id||'',
            ts:Date.now()
          }));}catch(e){}
        }
      }
    }catch(e){ console.warn('[Auth] Restore Supabase Auth falhou:',e); }
  }

  // ── Se não restaurou via Auth, tentar localStorage (MD5 legado) ─────
  if(!_restoredViaAuth){
    try{
      var saved=localStorage.getItem('cena_user');
      if(saved){
        var savedUser=JSON.parse(saved);
        // AUTH-PERSIST-1: usuário migrado (auth_user_id) NÃO entra só com cena_user
        if(savedUser && savedUser.auth_user_id && !DEMO){
          console.warn('[Auth] cena_user com auth_user_id sem sessão Auth — exigindo novo login');
          try{ localStorage.removeItem('cena_user'); }catch(eRm){}
          usuarioLogado = null;
          sbAuthShowSessaoIndisponivel(CENA_AUTH_MSG_EXPIRADA);
        } else {
          usuarioLogado=savedUser;
          // Validar perfil no servidor para evitar escalada via DevTools
          if(!DEMO&&usuarioLogado&&usuarioLogado.id){
            sbFetch('usuarios_sistema',{filters:['id=eq.'+usuarioLogado.id,'ativo=eq.true']}).then(function(dbRes){
              if(!dbRes||!dbRes.length){
                localStorage.removeItem('cena_user');usuarioLogado=null;
                document.getElementById('pg-app').classList.add('hidden');
                document.getElementById('pg-login').classList.remove('hidden');
                return;
              }
              var dbUser=dbRes[0];
              // Se no banco já migrou para Auth, bloquear falso login
              if(dbUser.auth_user_id){
                console.warn('[Auth] usuário migrado detectado no banco sem sessão — login necessário');
                try{ localStorage.removeItem('cena_user'); }catch(e2){}
                usuarioLogado=null;
                document.getElementById('pg-app').classList.add('hidden');
                document.getElementById('pg-login').classList.remove('hidden');
                sbAuthShowSessaoIndisponivel(CENA_AUTH_MSG_EXPIRADA);
                return;
              }
              usuarioLogado.perfil=dbUser.perfil;
              usuarioLogado.contrato_id=dbUser.contrato_id||'';
              usuarioLogado.equipe_id=dbUser.equipe_id||'';
              usuarioLogado.equipe_codigo=dbUser.equipe_codigo||'';
              try{localStorage.setItem('cena_user',JSON.stringify(usuarioLogado));}catch(e){}
            }).catch(function(){});
          }
        }
      }
    }catch(e){}
  }

  // ── Se não tem usuário, mostrar login e sair ─────────────────────────
  if(!usuarioLogado){ return; }

  // ── A partir daqui: usuário restaurado (Auth ou MD5) ─────────────────
  document.getElementById('topbar-user').textContent=usuarioLogado.nome;

  // ── Fluxo unificado: usuarioLogado já foi definido acima (Auth ou MD5) ─
  try{
    if(usuarioLogado){
      // Aplicar blindagem ANTES de mostrar pg-app
      if(typeof aplicarPerfilBody==='function') aplicarPerfilBody(usuarioLogado);
      else {
        if(usuarioLogado.perfil==='equipe'){
          document.body.classList.add('perfil-equipe');
        }
        if(usuarioLogado.perfil==='portaria'){
          document.body.classList.add('perfil-portaria');
        }
        if(usuarioLogado.perfil==='gerente_frotas'||usuarioLogado.perfil==='supervisor_frotas'){
          document.body.classList.add('perfil-'+usuarioLogado.perfil);
        }
        if(usuarioLogado.perfil==='almoxarife'){
          document.body.classList.add('perfil-almoxarife');
        }
      }

      document.getElementById('pg-login').classList.add('hidden');
      document.getElementById('pg-app').classList.remove('hidden');
      document.body.classList.remove('sem-login');

      // Para TMA: esconder imediatamente antes de qualquer render
      if(usuarioLogado.perfil==='equipe'){
        var _hids=['hdr-principal','bloco-metricas','nav-main','nav-sub',
                   'nav-sub-mobile','btn-hamburger','gestor-bar','nav-mobile-panel'];
        _hids.forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
        document.querySelectorAll('[id^="pg-"]').forEach(function(el){if(el.id!=='pg-app'&&el.id!=='pg-login'&&el.id!=='pg-app-content')el.classList.add('hidden');});
        var pgD=document.getElementById('pg-diario');
        if(pgD) pgD.classList.remove('hidden');
      }

      carregarPerfisExtras();
      carregarDados().then(function(){
      document.dispatchEvent(new CustomEvent('cena:logged-in'));
  auditLog('login','sistema','Login no sistema — perfil: '+(usuarioLogado.perfil||''),{email:usuarioLogado.email||''});
      console.log('[INIT] carregarDados OK — perfil:', usuarioLogado.perfil, 'equipe_id:', usuarioLogado.equipe_id);
      // Iniciar heartbeat de presença online
      setTimeout(onlineInit, 1500);
      // Start notification check for approvers
      if(['admin','gestor','coordenador','almoxarife'].includes(usuarioLogado.perfil)){
        setTimeout(notifVerificar, 2000);
        // Re-check every 5 minutes
        setInterval(notifVerificar, 10*60*1000);
      }
      // Show PWA install banner on tablet/mobile
      if(typeof pwaMostrarSeDisponivel === 'function') pwaMostrarSeDisponivel();
      // Load celulares for all profiles
      if(!DEMO) sbFetch('celulares_empresa',{order:'numero'}).then(function(rows){ if(rows) _celulares=rows; });
      // Kanban banner: only for equipe profile in field diary
      // For admin/gestor: Kanban is in Obras > Materiais tab
      if(usuarioLogado.perfil==='equipe' && usuarioLogado.equipe_id){
        setTimeout(function(){
          _plptVerificarMateriaisSeparados(usuarioLogado.equipe_id);
        }, 1500);
      }
      if(usuarioLogado.perfil==='equipe'){
        // Re-buscar dados atualizados do usuário do banco (equipe_id pode ter mudado)
        if(!DEMO){
          sbFetch('usuarios_sistema',{filters:['id=eq.'+usuarioLogado.id]}).then(function(res){
            if(res&&res.length){
              // Atualizar dados da sessão com o que está no banco
              var userAtual=res[0];
              if(userAtual.equipe_id) usuarioLogado.equipe_id=userAtual.equipe_id;
              if(userAtual.equipe_codigo) usuarioLogado.equipe_codigo=userAtual.equipe_codigo;
              usuarioLogado.contrato_id=userAtual.contrato_id||'';
              // Salvar sessão atualizada
              try{localStorage.setItem('cena_user',JSON.stringify({
                id:usuarioLogado.id,nome:usuarioLogado.nome,email:usuarioLogado.email,
                perfil:usuarioLogado.perfil,contrato_id:usuarioLogado.contrato_id||'',
                equipe_id:usuarioLogado.equipe_id||'',equipe_codigo:usuarioLogado.equipe_codigo||'',
                ts:Date.now()
              }));}catch(e){}
            }
            if(usuarioLogado.equipe_id||usuarioLogado.equipe_codigo){
              console.log('[INIT] showPageDiario (banco OK) equipe:', usuarioLogado.equipe_id, 'equipes[]:', equipes.length);
              resolveEquipeUsuario().then(function(){ showPageDiario(); });
            } else {
              localStorage.removeItem('cena_user');
              document.getElementById('pg-app').classList.add('hidden');
              document.getElementById('pg-login').classList.remove('hidden');
            }
          }).catch(function(){
            // Sem rede - usar dados do localStorage
            if(usuarioLogado.equipe_id||usuarioLogado.equipe_codigo){
              console.log('[INIT] showPageDiario (offline) equipe:', usuarioLogado.equipe_id);
              resolveEquipeUsuario().then(function(){ showPageDiario(); });
            } else {
              localStorage.removeItem('cena_user');
              document.getElementById('pg-app').classList.add('hidden');
              document.getElementById('pg-login').classList.remove('hidden');
            }
          });
        } else {
          // DEMO
          if(usuarioLogado.equipe_id||usuarioLogado.equipe_codigo){
            showPageDiario();
          }
        }
        return;
      }
      if(usuarioLogado.perfil==='encarregado'){
        console.log('[INIT] encarregado → showMain campo');
        resolveEquipeUsuario().then(function(){ showMain('campo'); });
      }else if(usuarioLogado.perfil==='supervisor_tma'||usuarioLogado.perfil==='coordenador_tma'){
        console.log('[INIT] supervisor/coordenador TMA → showMain tma');
        showMain('tma');
        setTimeout(function(){ showTMA('programacao'); }, 400);
      }else if((usuarioLogado.perfil==='supervisor'||usuarioLogado.perfil==='coordenador') && usuarioLogado.contrato_id){
        // Supervisor/coordenador com contrato único → vai direto para Programação de Projetos
        var _contIds = (usuarioLogado.contrato_id||'').split(',').map(function(s){return s.trim();}).filter(Boolean);
        if(_contIds.length === 1){
          console.log('[INIT] supervisor/coordenador contrato → plpt-programacao');
          window._plptProgCid = _contIds[0];
          showMain('operacional');
          setTimeout(function(){
            showPage('plpt-programacao');
            // Pré-selecionar o contrato no dropdown
            setTimeout(function(){
              var sel = document.getElementById('plpt-prog-contrato');
              if(sel) { sel.value = _contIds[0]; plptProgInit(); }
            }, 300);
          }, 400);
        } else {
          showMain('operacional');
        }
      }else if(usuarioLogado.perfil==='gerente_frotas'||usuarioLogado.perfil==='supervisor_frotas'){
        console.log('[INIT] perfil frotas → showMain frotas');
        document.body.classList.add('perfil-'+usuarioLogado.perfil);
        showMain('frotas');
      }else if(usuarioLogado.perfil==='almoxarife'){
        console.log('[INIT] almoxarife → showMain almoxarifado');
        document.body.classList.add('perfil-almoxarife');
        showMain('almoxarifado');
      }else if(usuarioLogado.perfil==='dp'||usuarioLogado.perfil==='rh'){
        console.log('[INIT] DP/RH → showMain rh');
        showMain('rh');
      }else if(usuarioLogado.perfil==='portaria'){
        console.log('[INIT] portaria → frotas-portaria');
        document.body.classList.add('perfil-portaria');
        showMain('frotas');
        setTimeout(function(){
          showPage('frotas-portaria');
          portMostrarAba('liberacao');
        },400);
      }else if(false){/*skip*/}else{
      if(usuarioLogado.perfil==='gestor'){
        var cids=(usuarioLogado.contrato_id||'').split(',').map(function(s){return s.trim();}).filter(Boolean);
        _gestorContratos=cids;_gestorContAtivo=null;
        showMain('dashboard');
      } else {
        window._filtroContrato=null;_gestorContAtivo=null;_gestorContratos=[];
        try{showMain('dashboard');}catch(err){
          console.error('Erro sessão showMain:',err);
          document.querySelectorAll('[id^="pg-"]').forEach(function(el){if(el.id!=='pg-app'&&el.id!=='pg-login'&&el.id!=='pg-app-content')el.classList.add('hidden');});
          var pg=document.getElementById('pg-dashboard');if(pg)pg.classList.remove('hidden');
          try{renderDashboard();}catch(e2){console.error('renderDashboard erro:',e2);}
        }
      }
    }}).catch(function(err){
      console.error('carregarDados falhou:',err);
      try{showMain('dashboard');}catch(e){}
    });
    }
  }catch(e){}
});

// ── MutationObserver: aplicar data-labels automaticamente ──
(function(){
  var obs = new MutationObserver(function(){
    aplicarDataLabels && aplicarDataLabels();
  });
  document.addEventListener('DOMContentLoaded', function(){
    var app = document.getElementById('pg-app');
    if(app) obs.observe(app, {childList:true, subtree:true});
    ajustarHeaderMobile && ajustarHeaderMobile();
  });
})();

// Se o 2º <script> falhar o parse, estes stubs evitam ReferenceError nos botões.
window.gpInit = window.gpInit || function(){ console.warn('gpInit: módulo ainda não carregou'); };
window._almShowAba = window._almShowAba || function(aba){
  if(typeof window._almShowAbaInterna==='function') return window._almShowAbaInterna(aba);
  console.warn('_almShowAba: módulo ainda não carregou', aba);
};
window._almShowAbaInterna = window._almShowAbaInterna || function(aba){
  console.warn('_almShowAbaInterna: módulo ainda não carregou', aba);
};

